-- 3. Insert 1450 Verified Jobs from VietJobs
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1, 2, 11, 'Cộng Tác Viên Môi Trường (Có Xe Đưa Đón)', 'Phối hợp với nhân viên hiện trường chuẩn bị dụng cụ, thiết bị lấy mẫu theo yêu cầu. Khuôn vác máy móc di chuyển từ xe tới địa điểm lấy mẫu. Thu dọn máy móc đưa lên xe cũng như về Văn phòng.', '- Nam , trình độ cao đẳng trở lên ngành môi trường - Giữ gìn các thiết bị, dụng cụ được giao. - Vệ sinh sạch sẽ nơi khu vực đoàn có tới lấy mẫu.
Kỹ năng mềm: [''Quản lý thời gian'', ''Giao tiếp hiệu quả'', ''Khả năng học hỏi nhanh'', ''Cam kết với công việc'']', 'PART_TIME', 'ONSITE', 'biên hoà', 'Đồng Nai', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 07:30 đến 17:00)', '[''Có xe công ty đưa đón'', ''Lương theo tuần'', ''Linh hoạt lựa chọn ngày làm việc trong tuần'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (2, 3, 11, 'Học Việc Giám Sát An Toàn', 'Hỗ trợ theo dõi và ghi nhận tình hình an toàn, vệ sinh lao động tại công trường dưới sự hướng dẫn của cán bộ phụ trách. Học cách kiểm tra trang bị bảo hộ của công nhân và cách nhắc nhở, hướng dẫn khi cần thiết. Hỗ trợ trong việc phổ biến nội quy an toàn cho công nhân mới. Ghi chú các quan sát thực tế và tham gia cùng đội ngũ trong các buổi kiểm tra hiện trường. Học hỏi quy trình xử lý các tình huống phát sinh liên quan đến an toàn lao động. Thực hiện các công việc khác theo sự phân công và hướng dẫn từ người phụ trách.', 'Sinh viên mới tốt nghiệp hoặc đang chờ bằng thuộc các ngành: Xây dựng, An toàn lao động, Môi trường,... Chăm chỉ, tinh thần cầu tiến, sẵn sàng học hỏi trong môi trường công trình. Không yêu cầu kinh nghiệm – sẽ được đào tạo và hướng dẫn trong suốt quá trình học việc.
Kỹ năng mềm: [''Chăm chỉ'', ''Tinh thần cầu tiến'', ''Sẵn sàng học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '5.0 - 8.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Có lương hỗ trợ học việc hấp dẫn'', ''Môi trường làm việc chuyên nghiệp, thân thiện, năng động'', ''Được tham gia và đào tạo thực tế tại các công trình nội thất cao cấp'', ''Cơ hội trở thành nhân viên chính thức sau kì học việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (3, 7, 2, 'Nhân Viên Phục Vụ Nhà Hàng', 'Chào đón và hướng dẫn khách vào bàn, giới thiệu menu, tư vấn món ăn và đồ uống. Ghi nhận, phục vụ món theo tiêu chuẩn, duy trì không gian làm việc sạch sẽ và hỗ trợ các công việc khác của nhà hàng. Hỗ trợ khách trong quá trình dùng bữa, thanh toán và xử lý các yêu cầu phát sinh. Giữ gìn vệ sinh khu vực làm việc và phối hợp với đồng nghiệp để đảm bảo chất lượng phục vụ. Giải quyết các yêu cầu và mối quan tâm của khách hàng một cách kịp thời và chuyên nghiệp. Đưa ra các đề xuất thực đơn và đảm bảo chất lượng thực phẩm đạt tiêu chuẩn.', 'Tiếng Anh giao tiếp ở mức khá. Đã từng có kinh nghiệm làm việc trong ngành hàng/ vị trí liên quan là lợi thế. Trung thực, cẩn thận, năng động trong công việc. Có tinh thần chịu học hỏi, trách nhiệm trong công việc. Linh hoạt và sẵn sàng làm việc nhiều ca khác nhau, bao gồm cả cuối tuần và ngày lễ.
Kỹ năng mềm: [''Trung thực'', ''Cẩn thận'', ''Năng động'', ''Chịu học hỏi'', ''Trách nhiệm'', ''Linh hoạt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'T2 – CN | Được nghỉ 1 ngày (được Team Leader sắp xếp)', '[''Phụ cấp ăn trưa'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Được đào tạo, phát triển bản thân'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (4, 8, 2, 'NV Phục Vụ Full PartTime', 'Chuẩn bị khu vực phục vụ, sẵn sàng trước giờ đón khách. Đón tiếp khách hàng với thái độ thân thiện, chuyên nghiệp. Nhận Order và phục vụ đồ ăn, thức uống đúng quy trình. Giao tiếp, hỗ trợ khách hàng, đặc biệt là khách hàng nước ngoài. Giữ vệ sinh khu vực làm việc sạch sẽ, gọn gàng. Phối hợp với Bếp và các bộ phận liên quan để đảm bảo chất lượng phục vụ.', '- Ưu tiên tuyển ứng viên Nữ - Có thể làm việc theo ca, bao gồm cả cuối tuần và các ngày lễ. - Sức khỏe tốt và có thể đứng trong thời gian dài. - Sạch sẽ, siêng năng, chăm chỉ. - Giao tiếp Tiếng Anh, tiếng Nhật (trung cấp, tương đương N3)
Kỹ năng mềm: [''Giao tiếp'', ''Làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca1: 10h00 - 14h00, Ca2: 17h00 - 22h30', '[''Được tăng lương theo quy chế của tổ chức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (5, 9, 2, 'Nhân Viên Pha Chế', 'TUYỂN GẤP - ĐỒNG ĐỘI XỊN SÒ CHO HIGHLANDS COFFEE V.52 Hải Dương. Nghe là thấy thơm mùi cà phê rồi đó! Thời gian làm việc linh hoạt như menu Highlands: Ca A: 6h30 – 15h (sáng tỉnh như cà phê!) Ca B: 15h – 23h (tối chill như trà sen vàng) Part-time thì bạn chọn: 4 hay 6 tiếng – Tùy lịch bạn rảnh! Thu nhập cực ổn áp: Từ 2x.000đ/giờ trở lên với Part-time! Có bảo hiểm đầy đủ khi là nhân viên chính thức. Ưu đãi sử dụng sản phẩm Highlands – uống cà phê nhà mình. Cơ hội học hỏi hết nấc: Được tham gia khoá học pha chế & kỹ năng chuẩn Highlands Coffee. Môi trường làm việc năng động, vui vẻ, teamwork đỉnh cao – không lo nhàm chán! Địa điểm làm việc: Trạm Dừng Nghỉ V.52 Cao Tốc Hà Nội - Hải Phòng (Hoàng Diệu - Gia Lộc) Vừa đi làm vừa được ngắm xe chạy vù vù ngoài cao tốc – còn gì chill hơn!', '• Tuổi từ 18 trở lên, đã tốt nghiệp cấp 3, nhanh nhẹn, chăm chỉ, hòa đồng. • Có thể đi làm các ngày thứ 7, Chủ nhật và ngày lễ, Tết. • Ưu tiên: Những bạn muốn gắn bó lâu dài với Công ty.
Kỹ năng chuyên môn: [''Vệ sinh An Toàn Thực Phẩm'', ''Pha Chế Đồ Uống'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Khả Năng Làm Việc Nhóm'']', 'PART_TIME', 'ONSITE', 'hải phòng', 'Hải Phòng', 'MONTHLY', 7000000.00, '3.0 - 7.0 triệu', 'Ca A: 6h30-15h, Ca B: 15h-23h, Part-time ca linh động (4,6,8 tiếng)', '[''Có bảo hiểm đầy đủ khi là nhân viên chính thức'', ''Ưu đãi sử dụng sản phẩm Highlands'', ''Cơ hội học hỏi hết nấc: Được tham gia khoá học pha chế & kỹ năng chuẩn Highlands Coffee'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (6, 10, 2, 'Nhân Viên Phục Vụ', 'Lấy order từ khách hàng, ghi nhận thông tin order từ khách hàng phải rõ ràng, chính xác món ăn, số lượng, đơn vị tính. Giới thiệu khách hàng các món ăn và đồ uống cho khách hàng. Hiểu biết về ẩm thực và các món ăn của nhà hàng. Phục vụ khách hàng đồ ăn và uống. Làm đúng quy cách và phong cách phục vụ của nhà hàng. Kiểm tra các món ăn trước khi phục vụ khách. Phục vụ đúng bàn, đúng món ăn, đủ số lượng, đúng thứ tự. Sẵn sàng trả lời và giải đáp mọi thắc mắc của khách hàng. Chất đầy đồ chén đĩa vào quầy service station. Bảo quản, cất giữ các đồ dùng ngăn nắp, gọn gàng, dễ kiểm kê. Quản lý các công cụ làm việc của nhà hàng: Bàn ghế, ly tách, dụng cụ làm việc và các vật dụng có liên quan. Báo cáo ngay khi phát hiện chén đĩa sứt mẻ mất vệ sinh. Hỗ trợ các đồng nghiệp khi nhà hàng đông khách. Phối hợp với thu ngân, quản lý nhà hàng và bếp trưởng khi khách gọi món, yêu cầu hủy thức ăn, tính tiền. Báo cáo với quản lý tất cả các sự cố xảy ra trong nhà hàng. Giao lại thông tin cho ca sau theo dõi. Bàn giao ca phải đầy đủ thông tin khách hàng và có mối liên kết chặt chẽ với đồng nghiệp, bàn giao mọi vấn đề liên quan trong ca làm việc thông qua Sổ lịch sử hoạt động của quán.', 'Tối thiểu 3-6 tháng kinh nghiệm làm việc trong ngành F&B. Có khả năng giao tiếp tiếng Anh, biết tiếng Hàn là một lợi thế. Có khả năng làm việc độc lập, làm việc nhóm. Có thể làm việc xoay ca. Trung thực, hoà đồng và có trách nhiệm với công việc.
Kỹ năng mềm: [''Làm việc nhóm'', ''Quản lý thời gian'', ''Phục Vụ Khách Hàng'', ''Giao tiếp tốt'', ''Khả Năng Chịu Áp Lực'']', 'PART_TIME', 'ONSITE', 'quận 7', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Ngày lễ (x2) theo Luật lao động Việt Nam'', ''Có phụ cấp ăn trưa, tối'', ''Phúc lợi đầy đủ: hiếu, hỷ, sinh nhật'', ''Thưởng hấp dẫn theo năng lực và hiệu suất làm việc'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (7, 2, 2, 'Nhân Viên Phục Vụ', '- Thực hiện các công việc đầu ca. - Thực hiện quy trình phục vụ thực khách. - Kiểm soát, bảo quản các công cụ - dụng cụ. - Thực hiện các công việc cuối ca. - Thanh toán cho khách. - Các công việc khác theo sự phân công của leader.', '- Nữ từ 20-35 tuổi. - Trình độ: Tốt nghiệp Trung cấp ngành nhà hàng khách sạn hoặc ngành nghề liên quan. - Kinh nghiệm: Ưu tiên ứng viên đã có kinh nghiệm trong lĩnh vực FnB. - Kỹ năng: - Khả năng giao tiếp Tiếng Anh cơ bản - Ngoại hình ưa nhìn, nhanh nhẹn - Cẩn thận, giải quyết vấn đề tốt, hòa đồng - Có trách nhiệm với công việc
Kỹ năng chuyên môn: [''Khả năng giao tiếp Tiếng Anh cơ bản'']
Kỹ năng mềm: [''Ngoại hình ưa nhìn'', ''Nhanh nhẹn'', ''Cẩn thận'', ''Giải quyết vấn đề tốt'', ''Hòa đồng'', ''Có trách nhiệm với công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '10h-14h, 18h-22h (ưu tiên xoay ca)', '[''Lương cơ bản'', ''Phụ cấp gửi xe'', ''Thưởng Hoa hồng'', ''Bao cơm 1 ngày/bữa'', ''Tiền tip'', ''BHXH, BHYT theo quy định của pháp luật'', ''Thưởng tháng 13'', ''Team building'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (8, 3, 2, 'Nhân Viên Phục Vụ Nhà Hàng Nhật', 'Đón tiếp, hướng dẫn khách hàng vào bàn và giới thiệu thực đơn. Tiếp nhận đơn hàng, phục vụ thức ăn, đồ uống và đảm bảo chất lượng dịch vụ. Đảm bảo khu vực bàn ăn sạch sẽ, gọn gàng. Giới thiệu món ăn, giải đáp thắc mắc của khách về thực đơn. Hỗ trợ các bộ phận khác khi có yêu cầu. Thực hiện các công việc khác theo chỉ đạo của quản lý.', 'Ngoại hình ưa nhìn, tự tin giao tiếp. Có kinh nghiệm liên quan dưới 1 năm. Ưu tiên đã làm nhà hàng Nhật. Tiếng Nhật giao tiếp từ N3 hoặc biết tiếng Anh (Không yêu cầu bằng cấp). Yêu thích ẩm thực Nhật Bản. Ưa sạch sẽ, tính cách hòa đồng thân thiện, làm việc nhóm tốt.
Kỹ năng mềm: [''Làm việc nhóm'', ''Phục Vụ Khách Hàng'', ''Giao tiếp tốt'', ''Khả Năng Chịu Áp Lực'', ''Nhanh Nhẹn, Hoạt Bát'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '5 tiếng/ ngày, 4 ngày/ tuần', '[''Hỗ trợ tiền teamwork 300.000 VNĐ/tháng'', ''Hỗ trợ cơm theo ca làm việc'', ''Môi trường làm việc chuyên nghiệp, thân thiện'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (9, 7, 2, 'Nhân Viên Fulltime/Parttime', 'Thời gian làm việc: Ưu tiên đăng ký xoay ca linh hoạt. PT: tất cả ngày trong tuần, theo giờ trong ca làm việc. FT: 48h/tuần, ca sáng tối luân chuyển thường xuyên, ngày off theo sự sắp xếp của cấp quản lý, không xin off ngày T7, CN hoặc các ngày lễ. Có trách nhiệm phối hợp với các vị trí phục vụ khác để cung cấp cho khách hàng dịch vụ tốt nhất. Chào đón khách và cung cấp thông tin về sản phẩm. Có sự liên kết thông tin với nhân viên bếp và nhân viên pha chế, nhân viên thu ngân. Nhận order đồ ăn, đồ uống và thực hiện các thủ tục cần thiết. Đảm bảo các order được phục vụ chính xác và đầy đủ. Quan sát khách hàng để nắm bắt và thực hiện việc đáp ứng các yêu cầu của khách hàng kịp thời đảm bảo khách hàng được hài lòng. Tổng hợp order và thực hiện các quy trình thủ tục thanh toán theo quy định của Công ty. Chuẩn bị sẵn sàng công cụ, dụng cụ đầy đủ và sạch sẽ trong các tủ station. Thực hiện các công việc chuẩn bị đầu giờ phục vụ theo sự phân công của QLCH.', 'Trình độ học vấn: Tốt nghiệp THCS trở lên. Kỹ năng chuyên môn: Tác phong/ngoại hình: Nhanh nhẹn, phù hợp với môi trường dịch vụ. Có khả năng tiếp nhận và truyền đạt thông tin. Có khả năng di chuyển linh động trong ca làm việc. Kinh nghiệm làm việc: Ưu tiên những người có ít nhất 6 tháng kinh nghiệm trong lĩnh vực phục vụ cửa hàng café, nhà hàng…. Yêu cầu khác: Giới tính: Nam / Nữ/ Khác. Độ tuổi: từ 18 đến 25 tuổi. Tính cách: Cẩn trọng, tỉ mỉ, trung thực, có tinh thần trách nhiệm, chịu được áp lực cao.
Kỹ năng chuyên môn: [''Nhanh nhẹn'', ''Có khả năng tiếp nhận và truyền đạt thông tin'', ''Có khả năng di chuyển linh động trong ca làm việc'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Quản lý thời gian'', ''Chịu được áp lực công việc'', ''Khả năng thích ứng'', ''Cam kết với công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca A: 6h30 – 14h30, Ca B: 14h00 – 22h30', '[''Thưởng theo hiệu quả công việc'', ''Môi trường làm việc chuyên nghiệp'', ''Cơ hội thăng tiến rõ ràng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (10, 8, 2, 'Nhân Viên Phục Vụ Parttime (50/50 Coffee_Tea)', 'Làm việc tại chuỗi cửa hàng 50/50 Coffee_tea. Tiếp đón khách hàng một cách lịch sự, thân thiện. Phục vụ đồ uống tại quầy và thức ăn cho khách tại bàn. Đảm bảo vệ sinh khu vực làm việc và khu vực khách hàng, bao gồm lau dọn bàn ghế, sàn nhà, quầy,.. Hỗ trợ khách hàng khi họ có nhu cầu (thêm nước, đổi món, khiếu nại…). Dọn dẹp và chuẩn bị khu vực phục vụ trước và sau ca làm. Phối hợp với các bộ phận khác để đảm bảo hoạt động của quán diễn ra suôn sẻ. Tuân thủ nội quy và quy trình làm việc của cửa hàng.', 'Không yêu cầu kinh nghiệm (được đào tạo nếu chưa có kinh nghiệm).
Kỹ năng mềm: [''Giao tiếp tốt'', ''Thái độ niềm nở'', ''Thân thiện'', ''Siêng năng'', ''Nhanh nhẹn'', ''Trung thực'', ''Có tinh thần trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Xoay ca theo lịch cửa hàng', '[''Lương theo giờ từ 23.000 - 26.000đ/h'', ''Thưởng doanh thu cửa hàng'', ''Cấp phát đồng phục miễn phí'', ''Mã giảm nội bộ mỗi ngày khi sử dụng sản phẩm công ty'', ''Được đào tạo từ đầu'', ''Môi trường làm việc năng động, thân thiện'', ''Cơ hội thăng tiến lên các vị trí cao hơn'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (11, 9, 2, 'Nhân Viên Pha Chế', 'Nhận và kiểm tra chất lượng nguyên liệu, đảm bảo số lượng nguyên liệu đủ để phục vụ cho khách hàng trong ca làm việc. Lau sạch các vật dụng phục vụ cho việc pha chế và đảm bảo khu vực quầy bar phải sạch sẽ. Kiểm tra và đảm bảo các thiết bị chuyên dụng hoạt động tốt. Gọt hoa quả, cắt tỉa đồ trang trí, chuẩn bị các loại nước ép. Giới thiệu cho khách hàng những thức uống ngon, theo mùa mà nhà hàng – khách sạn đang phục vụ, Order và tiến hành pha chế theo yêu cầu của khách hàng. Đảm bảo thức uống được pha chế theo đúng công thức, định lượng chuẩn của loại thức uống đó hoặc theo yêu cầu của khách hàng. Trang trí thức uống bắt mắt, thu hút. Kiểm tra lại thức uống trước khi phục vụ khách. Rửa sạch các vật dụng dùng để pha chế vào cuối ca làm việc và bảo quản vị trí thích hợp. Khi phát hiện sứt mẻ, hư hỏng phải báo cáo ngay với Quản lý để giải quyết. Phối hợp lên ý tưởng menu thức uống cho nhà hàng – khách sạn. Chủ động đề xuất những ý tưởng, kế hoạch để nâng cao chất lượng dịch vụ và cải tiến những kỹ thuật pha chế. Báo cáo với quản lý khi có sự cố xảy ra. Thực hiện các công việc khác khi được cấp trên yêu cầu.', 'Nam, nữ: Từ đủ 18 tuổi trở lên. Sức khỏe tốt, không mắc các bệnh truyền nhiễm, không xăm trổ, không dị tật, không tiền án tiền sự, không mắc các tệ nạn xã hội. Có chứng chỉ bartender, kinh nghiệm từ 6 tháng trở lên.', 'PART_TIME', 'ONSITE', 'tp phủ lý', 'Ninh Bình', 'MONTHLY', 6000000.00, '6.0 triệu', 'Xoay ca: Ca 1: 6h30 - 14h30, Ca 2: 14h30 - 22h30', '[''Khen thưởng tuần / tháng / năm'', ''Xét tăng lương đột xuất'', ''Hỗ trợ chỗ ở (nếu cần)'', ''BHXH, BHYT, BHTN theo quy định của công ty'', ''Hỗ trợ ăn ca tại công ty'', ''Chế độ phúc lợi khác theo quy định của công ty'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (12, 10, 2, 'Nhân Viên Pha Chế', 'Pha chế đồ uống theo menu quán. Order đồ uống, phục vụ khách tại quán. Dọn dẹp đảm bảo vệ sinh. Thực hiện các công việc khác theo yêu cầu của quản lý.', 'Có kinh nghiệm pha chế từ 01 năm trở lên. Đủ 18 - 30 tuổi. Tốt nghiệp trung cấp trở lên chuyên ngành dịch vụ, du lịch hoặc ngành liên quan. Ưu tiên ứng viên ở Phủ Lý, Hà Nam.
Kỹ năng chuyên môn: [''Kinh nghiệm pha chế'']', 'PART_TIME', 'ONSITE', 'tp phủ lý', 'Ninh Bình', 'MONTHLY', 6000000.00, '6.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Mức lương cạnh tranh theo năng lực'', ''Thỏa thuận khi phỏng vấn'', ''Được hưởng các chế độ theo quy định công ty và nhà nước'', ''Môi trường làm việc trẻ trung, năng động'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (13, 2, 2, 'Nhân Viên Kinh Doanh Du Lịch Parttime', 'Tìm kiếm, tiếp cận và phát triển hệ thống Đại lý, Cộng tác viên kinh doanh vé máy bay – phòng khách sạn – tour du lịch. Tư vấn chính sách, hướng dẫn sử dụng hệ thống Autic.vn. Chăm sóc, hỗ trợ Đại lý và Cộng tác viên trong suốt quá trình hợp tác. Báo cáo kết quả và đề xuất giải pháp phát triển thị trường.', 'Nam/Nữ, từ 20 – 28 tuổi, ngoại hình ưa nhìn, giao tiếp tốt. Yêu thích du lịch và kinh doanh. Ưu tiên ứng viên có kinh nghiệm sales, telesales, chăm sóc khách hàng. Sử dụng thành thạo máy tính văn phòng (Word, Excel, Zalo OA, Facebook Page…)
Kỹ năng chuyên môn: [''Sử dụng máy tính văn phòng (Word, Excel, Zalo OA, Facebook Page)'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Yêu thích du lịch và kinh doanh'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '10.0 - 15.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Lương chính: 20.000 đ/giờ'', ''Nghỉ thứ 7, chủ nhật'', ''Phụ cấp gửi xe, máy tính cá nhân làm việc, điện thoại'', ''Thưởng theo hiệu quả công việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (14, 3, 2, 'Thực Tập Sinh Kinh Doanh', 'Tư vấn, thuyết phục khách hàng sử dụng dịch vụ của công ty. Đàm phán trực tiếp với khách hàng để ký kết các hợp đồng dịch vụ và chăm sóc khách hàng; Tìm kiếm, mở rộng mạng lưới khách hàng, đại lý của công ty; Các công việc khác hỗ trợ hoạt động kinh doanh.', 'Sử dụng thành thạo internet và mạng xã hội; Kỹ năng giao tiếp và đàm phán tốt; Có thể làm việc ở cường độ cao và chịu được áp lực công việc. Đang là sinh viên, Tốt Nghiệp hoặc sắp tốt nghiệp cao đẳng, đại học....
Kỹ năng chuyên môn: [''Sử dụng thành thạo internet và mạng xã hội'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng đàm phán'', ''Chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'ninh bình', 'Ninh Bình', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Thời gian làm việc linh hoạt'', ''Lương + % hoa hồng + thưởng'', ''Hỗ trợ xác nhận giấy tờ thực tập'', ''Được tham gia các khóa đào tạo kỹ năng & nghiệp vụ của công ty'', ''Môi trường văn hóa doanh nghiệp trẻ, năng động, thân thiện và chuyên nghiệp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (15, 7, 2, 'Thực Tập Sinh Kinh Doanh Du Lịch', 'Tư vấn, thuyết phục khách hàng sử dụng dịch vụ của công ty. Đàm phán trực tiếp với khách hàng để ký kết các hợp đồng dịch vụ và chăm sóc khách hàng; Tìm kiếm, mở rộng mạng lưới khách hàng, đại lý của công ty; Các công việc khác hỗ trợ hoạt động kinh doanh.', 'Sử dụng thành thạo internet và mạng xã hội; Kỹ năng giao tiếp và đàm phán tốt; Có thể làm việc ở cường độ cao và chịu được áp lực công việc. Đang là sinh viên, Tốt Nghiệp hoặc sắp tốt nghiệp cao đẳng, đại học....
Kỹ năng chuyên môn: [''Sử dụng thành thạo internet và mạng xã hội'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng đàm phán'', ''Có thể làm việc ở cường độ cao'', ''Chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'ninh bình', 'Ninh Bình', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Thời gian làm việc linh hoạt'', ''Thu nhập hấp dẫn, lương + % hoa hồng + thưởng'', ''Hỗ trợ xác nhận giấy tờ thực tập'', ''Được tham gia các khóa đào tạo kỹ năng & nghiệp vụ của công ty'', ''Được làm việc trong môi trường văn hóa doanh nghiệp trẻ, năng động, thân thiện và chuyên nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (16, 8, 2, 'Nhân Viên Phục Vụ', 'Bưng bê, phục vụ đồ ăn sáng từ bếp ra nhà ăn cho khách. Hỗ trợ khách trong quá trình ăn sáng tại nhà ăn. Lau dọn bàn khi khách ăn xong. Quan sát khách trong thời gian dùng bữa sáng để báo bếp bổ sung thức ăn đưa lên cho khách. Hỗ trợ nhà bếp gọt, bổ hoa quả tráng miệng cho khách. Dọn bàn sau khi khách sử dụng xong. Các công việc khác theo yêu cầu của cấp trên.', 'Chấp nhận sinh viên. Không yêu cầu kinh nghiệm, được đào tạo. Yêu cầu tiếng anh giao tiếp cơ bản. Ngoại hình khá, nhanh nhẹn. Chủ động trong công việc.
Kỹ năng mềm: [''Làm việc nhóm'', ''Phục Vụ Khách Hàng'', ''Giao tiếp tốt'', ''Khả Năng Chịu Áp Lực'', ''Nhanh Nhẹn, Hoạt Bát'']', 'PART_TIME', 'REMOTE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', 'Thứ 2 - Chủ nhật (từ 06:00 đến 11:00)', '[''Được đào tạo chuyên môn, nâng cao kỹ năng'', ''Có cơ hội tiếp xúc với khách nước ngoài'', ''Môi trường làm việc hòa đồng, thân thiện'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (17, 9, 2, 'Nhân Viên Pha Chế', 'Pha chế, Phục vụ đồ uống theo đúng quy trình trong khu vực. Lưu tâm đối với các yêu cầu của khách hàng và những mong đợi của khách hàng. Xử lý yêu cầu của khách một cách hiệu quả. Theo dõi các hàng hóa được bán trong khu vực. Vệ sinh và thiết lập tự động các khu vực dịch vụ theo quy trình. Đảm bảo, duy trì và kiểm soát vấn đề vệ sinh và an toàn thực phẩm trong khu vực làm việc. Vệ sinh, chuẩn bị, sắp xếp Bar, bao gồm việc trang trí và làm thực đơn. Theo kịp xu hướng của thực phẩm và đồ uống.', 'Đam mê và yêu thích với ngành F&B và có kiến thức về các loại cà phê, đồ uống. Nhanh nhẹn, trung thực, kĩ tính và yêu thích công việc phục vụ khách hàng. Có kĩ năng giao tiếp, quan sát, nắm bắt các nhu cầu của khách hàng. Siêng năng, chủ động trong công việc và có tinh thần làm việc nhóm. Có kinh nghiệm làm barista hoặc trong lĩnh vực dịch vụ ăn uống. Thái độ làm việc vui vẻ, chuyên nghiệp, có kỹ năng giải quyết vấn đề, chịu được áp lực cao. Biết giao tiếp tiếng Anh hoặc tiếng Hàn sẽ là một ưu thế lớn.
Kỹ năng chuyên môn: [''Kiến thức về các loại cà phê, đồ uống'', ''Kỹ năng pha chế'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Trung thực'', ''Kĩ tính'', ''Yêu thích công việc phục vụ khách hàng'', ''Kỹ năng giao tiếp'', ''Tinh thần làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 9000000.00, '7.0 - 9.0 triệu', '8 tiếng (Ca sáng: 6h30 - 14h30, Ca tối: 14h30 - 22h30)', '[''Thưởng lương tháng 13'', ''Tăng lương hàng năm'', ''Du lịch, sinh nhật, hiếu hỷ'', ''Bảo hiểm xã hội theo quy định Nhà nước'', ''Phụ cấp ăn trưa'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (18, 10, 2, 'Nhân Viên Phục Vụ Nhà Hàng', 'Thực hiện công việc phối hợp với bộ phận Bếp, Phục vụ để lên món ăn và phục vụ món ăn cho khách hàng. Công việc sẽ được đào tạo khi vô làm, được thuyên chuyển vị trí để học hỏi thêm, có lộ trình lên Giám sát, Quản lý cụ thể. Được ưu tiên bố trí làm tại nhà hàng gần nhà, thuận tiện di chuyển.', 'KHÔNG yêu cầu kinh nghiệm, được đào tạo chuyên môn. Ứng viên chưa có kinh nghiệm nhưng qua trường lớp đào tạo/hoặc đang học là một lợi thế. Ưu tiên các bạn tốt nghiệp từ Trung cấp trở lên.', 'PART_TIME', 'REMOTE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '4.0 - 8.0 triệu', '5-6 tiếng', '[''Lương, thưởng hấp dẫn'', ''Phụ cấp tiền ăn đến 800.000đ/tháng'', ''Thưởng thành tích, thưởng tháng 13, 14'', ''Ưu đãi từ 10% tại tất cả nhà hàng thuộc hệ thống Golden Gate'', ''Cơ hội phát triển, lộ trình thăng tiến rõ ràng'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (19, 2, 2, 'Nhân Viên Phụ Bếp', 'Chuẩn bị, sơ chế nguyên vật liệu, gia vị và chế biến món ăn theo menu và chỉ thị từ quản lý. Đảm bảo vệ sinh khu vực bếp, dụng cụ nấu ăn và nguyên liệu theo tiêu chuẩn an toàn thực phẩm. Hỗ trợ quản lý trong việc quản lý nguyên liệu và kiểm soát lượng thực phẩm. Hợp tác với các bộ phận khác để đảm bảo món ăn được phục vụ đúng thời gian. Bảo trì và sử dụng thiết bị bếp đúng cách.', 'Nam/nữ từ 18 tuổi. Có kinh nghiệm bếp 6 tháng - 1 năm, ưu tiên có kinh nghiệm từng làm nhà hàng Nhật Bản. Biết tiếng Nhật hoặc tiếng Anh là một lợi thế. Chăm chỉ, cẩn thận, sạch sẽ. Có thể sắp xếp làm từ 4 ca/ tuần, 1 ca từ 5 tiếng và làm được các buổi tối và cuối tuần.
Kỹ năng chuyên môn: [''Biết tiếng Nhật hoặc tiếng Anh'']
Kỹ năng mềm: [''Chăm chỉ'', ''Cẩn thận'', ''Sạch sẽ'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Tối thiểu 20h/ tuần, mỗi ca từ 5h', '[''Phụ cấp gửi xe: 15.000 VNĐ/ngày'', ''Hỗ trợ tiền teamwork 300.000 VNĐ/tháng'', ''Bữa ăn tại nhà hàng cho ca làm từ 6 tiếng trở lên'', ''Tip'', ''Thưởng giới thiệu món'', ''Cơ hội thăng tiến lên chính thức'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (20, 3, 2, 'Nhân Viên Phục Vụ', 'Tuỳ từng vị trí hàng ngày được phân công tại khu vực phục vụ: Tư vấn, order, lên món phục vụ khách hàng; Dọn dẹp, set up bàn ăn theo quy định; Thu ngân (Tuỳ theo sự sắp xếp của quản lý).', 'Tuổi 18 – 25; Ưu tiên có thể làm cuối tuần, các ngày Lễ, Tết; Chăm chỉ, nhanh nhẹn, năng động, trung thực; Không yêu cầu kinh nghiệm; Khả năng giao tiếp tốt.
Kỹ năng mềm: [''Chăm chỉ'', ''Nhanh nhẹn'', ''Năng động'', ''Trung thực'', ''Khả năng giao tiếp tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.5 triệu', '4 – 6h/ngày, 4 – 5 ngày/tuần', '[''Thu nhập hấp dẫn: 25,500đ (tăng lương theo mức chuẩn của công ty nếu làm lâu dài)'', ''Có cơ hội được thăng tiến trở thành nhân viên chính thức và phát triển lên các vị trí quản lý nhà hàng'', ''Nghỉ 1 - 2 ngày/tuần, theo sự sắp xếp của quản lý'', ''Bảo hiểm tai nạn 24/24'', ''Được sắp xếp thời gian làm việc theo lịch học và nơi làm việc thuận tiện nhất'', ''Đào tạo nghiệp vụ nhà hàng miễn phí'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (21, 7, 2, 'Nhân Viên Phục Vụ Nhà Hàng', 'Đón tiếp, hướng dẫn khách hàng vào bàn và giới thiệu thực đơn. Tiếp nhận oder, bấm bill, phục vụ món và đảm bảo chất lượng dịch vụ, trải nghiệm khách hàng. Dọn dẹp, đảm bảo khu vực làm việc sạch sẽ, gọn gàng. Thực hiện, hỗ trợ các công việc khác theo chỉ đạo của quản lý.', 'Nữ ngoại hình ưa nhìn, tự tin giao tiếp. Không yêu cầu kinh nghiệm, có kinh nghiệm là điểm cộng. Ưu tiên UV từng có kinh nghiệm làm tại nhà hàng Nhật. Biết tiếng Nhật là một lợi thế.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Khả năng chịu áp lực'', ''Nhanh nhẹn'', ''Hoạt bát'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '1 tuần làm 4 ca, 1 ca từ 5 tiếng trở lên', '[''Teamwork party 300.000 VND/ tháng'', ''Bao cơm đối với ca làm 6 tiếng trở lên'', ''Phụ cấp gửi xe 15.000 VND/ ngày'', ''Thưởng, tips'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (22, 8, 2, 'Nhân Viên Phục Vụ Bàn', 'Phục vụ khách hàng dùng bữa. Tư vấn thêm cho khách hàng về thực đơn, đồ uống... Dọn dẹp bàn ăn trong quá trình khách dùng bữa. Setup khu vực phục vụ vào đầu các ca phục vụ.', 'Nam, Nữ, sức khỏe tốt. Tuổi từ 18 - 28. Có thể làm full time là 1 lợi thế. Ưu tiên ứng viên đã từng làm tại các nhà hàng.
Kỹ năng mềm: [''Nhanh nhẹn'', ''Nhiệt tình'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '6.0 - 7.5 triệu', '9h30 - 14h30 và 17h - 22h', '[''Ăn trưa'', ''Thưởng tháng 13'', ''Phụ cấp thâm niên'', ''Đào tạo nâng cao năng lực thường xuyên'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (23, 9, 2, 'Nhân Viên Thu Ngân Siêu Thị', 'Phục vụ khách hàng tại điểm bán và tại khu vực thu ngân. Thu tiền và hỗ trợ khách hàng trong việc thanh toán. Tư vấn hỗ trợ cho khách hàng về các hình thức thanh toán, các chương trình khuyến mại. Đảm bảo hình ảnh cửa hàng luôn gọn gàng, sạch đẹp và không khí cửa hàng luôn thân thiện, ấm cúng. Hỗ trợ Cửa hàng trưởng theo dõi hàng hoá xuất nhập, bảo quản hoá đơn chứng từ thu chi tại điểm bán. Xử lý đơn hàng tại điểm cửa hàng. Tiếp nhận và hỗ trợ xử lý các vấn đề, khiếu nại của khách hàng tại điểm bán. Quản lý, bảo quản cơ sở vật chất, hàng hoá tại điểm bán. Hỗ trợ kiểm kê hàng hoá thường xuyên và theo lịch của Công ty. Đảm bảo doanh thu theo kế hoạch của cửa hàng và doanh thu được phân bổ cho cá nhân. Chủ động tìm hiểu và học hỏi kiến thức về sản phẩm, về thị trường, kỹ năng mềm. Thực hiện các nhiệm vụ khác theo phân công của CHT và Ban lãnh đạo công ty.', 'Chăm chỉ, nhanh nhẹn. Biết cơ bản về máy tính. Có tình yêu với nấu ăn là một lợi thế. Tốt nghiệp cao đẳng trở lên (có nhận sinh viên thực tập).
Kỹ năng chuyên môn: [''Biết cơ bản về máy tính'']
Kỹ năng mềm: [''Chăm chỉ'', ''Nhanh nhẹn'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '5.6 - 8.0 triệu', 'Ca sáng: 6h00 - 14h00, Ca chiều: 14h00 - 22h00', '[''Lương cơ bản 5.600.000 + thưởng doanh thu + thưởng cuối năm'', ''Không trễ lương'', ''Môi trường năng động, có nhiều hoạt động kết nối'', ''Lộ trình thăng tiến rõ ràng'', ''Chế độ bảo hiểm đầy đủ'', ''Thưởng lễ, tết'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (24, 10, 2, 'Thực Tập Sinh Khách Sạn', '• Kiểm tra, xác minh và báo cáo tình trạng phòng • Hỗ trợ làm sạch các phòng và khu vực được chỉ định • Đảm bảo rằng tất cả các yêu cầu của khách được thực hiện • Hỗ trợ giám sát trong việc kiểm tra khách trả phòng • Báo cáo cho giám sát bất kỳ tài sản bị mất có giá trị và trả lại cho văn phòng càng sớm càng tốt • Báo cáo mọi khiếu nại của khách, sự cố của những người khả nghi trên sàn cho giám sát', '• Sinh viên năm 3, 4 hoặc mới tốt nghiệp các trường Đại học/Cao đẳng • Ưu tiên sinh viên chuyên ngành Nhà hàng - Khách sạn, Du lịch,... • Chăm chỉ, có tinh thần học hỏi • Có sức khỏe tốt • Thời gian thực tập: 3 tháng • Thời gian làm việc: 8h-17h (5 ngày/tuần)
Kỹ năng mềm: [''Chăm chỉ'', ''Có tinh thần học hỏi'', ''Có sức khỏe tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 triệu', '8h-17h (5 ngày/tuần)', '[''Phụ cấp thực tập'', ''Phụ cấp ăn trưa: 40k/ngày'', ''Free đồng phục'', ''Gửi xe miễn phí tại hầm gửi xe của khách sạn'', ''Hỗ trợ báo cáo, mộc thực tập'', ''Được đào tạo hướng dẫn tận tình các quy trình, quy định của bộ phận Buồng phòng'', ''Được ưu tiên cơ hội trở thành nhân viên chính thức sau kỳ thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (25, 2, 2, 'Nhân Viên Lễ Tân Văn Phòng (Theo Ca)', 'Chào đón khách theo quy trình chuẩn. Thực hiện quy trình check-in, check-out cho khách. Hướng dẫn chi tiết về các gói thuê, tiện ích và dịch vụ của khu coworking. Cập nhật và theo dõi quản lý khách sử dụng coworking. Phối hợp với PA thực hiện kiểm tra vệ sinh & sắp xếp khu coworking theo checklist hàng ngày. Đảm bảo các thiết bị văn phòng luôn trong trạng thái sẵn sàng. Quản lý lịch đặt phòng họp. Gửi thư từ, bưu phẩm. Báo cáo và theo dõi việc khắc phục sự cố. Quản lý, mua sắm vật tư và thiết bị văn phòng. Phối hợp với các phòng/ban/bộ phận liên quan để giải quyết các vấn đề phát sinh.', 'Sinh viên năm 3,4 các trường Đại học, Cao đẳng chuyên ngành hành chính văn phòng, văn thư - lưu trữ, hoặc các ngành nghề liên quan khác. Ưu tiên ứng viên từng làm các công việc tại nhà hàng, quán cà phê,..hoặc các công việc hành chính. Kỹ năng giao tiếp tốt, ứng xử chuyên nghiệp. Chăm chỉ, chịu khó, nhanh nhẹn, hoạt bát. Cẩn thận, tỉ mỉ trong công việc. Sử dụng thành thạo Microsoft Office. Có trách nhiệm cao trong công việc, trung thực, trung thành với công ty. Làm việc xoay ca: 8:00-12:00, 13:30-17:30 hoặc 18:00-22:00. Yêu cầu làm việc tối thiểu 4h/ngày.
Kỹ năng chuyên môn: [''Sử dụng thành thạo Microsoft Office'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Chăm chỉ'', ''Chịu khó'', ''Nhanh nhẹn'', ''Hoạt bát'', ''Cẩn thận'', ''Tỉ mỉ trong công việc'', ''Có trách nhiệm cao trong công việc'', ''Trung thực'', ''Trung thành với công ty'']', 'PART_TIME', 'ONSITE', 'vinhomes ocean park, nghĩa trụ, văn giang', NULL, 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm việc xoay ca: 8:00-12:00, 13:30-17:30 hoặc 18:00-22:00', '[''Có thể xoay ca linh động'', ''Được đào tạo bài bản về nghiệp vụ lễ tân - hành chính'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Tham gia các sự kiện, hoạt động vui chơi giải trí tại công ty như: teambuilding, companytrip, sinh nhật công ty'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (26, 3, 2, 'Thực Tập Sinh Tiền Sảnh/ Front Office Trainee', 'Cung cấp cho khách sự chào đón nồng nhiệt và chăm sóc họ trong suốt thời gian lưu trú, từ khi kiểm tra để kiểm tra. Hỗ trợ khách với hành lý và bãi đậu xe của họ khi cần thiết. Tạo trải nghiệm độc đáo và cá nhân cho khách của chúng tôi bằng cách làm việc cùng với các bộ phận khác. Có thể giao tiếp trôi chảy bằng tiếng Anh. Là đam mê về các dịch vụ địa phương và địa phương. Thực hiện các công việc liên quan khác theo yêu cầu.', 'Good in communication, English skill, Active and Dynamic. Working 5 day(s) per week, 9.5 hours/day. Internship minimum 3 months.
Kỹ năng chuyên môn: [''Microsoft Excel'']
Kỹ năng mềm: [''Good in communication'', ''Active'', ''Dynamic'']', 'INTERNSHIP', 'ONSITE', 'cần thơ', 'Cần Thơ', 'MONTHLY', 1000000.00, '1.0 triệu', '5 ngày/tuần, 9.5 giờ/ngày', '[''Internship in a professional environment - 5-star international standard'', ''On the job training from basic to advanced'', ''Working with colleagues with many years of experience'', ''Internship allowance: 1,000,000 VND/ month'', ''Provided 01 meal/ working shift'', ''Certificate of completion'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (27, 7, 2, 'Barista (Nhân Viên Pha Chế Part-Time)', '- Đảm nhiệm công việc nhận order & pha chế đồ uống tại quán - Đảm bảo VSATTP tại khu vực quầy pha chế - Kiểm tra, báo cáo và kiểm soát kho nguyên liệu pha chế - Phát triển menu thời vụ, menu đặc biệt dịp lễ Tết (nếu cần)', 'Tốt nghiệp Cao đẳng trở lên (ưu tiên sinh viên năm cuối) Có kinh nghiệm làm việc từ 6 tháng trở lên Có kinh nghiệm làm việc ở vị trí pha chế quán cafe Ưu tiên có bằng cấp về lĩnh vực pha chế Trung thực, thân thiện, nhiệt tình trong công việc Có tinh thần trách nhiệm, cầu tiến
Kỹ năng chuyên môn: [''Kinh nghiệm làm việc ở vị trí pha chế quán cafe'', ''Có bằng cấp về lĩnh vực pha chế'']
Kỹ năng mềm: [''Trung thực'', ''Thân thiện'', ''Nhiệt tình trong công việc'', ''Có tinh thần trách nhiệm'', ''Cầu tiến'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Sáng: 9h-13h30, Chiều: 13h30-18h, Tối: 18h-22h30', '[''Lương từ 20k/h + thưởng hiệu suất'', ''Lịch làm linh hoạt'', ''Môi trường Gen Z trẻ trung, sáng tạo'', ''Cơ hội thăng tiến'', ''Ưu đãi nhân viên, giảm giá đồ ăn, thức uống & sự kiện tại quán'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (28, 8, 2, 'Nhân Viên Nhà Hàng', 'Chào đón và tư vấn món ăn cho thực khách. Chuẩn bị dụng cụ ăn uống và set up không gian đúng quy định. Dọn dẹp bàn và lau bàn sau khi khách dùng xong. Quản lý và bảo quản hàng hóa, thiết bị. Giữ gìn vệ sinh và sắp xếp khu vực làm việc. (không dọn WC)', 'Không yêu cầu kinh nghiệm. Trung thực, nhiệt tình, có trách nhiệm trong công việc. Kỹ năng giao tiếp tốt, giọng nói dễ nghe. Khả năng làm việc độc lập và làm việc nhóm. Nhanh nhẹn, hoạt bát.
Kỹ năng mềm: [''Trung thực'', ''Nhiệt tình'', ''Có trách nhiệm trong công việc'', ''Kỹ năng giao tiếp tốt'', ''Giọng nói dễ nghe'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Nhanh nhẹn'', ''Hoạt bát'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 9000000.00, '5.0 - 9.0 triệu', 'Xoay ca 6 tiếng, 8 tiếng hoặc ca gãy theo thời gian cửa hàng mở cửa từ 9h30 tới 23h', '[''Chế độ bảo hiểm theo luật lao động nếu gắn bó từ 6 tháng với công ty và muốn lên Fulltime'', ''Được đào tạo và học hỏi thêm nhiều kỹ năng'', ''Môi trường làm việc năng động, thân thiện'', ''Được tham gia các hoạt động tập thể, teambuilding'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (29, 9, 2, 'Thực Tập Sinh Lễ Tân Khách Sạn', 'Kết hợp với Operations & Customer Care Representative trong các công việc CSKH hàng ngày, bao gồm nhưng không giới hạn các công việc sau: làm thủ tục nhận phòng/trả phòng cho khách dài hạn & ngắn hạn, giải đáp các thắc mắc qua email và hotline và hỗ trợ đáp ứng các yêu cầu của khách dài hạn & ngắn hạn. Hỗ trợ trong các công việc chuẩn bị giấy tờ, cập nhật các file/folder sử dụng cho mục đích CSKH và quản lý dữ liệu khách hàng cũng như gửi những thông báo cần thiết cho khách dài hạn qua Mailchimp. Làm việc với các nhà cung cấp dịch vụ kỹ thuật (ví dụ: bảo trì thang máy, bảo trì hồ bơi, sửa chữa điện nước, điện lạnh, xử lý côn trùng, v.v.) để đảm bảo các vấn đề bảo trì/bảo dưỡng của khách lưu trú và toà nhà luôn được giải quyết kịp thời. Hỗ trợ bộ phận Buồng Phòng khi cần thiết để đảm bảo tình trạng phòng, tiêu chuẩn set up phòng hoặc các khu vực công cộng của toà nhà luôn được giữ ở tình trạng hoàn thiện nhất. Tham gia đóng góp ý kiến cho các sự kiện được tổ chức dành cho cư dân của tòa nhà hoặc các sự kiện khác được tổ chức trong tòa nhà. Các công việc khác liên quan đến vận hành & CSKH được giao từ Giám Sát Vận Hành & CSKH và/hoặc Tổng Giám Đốc.', 'Sinh viên đại học năm 2 trở lên với một trong các ngành liên quan đến kinh doanh. Làm việc 6 ngày/tuần, 8 giờ/ngày và thời gian thực tập từ 4-6 tháng. Có tư duy chăm sóc khách hàng tốt và mục tiêu nghề nghiệp trong tương lai là công việc liên quan tới chăm sóc khách hàng. Giao tiếp tốt Tiếng Anh là một yêu cầu bắt buộc. Sẵn sàng học và sử dụng các công cụ năng suất trực tuyến hàng ngày: Google Workspace, Asana, Slack, Etc. Thái độ tích cực với các công việc được giao và chú ý đến các chi tiết. Hoạt bát, thân thiện, trung thực.
Kỹ năng chuyên môn: [''Google Workspace'', ''Asana'', ''Slack'']
Kỹ năng mềm: [''Tư duy chăm sóc khách hàng'', ''Giao tiếp tốt'', ''Thái độ tích cực'', ''Chú ý đến chi tiết'', ''Hoạt bát'', ''Thân thiện'', ''Trung thực'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Công ty tổ chức bữa ăn thân mật hàng tháng'', ''Trà chiều mỗi tuần'', ''Được đào tạo bài bản và tích lũy kinh nghiệm thực tế'', ''Môi trường làm việc vui vẻ, năng động'', ''Thưởng lễ tết, tiền tip, mọi quyền lợi như nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (30, 10, 2, 'Nhân Viên Lễ Tân Spa (Biết Tiếng Anh)', 'Đón tiếp và tư vấn khách hàng về các dịch vụ spa. Xử lý các thông tin liên quan đến khách hàng. Tiếp nhận cuộc gọi, check tin nhắn fanpage, trả lời thông tin và ghi nhận lịch hẹn. Phân công công việc cho nhân viên, đảm bảo khu vực lễ tân luôn sạch sẽ và gọn gàng. Báo cáo doanh thu, quản lý đơn hàng và hàng hóa.', 'Có khả năng giao tiếp tốt tiếng Anh. Có khả năng giao tiếp, tư vấn, tương tác tốt với khách hàng. Không yêu cầu kinh nghiệm, sẽ được đào tạo. Trung thực, nhiệt tình và có trách nhiệm trong công việc.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Tư vấn'', ''Trung thực'', ''Nhiệt tình'', ''Có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 8000000.00, '7.0 - 8.0 triệu', 'Thứ 2 - Chủ nhật (từ 14:00 đến 20:00), 6 tiếng, xoay ca', '[''Lương cơ bản + hoa hồng + thưởng'', ''Lương tháng 13'', ''Thưởng lễ Tết'', ''Sinh nhật'', ''Các phúc lợi, chế độ xã hội đầy đủ'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (31, 2, 2, 'Nhân Viên Pha Chế', 'Làm việc với phong thái thoải mái, nhiệt tình và lịch sự, có hiểu biết về các sản phẩm và các quy trình phục vụ. Làm việc đúng giờ, hiệu quả, thái độ tận tâm, giúp đỡ khách hàng, phục vụ thân thiện. Linh động trong lịch làm việc. Sẵn sàng làm các công việc tổ trưởng giao, luôn tiếp nhận những góp ý mang tính xây dựng. Chào đón và hướng dẫn khách vào bàn khi khách đến và ra về. Đảm bảo thức ăn và các bộ phận đã chuẩn bị sẵn sàng trước khi phục vụ khách hàng. Đảm bảo hoàn tất các công việc phụ, vệ sinh đầu ca và cuối ca mỗi ngày. Phối hợp làm việc với đồng nghiệp, thực hiện các công việc khác theo sự phân công của Cấp trên.', 'Tốt nghiệp THPT trở lên. Tiếng Anh giao tiếp cơ bản. Thái độ tốt, chăm chỉ, chịu khó học hỏi. Chưa có kinh nghiệm sẽ được đào tạo. Yêu cầu cụ thể khác: Kỹ năng giao tiếp, lắng nghe, đàm phán…
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Lắng nghe'', ''Đàm phán'']', 'PART_TIME', 'ONSITE', 'tp hạ long', NULL, 'MONTHLY', 7000000.00, '6.0 - 7.0 triệu', '8 giờ/ngày, 06 ngày/tuần', '[''Lương + thưởng'', ''Phụ cấp cơm & gửi xe'', ''Thưởng Lễ/Tết'', ''Bảo hiểm bắt buộc'', ''Đánh giá năng lực và xem xét điều chỉnh lương hằng năm'', ''Được đào tạo bởi các Quản lý Cấp cao từ các Khách sạn & Nhà hàng 5 sao'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (32, 3, 2, 'Giám Sát Nhà Hàng', '- Hỗ trợ Quản lý nhà hàng quản lý việc kinh doanh tại nhà hàng - Duy trì, kiểm soát tiêu chuẩn về chất lượng dịch vụ, vệ sinh an toàn thực phẩm - Hỗ trợ các bộ phận, khu vực trong nhà hàng trong mọi tình huống - Hỗ trợ Quản lý nhà hàng thực hiện kế hoạch làm việc, tuyển dụng, đào tạo nhân viên - Sắp xếp, thực hiện các hoạt động marketing, sự kiện, chương trình khuyến mại,… - Báo cáo cuối ca, tuần, tháng và các công việc khác theo yêu cầu từ cấp trên', '- Trình độ học vấn: Tốt nghiệp Trung cấp trở lên. - Kinh nghiệm: Có kinh nghiệm và năng lực làm việc ở vị trí Giám sát Nhà hàng hoặc tương đương. - Kỹ năng cần thiết: Giao tiếp chủ động; Có kỹ năng quản lý và xử lý vấn đề; Có kĩ năng đào tạo và giao tiếp tốt. - Phẩm chất, tác phong: Chính trực, Trách nhiệm và cầu thị. - Ưu tiên: Có định hướng phát triển theo đuổi ngành F&B lâu dài.
Kỹ năng chuyên môn: [''Giao tiếp chủ động'', ''Kỹ năng quản lý'', ''Kỹ năng xử lý vấn đề'', ''Kỹ năng đào tạo'']
Kỹ năng mềm: [''Chính trực'', ''Trách nhiệm'', ''Cầu thị'']', 'PART_TIME', 'REMOTE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30), ca gãy hoặc xoay ca 6 ngày 1 tuần, nghỉ trưa 30''', '[''Thưởng KPI tháng'', ''Thưởng hiệu quả cuối năm'', ''Chế độ phúc lợi theo Luật định'', ''Môi trường làm việc chuyên nghiệp, thân thiện'', ''Cơ hội phát triển lên các vị trí cao hơn'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (33, 7, 2, 'Quản Lý Cửa Hàng', 'Chịu hoàn toàn trách nhiệm về hiệu quả kinh doanh của của hàng phụ trách. Đảm bảo vận hành hiệu quả cửa hàng theo quy định và chính sách PHỞ24. Lập kế hoạch và phân công trách nhiệm cho cấp dưới, theo dõi việc thực hiện. Đảm bảo sự hài lòng khách hàng trong mỗi ca làm việc. Bố trí nhân viên và dự trù hàng hóa phục vụ nhu cầu khách hàng và việc kinh doanh. Thúc đẩy doanh thu thông qua áp dụng các chương trình Marketing và đào tạo nhân viên kỹ năng gợi ý bán hàng. Chỉ đạo, đào tạo và phát triển nhân viên đảm bảo giữ người hiệu quả. Tuyển dụng nhân viên theo nhu cầu. Kiểm soát chi phí hàng hóa, nhân sự & chất lượng thực phẩm tại cửa hàng. Kiểm soát tốt việc đặt hàng, hàng tồn hiệu quả. Giám sát, vận hành cơ sở vật chất, máy móc cửa hàng. Tuân thủ & quản lý nhân viên thực thi các quy định, chính sách của công ty.', 'Kinh nghiệm 2 năm trợ lý, quản lý nhà hàng tại các chuỗi F&B. Biết kiểm soát COL, COG. Giao tiếp tốt. Lanh lẹ, trung thực, chịu khó. Kỹ năng quản lý tốt. Kỹ năng chăm sóc khách hàng tốt. Có thể mở ca từ 5h30 sáng.
Kỹ năng chuyên môn: [''Kiểm soát COL'', ''Kiểm soát COG'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Lanh lẹ'', ''Trung thực'', ''Chịu khó'', ''Kỹ năng quản lý tốt'', ''Kỹ năng chăm sóc khách hàng tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh, quận 10', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '6 ngày/ tuần - Ca làm: 5h30-14h, 14h-22h', '[''Mức lương cạnh tranh, tăng theo level'', ''Tham gia BHXH, BHYT, BHTN 100% lương'', ''Tham gia các hoạt động đào tạo của Công ty'', ''Lộ trình thăng tiến lên những vị trí cao'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (34, 8, 2, 'Nhân Viên Phục Vụ (Có Tiếng Nhật/ Part Time)', 'Chịu trách nhiệm thực hiện các công việc được giao để hỗ trợ vận hành trơn tru hoạt động hàng ngày của quán bar. Đảm bảo hình ảnh quán luôn chỉn chu, phục vụ đồ uống và dịch vụ tốt, làm hài lòng khách hàng và đúng với tiêu chuẩn hoạt động của quán.', 'Giao tiếp được bằng tiếng Nhật (ưu tiên N4 trở lên). Vui vẻ, nhanh nhẹn, trung thực và có tinh thần làm việc nhóm. Có thể làm ca tối (từ 17:00 trở đi); linh hoạt cuối tuần/lễ là lợi thế. Ưu tiên có kinh nghiệm phục vụ quán cà phê/bar nhỏ, hoặc từng làm trong môi trường tiếp khách Nhật.
Kỹ năng mềm: [''Vui vẻ'', ''Nhanh nhẹn'', ''Trung thực'', ''Tinh thần làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', 'Ca tối (từ 17:00 trở đi)', '[''Lương cạnh tranh theo ca hoặc tháng + thưởng + tip (20-25k/h)'', ''Được rèn luyện tiếng Nhật với khách thực tế'', ''Làm việc trong không gian nhỏ, thân thiện, ít áp lực'', ''Được đào tạo nếu chưa có kinh nghiệm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (35, 9, 2, 'Nhân Viên Phục Vụ', 'Phục vụ thức ăn cho khách, đảm bảo vệ sinh nhà hàng, thanh toán cho khách, kiểm kê, quản lý hàng hóa tại sảnh nhà hàng, pha chế, chế biến salad cho khách. Thời gian làm việc: Tối thiểu 4-5 ngày/tuần (đăng ký làm việc từ 4 tiếng/ngày) với thời gian làm việc xoay ca linh hoạt phù hợp với lịch học và lịch cá nhân.', 'Có kinh nghiệm càng tốt, không có kinh nghiệm thì sẽ được đào tạo. Chăm chỉ, thành thật, chịu chủ động học hỏi. Khả năng làm việc độc lập và làm việc nhóm. Có định hướng làm việc lâu dài. Có định hướng thăng tiến trong công việc. Ứng viên có trình độ từ trung cấp trở lên.
Kỹ năng mềm: [''Chăm chỉ'', ''Thành thật'', ''Chủ động học hỏi'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '4 tiếng/ca, tối thiểu 4 ca/tuần', '[''Môi trường thuận lợi để phát triển tiếng Hàn, tiếng Anh'', ''Có định hướng thăng tiến cho nhân viên'', ''Học hỏi về F&B và dịch vụ'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (36, 10, 2, 'Nhân Viên Nhà Hàng', 'Đón tiếp và hướng dẫn khách vào bàn. Ghi nhận order và phục vụ món ăn, nước uống. Hỗ trợ khách hàng trong suốt bữa ăn, đảm bảo trải nghiệm tốt nhất. Dọn dẹp, sắp xếp bàn ghế, giữ gìn không gian nhà hàng sạch sẽ. Hỗ trợ các công việc khác theo yêu cầu của quản lý.', 'Đủ 18 tuổi trở lên; Không yêu cầu kinh nghiệm, sẽ được đào tạo từ đầu. Chỉ cần bạn không ngại vất vả và sẵn sàng học hỏi; Có thể làm việc xoay ca, tối thiểu 5 ngày / tuần (Part-time: làm 5-6h); Khi làm ca tối thì có thể làm việc đến hơn 23h; Sức khỏe bình thường, tính cách nhiệt tình, hòa đồng và vui vẻ; Thái độ tích cực, hiểu được tư duy dịch vụ hướng đến khách hàng; Tinh thần đồng đội tốt, tinh thần trách nhiệm cao.
Kỹ năng mềm: [''Tính cách nhiệt tình'', ''Hòa đồng'', ''Vui vẻ'', ''Thái độ tích cực'', ''Tinh thần đồng đội tốt'', ''Tinh thần trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '5.0 - 6.0 triệu', 'Full-time: ca sáng 9:00 - 18:00 | Ca chiều: 14:00 - 23:00; Part-time: ca sáng: 8:00 - 14:00 hoặc 9:00 - 15:00 | ca chiều: 17:00 - 23:00', '[''Mức lương thưởng cạnh tranh'', ''Tham gia đầy đủ chế độ Bảo hiểm theo quy định khi ký hợp đồng chính thức (Full-time)'', ''Môi trường trẻ trung, năng động'', ''Công việc có tính kế thừa cao, gắn bó lâu dài, nhiều cơ hội phát triển & thăng tiến nội bộ'', ''Các hoạt động hàng năm dành cho nhân viên: Team Building, Đại hội thể thao, Tiệc cuối năm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (37, 2, 2, 'Front Office Trainee - Thực Tập Sinh Tiền Sảnh', 'Hỗ trợ bộ phận Tiền sảnh trong các hoạt động vận hành hàng ngày như chào đón khách, làm thủ tục check-in/check-out, giải đáp thắc mắc và cung cấp thông tin dịch vụ, đồng thời học hỏi thực tế về quy trình vận hành chuyên nghiệp tại khách sạn quốc tế.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các chuyên ngành Quản trị khách sạn, Du lịch, hoặc các ngành liên quan. Giao tiếp tiếng Anh cơ bản – trung bình, ưu tiên có khả năng giao tiếp tốt. Kỹ năng giao tiếp tốt, ngoại hình ưa nhìn, thân thiện, cầu tiến. Nhanh nhẹn, chịu khó, sẵn sàng làm việc theo ca (bao gồm cuối tuần và ngày lễ). Có định hướng phát triển sự nghiệp trong ngành khách sạn.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp tiếng Anh cơ bản – trung bình'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Ngoại hình ưa nhìn'', ''Thân thiện'', ''Cầu tiến'', ''Nhanh nhẹn'', ''Chịu khó'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Theo ca', '[''Được đào tạo thực tế trong môi trường khách sạn quốc tế chuyên nghiệp.'', ''Học hỏi kỹ năng lễ tân, giao tiếp, xử lý tình huống và hệ thống vận hành khách sạn.'', ''Hỗ trợ phụ cấp thực tập, bữa ăn trong ca và đồng phục.'', ''Có cơ hội trở thành nhân viên chính thức sau kỳ thực tập (tùy theo năng lực và nhu cầu tuyển dụng).'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (38, 3, 2, 'Nhân Viên Set Up Xưởng Cây Part-Time', 'Sắp xếp, set up cây lên kệ, chăm sóc cây tại cửa hàng; Đóng gói sản phẩm theo đúng quy trình; Check các đơn hàng hằng ngày theo địa điểm giao hàng; Báo cáo các sự vụ và các thông tin khác theo yêu cầu của Trưởng Cửa hàng.', 'Ưu tiên nam: Từ 18 - 25 tuổi; Có gu thẩm mỹ, đam mê làm hình ảnh đẹp, sạch sẽ, chỉnh chu; Có kỹ năng giao tiếp, giải quyết vấn đề; Tư duy tích cực, hỗ trợ nhóm, chăm chỉ, cầu tiến, trung thực, cẩn trọng; Có kinh nghiệm & yêu thích cây cối.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Giải quyết vấn đề'', ''Tư duy tích cực'', ''Hỗ trợ nhóm'', ''Chăm chỉ'', ''Cầu tiến'', ''Trung thực'', ''Cẩn trọng'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '3.3 - 6.5 triệu', 'Xoay ca Part-time linh hoạt', '[''Môi trường sôi động, nhiệt huyết, sáng tạo tại Tropical Forest'', ''Chính sách giảm giá cho nhân sự công ty khi sử dụng dịch vụ tại hệ thống'', ''Được đào tạo về tư duy triển khai, sáng tạo, phát triển năng lực'', ''Xăng xe'', ''Thưởng hiệu quả làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (39, 7, 2, 'Nhân Viên Phục Vụ', 'Chào đón khách và phục vụ khách. Đưa menu và giới thiệu về các chương trình khuyến mãi cho khách. Ghi lại order và nhắc lại order cho khách. Phục vụ món cho khách. Kiểm tra và hỗ trợ khách. Dọn dẹp trước và sau khi phục vụ xong. Một số công việc khác theo sự phân công của quản lý.', 'Tuổi từ 18 trở lên. Ngoại hình dễ nhìn. Chăm chỉ, siêng năng trong công việc. Trung thực gắn bó lâu dài với công việc. Giao tiếp được tiếng Anh cơ bản là 1 lợi thế.
Kỹ năng mềm: [''Chăm chỉ'', ''Siêng năng'', ''Trung thực'', ''Giao tiếp'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Xoay ca linh hoạt, Partime: 5-8 tiếng / ngày, Fulltime: 8 tiếng / ngày', '[''1 tuần nghỉ 1 ngày'', ''Phụ cấp tiền gửi xe, tiền ăn trong ca'', ''Giảm giá khi ăn tại hệ thống nhà hàng'', ''Thưởng tháng 13, lễ tết lương nhân ba'', ''Môi trường làm việc chuyên nghiệp, phong cách phương Tây'', ''Được hưởng tiền tip'', ''Môi trường làm việc năng động, thân thiện'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (40, 8, 2, 'Nhân Viên Chăm Sóc Khách Sảnh', 'Tiếp đón khách hàng tại quầy lễ tân, hướng dẫn khách vào làm Dịch vụ, tham quan hoặc mua sắm tại Toyota Nankai Hải Phòng. Liên hệ, hỗ trợ, sắp xếp các lịch hẹn Dịch vụ và ghi nhận thông tin từ khách hàng. Giải đáp thắc mắc, cung cấp thông tin cho khách hàng qua điện thoại và tin nhắn.', '• Ưu tiên nữ sinh viên mới ra trường, gần công ty là 1 lợi thế • Kỹ năng giao tiếp tốt, giọng nói dễ nghe, có khả năng xử lý tình huống. • Trung thực, chăm chỉ và có tinh thần trách nhiệm. • Ứng viên có ngoại hình
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Giọng nói dễ nghe'', ''Có khả năng xử lý tình huống'', ''Trung thực'', ''Chăm chỉ'', ''Có tinh thần trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hải phòng', 'Hải Phòng', 'MONTHLY', 7000000.00, '6.0 - 7.5 triệu', '8h00-12h00 hoặc 13h00-17h00 hoặc từ 8h00-17h00 tùy lịch học', '[''Lương 6,000,000 VND/giờ + thưởng phụ kiện + phụ cấp đi lại'', ''Hỗ trợ ăn trưa'', ''Môi trường làm việc thân thiện, trẻ trung và năng động'', ''Được hướng dẫn và đào tạo các kỹ năng giao tiếp, xử lý tình huống'', ''Cơ hội làm việc và trau dồi kinh nghiệm thực tế'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (41, 9, 2, 'Thực Tập Phòng Điều Hành', 'Cập nhật Danh sách khách hàng cho Phòng điều hành, Hỗ trợ tiếp khách, họp đoàn (nếu có), Hỗ trợ cho P. Điều hành – Công ty, Dịch thuật hồ sơ visa, Làm việc theo sự chỉ đạo của cấp trên.', '1. Sinh viên năm 4 (thuộc diện thực tập bắt buộc từ nhà trường) 2. Vi tính văn phòng: biết sử dụng word, excel 3. Kỹ năng tiếng Anh tốt 4. Tính cách * Cẩn thận, chi tiết, có tinh thần trách nhiệm cao * Nhiệt tình trong công việc. * Có khả năng nắm bắt công việc nhanh, vui vẻ, hòa đồng. * Thời gian thực tập tối thiểu 2 tháng
Kỹ năng chuyên môn: [''Vi tính văn phòng: biết sử dụng word, excel'', ''Kỹ năng tiếng Anh tốt'']
Kỹ năng mềm: [''Cẩn thận, chi tiết, có tinh thần trách nhiệm cao'', ''Nhiệt tình trong công việc'', ''Có khả năng nắm bắt công việc nhanh, vui vẻ, hòa đồng'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Môi trường năng động, có cơ hội phát huy khả năng'', ''Được hưởng chế độ theo quy định của Công ty'', ''Hướng dẫn làm đề tài tốt nghiệp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (42, 10, 2, 'Nhân Viên Nhà Hàng Phụ Bếp', 'Nhân viên Phụ Bếp: - Phụ trách các công việc khu vực bếp- Đảm bảo vệ sinh an toàn thực phẩm- Chuẩn bị nguyên vật liệu để chế biến món ăn- Thái lát thịt hoặc chế biến salad', 'Đủ 18 tuổi trở lên;Không yêu cầu kinh nghiệm, sẽ được đào tạo từ đầu. Chỉ cần bạn không ngại vất vả và sẵn sàng học hỏi;Có thể làm việc xoay ca, tối thiểu 5 ngày / tuần (Part-time: làm 5-6h, Full-time: làm 8-9h);Khi làm ca tối thì có thể làm việc đến hơn 23h;Sức khỏe bình thường, tính cách nhiệt tình, hòa đồng và vui vẻ;Thái độ tích cực, hiểu được tư duy dịch vụ hướng đến khách hàng; Tinh thần đồng đội tốt, tinh thần trách nhiệm cao.
Kỹ năng chuyên môn: [''Vệ Sinh An Toàn Thực Phẩm'', ''Kỹ Năng Chuẩn Bị Thực Phẩm'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Tinh thần đồng đội tốt'', ''Thái độ tích cực'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Có thể làm việc xoay ca, tối thiểu 5 ngày / tuần (Part-time: làm 5-6h, Full-time: làm 8-9h)', '[''Mức lương thưởng cạnh tranh'', ''Tham gia đầy đủ chế độ Bảo hiểm theo quy định khi ký hợp đồng chính thức (Full-time)'', ''Môi trường trẻ trung, năng động'', ''Các hoạt động hàng năm dành cho nhân viên: Team Building, Đại hội thể thao, Tiệc cuối năm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (43, 2, 2, 'Nhân Viên Thu Ngân', 'Nhân viên thu ngân chịu trách nhiệm thu tiền từ khách hàng khi họ mua hàng hóa hoặc sử dụng dịch vụ, bao gồm cả tiền mặt và thẻ tín dụng. Thực hiện việc in hóa đơn và kiểm tra lại để đảm bảo tính chính xác trước khi thanh toán. Quản lý và lưu trữ biên lai thanh toán, đảm bảo mọi giao dịch được ghi nhận chính xác. Đối chiếu quỹ tiền mặt hàng ngày và kiểm tra doanh thu để đảm bảo tính chính xác. Cung cấp dịch vụ khách hàng tốt, giải đáp thắc mắc và hỗ trợ khách hàng trong quá trình thanh toán.', 'Dưới 1 năm kinh nghiệm, chấp nhận ứng viên chưa có kinh nghiệm, sẽ được đào tạo và hướng dẫn. Siêng năng, chăm chỉ, ổn định lâu dài. Nhận thanh toán của khách hàng, đảm bảo chính xác về giá cả và số lượng của từng loại mặt hàng; cấp hóa đơn cho khách hàng. Giữ cho không gian làm việc luôn sạch sẽ.
Kỹ năng mềm: [''Siêng năng'', ''Chăm chỉ'', ''Giữ không gian làm việc sạch sẽ'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 7000000.00, '5.0 - 7.0 triệu', 'Ca sáng: 9h-16h, Ca tối: 16h-22h, Ca Phụ bếp: 07h00 - 14h30 hoặc 14h00 - 21h30', '[''Thu nhập ổn định hàng tháng'', ''Lộ trình thăng tiến rõ ràng'', ''Xét duyệt tăng lương khi làm tốt'', ''Thưởng nhân viên theo từng tháng'', ''Môi trường năng động, trẻ trung, chuyên nghiệp'', ''Quà các dịp lễ, sinh nhật, thưởng Tết'', ''Phụ cấp ăn, đi lại'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (44, 3, 2, 'Nhân Viên Pha Chế', 'Barista chịu trách nhiệm pha chế tất cả các sản phẩm đồ uống cho khách. Chào đón khách hàng với dịch vụ nhanh chóng, thân thiện và phát triển mối quan hệ với khách hàng bằng cách tìm hiểu nhu cầu, đồ uống yêu thích. Xử lý khiếu nại của khách hàng đúng cách.', 'Tuổi từ 18 trở lên. Chăm chỉ, siêng năng trong công việc. Trung thực gắn bó lâu dài với công việc. Giao tiếp được tiếng Anh cơ bản là 1 lợi thế. Có kinh nghiệm và kiến thức cơ bản về Cà phê (sử dụng máy pha cà phê và vẽ Latte).
Kỹ năng chuyên môn: [''Kiến thức cơ bản về Cà phê'', ''Sử dụng máy pha cà phê'', ''Vẽ Latte'']
Kỹ năng mềm: [''Chăm chỉ'', ''Siêng năng'', ''Trung thực'', ''Giao tiếp'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '5-6 tiếng / ngày (Partime), 8 tiếng/ngày (Full-Time)', '[''Nghỉ phép 1 ngày/tuần'', ''Lương thưởng, trợ cấp dịch vụ'', ''Trợ cấp tiền gửi xe và ăn uống'', ''Giảm giá khi ăn tại hệ thống nhà hàng'', ''Được tham gia đầy đủ các loại hình bảo hiểm theo quy định: BHXH, BHYT, BHTN'', ''Môi trường làm việc chuyên nghiệp'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (45, 7, 2, 'Nhân Viên Phụ Bếp', 'Nhận Order món ăn, Sơ chế nguyên vật liệu theo yêu cầu, Chuẩn bị món ăn theo menu: cơm lươn, xiên nướng, sashimi, sushi, … và chỉ thị từ quản lý, Giữ gìn vệ sinh khu vực làm việc, Đảm bảo an toàn thực phẩm.', 'Trình độ: Trung cấp, Cao đẳng, Đại học trở lên,... Nhanh nhẹn, hòa đồng làm việc nhóm tốt. Có tay nghề, sử dụng dao tốt. Có kinh nghiệm làm việc tại các nhà hàng ở vị trí tương đương. Có tinh thần học hỏi, chịu khó.
Kỹ năng chuyên môn: [''Sử dụng dao tốt'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Hòa đồng'', ''Làm việc nhóm tốt'', ''Có tinh thần học hỏi'', ''Chịu khó'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Giờ mở cửa: 10h-24h - Đăng ký ca làm từ 5 tiếng trở lên/ngày', '[''Lương giờ: 25,000VND đến 40,000VND/Giờ'', ''Phụ cấp gửi xe: 15,000VND/ngày đi làm'', ''Phụ cấp 1 bữa ăn cho ca làm từ 6 tiếng trở lên'', ''Party nhà hàng hằng tháng 300,000VND/người'', ''Cơ hội thăng tiến lên vị trí full time'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (46, 8, 2, 'Trợ Lý Quản Lý Nhà Hàng (Ca Tối)', 'Quản lý hoạt động hàng ngày của nhà hàng, đảm bảo chất lượng dịch vụ, vệ sinh môi trường và ổn định chất lượng món ăn. Tuyển dụng, đào tạo và quản lý nhân viên nhà hàng, xây dựng tinh thần đồng đội, thúc đẩy nhân viên làm việc hiệu quả. Xử lý các phản hồi và khiếu nại của khách hàng, đảm bảo sự hài lòng của khách và nâng cao trải nghiệm dùng bữa. Theo dõi việc thu mua hàng hóa, đảm bảo định mức tồn kho tối thiểu cho nhà hàng.', '1. Tuổi: 28 - 40 2. Kinh nghiệm: Tối thiểu 3 năm ở vị trí tương đương 3. Kỹ năng giao tiếp và xử lý vấn đề tốt 4. Kỹ năng lập kế hoạch, giám sát và đánh giá tốt 5. Có khả năng làm việc độc lập và theo nhóm. Chịu được áp lực công việc 6. Quản lý nhân sự, tuyển dụng, và đào tạo tốt 7. Sử dụng word, excel cơ bản
Kỹ năng chuyên môn: [''Sử dụng word'', ''Sử dụng excel cơ bản'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng xử lý vấn đề'', ''Kỹ năng lập kế hoạch'', ''Kỹ năng giám sát'', ''Kỹ năng đánh giá'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc theo nhóm'', ''Chịu được áp lực công việc'']', 'FREELANCE', 'ONSITE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 14000000.00, '12.0 - 14.0 triệu', 'Thứ 2 - Thứ 7 (từ 05:45 đến 14:45)', '[''Thưởng theo doanh thu'', ''Thưởng các ngày lễ trong năm'', ''Được đào tạo để phát triển lên vị trí cao hơn'', ''Tháng nghỉ 3 ngày'', ''Ăn sáng và trưa tại nhà hàng (có hỗ trợ ăn ở nếu nhân sự ở xa)'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (47, 9, 2, 'Nhân Viên Thu Ngân Nhà Hàng', '- Thực hiện các công việc mở ca - Ghi nhận thông tin order - Thực hiện quy trình thanh toán cho khách - Hỗ trợ, xử lý các vấn đề phát sinh trong ca làm việc - Các công việc khác trong ca theo yêu cầu của cấp trên - Chi tiết công việc trao đổi cụ thể khi phỏng vấn', '- Ưu tiên có kinh nghiệm thu ngân hoặc vị trí tương đương. - Tuổi từ 18 đến 30 siêng năng và trung thực. Nhanh nhẹn, nhiệt tình trong công việc Giao tiếp tốt, ngoại hình ưa nhìn là một lợi thế.
Kỹ năng chuyên môn: [''Khả năng sử dụng máy tính tiền'', ''Khả năng xử lý tiền mặt và thẻ tín dụng'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Nhanh nhẹn'', ''Nhiệt tình trong công việc'', ''Siêng năng'', ''Trung thực'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 9000000.00, '7.0 - 9.0 triệu', 'Làm việc theo ca linh hoạt từ 06:45-12:00; 12:00-17:00; 17:00-23:00', '[''Thời gian làm việc linh hoạt'', ''Du lịch hàng năm cùng team'', ''Thưởng lễ, tết hấp dẫn'', ''Môi trường làm việc trẻ trung, năng động'', ''Tăng lương định kỳ & thưởng hiệu quả công việc'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (48, 10, 2, 'Cộng Tác Viên Du Lịch (Không Yêu Cầu Kinh Nghiệm)', 'Tư vấn và hỗ trợ khách hàng đặt vé máy bay nội địa & quốc tế. Chủ động tìm kiếm và tiếp cận khách hàng có nhu cầu các sản phẩm: Tour trong/ngoài nước, Combo khách sạn, vé máy bay, dịch vụ du lịch. Chăm sóc khách hàng qua các kênh: Zalo, Facebook, điện thoại, email,... Làm việc online tại nhà, không cần đến văn phòng. Báo cáo công việc khi cần và phối hợp xử lý các tình huống phát sinh (hoàn/hủy, đổi thông tin vé,...).', 'Kỹ năng giao tiếp tốt, có khả năng xây dựng mối quan hệ tốt với khách hàng. Chăm chỉ, chủ động tìm kiếm khách hàng. Yêu thích lĩnh vực du lịch và dịch vụ. Không yêu cầu kinh nghiệm.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Chăm chỉ'', ''Chủ động tìm kiếm khách hàng'', ''Yêu thích lĩnh vực du lịch và dịch vụ'']', 'FREELANCE', 'REMOTE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Không cần vốn'', ''Không ràng buộc thời gian'', ''Được ký hợp đồng để đảm bảo quyền lợi'', ''Đào tạo miễn phí 100%'', ''Cung cấp tài khoản tra vé chuyên nghiệp của hãng'', ''Có đội ngũ hỗ trợ riêng'', ''Cấp giấy chứng nhận cho các bạn sinh viên hoàn thành tốt công việc'', ''Hỗ trợ dấu thực tập cho sinh viên năm cuối'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (49, 2, 2, 'Nhân Viên Lễ Tân Spa (Biết Tiếng Hàn/ Tiếng Anh)', '- Đón tiếp và hỗ trợ khách hàng, chủ yếu là khách Hàn Quốc. - Giải đáp các thắc mắc của khách hàng về dịch vụ, sản phẩm, hoặc các vấn đề liên quan. - Tiếp nhận và xử lý các cuộc gọi, tin nhắn đặt lịch hẹn của khách hàng. - Ghi nhận thông tin khách hàng, cập nhật lịch sử sử dụng dịch vụ vào hệ thống. - Đảm bảo khu vực lễ tân luôn sạch sẽ, gọn gàng và chuyên nghiệp.', '- Nữ, độ tuổi: 19 - 28 tuổi - Ngoại ngữ: Tiếng Hàn hoặc Tiếng Anh. Ưu tiên ứng viên có thể Giao tiếp tiếng Hàn (99% khách hàng là người Hàn Quốc) - Phù hợp với các bạn đang học tiếng Hàn và muốn cải thiện kỹ năng giao tiếp - Ứng viên có thể đi làm ngay - Ưu tiên những bạn có mong muốn gắn bó lâu dài
Kỹ năng chuyên môn: [''Sử Dụng Phần Mềm Máy Tính (word, Excel)'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Quản lý thời gian'', ''Giao tiếp tốt'', ''Kỹ năng chăm sóc khách hàng'']', 'PART_TIME', 'ONSITE', 'quận 1', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Có thể xoay ca - Ca sáng: 9h30 - 19h30 - Ca chiều: 13h30 - 23h30 (Mỗi tháng OFF 4 ngày trừ T7,CN; lễ tân tự sắp xếp)', '[''Xét tăng lương mỗi 6 tháng'', ''Nhận 100% lương trong thời gian thử việc'', ''Tham gia BHXH sau 6 tháng làm việc'', ''Lương tháng 13'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (50, 3, 2, 'Nhân Viên Lễ Tân', 'Chào đón khách hàng với sự thân thiện và nhiệt tình. Hỗ trợ khách hàng đăng nhập vào hệ thống thành viên. Hỗ trợ soạn thảo hợp đồng giữa công ty và khách hàng. Đảm bảo sự vận hành trôi chảy của bộ phận dịch vụ khách hàng và cung cấp dịch vụ tối ưu đến tất cả hội viên. Bảo đảm rằng tất cả nhiệm vụ đều được hoàn thành theo chính sách và quy trình của công ty. Bảo đảm rằng hội viên nhận được giải đáp kịp thời cho tất cả các phản hồi và băn khoăn.', 'Tiếng Anh giao tiếp từ Khá trở lên. Kỹ năng Microsoft Office cơ bản. Thời gian làm việc: Part-time: tối thiểu 5h/ngày, 24h/tuần; Full-time: từ 5h30-14h30 hoặc từ 13h30-22h30, 6 ngày/tuần.
Kỹ năng chuyên môn: [''Kỹ năng Microsoft Office cơ bản'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Chăm Sóc Khách Hàng'', ''Giao tiếp tốt'', ''Kỹ năng xử lý tình huống'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '3.0 - 8.0 triệu', 'Part-time: tối thiểu 5h/ngày, 24h/tuần; Full-time: từ 5h30-14h30 hoặc từ 13h30-22h30, 6 ngày/tuần', '[''Tập luyện miễn phí tại các CLB California Fitness & Yoga'', ''Cơ hội làm việc trong môi trường chuyên nghiệp, sang trọng'', ''Tham gia các khóa đào tạo do công ty tổ chức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (51, 7, 2, 'Nhân Viên Thu Ngân Quầy Vé - Quầy F&B Parttime', '• Hỗ trợ & phối hợp tất cả các hoạt động của trung tâm • Tư vấn cho khách hàng về sản phẩm của trung tâm • Bán sản phẩm, dịch vụ & thanh toán cho khách hàng • Những nhiệm vụ khác khi được phân công khác', '• Ưu tiên Nữ • Yêu thích ngành hàng dịch vụ, thể thao, vui chơi giải trí • Có kinh nghiệm thu ngân, cashier là một lợi thế • Trung thực, năng động, nhiệt tình, chăm chỉ, ham học hỏi • Có thể làm việc theo ca
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp và phục vụ khách hàng tốt'', ''Có kinh nghiệm F&B (Food and Beverage Service)'']
Kỹ năng mềm: [''Trung thực'', ''Năng động'', ''Nhiệt tình'', ''Chăm chỉ'', ''Ham học hỏi'', ''Làm việc theo ca'']', 'PART_TIME', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Làm việc theo ca đăng ký với Quản lý trung tâm, trung bình 2-4h/ngày', '[''Làm việc trong môi trường năng động, được đào tạo kỹ năng chuyên môn'', ''Chính sách lương theo quy định của Nhà Nước'', ''Ngày lễ, Tết được tính theo mức lương X3 quy định nhà nước'', ''Bảo hiểm tai nạn 24/7'', ''Thưởng thêm hoa hồng doanh số'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (52, 8, 2, 'Thực Tập Sinh Kinh Doanh', '- Tư vấn khách về các chương trình tour, trao đổi về việc chỉnh sửa lịch trình theo nhu cầu của khách - Thiết kế tour - Liên hệ với các nhà cung cấp, đối tác của công ty - Theo dõi và chăm sóc khách hàng trước, trong, và sau tour - Thực hiện các công việc hành chính theo yêu cầu của ban lãnh đạo công ty.', 'Sinh viên ngành du lịch hoặc sinh viên chuyên ngành tiếng anh năm 3,4 hoặc sinh viên mới ra trường Tiếng anh giao tiếp tốt Trung thực, chăm chỉ, tình thần trách nhiệm Kỹ năng giao tiếp tốt
Kỹ năng chuyên môn: [''Tiếng anh giao tiếp tốt'']
Kỹ năng mềm: [''Trung thực'', ''Chăm chỉ'', ''Tinh thần trách nhiệm'', ''Kỹ năng giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Được đào tạo trở thành nhân viên chính thức'', ''Được tham gia các hoạt động của công ty'', ''Hỗ trợ dấu mộc công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (53, 9, 2, 'Thực Tập Sinh Kinh Doanh', 'Tìm kiếm danh sách nhà hàng phù hợp tại khắp các tỉnh thành phố lớn và các địa diểm du lịch nổi tiếng tại Việt Nam. Liên hệ gửi thông tin mời hợp tác dành cho nhà hàng. Hỗ trợ tư vấn, giới thiệu và kinh doanh các gói dịch vụ marketing dành cho nhà hàng. Hỗ trợ xây dựng và duy trì mối quan hệ với các đối tác nhà hàng. Được tham gia xây dựng chiến lược kinh doanh và phát triển từng thị trường, khu vực.', 'Sinh viên năm 3, 4 hoặc mới tốt nghiệp chuyên ngành Kinh doanh, Marketing hoặc các lĩnh vực liên quan. Kỹ năng giao tiếp tốt, năng động, có trách nhiệm trong công việc. Yêu thích ngành ẩm thực, kinh doanh và marketing.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Năng động'', ''Có trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Sáng Thứ 7: 8h00 đến 17h (Làm 2 ngày thứ 7 trong tháng)', '[''Mức thù lao: 2 triệu đồng/tháng + Thưởng KPI'', ''Phụ cấp vé xe hàng tháng'', ''Hỗ trợ làm báo cáo thực tập, đóng dấu xác nhận thực tập'', ''Cơ hội được tuyển dụng chính thức sau khi hoàn thành kỳ thực tập'', ''Học hỏi và phát triển kỹ năng kinh doanh thực tiễn'', ''Đào tạo bài bản từ đội ngũ chuyên gia giàu kinh nghiệm'', ''Thời gian làm việc linh hoạt, môi trường trẻ, năng động,… trang phục tự do.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (54, 10, 2, 'Sales Tour Outbound Và Nội Địa Part-Time', '- Tư vấn khách hàng về tour du lịch thị trường nội địa, outbound... trên data khách hàng của Công ty - Thiết kế, tính giá, đàm phán dịch vụ với các đối tác nước ngoài để xây dựng sản phẩm theo nhu cầu của khách hàng - Phối hợp cùng bộ phận Marketing đánh giá thị trường, định vị khách hàng – sản phẩm - Lập báo cáo công việc hàng tuần gửi quản lý trực tiếp.', '- Đang học chuyên ngành du lịch tại các trường Cao đẳng, Đại học trở lên - Thành thạo sử dụng các công cụ tin học văn phòng - Khả năng làm việc độc lập, nắm bắt công việc tốt, nhanh nhẹn, linh hoạt, xử lý tình huống tốt, có tinh thần hợp tác chặt chẽ với các bộ phận với tinh thần làm việc tập thể cao - Chăm chỉ, cẩn thận, nhiệt tình - Kỹ năng tổ chức và quản lý công việc hiệu quả.
Kỹ năng chuyên môn: [''Thành thạo sử dụng các công cụ tin học văn phòng'']
Kỹ năng mềm: [''Khả năng làm việc độc lập'', ''Nắm bắt công việc tốt'', ''Nhanh nhẹn'', ''Linh hoạt'', ''Xử lý tình huống tốt'', ''Có tinh thần hợp tác chặt chẽ với các bộ phận'', ''Chăm chỉ'', ''Cẩn thận'', ''Nhiệt tình'', ''Kỹ năng tổ chức và quản lý công việc hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 làm việc cách tuần', '[''Lương cố định + thưởng theo doanh số và hiệu quả công việc mang lại'', ''Xem xét ký hợp đồng chính thức nếu làm việc mang lại hiệu quả cao'', ''Ưu tiên tuyển sinh viên làm thêm theo thời gian hai bên có thể thoả thuận'', ''Được đào tạo nghiệp vụ chuyên nghiệp về bán tour Outbound và Nội địa'', ''Có cơ hội tham gia các chương trình trải nghiệm thực tế cùng công ty'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (55, 2, 2, 'Thực Tập Sinh Sales Tiếng Anh/Ý/Tây Ban Nha', 'Hỗ trợ quá trình hoàn thiện nội dung trên hệ thống/website. Thực hiện các nhiệm vụ liên quan đến nhập dữ liệu (chương trình/giá). Hỗ trợ tư vấn khách hàng, xây dựng chương trình tour. Thực hiện các công việc khác dưới sự phân công của người hướng dẫn. Chi tiết công việc sẽ được trao đổi cụ thể hơn khi phỏng vấn, không áp KPI, thoải mái về thời gian, lộ trình thăng tiến rõ ràng nếu bạn có năng lực.', 'Cẩn thận, chủ động, có trách nhiệm trong công việc. Cầu tiến, chăm chỉ, nhiệt tình. Tiếng Anh/ Tiếng Ý/ Tiếng Tây Ban Nha/ tiếng Trung: 4 kỹ năng Khá trở lên. Sinh viên từ năm 2,3,4 chuyên ngành về Du lịch/Ngôn Ngữ/Quản trị kinh doanh. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Tiếng Anh'', ''Tiếng Ý'', ''Tiếng Tây Ban Nha'']
Kỹ năng mềm: [''Cẩn thận'', ''Chủ động'', ''Có trách nhiệm'', ''Cầu tiến'', ''Chăm chỉ'', ''Nhiệt tình'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được đào tạo kiến thức về thị trường du lịch'', ''Được tham gia vào công việc thực tế'', ''Hỗ trợ chi phí đi lại + ăn trưa'', ''Thời gian linh động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (56, 3, 2, 'Thực Tập Sinh Điều Hành Tour', 'Chịu trách nhiệm tổ chức, thu xếp dịch vụ cho khách inbound vào Việt Nam. Điều chỉnh và phân công trách nhiệm cho hướng dẫn viên du lịch phụ trách chuyến đi. Quản lý & cập nhật cơ sở dữ liệu tuyến điểm các nhà cung cấp dịch vụ theo tuyến điểm. Làm việc với các nhà cung cấp dịch vụ như nhà hàng, khách sạn, xe, điểm tham quan… để đàm phán về cách thức, chất lượng và mức giá tốt. Chuẩn bị giấy tờ, hồ sơ đoàn theo hướng dẫn (Riêng ở HCM). Thu hồ sơ của guide, chụp hình vé, cập nhật cho team điều hành & kế toán (Riêng ở HCM). Chi tiết công việc sẽ được trao đổi cụ thể hơn khi phỏng vấn, không áp KPI, thoải mái về thời gian, lộ trình thăng tiến rõ ràng nếu bạn có năng lực.', 'Cẩn thận, chủ động, có trách nhiệm trong công việc. Cầu tiến, chăm chỉ, nhiệt tình. Sinh viên từ năm 2,3,4 chuyên ngành về Du lịch/Ngôn Ngữ. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Sử dụng laptop'']
Kỹ năng mềm: [''Cẩn thận'', ''Chủ động'', ''Có trách nhiệm'', ''Cầu tiến'', ''Chăm chỉ'', ''Nhiệt tình'']', 'INTERNSHIP', 'ONSITE', 'hà nội, đà nẵng', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được đào tạo kiến thức về thị trường du lịch'', ''Hỗ trợ chi phí đi lại + ăn trưa (từ 1-3tr/24 công)'', ''Thời gian linh động'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (57, 7, 2, 'Nhân Viên Sale (Part Time)', 'Giới thiệu dịch vụ quản lý vận hành OTA của công ty đến các chủ khách sạn, homestay villa… trên toàn quốc. Hình thức làm việc: làm online- Tìm kiếm khách sạn, villa tiềm năng và xây dựng mối quan hệ với chủ khách sạn, villa - Tư vấn, giải đáp thắc mắc và đặt lịch hẹn với các chủ cơ sở lưu trú quan tâm- Data các cơ sở lưu trú sẽ được công ty hướng dẫn thu thập. - Kịch bản nhắn tin và dịch vụ công ty sẽ được bộ phận quản lý thực tập đào tạo. - Báo cáo với bộ phận quản lý part time: các phản hồi của khách hàng. - Chốt hẹn và gửi thông tin cho quản lý để Venue chốt hợp đồng - Báo cáo công việc hàng tuần theo yêu cầu của quản lý. Mục tiêu hàng ngày: Tiếp cận tối thiểu 100 chủ khách sạn/villa , Chốt ít nhất 10 lịch hẹn với các chủ cơ sở quan tâm.', 'Sinh viên năm 2,3,4 các trường đại học, cao đẳng. Có tinh thần trách nhiệm trong công việc. Giao tiếp tốt, nhanh nhẹn, nhiệt tình. Không yêu cầu kinh nghiệm.
Kỹ năng mềm: [''Có tinh thần trách nhiệm trong công việc'', ''Giao tiếp tốt'', ''Nhanh nhẹn'', ''Nhiệt tình'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.7 - 3.0 triệu', 'Chọn ca sáng hoặc ca chiều', '[''Được đào tạo cách sale và làm việc với các chủ khách sạn'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (58, 8, 2, 'Nhân Viên Thu Ngân', 'Nhập order vào hệ thống, in hóa đơn và thanh toán cho khách. Đảm bảo hóa đơn chính xác, xử lý thanh toán tiền cho khách. Ghi nhận doanh thu, bàn giao quỹ cuối ca đầy đủ. Hỗ trợ trả lời thông tin về giá cả. Phối hợp công việc với bộ phận bếp và phục vụ để vận hành công việc trơn tru.', 'Nam/Nữ, trên 18 tuổi. Có kinh nghiệm thu ngân là một lợi thế. Cẩn thận và phối hợp tốt trong công việc. Có thể làm việc linh hoạt, làm tối thiểu 5 ca/tuần.
Kỹ năng mềm: [''Cẩn thận'', ''Phối hợp tốt trong công việc'', ''Làm việc linh hoạt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '4 - 6 tiếng', '[''Hỗ trợ 1 suất ăn ca nếu làm trên 4 giờ'', ''Được đào tạo kĩ năng miễn phí'', ''Cung cấp đầy đủ thiết bị và thông tin phục vụ công việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (59, 9, 2, 'Nhân Viên Thu Ngân (Part - Time)', 'Nhập order vào hệ thống, in hóa đơn và thanh toán cho khách. Đảm bảo hóa đơn chính xác, xử lý thanh toán tiền cho khách. Ghi nhận doanh thu, bàn giao quỹ cuối ca đầy đủ. Hỗ trợ trả lời thông tin về giá cả. Phối hợp công việc với bộ phận bếp và phục vụ để vận hành công việc trơn tru.', 'Nam/Nữ, trên 18 tuổi. Có kinh nghiệm thu ngân là một lợi thế. Cẩn thận và phối hợp tốt trong công việc. Có thể làm việc linh hoạt, làm tối thiểu 5 ca/tuần.
Kỹ năng chuyên môn: [''Khả năng sử dụng máy tính tiền'', ''Khả năng xử lý tiền mặt và thẻ tín dụng'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Khả năng làm việc dưới áp lực'', ''Cẩn thận và phối hợp tốt trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'xoay ca linh hoạt 4 - 6 tiếng', '[''Được đào tạo kĩ năng miễn phí'', ''Được cung cấp đầy đủ thiết bị và thông tin phục vụ công việc'', ''Hỗ trợ 1 suất ăn ca nếu làm trên 4 giờ'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (60, 10, 2, 'Tour Guide Part-Time Hè 2025 (Nữ)', 'Công việc của chúng tôi đòi hỏi các tài xế phải hộ tống khách hàng của chúng tôi một cách an toàn trong nhóm và các tour du lịch riêng của chúng tôi thông qua xe máy của họ. Trình điều khiển của chúng tôi được đào tạo về dịch vụ khách hàng, tuyến du lịch, kiến ​​thức thực phẩm và đào tạo an toàn.', 'Requirements: -A working motorbike that is in great shape. Automatic motorbikes are preferred. -Extremely fun and interesting personality. Someone who loves to talk and laugh! -English speaking skills that are considered fluent, especially in proper grammar and pronunciation.
Kỹ năng chuyên môn: [''Kỹ năng lái xe'', ''Kỹ năng giao tiếp'', ''Kỹ năng tiếng Anh'']
Kỹ năng mềm: [''Teamwork'', ''Giao tiếp'', ''Tính cách vui vẻ, thú vị'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 7000000.00, '3.0 - 7.0 triệu', '1 PM – 5 PM, 6 PM – 10 PM', '[''Tips'', ''Ngày nghỉ linh hoạt'', ''Môi trường làm việc chuyên nghiệp'', ''Đào tạo'', ''Bữa tối/tiệc cho nhân viên'', ''Chuyến đi công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (61, 2, 2, 'Nhân Viên Phục Vụ Nhà Hàng', 'Đón tiếp và hướng dẫn khách vào bàn. Ghi nhận order và phục vụ món ăn, nước uống. Hỗ trợ khách hàng trong suốt bữa ăn, đảm bảo trải nghiệm tốt nhất. Dọn dẹp, sắp xếp bàn ghế, giữ gìn không gian nhà hàng sạch sẽ. Hỗ trợ các công việc khác theo yêu cầu của quản lý.', 'Đủ 18 tuổi trở lên; Không yêu cầu kinh nghiệm, sẽ được đào tạo từ đầu. Chỉ cần bạn không ngại vất vả và sẵn sàng học hỏi; Có thể làm việc xoay ca, tối thiểu 5 ngày / tuần (Part-time: làm 5-6h); Khi làm ca tối thì có thể làm việc đến hơn 23h; Sức khỏe bình thường, tính cách nhiệt tình, hòa đồng và vui vẻ; Thái độ tích cực, hiểu được tư duy dịch vụ hướng đến khách hàng; Tinh thần đồng đội tốt, tinh thần trách nhiệm cao.
Kỹ năng mềm: [''Làm việc nhóm'', ''Phục Vụ Khách Hàng'', ''Giao tiếp tốt'', ''Khả Năng Chịu Áp Lực'', ''Nhanh Nhẹn'', ''Hoạt Bát'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Part-time: 5-6h/ngày, có thể làm ca tối đến hơn 23h', '[''Mức lương thưởng cạnh tranh'', ''Tham gia đầy đủ chế độ Bảo hiểm theo quy định khi ký hợp đồng chính thức (Full-time)'', ''Môi trường trẻ trung, năng động'', ''Cơ hội phát triển & thăng tiến nội bộ'', ''Các hoạt động hàng năm dành cho nhân viên: Team Building, Tiệc cuối năm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (62, 3, 2, 'Nhân Viên Phục Vụ', 'Nhân viên Phục vụ: - Tiếp nhận order của khách hàng - Tư vấn sản phẩm cho khách hàng - Phục vụ khách hàng - Đảm bảo vệ sinh an toàn thực phẩm - Vận chuyển món ăn đến khách hàng', 'Đủ 18 tuổi trở lên; Không yêu cầu kinh nghiệm, sẽ được đào tạo từ đầu. Chỉ cần bạn không ngại vất vả và sẵn sàng học hỏi; Có thể làm việc xoay ca, tối thiểu 5 ngày / tuần (Part-time: làm 5-6h, Full-time: làm 8-9h); Khi làm ca tối thì có thể làm việc đến hơn 23h; Sức khỏe bình thường, tính cách nhiệt tình, hòa đồng và vui vẻ; Thái độ tích cực, hiểu được tư duy dịch vụ hướng đến khách hàng; Tinh thần đồng đội tốt, tinh thần trách nhiệm cao.
Kỹ năng mềm: [''Làm việc nhóm'', ''Phục Vụ Khách Hàng'', ''Giao tiếp tốt'', ''Quản Lý Thời Gian Hiệu Quả'', ''Khả Năng Chịu Áp Lực Cao'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '4.0 - 8.0 triệu', 'Ca sáng: 8h – 17h, Ca tối: 14h – 22h', '[''Tham gia đầy đủ chế độ Bảo hiểm theo quy định khi ký hợp đồng chính thức (Full-time)'', ''Môi trường trẻ trung, năng động'', ''Công việc có tính kế thừa cao, gắn bó lâu dài, nhiều cơ hội phát triển & thăng tiến nội bộ'', ''Các hoạt động hàng năm dành cho nhân viên: Team Building, Đại hội thể thao, Tiệc cuối năm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (63, 7, 2, 'Nhân Viên Pha Chế', 'Làm việc với phong thái thoải mái, nhiệt tình và lịch sự, có hiểu biết về các sản phẩm và các quy trình phục vụ. Làm việc đúng giờ, hiệu quả, thái độ tận tâm, giúp đỡ khách hàng, phục vụ thân thiện. Linh động trong lịch làm việc. Sẵn sàng làm các công việc tổ trưởng giao, luôn tiếp nhận những góp ý mang tính xây dựng. Chào đón và hướng dẫn khách vào bàn khi khách đến và ra về. Đảm bảo thức ăn và các bộ phận đã chuẩn bị sẵn sàng trước khi phục vụ khách hàng. Đảm bảo hoàn tất các công việc phụ, vệ sinh đầu ca và cuối ca mỗi ngày. Phối hợp làm việc với đồng nghiệp, thực hiện các công việc khác theo sự phân công của Cấp trên.', 'Tốt nghiệp Trung cấp nghề trở lên. Tiếng Anh giao tiếp cơ bản. Thái độ tốt, chăm chỉ, chịu khó học hỏi. Chưa có kinh nghiệm sẽ được đào tạo.
Kỹ năng chuyên môn: [''Tiếng Anh giao tiếp cơ bản'']
Kỹ năng mềm: [''Thái độ tốt'', ''Chăm chỉ'', ''Chịu khó học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '8 giờ/ngày, 06 ngày/tuần', '[''Lương + thưởng + Tips'', ''Phụ cấp ca gãy'', ''Phụ cấp cơm & gửi xe'', ''Thưởng Lễ/Tết'', ''Bảo hiểm bắt buộc'', ''Được đào tạo bởi các Quản lý Cấp cao từ các Khách sạn & Nhà hàng 5 sao'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (64, 8, 2, 'Thực Tập Sinh Du Lịch', 'Hỗ trợ kinh doanh du lịch: Tìm hiểu và hỗ trợ xây dựng các chương trình tour du lịch (lịch trình, điểm đến, dịch vụ đi kèm). Hỗ trợ tư vấn khách hàng qua điện thoại, email hoặc trực tiếp (dưới sự hướng dẫn của nhân viên chính thức). Chuẩn bị tài liệu, báo giá, hợp đồng cho khách hàng theo mẫu có sẵn. Hỗ trợ vận hành tour: Phối hợp với các bộ phận để kiểm tra thông tin đặt dịch vụ (khách sạn, vé máy bay, nhà hàng, xe đưa đón, v.v.). Theo dõi tiến độ tour và hỗ trợ giải quyết các vấn đề phát sinh trong khả năng. Hỗ trợ hướng dẫn viên trong việc chuẩn bị tài liệu hoặc liên hệ với nhà cung cấp. Nghiên cứu thị trường: Thu thập thông tin về các điểm đến du lịch mới, xu hướng du lịch hiện tại. Hỗ trợ phân tích phản hồi của khách hàng để cải thiện chất lượng dịch vụ.', 'Sinh viên năm cuối ngành Du lịch hoặc các ngành liên quan. Đam mê ngành du lịch, mong muốn học hỏi và phát triển trong lĩnh vực này. Kỹ năng giao tiếp tốt, thân thiện, nhiệt tình. Biết sử dụng tin học văn phòng cơ bản (Word, Excel, PowerPoint). Không yêu cầu kinh nghiệm, nhưng cần tinh thần trách nhiệm và chủ động trong công việc.
Kỹ năng chuyên môn: [''Tin học văn phòng cơ bản (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Thân thiện'', ''Nhiệt tình'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Hỗ trợ chi phí thực tập theo thỏa thuận'', ''Được đào tạo kỹ năng chuyên môn về du lịch từ các anh/chị giàu kinh nghiệm'', ''Cơ hội tham gia trải nghiệm thực tế tại các tour du lịch của công ty (nếu có)'', ''Nhận giấy chứng nhận thực tập sau khi hoàn thành chương trình'', ''Cơ hội trở thành nhân viên chính thức nếu thể hiện tốt trong thời gian thực tập'', ''Ăn trưa'', ''Cước điện thoại'', ''Du lịch hàng năm'', ''Team building'', ''Thưởng hiệu quả làm việc'', ''Bảo hiểm xã hội'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (65, 9, 2, 'Thực Tập Sinh - Tư Vấn Viên Du Lịch', '- Dịch vụ tư vấn, chăm sóc khách hàng tiềm năng có nhu cầu về du lịch - Được cầm tay chỉ việc, hỗ trợ và hướng dẫn bài bản - Quản lý các trang, kênh thông tin du lịch - Phối hợp cùng Team để xây dựng thương hiệu công ty', '- Có laptop cá nhân - Ứng viên học các chuyên ngành du lịch, kinh tế là một lợi thế - Am hiểu và yêu thích du lịch là một lợi thế - Kỹ năng giao tiếp, khả năng thuyết phục tốt, phong thái tự tin - Chăm chỉ, nhiệt tình và cầu tiến trong công việc.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Khả năng thuyết phục'', ''Phong thái tự tin'', ''Chăm chỉ'', ''Nhiệt tình'', ''Cầu tiến trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Công tác phí hỗ trợ + hoa hồng doanh thu'', ''Có cơ hội được lên nhân viên chính thức'', ''Được trải nghiệm du lịch những sản phẩm công ty quản lý'', ''Được tham gia miễn phí các buổi đào tạo bài bản chuyên nghiệp'', ''Môi trường làm việc trẻ trung, chế độ minh bạch, cơ hội thăng tiến & phát triển bản thân'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (66, 10, 2, 'Nhân Viên Pha Chế Kiêm Thu Ngân (Part-Time)', 'Công việc vị trí thu ngân: tư vấn cho khách hàng các dòng sản phẩm Boost Juice. Pha chế các thức uống theo đúng công thức, tiêu chuẩn chất lượng. Tiếp đón, phục vụ và chăm sóc khách hàng tại cửa hàng. Đảm bảo vệ sinh tại cửa hàng luôn sạch sẽ.', 'Không yêu cầu kinh nghiệm. Ưu tiên giao tiếp Tiếng Anh (không bắt buộc). Siêng năng, chăm chỉ. Lịch học trống nhiều, đáp ứng được thời gian yêu cầu. Tinh thần tự giác, chủ động và trách nhiệm trong công việc.
Kỹ năng mềm: [''Siêng năng'', ''Chăm chỉ'', ''Tinh thần tự giác'', ''Chủ động'', ''Trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thời gian xoay ca linh động', '[''Lương Lễ, Tết x3'', ''Quà sinh nhật'', ''Lễ'', ''Tip'', ''Lixi'', ''Tham gia vào đội ngũ trẻ trung năng động'', ''Cơ hội thăng tiến lên các cấp Leader, Quản lý sau 6 tháng - 1 năm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (67, 2, 2, 'Sale Trainee - Thực Tập Sinh Kinh Doanh', 'Hỗ trợ đội ngũ kinh doanh trong các hoạt động bán hàng, chăm sóc khách hàng, quản lý dữ liệu và chuẩn bị tài liệu, nhằm nâng cao trải nghiệm khách hàng và phát triển kỹ năng thực tế cho bản thân.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các ngành Quản trị kinh doanh, Du lịch – Khách sạn, Marketing, Thương mại,... Kỹ năng giao tiếp tốt, chủ động, cẩn thận và cầu tiến. Sử dụng thành thạo Microsoft Office (Excel, Word, PowerPoint). Có khả năng giao tiếp tiếng Anh ở mức khá trở lên. Ưu tiên ứng viên có thể thực tập tối thiểu 3 tháng và cam kết làm việc toàn thời gian trong thời gian thực tập.
Kỹ năng chuyên môn: [''Microsoft Office (Excel, Word, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Chủ động'', ''Cẩn thận'', ''Cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Theo ca', '[''Môi trường khách sạn 5 sao quốc tế'', ''Cơ hội học hỏi, đào tạo trực tiếp'', ''Hỗ trợ phụ cấp thực tập'', ''Bữa ăn trong ca'', ''Đồng phục'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (68, 3, 2, 'Thực Tập Sinh Điều Hành Khách Sạn', 'Liên hệ với các khách sạn để cập nhật thông tin lên hệ thống Vntrip. Hỗ trợ xử lý báo giá cho các bộ phận bán hàng (CCS/Sales). Cập nhập giá phòng lên hệ thống. Hoàn thành các công việc khác do Teamlead giao.', '- Đang theo học các trường Đại học, Cao đẳng tại Hà Nội (chuyên ngành du lịch là một lợi thế). - Chăm chỉ, cẩn thận, nhiệt tình, giao tiếp tốt. - Nghiêm túc muốn học hỏi và hiểu thêm kiến thức về khách sạn và du lịch. - Có tinh thần trách nhiệm với công việc.
Kỹ năng mềm: [''Chăm chỉ'', ''Cẩn thận'', ''Nhiệt tình'', ''Giao tiếp tốt'', ''Tinh thần trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 1000000.00, '1.3 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ thực tập: 1.330.000đ/tháng'', ''Thưởng thêm nếu có thành tích tốt trong công việc'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Có cơ hội được nhận làm nhân viên chính thức tùy theo năng lực'', ''Được đào tạo các kỹ năng cần thiết để xử lý công việc'', ''Được tham gia các hoạt động ngoại khóa của công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (69, 7, 2, 'Nhân Viên Thu Ngân', 'Dọn dẹp và giữ vệ sinh khu vực làm việc: sàn bán hàng, quầy thu ngân, lối đi chính và văn phòng. Sắp xếp và châm hàng tại quầy thu ngân, đảm bảo khu vực luôn ngăn nắp và đầy đủ sản phẩm. Hỗ trợ khách hàng thanh toán, thao tác chính xác với các phương thức thanh toán cơ bản. Kiểm tra sản phẩm, ghi nhận thông tin bảo hành và ghi chú thông tin giao hàng vào phiếu giao hàng khi cần thiết. Trả giỏ và xe đẩy về đúng vị trí, giữ cho không gian mua sắm luôn gọn gàng. Hỗ trợ nhận hàng: Kiểm đếm số lượng thùng hàng, Di chuyển hàng hóa từ khu vực giao nhận vào trong cửa hàng.', 'Là sinh viên đang theo học các trường Đại học, Cao đẳng hoặc đã tốt nghiệp THPT. Ưu tiên từng làm việc tại siêu thị/ cửa hàng tiện lợi/ bán lẻ, nếu chưa có kinh nghiệm sẽ được đào tạo. Có thể sắp xếp thời gian làm việc linh hoạt, ưu tiên có thể xoay ca, cuối tuần, Lễ... Có tinh thần làm việc trách nhiệm và chịu được áp lực trong công việc. Tác phong nhanh nhẹn, sức khỏe tốt, trung thực. Kỹ năng giao tiếp, thái độ thân thiện chào hỏi khách hàng.
Kỹ năng chuyên môn: [''Khả Năng Tính Toán Nhanh Chóng Và Chính Xác'', ''Khả Năng Sử Dụng Máy Tính Tiền'', ''Khả Năng Xử Lý Tiền Mặt Và Thẻ Tín Dụng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Tác phong nhanh nhẹn'', ''Tinh thần làm việc trách nhiệm'', ''Chịu được áp lực trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh, quận 8, hà nội, thanh xuân', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '18h - 22h hoặc 10h - 14h vào các ngày Thứ 6, Thứ 7, Chủ Nhật', '[''Được trau dồi và phát triển kỹ năng giao tiếp chuyên nghiệp'', ''Được đào tạo và hướng dẫn nghiệp vụ bán hàng bài bản'', ''Có cơ hội trở thành nhân viên chính thức nếu hoàn thành tốt công việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (70, 8, 2, 'Cộng Tác Viên Kinh Doanh', 'Trình bày và chào bán sản phẩm, dịch vụ, giải pháp tới khách hàng và chốt sale. Tư vấn cho khách hàng về sản phẩm, dịch vụ phù hợp nhu cầu. Xây dựng và duy trì quan hệ bền chặt với khách hàng. Thu thập, phân tích và báo cáo thông tin thị trường, khách hàng và đối thủ cạnh tranh. Thực hiện các hoạt động tiếp thị, quảng cáo để tiếp cận khách hàng tiềm năng. Hỗ trợ đội ngũ bán hàng và tiếp thị trong các dự án và chiến dịch.', 'YÊU CẦU CÔNG VIỆC: - Sinh viên năm 3, năm 4 trở lên đang học tập và làm việc tại Hà Nội - Có định hướng làm việc trong ngành du lịch, sự kiện. - Cầu tiến chăm chỉ, giọng nói dễ nghe, khả năng thuyết phục khách hàng - Sử dụng thành thạo vi tính văn phòng - Có khả năng xử lý tình huống tốt
Kỹ năng chuyên môn: [''Sử dụng thành thạo vi tính văn phòng'']
Kỹ năng mềm: [''Cầu tiến'', ''Chăm chỉ'', ''Giọng nói dễ nghe'', ''Khả năng thuyết phục khách hàng'', ''Khả năng xử lý tình huống tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Trợ cấp phí hàng tháng'', ''Hoa hồng đơn hàng'', ''Linh hoạt thời gian'', ''Cơ hội trở thành nhân viên chính thức'', ''Được cấp tài liệu, kịch bản và hỗ trợ trong suốt quá trình làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (71, 9, 2, 'Thực Tập Sinh Kinh Doanh', 'Tìm hiểu các kiến thức về ngành du lịch, kỹ năng của công việc tư vấn dịch vụ du lịch. Thực hành, tham gia trực tiếp vào tư vấn khách hàng đặt các dịch vụ du lịch như đặt phòng khách sạn, vé máy bay, tour du lịch, tổ chức team building,... Học hỏi kỹ năng chăm sóc khách hàng, kỹ năng giải quyết các vấn đề của ngành dịch vụ du lịch. Liên hệ, gặp gỡ đối tác, trau dồi kinh nghiệm, tạo dựng các mối quan hệ kinh doanh. Các công việc liên quan đến kinh doanh, phát triển khách hàng theo định hướng của công ty.', 'Kỹ năng giao tiếp tốt, hòa đồng với mọi người xung quanh. Chăm chỉ, kiên trì, chính trực, có tinh thần cầu tiến, nỗ lực, ham học hỏi. Có thể đi làm được tối thiểu 70% thời gian của nhân viên chính thức (full-time). Yêu thích ngành du lịch, có khát vọng phát triển sự nghiệp.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Hòa đồng'', ''Chăm chỉ'', ''Kiên trì'', ''Chính trực'', ''Có tinh thần cầu tiến'', ''Nỗ lực'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 30000000.00, '8.0 - 30.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Được hướng dẫn và đào tạo bài bản'', ''Được hưởng lương + Hoa hồng + Thưởng'', ''Xét thưởng hằng tuần, tháng, quý'', ''Thưởng nóng theo thành tích'', ''Được cấp điện thoại Hotline riêng'', ''Xét duyệt để trở thành nhân viên chính thức'', ''Môi trường làm việc năng động'', ''Được hưởng đầy đủ các chế độ và chính sách của luật lao động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (72, 10, 2, 'Nhân Viên Bán Vé Xe Buýt 2 Tầng- Part Time', 'Thực hiện công việc bán vé, tiếp thị trực tiếp cho khách hàng tại các điểm dừng/điểm bán vé xe buýt 2 tầng; giới thiệu sản phẩm tour xe buýt, tư vấn thông tin hành trình và hỗ trợ khách mua vé nhanh chóng, hiệu quả.', 'Ưu tiên sinh viên ngành du lịch, ngoại ngữ, marketing,… Yêu thích giao tiếp, năng động, linh hoạt và có khả năng làm việc ngoài trời. Có thể làm việc theo ca (sáng, chiều, tối), kể cả cuối tuần, lễ Tết. Ưu tiên có kinh nghiệm trong mảng bán hàng, đặc biệt là du lịch & dịch vụ. Giao tiếp tiếng Anh cơ bản là lợi thế.
Kỹ năng mềm: [''Giao tiếp'', ''Năng động'', ''Linh hoạt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '5.0 - 8.0 triệu', 'Thứ 2 - Chủ nhật (từ 07:30 đến 15:30) và (từ 15:30 đến 22:30)', '[''Lương theo ca'', ''Hoa hồng hấp dẫn theo doanh số bán vé'', ''Được đào tạo kỹ năng bán hàng'', ''Môi trường làm việc năng động'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (73, 2, 2, 'Thực Tập Sinh Điều Hành', 'Hỗ trợ điều hành tour: liên hệ nhà cung cấp, đặt dịch vụ nhà hàng, khách sạn từ Châu Âu (Pháp, Thụy Sĩ, Đức, Ý,…). Theo dõi tiến độ tour, xử lý sự cố. Hỗ trợ tư vấn, chăm sóc khách hàng qua điện thoại, email, fanpage. Tham gia xây dựng chương trình tour và báo giá. Thực hiện các công việc liên quan đến vận hành và kinh doanh du lịch.', 'Ưu tiên các bạn có ngoại ngữ (Tiếng Anh - Nghe, Nói tốt). Sinh viên năm cuối hoặc mới tốt nghiệp ngành Du lịch, Quản trị Kinh doanh, Ngoại ngữ, Marketing... Yêu thích du lịch, có tinh thần trách nhiệm và chủ động học hỏi. Kỹ năng giao tiếp, làm việc nhóm tốt. Ưu tiên ứng viên có thể thực tập full-time hoặc ít nhất 3 buổi/tuần.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Làm việc nhóm'', ''Tinh thần trách nhiệm'', ''Chủ động học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được đào tạo bài bản từ đội ngũ điều hành và kinh doanh giàu kinh nghiệm'', ''Hỗ trợ phụ cấp thực tập + hoa hồng sale hấp dẫn'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Training Workshop thị trường Nước ngoài và Trong Nước'', ''Môi trường làm việc thân thiện, chuyên nghiệp'', ''Xăng xe'', ''Cước điện thoại'', ''Thưởng hiệu quả làm việc'', ''Du lịch hàng năm'', ''Team building'', ''Thưởng tháng 13'', ''Bảo hiểm full lương'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (74, 3, 7, 'Nhân Viên Digital Marketing Intern (Content)', 'Hỗ trợ thực hiện tất cả nội dung trực tuyến và quảng cáo thay mặt cho cả hai khách sạn, bao gồm nhưng không giới hạn ở phương tiện truyền thông xã hội, quảng cáo Google, quảng cáo Facebook, quảng cáo YouTube và quảng cáo hiển thị trực tuyến. Theo dõi và báo cáo về quảng cáo và nội dung trực tuyến của đối thủ cạnh tranh, xác định các kỹ thuật, tin nhắn và kênh hiệu quả và đảm bảo rằng các khách sạn trực tuyến quảng cáo trực tuyến ngoài quảng cáo đối thủ cạnh tranh. Ghi lại tất cả chi tiêu và quy trình tất cả các thủ tục giấy tờ cần thiết cho các nhiệm vụ liên quan đến vai trò. Nội dung được đọc lại cho các lỗi và sự không nhất quán và chỉnh sửa và đánh bóng nội dung hiện có để cải thiện khả năng đọc. Tạo các tiêu đề hấp dẫn và văn bản cơ thể sẽ thu hút sự chú ý của đối tượng mục tiêu. Xác định nhu cầu của khách hàng và đề xuất nội dung mới để giải quyết các khoảng trống trong nội dung hiện tại của công ty. Tham gia vào các hội thảo, hội thảo cho tổ chức. Tham gia khảo sát khách sạn và nhà hàng. Làm việc với các bộ phận bán hàng và văn phòng khách sạn để đào tạo nhân viên về các sản phẩm khách sạn mới. Tất cả các nhiệm vụ liên quan khác để cải thiện thương hiệu và thị trường của khách sạn.', 'Majoring in English or Marketing. Excellent verbal and written communication skills. Basic knowledge of social media and SEO. Driven and hard-working. Flexible and able to multitask. Ability to take initiative and spearhead projects.
Kỹ năng chuyên môn: [''Social Media'', ''SEO'']
Kỹ năng mềm: [''Excellent verbal and written communication skills'', ''Driven and hard-working'', ''Flexible and able to multitask'', ''Ability to take initiative and spearhead projects'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Partially remote/online (come into office 3x / week from 8:00 - 16:30)', '[''Opportunity to take digital marketing, SEO, and social media courses (sponsored by the company)'', ''Opportunity to improve English language and communication skills'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (75, 7, 7, 'Thực Tập Sinh Marketing Livestream', 'Hỗ trợ điều phối kỹ thuật và chuẩn bị cho các buổi livestream bán hàng. Tham gia phụ live/livestream cùng team, giới thiệu sản phẩm và tương tác với khách hàng. Tư vấn, chốt đơn qua tin nhắn, chăm sóc khách hàng trong quá trình mua hàng. Báo cáo và theo dõi doanh số bán hàng. Thực hiện các công việc khác theo sự phân công của quản lý.', 'Nữ, tuổi từ 18 – 28. Trung thực, trách nhiệm, tư duy tích cực, có tinh thần cầu tiến. Yêu thích công việc liên quan đến livestream, hình ảnh, video. Cẩn thận, tập trung, tỉ mỉ trong công việc. Ưu tiên sinh viên làm thêm hoặc người có mong muốn phát triển lâu dài trong lĩnh vực bán hàng – livestream.
Kỹ năng chuyên môn: [''Kỹ năng livestream'', ''Kỹ năng giao tiếp'', ''Khả năng sử dụng các nền tảng mạng xã hội'']
Kỹ năng mềm: [''Trung thực'', ''Trách nhiệm'', ''Tư duy tích cực'', ''Có tinh thần cầu tiến'', ''Cẩn thận'', ''Tập trung'', ''Tỉ mỉ'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 15000000.00, '5.0 - 15.0 triệu', 'Thứ 2 - Chủ nhật (từ 13:00 đến 17:30)', '[''Lương cứng 3.000.000đ/ca 4 tiếng/tháng'', ''Thưởng theo doanh số (%)'', ''Được đào tạo bài bản về kỹ năng livestream'', ''Môi trường làm việc trẻ trung, năng động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (76, 8, 7, 'Thực Tập Sinh Marketing', 'Bạn là sinh viên mới ra trường hoặc chuẩn bị tốt nghiệp? Bạn muốn bắt đầu sự nghiệp Marketing nhưng thiếu kinh nghiệm thực tế?=> Hãy tham gia chương trình Thực tập sinh Marketing có lương và được đào tạo từ A-Z bởi đội ngũ chuyên gia.', 'Yêu cầu ứng viên: Là sinh viên năm cuối hoặc mới tốt nghiệp các ngành Marketing, Truyền thông, Kinh tế, Quản trị kinh doanh, v.v. Có đam mê và định hướng phát triển sự nghiệp trong ngành Marketing. Năng động, chủ động học hỏi, chịu khó. Biết sử dụng Canva, Capcut, Tiktok, Facebook là lợi thế (không bắt buộc).
Kỹ năng chuyên môn: [''Canva'', ''Capcut'', ''Tiktok'', ''Facebook'']
Kỹ năng mềm: [''Năng động'', ''Chủ động học hỏi'', ''Chịu khó'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Đào tạo thực chiến MIỄN PHÍ'', ''Làm việc trong môi trường trẻ trung, năng động, sáng tạo'', ''Hỗ trợ lương thử việc trong thời gian thực tập'', ''Cơ hội được giữ lại làm nhân viên chính thức nếu thể hiện tốt'', ''Có mentor hướng dẫn, phản hồi thường xuyên'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (77, 9, 7, 'Nhân Viên Telesale / Kinh Doanh / Tư Vấn (Part-Time)', 'Tìm hiểu các dự án của Công ty đang bán. Gọi điện theo Data có sẵn từ Marketing và Team Leader để tư vấn về dự án công ty đang bán và lấy thông tin khách hàng. Chăm sóc khách hàng tiềm năng. Lập File báo cáo công việc hàng ngày.', 'KHÔNG YÊU CẦU KINH NGHIỆM. Có kinh nghiệm là một lợi thế. Thời gian làm việc tối thiểu 5 buổi 1 tuần, có thể làm các buổi tự chọn không cần cố định. Có máy tính riêng. Độ tuổi 18 - 35t.', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '3.0 - 7.0 triệu', 'Linh động sáng 9h - 11h30, chiều 14h - 17h', '[''Lương: 30k/ 1 giờ + thưởng 100k - 200k một cuộc hẹn'', ''Cung cấp sẵn điện thoại và data'', ''Môi trường làm việc chuẩn mực'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (78, 10, 7, 'Thực Tập Sinh Social Media Part Time (Có Lương)', 'Hỗ trợ thực hiện các chiến dịch marketing trên mạng xã hội, bao gồm: Lên lịch đăng bài, quản lý các nền tảng MXH: Facebook, Tiktok, Youtube. Tham gia triển khai các chương trình truyền thông, chiến dịch marketing theo định hướng thương hiệu. Sản xuất nội dung trên các kênh truyền thông xã hội như Facebook, Youtube, Tiktok,... với mục tiêu lan toả và thu hút tương tác. Cập nhật và biên tập thông tin thương hiệu trên các nền tảng truyền thông nhằm đảm bảo hình ảnh và thông tin doanh nghiệp luôn được duy trì nhất quán và chuyên nghiệp.', 'Không yêu cầu kinh nghiệm, đào tạo lại từ đầu. Làm việc chủ động, sáng tạo. Nhiệt tình chăm chỉ. Có tinh thần trách nhiệm với công việc.
Kỹ năng mềm: [''Làm việc chủ động'', ''Sáng tạo'', ''Nhiệt tình'', ''Chăm chỉ'', ''Có tinh thần trách nhiệm với công việc'']', 'PART_TIME', 'ONSITE', 'cầu giấy', 'Hà Nội', 'MONTHLY', 15000000.00, '5.0 - 15.0 triệu', 'Thứ 2 - Thứ 6 (Nghỉ T7 & CN), Sáng: 8h30 - 12h, Chiều: 14h - 17h30', '[''Hỗ trợ lương 1.500.000đ + 500.000đ chuyên cần + % hoa hồng cao + thưởng nóng'', ''Được hướng dẫn đào tạo hoàn thiện kỹ năng về Marketing'', ''Được đào tạo kiến thức về social media, Social marketing'', ''Có cơ hội được trở thành nhân viên chính thức sau tốt nghiệp'', ''Văn phòng làm việc được thiết kế hiện đại, tạo không gian làm việc thoải mái'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (79, 2, 7, 'Tiktok Content Creator', 'MÔ TẢ CÔNG VIỆC: - Sản xuất clip tiktok về cây kiểng lá - Sản xuất clip tiktok về chậu gốm giả cổ Nhân viên được định hướng nội dung content, công việc của nhân viên vị trí này là tổ chức quay, dựng là follow theo lịch post hàng ngày Kênh Làm Việc (chọn 1 trong 2): MUN GARDEN hoặc CHẬU NHÀ MON.', 'Welcome mọi giới tính. Ưu tiên gen Z. Có khả năng sản xuất, dựng clip tiktok. Thành thạo capcut, canva, tiktok. Có khả năng viết kịch bản clip. Có khả năng lồng tiếng cho clip. Có khả năng ăn nói lưu loát xuất hiện trong clip dạng VJ. Có kiến thức cơ bản về cây và chậu gốm là lợi thế. Yêu thiên nhiên, thích làm việc trong môi trường có cây cối, gốm, chậu...
Kỹ năng chuyên môn: [''Thành thạo capcut'', ''Thành thạo canva'', ''Thành thạo tiktok'']
Kỹ năng mềm: [''Có khả năng ăn nói lưu loát'', ''Có khả năng viết kịch bản clip'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '4.5 - 5.0 triệu', 'Mỗi tuần đến vườn 02 ngày để quay, còn lại dựng tại nhà.', '[''Được đào tạo cơ bản về cây cối hoặc chậu gốm'', ''Môi trường làm việc thân thiện, năng động'', ''Thưởng theo hiệu suất làm việc 1,000,000 - 3,000,000/ kênh/ tháng'', ''Xét duyệt tăng lương mỗi 12 tháng/ lần'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (80, 3, 7, 'Thực Tập Sinh Content Marketing', 'Mô tả CV: - Hỗ trợ sáng tạo nội dung trên các nền tảng: web, social, youtobe - Hỗ trợ lên ý tưởng và sản xuất tư liệu marketing - Các CV khác trực thuộc phòng MKT', '- Ưu tiên Sinh viên chuyên nghành MKT hoặc Báo chí - Yêu thích viết lách, sáng tạo nội dung, yêu thích marketing - Có tinh thần trách nhiệm, chăm chỉ. * Có kinh nghiệm viết content trước đó hoặc kỹ năng về viết lách * Có niềm đang mê với biên tập nội dung * Ưu tiên có khả năng quay dựng cơ bản
Kỹ năng chuyên môn: [''Content Marketing'', ''Viết lách'']
Kỹ năng mềm: [''Tinh thần trách nhiệm'', ''Chăm chỉ'', ''Sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Được đào tạo kiến thức MKT'', ''Cung cấp công cụ AI thực hành'', ''Tham gia dự án thực tế'', ''Hỗ trợ dấu xác nhận thực tập'', ''Nhiều cơ hội đào tạo và phát triển nghề nghiệp'', ''Thưởng'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (81, 7, 7, 'Nhân Viên Kinh Doanh Xuất Khẩu', 'Làm việc trên môi trường thương mại điện tử: Alibaba, Global Sources, các trang B2B... Và các trang mạng xã hội Facebook, Instagram, Tiktok... Tìm kiếm khách hàng, quảng bá mở rộng thị trường theo yêu cầu của phòng ban. Thực hiện các hoạt động giao dịch: thương lượng đàm phán với khách hàng, nhận đơn đặt hàng, thống nhất về giá, sản phẩm, chất lượng, điều khoản thanh toán, thời gian giao hàng và thúc đẩy thanh toán. Phối hợp với các bộ phận liên quan để theo dõi thực hiện đơn hàng đảm bảo các yêu cầu của khách hàng. Theo dõi và cập nhật thường xuyên cho khách hàng: tiến độ sản xuất, kế hoạch đóng hàng, theo dõi vận chuyển.', 'Yêu thích kinh doanh, có trách nhiệm trong công việc, có thái độ cầu tiến, chăm chỉ. Làm việc với 100% khách nước ngoài nên yêu cầu khá về tiếng Anh hoặc tiếng Pháp hoặc tiếng Nga. Có Laptop - Sử dụng vi tính văn phòng và internet thành thạo. Ưu tiên với các ứng viên là sinh viên từ năm 02 của trường Đại Học Kinh Tế, Ngoại Ngữ. Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực thương mại điện tử, bán hàng quốc tế.
Kỹ năng chuyên môn: [''Sử dụng vi tính văn phòng'', ''Internet thành thạo'']
Kỹ năng mềm: [''Kỹ năng đàm phán'', ''Kỹ năng tìm kiếm khách hàng'', ''Kỹ năng giao tiếp tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 10000000.00, '7.0 - 10.0 triệu', '13h30 - 18h00; thứ 2 đến thứ 6', '[''Lương cứng 3 triệu + hoa hồng'', ''Du lịch, liên hoan công ty'', ''Thưởng lễ Tết'', ''Được training về quản trị kinh doanh - Digital marketing global'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (82, 8, 7, 'Thực Tập Sinh Chăm Sóc Khách Hàng', 'Xây dựng và duy trì mối quan hệ tốt đẹp với khách hàng bằng cách tiếp nhận và giải đáp nhanh chóng các thắc mắc về tính năng sản phẩm; hỗ trợ xử lý mọi vấn đề phát sinh trong quá trình sử dụng. Liên hệ và CSKH đã lâu không sử dụng sản phẩm, cập nhật thông tin và khuyến khích họ trải nghiệm dịch vụ mới. Theo dõi và thông báo đến khách hàng về thời hạn sử dụng sản phẩm, hỗ trợ họ trong việc gia hạn một cách thuận tiện và hiệu quả. Tư vấn và hướng dẫn khách hàng sử dụng sản phẩm/dịch vụ, đảm bảo họ nhận được giá trị tối đa từ chúng. Thu thập ý kiến và phản hồi từ khách hàng để đề xuất cải tiến chất lượng sản phẩm và dịch vụ; phối hợp với các phòng ban liên quan để giải quyết nhanh chóng và hiệu quả.', 'Thời gian làm việc: Giờ hành chính (Được sắp xếp linh hoạt làm việc theo lịch học, Nghỉ tối đa 2 buổi/tuần (1 buổi=1/2 ngày)). Đối tượng: Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp. Kinh nghiệm: Không yêu cầu kinh nghiệm; chấp nhận ứng viên chưa có chuyên môn và sẽ được đào tạo. Ưu tiên: Ứng viên có kinh nghiệm trong tư vấn khách hàng, bán hàng, chăm sóc khách hàng hoặc telesales là một lợi thế. Yêu thích công việc tư vấn và chăm sóc khách hàng: Đam mê trong việc hỗ trợ và giải đáp thắc mắc cho khách hàng. Kỹ năng giao tiếp tốt: Tự tin, năng động và có khả năng truyền đạt thông tin một cách hiệu quả. Hỗ trợ dấu mộc thực tập (mộc tròn): Đáp ứng đầy đủ yêu cầu thực tập của nhà trường.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Tự tin'', ''Năng động'', ''Khả năng truyền đạt thông tin hiệu quả'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '2.5 - 6.0 triệu', 'Giờ hành chính (Thứ 2 - Thứ 6, từ 08:00 đến 17:00)', '[''Phụ cấp thực tập hấp dẫn'', ''Thưởng hiệu suất'', ''Thưởng lễ Tết'', ''Đóng bảo hiểm xã hội đầy đủ'', ''Cơ hội trở thành nhân viên chính thức'', ''Đào tạo chuyên sâu'', ''Đồ uống miễn phí'', ''Nghỉ phép có lương'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (83, 9, 7, 'Thực Tập Sinh Tuyển Dụng', 'Hỗ trợ đăng tin tuyển dụng trên các nền tảng phù hợp (Facebook, website việc làm,...). Tìm kiếm, sàng lọc hồ sơ ứng viên theo tiêu chí của công ty. Hỗ trợ liên hệ, sắp xếp lịch phỏng vấn với ứng viên. Hỗ trợ quản lý và cập nhật dữ liệu ứng viên. Tham gia xây dựng thương hiệu tuyển dụng và tìm kiếm idol Live Stream. Hỗ trợ các công việc hành chính liên quan đến tuyển dụng.', 'Giới tính: Nam/ Nữ (18 - 25 tuổi). Sinh viên năm 4 hoặc mới tốt nghiệp các ngành liên quan đến Quản trị Nhân sự, Kinh tế, Truyền thông,... Không yêu cầu kinh nghiệm, ưu tiên có hiểu biết về tuyển dụng hoặc nhân sự. Kỹ năng giao tiếp tốt, nhanh nhẹn, chủ động trong công việc. Có máy tính cá nhân.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp tốt'', ''Có máy tính cá nhân'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 10:00 đến 18:00)', '[''Được đào tạo về quy trình tuyển dụng và kỹ năng phỏng vấn'', ''Có cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Môi trường làm việc trẻ trung, năng động, cơ hội phát triển nghề nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (84, 10, 7, 'Cộng Tác Viên Tuyển Dụng - Không Cần Kinh Nghiệm', '• Tìm kiếm & giới thiệu ứng viên cho các vị trí bên mình • Follow ứng viên từ lúc nộp CV đến khi đi làm ổn định • Tương tác, hỗ trợ ứng viên như “chuyên viên HR đích thực” • Lọc CV, lên lịch phỏng vấn nếu cần – không bắt buộc', 'Không yêu cầu kinh nghiệm. Có kỹ năng giao tiếp tốt, khả năng thuyết phục và đàm phán. Có khả năng sử dụng các công cụ tìm kiếm và sàng lọc hồ sơ ứng viên.
Kỹ năng chuyên môn: [''Sử dụng các công cụ tìm kiếm và sàng lọc hồ sơ ứng viên'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng thuyết phục'', ''Khả năng đàm phán'']', 'FREELANCE', 'ONSITE', 'hà nội, thái nguyên', 'Hà Nội', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Thời gian làm việc linh hoạt', '[''Mức lương cạnh tranh, thỏa thuận theo năng lực'', ''Được đào tạo các kỹ năng chuyên môn và nghiệp vụ'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (85, 2, 7, 'Thực Tập Sinh Editor', 'Chịu trách nhiệm chỉnh sửa và biên tập nội dung văn bản cho các dự án. Đảm bảo chất lượng âm thanh và độ chính xác của văn bản, bao gồm việc kiểm tra ngữ pháp, chính tả và ngữ điệu. Hợp tác với các bộ phận khác để phát triển nội dung phù hợp với yêu cầu của dự án. Thực hiện các công việc liên quan đến sản xuất nội dung âm thanh, bao gồm việc ghi âm và xử lý âm thanh. Tìm kiếm và đề xuất các xu hướng mới trong lĩnh vực TTS để cải thiện chất lượng sản phẩm.', 'Có kiến thức cơ bản về các phần mềm dựng phim như Premiere, After Effects, CapCut hoặc các công cụ chỉnh sửa video khác. Năm cuối chuyên ngành liên quan đến truyền thông, thiết kế, hoặc các lĩnh vực tương tự. Ưu tiên từng có kinh nghiệm thực tập trong lĩnh vực biên tập nội dung hoặc edit video tại các công ty khác. Thành thạo các phần mềm thiết kế như Photoshop, Figma, Canva, PowerPoint,... Biết cách quay dựng cơ bản, có gu thẩm mỹ tốt về hình ảnh, bố cục, màu sắc. Chăm chỉ, có tinh thần học hỏi, chủ động trong công việc. Sáng tạo, nắm bắt xu hướng nhanh, có khả năng làm việc độc lập và cả làm việc theo nhóm. Có laptop cá nhân để làm việc. Năng động, cầu tiến, chịu được áp lực deadline.
Kỹ năng chuyên môn: [''Premiere'', ''After Effects'', ''CapCut'', ''Photoshop'', ''Figma'', ''Canva'', ''PowerPoint'']
Kỹ năng mềm: [''Chăm chỉ'', ''Có tinh thần học hỏi'', ''Chủ động trong công việc'', ''Sáng tạo'', ''Nắm bắt xu hướng nhanh'', ''Có khả năng làm việc độc lập'', ''Làm việc theo nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6', '[''Hỗ trợ chi phí thực tập hàng tháng'', ''Hỗ trợ mộc, báo cáo thực tập'', ''Được đào tạo về kiến thức và kỹ năng về thiết kế đồ họa'', ''Cơ hội trở thành nhân viên chính thức'', ''Tham gia vào các hoạt động của công ty'', ''Môi trường làm việc trẻ trung, năng động, thân thiện'', ''Ăn trưa'', ''Xăng xe'', ''Trang điểm'', ''Cước điện thoại'', ''Thưởng hiệu quả làm việc'', ''Thưởng tháng 13'', ''Signing bonus'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (86, 3, 7, 'Nhân Viên Chăm Sóc Khách Hàng', 'Trả lời tin nhắn, cuộc gọi, phản hồi từ khách hàng qua các kênh như Zalo, Facebook, Hotline, Email... Theo dõi tiến độ dự án, báo cáo tình hình thực hiện cho khách và tiếp nhận phản hồi điều chỉnh. Chăm sóc khách hàng trong và sau quá trình thực hiện, xử lý các yêu cầu phát sinh nhanh chóng. Tiếp nhận và xử lý các phản ánh, khiếu nại của khách hàng (nếu có). Ghi nhận thông tin khách hàng, cập nhật vào hệ thống dữ liệu. Phối hợp với các bộ phận khác (kinh doanh, kỹ thuật...) để giải quyết các yêu cầu liên quan. Thực hiện các công việc khác theo sự phân công của quản lý.', 'Nữ, tuổi từ 18 – 27 (ưu tiên người có mong muốn gắn bó lâu dài). Không yêu cầu kinh nghiệm, sẽ được đào tạo khi nhận việc. Giọng nói dễ nghe, giao tiếp tốt, kiên nhẫn và biết lắng nghe. Thành thạo vi tính văn phòng cơ bản (Word, Excel, nhập liệu). Chủ động, chăm chỉ, trung thực và có trách nhiệm.
Kỹ năng chuyên môn: [''Vi tính văn phòng cơ bản (Word, Excel, nhập liệu)'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Kiên nhẫn'', ''Biết lắng nghe'', ''Chủ động'', ''Chăm chỉ'', ''Trung thực'', ''Có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:00 đến 13:00), Thứ 2 - Thứ 6 (từ 18:00 đến 23:00)', '[''Cước điện thoại'', ''Được cấp Điện thoại, Máy tính, Tai nghe'', ''Team building'', ''Thưởng hiệu quả làm việc'', ''Môi trường agency năng động, sáng tạo, nhiều cơ hội học hỏi và mở rộng mối quan hệ'', ''Được đào tạo các kỹ năng về dịch vụ khách hàng, giao tiếp, xử lý tình huống, hiểu về Media & Marketing'', ''Làm việc trong môi trường trẻ trung, thân thiện'', ''Tham gia các hoạt động team building, sinh nhật, du lịch định kỳ'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (87, 7, 7, 'Nhân Viên Marketing', 'Phụ trách nội dung các bài viết đăng tải trên website, facebook và các trang truyền thông của JOLO Hà Nội nhằm tăng cường sự tiếp cận về thương hiệu đến các khách hàng tiềm năng. Tăng cường lượng khách hàng tiềm năng của JOLO English. Đảm bảo hình ảnh thương hiệu của Trung tâm đối với khách hàng tiềm năng. Các kế hoạch khác được tổ chức bởi phòng Marketing và cơ sở. Lập kế hoạch và triển khai các chiến thuật seeding online và offline tại các trường để thu thập khách hàng tiềm năng. Tổ chức, thực hiện, tham gia các hoạt động trực tiếp tại trường học, toà nhà và khu vực lân cận.', '1.Trình độ học vấn/chuyên môn: Tốt nghiệp Đại học trở lên tại các chuyên ngành báo chí, truyền thông (hoặc) đã có kinh nghiệm làm việc trong lĩnh vực này. Vi tính văn phòng tương đương B trở lên. Thành thạo các ứng dụng tin học văn phòng. Giao tiếp tốt Tiếng Anh Thành thạo tiếng Anh ở cả 4 kỹ năng: nghe, nói, đọc, viết. IELTS 6.0 trở lên. 2. Kỹ năng: Có kĩ năng thiết kế đồ họa. Kỹ năng lập kế hoạch, kỹ năng tổ chức công việc. Kỹ năng phân tích, tổng hợp, làm báo cáo. Kỹ năng giao tiếp tốt. Có kỹ năng thuyết trình, làm việc theo nhóm. 3. Kinh nghiệm: Có kinh nghiệm tại vị trí Truyền thông/ Marketing online. Có kinh nghiệm chụp ảnh. 4. Phẩm chất cá nhân: Có nhiều ý tưởng sáng tạo, tư duy tổng hợp và phân tích tốt. Có khả năng chịu được áp lực, nhiệt tình sáng tạo trong công việc. Năng động, nhanh nhẹn, trung thực, chăm chỉ và có tinh thần làm việc nhóm, ham học hỏi. Tinh thần cầu thị, trung thực, hòa đồng, nhiệt huyết, trách nhiệm với công việc.
Kỹ năng chuyên môn: [''Vi tính văn phòng tương đương B trở lên'', ''Thành thạo các ứng dụng tin học văn phòng'', ''Kỹ năng thiết kế đồ họa'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Kỹ năng lập kế hoạch'', ''Kỹ năng tổ chức công việc'', ''Kỹ năng phân tích'', ''Kỹ năng tổng hợp'', ''Kỹ năng làm báo cáo'', ''Kỹ năng thuyết trình'', ''Kỹ năng làm việc theo nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6: 8h00 - 17h30, Thứ 7: 8h00 - 12h', '[''Được đào tạo chuyên sâu về chuyên môn trong lĩnh vực tư vấn giáo dục'', ''Được tham gia các hoạt động nội bộ của Công ty'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (88, 8, 7, 'Thực Tập Sinh Kinh Doanh', 'Hỗ trợ tìm kiếm & chăm sóc khách hàng. Học cách tư vấn bất động sản, kỹ năng bán hàng. Theo team đi xem dự án, hỗ trợ báo giá, làm hợp đồng (nếu có). Cập nhật tin tức thị trường – đăng bài theo hướng dẫn.', 'Không yêu cầu kinh nghiệm, được đào tạo từ A-Z. Giao tiếp tốt, đam mê kinh doanh, yêu thích lĩnh vực bất động sản. Có tinh thần cầu tiến, chịu khó và ham học hỏi.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Giao tiếp'', ''Nghiên cứu thị trường'', ''Tìm kiếm khách hàng'', ''Thuyết trình'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Được đào tạo bài bản từ đội ngũ chuyên nghiệp trong ngành bất động sản'', ''Được trải nghiệm thực tế và thực hành trong môi trường ngành BĐS'', ''Cơ hội trở thành nhân viên chính thức nếu thể hiện tốt sau thời gian thực tập'', ''Hỗ trợ dấu mộc báo cáo thực tập cho sinh viên'', ''Có hoa hồng nếu phát sinh giao dịch trong thời gian thực tập'', ''Làm việc trong môi trường thoải mái, có cơ hội mở rộng mối quan hệ'', ''Linh hoạt thời gian học tập của bạn (tối thiểu 1 kì 3 tháng, 5 buổi/1 tuần)'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (89, 9, 7, 'Thực Tập Sinh Tuyển Dụng', 'Nghiên cứu và tạo nguồn tuyển dụng theo nhu cầu Công ty. Liên hệ ứng viên mời phỏng vấn và hỗ trợ tiến hành công tác nhận việc. Giải đáp thắc mắc của ứng viên kịp thời trên các kênh tuyển dụng của công ty như Facebook, Zalo, email,... Hỗ trợ xây dựng thương hiệu nhà tuyển dụng trên các nền tảng mạng xã hội như Facebook, LinkedIn, Tiktok, Instagram của công ty.', '* Sinh viên năm cuối các trường đại học * Đam mê và có định hướng ngành nhân sự * Mạnh về social là lợi thế * Am hiểu, biết thiết kế, chỉnh sửa video cơ bản * Thái độ/tư duy cởi mở, sẵn sàng học hỏi. * Chủ động, trách nhiệm và yêu thích công việc ứng tuyển.
Kỹ năng chuyên môn: [''Microsoft Office'', ''Canva'', ''Kỹ năng thiết kế video cơ bản'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'', ''Thái độ cởi mở'', ''Chủ động'', ''Trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường làm việc hiện đại, chuyên nghiệp, năng động, thân thiện'', ''Hỗ trợ báo cáo thực tập/ báo cáo tốt nghiệp'', ''Được hỗ trợ cơm trưa'', ''Cơ hội nghề nghiệp tại Sen Vàng Việt Nam'', ''Trợ cấp thực tập'', ''Thưởng hiệu quả làm việc'', ''Team building'', ''Du lịch hàng năm'', ''Khám sức khỏe định kỳ'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (90, 10, 7, 'Thực Tập Sinh Media (Youtube)', 'Dựng video, short và livestream trên nền tảng Youtube theo yêu cầu và kịch bản. Hỗ trợ tìm kiếm và tổng hợp dữ liệu, thông tin, hình ảnh, video, hoặc các tư liệu cần thiết phục vụ cho sản xuất nội dung. Sử dụng công cụ AI để phân tích nội dung, xử lý dữ liệu thô. Phối hợp với team để sản xuất nội dung. Các công việc liên quan theo sự phân công của người hướng dẫn.', 'Trình độ học vấn: Sinh viên năm cuối hoặc tốt nghiệp Cao đẳng, Đại học ở các chuyên ngành truyền thông đa phương tiện, designer, marketing hoặc các chuyên ngành liên quan. Biết sử dụng các công cụ cơ bản: Pr, Ps, Capcut và Canva. Có gu thẩm mỹ. Làm việc nhóm. Chỉnh chu, cẩn thận, có trách nhiệm.
Kỹ năng chuyên môn: [''Pr'', ''Ps'', ''Capcut'', ''Canva'']
Kỹ năng mềm: [''Có gu thẩm mỹ'', ''Làm việc nhóm'', ''Chỉnh chu'', ''Cẩn thận'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ dấu thực tập'', ''Hỗ trợ trang thiết bị làm việc'', ''Được hướng dẫn bởi các Anh/Chị giàu kinh nghiệm'', ''Môi trường làm việc hiện đại, chuyên nghiệp'', ''Mua sách Alpha Books với chiết khấu cao'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (91, 2, 7, 'Tiếp thị truyền thông xã hội', 'Tạo và quản lý nội dung phương tiện truyền thông xã hội (bài viết, câu chuyện, cuộn, video). Phát triển và duy trì các tài khoản truyền thông xã hội (Instagram, Facebook, Tiktok, LinkedIn). Tham gia với những người theo dõi, trả lời tin nhắn và xây dựng cộng đồng. Hỗ trợ tiếp thị qua email, bài đăng trên blog và cập nhật trang web. Theo dõi hiệu suất truyền thông xã hội và điều chỉnh các chiến lược phù hợp. Cộng tác về hình ảnh thương hiệu và nhắn tin.', 'Experience in social media marketing and content creation. Strong writing and visual storytelling skills. Familiarity with Canva, Adobe Suite, or similar tools. Basic knowledge of SEO and digital marketing trends. Self-motivated, organized, and detail-oriented. Experience with paid ads (Meta, Google) is a plus. Fluency in English is required.
Kỹ năng chuyên môn: [''SEO'', ''Data Analysis'', ''Content Creation'', ''Community Management'', ''Social Media Advertising'', ''Canva'', ''Adobe Suite'']
Kỹ năng mềm: [''Strong writing skills'', ''Visual storytelling'', ''Self-motivated'', ''Organized'', ''Detail-oriented'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 11000000.00, '10.0 - 11.0 triệu', 'flexible time', '[''Competitive compensation'', ''Flexible working arrangements'', ''Opportunity to work in a dynamic, creative environment'', ''Chance to collaborate with a passionate and supportive team'', ''Exposure to exciting projects in the luxury events and travel industry'', ''Thưởng hiệu quả làm việc'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (92, 3, 7, 'Thực Tập Sinh Phát Hành Nội Dung AI', 'Tham gia hỗ trợ phát triển ban nhạc AI đầu tiên của MCV – Cheeky Band, gồm các thành viên ảo, cá tính riêng, hát nhạc do AI tạo ra, với định hướng đột phá về công nghệ và giải trí. Hỗ trợ sản xuất MV, short video, livestream, phỏng vấn “ảo”. Viết nội dung giới thiệu thành viên band, xây dựng cá tính nhân vật. Vận hành fanpage, TikTok, Instagram… của ban nhạc. Tìm kiếm, thử nghiệm và đề xuất công cụ AI phù hợp. Tham gia xây dựng cộng đồng người hâm mộ (fanbase). Hỗ trợ lên idea viral content, trend, thử thách TikTok cho band.', 'Sinh viên các ngành Sư Phạm, Truyền thông, Báo chí, Sản xuất, Âm nhạc, Thiết kế, Công nghệ thông tin, Marketing… hoặc ngành liên quan. Ham học hỏi, chịu khó thử nghiệm công cụ mới, có tinh thần startup. Biết dùng AI là một lợi thế lớn (AI music, AI video, AI design…). Có năng lực sáng tạo nội dung (viết caption, dựng video, vẽ nhân vật, phối nhạc, dựng trend…). Thời gian linh hoạt, làm việc theo dự án.
Kỹ năng chuyên môn: [''Biết dùng AI'', ''Sáng tạo nội dung'', ''Viết caption'', ''Dựng video'', ''Vẽ nhân vật'', ''Phối nhạc'', ''Dựng trend'']
Kỹ năng mềm: [''Ham học hỏi'', ''Chịu khó thử nghiệm công cụ mới'', ''Có tinh thần startup'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 09:00 đến 13:00)', '[''Môi trường làm việc trẻ, năng động, đón đầu công nghệ'', ''Được đào tạo trực tiếp bởi các producer, biên tập viên, đạo diễn lâu năm'', ''Cơ hội trở thành nhân sự chính thức nếu thể hiện tốt'', ''Có cơ hội tham gia sản xuất các chương trình nổi tiếng, làm việc với nghệ sĩ, thương hiệu lớn'', ''Được hỗ trợ mộc báo cáo thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (93, 7, 7, 'Thực Tập Sinh Truyền Thông', 'Phối hợp với các bộ phận liên quan để lên kế hoạch và thực hiện các chiến dịch marketing, quảng cáo sản phẩm/dịch vụ của công ty. Nghiên cứu thị trường, phân tích đối thủ cạnh tranh, tìm hiểu nhu cầu và hành vi khách hàng. Xây dựng và quản lý nội dung trên các kênh truyền thông xã hội (Tiktok, YouTube, Facebook, Instagram, Zalo OA, ...). Viết bài, tạo nội dung hấp dẫn, sáng tạo để thu hút khách hàng. Quản lý và tối ưu hóa các kênh quảng cáo online (Google Ads, Facebook Ads, ...). Theo dõi, đánh giá hiệu quả của các chiến dịch marketing và đề xuất các phương án cải tiến. Tổ chức và tham gia các sự kiện, triển lãm để quảng bá sản phẩm/dịch vụ. Xây dựng và duy trì mối quan hệ tốt đẹp với khách hàng, đối tác và truyền thông. Báo cáo kết quả công việc định kỳ cho cấp trên.', 'Không yêu cầu kinh nghiệm. Sinh viên năm 3 - năm 4 hoặc Tốt nghiệp Cao đẳng/Đại học chuyên ngành Marketing, Truyền thông hoặc các chuyên ngành liên quan. Có kiến thức cơ bản về marketing online và offline. Có khả năng viết bài tốt, sáng tạo và thu hút. Khả năng sử dụng thành thạo các phần mềm tin học văn phòng (Word, Excel, PowerPoint). Có kỹ năng giao tiếp tốt, khả năng làm việc nhóm và chịu được áp lực công việc. Nắm bắt nhanh các xu hướng mới trong lĩnh vực marketing. Ưu tiên ứng viên có kinh nghiệm sử dụng các công cụ quản lý nội dung, các nền tảng quảng cáo online (Google Ads, Facebook Ads...). Có tinh thần trách nhiệm cao, chủ động trong công việc.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về marketing online và offline'', ''Sử dụng thành thạo các phần mềm tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng làm việc nhóm'', ''Chịu được áp lực công việc'', ''Sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 07:30 đến 17:00)', '[''Đào tạo chuyên sâu về AI Marketing'', ''Cơ hội trở thành nhân viên chính thức'', ''Hỗ trợ đầy đủ cho việc học'', ''Kinh nghiệm thực chiến'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (94, 8, 7, 'Thực Tập Sinh Marketing', 'Hỗ trợ đội ngũ kinh doanh trong việc tìm kiếm và phát triển khách hàng. Tham gia vào các hoạt động marketing (viết Content, đăng bài quảng cáo trên Facebook, quay dựng video TikTok, thu thập data từ quảng cáo,…). Nghiên cứu thị trường và phân tích dữ liệu để đưa ra các báo cáo. Tham gia vào các buổi họp và thảo luận để đưa ra ý tưởng phát triển dự án. Quản lý và phát triển nội dung trên fanpage. Thực hiện các công việc khác theo chỉ đạo quản lý.', 'Sinh viên năm 3-4 hoặc mới tốt nghiệp các ngành kinh tế, quản trị kinh doanh, marketing. Tham gia làm việc 4 buổi/tuần, thời gian tối thiểu 3 tiếng/buổi. Có đam mê với lĩnh vực bất động sản và mong muốn học hỏi. Kỹ năng giao tiếp tốt và có khả năng làm việc nhóm. Biết quay – dựng clip cơ bản bằng điện thoại (CapCut, TikTok Editor, v.v…). Nhanh nhẹn, chủ động và có tinh thần cầu tiến. Tham gia đầy đủ 03 ngày đào tạo công ty.
Kỹ năng chuyên môn: [''Biết quay – dựng clip cơ bản bằng điện thoại (CapCut, TikTok Editor, v.v…)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Có khả năng làm việc nhóm'', ''Nhanh nhẹn'', ''Chủ động'', ''Có tinh thần cầu tiến'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 15:00)', '[''Được đào tạo và hướng dẫn chi tiết bởi các chuyên gia trong ngành trong quá trình làm việc'', ''Cơ hội thực hành và phát triển kỹ năng nghề nghiệp'', ''Hỗ trợ dấu mộc sau 45 ngày làm việc cho các thực tập sinh có thành tích tốt'', ''Hỗ trợ chi phí thực tập khi phát sinh giao dịch và có cơ hội trở thành nhân viên chính thức sau khi kết thúc thực tập'', ''Thưởng hiệu quả làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (95, 9, 7, 'Nhân Viên Kiểm Duyệt - Support Penalty', 'Xét duyệt CMND của Seller trên hệ thống IH Shopee. Kiểm tra các thông tin của Seller đăng ký để trở thành Shopee Mall. Kiểm tra và duyệt thông tin khiếu nại của Seller: mô tả, mã đơn hàng, hình ảnh chứng minh không vi phạm, ... Báo cáo thông tin khiếu nại xử lý trong ngày theo biểu mẫu quy định.', 'Nắm vững các tiêu chí, quy định để xét duyệt Seller (ứng viên sẽ được training thêm kĩ về các quy định này). Có kỹ năng tin học, sử dụng được các phần mềm Microsoft Office/hệ thống xử lí công việc. Chủ động hoàn thành công việc đúng deadline, thái độ tích cực, cẩn thận và tỉ mỉ, đảm bảo độ chính xác cao.
Kỹ năng chuyên môn: [''Kỹ năng tin học'', ''Sử dụng Microsoft Office'']
Kỹ năng mềm: [''Chủ động'', ''Thái độ tích cực'', ''Cẩn thận'', ''Tỉ mỉ'', ''Đảm bảo độ chính xác cao'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Lương vào thứ 7 hàng tuần'', ''Trang bị đầy đủ công cụ, trang thiết bị'', ''Môi trường làm việc trẻ trung, năng động'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (96, 10, 7, 'Nhân Viên Thiết Kế', 'Thiết kế ấn phẩm social media (ảnh cover, carousel, reels, thumbnail) theo lịch content tuần. Thiết kế POSM/OOH tại điểm tủ. Chuẩn bị file in, làm việc với nhà in, kiểm tra màu và vật liệu. Làm các công việc theo yêu cầu của quản lý.', 'Nam/nữ từ 18-25 tuổi. Sử dụng thành thạo Adobe Photoshop, Illustrator; và Figma. Tư duy bố cục rõ ràng, mắt thẩm mỹ hiện đại, bám sát brand guideline. Kỹ năng trình bày ý tưởng, tiếp nhận feedback nhanh, chủ động đề xuất cải tiến. Có tư duy sáng tạo, linh hoạt và chủ động trong công việc. Kỹ năng làm việc độc lập và làm việc nhóm tốt.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Illustrator'', ''Figma'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Kỹ năng trình bày ý tưởng'', ''Kỹ năng làm việc độc lập'', ''Kỹ năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Cơ hội phát triển trong một startup công nghệ có tốc độ tăng trưởng nhanh'', ''Được đào tạo về kiến thức truyền thông và chăm sóc khách hàng'', ''Môi trường làm việc trẻ, năng động, chuyên nghiệp'', ''Hỗ trợ cấp dấu mộc thực tập cho sinh viên nếu cần'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (97, 2, 7, 'Nhân Viên Content & Video Creator', '1. Content: * Lên ý tưởng, viết kịch bản video ngắn (30s–2 phút) * Phối hợp với team Marketing xây dựng nội dung 2. Quay – Dựng: * Set up bối cảnh: góc máy, ánh sáng, âm thanh * Hỗ trợ quay cùng team content, stylist, nhân vật * Dựng video: cắt ghép, chỉnh màu, thêm hiệu ứng phù hợp nền tảng Thời gian làm việc: Full-time/Part-time tại văn phòng Hà Nội', 'Kỹ năng chuyên môn: * Biết dùng Canva, Capcut (Photoshop, AI là lợi thế) * Có gu thẩm mỹ, sáng tạo, bắt trend tốt * Giao tiếp tốt, chủ động, đúng deadline * Làm việc nhóm hiệu quả, tinh thần trách nhiệm cao Ưu tiên: * Ứng viên từng làm content video (TikTok, Instagram, Facebook) * Kinh nghiệm marketing ngành Sinh – Hóa – Y – Dược
Kỹ năng chuyên môn: [''Canva'', ''Capcut'', ''Photoshop'', ''AI'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Chủ động'', ''Đúng deadline'', ''Làm việc nhóm hiệu quả'', ''Tinh thần trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '8.0 - 10.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Đào tạo chuyên sâu về Content, Kĩ thuật Quay Dựng và Marketing tổng hợp'', ''Môi trường làm việc sáng tạo, năng động'', ''Cơ hội làm việc với các dự án lớn'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (98, 3, 7, 'Nhân Viên Truyền Thông Đối Ngoại Parttime', '+ Gửi thông tin đến khách hàng về nội dung, ý nghĩa, mục đích + Hỗ trợ, tư vấn và hoàn thành dịch vụ truyền thông theo mẫu + Viết bài PR theo mẫu có sẵn, tham gia tổ chức sự kiện tại Việt Nam, ASEAN, ASIA + Làm việc teamword, nâng cao kinh nghiệm và kỹ năng làm việc', '+ Nam/nữ tuổi Sinh viên ĐH, CĐ hoặc đã tốt nghiệp + Chăm chỉ, năng động, sáng tạo + Giao tiếp cơ bản, ứng xử tốt + Tin học Văn Phòng, Tiếng anh cơ bản + Hồ sơ xin việc gồm: đơn xin việc, sơ yếu lý lịch tự thuật + Nộp hồ sơ sớm sẽ được ưu tiên trước
Kỹ năng chuyên môn: [''Tin học Văn Phòng'', ''Tiếng Anh cơ bản'']
Kỹ năng mềm: [''Chăm chỉ'', ''Năng động'', ''Sáng tạo'', ''Giao tiếp cơ bản'', ''Ứng xử tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '2.0 - 6.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Môi trường trẻ trung, năng động'', ''Cơ hội thăng tiến cao'', ''Được đào tạo chuyên môn, kỹ năng làm việc'', ''Hỗ trợ dấu thực tập hoặc kiến tập'', ''Cấp giấy chứng nhận thời gian làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (99, 7, 7, 'Thực Tập Sinh Marketing Tool Part-Time, Full-Time', 'Quản lý và vận hành hệ thống tool, app quảng cáo của công ty có khả năng tiếp cận hàng triệu người. Xây dựng, lựa chọn các thông điệp truyền tải phù hợp để truyền thông. Nhập các thông tin truyền thông vào cơ sở dữ liệu của tool. Sử dụng Ai viết bài, làm clip,… Chuyển thông tin khách hàng quan tâm từ kết quả chạy tool về cho kinh doanh. Thời gian thực tập: 6 tháng. Công ty chỉ tuyển ứng viên đi thực tập lấy kinh nghiệm, để được đào tạo chuyên ngành và ở lại làm việc lâu dài cho công ty. Chứng chỉ thực tập được cấp sau khi hoàn thành khóa thực tập.', 'Chấp nhận sinh viên 1, 2, 3, 4. Nhanh nhẹn, linh hoạt, giao tiếp tốt. Có laptop cá nhân. Có kinh nghiệm xây dựng, tổ chức, hoạt động ở các club. Tự tin trước ống kính, trước nhiều khán giả, trong các hội thảo. Độc lập trong công việc, có khả năng làm việc nhóm.
Kỹ năng chuyên môn: [''Sử dụng Mạng Xã Hội'', ''Phân tích dữ liệu'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Quản lý thời gian'', ''Giao tiếp tốt'', ''Khả năng sáng tạo'', ''Viết Nội Dung'', ''Khả Năng Học Hỏi Nhanh'', ''Trung Thực'', ''Cẩn Thận'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Toàn thời gian: Từ thứ 2 đến thứ 6, 7h/ngày; Bán thời gian: Tối thiểu 15h/tuần', '[''Cấp chứng chỉ thực tập'', ''Phụ cấp hỗ trợ thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (100, 8, 7, 'Thực Tập Sinh Thiết Kế', 'Phụ trách thiết kế các ấn phẩm truyền thông của công ty: Banner, Poster, Standee, Backdrop, chỉnh sửa hình ảnh...trên kênh Online và Offline. Chỉnh sửa ảnh, chỉnh sửa và dựng video cơ bản. Tham gia sáng tạo, lên ý tưởng cho hình ảnh và chương trình truyền thông của công ty. Bảo đảm tiêu chuẩn thiết kế được duy trì một cách đồng nhất. Hoàn thành các công việc khác theo sự phân công của quản lý. Hỗ trợ các bộ phận khác khi có nhu cầu.', 'Sinh viên năm cuối hoặc đã tốt nghiệp các trường liên quan đến ngành Thiết kế đồ họa. Sử dụng kỹ năng thiết kế đồ họa và các công cụ thiết kế như Adobe Photoshop, Illustrator và các phần mềm đồ họa khác. Đam mê thiết kế đồ họa, có tư duy thiết kế tốt, đầu óc sáng tạo, truyền tải ý tưởng và giao tiếp tốt. Có khả năng biết chụp và chỉnh sửa hình ảnh, phần mềm chỉnh sửa video như Adobe Premiere Pro, Capcut là một điểm cộng. Có khả năng làm việc độc lập/nhóm và chịu được áp lực công việc. Cởi mở, sẵn sàng học hỏi, năng động, chủ động, chịu khó. Bảo đảm các sản phẩm đúng deadline và yêu cầu của dự án. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'', ''Adobe Premiere Pro'', ''Capcut'']
Kỹ năng mềm: [''Đam mê thiết kế đồ họa'', ''Tư duy thiết kế tốt'', ''Đầu óc sáng tạo'', ''Giao tiếp tốt'', ''Làm việc độc lập/nhóm'', ''Chịu được áp lực công việc'', ''Cởi mở'', ''Sẵn sàng học hỏi'', ''Năng động'', ''Chủ động'', ''Chịu khó'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Phụ cấp trong thời gian thực tập'', ''Khám phá và phát triển kỹ năng trong thiết kế đồ họa'', ''Hỗ trợ trong việc học hỏi, nâng cao kỹ năng và kiến thức chuyên môn'', ''Nhận voucher xem phim hàng tháng'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (101, 9, 7, 'Người tạo kinh doanh xã hội-Cộng tác viên (3 tháng)', 'Nhà sáng tạo kinh doanh xã hội (SBC) là một cuộc thi học tập và cạnh tranh đổi mới quốc tế, trao quyền cho các nhà thay đổi trẻ tuổi phát triển các ý tưởng kinh doanh xã hội, giải quyết các vấn đề xã hội cấp bách và tạo ra tác động bền vững. Trong những năm qua, SBC đã kết nối các sinh viên, cố vấn và các chuyên gia trên toàn thế giới để đồng sáng tạo các mô hình kinh doanh sáng tạo với mục đích xã hội. Chúng tôi đang tìm kiếm các cộng tác viên nhiệt tình và chủ động để tham gia nhóm tổ chức SBC của chúng tôi trong khoảng thời gian 3 tháng. Bạn sẽ làm việc trực tiếp với nhóm cốt lõi để hỗ trợ truyền thông, thực hiện sự kiện, tiếp cận cộng đồng và hậu cần dự án. Trách nhiệm chính bao gồm hỗ trợ lập kế hoạch và thực hiện các phiên định hướng SBC, các hoạt động kết nối mạng và hội thảo đào tạo, hỗ trợ giao tiếp người tham gia và duy trì sự tham gia của cộng đồng trên các kênh, điều phối hậu cần cho các sự kiện và hoạt động chương trình, nghiên cứu và tiếp cận với các đối tác tiềm năng, người tham gia.', 'You Are Someone Who: Is a university student or fresh graduate (preferably in Communications, Marketing, Business, or related fields). Has strong communication skills in both English and Vietnamese. Enjoys working with youth, social impact projects, and global initiatives. Is detail-oriented, responsible, and a proactive team player. Has experience with content creation, design tools (Canva, CapCut, etc.), or event organizing (a plus but not required).
Kỹ năng chuyên môn: [''Content creation'', ''Design tools (Canva, CapCut, etc.)'', ''Event organizing'']
Kỹ năng mềm: [''Strong communication skills'', ''Detail-oriented'', ''Responsible'', ''Proactive team player'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Monday - Friday (from 08:00 to 17:30)', '[''First-hand experience in organizing an international social innovation program'', ''Network expansion with students, experts, and mentors from around the world'', ''Mentorship and feedback from professionals in business, education, and impact sectors'', ''Certificate of contribution upon successful completion'', ''Flexible working hours'', ''Dynamic, supportive team culture'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (102, 10, 7, 'Thực Tập Sinh Content Creator', 'Triển khai sáng tạo nội dung (Reel, video short,...) trên đa kênh: Facebook, Instagram, Tiktok. Phối hợp với bộ phận media sáng tạo các kịch bản, ấn phẩm chất lượng đăng tải trên các nền tảng (nội dung, hình ảnh, video,...). Research các idea từ nhiều nguồn, video content xu hướng global đề xuất cho kênh mình phụ trách. Biết làm video, chỉnh sửa bằng các công cụ, ứng dụng AI vào công việc.', 'Tuyển dụng những bạn trẻ GenZ từ 2000 - 2006. Sáng tạo, tư duy ngôn ngữ & hình ảnh tốt, thường xuyên cập nhật các xu hướng mới. Kỹ năng sử dụng các công cụ làm việc cơ bản: Capcut, Canva, Photoshop... Kỹ năng hiểu và sáng tạo nội dung đa nền tảng: Facebook, Instagram, Website, Tiktok. Thái độ cầu tiến, học hỏi không giới hạn. Luôn chủ động - tích cực - phối hợp teamwork và báo cáo.
Kỹ năng chuyên môn: [''Capcut'', ''Canva'', ''Photoshop'']
Kỹ năng mềm: [''Sáng tạo'', ''Tư duy ngôn ngữ & hình ảnh tốt'', ''Thái độ cầu tiến'', ''Học hỏi không giới hạn'', ''Chủ động'', ''Tích cực'', ''Phối hợp teamwork'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 1000000.00, '0.3 - 1.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:15 đến 17:30)', '[''Hỗ trợ thực tập: 300.000 – 1.000.000 VNĐ/tháng'', ''Dấu mộc xác nhận thực tập'', ''Chứng nhận hoàn thành thực tập sinh xuất sắc'', ''Thư giới thiệu từ Trưởng phòng Truyền thông'', ''Cơ hội khóa học tiếng Anh miễn phí'', ''Được đào tạo hoặc cử đi đào tạo các kỹ năng phục vụ cho công việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (103, 2, 7, 'Cộng Tác Viên Thẻ Tín Dụng', 'Tư vấn, chăm sóc, tìm kiếm khách hàng mở thẻ tín dụng VIB. Hoàn tất hồ sơ mở thẻ cho khách hàng qua Max App. 100% Digital, Khách hàng không cần chuẩn bị hồ sơ như : Form, sao kê lương , HDLĐ. VIB Tuyển dụng trên Toàn Quốc, Phỏng vấn qua điện thoại, Ký HD Cộng Tác với VIB hội sở. Mỗi CTV được cấp 1 QR Code làm việc Online, không cần đến văn phòng, không gặp trực tiếp khách hàng.', 'Bạn chỉ cần thỏa 1 trong các điều kiện bên dưới. Nhân viên các Bank, Công ty Tài chính, Telesales, Bất động sản, Bảo hiểm, Chứng khoán, Du lịch, Kinh doanh, sales, nhân viên văn phòng, chăm sóc khách hàng.... Ưu tiên Telesales, Sales thị trường, Kênh POST, Sales, CSKH tất cả ngành nghề. Nhân viên văn phòng/ Sinh viên toàn quốc muốn làm thêm. Bạn đang đi làm và mong muốn có thêm công việc thứ 2 để có nguồn thu nhập thụ động. Quản lý đội ngũ, Teamleader, Sup, ASM, Head, Call Center. Hoặc là chủ doanh nghiệp, hộ kinh doanh.', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 46000000.00, '22.0 - 46.0 triệu', 'Làm việc Online', '[''Làm việc Online không cần đến văn phòng Ngân hàng VIB'', ''Cơ hội trở thành chuyên viên chính thức Fulltime tại VIB'', ''Được đào tạo bài bản về kỹ năng và nghiệp vụ của sản phẩm thẻ của VIB'', ''Chính sách hoa hồng CTV lên đến 1.000.000 vnđ/ Thẻ'', ''Hưởng hoa hồng trên số thẻ giới thiệu'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (104, 3, 7, 'Thực Tập Sinh Thiết Kế Đồ Họa', 'Phối hợp cùng Team Thiết kế và các bộ phận liên quan để sản xuất nội dung: banner, hình ảnh, video cho chiến dịch Digital. Tham gia cùng team AI Content để tạo ra các sản phẩm/dịch vụ mới phục vụ cho chiến dịch Digital Marketing của các dự án Bất động sản. Thực hiện các công việc khác trong chuyên môn theo sắp xếp của Quản lý trực tiếp.', 'Đang theo học ngành Thiết Kế Đồ Họa hoặc lĩnh vực liên quan. Portfolio thể hiện kỹ năng thiết kế và tính sáng tạo. Biết sử dụng các công cụ thiết kế: Photoshop, Illustrator, After Effect... Thực tế, linh hoạt, cởi mở, sẵn sàng đón nhận thử thách, thử sức và học hỏi cái mới.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''After Effect'']
Kỹ năng mềm: [''Khả Năng Làm Việc Nhóm'', ''Khả Năng Sáng Tạo Và Tư Duy Hình Ảnh'', ''Thực tế'', ''Linh hoạt'', ''Cởi mở'', ''Sẵn sàng đón nhận thử thách'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:00 đến 12:00), Thứ 7 làm việc tại nhà', '[''Hỗ trợ thực tập: 2-4 triệu/tháng/tùy năng lực'', ''Có cơ hội nhận thêm hoa hồng kinh doanh theo dự án với những chiến dịch xuất sắc'', ''Được xác nhận và đóng dấu tham gia thực tập từ công ty'', ''Có cơ hội trở thành nhân viên chính thức với thu nhập và chế độ đãi ngộ cao hơn nhiều lần'', ''Có cơ hội tham gia các hoạt động Team building và du lịch hàng năm của công ty'', ''Môi trường làm việc trẻ trung năng động, đồng nghiệp vui vẻ, hỗ trợ hết mình'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (105, 7, 7, 'Content Creator Tiếng Trung', 'Phát triển và quản lý kênh TikTok của công ty. Sưu tầm, tìm kiếm và sáng tạo nội dung phù hợp với định hướng phát triển kênh. Phối hợp với chuyên viên quay dựng để thực hiện các nội dung kênh. Theo dõi, phân tích số liệu tương tác trên các video và đưa ra đề xuất cải thiện. Lên kế hoạch nội dung phát triển kênh hàng tuần/ tháng.', 'Nữ: 20-30 tuổi. Tiếng Trung trình độ từ HSK 5 trở lên, có khả năng nghe hiểu cơ bản clip từ TQ. Có kinh nghiệm phát triển kênh TikTok, sáng tạo nội dung. Sáng tạo, nắm bắt nhanh nhạy các xu hướng thịnh hành trên TikTok và mạng xã hội. Khả năng làm việc độc lập và chủ động tìm kiếm ý tưởng mới. Hiểu biết về thị trường thời trang và đối tượng khách hàng mục tiêu. Kỹ năng giao tiếp tốt và khả năng làm việc nhóm. Để sản phẩm và portfolio trong CV.
Kỹ năng chuyên môn: [''Tiếng Trung (HSK 5 trở lên)'', ''Phát triển kênh TikTok'', ''Sáng tạo nội dung'']
Kỹ năng mềm: [''Sáng tạo'', ''Khả năng làm việc độc lập'', ''Kỹ năng giao tiếp'', ''Khả năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 12000000.00, '10.0 - 12.0 triệu', 'Thứ 2 - Thứ 7, 8h - 17h30 (Thứ 7 nghỉ sớm từ 16h30)', '[''Được đào tạo kỹ năng chuyên môn'', ''Được đào tạo kỹ năng mềm'', ''Đầy đủ chế độ đãi ngộ (bảo hiểm, trợ cấp đi lại, nhà ở, ăn trưa, du lịch)'', ''Thưởng lễ/Tết theo năng lực và hiệu quả kinh doanh'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (106, 8, 7, 'Nhân Viên Thiết Kế', 'Thiết kế các ấn phẩm truyền thông (banner, poster, brochure, social media post, v.v.). Hỗ trợ xây dựng bộ nhận diện thương hiệu, landing page, slide thuyết trình,... Phối hợp với team Marketing/Content để triển khai các chiến dịch truyền thông. Đảm bảo tiến độ và chất lượng sản phẩm đúng theo yêu cầu.', 'Thành thạo các công cụ thiết kế: Photoshop, Illustrator (biết thêm Figma, Premiere/After Effect là lợi thế). Có tư duy thẩm mỹ tốt, khả năng sáng tạo cao. Có kinh nghiệm thiết kế ít nhất 6 tháng. Có laptop cá nhân và chủ động trong công việc.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Figma'', ''Premiere'', ''After Effect'']
Kỹ năng mềm: [''Tư duy thẩm mỹ'', ''Khả năng sáng tạo'', ''Khả năng làm việc độc lập'', ''Quản lý thời gian hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Môi trường làm việc chuyên nghiệp'', ''Hỗ trợ phát triển cá nhân'', ''Tham gia các hoạt động thường niên của công ty'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (107, 9, 7, 'Thực Tập Sinh Marketing', '1. Hỗ trợ triển khai nội dung marketing • Viết bài đăng fanpage, website, nội dung email marketing, bài PR theo hướng dẫn. • Tìm kiếm ý tưởng, xu hướng sáng tạo nội dung trên các nền tảng số. • Biên tập hình ảnh, caption, hashtag cho các chiến dịch truyền thông. 2. Quản lý mạng xã hội & kênh online • Hỗ trợ quản lý và chăm sóc fanpage, TikTok, Zalo OA, Instagram, YouTube... • Trả lời comment, inbox khách hàng theo kịch bản có sẵn. • Cập nhật lịch đăng bài, theo dõi hiệu quả bài viết (lượt tiếp cận, tương tác...). 3. Thiết kế cơ bản & hỗ trợ media • Thiết kế hình ảnh đơn giản bằng Canva, PowerPoint hoặc hỗ trợ chỉnh sửa cơ bản bằng Photoshop (nếu biết). • Hỗ trợ quay video ngắn, clip hậu trường, sự kiện nội bộ. • Tham gia brainstorm, xây dựng concept chiến dịch hoặc video marketing. 4. Báo cáo & học tập • Báo cáo công việc hằng tuần, đề xuất cải tiến nội dung. • Tham gia các buổi đào tạo nội bộ về marketing, thương hiệu, content... • Được mentor hướng dẫn trực tiếp, nhận phản hồi giúp phát triển kỹ năng thực tế.', '• Sinh viên năm 3, 4 hoặc mới tốt nghiệp ngành Marketing, Truyền thông, QTKD... • Có khả năng viết tốt, tư duy logic, cảm thụ hình ảnh và thông điệp tốt. • Biết sử dụng các công cụ Canva, PowerPoint; ưu tiên biết cơ bản Photoshop, CapCut... • Có tinh thần học hỏi, trách nhiệm, làm việc nhóm tốt. • Có thể làm việc tối thiểu 3–5 buổi/tuần.
Kỹ năng chuyên môn: [''Canva'', ''PowerPoint'', ''Photoshop'', ''CapCut'']
Kỹ năng mềm: [''Khả năng viết tốt'', ''Tư duy logic'', ''Cảm thụ hình ảnh'', ''Làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Tối thiểu 3–5 buổi/tuần', '[''Phụ cấp hỗ trợ thực tập'', ''Giấy chứng nhận thực tập'', ''Đào tạo và mentor trực tiếp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (108, 10, 7, 'Thực Tập Sinh Media Quay, Dựng', 'Hỗ trợ set đèn, quay, xử lý màu, dựng clip truyền thông social. Phối hợp với bộ phận Content, designer xây dựng ý tưởng quay dựng. Tham gia các hoạt động của Team marketing. Lập báo cáo định kỳ. Các công việc liên quan theo sự phân công của người hướng dẫn.', 'Trình độ học vấn: Sinh viên năm cuối hoặc mới tốt nghiệp Cao đẳng, Đại học ở các chuyên ngành truyền thông đa phương tiện, designer, marketing hoặc các chuyên ngành liên quan. Có gu thẩm mỹ, nhiều ý tưởng trong quay dựng, cảm âm tốt. Làm việc nhóm. Chỉnh chu, cẩn thận, có trách nhiệm. Gửi kèm portfolio. Thời gian đến công ty: 2 buổi/ tuần (có thể đến Cty nhiều hơn theo nhu cầu).
Kỹ năng chuyên môn: [''Dựng phim'', ''Quay phim'', ''Sử dụng phần mềm chỉnh sửa video (Premiere Pro, Final Cut Pro, Davinci Resolve)'', ''Hiểu biết về ánh sáng, âm thanh, bố cục'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Chỉnh chu'', ''Cẩn thận'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 4 và Thứ 6 (08:00 đến 17:00)', '[''Được sử dụng máy ảnh, thiết bị chuyên nghiệp'', ''Được hướng dẫn bởi các Anh/Chị giàu kinh nghiệm'', ''Môi trường làm việc hiện đại'', ''Cơ hội phát triển lên các vị trí chính thức sau thời gian thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (109, 2, 7, 'Thực Tập Sinh Thiết Kế', 'Phối hợp với các bộ phận liên quan để hỗ trợ lên ý tưởng thiết kế cho các chương trình của công ty hoặc yêu cầu từ khách hàng. Tham gia cùng team lên ý tưởng thiết kế phù hợp với nội dung và mục đích của từng sự kiện/chương trình. Hỗ trợ thiết kế các ấn phẩm phục vụ sự kiện như: key visual, poster, brochure, standee, tagline, backdrop, photo booth,… Các công việc chi tiết sẽ được trao đổi thêm trong buổi phỏng vấn.', 'Có tư duy thẩm mỹ tốt, yêu thích sáng tạo và ham học hỏi. Sinh viên năm cuối hoặc vừa tốt nghiệp chuyên ngành Thiết kế đồ họa, Mỹ thuật ứng dụng, hoặc các ngành liên quan. Có nền tảng mỹ thuật và hiểu biết cơ bản về bố cục thiết kế. Biết sử dụng các phần mềm thiết kế như: Adobe Illustrator, Photoshop, InDesign, Corel,… Có cơ hội được làm việc ở các chương trình lớn.
Kỹ năng chuyên môn: [''Adobe Illustrator'', ''Photoshop'', ''InDesign'', ''Corel'']
Kỹ năng mềm: [''Tư duy thẩm mỹ tốt'', ''Yêu thích sáng tạo'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)', '[''Được hỗ trợ dấu mộc thực tập.'', ''Được công ty tổ chức các lớp huấn luyện, đào tạo hội nhập và nâng cao chuyên môn.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (110, 3, 7, 'Nhân Viên Vận Hành Livestream Facebook, Tiktok', 'Chuẩn bị & vận hành các phiên livestream chuyên nghiệp (setup ánh sáng, âm thanh, camera). Điều phối lịch phát sóng, đảm bảo luồng livestream diễn ra trơn tru. Chạy Ads cho phiên livestream. Quản lý kỹ thuật livestream (camera, ánh sáng, âm thanh...). Lên kịch bản live để tạo không khí sôi động và tương tác cao. Theo dõi và điều phối hoạt động của các phiên livestream, các chiến dịch bán hàng để đạt được mục tiêu doanh số đề ra. Tổng hợp và chia sẻ report hàng ngày về các phiên live, chủ động kiểm tra dashboard để theo dõi và tối ưu hiệu quả hoạt động. Phân tích dữ liệu và đề xuất giải pháp để cải thiện chất lượng livestream và tối ưu kênh bán hàng.', 'Có kinh nghiệm livestream và vận hành sàn TMĐT là một lợi thế. Biết chạy Ads cho phiên Livestream. Kỹ năng lên kịch bản cho phiên livestream. Điều chỉnh kỹ thuật trong phiên livestream. Biết sử dụng các công cụ livestream OBS (trên Facebook, TikTok Live). Biết setup góc máy quay, ánh sáng cơ bản phục vụ cho livestream.
Kỹ năng chuyên môn: [''Chạy Ads cho phiên Livestream'', ''Sử dụng các công cụ livestream OBS'', ''Setup góc máy quay, ánh sáng cơ bản'']
Kỹ năng mềm: [''Kỹ năng lên kịch bản cho phiên livestream'', ''Điều chỉnh kỹ thuật trong phiên livestream'', ''Kỹ năng giao tiếp'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 18000000.00, '11.0 - 18.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Lương thưởng tháng 13'', ''Thưởng hiệu quả kinh doanh'', ''Được tham gia BHXH, BHYT, BHTN'', ''Được trang bị máy tính, thiết bị ngay từ ngày đầu làm việc'', ''Môi trường làm việc trẻ trung, năng động'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (111, 7, 7, 'Thực Tập Sinh Video Content', '- Lên ý tưởng, viết kịch bản cho video ngắn (TikTok, Reels…) - Đóng góp sáng tạo nội dung và xuất hiện trong video - Quay dựng video cơ bản - Hỗ trợ các công việc liên quan đến sản xuất nội dung - Hỗ trợ lên idea, calendar và nội dung chi tiết cho bài đăng Facebook - Phối hợp xây dựng nội dung cho các kênh', 'Sinh viên năm 3,4 các ngành Marketing, kinh tế,… Chăm chỉ, chịu khó Có thể thực tập full trong 3 tháng Không yêu cầu kinh nghiệm. Không ngại ống kính, viết content
Kỹ năng chuyên môn: [''Sử dụng phần mềm chỉnh sửa video (premiere Pro, Final Cut Pro, Davinci Resolve)'', ''Quay phim cơ bản'']
Kỹ năng mềm: [''Chăm chỉ'', ''Chịu khó'', ''Không ngại ống kính'', ''Viết content'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '1.5 - 2.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:30)', '[''Trợ cấp thực tập'', ''Dấu mộc tròn báo cáo'', ''Cơ hội học tập, làm việc thực tế trong môi trường năng động'', ''Cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (112, 8, 7, 'Nhân Viên Livestream', 'Làm host livestream trên sàn thương mại điện tử về sản phẩm chăm sóc cơ thể cho nam và nữ brand ACE MAN, SHINEY độc quyền của công ty. Trực tiếp Livestream trên hệ thống sàn TMĐT: TiktokShop; Shopee của công ty để giới thiệu, quảng bá, bán hàng (các kênh tùy chiến dịch và thời điểm). Cùng team đánh giá hiệu quả công việc từ các buổi live, từ các chiến dịch theo số liệu thực tế. Báo cáo với trưởng bộ phận kết quả, những đề xuất hoặc vấn đề cần xử lý và cải thiện.', 'Nam, nữ, LGBT, độ tuổi sinh năm 2003 - 2007, ngoại hình ưa nhìn, hoạt ngôn. Không yêu cầu kinh nghiệm, sinh viên chưa kinh nghiệm được đào tạo. Có thể đăng ký làm được nhiều ca trong 1 ngày, mỗi ca khoảng 3 tiếng. Là người có khả năng hoạt ngôn, năng động, máu lửa, không ngại trước ống kính, chỉn chu, trách nhiệm, chăm chỉ, ham học hỏi. Mong muốn có được thu nhập cao, gắn bó lâu dài.
Kỹ năng mềm: [''Giao tiếp'', ''Năng động'', ''Trách nhiệm'', ''Chăm chỉ'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 10000000.00, '4.5 - 10.0 triệu', 'Ca 1 (8h – 11h); Ca 2 (10h – 13h); Ca 3 (19 – 22h); Ca 4 (20 – 23h)', '[''Lương tối thiểu 50.000đ/ giờ + phụ cấp'', ''Được đào tạo chuyên môn'', ''Môi trường làm việc trẻ trung, năng động'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (113, 9, 7, 'Nhân Viên Marketing (Part Time)', 'Phụ trách content social: Xây dựng page Instagram, Facebook, và Tiktok lĩnh vực gym nữ. Xây dựng kịch bản, nội dung bài viết, tìm kiến xu hướng và đề xuất ý tưởng cho gym contents. Quay, chụp, edit clip và hình ảnh để up mỗi tuần (có caption kèm theo).', 'Giới tính: Nữ, tuổi từ 23-30. Tốt nghiệp Cao đẳng, Đại học chuyên ngành Marketing hoặc các chuyên ngành liên quan. Ưu tiên ứng viên ở khu vực Biên Hòa, Đồng Nai. Không yêu cầu lên Công ty làm việc thường xuyên, có thể làm việc tại nhà. Có ít nhất 1 năm kinh nghiệm làm việc trong lĩnh vực Marketing. Hiểu biết sâu rộng về các kênh Marketing Online và Offline. Sử dụng thành thạo các phần mềm cơ bản trong ứng dụng chuyên môn. Nắm bắt nhanh nhạy xu hướng thị trường và có khả năng sáng tạo.
Kỹ năng chuyên môn: [''Sử dụng thành thạo các phần mềm cơ bản trong ứng dụng chuyên môn'', ''Hiểu biết sâu rộng về các kênh Marketing Online và Offline'']
Kỹ năng mềm: [''Nắm bắt nhanh nhạy xu hướng thị trường'', ''Có khả năng sáng tạo'']', 'PART_TIME', 'ONSITE', 'biên hòa', 'Đồng Nai', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thời gian linh động', '[''Môi trường làm việc năng động, thoải mái'', ''Công việc tự do'', ''Được cấp thẻ tập gym miễn phí trong vòng 2 tháng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (114, 10, 7, 'Thực Tập Sinh Marketing', '1. Hỗ trợ xây dựng nội dung truyền thông. Viết bài cho fanpage, website, email marketing, blog... Chụp ảnh hoặc hỗ trợ chụp ảnh sản phẩm in để dùng trong truyền thông. 2. Quản lý mạng xã hội và kênh truyền thông. Đăng bài lên Facebook, Instagram, Zalo OA, TikTok… Tương tác với khách hàng qua các kênh online. Theo dõi, cập nhật hiệu quả bài đăng.', 'Kỹ năng cần có: Kỹ năng viết nội dung (content writing). Am hiểu mạng xã hội, có tư duy thẩm mỹ tốt. Năng động, sáng tạo. Có kiến thức cơ bản về marketing và ngành in là lợi thế.
Kỹ năng chuyên môn: [''Kỹ năng viết nội dung (content writing)'', ''Am hiểu mạng xã hội'', ''Có kiến thức cơ bản về marketing và ngành in'']
Kỹ năng mềm: [''Năng động'', ''Sáng tạo'', ''Tư duy thẩm mỹ tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 07:30 đến 17:00)', '[''Được hướng dẫn kỹ về kỹ năng, quy trình và cách thực hiện công việc'', ''Được đào tạo kiến thức về sản phẩm & chuyên môn'', ''Được hưởng mức lương phù hợp với năng lực'', ''Được hướng dẫn đào tạo thêm về thiết kế'', ''Làm việc trong môi trường thân thiện'', ''Phụ cấp xăng xe, cước điện thoại'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (115, 2, 7, 'Thực Tập Sinh Designer', 'Hỗ trợ thực hiện thiết kế hình ảnh quảng cáo 2D, 3D, Motion Graphic,... Hỗ trợ team thiết kế các hình ảnh quảng cáo trên kênh Digital Marketing (website, facebook, google,...) như visual, banner ads, youtube,... Báo cáo cho Design Leader.', 'Sinh viên các trường đại học trong và ngoài nước khối ngành kinh tế, quản trị kinh doanh, marketing,.... Có am hiểu hoặc từng làm trong mảng thiết kế. Sử dụng cơ bản các công cụ Photoshop, Illustrator (biết sử dụng 1 trong các phần mềm Flash, Animate, After Effect, Premier là một lợi thế. Hoặc sẽ được training khi nhận việc).
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Flash'', ''Animate'', ''After Effect'', ''Premier'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'fulltime, tối đa 03 tháng', '[''Được đào tạo như một nhân viên thực thụ'', ''Có cơ hội trở thành nhân viên chính thức'', ''Môi trường làm việc chuyên nghiệp, năng động'', ''Tham gia các hoạt động phong trào ngoại khóa'', ''Cơ hội được đào tạo, học tập và cấp chứng chỉ của Google'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (116, 3, 7, 'Thực Tập Sinh Design', '- Hỗ trợ thực hiện thiết kế hình ảnh quảng cáo 2D, 3D, Motion Graphic,... - Hỗ trợ team thiết kế các hình ảnh quảng cáo trên kênh Digital Marketing (website, facebook, google,...) như visual, banner ads, youtube,... - Báo cáo cho Design Leader', '- Tốt nghiệp các trường đại học trong và ngoài nước khối ngành kinh tế, quản trị kinh doanh,marketing,.... - Có am hiểu hoặc từng làm trong mảng Digital marketing, Marketing online, Internet. - Thành thạo Tiếng Anh - Có kỹ năng giao tiếp, thuyết phục, thống kê, phân chia nhiệm vụ, lập kế hoạch tốt. - Nhạy bén, linh động, có khả năng đi công tác lâu dài, có hỗ trợ phụ cấp
Kỹ năng chuyên môn: [''Thiết kế hình ảnh quảng cáo 2D, 3D, Motion Graphic'', ''Digital marketing'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Thuyết phục'', ''Thống kê'', ''Phân chia nhiệm vụ'', ''Lập kế hoạch'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '2.0 triệu', 'Fulltime, tối đa 03 tháng', '[''Được đào tạo như một nhân viên thực thụ'', ''Cơ hội trở thành nhân viên chính thức'', ''Môi trường làm việc chuyên nghiệp'', ''Tham gia các hoạt động ngoại khóa'', ''Cơ hội được đào tạo và cấp chứng chỉ của Google'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (117, 7, 7, 'Nữ Nhân Viên Quay Video Ngắn, Livestream Bán Hàng', 'Làm mẫu video kênh tiktok, Livestream bán hàng hoặc chụp ảnh cùng sản phẩm tại cửa hàng. Quay video ngắn và đơn giản về cửa hàng, sản phẩm, nội bộ, hoặc nắm bắt các trend đang hot. Làm 4h-6h 1 ngày linh hoạt thời gian. Có thể sắp xếp thời gian để phù hợp ứng viên (nhất là các bạn sinh viên làm thêm).', 'Nữ có ngoại hình (ưu tiên bắt buộc vì sẽ phải tư vấn bán hàng và lên hình trong các video/live). Gu thời trang tốt, đảm bảo hình ảnh đẹp khi lên hình. Ăn nói lưu loát, giao tiếp tốt. Không ngại ống kính. Hợp tác được lâu dài (từ 6 tháng - 1 năm trở lên vì sản phẩm nước hoa hiệu là hàng cao cấp cần thời gian làm việc đủ lâu để hiểu sâu hơn). Ưu tiên các bạn trẻ năng động (nếu là sinh viên có thể ưu tiên thời gian làm phù hợp ứng viên - không cố định ca).
Kỹ năng mềm: [''Giao tiếp tốt'', ''Ăn nói lưu loát'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '5.0 - 6.0 triệu', '4 - 6 giờ mỗi ngày', '[''Thưởng hoa hồng theo doanh thu'', ''Thưởng nóng, cuối năm lương tháng 13, quà tết'', ''Nghỉ chủ nhật - nghỉ lễ tết theo quy định'', ''Hoạt động ngoại khóa thường xuyên'', ''Hợp đồng lao động, chế độ bảo hiểm đầy đủ nếu gắn bó lâu dài và làm fulltime'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (118, 8, 7, 'Thực Tập Tại PVL Farm – 6 Tháng', 'PVL — Pearl Vietnam Limited — là một trong những công ty nuôi cấy ngọc trai 100% vốn FDI lâu đời nhất tại vùng biển thanh bình Vạn Ninh gần Nha Trang. Chúng tôi giám sát mọi giai đoạn của việc nuôi trai: Từ việc nuôi cấy các sinh vật phù du cực nhỏ làm thức ăn cho con trai, cho đến việc thu hoạch những viên ngọc trai tuyệt đẹp bán ra thị trường quốc tế. Đây là cơ hội để bạn tham gia cùng chúng tôi tại thời điểm quan trọng khi chúng tôi kết hợp khoa học, tính bền vững và du lịch thành một câu chuyện duy nhất.', 'Tuyển dụng: 2 Thực tập sinh có nền tảng về Nuôi trồng thủy sản/Sinh học biển; 2 Thực tập sinh có nền tảng về CNTT/Tiếp thị kỹ thuật số/Tiếp thị chung/Kinh doanh.
Kỹ năng chuyên môn: [''Nuôi trồng thủy sản'', ''Sinh học biển'', ''CNTT'', ''Tiếp thị kỹ thuật số'', ''Kinh doanh'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Cẩn thận'', ''Chịu khó'', ''Khả năng học hỏi nhanh'', ''Khả năng thích ứng'']', 'INTERNSHIP', 'ONSITE', 'vạn ninh', NULL, 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 07:00 đến 17:00)', '[''Phụ cấp đi lại: 2.500.000 VND/tháng'', ''Thưởng hiệu quả làm việc'', ''Sự cố vấn từ các nhà lãnh đạo doanh nghiệp và nuôi trồng thủy sản cấp cao'', ''Lộ trình đào tạo nghề bài bản'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (119, 9, 7, 'Nhân Viên Marketing Part-Time', 'Viết bài PR, mô tả sản phẩm, bài viết cho các nền tảng Facebook, Alibaba, LinkedIn,... Tư vấn và chăm sóc khách hàng trong và ngoài nước qua các nền tảng zalo, facebook, whatsapp,... Gửi thông tin khách hàng cho bộ phận kinh doanh. Đăng bài tuyển dụng cho công ty khi cần thiết. Hỗ trợ các công việc khác theo yêu cầu của cấp trên.', 'Sinh viên năm 3–4 hoặc mới tốt nghiệp chuyên ngành Marketing, Kinh doanh, Logistics,... Tiếng anh ở mức khá Có kỹ năng giao tiếp, đàm phán Có kiến thức cơ bản về bán hàng, xuất nhập khẩu Kỹ năng viết nội dung tốt Tinh thần học hỏi, chủ động, trách nhiệm cao trong công việc Có laptop cá nhân
Kỹ năng chuyên môn: [''Kỹ năng viết nội dung'', ''Kiến thức cơ bản về bán hàng'', ''Xuất nhập khẩu'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Đàm phán'', ''Tinh thần học hỏi'', ''Chủ động'', ''Trách nhiệm cao trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '1.0 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Lương cứng: 25k/h + Thưởng doanh thu + Thưởng lễ'', ''Được học hỏi, đào tạo bài bản'', ''Đăng ký ca linh hoạt theo lịch học, không giới hạn số buổi đi làm, tối thiểu 4b/tuần'', ''Xét duyệt tăng lương theo năng lực'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (120, 10, 7, 'Nhân Viên Designer Partime Xoay Ca Linh Hoạt', 'Xây dựng ý tưởng và thiết kế đồ họa các sản phẩm truyền thông thương hiệu. Thiết kế các ấn phẩm quảng cáo in ấn, ấn phẩm cho sự kiện, sản phẩm quảng cáo online. Thực hiện các công việc khác theo sự phân công của Leader.', '- Nữ, có kinh nghiệm cộng tác viên từ 3 tháng vị trí tương đương, từng làm lĩnh vực thời trang - Tốt nghiệp Đại Học, Cao Đẳng chuyên nghành thiết kế đồ họa hoặc chuyên nghành có liên quan - Khả năng mỹ thuật tốt, tính năng động, sáng tạo, luôn chủ động trong công việc; - Kỹ năng làm việc độc lập và làm việc theo nhóm; - Gửi CV + Portfolio
Kỹ năng chuyên môn: [''Sử dụng thành thạo phần mềm thiết kế đồ họa (Photoshop, Illustrator, Ai)'']
Kỹ năng mềm: [''Khả năng làm việc độc lập và làm việc theo nhóm'', ''Khả năng sáng tạo và tư duy hình ảnh tốt'', ''Tính năng động'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.5 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)', '[''Thưởng các ngày lễ, Tết'', ''Sinh nhật hàng tháng, tặng quà Noel'', ''Tham gia hoạt động vui chơi, party, teambuilding, du lịch do Công ty tổ chức'', ''Được hưởng chế độ đào tạo nâng cao nghiệp vụ và có cơ hội thăng tiến trong nghề nghiệp'', ''Xét tăng lương phù hợp với sự nỗ lực, đóng góp cho sự phát triển Công Ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (121, 2, 7, 'Livestream shopee bán thời gian', 'Trực tiếp Livestream trên Shopee để giới thiệu và bán các sản phẩm thời trang Thiều Hoa. Hỗ trợ chăm sóc khách hàng: hướng dẫn, giải đáp, trả lời khách về tính năng, giá bán, CTKM, hướng dẫn khách hàng đặt hàng, lấy mã giảm giá. Các công việc khác theo yêu cầu của Ban Giám Đốc (nếu có). Livestream cho brand Paradox thuộc Thiều Hoa.', 'Nam/Nữ/LGBT độ tuổi từ 18 - 25. Tự tin trước ống kính, gương mặt ưa nhìn. Hoạt ngôn, giọng nói rõ ràng, giao tiếp lưu loát, biết cách thu hút dẫn dắt người xem, chốt đơn và bắt trend tốt.
Kỹ năng chuyên môn: []
Kỹ năng mềm: [''Tự tin trước ống kính'', ''Hoạt ngôn'', ''Giọng nói rõ ràng'', ''Giao tiếp lưu loát'', ''Biết cách thu hút dẫn dắt người xem'', ''Chốt đơn'', ''Bắt trend tốt'']', 'PART_TIME', 'ONSITE', 'hà tĩnh', 'Hà Tĩnh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 09:00 đến 23:00)', '[''Được đào tạo về kiến thức sản phẩm'', ''Cách thức livestream'', ''Môi trường làm việc thân thiện, năng động'', ''Đóng BHXH và hưởng các quyền lợi theo quy định nhà nước'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (122, 3, 7, 'Thực Tập Sinh Marketing', 'Viết Content dưới dạng article, print ads, video... Quản lý bài viết trên fanpage, website... Lên chiến dịch quảng cáo trên Facebook, Google Hỗ trợ tổ chức sự kiện, chương trình marketing hàng tháng, quý Tham gia đóng góp ý tưởng Branding, promotion cho bộ phận. Các công việc do cấp trên phân công.', 'Sinh viên sắp hoặc mới tốt nghiệp chuyên ngành marketing, quản trị kinh doanh,... có sở thích và mong muốn học hỏi, tìm hiểu sâu về marketing. Có kiến thức căn bản về Digital marketing hay Social media. Bắt buộc có khả năng viết content và thiết kế, chỉnh sửa hình ảnh cơ bản. Có tư duy Marketing và Sales tốt, khả năng học nhanh để đáp ứng yêu cầu công việc. Yêu thích môi trường trẻ, chủ động trong công việc, chịu được sức ép cao.
Kỹ năng chuyên môn: [''Digital marketing'', ''Social media'', ''Content writing'', ''Basic image editing'']
Kỹ năng mềm: [''Tư duy Marketing'', ''Tư duy Sales'', ''Khả năng học nhanh'', ''Chủ động trong công việc'', ''Chịu được sức ép cao'']', 'INTERNSHIP', 'ONSITE', 'hà tĩnh', 'Hà Tĩnh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Từ thứ 2-7, 8h30-17h30, thực tập 3 tháng, tối thiểu 10 buổi / tuần', '[''Có cơ hội trở thành nhân viên chính thức sau 3 tháng thực tập'', ''Được training bài bản các kiến thức về Digital Marketing từ A-Z'', ''Được rèn luyện kỹ năng Copywriter, Quảng cáo trong môi trường chuyên nghiệp'', ''Được đóng dấu mộc khi tham gia thực tập (Chỉ đóng dấu nếu đi làm tối thiểu 2 tháng)'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (123, 7, 7, 'Nhân Viên Livestream Tiktokshop Part Time Ca Tối', 'Livestream bán hàng trên nền tảng TikTok Shop theo lịch của công ty. Tương tác với người xem, giới thiệu sản phẩm trang sức bạc, chốt đơn trực tiếp trên live. Chuẩn bị sản phẩm, nội dung cần giới thiệu trước mỗi buổi live. Phối hợp cùng team marketing để tăng tương tác, tăng tỷ lệ chuyển đổi. Hỗ trợ quay video ngắn để đẩy traffic nếu cần.', 'Ngoại hình ưa nhìn, giao tiếp tốt, tự tin trước ống kính, biết cách khuấy động không khí livestream. Có kinh nghiệm livestream bán hàng trang sức bạc là một lợi thế. Giọng nói rõ ràng, biết nắm bắt tâm lý người mua. Yêu thích bán hàng, có tinh thần trách nhiệm, làm việc đúng giờ.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng bán hàng'', ''Kỹ Năng Tương Tác Với Khán Giả'', ''Kỹ Năng Sử Dụng Tiktok'', ''Kỹ Năng Livestream'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Tự tin trước ống kính'', ''Biết cách khuấy động không khí livestream'', ''Yêu thích bán hàng'', ''Có tinh thần trách nhiệm'', ''Làm việc đúng giờ'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.1 - 0.2 triệu', 'Thứ 2 - Chủ nhật (từ 18:00 đến 22:00)', '[''Thu nhập hấp dẫn: 80k-150k/h + 3% hoa hồng'', ''Được hỗ trợ đào tạo kỹ năng livestream chuyên sâu nếu chưa có kinh nghiệm'', ''Môi trường làm việc năng động, đồng nghiệp trẻ trung, nhiều cơ hội phát triển'', ''Cơ hội trở thành KOL/brand ambassador nếu thể hiện tốt'', ''Thưởng nóng theo lượt chốt đơn, KPI hằng tuần/tháng'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (124, 8, 7, 'Nhân Viên Thiết Kế 2D', 'Thiết kế minh họa các đơn hàng theo sản phẩm phục vụ khách hàng xem trước theo mẫu có sẵn. Tham gia sáng tạo, thiết kế theo mô tả, yêu cầu của khách dựa trên các thông số sản phẩm sẵn có. Gửi, sửa thiết kế theo yêu cầu của khách hàng. Giải quyết các vấn đề liên quan tới thiết kế đơn hàng cùng với bộ phận khác. Thực hiện báo cáo và nhiệm vụ khác theo sự phân công của cấp trên.', 'Nam nữ từ 18 tuổi, sức khỏe tốt. Đang học, đang làm liên quan tới thiết kế. Có tư duy, ý tưởng sáng tạo. Sử dụng thành thao các phần mềm chuyên dụng: Photoshop, Illustrator. Sử dụng thành thạo tin học văn phòng. Ưu tiên ứng viên đã từ làm việc liên quan tới thiết kế các sản phẩm quà tặng.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Giải quyết vấn đề'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Thưởng các ngày lễ tết'', ''Phụ cấp phí gửi xe'', ''Cơ hội làm việc gắn bó lâu dài'', ''Du lịch, teambuilding nhiều lần trong năm'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (125, 9, 7, 'Nhân Viên Kinh Doanh', '1. Tìm kiếm & tiếp cận khách hàng tiềm năng. Chủ động tìm kiếm cá nhân, doanh nghiệp, cửa hàng đang có nhu cầu: Thiết kế website chuyên nghiệp (giới thiệu sản phẩm, bán hàng online, dịch vụ…). Dịch vụ SEO từ khóa giúp website tăng thứ hạng Google, tăng lượt truy cập bền vững. Chạy quảng cáo Facebook, Google giúp tiếp cận khách hàng tiềm năng hiệu quả. 2. Giới thiệu dịch vụ. Chia sẻ thông tin về dịch vụ của công ty qua Zalo, Facebook, email, hoặc gặp mặt trực tiếp (nếu có). Giúp khách hàng hiểu được lợi ích khi sử dụng dịch vụ của GPWEBMEDIA. 3. Gửi thông tin khách hàng cho đội ngũ kỹ thuật. Sau khi khách hàng có nhu cầu, bạn chỉ cần: Thu thập họ tên, số điện thoại, mô tả nhu cầu. Gửi lại thông tin cho công ty.', 'Yêu thích công việc kết nối, giới thiệu dịch vụ đến người khác. Có kỹ năng giao tiếp cơ bản, tư duy chủ động và tinh thần cầu tiến. Biết sử dụng Zalo, Facebook hoặc các nền tảng mạng xã hội để tìm kiếm khách hàng. Ưu tiên: Freelancer, sinh viên, nhân viên văn phòng, người đang làm sales/marketing. Có mối quan hệ rộng trong các lĩnh vực thương mại, dịch vụ, doanh nghiệp khởi nghiệp… Không bắt buộc làm việc full-time. Không yêu cầu đến văn phòng – Làm việc từ xa, thời gian linh hoạt.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng đàm phán'', ''Kỹ năng thuyết phục'', ''Kỹ năng quản lý thời gian'', ''Kỹ năng tìm kiếm khách hàng tiềm năng'']
Kỹ năng mềm: [''Tư duy chủ động'', ''Tinh thần cầu tiến'']', 'FREELANCE', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hoa hồng hấp dẫn: 25%/hợp đồng'', ''Thanh toán minh bạch, đúng hẹn'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (126, 10, 7, 'Điều Phối Dự Án Website TMĐT', 'Adore là thương hiệu thời trang nữ hướng đến phong cách nữ tính, tinh tế và có bản sắc. Để đồng bộ hóa định vị thương hiệu mới và nâng cao trải nghiệm số, Adore sẽ thiết kế lại toàn bộ website bán hàng trên nền tảng Haravan. Mục tiêu của dự án: Giao diện mới thẩm mỹ cao, tối ưu trải nghiệm mua sắm trên di động. Tận dụng tối đa khả năng tích hợp của Haravan: kết nối Kiot Việt, CRM, thanh toán, giao vận, chăm sóc khách hàng, tự động hóa. Vận hành trơn tru và có khả năng phát triển bền vững trong tương lai.', 'Từng triển khai hoặc điều phối dự án trên nền tảng Haravan, ưu tiên ngành thời trang, lifestyle. Hiểu sâu về hệ sinh thái và giới hạn kỹ thuật của Haravan (giao diện, theme, tích hợp app, cấu hình…). Có tư duy UX/UI tốt, biết cách kết nối trải nghiệm người dùng với hành vi thực tế. Có khả năng giao tiếp, phối hợp tốt giữa team marketing (sáng tạo) và team kỹ thuật (dev Haravan). Biết kiểm thử cơ bản (UAT), có mắt thẩm mỹ là lợi thế lớn. Ưu tiên ứng viên có kinh nghiệm với hệ thống Kiot Việt hoặc các công cụ CRM, automation liên quan đến Haravan.
Kỹ năng chuyên môn: [''Haravan'', ''UX/UI'', ''CRM'', ''Kiot Việt'']
Kỹ năng mềm: [''Giao tiếp'', ''Phối hợp'', ''Kiểm thử'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thời gian linh hoạt', '[''Mức thù lao hấp dẫn theo kinh nghiệm và vai trò thực tế'', ''Cơ hội xây dựng một nền tảng số chỉn chu'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (127, 2, 7, 'Cộng Tác Viên Phát Tờ Rơi Và Khảo Sát Thị Trường', 'MÔ TẢ CÔNG VIỆC Phát catalogue giới thiệu sản phẩm máy móc thiết bị bếp công nghiệp (nồi nấu phở, máy xay giò chả, máy rửa bát công nghiệp...) tại các nhà hàng, quán ăn, bếp ăn tập thể. Khảo sát và thu thập thông tin khách hàng (data) theo mẫu:Tên quán, địa chỉ, loại hình Người phụ trách/quản lý, số điện thoại/Zalo liên hệ Chụp ảnh minh họa: biển hiệu, người nhận tờ rơi, ảnh check-in Một data hợp lệ cần bao gồm đầy đủ các thông tin sau:Tên quán: Ghi rõ ràng, đầy đủ – không viết tắt. Địa chỉ: Có số nhà, tên phố, phường/xã, quận/huyện cụ thể. Người liên hệ: Là chủ quán hoặc người quản lý có quyền quyết định mua sắm. SĐT hoặc Zalo: Có thể liên hệ và xác minh được (gọi được/sử dụng được). Loại hình quán: Ghi rõ là quán cơm, lẩu, buffet, quán nhậu, quán chay, bếp công nghiệp,... tùy thực tế. Tham gia buổi đào tạo nhanh trước khi bắt đầu. Cập nhật thông tin đầy đủ mỗi ngày tại biểu mẫu Google Sheet chuẩn của công ty.', 'Nam, sinh viên năm 3 – 4; có xe máy cá nhân Giao tiếp tốt, thái độ lịch sự – trung thực – chủ động Biết sử dụng điện thoại có kết nối internet, chụp ảnh rõ nét Có kỹ năng Google Sheet/Drive cơ bản Ưu tiên: yêu thích công việc thị trường, kinh doanh, thực địa
Kỹ năng chuyên môn: [''Kỹ năng Google Sheet/Drive cơ bản'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Thái độ lịch sự'', ''Trung thực'', ''Chủ động'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '0.5 - 10.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 11:00, từ 14:00 đến 17:00)', '[''Xăng xe'', ''Thưởng nóng trong ngày'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (128, 3, 7, 'VJ (VIDEO JOCKEY)-Gương Mặt Đại Diện Truyền Thông', 'Dẫn dắt/ Diễn xuất các chương trình, video clip trên kênh truyền thông của công ty (TikTok, Facebook,...). Tham gia lên ý tưởng nội dung, kịch bản để phát triển kênh. Tương tác với khán giả, tạo xu hướng và lan tỏa nội dung hấp dẫn. Hợp tác với đội ngũ sản xuất để tối ưu chất lượng video (hình ảnh, âm thanh, hiệu ứng,...). Tham gia các sự kiện, livestream của công ty (nếu cần).', 'Ngoại hình ưa nhìn, phong cách trẻ trung, năng động, có cá tính mạnh và khả năng tạo ấn tượng tốt với khán giả. Tính cách hài hước, "quậy", biết cách tạo không khí vui vẻ, gần gũi. Có khả năng diễn xuất, dẫn dắt nội dung lôi cuốn, tự nhiên trước ống kính. Khả năng ứng biến linh hoạt, phản ứng nhanh nhạy trong các tình huống phát sinh. Ưu tiên ứng viên có kinh nghiệm làm VJ, MC, hoặc hoạt động trong lĩnh vực giải trí, truyền thông. Giới tính: Nam, nữ hoặc LGBT. Có khả năng diễn xuất, tự tin trước ống kính. Hiểu biết cơ bản về các nền tảng mạng xã hội (TikTok, Facebook,...).
Kỹ năng chuyên môn: [''Kỹ Năng Dẫn Chương Trình'', ''Kỹ Năng Giao Tiếp Trước Đám Đông'', ''Hiểu Biết Về Truyền Thông'', ''Khả Năng Ứng Biến Linh Hoạt'', ''Kỹ Năng Diễn Xuất Trước Máy Quay'']
Kỹ năng mềm: [''Tính cách hài hước'', ''Khả năng diễn xuất'', ''Khả năng làm việc nhóm hoặc độc lập'', ''Tinh thần học hỏi'', ''Sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 7000000.00, '5.0 - 7.0 triệu', 'Thời gian làm việc linh hoạt không gò bó (1 tuần khoảng 3-4 buổi, mỗi buổi khoảng 3-4 tiếng)', '[''Thưởng theo hiệu suất video (view, engagement)'', ''Cơ hội trở thành gương mặt đại diện thương hiệu'', ''Hỗ trợ phát triển kênh cá nhân'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (129, 7, 7, 'Cộng Tác Viên Sản Xuất Video', 'Quay, dựng video, chụp ảnh, cắt ghép các clip để tạo thành 1 clip hoàn chỉnh. Chỉnh sửa, tạo hiệu ứng để hoàn chỉnh các video, clip theo yêu cầu của tổ chức. Tìm tư liệu và dựng các clip content có sẵn. Sáng tạo các nội dung video mới theo trend và định hướng của tổ chức. Hỗ trợ các công việc khác trong team truyền thông nội bộ.', 'Có kinh nghiệm làm việc ở vị trí Biên tập viên Video hoặc các vị trí tương tự. Thành thạo phần mềm biên tập video Capcut Pro. Hiểu biết sâu về quy trình sản xuất video. Tư duy sáng tạo, chú trọng đến chi tiết. Khả năng làm việc dưới áp lực và hoàn thành công việc đúng thời hạn. Kỹ năng giao tiếp và hợp tác tốt, có kiến thức về Marketing là 1 lợi thế.
Kỹ năng chuyên môn: [''Capcut Pro'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Chú trọng đến chi tiết'', ''Khả năng làm việc dưới áp lực'', ''Kỹ năng giao tiếp'', ''Hợp tác tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 09:00 đến 18:00)', '[''Làm việc trong môi trường trẻ trung, năng động'', ''Được chủ động đề xuất, đóng góp ý kiến xây dựng sản phẩm cùng team'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (130, 8, 7, 'Thực Tập Quản Trị Kinh Doanh(Sale Marketing Admin)', 'Học & thực hành lập kế hoạch sale marketing theo mục tiêu. Học & thực hành triển khai và phân tích hiệu quả kế hoạch sale marketing. Học thực hành phân tích & triển khai Mô hình kinh doanh, Mô hình bán, kênh truyền thông, tập khách hàng mục tiêu, sản phẩm, thị trường, kênh bán, kênh truyền thông. Học thực hành phân tích và phát triển sản phẩm. Học thực hành triển khai chiến dịch sale marketing, chạy facebook ads. Học Thực hành phân tích, lập kế hoạch và triển khai mô hình kinh doanh AFFIATE MLM & đánh giá hiệu quả triển khai các mô hình kinh doanh. Học và thực hành vận dụng AI và Automation Tool biên tập các nội dung marketing và đánh giá hiệu quả tổng kết rút ra các giải pháp tối ưu. Học và thực hành vận dụng AI biên tập tạo các video Clip quảng cáo giới thiệu sản phẩm và truyền thông nhận diện hình ảnh thương hiệu.', 'Sinh viên năm 3 hoặc năm cuối học quản trị kinh doanh & marketing các trường ĐH kinh tế or chuyên ngành BA tại các trường ĐH công nghệ. Có kỹ năng phân tích, tổng hợp, thuyết trình. Có kỹ năng Team Lead or tổ chức hoạt động nhóm, cộng đồng.
Kỹ năng chuyên môn: [''Kỹ năng phân tích'', ''Kỹ năng tổng hợp'', ''Kỹ năng thuyết trình'', ''Kỹ năng Team Lead'', ''Kỹ năng tổ chức hoạt động nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ thực tập 500k/tháng + Hoa hồng tham gia dự án'', ''Định kỳ 3 tháng review năng lực & hỗ trợ'', ''Xác nhận dấu mộc thực tập'', ''Thực tập 6 tháng được ưu tiên xét tuyển dụng nhân viên chính thức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (131, 9, 7, 'Thực Tập Viên Content Creator & Livestream', 'Thực hiện chính các hoạt động Livestream, sáng tạo Content, video ngắn trên Tiktok, Reel. Tham gia hoạt động Livestream trên các kênh bán hàng: Tiktok, Facebook, Shopee... Sản xuất nội dung trên các kênh Social Media như: Facebook, Tiktok, Zalo, Youtube, Website. Hoạt động Booking: Kết nối, làm việc với influencer, KOLs, KOCs... cho các chiến dịch cụ thể từ team. Tìm kiếm, kết nối với cá nhân và tổ chức thứ 3, quảng bá sản phẩm/ dịch vụ cho doanh nghiệp để đổi lấy phí hoa hồng từ mỗi lần bán hàng. Tham gia các hoạt động phát triển website. Tối ưu hoá từ khoá, phát triển nội dung chuẩn SEO. Hỗ trợ các bộ phận khác khi cần. Thực hiện các công việc liên quan khác do trưởng bộ phận sắp xếp.', 'Tốt nghiệp Cao đẳng / Đại học các khối ngành về Kinh tế, Thương mại điện tử, QTKD, Marketing. Có khả năng trong công việc lên ý tưởng, sản xuất nội dung video ngắn và livestream ở các công ty TMĐT. Có kiến thức tổng quan về Digital Marketing. Biết sử dụng cơ bản các phần mềm thiết kế như AI, Photoshop hoặc Canva, Capcut, Premiere là một lợi thế. Sử dụng thành thạo Excel, Nhạy bén với số liệu. Có kỹ năng làm việc độc lập, chủ động. Năng lực sáng tạo, hoạch định và triển khai kế hoạch. Trẻ trung, năng động, nhạy bén với các xu hướng mới. Có laptop cá nhân. Mong muốn học hỏi, thăng tiến trong công việc. Thái độ tốt, nhanh nhạy trong giao tiếp, công việc.
Kỹ năng chuyên môn: [''AI'', ''Photoshop'', ''Canva'', ''Capcut'', ''Premiere'', ''Excel'']
Kỹ năng mềm: [''Làm việc độc lập'', ''Chủ động'', ''Sáng tạo'', ''Hoạch định'', ''Triển khai kế hoạch'', ''Giao tiếp'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Hỗ trợ thực tập 2.000.000 đồng/tháng'', ''Lương KPI dựa trên hiệu quả công việc'', ''Chính sách lương thưởng, nghỉ lễ theo quy định của nhà nước'', ''Khóa học nâng cao chuyên môn do công ty tài trợ'', ''Trải nghiệm môi trường làm việc'', ''Chính sách mua hàng nội bộ hấp dẫn'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (132, 10, 7, 'Thực Tập Sinh Video Editor', 'Dựng, chỉnh sửa, cắt ghép video ngắn cho nền tảng TikTok, YouTube Shorts, Facebook Reels,... Phối hợp với Team Content/Design để hiện thực hóa ý tưởng video. Quay phim cơ bản nếu cần.', 'Ứng viên vui lòng gửi kèm portfolio (nếu có). Có laptop cá nhân. Biết sử dụng các phần mềm (Capcut/Premiere/...) cơ bản. Biết After Effects là một lợi thế.
Kỹ năng chuyên môn: [''Capcut'', ''Premiere'', ''After Effects'']
Kỹ năng mềm: [''Tư duy tốt về hình ảnh'', ''Góc quay'', ''Bố cục sáng tạo'', ''Nắm bắt trend nhanh'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Ăn trưa miễn phí tại bếp công ty'', ''Môi trường làm việc thân thiện, năng động và vui vẻ'', ''Hỗ trợ chứng nhận (dấu mộc) thực tập'', ''Cơ hội được tuyển dụng vào các vị trí chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (133, 2, 7, 'Nhân Viên Bán Hàng Tại Cửa Hàng', '- Tư vấn bán hàng điện thoại, máy tính bảng, phụ kiện công nghệ cho Khách Hàng. - Trực tiếp giải đáp thắc mắc, hướng dẫn khách hàng sử dụng sản phẩm và dịch vụ.', 'Nam / Nữ - Tuổi từ 18-26 tuổi Năng động, chăm chỉ và luôn cầu tiến Giao tiếp tự tin lưu loát. Ưu tiên ứng viên có kinh nghiệm. Tốt nghiệp từ Trung cấp.
Kỹ năng mềm: [''Năng động'', ''Chăm chỉ'', ''Giao tiếp tự tin lưu loát'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 12000000.00, '6.0 - 12.0 triệu', 'Thời gian làm việc theo ca linh động: ngày 8 tiếng (Có thể xoay ca)', '[''Mỗi tháng được nghỉ 2 ngày và 12 ngày phép trong năm'', ''Môi trường làm việc chuyên nghiệp, năng động, thân thiện'', ''Được ký hợp đồng làm việc lâu dài và ổn định'', ''Cơ hội thăng tiến trở thành trưởng nhóm'', ''Thưởng theo doanh số, thưởng theo các ngày lễ, thưởng cuối năm hấp dẫn'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (134, 3, 7, 'Thiết kế đồ họa bán thời gian', 'Thiết kế các ấn phẩm cho các kênh online và offline theo Account/content. Các ấn phẩm thiết kế trên kênh online: Facebook, Website. Các ấn phẩm offline: Voucher, Brochure, Standee, banner, poster. Thực hiện các yêu cầu khác theo yêu cầu của trưởng bộ phận.', 'Tinh thần chủ động tốt, khả năng giao tiếp và làm việc nhóm tốt. Có trách nhiệm cao trong công việc, tuân thủ đúng deadline. Thành thạo các công cụ thiết kế: AI, PTS,... Ưu tiên các bạn đã có kinh nghiệm.
Kỹ năng chuyên môn: [''AI'', ''Photoshop'']
Kỹ năng mềm: [''Tinh thần chủ động'', ''Khả năng giao tiếp'', ''Làm việc nhóm'', ''Trách nhiệm cao'', ''Tuân thủ deadline'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được đào tạo và hỗ trợ làm việc về mặt thiết kế'', ''Có cơ hội chuyển làm nhân viên chính thức'', ''Làm việc trong môi trường trẻ, năng động'', ''Hỗ trợ tiền vé xe'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (135, 7, 7, 'Thực Tập Sinh Báo Chí', '– Thực hiện các tác phẩm báo chí, truyền thông về lĩnh vực y tế - sức khỏe cho website, fanpage và các nền tảng truyền thông. – Tham gia trực tiếp tác nghiệp tại các hội thảo, hội nghị về lĩnh vực y tế - sức khỏe. – Hỗ trợ tổ chức các sự kiện, hội thảo chuyên ngành về y dược và sức khỏe (nếu có). – Thực hiện đề tài báo chí về lĩnh vực y tế - sức khỏe từ các trang báo nước ngoài. – Biên tập trang tin điện tử. – Thực hiện sản phẩm mạng xã hội (TikTok, Youtube, Spotify, Facebook) về lĩnh vực y tế - sức khỏe. – Hỗ trợ chiến dịch quảng cáo trên mạng xã hội (nếu có). – Hỗ trợ quản lý các kênh social, tương tác với độc giả và theo dõi hiệu quả bài đăng. – Thực hiện các công việc nghiên cứu thị trường, thu thập dữ liệu để đề xuất ý tưởng marketing. – Nghiên cứu xu hướng social media trong lĩnh vực y tế, chăm sóc sức khỏe để cập nhật nội dung phù hợp. – Phối hợp với các phòng ban để đảm bảo chiến dịch truyền thông hiệu quả. – Thực hiện các công việc phù hợp khác khi được phân công.', '– Sinh viên năm 3 - 4 đại học chuyên ngành báo chí, truyền thông, marketing. – Sử dụng thành thạo tin học văn phòng. – Giao tiếp, đọc, hiểu tiếng Anh căn bản. – Hiểu biết về thiết kế, SEO, Google Ads là một lợi thế. – Ưu tiên: Người có kiến thức và từng thực hiện các sản phẩm mạng xã hội (tiktok, youtube...), người có kinh nghiệm tác nghiệp thực tế (phỏng vấn, lấy tin…)
Kỹ năng chuyên môn: [''Sử dụng thành thạo tin học văn phòng'', ''Hiểu biết về thiết kế'', ''SEO'', ''Google Ads'']
Kỹ năng mềm: [''Giao tiếp'', ''Đọc'', ''Hiểu tiếng Anh căn bản'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 07:30 đến 16:30), Thứ 7 (từ 07:30 đến 11:30)', '[''Trợ cấp thực tập: Thỏa thuận'', ''Được xác nhận báo cáo thực tập cuối kỳ'', ''Được huấn luyện các kỹ năng báo chí – truyền thông'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (136, 8, 7, 'TTS Dự Án Truyền Thông (Mạnh Về Dựng Video)', 'Tham gia quay phim, ghi hình, đi sản xuất cho các dự án truyền thông của công ty. Thực hiện dựng video cơ bản: cắt ghép, chỉnh màu, chèn nhạc, hiệu ứng đơn giản trên các phần mềm dựng (Premiere, Capcut, After Effect v.v.). Hỗ trợ biên tập nội dung video (kịch bản, lời dẫn, line-up hình ảnh,...). Tham gia brainstorm ý tưởng nội dung phù hợp với đối tượng khán giả.', 'Sinh viên năm 3, 4 hoặc mới tốt nghiệp các chuyên ngành: Báo chí, Truyền thông, Sản xuất nội dung, Điện ảnh – Truyền hình, Công nghệ truyền thông. Có khả năng quay phim bằng điện thoại hoặc máy ảnh cơ bản, nắm được các nguyên tắc bố cục hình ảnh, ánh sáng, âm thanh. Biết sử dụng cơ bản các phần mềm dựng video như Adobe Premiere, Capcut,... Có tư duy hình ảnh tốt, tư duy thẩm mỹ và cập nhật các nội dung xu hướng nhanh. Có thể biên tập nội dung là một lợi thế. Chủ động, có trách nhiệm, có khả năng làm việc nhóm tốt.
Kỹ năng chuyên môn: [''Adobe Premiere'', ''Capcut'']
Kỹ năng mềm: [''Chủ động'', ''Có trách nhiệm'', ''Có khả năng làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ dấu thực tập và tài liệu làm khóa luận'', ''Được đào tạo bài bản bởi đội ngũ sản xuất chuyên nghiệp'', ''Được đi du lịch nhiều nơi, có trải nghiệm thực tế tại nhiều tỉnh thành trên cả nước'', ''Được tham gia miễn phí rất nhiều khóa học về chuyển đổi số, AI, MKT, Kinh doanh'', ''Cơ hội trở thành nhân viên chính thức nếu đạt kết quả tốt'', ''Môi trường làm việc trẻ trung, năng động, sáng tạo'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (137, 9, 7, 'Thực Tập Sinh Video Editor', 'Thiết kế, cắt ghép các hiệu ứng cho video. Chỉnh sửa video theo yêu cầu. Phối hợp với team để phát triển sự hiện diện của công ty trên các cộng đồng xã hội, diễn đàn.', 'Có laptop cá nhân. Chăm chỉ, cầu tiến, có khả năng làm việc độc lập và phối hợp tốt với nhóm. Sử dụng thành thạo ít nhất một trong các phần mềm chỉnh sửa video phổ biến (Adobe Premiere, After Effects, Final Cut Pro, Capcut...). Có kiến thức cơ bản về nguyên tắc quay phim, dựng phim, thiết kế.
Kỹ năng chuyên môn: [''Adobe Premiere'', ''After Effects'', ''Final Cut Pro'', ''Capcut'']
Kỹ năng mềm: [''Chăm chỉ'', ''Cầu tiến'', ''Có khả năng làm việc độc lập'', ''Phối hợp tốt với nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Hỗ trợ 3tr/tháng + thưởng'', ''Hỗ trợ đóng dấu chứng nhận thực tập'', ''Cơ hội thăng tiến rõ ràng theo lộ trình'', ''Hỗ trợ lịch làm việc linh hoạt cho những bạn còn lịch học ít tại trường.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (138, 10, 7, 'Nhân Viên Marketing Xuất Nhập Khẩu Part-Time', 'Thực hiện, hỗ trợ các công việc sau: Tiến hành lập kế hoạch viết content chuyên nghiệp để đạt được khách hàng mục tiêu, chào hàng trên các trang thương mại điện tử Facebook, Alibaba, LinkedIn; B2B. Tư vấn khách hàng trong nước và khách nước ngoài; xây dựng và triển khai công tác chăm sóc khách hàng, tư vấn các dịch vụ, giới thiệu các mặt hàng của công ty và chào bán, lập báo giá. Gửi thông tin khách hàng cho phòng kinh doanh. Các công việc khác theo yêu cầu của quản lý.', 'Trình độ học vấn: Sinh viên năm 2, 3, 4 của các trường Đại học chuyên ngành kinh tế, xuất khẩu, logistics,... Tiếng Anh giao tiếp cơ bản. Không yêu cầu kinh nghiệm. Có kỹ năng giao tiếp, đàm phán và tinh thần làm việc nhóm tốt, nhanh nhẹn hoạt bát trong công việc. Có kiến thức cơ bản về bán hàng, xuất nhập khẩu. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng đàm phán'', ''Kiến thức cơ bản về bán hàng'', ''Kiến thức về xuất nhập khẩu'']
Kỹ năng mềm: [''Tinh thần làm việc nhóm'', ''Nhanh nhẹn'', ''Hoạt bát'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Lương cứng: 25.000đ/1 giờ'', ''Thưởng doanh thu'', ''Thưởng lễ'', ''Được đào tạo bài bản về TMĐT'', ''Xét duyệt theo năng lực làm việc từ 2-3 tháng đề xuất làm nhân viên chính thức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (139, 2, 7, 'Thực Tập Trợ Lý Trưởng Bộ Phận Chăm Sóc Khách Hàng', 'Trợ lý cho trưởng bộ phận chăm sóc khách hàng trong các hoạt động phát triển, thu hút khách hàng, hỗ trợ khách hàng sau mua. Hỗ trợ quản lý, giám sát, thúc đẩy nhân viên làm việc. Đảm bảo công việc của bộ phận hoạt động xuyên suốt. Đóng góp ý tưởng để cải thiện phát triển. Thời gian thực tập: 6 tháng. Công ty chỉ tuyển ứng viên đi thực tập lấy kinh nghiệm, để được đào tạo chuyên ngành và ở lại làm việc lâu dài cho công ty.', 'Không yêu cầu kinh nghiệm. Có laptop cá nhân. Chấp nhận sinh viên 1, 2, 3, 4. Có giọng nói dễ nghe, rõ ràng, giao tiếp tốt. Khả năng giải quyết vấn đề và xử lý tình huống tốt. Có kỹ năng giao tiếp, lắng nghe và thấu hiểu khách hàng. Trung thực, nhiệt tình, có trách nhiệm trong công việc. Khả năng làm việc độc lập và làm việc nhóm hiệu quả. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). Tốt nghiệp trung cấp trở lên, không phân biệt chuyên ngành.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Khả năng giải quyết vấn đề'', ''Kỹ năng lắng nghe'', ''Trung thực'', ''Nhiệt tình'', ''Có trách nhiệm trong công việc'', ''Khả năng làm việc độc lập'', ''Làm việc nhóm hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca sáng từ 8 - 12h, Ca chiều từ 13h30 - 17h30, Ca tối từ 18h30 - 21h', '[''Cấp chứng chỉ thực tập'', ''Môi trường làm việc năng động, trẻ trung'', ''Có quyền tự chủ trong công việc'', ''Đào tạo nhân viên theo ISO 9001'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (140, 3, 7, 'Nhân Viên Xây Dựng Mô Hình Chuỗi Kinh Doanh', 'Lĩnh vực: Mô hình Chuỗi – Nhượng quyền Máy rửa bát công nghiệp. Làm việc tại Hà Nội hoặc TP. HCM hoặc làm online từ xa, không cần đến văn phòng. Có thể đi công tác toàn quốc để triển khai điểm nhượng quyền. Nghiên cứu, thiết kế và triển khai mô hình kinh doanh nhượng quyền hoặc chuỗi điểm rửa bát công nghiệp. Chuẩn hóa toàn bộ quy trình, công cụ và bộ tài liệu liên quan. Hỗ trợ tìm kiếm, đào tạo và triển khai mô hình cho các đối tác nhượng quyền.', 'Tốt nghiệp Đại học các ngành: Quản trị kinh doanh, Kinh tế, Kỹ thuật hệ thống, Chuỗi cung ứng, F&B… Có kinh nghiệm 1–3 năm làm trong các lĩnh vực: xây dựng mô hình kinh doanh, triển khai chuỗi, nhượng quyền, hoặc vận hành F&B. Am hiểu mô hình kinh doanh nhượng quyền, biết xây dựng quy trình, bộ tiêu chuẩn hóa. Khả năng tư duy hệ thống, lập kế hoạch, viết tài liệu tốt. Giao tiếp và phối hợp tốt giữa các phòng ban và đối tác bên ngoài. Sẵn sàng đi công tác các tỉnh để khảo sát và triển khai điểm rửa.
Kỹ năng chuyên môn: [''Xây dựng mô hình kinh doanh'', ''Triển khai chuỗi'', ''Nhượng quyền'', ''Vận hành F&B'']
Kỹ năng mềm: [''Khả năng tư duy hệ thống'', ''Lập kế hoạch'', ''Viết tài liệu'', ''Giao tiếp'', ''Phối hợp'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 15000000.00, '10.0 - 15.0 triệu', 'Làm online từ xa không gò bó thời gian', '[''Bảo hiểm xã hội'', ''Thưởng hiệu quả làm việc'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (141, 7, 7, 'Nhân Viên Livestream Parttime', '● Livestream bán các sản phẩm của công ty trên nền tảng Tik Tok Shop. ● Xây dựng kịch bản livestream, sáng tạo các concept livestream mới lạ, độc đáo. ● Đưa ra các điều chỉnh hàng tuần về nội dung livestream dựa trên các chỉ số hiệu quả. ● Cộng tác sát sao với đội chạy quảng cáo để tối ưu hiệu quả livestream từ nội dung trên video quảng cáo tới nội dung trong livestream. ● Tham gia vào việc làm diễn viên trong một số video xây kênh hoặc thông báo sale. ● Sẵn sàng tiếp nhận một số công việc quản lý các mẫu live parttime.', '● Đã có kinh nghiệm livestream từ 6 tháng trở lên. ● Khả năng giao tiếp hiệu quả ● Khả năng thuyết phục khách mua hàng tốt, hiểu sâu về tâm lý khách hàng. ● Linh hoạt trong các trường hợp bất ngờ: xử lý feedback tiêu cực, sự cố kỹ thuật, ● Giọng nói rõ ràng, có nội lực, không nói giọng địa phương, không bị ngọng. ● Sáng tạo, học hỏi nhanh từ thị trường, đối thủ.
Kỹ năng chuyên môn: [''Bán Hàng'', ''Livestream'', ''Xây Dựng Kịch Bản'']
Kỹ năng mềm: [''Khả năng giao tiếp hiệu quả'', ''Khả năng thuyết phục khách mua hàng'', ''Linh hoạt trong các trường hợp bất ngờ'', ''Sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 12000000.00, '10.0 - 12.0 triệu', 'Thứ 2 - Thứ 7 (từ 18:00 đến 00:00)', '[''Được đẩy Ads trong các phiên live'', ''Được đào tạo để trở thành Quản lý mẫu livestream'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (142, 8, 7, 'Thực Tập Sinh Phát Triển Kinh Doanh', 'Tìm kiếm và xây dựng danh sách khách hàng tiềm năng trong lĩnh vực doanh nghiệp SME, thực hiện chăm sóc khách hàng qua các kênh mail, điện thoại, Linkedin, nghiên cứu và phân tích thị trường, hỗ trợ thực hiện các chiến dịch kinh doanh, phối hợp với bộ phận Marketing và Tư vấn.', 'Ưu tiên năm cuối hoặc đang chờ bằng Đại học Khối ngành kinh tế, kế toán, nhân sự, quản trị kinh doanh. Hiểu cơ bản về quy trình bán hàng B2B, có kiến thức nền về quản trị doanh nghiệp, am hiểu cơ bản về thị trường doanh nghiệp SME tại Việt Nam.
Kỹ năng chuyên môn: [''Kỹ năng tìm kiếm thông tin'', ''Sử dụng Google Sheets'', ''Sử dụng Excel'', ''Sử dụng CRM'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'', ''Tư duy logic'', ''Chủ động'', ''Nhanh nhẹn'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được đào tạo trực tiếp từ đội ngũ chuyên gia tư vấn có kinh nghiệm >10 năm trong ngành'', ''Môi trường làm việc chuyên nghiệp'', ''Cơ hội tham gia các buổi coaching kỹ năng chuyên sâu'', ''Cơ hội trở thành nhân viên chính thức sau thời gian thực tập'', ''Phụ cấp thực tập và hoa hồng theo KPI'', ''Ăn trưa'', ''Cước điện thoại'', ''Thưởng hiệu quả làm việc'', ''Thưởng tháng 13'', ''Du lịch hàng năm'', ''Signing bonus'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (143, 9, 7, 'Nhân Viên Editor - Part-Time', 'Dựng video/short/reels đăng trên các nền tảng Tiktok, Facebook, Youtube theo kịch bản và yêu cầu. Tiếp nhận ý kiến phản hồi/feedback từ team nội dung và VJ,KOL để chỉnh sửa, hoàn thiện sản phẩm chất lượng. Làm việc partime tại công ty và kết hợp Online tại nhà.', 'Có khả năng dựng video tốt bằng các phần mềm chuyên dụng như: Premiere, Capcut, FinalCut,.... Editor yêu thích/Đam mê hoặc có kinh nghiệm làm việc trong công nghệ, điện thoại smartphone, laptop,.... và ứng dụng công nghệ, sản xuất nội dung. Có tư duy tốt về dựng video, khiếu hài hước, khả năng vận dụng hiệu ứng hình ảnh và âm thanh phù hợp trong những cảnh quay, mạnh về xử lý màu sắc là một lợi thế. Có tinh thần trách nhiệm cao, kỹ năng làm việc nhóm tốt. Cẩn thận , tỉ mỉ, sáng tạo, cầu tiến. Làm việc online kết hợp lên part-time tại công ty 4-5 buổi/tuần, trả video hoàn thiện trong ngày để team Nội dung đăng tải.
Kỹ năng chuyên môn: [''Premiere'', ''Capcut'', ''FinalCut'']
Kỹ năng mềm: [''Tinh thần trách nhiệm cao'', ''Kỹ năng làm việc nhóm'', ''Cẩn thận'', ''Tỉ mỉ'', ''Sáng tạo'', ''Cầu tiến'']', 'PART_TIME', 'REMOTE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '5.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:45 đến 17:45)', '[''Mức lương hấp dẫn theo năng lực'', ''Thưởng video viral'', ''Môi trường làm việc thân thiện, trẻ trung, năng động và chuyên nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (144, 10, 7, 'Thực Tập Thiết Kế Đồ Họa 2D', 'Thiết kế các banner Social, Thiết kế bộ nhận diện thương hiệu, Hỗ trợ thiết kế cho team video.', 'Sử dụng thành thạo photoshop, illustrator, canva. Nắm vững các tiêu chuẩn thẩm mỹ phối màu, bố cục, văn bản, tỷ lệ, khoảng thở... trong thiết kế. Sử dụng các công cụ AI là một lợi thế.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Canva'']
Kỹ năng mềm: [''Chủ động học hỏi'', ''Cập nhật xu hướng thiết kế'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Đóng dấu xác nhận thực tập'', ''Thực tập trên dự án thực tế'', ''Đào tạo nâng cao chuyên môn'', ''Làm việc trong môi trường thân thiện, chuyên nghiệp'', ''Du lịch, team building hàng năm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (145, 2, 7, 'Thực Tập Sinh Marketing', 'Tham gia xây dựng nội dung truyền thông và quản lý tối ưu các nền tảng: Facebook, TikTok... Hỗ trợ lên kế hoạch và triển khai các hoạt động marketing. Chụp hình, quay video, chỉnh sửa nội dung media liên quan đến dự án. Phối hợp cùng team để lên kế hoạch quảng bá hình ảnh công ty.', 'Ưu tiên sinh viên các ngành Marketing, Truyền thông, Báo chí, Kinh tế… hoặc chỉ cần chăm chỉ và đam mê sáng tạo. Năng động, có khả năng quay, chụp tốt. Biết cơ bản về thiết kế Canva, CapCut, hoặc phần mềm chỉnh sửa ảnh/video là lợi thế. Chăm chỉ, chịu khó học hỏi, có tinh thần làm việc nhóm.
Kỹ năng chuyên môn: [''Canva'', ''CapCut'']
Kỹ năng mềm: [''Năng động'', ''Chăm chỉ'', ''Chịu khó học hỏi'', ''Làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Được đào tạo bài bản từ đội ngũ chuyên nghiệp trong ngành bất động sản'', ''Được trải nghiệm thực tế và thực hành trong môi trường ngành BĐS'', ''Hỗ trợ dấu mộc báo cáo thực tập cho sinh viên'', ''Có hoa hồng nếu phát sinh giao dịch trong thời gian thực tập'', ''Làm việc trong môi trường thoải mái, không KPI, có cơ hội mở rộng mối quan hệ'', ''Linh hoạt thời gian học tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (146, 3, 7, 'SEO Executive', 'Xây dựng và triển khai chiến lược SEO toàn diện cho website công ty. Phân tích thị trường, đối thủ, từ đó đề xuất hướng đi tối ưu. Lên KPI SEO hàng tháng, quý và theo dõi tiến độ thực hiện. Báo cáo hiệu quả SEO cho trưởng bộ phận và ban giám đốc.', 'Kinh nghiệm trong lĩnh vực SEO. Hiểu rõ cách xây dựng chiến lược dài hạn, định hướng nội dung và backlink. Có tư duy phân tích dữ liệu, sử dụng thành thạo Google Analytics. Giao tiếp tốt, phối hợp hiệu quả với team nội dung, kỹ thuật, PR.
Kỹ năng chuyên môn: [''Seo On Page'', ''Seo Off Page'', ''Viết Nội Dung Seo'', ''Phân Tích Từ Khóa'', ''Tối Ưu Hóa Công Cụ Tìm Kiếm'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Phối hợp hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Mỗi nhân viên được quyền tự quyết hầu hết các đầu việc'', ''Bạn có toàn quyền lựa chọn cách thức triển khai, miễn là cam kết kết quả'', ''Đội ngũ leader đóng vai trò hỗ trợ'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (147, 7, 7, 'Local SEO Specialist', 'Quản lý Google Business Profile và tối ưu hóa cho kết quả tìm kiếm địa phương. Tăng cường hiển thị của doanh nghiệp trong Google Maps, local pack. Đánh giá và thu thập review khách hàng để tăng trust. Theo dõi và cải thiện thứ hạng từ khóa khu vực.', 'Am hiểu mô hình SEO Local, có kinh nghiệm với các công cụ như Whitespark, Moz Local. Biết cách xây dựng trích dẫn (NAP consistency) và tối ưu schema markup. Có kiến thức về trải nghiệm người dùng trên di động. Ưu tiên ứng viên từng làm việc với doanh nghiệp dịch vụ địa phương.
Kỹ năng chuyên môn: [''Nghiên Cứu Từ Khóa'', ''Phân Tích Dữ Liệu'', ''Seo Tối Ưu Hóa Công Cụ Tìm Kiếm Cục Bộ'', ''Google My Business'', ''Xây Dựng Liên Kết Cục Bộ'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Không ép làm ngoài giờ'', ''Khuyến khích nghỉ ngơi đúng lúc'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (148, 8, 7, 'Chuyên gia Backlink SEO', 'Nghiên cứu và triển khai chiến dịch xây dựng backlink chất lượng cao. Làm việc với blogger, báo chí, diễn đàn để đặt liên kết hiệu quả. Kiểm soát backlink độc hại, từ chối link spam qua Google Disavow Tool. Theo dõi domain authority, trust flow, link profile định kỳ.', 'Hiểu biết sâu về hệ thống backlink, anchor text, và PBN (nếu có). Có kinh nghiệm triển khai chiến dịch link building thủ công, không spam. Tư duy sáng tạo để tìm nguồn backlink mới và hợp lệ. Kỹ năng thương lượng, giao tiếp tốt.
Kỹ năng chuyên môn: [''Kiến Thức Về Seo On Page'', ''Kiến Thức Về Seo Off Page'', ''Xây Dựng Chiến Lược Backlink'', ''Phân Tích Backlink'', ''Tìm Kiếm Và Đánh Giá Website Chất Lượng Cao'', ''Viết Nội Dung Chất Lượng Cao (anchor Text)'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Kỹ năng thương lượng'', ''Giao tiếp tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Cung cấp dấu mộc xác nhận thực tập theo đúng yêu cầu của trường'', ''Hướng dẫn tận tình, có người đồng hành chuyên môn trong suốt quá trình thực tập'', ''Cơ hội được giữ lại làm việc chính thức nếu thể hiện tốt'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (149, 9, 7, 'Nhà phân tích SEO Data & Performance', 'Khai thác dữ liệu hành vi người dùng trên website để xác định điểm mạnh/yếu trong hành trình truy cập. Theo dõi và báo cáo hiệu quả SEO thông qua các chỉ số như tỷ lệ click (CTR), tỷ lệ thoát trang (bounce rate), thời gian trung bình trên trang,... Phân tích hiệu suất từ khóa theo từng nhóm nội dung, từng giai đoạn SEO. Xây dựng hệ thống dashboard trực quan, hỗ trợ ra quyết định cho team SEO/Content.', 'Thành thạo xử lý số liệu với Google Sheets/Excel nâng cao, biết sử dụng hàm nâng cao, hàm động. Có kinh nghiệm với Google Analytics (GA4), Search Console, Google Looker Studio (Data Studio). Tư duy logic, phân tích tốt, có khả năng phát hiện mẫu hình (pattern) ẩn trong dữ liệu. Biết triển khai A/B testing đơn giản và hiểu yếu tố UX ảnh hưởng đến SEO ra sao. Ưu tiên: ứng viên có kinh nghiệm phân tích hiệu quả chuyển đổi từ organic traffic.
Kỹ năng chuyên môn: [''Google Sheets'', ''Excel nâng cao'', ''Google Analytics (GA4)'', ''Search Console'', ''Google Looker Studio (Data Studio)'']
Kỹ năng mềm: [''Tư duy logic'', ''Phân tích tốt'', ''Khả năng phát hiện mẫu hình (pattern) ẩn trong dữ liệu'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Môi trường làm việc năng động, sáng tạo'', ''Hỗ trợ đóng dấu đỏ thực tập'', ''Cơ hội thử sức nhiều mảng khác nhau để phát triển đa kỹ năng'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (150, 10, 7, 'Thực Tập Sinh Nhân Sự', 'Tuyển dụng - Xây dựng quảng cáo công việc, ứng cử viên màn hình, poster thiết kế. Hỗ trợ các hoạt động và sự kiện. Hỗ trợ trên tàu với bộ khởi động mới trên tàu. Hoạt động của khách sạn - Tìm hiểu tất cả về hoạt động của một khách sạn làm việc. Thực hiện các công việc liên quan khác theo yêu cầu.', 'Good Excel, Word, PPT. English & Communication Skills. Design. MC Skills. Job Requirements: Discuss during interview. Working 5 day(s) per week, 9.5 hours/day. Commit to work for 3-6 months fulltime internship.
Kỹ năng chuyên môn: [''Microsoft Office (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Giao tiếp'', ''Kỹ năng tổ chức'']', 'INTERNSHIP', 'ONSITE', 'cần thơ', 'Cần Thơ', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Internship in a professional environment - 5-star international standard'', ''On the job training from basic to advanced'', ''Working with colleagues with many years of experience'', ''Internship allowance: 1,000,000 VND/ month'', ''Provided 01 meal/ working shift'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (151, 2, 7, 'SEO & Content Planner', 'Xây dựng kế hoạch nội dung dài hạn dựa trên chiến lược SEO. Kết hợp content marketing với SEO để tạo traffic bền vững. Quản lý lịch đăng bài, đo lường hiệu quả từng nhóm bài. Phối hợp với team social và performance để đồng bộ nội dung.', 'Có kinh nghiệm lập kế hoạch nội dung SEO. Khả năng tổ chức, sắp xếp công việc tốt, tư duy tổng thể. Biết phân nhóm từ khóa, tạo content cluster. Am hiểu hành vi người dùng và định hướng trải nghiệm nội dung.
Kỹ năng chuyên môn: [''Viết Nội Dung'', ''Nghiên Cứu Từ Khóa'', ''Phân Tích SEO'', ''Hiểu Biết Về SEO On Page Và Off Page'', ''Lập Kế Hoạch Nội Dung'']
Kỹ năng mềm: [''Khả năng tổ chức'', ''Sắp xếp công việc tốt'', ''Tư duy tổng thể'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Hỗ trợ đóng dấu đỏ thực tập'', ''Môi trường làm việc linh hoạt, trẻ trung'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (152, 3, 7, 'Thực Tập Sinh Biên Tập Viên Âm Nhạc', 'Thiết kế và edit video Facebook, Reels theo yêu cầu từng chủ đề âm nhạc. Lên ý tưởng và kế hoạch đăng bài trên các nền tảng. Biết viết content. Bắt trend âm nhạc theo xu hướng. Hỗ trợ các công việc truyền thông liên quan.', 'Các bạn sinh viên năm cuối, năng động, nhanh nhạy, tư duy sáng tạo, chủ động trong công việc, yêu thích mạng xã hội. Có gu âm nhạc và cảm thụ tốt (mọi thể loại càng tốt!). Ưu tiên biết thiết kế cơ bản và sử dụng công cụ Capcut hoặc Premiere/Canva. Có kinh nghiệm viết content trên mạng xã hội. Có thể thực tập 3 tháng full-time.
Kỹ năng chuyên môn: [''Thiết kế video'', ''Sử dụng Capcut'', ''Sử dụng Premiere'', ''Sử dụng Canva'']
Kỹ năng mềm: [''Năng động'', ''Nhanh nhạy'', ''Tư duy sáng tạo'', ''Chủ động trong công việc'', ''Yêu thích mạng xã hội'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Từ T2 - T6 (9h - 18h) & T7 (9h - 13h)', '[''Trợ cấp thực tập 1.000.000 VNĐ/tháng'', ''Môi trường làm việc trẻ'', ''Cơ hội học hỏi'', ''Xác nhận thực tập'', ''Cơ hội trở thành cộng tác viên chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (153, 7, 7, 'Nhân Viên Sales Tư Vấn Chụp Ảnh Kỷ Yếu', '- Tiếp cận, tư vấn khách hàng về các thông tin gói chụp ảnh Kỷ yếu - Chốt đơn hàng và tiến hành ký kết hợp đồng - Phối hợp với các bộ phận (điều phối, hậu cần, kế toán, hậu kỳ, ...) để hoàn thanh hợp đồng - Chăm sóc khách hàng trước, trong và sau khi ký kết hợp đồng', '- Ưu tiên sinh viên năm nhất và năm 2 trở lên - Yêu thích công việc kinh doanh, đam mê kiếm tiền - Nhanh nhẹn, chăm chỉ, nhiệt tình, ham học hỏi - Có laptop cá nhân - Làm việc tại VP 214 Nguyễn Xiển, Thanh Liệt, Hà Nội
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chăm chỉ'', ''Nhiệt tình'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 30000000.00, '7.0 - 30.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00), Thứ 7 (từ 08:00 đến 17:00)', '[''Thu nhập cạnh tranh (LC + KPI + Thưởng)'', ''Xoay ca parttime việc linh hoạt'', ''Được hướng dẫn cầm tay chỉ việc các kiến thức, kỹ năng chuyên môn, kỹ năng bán hàng'', ''Môi trường GenZ thoải mái, hòa đồng, vui vẻ và cùng nhau phát triển'', ''Tham gia các hoạt động ăn chơi, kết nối trong toàn công ty'', ''Team building'', ''Du lịch hàng năm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (154, 8, 7, 'Thực Tập Sinh Video Editor', 'Lên ý tưởng, dựng, cắt ghép và chỉnh sửa video và các clip ngắn, clip quảng cáo, clip Viral, video giới thiệu sản phẩm, mô tả sản phẩm; Dựng video animation, motion graphic theo yêu cầu; Phối hợp với Bộ phận liên quan sáng tạo các nội dung cho các sản phẩm, dự án về Truyền thông, Marketing; Tham gia xây dựng, biên soạn nội dung và lên ý tưởng cho chiến lược nội dung của công ty và khách hàng; Quản lý, giám sát hiệu quả truyền thông của video; Hỗ trợ các công việc khác theo sự phân công của Leader.', 'Sinh viên năm 3 hoặc năm 4 có đam mê với lĩnh vực Marketing, Truyền thông, Quảng cáo, Quay phim truyền hình,...; Sử dụng tốt các phần mềm biên tập, chỉnh sửa ảnh và video như Photoshop, Illustrator, After Effect, Premiere, Capcut và các phần mềm hỗ trợ có liên quan; Không yêu cầu kinh nghiệm, được đào tạo từ đầu; Có gu thẩm mỹ, sáng tạo và linh hoạt; Cập nhật nhanh các xu hướng, có khả năng sản xuất nội dung bắt trend; Có tinh thần cầu thị, ham học hỏi, chịu được áp lực công việc; Khả năng giải quyết vấn đề nhanh, kỹ năng teamwork và tôn trọng deadline.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''After Effect'', ''Premiere'', ''Capcut'']
Kỹ năng mềm: [''Sáng tạo'', ''Linh hoạt'', ''Giải quyết vấn đề'', ''Teamwork'', ''Tôn trọng deadline'']', 'INTERNSHIP', 'ONSITE', 'hà nội, đà nẵng', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Trợ cấp lương trong quá trình thực tập'', ''Môi trường làm việc chuyên nghiệp, năng động và sáng tạo'', ''Được tham gia các hoạt động văn hóa sôi nổi của công ty'', ''Cơ hội trở thành nhân viên chính thức ngay khi kết thúc thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (155, 9, 7, 'Thực Tập Sinh Kinh Doanh', 'Nghiên cứu thị trường, tìm kiếm và tiếp cận khách hàng tiềm năng có nhu cầu sử dụng máy trắc địa (ví dụ: công ty xây dựng, khảo sát, địa chất, quy hoạch, các kỹ sư tự do...) qua các nền tảng MXH. Đăng bài giới thiệu,bán hàng, và truyền thông về các sản phẩm, dịch vụ thông qua fanpage facebook, zalo hoặc các kênh đại diện của công ty. Hỗ trợ Marketing: Tham gia vào việc xây dựng và thực hiện các chiến lược marketing, bao gồm chuẩn bị tài liệu quảng bá, kiến thức về sản phẩm. Tư vấn, báo giá, chốt đơn, xử lí đơn hàng. Soạn hợp đồng, nhập liệu thông tin của khách hàng. Thay mặt công ty CSKH cá nhân & doanh nghiệp trước, trong và sau bán hàng. Duy trì mối quan hệ tốt với khách hàng, hỗ trợ giải đáp thắc mắc và đảm bảo sự hài lòng của khách hàng để khuyến khích mua hàng lặp lại hoặc giới thiệu khách hàng mới. Cập nhật thông tin thị trường: Nắm bắt xu hướng thị trường, thông tin về đối thủ cạnh tranh và phản hồi của khách hàng để đóng góp vào chiến lược kinh doanh của công ty. Tiếp nhận công việc và triển khai kế hoạch kinh doanh của leader. Báo cáo: Thực hiện báo cáo định kỳ về kết quả kinh doanh, danh sách khách hàng tiềm năng và các hoạt động đã thực hiện.', '1. Ưu tiên ứng viên đang theo học (năm 2-3-4) các chuyên ngành về QTKD, xây dựng, trắc địa, kinh tế hoặc các chuyên ngành liên quan. 2. Kỹ năng giao tiếp tốt, tự tin và có khả năng phản biện. 3. Có laptop cá nhân. 4. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). 5. Là người hướng ngoại, hoạt bát, nhanh nhẹn.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Tự tin'', ''Khả năng phản biện'', ''Hướng ngoại'', ''Hoạt bát'', ''Nhanh nhẹn'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '2.0 - 7.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Hỗ trợ lương cứng 2.000.000đ'', ''Phụ cấp ăn trưa'', ''Thưởng % doanh số'', ''Được đào tạo về chuyên môn và sản phẩm'', ''Hỗ trợ dấu thực tập và tài liệu liên quan'', ''Môi trường làm việc sáng tạo, năng động'', ''Lịch làm việc linh hoạt theo lịch học'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (156, 10, 7, 'Thực Tập Sinh Livestream', '+ Hỗ trợ lên kịch bản, nội dung cho các buổi livestream bán hàng trên Facebook, TikTok, Shopee Live,… + Tham gia Hỗ trợ MC/BTV trong quá trình livestream, chuẩn bị sản phẩm, setup bối cảnh. + Theo dõi, quản lý bình luận, tương tác với khách hàng trong livestream. + Hỗ trợ xử lý đơn hàng, xác nhận thông tin khách hàng sau livestream. + Phối hợp với team Marketing để tối ưu hiệu quả livestream. + Nghiên cứu, cập nhật xu hướng livestream để đề xuất ý tưởng mới. + Các công việc khác theo yêu cầu của quản lý.', '+ Sinh viên hoặc người yêu thích công việc livestream và bán hàng online. + Nhanh nhẹn, hoạt bát, có kỹ năng giao tiếp tốt. + Biết sử dụng các nền tảng livestream như TikTok, Shopee Live, Facebook Live. + Có khả năng chịu áp lực, xử lý tình huống linh hoạt trong quá trình livestream. + Có kinh nghiệm livestream là một lợi thế. + Có laptop cá nhân.
Kỹ năng chuyên môn: [''Sử dụng các nền tảng livestream như TikTok, Shopee Live, Facebook Live'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Hoạt bát'', ''Kỹ năng giao tiếp tốt'', ''Có khả năng chịu áp lực'', ''Xử lý tình huống linh hoạt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được đào tạo về kỹ năng livestream, kịch bản, cách tăng tương tác'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Môi trường làm việc năng động, nhiều cơ hội phát triển'', ''Hỗ trợ chứng nhận thực tập nếu cần'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (157, 2, 7, 'Thực Tập Sinh Media Quay Dựng Video', '- Thực hiện quay các video sự kiện, phóng sự, TVC,… - Biên tập các video sự kiện, phóng sự, TVC… phục vụ cho các kênh truyền thông Website, You Tube , Facebook… - Tìm kiếm các trend mới, video mới phù hợp với xu hướng khách hàng quan tâm. - Chịu trách nhiệm về các sản phẩm truyền thông chung của Team Media (video, hình ảnh),...và theo từng chiến dịch Marketing của công ty. - Xây dựng kho lưu trữ video, hình ảnh các nội dung liên quan tới hoạt động của công ty.', '- Biết quay phim, đảm bảo chất lượng hình ảnh tốt. - Biết sử dụng các thiết bị quay phim (Máy ảnh Sony, Crane, Ronin, Mic thu âm vv) - Kỹ năng dựng phim cơ bản (Adobe Premiere, After Effect cơ bản) - Kỹ năng làm việc nhóm - Sáng tạo trong làm phim. - Chịu được áp lực trong công việc.
Kỹ năng chuyên môn: [''Biết quay phim'', ''Sử dụng các thiết bị quay phim (Máy ảnh Sony, Crane, Ronin, Mic thu âm)'', ''Kỹ năng dựng phim cơ bản (Adobe Premiere, After Effect cơ bản)'']
Kỹ năng mềm: [''Kỹ năng làm việc nhóm'', ''Sáng tạo trong làm phim'', ''Chịu được áp lực trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7: 8h30-12h30', '[''Nhân viên và người thân được mua nhà ưu đãi theo chính sách công ty'', ''Được tham gia các khóa đào tạo- huấn luyện phát triển năng lực'', ''Được du lịch, nghỉ dưỡng 4-5 sao trong và ngoài nước'', ''Môi trường làm việc năng động, trẻ trung, nhiệt huyết, nhân viên thanh lịch'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (158, 3, 7, 'Thực Tập Sinh Quản Lý Kênh (SEO) Youtube', 'Góp phần thúc đẩy hiệu quả kênh YouTube và các nền tảng số của công ty thông qua hoạt động SEO. Cam kết hoàn thành tốt các mục tiêu được giao. Tối ưu tiêu đề, mô tả, hashtag, từ khóa cho các video trên YouTube. Phân tích, theo dõi hiệu suất SEO và đề xuất cải tiến. Tham gia lên kế hoạch từ khóa, nghiên cứu xu hướng nội dung, hỗ trợ các chiến dịch tăng trưởng kênh. Học hỏi và thực hành các công cụ SEO như: TubeBuddy, VidIQ, Google Trends, Analytics... Chi tiết công việc sẽ trao đổi thêm trong buổi phỏng vấn.', 'Yêu thích và mong muốn phát triển sự nghiệp trong lĩnh vực SEO và YouTube Marketing. Không yêu cầu bằng cấp đúng chuyên ngành. Có tư duy phân tích, kỹ năng tìm kiếm thông tin và làm việc với dữ liệu. Có hiểu biết cơ bản hoặc đã từng tìm hiểu về SEO YouTube là lợi thế. Thái độ làm việc nghiêm túc, cầu tiến, chủ động học hỏi và có khả năng làm việc nhóm tốt.
Kỹ năng chuyên môn: [''SEO'', ''YouTube Marketing'', ''TubeBuddy'', ''VidIQ'', ''Google Trends'', ''Analytics'']
Kỹ năng mềm: [''Tư duy phân tích'', ''Kỹ năng tìm kiếm thông tin'', ''Làm việc nhóm'', ''Thái độ làm việc nghiêm túc'', ''Cầu tiến'', ''Chủ động học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Thứ 2 – Thứ 6: 8h30 – 18h00 (nghỉ trưa 1h30), Thứ 7: Làm việc cách tuần', '[''Giấy chứng nhận thực tập'', ''Cơ hội trở thành nhân viên chính thức với mức lương 8 – 15 triệu VNĐ/tháng'', ''Phụ cấp ăn trưa: 720.000 VNĐ/tháng'', ''Thưởng theo hiệu quả SEO/dự án'', ''Đóng BHXH đầy đủ'', ''Teambuilding hàng năm'', ''Du lịch trong/ngoài nước khi đạt mục tiêu dự án'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (159, 7, 7, 'Thực Tập Sinh Truyền Thông Nội Bộ', 'Hỗ trợ xây dựng nội dung cho các kênh truyền thông nội bộ (bản tin nội bộ, email, group chat, bảng tin văn phòng, v.v.). Phối hợp ghi hình – chụp ảnh – dựng video ngắn cho các hoạt động nội bộ, sự kiện, chiến dịch văn hóa doanh nghiệp. Tham gia tổ chức các sự kiện nội bộ: sinh nhật nhân viên, vinh danh nhân sự, ngày lễ đặc biệt, teambuilding, v.v. Hỗ trợ thu thập ý kiến – khảo sát nhân viên, giúp nâng cao trải nghiệm làm việc. Đề xuất các ý tưởng sáng tạo để làm mới nội dung truyền thông, giúp lan toả văn hóa doanh nghiệp gần gũi và thú vị hơn. Thực hiện các công tác khác theo sự phân công của quản lý trực tiếp.', '- Sinh viên năm 3,4 thuộc các chuyên ngành liên quan; - Có laptop cá nhân; - Thực tập tối thiểu 6 buổi/tuần (4 tiếng/buổi); - Có tinh thần cầu tiến, ham học hỏi và chủ động trong công việc. - Biết sử dụng cơ bản các công cụ thiết kế (Canva, CapCut, v.v.) - Năng động, hoạt bát, không ngại đám đông - Có khả năng hoạt náo
Kỹ năng chuyên môn: [''Sử dụng cơ bản các công cụ thiết kế (Canva, CapCut)'']
Kỹ năng mềm: [''Tinh thần cầu tiến'', ''Ham học hỏi'', ''Chủ động trong công việc'', ''Năng động'', ''Hoạt bát'', ''Có khả năng hoạt náo'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 2000000.00, '1.5 - 2.5 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 07:00), tối thiểu 06 buổi/tuần (mỗi buổi 4 tiếng)', '[''Hỗ trợ dấu mộc thực tập tại công ty'', ''Có cơ hội trở thành nhân viên chính thức của công ty'', ''Hỗ trợ phụ cấp khi thực tập'', ''Tham gia các hoạt động chung của công ty'', ''Được đào tạo kỹ năng công việc chuyên môn'', ''Tham gia các khóa đào tạo kỹ năng mềm'', ''Môi trường làm việc trẻ trung, năng động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (160, 8, 7, 'Chuyên Viên Thiết Kế Quay Dựng Video (Part Time)', '- Quay, dựng video, chụp ảnh, cắt ghép các clip để tạo thành 1 clip hoàn chỉnh. - Phối hợp với bộ phận nội dung để lên kịch bản, ý tưởng cho video - Chỉnh sửa, tạo hiệu ứng để hoàn chỉnh các video, clip theo yêu cầu của Công ty. - Quay/dựng video khách hàng, video thương hiệu, video quảng cáo theo sự yêu cầu của phòng Marketing cho các nền tảng: Youtube, Facebook, Tiktok,… - Hỗ trợ chụp ảnh sản phẩm. - Tiếp nhận & xử lý yêu cầu của các phòng ban khác - Tham gia vào quá trình sáng tạo concept, phát triển ý tưởng, xây dựng hình ảnh và thực hiện thiết kế cho các ấn phẩm của Công ty/Dự án - Dựng và sản xuất các video nội bộ của công ty - Công tác khác: Chịu trách nhiệm chỉnh sửa hình ảnh tư liệu phục vụ công tác Marketing và truyền thông (hình ảnh cập nhật Website, hình ảnh cập nhật facebook...) - Cập nhật xu hướng thiết kế, nâng cao chất lượng nghiệp vụ - Thực hiện báo cáo và các nhiệm vụ khác theo sự phân công của cấp trên', '* Yêu cầu kinh nghiệm từ 1 năm * Sử dụng thành thạo một số phần mềm dựng phim như Pr, Ae.... và các thiết bị quay dựng. * Kinh nghiệm Dựng video và thiết kế 2D * Sử dụng thành thạo các phần mềm Pts, A * Có kiến thức thiết kế, xử lý hình ảnh, đồ họa, video * Sử dụng thành thạo tin học văn phòng (words, Excel, PP,…. ) * Tốt nghiệp chuyên ngành Thiết kế đồ họa, Kiến trúc, Mỹ thuật ứng dụng hoặc liên quan * Có ý tưởng sáng tạo và có phong cách thiết kế riêng. Có tư duy và kiến thức chuyên môn về thiết kế, quảng cáo, in ấn,…
Kỹ năng chuyên môn: [''Sử dụng thành thạo một số phần mềm dựng phim như Pr, Ae'', ''Kinh nghiệm Dựng video và thiết kế 2D'', ''Sử dụng thành thạo các phần mềm Pts, A'', ''Có kiến thức thiết kế, xử lý hình ảnh, đồ họa, video'', ''Sử dụng thành thạo tin học văn phòng (words, Excel, PP)'']
Kỹ năng mềm: [''Có ý tưởng sáng tạo và có phong cách thiết kế riêng'', ''Có tư duy và kiến thức chuyên môn về thiết kế, quảng cáo, in ấn'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Thưởng dự án'', ''Thưởng lễ, Tết'', ''Thưởng theo năng lực'', ''Hưởng đầy đủ các chế độ BHXH, BHYT, BHTN đầy đủ theo quy định của pháp luật'', ''Môi trường làm việc chuyên nghiệp, sáng tạo, hỗ trợ phát triển cá nhân'', ''Được đào tạo, đề xuất cập nhật công nghệ thiết kế mới'', ''Tham gia các hoạt động thường niên của công ty: văn nghệ, thể thao'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (161, 9, 7, 'Thực Tập Sinh Livestream TikTok Theo Ca Sáng/Tối', 'Livestream trên TikTok bán các sản phẩm bánh trung thu truyền thống của công ty. Thời gian linh hoạt theo ca: Ca sáng: 9h00 – 12h00, Ca trưa: 12h00 – 15h00, Ca chiều: 15h00 – 18h00, Ca tối: 18h00 – 21h00. Hỗ trợ chuẩn bị sản phẩm trước khi live (setup khung, kiểm tra ánh sáng, chuẩn bị đạo cụ…). Giao tiếp tự nhiên, giới thiệu sản phẩm thu hút, chốt đơn ngay trên live. Làm việc tại văn phòng có hỗ trợ đạo cụ, thiết bị và đóng dấu xác nhận thực tập chính thức từ công ty. Các công việc khác theo sự chỉ đạo của cấp trên.', 'Sinh viên năm 2–4, ưu tiên các ngành Thương mại điện tử, Truyền thông, Marketing, Kinh doanh, hoặc có đam mê với livestream bán hàng. Gương mặt sáng, giọng nói dễ nghe, rõ ràng (không nói ngọng, nói lắp), ưu tiên giọng miền Nam. Tự tin giao tiếp, biết cách tương tác với người xem trên live. Có trách nhiệm, đúng giờ, ham học hỏi. Biết sử dụng TikTok cơ bản là một lợi thế. Sau thời gian thực tập Mong muốn hợp tác làm việc lâu dài gắn bó cùng Công ty.
Kỹ năng chuyên môn: [''Biết sử dụng TikTok cơ bản'']
Kỹ năng mềm: [''Tự tin giao tiếp'', ''Có trách nhiệm'', ''Đúng giờ'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Hỗ trợ phụ cấp từ 3 đến 6 triệu hàng tháng tùy năng lực'', ''Hỗ trợ dấu mộc tròn và nhận xét báo cáo thực tập sau 2 tháng'', ''Được đào tạo kỹ năng livestream, kỹ năng bán hàng thực chiến trên TikTok'', ''Được làm việc trong môi trường chuyên nghiệp thân thiện, năng động'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (162, 10, 7, 'Thực Tập Sinh Kinh Doanh', 'Tiếp nhận các kế hoạch triển khai kinh doanh của Phòng kinh doanh. Nắm vững thông tin, kiến thức của dự án để tư vấn cho khách hàng. Tìm kiếm khách hàng mới, chăm sóc khách hàng cũ. Hỗ trợ khách các thủ tục mua bán và giao dịch.', 'Không yêu cầu kinh nghiệm, chưa có sẽ được đào tạo. Kỹ năng làm việc độc lập và làm việc nhóm. Tự tin, giao tiếp tốt, ham học hỏi là 1 lợi thế. Năng động, sáng tạo, nhiệt tình, nghiêm túc và có trách nhiệm với công việc. Đảm bảo chỉ tiêu kinh doanh, hoàn thành nhiệm vụ trước trưởng bộ phận quản lý trực tiếp.
Kỹ năng mềm: [''Kỹ năng làm việc độc lập'', ''Kỹ năng làm việc nhóm'', ''Tự tin'', ''Giao tiếp tốt'', ''Ham học hỏi'', ''Năng động'', ''Sáng tạo'', ''Nhiệt tình'', ''Có trách nhiệm với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội, đà nẵng', 'Hà Nội', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường làm việc trẻ trung, năng động, chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức'', ''Được cung cấp nguồn hàng đa dạng, độc quyền'', ''Được hưởng các chính sách phúc lợi theo quy định của công ty'', ''Được đào tạo, học hỏi và nâng cao nghiệp vụ kinh doanh thường xuyên'', ''Hỗ trợ lương tháng + hoa hồng + thưởng hiệu quả công việc'', ''Hỗ trợ con dấu thực tập (thời gian thực tập tối thiểu 3 tháng)'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (163, 2, 7, 'Thực Tập Sinh Quay Dựng Video & Thiết Kế', '- Xây dựng ý tưởng và thiết kế đồ họa các banner, sản phẩm truyền thông cho các sản phẩm của công ty. - Phối Hợp tổ chức Livestream, quay short video định kỳ. - Tham gia lên ý tưởng xây dựng kịch bản video, phối hợp với biên tập viên dựng video. - Thực hiện quay, dựng các video (giới thiệu sản phẩm, sự kiện, cảm nhận/đánh giá sản phẩm,...), edit video tiktok / youtube theo yêu cầu của người hướng dẫn - Phụ trách phân phối và phát triển nội dung sản phẩm trên đa dạng các kênh truyền thông (YouTube, Facebook, TikTok...). - Cập nhật các thông tin sự kiện hot, trend thường xuyên vào video. - Báo cáo, lập kế hoạch và đưa ra ý tưởng mới. - Hỗ trợ các công việc liên quan khác', '- Biết sử dụng phần mềm edit cơ bản như premier, photoshop, AI, canva, capcut... (ưu tiên có kinh nghiệm) - Biết sử dụng tiếng anh cơ bản - Thực tập Fulltime - Yêu thích và định hướng lâu dài về mảng thiết kế & edit video - Nhiệt tình, nghiêm túc và có trách nhiệm với công việc.
Kỹ năng chuyên môn: [''premier'', ''photoshop'', ''AI'', ''canva'', ''capcut'']
Kỹ năng mềm: [''Nhiệt tình'', ''Nghiêm túc'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Được hưởng chính sách lương thưởng, nghỉ lễ theo quy định của nhà nước.'', ''Được học hỏi và làm việc trong môi trường năng động.'', ''Thực tập sinh được đào tạo và thực hành chuyên ngành miễn phí.'', ''Được trải nghiệm môi trường làm việc và rút kinh nghiệm thực tế.'', ''Được tham quan trải nghiệm thực tế các Farm trên nhiều tỉnh thành.'', ''Nếu thực tập tốt sẽ được nhận làm nhân viên chính thức của công ty.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (164, 3, 7, 'Thực Tập Hỗ Trợ Khách Hàng Part-Time, Full-Time', 'Tiếp nhận và xử lý các cuộc gọi, email, tin nhắn từ khách hàng. Hỗ trợ khách hàng giải đáp thắc mắc về sản phẩm, dịch vụ của công ty. Giải quyết các vấn đề, khiếu nại của khách hàng một cách nhanh chóng và hiệu quả. Cập nhật thông tin khách hàng và lịch sử giao dịch. Tham gia các hoạt động tư vấn khách hàng khác theo sự phân công của quản lý. Làm việc nhóm hiệu quả để đạt được mục tiêu chung của bộ phận. Đóng góp ý tưởng để cải thiện chất lượng dịch vụ khách hàng. Thời gian thực tập: 6 tháng. Công ty chỉ tuyển ứng viên đi thực tập lấy kinh nghiệm, để được đào tạo chuyên ngành và ở lại làm việc lâu dài cho công ty.', 'Không yêu cầu kinh nghiệm. Có khả năng giao tiếp tốt, giọng nói dễ nghe, rõ ràng. Có kỹ năng lắng nghe tích cực và thấu hiểu khách hàng. Khả năng giải quyết vấn đề và ra quyết định nhanh chóng. Có khả năng làm việc độc lập và làm việc nhóm. Trung thực, nhiệt tình, có trách nhiệm trong công việc. Thành thạo tin học văn phòng (Word, Excel). Khả năng sử dụng các phần mềm hỗ trợ chăm sóc khách hàng là một lợi thế. Khả năng thích nghi nhanh với môi trường làm việc năng động. Sinh viên năm 1, 2, 3, và 4, Không yêu cầu kinh nghiệm, được đào tạo bài bản. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel)'']
Kỹ năng mềm: [''Giao tiếp'', ''Lắng nghe'', ''Giải quyết vấn đề'', ''Làm việc nhóm'', ''Trung thực'', ''Nhiệt tình'', ''Có trách nhiệm trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', '1 tuần làm tối thiểu 6 ca, tương đương tối thiểu 15h/tuần', '[''Phụ cấp hỗ trợ thực tập để ăn trưa, gửi xe, xăng xe: 10.000 đ/h'', ''Cấp chứng chỉ thực tập'', ''Môi trường làm việc năng động, trẻ trung'', ''Được tăng lương và đề bạt làm nhân viên chính thức nếu có kết quả thực tập tốt'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (165, 7, 7, 'Nhiếp ảnh gia/biên tập viên video', 'Thời gian làm việc: Linh hoạt 3 ngày/tuần, tự chọn từ Thứ 2 đến Thứ 7 (khung giờ: 09h00 – 18h00). Chọn lọc và biên tập nội dung theo yêu cầu từng dự án. Sắp xếp nội dung hợp lý, thực hiện các chỉnh sửa cuối trước khi phát hành. Dùng phần mềm thiết kế/video như Adobe Premiere, Final Cut Pro, Photoshop,… để tạo nội dung hấp dẫn. Chỉnh sửa hình ảnh phù hợp với chủ đề của dự án.', 'Sinh viên đang học hoặc mới ra trường đang tìm nơi học việc thực tế. Có tư duy sáng tạo và khả năng làm nội dung đúng định hướng thương hiệu. Chủ động, có tinh thần trách nhiệm, yêu thích học hỏi và phát triển bản thân.
Kỹ năng chuyên môn: [''Adobe Premiere'', ''Final Cut Pro'', ''Photoshop'']
Kỹ năng mềm: [''Sáng tạo'', ''Chủ động'', ''Tinh thần trách nhiệm'', ''Yêu thích học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.5 triệu', 'Linh hoạt 3 ngày/tuần, tự chọn từ Thứ 2 đến Thứ 7 (khung giờ: 09h00 – 18h00)', '[''Hưởng chế độ BHXH, BHYT, BHTN đầy đủ khi lên chính thức'', ''Làm việc trong môi trường trẻ, năng động, thân thiện'', ''Hỗ trợ thực tập: 2.500.000 VNĐ/tháng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (166, 8, 7, 'Nhân Viên Pg Sampling Rượu Hàn Quốc', 'Giới thiệu sản phẩm rượu Hàn Quốc tới khách hàng tại nhà hàng được phân công. Là đại sứ thương hiệu của sản phẩm. Tư vấn bán hàng nếu khách hàng có nhu cầu.', 'Ngoại hình khá. Kỹ năng giao tiếp tốt. Ưu tiên ứng viên đã có kinh nghiệm PG.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'']', 'PART_TIME', 'REMOTE', 'nam từ liêm', 'Hà Nội', 'MONTHLY', 5000000.00, '5.0 - 5.5 triệu', 'Thứ 2 - Thứ 6 (từ 17:00 đến 21:00)', '[''Thưởng theo doanh số'', ''Môi trường làm việc năng động'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (167, 9, 7, 'Thực Tập Trợ Lý Điều Hành Part-Time, Full-Time', 'Hỗ trợ Qua trong việc quản lý văn phòng và điều hành các bộ phận trong công ty. Quản lý, sắp xếp lịch làm việc, cuộc họp, báo cáo tiến độ công việc các bộ phận. Kiểm tra và hỗ trợ giám sát công việc nhân viên cùng HR. Thay mặt giám đốc đưa ra quyết định trong phạm vi cho phép. Quản lý và cập nhật thông tin, dữ liệu văn phòng. Thực hiện các công việc khác theo sự phân công của Giám đốc. Khi bắt đầu, ứng viên sẽ chưa hiểu và triển khai công việc các bộ phận được. Công ty sẽ đào tạo ứng viên lần lượt ở các bộ phận chăm sóc khách hàng, kinh doanh, marketing, nhân sự, hành chính,… sau khi hiểu được các bộ phận mới có thể bắt đầu làm trợ lý điều hành được. Thời gian thực tập: 6 tháng. Công ty chỉ tuyển ứng viên đi thực tập lấy kinh nghiệm, để được đào tạo chuyên ngành và ở lại làm việc lâu dài cho công ty. Chứng chỉ thực tập được cấp sau khi hoàn thành khóa thực tập.', 'Không yêu cầu kinh nghiệm. Có kỹ năng giao tiếp tốt, giọng nói dễ nghe, tác phong chuyên nghiệp. Có kỹ năng quản lý thời gian hiệu quả, khả năng làm việc độc lập và theo nhóm. Có khả năng tổ chức, sắp xếp công việc khoa học, ngăn nắp, cẩn thận. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). Trung thực, nhanh nhẹn, có tinh thần trách nhiệm cao. Khả năng làm việc dưới áp lực tốt. Sinh viên năm 1, 2, 3, và 4, Không yêu cầu kinh nghiệm, được đào tạo bài bản. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Kỹ năng quản lý thời gian hiệu quả'', ''Khả năng làm việc độc lập và theo nhóm'', ''Khả năng tổ chức, sắp xếp công việc khoa học, ngăn nắp, cẩn thận'', ''Trung thực, nhanh nhẹn, có tinh thần trách nhiệm cao'', ''Khả năng làm việc dưới áp lực tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Part Time Trong giờ hành chính: 6 ca/ Tuần, Trong đó có 02 ca vào "các buổi tối hoặc chiều T7 hoặc CN"', '[''Phụ cấp hỗ trợ thực tập để ăn trưa, gửi xe, xăng xe: 10.000 đ/h'', ''Được tăng lương và đề bạt làm nhân viên chính thức nếu có kết quả thực tập tốt'', ''Cấp chứng chỉ thực tập'', ''Môi trường làm việc năng động, trẻ trung'', ''Có quyền tự chủ trong công việc'', ''Đào tạo nhân viên theo ISO 9001'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (168, 10, 7, 'Chuyên Viên SEO Entity', 'Phân tích và triển khai chiến lược SEO Entity để xây dựng hệ thống thực thể ngữ nghĩa (entities) cho website. Kết nối và mở rộng mối quan hệ giữa các thực thể (entity relationship) thông qua bài viết, schema, backlink và cấu trúc website. Tối ưu nội dung theo hướng ngữ nghĩa (semantic SEO), đề xuất cải thiện chủ đề bài viết, internal link, thẻ heading, anchor text… Triển khai schema markup (FAQ, Product, Organization, Article...) để tăng độ uy tín và khả năng hiểu nội dung từ Google. Sử dụng các công cụ: Google NLP, InLinks, WordLift, schema.org, GSC, Ahrefs, SEMrush… để đo lường và theo dõi tiến độ.', 'Có nền tảng kiến thức tốt về SEO tổng thể, đặc biệt là Entity và Semantic SEO. Hiểu rõ về cấu trúc dữ liệu, schema markup, silo content và topical authority. Khả năng tư duy hệ thống, logic, tỉ mỉ và chủ động cập nhật kiến thức mới. Ưu tiên: đã từng xây dựng hệ thống entity cho website hoặc triển khai dự án SEO thực thể.
Kỹ năng chuyên môn: [''Nghiên Cứu Từ Khóa'', ''Xây Dựng Liên Kết'', ''Tối Ưu Hóa On Page Seo'', ''Phân Tích Dữ Liệu Seo'', ''Hiểu Biết Về Schema Markup Và Entity'']
Kỹ năng mềm: [''Khả năng tư duy hệ thống'', ''Logic'', ''Tỉ mỉ'', ''Chủ động cập nhật kiến thức mới'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Thưởng hiệu quả làm việc'', ''Cơ hội tham gia các dự án SEO quốc tế'', ''Cấp chứng nhận thực tập'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (169, 2, 7, 'Thực Tập Sinh Video Editor', '- Dựng video đa nền tảng: Biên tập video chủ đề công nghệ AI/Automation (explainer videos) cho các kênh TikTok/Reels/YouTube (tutorial, review, behind-the-scenes). - Chỉnh sửa, tạo hiệu ứng để hoàn chỉnh các video, clip theo yêu cầu. Tối ưu video theo insight người dùng (A/B testing định dạng). - Hỗ trợ sản xuất: Phối hợp với team Content/Design để hiện thực hóa ý tưởng video. Quay phim cơ bản nếu cần.', '- Ứng viên là sinh viên năm 3 - năm 4, sinh viên sắp ra trường muốn thực tập học hỏi trau dồi kinh nghiệm thực chiến Designer Graphic thuộc chuyên ngành Thiết kế/Điện ảnh/Truyền thông, Digital Marketing,... - Ưu tiên ứng viên có Portfolio thể hiện tư duy sáng tạo (dự án học thuật/cá nhân đều được tính). - Thành thạo công cụ/phần mềm: Premiere Pro (bắt buộc), After Effects (ưu tiên), DaVinci Resolve. Biết dùng AI hỗ trợ dựng phim (CapCut, Canva) là điểm cộng lớn. - Có tư duy hình ảnh cơ bản, nhạy bén với trend video trên nền tảng ngắn (TikTok/Reels). - Có hứng thú với AI/ Automation - không cần chuyên sâu nhưng cần hiểu bản chất sản phẩm. - Chi tiết, cẩn thận với từng timeline, chịu được áp lực chỉnh sửa theo feedback và sẵn sàng học công cụ AI mới. - Tư duy chủ động, học nhanh, không chờ ai nhắc việc. Tinh thần khởi nghiệp, thích kiếm tiền và thử sức nhiều vai trò.
Kỹ năng chuyên môn: [''Premiere Pro'', ''After Effects'', ''DaVinci Resolve'', ''AI hỗ trợ dựng phim (CapCut, Canva)'']
Kỹ năng mềm: [''Tư duy chủ động'', ''Học nhanh'', ''Chi tiết'', ''Cẩn thận'', ''Chịu được áp lực'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Học từ thực chiến'', ''Mentorship từ Founder'', ''Huấn luyện chuyên sâu'', ''Cơ hội tạo dòng tiền'', ''Con đường rõ ràng đến vị trí chính thức'', ''Môi trường lý tưởng để phát triển'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (170, 3, 7, 'Video Editor Intern', 'Chỉnh sửa các video dạng ngắn cho quần short Tiktok, YouTube và YouTube bằng các công cụ như Capcut, Premiere Pro hoặc After Effects. Đảm bảo giai điệu thương hiệu nhất quán và chất lượng trên tất cả các tài liệu được chỉnh sửa. Thực hiện theo các bản tóm tắt hoặc tập lệnh thô để tạo các video hấp dẫn phù hợp với các mục tiêu chiến dịch. Tải lên và lên lịch nội dung trên các nền tảng bao gồm YouTube, Tiktok. Thêm chú thích, mô tả và thẻ được tối ưu hóa để cải thiện khả năng khám phá và sự tham gia. Phối hợp với nhóm nội dung để sắp xếp các bản phát hành video với lịch tiếp thị. Tham gia vào các phiên động não với các nhóm sáng tạo và tiếp thị. Đề xuất các định dạng mới hoặc góc độ nội dung để thúc đẩy sự duy trì của người xem và tăng trưởng đối tượng. Hỗ trợ trong việc tổ chức các tập tin dự án, tài sản và sao lưu.', 'Currently pursuing or recently graduated in Film, Media, Multimedia Design, Communications, or related fields. Proficient with CapCut and familiar with Adobe Premiere Pro, After Effects, or similar tools. Good visual storytelling skills and an eye for clean, engaging edits. Understanding of short-form content trends on TikTok, YouTube, and Reels. Organized, reliable, and open to receiving feedback and iterating quickly. A portfolio or demo reel of past editing work is highly encouraged. Availability to work full-time on-site in HCM for the internship period.
Kỹ năng chuyên môn: [''CapCut'', ''Adobe Premiere Pro'', ''After Effects'']
Kỹ năng mềm: [''Good visual storytelling skills'', ''Organized'', ''Reliable'', ''Open to receiving feedback'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Monday - Friday (from 09:00 to 18:00)', '[''Monthly internship allowance provided'', ''Opportunity for full-time employment upon successful completion of the internship'', ''Guidance and training on work-related skills'', ''Access to relevant training courses'', ''Participation in company internal activities and team-building events'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (171, 7, 7, 'Chuyên Viên Đối Ngoại Tiếng Đức', '- Đại diện cho tập đoàn EI GROUP làm việc với các trường và doanh nghiệp để tìm kiếm hợp đồng và cơ hội học tập làm việc cho học viên. - Được đào tạo và cung cấp Data khách hàng và phần mềm quản lý. - Được hưởng hoa hồng trên mỗi học sinh bay. - Được hưởng hoa hồng trên mỗi đối tác ký kết hợp tác. - Gửi BC cập nhật trên phần mềm. - Thực hiện các công việc khác theo sự phân công của cấp trên. Có 2 hình thức làm việc: -Freelancer linh hoạt thời gian, chỗ làm việc, - Fulltime (Chuyên viên Đối ngoại chính thức) làm việc tại Văn phòng Hà Nội - Parttime (Có thể sắp xếp linh hoạt thời gian lên văn phòng làm việc).', '* Đối với người Việt Nam: Sử dụng được tiếng Đức (từ B2 trở lên) [Ưu tiên ứng viên có kinh nghiệm sinh sống tại Đức] * Kĩ năng: Người Việt Nam có tiếng Đức giao tiếp tốt, người Đức đang sinh sống tại Việt Nam. * Ưu tiên các ứng viên đã từng đi du học, có kinh nghiệm làm việc trong các mảng về ngoại ngữ, du học, XKLĐ và định cư tại nước ngoài. * Chăm chỉ, chịu khó, chủ động, có trách nhiệm với công việc được giao. * Có thể chọn 1 trong 2 hình thức làm việc: - Fulltime (Chuyên viên Đối ngoại chính thức) làm việc tại Văn phòng Hà Nội hoặc tại HCM - Parttime (Có thể sắp xếp linh hoạt thời gian lên văn phòng làm việc) hoặc Freelancer tại CHLB Đức.
Kỹ năng chuyên môn: [''Tiếng Đức (từ B2 trở lên)'']
Kỹ năng mềm: [''Chăm chỉ'', ''Chịu khó'', ''Chủ động'', ''Có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 30000000.00, '15.0 - 30.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Tham gia BHXH'', ''Chế độ nghỉ mát'', ''Thưởng các ngày Lễ, tết'', ''Môi trường làm việc chuyên nghiệp'', ''Được tham gia các chương trình đào tạo'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (172, 8, 7, 'Thiết kế đồ họa thực tập', 'Thiết kế, sáng tạo và phát triển đa dạng các ấn phẩm báo chí, truyền thông, key visual cho các chiến dịch, dự án; Phối hợp với bộ phận liên quan lên ý tưởng thiết kế các ấn phẩm quảng cáo trên kênh Digital Marketing (Website, Facebook, Youtube,...); Nắm bắt nhu cầu, cập nhật xu hướng của thị trường để nâng cao chất lượng và phát triển đa dạng các chủ đề, nội dung và phong cách thiết kế mới phù hợp; Làm việc cùng thành viên và Leader trong quá trình lên ý tưởng sáng tạo và triển khai các chiến dịch cho khách hàng và công ty; Hỗ trợ các công việc khác theo sự phân công của Leader.', 'Sắp/ Tốt nghiệp chuyên ngành Thiết kế đồ họa, Mỹ thuật, Truyền thông Đa phương tiện,...; Kỹ năng sử dụng thành thạo các phần mềm thiết kế (Photoshop, Illustrator, Indesign,...); Có khả năng và tư duy thẩm mỹ tốt; Yêu cái đẹp và thích sáng tạo; Khả năng giải quyết vấn đề nhanh, kỹ năng teamwork và tôn trọng deadline; Ưu tiên ứng viên đã có kinh nghiệm thiết kế các ấn phẩm liên quan; Biết vẽ minh họa, dựng 3D sản phẩm là một lợi thế; Đã có kinh nghiệm làm việc tại đơn vị truyền thông/ Marketing/ Agency là một lợi thế.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Indesign'']
Kỹ năng mềm: [''Khả năng giải quyết vấn đề nhanh'', ''Kỹ năng teamwork'', ''Tôn trọng deadline'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Trợ cấp lương trong quá trình thực tập'', ''Môi trường làm việc chuyên nghiệp, năng động và sáng tạo'', ''Cơ hội được trực tiếp triển khai các dự án lớn'', ''Được đào tạo theo mô hình training on job'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (173, 9, 7, 'Thực Tập Sinh VJ / MC / Host', 'Đây không chỉ là một vị trí thực tập, mà là một trong những vị trí nhân sự trọng điểm của Z15 Miracle Vietnam – nơi tìm kiếm, đầu tư và phát triển gương mặt đại diện cho thế hệ MC/VJ truyền cảm hứng, có khả năng truyền tải thông điệp và giá trị thương hiệu ra cộng đồng. Tham gia dẫn dắt các nội dung video, podcast, talkshow hoặc livestream thuộc các dự án truyền thông, giáo dục, giải trí của Z15 Miracle. Chủ động đề xuất ý tưởng format chương trình mới, kịch bản dẫn dắt, tương tác nội dung sáng tạo theo từng tệp khán giả. Làm việc với team nội dung, sản xuất và marketing để xây dựng hình ảnh cá nhân và phát triển thương hiệu MC/VJ. Tham gia ghi hình, quay video (qua Zoom/Google Meet hoặc tại các điểm hỗ trợ sản xuất của Z15 Miracle). Hỗ trợ truyền thông các sản phẩm do mình tham gia dẫn dắt trên các nền tảng social (TikTok, YouTube, Facebook...).', 'Có đam mê, năng lượng tích cực và kỹ năng giao tiếp tốt khi đứng trước ống kính hoặc micro. Có khả năng ứng biến linh hoạt, sáng tạo trong cách dẫn dắt và xử lý tình huống. Ưu tiên các ứng viên có kinh nghiệm dẫn chương trình, quay TikTok, podcast, vlog, livestream... hoặc có chất giọng ấn tượng. Có thiết bị cơ bản để làm việc từ xa (micro, điện thoại/webcam ổn định, kết nối mạng tốt). Đầu vào yêu cầu cao: Z15 Miracle Vietnam tìm kiếm những nhân tố xuất sắc, tiềm năng và có tư duy chuyên nghiệp trong hành trình trở thành một MC/VJ có sức ảnh hưởng thật sự. Sẵn sàng làm việc hybrid hoặc linh hoạt online, phối hợp hiệu quả cùng các thành viên khác trong The Nexus Generation by Z15 Miracle.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng dẫn chương trình'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Giao tiếp tốt'', ''Ngoại hình ưa nhìn'', ''Kỹ Năng Ứng Biến Tốt'', ''Kỹ Năng Ăn Nói Lưu Loát'']', 'INTERNSHIP', 'ONSITE', 'hải phòng, hà nội', 'Hải Phòng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thời gian làm việc được thỏa thuận', '[''Được công nhận là thành viên chính thức của The Nexus Generation by Z15 Miracle'', ''Thu nhập hấp dẫn'', ''Làm việc từ xa hoàn toàn'', ''Giấy xác nhận thực tập'', ''Cơ hội nhận offer chính thức'', ''Được đầu tư tài nguyên cá nhân để phát triển hình ảnh và kỹ năng'', ''Thường xuyên được tạo điều kiện xuất hiện trên các kênh truyền thông lớn'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (174, 10, 7, 'Cộng Tác Viên Khảo Sát Thị Trường', 'Thu thập, tìm kiếm thông tin khách hàng/ Hộ kinh doanh. Hỗ trợ HKD cảm thấy khó khăn trong việc tiếp cận và phải tìm hiểu, áp dụng các quy định về luật pháp, thông tư, nghị định, hồ sơ... liên quan đến việc áp dụng hóa đơn điện tử theo thông tư 70. Hướng dẫn các chủ HKD chưa xuất được hóa đơn điện tử và tư vấn các gói kí số, hóa đơn điện tử do SAVITAX làm đại lý. Giới thiệu phần mềm MISA cho các HKD chưa đăng ký và hướng dẫn sử dụng, hỗ trợ hướng dẫn và bảo hành dịch vụ khi mua qua nhân viên SAVITAX. Thông báo về tham gia BHXH bắt buộc dành cho các chủ hộ từ ngày 1/7/2025, hướng dẫn chi tiết. Lấy thông tin của khách hàng về cho phòng kinh doanh tư vấn (GPKD, CCCD, Mail, SĐT, …). Ghi nhận nhu cầu và phản hồi về dịch vụ kế toán.', 'Siêng năng, trung thực, hoạt ngôn. Có smartphone, luôn kết nối sẵn Internet phục vụ cho quá trình làm việc. Có phương tiện di chuyển, biết sử dụng google map phục vụ cho công việc. Sinh viên năm 2,3 các trường Cao đẳng, Đại học. Nam/nữ dưới 40 tuổi, có sức khỏe tốt, không ngại thời tiết.
Kỹ năng chuyên môn: [''Phân tích dữ liệu'', ''Nghiên Cứu Thị Trường'', ''Thu Thập Dữ Liệu'']
Kỹ năng mềm: [''Siêng năng'', ''Trung thực'', ''Hoạt ngôn'', ''Khả Năng Tổng Hợp Thông Tin'', ''Hiểu Biết Về Thị Trường Mục Tiêu'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 10000000.00, '2.0 - 10.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 2 - Thứ 7 (từ 08:00 đến 12:00), Thứ 7 làm online', '[''Theo số lượng khảo sát hợp lệ + thưởng hiệu suất'', ''Có training về các kiến thức cần thiết trước khi các bạn đi thị trường'', ''CTV làm full time: 2.000.000đ + 10% Hoa hồng trên đơn hàng'', ''CTV part time: 10% Hoa hồng trên đơn hàng'', ''Lộ trình thăng tiến rõ ràng theo năng lực'', ''Làm việc trong một môi trường chuyên nghiệp năng động, trẻ trung'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (175, 2, 7, 'Thực Tập Sinh Designer', '• Thiết kế logo các tài liệu và các ấn phẩm in ấn phục vụ cho việc xây dựng thương hiệu, hình ảnh công ty. • Thiết kế và lên nội dung cho các banner online, video clip cho các chương trình digital marketing như facebook, google display, quảng cáo trên youtube. • Đảm bảo chất lượng hình ảnh, chính xác trong thiết kế và các vật phẩm quảng cáo.', '• Kinh nghiệm: Không yêu cầu. • Trình độ: Sinh viên năm 3, 4 Đại học, Cao đẳng chuyên ngành thiết kế đồ họa hoặc các chuyên ngành liên quan. • Am hiểu các phần mềm đồ họa Photoshop/AI... và các phần mềm hỗ trợ khác.
Kỹ năng chuyên môn: [''Photoshop'', ''AI'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Cơ hội lớn được trở thành nhân viên chính thức sau kỳ thực tập'', ''Hỗ trợ xác nhận báo cáo thực tập, nhận xét đánh giá, dấu mộc, gửi email xác nhận với trường'', ''Được hướng dẫn công việc từ các anh/chị quản lý'', ''Được học hỏi những kiến thức và vận dụng vào công việc thực tế'', ''Được trải nghiệm môi trường làm việc năng động, sáng tạo, chuyên nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (176, 3, 7, 'Video Editor Part-Time', 'Trực tiếp quay dựng và chỉnh sửa, biên tập các video truyền thông của công ty; Phối hợp với Designer, FB ads lên ý tưởng video cho các kênh truyền thông của công ty; Làm các báo cáo theo tuần, tháng; Các công việc khác về mảng truyền thông theo sự phân công của cấp trên.', 'Ưu tiên ứng viên chuyên ngành Marketing hoặc các ngành có liên quan đến truyền thông Marketing, có kinh nghiệm trong mảng giáo dục; Ưu tiên ứng viên có kinh nghiệm chỉnh sửa, thiết kế, biên tập các video truyền thông trên Facebook hay Tiktok; Sử dụng tốt các công cụ, phần mềm chỉnh sửa, thiết kế video như Premiere, After Effects, Adobe Illustrator; Am hiểu chính sách hoạt động, các tạo trend của nền tảng Facebook, Tiktok; Có tư duy sáng tạo, bắt trend tốt, truyền tải được nội dung qua video; Có máy tính cá nhân.
Kỹ năng chuyên môn: [''Premiere'', ''After Effects'', ''Adobe Illustrator'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Bắt trend tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '2.5 triệu', 'Tối thiểu đăng ký 5 ca/tuần, Ca sáng: 8h - 12h, Ca chiều: 13h - 17h, Ca tối: 17h30 - 21h30', '[''Lương cứng: 2.500.000 VNĐ/tháng'', ''Thử việc 2 tháng (85% lương)'', ''Xét tăng lương mỗi 6 tháng làm việc'', ''Cơ hội tăng lương và kiếm thêm thu nhập theo thời gian gắn bó'', ''Làm việc trong môi trường trẻ, năng động, phát triển tốt về chuyên môn'', ''Tham gia các chương trình, sự kiện thường niên của Công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (177, 7, 7, 'Thực Tập Sinh Thiết Kế Đồ Hoạ', 'Hỗ trợ thiết kế các ấn phẩm truyền thông phục vụ hoạt động nội bộ và truyền thông số (digital), bao gồm: banner, poster, standee, backdrop, tờ rơi, name card, quà tặng, sale kit,... Tham gia hỗ trợ xây dựng và duy trì hệ thống nhận diện thương hiệu của công ty. Chỉnh sửa, tối ưu hình ảnh, video đơn giản trên các kênh truyền thông của công ty (website, fanpage, nội bộ,...). Hỗ trợ chụp và chỉnh sửa ảnh sự kiện, hoạt động nội bộ khi cần. Phối hợp cùng team Marketing triển khai các ý tưởng thiết kế cho chiến dịch truyền thông; hỗ trợ team Nội thất trong việc lên ý tưởng đồ họa cho các dự án (nếu có). Thực hiện các công việc liên quan khác theo phân công của Quản lý trực tiếp.', 'Sử dụng thành thạo các phần mềm thiết kế như Adobe Illustrator, Photoshop, InDesign, Premiere và các phần mềm chỉnh sửa video cơ bản. Có khả năng vẽ tay/sketch và biết sử dụng phần mềm thiết kế 3D là một lợi thế. Yêu thích hoặc có đam mê với nghệ thuật, mỹ thuật, thiết kế đồ họa. Có tư duy sáng tạo, tinh thần trách nhiệm cao, chủ động trong công việc, có khả năng làm việc nhóm và độc lập. Biết chụp ảnh, set-up bố cục chụp ảnh sản phẩm hoặc sự kiện là điểm cộng.
Kỹ năng chuyên môn: [''Adobe Illustrator'', ''Photoshop'', ''InDesign'', ''Premiere'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Tinh thần trách nhiệm cao'', ''Chủ động trong công việc'', ''Khả năng làm việc nhóm'', ''Khả năng làm việc độc lập'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Thực tập có trợ cấp'', ''Hỗ trợ chi phí gửi xe'', ''Môi trường làm việc trẻ trung, năng động'', ''Được hướng dẫn, đào tạo phát triển nghề nghiệp'', ''Đi du lịch - teambuilding 2 lần/năm'', ''Văn phòng tiện nghi'', ''Cơ hội trở thành nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (178, 8, 7, 'Intern Thiết Kế/ Design', 'Hỗ trợ thiết kế các ấn phẩm truyền thông cho các chiến dịch Marketing: Banner, Poster, Social Media Post, Catalogue, Profile… Tham gia xây dựng ý tưởng thiết kế theo định hướng của team hoặc theo yêu cầu từng dự án. Phối hợp với các bộ phận liên quan để đảm bảo sản phẩm thiết kế đúng tiến độ và chất lượng. Hỗ trợ chỉnh sửa, hoàn thiện các file thiết kế theo phản hồi. Thực hiện các công việc khác theo sự phân công của quản lý.', 'Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp chuyên ngành Thiết kế đồ họa, Mỹ thuật, hoặc các ngành liên quan. Thành thạo các phần mềm thiết kế cơ bản: Photoshop, Illustrator, Canva là lợi thế. Có tư duy thẩm mỹ tốt, sáng tạo, nắm bắt nhanh xu hướng thiết kế. Khả năng làm việc nhóm và tiếp nhận feedback tốt. Chủ động, trách nhiệm, cẩn thận trong công việc. Có portfolio hoặc một số sản phẩm thiết kế đã từng thực hiện là điểm cộng. Có laptop riêng sử dụng cho công việc.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Canva'']
Kỹ năng mềm: [''Tư duy thẩm mỹ tốt'', ''Sáng tạo'', ''Khả năng làm việc nhóm'', ''Tiếp nhận feedback tốt'', ''Chủ động'', ''Trách nhiệm'', ''Cẩn thận'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 11:30)', '[''Đào tạo chuyên ngành và nâng cao kinh nghiệm thực tế'', ''Có hỗ trợ dấu mộc thực tập'', ''Được nghỉ phép 1 ngày/ tháng'', ''Phụ cấp ăn trưa 500,000'', ''Công ty trả phí giữ xe tháng'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (179, 9, 7, 'CTV Trực Live', 'Hỗ trợ chuẩn bị nước uống, sản phẩm live, thiết bị live. Phối hợp cùng host trong suốt quá trình livestream: nhắc host đọc cmt, tương tác bên ngoài, ghim sản phẩm. Đảm bảo buổi livestream diễn ra suôn sẻ, hỗ trợ xử lý các vấn đề phát sinh (nếu có). Không yêu cầu xuất hiện trước ống kính.', 'Nam/Nữ từ 18-30 tuổi, nhanh nhẹn, nhiệt tình, có trách nhiệm trong công việc. Không cần kinh nghiệm, sẽ được đào tạo từ đầu. Ưu tiên biết sử dụng mạng xã hội (TikTok, Facebook, Shopee, v.v.)
Kỹ năng chuyên môn: [''Sử dụng mạng xã hội (TikTok, Facebook, Shopee)'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Nhiệt tình'', ''Có trách nhiệm trong công việc'']', 'PART_TIME', 'ONSITE', 'quảng ninh', 'Quảng Ninh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Ca 1: 8h-18h, Ca 2: 18-24h30, Ca 3: 18-1 sáng (sau 00h x2 lương)', '[''Môi trường làm việc năng động, thân thiện'', ''Cơ hội học hỏi kỹ năng bán hàng'', ''Thưởng + Phụ cấp'', ''Để xe tại công ty'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (180, 10, 7, 'Nhà thiết kế đồ họa (thực tập)', 'Vị trí: Intern Graphic DesignerSố lượng: 01 - Thiết kế các ấn phẩm truyền thông kỹ thuật số (Facebook, Instagram, YouTube…) theo Key Visual của thương hiệu. - Edit video marketing cơ bản phục vụ các chiến dịch Digital. - Tham gia đóng góp ý tưởng và hỗ trợ triển khai các hoạt động Marketing. - Hỗ trợ một số công việc Marketing khác theo sự phân công từ Leader.', '- Sinh viên năm cuối đã hoàn tất chương trình học chuyên ngành Thiết kế, Marketing, Truyền thông hoặc các ngành liên quan. - Thành thạo phần mềm Adobe chuyên dụng: Illustrator, Photoshop, Premiere. - Phong cách thiết kế hiện đại, phù hợp với lĩnh vực công nghệ làm đẹp. - Kỹ năng giao tiếp tiếng Anh ở mức khá trở lên (Nghe – Nói – Đọc – Viết). - Tư duy sáng tạo, chủ động học hỏi, có định hướng phát triển trong mảng Digital Marketing. - Năng động, nhiệt huyết, cầu tiến, có trách nhiệm với công việc. - Có laptop cá nhân phục vụ công việc. - Không nhận ứng viên làm việc online. - Thời gian thực tập: 03 tháng.
Kỹ năng chuyên môn: [''Adobe Illustrator'', ''Adobe Photoshop'', ''Adobe Premiere'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tiếng Anh'', ''Tư duy sáng tạo'', ''Chủ động học hỏi'', ''Năng động'', ''Nhiệt huyết'', ''Có trách nhiệm với công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Trợ cấp thực tập: tối đa 5 triệu đồng/tháng'', ''Phụ cấp ăn trưa'', ''Phụ cấp gửi xe'', ''Phụ cấp đi lại'', ''Hỗ trợ dấu mộc thực tập'', ''Được đào tạo bài bản về thiết kế và edit video'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (181, 2, 7, 'Thực Tập Sinh Thiết Kế Đồ Họa', 'Hỗ trợ thiết kế các mẫu quảng cáo trên kênh digital marketing (website, facebook, google…) như facebook post, banner, clip... Thiết kế các ấn phẩm truyền thông cho công ty: logo, banner, tờ rơi, brochure,... Edit video, dựng video theo các kịch bản có sẵn; Chỉnh sửa và thiết kế ảnh theo yêu cầu; Thành thạo các phần mềm thiết kế như Photoshop, Illustrator,... Có kỹ năng cơ bản của các phần mềm chỉnh sửa video: AE, PR.', 'Sinh viên năm 3 trở lên các chuyên ngành về thiết kế đồ họa, mỹ thuật công nghiệp, truyền thông đa phương tiện... Sử dụng được các ứng dụng, công cụ thiết kế đồ họa: Adobe illustrator, Indesign…; chỉnh sửa ảnh: Adobe Photoshop, Lightroom...; xử lý video cơ bản: Adobe Premiere, After Effects… Có khả năng sáng tạo trong thiết kế; Có các kỹ năng mềm: tư duy marketing, tổ chức, làm việc nhóm, làm việc độc lập…
Kỹ năng chuyên môn: [''Adobe Illustrator'', ''Adobe InDesign'', ''Adobe Photoshop'', ''Adobe Lightroom'', ''Adobe Premiere'', ''After Effects'']
Kỹ năng mềm: [''Sáng tạo trong thiết kế'', ''Tư duy marketing'', ''Tổ chức'', ''Làm việc nhóm'', ''Làm việc độc lập'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), linh hoạt thời gian làm việc', '[''Môi trường làm việc năng động, thân thiện, chuyên nghiệp'', ''Cơ hội học hỏi phát triển chuyên môn'', ''Tham gia CLB free các câu lạc bộ: đá bóng, cầu lông'', ''Thưởng tháng 13'', ''Được cấp máy tính'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (182, 3, 7, 'Video Editor Freelance', 'Dựng các video ngắn (Reels/TikTok) từ source có sẵn (hình ảnh, video) theo brief đã thống nhất. Sản xuất nội dung cho các kênh: Facebook/Instagram (dùng chung source). TikTok (có thể khai thác thêm source mới để phù hợp nền tảng). Đảm bảo video cuốn hút, đúng chủ đề, đúng deadline.', 'Kinh nghiệm tối thiểu 06 tháng trong lĩnh vực dựng video, đặc biệt là Reels/TikTok. Sử dụng thành thạo ít nhất một phần mềm dựng video như CapCut, Premiere, After Effects, v.v. Có gu thẩm mỹ hình ảnh, nắm bắt xu hướng nhanh, sáng tạo. Có khả năng làm việc độc lập, đúng deadline, giao tiếp tốt khi nhận brief.
Kỹ năng chuyên môn: [''CapCut'', ''Premiere'', ''After Effects'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Làm việc độc lập'', ''Sáng tạo'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Thù lao cạnh tranh hấp dẫn'', ''Làm việc linh hoạt, không gò bó thời gian'', ''Cơ hội cộng tác lâu dài nếu phù hợp'', ''Được mua Nội thất với giá ưu đãi'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (183, 7, 7, 'Cộng Tác Viên Kinh Doanh', 'Tìm kiếm, khai thác và phát triển khách hàng tiềm năng. Tư vấn, giới thiệu sản phẩm/dịch vụ chuyên về ''Gói marketing tích hợp A.I'' của công ty đến khách hàng. Thực hiện các hoạt động đàm phán và ký kết hợp đồng. Chăm sóc khách hàng sau bán hàng, duy trì mối quan hệ lâu dài. Thực hiện các báo cáo theo yêu cầu của cấp trên.', 'Có kỹ năng giao tiếp, thuyết phục và đàm phán tốt. Có tư duy logic, khả năng làm việc độc lập và làm việc nhóm. Đam mê kinh doanh, có tinh thần cầu tiến và ham học hỏi. Ưu tiên các bạn là sinh viên các trường CĐ, ĐH ngành QTKD, Truyền thông, Marketing, Quan hệ công chúng... hoặc người có đam mê/ động lực kiếm tiền cao.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'', ''Kỹ năng đàm phán'']
Kỹ năng mềm: [''Tư duy logic'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Đam mê kinh doanh'', ''Tinh thần cầu tiến'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.5 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 09:00 đến 12:00)', '[''Lương, thưởng thỏa thuận theo năng lực và theo doanh số'', ''Được đào tạo bài bản về sản phẩm, kỹ năng bán hàng'', ''Tham gia vào các hoạt động, quy trình sản xuất video/hình ảnh'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (184, 8, 7, 'Thực Tập Sinh Media Quay, Dựng', '- Hỗ trợ set đèn, quay, xử lý màu, dựng clip truyền thông social - Phối hợp với bộ phận Content, designer xây dựng ý tưởng quay dựng. - Tham gia các hoạt động của Team marketing - Lập báo cáo định kỳ. - Các công việc liên quan theo sự phân công của người hướng dẫn.', '- Trình độ học vấn: Sinh viên năm cuối hoặc mới tốt nghiệp Cao đẳng, Đại học ở các chuyên ngành truyền thông đa phương tiện, designer, marketing hoặc các chuyên ngành liên quan. - Có gu thẩm mỹ, nhiều ý tưởng trong quay dựng, cảm âm tốt. - Làm việc nhóm. - Chỉnh chu, cẩn thận, có trách nhiệm. - Gửi kèm portfolio - Thời gian đến công ty: 2 buổi/ tuần (có thể đến Cty nhiều hơn theo nhu cầu)
Kỹ năng chuyên môn: [''Dựng phim'', ''Quay phim'', ''Kỹ năng sử dụng camera'', ''Hiểu biết về ánh sáng, âm thanh'', ''Sử dụng phần mềm chỉnh sửa video (Premiere Pro, Final Cut Pro, Davinci Resolve, v.v.)'']
Kỹ năng mềm: [''Có gu thẩm mỹ'', ''Nhiều ý tưởng trong quay dựng'', ''Cảm âm tốt'', ''Làm việc nhóm'', ''Chỉnh chu'', ''Cẩn thận'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 3 (từ 08:00 đến 17:00), Thứ 5 (từ 08:00 đến 17:00)', '[''Được sử dụng máy ảnh, thiết bị chuyên nghiệp'', ''Được hướng dẫn bởi các Anh/Chị giàu kinh nghiệm'', ''Môi trường làm việc hiện đại, với đội ngũ marketing trẻ tuổi, chuyên nghiệp'', ''Cơ hội phát triển lên các vị trí chính thức sau thời gian thực tập'', ''Xác nhận thực tập: có'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (185, 9, 7, 'Giảng Viên Thiết Kế Đồ Họa', 'Hợp tác theo hình thức part time (linh động lịch đáp ứng giảng dạy theo 3 ca: sáng, chiều hoặc tối). Phối hợp cùng đội ngũ nhân sự của Trường để tham mưu, cố vấn biên soạn giáo án, giáo trình, tài liệu giảng dạy theo tiêu chuẩn. Tham gia công tác giảng dạy phù hợp với thế mạnh chuyên môn Thiết kế Đồ họa.', 'Tốt nghiệp các trường đào tạo chuyên ngành Thiết kế, mỹ thuật, đồ họa,... trong và ngoài nước. Có kinh nghiệm thực tế về Thiết kế đồ họa hoặc có bằng cấp, chứng chỉ liên quan đến Thiết kế. Thế mạnh chuyên môn: vẽ tay, phác thảo, phát triển ý tưởng sáng tạo... Có kinh nghiệm làm việc qua các phần mềm: Indesign, Dimension, UX/UI. Ưu tiên ứng viên có 2-3 năm kinh nghiệm tối thiểu ở vị trí: Trưởng nhóm/ Trưởng phòng Thiết kế hoặc có kinh nghiệm giảng dạy Thiết kế đồ họa tại các trường/trung tâm đào tạo, doanh nghiệp.
Kỹ năng chuyên môn: [''Indesign'', ''Dimension'', ''UX/UI'']
Kỹ năng mềm: [''Vẽ tay'', ''Phác thảo'', ''Phát triển ý tưởng sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 25000000.00, '15.0 - 25.0 triệu', 'Linh động lịch giảng dạy từ thứ 2 đến thứ 7, theo 3 ca: Sáng: 8h30 - 11h30, Chiều: 13h30 - 16h30, Tối: 18h00 - 21h00', '[''Lộ trình phát triển cụ thể, rõ ràng'', ''Chế độ chăm sóc Giảng viên: sinh nhật, hiếu hỉ, ốm đau...'', ''Du lịch, teambuilding Giảng viên hàng năm'', ''Các hoạt động truyền thông nội bộ định kì: Lễ Tri ân Giảng viên 20/11, Workshop, Talkshow...'', ''Chế độ thưởng, chăm sóc sức khỏe, đào tạo nội bộ...'', ''Công tác phí'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (186, 10, 7, 'Thực Tập Sinh Edit Video, Graphic Designer', 'Thực tập sinh Edit video: Quay dựng video ngắn: TikTok, Reels, Viral video, Video sản phẩm, Video dự án,... Tối ưu định dạng trên từng nền tảng. Phối hợp với bộ phận liên quan lên ý tưởng cách quay, dựng video. Thực tập sinh chỉnh sửa hình ảnh, thiết kế đồ họa: Chụp ảnh, chỉnh sửa ảnh sản phẩm. Thiết kế nội dung hình ảnh cho các kênh Social. Thiết kế ấn phẩm truyền thông: poster, banner, hình ảnh social media,.. Phối hợp cùng team marketing và sale để lên ý tưởng hình ảnh, video theo từng chiến dịch cụ thể.', '• Sinh viên năm cuối hoặc mới tốt nghiệp các ngành Marketing, Truyền thông, Thiết kế đồ họa,...các ngành liên quan • Đã có dự án cá nhân • Có laptop cá nhân • Thời gian thực tập: Tối thiểu 3 tháng. Sau thời gian thực tập được cân nhắc lên làm nhân viên chính thức • Có khả năng sáng tạo nội dung phù hợp với từng nhóm người dùng. • Kỹ năng giao tiếp và tương tác xã hội tốt • Biết sử dụng các công cụ chỉnh sửa hình ảnh video, biết sử dụng máy ảnh
Kỹ năng chuyên môn: [''Sử dụng các công cụ chỉnh sửa hình ảnh video'', ''Biết sử dụng máy ảnh'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Tương tác xã hội'', ''Sáng tạo nội dung'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Từ thứ 2 – thứ 6, linh động', '[''Thưởng thêm theo hiệu suất làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (187, 2, 7, 'Thực Tập Sinh Content Marketing', '- Lên ý tưởng, sáng tạo nội dung trên các nền tảng mạng xã hội để quảng bá thương hiệu và dịch vụ: Youtube, Tiktok, Facebook, Fanpage... - Lên timeline nội dung quảng bá dịch vụ và đăng trên các phương tiện truyền thông Công ty giao. - Lên kịch bản quay dựng clip quảng bá thương hiệu trên các kênh như tiktok, youtube… - Báo cáo cập nhật kết quả với quản lý trực tiếp.', '- Sinh viên năm 4 hoặc mới ra trường. - Có laptop riêng, điện thoại riêng - Có khả năng phát triển ý tưởng, kịch bản, hậu kỳ và triển khai các nội dung dạng video ngắn. - Có tư duy nhạy bén, sáng tạo, nhanh chóng nắm bắt xu hướng. - Biết khai thác tài nguyên có sẵn trên Internet để đáp ứng công việc (hình ảnh, video...). - Thành thạo các công cụ edit video. - Quyết tâm để hoàn thành mục tiêu, có khả năng làm việc độc lập. - Có khả năng thấu hiểu thị trường để tạo bài quảng cáo phù hợp.
Kỹ năng chuyên môn: [''Thành thạo các công cụ edit video'']
Kỹ năng mềm: [''Có khả năng phát triển ý tưởng'', ''Tư duy nhạy bén'', ''Sáng tạo'', ''Có khả năng làm việc độc lập'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:00)', '[''Dấu thực tập'', ''Môi trường làm việc chuyên nghiệp, năng động và thân thiện'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (188, 3, 7, 'Thực Tập Sinh Video Editor', 'Phối hợp với Content Creator lên kế hoạch ý tưởng, nội dung cho các video theo từng chiến dịch của công ty. Dựng và chỉnh sửa video, cắt ghép âm thanh, hình ảnh nội dung cho video. Các công việc khác được cấp trên giao phó. Phối hợp với các phòng ban làm các nhiệm vụ liên quan.', 'Sử dụng tốt các phần mềm chỉnh sửa video. (Capcut) Có khả năng sáng tạo video viral dưa trên Content. Xử lý công việc thông minh, nhanh nhẹn, chăm chỉ, có trách nhiệm trong công việc, ham học hỏi. Biết sử dụng các công cụ AI theo yêu cầu công việc.
Kỹ năng chuyên môn: [''Sử dụng phần mềm chỉnh sửa video (Capcut)'', ''Biết sử dụng các công cụ AI'']
Kỹ năng mềm: [''Khả năng sáng tạo'', ''Xử lý công việc thông minh'', ''Nhanh nhẹn'', ''Chăm chỉ'', ''Có trách nhiệm trong công việc'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00), thời gian linh hoạt theo ca học', '[''Mức lương thỏa thuận tại buổi phỏng vấn'', ''Có cơ hội được nhận vào làm việc chính thức tại Công ty'', ''Làm việc trong môi trường trẻ, năng động và sáng tạo'', ''Hỗ trợ các vấn đề phát sinh liên quan đến nhà trường'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (189, 7, 7, 'Nhân Viên Thời Vụ Seller Engagement (Socical)', 'Phân loại thông tin có sẵn trên các nhóm Facebook thành các nhóm theo hướng dẫn. Cập nhật nội dung, hình ảnh, bài viết trên website theo yêu cầu. Chỉnh sửa bài viết theo nhu cầu của người bán hàng. Gửi yêu cầu và theo dõi các design hình ảnh, gif với team internal.', 'Có kiến thức về social, hội nhóm Facebook. Có kinh nghiệm tổng hợp data trên Facebook group. Tiếng Anh cơ bản. Thành thạo tin học văn phòng: Excel, Google Sheet, ... Tỉ mỉ, cẩn thận, trung thực, chịu khó, linh động, không ngại di chuyển, có thời gian trống đảm bảo được công việc.
Kỹ năng chuyên môn: [''Tin học văn phòng: Excel, Google Sheet'']
Kỹ năng mềm: [''Tỉ mỉ'', ''Cẩn thận'', ''Trung thực'', ''Chịu khó'', ''Linh động'', ''Không ngại di chuyển'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '9h-18h (nghỉ trưa 1 tiếng), làm việc 5 ngày/tuần', '[''Chi lương theo tuần, nhận vào thứ 7 hàng tuần'', ''Được đào tạo, hướng dẫn công việc khi vào làm'', ''Được trang bị đầy đủ các công cụ, trang thiết bị phục vụ công việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (190, 8, 7, 'Thực Tập Sinh Digital Marketing', 'Chúng tôi đang tìm kiếm Thực Tập Sinh Digital Marketing năng động và đam mê để tham gia vào đội ngũ Marketing của công ty. Vị trí này sẽ cung cấp cho bạn cơ hội học hỏi và thực hành trong môi trường thực tế, hỗ trợ các hoạt động marketing số và giúp phát triển các chiến dịch quảng bá thương hiệu cho chuỗi siêu thị và quán café. Trách nhiệm chính: 1. Hỗ trợ quản lý nội dung: - Tham gia vào việc tạo nội dung cho các nền tảng kỹ thuật số như website, blog, và mạng xã hội. - Hỗ trợ chỉnh sửa và tối ưu hóa nội dung để đạt hiệu quả cao nhất. 2. Quản lý mạng xã hội: - Hỗ trợ đăng bài và theo dõi các hoạt động trên các kênh mạng xã hội của công ty như Facebook, Instagram, Zalo, và TikTok. - Tham gia vào việc quản lý lịch đăng bài và tương tác với người dùng trên các nền tảng này. 3. Phân tích dữ liệu: - Hỗ trợ theo dõi và phân tích các chỉ số hiệu quả của chiến dịch Digital Marketing. - Tham gia vào việc báo cáo và đưa ra các đề xuất cải thiện dựa trên dữ liệu thu thập. 4. Hỗ trợ các chiến dịch quảng cáo trực tuyến: - Hỗ trợ triển khai các chiến dịch quảng cáo trên Google, Facebook, và các kênh khác. - Giám sát và đánh giá hiệu quả của các chiến dịch để đưa ra điều chỉnh kịp thời. 5. Nghiên cứu thị trường: - Thực hiện các nghiên cứu thị trường để cập nhật xu hướng mới nhất trong ngành và đề xuất ý tưởng sáng tạo cho các chiến dịch marketing.', 'Trình độ học vấn: Sinh viên 3, năm cuối hoặc mới tốt nghiệp các ngành Marketing, Truyền thông, Quản trị Kinh doanh, hoặc các lĩnh vực liên quan. - Kỹ năng: - Có hiểu biết cơ bản về Digital Marketing và các công cụ như Google Analytics, Facebook Ads là một lợi thế. - Kỹ năng viết tốt, sáng tạo và có khả năng diễn đạt ý tưởng một cách rõ ràng. - Có tinh thần học hỏi, cẩn thận, và trách nhiệm trong công việc. - Có khả năng sáng tạo nội dung trên các nền tảng social. - Khả năng làm việc nhóm tốt.
Kỹ năng chuyên môn: [''Google Analytics'', ''Facebook Ads'']
Kỹ năng mềm: [''Kỹ năng viết tốt'', ''Sáng tạo'', ''Có khả năng diễn đạt ý tưởng một cách rõ ràng'', ''Có tinh thần học hỏi'', ''Cẩn thận'', ''Trách nhiệm trong công việc'', ''Khả năng làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'tp buôn ma thuột', NULL, 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Cơ hội học hỏi và phát triển kỹ năng trong môi trường làm việc thực tế'', ''Được hướng dẫn và đào tạo bởi các chuyên gia trong lĩnh vực Digital Marketing'', ''Có cơ hội trở thành nhân viên chính thức sau khi kết thúc thực tập'', ''Hỗ trợ dấu thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (191, 9, 7, 'Thiết kế đồ họa thực tập', 'Hỗ trợ team Design thiết kế các ấn phẩm theo các chương trình khuyến mãi. Hỗ trợ team Content thực hiện các ấn phẩm trên các trang Social. Tham gia brainstorm để phát triển ideas và định hướng thiết kế. Chủ động cập nhật xu hướng thiết kế và tăng cường khả năng tư duy phản biện.', 'Sinh viên học kỳ cuối hoặc đang đợi bằng, đã tốt nghiệp… Có thể thực tập fulltime. Biết sử dụng công cụ Photoshop, Illustrator, AE. Có tư duy thiết kế để phát triển ý tưởng. Có tinh thần và thái độ tốt, có ý muốn cầu tiến trong công việc.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''AE'']
Kỹ năng mềm: [''Tư duy thiết kế'', ''Tinh thần cầu tiến'', ''Thái độ tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Fulltime', '[''Hỗ trợ lương thực tập'', ''Dấu mộc thực tập'', ''Cơ hội phát triển lên nhân viên thử việc'', ''Hướng dẫn, đào tạo chuyên môn về thiết kế'', ''Môi trường làm việc trẻ trung, năng động, sáng tạo'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (192, 10, 7, 'Thực Tập Sinh Graphic Design', 'Lên ý tưởng và thiết kế các ấn phẩm truyền thông phục vụ cho hoạt động quảng cáo, nội dung website, social media như banner, cover, infographics, v.v. Phối hợp với content writer để tạo ra các sản phẩm thiết kế phù hợp với nội dung của blog, email marketing, các trang mạng xã hội của công ty. Chụp ảnh sản phẩm và các hoạt động của công ty. Thực hiện các công việc khác liên quan dưới sự phân công của người hướng dẫn.', 'Sinh viên năm cuối hoặc mới tốt nghiệp ngành thiết kế đồ họa, mỹ thuật hoặc liên quan (ưu tiên có thể làm việc fulltime). Thời gian thực tập ít nhất 3 tháng. Thành thạo các phần mềm thiết kế: Adobe Photoshop, Adobe Premiere, Indesign,... Có Laptop cá nhân. Khả năng tư duy sáng tạo, thẩm mỹ tốt. Thái độ tích cực, chủ động học hỏi.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Premiere'', ''Indesign'']
Kỹ năng mềm: [''Khả năng tư duy sáng tạo'', ''Thẩm mỹ tốt'', ''Thái độ tích cực'', ''Chủ động học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 09:00 đến 12:00)', '[''Hỗ trợ dấu mộc thực tập'', ''Học hỏi và phát triển kỹ năng'', ''Cơ hội gắn bó lâu dài với công ty'', ''Môi trường làm việc trẻ trung, năng động và sáng tạo'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (193, 2, 7, 'Nhân Viên Sales-Marketing Part-Time - Dự Án Miapet', 'Di chuyển đến các cửa hàng thú cưng để giới thiệu và tư vấn về sản phẩm/dịch vụ của MiaPet. Giải thích cơ bản về nền tảng và lợi ích khi sử dụng MiaPet. Mời hợp tác và hỗ trợ cửa hàng đăng ký tài khoản. Mỗi ngày tối thiểu ghé thăm 3 cửa hàng. Báo cáo kết quả công việc hằng ngày.', 'Yêu thích thú cưng, có thiện cảm với ngành chăm sóc thú cưng. Giao tiếp tốt, tự tin, chăm chỉ và chủ động trong công việc. Không ngại di chuyển, có smartphone hỗ trợ thao tác nhanh. Ưu tiên sinh viên hoặc người có kinh nghiệm bán hàng, giới thiệu sản phẩm.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Tự tin'', ''Chăm chỉ'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Làm việc trong môi trường năng động, linh hoạt, không gò bó'', ''Được tiếp cận kiến thức về ngành thú cưng và kỹ năng giao tiếp, bán hàng'', ''Cơ hội mở rộng mạng lưới, tiếp cận nhiều đối tác trong ngành'', ''Hỗ trợ giấy tờ, xác nhận thực tập đầy đủ nếu cần'', ''Là bước đệm tốt nếu bạn muốn theo đuổi các vị trí chính thức sau này'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (194, 3, 7, 'Cộng Tác Viên Video Editor', '- Thiết kế ảnh & dựng video ngắn theo nội dung có sẵn - Phối hợp với các bộ phận khác để tạo các ấn phẩm truyền thông trên các nền tảng mạng xã hội, chủ yếu là các video tin tức trên Facebook, TikTok, Youtube... - Cập nhật xu hướng của các nền tảng mạng xã hội - Thường xuyên đề xuất ý tưởng liên quan đến công việc phụ trách', '- Sinh viên đang theo học các chuyên ngành truyền thông, marketing, quảng cáo. Có thể làm việc theo hình thức part time/ remote và đảm bảo tiến độ công việc theo kế hoạch. - Sử dụng tốt các phần mềm chỉnh sửa ảnh & video cơ bản (Adobe, Capcut Pro, Canva....) - Có gu thẩm mỹ, sáng tạo, nắm bắt được xu hướng thịnh hành của các nền tảng mạng xã hội - Ưu tiên có khả năng đọc và phân tích các chỉ số quản trị trên các kênh truyền thông - Ưu tiên biết nắm bắt các quy định kiểm duyệt của các nền tảng mạng xã hội- Chủ động trong công việc và có kỹ năng làm việc nhóm
Kỹ năng chuyên môn: [''Adobe'', ''Capcut Pro'', ''Canva'']
Kỹ năng mềm: [''Có gu thẩm mỹ'', ''Sáng tạo'', ''Chủ động trong công việc'', ''Kỹ năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '5.0 - 6.0 triệu', 'Làm việc linh hoạt', '[''Hỗ trợ các chi phí học tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (195, 7, 7, 'Thực Tập Sinh Design', 'Nghiên cứu, cập nhật các xu hướng thiết kế mới nhằm nâng cao chất lượng và hiệu quả của các sản phẩm thiết kế. Phối hợp với team để đưa ra thiết kế phù hợp. Hỗ trợ thiết kế, chỉnh sửa và cập nhật các sản phẩm liên quan đến branding, bao bì, logo theo yêu cầu. Thực hiện các nhiệm vụ khác theo sự phân công của Quản lý trực tiếp.', 'Sinh viên đang theo học chuyên ngành Thiết kế Đồ họa, Truyền thông đa phương tiện hoặc các lĩnh vực liên quan. Không yêu cầu kinh nghiệm.(Ưu tiên các SV đã thực tập hoặc làm việc ngắn hạn trước đó) Có khả năng sử dụng cơ bản các phần mềm thiết kế đồ họa như AI, Adobe Illustrator, Photoshop. Cẩn thận, tỉ mỉ trong công việc và có khả năng làm việc nhóm tốt.
Kỹ năng chuyên môn: [''AI'', ''Adobe Illustrator'', ''Photoshop'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Khả năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ gửi xe'', ''Thời gian làm việc linh hoạt'', ''Cơ hội tham gia vào các dự án'', ''Được đào tạo, hướng dẫn các kỹ năng chuyên môn'', ''Hỗ trợ dấu và đánh giá trong quá trình thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (196, 8, 7, 'Thực Tập Sinh Video Editor', 'Chỉnh sửa, cắt ghép video theo format short video (TikTok, Reels). Tạo hiệu ứng, chèn text, filter, âm thanh giúp video thu hút người xem. Cập nhật phong cách dựng video đang trend trên TikTok. Tối ưu tốc độ video, giúp nội dung giữ chân người xem lâu hơn. Đảm bảo chất lượng video phù hợp với tiêu chuẩn từng level của seller.', 'Biết sử dụng ít nhất 1 công cụ dựng video trên Premiere Pro, CapCut, After Effects,... Có khả năng quay cơ bản. Biết sử dụng AI hỗ trợ cắt ghép video để tối ưu tốc độ làm việc. Có tư duy sáng tạo, khả năng bắt trend tốt. Làm việc nhanh, đáp ứng deadline. Có laptop cá nhân để phục vụ công việc.
Kỹ năng chuyên môn: [''Premiere Pro'', ''CapCut'', ''After Effects'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Khả năng bắt trend'', ''Làm việc nhanh'', ''Đáp ứng deadline'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', '8h00 - 12h00 và 13h30 - 17h30 từ Thứ 2 - Thứ 6 và 50% Thứ 7 trong tháng', '[''Hỗ trợ thực tập'', ''Hỗ trợ dấu mộc'', ''Được hưởng các chính sách phúc lợi theo quy định của công ty'', ''Được đào tạo, nâng cao nghiệp vụ thường xuyên'', ''TGIF, tiệc sinh nhật, thâm niên, company meeting hàng tháng và tham gia các câu lạc bộ của công ty'', ''Có cơ hội trở thành nhân viên chính thức sau kỳ thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (197, 9, 7, 'Thực Tập Sinh Content Marketing', 'Hỗ trợ triển khai sáng tạo nội dung (Reel, video short...) trên đa kênh: Facebook, Instagram. Phối hợp với bộ phận media sáng tạo các kịch bản, ấn phẩm chất lượng đăng tải trên các nền tảng( nội dung, hình ảnh, video...). Research các idea từ nhiều nguồn, video content xu hướng global đề xuất cho kênh mình phụ trách. Học hỏi làm video, chỉnh sửa bằng các công cụ, ứng dụng AI vào công việc. Xây kênh và kéo traffic cho kênh về website. Hợp tác cùng Leader team và hổ trợ các thành viên trong team. Thực hiện công việc và hoàn thành theo phân công của Leader.', 'Sinh viên năm 2-4 các trường Cao đẳng - Đại học, thuộc các chuyên ngành: Truyền thông, Marketing, Báo Chí, QTKD... Sáng tạo, tư duy ngôn ngữ & hình ảnh tốt, thường xuyên cập nhật các xu hướng mới. Kỹ năng hiểu và sáng tạo nội dung đa nền tảng: Facebook, Instagram. Thái độ cầu tiến, mong muốn được học hỏi, chủ động tìm hiểu, tích cực trau dồi.
Kỹ năng chuyên môn: [''Kỹ năng hiểu và sáng tạo nội dung đa nền tảng: Facebook, Instagram.'']
Kỹ năng mềm: [''Sáng tạo'', ''Tư duy ngôn ngữ & hình ảnh tốt'', ''Thái độ cầu tiến'', ''Mong muốn được học hỏi'', ''Chủ động tìm hiểu'', ''Tích cực trau dồi'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 2000000.00, '0.5 - 2.0 triệu', 'Thứ 2 đến thứ 7 (làm xen kẽ 2 thứ 7/tháng) - Sáng: 8h00-12h00 - Chiều: 13h30-17h30', '[''Hỗ trợ cơ bản (theo bậc 500.000 - 1.000.000 Vnđ) + thưởng kết quả mang lại (thu nhập từ 500.000 - 2.000.000 Vnđ/tháng)'', ''Được cung cấp dấu mộc và số liệu, đồng thời hỗ trợ chữ ký, đánh giá để hoàn thành các bài báo cáo, khoá luận tốt nghiệp.'', ''Được tự đăng ký lịch thực tập theo lịch học (tối thiểu -5 buổi/tuần).'', ''Được cung cấp sẵn tài khoản (page + kênh).'', ''Được đào tạo về kĩ năng làm thị trường Global, có cơ hội học hỏi và tiếp xúc với môi trường doanh nghiệp.'', ''Được đào tạo ứng dụng AI vào công việc Content, Marketing.'', ''Được trang bị đầy đủ công cụ phần mềm, hệ thống tài khoản, ứng dụng AI để thực tập.'', ''Cơ hội lên nhân viên chính thức, làm việc trong môi trường thương mại điện tử toàn cầu năng động, có nhịp độ nhanh.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (198, 10, 7, 'Nhà thiết kế đồ họa thực tập', 'Hỗ trợ thiết kế các ấn phẩm truyền thông như banner, poster, social post, infographic, gif,… Tham gia vào quá trình lên ý tưởng, phác thảo và thiết kế sản phẩm theo yêu cầu của các phòng ban. Hỗ trợ chỉnh sửa, hoàn thiện các thiết kế theo feedback. Thực hiện các công việc liên quan đến hình ảnh thương hiệu trên các kênh truyền thông. Cập nhật xu hướng thiết kế mới, đề xuất ý tưởng sáng tạo để nâng cao chất lượng sản phẩm. Phối hợp với các thành viên trong team để đảm bảo tiến độ và chất lượng công việc.', 'Sinh viên năm 2,3,4 hoặc mới tốt nghiệp các ngành Thiết kế đồ họa, Mỹ thuật, Truyền thông hoặc các ngành liên quan. Thành thạo các phần mềm thiết kế: Adobe Photoshop, Illustrator (biết thêm After Effects/Premiere là một lợi thế). Có tư duy thẩm mỹ tốt, sáng tạo và đam mê với thiết kế. Khả năng làm việc độc lập và làm việc nhóm tốt. Có laptop cá nhân phục vụ công việc.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'', ''After Effects'', ''Premiere'']
Kỹ năng mềm: [''Tư duy thẩm mỹ tốt'', ''Sáng tạo'', ''Đam mê với thiết kế'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 17:00)', '[''Môi trường làm việc hiện đại, năng động, khuyến khích tối đa sự sáng tạo của nhân viên'', ''Thời gian làm việc linh động, Partime tối thiểu 5 buổi/tuần'', ''Hỗ trợ dấu mộc và tài liệu thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (199, 2, 7, 'Nhà thiết kế sáng tạo thực tập', 'Epic Journal đang tìm kiếm một thực tập sinh thiết kế sáng tạo để mang lại trải nghiệm kể chuyện và du lịch vào cuộc sống thông qua thiết kế. Trách nhiệm chính bao gồm tạo sàn đề xuất và bộ dụng cụ bán hàng, thiết kế các bộ sưu tập du lịch và tạo hình ảnh cho các nền tảng truyền thông xã hội.', 'Passion & Love in Traveling, if you believe in our motto “Travel is Transformation”. Be creative to and dare to step out of your comfort zone everyday. Be open minded to work alongside with AI. Proficiency in Adobe Illustrator, Photoshop, and InDesign.
Kỹ năng chuyên môn: [''Adobe Illustrator'', ''Photoshop'', ''InDesign'']
Kỹ năng mềm: [''Creativity'', ''Open-mindedness'', ''Ability to work independently and in a team'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Internship certificate recognized both in Vietnam and the UK'', ''Direct pathway to enter the luxury travel & education industry'', ''Financial support and on-the-job training'', ''Continuous mentorship'', ''Opportunity to transition into a full-time role'', ''Potential recommendation and certification from UK-based company for top performers'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (200, 3, 7, 'Nhân Viên Quay Chụp Part-Time', 'Quay chụp trong các event, sự kiện hoặc chụp các ấn phẩm theo yêu cầu từ leader; Quay dựng, chỉnh sửa các video theo phân công từ team; Hỗ trợ lên kịch bản, quay dựng các video event, TVC cho trung tâm (nếu có).', 'Biết sử dụng máy ảnh, máy quay, phụ kiện quay chụp; hiểu và vận dụng được các kỹ thuật quay phim, chụp ảnh cơ bản; Biết sử dụng các phần mềm chỉnh sửa ảnh (Photoshop, Lightroom,...); Biết sử dụng các phần mềm chỉnh sửa, dựng video cơ bản (Premiere, Final Cut, Capcut,...); Ưu tiên các bạn sinh viên đã có kinh nghiệm quay dựng video cho các hoạt động của CLB, đơn vị trường học hoặc đã từng có kinh nghiệm làm việc ở vị trí tương đương tại các công ty khác.
Kỹ năng chuyên môn: [''Sử dụng máy ảnh'', ''Sử dụng máy quay'', ''Photoshop'', ''Lightroom'', ''Premiere'', ''Final Cut'', ''Capcut'']
Kỹ năng mềm: [''Làm việc độc lập'', ''Làm việc theo nhóm'', ''Tuân thủ thời gian biểu'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm việc tối thiểu 05 ca/tuần', '[''Thưởng theo KPI'', ''Được đào tạo hàng tuần các kỹ năng'', ''Học IELTS miễn phí tại IZONE'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (201, 7, 7, 'Giáo Viên Môn Kinh Doanh (Business) Bằng Tiếng Anh', '- Xây dựng phân phối chương trình môn chuyên ngành Kinh doanh Business Studies (bậc học Cambridge IGCSE/AS/A Level) của các lớp đầu năm học (bao gồm phân phối chương trình long term, medium term/syllabus và short term plan của môn học) đối với học sinh bậc THPT (Lớp 9-12). - Trực tiếp giảng dạy môn học Kinh doanh/Business Studies (dạy bằng tiếng Anh) theo phân phối chương trình và thời khóa biểu được phân công phù hợp với lịch của giáo viên. - Xậy dựng và lưu trữ theo quy định giáo án môn Kinh doanh/ Business Studies (Cambridge IGCSE/AS/A Level) (bao gồm giáo án, slide học tập, work sheet...), bảo đảm bộ giáo án đảm đúng phân phối chương trình, đúng năng lực học sinh, có điều chỉnh phù hợp yêu cầu học tập thực tế từng lớp học; - Soạn bài kiểm tra/Unit Test môn Kinh doanh/Business Studies (bậc học Cambridge IGCSE/AS/A Level). - Soạn đề kiểm tra môn Kinh doanh/ Business Studies (bậc học Cambridge IGCSE/AS/A Level) trong năm học bao gồm 04 đề (bao gồm đề dự phòng): giữa kỳ và cuối kỳ học kỳ 1 và học kỳ 2; - Bồi dưỡng, hỗ trợ và luyện tập phù hợp cho học sinh trong quá trình học tập và trước các kì thi của môn học Business Studies/Kinh doanh. - Tutor cho học sinh 1-2 buổi/tuần (mỗi buổi khoảng 30’ – 45''); - Theo dõi học sinh học và điều chỉnh chương trình học/giáo án phù hợp với năng lực học sinh từng lớp theo môn học; - Tham gia xây dựng hoàn thiện chương trình quốc tế đặc thù ;', '- Tiến sĩ/Thạc sĩ ngành Kinh doanh/Kinh tế học/Marketing hoặc các ngành khác có liên quan. - Có kinh nghiệm học tập, làm việc ở nước ngoài là một lợi thế. - Năng lực ngôn ngữ tiếng Anh phù hợp giảng dạy, tương đương IELTS 6.5 trở lên; - Kinh nghiệm giảng dạy là lợi thế; - Tận tâm với học sinh và nghề dạy học. - Có kinh nghiệm đứng lớp là một lợi thế.
Kỹ năng chuyên môn: [''Năng lực ngôn ngữ tiếng Anh tương đương IELTS 6.5 trở lên'']
Kỹ năng mềm: [''Tận tâm với học sinh và nghề dạy học'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 30000000.00, '15.0 - 30.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Lương cạnh tranh, theo năng lực thực tế và tiết dạy'', ''Hỗ trợ cung cấp chương trình và xây dựng giáo án giảng dạy'', ''Hỗ trợ chi phí đi lại đến trường học'', ''Bảo hiểm y tế, bảo hiểm thất nghiệp, bảo hiểm xã hội'', ''Khám sức khoẻ định kỳ'', ''Thưởng học kì, thưởng Tết và hỗ trợ sự kiện'', ''Ăn trưa'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (202, 8, 7, 'Thực Tập Sinh Marketing', 'Chúng tôi đang tìm kiếm thực tập sinh Marketing năng động, sáng tạo và yêu thích mạng xã hội để cùng đồng hành và phát triển thương hiệu trên nền tảng số. Cụ thể, bạn sẽ: - Quản lý fanpage Facebook: - Đăng bài viết theo kế hoạch nội dung - Trả lời bình luận, tin nhắn khách hàng - Phối hợp thiết kế hình ảnh đơn giản bằng Canva (nếu biết) - Làm nội dung TikTok: - Lên ý tưởng video ngắn liên quan đến sản phẩm/dịch vụ - Quay và dựng video (có thể hỗ trợ công cụ & hướng dẫn) - Theo dõi hiệu quả video và đề xuất cải tiến - Tham gia xây dựng chiến lược nội dung: - Góp ý tưởng sáng tạo cho các chiến dịch truyền thông - Phối hợp team thực hiện mini game, chương trình viral...', 'Sinh viên các ngành Marketing, Truyền thông, Báo chí hoặc các ngành liên quan Biết sử dụng Facebook, TikTok thành thạo Có kỹ năng viết caption, tư duy hình ảnh cơ bản Có khiếu thẩm mỹ, yêu thích sáng tạo nội dung Ưu tiên: Biết dựng video cơ bản bằng CapCut/InShot hoặc phần mềm tương đương
Kỹ năng chuyên môn: [''Sử dụng Facebook, TikTok thành thạo'', ''Kỹ năng viết caption'', ''Tư duy hình ảnh cơ bản'']
Kỹ năng mềm: [''Có khiếu thẩm mỹ'', ''Yêu thích sáng tạo nội dung'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Có hỗ trợ chi phí/thưởng theo hiệu quả công việc'', ''Làm việc trong môi trường trẻ trung, học hỏi nhanh'', ''Được hướng dẫn, đào tạo bài bản từ A–Z nếu chưa có kinh nghiệm'', ''Cơ hội trở thành nhân viên chính thức sau thực tập'', ''Ăn trưa'', ''Cước điện thoại'', ''Thưởng hiệu quả làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (203, 9, 7, 'Thiết kế sản xuất thực tập (bao bì B2B)', 'Nhận bản tóm tắt thiết kế từ nhóm bán hàng (logo khách hàng, số lượng, loại hộp, yêu cầu đặc biệt). Tạo các mockup trực quan với logo khách hàng để bán hàng để chia sẻ với khách hàng (sử dụng Photoshop, Illustrator hoặc các công cụ có liên quan khác). Sau khi được phê duyệt, phối hợp với nhà sản xuất in để sản xuất tác phẩm nghệ thuật cuối cùng để sản xuất. Sửa đổi và điều chỉnh các tập tin dựa trên các vấn đề phản hồi hoặc kỹ thuật từ nhà máy. Theo dõi tất cả các đơn đặt hàng B2B được gán và đảm bảo phân phối đúng, đúng giờ của mỗi tệp.', 'Proficient in Photoshop / Illustrator or equivalent design software. Meticulous, detail-focused, and well-organized under tight deadlines. Strong communication skills – able to work cross-functionally with both Sales and Production. Strongly preferred: Prior experience or academic background in Graphic Design and Printing Technology.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'']
Kỹ năng mềm: [''Meticulous'', ''Detail-focused'', ''Well-organized'', ''Strong communication skills'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Monthly stipend of 2,000,000 VND (net)'', ''20% discount at all our bakeries, cafés, and lounges'', ''TLC trial card worth 250,000 VND per month'', ''Access to team engagement and bonding activities'', ''Potential opportunity for a full-time position upon completion'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (204, 10, 7, 'Thực Tập Sinh Quản Lý Và Phát Triển Nhân Sự', 'Công việc hành chính nhân sự của công ty, tham gia vào quá trình tuyển dụng hoặc đào tạo nhân sự. Lên dự án kế hoạch phát triển tuyển dụng cho công ty: đăng tin tuyển dụng, sàng lọc hồ sơ, ... Phát triển các chương trình chiến dịch tuyển dụng thực tập sinh, hợp tác với các trường cao đẳng đại học trong và ngoài nước trong việc tuyển dụng. Hỗ trợ xử lý các công việc khác theo sự phân công của cấp trên.', 'Trình độ: Sinh viên năm 2 đến cử nhân tốt nghiệp đại học/cao đẳng chuyên ngành kinh tế, quản trị nhân sự hành chính, ... Có khả năng làm việc với thái độ làm việc tích cực và chủ động. Chủ động trong công việc, có tinh thần trách nhiệm, có tinh thần làm việc nhóm, có khả năng nghiên cứu công việc mới, thực hiện các yêu cầu từ cấp trên.
Kỹ năng mềm: [''Thái độ làm việc tích cực'', ''Chủ động trong công việc'', ''Tinh thần trách nhiệm'', ''Làm việc nhóm'', ''Khả năng nghiên cứu'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Hỗ trợ dấu mộc xác nhận thực tập'', ''Cấp giấy chứng nhận, chứng chỉ thực tập khi hoàn thành chương trình'', ''Hướng dẫn training trực tiếp'', ''Nâng cao hồ sơ profile công việc'', ''Cơ hội trở thành nhân viên chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (205, 2, 7, 'Thực tập phát triển kinh doanh', 'Thực tập sinh Business Development tại Go Media sẽ hỗ trợ đội ngũ phát triển kinh doanh trong việc xây dựng và triển khai các chiến lược mở rộng kinh doanh, với các nhiệm vụ chính bao gồm: Hỗ trợ việc tìm kiếm và xác định các khách hàng tiềm năng qua các kênh trực tuyến và ngoại tuyến. Tham gia các buổi gặp gỡ hoặc trao đổi để nắm bắt nhu cầu khách hàng và đề xuất giải pháp ban đầu. Phối hợp với đội ngũ để chuẩn bị tài liệu giới thiệu dịch vụ marketing, truyền thông, quảng cáo của Go Media. Tham gia vào việc duy trì và phát triển mối quan hệ với khách hàng hiện tại qua các hoạt động chăm sóc khách hàng. Tham gia vào các buổi brainstorming để đưa ra các giải pháp kinh doanh sáng tạo giúp khách hàng tăng cường hiệu quả. Thực hiện các báo cáo kết quả kinh doanh định kỳ, hỗ trợ phân tích và đưa ra đề xuất tối ưu hóa các mối quan hệ hợp tác.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các chuyên ngành Marketing, Truyền thông, Kinh doanh, hoặc các lĩnh vực liên quan. Có kiến thức cơ bản về marketing, truyền thông và dịch vụ khách hàng. Kỹ năng giao tiếp tốt, cởi mở và có khả năng thuyết phục. Có khả năng làm việc nhóm và phối hợp với các phòng ban hiệu quả. Tinh thần cầu tiến, ham học hỏi và chịu được áp lực công việc. Sử dụng thành thạo các công cụ MS Office (Word, Excel, PowerPoint).
Kỹ năng chuyên môn: [''Kiến thức cơ bản về marketing'', ''Truyền thông'', ''Dịch vụ khách hàng'', ''Sử dụng thành thạo các công cụ MS Office (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Cởi mở'', ''Có khả năng thuyết phục'', ''Có khả năng làm việc nhóm'', ''Phối hợp với các phòng ban hiệu quả'', ''Tinh thần cầu tiến'', ''Ham học hỏi'', ''Chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Lương cơ bản: 2,000,000 - 4,000,000 VNĐ + hoa hồng theo doanh số'', ''Được đào tạo về kỹ năng bán hàng, kiến thức sản phẩm và nghiệp vụ chuyên môn'', ''Cơ hội thăng tiến rõ ràng dựa trên năng lực'', ''Môi trường làm việc chuyên nghiệp, năng động và thân thiện'', ''Được tham gia các hoạt động team building, du lịch hàng năm'', ''Chế độ bảo hiểm theo quy định của pháp luật'', ''Thưởng các dịp Lễ, Tết và thưởng hiệu suất công việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (206, 3, 7, 'Thực Tập Sinh Video Editor', '+ Dựng, chỉnh sửa, cắt ghép video theo yêu cầu của team content. + Thêm hiệu ứng, âm thanh, hình ảnh để video thu hút hơn. + Hỗ trợ lên ý tưởng, dựng video ngắn cho nền tảng TikTok, YouTube Shorts, Facebook Reels,... + Phối hợp với team Marketing để sản xuất nội dung video phù hợp với xu hướng.', '+ Sinh viên năm 3/năm cuối ngành: MKT, PR, truyền thông,... hoặc người mới có đam mê với dựng video. + Thành thạo Canva, CapCut, hoặc các phần mềm dựng phim khác. + Biết After Effects là một lợi thế. + Có tư duy sáng tạo, nắm bắt trend nhanh. + Có laptop cá nhân. + Biết dùng chat GPT hỗ trợ công việc.
Kỹ năng chuyên môn: [''Canva'', ''CapCut'', ''After Effects'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Nắm bắt trend nhanh'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Làm việc trong môi trường sáng tạo, trẻ trung, năng động'', ''Được tham gia vào các dự án nội dung hấp dẫn cùng team'', ''Hỗ trợ chứng nhận (dấu) thực tập nếu cần'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (207, 7, 7, 'Thực Tập Sinh Thiết Kế Đồ Họa', '- Hỗ trợ thiết kế backdrop, banner bằng phần mềm Adobe Illustrator. - Khuyến khích tham gia thêm vào việc edit video, chụp ảnh, viết content (nếu có khả năng). - Hỗ trợ các hoạt động tổ chức sự kiện học sinh, hội thảo (lên kế hoạch sự kiện, hậu cần và truyền thông). - Các hoạt động khác theo phân công.', '- Sinh viên đang học năm 2,3,4, thực sự đam mê về thiết kế đồ họa, thực sự có mong muốn trải nghiệm, học hỏi công việc thực tế, để tích lũy kinh nghiệm. - Thời gian thực tập từ 4-6 tháng. Cần đáp ứng được thời gian thực tập. - Chuyên ngành theo học: Truyền thông đa phương tiện, Thiết kế, Đồ Họa, ... - Trách nhiệm, ham học hỏi, nhiệt tình, chăm chỉ.
Kỹ năng chuyên môn: [''Adobe Illustrator'']
Kỹ năng mềm: [''Trách nhiệm'', ''Ham học hỏi'', ''Nhiệt tình'', ''Chăm chỉ'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', '7:45 đến 16:45, từ thứ 2 đến thứ 6, và 2 ngày thứ 7 trong một tháng', '[''Hỗ trợ tiền 2tr (tự túc ăn) nếu fulltime, 1tr (tự túc ăn) nếu parttime'', ''Hỗ trợ ăn sáng, ăn trưa tại trường trong thời gian thực tập'', ''Nhận được thư xác nhận, dấu mộc từ trưởng đơn vị về quá trình thực tập'', ''Được trải nghiệm môi trường truyền thông giáo dục chuyên nghiệp'', ''Được đào tạo về truyền thông, tổ chức sự kiện'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (208, 8, 7, 'Thực Tập Sinh Design', 'Phụ trách mảng thiết kế trong công ty: bộ nhận diện thương hiệu, key visual cho các campaign, các artwork liên quan tới illustration 2D. Tham gia lên ý tưởng, tham gia brainstorm, tìm kiếm idea cho các dự án của công ty. Các nhiệm vụ phù hợp khác liên quan tới chuyên môn thiết kế.', 'Ưu tiên creative idea (khả năng lên ý tưởng, định hướng, thể hiện idea thông qua hình ảnh). Sử dụng thành thạo các công cụ thiết kế Adobe PTS, AI, có điểm cộng nếu biết thêm các phần mềm thiết kế khác (Id, Ae, Lr, Pr, Figma..). Kỹ năng trình bày ý tưởng, giao tiếp tốt, kỹ năng làm việc nhóm. Có thái độ làm việc tích cực, năng động, kỷ luật, cầu tiến.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'', ''Adobe InDesign'', ''Adobe After Effects'', ''Adobe Lightroom'', ''Adobe Premiere'', ''Figma'']
Kỹ năng mềm: [''Kỹ năng trình bày ý tưởng'', ''Giao tiếp tốt'', ''Kỹ năng làm việc nhóm'', ''Thái độ làm việc tích cực'', ''Năng động'', ''Kỷ luật'', ''Cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Có trợ cấp thực tập'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Được đào tạo phát triển kỹ năng chuyên môn'', ''Sếp hỗ trợ và chỉ dẫn trong công việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (209, 9, 7, 'Biên tập viên/Quay dựng bán thời gian', 'Hỗ trợ đội ngũ VJ quay chụp và dựng các clip theo từng chiến dịch truyền thông và quảng cáo tại trung tâm giáo dục về Tiếng Anh và Tin học. Làm việc với VJ/Content Creator để đưa ra sản phẩm cuối cùng cho từng chiến dịch truyền thông. Phối hợp và góp ý cùng team nội dung lên ý tưởng kịch bản và góc quay. Hoàn thành Edit tối thiểu 20 video/tháng được duyệt. Địa điểm làm việc: Tòa nhà 295 Thanh Nhàn, Hai Bà Trưng, Hà Nội hoặc làm việc tại các địa điểm phục vụ cho việc ghi hình được phân công. Thời gian: Làm việc tại trung tâm 4 ca/tuần (chủ động đăng ký ca làm việc hoặc theo sự điều phối của team leader). Có tuyển ứng viên làm online (Nếu ứng tuyển online vui lòng ghi rõ trong CV). Ứng viên vui lòng gửi portfolio/link sản phẩm video đã từng làm kèm CV khi ứng tuyển.', 'Có thiết bị quay chụp đảm bảo chất lượng hình ảnh ở mức cơ bản (Smartphone, máy ảnh, máy quay,…). Sử dụng tốt các phầm mềm edit video như Premiere, After Effects, CapCut,… Sáng tạo, chịu khó cập nhật các hot trend để ứng dụng trong edit video. Tư duy logic, bao quát công việc tốt. Có kỹ năng quay chụp và hậu kì. Đẹp trai/Hài hước là một lợi thế.
Kỹ năng chuyên môn: [''Premiere'', ''After Effects'', ''CapCut'']
Kỹ năng mềm: [''Sáng tạo'', ''Tư duy logic'', ''Chịu khó cập nhật các hot trend'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Tối thiểu đăng ký 4 ca/tuần', '[''Lương cứng: 1.000.000 VND + Lương theo sản phẩm (150.000 VND/video được duyệt)'', ''Thưởng thêm 30.000 VND/bài cho video có lượt tiếp cận tự nhiên >5000 lượt'', ''Nhận thêm hoa hồng đối với các video quảng cáo đạt hiệu quả'', ''Ưu đãi dành riêng cho nhân viên khi đến các cơ sở trực thuộc 10 Group'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (210, 10, 7, 'Thực Tập Sinh Thiết Kế', 'Thiết kế hình ảnh phục vụ cho công việc thực hiện motion graphic. Phát triển ý tưởng, sáng tạo cho storyboard từ kịch bản chữ. Hỗ trợ, tham gia thực hiện animation, motion, sound effects.', 'Biết sử dụng thành thạo các phần mềm thiết kế hình ảnh như Photoshop, Illustrator, sử dụng cơ bản phần mềm Premiere Pro, After Effects. Có tư duy sáng tạo và gu thẩm mỹ tốt. Trách nhiệm và tinh thần học hỏi cao. Yêu thích các dự án phim hoạt hình. Am hiểu và đã từng tham gia các đồ án làm clip hoạt hình là một lợi thế.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Premiere Pro'', ''After Effects'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Gu thẩm mỹ tốt'', ''Trách nhiệm'', ''Tinh thần học hỏi cao'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '8:00 - 17:00 Từ Thứ 2 - Thứ 6', '[''Phụ cấp tiền cơm trưa'', ''Phụ cấp xăng xe'', ''Tiền gửi xe'', ''Được đào tạo, hướng dẫn công việc'', ''Hỗ trợ dấu mộc, tài liệu và người hướng dẫn làm báo cáo thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (211, 2, 7, 'Thiết kế đồ họa sáng tạo thực tập', 'Hỗ trợ Senior Creative Graphic Designer 1 trong các công việc sau: Phụ trách Ấn phẩm Campaign Trade MKT, Lên idea và thống nhất idea với planner, Hoàn thành thiết kế Keyvisual cho toàn bộ campaign, Thiết kế các ấn phẩm Social còn lại theo Keyvisual chính. Phụ trách Ấn phẩm Campaign Brand MKT, Lên idea và thống nhất idea với planner, Hoàn thành thiết kế Keyvisual cho toàn bộ campaign, Thiết kế các ấn phẩm Social còn lại theo Keyvisual chính. Phụ trách Ấn phẩm Project khác, Lên idea và thống nhất idea với planner, Hoàn thành thiết kế Keyvisual cho toàn bộ campaign, Thiết kế các ấn phẩm Social còn lại theo Keyvisual chính. Phụ trách công việc khác: Phụ trách công việc khác được giao.', 'Tối thiểu sinh viên năm 3, có ấn phẩm demo là 1 lợi thế. Đam mê thiết kế, giàu ý tưởng sáng tạo, thẩm mỹ tốt, có khả năng phát triển những ý tưởng tạo hình độc đáo. Có kiến thức mỹ thuật bao gồm: bố cục, phối màu, font. Hiểu đường nét, mảng, hình khối, ánh sáng trong thiết kế. Sử dụng Thành Thạo các công cụ thiết kế PTS, AI.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'']
Kỹ năng mềm: [''Đam mê thiết kế'', ''Sáng tạo'', ''Thẩm mỹ tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Tối thiểu 6 buổi/1 tuần, Sáng: 8h30 -12h, Chiều: 13h30-18h', '[''Thưởng các ngày lễ, Tết trong năm'', ''Lương tháng 13'', ''Xét tăng lương 1-2 lần/năm'', ''Ưu đãi giá khi mua sản phẩm từ các hệ thống của công ty'', ''Tham gia các chương trình du lịch hàng năm'', ''Chế độ ăn sáng Free hàng ngày tại Canteen công ty'', ''Cung cấp laptop/Macbook làm việc'', ''Chế độ BHXH, nghỉ phép,…'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (212, 3, 7, 'Nhân Viên Media (Quay Dựng Và Edit Video)', 'Quay dựng các video truyền thông, bán hàng trên Fakebook, Tiktok. Setup bối cảnh, đạo cụ phù hợp với từng nội dung video. Sáng tạo trong cách lựa chọn góc quay, hiệu ứng chuyển động. Đã có content để làm kịch bản video.', 'Tốt nghiệp chuyên ngành thiết kế ,truyền thông, Marketing,... hoặc có kinh nghiệm thực chiến. Kinh nghiệm thực chiến từ 1 năm trở lên. Biết cách setup bối cảnh, đạo cụ phù hợp với từng nội dung video. Sáng tạo trong cách lựa chọn góc quay, hiệu ứng chuyển động. Có tư duy hình ảnh sáng tạo tốt, đột phá và khác biệt. Sử dụng thành thạo các phần mềm chỉnh sửa video (Premiere, CapCut...). Quay dựng các video truyền thông, bán hàng trên Fb, Tiktok.
Kỹ năng chuyên môn: [''Sử dụng thành thạo các phần mềm chỉnh sửa video (Premiere, CapCut...)'']
Kỹ năng mềm: [''Sáng tạo trong cách lựa chọn góc quay'', ''hiệu ứng chuyển động'', ''tư duy hình ảnh sáng tạo tốt'']', 'PART_TIME', 'ONSITE', 'nghệ an', 'Nghệ An', 'MONTHLY', 20000000.00, '10.0 - 20.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Xét tăng lương 6 tháng - 1 năm theo năng lực và tình hình hoạt động kinh doanh của công ty'', ''Lương tháng 13 và thưởng lễ, tết (theo tình hình kinh doanh của Công ty)'', ''Được tham gia BHYT, BHXH, ... theo quy định pháp luật'', ''Làm việc trong môi trường năng động, chuyên nghiệp, thân thiện và đoàn kết, có nhiều cơ hội thăng tiến'', ''Được đào tạo, nâng cao nghiệp vụ thường xuyên'', ''Được tham gia các hoạt động du lịch, teambuilding, đào tạo ngoại khóa do công ty tổ chức'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (213, 7, 7, 'Thực Tập Sinh Media Quay, Dựng', 'Quay phim, chụp ảnh, thiết kế và sản xuất hậu kỳ, dựng phim (âm thanh, hình ảnh, kỹ xảo,..) cho các clip quảng cáo của công ty và khách hàng. Kết hợp cùng team thiết kế xây dựng và lưu trữ kho video, thư viện ảnh và thông tin của công ty. Hỗ trợ các công việc liên quan đến event theo sự điều phối từ cấp trên. Chịu trách nhiệm quản lý các công cụ tác nghiệp: Máy quay, fly cam, pin, chụp hình... Ưu tiên các ứng viên có máy móc, được trả phí khi sử dụng máy cá nhân. Các công việc phát sinh khác khi được yêu cầu.', '• Học / Tốt nghiệp Đại học chuyên ngành thiết kế đồ hoạ, mỹ thuật. • Thích làm việc tại Startup Agency - Nơi công việc luôn biến động đòi hỏi tinh thần và khả năng làm việc tốc độ cao. • Có ít nhất 06 tháng kinh nghiệm ở vị trí tương đương. • Sử dụng tốt các phần mềm đồ hoạ • Biết sử dụng các phần mềm MS execl/Power Point/Outlook và quay dựng Adobe là một lợi thế. • Biết quay flycam, làm concept sản phẩm. • Có Kinh nghiệm về quay dựng, edit video ngành du lịch là một lợi thế.
Kỹ năng chuyên môn: [''Sử dụng phần mềm đồ hoạ'', ''Quay dựng video (Adobe Premiere, Final Cut Pro, Davinci Resolve)'', ''Sử dụng MS Excel, PowerPoint, Outlook'']
Kỹ năng mềm: [''Khả năng làm việc tốc độ cao'', ''Tinh thần làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Đóng BHXH và nghỉ phép, lễ Tết theo quy định'', ''Du lịch 1 lần/năm'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Cơ hội thăng tiến và được đào tạo phát triển'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (214, 8, 7, 'Thực Tập Sinh Media', 'Hỗ trợ quay phim, chụp ảnh các dự án, hoạt động của công ty hoặc dự án marketing. Thực hiện biên tập, chỉnh sửa hình ảnh và video hậu kỳ. Phối hợp với các bộ phận liên quan xây dựng nội dung đa phương tiện nhằm quảng bá sản phẩm. Báo cáo công việc hàng tuần.', 'Sinh viên năm 3, 4 chuyên ngành Truyền thông, Marketing, … hoặc các ngành có liên quan. Yêu thích công việc liên quan đến truyền thông, sự kiện, marketing. Biết chụp, quay video bằng điện thoại. Sử dụng được các phần mềm chỉnh sửa ảnh, video. Có tư duy sáng tạo, nhạy bén trong việc tìm kiếm ý tưởng. Năng động, nhanh nhẹn và có trách nhiệm. Sẵn sàng hỗ trợ quay chụp tại hiện trường tại các nhà vườn hoặc sự kiện khi cần thiết.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrators'', ''Quay Phim Và Chỉnh Sửa Video (capcut)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Làm việc nhóm'', ''Khả Năng Học Hỏi Nhanh'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Tối thiểu 4 buổi trong tuần', '[''Trợ cấp thực tập'', ''Môi trường làm việc năng động, cơ hội va chạm thực tế'', ''Hỗ trợ dấu mộc và số liệu báo cáo (nếu cần)'', ''Tham gia các hoạt động giải trí, thể thao hàng tuần của công ty'', ''Cơ hội trở thành mảnh ghép chính thức tại HiFarm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (215, 9, 7, 'Thực Tập Sinh Marketing', '- Marketing trên các nền tảng social như Tiktok, Facebook, Website dựa trên dự án công ty có sẵn. - Được trainning đầy đủ về Video Marketing, Content Marketing và Sale - Giới thiệu tư vấn căn hộ phù hợp với nhu cầu của khách hàng từ rổ hàng sẵn có của công ty. - Hỗ trợ Khách Hàng xem phòng trực tiếp tại các dự án. - Tư vấn khách hàng online theo nhu cầu Khách Hàng', '- Có các thiết bị cơ bản như xe máy, laptop, smartphone - Tinh thần nhiệt huyết tốt, chăm chỉ, kiên trì - Không yêu cầu kinh nghiệm - Học sinh, sinh viên - Không Tuyển từ sinh năm 99 trở lên - Được phụ cấp toàn bộ 100% chi phí marketing - Đồng phục, thẻ đeo, tab chứa hồ sơ free 100% - Các hoạt động đội nhóm trong tháng free 100%
Kỹ năng chuyên môn: [''Video Marketing'', ''Content Marketing'']
Kỹ năng mềm: [''Tinh thần nhiệt huyết'', ''Chăm chỉ'', ''Kiên trì'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 12000000.00, '6.0 - 12.0 triệu', '8:00 - 20:00 : Thời Gian Linh Động', '[''Được đào tạo và hướng dẫn tận tình từ các cấp quản lý'', ''Tham gia các hoạt động vui chơi thường niên'', ''Môi trường làm việc chuyên nghiệp, thân thiện, vui vẻ'', ''Lộ trình thăng tiến rõ ràng'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (216, 10, 7, 'Nhân Viên Seo Đăng Sản Phẩm', 'Đăng sản phẩm chuẩn SEO, Đăng hình ảnh sản phẩm chuẩn SEO, Làm việc cùng team SEO tăng doanh thu từ website của công ty.', 'Kinh nghiệm viết nội dung sản phẩm chuẩn SEO, Tinh thần học hỏi: Sẵn sàng cập nhật kiến thức mới về SEO và các xu hướng viết nội dung. Có kiến thức về SEO, Đam mê và có hứng thú nghề SEO.
Kỹ năng chuyên môn: [''Viết nội dung sản phẩm chuẩn SEO'', ''Kiến thức về SEO'']
Kỹ năng mềm: [''Tinh thần học hỏi'', ''Đam mê và có hứng thú nghề SEO'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '3.0 - 10.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Thưởng KPI'', ''Thưởng trực tiếp theo hiệu quả công việc'', ''Đóng dấu đỏ thực tập/ làm việc tại công ty'', ''Chứng nhận có đóng góp cho công ty'', ''Chứng nhận tham gia Global Marketing'', ''Chứng nhận tham gia Triển Lãm Quốc Tế của công ty'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (217, 2, 7, 'Tiếp thị và truyền thông thực tập', 'Liên quan đến việc động não và thực hiện các ý tưởng cho các hoạt động của trường, đặc biệt là các hoạt động tiếp thị; Liên tục giám sát và cập nhật tin tức từ tất cả các nhóm giáo dục trên các nền tảng mạng xã hội để nắm bắt xu hướng thị trường và đưa ra dự đoán phù hợp; Hỗ trợ nhóm nội bộ trong các nhiệm vụ khác nhau, bao gồm nhưng không giới hạn trong các sự kiện của trường, sáng tạo nội dung, nhiếp ảnh, quản lý cộng đồng, gieo hạt, v.v .; Chịu trách nhiệm tạo ra nội dung trên các nền tảng xã hội chính thức của trường học; Giấy tờ; Các nhiệm vụ khác theo hướng dẫn của người quản lý/giám sát viên.', '1. Education: University Degree with Marketing/Business background is an advantage; 2. Experience (type of): Well-experienced with Marketing background; Used to work in Education industry is a plus; 3. Specific knowledge/ skill: Love working in Education industry; Strong business mindset, analytical power, good communication and presentation skill; Have good sense of beauty; Good English at 04 skills; Energized, open-minded and extremely proactive; Practical creativity and result-oriented; Passion to growth and strong time management skill to work in a changeable environment, manage workload and multiple projects; Responsible and honest at work; Careful and detailed with both words, numbers and visual; High progressive spirit: demonstrate enthusiasm and a proactive approach to learning; Strong writing abilities with attention to detail is an advanced. Ability to craft clear, concise, and compelling content tailored to different audiences and platforms.
Kỹ năng chuyên môn: [''Strong business mindset'', ''Analytical power'', ''Good communication and presentation skill'', ''Strong writing abilities'']
Kỹ năng mềm: [''Energized'', ''Open-minded'', ''Extremely proactive'', ''Practical creativity'', ''Result-oriented'', ''Passion to growth'', ''Strong time management skill'', ''Responsible'', ''Honest'', ''Careful'', ''Detailed'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '4.0 triệu', 'Thứ 2 - Thứ 6 (từ 07:45 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Fixed monthly allowance'', ''Nutritious lunches at the School canteen'', ''Positive and transparent working environment'', ''Opportunities for professional and career development'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (218, 3, 7, 'Thực Tập Sinh Nghiên Cứu Thị Trường', 'Nghiên cứu thị trường về khách hàng, hành vi mua hàng, mong muốn, insight, đối tượng là các chủ doanh nghiệp. Hỗ trợ thu thập và phân tích dữ liệu cơ bản. Hỗ trợ thiết lập và quản lý camp quảng cáo.', '1. Bạn thực sự đam mê, quyết liệt với mục tiêu, nói không với ổn định, an toàn, làm hết giờ về và về chill. 2. Bạn có trong mình tinh thần học tập không ngừng luôn khao khát được bứt phá phát triển, thăng tiến trong sự nghiệp, gia tăng thu nhập. 3. Làm việc tại công ty tối thiểu 3 buổi/tuần. 4. Độ tuổi: ưu tiên dưới 23.
Kỹ năng chuyên môn: [''Phân tích dữ liệu'', ''Nghiên cứu thị trường'', ''Thu thập dữ liệu'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Tinh thần học tập'', ''Quyết liệt với mục tiêu'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Part time linh hoạt online/offline, tối thiểu lên công ty 3 buổi/tuần', '[''Được đào tạo và phát triển nhanh gấp 3-5 lần'', ''Thời gian làm việc linh hoạt'', ''Cơ hội trở thành nhân viên chính thức'', ''Hỗ trợ dấu mộc thực tập và tài liệu marketing độc quyền'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (219, 7, 7, 'Nhân Viên Truyền Thông Nội Bộ', 'Hỗ trợ lên kế hoạch truyền thông phù hợp yêu cầu xây dựng văn hóa doanh nghiệp. Phụ trách các kênh truyền thông của công ty: website, fanpage, kênh thông tin nội bộ,... Phụ trách biên tập các ấn phẩm nội bộ (edit poster, edit video), các tài liệu truyền thông. Lên ý tưởng xây dựng, tổ chức các event nội bộ, các sự kiện truyền thông, các hoạt động tập thể. Một số công việc khác theo yêu cầu của cấp Quản lý.', 'Sinh viên năm ba, năm cuối các Đại học chuyên ngành báo chí, truyền thông, quan hệ công chúng hoặc các chuyên ngành có liên quan. Đi làm tối thiểu 5 buổi/tuần (Ưu tiên đi được buổi chiều). Có kinh nghiệm trong lĩnh vực PR, truyền thông là một lợi thế. Có kiến thức tổ chức các sự kiện văn hóa tập thể, kỹ năng viết báo, viết tin cổ động tốt, truyền đạt mạch lạc, thu hút mọi người. Ưu tiên ứng viên nhanh nhẹn, ngoại hình ưa nhìn, có khả năng kết nối, cổ động mọi người, khuấy động không khí trong đám đông, chủ động triển khai công việc. Có khả năng làm việc nhóm tốt, nhiệt tình, năng động, yêu thích các hoạt động xã hội, tập thể. (Có khả năng thuyết trình, làm MC là một lợi thế)
Kỹ năng chuyên môn: [''Kỹ năng viết báo'', ''Kỹ năng viết tin cổ động'', ''Kỹ năng tổ chức sự kiện'']
Kỹ năng mềm: [''Kỹ năng làm việc nhóm'', ''Năng động'', ''Khả năng kết nối'', ''Khả năng cổ động'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 00:00 đến 00:00)', '[''Môi trường làm việc năng động, chuyên nghiệp'', ''Có cơ hội trở thành nhân viên chính thức'', ''Seminar về kiến thức chuyên môn, ngoại ngữ và các kỹ năng khác'', ''Teambuilding, party, dã ngoại, thể thao, du lịch công ty'', ''Khám sức khỏe định kỳ 1 lần/năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (220, 8, 7, 'Nhân Viên Marketing Executive Part-Time', 'Nghiên cứu và phân tích các thông tin, dữ liệu về sản phẩm và diễn biến thị trường. Quản lý và sản xuất nội dung trên các nền tảng truyền thông đa nền tảng của doanh nghiệp (Website, Facebook, Instagram, TikTok, Threads,...). Xây dựng và phụ trách triển khai các chiến dịch Marketing đa hình thức như Online hoặc Offline. Lập báo cáo định kỳ dựa trên kết quả công việc. Phối hợp với các phòng ban khác để triển khai các kế hoạch marketing của doanh nghiệp.', 'Có kinh nghiệm làm việc trong lĩnh vực Marketing tối thiểu 6 tháng hoặc là Chủ nhiệm/Trưởng ban truyền thông của một câu lạc bộ/hội sinh viên tại các trường đại học tối thiểu 1 năm. Có kỹ năng sáng tạo nội dung số trên đa nền tảng. Có kỹ năng viết lách tốt ở nhiều dạng nội dung khác nhau. Có kinh nghiệm quản trị ít nhất 1 kênh truyền thông (Facebook, Instagram, Threads, Youtube, TikTok,...). Có kỹ năng thiết kế cơ bản và thành thạo tin học văn phòng.
Kỹ năng chuyên môn: [''Social Media Marketing'', ''Content Marketing'', ''Digital Marketing'', ''Nghiên Cứu Thị Trường'', ''Sáng tạo nội dung'', ''Quản lý thời gian'', ''Giao tiếp'']
Kỹ năng mềm: [''Tư duy mở'', ''Tinh thần chủ động'', ''Cầu tiến'', ''Trách nhiệm'', ''Khả năng chịu áp lực'', ''Quản lý thời gian'', ''Kỹ năng teamwork'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', '20h/5 ngày/tuần, linh hoạt đăng ký từ 08:00 đến 18:00', '[''Lộ trình thăng tiến rõ ràng'', ''Chương trình đào tạo'', ''Môi trường làm việc trẻ trung, năng động'', ''Teambuilding định kỳ 2 lần/năm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (221, 9, 7, 'Cộng Tác Viên Thiết Kế', '- Thiết kế banner & các hạng mục phục vụ cho livestream - Hỗ trợ Resize, Adapt banners cho web/app. - Hỗ trợ Thiết kế Facebook Post, Facebook Ads, Google Ads - Hỗ trợ Thiết kế Banners cho các sàn Thương Mại Điện Tử - Theo dõi, chịu trách nhiệm về tiến độ & khối lượng công việc - Kiểm tra & sửa file theo yêu cầu - Các nhiệm vụ khác theo sự phân công của Quản lý', '- Có Laptop để làm việc - Có gout thẩm mỹ tốt - Thành thạo FIGMA, AI hoặc PHOTOSHOP - Có kinh nghiệm thiết kế Digital Marketing - Cẩn thận, tỉ mỉ, chi tiết, có trách nhiệm - Có khả năng sắp xếp công việc, đảm bảo timeline, có tính tổ chức, có thể làm việc được trong điều kiện áp lực cao khi triển khai nhiều dự án cùng lúc. - Có khả năng làm việc độc lập & làm việc nhóm tốt.
Kỹ năng chuyên môn: [''FIGMA'', ''AI'', ''PHOTOSHOP'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Chi tiết'', ''Có trách nhiệm'', ''Có khả năng sắp xếp công việc'', ''Đảm bảo timeline'', ''Có tính tổ chức'', ''Có khả năng làm việc độc lập'', ''Làm việc nhóm tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Cơ hội được trở thành Nhân viên chính thức của Concung.com'', ''Được tham gia các hoạt động nội bộ của công ty'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (222, 10, 7, 'Thực Tập Sinh Marketing', 'Hỗ trợ xây dựng và thực hiện các chiến dịch marketing cho các sản phẩm thời trang trẻ em của công ty. Quản lý và phát triển nội dung cho các kênh social media (Website Facebook, Instagram, TikTok) của thương hiệu. Tham gia các hoạt động xây dựng và truyền thông thương hiệu. Tham gia nghiên cứu để đề xuất ý tưởng marketing phù hợp. Tham gia thiết kế các ấn phẩm marketing như banner, poster, lookbook cho các bộ sưu tập mới. Tham gia các hoạt động sản xuất nội dung video content, chụp hình sản phẩm. Tham gia booking làm việc với các KOL, KOC, mẫu nhí... Tham gia phân tích hiệu quả các chiến dịch marketing và đề xuất cải tiến.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các ngành Marketing, Truyền thông hoặc các ngành liên quan. Không yêu cầu kinh nghiệm làm việc trước đó. Có kiến thức cơ bản về marketing, marketing online và digital marketing. Có kỹ năng thiết kế cơ bản các phần mềm như Photoshop, Canva là lợi thế. Kỹ năng viết content marketing tốt, có khả năng sáng tạo nội dung hấp dẫn. Năng động, sáng tạo, ham học hỏi.
Kỹ năng chuyên môn: [''Marketing'', ''Marketing online'', ''Digital marketing'', ''Photoshop'', ''Canva'']
Kỹ năng mềm: [''Kỹ năng viết content marketing'', ''Sáng tạo nội dung'', ''Năng động'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được đào tạo chuyên sâu về Marketing'', ''Được hỗ trợ chi phí đi lại, ăn trưa trong thời gian thực tập'', ''Cơ hội thực hành và áp dụng kiến thức marketing vào thực tế'', ''Làm việc trong môi trường năng động, sáng tạo của ngành thời trang'', ''Cơ hội được chuyển đổi thành nhân viên chính thức sau khi kết thúc thời gian thực tập'', ''Được cấp giấy chứng nhận thực tập sau khi hoàn thành chương trình'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (223, 2, 7, 'Digital Marketing (Intern/Part-Time)', '- Xây dựng nội dung, quản lý các kênh Social Media (Facebook, Instagram, Zalo, Google,...) và các website theo kế hoạch; - Triển khai và đo lường các kế hoạch performance marketing (Meta Ads, Google Ads, Tiktok Ads,...); - Phân tích, đo lường và tối ưu hóa về SEO, ASO trên website và ứng dụng của công ty; - Làm việc với team media xây dựng và lên kế hoạch quay dựng, chụp ảnh, thiết kế; - Đo lường và thực hiện các báo cáo các hoạt động marketing được phân công. Tham gia, hỗ trợ xây dựng các kế hoạch chiến lược; - Tham gia nghiên cứu các hoạt động marketing của đối thủ, nghiên cứu hành vi khách hàng, nắm bắt các xu hướng marketing mới; - Phối hợp, hỗ trợ các bộ phận liên quan để hoàn thành công việc. Thực hiện các công việc khác thuộc chuyên môn marketing theo định hướng của công ty.', '- Sinh viên năm 3-4 hoặc mới tốt nghiệp chuyên ngành Marketing hoặc chuyên ngành khác có liên quan; - Không yêu cầu kinh nghiệm; - Kỹ năng giao tiếp và trình bày tốt, năng động, cầu tiến; - Tính tỉ mỉ, kiên trì, chịu được áp lực.
Kỹ năng chuyên môn: [''Social Media Marketing'', ''Content Marketing'', ''Email Marketing'', ''SEO (Search Engine Optimization)'', ''Digital Marketing Fundamentals'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Trình bày tốt'', ''Năng động'', ''Cầu tiến'', ''Tính tỉ mỉ'', ''Kiên trì'', ''Chịu được áp lực'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Hỗ trợ cơm trưa'', ''Cà phê'', ''Môi trường năng động, chuyên nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (224, 3, 7, 'Thực Tập Sinh Digital Sales Marketing', 'Thực tập lập & triển khai kế hoạch digital sale & marketing online. Thực tập chạy chiến dịch marketing, kế hoạch kinh doanh bán hàng online, offline. Thực tập kinh doanh mô hình Affiliate, MLM. Thực tập viết & lập kế hoạch content, SEO. Thực tập quản lý fanpage, kênh social network & media. Thực tập sale & chốt đơn hàng online & offline. Thực tập tư vấn phần mềm ERP cho doanh nghiệp, Hộ kinh doanh, Startup. Thực tập chăm sóc khách hàng online. Thực tập tổ chức sự kiện truyền thông & hội thảo...', 'Học cao đẳng hoặc đại học các chuyên ngành kinh tế, quản trị kinh doanh, marketing, CNTT, Quản lý hệ thống thông tin, Đam mê kinh doanh, bán hàng, tổ chức sự kiện, marketing. ưu tiên có kỹ năng giao tiếp; Có nhiều mối quan hệ. Thời gian thực tập 6 tháng.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng viết content'', ''SEO'']
Kỹ năng mềm: [''Đam mê kinh doanh'', ''Bán hàng'', ''Tổ chức sự kiện'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Hỗ trợ 200k/tháng'', ''Hoa hồng kinh doanh'', ''Thưởng vượt chỉ tiêu kinh doanh'', ''Hỗ trợ dấu mộc xác nhận thực tập sau 3 tháng'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (225, 7, 7, 'Thực Tập Sinh Content Tiktok', 'Lên ý tưởng, sáng tạo nội dung video TikTok theo trend & phù hợp với thương hiệu Sen Clinic&Pharma - thuộc tập đoàn Sen Group. Viết kịch bản ngắn gọn, thu hút và dễ viral. Theo dõi & phân tích xu hướng TikTok, đề xuất ý tưởng mới. Tham gia vào quá trình sản xuất, edit video. Các công việc khác theo yêu cầu của quản lý trực tiếp.', 'Sinh viên năm 4 các ngành Marketing, Truyền thông, Ngôn ngữ hoặc các lĩnh vực liên quan. Có kỹ năng viết tốt, biết lên ý tưởng xây dựng kịch bản, edit video đơn giản. Có mong muốn phát triển về xây dựng thương hiệu, marketing/quảng cáo. Nhanh nhẹn, chủ động trong công việc, có khả năng làm việc nhóm và chịu được áp lực deadline. Thực tập được tối thiểu 3 tháng. Có Laptop và phương tiện đi lại. Ưu tiên ứng viên có kinh nghiệm viết content Tiktok. Ưu tiên ứng viên ở Quận 1, Quận 4, Quận 7, làm được fulltime, không ngại di chuyển.
Kỹ năng chuyên môn: [''Kỹ năng viết tốt'', ''Biết lên ý tưởng xây dựng kịch bản'', ''Edit video đơn giản'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chủ động trong công việc'', ''Có khả năng làm việc nhóm'', ''Chịu được áp lực deadline'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 - 3.5 triệu', 'Thực tập fulltime 5,5 ngày/tuần', '[''Phụ cấp thực tập: 3.000.000 + thưởng'', ''Hỗ trợ mộc và báo cáo thực tập'', ''Cơ hội lên nhân viên chính thức sau thời gian thực tập'', ''Được hướng dẫn, đào tạo, định hướng về phát triển kỹ năng, sự nghiệp tại Tập đoàn trong nhiều lĩnh vực'', ''Không gian làm việc thoải mái, năng động, tự do sáng tạo và đóng góp ý kiến'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (226, 8, 7, 'Thực Tập Sinh Marketing', 'Các công việc thuộc bộ phận marketing như: Quản lý, đăng bài sản phẩm trên web, Hỗ trợ SEO cải thiện thứ hạng từ khoá, Viết bài content chất lượng, chuẩn SEO, Vận hành kênh TMĐT. Ứng viên có thể chọn ca sáng hoặc ca chiều hoặc full-time. 1 tuần đăng ký làm 5 ca (sáng hoặc chiều).', 'Có định hướng theo ngành Marketing trong tương lai. Khả năng viết lách tốt, đúng chính tả, đúng ngữ nghĩa, văn phong hay. Xử lý hình ảnh cơ bản. Chăm chỉ và tinh thần kỷ luật tốt.
Kỹ năng chuyên môn: [''Xử lý hình ảnh cơ bản'', ''Viết bài content chất lượng, chuẩn SEO'']
Kỹ năng mềm: [''Khả năng viết lách tốt'', ''Chăm chỉ'', ''Tinh thần kỷ luật tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', 'Ca sáng 8-12h, chiều 13-17h', '[''Chế độ thưởng đầy đủ'', ''Có hỗ trợ dấu đỏ đầy đủ cho thực tập sinh'', ''Được đào tạo kỹ năng và các phần mềm chuyên dụng'', ''Môi trường làm việc năng động, đoàn kết, hỗ trợ lẫn nhau'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (227, 9, 7, 'Thực Tập Sinh Trade Marketing', '- Triển khai đi thị trường (Market Visit) nhằm phân tích, đánh giá & đề xuất liên kết với các đối tác bao gồm phòng khám mẹ và bé, các office building, các căn hộ cao cấp,..- Giám sát, báo cáo chất lượng triển khai của từng dự án - Phối hợp tổ chức các sự kiện, workshop, các chương trình khuyến mãi cùng đối tác - Triển khai các chiến dịch truyền thông offline như phát tờ rơi, banner, standee, POSM.', '- Nhanh nhẹn, năng động, chịu khó. - Thích công việc đi thị trường - Kỹ năng giao tiếp tốt, chủ động, phân tích, đánh giá và có tinh thần học hỏi.- Chủ động, khả năng làm việc nhóm và làm việc độc lập.- Thành thạo vi tính văn phòng
Kỹ năng chuyên môn: [''Thành thạo vi tính văn phòng'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Năng động'', ''Chịu khó'', ''Kỹ năng giao tiếp tốt'', ''Chủ động'', ''Phân tích'', ''Đánh giá'', ''Có tinh thần học hỏi'', ''Khả năng làm việc nhóm'', ''Làm việc độc lập'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.5 - 4.5 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30) và Thứ 2 - Thứ 6 (từ 10:30 đến 19:30)', '[''Cung cấp mộc tròn thực tập'', ''Cung cấp thông tin làm báo cáo'', ''Làm việc trong môi trường năng động, vui vẻ'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (228, 10, 7, 'Chuyên Viên Quản Lý CLB Tiếng Anh', 'Lên kế hoạch, xây dựng kịch bản, biên tập nội dung cho hoạt động CLB Tiếng Anh. Tổ chức các buổi Workshop cho CLB Tiếng Anh. Tổ chức các buổi học tiếng Anh. Thuyết trình dẫn dắt các buổi workshop. Quản lý sinh hoạt, tổ chức, giao lưu, vui chơi, du lịch cho các hội viên. Phụ trách marketing thu hút thành viên mới cho CLB. Kết nối với các đối tác để mở rộng mạng lưới hoạt động của CLB. Tuyển dụng, đào tạo và quản lý đội ngũ nhân viên hỗ trợ.', 'Nam và nữ từ 20- 33 tuổi. Có ít nhất 1 năm kinh nghiệm trong Đào tạo / Giáo dục. Biết thuyết trình, dẫn dắt, truyền cảm hứng cho các thành viên. Có kỹ năng viết kịch bản cho các chương trình, sự kiện…. Giọng nói nhẹ nhàng, nói lưu loát, có khả năng diễn đạt tốt. Ngoại hình đàng hoàng, phong cách đỉnh đạc. Ưu tiên biết các kỹ năng Marketing, PR, truyền thông.
Kỹ năng chuyên môn: [''Kỹ năng viết kịch bản'', ''Kỹ năng marketing'', ''Kỹ năng PR'', ''Kỹ năng truyền thông'']
Kỹ năng mềm: [''Thuyết trình'', ''Truyền cảm hứng'', ''Giao tiếp tốt'', ''Quản lý thời gian'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 50000000.00, '50.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Thưởng KPI hiệu quả hoạt động từ 100 – 300tr / tháng'', ''Thưởng lễ, tết, sinh nhật'', ''Thưởng du lịch nước ngoài thường xuyên'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (229, 2, 7, 'Thực Tập Marketing Facebook Part Time, Full Time', 'Quản lý hệ thống Facebook với gần 800.000 thành viên của công ty. Duyệt tin, duyệt thành viên, đăng bài để thúc đẩy hệ thống Facebook phát triển. Quay các clip, làm các clip thú vị để thúc đẩy thành viên mới. Sử dụng Ai viết bài, làm clip,… Livestream trên Facebook của công ty. Thời gian thực tập: 6 tháng. Công ty chỉ tuyển ứng viên đi thực tập lấy kinh nghiệm, để được đào tạo chuyên ngành và ở lại làm việc lâu dài cho công ty. Chứng chỉ thực tập được cấp sau khi hoàn thành khóa thực tập.', 'Chấp nhận sinh viên 1, 2, 3, 4. Có laptop cá nhân. Có kinh nghiệm xây dựng, tổ chức, hoạt động ở các club.
Kỹ năng chuyên môn: [''Sử dụng Ai viết bài'', ''Livestream trên Facebook'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Linh hoạt'', ''Giao tiếp tốt'', ''Tự tin trước ống kính'', ''Độc lập trong công việc'', ''Có khả năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Part Time Trong giờ hành chính: 6 ca/ Tuần, Trong đó có 02 ca vào "các buổi tối hoặc chiều T7 hoặc CN"', '[''Cấp chứng chỉ thực tập'', ''Phụ cấp hỗ trợ thực tập để ăn trưa, gửi xe, xăng xe: 10.000 đ/h'', ''Môi trường làm việc năng động, trẻ trung'', ''Được tăng lương và đề bạt làm nhân viên chính thức nếu có kết quả thực tập tốt'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (230, 3, 7, 'Thực Tập Sinh Content Marketing', 'Quản lý và phát triển các trang mạng xã hội (Facebook): Lên kế hoạch nội dung sáng tạo, phù hợp với chủ đề golf và pickleball. Biết chỉnh sửa ảnh, thiết kế hình ảnh cơ bản theo dõi hiệu suất và đưa ra chiến lược tối ưu nội dung. Viết bài PR sự kiện: Soạn thảo các bài viết truyền thông Social và báo chí trước, trong và sau sự kiện. Phối hợp với các đối tác báo chí và nền tảng truyền thông để quảng bá sự kiện. Tổ chức và truyền thông sự kiện: Hỗ trợ tổ chức các sự kiện như giải golf, giải pickleball, hội thảo hoặc họp báo. Quản lý tư liệu hình ảnh, video từ sự kiện để phục vụ truyền thông. Phát triển các bài viết tổng hợp sau sự kiện một cách chuyên nghiệp và sáng tạo. Phân tích và báo cáo: Theo dõi hiệu quả các chiến dịch truyền thông, theo dõi đối thủ. Báo cáo kết quả và đề xuất các cải tiến cho tương lai.', 'Kỹ năng viết bài, viết lách và sáng tạo nội dung thu hút. Thành thạo các công cụ thiết kế và chỉnh sửa hình ảnh. Hiểu biết hoặc có đam mê về thể thao (đặc biệt là golf, pickleball). Có kinh nghiệm tổ chức sự kiện và quản lý các kênh mạng xã hội. Khả năng làm việc độc lập và kỹ năng tổ chức tốt. Kỹ năng quản lý thời gian và làm việc dưới áp lực cao. Khả năng phân tích dữ liệu từ các nền tảng mạng xã hội để tối ưu chiến lược nội dung. Có kiến thức cơ bản về quay dựng video là một lợi thế. Hiểu biết về quảng cáo và cách chạy chiến dịch quảng cáo trên các nền tảng như Facebook Ads sẽ là điểm cộng lớn.
Kỹ năng chuyên môn: [''Kỹ năng viết bài'', ''Thành thạo các công cụ thiết kế và chỉnh sửa hình ảnh'', ''Kiến thức cơ bản về quay dựng video'']
Kỹ năng mềm: [''Kỹ năng tổ chức'', ''Kỹ năng quản lý thời gian'', ''Khả năng làm việc độc lập'', ''Kỹ năng phân tích dữ liệu'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '8:00 – 17:00 từ Thứ 2 – Thứ 6', '[''Môi trường làm việc trẻ trung, chuyên nghiệp, năng động'', ''Cơ hội trở thành nhân viên chính thức'', ''Trải nghiệm trong sự kiện'', ''Giấy chứng nhận thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (231, 7, 7, 'Thực Tập Sinh Event Marketing', 'Hỗ trợ tìm kiếm Golfer, Nhà tài trợ, nhà cung cấp. Triển khai, hỗ trợ tổ chức các hoạt động marketing, sự kiện golf. Phối hợp tốt với các đơn vị liên quan để đảm bảo kế hoạch triển khai hiệu quả. Xây dựng và duy trì tốt mối quan hệ với khách hàng sau mỗi sự kiện. Thực hiện công việc theo yêu cầu của cấp trên.', 'Chưa có kinh nghiệm sẽ được đào tạo và trao đổi cụ thể khi phỏng vấn. Nhiệt tình, năng động trong công việc. Có tinh thần trách nhiệm. Kỹ năng giao tiếp. Kỹ năng làm việc nhóm. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Tổ chức sự kiện'', ''Tìm kiếm khách hàng'', ''Khả năng giải quyết vấn đề'']
Kỹ năng mềm: [''Nhiệt tình'', ''Năng động'', ''Có tinh thần trách nhiệm'', ''Kỹ năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ dấu mộc, tài liệu tham khảo trong 2 tháng thực tập'', ''Được làm việc trong môi trường trẻ trung, chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức'', ''Trải nghiệm trong môi trường làm việc năng động: Đi du lịch, tham gia các cuộc thi, sự kiện lớn do công ty tổ chức'', ''Sắp xếp thời gian làm việc phù hợp với lịch học'', ''Được thưởng sau mỗi sự kiện, không hỗ trợ chi phí, nhận hoa hồng theo kết quả đạt được.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (232, 8, 7, 'Thực Tập Sinh Marketing', 'Được đào tạo kiến thức cơ bản để đáp ứng công việc. Đóng góp ý tưởng xây dựng các tuyến bài cho các kênh Social của công ty. Hỗ trợ các dự án phòng Marketing đang triển khai. Ứng viên có thể lựa chọn làm việc Fulltime/ Part-time.', 'Ưu tiên sinh viên năm 2- 3 đại học. Ứng viên đang theo học Marketing và muốn trải nghiệm môi trường làm việc chuyên nghiệp. Có khả năng sáng tạo. Sử dụng thành thạo PowerPoint, Canvas, Capcut…
Kỹ năng chuyên môn: [''PowerPoint'', ''Canvas'', ''Capcut'']
Kỹ năng mềm: [''Sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được tham gia các chương trình đào tạo, huấn luyện của Công ty'', ''Cơ hội thăng tiến, và tuyển dụng thành nhân viên chính thức trong tương lai'', ''Môi trường làm việc chuyên nghiệp, thân thiện, năng động'', ''Có hỗ trợ CHI PHÍ thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (233, 9, 7, 'Thực Tập Sinh Marketing Thực Chiến', 'Xây dựng, phát triển và quản lý kênh truyền thông, đặc biệt là TikTok, Facebook, Zalo để thu hút học viên tiềm năng. Tạo nội dung sáng tạo (bài viết, ảnh, video) theo trend, phù hợp chiến lược thương hiệu và insight khách hàng. Phối hợp team marketing để triển khai quảng cáo (performance) trên Facebook, TikTok, Google… Tham gia các hoạt động nghiên cứu thị trường, đối thủ, và insight người dùng. Được tham gia tổ chức sự kiện online/offline: webinar, livestream, workshop. Được đào tạo kỹ năng sale tư vấn, xây dựng thương hiệu cá nhân, viết lách, giao tiếp, và tư duy hệ thống.', 'Sinh viên hoặc mới tốt nghiệp tại các trường Cao đẳng, Đại học... không yêu cầu kinh nghiệm. Năng động, sáng tạo, yêu thích marketing hoặc sale. Biết sử dụng các nền tảng, công cụ thiết kế đơn giản như Facebook, tiktok, Canva, capcut... là một lợi thế.
Kỹ năng chuyên môn: [''Facebook'', ''TikTok'', ''Canva'', ''Capcut'']
Kỹ năng mềm: [''Năng động'', ''Sáng tạo'', ''Yêu thích marketing hoặc sale'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00), linh hoạt theo ca', '[''Cơ hội học hỏi và phát triển trong môi trường giáo dục năng động, chuyên nghiệp'', ''Được đào tạo, trải nghiệm hệ sinh thái marketing tổng thể'', ''Cơ hội trở thành nhân viên chính thức'', ''Cơ chế hoa hồng dự án lên tới 10-20tr/tháng'', ''Môi trường làm việc trẻ trung, năng động và thân thiện'', ''Được tham gia các hoạt động team building, sự kiện của công ty'', ''Thưởng hiệu quả làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (234, 10, 7, 'Thực Tập Sinh Marketing', 'Hỗ trợ hoạt động Marketing- Truyền thông: Tham gia xây dựng kế hoạch marketing tuần/tháng để hỗ trợ kế hoạch kinh doanh. Thực hiện các hoạt động quảng bá thương hiệu/kinh doanh qua kênh online/offline như: email marketing, quảng cáo, mạng xã hội (Facebook, LinkedIn, Instagram, Tiktok, Sàn TMĐT, v.v.). Chuẩn bị ấn phẩm truyền thông như bài viết, video, infographic, v.v., phù hợp với kế hoạch kinh doanh. Hỗ trợ phòng kinh doanh: Thực hiện khảo sát thị trường, phân tích đối thủ cạnh tranh, và tổng hợp thông tin hỗ trợ công tác bán hàng. Chuẩn bị tài liệu thuyết trình, brochure hoặc nội dung giới thiệu sản phẩm. Tham gia tổ chức và triển khai các sự kiện (online/offline) dành cho phòng kinh doanh như hội thảo, hội chợ, hoặc workshop. Công việc liên quan khác: Lập báo cáo kết quả công việc định kỳ. Hỗ trợ các công việc khác theo yêu cầu của quản lý.', 'Sinh viên năm 3-4 các ngành Marketing, Quản trị Kinh doanh, Truyền thông hoặc lĩnh vực liên quan. Biết sử dụng các công cụ hỗ trợ như Canva, Photoshop, hoặc Google Analytics là lợi thế. Kỹ năng viết và giao tiếp tốt. Nhanh nhẹn, chủ động học hỏi và làm việc nhóm hiệu quả.
Kỹ năng chuyên môn: [''Canva'', ''Photoshop'', ''Google Analytics'']
Kỹ năng mềm: [''Kỹ năng viết'', ''Giao tiếp tốt'', ''Nhanh nhẹn'', ''Chủ động học hỏi'', ''Làm việc nhóm hiệu quả'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Trợ cấp thực tập'', ''Hỗ trợ dấu mộc và tài liệu báo cáo'', ''Tham gia tiệc/workshop các ngày Lễ, kỷ niệm công ty'', ''Có người hướng dẫn trực tiếp, được feedback và lắng nghe idea/đề xuất'', ''Môi trường văn hóa - năng động, nhiệt huyết'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (235, 2, 7, 'Thực Tập Sinh Booking KOL/KOC', 'Hỗ trợ và được đào tạo thực chiến các công việc: Phối hợp với team Vận hành lập kế hoạch Content & Booking KOC/KOL phù hợp theo từng tháng. Tìm kiếm, tiến hành trao đổi công việc cụ thể với các KOL/KOC phù hợp với nhãn hàng hàng. Tham gia lập kế hoạch, tổ chức các phiên Key Livestream với KOC/KOL và nhãn hàng. Nghiên cứu, trao đổi với Nhãn Hàng để hiểu biết sâu sắc về sản phẩm, tệp khách hàng mục tiêu của Nhãn Hàng, các thông điệp truyền thông, điểm nhấn bán hàng. Thực hiện báo doanh thu, KPI, thanh toán cho KOC/KOL đối soát dòng tiền với Brands. Làm việc, phối hợp với các KOC trong UpBase MCN network để sáng tạo nội dung giúp phát triển kênh TikTok của Nhãn Hàng và Short videos chuyển đổi bán hàng. Báo cáo kết quả trực tiếp cho quản lý.', 'Sinh viên năm cuối hoặc đã tốt nghiệp Đại học chuyên ngành Marketing, Truyền thông, Quản trị kinh doanh hoặc các ngành liên quan. Có kiến thức căn bản về Marketing, IMC, PR, Bán hàng; Am hiểu sử dụng các công cụ, phương tiện truyền thông, nguyên tắc phân bổ ngân sách, và quy trình làm việc với đối tác truyền thông. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Kiến thức căn bản về Marketing'', ''IMC'', ''PR'', ''Bán hàng'', ''Sử dụng các công cụ truyền thông'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Kỹ năng đàm phán và thương lượng'', ''Kỹ năng quản lý thời gian và công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Thưởng tháng lương 13++'', ''Thưởng hiệu suất'', ''Chế độ đãi ngộ dành cho CBNV và người thân hàng năm'', ''Khám sức khỏe định kỳ hàng năm'', ''Chế độ thưởng cổ phần ESOP hàng năm'', ''Đóng BHXH, BHYT, BHTN theo quy định'', ''Review lương 1-2 lần/ năm'', ''Du lịch, teambuilding 1-2 lần/ năm'', ''Được tham gia các chương trình đào tạo và huấn luyện chuyên môn'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (236, 3, 7, 'Cộng Tác Viên Marketing', 'Lên nội dung Fanpage theo từng tuyến chiến dịch Marketing. Triển khai phối hợp hỗ trợ sự kiện khi cần. Làm video, hình ảnh Marketing với các công cụ. Lên chiến dịch chạy quảng cáo từng đợt.', 'Sinh viên các ngành Marketing, Truyền thông, Báo chí, Kinh tế... hoặc có đam mê với Marketing. Chủ động, ham học hỏi, có tinh thần trách nhiệm. Ưu tiên biết chụp ảnh, chỉnh sửa video cơ bản (không bắt buộc).
Kỹ năng chuyên môn: [''Chụp ảnh'', ''Chỉnh sửa video cơ bản'']
Kỹ năng mềm: [''Chủ động'', ''Ham học hỏi'', ''Có tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Được thưởng thêm nếu đảm bảo chất lượng công việc tốt'', ''Được đào tạo công việc Marketing và kỹ năng ứng dụng AI trong công việc'', ''Môi trường làm việc chuyên nghiệp, trẻ trung, có định hướng'', ''Hỗ trợ dấu mộc thực tập và xác nhận quá trình làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (237, 7, 7, 'Trang web SEO nội dung', '- Research, lên ý tưởng nội dung, hình ảnh theo chiến lược SEO của đội ngũ SEO. - Có khả năng lên outline bài viết theo chủ đề được giao. - Viết bài theo Outline được giao phó. - Phối hợp các đội ngũ outsource content bên ngoài để thực thi triển khai, review nội dung để đảm bảo content cho khách hàng. - Tối ưu bài viết content sau khi hoàn thiện từ đội ngũ outsource giúp cho chuẩn SEO hơn với tiêu chuẩn của cty và khiến hay hơn. - Hoàn thành các công việc liên quan được cấp trên giao phó.', '1.Học vấn, Kiến thức:- Học vấn: Tốt nghiệp Đại học trở lên (hoặc sinh viên làm thêm)- Ưu tiên chuyên ngành Ngôn ngữ Anh, văn hoá, báo chí, truyền thông, marketing là lợi thế. 2.Kinh nghiệm:- Có kinh nghiệm viết content dưới 1 năm.- Có kinh nghiệm làm ở vị trí content / biên tập các ngành công nghệ/marketing/kinh doanh/sáng tạo/SEO/MMO/E-commerce là một lợi thế. 3. Kỹ năng:- Khả năng tin học văn phòng tốt.- Có kỹ năng tiếng anh cơ bản (đọc và viết tốt).Ưu tiên ứng viên có chứng chỉ IL, Toiec.- Sắp xếp, phân bổ thời gian hợp lí có kỹ năng làm việc nhóm tốt. 4. Tố chất cá nhân cần có để công việc thành công:- Đam mê SEO, Content & Digital Marketing.- Cẩn thận, chăm chỉ và chủ động trong công việc.- Có kỷ luật bản thân, có khát vọng thành công và thăng tiến trong sự nghiệp- Hòa đồng, vui vẻ, năng động- Trung thực và có đạo đức nghề nghiệp- Cẩn thận, kỹ tính, chịu khó, khả năng chịu áp lực cao.- Có mong muốn gắn bó lâu dài với công ty
Kỹ năng chuyên môn: [''Nghiên Cứu Từ Khóa'', ''Seo On Page'', ''Seo Off Page'', ''Phân Tích Dữ Liệu Seo (google Analytics, Search Console)'', ''Viết Nội Dung Seo'']
Kỹ năng mềm: [''Khả năng tin học văn phòng tốt'', ''Sắp xếp, phân bổ thời gian hợp lí'', ''Kỹ năng làm việc nhóm tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '5.0 - 7.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Có lộ trình thăng tiến trong công việc rõ ràng'', ''Thưởng các dịp lễ, tết'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (238, 8, 7, 'Nhân Viên Kinh Doanh Website', 'Tìm kiếm và phát triển khách hàng tiềm năng trong lĩnh vực phần mềm, internet và thương mại điện tử. Phân tích nhu cầu của khách hàng và tư vấn các giải pháp phần mềm phù hợp. Thực hiện các cuộc gọi, email, gặp gỡ trực tiếp để giới thiệu sản phẩm/dịch vụ. Xây dựng và duy trì mối quan hệ tốt đẹp với khách hàng. Lập kế hoạch và thực hiện các chiến dịch marketing, quảng bá sản phẩm. Theo dõi và quản lý tiến độ bán hàng, đảm bảo đạt được mục tiêu doanh số. Báo cáo kết quả công việc cho quản lý và đóng góp ý kiến cải thiện hoạt động kinh doanh. Tham gia các hoạt động đào tạo, cập nhật kiến thức về sản phẩm và kỹ năng bán hàng.', 'Không yêu cầu kinh nghiệm, được đào tạo bài bản. Tốt nghiệp Cao đẳng/Đại học chuyên ngành kinh tế, marketing, công nghệ thông tin hoặc các chuyên ngành liên quan. Kỹ năng giao tiếp, đàm phán và thuyết phục tốt. Khả năng làm việc độc lập và làm việc nhóm hiệu quả. Có kỹ năng lập kế hoạch, tổ chức và quản lý thời gian. Nắm bắt nhanh các kiến thức về phần mềm, internet và thương mại điện tử. Trung thực, năng động, nhiệt tình và có trách nhiệm trong công việc. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). Khả năng sử dụng các công cụ tìm kiếm khách hàng, quản lý khách hàng (CRM) là một lợi thế.
Kỹ năng chuyên môn: [''tin học văn phòng (Word, Excel, PowerPoint)'', ''các công cụ tìm kiếm khách hàng'', ''quản lý khách hàng (CRM)'']
Kỹ năng mềm: [''giao tiếp'', ''đàm phán'', ''thuyết phục'', ''lập kế hoạch'', ''tổ chức'', ''quản lý thời gian'']', 'FREELANCE', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'FIXED_PROJECT', 50000000.00, '10.0 - 50.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Lương, thưởng cạnh tranh và hấp dẫn theo năng lực'', ''Chế độ bảo hiểm đầy đủ theo luật lao động'', ''Môi trường làm việc năng động, chuyên nghiệp và thân thiện'', ''Cơ hội thăng tiến và phát triển nghề nghiệp rõ ràng'', ''Được đào tạo bài bản về kỹ năng bán hàng, sản phẩm và kiến thức ngành'', ''Thưởng doanh số, thưởng lễ, tết và các hoạt động team building thường xuyên'', ''Nghỉ phép năm, các chế độ phúc lợi khác theo quy định của công ty'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (239, 9, 7, 'Thực Tập Sinh Truyền Thông Part-Time', 'Quản trị fanpage, website. Sáng tạo nội dung. Tìm hiểu xu hướng mạng xã hội, đề xuất nội dung mới phù hợp với học sinh 18–25 tuổi. Tham gia cùng team triển khai chiến dịch truyền thông, hỗ trợ tổ chức sự kiện, hội thảo.', 'Sinh viên năm 2 trở lên chuyên ngành: Marketing, Truyền thông, Báo chí hoặc các ngành liên quan. Có kỹ năng content, media, tư duy tích cực, nhanh nhạy với mạng xã hội (Facebook, TikTok...). Yêu thích lĩnh vực giáo dục, đặc biệt là du học. Biết sử dụng cơ bản các công cụ thiết kế như Canva Capcut là lợi thế. Ưu tiên ứng viên từng viết blog, kịch bản video, từng tham gia CLB truyền thông/sự kiện/sinh viên.
Kỹ năng chuyên môn: [''Kỹ năng content'', ''Sử dụng cơ bản các công cụ thiết kế như Canva, Capcut'']
Kỹ năng mềm: [''Tư duy tích cực'', ''Nhanh nhạy với mạng xã hội'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Từ thứ 2 - thứ 6, nghỉ T7 + CN', '[''Có hỗ trợ chi phí thực tập theo hiệu quả công việc'', ''Được đào tạo về kỹ năng viết bài chuẩn SEO, viết nội dung quảng cáo, viết kịch bản video TikTok'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Môi trường làm việc trẻ trung, nhân văn và có định hướng phát triển lâu dài'', ''Ăn trưa, Xăng xe'', ''Thưởng hiệu quả làm việc'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (240, 10, 7, 'Thực Tập Sinh Nghiên Cứu Thị Trường', 'Được trực tiếp tham gia vào quá trình nghiên cứu, triển khai dự án, tổng hợp dữ liệu giá các dự án. Khảo sát thị trường, thu thập dữ liệu, lập báo cáo nghiên cứu thị trường. Hỗ trợ giám đốc dự án đóng góp xây dựng nội dung giới thiệu sản phẩm. Hỗ trợ theo dõi tình trạng dự án.', 'Không yêu cầu có kinh nghiệm sẽ được đào tạo. Ưu tiên sinh viên các khối nghành, chuyên nghành: kinh tế, bất động sản, quản trị kinh doanh. Thích trải nghiệm trong lĩnh vực Bất động sản. Ưu tiên có kỹ năng thuyết trình, giải quyết vấn đề tốt. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Tin học văn phòng: word, excel, powerpoint'']
Kỹ năng mềm: [''Kỹ năng thuyết trình'', ''Giải quyết vấn đề'', ''Tinh thần sáng tạo'', ''Học hỏi'', ''Cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7: 08:00 - 12:00', '[''Lương hỗ trợ 3.000.000 VNĐ/ tháng'', ''Cơ hội thăng tiến'', ''Được đào tạo trực tiếp từ trưởng phòng'', ''Môi trường làm việc năng động'', ''Tham gia vào các hoạt động vui chơi, Teambuilding'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (241, 2, 7, 'Thực Tập Sinh Marketing', 'Lên kịch bản video, thực hiện quay, chỉnh sửa, cắt ghép và dựng video theo các yêu cầu cụ thể của từng dự án; Hiệu chỉnh các video để phù hợp với các nền tảng khác nhau như Facebook, YouTube, TikTok; Viết bài đăng và nội dung truyền thông cho các nền tảng mạng xã hội liên quan đến thương hiệu, dự án hoặc sự kiện của công ty (Facebook, Instagram, Tiktok, LinkedIn...); Thiết kế ấn phẩm truyền thông chất lượng cao (bài viết, story, poster, banner, thông báo cáo chí...) theo kế hoạch được cấp trên đề ra; Tạo lập và thực hiện các phương án phát triển và quản lý tuyến nội dung cho các kênh truyền thông, mạng xã hội của các account khác nhau và đảm bảo sự hài lòng của đối tác và khách hàng; Thực hiện các phần việc thiết kế và các việc được yêu cầu khác từ cấp trên.', 'Sinh viên năm 3, năm 4, hoặc mới ra trường trong các ngành Marketing, Thương mại Điện tử, Sự kiện - Truyền Thông, Thiết kế,... Có kỹ năng viết nội dung, thuyết trình và giao tiếp tốt; Sử dụng Canva, Capcut thành thạo và biết cơ bản các phần mềm thiết kế khác (Photoshop, Illustrator,...) là một điểm cộng; Có kỹ năng tiếng Anh là một điểm cộng; Kỹ năng tổ chức, quản lý thời gian tốt và khả năng giao tiếp hiệu quả; Tư duy độc lập và khả năng làm việc nhóm, chịu được áp lực công việc cao.
Kỹ năng chuyên môn: [''Sử dụng Canva'', ''Capcut'', ''Photoshop'', ''Illustrator'']
Kỹ năng mềm: [''Kỹ năng viết nội dung'', ''Thuyết trình'', ''Giao tiếp'', ''Tổ chức'', ''Quản lý thời gian'', ''Làm việc nhóm'', ''Chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)', '[''Được đào tạo và thực tập các chuyên môn Marketing, Phát triển kinh doanh, Vận hành, công nghệ thông tin'', ''Hỗ trợ dấu mộc thực tập'', ''Có phụ cấp thực tập + Thưởng KPI và chuyên cần'', ''Được trực tiếp tham gia triển khai những dự án thực tế của công ty'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (242, 3, 7, 'Content Social Creator - Hợp Đồng Ngắn Hạn', 'Hỗ trợ viết nội dung cho các kênh mạng xã hội của thương hiệu (Facebook, Instagram, TikTok...) liên quan đến sản phẩm, chương trình khuyến mãi, cửa hàng, hoặc sự kiện. Tìm hiểu xu hướng mạng xã hội, đề xuất các nội dung bắt trend để thu hút tương tác, đặc biệt trên TikTok và Instagram Reels. Hỗ trợ biên tập caption, mô tả sản phẩm, kịch bản clip ngắn cho nội dung giới thiệu sản phẩm. Phối hợp cùng team thiết kế và media để sản xuất hình ảnh, video đăng mạng xã hội. Theo dõi hiệu quả bài viết (reach, tương tác, lượt chia sẻ) và hỗ trợ tổng hợp báo cáo định kỳ. Lên kế hoạch và đăng bài theo lịch đăng tải đã được duyệt. Hỗ trợ các công việc khác liên quan đến content và marketing theo yêu cầu.', 'Học vấn: Là sinh viên năm 3 – năm cuối hoặc mới tốt nghiệp chuyên ngành Truyền thông, Marketing, Báo chí, PR hoặc các ngành liên quan. Kinh nghiệm: Không yêu cầu kinh nghiệm. Kiến thức: Có tư duy sáng tạo, biết cách truyền tải nội dung hấp dẫn, phù hợp với khách hàng mục tiêu trong ngành bán lẻ. Kỹ năng: Yêu thích và sử dụng thành thạo mạng xã hội (Facebook, TikTok, Instagram...). Biết sử dụng Canva, CapCut, hoặc công cụ chỉnh sửa ảnh/video cơ bản là một lợi thế. Tính cách: Có tinh thần trách nhiệm, làm việc đúng deadline, chủ động học hỏi, giao tiếp cởi mở.
Kỹ năng chuyên môn: [''Sử dụng thành thạo mạng xã hội (Facebook, TikTok, Instagram)'', ''Biết sử dụng Canva, CapCut, hoặc công cụ chỉnh sửa ảnh/video cơ bản'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Truyền tải nội dung hấp dẫn'', ''Tinh thần trách nhiệm'', ''Làm việc đúng deadline'', ''Chủ động học hỏi'', ''Giao tiếp cởi mở'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 – Thứ 6 (Có thể linh động thời gian làm việc tại văn phòng theo sự phân công của Quản lý)', '[''Tham gia BHXH, BHYT theo đúng quy định của Nhà nước'', ''Chế độ phúc lợi theo chính sách nội bộ'', ''Được đào tạo nâng cao nghiệp vụ trong quá trình làm việc'', ''Môi trường làm việc chuyên nghiệp, năng động và hiệu quả'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (243, 7, 7, 'Thực Tập Sinh Marketing', '1. Biên tập, dựng & chỉnh sửa video ngắn trên CapCut (promo clip, highlight sự kiện), đảm bảo chất lượng hình ảnh, âm thanh và tempo phù hợp. 2. Thiết kế cơ bản các ấn phẩm truyền thông (banner, poster, social media card) trên Canva hoặc Photoshop. 3. Soạn caption, hashtag, lên kịch bản clip ngắn, phối hợp với Full-time để đảm bảo thống nhất thông điệp. 4. Hỗ trợ tổ chức sự kiện offline: setting backdrop, phát tờ rơi, ghi hình livestream. 5. Cập nhật kịp thời feedback từ sự kiện, hỗ trợ tối ưu nội dung cho lần sau.', '1. Sinh viên chuyên ngành Marketing, Truyền thông, Thiết kế đồ họa hoặc tương đương. 2. Có kinh nghiệm biên tập video trên CapCut ≥ 3 tháng và thiết kế cơ bản trên Canva/Photoshop. 3. Có thể sử dụng công cụ Adobe Illustrator, Adobe Premiere, ... có tư duy thẩm mỹ tốt. 4. Sáng tạo, bắt nhịp xu hướng video Reels, Shorts. 5. Khả năng làm việc linh hoạt theo khung giờ sự kiện (chủ yếu buổi chiều và cuối tuần).
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Premier'', ''Canva'', ''Figma'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Sáng tạo'', ''Khả năng làm việc linh hoạt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), theo ca', '[''Môi trường làm việc trẻ trung, năng động'', ''Được tham gia các khóa đào tạo chuyên môn, kỹ năng phục vụ công việc'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (244, 8, 7, 'Cộng Tác Viên Trực Page Part Time Online', 'Trực, tư vấn và chốt đơn hàng qua Pancake. Chốt đơn hàng kiểm tra size, mã và lên đơn gửi đi. Tư vấn SIZE số, Giải đáp thắc mắc về form dáng chất liệu khách hàng qua pancake. Tư vấn các chương trình khuyến mại, giảm giá cho khách hàng. Chăm sóc khách hàng đã mua hàng để trở thành khách hàng thân thiết, trò chuyện, chia sẻ, hỗ trợ KH về đơn hàng khi cần và giới thiệu sản phẩm mới. Báo cáo kết quả làm việc: Doanh số ngày, doanh số ups, số data nhận được, số tiền về trong tháng, tỉ lệ chốt đơn. Thực hiện các công việc khác theo yêu cầu của trưởng bộ phận.', 'Nữ, có độ tuổi <30. Đã có kinh nghiệm sử dụng Pancake. Tốc độ đánh máy nhanh. Có laptop cá nhân. Có tinh thần trách nhiệm cao, ham học hỏi, sẵn sàng đón nhận tư duy mới. Có kỹ năng tư vấn, bán hàng, xử lý từ chối của khách hàng. Có kỹ năng giao tiếp online, sử dụng thành thạo máy tính.
Kỹ năng chuyên môn: [''Sử dụng Pancake'', ''Tốc độ đánh máy nhanh'', ''Sử dụng thành thạo máy tính'']
Kỹ năng mềm: [''Kỹ năng tư vấn'', ''Kỹ năng bán hàng'', ''Kỹ năng giao tiếp online'', ''Tinh thần trách nhiệm cao'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '4.0 - 8.0 triệu', 'Thứ 2 - Chủ nhật (từ 07:30 đến 12:00, 13:00 đến 17:30, 18:00 đến 22:30)', '[''Lương cứng 2,5 - 3,5 triệu + %Doanh thu'', ''Nghỉ 2 ngày/tháng theo lịch đăng ký'', ''Làm việc online tại nhà'', ''Môi trường làm việc trẻ, năng động'', ''Lộ trình thăng tiến rõ ràng'', ''Chế độ nghỉ phép, nghỉ lễ tết, hiếu, hỉ, sinh nhật, team building'', ''Thưởng các ngày Lễ, Tết, thưởng thành tích, thưởng năm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (245, 9, 7, 'Thực Tập Sinh Marketing', 'Lọc dữ liệu khách hàng, gắn nhãn và sắp xếp trên hệ thống lưu trữ, báo cáo số liệu thống kê; Salephone tư vấn sơ bộ đến khách hàng, ghi nhận nhu cầu khách hàng; Hỗ trợ livestream giới thiệu dự án; Edit video ngắn đơn giản từ ứng dụng Canva, Capcut,…; Các công việc khác theo yêu cầu của cấp quản lý.', 'Không yêu cầu kinh nghiệm – ứng viên sẽ được đào tạo kỹ năng trong quá trình thực tập. Độ tuổi từ 18 đến 22 tuổi, ưu tiên sinh viên năm 2 trở lên hoặc mới tốt nghiệp các ngành Marketing, Quản trị Kinh doanh... Kỹ năng giao tiếp tốt, tự tin trong việc trao đổi qua điện thoại và gặp gỡ trực tiếp khách hàng; có khả năng lắng nghe và thuyết phục khách hàng. Có laptop cá nhân để phục vụ công việc (lọc dữ liệu, nhập liệu, cập nhật thông tin,...). Tác phong làm việc chuyên nghiệp.
Kỹ năng chuyên môn: [''Sử dụng ứng dụng Canva'', ''Sử dụng ứng dụng Capcut'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Tự tin trong việc trao đổi qua điện thoại'', ''Khả năng lắng nghe'', ''Khả năng thuyết phục khách hàng'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), T7 (8:30 đến 12:00)', '[''Hỗ trợ dấu mộc đỏ'', ''Số liệu thực tập'', ''Được đào tạo chuyên sâu về kỹ năng chuyên môn'', ''Cơ hội trở thành nhân viên chính thức'', ''Thời gian linh hoạt'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (246, 10, 7, 'Người tạo nội dung (Bán thời gian)', 'Lên ý tưởng, viết kịch bản nội dung video dài 1 phút quảng cáo sản phẩm cho khách hàng và cho công ty. Có thể làm VJ (nếu kịch bản cần). Tham gia vào quá trình sản xuất, dựng video đảm bảo kịch bản được triển khai đúng tiến độ, đúng ý tưởng. Nghiên cứu xu hướng, hashtag và nội dung phổ biến trên TikTok để đảm bảo nội dung sáng tạo luôn cập nhật và thu hút.', 'Có tư duy viết kịch bản TikTok, am hiểu nền tảng TikTok. Đam mê và có khả năng sáng tạo, kỹ năng giao tiếp tốt. Là sinh viên năm 3, năm cuối các trường Đại học chuyên ngành Marketing, Báo chí, Truyền thông, Quan hệ công chúng,... và các ngành liên quan khác. Là người cần thận, tỉ mì. Linh động thời gian, đàm bào tối thiểu 5 ca sáng - chiều trên tuần. Laptop cá nhân.
Kỹ năng chuyên môn: [''Tư duy viết kịch bản TikTok'', ''Am hiểu nền tảng TikTok'']
Kỹ năng mềm: [''Đam mê và có khả năng sáng tạo'', ''Kỹ năng giao tiếp tốt'', ''Cần thận, tỉ mỉ'', ''Linh động thời gian'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00), Sáng thứ 7 (8:30-12h)', '[''Môi trường làm việc thoải mái, sáng tạo, trẻ trung'', ''Cơ hội tham gia khóa học, workshop trong và ngoài công ty'', ''Mở rộng network'', ''Cơ hội gặp gỡ các KOC/KOLs'', ''Trở thành nhân viên chính thức với mức lương cạnh tranh'', ''Được hướng dẫn nếu chưa có kinh nghiệm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (247, 2, 7, 'Nhân Viên Content Creator (Part Time)', '- Xây dựng, quản lý nội dung (bao gồm viết nội dung, trình bày ý tưởng về hình ảnh) trên Fanpage, Website. - Chịu trách nhiệm sản xuất nội dung truyền thông (Digital/Offline,...) như bài viết, idea video / hình ảnh,... - Tham gia cùng team xây dựng và quản lý các chiến dịch Marketing, đóng góp các ý tưởng nội dung sáng tạo cho chiến dịch Digital Marketing. - Biên tập nội dung truyền thông trên các kênh truyền thông của Công ty (Email, nội dung PR báo chí, Nội dung seeding,...) - Xây dựng nội dung email marketing, phát triển group khách hàng. - Thực hiện các công việc theo chỉ đạo trực tiếp từ trưởng bộ phận và Ban lãnh đạo.', '- Tốt nghiệp Đại học chuyên ngành Marketing, Truyền thông là 1 lợi thế. - Kinh nghiệm làm việc: từ 1 năm trở lên tại vị trí tương đương trong lĩnh vực Bất động sản. - Đam mê viết lách, yêu thích công việc làm nội dung, có khả năng diễn đạt ý tưởng tốt bằng con chữ. - Nhanh nhạy với xu hướng marketing. - Nhanh nhẹn, biết cách tổ chức và sắp xếp công việc. - Tinh thần làm việc có trách nhiệm, biết cách phối hợp nhóm và có khả năng làm việc độc lập.
Kỹ năng chuyên môn: [''Sáng tạo nội dung'', ''Viết Nội Dung'', ''Quản Lý Mạng Xã Hội'', ''Seo Cơ Bản'', ''Chỉnh Sửa Hình Ảnh'', ''Video Cơ Bản'']
Kỹ năng mềm: [''Đam mê viết lách'', ''Nhanh nhạy với xu hướng marketing'', ''Nhanh nhẹn'', ''Tổ chức và sắp xếp công việc'', ''Tinh thần làm việc có trách nhiệm'', ''Phối hợp nhóm'', ''Làm việc độc lập'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Giờ giấc làm việc linh hoạt', '[''Làm việc trong môi trường năng động, chuyên nghiệp'', ''Có nhiều cơ hội thăng tiến'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (248, 3, 7, 'Thực Tập Sinh Thiết Kế Đồ Họa', '- Hỗ trợ công việc thiết kế cho phòng Marketing trong thiết kế ấn phẩm, post social của công ty... - Hỗ trợ thiết kế theo nhận diện thương hiệu - Cắt ghép, chỉnh sửa video ngắn - Hỗ trợ công tác tổ chức sự kiện của công ty - Thực hiện các công việc khác theo sự phân công của trưởng phòng', '- Sinh viên đang theo học ngành Thiết kế tại các trường Cao Đẳng, Đại học - Không yêu cầu kinh nghiệm nhưng cần thái độ làm việc nghiêm túc - Đam mê thiết kế, thẩm mỹ tốt, giàu ý tưởng sáng tạo - Có sản phẩm demo/Porfolio là một lợi thế - Trung thực, ham học hỏi.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'']
Kỹ năng mềm: [''Thái độ làm việc nghiêm túc'', ''Đam mê thiết kế'', ''Thẩm mỹ tốt'', ''Giàu ý tưởng sáng tạo'', ''Trung thực'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh, quận 2', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Tối thiểu 3 ngày/tuần, Sáng: 8h00 đến 12h00, Chiều: 13h30 đến 17h30', '[''Được hỗ trợ chi phí thực tập'', ''Được làm việc trong môi trường năng động'', ''Được hiểu về hoạt động Marketing trong một doanh nghiệp'', ''Được cân nhắc ký hợp đồng lao động chính thức nếu kết quả thực tập tốt và có tiềm năng'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (249, 7, 7, 'Thực Tập Sinh Thương Mại Điện Tử', 'Hỗ trợ quản lý và vận hành các sàn thương mại điện tử của công ty. Tham gia xây dựng và triển khai các chiến lược bán hàng trực tuyến. Phân tích dữ liệu bán hàng và đề xuất các giải pháp cải thiện hiệu quả. Hỗ trợ quản lý nội dung và hình ảnh sản phẩm trên các nền tảng thương mại điện tử. Tham gia vào quá trình xử lý đơn hàng, theo dõi vận chuyển và chăm sóc khách hàng. Nghiên cứu thị trường và đối thủ cạnh tranh trong lĩnh vực thương mại điện tử. Hỗ trợ các hoạt động marketing online để tăng lượng truy cập và chuyển đổi.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các ngành Kinh tế, TMĐT, Marketing, CNTT hoặc các ngành liên quan. Không yêu cầu kinh nghiệm làm việc trước đó. Có hiểu biết cơ bản về thương mại điện tử và xu hướng thị trường online. Thành thạo tin học văn phòng, đặc biệt là Excel. Có kỹ năng phân tích và tổng hợp dữ liệu. Có khả năng làm việc độc lập và theo nhóm. Chủ động, sáng tạo và có khả năng học hỏi nhanh. Có kỹ năng giao tiếp và viết lách tốt. Ưu tiên ứng viên có kinh nghiệm sử dụng các nền tảng thương mại điện tử. Thực tập full time.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng, đặc biệt là Excel'']
Kỹ năng mềm: [''Kỹ năng phân tích và tổng hợp dữ liệu'', ''Khả năng làm việc độc lập và theo nhóm'', ''Chủ động, sáng tạo và có khả năng học hỏi nhanh'', ''Kỹ năng giao tiếp và viết lách tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 09:00 đến 13:00)', '[''Được đào tạo chuyên sâu về thương mại điện tử và kỹ năng làm việc'', ''Có cơ hội được làm việc trong môi trường chuyên nghiệp, năng động'', ''Được tham gia các dự án thực tế và đóng góp ý kiến'', ''Có cơ hội được nhận vào làm chính thức sau khi kết thúc thời gian thực tập'', ''Hỗ trợ mộc và báo cáo thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (250, 8, 7, 'Media & Design Intern', 'Hỗ trợ setup góc quay, chuẩn bị ekip và kỹ thuật quay phim (chiếm khoảng 40% công việc). Hỗ trợ thiết kế hình ảnh, poster và các nội dung thị giác khác (chiếm khoảng 60%). Tham gia các công việc khác theo hướng dẫn của mentor và phù hợp với vị trí.', 'Sinh viên năm 3-4 ngành liên quan đến media, thiết kế đồ họa hoặc lĩnh vực tương đương. Đam mê thiết kế và sáng tạo nội dung. Có kỹ năng sử dụng các phần mềm Adobe Photoshop, AI hoặc các phần mềm thiết kế đồ họa khác. Chịu học hỏi, ham học hỏi và mong muốn phát triển kỹ năng đa dạng trong lĩnh vực media và thiết kế. Ứng viên gửi portfolio đính kèm.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'']
Kỹ năng mềm: [''Chịu học hỏi'', ''Ham học hỏi'', ''Sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 17:30)', '[''Được đào tạo, hướng dẫn về chuyên môn'', ''Hỗ trợ lương trong quá trình thực tập'', ''Hỗ trợ phụ cấp theo chính sách công ty'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (251, 9, 7, 'TTS Content Lĩnh Vực Tâm Linh Phật Giáo Có Hỗ Trợ', 'Hỗ trợ triển khai sáng tạo nội dung cho các kênh Facebook, Tiktok của công ty. Phối hợp với bộ phận media sáng tạo các kịch bản, ấn phẩm chất lượng đăng tải trên các nền tảng( nội dung, hình ảnh, video...) đảm bảo nội dung sinh động và cuốn hút. Nghiên cứu, chủ động nắm bắt các xu hướng, nhu cầu của người dùng trên các nền tảng mạng xã hội (Facebook, Youtube, Tiktok), đưa ra định hướng về các series, chủ đề nội dung phù hợp cho kênh. Hợp tác cùng Leader team và hỗ trợ các thành viên trong team. Thực hiện các công việc khác theo yêu cầu của quản lý.', 'Không yêu cầu kinh nghiệm, được đào tạo bài bản. Sinh viên năm 1-4 các trường Cao đẳng - Đại học, thuộc các chuyên ngành: Truyền thông, Marketing, Báo Chí, Văn Hóa, Nhân Văn. Yêu thích lĩnh vực Văn Hóa Phật Giáo - Tín Ngưỡng Dân Gian - Phong Thủy, Sản Phẩm Tâm Linh là lợi thế. Có đam mê với lĩnh vực content marketing. Khả năng viết lách tốt, ngôn ngữ chính xác, mạch lạc và hấp dẫn. Nắm vững các nền tảng mạng xã hội phổ biến như Facebook, TikTok, Zalo… Khả năng làm việc độc lập và làm việc nhóm hiệu quả. Trung thực, nhiệt tình, năng động và sáng tạo.
Kỹ năng chuyên môn: [''Khả năng viết lách tốt'', ''Nắm vững các nền tảng mạng xã hội phổ biến như Facebook, TikTok, Zalo'']
Kỹ năng mềm: [''Trung thực'', ''Nhiệt tình'', ''Năng động'', ''Sáng tạo'', ''Khả năng làm việc độc lập và làm việc nhóm hiệu quả'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', 'Linh động theo lịch học', '[''Mức hỗ trợ 3.000.000'', ''Được làm việc trong môi trường năng động, chuyên nghiệp và thân thiện'', ''Được hướng dẫn, đào tạo bài bản để trở thành chuyên gia trong lĩnh vực'', ''Được tham gia vào quá trình lên kế hoạch và triển khai các chiến dịch truyền thông - marketing'', ''Được tham gia vào các sự kiện lớn của Phật Giáo trong năm'', ''Cơ hội làm nhân viên chính thức sau kỳ thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (252, 10, 7, 'Nội dung thực tập', 'Viết bài, biên tập nội dung các bài viết social, email, bài website. Viết bài theo từ khóa được cung cấp, nội dung phù hợp với chủ đề được giao. Quản lý nhóm CTV viết bài, bao gồm theo dõi tiến độ và đánh giá chất lượng bài viết. Chỉnh sửa theo yêu cầu của khách hàng. Đã từng có kinh nghiệm viết bài social,... là một lợi thế. Có thể viết nhiều lĩnh vực là một lợi thế.', 'Có mặt ở công ty tối thiểu 3 ngày /tuần. Có laptop cá nhân. Đảm bảo đúng deadline. Khả năng viết lách tốt, đúng chính tả,... Khả năng tư duy, tìm kiếm, học hỏi nhanh. Có khả năng dịch thuật là một lợi thế. Có trách nhiệm, cẩn thận, tinh thần học hỏi.
Kỹ năng chuyên môn: [''Viết bài'', ''Biên tập nội dung'', ''Sử dụng thành thạo các phần mềm văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Khả năng viết lách tốt'', ''Khả năng tư duy'', ''Có trách nhiệm'', ''Cẩn thận'', ''Tinh thần học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Trợ cấp: 1.000.000/tháng'', ''Được đào tạo kỹ năng viết'', ''Cơ hội học hỏi và phát triển kỹ năng về Content Marketing'', ''Môi trường làm việc năng động, vui vẻ và chuyên nghiệp'', ''Du lịch hàng năm'', ''Team building'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (253, 2, 7, 'Nhân Viên Sáng Tạo Nội Dung', 'Làm việc trực tiếp với Marketing Executive/Account Manager để tạo và thực hiện các kế hoạch truyền thông hàng tháng. Sáng tạo nội dung, theo dõi hiệu quả các bài đăng trên các kênh truyền thông: Facebook, TikTok, Instagram & Threads theo Content Plan. Edit các video ngắn cho TikTok, Facebook theo Content Plan. Hỗ trợ các hoạt động truyền thông khác theo sắp xếp và hướng dẫn của Leader.', 'Sinh viên năm 3 trở lên chuyên ngành Truyền thông/Marketing, có thể làm việc tại văn phòng khoảng 25 giờ/tuần. Yêu thích ngành truyền thông, sáng tạo có hứng thú với Branding và xây dựng các Campaign Marketing. Có khả năng viết nội dung trên các nền tảng mạng xã hội như Facebook, Instagram, Tiktok. Có khả năng sử dụng tốt / thành thạo các ứng dụng như Capcut, Canva. Chủ động theo dõi tiến độ công việc, nắm chắc thông tin sản phẩm và tài liệu của chương trình học. Chủ động cập nhật các xu hướng nội dung, xu hướng marketing trên các nền tảng mạng xã hội. Nghiêm túc và cầu tiến trong công việc, đảm bảo đúng deadline.
Kỹ năng chuyên môn: [''Sáng tạo nội dung'', ''Viết Nội Dung Seo Cơ Bản'', ''Sử Dụng Thành Thạo Các Phần Mềm Văn Phòng (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Chủ động theo dõi tiến độ công việc'', ''Nghiêm túc và cầu tiến trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Môi trường làm việc trẻ trung, năng động'', ''Giờ giấc làm việc linh hoạt'', ''Cơ hội học tập, trau dồi hướng tới vị trí nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (254, 3, 7, 'Thực Tập Marketing', 'USEED International là tổ chức hoạt động chuyên nghiệp trong lĩnh vực tư vấn du học và dịch vụ visa du lịch quốc tế. Sau hơn 10 năm hoạt động, USEED International đã có những bước phát triển vững chắc khi đưa được hàng ngàn học sinh, sinh viên Việt Nam sang du học tại nhiều nước trên thế giới như: Mỹ, Úc, Canada, Singapore, Châu Âu.', 'Đảm bảo có mặt tại văn phòng ít nhất 3 ngày 1 tuần. Sinh viên năm cuối hoặc mới tốt nghiệp các ngành: Marketing, Kinh tế, Sư phạm,… Có khả năng sáng tạo nội dung trên các nền tảng mạng xã hội, website và có khả năng viết lách. Có thể thực tập toàn thời gian từ 2 – 3 tháng. Có khả năng giao tiếp tiếng Anh ở mức khá tốt. Biết sử dụng công nghệ, phần mềm ứng dụng cho Marketing.
Kỹ năng chuyên môn: [''Sáng tạo nội dung trên các nền tảng mạng xã hội'', ''Sử dụng công nghệ, phần mềm ứng dụng cho Marketing'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Kỹ năng viết lách'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được thực tế trải nghiệm các công việc Marketing'', ''Được đào tạo trong quá trình thực tập'', ''Học cách lập kế hoạch content, thiết kế cơ bản và tổ chức sự kiện'', ''Được hỗ trợ dấu mộc thực tập'', ''Cơ hội làm việc với đối tác nước ngoài'', ''Môi trường làm việc năng động, cơ hội mở rộng network với đại diện các trường quốc tế'', ''Nâng cao khả năng tiếng Anh'', ''Giấy chứng nhận đã hoàn thành Kỳ Thực Tập từ USEED International'', ''Có cơ hội trở thành nhân viên chính thức ngay sau khi tốt nghiệp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (255, 7, 7, 'Intern Marketing', 'Quản lý và phát triển các kênh social media. Sáng tạo nội dung, đồng bộ nhận dạng thương hiệu qua các nền tảng mạng xã hội. Phát triển độc lập các nội dung trên từng nền tảng khác nhau. Chụp hình, quay dựng lên ý tưởng cho các chiến dịch quảng cáo trên các nền tảng Facebook, Tiktok. Quản lý và phát triển sản phẩm trên các sàn TMĐT. Lên kế hoạch chạy ads hiệu quả và phù hợp với ngân sách được đề ra. Theo dõi và đánh giá độ hiệu quả của các hoạt động marketing. Quản lý và lên kế hoạch Tìm hiểu khách hàng & thị trường. Tham gia và hỗ trợ vào các hoạt động khác của công ty.', 'Yêu Cầu & Trình Độ Chuyên Môn: Thực tập- Intern (sinh viên or mới tốt nghiệp) Chuyên ngành marketing hoặc kinh tế Có khả năng làm việc độc lập và theo nhóm Nhạy bén, bắt trend, viết nội dung sáng tạo, độc đáo Trung thực, cẩn thận, chăm chỉ, có trách nhiệm cao trong công việc
Kỹ năng chuyên môn: [''Social Media Marketing'', ''Viết nội dung'']
Kỹ năng mềm: [''Khả năng làm việc độc lập'', ''Khả năng làm việc theo nhóm'', ''Nhạy bén'', ''Chăm chỉ'', ''Trung thực'', ''Cẩn thận'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Môi trường làm việc chuyên nghiệp'', ''Cơ hội thăng tiến'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (256, 8, 7, 'Nhân Viên Design Online', 'Thiết kế các sản phẩm nghành POD, thị trường Mỹ và EU, các sản phẩm: mug, t-shirt, doormat, tumbler ... Design Graphic 2D và 3D theo những ý tưởng được giao trực tiếp từ bộ phần ideas.', '1. Có kinh nghiệm về design graphic POD 6 tháng trở lên. 2. Thành thạo PTS, Illustrator, ... có thẩm mĩ, ưa sáng tạo 3. Đảm Bảo Hiệu Quả công việc (được yêu cầu từ đầu) 4. Cẩn thận, tỉ mỉ; 5. Trách nhiệm cao và đạo đức tốt. Tinh thần hướng đến mục tiêu chung
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Trách nhiệm cao'', ''Đạo đức tốt'', ''Tinh thần hướng đến mục tiêu chung'']', 'FREELANCE', 'ONSITE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 15000000.00, '12.0 - 15.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Thưởng hiệu quả làm việc'', ''Được training bởi đội ngũ designer giàu kinh nghiệm'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (257, 9, 7, 'Thực Tập Sinh Marketing', 'Cập nhật xu hướng, trend, chuyển đổi trend hoặc tạo content mới vào ngành bảo hiểm. Phân tích sản phẩm công ty, thị trường ngành bảo hiểm. Lên từ 3-4 script về sản phẩm, tuyển dụng trong 1 tuần. Đào tạo và hỗ trợ các nhân viên: hướng dẫn sử dụng công cụ, phầm mềm của công ty.', 'Sinh viên năm thứ 4 các ngành kinh tế, ngoại thương, ngoại ngữ, marketing… hoặc sinh viên năm 3 nhưng đã hoàn thành hầu hết chương trình học. Ưu tiên các bạn có kiến thức và kinh nghiệm về viết content marketing,… Có khả năng làm việc độc lập và theo nhóm. Nhiệt tình, vui vẻ, yêu thích công việc kinh doanh và giao dịch với khách hàng, có trách nhiệm cao trong công việc và chịu được áp lực. Sắp xếp được thời gian hợp lý giữa việc học và đi làm. Thời gian làm việc: 8h/ ngày từ thứ 2 đến thứ 6. Cam kết thời gian thực tập đủ 2 tháng.
Kỹ năng chuyên môn: [''Viết content marketing'']
Kỹ năng mềm: [''Làm việc độc lập'', ''Làm việc nhóm'', ''Nhiệt tình'', ''Vui vẻ'', ''Có trách nhiệm cao trong công việc'', ''Chịu được áp lực'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '8h/ ngày từ thứ 2 đến thứ 6', '[''Chế độ làm việc linh hoạt'', ''Cung cấp dấu mộc thực tập'', ''Được đào tạo, thực hành những kinh nghiệm'', ''Tham gia vào môi trường làm việc trẻ, năng động, nhiệt huyết'', ''Có phụ cấp đi lại hàng tháng'', ''Hỗ trợ tạo điều kiện không để ảnh hưởng đến việc học tập'', ''Có cơ hội lên nhân viên chính thức nếu có kết quả làm việc tốt'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (258, 10, 7, 'Tiếp thị thực tập (nghiên cứu AI)', 'Phát triển nội dung điều khiển AI và ý tưởng sáng tạo cho các nền tảng truyền thông xã hội. Tiến hành nghiên cứu, phân tích và tài liệu đào tạo về cách AI có thể được áp dụng cho các nhiệm vụ tiếp thị. Hỗ trợ phát triển sản phẩm AI Mentor với trọng tâm là các tính năng liên quan đến tiếp thị. Tham gia vào các dự án tập trung vào việc xây dựng và tăng cường các công cụ AI cho các chiến dịch tiếp thị. Hỗ trợ các quy trình nội bộ trong bộ phận tiếp thị và các nhiệm vụ liên quan khác.', 'A 3rd or 4th-year student majoring in Marketing, Communications, Business, or related fields. Strong interest in AI and its applications in marketing. Basic knowledge in social media platforms or marketing in general (experience with AI tools is a plus). Prefer good English skills (both written and verbal). Honest, hardworking, proactive and eager to learn, want to have ownership of your works.
Kỹ năng chuyên môn: [''Basic knowledge in social media platforms'', ''Experience with AI tools (a plus)'']
Kỹ năng mềm: [''Strong interest in AI and its applications in marketing'', ''Good English skills (both written and verbal)'', ''Honest'', ''Hardworking'', ''Proactive'', ''Eager to learn'', ''Desire to have ownership of works'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:30 đến 18:00)', '[''Dynamic and creative working environment'', ''Flexible working hours with a hybrid model'', ''Access to premium AI tools and productivity platforms'', ''Training provided on professional skills and foundational knowledge in AI research and application'', ''Direct exposure to real-world projects and cutting-edge AI tools'', ''Clear career growth path and regular performance feedback'', ''Supportive and collaborative team culture'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (259, 2, 7, 'Thực Tập Sinh Sale Marketing', 'Hỗ trợ đội ngũ kinh doanh trong việc tìm kiếm và phát triển khách hàng. Tham gia vào các hoạt động marketing và quảng bá sản phẩm công ty. Nghiên cứu thị trường và phân tích dữ liệu để đưa ra các báo cáo. Tham gia vào các buổi họp và thảo luận để đưa ra ý tưởng phát triển dự án. Quản lý và phát triển nội dung trên fanpage.', 'Sinh viên năm 3-4 hoặc mới tốt nghiệp các ngành kinh tế, quản trị kinh doanh, marketing. Tham gia làm việc 4 buổi/tuần, thời gian tối thiểu 2 tiếng/buổi. Có đam mê và mong muốn học hỏi lĩnh vực mới. Kỹ năng giao tiếp tốt và có khả năng làm việc nhóm. Biết quay – dựng clip cơ bản bằng điện thoại (CapCut, TikTok Editor, v.v…). Nhanh nhẹn, chủ động và có tinh thần cầu tiến. Tham gia đầy đủ 03 ngày đào tạo công ty.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng làm việc nhóm'', ''Biết quay – dựng clip cơ bản bằng điện thoại (CapCut, TikTok Editor, v.v…)'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chủ động'', ''Có tinh thần cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 10:00), tham gia làm việc 4 buổi/tuần, thời gian tối thiểu 2 tiếng/buổi', '[''Được đào tạo và hướng dẫn chi tiết bởi các chuyên gia trong ngành'', ''Cơ hội thực hành và phát triển kỹ năng nghề nghiệp'', ''Hỗ trợ dấu mộc sau 45 ngày làm việc cho các thực tập sinh có thành tích tốt'', ''Hỗ trợ chi phí thực tập khi phát sinh giao dịch'', ''Có cơ hội trở thành nhân viên chính thức sau khi kết thúc thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (260, 3, 7, 'Trợ lý quản lý thương hiệu', 'Quản lý và lên kế hoạch Marketing (ATL & BTL) để phát triển doanh số nhóm sản phẩm sử dụng hình ảnh bản quyền (IP-Intellectual property), bao gồm cả IP mua bản quyền từ quốc tế và IP do công ty tự sáng tạo. Làm việc chặt chẽ với chủ sở hữu IP để đảm bảo tuân thủ quyền sử dụng và phát triển sản phẩm phù hợp với hình ảnh thương hiệu. Hợp tác với đội ngũ phát triển sản phẩm để thiết kế và triển khai các sản phẩm mới, đảm bảo tích hợp IP một cách sáng tạo và hiệu quả. Theo dõi và phân tích xu hướng thị trường, đề xuất chiến lược sử dụng hình ảnh IP vào sản phẩm, tìm kiếm IP mới phù hợp với định hướng kinh doanh của công ty và thị trường hoặc sáng tạo tạo IP mới. Tổ chức và quản lý các chiến dịch quảng cáo và khuyến mãi liên quan đến sản phẩm IP, từ ATL đến BTL. Đảm bảo rằng tất cả các hoạt động quảng cáo và tiếp thị đều phản ánh đúng giá trị và thông điệp của thương hiệu. Làm việc chặt chẽ với các bộ phận phòng ban & chủ sở hữu IP để triển khai thông suốt kế hoạch phát triển sản phẩm, tung hàng, kinh doanh và báo cáo. Thực hiện phân tích số liệu đánh giá sức khỏe Nhãn hàng, danh mục sản phẩm: Doanh số, sản lượng, xu hướng phát triển của Nhãn hàng, sản phẩm để đề xuất hướng phát triển theo yêu cầu của QLNH. Triển khai thực hiện các hoạt động quảng bá hình ảnh, định vị Nhãn hàng theo kế hoạch đã được duyệt từ cấp trên. Hỗ trợ QLNH quản lý, theo dõi việc sử dụng hình ảnh sản phẩm/nhãn hàng trên các kênh truyền thông, điểm bán,… & các thiết kế công bố ra bên ngoài khác. Đảm bảo tính nhất quán về thông điệp và tính cách Nhãn hàng trong các sự kiện có sự xuất hiện của Nhãn hàng trên các phương tiện truyền thông, điểm bán. Tham gia trực tiếp, kiểm soát nội dung của các hoạt động liên quan đến việc đào tạo/giới thiệu sản phẩm và Nhãn hàng. Cập nhật hình ảnh sản phẩm, nhãn hàng tại điểm bán để có các đề xuất khi cần thiết. Quản lý & cập nhật nội dung thông tin Nhãn hàng, sản phẩm trên các website, fanpage, youtube… theo định hướng nội dung đã thống nhất với QLNH. Duy trì tương tác với các thành viên của trang. Phối hợp với Bộ phận Thiết kế và Phát triển sản phẩm mới thực hiện các ấn phẩm quảng bá và hỗ trợ bán hàng: mô tả sản phẩm, bao bì mùa vụ, sản phẩm mùa vụ, tờ rơi… Phối hợp với BP. R&D, CAT về thông tin sản phẩm mới, thiết kế Mô tả sản phẩm mới, trao đổi thông tin nhu cầu và xu hướng thị trường, thị hiếu người tiêu dùng thực hiện các phương án sản sản phẩm mới. Phối hợp với BP. Mua Hàng lựa chọn NCC cho từng chiến dịch cụ thể. Phối hợp với BP. Sản Xuất cho tiến độ SP mới hoặc SP theo dự án. Phối hợp với BP. Kinh doanh về việc lên kế hoạch & triển khai các hoạt động bán hàng. Phối hợp với Khối Tài chính Kế toán của Tập đoàn nhằm tuân thủ theo các chính sách chung, hoàn thiện các hồ sơ, thủ tục thanh toán cho các chương trình marketing. Phối hợp với Khối Quản trị Chất lượng Toàn diện (TQM) của Tập đoàn về hồ sơ kiểm soát chất lượng của các sản phẩm mang tính bán hàng mùa vụ; các sản phẩm sử dụng cho các chương trình Marketing khác; thông tin báo cáo về Thỏa mãn khách hàng hằng năm. Phối hợp với BP. Điều Phối của Tập đoàn và các công ty con đối với tiến độ sản xuất & phân bổ ra thị trường nhóm SP bán hàng mùa vụ & tiến độ phân bổ các vật phẩm POSM tại Điểm bán. Phối hợp với TLHC, HTTL hoặc các BP liên quan theo chỉ định của QLNH: cải tiến sản phẩm hiện có; các ý tưởng liên quan đến quảng bá Nhãn hàng, sản phẩm, hoạt động hỗ trợ bán hàng cho điểm bán, các chương trình cho NTD cuối cùng. Bảo mật thông tin liên quan. Lập Báo cáo định kỳ hàng tuần, tháng, quý hoặc báo cáo đột xuất cho QLNH.', 'Tốt nghiệp Đại học trở lên chuyên ngành Kinh tế/ Quản trị kinh doanh/ Marketing hoặc các ngành nghề liên quan. Tối thiểu 2 năm kinh nghiệm làm việc ở vị trí tương đương tại các Công ty, Tập đoàn. Có kiến thức về lĩnh vực Tiếp thị và vận dụng vào thực tế; Có kiến thức về nghiệp vụ Tiếp thị sản phẩm, dịch vụ và thương hiệu; Khả năng phân tích tốt, chịu áp lực công việc. Tiếng Anh thương mại: Tốt. Ưu tiên đã có kinh nghiệm quản lý các sản phẩm sử dụng hình ảnh IP.
Kỹ năng chuyên môn: [''Kiến thức về lĩnh vực Tiếp thị'', ''Kiến thức về nghiệp vụ Tiếp thị sản phẩm, dịch vụ và thương hiệu'']
Kỹ năng mềm: [''Khả năng phân tích tốt'', ''Chịu áp lực công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:45)', '[''Lương tháng 13'', ''Thưởng KPI cuối năm'', ''Phụ cấp cơm trưa'', ''Chế độ BHXH'', ''Nghỉ phép năm'', ''Thưởng Tết'', ''Thưởng Lễ 30/04, 02/09'', ''Các khoản phúc lợi theo chính sách của Công ty'', ''Tham gia các chương trình đào tạo kỹ năng chuyên môn'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (261, 7, 7, 'Thực Tập Sinh Graphic Design', 'Thiết kế các ấn phẩm quảng cáo phục vụ cho hoạt động kinh doanh của công ty thời trang, bao gồm: banner website, poster, catalogue, brochure, hình ảnh sản phẩm, thiết kế nội dung truyền thông trên mạng xã hội (social media). Phối hợp với bộ phận Marketing để lên ý tưởng thiết kế, đảm bảo tính thống nhất về thương hiệu và phù hợp với chiến lược truyền thông. Chỉnh sửa và hoàn thiện các thiết kế theo yêu cầu của khách hàng hoặc cấp trên. Quản lý và lưu trữ file thiết kế. Nghiên cứu xu hướng thiết kế mới, cập nhật kiến thức và kỹ năng liên quan đến lĩnh vực thiết kế đồ họa.', 'Tốt nghiệp Cao đẳng/Đại học chuyên ngành Thiết kế đồ họa hoặc các chuyên ngành liên quan. Có thể thực tập toàn thời gian và thực tập 3 tháng. Có kinh nghiệm trong lĩnh vực thiết kế đồ họa sẽ là lợi thế, ưu tiên ứng viên có kinh nghiệm làm việc trong ngành thời trang. Thành thạo phần mềm Adobe Photoshop, Adobe Illustrator. Có gu thẩm mỹ tốt, khả năng sáng tạo và nắm bắt xu hướng thiết kế hiện đại. Khả năng làm việc độc lập và làm việc nhóm tốt. Có tinh thần trách nhiệm cao, cẩn thận, tỉ mỉ trong công việc. Khả năng giao tiếp tốt, chủ động trong công việc.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'']
Kỹ năng mềm: [''Khả năng sáng tạo'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Tinh thần trách nhiệm cao'', ''Cẩn thận'', ''Tỉ mỉ'', ''Khả năng giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Hỗ trợ trợ cấp thực tập: 3.000.000 VNĐ/tháng'', ''Trợ cấp tiền ăn trưa và giữ xe'', ''Hỗ trợ dấu mộc thực tập và báo cáo thực tập'', ''Môi trường làm việc năng động, chuyên nghiệp và thân thiện'', ''Cơ hội được lên chính thức sau thời gian thực tập'', ''Quà tặng các dịp Lễ, Tết, Trung Thu, Quốc Tế Phụ Nữ'', ''Tham gia các hoạt động YEP, team building, du lịch, nghỉ mát hàng năm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (262, 8, 7, 'Content Sáng Tạo Nội Dung (Tiếng Anh)', 'Công việc chính: Quản trị và sáng tạo nội dung mạng xã hội. Nhanh nhạy, nắm bắt tin tức hot trên mạng xã hội để sáng tạo các content kiến thức liên quan cho kênh, biết cách chuyển hóa tin phù hợp với màu sắc của page. Có khả năng sáng tạo, khai thác được các góc nhìn mới lạ, thú vị, có góc nhìn đa chiều trong một vấn đề và khai thác quan điểm cá nhân tốt. Kiểm soát nội dung đã đăng tải: theo dõi và lắng nghe ý kiến đóng góp từ khán giả. Tương tác, kết nối với người xem. Báo cáo hiệu quả nội dung, hiệu quả công việc lên leader. Thực hiện các công việc khác theo yêu cầu của leader.', 'Tư duy sáng tạo, linh hoạt, nhìn vấn đề đa chiều. Ưu tiên có kinh nghiệm hoặc đam mê trong lĩnh sáng tạo nội dung; xây dựng nội dung trên các kênh cộng đồng. Mặt sáng, giao tiếp tốt là một lợi thế. Chủ động cập nhật trending phù hợp với khách hàng mục tiêu. Kỹ năng làm việc nhóm, truyền tải ý tưởng tốt. Đam mê công việc, sáng tạo, siêng năng, kiên nhẫn, có trách nhiệm và chịu được áp lực công việc. QUAN TRỌNG NHẤT là có thái độ cầu tiến và cam kết đúng deadline.
Kỹ năng chuyên môn: [''Content Research Skills'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Linh hoạt'', ''Kỹ năng làm việc nhóm'', ''Truyền tải ý tưởng tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '3.5 - 10.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Làm việc trong môi trường trẻ, mọi ý tưởng đều được lắng nghe'', ''Du lịch, teambuilding theo quy định của công ty'', ''Tăng lương theo năng lực và hiệu quả làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (263, 9, 7, 'NHÂN VIÊN Content Marketing', 'Viết bài đăng cho fanpage Facebook và website công ty. Lên ý tưởng, triển khai nội dung quảng bá sản phẩm, khuyến mãi, thương hiệu. Chỉnh sửa ảnh sản phẩm và poster đơn giản (dùng Canva, hoặc phần mềm cơ bản). Cắt ghép video ngắn (review, hướng dẫn sử dụng, feedback khách hàng...). Phối hợp với đội ngũ bán hàng/marketing để cập nhật nội dung phù hợp theo từng giai đoạn.', 'Không yêu cầu kinh nghiệm, sẽ được hướng dẫn khi vào làm. Ưu tiên bạn có kỹ năng viết tốt, yêu thích sáng tạo nội dung. Biết sử dụng công cụ thiết kế ảnh cơ bản (Canva, Photoshop cơ bản). Có thể chỉnh sửa video đơn giản (CapCut). Có trách nhiệm, làm việc đúng deadline.
Kỹ năng chuyên môn: [''Canva'', ''Photoshop cơ bản'', ''CapCut'']
Kỹ năng mềm: [''Kỹ năng viết tốt'', ''Yêu thích sáng tạo nội dung'', ''Có trách nhiệm'', ''Làm việc đúng deadline'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (08:00 - 12:00, 13:30 - 17:30)', '[''Thưởng nếu đạt KPI'', ''Môi trường làm việc năng động, thoải mái'', ''Được học hỏi thêm về marketing, thiết kế và thương mại điện tử'', ''Cơ hội trở thành nhân viên chính thức nếu phù hợp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (264, 10, 7, 'Thực Tập Sinh Growth/Content Marketing', 'Viết content (ưu tiên cho video) để phát triển người dùng trên đa kênh: Tiktok, Facebook, Instagram, .v.v.v. Làm các dự án “điên” mà đầy sáng tạo cùng team Growth.', '1. Có định hướng theo ngành Marketing và đã tìm hiểu cơ bản về Marketing: SEO, Website, content… 2. Ưu tiên ứng viên có kỹ năng về chỉnh sửa ảnh và video trên máy tính. 3. Dám làm điều khác biệt cùng với team growth.
Kỹ năng chuyên môn: [''Kỹ năng chỉnh sửa ảnh'', ''Kỹ năng chỉnh sửa video'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Trợ cấp 3 triệu/tháng'', ''Hỗ trợ dấu xác nhận thực tập'', ''Được làm việc trong môi trường start-up trẻ trung, năng động và đầy thử thách'', ''Được đào tạo, nâng cao nghiệp vụ'', ''Có cơ hội trở thành nhân viên chính thức sau thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (265, 2, 7, 'Thực Tập Sinh Marketing', 'Khảo sát, nghiên cứu thị trường, nghiên cứu đối thủ.... Content Hình ảnh, nội dung kịch bản, dựng, edit… LÀM AI. Thực hiện các công cụ Marketing miễn phí và có phí… Xây dựng, theo dõi, chăm sóc group, page... bán hàng các nền tảng Youtube, Facebook, IG, Zalo, Instagram... Được hướng dẫn cụ thể và cung cấp tài liệu nghiên cứu để hoàn thành tốt công việc.', 'Không yêu cầu Kinh nghiệm. Nếu ứng viên có hiểu biết cơ bản về các công việc trên là một lợi thế. Đam mê nền tảng youtube, Tiktok...Cập nhật, nắm bắt thường xuyên xu thế mới. Có Laptop cá nhân. Làm việc tối thiểu 4 buổi/tuần và 4ngày/tuần(với SV cần Hỗ trợ đóng dấu mộc thực tập sinh). Có trách nhiệm công việc, có khả năng tự học tốt, tinh thần tốt, đam mê với công việc, siêng năng chăm chỉ, chịu khó học hỏi, sáng tạo và chịu được áp lực học và làm việc.
Kỹ năng mềm: [''Làm việc nhóm'', ''Khả Năng Học Hỏi Nhanh'', ''Trung Thực'', ''Chăm Chỉ'', ''Chịu Khó'', ''Siêng Năng'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Được làm việc với Founder có nhiều năm kinh nghiệm'', ''Được tự do sáng tạo và đề xuất thực hiện ý tưởng mới'', ''Được hướng dẫn về Social, Sáng tạo Content, Marketing...AI'', ''Được trực tiếp triển khai những dự án thực tế của công ty'', ''Hỗ trợ xác nhận Báo cáo kết quả thực tập có đóng dấu mộc'', ''Thưởng nóng khi công việc đạt kết quả tốt (Từ 500.000 đồng - 5.000.000 đồng)'', ''Cơ hội được giữ lại công ty làm việc và phát triển tiếp dự án'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (266, 3, 7, 'Nhân Viên Marketing Part-Time', '+ Viết bài + trực fanpage + Update thông tin khách hàng và chuyển cho team Sales + Hỗ trợ sự kiện tại chi nhánh + Phụ trách hoạt động đi Direct: lên kế hoạch đi, phân công nhân sự và nhiệm vụ, đảm bảo KPI data và lộ trình đi Direct theo kế hoạch + Tham gia họp kế hoạch MKT chi nhánh + Cập nhật và phân tích chương trình MKT của Hội sở (LLV) gửi; đưa ra phương án MKT cho chi nhánh Hà Đông', '- Sinh viên theo học các ngành truyền thông/marketing - Khả năng Đọc/Viết tiếng Anh khá- Biết sử dụng các công cụ Power Point, Excel, Word- Có khả năng Design là một lợi thế
Kỹ năng chuyên môn: [''Power Point'', ''Excel'', ''Word'']
Kỹ năng mềm: [''Khả năng Đọc/Viết tiếng Anh khá'', ''Có khả năng Design là một lợi thế'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', '112h/ tháng, Có ít nhất 2 buổi làm ca từ 17h - 21h', '[''Rate: upto 40k/h'', ''Trang thiết bị, cơ sở vật chất khang trang, hiện đại, đầy đủ'', ''Môi trường quốc tế trẻ trung, thân thiện, năng động'', ''Thưởng cuối năm và thưởng các ngày Lễ, Tết trong năm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (267, 7, 7, 'Thực Tập Sinh Marketing Part-Time', '+ Viết bài + trực fanpage + Update thông tin khách hàng và chuyển cho team Sales + Lên kế hoạch và phối hợp triển khai sự kiện tại chi nhánh + Phụ trách và tham gia hoạt động đi Direct: lên kế hoạch đi, phân công nhân sự và nhiệm vụ, đảm bảo KPI data và lộ trình đi Direct theo kế hoạch + Tham gia họp kế hoạch MKT chi nhánh + Cập nhật và phân tích chương trình MKT của Hội sở (LLV) gửi; đưa ra phương án MKT cho chi nhánh Hà Đông', '- Có thể làm ca tối từ 17h-21h ít nhất 2 ngày/tuần - Sinh viên theo học các ngành truyền thông/marketing - Khả năng Đọc/Viết tiếng Anh khá - Biết sử dụng các công cụ Power Point, Canva để design và edit
Kỹ năng chuyên môn: [''Power Point'', ''Canva'']
Kỹ năng mềm: [''Khả năng Đọc/Viết tiếng Anh khá'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 - 3.5 triệu', 'Được đăng ký ca làm, yêu cầu làm đủ 112h/tháng', '[''Thưởng cuối năm'', ''Thưởng các ngày Lễ, Tết trong năm'', ''Được cấp Máy tính'', ''Môi trường làm việc quốc tế trẻ trung, thân thiện, năng động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (268, 8, 7, 'Thực Tập Content/ SEO Marketing - Làm Việc Online', 'Biên tập nội dung Website, Blog, Forum, Google+, Facebook... Đăng bài viết Website, Blog, Forum, Google+, Facebook... Quản trị Website, Forum, Fanpage... Sử dụng các công cụ Google Analytics, Webmaster và một số công cụ khác liên quan. Được hướng dẫn và họp online hàng tuần theo yêu cầu công việc.', 'Thực tập content: Ưu tiên các bạn nữ chuyên ngành báo chí, truyền thông, văn học hoặc có khả năng viết lách. Thực tập SEO: Ưu tiên các bạn học chuyên ngành công nghệ thông tin. Không yêu cầu kinh nghiệm. Công ty sẽ đào tạo trong quá trình làm việc.
Kỹ năng chuyên môn: [''Sử dụng các công cụ Google Analytics'', ''Webmaster'']
Kỹ năng mềm: [''Quản lý thời gian'', ''Giao tiếp'', ''Làm việc nhóm'', ''Làm việc độc lập'', ''Tính kiên nhẫn'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được đào tạo các kỹ năng phục vụ cho nhu cầu công việc và thực tập'', ''Phát triển các kỹ năng mềm'', ''Nhận lương theo năng lực'', ''Được trải nghiệm nhiều lĩnh vực và các kiến thức chuyên sâu'', ''Cơ hội trở thành nhân viên chính thức của công ty'', ''Hỗ trợ sinh viên thực tập online tại nhà'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (269, 9, 7, 'Thực Tập Sinh Digital Marketing', 'Nắm bắt thông tin liên quan đến sản phẩm được giao triển khai. Tham gia vận hành, quản trị hệ thống thương mại điện tử của công ty. Theo dõi, tổng hợp dữ liệu, phân tích và hoàn thành báo cáo. Quản lý và tối ưu hóa các chiến dịch để đạt mục tiêu theo kế hoạch. Hỗ trợ cho các hoạt động marketing chung.', 'Là sinh viên cao đẳng, đại học năm ba, năm cuối hoặc mới tốt nghiệp chuyên ngành Marketing, Truyền thông, Quản trị kinh doanh, báo chí, thương mại,... hoặc các ngành liên quan. Yêu thích Thương Mại Điện Tử, Marketing & Sử dụng mạng xã hội thành thạo. Không yêu cầu kinh nghiệm, được đào tạo toàn bộ khi nhận việc. Ưu tiên có kỹ năng sử dụng cơ bản các phần mềm như Canva, Capcut. Có laptop.
Kỹ năng chuyên môn: [''Sử dụng mạng xã hội thành thạo'', ''Kỹ năng sử dụng cơ bản các phần mềm như Canva, Capcut'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Thưởng hiệu quả'', ''Thưởng kinh doanh theo Quy định của bộ phận'', ''Được đào tạo chuyên sâu liên tục về Marketing & truyền thông'', ''Làm việc trong môi trường năng động, sáng tạo'', ''Cơ hội vào chính thức sau thời gian thực tập và thăng tiến rõ ràng'', ''Hỗ trợ dấu mộc, thông tin báo cáo thực tập đối với thực tập sinh'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (270, 10, 7, 'Sales Intern', 'Làm việc chặt chẽ với Leader hoặc nhân sự được phân công và hoàn thành tất cả các nhiệm vụ được giao. Tổ chức các workshop theo yêu cầu của AM và chuẩn bị nội dung cho sự kiện (khi cần). Tạo và phát triển các kênh marketing trên mạng xã hội như LinkedIn, Facebook... để tìm kiếm khách hàng tiềm năng. Nghiên cứu và lập danh sách khách hàng tiềm năng. Hỗ trợ phát triển mối quan hệ khách hàng và duy trì các tài khoản hiện có (khi cần).', 'Sinh viên (năm 2 - 4) theo học các chuyên ngành Sales, Quảng cáo, Marketing, Kinh doanh hoặc các ngành liên quan tại nước ngoài. Giao tiếp tiếng Anh tốt là một lợi thế. Có kiến thức về công nghệ thông tin là một điểm cộng. Tinh thần tự giác, chủ động cao trong công việc. Có khả năng làm việc độc lập hoặc theo nhóm. Kỹ năng giao tiếp xuất sắc. Giữ bình tĩnh trong môi trường làm việc nhanh, áp lực cao. Nhanh nhẹn, chăm chỉ, nhiệt huyết.
Kỹ năng chuyên môn: [''Kiến thức về công nghệ thông tin'']
Kỹ năng mềm: [''Giao tiếp tiếng Anh tốt'', ''Tinh thần tự giác, chủ động cao'', ''Làm việc độc lập hoặc theo nhóm'', ''Kỹ năng giao tiếp xuất sắc'', ''Giữ bình tĩnh trong môi trường làm việc nhanh, áp lực cao'', ''Nhanh nhẹn, chăm chỉ, nhiệt huyết'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được học hỏi từ AM về các kỹ năng như làm việc với khách hàng, xử lý tình huống thực tế'', ''Mở rộng mạng lưới, có cái nhìn toàn diện về sản phẩm & khách hàng, tham gia vào các dự án thực tế'', ''Có cơ hội trở thành nhân viên chính thức sau kỳ thực tập nếu thể hiện tốt'', ''Được đào tạo bài bản về kỹ năng liên quan đến Sales'', ''Được trợ cấp 1 triệu/ tháng'', ''Tham gia vào các hoạt động của công ty: happy hour, team fund, birthday'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (271, 2, 7, 'Thực Tập Sinh Booking KOL/KOC', 'Tìm kiếm và Xây dựng Mối Quan hệ Creator: Chủ động tìm kiếm và xác định các creator (KOL/KOC) phù hợp với hình ảnh và mục tiêu của thương hiệu. Xây dựng mối quan hệ lâu dài, vững chắc và mời họ hợp tác chiến lược cùng nhãn hàng. Quản lý và Vận hành Team Creator Nội Bộ: Hỗ trợ thiết lập và vận hành hiệu quả đội ngũ creator nội bộ (in-house), đảm bảo họ có đủ công cụ và định hướng để sản xuất nội dung chất lượng cao. Hỗ trợ Vận hành Livestream: Đảm bảo các buổi livestream của KOL/KOC diễn ra suôn sẻ và hiệu quả, bao gồm việc chuẩn bị, hỗ trợ kỹ thuật và sẵn sàng xử lý các vấn đề phát sinh trong suốt phiên live. Phát Triển Kênh Affiliate Marketing: Tăng cường và mở rộng kênh tiếp thị liên kết (Affiliate Marketing) thông qua việc trao đổi và triển khai các chiến dịch với các đối tác affiliate hiện có của công ty. Tham gia Hoạt Động Doanh Nghiệp: Tích cực tham gia vào các hoạt động và sự kiện do công ty tổ chức, góp phần vào sự phát triển chung của đội ngũ và thương hiệu.', '* Sinh viên năm cuối hoặc vừa tốt nghiệp tại Thành phố Hồ Chí Minh; * Có niềm đam mê với Marketing. Thích làm việc với KOL/KOC. * Có kiến thức về KOL/KOC, influencer. Có kinh nghiệm làm việc trong mảng booking KOL, các sàn thương mại điện tử, đặc biệt là Tiktok là một lợi thế. * Nhanh nhạy và nắm bắt được tâm lý người dùng trên các nền tảng mạng xã hội (Facebook, Tiktok,…) * Kỹ năng giao tiếp, kỹ năng làm việc nhóm tốt. * Thái độ trung thực, chịu khó học hỏi. * Kỹ năng quản lý thời gian hiệu quả và sắp xếp công việc theo tiến độ đưa ra.
Kỹ năng chuyên môn: [''KOL/KOC'', ''influencer'', ''Affiliate Marketing'', ''Social Marketing'', ''TMĐT'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng làm việc nhóm'', ''Quản lý thời gian'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'T2 – T6, thứ 7 làm tại nhà', '[''Hỗ trợ training thực chiến'', ''Lộ trình thăng tiến rõ ràng'', ''Môi trường làm việc chuyên nghiệp'', ''Tham gia các hoạt động vui chơi giải trí'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (272, 3, 7, 'Thực Tập Sinh Content Marketing', 'Sản xuất content hàng ngày cho các kênh web, page, tiktok, group. Hỗ trợ quản trị các kênh theo năng lực. Sáng tạo nội dung viral cho các kênh media. Tham gia tổ chức các hoạt động truyền thông online và offline.', 'Sinh viên đang theo học các nghành MKT, truyền thông, báo chí, kinh doanh... hoặc có đam mê với nghề Marketing. Có kỹ năng viết cơ bản; ưu tiên sử dụng được các công cụ chỉnh sửa ảnh và video căn bản: canva, capcut. Ham học hỏi, năng động, chủ động.
Kỹ năng chuyên môn: [''Kỹ năng viết cơ bản'', ''Sử dụng được các công cụ chỉnh sửa ảnh và video căn bản: canva, capcut'']
Kỹ năng mềm: [''Ham học hỏi'', ''Năng động'', ''Chủ động'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Có lương + phụ cấp theo sản phẩm làm được'', ''Được đào tạo bài bản về Marketing'', ''Được tham gia vào các hoạt động, công việc MKT của doanh nghiệp'', ''Hỗ trợ dấu thực tập nếu cần'', ''Du lịch hàng năm'', ''Team building'', ''Thưởng hiệu quả làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (273, 7, 7, 'Nội dung sáng tạo bán thời gian/toàn thời gian', 'Triển khai các dạng content (tiếng Việt & tiếng Anh) cho thị trường Du lịch qua các kênh SEO, email marketing hoặc social media. Làm việc cùng design team để đảm bảo các materials UX, UI sẽ đồng nhất với concept ban đầu, hoặc tự triển khai thiết kế/ sản xuất các media đơn giản như banner, poster hoặc video. Tìm hiểu thêm về sản phẩm/ dịch vụ/ đối tượng mục tiêu/ insight và những hoạt động của ngành Du lịch. Tham gia vào việc xây dựng chiến lược SEO cho website của công ty, tối ưu hóa website theo tiêu chuẩn SEO.', 'Ưu tiên đã có 06 tháng - 1 năm kinh nghiệm liên tục ở 1 doanh nghiệp trong quá khứ (bao gồm cả part-time/thực tập). Tinh thần học hỏi không ngần ngại. Tiếng Anh tốt (Đọc/viết). Hòa đồng và thích giao tiếp với đồng nghiệp. Yêu cầu làm được tối thiểu 20h/tuần (Đối với Part-time).
Kỹ năng chuyên môn: [''Viết Nội Dung Sáng Tạo'', ''Hiểu Biết Về SEO Cơ Bản'', ''Kỹ Năng Viết Lách Tốt'', ''Quản Lý Thời Gian Hiệu Quả'']
Kỹ năng mềm: [''Tinh thần học hỏi không ngần ngại'', ''Hòa đồng và thích giao tiếp với đồng nghiệp'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Lộ trình phát triển rõ ràng'', ''Môi trường làm việc linh hoạt'', ''Hỗ trợ dấu thức tập khi hoàn thành đủ thời gian thực tập yêu cầu'', ''Có thể xoay ca linh hoạt từ thứ 2 đến thứ 6'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (274, 8, 7, 'CTV Vận Hành Livestream', 'Chuẩn bị và quản lý vận hành các phiên livestream chuyên nghiệp (setup ánh sáng, âm thanh, camera, đường truyền). Đảm bảo phiên livestream được diễn ra theo đúng kế hoạch. Đảm bảo các hoạt động vận hành được diễn ra xuyên suốt phiên livestream: ghim sản phẩm, thêm sản phẩm, chỉnh lỗi phát sinh trên nền tảng, vouchers, quản trị và vận hành nên tảng trong phiên livestream,... Điều phối lịch phát sóng, đảm bảo luồng livestream diễn ra trơn tru. Thúc đẩy tương tác và thu hút khách hàng trong phiên livestream. Hỗ trợ host/ mẫu khi cần.', 'Có trách nhiệm, chăm chỉ, chịu khó học hỏi. Giao tiếp tốt, phản xạ nhanh. Yêu thích lĩnh vực livestream trên các sàn thương mại điện tử. Ưu tiên ứng viên có kinh nghiệm hỗ trợ hoặc tham gia vận hành livestream.
Kỹ năng chuyên môn: [''Sử dụng thành thạo các phần mềm livestream (OBS, Streamyard, v.v.)'']
Kỹ năng mềm: [''Có trách nhiệm'', ''Chăm chỉ'', ''Chịu khó học hỏi'', ''Giao tiếp tốt'', ''Phản xạ nhanh'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '4.0 - 8.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 22:00), Thứ 7 - Chủ nhật (từ 08:00 đến 22:00)', '[''Môi trường làm việc năng động'', ''Có cơ hội học hỏi và phát triển kỹ năng trong lĩnh vực livestream & TMĐT'', ''Thời gian linh hoạt'', ''Được đào tạo và hướng dẫn chi tiết về công việc'', ''Đội nhóm luôn hỗ trợ và giúp đỡ lẫn nhau'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (275, 9, 7, 'Thực Tập Sinh Vận Hành Livestream', 'Triển khai & vận hành các phiên livestream inhouse đảm bảo chất lượng hình ảnh, âm thanh, ánh sáng chuyên nghiệp theo tiêu chuẩn của nền tảng TikTok/Shopee. Lên concept & kịch bản livestream sáng tạo, tối ưu format chương trình sale, minigame, quà tặng nhằm tăng tương tác và tỷ lệ chuyển đổi. Setup & quản lý thiết bị livestream (camera, lighting, âm thanh, phần mềm hỗ trợ, OBS...) để đảm bảo buổi phát sóng mượt mà, ổn định. Phối hợp với Host, KOL/KOC hướng dẫn cách tương tác, diễn xuất trước ống kính để tối ưu hiệu suất bán hàng. Giám sát & điều phối quá trình livestream theo timeline, xử lý sự cố kỹ thuật nhanh chóng để đảm bảo chất lượng buổi phát sóng. Theo dõi & đánh giá dữ liệu livestream (view, comment, tỷ lệ chốt đơn, thời gian xem...), đề xuất phương án cải thiện cho các phiên live tiếp theo. Nghiên cứu & cập nhật công nghệ, xu hướng livestream mới, tối ưu kỹ thuật sản xuất để tăng sức hút và hiệu quả bán hàng.', 'Nhiệt huyết, máu chiến, sẵn sàng lăn xả, chủ động với công việc. Hướng ngoại, giao tiếp tốt, có kỹ năng phối hợp với nhiều bộ phận. Chỉn chu, luôn hoàn thành deadline, cam kết đạt mục tiêu. Sẵn sàng thay đổi, thích ứng nhanh để đạt kết quả vượt trội.
Kỹ năng chuyên môn: [''Sử dụng phần mềm OBS'', ''Quản lý thiết bị livestream'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Hướng ngoại'', ''Chủ động'', ''Thích ứng nhanh'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Trợ cấp thực tập: 3,000,000VND/ 1 tháng'', ''Friday Sharing vào Thứ 6 hàng tuần'', ''Hỗ trợ hoàn thành luận văn/báo cáo tốt nghiệp'', ''Môi trường làm việc năng động, sáng tạo'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (276, 10, 7, 'TTS Sáng Tạo Nội Dung (Thiên Về Tiktok)', 'Tham gia xây dựng ý tưởng nội dung, kịch bản video sáng tạo cho nền tảng TikTok theo định hướng của công ty. Trực tiếp sản xuất video TikTok: lên nội dung, quay dựng cơ bản (nếu cần), phối hợp với team thiết kế & quay phim. Cập nhật liên tục các trending TikTok để đề xuất các format nội dung mới, mang tính viral. Phối hợp với các phòng ban để đảm bảo tính đồng nhất về thông điệp và hình ảnh thương hiệu. Viết bài chuẩn SEO phục vụ cho các nền tảng website, fanpage, landing page. Tham gia hỗ trợ tổ chức các sự kiện truyền thông, workshop, livestream (online/offline) theo kế hoạch truyền thông.', 'Sinh viên năm 3, 4 hoặc mới tốt nghiệp các chuyên ngành: Marketing, Báo chí, Truyền thông, Biên tập, Sáng tạo nội dung,... Có hiểu biết cơ bản và yêu thích nền tảng TikTok; ưu tiên ứng viên có xây kênh TikTok cá nhân hoặc đã từng làm nội dung TikTok. Có khả năng sáng tạo ý tưởng nhanh, tư duy nội dung đa dạng, phong phú. Có kỹ năng viết nội dung tốt, ưu tiên ứng viên có kinh nghiệm viết bài chuẩn SEO. Chủ động, có trách nhiệm, có khả năng làm việc độc lập và làm việc nhóm tốt. Ưu tiên ứng viên năng động, thích tham gia các hoạt động tổ chức sự kiện và sản xuất nội dung thực tế.
Kỹ năng chuyên môn: [''Kỹ năng viết nội dung'', ''Viết bài chuẩn SEO'', ''Kỹ năng quay dựng video cơ bản'']
Kỹ năng mềm: [''Sáng tạo ý tưởng'', ''Tư duy nội dung đa dạng'', ''Chủ động'', ''Có trách nhiệm'', ''Làm việc độc lập'', ''Làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ dấu thực tập và tài liệu làm khóa luận'', ''Được đào tạo bài bản bởi đội ngũ sản xuất truyền thông chuyên nghiệp'', ''Cơ hội tham gia miễn phí rất nhiều khóa học về chuyển đổi số, AI, MKT, Kinh doanh'', ''Cơ hội trở thành nhân viên chính thức nếu đạt kết quả tốt'', ''Môi trường làm việc trẻ trung, năng động, sáng tạo'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (277, 2, 7, 'Thực Tập Sinh Kinh Doanh', 'Tư vấn, giới thiệu các sản phẩm của công ty đến khách hàng tiềm năng. Đăng tin, chăm sóc khách hàng cũ và mới, giữ mối quan hệ với khách hàng. Đàm phán, thương lượng, chốt hợp đồng (được hỗ trợ cùng đội ngũ Heco Land). Không áp KPI.', 'Không kinh nghiệm sẽ được đào tạo chuyên sâu (cầm tay chỉ việc). Siêng năng, chăm chỉ, không ngại khó khăn, đam mê kiếm tiền. Có trách nhiệm, cầu tiến trong công việc. Đào tạo 3 ngày tại văn phòng.
Kỹ năng mềm: [''Siêng năng'', ''Chăm chỉ'', ''Có trách nhiệm'', ''Cầu tiến trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 10:00), Tự do linh động tham gia làm việc 4 buổi/tuần, thời gian tối thiểu 2 tiếng/buổi.', '[''Hoa hồng theo sản phẩm (nhận ngay trong 24h)'', ''Được đào tạo và hướng dẫn chi tiết bởi các chuyên gia trong ngành'', ''Cơ hội thực hành và phát triển kỹ năng nghề nghiệp'', ''Hỗ trợ dấu mộc sau 45 ngày làm việc cho các thực tập sinh có thành tích tốt'', ''Hỗ trợ chi phí thực tập khi phát sinh giao dịch'', ''Có cơ hội trở thành nhân viên chính thức sau khi kết thúc thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (278, 3, 7, 'Thực Tập Sinh Kinh Doanh', 'Bạn đang là sinh viên năm cuối và mong muốn phát triển sự nghiệp? Đây là cơ hội dành cho Bạn! Tham gia đội ngũ 24H, Bạn sẽ nhận được khóa đào tạo chuyên sâu và có lộ trình phát triển rõ ràng! Lộ trình đào tạo: 1. Tháng đầu tiên: Đào tạo ứng dụng văn phòng (Word, Excel, Powerpoint, Viết email, báo cáo top đầu việc,…), Đào tạo kiến thức sản phẩm về ngành truyền thông quảng cáo, Được làm quen với hệ thống ERP và Luật Quảng cáo. 2. Tháng thứ 2: Đào tạo kỹ năng mềm, bán hàng (Tìm kiếm Khách hàng, liên hệ Khách hàng, đàm phán, chốt hợp đồng, chính sách sau bán, up sales,…), Thực hành gọi điện cho Khách hàng, gặp Khách hàng, gửi báo giá,…', 'Đối tượng: Sinh viên năm cuối các trường Đại học/Cao đẳng, yêu thích học hỏi và muốn phát triển kỹ năng bán hàng. Cam kết bảo mật thông tin và tham gia đầy đủ chương trình đào tạo. Cam kết không nghỉ việc ở tháng đầu tiên và hoàn thành tất cả các bài kiểm tra.
Kỹ năng chuyên môn: [''Word'', ''Excel'', ''Powerpoint'']
Kỹ năng mềm: [''Kỹ năng bán hàng'', ''Giao tiếp'', ''Đàm phán'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ 2 triệu đồng/tháng trong tháng đầu tiên'', ''Hỗ trợ cứng 3 triệu đồng/tháng từ tháng thứ 2'', ''Thưởng hiệu suất'', ''Cấp chứng nhận chương trình đào tạo kinh doanh quảng cáo'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (279, 7, 7, 'Thực Tập Sinh Content Marketing Tiktok', 'Lên ý tưởng và xây dựng nội dung video ngắn liên quan đến sản phẩm màn hình LED: giới thiệu sản phẩm, hậu trường lắp đặt, hướng dẫn sử dụng, case study công trình… Quay, dựng video đơn giản bằng điện thoại và phần mềm CapCut (hoặc các công cụ khác nếu có thể). Hỗ trợ viết caption, chèn hashtag, nhạc trending, tối ưu để video dễ viral. Phối hợp với bộ phận kỹ thuật/kinh doanh để hiểu sản phẩm và phản ánh đúng USP (lợi thế sản phẩm). Theo dõi hiệu quả video, hỗ trợ đề xuất cải tiến nội dung theo trend TikTok. Nghiên cứu đối thủ và xu hướng TikTok trong ngành thiết bị trình chiếu/màn hình.', 'Sinh viên các ngành: Marketing, Truyền thông, Thương mại điện tử, Công nghệ thông tin hoặc liên quan. Yêu thích sáng tạo nội dung, đặc biệt trên nền tảng TikTok. Có kỹ năng quay dựng cơ bản bằng điện thoại, biết dùng CapCut là lợi thế lớn. Hiểu biết cơ bản về TikTok algorithm, trend, âm nhạc viral. Có tư duy hình ảnh, thẩm mỹ tốt.
Kỹ năng chuyên môn: [''Kỹ năng quay dựng cơ bản bằng điện thoại'', ''Biết dùng CapCut'']
Kỹ năng mềm: [''Yêu thích sáng tạo nội dung'', ''Có tư duy hình ảnh'', ''Thẩm mỹ tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 14000000.00, '7.0 - 14.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Được hưởng đầy đủ các quyền lợi theo Luật lao động Việt Nam và nội quy, quy chế của Công ty.'', ''Môi trường làm việc trẻ trung, sáng tạo, chuyên nghiệp & thân thiện.'', ''Có lộ trình thăng tiến rõ ràng, môi trường năng động, chuyên nghiệp'', ''Chế độ nghỉ lễ, phép năm, du lịch, team building hàng năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (280, 8, 7, 'Designer Freelancer', 'Tham gia vào việc phát triển thiết kế, trực quan chính, bài đăng/video xã hội cho phương tiện truyền thông xã hội (Facebook & Instagram) và các kênh thuộc sở hữu khác (Trang web, APP & EDM). Tạo ý tưởng, đóng góp đầu vào cho các hướng hình ảnh & thiết kế cho tiếp thị. Tại chỗ ít nhất 3 ngày mỗi tuần.', 'At least 1 year of Graphic design. Highly preferred candidates with portfolios. Attention to details and willingness to cooperate in a long-run. Hospitality & lifestyle background is a plus. Excellent in Photoshop & Illustration. Able to DI/Edit photos.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustration'']
Kỹ năng mềm: [''Chú ý đến chi tiết'', ''Sẵn sàng hợp tác lâu dài'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '5.0 - 6.0 triệu', 'Onsite ít nhất 3 ngày mỗi tuần', '[''Môi trường làm việc năng động và chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (281, 9, 7, 'Thực Tập Sinh Marketing', 'Lên ý tưởng, nội dung hình ảnh, video. Phân tích, nắm bắt xu hướng thị trường. Hỗ trợ lên kế hoạch và tổ chức các sự kiện. Cắt, dựng, xử lí hình ảnh. Hoàn thành những dự án được giao.', 'Sinh viên năm 3 - 4 các trường Đại Học, ưu tiên các bạn làm full-time. Có laptop cá nhân. Có khả năng làm việc độc lập và làm việc nhóm. Tinh thần cầu tiến, chịu áp lực, ham học hỏi. Thái độ tích cực, linh hoạt trong công việc. Thành thạo các phần mềm thiết kế, edit như PTS, canva, capcut.
Kỹ năng chuyên môn: [''Photoshop'', ''Canva'', ''Capcut'']
Kỹ năng mềm: [''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Tinh thần cầu tiến'', ''Chịu áp lực'', ''Ham học hỏi'', ''Thái độ tích cực'', ''Linh hoạt trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Hỗ trợ các bạn TTS đầy đủ về các báo cáo thực tập: dấu mộc, số liệu'', ''Thưởng hoạt động theo memo hàng tháng'', ''Cơ chế thăng tiến rõ ràng'', ''Môi trường làm việc năng động, tự do, hiện đại và thỏa sức sáng tạo'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (282, 10, 7, 'Thực Tập Sinh Marketing', 'Thực tập sinh Marketing – Đa lĩnh vực Địa điểm: đường XP1, KĐT Viglacera Xuân Phương, Nam Từ Liêm, Hà Nội Thời gian: Linh hoạt, Full time 8h30-12h và 13h30 - 17h Mô tả công việc: Hỗ trợ xây dựng nội dung marketing cho các sản phẩm của công ty (bài viết, video ngắn, ý tưởng quảng bá...) Tham gia quản lý và phát triển các nền tảng truyền thông như Fanpage, TikTok, Zalo OA, Shopee, Website… Lên kế hoạch và thực hiện các chiến dịch truyền thông cho từng mảng sản phẩm/dịch vụ Phối hợp với team kinh doanh để tạo ra nội dung phù hợp với đối tượng khách hàng mục tiêu Nghiên cứu thị trường, theo dõi đối thủ và đề xuất cải tiến chiến lược truyền thông', 'Yêu cầu: Sinh viên các ngành Marketing, Truyền thông, Báo chí, Thiết kế hoặc đam mê lĩnh vực sáng tạo nội dung Có khả năng viết lách, tư duy thẩm mỹ và yêu thích mạng xã hội Nắm cơ bản về các công cụ: Digital, Canva, CapCut, Google Drive (ưu tiên biết chạy quảng cáo FB/TikTok) Chủ động, sáng tạo, ham học hỏi
Kỹ năng chuyên môn: [''Digital'', ''Canva'', ''CapCut'', ''Google Drive'']
Kỹ năng mềm: [''Chủ động'', ''Sáng tạo'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'nam từ liêm', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Full time 08h30-12h và 13h30-17h', '[''Được hướng dẫn từ A-Z quy trình xây dựng chiến dịch marketing thực tế'', ''Làm việc trong môi trường trẻ, năng động, mentor thân thiện'', ''Có cơ hội phát triển chuyên môn cả mảng thương mại điện tử & marketing giáo dục'', ''Có xác nhận thực tập và cơ hội trở thành nhân sự chính thức sau kỳ thực tập'', ''Mức hỗ trợ: Có hỗ trợ thực tập + thưởng theo hiệu quả công việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (283, 2, 7, 'Nhân Viên Marketing Part Time', '- Đăng bài, chào hàng, quảng bá sản phẩm trên các nền tảng thương mại điện tử Facebook, Alibaba, LinkedIn,... - Hỗ trợ tư vấn sản phẩm, làm báo giá cho khách hàng trong nước và quốc tế - Tìm kiếm data khách hàng có nhu cầu và gửi thông tin khách hàng cho phòng kinh doanh - Đăng tuyển những vị trí cần tuyển và gửi CV về cho phòng hành chính - Các công việc khác theo yêu cầu của quản lý', '- Trình độ học vấn: Sinh viên năm 2, 3 của các trường Đại học - Ưu tiên ứng viên học chuyên ngành kinh tế, xuất khẩu, logistics,… - Tiếng Anh cơ bản - Có kỹ năng giao tiếp, đàm phán và tinh thần làm việc nhóm tốt, nhanh nhẹn hoạt bát trong công việc - Có kiến thức cơ bản về bán hàng, xuất nhập khẩu - Có laptop cá nhân
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng đàm phán'', ''Kiến thức cơ bản về bán hàng'', ''Kiến thức về xuất nhập khẩu'']
Kỹ năng mềm: [''Tinh thần làm việc nhóm'', ''Nhanh nhẹn'', ''Hoạt bát'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '1.0 - 5.0 triệu', 'Từ Thứ 2 đến Sáng Thứ 7, Sáng từ 8h - 12h, Chiều từ 13h30 - 17h30', '[''Có hỗ trợ dấu mộc thực tập'', ''Lương cứng: 25.000đ/1 giờ + Thưởng doanh thu + Thưởng lễ'', ''Được học hỏi, đào tạo bài bản'', ''Xét duyệt theo năng lực làm việc từ 2-3 tháng đề xuất làm nhân viên chính thức fulltime'', ''Đăng ký ca linh hoạt theo lịch học trên trường, không giới hạn số buổi đi làm, tối thiểu 4 buổi/1 tuần'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (284, 3, 7, 'Nội dung tiếp thị thực tập', '- Tham gia xây dựng đóng góp ý tưởng về hình ảnh và nội dung cho các dự án của công ty. - Theo dõi tiến độ công việc, xử lý công việc theo yêu cầu cho các chiến dịch của khách hàng và của công ty. - Quay video/chụp ảnh cho các chiến dịch, sự kiện của khách hàng và của công ty. - Báo cáo tình hình thực hiện công việc được giao cho cấp trên. - Thực hiện các công việc khác theo yêu cầu của cấp trên.', '- Sinh viên năm 2-3-4, chuyên ngành Marketing, Truyền thông, Báo chí, Thương mại điện tử,... - Ưu tiên các ứng viên tại Tân Phú hoặc ở gần công ty. - Có khả năng tìm kiếm thông tin, sáng tạo nội dung. - Kỹ năng tin học văn phòng cơ bản, có laptop cá nhân. - Có kiến thức cơ bản về marketing, truyền thông. - Năng động, nhiệt huyết, ham học hỏi, có trách nhiệm với công việc. - Có kỹ năng làm việc nhóm, khả năng giao tiếp, ứng xử tốt. - Biết quản lý các nền tảng social, biết sử dụng phần mềm Capcut, Canva và các phần mềm chỉnh sửa video, hình ảnh khác là một lợi thế.
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng cơ bản'', ''Biết sử dụng phần mềm Capcut'', ''Canva'', ''Các phần mềm chỉnh sửa video, hình ảnh khác'']
Kỹ năng mềm: [''Năng động'', ''Nhiệt huyết'', ''Ham học hỏi'', ''Có trách nhiệm với công việc'', ''Kỹ năng làm việc nhóm'', ''Khả năng giao tiếp'', ''Ứng xử tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 17:30), 4-5 buổi/tuần', '[''Thưởng hiệu suất nhân viên'', ''Sinh nhật nhân viên'', ''BHYT, BHXH, bảo hiểm thất nghiệp theo quy định của Luật Lao động (khi là nhân viên chính thức)'', ''Miễn phí trà, coffee, bánh kẹo tại khu vực ăn uống của công ty'', ''Được đào tạo các kỹ năng thực chiến trong ngành Marketing'', ''Cơ hội cọ sát với các khách hàng danh tiếng'', ''Môi trường làm việc năng động, linh hoạt có nhiều cơ hội thăng tiến'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (285, 7, 7, 'Thực Tập Sinh SEO Marketing', 'Chăm sóc và lên nội dung các kênh Mạng xã hội: Fanpage, Website, Youtube, Tiktok thường xuyên để đảm bảo số lượng tiếp cận và tương tác luôn được duy trì ổn định và có các biện pháp, kế hoạch điều chỉnh kịp thời khi thấy lượng tương tác giảm. Biên tập và viết bài PR, có quy trình content cụ thể cho các kênh truyền thông của Công ty và mở rộng các kênh khác; Phối hợp cùng các bộ phận khác nhằm đảm bảo mục tiêu chung của Công ty đạt kết quả tối ưu; Kết hợp các kênh blogger, facebook marketing, Youtube Video marketing nhằm tăng Traffic cho website. Thiết kế hình ảnh, làm video cơ bản.', '- Đam mê viết lách - Có khả năng sáng tạo. - Có chuyên môn về truyền thông cơ bản. - Có khả năng làm việc độc lập và làm việc nhóm - Sinh viên đang theo học các ngành liên quan đến SEO, marketing,...
Kỹ năng chuyên môn: [''SEO'', ''Marketing'']
Kỹ năng mềm: [''Sáng tạo'', ''Làm việc độc lập'', ''Làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thời gian linh hoạt', '[''Lương học việc từ 3 triệu đến 4 triệu cho full time'', ''Hỗ trợ con dấu thực tập, thư giới thiệu'', ''Đào tạo chuyên sâu kiến thức chuyên môn về SEO'', ''Đào tạo chuyên sâu các kỹ năng quản lý, làm việc'', ''Đào tạo các công cụ làm việc của công ty'', ''Hưởng chính sách theo quy định công ty'', ''Du lịch cùng công ty 1 lần/năm'', ''Ăn trưa, Xăng xe'', ''Được cấp Điện thoại'', ''Team building'', ''Thưởng hiệu quả làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (286, 8, 7, 'Thực Tập Sinh Booking', 'Tìm kiếm & Liên hệ: Tìm kiếm các nano/micro KOC phù hợp với chiến dịch và liên hệ để giới thiệu, mời hợp tác. Sắp xếp và quản lý tiến độ lên bài và chất lượng nội dung của Nano/Micro KOC. Hỗ trợ dự án: Theo dõi, báo cáo và hỗ trợ KOC và team vận hành kho để đảm bảo hiệu quả booking. Cập nhật & Quản lý: Quản lý danh sách KOC, cập nhật thông tin và phản hồi từ đối tác.', 'Sinh viên các ngành Digital Marketing, Truyền thông hoặc các ngành liên quan. Kỹ năng giao tiếp, thuyết phục và quản lý thời gian tốt. Năng động, chủ động và có khả năng làm việc độc lập cũng như theo nhóm. Có laptop cá nhân để phục vụ cho công việc. Ưu tiên có kiến thức cơ bản về marketing trên mạng xã hội và có khả năng làm việc fulltime.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về marketing trên mạng xã hội'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'', ''Quản lý thời gian tốt'', ''Năng động'', ''Chủ động'', ''Có khả năng làm việc độc lập'', ''Có khả năng làm việc theo nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Hỗ trợ ký và đóng mộc thực tập'', ''Cơ hội học hỏi và trải nghiệm môi trường làm việc marketing thực tế, chuyên nghiệp'', ''Được đào tạo từ A-Z và hỗ trợ phát triển kỹ năng Marketing cơ bản'', ''Có thể chuyển sang làm việc chính thức sau kỳ thực tập nếu đạt yêu cầu'', ''Môi trường làm việc năng động, trẻ trung, chuyên nghiệp; phát triển kỹ năng, giao lưu, học hỏi, mở rộng kiến thức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (287, 9, 7, 'Editor Video', '1. Chuyên môn - Edit video ngắn theo kịch bản đã có sẵn - Edit video quảng cáo cho đa dạng ngành hàng, video doanh nghiệp - Làm việc cùng Team media, tiếp nhận ý tưởng, edit sản phẩm Media của công ty và của khách hàng - Đi quay thực tế và quay tại văn phòng 2. Các công việc liên quan khác - Nhận kế hoạch từ Quản lý bộ phận triển khai và theo dõi các hoạt động trong kế hoạch - Thực hiện các nhiệm vụ khác trong phạm vi trách nhiệm công việc phụ trách, được giao bởi Quản lý trực tiếp và Ban Lãnh đạo', '- Ứng viên có từ 1 năm kinh nghiệm edit video, đặc biệt là video ngắn cho social - Ứng viên có khả năng sử dụng máy quay - Kỹ năng làm việc nhóm tốt - Kỹ năng tổ chức và quản lý thời gian tốt - Sáng tạo, linh hoạt
Kỹ năng chuyên môn: [''Sử dụng phần mềm chỉnh sửa video (Premiere Pro, Final Cut Pro, Davinci Resolve, Adobe After Effects)'', ''Kỹ năng dựng phim, cắt ghép video'', ''Hiểu biết về quy trình sản xuất video'', ''Chỉnh sửa màu sắc và âm thanh'']
Kỹ năng mềm: [''Kỹ năng làm việc nhóm tốt'', ''Kỹ năng tổ chức và quản lý thời gian tốt'', ''Sáng tạo'', ''Linh hoạt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 18000000.00, '12.0 - 18.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00), Nghỉ trưa 2 tiếng', '[''Phụ cấp 1,2 triệu'', ''KPI'', ''Thưởng lễ, Tết, lương tháng 13 theo quy định'', ''Hưởng đầy đủ các chế độ BHXH, BHYT theo quy định của pháp luật'', ''Môi trường làm việc trẻ, năng động'', ''Tham gia các chương trình liên hoan, du lịch cùng Công ty'', ''Thưởng theo kết quả công việc và vinh danh, thăng tiến'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (288, 10, 7, 'Freelancer Media Bất Động Sản', 'FREELANCER TUYỂN DỤNG MEDIA – EDIT VIDEO BẰNG CAPCUT (LÀM TỪ XA) Vị trí: Freelancer Media – Dựng video ngắn Giới tính: Nữ, Khu vực: Toàn Quốc Hình thức: Làm việc từ xa (remote, freelance) • Dựng video ngắn (TikTok, Reels, Shorts) theo nội dung có sẵn • Sử dụng CapCut để thêm hiệu ứng, text, âm thanh hấp dẫn • Ưu tiên video dạng giới thiệu, review sản phẩm, bất động sản • Nhận video – làm linh hoạt – đảm bảo đúng deadline', '• Có kỹ năng edit video bằng CapCut (trên điện thoại hoặc PC) • Có mắt thẩm mỹ, tư duy nội dung tốt • Ưu tiên ứng viên: • Là nữ, có laptop hoặc smartphone, có trách nhiệm với công việc • Sinh sống ở các tỉnh (toàn quốc) • Từng làm video về bất động sản là lợi thế lớn • Cam kết làm đều, đúng deadline, nhận số lượng lớn • Thời gian làm việc linh hoạt, không gò bó, miễn đúng hạn
Kỹ năng chuyên môn: [''CapCut'']
Kỹ năng mềm: [''Có mắt thẩm mỹ'', ''Tư duy nội dung tốt'', ''Trách nhiệm với công việc'']', 'FREELANCE', 'REMOTE', 'hồ chí minh', 'Hồ Chí Minh', 'FIXED_PROJECT', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 00:00 đến 00:00)', '[''Làm việc 100% từ xa'', ''Có nội dung & hướng dẫn cụ thể'', ''Thu nhập ổn định, tăng theo năng lực'', ''Cơ hội cộng tác lâu dài nếu làm tốt'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (289, 2, 7, 'Thực Tập Sinh Đăng Tải Video - Biết Tiếng Trung', 'Hỗ trợ trưởng nhóm trong việc ghi chép bảng biểu, phân chia công việc cho các thành viên trong team hàng ngày. Theo dõi và tổng hợp tiến độ công việc của team, báo cáo định kỳ. Trao đổi với quản lý người Trung, báo cáo tiến độ công việc hàng ngày một cách rõ ràng và chính xác. Hỗ trợ team hoàn thành đầy đủ KPI theo ngày/tuần/tháng. Sắp xếp lịch đăng bài, hỗ trợ lên kế hoạch seeding theo từng chiến dịch. Giao tiếp, truyền đạt yêu cầu công việc giữa các thành viên bằng tiếng Trung (nếu cần). Thực hiện các công việc hành chính khác được giao liên quan đến team seeding.', 'Không yêu cầu kinh nghiệm. Biết tiếng Trung (nghe, nói, đọc, viết cơ bản trở lên). Có khả năng sử dụng Google Sheet/Excel để lập bảng biểu, theo dõi công việc. Giao tiếp tốt, có khả năng làm việc nhóm và chịu được áp lực tiến độ. Cẩn thận, có tinh thần trách nhiệm, chủ động trong công việc.
Kỹ năng chuyên môn: [''Google Sheet'', ''Excel'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Khả năng làm việc nhóm'', ''Chịu được áp lực tiến độ'', ''Cẩn thận'', ''Có tinh thần trách nhiệm'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '5.0 - 6.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00), Nghỉ trưa 1 tiếng', '[''Được đào tạo về quy trình làm việc'', ''Kỹ năng quản lý team seeding'', ''Hỗ trợ tiền gửi xe'', ''Môi trường năng động, trẻ trung'', ''Cơ hội trở thành nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (290, 3, 7, 'Idol Live TikTok (Fulltime/Parttime)', 'Live đơn nội dung giải trí: hát, trò chuyện, kể chuyện, PK... nền tảng TikTok Việt Nam (nội dung live bắt buộc phải hợp pháp, không được vi phạm các từ khóa cấm của TikTok). Xây dựng mối quan hệ tích cực với user Việt bằng cách giao lưu, trò chuyện với họ mỗi ngày. Áp dụng khả năng nói chuyện khéo léo, tư duy logic (EQ cao), kết hợp với sở trường riêng nếu có: hát, nhảy, kể chuyện, sáng tạo trend mới...) để mang đến những phiên live thú vị gây ấn tượng với user. Tăng độ nhận diện với user mới, tạo dựng thương hiệu nhằm tích lũy thêm nhiều user cứng. Và đồng hành cùng họ chinh phục những trận PK thú vị, máu lửa, hấp dẫn mỗi ngày tăng giá trị thu nhập bản thân.', 'Nữ từ 18-29 tuổi (không tuyển nam), Ngoại hình ưa nhìn, Không yêu cầu kinh nghiệm live, Biết hát hoặc nhảy là một lợi thế, Hoạt ngôn, thân thiện, thích giao lưu kết bạn, trò chuyện tâm sự với người hâm mộ.
Kỹ năng chuyên môn: [''Sử dụng thành thạo TikTok'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Hoạt ngôn'', ''Thân thiện'', ''Thích giao lưu kết bạn'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 26000000.00, '10.0 - 26.0 triệu', 'Fulltime ca làm 8 tiếng live 6 tiếng/ngày', '[''Thử việc 2 tháng không áp KPI'', ''Được hướng dẫn và đào tạo bài bản'', ''Làm việc trực tiếp tại văn phòng'', ''Hỗ trợ đầy đủ trang thiết bị live'', ''Mỗi tuần được off 1 ngày tự chọn'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (291, 7, 7, 'Thực Tập Sinh Marketing', '1. Quản trị dữ liệu khách hàng - Phản hồi và quản lý các bình luận, tin nhắn của khách hàng trên các kênh chính thống và mạng xã hội của công ty. - Đồng bộ dữ liệu lên hệ thống công ty phục vụ Team Sale bán hàng. 2. Sản xuất nội dung - Cùng team quản lý và phát triển nội dung trên các kênh Social Media: Facebook, Instagram, Tiktok - Biên tập và sản xuất các nội dung bài blog SEO trên website 3. Các công việc khác theo chỉ định của công ty.', '- Sinh viên năm cuối hoặc mới tốt nghiệp ngành Marketing, Quản Trị Kinh Doanh, Quản trị Du Lịch & Lữ Hành. - Không yêu cầu kinh nghiệm. - Có kiến thức cơ bản về Marketing và Social media. - Sử dụng các công cụ thiết kế như Canvas, Capcut là 1 lợi thế. - Tư duy logic, có gu thẩm mỹ, chủ động, nhiệt tình và có khả năng làm việc độc lập cũng như theo nhóm - Có hiểu biết về ngành Du lịch là một lợi thế. - Kỹ năng quan sát, lập kế hoạch, giám sát cẩn thận và chi tiết - Tôn trọng quy trình làm việc, nhanh chóng thích nghi với sự đổi mới và xu hướng trong ngành marketing - Có tinh thần trách nhiệm, cầu thị trong công việc.
Kỹ năng chuyên môn: [''Sử dụng các công cụ thiết kế như Canvas'', ''Capcut'']
Kỹ năng mềm: [''Tư duy logic'', ''Có gu thẩm mỹ'', ''Chủ động'', ''Nhiệt tình'', ''Có khả năng làm việc độc lập'', ''Làm việc theo nhóm'', ''Kỹ năng quan sát'', ''Lập kế hoạch'', ''Giám sát cẩn thận và chi tiết'', ''Tôn trọng quy trình làm việc'', ''Nhanh chóng thích nghi với sự đổi mới và xu hướng trong ngành marketing'', ''Có tinh thần trách nhiệm'', ''Cầu thị trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:30 đến 12:30)', '[''Được đào tạo về kỹ năng Marketing'', ''Cơ hội học hỏi và phát triển kỹ năng Marketing thực tế'', ''Được tham gia các dự án Marketing thực tế của Công ty'', ''Cơ hội được nhận vào làm chính thức sau khi kết thúc thời gian thực tập'', ''Hỗ trợ dấu mộc hoàn thành báo cáo'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (292, 8, 7, 'Thực tập sinh xã hội', 'I. INTERNAL > > Chuẩn bị livestream 1. Chuẩn bị sản phẩm theo danh mục sản phẩm được phê duyệt 2. Set up hiện trường cho buổi live 3. Set up các công cụ trước buổi live > > Trong livestream 1. Phối hợp với các bộ phận trong team (như Content, Digital...) để vận hành trong live 2. Hỗ trợ livestream, tương tác cùng host trong livestream. 3. Hỗ trợ làm model quay chụp sản phẩm 4. Thực hiện các phần hình ảnh, nội dung trên công cụ live 5. Tương tác với khách hàng và phối hợp với bộ phận Callcenter để xử lý các vấn đề của khách hàng trong live > > Sau livestream 1. Báo cáo số liệu, hiệu quả livestream theo ngày/tuần/tháng với line manager II. EXTERNAL 1. Liên hệ hợp tác, chuyển hàng hoá sản phẩm cho các bạn KOL/KOC theo danh mục được duyệt 2. Báo cáo số liệu, hiệu quả livestream của KOL/KOC với line manager 3. Làm hợp đồng thanh toán chi phí cho KOL/KOC Và một số công việc phát sinh do line manager giao cho', '- Sinh viên năm 3/năm 4 hoặc sắp/mới tốt nghiệp Đại học/Cao đẳng chuyên ngành Marketing; - Có am hiểu về thời trang là một lợi thế; - Chăm chỉ, nhanh nhẹn, nhiệt tình, không ngại khó và quan trọng nhất là có thái độ làm việc tích cực; - Có các kỹ năng văn phòng cơ bản
Kỹ năng chuyên môn: [''Kỹ năng văn phòng cơ bản'']
Kỹ năng mềm: [''Chăm chỉ'', ''Nhanh nhẹn'', ''Nhiệt tình'', ''Thái độ làm việc tích cực'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 11:00 đến 15:00)', '[''Trợ cấp thực tập'', ''Lịch làm việc linh động'', ''Môi trường làm việc trẻ trung, năng động'', ''Hướng dẫn từ Mentor/ Supervisor/ Manager'', ''Cơ hội trở thành nhân viên chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (293, 9, 7, 'Thực Tập Sinh Phát Hành Nội Dung', 'Hỗ trợ Vận hành/Quản lý các kênh social. Theo dõi, tối ưu nội dung để tăng độ tiếp cận và tương tác. Biên tập nội dung, video và phát hành nội dung trên các nền tảng YouTube, TikTok, Facebook,… của đối tác. Thực hiện các công việc được giao theo yêu cầu của Trưởng bộ phận.', 'Sinh viên năm cuối hoặc vừa tốt nghiệp ngành Truyền thông đa phương tiện, Dựng phim, Thiết kế đồ họa,… hoặc các ngành có liên quan. Ưu tiên có kinh nghiệm phát hành và quản lý trên các nền tảng social; Có kỹ năng edit video, biết sử dụng: Capcut, Pr,... Biết SEO trên nền tảng YouTube, Facebook là lợi thế. Chăm chỉ, có tinh thần cầu tiến, trách nhiệm và tự giác. Có thể thực tập 3 tháng.
Kỹ năng chuyên môn: [''Kỹ năng edit video'', ''Biết sử dụng Capcut, Pr'']
Kỹ năng mềm: [''Chăm chỉ'', ''Có tinh thần cầu tiến'', ''Trách nhiệm'', ''Tự giác'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 09:00 đến 13:00)', '[''Được đào tạo và hướng dẫn công việc'', ''Được làm việc trong môi trường trẻ trung năng động'', ''Được hỗ trợ mộc báo cáo thực tập'', ''Cơ hội trở thành nhân viên chính thức tại công ty'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (294, 10, 7, 'Nhân Viên Content Marketing Part-Time Mảng Căn Hộ', 'Viết bài chuẩn SEO để đăng lên website công ty (sẽ được hướng dẫn nếu chưa có kinh nghiệm). Quay chụp căn hộ, thiết kế bài đăng hình ảnh đẹp mắt để đăng trên các kênh social (Facebook, Instagram,...). Kiểm tra thông tin căn hộ và phối hợp cùng team sales để cập nhật dữ liệu, đảm bảo thông tin luôn chính xác và mới nhất cho khách thuê.', 'Sinh viên các trường đại học, cao đẳng (ưu tiên khối ngành marketing, truyền thông, ngoại ngữ... nhưng không bắt buộc). Giao tiếp tiếng Anh cơ bản đến khá. Yêu thích công việc sáng tạo nội dung, chủ động, năng động và có tinh thần học hỏi. Ưu tiên các bạn biết quay dựng video, cắt ghép cơ bản. Không yêu cầu kinh nghiệm – bạn chỉ cần sẵn sàng học hỏi, chúng tôi sẽ đào tạo.
Kỹ năng chuyên môn: [''Viết bài chuẩn SEO'', ''Quay dựng video'', ''Cắt ghép video'']
Kỹ năng mềm: [''Giao tiếp'', ''Sáng tạo'', ''Chủ động'', ''Năng động'', ''Tinh thần học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Thời gian làm việc linh hoạt'', ''Môi trường làm việc trẻ trung, thoải mái'', ''Cơ hội nâng cao tiếng Anh'', ''Được đào tạo thực tế về thị trường bất động sản cao cấp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (295, 2, 7, 'Thực Tập Sinh Kinh Doanh', 'Tìm kiếm, tiếp cận khách hàng tiềm năng có nhu cầu làm website hoặc phần mềm quản lý BĐS. Giới thiệu, tư vấn gói sản phẩm/dịch vụ phù hợp. Hỗ trợ phòng kinh doanh trong các hoạt động marketing online. Cập nhật báo cáo khách hàng, theo dõi tiến độ chăm sóc. Tham gia đào tạo về kỹ năng sale, công nghệ website & phần mềm.', 'Sinh viên năm 2–4 các ngành Kinh doanh hoặc Marketing. Yêu thích kinh doanh và muốn phát triển trong lĩnh vực công nghệ. Có kỹ năng giao tiếp, chủ động học hỏi và tinh thần làm việc nhóm. Ưu tiên có kinh nghiệm từng làm cộng tác viên sale, telesale, hoặc biết sử dụng CRM là điểm cộng.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Chủ động học hỏi'', ''Tinh thần làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được đào tạo từ A-Z về kỹ năng tư vấn, công nghệ website/phần mềm'', ''Hỗ trợ phụ cấp thực tập + % hoa hồng cao trên từng hợp đồng thành công'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Làm việc trong môi trường trẻ trung, năng động, nhiều cơ hội'', ''Được cấp chứng nhận thực tập & hỗ trợ báo cáo tốt nghiệp nếu cần'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (296, 3, 7, 'Marketing Intern', 'Hỗ trợ lên ý tưởng và triển khai nội dung cho Fanpage, Website, Email, Social Media. Hỗ trợ chạy các chiến dịch truyền thông, quảng cáo online (Facebook, Google, TikTok, ...). Phối hợp với team thiết kế, media và các bộ phận liên quan để xử lý công việc. Tham gia lên kế hoạch và tổ chức các chương trình, sự kiện (online/offline). Báo cáo kết quả công việc hàng tuần cho quản lý trực tiếp. Thực hiện các công việc khác theo sự phân công của quản lý.', 'Có laptop cá nhân. Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp các ngành Marketing, Truyền thông, không yêu cầu kinh nghiệm. Yêu thích và muốn phát triển sự nghiệp trong lĩnh vực Marketing. Có kỹ năng viết lách, giao tiếp tốt, tư duy logic. Chủ động, ham học hỏi, có tinh thần trách nhiệm.
Kỹ năng chuyên môn: [''Kỹ năng viết lách'', ''Giao tiếp tốt'', ''Tư duy logic'']
Kỹ năng mềm: [''Chủ động'', ''Ham học hỏi'', ''Có tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '2.0 - 2.5 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 12:00 và từ 13:30 đến 17:30)', '[''Có cơ hội học hỏi, rèn luyện kỹ năng từ các dự án thực tế'', ''Hỗ trợ dấu mộc xác nhận thực tập (nếu cần)'', ''Môi trường làm việc trẻ trung, sáng tạo, chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức'', ''Team building'', ''Thưởng hiệu quả làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (297, 7, 7, 'VJ/Người tạo nội dung Bán thời gian', 'Lên ý tưởng và viết kịch bản cho các video ngắn xoay quanh các chủ đề hot: cuộc sống văn phòng, Gen Z đi làm,... Tự quay và dựng video ngắn (TikTok, Reels...) Tham gia brainstorm cùng team để bắt trend nhanh, tạo nội dung “chất & chất lượng”.', 'Chăm chỉ, thật thà, ham học hỏi. Biết quay – edit cơ bản bằng các app như CapCut, Premiere, VN... Chủ động thời gian, linh hoạt trong công việc.
Kỹ năng chuyên môn: [''Quay video'', ''Edit video'', ''Sử dụng ứng dụng như CapCut, Premiere, VN'']
Kỹ năng mềm: [''Chăm chỉ'', ''Thật thà'', ''Ham học hỏi'', ''Khả năng kể chuyện'', ''Nắm bắt tâm lý và tình huống'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:45 đến 17:45)', '[''Hỗ trợ xây dựng kênh cá nhân từ A-Z'', ''Cơ hội nhận job booking, quay quảng cáo cùng các brand lớn'', ''Môi trường trẻ, vui, thoải mái thể hiện “chất riêng”'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (298, 8, 7, 'Nhân Viên Sale-Marketing Part-Time', 'Viết bài PR, mô tả sản phẩm, bài viết cho các nền tảng Facebook, Alibaba, LinkedIn,... Tư vấn và chăm sóc khách hàng trong và ngoài nước qua các nền tảng zalo, facebook, whatsapp,... Gửi thông tin khách hàng cho bộ phận kinh doanh. Đăng bài tuyển dụng cho công ty khi cần thiết. Hỗ trợ các công việc khác theo yêu cầu của cấp trên.', 'Sinh viên năm 3–4 hoặc mới tốt nghiệp chuyên ngành Kinh doanh quốc tế, Kinh tế quốc tế, Logistics và chuỗi cung ứng,… Yêu cầu Tiếng Anh tốt. Tinh thần học hỏi, chủ động, trách nhiệm cao trong công việc. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Tiếng Anh tốt'']
Kỹ năng mềm: [''Tinh thần học hỏi'', ''Chủ động'', ''Trách nhiệm cao trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Lương cứng: 25k/h'', ''Thưởng doanh thu'', ''Thưởng lễ'', ''Được học hỏi, đào tạo bài bản'', ''Đăng ký ca linh hoạt theo lịch học'', ''Xét duyệt tăng lương theo năng lực'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (299, 9, 7, 'TRợ trực tiếp bán thời gian', '- Hỗ trợ livestream bán các sản phẩm của công ty trên nền tảng Tik Tok Shop. - Xây dựng kịch bản livestream, sáng tạo các concept livestream mới lạ, độc đáo. - Báo cáo tình hình, tiến độ công việc trình cấp trên và đề xuất các điều chỉnh hàng tuần về nội dung livestream dựa trên các chỉ số hiệu quả. - Tham gia vào việc làm diễn viên trong một số video xây kênh hoặc thông báo sale. - Tham gia các buổi đào tạo, trao đổi để nâng cao chất lượng công việc.', '- Độ tuổi từ 19 - 24 - Có ngoại hình ưa nhìn - Khả năng giao tiếp tốt, nói rõ ràng, có nội lực, không nói giọng địa phương, không nói ngọng. - Khả năng thuyết phục khách mua hàng tốt, hiểu sâu về tâm lý khách hàng. - Linh hoạt trong các trường hợp bất ngờ: xử lý feedback tiêu cực, sự cố kỹ thuật, … - Quản lý công việc hiệu quả khi làm việc nhóm và làm việc cá nhân. - Chủ động, nhiệt tình, chăm chỉ, có trách nhiệm với công việc.
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Khả năng thuyết phục khách mua hàng'', ''Quản lý công việc hiệu quả khi làm việc nhóm và làm việc cá nhân'', ''Chủ động, nhiệt tình, chăm chỉ, có trách nhiệm với công việc'']', 'PART_TIME', 'ONSITE', 'bắc từ liêm', 'Hà Nội', 'MONTHLY', 6000000.00, '5.0 - 6.0 triệu', 'Ca 5h & 3h, Đăng ký tối thiểu 6 ca/tuần', '[''Thưởng hiệu quả làm việc'', ''Du lịch hàng năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (300, 10, 7, 'Máy chủ livestream', 'Livestream bán các sản phẩm của công ty trên nền tảng Tik Tok Shop/ Shopee. Xây dựng kịch bản livestream, sáng tạo các concept livestream mới lạ, độc đáo. Cộng tác sát sao với đội chạy quảng cáo để tối ưu hiệu quả livestream từ nội dung trên video quảng cáo tới nội dung trong livestream. Sẵn sàng tiếp nhận một số công việc quản lý các mẫu live parttime. Tham gia các buổi đào tạo, trao đổi để nâng cao chất lượng công việc.', 'Nam/Nữ, Độ tuổi từ 18-28. Đã có kinh nghiệm livestream từ 2 tháng trở lên. Ngoại hình ưa nhìn, gọn gàng. Khả năng giao tiếp tốt, nói rõ ràng, có nội lực, không nói giọng địa phương. Khả năng thuyết phục khách mua hàng tốt, hiểu sâu về tâm lý khách hàng. Linh hoạt trong các trường hợp bất ngờ: xử lý feedback tiêu cực, sự cố kỹ thuật, ... Sáng tạo, học hỏi nhanh từ thị trường, đối thủ. Quản lý công việc hiệu quả khi làm việc nhóm và làm việc cá nhân. Chủ động, nhiệt tình, chăm chỉ, có trách nhiệm với công việc. THÔNG TIN HỒ SƠ: Bản CV + 1-2 video Live.
Kỹ năng chuyên môn: [''Thành Thạo Phần Mềm Livestream (obs, Streamlabs, V.v.)'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Khả năng thuyết phục khách mua hàng'', ''Sáng tạo'', ''Quản lý công việc hiệu quả'', ''Chủ động'', ''Nhiệt tình'', ''Chăm chỉ'', ''Có trách nhiệm với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 12000000.00, '10.0 - 12.0 triệu', '18h - 21h & 21h - 24h', '[''Thưởng các ngày Lễ, Tết'', ''Được tổ chức sinh nhật'', ''Được đào tạo để trở thành Quản lý mẫu livestream'', ''Team building'', ''Signing bonus'', ''Thưởng hiệu quả làm việc'', ''Du lịch hàng năm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (301, 2, 7, 'Thực Tập Sinh Digital Marketing Có Hỗ Trợ Lương', 'Tham gia thực tập trong mảng Giải pháp kế toán TOPA & Dịch vụ Kế toán Thuế của công ty với công việc như sau: Tìm hiểu & trực tiếp Tham gia đầy đủ các hoạt động Marketing của Doanh nghiệp. Tìm hiểu và thực hiện các hoạt động đẩy mạnh Content Marketing & Brand Marketing bao gồm: Content Marketing, Quản lý các Kênh Marketing Online, Website, Blog, Fanpage. Thiết lập các công cụ Marketing Online. Thiết kế - Design các tài liệu Marketing.', 'Sinh viên năm cuối các trường Đại Học, Cao Đẳng chuyên ngành Marketing, Luật doanh nghiệp, Tài chính kế toán, Quản trị kinh doanh. Có khả năng đọc hiểu, tìm hiểu nhanh các văn bản luật, quy định về doanh nghiệp, thuế. Nhiệt tình, năng nổ, quyết tâm, tự tin. Có thái độ tích cực, làm việc trách nhiệm và không ngừng học hỏi. Tự tin, sáng tạo, chủ động trong công việc.
Kỹ năng chuyên môn: [''Photoshop'', ''MS Offices'', ''Canva'']
Kỹ năng mềm: [''Nhiệt tình'', ''Năng nổ'', ''Quyết tâm'', ''Tự tin'', ''Sáng tạo'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Có hỗ trợ dấu mộc'', ''Phụ cấp thực tập theo thời gian'', ''Thưởng KPI theo kết quả công việc'', ''Được đào tạo về kiến thức về Marketing'', ''Được đào tạo sử dụng các công cụ Marketing'', ''Môi trường làm việc trẻ trung'', ''Được lựa chọn làm việc từ xa (Không đến văn phòng) tối đa 06 ngày / tháng'', ''Team-building theo chế độ công ty'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (302, 3, 7, 'Nhân Viên Marketing', '- Nghiên cứu thị trường, cập nhật xu hướng nhằm cung cấp thông tin cải thiện/cải tiến dịch vụ. - Báo cáo, đánh giá kết quả của các chiến dịch quảng cáo và truyền thông. - Xây dựng mục tiêu, kế hoạch, lộ trình phát triển và nâng cao nhận diện thương hiệu. - Thu hút, giao tiếp, kết nối hiệu quả với khách hàng, và các đối tác.', '- Tốt nghiệp trình độ Đại học trở lên các khối ngành Kinh tế (hoặc có chứng chỉ marketing). - Cam kết gắn bó lâu dài. - Ưu tiên biết xây kênh tiktok và nội dung video review. - Tinh thần chủ động, trách nhiệm cao trong công việc, tư duy sáng tạo. - Có khả năng lập kế hoạch, xây dựng chiến lược, triển khai công việc. - Kỹ năng giao tiếp tốt, tiếng Anh cơ bản (Biết là tiếng Hàn là một lợi thế).
Kỹ năng chuyên môn: [''Xây dựng kế hoạch marketing'', ''Nghiên cứu thị trường'', ''Kỹ năng giao tiếp'']
Kỹ năng mềm: [''Tinh thần chủ động'', ''Trách nhiệm cao trong công việc'', ''Tư duy sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 12000000.00, '10.0 - 12.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được đóng BHXH và các chế độ theo quy định của Pháp luật'', ''Hưởng phúc lợi, thưởng theo quy định công ty'', ''Thưởng lương tháng thứ 13'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (303, 7, 7, 'Content Marketing', 'Lên kế hoạch và triển khai nội dung cho các kênh truyền thông của công ty (Facebook, Instagram, TikTok, Website, v.v.) Phối hợp với bộ phận sản xuất/ thiết kế để xây dựng nội dung hình ảnh, video truyền thông. Viết nội dung quảng cáo, kịch bản video, slogan,... Theo dõi hiệu quả của nội dung (tương tác, lượt tiếp cận, chuyển đổi...) và đề xuất hướng cải thiện. Nghiên cứu thị trường, đối thủ, xu hướng nội dung và hành vi người dùng để xây dựng nội dung phù hợp với thương hiệu. Tham gia xây dựng chiến dịch truyền thông, phát triển câu chuyện thương hiệu.', 'Tốt nghiệp Cao đẳng/Đại học chuyên ngành Marketing, Truyền thông, Báo chí, hoặc các ngành liên quan. Có ít nhất 6 tháng – 1 năm kinh nghiệm ở vị trí tương đương (chấp nhận sinh viên mới tốt nghiệp có portfolio tốt). Kỹ năng viết tốt, tư duy ngôn ngữ sáng tạo, bắt trend nhanh. Sử dụng thành thạo các nền tảng mạng xã hội như Facebook, Instagram, Tiktok… Hiểu biết cơ bản về SEO, Facebook Ads, TikTok, các kênh social phổ biến. Biết sử dụng các công cụ như: Canva, Capcut, Google Workspace,... Khả năng làm việc nhóm tốt, chủ động, tỉ mỉ, đúng deadline.
Kỹ năng chuyên môn: [''Sử dụng thành thạo các nền tảng mạng xã hội như Facebook, Instagram, Tiktok'', ''Hiểu biết cơ bản về SEO'', ''Facebook Ads'', ''Các kênh social phổ biến'', ''Biết sử dụng các công cụ như: Canva, Capcut, Google Workspace'']
Kỹ năng mềm: [''Kỹ năng viết tốt'', ''Tư duy ngôn ngữ sáng tạo'', ''Bắt trend nhanh'', ''Khả năng làm việc nhóm tốt'', ''Chủ động'', ''Tỉ mỉ'', ''Đúng deadline'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 12:00), 5 buổi/tuần', '[''Môi trường trẻ trung, năng động'', ''Cơ hội thăng tiến'', ''Học hỏi, phát triển kỹ năng marketing tổng thể'', ''Review tăng lương định kỳ'', ''Thưởng Tết'', ''Đóng BHXH theo quy định'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (304, 8, 7, 'TTS ThiếT Kế', 'Lên ý tưởng và thiết kế các sản phẩm in ấn: Poster, Banner, Catalogue,... Sáng tạo nội dung hình ảnh và thiết kế ấn phẩm quảng cáo trên kênh Social & Digital (Website, Facebook, Shopee, Lazada,...) như poster hình ảnh, banner; Nghiên cứu, đề xuất, đóng góp ý kiến, định hướng thiết kế cho ấn phẩm. Edit video cơ bản. Thực hiện các công việc khác theo yêu cầu của cán bộ quản lý.', 'Ưu tiên sinh viên năm 4 hoặc mới ra trường ưu tiên chuyên ngành Thiết kế, Mỹ thuật, Đồ họa. Nếu là sinh viên năm 2,3 thì cần đảm bảo được yêu cầu về mặt thời gian. Tư duy sáng tạo, gu thẩm mỹ tốt, theo kịp thời đại. Có kỹ năng sử dụng phần mềm thiết kế Illutrator, Photoshop. Có tinh thần trách nhiệm và trung thực. Nhanh nhẹn, giao tiếp tốt, có khả năng sắp xếp và điều phối nhiều luồng công việc. Biết sự dụng các phần mềm AI hỗ trợ công việc là một lợi thế.
Kỹ năng chuyên môn: [''Illutrator'', ''Photoshop'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Gu thẩm mỹ tốt'', ''Trách nhiệm'', ''Trung thực'', ''Nhanh nhẹn'', ''Giao tiếp tốt'', ''Khả năng sắp xếp và điều phối công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Hỗ trợ dấu mộc thực tập'', ''Chứng nhận sau khi kết thúc kỳ thực tập'', ''Môi trường trẻ trung, năng động'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (305, 9, 7, 'Thực Tập Sinh Thiết Kế Đồ Họa', '1. Thiết kế đồ họa: Hỗ trợ thiết kế các ấn phẩm truyền thông (banner, poster, social media post...) phục vụ chiến dịch marketing. Hỗ trợ thiết kế tài liệu in ấn, POSM, bảng hiệu, hình ảnh trưng bày tại cửa hàng. Tham gia phát triển hình ảnh thương hiệu cùng team thiết kế. 2. Edit video (cơ bản): Cắt ghép, chỉnh sửa video ngắn (Reels, TikTok, Stories...) phục vụ truyền thông và chiến dịch online. Hỗ trợ chỉnh sửa màu sắc, chèn text, nhạc và hiệu ứng đơn giản. 3. Cập nhật xu hướng: Tìm hiểu và đề xuất ý tưởng thiết kế theo các xu hướng hiện đại. Ưu tiên ứng dụng công nghệ AI trong công việc để nâng cao hiệu suất. 4. Hợp tác – đồng bộ thương hiệu: Phối hợp với bộ phận Marketing và các team khác để đảm bảo sản phẩm thiết kế đúng định hướng nhận diện thương hiệu. Tham gia brainstorm ý tưởng cho các chiến dịch truyền thông. 5. Các công việc khác theo phân công của quản lý.', 'Sinh viên năm 3, 4 hoặc đã tốt nghiệp Cao đẳng/Đại học chuyên ngành Thiết kế đồ họa, Truyền thông đa phương tiện hoặc các ngành liên quan. Biết sử dụng các phần mềm thiết kế như Photoshop, Illustrator. Có khả năng chụp ảnh, quay và chỉnh sửa video cơ bản là điểm cộng. Ưu tiên ứng viên có sản phẩm minh họa (Portfolio), đặc biệt nếu có sử dụng AI trong thiết kế. Thời gian thực tập tối thiểu: 6 tháng.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'']
Kỹ năng mềm: [''Tư duy sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '5.0 triệu', '9,5 tiếng/ ngày, lên văn phòng tối thiểu 3 ngày/ tuần', '[''Hỗ trợ mộc thực tập cho các bạn sinh viên'', ''Được cung cấp thiết bị/ phần mềm làm việc'', ''Được training về chuyên môn'', ''Môi trường làm việc năng động, đồng nghiệp trẻ trung và sẵn sàng hỗ trợ'', ''Có cơ hội được xem xét và đánh giá trở thành nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (306, 10, 7, 'Bác Sĩ Da Liễu', 'Tư vấn 1:1 qua video call / chat. Phân tích tình trạng da, lịch sử sử dụng sản phẩm của khách. Thiết kế routine chăm da, đề xuất sản phẩm phù hợp. Hỗ trợ chăm sóc khách hàng sau bán. Hỗ trợ đào tạo chuyên môn cho team: marketing, sales. Xuất hiện trên các phương tiện truyền thông như một KOL nội bộ.', 'Đã tốt nghiệp chính quy chuyên ngành da liễu / y dược / spa thẩm mỹ có chứng chỉ hợp pháp. Có đạo đức nghề nghiệp, cam kết chất lượng trong tư vấn. Hiểu biết sâu về mỹ phẩm, nắm rõ về các thành phần sản phẩm. Kỹ năng giao tiếp tốt, tự tin, yêu thích chia sẻ và đào tạo. Ưu tiên ứng viên từng làm chuyên viên spa, bác sĩ da liễu, hoặc beauty consultant.
Kỹ năng chuyên môn: [''Hiểu biết sâu về mỹ phẩm'', ''Nắm rõ về các thành phần sản phẩm'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Tự tin'', ''Yêu thích chia sẻ và đào tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 28000000.00, '15.0 - 28.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), làm hai thứ 7 mỗi tháng: 9h - 17h', '[''Lương cơ bản + Lương KPI + Thưởng % doanh thu + Phụ cấp'', ''Cơ hội sở hữu cổ phần'', ''Môi trường sáng tạo, hỗ trợ phát triển chuyên môn'', ''Xây dựng thương hiệu cá nhân trong ngành'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (307, 2, 7, 'Thực Tập Sinh Content SEO Marketing - Làm Online', 'Demo nội dung website. Quản lý và tối ưu hóa nội dung trên các nền tảng kỹ thuật số như website, blog, mạng xã hội. Viết bài blog, bài viết website, bài đăng mạng xã hội. Nghiên cứu từ khóa, phân tích đối thủ cạnh tranh và xu hướng thị trường để tạo ra nội dung chất lượng cao. Theo dõi và phân tích hiệu quả của các chiến dịch nội dung, báo cáo kết quả và đề xuất cải tiến. Tối ưu hóa nội dung SEO (Search Engine Optimization) để cải thiện thứ hạng tìm kiếm trên Google. Cập nhật kiến thức về marketing content và các xu hướng mới nhất.', 'Không yêu cầu kinh nghiệm, được đào tạo. Hiểu về quản trị website Wordpress. Có niềm đam mê với Marketing và viết lách. Khả năng phân tích dữ liệu và báo cáo hiệu quả công việc. Có khả năng làm việc độc lập và làm việc nhóm. Trung thực, chịu khó, có tinh thần trách nhiệm cao.
Kỹ năng chuyên môn: [''Quản trị website Wordpress'']
Kỹ năng mềm: [''Khả năng phân tích dữ liệu'', ''Làm việc độc lập'', ''Làm việc nhóm'', ''Trung thực'', ''Chịu khó'', ''Có tinh thần trách nhiệm cao'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Làm việc online tại nhà', '[''Được đào tạo bài bản về SEO, Website, Content và các công cụ Marketing'', ''Hỗ trợ con dấu thực tập báo cáo'', ''Phụ cấp thưởng: 1tr-2tr/tháng'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (308, 3, 7, 'Thực Tập Sinh BD KOL - Hợp Tác Và Phát Triển KOL', 'Tìm kiếm và sàng lọc các KOL/KOC tiềm năng thông qua nền tảng như TikTok, Shopee. Phụ trách liên hệ và trao đổi hợp tác với KOL/KOC: gửi mẫu thử, trao đổi nội dung đăng video, tổng hợp dữ liệu cơ bản, thu thập phản hồi từ KOL/KOC. Thúc đẩy quá trình hợp tác: theo dõi việc gửi mẫu, cập nhật tiến độ đăng video, lưu trữ dữ liệu, giám sát tình hình đăng tải nội dung của KOL/KOC. Hỗ trợ xây dựng và duy trì database KOL/KOC (phân loại, gắn thẻ, trạng thái hợp tác, v.v.). Tổng hợp dữ liệu hiệu quả bán hàng của KOL/KOC (tỷ lệ chuyển đổi sản phẩm, lượt xem video, v.v.)', 'Thường xuyên, yêu thích hoạt động trên các nền tảng Tiktok, Facebook; nhạy bén với các trend mạng xã hội. Hiểu rõ quy trình quay dựng video, có kinh nghiệm quay vlog đời sống. Yêu thích, am hiểu làm đẹp, các sản phẩm chăm sóc da, tóc là lợi thế. Có tính chấp hành, tinh thần làm việc nhóm, giao tiếp hiệu quả. Tự tin, thích xuất hiện trước ống kính. Khả năng học hỏi, thích nghi nhanh, linh hoạt trong công việc.
Kỹ năng mềm: [''Giao tiếp hiệu quả'', ''Tinh thần làm việc nhóm'', ''Tự tin'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.5 - 5.0 triệu', '9h - 18h, thứ 2 đến thứ 6', '[''Môi trường trẻ, năng động, cơ hội phát triển lâu dài'', ''Hỗ trợ phụ cấp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (309, 7, 7, 'Thực Tập Sinh Content & Video Editor', 'Tham gia xây dựng nội dung video ngắn: viết kịch bản, hỗ trợ quay, dựng video cơ bản. Biên tập video theo yêu cầu, đảm bảo nội dung hấp dẫn, đúng định hướng thương hiệu. Hỗ trợ quản lý, lên lịch đăng bài và theo dõi hiệu quả các nội dung trên nền tảng số. Cập nhật các xu hướng sáng tạo nội dung mới (trending TikTok, Reels, Shorts,...). Thực hiện các công việc khác theo phân công của cấp trên.', 'Ưu tiên biết tiếng Trung. Dựa theo đặc điểm sản phẩm, trend beauty để thiết kế nội dung video ngắn phù hợp với nên tảng tiktok. Quản lý kênh tiktok, quản lý source. Tự quay và dựng video ngắn bao gồm hiệu ứng, ánh sáng, bố cục,... Sử dụng Capcut và các công cụ khác để xử lý hậu kỳ, tối ưu về tốc độ, phụ đề, nhạc nền video. Có thể hợp tác xuất hiện trước ống kính.
Kỹ năng chuyên môn: [''Capcut'', ''Công cụ dựng video'']
Kỹ năng mềm: [''Sáng tạo'', ''Quản lý thời gian'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.5 - 5.0 triệu', '9h - 18h, thứ 2 đến thứ 6', '[''Môi trường trẻ, năng động, cơ hội phát triển lâu dài'', ''Hỗ trợ phụ cấp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (310, 8, 7, 'Thực Tập Sinh Thiết Kế Đồ Họa', 'Thiết kế các ấn phẩm marketing (poster, banner, brochure,...) phục vụ cho các chiến dịch quảng cáo của công ty. Thiết kế giao diện website, landing page, các ấn phẩm truyền thông số (social media post, email marketing,...). Phối hợp với team marketing để hiểu rõ yêu cầu và mục tiêu của từng chiến dịch, từ đó tạo ra các thiết kế phù hợp. Đề xuất ý tưởng thiết kế sáng tạo, độc đáo và đáp ứng xu hướng thị trường. Chỉnh sửa và hoàn thiện các thiết kế dựa trên phản hồi từ khách hàng và team. Quản lý và lưu trữ file thiết kế một cách khoa học và hiệu quả. Tham gia các buổi họp nhóm, brainstorming để đóng góp ý kiến và hoàn thiện sản phẩm.', 'Không yêu cầu kinh nghiệm, được đào tạo bài bản. Có khả năng sử dụng thành thạo Photoshop, Illustrator. Hiểu biết về nguyên tắc thiết kế đồ họa (màu sắc, bố cục, typography). Khả năng sáng tạo, tư duy hình ảnh tốt. Khả năng làm việc nhóm, giao tiếp tốt. Có tinh thần trách nhiệm, chủ động trong công việc. Khả năng làm việc độc lập và chịu được áp lực công việc. Am hiểu về xu hướng thiết kế hiện đại là một lợi thế. Có portfolio (nếu có) để thể hiện khả năng thiết kế.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'']
Kỹ năng mềm: [''Khả năng sáng tạo'', ''Tư duy hình ảnh tốt'', ''Khả năng làm việc nhóm'', ''Giao tiếp tốt'', ''Tinh thần trách nhiệm'', ''Chủ động trong công việc'', ''Khả năng làm việc độc lập'', ''Chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 17:00)', '[''Được tham gia các dự án thực tế tại công ty'', ''Được hướng dẫn, thảo luận để có được kinh nghiệm trong triển khai thiết kế thương hiệu'', ''Công ty đóng mộc xác thực trong quá trình thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (311, 9, 7, 'Thực Tập Sinh Marketing Và Quay Dựng Video Tiktok', 'Lên idea, plan và phụ trách content cho các kênh social như Facebook, TikTok; content website, SEO,... Phụ trách quay phim và biên tập nội dung video, phục vụ cho hoạt động truyền thông, giới thiệu sản phẩm trên channel online: Youtube, Facebook, tiktok... Xây dựng được nội dung, số lượng cũng như đảm bảo chất lượng của video/ hình ảnh. Thực hiện các công việc khác theo yêu cầu của công ty. Hỗ trợ lên kế hoạch nhận diện thương hiệu và quảng bá sản phẩm. Báo cáo kết quả công việc cho Quản lý trực tiếp.', 'Sinh viên năm 2 - 4 các trường đại học các chuyên ngành liên quan đến Kinh tế, Kinh doanh, Truyền thông, Marketing,... Khả năng sử dụng ngôn từ tốt, ưu tiên có kiến thức cơ bản về Marketing, biết chụp hình , quay phim và có khả năng dựng video ngắn trên tiktok. Có tinh thần trách nhiệm cao, chủ động học hỏi, tư duy sáng tạo. Có thể làm việc tối thiểu 5 ngày /tuần tại văn phòng từ T2-CN.
Kỹ năng chuyên môn: [''Biết chụp hình'', ''Quay phim'', ''Dựng video ngắn trên TikTok'']
Kỹ năng mềm: [''Khả năng sử dụng ngôn từ tốt'', ''Tinh thần trách nhiệm cao'', ''Chủ động học hỏi'', ''Tư duy sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Tối thiểu 5 ngày /tuần tại văn phòng từ T2-CN', '[''Được hưởng trợ cấp thực tập'', ''Được đào tạo, trang bị các kiến thức thực tế về kỹ năng chuyên môn, kỹ năng mềm phục vụ công việc'', ''Môi trường làm việc năng động, thân thiện'', ''Được xác nhận và đóng dấu mộc thực tập và trở thành nhân viên chính thức khi tốt nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (312, 10, 7, 'Nhân Viên Quay Dựng (Part-Time)', 'Quay và dựng video ngắn trên nền tảng Tiktok theo chiến lược công ty. Chủ yếu là quay dựng sản phẩm của công ty (áo, cốc, chăn, đồ decor,...). Gen Video theo Prompt có sẵn bằng AI (công ty cấp tool). Phối hợp với các phòng ban, dựng các video theo yêu cầu của từng dự án (Quay, chụp sản phẩm, cắt nối hình ảnh theo kịch bản, làm hiệu ứng hình ảnh, âm thanh, chữ, nhạc nền, phù hợp với định hướng của sản phẩm,…). Set up cảnh quay phù hợp với từng sản phẩm. Chịu trách nhiệm chỉnh sửa, xử lý, biên tập và dựng video theo chiến lược marketing. Làm affiliate tiktokshop để kiếm thêm thu nhập.', 'Quay tối thiểu 5 - 6 clip/ca 2h, mỗi clip dài khoảng 11s - 15s (tùy theo yêu cầu). Có kinh nghiệm quay chụp đồ vật, sử dụng thành thạo phần mềm Capcut và các phần mềm chỉnh sửa video khác (nếu có). Có thẩm mỹ, sáng tạo, có kinh nghiệm làm viral video trên các nền tảng TikTok, Facebook, YouTube,… Yêu thích và muốn tìm hiểu về văn hóa phương Tây, khả năng học hỏi nhanh. Có chuyên môn quay dựng, sáng tạo content là 1 lợi thế. Sử dụng thành thạo các thiết bị quay, chụp (chủ yếu quay bằng điện thoại).
Kỹ năng chuyên môn: [''Phần mềm Capcut'', ''Phần mềm chỉnh sửa video'']
Kỹ năng mềm: [''Sáng tạo'', ''Thẩm mỹ'', ''Khả năng làm việc độc lập và theo nhóm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thời gian làm việc linh hoạt (tối thiểu 5 buổi/tuần)', '[''Môi trường làm việc văn minh, công bằng'', ''Các hoạt động của Công ty: Sinh nhật, vui chơi giải trí'', ''Văn phòng đẹp, tiện ích'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (313, 2, 7, 'Trade Marketing Intern', 'Hỗ trợ phân tích dữ liệu thị trường và nền tảng số (Facebook, Zalo, Website, Email Marketing). Phối hợp thực hiện các chiến dịch tiếp cận học viên thông qua sự kiện, hội thảo du học nghề, workshop định hướng nghề nghiệp. Thu thập, nhập liệu và quản lý thông tin khách hàng tiềm năng trên hệ thống CRM của công ty. Phối hợp tổ chức các chương trình dành cho học viên (giao lưu văn hóa Đức, hỗ trợ định hướng hồ sơ xin visa, workshop kỹ năng mềm). Phối hợp với bộ phận thiết kế để phát triển các ấn phẩm truyền thông (brochure, banner, poster, infographic).', 'Ưu tiên ứng viên nam. Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp chuyên ngành Marketing, Quản trị kinh doanh hoặc các ngành liên quan. Có khả năng viết lách, tư duy logic, yêu thích lĩnh vực truyền thông, marketing. Kỹ năng giao tiếp tốt, cẩn thận, chủ động trong công việc.
Kỹ năng chuyên môn: [''Phân tích dữ liệu thị trường'', ''Sử dụng nền tảng số (Facebook, Zalo, Website, Email Marketing)'', ''Quản lý thông tin khách hàng trên hệ thống CRM'']
Kỹ năng mềm: [''Kỹ năng viết lách'', ''Tư duy logic'', ''Kỹ năng giao tiếp'', ''Cẩn thận'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', '8h30 - 17h30 từ T2-T6, 8h30 - 12h T7', '[''Hỗ trợ thực tập + phụ cấp ăn trưa (Tối đa 2tr/tháng)'', ''Tham gia các chương trình hoạt động văn hóa đa dạng'', ''Môi trường năng động, trẻ trung, hội nhập quốc tế'', ''Được cung cấp dấu mộc thực tập (nếu cần)'', ''Được đào tạo bài bản'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (314, 3, 7, 'Thực Tập Sinh Content Marketing', 'Viết bài PR, nội dung cho nền tảng mạng xã hội. Hỗ trợ tối ưu trải nghiệm người dùng. Phối hợp cùng các bộ phận thiết kế để triển khai các chiến dịch truyền thông. Thực hiện các công việc khác theo sự phân công của người phụ trách.', 'Có khả năng viết tốt, tư duy logic, ngôn ngữ sáng tạo. Yêu thích sáng tạo nội dung, viết bài, có trách nhiệm với deadline. Có kiến thức về Content và có khả năng viết nội dung chuẩn SEO. Có kiến thức hoặc định hướng làm việc trong ngành Digital Marketing là một lợi thế. Biết sử dụng công cụ văn phòng (Word, Excel, Google Drive). Ưu tiên ứng viên đã từng làm content hoặc có portfolio bài viết.
Kỹ năng chuyên môn: [''Viết nội dung chuẩn SEO'', ''Sử dụng công cụ văn phòng (Word, Excel, Google Drive)'']
Kỹ năng mềm: [''Khả năng viết tốt'', ''Tư duy logic'', ''Ngôn ngữ sáng tạo'', ''Trách nhiệm với deadline'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Trợ cấp: 2.000.000-3.000.000/tháng + thưởng hiệu suất'', ''Được đào tạo, hướng dẫn chuyên môn'', ''Cơ hội học hỏi thực tế trong môi trường chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức sau thời gian thử việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (315, 7, 7, 'Tài khoản chính thực tập', '- Chịu trách nhiệm xây dựng và củng cố mối quan hệ với khách hàng, cũng như hiểu rõ các yêu cầu và mục tiêu của họ để đưa ra các khuyến nghị có giá trị; - Đóng vai trò là đầu mối liên lạc chính giữa khách hàng và nhóm nội bộ, phản hồi nhanh chóng các vấn đề nảy sinh trong suốt các dự án và cung cấp tư vấn khách hàng phù hợp; - Quản lý toàn bộ chiến dịch và cộng tác chặt chẽ với các nhóm khác để đảm bảo rằng dự án đạt được KPI đúng tiến độ, trong ngân sách và chất lượng tốt; - Hỗ trợ làm các thủ tục giấy tờ, sau hợp đồng, chấm dứt hợp đồng và quy trình thanh toán; - Lấy thông tin tóm tắt về chiến dịch từ Khách hàng, phát triển giao tiếp hiệu quả đến cuộc phỏng vấn cũng như nhận được thông tin rõ ràng và kỳ vọng của chiến dịch; - Phối hợp với nhóm Nội bộ để phát triển định hướng chiến lược tổng thể, xây dựng và trình bày Kế hoạch Truyền thông & Đề xuất Truyền thông kỹ lưỡng; - Phụ trách nghiên cứu, thu thập dữ liệu và phân tích, lấy dữ liệu phù hợp và đào sâu thông tin chi tiết về người tiêu dùng kỹ thuật số; - Tham gia nghiên cứu và phát triển các giải pháp và dịch vụ tốt hơn cho công ty.', '- Tốt nghiệp cao đẳng, đại học trở lên các chuyên ngành về quản trị kinh doanh, Kinh tế, Tài chính, Quản lý / chuỗi cung ứng. - Có 1 năm kinh nghiệm trong lĩnh vực marketing (E-commerce, Digital, TikTok, Agency). - Làm việc độc lập và chủ động đảm nhận những trách nhiệm mới khi cần thiết nhất. - Có hiểu biết tốt về quy trình và tối ưu hóa quy trình làm việc. - Giỏi giao tiếp, đàm phán và giải quyết vấn đề. - Thành thạo Microsoft Excel và Microsoft PowerPoint, kỹ năng tiếng Anh là một lợi thế tốt.
Kỹ năng chuyên môn: [''Microsoft Excel'', ''Microsoft PowerPoint'']
Kỹ năng mềm: [''Giao tiếp'', ''Đàm phán'', ''Giải quyết vấn đề'', ''Làm việc độc lập'', ''Chủ động'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '4.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 09:00 đến 15:00)', '[''Có hỗ trợ lương/thưởng theo chính sách thực tập'', ''Được đào tạo bài bản về quy trình làm việc với Creator từ A–Z'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Làm việc trong môi trường năng động, trẻ trung'', ''Học hỏi từ các team chuyên môn (Livestream, Creative, Performance)'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (316, 8, 7, 'Trợ Lý ONLINE Vận Hành Sàn TMĐT-Ko Cần Kinh Nghiệm', 'Shop mình đang cần tìm 1 bạn trợ lý online hỗ trợ vận hành gian hàng trên sàn thương mại điện tử. Công việc không cần sáng tạo quá nhiều, chỉ cần bạn cẩn thận và làm đúng hướng dẫn. Công việc bao gồm: Thiết kế banner trang trí shop, banner khuyến mãi bằng Canva hoặc Photoshop cơ bản; Thiết lập combo mua hàng, voucher, chương trình khuyến mãi, Flash Sale...; Thực hiện đúng các đầu việc theo kế hoạch tháng được giao sẵn.', 'Yêu cầu: Biết sử dụng Canva / phần mềm thiết kế đơn giản; Ưu tiên đã từng làm việc với Shopee / TikTok Shop (không bắt buộc); Làm việc cẩn thận, đúng deadline, có trách nhiệm; Có thời gian phản hồi và xử lý công việc hàng ngày; Sinh viên năm 3–4 hoặc freelancer đều phù hợp.
Kỹ năng chuyên môn: [''Canva'', ''Photoshop cơ bản'']
Kỹ năng mềm: [''Cẩn thận'', ''Đúng deadline'', ''Có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '5.0 triệu', 'Part-time online tại nhà', '[''Thưởng theo KPI nếu làm tốt'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (317, 9, 7, 'Thực Tập Sinh Thiết Kế Đồ Hoạ & Video Editor', 'Thiết kế các ấn phẩm truyền thông như: banner, poster, brochure, infographic, hình ảnh đăng mạng xã hội, hình ảnh website... Lên ý tưởng và thực hiện chỉnh sửa video: TVC, clip quảng cáo, video sản phẩm, motion graphic, video TikTok, Reels, Shorts,... Hỗ trợ các hoạt động truyền thông – marketing khác (nếu có). Phối hợp với team Marketing hoặc Content để đảm bảo sản phẩm thiết kế phù hợp định hướng thương hiệu. Cập nhật xu hướng thiết kế mới, đề xuất ý tưởng sáng tạo.', 'Là sinh viên năm 3, 4 hoặc mới tốt nghiệp chuyên ngành thiết kế đồ họa, mỹ thuật, truyền thông đa phương tiện hoặc các ngành liên quan. Biết sử dụng cơ bản các phần mềm thiết kế và chỉnh sửa video như: Capcut, Photoshop, Illustrator, Premiere Pro, (hoặc các công cụ tương đương). Có khả năng tư duy thẩm mỹ tốt, sáng tạo, linh hoạt. Có laptop cá nhân để làm việc (ưu tiên). Ưu tiên ứng viên có sản phẩm cá nhân hoặc từng thực hiện dự án sáng tạo (có thể đính kèm portfolio).
Kỹ năng chuyên môn: [''Capcut'', ''Photoshop'', ''Illustrator'', ''Premiere Pro'']
Kỹ năng mềm: [''Tư duy thẩm mỹ tốt'', ''Sáng tạo'', ''Linh hoạt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Được đào tạo và hướng dẫn trực tiếp từ đội ngũ thiết kế hoặc marketing'', ''Cơ hội thực hành và xây dựng portfolio chuyên nghiệp với các dự án thực tế'', ''Môi trường làm việc trẻ trung, năng động'', ''Hỗ trợ dấu mộc thực tập và xác nhận hoàn thành thực tập'', ''Cơ hội trở thành nhân viên chính thức nếu thể hiện tốt'', ''Hỗ trợ chi phí thực tập + thưởng theo hiệu suất'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (318, 10, 7, 'Content Marketing (Học Việc)', 'Học việc, tiến đến phụ trách mảng content daily (biên tập nội dung) theo kế hoạch. Làm việc với chi nhánh hỗ trợ mkt online: Livestream lấy dữ liệu hình ảnh theo quy chuẩn. Thực hiện các công việc theo cấp trên yêu cầu.', 'Có đam mê, năng khiếu về viết lách, có định hướng phát triển trong lĩnh vực Content Marketing. Trách nhiệm, ham học hỏi, tinh thần cầu tiến. Tinh thần hợp tác nhóm tốt.
Kỹ năng chuyên môn: [''Biên tập'', ''Sáng tạo nội dung'', ''Viết Lách'', ''Sử Dụng Mạng Xã Hội'']
Kỹ năng mềm: [''Trách nhiệm'', ''Ham học hỏi'', ''Tinh thần cầu tiến'', ''Tinh thần hợp tác nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Trợ cấp học việc tới 5 triệu/ tháng'', ''Được làm việc tại môi trường chuyên nghiệp, lĩnh vực nha khoa y tế'', ''Được đào tạo chuyên môn về MKT: Phân tích chân dung khách hàng, kế hoạch & triển khai content, bước đầu tiếp cận tới biên tập nội dung'', ''Ăn trưa'', ''Thưởng hiệu quả làm việc'', ''Team building'', ''Du lịch hàng năm'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (319, 2, 7, 'Nhân Viên Thiết Kế Part-Time', 'Thiết kế các tài liệu chuyên môn (Sách, giáo trình, Slide giảng dạy,...). Thiết kế các ấn phẩm truyền thông trên kênh digital marketing (Facebook, Instagram,...) như bài đăng Social, Email template, v.v… Đảm bảo hệ thống ấn phẩm theo đúng bộ nhận diện thương hiệu của công ty.', 'Ưu tiên sinh viên năm 2 năm 3 các trường Đại học từ độ tuổi (2004-2006). Sử dụng thành thạo các phần mềm thiết kế như Adobe Illustrator, Figma, Adobe Photoshop, Adobe Indesign,... Có tư duy thẩm mỹ nhạy bén về mặt thiết kế, hình ảnh, bố cục, màu sắc; Ưu tiên các bạn đã có kinh nghiệm làm việc tại vị trí thiết kế, marketing.
Kỹ năng chuyên môn: [''Adobe Illustrator'', ''Figma'', ''Adobe Photoshop'', ''Adobe Indesign'']
Kỹ năng mềm: [''Tư duy thẩm mỹ'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc theo nhóm'', ''Quản lý thời gian hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Học IELTS miễn phí tại IZONE'', ''Thưởng theo hiệu quả làm việc'', ''Xét tăng lương theo hiệu quả công việc'', ''Đào tạo hàng tuần các kỹ năng'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (320, 3, 7, 'Thực Tập Sinh Marketing', 'Hỗ trợ đội ngũ Marketing trong việc lên ý tưởng, sáng tạo và phát triển nội dung (bài viết, hình ảnh, video) cho website, mạng xã hội và các chiến dịch truyền thông. Nghiên cứu thị trường, phân tích đối thủ, tìm kiếm thông tin, chủ đề phù hợp để tạo nội dung thu hút. Triển khai và tối ưu các chiến dịch Digital Marketing trên các nền tảng như Facebook Ads, SEO, Social Media,... đảm bảo hiệu quả và tối ưu chi phí. Quản lý, đo lường, đánh giá hiệu quả các hoạt động marketing, lập báo cáo và đề xuất cải thiện. Hỗ trợ các hoạt động truyền thông, sự kiện, branding, đóng góp ý tưởng và tham gia brainstorming. Học hỏi, đào tạo và phát triển kỹ năng về xây dựng chiến lược marketing, content, quảng cáo. Hỗ trợ các công việc khác theo yêu cầu của quản lý.', 'Có laptop. Không yêu cầu kinh nghiệm (ưu tiên học các ngành có liên quan đến MKT). Chủ động trao đổi với leader, đồng nghiệp. Tinh thần học hỏi và cải tiến không ngừng. Quyết liệt và cam kết với mục tiêu.
Kỹ năng chuyên môn: [''Content Marketing'', ''SEO'', ''Digital Marketing'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Chủ động'', ''Tinh thần học hỏi'', ''Quyết liệt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Môi trường năng động'', ''Đào tạo về Content Marketing, SEO, Marketing Online'', ''Đào tạo kỹ năng mềm'', ''Cơ hội trở thành nhân viên chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (321, 7, 7, 'SEO Website', 'Phân tích và tối ưu on-page (title, meta, internal link, URL). Kiểm tra technical SEO: tốc độ tải trang, mobile-friendly, index. Sử dụng Google Search Console và các công cụ crawl để phát hiện lỗi SEO. Làm việc với đội ngũ lập trình để cải thiện cấu trúc website.', 'Có nền tảng vững về SEO kỹ thuật, biết sử dụng Screaming Frog, Google Tag Manager. Biết HTML/CSS cơ bản. Am hiểu các yếu tố ảnh hưởng đến crawl budget và indexability. Ưu tiên ứng viên từng làm SEO cho trang thương mại điện tử.
Kỹ năng chuyên môn: [''SEO kỹ thuật'', ''Screaming Frog'', ''Google Tag Manager'', ''HTML/CSS cơ bản'']
Kỹ năng mềm: [''Sáng tạo'', ''Khả năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Không gian làm việc mở'', ''Được tự do đề xuất ý tưởng'', ''Văn hóa công ty hướng đến sáng tạo'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (322, 8, 7, 'Sáng Tạo Nội Dung Chuẩn SEO', 'Lên kế hoạch và viết bài chuẩn SEO cho website công ty. Phối hợp với team content và marketing để xây dựng hệ thống bài viết theo từng giai đoạn phát triển. Nghiên cứu từ khóa, triển khai chiến lược nội dung tăng thứ hạng Google. Theo dõi hiệu suất từ bài viết SEO, cập nhật và tối ưu nội dung định kỳ.', 'Có kinh nghiệm viết content SEO. Hiểu biết về công cụ như Google Keyword Planner, Ahrefs, SEMrush là một lợi thế. Kỹ năng viết tốt, sáng tạo, tư duy hệ thống nội dung logic. Ưu tiên ứng viên có portfolio hoặc blog cá nhân.
Kỹ năng chuyên môn: [''Viết content SEO'', ''Google Keyword Planner'', ''Ahrefs'', ''SEMrush'']
Kỹ năng mềm: [''Kỹ năng viết tốt'', ''Sáng tạo'', ''Tư duy hệ thống nội dung logic'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Đăng ký giờ làm linh hoạt'', ''Phụ cấp xăng xe'', ''Cước điện thoại'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (323, 9, 7, 'Nhân Viên Thiết Kế Đồ Họa', '- Thiết kế lại logo, hình ảnh cho các sản phẩm thời trang, khẩu trang, cốc, mũ, poster,... theo những ý tưởng có sẵn nhằm thỏa mãn yêu cầu của khách hàng - Sáng tạo các mẫu thiết kế mới mang tính độc đáo và bắt kịp xu hướng thị trường phục vụ hoạt động kinh doanh của Công ty theo yêu cầu - Thường xuyên báo cáo kế hoạch làm việc và tiến độ thực hiện công việc cho trưởng bộ phận - Chịu trách nhiệm về kết quả công việc được giao trước trưởng bộ phận', '- Tốt nghiệp Trung cấp, Cao đẳng, Đại học chuyên ngành Thiết kế - Biết sử dụng các phần mềm chỉnh sửa, thiết kế như Photoshop, Illustrator/Corel,… ưu tiên có kinh nghiệm làm các mockup 3d -Có gu thẩm mỹ tốt
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Corel'']
Kỹ năng mềm: [''Có gu thẩm mỹ tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 9000000.00, '6.0 - 9.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Phụ cấp theo vị trí công việc'', ''Thưởng kpi'', ''Chế độ theo quy định của Nhà nước'', ''Du lịch, lễ tết, hiếu hỉ, sinh con'', ''Bảo hiểm xã hội'', ''Khám sức khỏe định kỳ'', ''Team building'', ''Du lịch hàng năm'', ''Thưởng hiệu quả làm việc'', ''Thưởng tháng 13'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (324, 10, 7, 'Marketing Intern', 'Tìm kiếm và liên hệ KOC/KOL trong lĩnh vực sức khỏe, mẹ & bé, nhà thuốc. Theo dõi và cập nhật tiến độ booking trên file. Cập nhật báo cáo theo tuần/tháng. Hỗ trợ team Marketing các công việc khác khi cần.', 'Là sinh viên năm 3, 4 hoặc mới tốt nghiệp các ngành QTKD, Marketing, Dược, Truyền thông. Có tư duy logic, chủ động và chịu được áp lực. Biết sử dụng Google Sheet/Excel cơ bản và mạng xã hội. Ưu tiên có hiểu biết về Tiktok, chăm sóc sức khỏe, nhà thuốc hoặc từng booking KOL. Có laptop cá nhân để làm việc.
Kỹ năng chuyên môn: [''Google Sheet'', ''Excel'', ''Mạng xã hội'']
Kỹ năng mềm: [''Tư duy logic'', ''Chủ động'', ''Chịu được áp lực'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Đào tạo 1:1 quy trình booking dược phẩm chuyên nghiệp'', ''Môi trường tiếp cận tư duy marketing chuẩn châu Âu'', ''Cơ hội tham gia các buổi training nội bộ chuyên sâu'', ''Cơ hội trở thành nhân viên chính thức hoặc CTV marketing sau thực tập'', ''Hỗ trợ đóng dấu mộc thực tập'', ''Làm việc cùng một team trẻ trung'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (325, 2, 7, 'Tiếp thị nội dung TTS', 'Lên kế hoạch và thực hiện các chiến dịch content marketing cho các sản phẩm, dịch vụ của công ty. Viết bài quảng cáo, bài PR, bài báo, blog post về các chủ đề liên quan đến ngành hàng tiêu dùng nhanh (FMCG). Phối hợp với team thiết kế để tạo ra các hình ảnh, video minh họa cho nội dung. Nghiên cứu xu hướng thị trường, phân tích đối thủ cạnh tranh để đề xuất ý tưởng nội dung mới.', 'Có kỹ năng viết lách tốt, văn phong mạch lạc, hấp dẫn. Có kiến thức cơ bản về content marketing, social media marketing. Có khả năng sáng tạo, tư duy nhanh nhạy, nắm bắt xu hướng thị trường. Thành thạo tin học văn phòng, có khả năng sử dụng các công cụ thiết kế cơ bản là một lợi thế. Có khả năng làm việc độc lập và làm việc nhóm tốt. Chủ động, sáng tạo trong công việc, có tinh thần học hỏi cao.
Kỹ năng chuyên môn: [''Kỹ năng viết lách'', ''Tin học văn phòng'', ''Sử dụng các công cụ thiết kế cơ bản'']
Kỹ năng mềm: [''Sáng tạo'', ''Tư duy nhanh nhạy'', ''Làm việc độc lập'', ''Làm việc nhóm tốt'', ''Chủ động'', ''Có tinh thần học hỏi cao'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 12:00 đến 17:00)', '[''Mức lương cạnh tranh'', ''Được đào tạo về kỹ năng marketing, content writing'', ''Môi trường làm việc trẻ trung, năng động'', ''Có cơ hội phát triển bản thân'', ''Tham gia các hoạt động team building, du lịch nghỉ mát hàng năm'', ''Chế độ bảo hiểm đầy đủ theo quy định của pháp luật'', ''Thưởng các dịp lễ tết, thưởng theo hiệu quả công việc'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (326, 3, 7, 'Xuất bản nội dung AI', 'Tham gia hỗ trợ phát triển ban nhạc AI đầu tiên của MCV – Cheeky Band, gồm các thành viên ảo, cá tính riêng, hát nhạc do AI tạo ra, với định hướng đột phá về công nghệ và giải trí. Hỗ trợ sản xuất MV, short video, livestream, phỏng vấn “ảo”. Viết nội dung giới thiệu thành viên band, xây dựng cá tính nhân vật. Vận hành fanpage, TikTok, Instagram... của ban nhạc. Tìm kiếm, thử nghiệm và đề xuất công cụ AI phù hợp. Tham gia xây dựng cộng đồng người hâm mộ (fanbase). Hỗ trợ lên idea viral content, trend, thử thách TikTok cho band.', 'Sinh viên các ngành Sư Phạm, Truyền thông, Báo chí, Sản xuất, Âm nhạc, Thiết kế, Công nghệ thông tin, Marketing... hoặc ngành liên quan. Ham học hỏi, chịu khó thử nghiệm công cụ mới, có tinh thần startup. Biết dùng AI là một lợi thế lớn (AI music, AI video, AI design...). Có năng lực sáng tạo nội dung (viết caption, dựng video, vẽ nhân vật, phối nhạc, dựng trend...). Thời gian linh hoạt, làm việc theo dự án.
Kỹ năng chuyên môn: [''Biết dùng AI'']
Kỹ năng mềm: [''Ham học hỏi'', ''Chịu khó thử nghiệm công cụ mới'', ''Có tinh thần startup'', ''Năng lực sáng tạo nội dung'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 09:00 đến 13:00)', '[''Trợ cấp: 1.000.000 vnđ/ tháng'', ''Môi trường làm việc trẻ, năng động, đón đầu công nghệ'', ''Được đào tạo trực tiếp bởi các producer, biên tập viên, đạo diễn lâu năm'', ''Cơ hội trở thành nhân sự chính thức nếu thể hiện tốt'', ''Có cơ hội tham gia sản xuất các chương trình nổi tiếng, làm việc với nghệ sĩ, thương hiệu lớn'', ''Được hỗ trợ mộc báo cáo thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (327, 7, 7, 'Thực Tập Sinh Digital Marketing (FB Ads, GG Ads)', 'Hỗ trợ xây dựng và triển khai các chiến lược quảng cáo toàn diện trên nền tảng Facebook, Google Ads và các nền tảng khác; Hỗ trợ theo dõi, thống kê và phân tích số liệu, để đánh giá hiệu quả của chiến dịch; Nghiên cứu khách hàng, tìm insight và đề xuất thông điệp phù hợp với từng tệp đối tượng. Phối hợp chặt chẽ với team content, thiết kế và sales để đảm bảo thông điệp nhất quán và hiệu quả. Cập nhật xu hướng nội dung, thuật toán mới từ Facebook/Google để ứng dụng vào thực tế.', 'Trình độ học vấn: Sinh viên năm 3, 4 học chuyên ngành liên quan; Có laptop làm việc; Chủ động trong công việc, nhiệt tình, có trách nhiệm; Có kiến thức nền tảng về Digital Marketing, Facebook Ads, Google Ads; Có kiến thức về công cụ phân tích như Google Analytics, Facebook Insights là một lợi thế; Tiếng anh đọc – viết.
Kỹ năng chuyên môn: [''Digital Marketing'', ''Facebook Ads'', ''Google Ads'', ''Google Analytics'', ''Facebook Insights'']
Kỹ năng mềm: [''Chủ động trong công việc'', ''Nhiệt tình'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.5 - 3.0 triệu', '30-35 giờ làm việc/tuần', '[''Hỗ trợ thực tập (100k/ngày) + thưởng'', ''Được đào tạo kỹ lưỡng, hỗ trợ nhiệt tình'', ''Làm việc trong môi trường năng động, hòa đồng, chuyên nghiệp'', ''Được hỗ trợ dấu mộc thực tập'', ''Có cơ hội thăng tiến lên vị trí cao hơn nếu làm tốt'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (328, 8, 7, 'Nhân Viên Livestream Partime (Mảng Mẹ Bé)', 'Tổ chức và thực hiện các buổi livestream sản phẩm, dịch vụ nhằm tăng cường tương tác với khách hàng và thúc đẩy doanh số bán hàng. Phối hợp với các bộ phận liên quan để chuẩn bị nội dung, hình ảnh và video cho các buổi livestream, đảm bảo chất lượng và tính hấp dẫn. Theo dõi và phân tích dữ liệu từ các buổi livestream để đánh giá hiệu quả và cải thiện chiến lược truyền thông. Tương tác trực tiếp với người xem trong suốt buổi livestream, trả lời câu hỏi và giải đáp thắc mắc để tạo sự kết nối và tăng cường lòng tin của khách hàng. Cập nhật và quản lý các kênh truyền thông xã hội liên quan đến livestream, bao gồm việc tạo nội dung và lên lịch đăng bài để thu hút lượng người xem tối đa.', 'Tốt nghiệp cao đẳng hoặc đại học các ngành liên quan đến truyền thông, marketing hoặc nghệ thuật. Đã từng làm việc trong lĩnh vực livestream hoặc truyền thông trực tuyến. Kỹ năng giao tiếp tốt, có khả năng tương tác và thu hút khán giả trong thời gian thực. Sử dụng thành thạo các công cụ livestream và phần mềm chỉnh sửa video. Có kiến thức về các nền tảng mạng xã hội và xu hướng nội dung trực tuyến hiện nay. Khả năng làm việc độc lập và dưới áp lực, sắp xếp thời gian hiệu quả để đảm bảo lịch livestream.
Kỹ năng chuyên môn: [''Sử dụng thành thạo các công cụ livestream'', ''Phần mềm chỉnh sửa video'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng tương tác và thu hút khán giả trong thời gian thực'', ''Khả năng làm việc độc lập và dưới áp lực'', ''Sắp xếp thời gian hiệu quả'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Lương theo tiếng làm việc'', ''Thời gian làm việc linh hoạt, thỏa thuận giữa 2 bên'', ''Có nhân viên hỗ trợ set up'', ''Tự tin livestream do sản phẩm có giấy tờ nguồn gốc rõ ràng'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (329, 9, 7, 'Thực Tập Sinh CONTENT MARKETING (TIẾNG ANH)', 'Tham gia xây dựng và triển khai kế hoạch nội dung cho các kênh truyền thông số: Facebook, Instagram, TikTok, Website, Email... Viết bài PR, blog, nội dung quảng cáo, nội dung landing page, mô tả sản phẩm/dịch vụ bất động sản. Hỗ trợ lên ý tưởng và viết kịch bản video, reels, TikTok cùng team Media. Phối hợp với thiết kế để đảm bảo nội dung và hình ảnh đồng bộ, hiệu quả truyền thông tốt. Cập nhật xu hướng nội dung, tham gia brainstorm và đề xuất các chiến dịch sáng tạo mới. Các công việc khác theo phân công của quản lý.', 'Là sinh viên năm 3–4 hoặc mới tốt nghiệp chuyên ngành Truyền thông, Marketing, Báo chí, hoặc các ngành liên quan. Yêu thích viết lách, tư duy sáng tạo, chủ động cập nhật trend. Có khả năng trình bày nội dung rõ ràng, mạch lạc, đúng chính tả. Biết thiết kế đơn giản với Canva. Có tinh thần học hỏi, trách nhiệm và cam kết với công việc. Ưu tiên ứng viên có kinh nghiệm viết content trên mạng xã hội hoặc có sản phẩm nội dung cá nhân. Gửi kèm Portfolio.
Kỹ năng chuyên môn: [''Viết bài PR, blog, nội dung quảng cáo, nội dung landing page, mô tả sản phẩm/dịch vụ'', ''Biết thiết kế đơn giản với Canva'']
Kỹ năng mềm: [''Yêu thích viết lách'', ''Tư duy sáng tạo'', ''Có khả năng trình bày nội dung rõ ràng, mạch lạc, đúng chính tả'', ''Có tinh thần học hỏi, trách nhiệm và cam kết với công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Hỗ trợ phụ cấp thực tập hàng tháng'', ''Được đào tạo, hướng dẫn trực tiếp từ các anh chị trong team'', ''Làm việc trong môi trường sáng tạo – thân thiện – có định hướng phát triển rõ ràng'', ''Tham gia các hoạt động nội bộ, team building cùng công ty'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập nếu phù hợp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (330, 10, 7, 'Tiếp thị nội dung Bán thời gian - NgànH F & B', 'Sản xuất nội dung hàng tuần cho kênh TikTok, Facebook và Instagram. Hỗ trợ tìm kiếm và hợp tác với các KOCs cho các chiến dịch. Hỗ trợ các hoạt động của công ty để đạt được KPI cá nhân và của team. Thực hiện các công việc khác theo sự phân công của quản lý trực tiếp.', 'Có tư duy sáng tạo tốt, khả năng bắt trend xu hướng các nội dung mạng xã hội. Thành thạo các công cụ sáng tạo nội dung cơ bản như Capcut, Canva. Tính cách cởi mở, năng động. Tối thiểu 25 giờ/tuần, từ thứ Hai đến thứ Sáu (9h sáng - 5h chiều). Khả năng giao tiếp Tiếng Anh là một lợi thế. Kinh nghiệm dưới 1 năm hoặc không yêu cầu kinh nghiệm. Sinh viên năm cuối hoặc mới tốt nghiệp các trường Cao đẳng, Đại học.
Kỹ năng chuyên môn: [''Capcut'', ''Canva'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Khả năng bắt trend'', ''Tính cách cởi mở'', ''Năng động'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Tối thiểu 25 giờ/tuần, từ thứ Hai đến thứ Sáu (9h sáng - 5h chiều)', '[''Thưởng hiệu quả làm việc'', ''Team building'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (331, 2, 7, 'Tài khoản thực tập', 'Dịch vụ & Kế hoạch khách hàng. Lấy tóm tắt dự án từ khách hàng. Làm việc phối hợp với các nhóm nội bộ như sáng tạo, chiến lược, hoạt động và với các đối tác/nhà cung cấp bên ngoài. Phát triển dự án và thực hiện. Hiện tại và bán ý tưởng cho khách hàng. Theo dõi khách hàng để đạt được thỏa thuận dự án và ký hợp đồng. Chịu trách nhiệm quản lý dự án như kế hoạch đã đồng ý với khách hàng. Đảm bảo dòng thời gian và chất lượng của dự án theo thỏa thuận với khách hàng. Chịu trách nhiệm về các khoản nợ liên quan đến khách hàng của mình. Chăm sóc khách hàng một cách chuyên nghiệp.', 'Enthusiasm for activation/event. Fluency in English, both written and verbal. Capability in client servicing, project planning and execution. Any experience is preferred. Carefulness, attention to details. Being ambitious, with the ability to withstand work pressure. Good presentation skill. Competence in Microsoft Powerpoint, Apple Keynote, Google Slides, or any equivalent presentation software.
Kỹ năng chuyên môn: [''Microsoft Powerpoint'', ''Apple Keynote'', ''Google Slides'']
Kỹ năng mềm: [''Communication (written and verbal)'', ''Presentation skills'', ''Attention to details'', ''Ability to withstand work pressure'', ''Client servicing'', ''Project planning and execution'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Allowance/Compensation depending on the company’s policy'', ''Friendly, dynamic working environment'', ''Fast growth and development'', ''Opportunity to experience a professional agency environment'', ''Support with company stamp and signature for internship confirmation'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (332, 3, 7, 'Thực Tập Sinh Content Marketing Tiếng Anh Du Lịch', 'Viết blog Tiếng Anh giới thiệu các địa điểm, địa danh du lịch, các nội dung du lịch ấn tượng tới người đọc. Thực hiện tác vụ SEO website, tối ưu nội dung trên công cụ tìm kiếm. Thực hiện các tác vụ truyền thông khác.', 'Là sinh viên đang học tập tại Hà Nội, sử dụng tốt tiếng Anh. Không yêu cầu kinh nghiệm, kỹ năng đọc, viết tốt. Có thể làm 6 buổi 1 tuần (sáng hoặc chiều từ thứ 2 đến thứ 6 và sáng thứ 7). Có thể linh hoạt lịch làm theo lịch cá nhân.
Kỹ năng chuyên môn: [''Kỹ năng đọc, viết tiếng Anh'', ''Sử dụng các tool thiết kế hình ảnh, clip'']
Kỹ năng mềm: [''Tỉ mỉ'', ''Chi tiết'', ''Cẩn thận'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '1.5 - 3.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Nghỉ các ngày lễ theo bộ luật lao động'', ''Có cơ hội học hỏi, cọ sát và phát triển bản thân'', ''Được tham gia các hoạt động nội bộ Công ty'', ''Hỗ trợ dấu mộc thực tập sau 2 tháng làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (333, 7, 7, 'Thực Tập Sinh Kinh Doanh', '- Liên hệ với khách hàng theo nguồn data có sẵn do công ty cung cấp. - Tư vấn, hỗ trợ khách hàng về các sản phẩm và dịch vụ của công ty. - Phối hợp với các bộ phận khác để chăm sóc và duy trì mối quan hệ với khách hàng. - Báo cáo kết quả công việc định kỳ cho người hướng dẫn. - Thực hiện các công việc khác theo phân công nhằm phục vụ hoạt động kinh doanh – truyền thông của công ty.', '- Sinh viên năm 2, 3, 4 hoặc mới tốt nghiệp thuộc các chuyên ngành: Marketing, Quản trị kinh doanh, Kinh doanh thương mại, Quan hệ công chúng,… - Không yêu cầu kinh nghiệm – sẽ được đào tạo bài bản. - Có laptop cá nhân để hỗ trợ công việc. - Chăm chỉ, có tinh thần cầu tiến và chủ động học hỏi, Kỹ năng giao tiếp tốt - Làm việc tối thiểu 8 buổi/tuần.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp tốt'']
Kỹ năng mềm: [''Chăm chỉ'', ''Có tinh thần cầu tiến'', ''Chủ động học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Có hỗ trợ phụ cấp thực tập hằng tháng'', ''Nhận hoa hồng khi mang về doanh số từ khách hàng'', ''Được đóng dấu, chữ ký xác nhận, nhận xét thực tập khi kết thúc thời gian thực tập'', ''Được mentor và đội ngũ quản lý cấp cao trực tiếp hướng dẫn'', ''Được tham gia các buổi đào tạo chuyên sâu về kinh doanh, marketing và truyền thông'', ''Làm việc trong môi trường năng động, nhiều cơ hội trải nghiệm thực tế'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (334, 8, 7, 'Thực Tập Sinh Marketing Tiếng Trung HSK', 'Viết bài chuẩn SEO website. Viết kịch bản và xây dựng nội dung cho các video quảng cáo/tiktok HSK. Quay, dựng video dựa trên kịch bản đã viết. Phối hợp với các bộ phận khác để triển khai ý tưởng truyền thông.', '- Văn phong tốt, yêu thích và đam mê viết lách - Có Tiếng Trung tốt hoặc có chứng chỉ HSK là một lợi thế - Có điện thoại, máy tính cá nhân để quay video làm việc - TTS part time, yêu cầu thời gian thực tập tối thiểu 4 tháng, làm việc 5-6 buổi/tuần (tùy theo lịch của công ty) (20-23 giờ/tuần), sắp xếp linh động theo lịch học - Các bạn cân nhắc kế hoạch cá nhân trước khi ứng tuyển, không ứng tuyển tùy hứng làm mất thời gian 2 bên -Tuyển từ 2-3 bạn thực tập sinh
Kỹ năng chuyên môn: [''Viết bài chuẩn SEO'', ''Quay video'', ''Dựng video'']
Kỹ năng mềm: [''Văn phong tốt'', ''Yêu thích viết lách'', ''Khả năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', '5-6 buổi/tuần', '[''Trợ cấp 1 - 2 triệu đồng'', ''Hỗ trợ người tham khảo trong CV'', ''Được đào tạo kỹ năng viết kịch bản'', ''Học hỏi kinh nghiệm làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (335, 9, 7, 'Thực Tập Sinh Kinh Doanh', 'Làm việc theo nhóm, lập đội nghiên cứu thị trường và định vị sản phẩm. Lên kế hoạch giới thiệu sản phẩm. Làm các kênh truyền thông và telesales.', 'Nhanh nhẹn, linh hoạt và chăm chỉ. Tôn trọng văn hóa công ty. Tôn trọng hoạt động thể, phát huy sáng kiến đóng góp cho phong trào tập thể. Làm việc nghiêm túc và tập trung. Năng động xã giao và gặp gỡ khách hàng. Ứng viên sau khi nộp CV, kiểm tra mail để nhận lịch mời PV qua email. (1,2 ngày sau khi nộp CV)
Kỹ năng chuyên môn: [''Social Media Marketing'', ''Phân tích dữ liệu'', ''Nghiên Cứu Thị Trường'', ''viết content Marketing Cơ Bản'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Linh hoạt'', ''Chăm chỉ'', ''Tôn trọng văn hóa công ty'', ''Năng động xã giao'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được hỗ trợ từ 1tr đến 2tr một tháng trong quá trình TTS'', ''Mọi chế độ tập thể và theo quy định của công ty'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (336, 10, 7, 'Nhân Viên SEO Backlink', '- Tối ưu onpage website, các chỉ số SEO; - Xây dựng hệ thống link liên kết nội bộ. - Xây dựng và triển khai chiến lược link building (Lên kế hoạch -> triển khai -> theo dõi chất lượng nguồn backlink); - Báo cáo kết quả và vấn đề phát sinh lên cấp trên trực tiếp. - Có chí hướng phát triển và học hỏi.', 'Kỹ năng chuyên môn: * Hiểu biết sâu về SEO, thuật toán tìm kiếm của Google và các công cụ hỗ trợ SEO như Google Analytics, Google Search Console, Ahrefs, SEMrush. * Kỹ năng nghiên cứu từ khóa và phân tích đối thủ. Tư duy và phát triển cá nhân: * Có tinh thần học hỏi và cập nhật xu hướng mới trong lĩnh vực SEO. * Chí hướng phát triển sự nghiệp, khả năng làm việc độc lập cũng như trong nhóm. Khả năng lập kế hoạch và quản lý công việc: * Có kỹ năng tổ chức, theo dõi công việc và giải quyết vấn đề.
Kỹ năng chuyên môn: [''SEO'', ''Google Analytics'', ''Google Search Console'', ''Ahrefs'', ''SEMrush'']
Kỹ năng mềm: [''Tư duy tổ chức'', ''Giải quyết vấn đề'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Thưởng KPI'', ''Thưởng trực tiếp theo hiệu quả công việc'', ''Đóng dấu đỏ thực tập của công ty'', ''Môi trường làm việc năng động, sáng tạo'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (337, 2, 7, 'Thực Tập Sinh Thiết Kế', '- Tham gia các chuỗi các hoạt động sự kiện do Công ty tổ chức - Tham gia đưa ý tưởng thiết kế cho các sự kiện, dự án của Công ty .... - Tham gia các hoạt động nội bộ', '- SV năm cuối CÁC NGÀNH THIẾT KẾ - Biết sử dụng các ứng dụng đồ họa cơ bản - Mong muốn được phát triển bản thân
Kỹ năng chuyên môn: [''Biết sử dụng các ứng dụng đồ họa cơ bản'']
Kỹ năng mềm: [''Mong muốn được phát triển bản thân'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Sinh viên được tạo điều kiện thực tập tối đa'', ''Được tham gia vào các sự kiện lớn'', ''Bảng xác nhận quá trình thực tập'', ''Hỗ trợ xăng xe đi lại'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (338, 3, 7, 'Thực Tập Sinh Kinh Doanh', 'Gọi điện thoại cho khách hàng tiềm năng để tư vấn, giới thiệu sản phẩm/dịch vụ. Tư vấn và giải đáp mọi thắc mắc của khách hàng liên quan đến sản phẩm/ dịch vụ của Công ty. Gửi báo giá, tư vấn sản phẩm/dịch vụ cho khách hàng quan tâm qua kênh online. Thực hiện các công việc theo phân công của quản lý. Báo cáo kết quả công việc hàng ngày cho quản lý.', 'Các bạn mới ra trường chưa có kinh nghiệm, sinh viên năm 4 có thể làm được full time. Kỹ năng giao tiếp tốt. Có giọng nói chuẩn, không nói ngọng, không nói tiếng địa phương. Tư duy sáng tạo, tư duy giải quyết vấn đề, tư duy leadership. Chăm chỉ, nhanh nhẹn, có trách nhiệm với công việc được giao.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Tư duy sáng tạo'', ''Tư duy giải quyết vấn đề'', ''Tư duy leadership'', ''Chăm chỉ'', ''Nhanh nhẹn'', ''Có trách nhiệm với công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Lương cứng 1.500.000 đồng + Lương KPI + PC ăn trưa + thưởng'', ''Được đào tạo các kỹ năng làm việc'', ''Có cơ hội trở thành nhân viên chính thức sau thời gian thực tập'', ''Hỗ trợ dấu mộc cho các bạn sinh viên'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (339, 7, 7, 'Thực Tập Thiết Kế Đồ Họa 2D Mảng Print On Demand', '• Tạo ra các thiết kế hấp dẫn và độc đáo cho sản phẩm POD (áo, cốc, thảm, nón...) • Phối hợp chặt chẽ với bộ phận Idea và Marketing để đảm bảo thiết kế phù hợp với concept và xu hướng thị trường • Chỉnh sửa và tối ưu hóa thiết kế theo phản hồi từ team và khách hàng • Theo dõi xu hướng thiết kế mới và áp dụng vào công việc • Biết chụp hình sản phẩm, quay dựng video ngắn cho Tiktok bằng Capcut • Các công việc khác liên quan theo yêu cầu của quản lý hoặc cấp trên', '• Đang theo học chuyên ngành Thiết kế đồ họa hoặc liên quan • Biết tiếng Anh cơ bản • Kỹ năng vẽ tay, biết chụp ảnh sản phẩm, edit video sử dụng Capcut là một lợi thế • Ưu tiên thời gian thực tập fulltime
Kỹ năng chuyên môn: [''Kỹ năng vẽ tay'', ''Biết chụp ảnh sản phẩm'', ''Edit video sử dụng Capcut'']
Kỹ năng mềm: [''Khả năng làm việc nhóm'', ''Sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Môi trường làm việc trẻ trung, năng động, sáng tạo'', ''Cơ hội phát triển và trở thành nhân viên chính thức'', ''Phụ cấp: ăn trưa, xăng xe'', ''Du lịch, team-building hàng năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (340, 8, 7, 'Thực Tập Sinh Marketing', 'Thiết kế Poster sản phẩm, Poster cho các phòng ban khác theo yêu cầu của quản lý. Xây dựng, thiết kế nội dung và đăng bài trên các Fanpage. Thực hiện các công việc chạy Ads, Landing Page trên các nền tảng và SEO. Quay và chỉnh sửa video cơ bản.', 'Ưu tiên sinh viên năm 3, năm 4 chuyên ngành Marketing hoặc các ngành có liên quan. Có khả năng thiết kế, tư duy hình ảnh và làm việc nhóm tốt. Tinh thần trách nhiệm cao, chủ động trong công việc, sẵn sàng học hỏi và phát triển. Kỹ năng giao tiếp tốt, linh hoạt trong xử lý tình huống và yêu thích công việc sáng tạo. Ưu tiên ứng viên biết quay dựng video và chạy Ads.
Kỹ năng chuyên môn: [''Thiết kế Poster'', ''Chạy Ads'', ''SEO'', ''Quay và chỉnh sửa video'']
Kỹ năng mềm: [''Tư duy hình ảnh'', ''Làm việc nhóm'', ''Tinh thần trách nhiệm'', ''Giao tiếp tốt'', ''Linh hoạt trong xử lý tình huống'', ''Yêu thích công việc sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Hỗ trợ thông tin và tài liệu cho báo cáo thực tập'', ''Thời gian làm việc linh hoạt'', ''Khóa đào tạo chuyên sâu'', ''Cơ chế thăng tiến rõ ràng'', ''Môi trường làm việc năng động'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (341, 9, 7, 'Nhân Viên Content Marketing', '- Lên kế hoạch nội dung theo tuần/tháng cho các kênh: Fanpage, TikTok, Instagram - Viết bài, lên ý tưởng và sản xuất nội dung phù hợp với định hướng thương hiệu - Cập nhật tin tức, xu hướng thị trường và nhu cầu của khách hàng - Phối hợp cùng đội ngũ để đảm bảo chất lượng hình ảnh, nội dung và tiến độ đăng tải', '- Đang là sinh viên hoặc đã tốt nghiệp Đại Học. - Có laptop cá nhân - Biết sử dụng máy ảnh cơ, có mắt thẩm mỹ - Thành thạo Canva, Capcut, Photoshop hoặc phần mềm thiết kế tương đương - Có kinh nghiệm xây dựng nội dung/hình ảnh cho các nền tảng mạng xã hội (ưu tiên ứng viên từng làm trong ngành F&B) - Nhanh nhẹn, chủ động, có tinh thần trách nhiệm và cam kết với công việc
Kỹ năng chuyên môn: [''Thành thạo Canva'', ''Capcut'', ''Photoshop'', ''Biết sử dụng máy ảnh cơ'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chủ động'', ''Có tinh thần trách nhiệm'', ''Cam kết với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được đào tạo chuyên môn trong ngành F&B'', ''Cung cấp học liệu và công cụ hỗ trợ công việc'', ''Làm việc trong môi trường ổn định, có định hướng phát triển lâu dài'', ''Chế độ nghỉ lễ – Tết đầy đủ theo quy định của Nhà nước'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (342, 10, 7, 'Thực Tập Sinh Truyền Thông - Marketing', '- Nghiên cứu, thu thập thông tin về thị trường, đối thủ và khách hàng mục tiêu. - Tham gia phân tích dữ liệu, khảo sát thị trường, tiếp cận khách hàng và đánh giá hiệu quả các chiến dịch marketing. - Giúp quản lý và cập nhật các kênh truyền thông của công ty như website, mạng xã hội. - Thực hiện việc đăng bài viết, hình ảnh, video và các nội dung khác lên các nền tảng truyền thông xã hội. - Tương tác với khách hàng trên các nền tảng này để duy trì và tăng cường sự kết nối. - Hỗ trợ lên ý tưởng trong việc viết bài blog, bài PR, bài quảng cáo và các bài viết trên mạng xã hội. - Thiết kế và chỉnh sửa hình ảnh đơn giản, video marketing cho các chiến dịch truyền thông. - Hỗ trợ lên kế hoạch và tổ chức các sự kiện, hội thảo của công ty. - Thực hiện các công việc hậu cần như chuẩn bị tài liệu, quà tặng, trang trí, và hỗ trợ khách mời. - Hỗ trợ trong việc chuẩn bị các tài liệu, hợp đồng, và các báo cáo kết quả dự án cho các cuộc họp với khách hàng. - Thực hiện các công tác hành chính liên quan đến quản lý tài liệu, hợp đồng và các thủ tục cần thiết cho dự án. - Cơ hội học hỏi và trau dồi kỹ năng quản lý dự án, tư vấn và đánh giá giải pháp trong môi trường doanh nghiệp thực tế. - Tham gia vào các khóa đào tạo nội bộ và hoạt động phát triển nghề nghiệp.', '* Ứng viên chuẩn bị tốt nghiệp các chuyên ngành liên quan * Có laptop cá nhân * Có thể làm fulltime * Có ý thức trách nhiệm, thái độ tốt, nhanh nhẹn hoạt bát * Thành thạo tin học văn phòng : Word, Excel, Powerpoint... * Có kỹ năng viết và sáng tạo nội dung * Có kỹ năng quay chụp, edit cơ bản
Kỹ năng chuyên môn: [''Tin học văn phòng: Word, Excel, Powerpoint'', ''Kỹ năng viết và sáng tạo nội dung'', ''Kỹ năng quay chụp, edit cơ bản'']
Kỹ năng mềm: [''Ý thức trách nhiệm'', ''Thái độ tốt'', ''Nhanh nhẹn'', ''Hoạt bát'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 1000000.00, '1.5 triệu', 'Fulltime', '[''Hỗ trợ phụ cấp trách nhiệm 1.500.000đ'', ''Hỗ trợ dấu mộc, thư giới thiệu sau thực tập'', ''Môi trường làm việc chuyên nghiệp, năng động'', ''Hướng dẫn và đào tạo từ đội ngũ quản lý có kinh nghiệm'', ''Tham gia các khóa đào tạo, nâng cao nghiệp vụ chuyên môn'', ''Tham gia trực tiếp vào các sự kiện, dự án thực tế'', ''Cơ hội trở thành nhân viên chính thức sau thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (343, 2, 7, 'Thực Tập Sinh Content Marketing', 'Xây dựng nội dung, chăm sóc và quản trị nội dung cho các kênh truyền thông và trang mạng xã hội của Team Sales. Đánh giá và đo lường hiệu quả của các tuyến nội dung. Tham gia xây dựng, đóng góp ý tưởng và lập kế hoạch cho chiến lược Content Marketing. Phối hợp với bộ phận liên quan để sản xuất nội dung cho các sản phẩm. Phối hợp với nhân viên ADs sử dụng các công cụ tìm xu hướng content mới.', 'Học (Tốt nghiệp) các trường/ khóa học chuyên ngành Marketing. Có tiếp xúc, hiểu biết về content marketing. Khả năng nghiên cứu, cập nhật nhanh các xu hướng nội dung mới, bắt trend trên mạng xã hội. Có khả năng làm việc và hỗ trợ nhóm tốt. Nhanh nhẹn, sáng tạo, khả năng xử lý và ứng biến công việc tốt; Tinh thần trách nhiệm cao, ham học hỏi, làm việc độc lập và phối hợp đội nhóm tốt.
Kỹ năng chuyên môn: [''Nghiên cứu từ khóa SEO cơ bản'', ''Sử dụng mạng xã hội'']
Kỹ năng mềm: [''Khả năng làm việc nhóm'', ''Sáng tạo'', ''Tinh thần trách nhiệm cao'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:30 đến 16:30)', '[''Trợ cấp lương 2.000.000 - 4.000.000'', ''Môi trường làm việc chuyên nghiệp'', ''Được tham gia các hoạt động văn hóa sôi nổi của công ty'', ''Được đào tạo và tham gia các buổi đào tạo/khóa học miễn phí về nghiệp vụ Marketing'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (344, 3, 7, 'Thực Tập Sinh Tư Vấn Website', 'Tìm kiếm khách hàng tiềm năng thông qua các kênh online và offline. Liên hệ, tư vấn và giới thiệu các sản phẩm dịch vụ về Domain/Hosting/Server của công ty đến khách hàng. Chăm sóc khách hàng, giải đáp thắc mắc và hỗ trợ khách hàng trong quá trình sử dụng sản phẩm/dịch vụ. Lập kế hoạch kinh doanh cá nhân, báo cáo kết quả kinh doanh định kỳ. Đàm phán và ký kết hợp đồng với khách hàng. Quản lý danh sách khách hàng và thông tin liên hệ. Phối hợp với các bộ phận khác trong công ty để đảm bảo chất lượng dịch vụ khách hàng.', 'Không yêu cầu kinh nghiệm. Kỹ năng đàm phán tốt. Kỹ năng thuyết phục tốt. Kỹ năng quản lý thời gian hiệu quả. Kỹ năng lập kế hoạch tốt. Có khả năng giao tiếp tốt, giọng nói dễ nghe. Khả năng sử dụng máy tính thành thạo. Nhiệt tình, năng động, ham học hỏi. Ưu tiên sinh viên năm 4 các trường CĐ, ĐH. Hỗ trợ vắng tối đa 2 buổi/ tuần.
Kỹ năng chuyên môn: [''Sử dụng máy tính thành thạo'']
Kỹ năng mềm: [''Kỹ năng đàm phán tốt'', ''Kỹ năng thuyết phục tốt'', ''Kỹ năng quản lý thời gian hiệu quả'', ''Kỹ năng lập kế hoạch tốt'', ''Có khả năng giao tiếp tốt, giọng nói dễ nghe'', ''Nhiệt tình, năng động, ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Môi trường làm việc năng động, chuyên nghiệp và thân thiện'', ''Được đào tạo bài bản về sản phẩm, kỹ năng bán hàng và kỹ năng mềm'', ''Có nhiều cơ hội thăng tiến sau khi hoàn thành khóa thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (345, 7, 7, 'Thực Tập Sinh Marketing', 'Hỗ trợ đội ngũ kinh doanh trong việc tìm kiếm và phát triển khách hàng tiềm năng. Tham gia các hoạt động marketing và quảng bá sản phẩm mà công ty đưa ra. Nghiên cứu thị trường, phân tích dữ liệu và lập báo cáo. Góp ý, tham gia các buổi họp và thảo luận để phát triển ý tưởng dự án. Quản lý và phát triển nội dung trên fanpage (viết bài, đăng bài, tương tác với khách hàng).', 'Là sinh viên năm 3, năm 4 hoặc mới tốt nghiệp các ngành Kinh tế, Quản trị kinh doanh, Marketing. Có thể làm việc ít nhất 4 buổi/tuần (tối thiểu 2 giờ/buổi). Có kỹ năng giao tiếp tốt, làm việc nhóm hiệu quả. Biết quay dựng video cơ bản bằng điện thoại (sử dụng CapCut, TikTok Editor, hoặc phần mềm tương tự). Nhanh nhẹn, chủ động và có tinh thần học hỏi. Cam kết tham gia đầy đủ chương trình đào tạo 3 ngày tại công ty.
Kỹ năng chuyên môn: [''Quay dựng video cơ bản'', ''Sử dụng CapCut'', ''Sử dụng TikTok Editor'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Làm việc nhóm hiệu quả'', ''Nhanh nhẹn'', ''Chủ động'', ''Có tinh thần học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 16:00)', '[''Được đào tạo và hướng dẫn bài bản bởi các chuyên gia trong ngành'', ''Cơ hội rèn luyện và phát triển kỹ năng nghề nghiệp thực tiễn'', ''Hỗ trợ chi phí thực tập khi phát sinh giao dịch'', ''Có cơ hội được xét tuyển trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (346, 8, 7, 'Thực Tập Sinh Content Creator TikTok', 'Lên ý tưởng và xây dựng kịch bản nội dung video TikTok theo định hướng của công ty. Tự quay, dựng và chỉnh sửa video hoàn chỉnh để đăng lên kênh TikTok chính thức. Nghiên cứu xu hướng, bắt trend phù hợp để tăng độ tương tác và thu hút người xem. Tham gia đóng góp ý tưởng nội dung cho các chiến dịch truyền thông, marketing của công ty. Phối hợp với bộ phận marketing và các bộ phận khác để đảm bảo nội dung đúng mục tiêu và hình ảnh thương hiệu. Sẵn sàng hỗ trợ các công việc khác liên quan đến truyền thông, marketing hoặc vận hành theo phân công.', 'Đam mê sáng tạo nội dung trên nền tảng Tiktok. Có khả năng lên ý tưởng, viết kịch bản, tự quay và dựng video. Nắm bắt xu hướng nhanh, sáng tạo ý tưởng thu hút và phù hợp với thị trường. Chủ động, cởi mở, ham học hỏi và có kỹ năng làm việc nhóm tốt. Sẵn sàng hỗ trợ các công việc khác liên quan đến truyền thông, marketing. Biết sử dụng các công cụ chỉnh sửa video cơ bản.
Kỹ năng chuyên môn: [''Kỹ năng quay phim'', ''Chỉnh sửa video cơ bản'', ''Sử dụng thành thạo TikTok'']
Kỹ năng mềm: [''Kỹ năng làm việc nhóm'', ''Chủ động'', ''Cởi mở'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), linh hoạt, tối thiểu 3-4 ngày/tuần theo thỏa thuận.', '[''Hỗ trợ chi phí thực tập'', ''Được đào tạo, hướng dẫn về quy trình sản xuất nội dung và kỹ năng truyền thông'', ''Môi trường làm việc thân thiện, năng động, tạo điều kiện học hỏi và phát triển'', ''Cơ hội tích lũy kinh nghiệm thực tế, nâng cao kỹ năng sáng tạo và sản xuất nội dung'', ''Có cơ hội trở thành cộng tác viên hoặc nhân viên chính thức sau khi hoàn thành quá trình thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (347, 9, 7, 'Thực Tập Sinh Marketing (Account Intern)', 'Hỗ trợ xây dựng và triển khai các kế hoạch tiếp thị và quảng cáo hiệu quả cho khách hàng dựa trên thông tin kinh doanh của họ. Tổng hợp các báo cáo về tình hình thị trường, nhu cầu khách hàng tiềm năng, định hướng sản phẩm. Tham gia xây dựng ý tưởng để sản phẩm dịch vụ có lợi thế cạnh tranh so với thị trường. Thường xuyên tìm hiểu, cập nhật xu hướng, sáng kiến tiếp thị mới, hỗ trợ soạn thảo các đề xuất kinh doanh mới. Những công việc khác theo yêu cầu của Quản lý.', 'Học vấn: Năm cuối các trường đại học chuyên ngành Marketing, Quản trị kinh doanh (Ưu tiên các bạn biết làm research). Kiến thức về cơ cấu tổ chức và kinh doanh. Khả năng sử dụng thành thạo Microsoft Office, email và internet. Kỹ năng giao tiếp tốt. Có trách nhiệm, làm việc có tổ chức.
Kỹ năng chuyên môn: [''Microsoft Office'', ''email'', ''internet'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Có trách nhiệm'', ''Làm việc có tổ chức'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Phụ cấp theo thỏa thuận'', ''Cơ hội làm việc chính thức với mức lương hấp dẫn nếu năng lực tốt'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (348, 10, 7, 'Thực Tập Sinh Marketing Mobile App', 'Sáng tạo các ý tưởng, tính năng sản phẩm Mobile App/Game hữu ích cho người dùng thị trường: US, UK, Nhật, Hàn... Nghiên cứu người dùng bằng các công cụ như: Google Play, Sensor tower, App annie, Google Console, Firebase,... Tổng hợp dữ liệu, đưa ra ý tưởng cải tiến sản phẩm và chiến lược marketing. Lên kế hoạch, xây dựng nội dung quảng cáo và làm thương hiệu trên các kênh: Google ads, Fb ads, Tiktok, CH-Play, Apple Store, báo chí... Thử nghiệm A/B testing các phương án cải tiến sản phẩm. Theo dõi và đưa ra quyết định quyết đoán, chính xác cho việc phân phối sản phẩm đến người dùng. Teamwork với Designer và Developer để sản xuất, phát hành, cải tiến các sản phẩm Mobile app. Áp dụng mô hình Scrum, sử dụng công cụ Jira kiểm soát Task list đảm bảo tiến độ dự án. Liên tục học hỏi, thử nghiệm kênh marketing mới.', 'Thành thạo tiếng Anh (IELTS 6.0 trở lên hoặc tương đương). Sinh viên năm cuối hoặc có thể làm việc fulltime. Ưu tiên sinh viên trường top (ĐHQG, Neu, Ftu, Hust, ...). Điểm cộng nếu có kinh nghiệm viết content SEO hoặc từng chạy Google ads/ Fb ads. Tư duy phân tích, đánh giá số liệu tốt. Có kiến thức về thị trường app/game mobile là điểm cộng. Sáng tạo, nhiệt huyết, cởi mở, trách nhiệm và muốn chinh phục. Yêu thích chơi game, đam mê công nghệ. Có kinh nghiệm tham gia các dự án về công nghệ là điểm cộng.
Kỹ năng chuyên môn: [''Google Play'', ''Sensor tower'', ''App annie'', ''Google Console'', ''Firebase'']
Kỹ năng mềm: [''Sáng tạo'', ''Nhiệt huyết'', ''Cởi mở'', ''Trách nhiệm'', ''Tư duy phân tích'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Phụ cấp lương cứng 3,000,000 - 4,000,000 VND + Có thưởng'', ''Thưởng com, thu nhập up to 30,000,000 VND'', ''Thu nhập 13-16 tháng lương/năm, thưởng Lễ Tết'', ''Thưởng 4 - 6 tháng lương 1 năm với nhân sự Top đầu'', ''Được training trong chương trình Master app/games Lab'', ''Gửi xe miễn phí, tea-break hàng ngày'', ''Môi trường làm việc văn minh, công bằng, tinh thần Startup năng động'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (349, 2, 7, 'Nội dung tiếp thị thực tập', 'Viết content fanpage, TikTok, website theo lịch đã định và định hướng thương hiệu. Cập nhật xu hướng (trend) trên mạng xã hội và đề xuất nội dung phù hợp. Tham gia brainstorm ý tưởng cùng team marketing và học thuật. Hỗ trợ truyền thông cho các sự kiện nhỏ (webinar, workshop, hoạt động offline). Học cách phân tích hiệu suất bài viết, kênh truyền thông để cải thiện nội dung.', 'Sinh viên năm 3, 4 hoặc mới tốt nghiệp các ngành: Marketing, Truyền thông, Quản trị kinh doanh, … hoặc các ngành liên quan. Không yêu cầu kinh nghiệm, chỉ cần bạn chăm viết – ham học – chủ động. Có khả năng viết lách tốt, tư duy tích cực, yêu thích môi trường giáo dục. Biết dùng Canva, CapCut hoặc các app chỉnh sửa đơn giản là lợi thế. Có laptop cá nhân và làm việc offline tại chi nhánh.
Kỹ năng chuyên môn: [''Canva'', ''CapCut'']
Kỹ năng mềm: [''Viết lách tốt'', ''Tư duy tích cực'', ''Yêu thích môi trường giáo dục'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Cấp dấu mộc và số liệu thực tập'', ''Học miễn phí chứng chỉ TESOL 120 giờ nếu gắn bó lâu dài'', ''Được đào tạo 1:1 bởi Leader có kinh nghiệm'', ''Cơ hội trở thành nhân sự chính thức sau thời gian thực tập'', ''Làm việc trong môi trường trẻ trung, văn minh, giàu cảm hứng học tập & phát triển'', ''Tham gia các hoạt động nội bộ, teambuilding, kết nối với đội ngũ giảng viên TESOL'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (350, 3, 7, 'Thực Tập Sinh Content Marketing', 'Xây dựng nội dung, chăm sóc và quản trị nội dung cho các kênh truyền thông và trang mạng xã hội của dự án; Tham gia xây dựng, đóng góp ý tưởng và lập kế hoạch cho chiến lược Content Marketing của dự án; Phối hợp với bộ phận liên quan để sản xuất nội dung cho các sản phẩm, dịch vụ liên quan; Thực hiện các công việc khác theo sự phân công của Manager.', 'Sắp/ Đã tốt nghiệp chuyên ngành Marketing, Báo chí, PR, Quảng cáo, Truyền thông, Tiếp thị,...; Có niềm yêu thích, đam mê, định hướng rõ ràng, nghiêm túc với Marketing; Khả năng nghiên cứu, cập nhật nhanh các xu hướng nội dung mới, bắt trend trên mạng xã hội; Khả năng tư duy sáng tạo, kỹ năng viết nội dung, kịch bản và diễn đạt tốt; Có kỹ năng về Thiết kế và Edit Video; Nhanh nhẹn, sáng tạo, khả năng xử lý và ứng biến công việc tốt; Chủ động, kiên trì với mục tiêu, chịu được áp lực và đúng deadline; Tinh thần trách nhiệm cao, ham học hỏi, làm việc độc lập và phối hợp đội nhóm tốt.
Kỹ năng chuyên môn: [''Thiết kế và Edit Video'']
Kỹ năng mềm: [''Khả năng nghiên cứu'', ''Tư duy sáng tạo'', ''Kỹ năng viết nội dung'', ''Chịu được áp lực'', ''Tinh thần trách nhiệm cao'', ''Ham học hỏi'', ''Làm việc độc lập và phối hợp đội nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng, hà nội', 'Đà Nẵng', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30), Thứ 7 làm sáng cách tuần', '[''Trợ cấp lương trong quá trình thực tập'', ''Môi trường làm việc chuyên nghiệp, năng động'', ''Hỗ trợ định hướng phát triển'', ''Tham gia các hoạt động văn hóa của công ty'', ''Cơ hội trở thành Nhân viên chính thức ngay khi kết thúc thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (351, 7, 7, 'Thực Tập Sinh Marketing', 'Hỗ trợ trong việc sáng tạo nội dung (viết các bài viết social theo dạng ngắn gọn, súc tích, bắt trend). Hỗ trợ thực hiện quay dựng short video trên TikTok. Hỗ trợ thiết kế một số mẫu cơ bản (là một lợi thế cạnh tranh). Hỗ trợ các sự kiện internal & external (nếu có). Hỗ trợ một số công việc khác trong công việc (nếu có).', 'Sinh viên năm 3-4 Đại học, cao đẳng học ngành Marketing hoặc những ngành liên quan. Có sự yêu thích, đam mê trong lĩnh vực sáng tạo nội dung, truyền thông. Biết sử dụng các công cụ quay dựng và thiết kế cơ bản (Photoshop, Canva, Capcut, Figma...) là một lợi thế. Có khả năng viết thêm bài nội dung cho fanpage, website, blog hoặc các kênh truyền thông khác của công ty. Có kỹ năng dùng photoshop để thực hiện các layout đơn giản là một lợi thế. Chủ động, có tinh thần học hỏi, teamwork tốt và linh hoạt trong công việc.
Kỹ năng chuyên môn: [''Photoshop'', ''Canva'', ''Capcut'', ''Figma'']
Kỹ năng mềm: [''Chủ động'', ''Có tinh thần học hỏi'', ''Teamwork tốt'', ''Linh hoạt trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '0.1 - 1.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được hỗ trợ 1.000.000 VND/tháng khi làm đủ 100h/tháng'', ''Hỗ trợ về bài báo cáo, dấu mộc'', ''Được training chi tiết về công việc'', ''Cơ hội được tiếp xúc công việc thực tiễn'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (352, 8, 7, 'Thực Tập Sinh Truyền Thông - Marketing', '- Lên ý tưởng và triển khai các chiến dịch Marketing cho các sản phẩm Giáo dục của Công ty. - Chỉnh sửa thiết kế hình ảnh, poster,... - Xây dựng content cho website, landingpage, fanpage,... - Phối hợp cùng các phòng ban để tổ chức các hoạt động PR, Marketing,... - Thực hiện theo sự chỉ đạo công việc của cấp trên.', '- Sinh viên năm 3, 4 các ngành liên quan đến Marketing, truyền thông,... - Có laptop cá nhân. - Có kỹ năng sử dụng các công cụ thiết kế: Canva, CapCut, PhotoShop. - Sáng tạo video, xây dựng nội dung trên mạng xã hội. - Ưu tiên ứng viên làm được Full time.
Kỹ năng chuyên môn: [''Canva'', ''CapCut'', ''PhotoShop'']
Kỹ năng mềm: [''Sáng tạo video'', ''Xây dựng nội dung trên mạng xã hội'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Phụ cấp học việc'', ''Được hỗ trợ dấu thực tập'', ''Được đào tạo kiến thức, kỹ năng chuyên môn cần thiết'', ''Môi trường làm việc năng động, khuyến khích sáng tạo và phát triển bản thân'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (353, 9, 7, 'Thực Tập Sinh SEO', 'Nghiên cứu từ khóa bằng cách sử dụng một số công cụ hỗ trợ như Ahrefs hoặc Semrush để tìm kiếm và phân tích từ khóa phù hợp. Chỉnh sửa và tối ưu bài viết theo chuẩn SEO: Tiêu đề, meta description, heading, từ khóa, liên kết nội bộ… Xây dựng liên kết (Off-page SEO): Bằng cách thực hiện chiến lược xây dựng backlink qua việc đăng bài trên blog, diễn đàn và các website liên quan. Phân tích và theo dõi hiệu quả SEO. Làm các công việc liên quan theo sự chỉ đạo bộ phận quản lý.', 'Không yêu cầu kinh nghiệm. Đang là sinh viên năm 2, 3, 4 các chuyên ngành Marketing, truyền thông, báo chí hay các chuyên ngành liên quan. Biết sử dụng tin học văn phòng và có khả năng sử dụng các phần mềm thiết kế cơ bản: Canva, Powerpoint,… và các ứng dụng internet. Nhạy bén, năng động, sáng tạo, có tinh thần trách nhiệm với công việc. Hòa đồng, thân thiện với đồng nghiệp. Có laptop cá nhân. Thời gian thực tập: 06 tháng.
Kỹ năng chuyên môn: [''Sử dụng tin học văn phòng'', ''Sử dụng các phần mềm thiết kế cơ bản: Canva, Powerpoint'']
Kỹ năng mềm: [''Nhạy bén'', ''Năng động'', ''Sáng tạo'', ''Có tinh thần trách nhiệm với công việc'', ''Hòa đồng'', ''Thân thiện với đồng nghiệp'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)', '[''Làm việc trong môi trường chuyên nghiệp, năng động'', ''Được đào tạo thực tế về viết nội dung chuẩn SEO'', ''Học hỏi kinh nghiệm từ đội ngũ nhân viên tận tâm'', ''Nhận trợ cấp xứng đáng với nỗ lực và cống hiến'', ''Cấp giấy chứng nhận có dấu mộc của Công ty'', ''Cơ hội xét duyệt trở thành nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (354, 10, 7, 'Trực Page Tư Vấn Bán Hàng (Làm Online Theo Ca)', 'Công việc chi tiết: Tư vấn sản phẩm và thuyết phục chốt đơn cho khách. ( Các sản phầm về Thời Trang & Làm Đẹp “ Beauty ). Trả lời phản hồi của khách trên Fanpage. Chăm sóc data khách hàng sẵn có và data khách hàng mới (nếu có). Thực hiện các công việc khác theo yêu cầu phía cấp trên.', 'Nam/Nữ từ 21-32 tuổi, tốt nghiệp Trung cấp trở lên. Có kinh nghiệm trong lĩnh vực chăm sóc khách hàng, tư vấn chốt đơn từ 6 tháng đến 1 năm trở lên. Siêng năng chịu khó trong công việc. Có thể tham gia đào tạo tại công ty.
Kỹ năng chuyên môn: [''Chăm sóc khách hàng'', ''Tư vấn'']
Kỹ năng mềm: [''Siêng năng'', ''Chịu khó'']', 'FREELANCE', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'FIXED_PROJECT', 16000000.00, '8.0 - 16.0 triệu', 'Ca 1: 7H30 - 15H30, Ca 2: 15H30 - 22H30', '[''Thưởng doanh số'', ''Thưởng cuối năm'', ''Môi trường làm việc năng động'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (355, 2, 7, 'Thực tập tiếp thị kỹ thuật số', 'Hỗ trợ sản xuất nội dung media, phối hợp chụp ảnh sản phẩm, hoạt động nội bộ, sự kiện... phục vụ các kênh marketing. Hỗ trợ quay và dựng video: giới thiệu sản phẩm, hướng dẫn sử dụng... Hỗ trợ chỉnh sửa, biên tập hình ảnh/video đảm bảo đúng nhận diện thương hiệu. Tham gia hỗ trợ chạy quảng cáo Google Ads, Facebook Ads. Hỗ trợ quản lý nội dung và tương tác trên Zalo OA (Official Account). Tham gia xây dựng và phát triễn kênh tiktok. Được training kiến thức và thực hành trực tiếp cùng team theo từng giai đoạn.', 'Sinh viên năm 3, 4 hoặc mới tốt nghiệp chuyên ngành Thiết kế, Marketing, Truyền thông. Có đam mê với thiết kế, Digital Marketing, ham học hỏi và cầu tiến. Thành thạo Adobe Creative Suite: Photoshop, Illustrator, Canva. Portfolio thể hiện kỹ năng thiết kế và tính sáng tạo. Biết sử dụng các công cụ AI là một lợi thế. Có tinh thần làm việc nhóm, trách nhiệm và chủ động trong công việc.
Kỹ năng chuyên môn: [''Adobe Creative Suite'', ''Photoshop'', ''Illustrator'', ''Canva'']
Kỹ năng mềm: [''Tinh thần làm việc nhóm'', ''Trách nhiệm'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 11:30)', '[''Có hỗ trợ phụ cấp thực tập'', ''Có cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Môi trường làm việc năng động, hỗ trợ tối đa cho người mới'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (356, 3, 7, 'Marketing Intern', '• Biên soạn nội dung (content), hình ảnh, video clip phục vụ cho các website, các phương tiện social media... • Viết bài và đăng bài lên các trang mạng xã hội • Tổ chức các sự kiện hội thảo hàng tuần...', '• Sinh viên năm 4 chuyên ngành Marketing các trường ĐH, CĐ • Có kiến thức, tư duy marketing • Kỹ năng tìm kiếm thông tin trên mạng tốt • Có khả năng tự học hỏi • Năng động, sáng tạo • Có tinh thần trách nhiệm trong công việc
Kỹ năng chuyên môn: [''Kỹ năng tìm kiếm thông tin trên mạng'']
Kỹ năng mềm: [''Năng động'', ''Sáng tạo'', ''Có tinh thần trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Hỗ trợ chi phí thực tập'', ''Được đào tạo kỹ năng mềm, kỹ năng làm việc'', ''Được hướng dẫn cụ thể trong quá trình thực tập như một nhân viên fulltime'', ''Có cơ hội nhận vào làm chính thức sau khi kết thúc thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (357, 7, 7, 'Tối ưu hóa quảng cáo thực tập', 'Chịu trách nhiệm về kế hoạch chi tiết của phương tiện kỹ thuật số và thực hiện từng chiến dịch phù hợp với các mục tiêu kinh doanh bằng cách sử dụng các nền tảng quảng cáo (quảng cáo của Shopee, quảng cáo Lazada, CPA FB, Mua sắm GG với Shopee, ..). Chịu trách nhiệm về các tài liệu truyền thông được tối ưu hóa từ nội dung của chiến dịch. Chịu trách nhiệm theo dõi và báo cáo phương tiện kỹ thuật số (đo lường/phân tích sự hiểu biết/hành vi của đối tượng). Luôn cập nhật với các xu hướng mới nhất và thực tiễn tốt nhất trong tiếp thị truyền thông/thương mại điện tử/hiệu suất kỹ thuật số.', 'Creative in identifying target audiences and devising digital campaigns that engage consumers the most. Ability to adapt to new technologies and embrace AI-powered marketing tools. Strong analytical skills and data-driven thinking. 3rd/4th year student in university (relevant major is preferred). Hard working and eager to learn.
Kỹ năng chuyên môn: [''Digital media'', ''Ads platforms (Shopee Ads, Lazada Ads, FB CPAs, GG Shopping)'', ''Data analysis'']
Kỹ năng mềm: [''Creativity'', ''Adaptability'', ''Analytical skills'', ''Hard working'', ''Eager to learn'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Internship allowance support'', ''On-the-job training'', ''Professional working environment'', ''Opportunities for advancement'', ''Professional training and development'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (358, 8, 7, 'Thực Tập Sinh Content SEO (Có Phụ Cấp)', 'Tham gia xây dựng ý tưởng nội dung trong các dự án của công ty. Lên outline bài viết, viết bài theo ngày, tuần, tháng. Thực tập viết bài trên các dự án cụ thể được giao có sự hướng dẫn và kiểm tra. Triển khai viết bài chuẩn SEO. Viết bài tin tức, bài review sản phẩm. Viết bài tăng traffic, cập nhật hàng tuần/ tháng cho website.', '1. Sinh viên các trường Đại học chuyên ngành Marketing, Kinh tế, Truyền thông đối ngoại, Báo chí, Xã hội nhân văn hoặc các ngành khác có liên quan. 2. Có kỹ năng viết bài, định hướng và tổng hợp thông tin tốt. 3. Đã có kinh nghiệm viết bài dài khoảng 800 chữ trở lên. 4. Kỹ năng sử dụng Microsoft Office (Word, Excel, Powerpoint,...). 5. Có khả năng sáng tạo và viết nội dung lôi cuốn, thu hút. 6. Thích nghi, sẵn sàng học hỏi và cập nhật các công nghệ mới. 7. Thời gian thực tập tối thiểu 3 tháng. 8. Thời gian làm việc: 4 ngày/ tuần, ưu tiên full-time.
Kỹ năng chuyên môn: [''Kỹ năng viết bài'', ''Kỹ năng sử dụng Microsoft Office (Word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Định hướng và tổng hợp thông tin tốt'', ''Sáng tạo và viết nội dung lôi cuốn, thu hút'', ''Thích nghi, sẵn sàng học hỏi và cập nhật các công nghệ mới'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được hỗ trợ mộc và số liệu cho sinh viên làm báo cáo thực tập'', ''Cơ hội trở thành nhân viên chính thức sau khi kết thúc thực tập'', ''Nghỉ thứ 7, chủ nhật và các ngày lễ theo quy định'', ''Được tham gia các khóa đào tạo không giới hạn để nâng cao kỹ năng phục vụ cho công việc'', ''Làm việc trong môi trường chuyên nghiệp, năng động và phát huy được năng lực của bản thân'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (359, 9, 7, 'Trợ Lý/Hỗ Trợ Livestream (Biết Edit Video/Photo)', '- Hỗ Trợ Host Livestream chính trong việc bán hàng trên các nền tảng TikTok, Shopee - Hỗ trợ làm video phục vụ cho bán hàng, quay clip, chỉnh sửa hình ảnh sản phẩm - Hỗ trợ show và đọc tính năng sản phẩm - Hỗ trợ vận hành trong buổi phát sóng', '- Có kinh nghiệm trong mảng ứng dụng - Biết chỉnh sửa video, hình ảnh - Nhanh nhẹn, nhiệt tình - Trình độ vi tính cơ bản - Tác phong làm việc chuyên nghiệp, năng động
Kỹ năng chuyên môn: [''Chỉnh sửa video'', ''Chỉnh sửa hình ảnh'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Nhiệt tình'', ''Tác phong làm việc chuyên nghiệp'', ''Năng động'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '8.0 triệu', 'Buổi tối từ 18h đến 22h', '[''Có thưởng thêm theo hiệu quả live'', ''Được tự do sáng tạo'', ''Phát triển kinh nghiệm cá nhân'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (360, 10, 7, 'TTS Sáng Tạo Nội Dung/ Content Creative Intern', 'Phối hợp với đội ngũ marketing để lên ý tưởng và sáng tạo nội dung cho các chiến dịch truyền thông, quảng cáo. Viết bài PR, quảng cáo, bài đăng mạng xã hội cho các sản phẩm/dịch vụ của công ty và khách hàng. Sáng tạo nội dung cho các video ngắn trên đa nền tảng TikTok, Reels. Nghiên cứu xu hướng, phân tích đối thủ để đề xuất ý tưởng nội dung mới. Biên tập, chỉnh sửa nội dung trước khi xuất bản. Theo dõi, phân tích hiệu quả của các nội dung đã đăng tải.', 'Không yêu cầu kinh nghiệm, sinh viên năm cuối hoặc mới tốt nghiệp các ngành Marketing, Báo chí, Truyền thông (Ưu tiên CV có kèm Portfolio các dự án đã thực hiện). Có khả năng lập kế hoạch, sáng tạo nội dung đa dạng: bài viết, hình ảnh, video. Nắm bắt xu hướng truyền thông trên mạng xã hội, đặc biệt là TikTok. Kỹ năng viết lách tốt, văn phong đa dạng. Có khả năng nghiên cứu, tổng hợp thông tin nhanh chóng. Sáng tạo, nhiệt tình, chủ động trong công việc. Ưu tiên ứng viên có thể dựng và chỉnh sửa clip bằng CapCut hoặc các phần mềm khác (công ty sẽ cung cấp các dụng cụ quay dựng cần thiết). Có laptop cá nhân.
Kỹ năng chuyên môn: [''Content Marketing'', ''Content Creation'', ''TikTok'']
Kỹ năng mềm: [''Sáng tạo'', ''Nhiệt tình'', ''Chủ động trong công việc'', ''Kỹ năng viết lách tốt'', ''Nắm bắt xu hướng truyền thông'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 - 2.2 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 09:00 đến 12:00)', '[''Được đào tạo các kỹ năng chuyên môn'', ''Cơ hội học hỏi và làm việc trong môi trường chuyên nghiệp'', ''Được tham gia các dự án thực tế'', ''Có cơ hội được nhận vào làm chính thức'', ''Được hỗ trợ các chi phí đi lại, ăn trưa'', ''Tham gia các hoạt động team building'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (361, 2, 7, 'Thực Tập Sinh', 'Xây dựng nội dung, triển khai các chiến dịch truyền thông và hỗ trợ phát triển thương hiệu. Hỗ trợ tổ chức sự kiện, cuộc thi, chương trình trải nghiệm giáo dục công nghệ. Viết Content các bài đăng Page.', 'Sinh viên năm 3, 4 hoặc mới tốt nghiệp các chuyên ngành liên quan: Sư phạm, Công nghệ thông tin, Kỹ thuật điều khiển & tự động hóa, Cơ điện tử, Giáo dục STEM, Marketing, Truyền thông, Quản trị Kinh doanh, Nhân sự, Sự kiện, Dịch vụ khách hàng. Chủ động, trách nhiệm và có tinh thần học hỏi. Kỹ năng giao tiếp tốt, có khả năng làm việc nhóm hiệu quả. Quan tâm đến giáo dục công nghệ, đổi mới sáng tạo và phát triển bản thân.
Kỹ năng mềm: [''Chủ động'', ''Trách nhiệm'', ''Có tinh thần học hỏi'', ''Kỹ năng giao tiếp tốt'', ''Có khả năng làm việc nhóm hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Có trợ cấp dành cho intern (sẽ trao đổi khi phỏng vấn)'', ''Thưởng dự án hàng tháng'', ''Có cơ hội được giới thiệu vào các công ty, tập đoàn, doanh nghiệp, cơ sở giáo dục công lập, tư thục và các đối tác chiến lược của IRIS Academy.'', ''Được hướng dẫn bởi đội ngũ chuyên gia giàu kinh nghiệm.'', ''Trực tiếp tham gia vào các dự án thực tế, rèn luyện kỹ năng chuyên môn.'', ''Môi trường làm việc chuyên nghiệp, có lộ trình phát triển rõ ràng.'', ''Hỗ trợ chứng nhận thực tập, có cơ hội trở thành nhân sự chính thức.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (362, 3, 7, 'Thực Tập Sinh Marketing (Mạnh Thiết Kế)', 'Sáng tạo và thiết kế CV, portfolio, CV video. Xây dựng các thiết kế profile doanh nghiệp; đảm bảo sự chuyên nghiệp và sự độc đáo. Thực hiện thiết kế cho các ấn phẩm (tạp chí nội bộ doanh nghiệp,…). Phối hợp với các phòng ban để thiết kế sổ tay văn hóa, giúp nhân viên nhanh chóng hiểu và làm quen với giá các trị, văn hóa công ty. Thiết kế các background phục vụ cho các sự kiện, hội thảo hay các chiến dịch truyền thông, đảm bảo tính thẩm mỹ và đồng nhất với thương hiệu.', 'Sinh viên các trường Đại học, Cao đẳng chuyên ngành Marketing, Thiết kế đồ họa,… (Ưu tiên làm fulltime). Không yêu cầu kinh nghiệm. Biết sử dụng các phần mềm thiết kế đồ họa: Photoshop, canva, Illustrator, After Effect,…. Sáng tạo, ham học, làm việc nhóm tốt. Lưu ý: Ứng viên khi ứng tuyển vui lòng gửi kèm portfolio sản phẩm (nếu có).
Kỹ năng chuyên môn: [''Photoshop'', ''Canva'', ''Illustrator'', ''After Effect'']
Kỹ năng mềm: [''Sáng tạo'', ''Ham học'', ''Làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Môi trường làm việc trẻ trung, năng động'', ''Có cơ hội để học hỏi, tích lũy và phát triển năng lực cá nhân'', ''Các chính sách khác theo thỏa thuận'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (363, 7, 7, 'Nhân Viên Marketing', 'Bạn sẽ là một phần của team sáng tạo trẻ trung và năng động, với nhiệm vụ chính: 1. Xây dựng ý tưởng và quay dựng clip TikTok: Tham gia vào quá trình lên ý tưởng sáng tạo cho các nội dung trên TikTok, Phối hợp với team để xây dựng kịch bản, chuẩn bị bối cảnh và quay dựng video, Chỉnh sửa và hoàn thiện video cơ bản bằng capcut, Đề xuất các ý tưởng mới lạ, sáng tạo giúp kênh TikTok phát triển mạnh mẽ. 2. Cùng team xây dựng content cho kênh Social Media (Facebook, TikTok): Phối hợp cùng team Marketing để lập kế hoạch nội dung hàng tuần, hàng tháng cho các nền tảng Social Media, Sáng tạo nội dung đa dạng: hình ảnh, video, bài viết ngắn, minigame, sự kiện trực tuyến..., Tương tác với người dùng trên các nền tảng, phản hồi kịp thời và giải đáp thắc mắc nếu cần.', 'Có kỹ năng sử dụng capcut để chỉnh sửa video cơ bản, Biết thiết kế canva cơ bản, Ham học hỏi và phát triển bản thân, Thái độ làm việc tích cực, tử tế, Không yêu cầu kinh nghiệm
Kỹ năng chuyên môn: [''capcut'', ''canva'']
Kỹ năng mềm: [''ham học hỏi'', ''thái độ làm việc tích cực'', ''tử tế'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được hướng dẫn Marketing Online'', ''Được hướng dẫn thiết kế, quay video, chụp ảnh cơ bản'', ''Được hướng dẫn tổ chức sự kiện Offline'', ''Được tham gia đào tạo'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (364, 8, 7, 'Nhân Viên Livestream Partime', 'Lương cơ bản 3.000.000/75h livestream + hoa hồng (thu nhập trên 20.000.000/tháng). Livestream bán hàng trên kênh Tiktok. Học sản phẩm, tìm kiếm cách livestream phù hợp, giữa được cá tính riêng của bản thân. Hỗ trợ lên chương trình bán hàng hàng tháng. Hỗ trợ tìm kiếm quà tặng, update những quà tặng mới, quà tặng có tiềm năng cho team live. Báo cáo doanh thu mỗi tuần. Học tập cách livestream mới và cập nhật hàng tuần vào nhóm chung. Chọn ca live trong thời gian từ 7h00 - 24h00.', 'Có độ tuổi 18 – 35, chỉ cần 2,5h/ngày – 75h/tháng (có thể làm việc toàn thời gian nếu muốn). Khả năng giao tiếp và trình bày lưu loát, không ngại xuất hiện trước ống kính. Có đam mê với việc bán hàng. Chịu được áp lực công việc cùng những dịp sale trọng điểm trong tháng. Cơ hội việc làm chính thức sau thực tập.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng livestream'']
Kỹ năng mềm: [''Khả năng trình bày lưu loát'', ''Chịu được áp lực công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 20000000.00, '3.0 - 20.0 triệu', 'Thời gian linh hoạt', '[''Du lịch hàng năm'', ''Team building'', ''Thưởng hiệu quả làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (365, 9, 7, 'Thực Tập Sinh Content MKT', 'Phát triển và thực hiện chiến lược nội dung marketing toàn diện cho sản phẩm/dịch vụ của công ty; Sáng tạo nội dung và đăng bài trên các trang fanpage, website, Group của Công ty; Quản lý và cập nhật nội dung trên website và các nền tảng mạng xã hội; Phối hợp với các bộ phận khác trong công ty để thực hiện các chiến dịch marketing hiệu quả; Theo dõi và cập nhật các chỉ số đo lường hiệu quả của nội dung.', 'Không yêu cầu kinh nghiệm; Đam mê marketing và viết lách; Có khả năng viết và biên tập nội dung hấp dẫn; Tư duy ứng dụng AI vào; Có kỹ năng giao tiếp và làm việc nhóm tốt; Nhanh nhẹn, năng động, sáng tạo; Ham học hỏi, tư duy cầu tiến.
Kỹ năng chuyên môn: [''Viết nội dung'', ''Sử dụng các công cụ mạng xã hội'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Làm việc nhóm'', ''Năng động'', ''Sáng tạo'', ''Ham học hỏi'', ''Tư duy cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Thưởng hiệu quả công việc'', ''Cơ hội trở thành nhân viên chính thức'', ''Phụ cấp ăn trưa 35.000 VNĐ/ngày'', ''Môi trường làm việc năng động, chuyên nghiệp và thân thiện'', ''Được đào tạo và phát triển chuyên môn thường xuyên'', ''Cơ hội thăng tiến và phát triển sự nghiệp'', ''Các chế độ bảo hiểm theo quy định của pháp luật'', ''Chế độ nghỉ phép, nghỉ lễ theo quy định'', ''Tham gia các hoạt động team building, du lịch hàng năm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (366, 10, 7, 'Nhân Viên Livestream Tiktok', 'Trực tiếp giới thiệu sản phẩm đến khách hàng qua livestream, làm nổi bật các đặc điểm, công dụng, tính năng và giá cả cạnh tranh. Trình bày chi tiết các chương trình khuyến mãi đang áp dụng nhằm thu hút người xem và thúc đẩy doanh số. Tư vấn, giải đáp thắc mắc của khách hàng trong suốt quá trình livestream, bao gồm thông tin đặt hàng, chính sách hậu mãi và giới thiệu thương hiệu. Xây dựng và triển khai các kịch bản thu hút người xem, kêu gọi theo dõi và tăng tương tác trong mỗi buổi phát sóng. Thực hiện các công việc khác theo chỉ đạo của cấp trên.', 'Không yêu cầu giới tính, ngoại hình – chỉ cần bạn tự tin và truyền cảm trên livestream. Có kinh nghiệm livestream trên TikTok, am hiểu các quy định và thuật toán của nền tảng. Kỹ năng giao tiếp linh hoạt, tư vấn tốt và chốt đơn hiệu quả. Chủ động, chăm chỉ, nhiệt tình và luôn sẵn sàng học hỏi để nâng cao hiệu quả công việc.
Kỹ năng chuyên môn: [''Kỹ năng livestream trên TikTok'', ''Am hiểu các quy định và thuật toán của nền tảng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp linh hoạt'', ''Tư vấn tốt'', ''Chốt đơn hiệu quả'', ''Chủ động'', ''Chăm chỉ'', ''Nhiệt tình'', ''Sẵn sàng học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo các khung giờ cần tuyển', '[''Lương cơ bản 90.000đ/giờ + thưởng hiệu quả lên đến 1.000.000đ/buổi livestream'', ''Tổng thu nhập có thể lên đến 20 triệu đồng/tháng'', ''Cơ hội đào tạo bài bản'', ''Môi trường làm việc năng động'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (367, 2, 7, 'Marketing Intern', 'Thực hiện và thực hiện các kế hoạch tiếp thị và bán hàng, tạo ra khách hàng tiềm năng, thiết lập quan hệ đối tác, quản lý tài khoản truyền thông xã hội và hỗ trợ trong việc lập kế hoạch, thực hiện và tối ưu hóa các chiến dịch.', '3rd year or 4th year students who can work at least 3 full days per week, ideally in a relevant degree such as marketing, advertising, communications, business, entrepreneurship or similar. Good communication skill both in Speaking and Writing. Organizational skill: Keep the tasks delivered on time, budgets in check, detailed oriented. High flexibility and problem solving: manage the ad-hocs in a proper way which meets the standard of budget and timeline. Having fitness and beauty sense and creativity in work is a plus. Duration: 3 months.
Kỹ năng mềm: [''Good communication skill both in Speaking and Writing'', ''Organizational skill'', ''High flexibility and problem solving'']', 'PART_TIME', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.5 triệu', 'At least 3 full days per week', '[''Monthly allowance: VND 2,500,000 gross'', ''On the job training'', ''Free membership at California Fitness & Yoga'', ''Attend soft skill training courses organized by the company'', ''Attend company events & parties'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (368, 3, 7, 'Thực Tập Sinh Content Marketing', 'Lên ý tưởng và thực hiện nội dung video ngắn (TikTok, Reels…). Quay và chỉnh sửa video cơ bản phục vụ cho nội dung mạng xã hội. Tìm kiếm, liên hệ và phối hợp với các UGC/KOC để triển khai chiến dịch marketing. Hỗ trợ team xây dựng và phát triển nội dung trên các nền tảng MXH. Được đào tạo kỹ năng livestream, thực hiện livestream. Các công việc liên quan đến Marketing/ Truyền thông theo chỉ đạo của Quản lý.', 'Có hiểu biết, kinh nghiệm, và tư duy làm content marketing. Yêu thích công việc sáng tạo nội dung và cung cấp giá trị cho khách hàng. Am hiểu về SEO và tối ưu nội dung trên website. Có tinh thần trách nhiệm, làm việc độc lập và làm việc nhóm tốt.
Kỹ năng chuyên môn: [''SEO'', ''Content Marketing'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Sáng tạo'', ''Tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được sử dụng sản phẩm với giá ưu đãi riêng của nhân viên'', ''Môi trường làm việc trẻ trung, năng động, hòa đồng'', ''Được tham gia các chương trình đào tạo, nâng cao kỹ năng'', ''Hỗ trợ dấu mộc thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (369, 7, 7, 'Thực Tập Sinh Designer Graphic', '- Thiết kế đa nền tảng: Tạo banner, poster, slide, email marketing, landing page trình bày sản phẩm AI, automation cho team. - Phối hợp team Content tạo hình ảnh cho social media (Facebook, LinkedIn, Tiktok,...) - Cập nhật xu hướng: Nghiên cứu xu hướng design cho ngành công nghệ (glassmorphism, 3D elements, AI-art...), ứng dụng AI trong thiết kế (Midjourney, Adobe Firefly).', '- Ứng viên là sinh viên năm 3 - năm 4, sinh viên sắp ra trường muốn thực tập học hỏi trau dồi kinh nghiệm thực chiến Designer Graphic thuộc chuyên ngành Digital Marketing, Designer Graphic,... hoặc yêu thích sự sáng tạo, thiết kế,... - Thành thạo các công cụ: Figma, Adobe Photoshop/Illustrator, Canva,... - Tư duy chủ động, học nhanh, không chờ ai nhắc việc. Tinh thần khởi nghiệp, thích kiếm tiền và thử sức nhiều vai trò.
Kỹ năng chuyên môn: [''Figma'', ''Adobe Photoshop'', ''Adobe Illustrator'', ''Canva'']
Kỹ năng mềm: [''Tư duy chủ động'', ''Học nhanh'', ''Tinh thần khởi nghiệp'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Học từ thực chiến, làm dự án thật'', ''Mentorship từ Founder'', ''Huấn luyện chuyên sâu & Phát triển cá nhân'', ''Cơ hội tạo dòng tiền, thu nhập hấp dẫn'', ''Con đường rõ ràng đến vị trí chính thức'', ''Môi trường lý tưởng để phát triển'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (370, 8, 7, 'Thực Tập Sinh R&D AI Tool', '- Khảo sát & Review công cụ AI: Sử dụng, test công cụ AI/tuần (từ ChatGPT đến tool automation ít người biết) đánh giá tốc độ xử lý, độ chính xác, trải nghiệm người dùng. - Cập nhật công cụ AI mới nổi hàng tuần, thực hiện A/B testing hiệu quả giữa các nền tảng. - Viết review "có tâm" từ góc độ người dùng phổ thông & xây dựng tutorial dễ hiểu (text/video) cho nội bộ và khách hàng.', '- Ứng viên là sinh viên năm 3 - năm 4, sinh viên sắp ra trường muốn thực tập học hỏi trau dồi kinh nghiệm thuộc chuyên ngành IT/Kinh tế/Ngoại ngữ/Hệ thống thông tin/Digital Marketing,... có đam mê AI, thích viết blog/vlog công nghệ. - Đam mê công nghệ như game thủ: Thích "nghịch" công cụ mới, không ngại thử nghiệm, sẵn sàng học 3 tool/ngày nếu cần. - Có hứng thú với AI/automation - không cần chuyên sâu nhưng cần hiểu bản chất sản phẩm. - Tư duy chủ động, học nhanh, không chờ ai nhắc việc. Tinh thần khởi nghiệp, thích kiếm tiền và thử sức nhiều vai trò.
Kỹ năng chuyên môn: [''Lập Trình Python'', ''Kiến Thức Về Machine Learning'', ''Kiến Thức Về Deep Learning'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Khả năng giải quyết vấn đề'', ''Tư duy chủ động'', ''Học nhanh'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Học từ thực chiến, làm dự án thật'', ''Mentorship từ Founder'', ''Huấn luyện chuyên sâu & Phát triển cá nhân'', ''Cơ hội tạo dòng tiền, thu nhập hấp dẫn'', ''Con đường rõ ràng đến vị trí chính thức'', ''Môi trường lý tưởng để phát triển'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (371, 9, 7, 'Thực Tập Sinh Content Creator', '- Viết & sản xuất content "Chất": Sáng tạo nội dung (bài viết, infographic, script video) về AI/Automation dễ hiểu, cuốn hút cho các kênh Social. - Truyền cảm hứng bằng con chữ: Biến công nghệ phức tạp thành câu chuyện gần gũi, thú vị với người dùng phổ thông. - Nghiên cứu & Bắt trend: Update xu hướng AI toàn cầu, phân tích case study thực tế để tạo content "đúng trend, đúng insight". - Tối ưu hiệu suất công việc: Phối hợp team Design/Videographer triển khai content đa nền tảng (Facebook, Tiktok, Instagram).', '- Ứng viên là sinh viên năm 3 - năm 4, sinh viên sắp ra trường muốn thực tập học hỏi trau dồi kinh nghiệm thực chiến Content AI thuộc chuyên ngành Marketing, Báo chí truyền thông, Digital Marketing, Hệ thống thông tin, Thương mại điện tử,... hoặc yêu thích Content Marketing,... - Đam mê Công nghệ & Sáng tạo (AI, Automation, ChatGPT...) hoặc sẵn sàng học hỏi cực nhanh về lĩnh vực này. - Kỹ năng viết lách ưu tiên: Khả năng viết rõ ràng, mạch lạc, biến chủ đề khô khan thành nội dung hấp dẫn. - Tư duy chủ động, có khả năng tự học, nghiên cứu tốt. Tinh thần khởi nghiệp, thích kiếm tiền và thử sức nhiều vai trò.
Kỹ năng chuyên môn: [''Viết nội dung'', ''Sáng tạo nội dung'', ''Nghiên cứu từ khóa'', ''Quản lý mạng xã hội cơ bản'']
Kỹ năng mềm: [''Tư duy chủ động'', ''Khả năng tự học'', ''Nghiên cứu tốt'', ''Đam mê công nghệ'', ''Sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Học từ thực chiến, làm dự án thật'', ''Mentorship từ Founder'', ''Huấn luyện chuyên sâu & Phát triển cá nhân'', ''Cơ hội tạo dòng tiền, thu nhập hấp dẫn'', ''Con đường rõ ràng đến vị trí chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (372, 10, 7, 'Người tạo video bán thời gian', 'Tham gia vào các phiên quay video cho nội dung dạng ngắn và dạng dài trên quần short Tiktok, YouTube và YouTube. Phối hợp với các nhóm máy chủ và biên tập viên để sắp xếp lịch trình chụp, góc nội dung và phân phối. Hỗ trợ trong việc thực hiện các bản tóm tắt sáng tạo thông qua lập kế hoạch cảnh, đề xuất chiếu sáng và chỉ đạo các bức ảnh. Đóng góp ý tưởng trong các phiên động não cho các chiến lược, thiết lập và tham gia của khán giả. Đảm bảo rằng tất cả các bản thu âm đáp ứng kỳ vọng chất lượng trong việc đóng khung, rõ ràng và tính nhất quán của thương hiệu. Luôn cập nhật với các xu hướng video dạng ngắn và các hành vi nội dung dành riêng cho nền tảng.', 'Currently pursuing or holding a degree in Media, Film Production, Communications, or a related field. Proven interest or prior experience in videography, content creation, or media production. Proficient in handling camera equipment, basic lighting techniques, and framing/composition. Strong sense of visual storytelling with an eye for detail and aesthetics. Ability to work both independently and as part of a creative team in a fast-paced environment. Highly organized with a strong sense of responsibility and time management.
Kỹ năng chuyên môn: [''Handling camera equipment'', ''Basic lighting techniques'', ''Framing/composition'']
Kỹ năng mềm: [''Strong sense of visual storytelling'', ''Highly organized'', ''Strong sense of responsibility'', ''Time management'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Monday to Friday (from 09:00 to 18:00), Minimum 150 hours/month, scheduled flexibly based on the team’s production calendar.', '[''Opportunity to extend into long-term collaboration or full-time position based on performance.'', ''Guidance and training on work-related skills.'', ''Access to relevant training courses.'', ''Participation in company activities and team-building events.'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (373, 2, 7, 'Chủ nhà-Người đánh giá sản phẩm bán thời gian', 'Nội dung Hosting & VoiceOver: Các phân đoạn máy chủ trên máy chủ cho nội dung tập trung vào sản phẩm bao gồm: Tiktok, YouTube. Thực hiện giọng nói cho các video đào tạo và giáo dục sản phẩm, đảm bảo sự rõ ràng, chuyên nghiệp và liên kết với giai điệu thương hiệu. Kiến thức sản phẩm & phân phối đánh giá: Cung cấp các đánh giá sản phẩm rõ ràng, tự tin và thông tin, unboxing và so sánh. Địa chỉ Câu hỏi thường gặp (Câu hỏi thường gặp) từ khách hàng ở định dạng video. Nghiên cứu và hiểu các sản phẩm của Bosch để đảm bảo giao hàng chính xác và hấp dẫn. Phối hợp & Làm việc nhóm: Hợp tác với các nhà viết kịch bản, nhà quay phim và biên tập viên để đảm bảo luồng sản xuất liền mạch. Căn chỉnh chặt chẽ với nhóm nội dung về nhắn tin, giai điệu trực quan và mục tiêu của khán giả. Tham gia vào các cuộc họp giao ban trước và diễn tập khi cần thiết.', 'On-camera confidence with a natural, professional, and charismatic delivery style. Strong verbal communication skills in Vietnamese (English is a plus), able to explain product features clearly and engagingly. Prior experience in hosting videos, livestreams, or social media content is an advantage. Familiarity with consumer products, especially home appliances, is preferred. Ability to follow scripts while also improvising naturally when needed. Comfortable working under production timelines and adapting to different content formats. Interest in e-commerce, digital content, and customer education is a strong plus.
Kỹ năng chuyên môn: [''On-camera confidence'', ''Verbal communication skills'', ''Familiarity with consumer products'']
Kỹ năng mềm: [''Teamwork'', ''Adaptability'', ''Research skills'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Negotiable part-time allowance'', ''Opportunity for long-term collaboration'', ''Guidance and training'', ''Access to training courses'', ''Participation in company activities'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (374, 3, 7, 'Thực Tập Sinh Trợ Lý Dự Án', 'Thực tập sinh trợ lý cho Giám đốc - Dự án “HOTLIST 2025” của Travellive Media Group: Hỗ trợ, tham gia vào quá trình lên ý tưởng, xây dựng nội dung và vận hành dự án cùng đội ngũ tổ chức. Hỗ trợ soạn thảo tài liệu, proposal, nội dung truyền thông, làm plan, report,... Các công việc khác được phân công theo sắp xếp của quản lý.', 'Sinh viên năm 3, năm 4 hoặc vừa tốt nghiệp chuyên ngành Marketing, Truyền thông, Ngoại thương, Quản trị du lịch. Yêu cầu: Tiếng Anh tốt. Có sự quan tâm đến lĩnh vực truyền thông, quảng cáo, digital marketing, influencer marketing,... Kỹ năng giao tiếp tốt, năng động, tư duy logic, nhanh nhạy và chủ động trong công việc. Sử dụng thành thạo công cụ văn phòng, ưu tiên biết Canva hoặc các công cụ trình bày proposal. Có tinh thần học hỏi, cầu tiến, sẵn sàng làm việc trong môi trường năng động, deadline nhanh.
Kỹ năng chuyên môn: [''Sử dụng thành thạo công cụ văn phòng'', ''Biết Canva hoặc các công cụ trình bày proposal'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Năng động'', ''Tư duy logic'', ''Nhanh nhạy'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Có mức hỗ trợ thực tập và đóng dấu xác nhận thực tập của công ty'', ''Được training bài bản về kiến thức media & truyền thông đa kênh'', ''Làm việc với đội ngũ chuyên nghiệp trong lĩnh vực truyền thông – báo chí – hospitality'', ''Có cơ hội trở thành nhân viên chính thức hoặc hỗ trợ freelance sau kỳ thực tập'', ''Môi trường trẻ trung, sáng tạo, nhiều cơ hội phát triển bản thân'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (375, 7, 7, 'Livestream parttime (sàn tm đt)', 'Lên kịch bản livestream theo từng phiên live đảm bảo hấp dẫn, thu hút. Giới thiệu về sản phẩm cho khách hàng: đặc điểm nổi bật, giá thành, công dụng, tính năng,… Giới thiệu về chương trình khuyến mãi trên livestream. Tư vấn, giải đáp các thắc mắc của khách hàng trên livestream liên quan tới đặt hàng, chính sách hậu mãi và Giới thiệu về thương hiệu. Xây dựng các kịch bản kêu gọi khách hàng theo dõi và tương tác với livestream. Thực hiện một số công việc khác theo sự phân công của cấp trên.', 'Không yêu cầu giới tính, ngoại hình sáng. Ca làm việc linh hoạt theo sự phân công từ TBP Các khung giờ cần tuyển: 6h-9h, 9h-11h, 14h-17h, 18h-21h, 21h-23h. Làm được tối thiểu 1 phiên/ngày. Ưu tiên có thể làm 2 phiên/ngày. Ứng viên có từ 6 tháng tại vị trí livestream. Kỹ năng tư vấn tiếp và chốt sale tốt. Kỹ năng giao tiếp. Nhiệt tình, năng nổ, chăm chỉ và chủ động trong công việc.
Kỹ năng chuyên môn: [''Kỹ năng tư vấn'', ''Kỹ năng giao tiếp'', ''Kỹ năng chốt sale'']
Kỹ năng mềm: [''Nhiệt tình'', ''Năng nổ'', ''Chăm chỉ'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo sự phân công từ TBP', '[''Cơ hội tham gia nhiều khóa đào tạo nâng cao chuyên môn nghiệp vụ'', ''Có lộ trình thăng tiến thành nhân viên chính thức'', ''Tham gia các hoạt động gắn kết, phát triển văn hóa doanh nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (376, 8, 7, 'Thực tập sinh đối tác MCN Tiktok', '• Tìm kiếm, tiếp cận và mời các Creators (nhà sáng tạo) tiềm năng trên TikTok tham gia hệ thống MCN. • Đánh giá hiệu suất và tiềm năng của nhà sáng tạo dựa trên dữ liệu, xu hướng và chỉ số tăng trưởng. • Đàm phán hợp tác, ký kết thỏa thuận và onboard Creators vào hệ thống MCN. • Hỗ trợ các Creator trong MCN, Cập nhật thông tin cho nhà sáng tạo về các chính sách, công cụ và xu hướng mới từ TikTok. • Theo dõi và báo cáo Performance của các Creators trong MCN.', '• Sinh viên hoặc mới tốt nghiệp các ngành Truyền thông, Marketing, Báo chí, Ngôn ngữ, hoặc các ngành liên quan. • Có đam mê với mạng xã hội, sáng tạo nội dung và nắm bắt trend tốt. • Kỹ năng giao tiếp tốt, hướng ngoại.
Kỹ năng chuyên môn: [''Social Media Marketing'', ''Communication Skills'', ''Collaboration Skills'', ''Project Management (basic)'', ''Tiktok Knowledge'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Hướng ngoại'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Môi trường làm việc trẻ trung, năng động, nhiều cơ hội học hỏi'', ''Được đào tạo và hướng dẫn bởi đội ngũ giàu kinh nghiệm'', ''Cơ hội trở thành nhân viên chính thức nếu thể hiện tốt'', ''Được hỗ trợ, kết nối các mối quan hệ phục vụ cho công việc tương lai'', ''Được hướng dẫn và đào tạo trong suốt thời gian thực tập'', ''Được tham gia các event/workshop của TikTok Việt Nam'', ''Hỗ trợ dấu mộc thực tập (nếu Trường yêu cầu)'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (377, 9, 7, 'Nội dung thực tập Mkt', 'Phát triển và thực hiện các chiến lược xây dựng thương hiệu của công ty; Lên ý tưởng content và đăng bài truyền thông trên các trang fanpage; Xây dựng và quản lý nội dung truyền thông trên các kênh Online; Tham gia lập kế hoạch và tổ chức các sự kiện truyền thông, quảng bá thương hiệu; Giám sát và đánh giá hiệu quả của các chiến dịch truyền thông; Báo cáo định kỳ về tình hình thương hiệu và các hoạt động truyền thông; Đề xuất các ý tưởng sáng tạo để nâng cao nhận diện thương hiệu; Đảm bảo thông điệp truyền thông nhất quán và phù hợp với định hướng của công ty.', 'Không yêu cầu kinh nghiệm; Ưu tiên sinh viên năm cuối các trường chuyên ngành Marketing, Truyền thông, Quan hệ công chúng hoặc các ngành liên quan; Có thế mạnh về sáng tạo nội dung, yêu thích công việc sáng tạo nội dung; Có tinh thần trách nhiệm cao, năng động, sáng tạo; Kỹ năng sử dụng các công cụ hỗ trợ cho công việc content MKT; Am hiểu về thị trường thương mại điện tử và giáo dục là một lợi thế.
Kỹ năng chuyên môn: [''Kỹ năng sử dụng các công cụ hỗ trợ cho công việc content MKT'']
Kỹ năng mềm: [''Sáng tạo'', ''Tinh thần trách nhiệm cao'', ''Năng động'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), 2 thứ 7 trong tháng', '[''Phụ cấp cơm trưa 35.000/ngày'', ''Có lương thưởng khi hiệu suất công việc tốt'', ''Cơ hội trở thành nhân viên chính thức'', ''Được đào tạo và nâng cao kỹ năng, chuyên môn'', ''Môi trường làm việc trẻ, năng động'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (378, 10, 7, 'Tài khoản tiếp thị thực tập', 'Quản lý, phát triển & mở rộng mạng lưới quan hệ với khách hàng tiềm năng; Nhận brief, liên hệ, trao đổi với khách hàng có nhu cầu triển khai dự án; Hỗ trợ xây dựng Proposal/ Plan cho dự án; Tham gia pitching và theo dõi tiến độ dự án cùng team liên quan; Thực hiện các nghiệp vụ: Báo giá, đàm phán, chốt hợp đồng & chăm sóc khách hàng; Kết nối khách hàng với team nội bộ (Creative, Design, Digital) để thúc đẩy thực thi kế hoạch đúng yêu cầu và đảm bảo deadline các hạng mục công việc; Chăm sóc, duy trì mối quan hệ với khách hàng, quản lý danh sách khách hàng tiềm năng; Thực hiện các công việc khác theo yêu cầu của Manager.', 'Sắp/ Đã tốt nghiệp chuyên ngành Kinh tế, Quản trị Kinh doanh, Marketing, Truyền thông,...; Có niềm yêu thích, đam mê, định hướng rõ ràng, nghiêm túc với Marketing; Tiếng Anh mức độ khá trở lên; Kỹ năng giao tiếp, đàm phán, thuyết phục, bán hàng, ngoại hình ưa nhìn. Thích học hỏi cái mới, không ngại bị từ chối; Quản lý thời gian và phân bổ công việc với khối lượng lớn; Vui vẻ, hoà đồng và thân thiện, tinh thần cầu tiến trong công việc; Chủ động, ham học hỏi, tìm hiểu kiến thức mới liên quan về Truyền thông, Marketing; Tư duy linh hoạt, nhạy bén với thị trường; Có kinh nghiệm ở vị trí liên quan đến công việc kinh doanh, chăm sóc khách hàng là một lợi thế; Có kinh nghiệm làm việc tại đơn vị Truyền thông/ Marketing/ Agency là một lợi thế.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Đàm phán'', ''Thuyết phục'', ''Bán hàng'', ''Quản lý thời gian'', ''Phân bổ công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Trợ cấp lương trong quá trình thực tập'', ''Môi trường làm việc chuyên nghiệp, năng động'', ''Hỗ trợ định hướng phát triển'', ''Tham gia các hoạt động văn hóa của công ty'', ''Được đào tạo theo mô hình training on job'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (379, 2, 7, 'Project Management Intern', 'Hỗ trợ các anh chị team Account trong việc triển khai các dự án của công ty thông qua các tasks như: kiểm tra deadline của team nội bộ, báo cáo tình hình dự án, quản lý và đảm bảo chất lượng dự án. Tham gia và thực hành quản lý các dự án về Technical như: Website, Ecommerce, POS, Loyalty, Automation Marketing, AI, CRM, ERP, ... Chuẩn bị các giấy tờ, hồ sơ của dự án cho team Account. Hỗ trợ tư vấn, gửi báo giá, proposal cho khách hàng. Thực hiện báo cáo theo yêu cầu của Account Manager. Thực hiện các công việc khác theo sự phân công của Account Manager.', 'Sinh viên hoặc đã tốt nghiệp các ngành CNTT, Hệ thống thông tin, Thương mại điện tử, Marketing, Tài chính, Quản trị kinh doanh. Không yêu cầu kinh nghiệm. Có sự quan tâm nhất định đối với ngành Công nghệ - Kỹ thuật. Có kinh nghiệm quản lý dự án Công nghệ là lợi thế. Thành thạo tin học văn phòng (Word, Excel, Powerpoint). Kỹ năng giao tiếp tốt. Khả năng lãnh đạo đội nhóm. Yêu thích quản lý, sắp xếp nhân sự, kiểm soát và đánh giá hiệu quả công việc. Tỉ mỉ, chỉnh chu. Lắng nghe tốt. Chủ động học hỏi. Tích cực với áp lực công việc.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng lãnh đạo đội nhóm'', ''Tỉ mỉ, chỉnh chu'', ''Lắng nghe tốt'', ''Chủ động học hỏi'', ''Tích cực với áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Có cơ hội được đào tạo toàn diện về Công nghệ số và Quản trị truyền thông kỹ thuật số.'', ''Có cơ hội tiếp cận với phương pháp và quy trình quản trị dự án truyền thông kỹ thuật số một cách có tổ chức và hiện đại.'', ''Cơ hội phát triển kỹ năng mềm trong công việc.'', ''Làm việc trong môi trường thân thiện với nhiều công nghệ mới.'', ''Hỗ trợ hoàn thành báo cáo và con dấu thực tập.'', ''Có cơ hội tiếp nhận lộ trình phát triển trở thành nhân viên chính thức của công ty.'', ''Cơ hội tham gia vào các hoạt động Teambuilding, YEP.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (380, 3, 7, 'Thực Tập Sinh Booking KOL/KOC', '- Phụ trách liên hệ và xây dựng mối quan hệ với các TikToker tại Việt Nam theo danh mục chỉ định; - Hỗ trợ quản lý danh sách KOLs, cập nhật database, theo dõi tiến độ booking. - Hỗ trợ team triển khai các chiến dịch influencer marketing.', '- Có thể làm việc toàn thời gian, thực tập tối thiểu 2 tháng; - Tinh thần học hỏi cao, có trách nhiệm và ý thức làm việc nhóm tốt; - Ưu tiên các bạn sinh viên năm cuối ngành truyền thông, marketing, ngoại ngữ...
Kỹ năng mềm: [''Tinh thần học hỏi cao'', ''Có trách nhiệm'', ''Ý thức làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Đào tạo bài bản'', ''Cơ hội học hỏi thực tế ngành MCN & influencer marketing'', ''Có hoa hồng doanh số nếu đạt KPI'', ''Cơ hội trở thành nhân viên chính thức sau khi kết thúc thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (381, 7, 7, 'Trưởng Nhóm Marketing Affiliate', 'Triển khai quảng cáo, marketing cho các sản phẩm giáo dục. Xây kênh Marketing Google, Facebook, Youtube, Tiktok. Seeding trên các group, forum. Tư vấn thông tin cho khách hàng. Có thể làm việc online, remote.', 'Nam/Nữ, Tuổi từ 18 - 35 tuổi. Thành thạo AI trí tuệ nhân tạo. Thành thạo Canva / Capcut. Biết xây dựng kịch bản, ý tưởng marketing. Sử dụng thành thạo các công cụ marketing Online. Biết thiết kế design / video marketing. Thành thạo Facebook, Tiktok, Youtube , Google ads. Thành thạo chiến thuật marketing du kích. Có khả năng xây dựng team CTV Affiliate.
Kỹ năng chuyên môn: [''AI trí tuệ nhân tạo'', ''Canva'', ''Capcut'', ''Google Ads'', ''Facebook Ads'', ''Tiktok'', ''Youtube'']
Kỹ năng mềm: [''Xây dựng kịch bản'', ''Ý tưởng marketing'', ''Thiết kế design'', ''Video marketing'', ''Xây dựng team CTV Affiliate'']', 'PART_TIME', 'REMOTE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 25000000.00, '10.0 - 25.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Thưởng KPI 20 - 100 triệu / tháng theo hiệu quả công việc'', ''Thưởng lễ, tết, sinh nhật'', ''Du lịch thường xuyên'', ''Bảo hiểm y tế'', ''Thưởng tết năm từ 20 - 50 triệu'', ''Cước điện thoại'', ''Điện thoại làm việc'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (382, 8, 7, 'Thực Tập Sinh Content Creator', 'Sáng tạo nội dung cho fanpage, website, TikTok, Instagram, v.v. Viết caption, kịch bản video ngắn, nội dung viral, bài blog… Hỗ trợ lên ý tưởng, xây dựng kịch bản cho các chiến dịch truyền thông. Phối hợp cùng team thiết kế, media để đảm bảo nội dung đồng bộ và hiệu quả. Cập nhật xu hướng mới, chủ động đề xuất các ý tưởng sáng tạo.', 'Là sinh viên năm 3, 4 hoặc mới tốt nghiệp các ngành Truyền thông, Marketing, Báo chí, Ngôn ngữ, hoặc liên quan. Có khả năng viết tốt, ngôn từ linh hoạt, tư duy sáng tạo. Yêu thích và thường xuyên theo dõi các nền tảng mạng xã hội. Chủ động, cầu tiến, có tinh thần học hỏi. Ưu tiên ứng viên có kinh nghiệm viết content cá nhân, từng làm CTV viết bài.
Kỹ năng chuyên môn: [''Viết nội dung'', ''Sáng tạo nội dung'', ''Sử dụng các nền tảng mạng xã hội'']
Kỹ năng mềm: [''Khả năng viết tốt'', ''Ngôn từ linh hoạt'', ''Tư duy sáng tạo'', ''Chủ động'', ''Cầu tiến'', ''Có tinh thần học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 3000000.00, '1.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Trợ cấp thực tập'', ''Được đào tạo bài bản về content marketing'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Môi trường làm việc trẻ trung, năng động'', ''Mentor hỗ trợ tận tâm'', ''Tham gia các hoạt động team, sự kiện nội bộ thú vị'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (383, 9, 7, 'Thực Tập Sinh Marketing', 'Hỗ trợ lên ý tưởng, xây dựng nội dung quảng bá sản phẩm trên các nền tảng Facebook, Zalo, TikTok, Website,... Hỗ trợ chạy quảng cáo Facebook Ads, Google Ads và tối ưu hóa hiệu quả chiến dịch. Tham gia nghiên cứu thị trường, phân tích khách hàng tiềm năng. Hỗ trợ tổ chức các sự kiện, hội thảo bán hàng, livestream. Thiết kế hình ảnh, video cơ bản (nếu có kỹ năng). Các công việc khác theo sự phân công của quản lý.', 'Sinh viên năm 3, năm 4 hoặc mới ra trường chuyên ngành Marketing, Kinh doanh, Truyền thông hoặc các ngành liên quan. Có kỹ năng viết content, sáng tạo nội dung. Ham học hỏi, chăm chỉ, chủ động trong công việc.
Kỹ năng chuyên môn: [''Kỹ năng viết content'', ''Sáng tạo nội dung'']
Kỹ năng mềm: [''Ham học hỏi'', ''Chăm chỉ'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Được đào tạo kiến thức marketing thực chiến trong lĩnh vực bất động sản.'', ''Hỗ trợ phụ cấp thực tập 3-5tr/tháng.'', ''Thưởng nếu đủ kpi.'', ''Có cơ hội trở thành nhân viên chính thức nếu thể hiện tốt.'', ''Môi trường làm việc năng động, trẻ trung, có cơ hội phát triển kỹ năng chuyên môn.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (384, 10, 7, 'Thực Tập Sinh Phòng Kinh Doanh', 'Hỗ trợ đội ngũ kinh doanh trong việc tìm kiếm, tiếp cận và chăm sóc khách hàng tiềm năng. Tham gia tư vấn và giới thiệu sản phẩm bất động sản của công ty đến khách hàng. Hỗ trợ tổ chức các sự kiện mở bán, hội thảo, roadshow do công ty tổ chức. Cập nhật và quản lý dữ liệu khách hàng trên hệ thống CRM. Tham gia các buổi đào tạo nội bộ để nâng cao kiến thức về bất động sản, kỹ năng bán hàng. Thực hiện các công việc khác theo sự phân công của quản lý.', 'Là sinh viên năm 3 hoặc năm 4 mới tốt nghiệp các ngành: Quản trị Kinh doanh, Marketing, Quản trị Văn phòng, Quản trị Thông tin hoặc các ngành gần hoặc có đam mê kinh doanh, học hỏi về Bất động sản. Muốn trau dồi kĩ năng giao tiếp, tư vấn, gặp gỡ nhiều người. Ưu tiên thực tập fulltime (cơ hội lên thử việc nhanh hơn sau 1-2 tháng). Vẫn chấp nhận Parttime theo lịch học cá nhân (thực tập tối đa 3 tháng). Vui vẻ, chủ động, nhiệt tình, chịu khó, có trách nhiệm với công việc được giao. Biết sử dụng tin học văn phòng cơ bản. Có laptop và phương tiện cá nhân là một lợi thế.
Kỹ năng chuyên môn: [''Tin học văn phòng cơ bản'']
Kỹ năng mềm: [''Giao tiếp'', ''Chủ động'', ''Nhiệt tình'', ''Chịu khó'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 7000000.00, '5.0 - 7.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Có phụ cấp thực tập'', ''Không áp doanh số (KPI)'', ''Được đào tạo từ đầu'', ''Hỗ trợ xác nhận thực tập, dấu mộc, thư giới thiệu nếu cần'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (385, 2, 7, 'Thực Tập Sinh Content Marketing', 'Tư vấn, giới thiệu các sản phẩm nội thất gia đình, nội thất trẻ em (giường tầng, bàn, tủ, kệ, …) đến khách hàng. Quản lý, xây dựng content cho các fanpage, hội nhóm kênh mạng xã hội của công ty. Làm cầu nối giữa khách hàng và chủ nhà. Hỗ trợ khách hàng trong quá trình giao dịch, từ tư vấn cho đến ký kết hợp đồng. Phối hợp với các bộ phận khác trong công ty để đảm bảo quá trình cho thuê diễn ra suôn sẻ.', '• Không yêu cầu kinh nghiệm làm việc trước đó (sẽ được đào tạo) • Chăm chỉ, siêng năng • Chủ động trong công việc, có tinh thần cầu tiến.
Kỹ năng chuyên môn: [''Microsoft Office (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Quản lý thời gian'', ''Giao tiếp'', ''Kỹ năng thuyết trình'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Hỗ trợ xác nhận và cung cấp mộc thực tập tại công ty'', ''Môi trường làm việc chuyên nghiệp, có cơ hội phát triển'', ''Có cơ hội được đề bạt thành nhân viên chính thức sau khi kết thúc thời gian thực tập'', ''Team building'', ''Thưởng hiệu quả làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (386, 3, 7, 'Thực Tập Sinh Marketing', 'Trực tiếp lên kế hoạch clip phát triển kênh Tiktok. Hỗ trợ edit video và seeding tăng follow kênh. Các công việc khác theo phân công từ cấp trên.', 'Đang theo học các ngành liên quan tiếng Trung hoặc Marketing. Yêu thích kênh Tiktok, tự tin lên hình và có khả năng diễn xuất. Tư duy sáng tạo, bắt trend tốt. Thái độ chân thành, cầu thị, tích cực, nhiệt huyết với công việc.
Kỹ năng mềm: [''Yêu thích kênh Tiktok'', ''Tự tin lên hình'', ''Có khả năng diễn xuất'', ''Tư duy sáng tạo'', ''Bắt trend tốt'', ''Thái độ chân thành'', ''Cầu thị'', ''Tích cực'', ''Nhiệt huyết với công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm việc theo ca, Ca sáng: 8:30 - 12:00, Ca chiều: 13:30 - 21:00', '[''Được tham gia các chương trình đào tạo phát triển năng lực và kĩ năng chuyên môn'', ''Được hỗ trợ chi phí ăn trưa, đi lại'', ''Được xét duyệt nhân viên chính thức sau khi ứng viên tốt nghiệp'', ''Hỗ trợ dấu mộc thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (387, 7, 7, 'Thực Tập Sinh Marketing', 'Xây dựng nội dung và kịch bản cho các nền tảng social media: Facebook, Tiktok, Website. Hỗ trợ công tác media trong các sự kiện. Chỉnh sửa hình ảnh, video bằng các phần mềm cơ bản như Capcut, Canva. Tham gia các hoạt động brainstorm chiến dịch mới cùng team Marketing. Các công việc khác theo yêu cầu của quản lý trực tiếp.', 'Là sinh viên năm cuối chuyên ngành Marketing, ưu tiên có thể thực tập fulltime. Năng động, nhiệt tình. Nắm bắt xu hướng nhanh, cập nhật các tin tức xã hội thường xuyên. Thích sử dụng mạng xã hội. Biết tiếng Anh, tiếng Đức là một lợi thế.
Kỹ năng chuyên môn: [''Sử dụng phần mềm chỉnh sửa hình ảnh, video như Capcut, Canva'']
Kỹ năng mềm: [''Năng động'', ''Nhiệt tình'', ''Nắm bắt xu hướng nhanh'', ''Thích sử dụng mạng xã hội'']', 'PART_TIME', 'ONSITE', 'đại kim, hoàng mai', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:30 đến 12:00)', '[''Nhận hỗ trợ thực tập + chi phí gửi xe'', ''Nhận thưởng dựa theo thành tích công việc'', ''Được học hỏi các kĩ năng về marketing, media, bán hàng'', ''Môi trường năng động, trẻ trung'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (388, 8, 7, 'Video Editor Intern', 'Chụp hình sản phẩm. Dựng video sản phẩm, video hoạt động, cắt ghép các clip source, TikTok, shopee... chỉnh sửa, tạo hiệu ứng để hoàn thành các video hoàn chỉnh theo kế hoạch, yêu cầu, định hướng của Khách hàng và nội bộ. Biên tập, chỉnh sửa, cắt ghép hình ảnh, âm thanh thành video hoàn chỉnh; Đảm bảo thời gian của từng hạng mục theo kế hoạch. Hỗ trợ chụp và chỉnh sửa ảnh cho sự kiện, hậu trường, hoặc nội dung mạng xã hội khi cần. Vận hành các thiết bị quay cơ bản (camera, gimbal, micro, đèn...) cho các buổi quay trong studio hoặc ngoại cảnh. Hỗ trợ chuẩn bị bối cảnh quay: ánh sáng, khung hình, âm thanh và chuyển động camera. Sắp xếp, quản lý file video, duy trì hệ thống sao lưu. Hỗ trợ cập nhật, sáng tạo thêm những clip, trending video theo những dự án quảng bá team đang thực hiện. Thực hiện các công việc liên quan theo sự hướng dẫn của Mentor.', 'Sử dụng thành thạo ít nhất một phần mềm dựng video (ví dụ: Adobe Premiere, CapCut, Final Cut, Davinci Resolve...). Sinh viên năm 3, năm 4 các trường Đại học chuyên ngành các ngành liên quan. Là người chăm chỉ, sáng tạo, có tinh thần trách nhiệm và ham học hỏi để phát triển kỹ năng. Có tư duy về bố cục, hình ảnh và thẩm mỹ tốt. Ưu tiên ứng viên: Đã từng hỗ trợ hoặc trực tiếp sản xuất các video về marketing hoặc có Portfolio sản phẩm đã thực hiện.
Kỹ năng chuyên môn: [''Adobe Premiere'', ''CapCut'', ''Final Cut'', ''Davinci Resolve'']
Kỹ năng mềm: [''Chăm chỉ'', ''Sáng tạo'', ''Tinh thần trách nhiệm'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 18:30), Thứ 7 (9h30 - 12h, 13h - 18h30)', '[''Hỗ trợ lương thực tập'', ''Đào tạo nâng cao chuyên môn MKT'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (389, 9, 7, 'Thực Tập Sinh Marketing', 'Đăng tin, chạy QC, tìm kiếm data khách hàng. Hỗ trợ phòng Kinh Doanh quay/dựng clip về sản phẩm. (Sẽ được đào tạo). Quản lí fanpage FB, Tiktok, IG…', 'Sinh viên năm 2-4, ưu tiên các ngành Kinh Doanh, Marketing.. Lên đủ 4 buổi sáng/ tuần (từ thứ 2- thứ 7, được linh hoạt thời gian theo lịch học) Siêng năng, chịu khó.
Kỹ năng mềm: [''Siêng năng'', ''Chịu khó'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 14:00)', '[''Được training bài bản'', ''Hỗ trợ dấu mộc báo cáo sau 45 ngày'', ''Có hỗ trợ phụ cấp tùy vị trí'', ''Cơ hội trở thành nhân viên chính thức sau thực tập'', ''Được tham gia các sự kiện, hoạt động chung như nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (390, 10, 7, 'Nhân Viên Content Creator/VJ/Talents Kênh Tiktok', 'Sáng tạo nội dung cho kênh Tiktok, lựa chọn 1 trong 3 chủ đề: Giải trí (showbiz, idol), làm đẹp (skincare và makeup), ăn uống. Lên kịch bản, quay, lên hình, phối hợp edit nội dung ngắn hấp dẫn. Tối ưu hóa nội dung để video lên xu hướng (hiện tại kênh đã có concept win, chỉ cần tiếp tục triển khai). Làm việc cùng team video để đảm bảo nội dung chất lượng + đúng deadline.', 'Nam/nữ độ tuổi từ 18-28t (đảm bảo lên công ty tối thiểu 3 buổi/tuần, lựa chọn tùy theo lịch học).
Kỹ năng chuyên môn: [''Biết làm content Tiktok'', ''Am hiểu xây kênh và nắm chắc thuật toán của nền tảng'', ''Biết viết content thu hút, caption chất, hashtag chuẩn'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Không ngại lên hình: tự tin, giọng nói rõ ràng, nhiều năng lượng'', ''Biết teamwork - làm việc tốt với quay dựng để ra video chỉn chu'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Bảo hiểm xã hội'', ''Team building'', ''Du lịch hàng năm'', ''Phụ cấp thâm niên'', ''Thưởng tháng 13'', ''Thưởng hiệu quả làm việc'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (391, 2, 7, 'Thực Tập Sinh Content Marketing', '- Tham gia xây dựng ý tưởng nội dung trong các dự án truyền thông/ marketing - Lên kế hoạch bài viết theo ngày/tuần/tháng - Thực tập viết bài PR trực tiếp, gián tiếp - Thực tập viết bài chuẩn SEO trên website/các trang mạng xã hội - Thực tập lên các ý tưởng sáng tạo nhằm thu hút tương tác của người dùng - Thực tập viết nội dung bài quảng cáo trên Facebook', '- Đang theo học đại học chuyên ngành marketing, kinh tế, truyền thông đối ngoại, báo chí, xã hội nhân văn, hoặc các ngành khác có liên quan - Có kỹ năng viết bài, định hướng và tổng hợp thông tin tốt - Thành thạo Internet, tin học văn phòng - Thích nghi, sẵn sàng học hỏi và cập nhật các công nghệ mới, xu hướng trong lĩnh vực social media - Nhạy bén với xu thế, nhạy cảm với tâm lý khách hàng - Sáng tạo, chăm chỉ, chịu khó, tinh thần trách nhiệm cao
Kỹ năng chuyên môn: [''Kỹ năng viết bài'', ''Thành thạo Internet'', ''Tin học văn phòng'']
Kỹ năng mềm: [''Thích nghi'', ''Sẵn sàng học hỏi'', ''Nhạy bén với xu thế'', ''Sáng tạo'', ''Chăm chỉ'', ''Chịu khó'', ''Tinh thần trách nhiệm cao'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thời gian làm việc linh hoạt, check in từ 8h đến 9h (ngày làm 8 tiếng)', '[''Bảo hiểm xã hội'', ''Du lịch hàng năm'', ''Team building'', ''Được bổ sung, đào tạo liên tục các kiến thức về Content'', ''Làm việc tại môi trường trẻ, năng động, hòa đồng, vui vẻ'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (392, 3, 7, 'Nhân Viên Marketing Seeding Part-Time', 'Phụ trách nội dung các bài viết đăng tải trên website, facebook và các trang truyền thông của Trung tâm nhằm tăng cường sự tiếp cận về thương hiệu đến các khách hàng tiềm năng. Tăng cường lượng khách hàng tiềm năng của Trung tâm. Đảm bảo hình ảnh thương hiệu của Trung tâm đối với khách hàng tiềm năng. Các kế hoạch khác được tổ chức bởi phòng Marketing và cơ sở của Trung tâm.', '● Đang là sinh viên năm 1,2,3 và sinh viên năm cuối chờ bằng hoặc đã tốt nghiệp Đại học trở lên các chuyên ngành liên quan đến Marketing: Đại học Kinh Tế Quốc Dân, Đại học Thương Mại, Đại học Quốc gia Hà Nội, Đại học Hà Nội,... ● Ưu tiên Giao tiếp tiếng anh tốt ● Có kinh nghiệm làm việc liên quan tới Truyền thông - Marketing là lợi thế. ● Kỹ năng giao tiếp tốt. Có kỹ năng thuyết trình, làm việc nhóm
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Kỹ năng thuyết trình'', ''Làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Linh hoạt theo thời gian rảnh của ứng viên', '[''Môi trường làm việc trẻ, năng động'', ''Cơ hội làm việc cùng giáo viên nước ngoài'', ''Tham gia các hoạt động nghỉ mát, teambuilding'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (393, 7, 7, 'Thực Tập Sinh Marketing (Edit Video)', '• Hỗ trợ team Marketing sản xuất và chỉnh sửa các video truyền thông cho các nền tảng mạng xã hội (Facebook, TikTok, YouTube...), góp phần nâng cao nhận diện thương hiệu và tương tác người dùng. • Cắt ghép và chỉnh sửa video theo kịch bản có sẵn hoặc hướng dẫn từ team. • Biên tập hậu kỳ: thêm hiệu ứng hình ảnh, âm thanh, phụ đề, logo thương hiệu, intro/outro cho video. • Tối ưu định dạng video cho từng nền tảng mạng xã hội (dọc cho TikTok, ngang cho YouTube, vuông cho Instagram...). • Sáng tạo nội dung video ngắn (dưới 1 phút), nắm bắt xu hướng để đề xuất hoặc hỗ trợ thực hiện các nội dung viral. • Lưu trữ, quản lý thư viện dữ liệu: video gốc, asset, template hậu kỳ theo hệ thống dùng chung. • Phối hợp với các bộ phận liên quan (thiết kế, nội dung, truyền thông) để đảm bảo tiến độ và chất lượng sản phẩm đầu ra. • Tham gia brainstorm cùng team để đóng góp ý tưởng và nâng cao chất lượng nội dung video định kỳ.', '• Sinh viên năm 2–4 chuyên ngành Marketing, Thiết Kế Đồ Họa, Quay Dựng Video. Có khả năng chịu áp lực cao là một lợi thế • Có kỹ năng sử dụng các phần mềm edit cơ bản: CapCut, Premiere, After Effects, Canva... • Có thẩm mỹ hình ảnh, hiểu xu hướng video mạng xã hội. • Chăm chỉ, cẩn thận, có tinh thần học hỏi và chủ động. • Có thiết bị cá nhân (laptop/điện thoại) phục vụ công việc. • Có tinh thần hỗ trợ đội nhóm
Kỹ năng chuyên môn: [''CapCut'', ''Premiere'', ''After Effects'', ''Canva'']
Kỹ năng mềm: [''Chăm chỉ'', ''Cẩn thận'', ''Có tinh thần học hỏi'', ''Chủ động'']', 'INTERNSHIP', 'ONSITE', 'quận 7, hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Hỗ trợ dấu mộc xác nhận thực tập'', ''Có cơ hội trở thành nhân sự chính thức nếu thể hiện tốt'', ''Môi trường làm việc trẻ, năng động'', ''Được đào tạo thêm về kỹ năng dựng video, storytelling, tối ưu nội dung đa nền tảng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (394, 8, 7, 'Nhân Viên Content Tiếng Trung Full/Part Time', 'Lên kế hoạch nội dung theo tuần/ tháng/quý và phát triển nội dung trên các kênh Tiktok, Youtube, Page Facebook, Group Facebook, Instagram của công ty. Sáng tạo nội dung, đưa ra ý tưởng concept, kịch bản quay video, chuyển thể ý tưởng thành kịch bản quay dựng chi tiết & voice cho các tuyến nội dung trên các kênh truyền thông. Phối hợp diễn xuất trực tiếp trong các video theo nội dung đã định hướng. Nghiên cứu trends, bắt trends, tìm hiểu cách thức hoạt động, thuật toán theo thời gian của TikTok, Youtube, Facebook.', '● Tiếng Trung giao tiếp thành thạo, phát âm chuẩn, tương đương HSK 4 ● Ngoại hình ưa nhìn, tự tin trước máy quay ● Chủ động, trách nhiệm, tư duy linh hoạt, logic, làm việc khoa học, có kế hoạch ● Năng động, sáng tạo, thẩm mỹ và “bắt trend” tốt, có kiến thức về xây dựng content trên các kênh social ● Có nền tảng về Marketing, Truyền thông, Báo chí hoặc các lĩnh vực liên quan là một lợi thế ● Có khả năng thiết kế ảnh, edit video cơ bản ● Ưu tiên biết ứng dụng AI trong công việc
Kỹ năng chuyên môn: [''Thiết kế ảnh'', ''Edit video cơ bản'', ''Ứng dụng AI trong công việc'']
Kỹ năng mềm: [''Chủ động'', ''Trách nhiệm'', ''Tư duy linh hoạt'', ''Logic'', ''Làm việc khoa học'', ''Có kế hoạch'', ''Năng động'', ''Sáng tạo'', ''Thẩm mỹ'', ''Bắt trend tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Lương 2 - 4 triệu + trợ cấp (Part time)'', ''Lương cứng: 7.000.000 VNĐ - 9.000.000 VNĐ + Phụ cấp + thưởng (Full time)'', ''Các chế độ phúc lợi đầy đủ theo quy định công ty và luật lao động'', ''Review lương hàng năm'', ''Teambuilding'', ''Company trip'', ''Thưởng dịp sinh nhật, lễ tết, thưởng cuối năm'', ''Học miễn phí các khóa học tiếng Nhật, tiếng Trung'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (395, 9, 7, 'Media Supporter - Parttime', 'Thực hiện lên ý tưởng set up bối cảnh, chuẩn bị đạo cụ cho các buổi quay/chụp. Đóng vai trò mẫu tay, mẫu thời trang khi cần quay cận cảnh sản phẩm. Hỗ trợ quay phim/chụp ảnh theo yêu cầu, giữ góc quay ổn định. Thực hiện in ấn sample mẫu. Phối hợp với Team Media để đảm bảo tiến độ & chất lượng nội dung. Sắp xếp lại bối cảnh sau khi quay.', 'Ngoại hình ưa nhìn. Có tư duy về thẩm mỹ, sắp xếp bố cục thuận mắt. Yêu thích công việc liên quan đến sáng tạo nội dung, quay chụp. Ứng viên có khả năng làm việc nhóm tốt, nhanh nhẹn, tỉ mỉ, cẩn thận. Có thể làm việc theo ca, linh hoạt thời gian.
Kỹ năng mềm: [''Làm việc nhóm'', ''Quản lý thời gian'', ''Giao tiếp tốt'', ''Khả Năng Học Hỏi Nhanh'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Linh hoạt', '[''Môi trường làm việc trẻ trung, năng động'', ''Được tiếp xúc với các thiết bị quay chụp chuyên nghiệp'', ''Học hỏi kinh nghiệm từ Team Media'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (396, 10, 7, 'Thực Tập Sinh Content Marketing (Nữ) Hỗ Trợ Lương', 'Thực hiện nghiên cứu từ khóa đơn giản và Viết bài seo SEO để tăng lưu lượng truy cập web. Làm nội dung các kênh tiktok, youtube, facebook.', 'Khả năng viết tốt, sẽ được đào tạo thêm về chuyên môn. Quan tâm và luôn cập nhật các xu hướng nội dung hot hay trendy trên social media. Chăm chỉ, chịu khó và có khả năng làm việc dưới áp lực cao. Tinh thần đội nhóm cao.
Kỹ năng chuyên môn: [''SEO'', ''Content Creation'']
Kỹ năng mềm: [''Khả năng viết tốt'', ''Chăm chỉ'', ''Chịu khó'', ''Làm việc dưới áp lực'', ''Tinh thần đội nhóm cao'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '4.0 - 7.0 triệu', 'Từ 8h00 - 17h30 (8h/ngày) - Linh hoạt thời gian theo lịch học', '[''Lương tháng 13'', ''Du lịch định kỳ hàng năm'', ''Tham gia các khóa đào tạo chuyên môn'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Chế độ lương, thưởng hấp dẫn'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (397, 2, 7, 'Thực Tập Sinh Key Account (Sales B2B)', 'Hỗ trợ tìm kiếm và xây dựng danh sách khách hàng doanh nghiệp tiềm năng (B2B). Liên hệ để trao đổi, giới thiệu sản phẩm/dịch vụ đến khách hàng doanh nghiệp. Book lịch các cuộc hẹn giữa khách hàng và đội ngũ Sales chính thức. Tham gia cùng team Sales trong các cuộc gặp khách hàng, ghi nhận thông tin và hỗ trợ làm proposal. Phối hợp với các phòng ban khác để đảm bảo tiến độ và chất lượng chăm sóc khách hàng. Thực hiện các công việc khác theo yêu cầu của quản lý.', 'Sinh viên năm cuối, sắp tốt nghiệp hoặc đã tốt nghiệp các chuyên ngành QTKD, QTDN, TMDT, KDQT hoặc một số chuyên ngành liên quan. Nhanh nhẹn, chăm chỉ và có đam mê với Thương mại điện tử, Kinh doanh, Phát triển kinh doanh. Ưu tiên ứng viên có kỹ năng giao tiếp tiếng Anh hoặc tiếng Trung tốt. Tư duy nhanh nhạy, kỹ năng phân tích và sáng tạo. Có khả năng multi-tasking và quản lý đồng thời nhiều dự án.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp tiếng Anh'', ''Kỹ năng giao tiếp tiếng Trung'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chăm chỉ'', ''Đam mê với Thương mại điện tử'', ''Kinh doanh'', ''Phát triển kinh doanh'', ''Tư duy nhanh nhạy'', ''Kỹ năng phân tích'', ''Sáng tạo'', ''Multi-tasking'', ''Quản lý đồng thời nhiều dự án'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.5 triệu', '5 ngày/tuần - Thời gian làm việc linh hoạt', '[''Trợ cấp thực tập: 3.500.000VND/ tháng'', ''Được hướng dẫn và tham gia vào các dự án thực tế'', ''Có cơ hội trở thành nhân viên chính thức sau thời gian thực tập'', ''Hỗ trợ dấu mộc thực tập'', ''Pantry với free trà, cà phê, snack'', ''Môi trường làm việc thoải mái, năng động, thời gian làm việc linh hoạt'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (398, 3, 7, 'Nhân Viên Kinh Doanh', '- Tiếp nhận, sàng lọc danh sách khách hàng tiềm năng từ chiến dịch Marketing để trở thành đối tượng cho khâu sales. - Tư vấn, giới thiệu công ty và sản phẩm /dịch vụ đến các khách hàng tiềm năng. - Nhận biết, nắm bắt nhu cầu của khách hàng để từ đó giới thiệu các dịch vụ phù hợp. - Chủ động tìm kiếm các cơ hội kinh doanh mới trên thị trường. - Thực hiện các sự kiện, booking KOL.', '- Có các kỹ năng giao tiếp, đàm phán và các kỹ năng cần thiết cho các vị trí liên quan. - Chăm chỉ, năng động, có tính kỷ luật cao. - Có đam mê trong lĩnh vực truyền thông, marketing.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng đàm phán'', ''Chăm chỉ'', ''Năng động'', ''Tính kỷ luật cao'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Lịch làm việc linh hoạt', '[''Lương + phụ cấp thỏa thuận khi phỏng vấn'', ''Hoa hồng cao từ 10-20% cho mỗi hợp đồng'', ''Được đào tạo hàng tuần, hàng tháng về các kỹ năng truyền thông'', ''Mở rộng mối quan hệ và làm việc với các báo đài, người nổi tiếng'', ''Công việc trẻ trung, năng động, sáng tạo'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (399, 7, 7, 'CTV Thư Viện Kiêm Chăm Sóc Khách Hàng', '- Duy trì không gian thư viện chuyên nghiệp và thân thiện cho học sinh và phụ huynh; - Tham gia tổ chức và điều phối các hoạt động liên quan đến thư viện (tổ chức trò chơi cùng các con); - Nhận thông tin phản hồi từ PH về chất lượng dạy học & Trung Tâm (gọi điện thoại); - Hỗ trợ PHHS trong các hoạt động đăng ký thẻ, mượn/trả sách và các hỗ trợ khác (nếu có phát sinh); - Sắp xếp, phân loại các sách/tài liệu được trả lại theo loại, vị trí; - Thực hiện báo cáo kiểm kê sách định kỳ, thông báo các sách quá hạn/thất lạc; - Sửa chữa sách hỏng hoặc sắp hỏng (nếu có); - Hỗ trợ các công việc liên quan đến bộ phận CSKH khi có yêu cầu và các công việc khác khi được phân công.', '- Có tinh thần tổ chức, sắp xếp và quản lý công việc khoa học, hiệu quả; - Đúng giờ, trung thực, trách nhiệm; - Có năng lực tự học, tư duy tích cực.
Kỹ năng mềm: [''Tinh thần tổ chức'', ''Quản lý công việc'', ''Trung thực'', ''Trách nhiệm'', ''Tư duy tích cực'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Tham gia các hoạt động sự kiện của Công ty'', ''Tham gia các khóa đào tạo nội bộ của Công ty'', ''Hỗ trợ chi phí khi làm việc tại IEG'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (400, 8, 7, 'Thực Tập Sinh Kinh Doanh', '- Tìm hiểu về các dịch vụ, giải pháp của Công ty và phát triển các phương pháp tư vấn khách hàng, để chuyển đổi tốt hơn trong doanh số. - Xác định nhu cầu của khách hàng và phối hợp cùng team để tìm cách tư vấn khách hàng phù hợp. - Phân tích nhu cầu và các vướng mắc của khách hàng. - Làm đề xuất báo giá và phối hợp với các team để xây dựng proposal cho khách hàng. - Chăm sóc và theo dõi khách hàng trước, trong, và sau khi hợp tác. - Tạo dựng mối quan hệ thân thiết với khách hàng. - Nhận ra những khách hàng tiềm năng, nắm bắt cơ hội và chốt deal nhanh chóng. - Nhận thức tốt về thương hiệu kinh doanh của công ty, các dịch vụ và giải pháp của công ty.', '- Sinh viên năm 4 hoặc đã tốt nghiệp các chuyên ngành về Marketing, Quản trị kinh doanh, hoặc các chuyên ngành liên quan. - Tỉ mỉ, cẩn thận, biết lắng nghe, sẵn sàng học hỏi, chịu được áp lực công việc, có khả năng làm việc nhóm. - Có thể thực tập full time. - Ngoại hình sáng, có khả năng giao tiếp Tiếng Anh cơ bản. - Có niềm đam mê và yêu thích kinh doanh. - Khả năng thuyết phục. - Học nhanh và giải quyết vấn đề nhanh. - Sẵn sàng học và nghiên cứu các lĩnh vực để tư vấn tốt hơn về dịch vụ và giải pháp của Công ty. - Sẵn sàng đầu tư thời gian và nỗ lực để nghiên cứu và thúc đẩy doanh số.
Kỹ năng mềm: [''Tỉ mỉ'', ''Cẩn thận'', ''Biết lắng nghe'', ''Sẵn sàng học hỏi'', ''Chịu được áp lực công việc'', ''Có khả năng làm việc nhóm'', ''Khả năng thuyết phục'', ''Học nhanh'', ''Giải quyết vấn đề nhanh'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Full time', '[''Có cơ hội được đào tạo toàn diện về Công nghệ số và Quản trị truyền thông kỹ thuật số'', ''Có cơ hội tiếp cận với phương pháp và quy trình quản trị dự án truyền thông kỹ thuật số'', ''Được giúp đỡ, hướng dẫn, huấn luyện kỹ năng mềm trong công việc'', ''Làm việc trong môi trường thân thiện với nhiều công nghệ mới'', ''Hỗ trợ hoàn thành báo cáo và con dấu thực tập'', ''Được xây dựng lộ trình phát triển trở thành nhân viên chính thức của công ty'', ''Được tham gia vào các hoạt động Teambuilding, YEP'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (401, 9, 7, 'Nhân Viên Chăm Sóc Khách Làm Part-Time', '- Gọi điện tìm kiếm khách hàng từ những nguồn data khách hàng sẵn từ Trưởng phòng - Cung cấp, tư vấn đầy đủ và chính xác thông tin sản phẩm - Giải quyết thắc mắc của khách hàng, phối hợp bộ phận Hành chính Kinh doanh xử lý khiếu nại - Chăm sóc khách hàng theo chương trình chung của công ty - Những công việc khác theo sự phân công của quản lý trực tiếp **Lưu ý: Telesale không phải chốt sale mà chỉ gọi điện lấy thông tin, địa chỉ của khách hàng để chuyển cho nhân viên kinh doanh đi gặp khách hàng tư vấn trực tiếp**', '- Sinh viên các trường đại học - Không yêu cầu kinh nghiệm, chưa có sẽ được cầm tay chỉ việc. - Thân thiện, ham học hỏi, kiên trì là 1 lợi thế. - Năng động, sáng tạo, nhiệt tình, nghiêm túc và có trách nhiệm với công việc
Kỹ năng mềm: [''Thân thiện'', ''Ham học hỏi'', ''Kiên trì'', ''Năng động'', ''Sáng tạo'', ''Nhiệt tình'', ''Nghiêm túc'', ''Có trách nhiệm với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '6.0 - 8.0 triệu', 'Thời gian làm việc linh hoạt (Parttime/Fulltime)', '[''Lương cứng từ 5.000.000 - 10.000.000 Triệu/Tháng + Hoa hồng + Thưởng nóng'', ''Đề xuất/Xét duyệt tăng lương theo từng tháng'', ''Hỗ trợ tiền gửi xe, ăn trưa'', ''Môi trường làm việc chuyên nghiệp, trẻ trung năng động'', ''Cơ hội thăng tiến trong công việc'', ''Tham dự các chương trình team building, party, du lịch'', ''Đãi ngộ theo chế độ lễ Tết và các ngày lễ hấp dẫn'', ''Chính sách đào tạo về các kĩ năng mềm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (402, 10, 7, 'Thực Tập Sinh Đăng Bài SEO (Parttime)', 'Mục đích của công việc: Phối hợp với Kỹ thuật SEO để đăng bài viết hoàn chỉnh lên website cho các dự án SEO. Nhiệm vụ và trách nhiệm chính của công việc: Đảm bảo tiến độ đăng bài, đảm bảo chất lượng bài đăng, cam kết bảo mật thông tin.', 'Phương tiện cá nhân: Có laptop cá nhân. Học vấn: Ứng viên đang học chuyên ngành marketing, PR, truyền thông, báo chí hoặc học chuyên ngành khác nhưng đam mê học hỏi về Marketing và SEO.
Kỹ năng chuyên môn: [''Sử dụng thành thạo Google Docs'', ''Sử dụng Google Sheet'', ''Sử dụng photoshop cơ bản'']
Kỹ năng mềm: [''Quản lý thời gian tốt'', ''Cẩn thận'', ''Tỉ mỉ'', ''Chủ động trong công việc'', ''Tư duy khoa học'', ''Kiên trì'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.5 - 2.0 triệu', '8h30 - 11h45, 13h00 - 17h30', '[''Được hỗ trợ dấu thực tập'', ''Được đào tạo kỹ năng chỉnh sửa hình ảnh cơ bản trên photoshop'', ''Cơ hội tham gia các buổi đào tạo về chuyên môn SEO'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (403, 2, 7, 'Thực Tập Sinh Content Website', 'Tìm kiếm từ khóa/chủ đề cho nội dung bài viết. Viết bài, lên nội dung cho website. Lập kế hoạch nội dung. Lên nội dung bài viết cho fanpage.', 'Sinh viên đang học các ngành Báo chí, truyền thông, ngôn ngữ,.... có đam mê với Marketing nói chung và Content marketing nói riêng. Năng động, nhiệt tình, sôi nổi. Có khả năng làm việc độc lập. Có kỹ năng giải quyết vấn đề, tiếp nhận và phân tích.
Kỹ năng chuyên môn: [''SEO'', ''Content writing'']
Kỹ năng mềm: [''Năng động'', ''Nhiệt tình'', ''Có khả năng làm việc độc lập'', ''Kỹ năng giải quyết vấn đề'', ''Kỹ năng tiếp nhận và phân tích'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ lương thực tập'', ''Hỗ trợ xác nhận thực tập'', ''Được đào tạo kỹ năng chuyên môn về SEO và content'', ''Làm việc trong môi trường trẻ trung, năng động'', ''Có thưởng cùng phòng ban nếu có kết quả tốt'', ''Lên nhân viên chính thức kể'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (404, 3, 7, 'Thực Tập Sinh Content Writer', 'Hỗ trợ viết nội dung theo đúng yêu cầu về format, phong cách và thời hạn cho các dự án video ngắn/dài, podcast, blog, ... Hỗ trợ lên ý tưởng kịch bản và xây dựng khung chương trình cho các dự án theo yêu cầu. Phát triển và viết kịch bản sáng tạo cho nội dung dựa trên brief được giao. Nghiên cứu và thu thập thông tin liên quan đến các chủ đề khác nhau để đảm bảo tính chính xác và xác thực của nội dung cần viết. Hợp tác với các bộ phận khác để đảm bảo chất lượng nội dung. Luôn cập nhật và trau dồi kiến thức mới nhất về nội dung.', 'Sinh viên muốn làm thêm lấy kinh nghiệm. Hoặc đang là sinh viên năm cuối, mới ra trường hoặc chuẩn bị tốt nghiệp. Mong muốn học thêm kỹ năng và phát triển bản thân trong mảng Content, Biên kịch. Có khả năng viết nội dung sáng tạo theo nhiều phong cách khác nhau.
Kỹ năng chuyên môn: [''Viết nội dung sáng tạo'']
Kỹ năng mềm: [''Khả năng làm việc nhóm'', ''Khả năng sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.5 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:45)', '[''Chi phí hỗ trợ thực tập: 1.500.000'', ''Cơ hội trở thành nhân viên chính thức'', ''Môi trường làm việc trẻ trung, năng động'', ''Hỗ trợ học tập phát triển chuyên môn'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (405, 7, 7, 'Giám đốc điều hành tiếp thị', 'Hỗ trợ lập kế hoạch và triển khai các chiến dịch Marketing đa nền tảng. Quản lý, tối ưu các kênh truyền thông số (Fanpage, Website, Tiktok...). Hỗ trợ lên ý tưởng, viết nội dung cho các ấn phẩm Marketing (post, banner, bài viết...). Tham gia triển khai và theo dõi hiệu quả các chiến dịch quảng cáo (Facebook Ads, Google Ads cơ bản nếu có). Nghiên cứu thị trường, phân tích đối thủ và hành vi khách hàng. Theo dõi, tổng hợp và báo cáo hiệu quả các hoạt động Marketing định kỳ. Phối hợp với các bộ phận khác (Sales,...) để đảm bảo hiệu quả công việc. Hỗ trợ các công việc hành chính Marketing khác theo yêu cầu.', 'Tốt nghiệp Cao đẳng/Đại học chuyên ngành Marketing, Quản trị kinh doanh hoặc các ngành liên quan. Có kinh nghiệm làm việc ở vị trí tương đương là một lợi thế (Hoặc: Sinh viên năm cuối/Mới tốt nghiệp có đam mê và định hướng rõ ràng về Marketing). Có kiến thức nền tảng vững chắc về Marketing và Digital Marketing. Kỹ năng viết lách, giao tiếp và trình bày tốt. Thành thạo các công cụ văn phòng (Word, Excel, PowerPoint). Chủ động, nhiệt tình, có tinh thần trách nhiệm cao và khả năng làm việc nhóm. Tư duy sáng tạo, ham học hỏi và thích nghi nhanh với sự thay đổi. Biết sử dụng các công cụ chỉnh sửa ảnh/video cơ bản là một lợi thế.
Kỹ năng chuyên môn: [''Marketing'', ''Digital Marketing'', ''Sử dụng các công cụ văn phòng (Word, Excel, PowerPoint)'', ''Sử dụng các công cụ chỉnh sửa ảnh/video cơ bản'']
Kỹ năng mềm: [''Kỹ năng viết lách'', ''Giao tiếp'', ''Trình bày'', ''Chủ động'', ''Nhiệt tình'', ''Tinh thần trách nhiệm cao'', ''Khả năng làm việc nhóm'', ''Tư duy sáng tạo'', ''Ham học hỏi'', ''Thích nghi nhanh với sự thay đổi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), làm việc từ 3-5 buổi/tuần', '[''Môi trường làm việc trẻ trung, năng động, thoải mái sáng tạo'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (406, 8, 7, 'Thực Tập Sinh MARKETING', 'Là Marketing Intern tại T.U.N.G dining, bạn sẽ hỗ trợ bộ phận Marketing trong các công việc sáng tạo nội dung trên các kênh truyền thông và triển khai các hoạt động marketing theo kế hoạch.', 'Sinh viên năm 3, 4 hoặc mới tốt nghiệp chuyên ngành Marketing, Truyền thông hoặc các chuyên ngành có liên quan. Có khả năng viết content sáng tạo, logic và nắm bắt xu hướng truyền thông tốt. Hiểu biết cơ bản về social media (Facebook, Instagram). Biết sử dụng Photoshop/Illustrator là lợi thế. Có tư duy tổ chức công việc, chủ động và linh hoạt. Có tư duy làm việc có mục đích và hướng tới giải quyết vấn đề. Có gu thẩm mỹ đối với hình ảnh. Có laptop cá nhân để hỗ trợ công việc.
Kỹ năng chuyên môn: [''Sử dụng Photoshop'', ''Sử dụng Illustrator'', ''Viết nội dung cho mạng xã hội'']
Kỹ năng mềm: [''Khả năng viết content sáng tạo'', ''Tư duy tổ chức công việc'', ''Chủ động và linh hoạt'', ''Tư duy làm việc có mục đích'', ''Gu thẩm mỹ đối với hình ảnh'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '2.0 - 2.5 triệu', 'Thứ 2 - Thứ 7 (từ 09:30 đến 18:30)', '[''Được đào tạo và làm việc về Marketing thực tế trong ngành F&B cao cấp'', ''Môi trường làm việc chuyên nghiệp, sáng tạo, thân thiện'', ''Hỗ trợ chi phí & cơ hội trở thành nhân viên chính thức'', ''Ăn trưa'', ''Team building'', ''Thưởng hiệu quả làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (407, 9, 7, 'Marketing Intern', 'Nghiên cứu và phân tích (15%): Theo dõi các trang tin tức và xu hướng của ngành. Tiến hành nghiên cứu và phân tích tin tức, đối thủ, các tài liệu liên quan từ bộ phần kỹ thuật. Sáng tạo nội dung - sản phẩm số cho công ty (70%): Hỗ trợ tạo nội dung cho các kênh truyền thông của công ty (Facebook, Website, Youtube, LinkedIn). Tối ưu nội dung chuẩn SEO cho trang blog và trang dạng TMĐT. Đóng góp ý tưởng sáng tạo và đề xuất phát triển nội dung. Hỗ trợ tạo và thiết kế ấn phẩm số: Poster, Banner, Thumbnail, Market Report,... Tổng hợp và báo cáo hiệu quả từ các kênh (10%). Nhập và tối ưu nội dung Website (5%): Nhập thông tin sản phẩm trên Website.', 'Yêu cầu công việc: Sinh viên năm 3, năm cuối hoặc sinh viên mới ra trường chuyên ngành Marketing, Kinh tế, PR và các ngành liên quan, có định hướng làm việc tại doanh nghiệp B2B. Có laptop cá nhân. Có kỹ năng research thông tin, viết, khả năng sử dụng các phần mềm cơ bản như: Canva, CapCut,... và MS Office. Tinh thần chủ động trong công việc, tự tin trao đổi và đưa ra ý kiến. Trình độ ngoại ngữ: TOEIC 450+ hoặc có khả năng sử dụng tool dịch thuật. Tối thiểu 4h/ngày, 7 ngày/tuần.
Kỹ năng chuyên môn: [''Canva'', ''CapCut'', ''MS Office'']
Kỹ năng mềm: [''Kỹ năng research thông tin'', ''Viết'', ''Tinh thần chủ động trong công việc'', ''Tự tin trao đổi và đưa ra ý kiến'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '1.8 - 5.0 triệu', 'Tối thiểu 4h/ngày, 7 ngày/tuần', '[''Trợ cấp thực tập: 1.800.000 VNĐ/tháng (+ thưởng khi đạt KPI)'', ''Hỗ trợ đóng dấu mộc và dữ liệu làm báo cáo thực tập'', ''Được đào tạo từ đầu, truy cập tài liệu khóa học training do công ty đầu tư'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (408, 10, 7, 'Cán Bộ Quản Lý Lớp Học', 'Hỗ trợ Ban Giám đốc trong công tác điều hành và quản lý hoạt động chung của Trung tâm. Địa điểm làm việc của Trung tâm tại Ngọc Hồi, Thanh Trì, Hà Nội. Đảm bảo các hoạt động vận hành hằng ngày diễn ra suôn sẻ, đúng quy trình. Quản lý công tác tuyển sinh, chăm sóc và giải quyết thắc mắc của học viên/phụ huynh. Lên lịch, điều phối giáo viên, trợ giảng phù hợp với lịch học của Trung tâm. Theo dõi, báo cáo tình hình hoạt động định kỳ cho Ban Giám đốc. Hỗ trợ tổ chức các sự kiện, hội thảo và hoạt động ngoại khóa tại Trung tâm.', 'Tốt nghiệp hoặc đang theo học Cao đẳng/Đại học, ưu tiên các ngành Quản lý Giáo dục, Kinh tế hoặc Quản trị Kinh doanh. Kỹ năng giao tiếp tốt, khả năng xử lý tình huống linh hoạt. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). Tinh thần trách nhiệm cao, khả năng làm việc độc lập.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng xử lý tình huống linh hoạt'', ''Tinh thần trách nhiệm cao'', ''Khả năng làm việc độc lập'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '2.0 - 7.0 triệu', 'Thứ 2 - Chủ nhật (từ 16:00 đến 21:00)', '[''Thu nhập ổn định'', ''Thưởng theo hiệu suất công việc'', ''Được đào tạo kỹ năng quản lý, điều hành'', ''Cơ hội thăng tiến lên các vị trí cấp cao trong Trung tâm'', ''Môi trường làm việc thân thiện, chuyên nghiệp'', ''Cước điện thoại'', ''Thưởng tháng 13'', ''Thưởng hiệu quả làm việc'', ''Team building'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (409, 2, 7, 'Booking KOL/KOC', 'Tìm kiếm và liên hệ: Chủ động tìm kiếm, kết nối và đàm phán với KOLs/KOCs, các đối tác và nhà cung cấp dịch vụ phù hợp với yêu cầu của chiến dịch. Quản lý booking: Theo dõi, điều phối và quản lý các booking để đảm bảo đúng tiến độ, chất lượng và ngân sách. Xử lý hợp đồng: Hỗ trợ soạn thảo, kiểm tra và quản lý hợp đồng, chứng từ liên quan đến booking. Phối hợp nội bộ: Làm việc chặt chẽ với các bộ phận Marketing, Content, và các team liên quan để tối ưu hóa hiệu quả chiến dịch. Báo cáo công việc: Cập nhật tiến độ và báo cáo kết quả công việc hàng ngày/tuần, đề xuất giải pháp cải thiện khi cần thiết. Xử lý vấn đề: Nhanh chóng giải quyết các vấn đề phát sinh trong quá trình làm việc với KOLs/KOCs hoặc đối tác.', '1. Kỹ năng * Có ít nhất 6 tháng - 1 năm kinh nghiệm trong lĩnh vực booking, làm việc với KOLs/KOCs hoặc các công việc liên quan đến influencer marketing. * Tiếng Anh thông thạo (giao tiếp lưu loát, viết email chuyên nghiệp, làm việc trực tiếp với KOLs/KOCs quốc tế). * Kỹ năng giao tiếp và đàm phán xuất sắc, linh hoạt trong xử lý tình huống. * Kỹ năng quản lý thời gian và tổ chức công việc hiệu quả, đặc biệt trong môi trường làm việc áp lực cao. * Am hiểu về các nền tảng mạng xã hội (Instagram, TikTok, YouTube, v.v.) và xu hướng influencer marketing. 2. Phẩm chất * Chủ động và quyết liệt: Luôn bám sát mục tiêu, không ngại khó khăn để đạt được kết quả. * Kiên trì và trung thực: Xây dựng lòng tin với đối tác và nội bộ công ty. * Cẩn thận, tỉ mỉ: Đảm bảo không có sai sót trong quản lý booking, hợp đồng và báo cáo. * Ham học hỏi: Sẵn sàng tiếp thu kiến thức mới và cập nhật xu hướng trong ngành. 3. Cam kết * Tuân thủ SLA (Service Level Agreement): Phản hồi nhanh, hoàn thành công việc đúng hạn. * Báo cáo tiến độ hàng ngày. * Tham gia họp định kỳ (hàng tuần/tháng) để đánh giá hiệu suất.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng đàm phán'', ''Quản lý thời gian'', ''Am hiểu về các nền tảng mạng xã hội'']
Kỹ năng mềm: [''Chủ động'', ''Kiên trì'', ''Cẩn thận'', ''Ham học hỏi'']', 'FREELANCE', 'ONSITE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Linh hoạt', '[''Mức thu nhập dựa trên năng lực và hiệu suất'', ''Môi trường làm việc chuyên nghiệp'', ''Cơ hội hợp tác với các KOLs/KOCs nổi tiếng'', ''Cơ hội tham gia các dự án lớn'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (410, 3, 7, 'Thực Tập Sinh SEO', 'Đăng tải, tối ưu SEO onpage các trang sản phẩm, danh mục sản phẩm, bài viết tin tức blog. Triển khai internal link các sản phẩm theo mô hình silo. Research keywords, lên layout nội dung phù hợp cho các trang danh mục sản phẩm, ngành hàng và bài tin tức. Tiếp nhận định hướng từ trưởng bộ phận để đưa plan triển khai và thực thi ở ngành hàng, cụm topics phù hợp với từng giai đoạn. Triển khai offpage trên các nền tảng social profile hỗ trợ hiệu suất performance. Hỗ trợ xây dựng nội dung SEO.', 'Có kiến thức SEO cơ bản. Đã từng thao tác làm việc trên Google Sheets. Điểm cộng nếu có: Có sở thích tìm hiểu, theo dõi các thông tin về công nghệ thông tin, AI, các sản phẩm công nghệ. Có khả năng đọc hiểu tiếng Anh từ trung bình đến khá tốt. Có tư duy trong việc phân phối khối lượng công việc theo timeline hợp lý. Có tư duy mạch lạc trong việc nhận thông tin, giải quyết vấn đề. Có tư duy research, nghiên cứu và đúc kết thông tin tốt.
Kỹ năng chuyên môn: [''SEO cơ bản'', ''Google Sheets'']
Kỹ năng mềm: [''Tư duy mạch lạc'', ''Giải quyết vấn đề'', ''Tư duy research'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:45 đến 17:45)', '[''Hỗ trợ dấu mộc thực tập'', ''Daily food đa dạng (miễn phí sữa chua, trái cây, trà, cafe, bánh kẹo)'', ''Môi trường làm việc trẻ trung, năng động và thân thiện'', ''Được hướng dẫn công việc tận tình, đào tạo về SEO'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (411, 7, 7, 'Thực Tập Sinh Content SEO', 'Nghiên cứu, phân tích sản phẩm/dịch vụ của doanh nghiệp, phân tích khách hàng và đối thủ để đóng góp vào xây dựng chiến lược bài viết SEO. Lên outline bài viết, viết bài theo ngày, tuần, tháng. Triển khai viết bài viết chuẩn SEO trên website được giao có sự hướng dẫn và kiểm tra. Viết bài PR, bài chuẩn SEO trên website/các trang mạng xã hội khác để thu hút, tăng lượng traffic, lượng tương tác người dùng. Lập báo cáo định kỳ. Các công việc liên quan theo sự phân công của người hướng dẫn.', 'Trình độ học vấn: Sinh viên năm cuối hoặc mới tốt nghiệp Cao đẳng, Đại học ở các chuyên ngành Quản trị kinh doanh, Marketing, Báo chí, Truyền thông, Ngôn ngữ Anh và các ngành khác có liên quan. Tư duy content tốt, kỹ năng viết tốt, rành mạch, dễ hiểu, đúng chính tả. Có kiến thức cơ bản về SEO, xử lý hình ảnh bằng Photoshop, Canva. Có trách nhiệm và hoàn thành công việc đúng thời hạn. Chịu học hỏi và phát triển bản thân. Đến văn phòng 2 buổi/ tuần.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về SEO'', ''Xử lý hình ảnh bằng Photoshop'', ''Canva'']
Kỹ năng mềm: [''Tư duy content tốt'', ''Kỹ năng viết tốt'', ''Có trách nhiệm và hoàn thành công việc đúng thời hạn'', ''Chịu học hỏi và phát triển bản thân'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 3 (từ 08:00 đến 17:00), Thứ 5 (từ 08:00 đến 17:00)', '[''Môi trường làm việc năng động, chuyên nghiệp'', ''Được đào tạo các kỹ năng liên quan đến SEO, Content Marketing'', ''Được hướng dẫn bởi các Anh/Chị giàu kinh nghiệm'', ''Cơ hội phát triển lên các vị trí chính thức sau thời gian thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (412, 8, 7, 'Nhân Viên Video Editor', 'Chỉnh sửa, tạo hiệu ứng chèn text để hoàn chỉnh các video, clip theo kịch bản, yêu cầu cấp trên. Kiểm tra chất lượng nội dung và hình thức của sản phẩm trước khi bàn giao cho các bộ phận liên quan. Đảm bảo công việc: Tối thiểu 20 VIDEO ( dài 60-90s ) / tháng, thời gian trả video sau khi nhận brief là 5h, fix video nhanh trong 1h.', 'Sử dụng thành thạo các phần mềm thiết kế, chỉnh sửa ảnh, video: Capcut, Ai, Ps, Ae,... Có kinh nghiệm làm video trong lĩnh vực làm đẹp, skincare, thẩm mỹ da là lợi thế lớn. Có nền tảng và tư duy tốt về layout, typography, màu sắc. Sáng tạo, có khả năng nắm bắt xu hướng và đề xuất ý tưởng mới. Nhanh nhẹn, linh hoạt, yêu thích công việc. Làm việc ĐÚNG DEADLINE có tinh thần trách nhiệm, ham học hỏi và tìm tòi.
Kỹ năng chuyên môn: [''Capcut'', ''Ai'', ''Ps'', ''Ae'']
Kỹ năng mềm: [''Sáng tạo'', ''Nhanh nhẹn'', ''Linh hoạt'', ''Có tinh thần trách nhiệm'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Lựa chọn 1 ca offline mỗi ngày từ Thứ 2 – Thứ 7, trong đó: Ca 1: 9h30 - 13h30, Ca 2: 14h - 18h', '[''Môi trường làm việc trẻ, năng động, sáng tạo'', ''Lương thưởng hấp dẫn, phù hợp với năng lực'', ''Có cơ hội làm việc với KOL, KOC lớn trong lĩnh vực làm đẹp, thẩm mỹ'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (413, 9, 7, 'Thực Tập Sinh Partnership', 'Hỗ trợ xây dựng và duy trì mối quan hệ với các đối tác như thương hiệu, tổ chức, influencer, trường học, cộng đồng,... Phối hợp tổ chức các chương trình hợp tác như: chiến dịch đồng thương hiệu, sự kiện, chiến dịch marketing, ưu đãi dành cho khách hàng,... Chuẩn bị và theo dõi các tài liệu làm việc với đối tác: hợp đồng, đề xuất hợp tác, biên bản,... Tổng hợp kết quả và đề xuất cải tiến sau mỗi chương trình hợp tác. Thực hiện các công việc khác theo sự hướng dẫn của quản lý.', 'Tổng thời gian tham gia chương trình thực tập: 3 tháng hoặc 6 tháng. Luôn nỗ lực hết mình để hoàn thành chương trình thực tập. Là sinh viên từ năm 1- 4 các ngành liên quan như: Kinh doanh, Marketing, Truyền thông, Quan hệ công chúng,... Yêu thích lĩnh vực đối tác, thương hiệu, sự kiện và các hoạt động kết nối cộng đồng. Có kỹ năng giao tiếp, làm việc nhóm và chủ động trong công việc. Cẩn thận, biết sắp xếp công việc, có khả năng theo dõi tiến độ và xử lý nhiều đầu việc cùng lúc. Thành thạo Google Workspace (Docs, Sheets, Slides); ưu tiên biết dùng Canva, Notion. Có thể viết email, chuẩn bị tài liệu (proposal, báo cáo, biên bản,...).
Kỹ năng chuyên môn: [''Google Workspace (Docs, Sheets, Slides)'', ''Canva'', ''Notion'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Làm việc nhóm'', ''Chủ động trong công việc'', ''Cẩn thận'', ''Biết sắp xếp công việc'', ''Có khả năng theo dõi tiến độ và xử lý nhiều đầu việc cùng lúc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), tối thiểu 4 tiếng/ ngày, 5 buổi/ tuần', '[''Được tham gia các khóa đào tạo, phát triển kỹ năng'', ''Cơ hội tham gia trực tiếp vào quá trình thực hiện công việc'', ''Chứng chỉ hoàn thành chương trình thực tập'', ''Thư giới thiệu từ cấp quản lý (nếu có nguyện vọng)'', ''Cơ hội trở thành Best Talent với giải thưởng 5,000,000 VND tiền mặt'', ''Cơ hội trở thành Best Transformation với giải thưởng 5,000,000 VND tiền mặt hoặc 01 năm mentoring'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (414, 10, 7, 'Thực Tập Sinh Community Builder', 'Quản lý và tương tác với cộng đồng người dùng trên các kênh như Facebook Group, Tiktok, Zalo, ... Viết nội dung ngắn (bài post, mini game, câu hỏi tương tác, v.v.) để giữ cộng đồng luôn sôi động. Trả lời tin nhắn, bình luận, hỗ trợ giải đáp thắc mắc cho thành viên. Góp ý và đề xuất ý tưởng để phát triển cộng đồng. Hỗ trợ tổ chức các sự kiện nhỏ (online hoặc offline nếu có).', 'Tổng thời gian tham gia chương trình thực tập: 3 tháng hoặc 6 tháng. Luôn nỗ lực hết mình để hoàn thành chương trình thực tập. Giao tiếp tốt, thân thiện, thích kết nối và xây dựng cộng đồng. Thành thạo ít nhất 1 nền tảng: Facebook Group, Zalo, Tik Tok. Có khả năng viết nội dung ngắn, tạo tương tác (caption, minigame, post...). Chủ động, có trách nhiệm, sẵn sàng học hỏi. Ưu tiên nếu từng làm admin group, leader CLB, biết Canva hoặc từng tổ chức sự kiện/hoạt động cộng đồng.
Kỹ năng chuyên môn: [''Thành thạo ít nhất 1 nền tảng: Facebook Group, Zalo, Tik Tok'', ''Có khả năng viết nội dung ngắn, tạo tương tác (caption, minigame, post...)'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Thân thiện'', ''Thích kết nối và xây dựng cộng đồng'', ''Chủ động'', ''Có trách nhiệm'', ''Sẵn sàng học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), tối thiểu 4 tiếng/ ngày, 5 buổi/ tuần', '[''Được tham gia các khóa đào tạo, phát triển kỹ năng'', ''Được tạo cơ hội để sinh viên tham gia trực tiếp vào quá trình thực hiện công việc'', ''Giúp đỡ thực tập sinh nhìn nhận và thấu hiểu bản thân'', ''Có cơ hội được kết nối thực với doanh nghiệp/tổ chức'', ''Được trả mức thù lao 1.000.000 VND (kể từ tháng thứ 4 trở đi)'', ''Được hỗ trợ chữ ký và mộc thực tập'', ''Được cấp chứng chỉ hoàn thành chương trình thực tập'', ''Có cơ hội trở thành Best Talent với giải thưởng 5,000,000 VND tiền mặt'', ''Có cơ hội trở thành Best Transformation với giải thưởng 5,000,000 VND tiền mặt hoặc 01 năm mentoring'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (415, 2, 7, 'Thực Tập Sinh Content Marketing', 'Chịu trách nhiệm lên content, lên ý tưởng về hình ảnh, để chủ động quản lý nội dung quảng cáo phù hợp. Lên các chương trình sự kiện marketing theo event, ngày, tháng, năm. Nghiên cứu xu hướng thị trường và đề xuất ý tưởng nội dung phù hợp với chiến lược marketing. Phối hợp với đội ngũ thiết kế và marketing để tạo ra các nội dung hấp dẫn và phù hợp với đối tượng mục tiêu. Thực hiện các công việc khác theo yêu cầu từ quản lý.', 'Tổng thời gian tham gia chương trình thực tập: 3 tháng hoặc 6 tháng. Luôn nỗ lực hết mình để hoàn thành chương trình thực tập. Ngành học: Ưu tiên Marketing, QTKD, Kinh tế hoặc các ngành có liên quan. Có tư duy và sự yêu thích đối với Marketing. Kỹ năng viết và sáng tạo nội dung tiếng Việt, tiếng Anh tốt, yêu cầu tiếng Anh tốt. Năng động, sáng tạo, nhiệt tình, cầu tiến trong công việc. Có khả năng thiết kế trên các công cụ cơ bản như Canva.com; Photoshop, Illustrator là một lợi thế. Sử dụng Facebook/Tiktok/Blog là một lợi thế.
Kỹ năng chuyên môn: [''Kỹ năng viết và sáng tạo nội dung tiếng Việt'', ''Kỹ năng viết và sáng tạo nội dung tiếng Anh'', ''Thiết kế trên các công cụ cơ bản như Canva.com, Photoshop, Illustrator'']
Kỹ năng mềm: [''Năng động'', ''Sáng tạo'', ''Nhiệt tình'', ''Cầu tiến trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), tối thiểu 4 tiếng/ ngày, 5 buổi/ tuần', '[''Được tham gia các khóa đào tạo, phát triển kỹ năng'', ''Cơ hội tham gia trực tiếp vào quá trình thực hiện công việc'', ''Chứng chỉ hoàn thành chương trình thực tập'', ''Thư giới thiệu từ cấp quản lý (nếu có nguyện vọng)'', ''Giải thưởng 5,000,000 VND cho Best Talent'', ''Giải thưởng 5,000,000 VND hoặc 01 năm mentoring với CEO cho Best Transformation'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (416, 3, 7, 'Nội dung xã hội thực tập', 'Tại V-Odyssey, chúng tôi pha trộn du lịch cao cấp, khám phá văn hóa và giáo dục ưu tú vào những trải nghiệm biến đổi. Chúng tôi đang tìm kiếm một thực tập viên truyền thông xã hội để hỗ trợ cách kể chuyện kỹ thuật số của chúng tôi và khuếch đại sự hiện diện thương hiệu của chúng tôi trên các nền tảng.', 'Key Responsibilities: Develop engaging, creative content for Facebook, Instagram, TikTok, and more. Support ongoing campaigns: schedule posts, monitor engagement, and report insights. Write and edit compelling social media copy aligned with brand tone and messaging. Stay updated on the latest trends to integrate into our content strategy. Collaborate with the marketing team to ensure consistent messaging across all channels.
Kỹ năng chuyên môn: [''Photography'', ''Video editing'']
Kỹ năng mềm: [''Creativity'', ''Trend awareness'', ''Collaboration'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Official internship certificate recognized in Vietnam and the UK'', ''Real-world experience in the luxury travel and education sector'', ''Financial support and on-the-job training throughout the internship'', ''Opportunity to receive a UK-based certification and recommendation for top-performing interns'', ''A dynamic, young, and professional work environment'', ''Potential for full-time employment and continued career growth in Digital Marketing'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (417, 7, 7, 'Nhân Viên Trực Page Part-Time', 'Tư vấn, hỗ trợ khách hàng qua các kênh mạng xã hội về dịch vụ thẩm mỹ, làm đẹp. Giải đáp thắc mắc, chốt lịch hẹn với khách hàng. Làm việc theo ca, 1 ngày có ca 1: 8h-17h, ca 2: 17h-22h, 8h-20h làm ở cty, 20h-22h làm ở nhà, đăng ký tối thiểu 6 ca/tuần.', 'Biết sử dụng tin học văn phòng. Giao tiếp linh hoạt, phản hồi nhanh chóng. Có kinh nghiệm CSKH là một lợi thế.
Kỹ năng chuyên môn: [''Biết sử dụng tin học văn phòng'']
Kỹ năng mềm: [''Giao tiếp linh hoạt'', ''Phản hồi nhanh chóng'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Theo ca', '[''Môi trường làm việc thân thiện, năng động'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (418, 8, 7, 'Thực Tập Sinh Kinh Doanh', 'Thực hiện chăm sóc, tư vấn cho khách hàng về các sản phẩm của công ty. Thực hiện quy trình bán hàng và chăm sóc khách hàng theo quy trình tiêu chuẩn của công ty. Tham gia tổ chức các sự kiện quảng bá, giới thiệu sản phẩm. Thực hiện các báo cáo bán hàng theo yêu cầu. Thực hiện các nhiệm vụ khác theo yêu cầu của quản lý.', 'Tổng thời gian tham gia chương trình thực tập: 3 tháng hoặc 6 tháng. Luôn nỗ lực hết mình để hoàn thành chương trình thực tập. Ưu tiên ngành học: chuyên ngành Kinh tế, Quản trị Kinh doanh…. đang tìm kiếm cơ hội thực tập/ phát triển trong lĩnh vực Kinh doanh. Có khả năng giao tiếp tốt, giải quyết vấn đề khéo léo, có đam mê và định hướng nghề Kinh doanh. Cẩn thận, cầu tiến trong công việc, quản lý thời gian và khả năng làm việc nhóm tốt để xử lý đa nhiệm vụ. Chủ động trong công việc.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Giải quyết vấn đề'', ''Cẩn thận'', ''Cầu tiến'', ''Quản lý thời gian'', ''Làm việc nhóm'', ''Chủ động'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), tối thiểu 4 tiếng/ ngày, 5 buổi/ tuần', '[''Được tham gia các khóa đào tạo, phát triển kỹ năng'', ''Cơ hội tham gia trực tiếp vào quá trình thực hiện công việc'', ''Chứng chỉ hoàn thành chương trình thực tập'', ''Thưởng theo hiệu suất công việc'', ''Cơ hội trở thành Best Talent với giải thưởng 5,000,000 VND'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (419, 9, 7, 'Thực Tập Sinh Thiết Kế Đồ Hoạ', 'Hỗ trợ thiết kế các hạng mục công việc, dự án tại công ty bao gồm hình ảnh, video; Hỗ trợ thiết kế ấn phẩm sự kiện và truyền thông: Backdrop, flyer, banner, invitation card, standee… Hỗ trợ thiết kế thương hiệu: nhận diện thương hiệu, Catalogue, Card visit, Poster, Banner, Tờ rơi, Brochure, hồ sơ năng lực... sản phẩm in ấn phục vụ công việc quảng bá sản phẩm, thương hiệu của đối tác, khách hàng và công ty. Chuẩn bị hình ảnh minh họa hoặc các bản phác thảo, format chương trình truyền hình, sự kiện, các bản trình bày ý tưởng. Thực hiện thiết kế các ấn phẩm liên quan đến truyền thông nội bộ, các ấn phẩm trên các kênh social. Thiết kế, chỉnh sửa các tài liệu theo yêu cầu của công ty. Thực hiện các nhiệm vụ khác theo yêu cầu của quản lý.', 'Tổng thời gian tham gia chương trình thực tập: 3 tháng hoặc 6 tháng; Luôn nỗ lực hết mình để hoàn thành chương trình thực tập; Ưu tiên ngành học: Thiết kế đồ họa, Marketing, QTKD, Kinh tế hoặc các ngành có liên quan. Có tư duy và sự yêu thích đối với Thiết kế đồ họa; Ưu tiên có kiến thức về thiết kế đồ họa, marketing, truyền thông; Biết sử dụng các công cụ thiết kế: Canva; Adobe Photoshop, Adobe Premiere, Illustrator. Sử dụng Facebook/Tiktok/Blog; Hướng tới khách hàng, kỹ năng tổ chức công việc, làm việc nhóm và độc lập; Có tư duy thẩm mỹ, khả năng sáng tạo cơ bản; Cẩn thận, cầu tiến trong công việc, quản lý thời gian và khả năng làm việc nhóm tốt để xử lý đa nhiệm vụ; Có khiếu thẩm mỹ phù hợp thị hiếu hiện nay. Chủ động trong công việc.
Kỹ năng chuyên môn: [''Canva'', ''Adobe Photoshop'', ''Adobe Premiere'', ''Illustrator'']
Kỹ năng mềm: [''Kỹ năng tổ chức công việc'', ''Làm việc nhóm'', ''Độc lập'', ''Tư duy thẩm mỹ'', ''Khả năng sáng tạo'', ''Cẩn thận'', ''Cầu tiến'', ''Quản lý thời gian'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), tối thiểu 4 tiếng/ ngày, 5 buổi/ tuần', '[''Được tham gia các khóa đào tạo'', ''Cơ hội kết nối với doanh nghiệp'', ''Thù lao 1.000.000 VND (kể từ tháng thứ 4 trở đi)'', ''Chứng chỉ hoàn thành chương trình thực tập'', ''Thư giới thiệu từ cấp quản lý (nếu có nguyện vọng)'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (420, 10, 7, 'Thực Tập Sinh Video Editor', 'Chỉnh sửa, biên tập video theo kịch bản từ Content Creator. Thực hiện các hiệu ứng âm thanh, hình ảnh và đồ họa cơ bản để tăng tính sinh động cho video. Hỗ trợ sáng tạo nội dung video theo xu hướng trên TikTok, Facebook Reels, YouTube. Hỗ trợ phối hợp với Content Creator, lên kế hoạch ý tưởng, nội dung cho các video để hoàn thiện sản phẩm cuối cùng. Tham gia vào các dự án thực tế, đóng góp ý tưởng sáng tạo và nhận phản hồi trực tiếp từ các chuyên gia. Thực hiện các công việc khác theo yêu cầu từ quản lý.', 'Tổng thời gian tham gia chương trình thực tập: 3 tháng hoặc 6 tháng. Luôn nỗ lực hết mình để hoàn thành chương trình thực tập. Sinh viên từ năm nhất đến năm tư tại các trường đại học trên cả nước. (Ưu tiên ứng viên biết sử dụng một số phần mềm như Capcut, Adobe Photoshop, Adobe Premiere, và có kiến thức về Adobe After Effect,...). Ưu tiên ứng viên có kinh nghiệm biên tập video. Có tư duy thẩm mỹ, khả năng sáng tạo cơ bản. Cẩn thận, cầu tiến trong công việc, quản lý thời gian và khả năng làm việc nhóm tốt để xử lý đa nhiệm vụ. Có khiếu thẩm mỹ phù hợp thị hiếu hiện nay. Chủ động trong công việc.
Kỹ năng chuyên môn: [''Capcut'', ''Adobe Photoshop'', ''Adobe Premiere'', ''Adobe After Effect'']
Kỹ năng mềm: [''Tư duy thẩm mỹ'', ''Khả năng sáng tạo'', ''Cẩn thận'', ''Cầu tiến'', ''Quản lý thời gian'', ''Khả năng làm việc nhóm'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), tối thiểu 4 tiếng/ ngày, 5 buổi/ tuần', '[''Được tham gia các khóa đào tạo, phát triển kỹ năng'', ''Cơ hội thực hiện công việc thực tế'', ''Trả mức thù lao 1,000,000 VND (kể từ tháng thứ 4 trở đi)'', ''Hỗ trợ chữ ký và mộc thực tập'', ''Cấp chứng chỉ hoàn thành chương trình thực tập'', ''Cơ hội trở thành Best Talent với giải thưởng 5,000,000 VND'', ''Cơ hội trở thành Best Transformation với giải thưởng 5,000,000 VND hoặc 01 năm mentoring'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (421, 2, 7, 'Cộng Tác Viên PART-TIME MARKETING', 'Tham gia dự án marketing công nghệ cho thương hiệu HIXPad và hệ thống Hireview. Hỗ trợ triển khai nội dung cho Website, Facebook, TikTok, YouTube. Làm việc theo checklist, được hướng dẫn và đào tạo từ đầu. Góp ý, brainstorm ý tưởng nội dung theo từng tuần.', 'Không yêu cầu kinh nghiệm (được đào tạo, hướng dẫn cụ thể). Có laptop cá nhân và chủ động về thời gian. Tinh thần trách nhiệm, làm việc đúng deadline. Biết sử dụng các công cụ cơ bản như Google Docs, Canva, TikTok là lợi thế. Ưu tiên sinh viên các ngành: Marketing, Báo chí, Truyền thông, Thiết kế, Multimedia…
Kỹ năng chuyên môn: [''Google Docs'', ''Canva'', ''TikTok'']
Kỹ năng mềm: [''Tinh thần trách nhiệm'', ''Chủ động về thời gian'', ''Làm việc đúng deadline'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Môi trường trẻ trung, năng động, phù hợp với sinh viên'', ''Tham gia vào các dự án thật – có sản phẩm, có thị trường'', ''Có cơ hội làm việc lâu dài nếu thể hiện tốt'', ''Được học hỏi quy trình sáng tạo nội dung từ A → Z'', ''Có cơ hội nâng mức thu nhập, xét full-time sau 1–2 tháng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (422, 3, 7, 'Nhân Viên Kinh Doanh Homestay/Khách Sạn', 'Chăm sóc khách hàng có nhu cầu trên tất cả nền tảng online về giá tiền, tiện ích các căn hộ, Homestay của HNT House đến khi khách hàng hoàn thành đặt phòng. Tính tiền, gửi khách hàng thông tin đặt phòng, gửi khách hàng xác nhận. Gửi thông tin cho kế toán, gửi thông tin cho vận hành tại căn hộ, Homestay của HNT House. Khóa lịch và vào file excel các đơn đặt phòng. Tiếp nhận và xử lý các vấn đề của khách hàng đặc biệt về vấn đề đặt phòng. Chăm sóc sau khi khách hàng sử dụng dịch vụ qua tất cả nền tảng online của HNT House. Thực hiện các công việc đáp ứng kế hoạch kinh doanh của trưởng phòng, giám đốc kinh doanh và sự chỉ đạo của Ban lãnh đạo HNT House.', 'Không có kinh nghiệm sẽ được đào tạo. Ở văn phòng hoặc cơ sở của HNT House tối thiểu 16 giờ/tuần và hoàn thành KPI kinh doanh được phân bổ. Kỹ năng trao đổi tin nhắn, văn bản, hội thoại khéo léo, tình cảm, nắm bắt tâm lý khách hàng. Làm việc nhóm, đáp ứng deadlines, chăm chỉ ham học hỏi, cẩn thận. Tư duy làm ngành dịch vụ, cầu thị, lễ phép.
Kỹ năng mềm: [''Kỹ năng trao đổi tin nhắn'', ''Làm việc nhóm'', ''Chăm chỉ ham học hỏi'', ''Cẩn thận'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '10.0 - 15.0 triệu', 'Thời gian làm việc linh động, 1 tuần tối thiểu ở công ty 2 buổi và 1 buổi đào tạo', '[''Môi trường làm việc trẻ, năng động'', ''Lương cứng + hoa hồng + thưởng KPI'', ''Thưởng tháng 13'', ''Tham gia BHXH, BHYT và BHTN theo quy định nhà nước'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (423, 7, 7, 'Quản lý tài khoản khóa chuyên gia (chăm sóc sức khỏe)', 'Thực hiện cửa hàng điện tử, hoạt động, khuyến mãi và giao dịch. Liệt kê, gửi giao dịch, thiết lập chương trình khuyến mãi, đăng ký chiến dịch. Giám sát DKSH KPI trên thị trường điện tử. Duy trì & cập nhật dữ liệu chính (sản phẩm, giá cả, quảng bá, v.v.). Phân tích dữ liệu/ bảng điều khiển/ báo cáo về hiệu suất EC và nâng cao quy trình. Theo dõi các hoạt động bán hàng, tham gia của người tiêu dùng, chương trình khách hàng thân thiết, kế hoạch quảng cáo hàng tháng và thực hiện. Theo dõi và báo cáo về số liệu hiệu suất tài khoản. Tiến hành đánh giá kinh doanh thường xuyên với khách hàng để đánh giá tiến trình và điều chỉnh các chiến lược khi cần thiết. Báo cáo theo phân công (hàng tuần, hàng tháng). Làm việc chặt chẽ với KAM cao cấp, thương hiệu, phương tiện truyền thông, thiết kế, nhóm vận hành để phù hợp với các chương trình khuyến mãi, hàng tồn kho và ra mắt sản phẩm. Phối hợp với các đối tác bên ngoài để tăng cường dòng chảy kinh doanh trơn tru.', 'Bachelor’s in Business Administration, Marketing, Digital, Ecommerce or relevant level. 1-2 year working experience in ecommerce industry (Platform, Enabler is preferred). Preferred: Candidates with experience in beauty, personal care, or pharmaceutical cosmetics categories. Strong communication and negotiation skills in English; strategic thinking and problem-solving abilities. Proficient in Seller Center, SAP, and Microsoft Office; knowledgeable in e-commerce and digital marketing. Excellent organizational, multitasking skills; able to work independently and as part of a team with great attention to detail.
Kỹ năng chuyên môn: [''Seller Center'', ''SAP'', ''Microsoft Office'']
Kỹ năng mềm: [''Strong communication'', ''Negotiation skills'', ''Strategic thinking'', ''Problem-solving abilities'', ''Excellent organizational skills'', ''Multitasking skills'', ''Attention to detail'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 14000000.00, '12.0 - 14.0 triệu', 'Monday - Friday (from 09:00 to 18:00)', '[''Competitive salary'', ''Bonus according to policy'', ''Professional and friendly multinational working environment'', ''Phone allowance'', ''Provided computer'', ''Social insurance'', ''Health insurance'', ''Health insurance for family members'', ''Full salary insurance'', ''Team building'', ''Periodic health check'', ''Seniority allowance'', ''Performance bonus'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (424, 8, 7, 'Thực Tập Sinh Video Editor', 'Phối hợp với Team MKT để lên ý tưởng cho Video. Dựng và chỉnh sửa video bằng phần mềm Capcut… Các công việc khác được cấp trên giao phó. Phối hợp với các phòng ban làm các nhiệm vụ liên quan.', 'Sử dụng tốt các phần mềm chỉnh sửa video. (Capcut) Có khả năng sáng tạo video viral dưa trên Content. Xử lý công việc thông minh, nhanh nhẹn, chăm chỉ, có trách nhiệm trong công việc, ham học hỏi. Biết sử dụng các công cụ AI theo yêu cầu công việc.
Kỹ năng chuyên môn: [''Capcut'', ''Phần mềm chỉnh sửa video'']
Kỹ năng mềm: [''Sáng tạo'', ''Chăm chỉ'', ''Có trách nhiệm'', ''Ham học hỏi'', ''Xử lý công việc thông minh'', ''Nhanh nhẹn'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)', '[''Thưởng hiệu quả làm việc'', ''Du lịch hàng năm'', ''Thưởng tháng 13'', ''Team building'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (425, 9, 7, 'Thực Tập Sinh SEO Part Time', 'Tham gia xây dựng nội dung website, thực hiện nghiên cứu từ khóa, nghiên cứu website và phân tích đối thủ cạnh tranh, thực hiện các công việc tối ưu Onpage và Offpage, tham gia xây dựng các kế hoạch Content, viết Content và tối ưu Content chuẩn SEO, sử dụng các công cụ Google Analytics, Google Search Console, Ahrefs,... để theo dõi dữ liệu từ trang web, thực hiện các công việc khác theo sự phân công của trưởng nhóm.', 'Không yêu cầu kinh nghiệm, làm việc tối thiểu 5 buổi/ tuần (1 ngày làm việc gồm 2 buổi), có mong muốn được gắn bó và làm việc lâu dài với mảng SEO, chăm chỉ, nhiệt tình, chủ động, ham học hỏi, có khả năng làm việc độc lập và làm việc theo nhóm, là sinh viên các trường cao đẳng, ĐH chuyên ngành công nghệ thông tin, marketing, kinh tế hoặc các sinh viên qua lớp đào tạo ngắn hạn về SEO…là một điểm cộng, có khả năng viết bằng tiếng Anh là một điểm cộng.
Kỹ năng chuyên môn: [''Google Analytics'', ''Google Search Console'', ''Ahrefs'']
Kỹ năng mềm: [''Chăm chỉ'', ''Nhiệt tình'', ''Chủ động'', ''Ham học hỏi'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc theo nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 17:00)', '[''Được đào tạo đầy đủ các kĩ năng chuyên môn về SEO'', ''Phụ cấp thực tập từ 2-3 triệu/ tháng'', ''Môi trường làm việc thoải mái, năng động với phần lớn nhân viên thuộc Gen Z'', ''Được đi du lịch cùng công ty tối thiểu 2 lần/ năm'', ''Lộ trình thăng tiến rõ ràng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (426, 10, 7, 'Thực Tập Sinh Marketing Part-Time', 'Nghiên cứu insight khách hàng, phân tích đối thủ và xu hướng nội dung thị trường. Xây dựng chiến lược nội dung, lên kế hoạch và quản lý lịch trình xuất bản nội dung (content calendar). Sáng tạo đa dạng các loại nội dung: Bài viết Blog, bài PR, bài SEO chuẩn. Nội dung mạng xã hội (Facebook, TikTok, Google): caption, kịch bản video ngắn, idea hình ảnh. Nội dung Website/Landing Page. Nội dung quảng cáo (text ads, headline, description) sáng tạo, thu hút. Tối ưu hóa nội dung cho các công cụ tìm kiếm (SEO) và tương tác người dùng. Quản lý, vận hành các kênh nội dung của công ty (Fanpage, Blog/Website...). Đo lường, phân tích hiệu quả nội dung và đề xuất các phương án cải thiện. Phối hợp chặt chẽ với đội Marketing để đảm bảo nội dung đồng bộ và hiệu quả.', 'Trình độ: phù hợp với các bạn sinh viên chuyên ngành Marketing, hoặc có kỹ năng tốt ở mảng này; Kinh nghiệm: Không yêu cầu kinh nghiệm; Sử dụng tốt các công cụ chỉnh sửa video, đồ họa cơ bản (CapCut, Canva, Premiere cơ bản…); Có kiến thức cơ bản về SEO và cách viết nội dung chuẩn SEO. Sáng tạo, chủ động, nắm bắt trend nhanh, yêu thích công việc liên quan đến marketing.
Kỹ năng chuyên môn: [''Sử dụng tốt các công cụ chỉnh sửa video'', ''Đồ họa cơ bản (CapCut, Canva, Premiere cơ bản)'', ''Kiến thức cơ bản về SEO'']
Kỹ năng mềm: [''Sáng tạo'', ''Chủ động'', ''Nắm bắt trend nhanh'', ''Yêu thích công việc liên quan đến marketing'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), linh hoạt 3-5 buổi/tuần', '[''Môi trường làm việc trẻ trung, năng động, thoải mái sáng tạo'', ''Được đào tạo bài bản về Marketing'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (427, 2, 7, 'Tiếp thị nội dung bán thời gian', 'Nghiên cứu insight khách hàng, phân tích đối thủ và xu hướng nội dung thị trường. Xây dựng chiến lược nội dung, lên kế hoạch và quản lý lịch trình xuất bản nội dung (content calendar). Sáng tạo đa dạng các loại nội dung: Bài viết Blog, bài PR, bài SEO chuẩn. Nội dung mạng xã hội (Facebook, TikTok, Google): caption, kịch bản video ngắn, idea hình ảnh. Nội dung Website/Landing Page. Nội dung quảng cáo (text ads, headline, description) sáng tạo, thu hút. Tối ưu hóa nội dung cho các công cụ tìm kiếm (SEO) và tương tác người dùng. Quản lý, vận hành các kênh nội dung của công ty (Fanpage, Blog/Website...). Đo lường, phân tích hiệu quả nội dung và đề xuất các phương án cải thiện. Phối hợp chặt chẽ với đội Marketing để đảm bảo nội dung đồng bộ và hiệu quả.', 'Kỹ năng viết lách xuất sắc, tư duy sáng tạo, khả năng ''chơi chữ'' và kể chuyện. Am hiểu về các nền tảng mạng xã hội và xu hướng nội dung mới nhất. Có kiến thức cơ bản về SEO và cách viết nội dung chuẩn SEO. Chủ động, có trách nhiệm, khả năng làm việc độc lập và làm việc nhóm. Kỹ năng nghiên cứu, tổng hợp thông tin tốt. Biết sử dụng các công cụ chỉnh sửa ảnh/video cơ bản là một lợi thế.
Kỹ năng chuyên môn: [''Kỹ năng viết lách'', ''Kiến thức cơ bản về SEO'', ''Sử dụng các công cụ chỉnh sửa ảnh/video cơ bản'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Kỹ năng nghiên cứu'', ''Tổng hợp thông tin'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), làm việc từ 3-5 buổi/tuần', '[''Thưởng hiệu quả làm việc'', ''Môi trường làm việc trẻ trung, năng động, thoải mái sáng tạo'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (428, 3, 7, 'Thực Tập Sinh Marketing', 'Hỗ trợ triển khai các hoạt động marketing, đặc biệt trên các nền tảng mạng xã hội. Hỗ trợ xây dựng và thực hiện nội dung: viết caption, thiết kế hình ảnh, dựng video ở mức cơ bản. Nghiên cứu xu hướng, đề xuất ý tưởng sáng tạo phù hợp với đối tượng mục tiêu. Hỗ trợ các công việc hành chính và nhiệm vụ khác theo phân công của quản lý.', 'Sinh viên đại học năm 3,4. Chuyên ngành Marketing hoặc các chuyên ngành khác có liên quan. Có kỹ năng quay, dựng video trên điện thoại, máy tính. Nắm bắt, cập nhật các xu hướng trên mạng xã hội, giới trẻ. Có hiểu biết về MKT là lợi thế. Có thiết bị cá nhân hỗ trợ công việc (Điện Thoại, Lap).
Kỹ năng chuyên môn: [''Kỹ năng quay, dựng video trên điện thoại, máy tính'', ''Sử dụng Canva, Capcut'']
Kỹ năng mềm: [''Nắm bắt, cập nhật các xu hướng trên mạng xã hội'', ''Có hiểu biết về Marketing là lợi thế'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 là ngày dự phòng', '[''Được hướng dẫn, đào tạo nghiệp vụ, kỹ năng mềm và công việc thực tế'', ''Hỗ trợ dấu mộc và chữ ký cho giấy xác nhận thực tập và báo cáo thực tập'', ''Cơ hội đào tạo chuyên nghiệp, học hỏi và trải nghiệm các nghiệp vụ thực tế, phát triển chuyên môn cá nhân'', ''Môi trường làm việc thân thiện, chuyên nghiệp, năng động'', ''Có cơ hội trở thành nhân viên chính thức nếu đáp ứng được yêu cầu công việc sau khi kết thúc thời gian tập sự và có bằng tốt nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (429, 7, 7, 'Nhân Viên Content Marketing', '- Lên content plan định kỳ cho các kênh social (chủ yếu là Facebook). - Viết bài đăng Facebook theo mục tiêu truyền thông và định hướng thương hiệu. - Lên lịch đăng bài, theo dõi hiệu quả cơ bản. - Sử dụng AI (đặc biệt là ChatGPT hoặc các công cụ tương đương) để hỗ trợ sáng tạo nội dung, viết kịch bản, xây dựng concept video hấp dẫn. - Quay clip/ảnh sản phẩm cơ bản (dùng điện thoại), phục vụ cho nội dung đăng tải. - Hỗ trợ các công việc liên quan đến nội dung và hình ảnh khác theo phân công.', '- Ưu tiên sinh viên ngành Marketing, Truyền thông, Báo chí,... các trường FTU, NEU, AJC,... hoặc người đã có kinh nghiệm làm nội dung. - Có tư duy nội dung, biết viết bài thu hút và phù hợp với từng tệp khách hàng. - Biết quay dựng, thiết kế cơ bản trên Canva, Capcut. - Có tinh thần trách nhiệm cao trong công việc, khả năng giải quyết vấn đề tốt. - Có laptop cá nhân.
Kỹ năng chuyên môn: [''Sử dụng AI (ChatGPT hoặc các công cụ tương đương)'', ''Quay clip/ảnh sản phẩm cơ bản'', ''Thiết kế cơ bản trên Canva, Capcut'']
Kỹ năng mềm: [''Tư duy nội dung'', ''Khả năng giải quyết vấn đề'', ''Tinh thần trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00), Thứ 7: 8h30 -12h30', '[''Xét tăng lương định kỳ theo năng lực'', ''Cơ hội thăng tiến'', ''Môi trường làm việc năng động, thân thiện'', ''Được trau dồi và đào tạo các kiến thức chuyên sâu về Marketing và truyền thông'', ''Thưởng theo dự án nếu hoàn thành tốt công việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (430, 8, 7, 'Nhân Viên Design (Part Time)', 'Thiết kế sáng tạo ấn phẩm truyền thông cho các chiến dịch Marketing và quảng cáo online & offline theo kế hoạch PR - Content. Thiết kế các sản phẩm in ấn như: Poster, Standee, Backdrop, Poster, Banner,... nhằm phục vụ cho hoạt động kinh doanh. Chịu trách nhiệm về tiến độ cho các ấn phẩm truyền thông.', 'Có kinh nghiệm thiết kế thương hiệu (Ưu tiên lĩnh vực nhà hàng quán ăn,...). Tính cách: hòa đồng, nỗ lực, thích học hỏi tìm hiểu và nâng cao kỹ năng nghề nghiệp. Tự quản lý, sắp xếp và phân chia công việc tốt để hoàn thành deadline, có tinh thần hỗ trợ công việc cho các bạn khác. Có tư duy thẩm mỹ, sáng tạo, chủ động công việc cá nhân và tương tác nhóm tốt. Am hiểu các phong cách thiết kế. Sử dụng thành thạo phần mềm: Photoshop, Illustrator,... Ưu tiên các bạn có laptop.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'']
Kỹ năng mềm: [''Hòa đồng'', ''Nỗ lực'', ''Thích học hỏi'', ''Tự quản lý'', ''Sắp xếp công việc'', ''Tinh thần hỗ trợ'', ''Tư duy thẩm mỹ'', ''Sáng tạo'', ''Tương tác nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00), Thứ 7: 8h30 -12h30', '[''Được training toàn bộ kỹ năng thiết kế'', ''Được trau dồi và đào tạo các kiến thức chuyên sâu về Marketing và truyền thông'', ''Được làm việc với đa dạng ngành hàng, môi trường trẻ trung, năng động'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (431, 9, 7, 'Thực Tập Sinh Marketing', 'Tìm kiếm và tổng hợp dữ liệu khách hàng tiềm năng. Lên ý tưởng và xây dựng nội dung marketing sáng tạo, thu hút. Quản lý và chăm sóc trang Facebook (giao diện cá nhân được công ty cấp). Phối hợp với team trong các hoạt động truyền thông và chăm sóc khách hàng.', 'Là sinh viên năm 3 hoặc năm 4 chuyên ngành Marketing, Quản trị kinh doanh, Truyền thông hoặc các ngành liên quan. Có laptop cá nhân và sử dụng thành thạo tin học văn phòng. Năng động, sáng tạo, có khả năng giao tiếp và làm việc nhóm tốt. Có định hướng phát triển nghề nghiệp trong lĩnh vực Marketing.
Kỹ năng chuyên môn: [''Sử dụng thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Năng động'', ''Sáng tạo'', ''Có khả năng giao tiếp'', ''Làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), part time 4 buổi 1 tuần, mỗi buổi 4 tiếng', '[''Hỗ trợ tài liệu, dấu mộc phục vụ báo cáo thực tập'', ''Được hướng dẫn và đào tạo bài bản các kỹ năng về Marketing thực chiến'', ''Cơ hội học hỏi từ các dự án thực tế, nâng cao kinh nghiệm làm việc'', ''Môi trường làm việc trẻ trung, năng động, đồng nghiệp thân thiện'', ''Thưởng hiệu suất (KPI) và hoa hồng theo kết quả công việc'', ''Không yêu cầu trang phục, thoải mái thể hiện cá tính'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (432, 10, 7, 'Thực Tập Sinh Marketing', 'Phối hợp với bộ phận kinh doanh và thiết kế để xây dựng chiến lược marketing online cho các dự án của công ty. Quản lý và tối ưu hóa các kênh marketing online như Google Ads, Facebook Ads, SEO, mạng xã hội khác. Phân tích dữ liệu marketing, báo cáo kết quả và đề xuất các chiến lược tối ưu hóa hiệu quả. Nghiên cứu và cập nhật xu hướng marketing online mới nhất, áp dụng vào thực tiễn. Tạo nội dung marketing online hấp dẫn (hình ảnh, video, bài viết) trên các nền tảng mạng xã hội. Quản lý và tương tác với cộng đồng mạng xã hội, giải đáp thắc mắc của khách hàng. Theo dõi và đo lường hiệu quả của các chiến dịch marketing online. Hỗ trợ xây dựng và triển khai các chương trình khuyến mãi, sự kiện online.', 'Không yêu cầu kinh nghiệm, được đào tạo bài bản. Tốt nghiệp Cao đẳng/Đại học chuyên ngành Marketing, Truyền thông, Quản trị kinh doanh hoặc các ngành liên quan. Có kiến thức cơ bản về marketing online và các kênh marketing kỹ thuật số. Khả năng phân tích số liệu, báo cáo và tổng hợp thông tin. Khả năng làm việc độc lập và làm việc nhóm tốt. Có khả năng giao tiếp tốt, nhanh nhẹn, năng động, sáng tạo. Thành thạo tin học văn phòng (Word, Excel, Powerpoint). Có kỹ năng viết và chỉnh sửa nội dung tốt (một lợi thế).
Kỹ năng chuyên môn: [''Kiến thức cơ bản về marketing online'', ''Các kênh marketing kỹ thuật số'', ''Tin học văn phòng (Word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Khả năng phân tích số liệu'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Giao tiếp tốt'', ''Năng động'', ''Sáng tạo'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 7 (từ 07:30 đến 17:30)', '[''Mức lương cạnh tranh'', ''Thưởng hiệu quả công việc'', ''Môi trường làm việc chuyên nghiệp, năng động, thân thiện'', ''Được đào tạo bài bản về kỹ năng marketing online'', ''Cơ hội thăng tiến và phát triển nghề nghiệp'', ''Được hưởng đầy đủ các chế độ bảo hiểm theo quy định của pháp luật'', ''Tham gia các hoạt động team building, nghỉ mát hàng năm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (433, 2, 7, 'Social Content Creator', 'Lên kịch bản, ý tưởng xây dựng nội dung quảng bá thương hiệu NOAM. Lên hình, đóng chính trong các video quảng bá thương hiệu. Edit video, tự đăng tải lên các MXH quản lý. Tham khảo thị trường, bắt trend phù hợp với thương hiệu. Các công việc khác theo chỉ đạo của cấp trên.', 'Nam, ngoại hình sáng, lên hình tự tin, bắt khung hình. Có kinh nghiệm xây kênh. Có trang tiktok cá nhân (hoặc các trang mxh khác). Không ngại ống kính, đã từng lên hình cho những video quảng bá (ưu tiên dạng video giải trí). Nắm bắt được hot trending ở từng thời điểm. Ưu tiên biết sử dụng Capcut, Canva, Photoshop…
Kỹ năng chuyên môn: [''Capcut'', ''Canva'', ''Photoshop'']
Kỹ năng mềm: [''Tự tin trước ống kính'', ''Nắm bắt hot trending'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', '08h30 - 13h00 hoặc 13h00 - 17h30', '[''Thử việc 01 tháng, nhận 85% lương chính thức'', ''Được hưởng các chế độ của công ty như BHXH, ngày phép'', ''Môi trường làm việc trẻ trung, năng động'', ''Được mua hàng với giá ưu đãi'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (434, 3, 7, 'Thực Tập Sinh Marketing', '- Theo dõi, chăm sóc, hỗ trợ, giải đáp các nhu cầu của khách hàng và đánh giá của khách hàng về dịch vụ. - Học hỏi, nghiên cứu, triển khai theo các hoạt động Digital Marketing của công ty để tăng tương tác với khách hàng như: Thương mại trên mạng xã hội, quản lý thông tin trên Website, Viết bài, Soạn nội dung Newsletter, Triển khai Seeding, SEO, GOOGLE... - Tham gia vận hành, quản trị hệ thống thương mại điện tử của Công ty. - Theo dõi, tổng hợp dữ liệu, phân tích và hoàn thành báo cáo. - Các công việc khác theo sự sắp xếp trực tiếp của Founder.', '- Sinh viên đang chờ tốt nghiệp Trung cấp, Cao đẳng, Đại học; - Có Laptop cá nhân - Lý lịch rõ ràng - Sức khỏe: Tốt - Thời gian thực tập tối thiểu 3 tháng
Kỹ năng chuyên môn: [''Digital Marketing'', ''SEO'', ''Google'']
Kỹ năng mềm: [''Giao tiếp'', ''Hỗ trợ khách hàng'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 16:00)', '[''Phụ cấp tiền xăng xe 250k/tháng cho thực tập sinh có địa chỉ cách công ty >=15km'', ''Hỗ trợ dấu mộc, giấy chứng nhận sau khi kết thúc thực tập'', ''Thực tập sinh lấy mộc (full time) tối thiểu 3 tháng phụ cấp thực tập tháng đầu 500k'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (435, 7, 7, 'Thực Tập Sinh Truyền Thông Marketing', 'Xây dựng nội dung cho các bài đăng Facebook và Mạng Xã hội. Lên định hướng nội dung và viết comment seeding. Thu thập thông, tìm kiếm, nghiên cứu thông tin (thương hiệu, ngành hàng). Trực tiếp tham gia hỗ trợ các chiến dịch truyền thông, Marketing cùng các doanh nghiệp hàng đầu Việt Nam (VNA, Viettel, VCB, VPBank,...) trên các nền tảng MXH. Trực tiếp tham gia xử lý khủng hoảng truyền thông cho đối tác, dựa trên thống kê và lượng hóa các chỉ số.', 'Có tư duy giải quyết, phân tích vấn đề. Có kiến thức cơ bản về marketing, các kênh social media. Có kỹ năng sản xuất nội dung là ưu thế. Chăm chỉ, cần thận, trung thực. Tư duy logic, có khả năng tự học & chủ động giải quyết vấn đề. Làm việc nhóm tốt. Làm được full time, có laptop cá nhân.
Kỹ năng chuyên môn: [''Tin học văn phòng'', ''Content Marketing'', ''Seeding'']
Kỹ năng mềm: [''Tư duy giải quyết'', ''Phân tích vấn đề'', ''Chăm chỉ'', ''Cần thận'', ''Trung thực'', ''Tư duy logic'', ''Khả năng tự học'', ''Làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 1000000.00, '1.5 triệu', 'Từ thứ 2 đến thứ 6: 08h15 - 17h15; Thứ 7: 9h00 - 12h00', '[''Có cơ hội lên nhân viên chính thức'', ''Tham gia vào các dự án lớn'', ''Môi trường năng động, chuyên nghiệp'', ''Thưởng nóng hàng tháng'', ''Thưởng các ngày lễ'', ''Chế độ phúc lợi khác (pantry, du lịch, team building, happy hours)'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (436, 8, 7, 'Thực Tập Sinh Content Marketing - Có Lương', 'Viết mô tả sản phẩm hấp dẫn, chuẩn SEO cho các sản phẩm POD (áo thun, cốc, tranh canvas, v.v...) trên các nền tảng như Etsy, Amazon, Shopify... Sáng tạo nội dung hình ảnh, video ngắn phục vụ truyền thông trên mạng xã hội: TikTok. Tìm hiểu và cập nhật xu hướng thiết kế, từ khóa, niche đang hot trong cộng đồng POD. Phối hợp với designer để đề xuất ý tưởng thiết kế phù hợp với xu hướng và insight khách hàng. Báo cáo kết quả công việc định kỳ và đề xuất cải tiến.', 'Sinh viên năm 3 trở lên các ngành Marketing, Truyền thông, Thương mại điện tử hoặc ngành liên quan. Có khả năng, sáng tạo, nắm bắt trend nhanh. Quan tâm hoặc từng biết đến mô hình POD là một lợi thế. Có kỹ năng tìm kiếm, research thị trường cơ bản. Biết sử dụng Canva, CapCut hoặc phần mềm chỉnh sửa cơ bản là lợi thế. Tinh thần học hỏi cao, cầu tiến và chủ động trong công việc.
Kỹ năng chuyên môn: [''Biết sử dụng Canva'', ''Biết sử dụng CapCut'', ''Kỹ năng tìm kiếm'', ''Research thị trường cơ bản'']
Kỹ năng mềm: [''Sáng tạo'', ''Nắm bắt trend nhanh'', ''Tinh thần học hỏi cao'', ''Cầu tiến'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Môi trường năng động'', ''Cơ hội cọ xát thực tế với ngành thương mại điện tử quốc tế'', ''Được đào tạo quy trình vận hành của mô hình POD'', ''Có cơ hội trở thành nhân sự chính thức'', ''Hỗ trợ dấu mộc thực tập'', ''Phụ cấp thực tập (nếu có) + hỗ trợ chi phí khác theo chính sách công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (437, 9, 7, 'CTV Sales Tư Vấn Du Học Hàn Quốc', 'Tuyển CTV làm việc từ xa phạm vi trên toàn quốc. Lĩnh vực: Tư vấn du học Hàn Quốc. Mô tả: Tìm kiếm ứng viên có nhu cầu du học Hàn Quốc trên các hội nhóm đã được công ty cung cấp sẵn. Tư vấn cho sinh viên có nhu cầu du học Hàn Quốc theo kịch bản có sẵn.', 'Không yêu cầu kinh nghiệm, được đào tạo. Có khả năng giao tiếp tốt, có khả năng đứng trước máy quay là một lợi thế lớn. Chăm chỉ, nhiệt huyết, chủ động trong công việc. Có ngôn ngữ Hàn là một lợi thế (Không bắt buộc).
Kỹ năng mềm: [''Giao tiếp tốt'', ''Chăm chỉ'', ''Nhiệt huyết'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 15000000.00, '10.0 - 15.0 triệu', 'Thời gian làm việc linh động', '[''Tỷ lệ % hoa hồng cao ứng với mỗi đầu sinh viên du học thành công'', ''Được đào tạo bởi các chuyên gia trong lĩnh vực tư vấn du học Hàn Quốc'', ''Được đào tạo hoàn toàn miễn phí thường xuyên thông qua các buổi Zoom hàng tuần'', ''Môi trường làm việc linh động, không bắt buộc phải có mặt ở công ty'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (438, 10, 7, 'Thực Tập Sinh Truyền Thông', 'Trực tiếp hoặc hỗ trợ lên kế hoạch, tổ chức sự kiện và các hoạt động xây dựng văn hóa doanh nghiệp. Trực tiếp hoặc hỗ trợ xây dựng và triển khai các hoạt động truyền thông trong công ty (bản tin, news, email...). Tham gia triển khai, hỗ trợ các chương trình sự kiện lớn nhỏ của FPT/FIS. Là một phần trong công tác gắn kết nhân sự của Công Ty và các đơn vị trong công ty.', 'Sinh viên năm 3,4 đại học các ngành liên quan đến truyền thông, marketing, văn hoá đoàn thể, hoặc tương đương. Có năng khiếu văn hóa – văn nghệ - thể thao. Đã từng tham gia tổ chức các sự kiện hoặc là thành viên các tổ chức Đoàn Thanh niên – Hội Sinh viên – Câu lạc bộ – Đội – Nhóm tại trường đại học... Ưu tiên có tài lẻ như hát, nhảy,...
Kỹ năng mềm: [''Nhiệt tình'', ''Năng động'', ''Trung thực'', ''Chịu được áp lực trong công việc'', ''Tư duy logic tốt'', ''Khả năng tự học'', ''Chủ động'', ''Cầu tiến trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Có cơ hội trở thành cộng tác viên, nhân viên chính thức với mức thu nhập hấp dẫn sau quá trình đào tạo.'', ''Được đào tạo, hướng dẫn, định hướng chuyên môn sớm bởi các kỹ sư, chuyên gia giàu kinh nghiệm và thực hành trực tiếp trong các dự án.'', ''Hỗ trợ đánh giá dấu mộc thực tập.'', ''Tham gia các hoạt động văn hoá, sự kiện hấp dẫn của Công ty FPT IS và Tập đoàn FPT.'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (439, 2, 7, 'Thực Tập Sinh Trợ Lý Quản Lý', 'Bạn sẽ hỗ trợ quản lý trung tâm trong các công việc hằng ngày như: Nhắc việc, theo dõi tiến độ và hỗ trợ điều phối công việc giữa các phòng ban (Sales, Học vụ, Nhân sự…). Tổng hợp báo cáo, đề xuất giải pháp nếu có vấn đề phát sinh. Hỗ trợ quản lý tổ chức các hoạt động vận hành, đào tạo nội bộ, sự kiện nhỏ. Quan sát và học cách vận hành hệ thống một cách bài bản.', 'Không yêu cầu kinh nghiệm (sẽ được đào tạo bài bản từ đầu). Giao tiếp cơ bản bằng tiếng Anh là một lợi thế. Tư duy chủ động, trách nhiệm, kỷ luật và sẵn sàng học hỏi. Yêu thích con người, môi trường giáo dục và mong muốn phát triển bản thân.
Kỹ năng chuyên môn: [''Microsoft Office (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Giao tiếp'', ''Tư duy chủ động'', ''Trách nhiệm'', ''Kỷ luật'', ''Sẵn sàng học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', '8 giờ/ngày, nghỉ 1 ngày/tuần', '[''Học miễn phí chứng chỉ TESOL 120 giờ'', ''Đào tạo trực tiếp 1:1 bởi quản lý cấp cao'', ''Tham gia các buổi training nội bộ'', ''Thưởng hiệu suất'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (440, 3, 7, 'Tài khoản thực tập', 'Hỗ trợ điều hành tài khoản, hỗ trợ trình bày các kế hoạch và đề xuất đánh bóng cho các dự án, thiết lập hậu cần cho các cuộc họp, xử lý giấy tờ cho các hợp đồng và chấp nhận với khách hàng, giám sát chi phí đặt phòng của nhà cung cấp, làm việc trực tiếp với nhóm Kế toán và Tài chính để xử lý thanh toán. Xử lý giấy tờ, chuẩn bị các hình thức tiêu chuẩn, hợp đồng, báo cáo, biên bản cuộc họp, danh sách kiểm tra, hỗ trợ thu thập, tổ chức và điền vào tài liệu, đảm bảo tính chính xác và bảo mật của các tài liệu, hỗ trợ hoạt động văn phòng hàng ngày.', 'Current student or recent graduate in Business Administration, Office Management, or related field. Basic knowledge of office tools (e.g., Microsoft Word, Excel, Google Workspace...). English skills: reading, and writing. Energetic, enthusiastic, and marketing-oriented. Good communication skills and confidence in working with colleagues.
Kỹ năng chuyên môn: [''Basic knowledge of office tools (e.g., Microsoft Word, Excel, Google Workspace...)'']
Kỹ năng mềm: [''Energetic'', ''enthusiastic'', ''marketing-oriented'', ''Good communication skills'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '9 AM – 6 PM, Monday to Friday, with a 2-hour lunch break', '[''A paid internship with a structured training roadmap'', ''Hybrid work model (online/ offline)'', ''Weekly “Happy Hour” and monthly birthday parties'', ''Company trip at least 02 times a year'', ''Dynamic work environment'', ''Flexible working hours'', ''Friendly colleagues'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (441, 7, 7, 'Thực Tập Sinh Content Marketing', 'Sáng tạo nội dung bài viết, hình ảnh, video ngắn phục vụ truyền thông trên Tiktok. Hỗ trợ lên kế hoạch và triển khai các chiến dịch marketing theo định hướng của team. Tìm hiểu và cập nhật xu hướng thiết kế, từ khóa, niche đang hot trong cộng đồng. Tham gia vào quá trình xây dựng kịch bản nội dung cho quảng cáo. Phối hợp với designer để đề xuất ý tưởng thiết kế phù hợp với xu hướng và insight khách hàng. Báo cáo kết quả công việc định kỳ và đề xuất cải tiến.', 'Sinh viên năm 3 trở lên các ngành Marketing, Truyền thông, Thương mại điện tử hoặc ngành liên quan. Có khả năng sáng tạo, nắm bắt trend nhanh. Tiếng Anh cơ bản từ 550 Toeic trở lên (hoặc các bằng cấp tiếng anh tương đương). Quan tâm hoặc từng biết đến mô hình POD là một lợi thế. Có kỹ năng tìm kiếm, research thị trường cơ bản. Biết sử dụng Canva, CapCut hoặc phần mềm chỉnh sửa cơ bản là lợi thế. Tinh thần học hỏi cao, cầu tiến và chủ động trong công việc.
Kỹ năng chuyên môn: [''Biết sử dụng Canva'', ''Biết sử dụng CapCut'', ''Phần mềm chỉnh sửa cơ bản'']
Kỹ năng mềm: [''Khả năng sáng tạo'', ''Nắm bắt trend nhanh'', ''Kỹ năng tìm kiếm'', ''Research thị trường cơ bản'', ''Tinh thần học hỏi cao'', ''Cầu tiến'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được đào tạo từ đầu theo lộ trình cụ thể'', ''Mentor hướng dẫn 1:1'', ''Làm việc trong môi trường thực tế - cá tính, học nhanh'', ''Lộ trình thăng tiến rõ ràng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (442, 8, 7, 'Nhà thiết kế đồ họa thực tập Thương mại điện tử', 'Thiết kế các ấn phẩm branding và marketing cho hoạt động e-commerce: Thiết kế banner, poster, visual cho các website và sàn thương mại điện tử. Tạo product image, lifestyle photo cho sản phẩm ecommerce. Thiết kế packaging, nhãn mác sản phẩm. Xây dựng key visual (KV) và định hướng hình ảnh cho các campaign marketing online. Thiết kế ấn phẩm truyền thông đa kênh: Các ấn phẩm social media (Facebook, TikTok...) như post, story, banner. Landing page, onepage, slide presentation. Hỗ trợ các hoạt động branding: Tham gia brainstorm ý tưởng creative cho campaign. Thiết kế template cho các hoạt động marketing định kỳ. Thực hiện các công việc khác theo sự phân công của mentor/quản lý trực tiếp.', 'Trình độ học vấn: Sinh viên năm 3, 4 hoặc mới tốt nghiệp các ngành: Thiết kế đồ họa, Mỹ thuật ứng dụng, Marketing, hoặc các ngành liên quan. Có portfolio thể hiện khả năng thiết kế (bắt buộc). Kỹ năng chuyên môn: Sử dụng thành thạo Adobe Photoshop, Illustrator. Có kiến thức cơ bản về Figma, Canva là lợi thế. Có khả năng làm việc với hình ảnh sản phẩm, chỉnh sửa ảnh chuyên nghiệp. Kỹ năng mềm: Có tư duy sáng tạo và khả năng thích ứng nhanh. Không yêu cầu kinh nghiệm. Có kinh nghiệm thiết kế freelance, dự án cá nhân hoặc tham gia các cuộc thi thiết kế là lợi thế.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'', ''Figma'', ''Canva'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Khả năng thích ứng nhanh'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '8.0 - 10.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:15), Thứ 7 (từ 08:30 đến 12:00)', '[''Trợ cấp thực tập'', ''Hỗ trợ chi phí ăn trưa và đi lại'', ''Được mentoring bởi senior designer và marketing manager'', ''Tham gia các dự án thực tế'', ''Môi trường làm việc trẻ trung, năng động'', ''Được đào tạo về quy trình thiết kế chuyên nghiệp'', ''Cơ hội được offer làm việc chính thức sau khi hoàn thành thực tập xuất sắc'', ''Được cấp chứng nhận hoàn thành thực tập'', ''Tham gia các khóa đào tạo, workshop nâng cao kỹ năng'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (443, 9, 7, 'Partime freelancer', 'Freelancer làm việc nửa ngày tại văn phòng. Làm theo sự chỉ đạo công việc cụ thể của lãnh đạo (bao gồm tìm kiếm khách hàng trực tuyến trên mạng xã hội và tuyển dụng trực tuyến…). Tiếp xúc với các ngành nghề về bất động sản và tài chính ngân hàng.', 'Có laptop cá nhân, năng động, sáng tạo. Đã có kinh nghiệm kinh doanh online là một lợi thế. Có kiến thức về đăng bài bán hàng/tuyển dụng trên các hội nhóm facebook. Biết vận dụng các công cụ marketing trên các nền tảng mạng xã hội để phục vụ công việc hiệu quả. Đã tốt nghiệp đại học hoặc đang đi học đại học.
Kỹ năng chuyên môn: [''Kiến thức về đăng bài bán hàng/tuyển dụng trên các hội nhóm facebook'', ''Sử dụng các công cụ marketing trên các nền tảng mạng xã hội'']
Kỹ năng mềm: [''Năng động'', ''Sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 18000000.00, '10.0 - 18.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Mức lương cứng: 3 triệu + hoa hồng kinh doanh upto 10-15 triệu/tháng'', ''Công việc nửa ngày, linh động thời gian'', ''Được học hỏi các kiến thức về bất động sản và tài chính ngân hàng'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (444, 10, 7, 'Sales Marketing (Part-Time)', 'Tìm kiếm, cập nhật thông tin chi tiết về khách hàng, đối tác có nhu cầu sử dụng các dịch vụ marketing trên tiktok (xây kênh, vận hành shop, chạy ads) từ nhiều nguồn. Phối hợp với bộ phận account và Plan marketing lên kế hoạch, giải pháp sơ bộ phù hợp với mục tiêu kinh doanh, truyền thông của khách hàng để có thể mời được khách hàng sử dụng dịch vụ. Thực hiện các nghiệp vụ kinh doanh: Báo giá, đàm phán, ký kết hợp đồng & chăm sóc khách hàng. Phối hợp cùng bộ phận khác nhằm mang đến lợi ích và hiệu quả tối đa trong triển khai dự án với khách hàng. Quản lý dữ liệu khách hàng theo sự phân công từ bộ phận quản lý. Duy trì phát triển mạng lưới khách hàng, đối tác.', 'Sinh viên năm 3, năm cuối các trường Đại học/Cao đẳng khối ngành QTKD, Marketing. Có đam mê với công việc sale, marketing sáng tạo. Tự tin trong giao tiếp. Có kỹ năng thuyết phục là điểm cộng lớn. Khả năng tổ chức công việc và quản lý thời gian tốt. Khả năng giao tiếp rành mạch, rõ ràng. Có thái độ chủ động, ham học hỏi và có ý thức nâng cao kiến thức và kinh nghiệm.
Kỹ năng mềm: [''Tự tin trong giao tiếp'', ''Kỹ năng thuyết phục'', ''Khả năng tổ chức công việc'', ''Quản lý thời gian tốt'', ''Giao tiếp rành mạch, rõ ràng'', ''Thái độ chủ động'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '2.0 - 2.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00), Sáng thứ 7 (8:30-12h)', '[''Lương và Thưởng theo năng lực và chất lượng công việc'', ''Hoa hồng dự án khi đạt KPIs'', ''Được đào tạo chuyên sâu về chiến lược, kế hoạch marketing'', ''Làm việc trực tiếp với TikTok'', ''Môi trường năng động'', ''Hướng dẫn từ đầu nếu chưa có kinh nghiệm'', ''Chế độ phúc lợi đầy đủ theo quy định của công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (445, 2, 7, 'Thực Tập Sinh Content Marketing Part Time', '- Lên kế hoạch và trực tiếp sản xuất nội dung và hình ảnh, chia sẻ thông tin hữu ích về tiếng Anh IELTS - Cập nhật tin tức phù hợp với các fanpage, TikTok của công ty - Bắt trend, sáng tạo kịch bản, nội dung, concept quay của video viral, đáp ứng nhu cầu hữu ích trong cuộc sống. - Quản lý các trang fanpage facebook, TikTok của công ty. - Duyệt & trả lời nội dung bình luận. - Check lại nội dung video và chỉnh sửa (nếu có). Báo cáo định kỳ: Cập nhật, báo cáo công việc theo quy định & khi được yêu cầu. Công việc khác: Yêu cầu chuẩn chỉnh về hình ảnh, tác phong đáp ứng tiêu chí đại sứ thương hiệu của Tập đoàn.', 'Kinh nghiệm: KHÔNG YÊU CẦU KINH NGHIỆM (Ưu tiên đã từng có kinh nghiệm xây dựng, sản xuất Content viral TikToK hoặc quản trị page) Chứng chỉ: Tối thiểu IELTS 6.0 hoặc chứng chỉ tương đương (IELTS, TOEIC,…) Thái độ, tố chất: - Trung thực, nhiệt tình, có trách nhiệm với công việc. - Tâm huyết, có tinh thần học hỏi và phát triển bản thân, gắn bó và yêu thích sự đổi mới sáng tạo. Yêu cầu: - Cẩn thận, tỉ mỉ. - Có định hướng phát triển sâu trong lĩnh vực Marketing.
Kỹ năng chuyên môn: [''Sáng tạo nội dung'', ''Nghiên cứu từ khóa'', ''Viết Lách Seo Cơ Bản'', ''Sử Dụng Thành Thạo Các Phần Mềm Văn Phòng (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Trung thực'', ''Nhiệt tình'', ''Có trách nhiệm với công việc'', ''Tâm huyết'', ''Có tinh thần học hỏi và phát triển bản thân'', ''Gắn bó và yêu thích sự đổi mới sáng tạo'', ''Cẩn thận'', ''Tỉ mỉ'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.5 - 5.5 triệu', 'Thứ 2 - sáng thứ 7 (Từ 8h30 – 12h00, 13h30 - 17h30)', '[''Được đào tạo về cách xây dựng đa dạng các loại hình content: content SEO, Content viral, content quảng cáo'', ''Được đào tạo chuyên sâu về Digital Marketing'', ''Thưởng hiệu quả làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (446, 3, 7, 'Cộng Tác Viên Content Marketing Short Clip', '- Lên kế hoạch và trực tiếp sản xuất nội dung và hình ảnh, chia sẻ thông tin hữu ích về tiếng Anh IELTS - Cập nhật tin tức phù hợp với các fanpage, TikTok của công ty - Bắt trend, sáng tạo kịch bản, nội dung, concept quay của video viral, đáp ứng nhu cầu hữu ích trong cuộc sống. - Quản lý các trang fanpage facebook, TikTok của công ty. - Duyệt & trả lời nội dung bình luận. - Check lại nội dung video và chỉnh sửa (nếu có). Báo cáo định kỳ: Cập nhật, báo cáo công việc theo quy định & khi được yêu cầu. Công việc khác: Yêu cầu chuẩn chỉnh về hình ảnh, tác phong đáp ứng tiêu chí đại sứ thương hiệu của Tập đoàn.', 'Kinh nghiệm: KHÔNG YÊU CẦU KINH NGHIỆM (Ưu tiên đã từng có kinh nghiệm xây dựng, sản xuất Content viral TikToK hoặc quản trị page) Chứng chỉ: Tối thiểu IELTS 6.0 hoặc chứng chỉ tương đương (IELTS, TOEIC,…) Thái độ, tố chất: - Trung thực, nhiệt tình, có trách nhiệm với công việc. - Tâm huyết, có tinh thần học hỏi và phát triển bản thân, gắn bó và yêu thích sự đổi mới sáng tạo. Yêu cầu: - Cẩn thận, tỉ mỉ. - Có định hướng phát triển sâu trong lĩnh vực Marketing.
Kỹ năng chuyên môn: [''Sản xuất nội dung viral TikTok'', ''Quản trị fanpage'']
Kỹ năng mềm: [''Trung thực'', ''Nhiệt tình'', ''Có trách nhiệm với công việc'', ''Tâm huyết'', ''Có tinh thần học hỏi và phát triển bản thân'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.5 - 5.5 triệu', 'Thứ 2 - sáng thứ 7 (Từ 8h30 – 12h00, 13h30 - 17h30)', '[''Được đào tạo về cách xây dựng đa dạng các loại hình content'', ''Được đào tạo chuyên sâu về Digital Marketing'', ''Thưởng hiệu quả làm việc'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (447, 7, 7, 'Thực Tập Sinh MEDIA', '- Tham gia lên ý tưởng xây dựng kịch bản video / tham gia quay chụp các dự án đã hoàn thiện của công ty - Lên thiết kế, chỉnh sửa hình ảnh để minh họa bài viết, cho video clip quay và dựng. - Hỗ trợ bộ phận sản xuất trong việc đưa ra ý tưởng và kế hoạch sản xuất video - Hỗ trợ chuẩn bị và thực hiện tác vụ quay, đảm bảo chất lượng source video tốt nhất - Phối hợp với đội ngũ Video Editor, theo dõi và hỗ trợ xử lý hậu kỳ nhằm đưa ra sản phẩm tốt nhất - KPIs được tính dựa trên số lượng video sản xuất - Báo cáo trực tiếp cho leader. - Thực hiện các công việc khác được giao', '- Đi làm 2 ngày/tuần tại văn phòng, các ngày còn lại làm online (Có thể sắp xếp thời gian linh hoạt theo lịch học cá nhân) - Sử dụng thông thạo các phần mềm: Premiere, Illustrator, Photoshop, Capcut,... - Hiểu về truyền thông, sử dụng thành thạo máy quay, máy chụp hình, các phần mềm đồ họa và dựng video. - Có gu thẩm mỹ, tư duy hình ảnh tốt. - Có khả năng thu voice cho các sản phẩm video (có thể sử dụng AI) - Có tinh thần cầu thị, ham học hỏi và phát triển kỹ năng của bản thân. - Trẻ trung, năng động, chịu khó học hỏi các xu hướng thị trường.
Kỹ năng chuyên môn: [''Premiere'', ''Illustrator'', ''Photoshop'', ''Capcut'']
Kỹ năng mềm: [''Có gu thẩm mỹ'', ''Tư duy hình ảnh tốt'', ''Tinh thần cầu thị'', ''Ham học hỏi'', ''Năng động'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 3 (từ 08:00 đến 17:30)', '[''Môi trường thân thiện và năng động'', ''Được đào tạo các kỹ năng trong công việc'', ''Thưởng hấp dẫn theo chính sách công ty, các dịp Lễ Tết'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (448, 8, 7, 'Intern Marketing', 'Lên kế hoạch chăm sóc các nền tảng mạng xã hội được công ty cung cấp. Quản lý các nền tảng mạng xã hội được công ty cung cấp như Website, Tiktok, Facebook, Zalo, Gmap, v.v.. Thực hiện các công việc khác theo yêu cầu của người quản lý.', 'Sinh viên năm 4 hoặc mới ra trường chuyên ngành liên quan đến ngành marketing hoặc quản trị kinh doanh. Sử dụng thành thạo máy tính và các phần mềm văn phòng. Kỹ năng giao tiếp, truyền đạt tốt, có khả năng kết nối và xây dựng mối quan hệ. Có khả năng tự nghiên cứu, học hỏi từ tài liệu công ty cung cấp và sáng tạo trong công việc. Tư duy cầu tiến, chủ động trong công việc và ham học hỏi. Đặc biệt: Đam mê lĩnh vực Marketing, bán hàng và mong muốn thử thách bản thân, vượt qua giới hạn bản thân. Có tinh thần trách nhiệm với công việc cao. Ưu tiên ứng biết sử dụng canva, capcut cơ bản. Yêu cầu thực tập tối thiểu 6 tháng.
Kỹ năng chuyên môn: [''Sử dụng thành thạo máy tính'', ''Các phần mềm văn phòng'', ''Canva (ưu tiên)'', ''Capcut (ưu tiên)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Truyền đạt tốt'', ''Khả năng kết nối và xây dựng mối quan hệ'', ''Tư duy cầu tiến'', ''Chủ động trong công việc'', ''Ham học hỏi'', ''Tinh thần trách nhiệm cao'']', 'INTERNSHIP', 'ONSITE', 'thanh hoá', 'Thanh Hóa', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được đào tạo lập kế hoạch Marketing'', ''Được đào tạo kiến thức về Digital Marketing, Sales, Trade'', ''Được rèn luyện các kỹ năng chuyên môn qua các dự án thực tế của công ty'', ''Được hỗ trợ dấu mộc thực tập'', ''Có cơ hội được trở thành nhân viên chính thức sau tốt nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (449, 9, 7, 'Thực Tập Sinh Marketing', 'Phân tích khách hàng nhằm xây dựng proposal theo mong muốn của khách hàng. Quản lý, giám sát hiệu quả hoạt động sản xuất nội dung. Hỗ trợ công tác tuyển dụng Nhân sự dự án. Thực hiện các công việc khác theo yêu cầu của cấp trên.', '- Có chuyên ngành và đam mê trong ngành Marketing - Có thể làm việc full-time trong tối thiểu 3 tháng - Ưu tiên các bạn có mong muốn phát triển nhiều kỹ năng trong ngành Marketing. - Lưu ý: Thích ứng với môi trường công ty nhỏ.
Kỹ năng chuyên môn: [''Marketing Cơ Bản'', ''Social Media Marketing'', ''Viết Nội Dung'', ''Thiết Kế Đồ Họa Cơ Bản (photoshop, Canva)'', ''Phân Tích Dữ Liệu Cơ Bản'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được thực làm: lập kế hoạch, triển khai dự án với tập đoàn lớn...'', ''Được hưởng các chế độ Bảo hiểm theo quy định pháp luật khi vào chính thức.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (450, 10, 7, 'Intern Marketing', 'Áp dụng kiến thức marketing vào các dự án thực tế. Làm quen với quy trình làm việc, công cụ và văn hóa doanh nghiệp. Tìm hiểu về bộ nhận diện thương hiệu và các quy chuẩn truyền thông. Soạn thảo nội dung cho mạng xã hội, email, blog và đề xuất chiến dịch. Thực hiện các công việc thiết kế cơ bản, dựng video và lên lịch đăng bài. Báo cáo công việc hàng tuần kèm phần tự đánh giá.', 'Năng động, nhiệt tình. Nắm bắt xu hướng nhanh, cập nhật các tin tức xã hội thường xuyên. Thích sử dụng mạng xã hội. Chủ động và ham học hỏi. Tư duy linh hoạt, sẵn sàng tiếp nhận phản hồi. Quản lý thời gian tốt, đảm bảo tiến độ công việc.
Kỹ năng chuyên môn: [''Social Media Marketing'', ''Phân tích dữ liệu'', ''Nghiên Cứu Thị Trường'', ''Viết Nội Dung Marketing Cơ Bản'']
Kỹ năng mềm: [''Năng động'', ''Nhiệt tình'', ''Chủ động'', ''Ham học hỏi'', ''Tư duy linh hoạt'', ''Quản lý thời gian tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 17:00)', '[''Được đào tạo bài bản từ A đến Z'', ''Tham gia vào nhiều mảng: nội dung, thương hiệu, chiến dịch'', ''Được nhận phản hồi thường xuyên'', ''Có cơ hội trở thành cộng tác viên hoặc nhân sự chính thức'', ''Hỗ trợ dấu mộc và nhận xét thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (451, 2, 7, 'Người tạo nội dung thực tập', 'Tham gia xây dựng nội dung truyền thông cho nền tảng kết nối việc làm nước ngoài (tại các thị trường như Nhật Bản, Hàn Quốc, Đức, Đài Loan, v.v.). Viết bài cho các kênh social media (Facebook, TikTok, Instagram, LinkedIn...), bài blog, bài PR giới thiệu chương trình/tin tuyển dụng. Lên ý tưởng cho các chiến dịch truyền thông hoặc series nội dung định kỳ. Phối hợp với bộ phận thiết kế và video để sản xuất các nội dung đa dạng: ảnh, video ngắn, infographic, v.v. Nghiên cứu insight người lao động và cập nhật các xu hướng truyền thông mới để tối ưu hiệu quả tiếp cận.', 'Là sinh viên năm 4 hoặc mới ra trường các ngành liên quan: Truyền thông, Marketing, Ngôn ngữ, Báo chí, Xã hội học,... Có khả năng viết lách tốt, tư duy logic và sáng tạo. Có hiểu biết hoặc quan tâm đến thị trường lao động quốc tế là một lợi thế. Có trách nhiệm, chủ động trong công việc và tinh thần học hỏi cao. Ưu tiên ứng viên có kinh nghiệm xây dựng nội dung trên các nền tảng mạng xã hội (có thể là fanpage cá nhân, TikTok, blog, v.v.).
Kỹ năng chuyên môn: [''Viết bài cho các kênh social media'', ''Lên ý tưởng cho các chiến dịch truyền thông'', ''Phối hợp với bộ phận thiết kế và video'']
Kỹ năng mềm: [''Khả năng viết lách tốt'', ''Tư duy logic'', ''Sáng tạo'', ''Trách nhiệm'', ''Chủ động trong công việc'', ''Tinh thần học hỏi cao'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Chi phí hỗ trợ thực tập 2.000.000 - 5.000.000 VND'', ''Thưởng bonus theo performance tối thiểu 1.000.000 VND + thưởng KPI'', ''Được hướng dẫn và đào tạo kỹ năng viết content'', ''Cấp giấy chứng nhận thực tập'', ''Cơ hội được giữ lại làm nhân viên chính thức nếu thể hiện tốt'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (452, 3, 7, 'Nhân Viên Livestream Thời Trang Part - Time', 'Tham gia livestream trực tiếp trên các nền tảng (Facebook, TikTok, Shopee Live,...) để giới thiệu, tư vấn sản phẩm cho khách hàng ngày 2 ca, mỗi ca 3-4 tiếng. Tương tác với khách hàng tạo không khí sôi nổi nhằm tăng khả năng bán hàng, giữ chân khách xem live. Hỗ trợ team setup bối cảnh, kiểm tra ánh sáng, góc máy. Chuẩn bị thông tin về sản phẩm trước khi livestream. Đưa ra phản hồi về sản phẩm, cách thức livestream để nâng cao hiệu quả công việc.', 'Độ tuổi 23 – 30. Chiều cao 1m60 - 1m65, size S/M. Ưu tiên ứng viên có kinh nghiệm ít nhất 6 tháng làm mẫu livestream, mẫu ảnh thời trang nữ. Không có kinh nghiệm sẽ được đào tạo. Ngoại hình ưa nhìn, biết diễn xuất bằng gương mặt và hình thể, tự tin trước máy quay. Giọng nói rõ ràng, truyền cảm.
Kỹ năng chuyên môn: [''Sử dụng thành thạo các phần mềm Livestream (obs, Facebook Live, Instagram Live, Tiktok Live...)'']
Kỹ năng mềm: [''Giao tiếp lưu loát'', ''Tự tin trước camera'', ''Kỹ năng thuyết trình'', ''Hiểu biết về thời trang'', ''Khả năng xử lý tình huống'', ''Ứng biến linh hoạt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '7.5 - 15.0 triệu', 'Thứ 2 - Thứ 7 (từ 10:30 đến 14:30) và (từ 19:30 đến 23:00)', '[''Phụ cấp ăn trưa 30.000đ/ngày'', ''Phụ cấp gửi xe'', ''Lương tháng thứ 13'', ''Hưởng các chế độ đãi ngộ theo luật lao động như: BHXH, BHYT, BHTN'', ''Chế độ phúc lợi mở rộng khác như: Sinh nhật, thăm quan, du lịch, team building'', ''Môi trường làm việc năng động, chuyên nghiệp, có nhiều cơ hội thăng tiến'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (453, 7, 7, 'Học Việc Vận Hành Sàn Thương Mại Điện Tử', 'Cập nhật và theo dõi các sản phẩm, dịch vụ trên sàn Shopee. Hỗ trợ các hoạt động niêm yết sản phẩm mới, quản lý tồn kho và hình ảnh sản phẩm trên nền tảng. Đảm bảo tất cả các sản phẩm trên sàn đều đáp ứng tiêu chuẩn của Shopee, đồng thời hỗ trợ giải quyết các vấn đề liên quan đến danh mục sản phẩm. Tham gia vào việc chuẩn bị và triển khai các chiến dịch quảng cáo, khuyến mãi của Shopee (Flash Sale, mã giảm giá, chương trình Tết, Black Friday, etc.). Hỗ trợ xây dựng nội dung cho các chương trình quảng bá và chương trình khuyến mãi. Giám sát kết quả của các chiến dịch và báo cáo kết quả cho bộ phận quản lý. Thu thập và phân tích dữ liệu về hoạt động bán hàng, khách hàng và các chỉ số hiệu suất khác của sàn Shopee. Hỗ trợ các hoạt động báo cáo định kỳ về tình hình kinh doanh, hiệu quả của các chiến dịch khuyến mãi và các vấn đề vận hành khác.', 'Là sinh viên các trường đại học Kinh Tế, Thương Mại, Ngoại Thương hoặc các trường liên quan. Có sự quan tâm đặc biệt đến thương mại điện tử và mong muốn phát triển toàn diện trong lĩnh vực này. Tham gia các câu lạc bộ hoặc hoạt động liên quan đến thương mại điện tử là một lợi thế. Không yêu cầu kinh nghiệm, nhưng yêu cầu ứng viên là người chủ động, ham học hỏi, có tư duy giải pháp và làm việc nhóm tốt. Sẵn sàng được đào tạo bài bản và nhận cơ hội phát triển từ thực tập sinh lên thử việc và chính thức.
Kỹ năng mềm: [''Chủ động'', ''Ham học hỏi'', ''Tư duy giải pháp'', ''Làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Lương cứng 4tr + % doanh thu + thưởng (nếu có)'', ''Được đào tạo bài bản từ đầu'', ''Gửi xe miễn phí'', ''Du lịch hàng năm, liên hoan hàng tháng'', ''Được đóng đầy đủ các loại bảo hiểm theo quy định của nhà nước'', ''Lên nhân viên chính thức sau 1-2 tháng học việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (454, 8, 7, 'Thực Tập Sinh Content Tiktok', 'Xây dựng và quản lý các kênh Social Media (Tiktok) của dự án. Lên kịch bản và sáng tạo video Tiktok, ứng dụng cho Short Youtube. Sử dụng các công cụ sáng tạo video AI công ty cung cấp tạo các video AI. Có khả năng bắt trend, nắm bắt xu hướng mới của các kênh. Nghiên cứu các nội dung viral, hấp dẫn để áp dụng vào kênh mình quản lý. Thực hiện các công việc liên quan khác theo yêu cầu của cấp Quản lý.', 'Đang theo học hoặc tốt nghiệp các chuyên ngành Báo chí - Truyền Thông,, Marketing,... Biết sử dụng các công cụ chỉnh sửa video, hình ảnh cơ bản như Capcut, Canva,... Có kỹ năng biên tập, sáng tạo thông điệp truyền thông, concept, content marketing. Tư duy content tốt, sáng tạo, hướng người dùng, biết phân tích tâm lý hành vi của người dùng. Tinh thần trách nhiệm cao, chủ động, nhanh nhẹn trong công việc.
Kỹ năng chuyên môn: [''Biết sử dụng các công cụ chỉnh sửa video, hình ảnh cơ bản như Capcut, Canva'']
Kỹ năng mềm: [''Kỹ năng biên tập'', ''Sáng tạo thông điệp truyền thông'', ''Tư duy content tốt'', ''Sáng tạo'', ''Hướng người dùng'', ''Phân tích tâm lý hành vi của người dùng'', ''Tinh thần trách nhiệm cao'', ''Chủ động'', ''Nhanh nhẹn trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Môi trường làm việc hiện đại, chuyên nghiệp, có sự thăng tiến, đánh giá định kỳ'', ''Được tham gia các chương trình đào tạo phát triển năng lực và kỹ năng chuyên môn'', ''Được xét duyệt nhân viên chính thức sau khi ứng viên tốt nghiệp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (455, 9, 7, 'Thực Tập Sinh Marketing', '- Tư vấn khách hàng. - CSKH trên Zalo. - Xây đa kênh truyền thông: Facebook, Tiktok, Youtube... - Không yêu cầu kinh nghiệm, sẽ được đào tạo từ A-Z, cầm tay chỉ việc tới khi thạo việc; đặt mục tiêu KPIs phù hợp với năng lực. - Có laptop cá nhân. - Trung thực, có tinh thần trách nhiệm - Chăm chỉ, ham học hỏi có chí tiến thủ - Có khả năng giao tiếp, đàm phán tốt.', '- Có laptop cá nhân. - Tốt nghiệp chuyên ngành marketing, kinh doanh hoặc có liên quan - Trung thực, có tinh thần trách nhiệm - Chăm chỉ, ham học hỏi có chí tiến thủ - Có khả năng giao tiếp, đàm phán tốt. - Yêu thích lĩnh vực kinh doanh càng tốt
Kỹ năng chuyên môn: [''Social Media Marketing'', ''Phân tích dữ liệu'', ''Nghiên Cứu Thị Trường'', ''Viết Nội Dung Marketing Cơ Bản'']
Kỹ năng mềm: [''Trung thực'', ''Có tinh thần trách nhiệm'', ''Chăm chỉ'', ''Ham học hỏi'', ''Có chí tiến thủ'', ''Có khả năng giao tiếp'', ''Đàm phán tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '3.0 - 15.0 triệu', 'Thứ 2 - Thứ 7 (từ 07:30 đến 17:00)', '[''Được đào tạo để nâng cao kiến thức, kỹ năng'', ''Môi trường làm việc trẻ trung, đầy đủ tiện nghi'', ''Được hưởng đầy đủ các chế độ phúc lợi Bảo hiểm'', ''Tham gia các hoạt động sinh nhật, party, du lịch, hiếu hỉ'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (456, 10, 7, 'Nhân Viên Digital Makerting Google Ads', 'Set chiến dịch google shopping, Set chiến dịch google map, Tăng traffic tự nhiên cho website', 'Yêu cầu ứng viên: Kiến thức về SEO, Sẵn sàng tìm hiểu kiến thức mới, Đam mê SEO
Kỹ năng chuyên môn: [''Kiến thức về SEO'']
Kỹ năng mềm: [''Sẵn sàng tìm hiểu kiến thức mới'', ''Đam mê SEO'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Thưởng KPI'', ''Thưởng trực tiếp theo hiệu quả công việc'', ''Đóng dấu đỏ thực tập/ làm việc tại công ty'', ''Chứng nhận có đóng góp cho công ty'', ''Chứng nhận tham gia Global Marketing'', ''Chứng nhận tham gia Triển Lãm Quốc Tế của công ty'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (457, 2, 7, 'Thực Tập Sinh Content Marketing', 'Đề xuất đóng góp ý kiến và tham gia sáng tạo kịch bản/nội dung cho chiến dịch truyền thông trên các mạng xã hội (Tiktok, Facebook, Youtube, Instagram). Tham gia lên kế hoạch các chiến dịch Marketing của công ty. Viết bài content SEO. Viết bài PR khi công ty có kế hoạch đi báo chí. Hỗ trợ triển khai các sự kiện, hoạt động của công ty.', 'Có laptop cá nhân khi đi làm. Sinh viên chuyên ngành Truyền thông, Marketing, Quan hệ Công chúng, Truyền thông đa phương tiện, QTKD,... Năng động, ham học hỏi, có trách nhiệm với công việc được giao. Tin học văn phòng cơ bản. Kỹ năng làm việc nhóm tốt và tuân thủ deadline công việc. UV có ngoại hình và ăn nói tốt là một lợi thế. Ưu tiên UV biết cơ bản Tiếng Anh.
Kỹ năng chuyên môn: [''Tin học văn phòng cơ bản'']
Kỹ năng mềm: [''Năng động'', ''Ham học hỏi'', ''Có trách nhiệm với công việc'', ''Kỹ năng làm việc nhóm tốt'', ''Tuân thủ deadline'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '0.5 - 1.0 triệu', 'Từ Thứ 2 - Thứ 6 (8h00-17h00); Thứ 7 (buổi sáng)', '[''Hỗ trợ xăng xe đi lại'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Cơ hội được tuyển dụng vào các vị trí chính thức'', ''Thực tập được chỉ dẫn tận tình'', ''Được cấp giấy chứng nhận, mộc, số liệu cho báo cáo thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (458, 3, 7, 'Nhân Viên Livestream', 'Thực hiện livestream bán hàng, giao lưu khách hàng định kỳ trên các nền tảng như Facebook, TikTok, ... nhằm giới thiệu và quảng bá dịch vụ/ sản phẩm vàng, trang sức đến khách hàng. Truyền thông hình ảnh thương hiệu thông qua nội dung livestream hấp dẫn, gần gũi và chuyên nghiệp. Tư vấn, giải đáp thắc mắc về sản phẩm, dịch vụ và các chính sách mua bán, bảo hành, thanh toán trong thời gian livestream. Phối hợp với bộ phận Marketing lên kế hoạch chủ đề, sản phẩm, kịch bản livestream theo từng chiến dịch bán hàng. Tạo dựng mối quan hệ với khách hàng, khuyến khích tương tác và thu hút người xem quay lại livestream. Theo dõi, tổng hợp số liệu (lượt xem, tương tác, doanh thu...) sau mỗi buổi live và đề xuất cải tiến. Hỗ trợ nội dung trên nền tảng số như quay video ngắn, chụp ảnh sản phẩm, lên trend nếu cần.', 'Ngoại hình ưa nhìn, giao tiếp linh hoạt, có khả năng nói chuyện cuốn hút, tự tin trước ống kính. Có kiến thức cơ bản về fintech, vàng, trang sức là một lợi thế (không có sẽ được đào tạo). Có kinh nghiệm livestream bán hàng là lợi thế, đặc biệt trên các nền tảng TikTok, Facebook. Có tư duy bán hàng, biết nắm bắt tâm lý khách hàng, xử lý tình huống linh hoạt. Nhiệt tình, kiên nhẫn, thích tương tác với khách hang. Có kỹ năng sử dụng điện thoại, mạng xã hội, nền tảng livestream.
Kỹ năng chuyên môn: [''Kỹ năng livestream'', ''Sử dụng điện thoại'', ''Mạng xã hội'']
Kỹ năng mềm: [''Giao tiếp linh hoạt'', ''Tư duy bán hàng'', ''Xử lý tình huống linh hoạt'', ''Nhiệt tình'', ''Kiên nhẫn'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Thu nhập cạnh tranh'', ''Cơ hội đào tạo chuyên sâu'', ''Môi trường làm việc trẻ trung'', ''Hỗ trợ công cụ livestream'', ''Thưởng hiệu quả theo từng chiến dịch'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (459, 7, 7, 'NHÂN VIN LiveStream/ Host LiveStream Bán thời gian', '- Lên kịch bản, thực hiện ghi hình và livestream trên các nền tảng TMĐT tại Studio. - Giới thiệu các sản phẩm của thương hiệu, chương trình khuyến mãi, sự kiện đặc biệt và tư vấn khách hàng trực tiếp trên livestream. - Tạo không khí buổi livestream luôn sôi nổi, nhiệt tình hướng dẫn khách hàng mua hàng và tương tác với khách hàng. - Đảm bảo hình ảnh, nội dung livestream đúng với các tiêu chí của nhãn hàng, đúng thông tin sản phẩm. - Báo cáo tình hình, tiến độ công việc trình cấp trên. - Có thể đưa ra đề xuất cải thiện, nâng cao chất lượng công việc.', '- Nữ, tuổi từ 20-28 - Đã có kinh nghiệm livestream tối thiểu 2 tháng ở ngành hàng mỹ phẩm trên các nền tảng thương mại điện tử. - Ngoại hình ưa nhìn, có kiến thức về trang điểm, mỹ phẩm, biết tự makeup. - Có khả năng nói lưu loát, kỹ năng xử lý tình huống và giải quyết vấn đề tốt. - Quản lý công việc hiệu quả khi làm việc nhóm và làm việc cá nhân. - Chủ động, nhiệt tình, chăm chỉ, có trách nhiệm với công việc.
Kỹ năng chuyên môn: [''Sử dụng phần mềm livestream (OBS, Streamlabs, v.v.)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng xử lý tình huống'', ''Quản lý công việc hiệu quả'', ''Chủ động'', ''Nhiệt tình'', ''Chăm chỉ'', ''Có trách nhiệm với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '10.0 - 15.0 triệu', '2-3 giờ/ca livestream, 1 ngày có thể làm 2 ca, 1 tuần làm 4-5 ngày', '[''Chế độ ăn nhẹ tại Studio Livestream'', ''Chế độ trà chiều: 60.000/tháng'', ''Chế độ học tập: tham gia các khóa học đào tạo về chuyên môn'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (460, 8, 7, 'Cộng Tác Viên Video Editor (Remote)', 'Phối hợp cùng Media planner nghiên cứu xu hướng, sở thích, nhu cầu của người dùng mục tiêu. Từ đó sáng tạo video, cắt ghép, chỉnh sửa theo kịch bản có sẵn. Hỗ trợ team Media xây dựng các phân đoạn dùng trong các sản phẩm video truyền thông. Chỉnh sửa video theo yêu cầu, đảm bảo chất lượng nội dung phù hợp. Đảm bảo tiến độ công việc theo kế hoạch và theo sự phân công của công ty.', 'Tốt nghiệp từ các trường về đào tạo truyền thông đa phương tiện. Có kiến thức và có thể sử dụng thành thạo phần mềm dựng video như Adobe Premiere, CapCut, và biết cơ bản về Adobe Photoshop, Illustrator. Kỹ năng đọc hiểu kịch bản (brief), phát triển ý tưởng, sáng tạo phù hợp với yêu cầu của sản phẩm và dự án. Có nền tảng tư duy thẩm mỹ, bố cục khung hình, điện ảnh là 1 lợi thế. Yêu thích sáng tạo trong chủ đề gia đình, mẹ và bé. Năng động, nhiệt tình, kiên trì, chịu khó, có khả năng chịu áp lực. Có tinh thần nghiên cứu học hỏi, nâng cao nghiệp vụ.
Kỹ năng chuyên môn: [''Adobe Premiere'', ''CapCut'', ''Adobe Photoshop'', ''Adobe Illustrator'']
Kỹ năng mềm: [''Năng động'', ''Nhiệt tình'', ''Kiên trì'', ''Chịu khó'', ''Có khả năng chịu áp lực'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm việc linh hoạt', '[''Thưởng hiệu suất theo quy định của công ty'', ''Hỗ trợ chi phí học tập nâng cao nghiệp vụ ngoài doanh nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (461, 9, 7, 'Thực Tập Sinh Thiết Kế Đồ Họa', 'Tham gia xử lý các công việc phát sinh tại phòng marketing, media, nội dung. Huấn luyện các kỹ năng để thực hiện công việc thiết kế, dựng clip. Một số công việc khác có liên quan trực tiếp đến marketing, thiết kế đồ họa. Được đào tạo, hướng dẫn, chia sẽ kinh nghiệm, kiến thức marketing trong quá trình thực tập.', 'Giới tính: Nam/Nữ. Là sinh viên năm 3, 4 các trường đại học và cao đẳng chuyên ngành quản trị kinh doanh, thiết kế, marketing. Trung thực, nhiệt tình và có tinh thần trách nhiệm. Thực tập toàn thời gian trong giờ hành chính tại văn phòng Công ty trong khoảng thời gian ít nhất là 03 tháng.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'', ''Adobe InDesign'', ''Thiết kế đồ họa'', ''Kiến Thức Về Màu Sắc'']
Kỹ năng mềm: [''Trung thực'', ''Nhiệt tình'', ''Có tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung'', ''Được hỗ trợ dấu mộc thực tập'', ''Cơ hội trở thành nhân viên chức thức sau thời gian thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (462, 10, 7, 'Nội dung tiếp thị thực tập', 'Chịu trách nhiệm về chất lượng công việc nội dung sáng tạo. Xây dựng và thể hiện câu chuyện, ý tưởng sáng tạo dựa trên phân tích insight và nhu cầu từng nhóm khách hàng, từ đó đề xuất các chiến thuật sáng tạo nội dung (video clip, photoshoot, PR, hoạt động tương tác social như minigame, Booking báo chí, Booking KOL/KOC, seeding...) nhằm đạt mục tiêu truyền thông của dự án. Xây dựng kế hoạch và viết nội dung cho các kênh digital của công ty do Leader giao: website, fanpage, social media ads, ... Viết kịch bản video, ý tưởng nội dung layout webiste và các ấn phẩm marketing. Thực hiện các nhiệm vụ về content marketing mà cấp trên yêu cầu.', 'Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp các chuyên ngành liên quan. Nắm rõ kiến thức digital marketing cơ bản. Có mục tiêu phát triển lâu dài ở vị trí cao hơn trong môi trường Agency Marketing. Thái độ làm việc nghiêm túc. Ưu tiên ứng viên có thể đi làm full-time.
Kỹ năng chuyên môn: [''Digital marketing'']
Kỹ năng mềm: [''Thái độ làm việc nghiêm túc'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 3000000.00, '0.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được đào tạo và hướng dẫn bởi đội ngũ thiết kế giàu kinh nghiệm'', ''Có cơ hội tham gia vào các dự án thực tế, tích lũy kinh nghiệm làm việc trong môi trường chuyên nghiệp'', ''Hỗ trợ dấu mộc thực tập và chứng nhận sau khi kết thúc kỳ thực tập'', ''Được nhận trợ cấp 500.000 - 3.000.000 trong quá trình thực tập'', ''Văn hóa doanh nghiệp luôn muốn hướng tới cho nhân viên có được đức tính: tham vọng - tự tin - khiêm tốn - đáng tin cậy - lạc quan - chăm chỉ - sáng tạo - trung thực'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (463, 2, 7, 'Thực Tập Sinh Content Creator', 'Tham gia lên ý tưởng và sản xuất nội dung sáng tạo cho các kênh truyền thông của công ty và khách hàng (Facebook, Instagram, TikTok, YouTube, Website, v.v.). Phối hợp với team Marketing để phát triển nội dung cho các chiến dịch truyền thông và quảng cáo. Tạo và chỉnh sửa các dạng nội dung đa phương tiện như bài viết, hình ảnh, video, infographic. Thực hiện nghiên cứu từ khóa và xu hướng nội dung để đề xuất các ý tưởng mới và phù hợp. Đảm bảo nội dung đáp ứng các yêu cầu về chất lượng, tính sáng tạo và đúng thời hạn. Hỗ trợ quản lý các kênh truyền thông xã hội, tương tác với cộng đồng online.', 'Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp các chuyên ngành liên quan. Có đam mê với việc sáng tạo nội dung, đặc biệt là trên các nền tảng mạng xã hội. Kỹ năng viết và chỉnh sửa nội dung tốt, có khả năng sáng tạo và tư duy mới mẻ. Biết sử dụng các công cụ chỉnh sửa hình ảnh, video như Photoshop, Canva là một lợi thế. Có khả năng làm việc nhóm, ham học hỏi và chủ động trong công việc.
Kỹ năng chuyên môn: [''Sử dụng các công cụ chỉnh sửa hình ảnh'', ''Sử dụng các công cụ chỉnh sửa video như Photoshop, Canva'']
Kỹ năng mềm: [''Kỹ năng viết và chỉnh sửa nội dung tốt'', ''Khả năng sáng tạo'', ''Tư duy mới mẻ'', ''Khả năng làm việc nhóm'', ''Ham học hỏi'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 8000000.00, '2.0 - 8.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ bảy: 08:00 - 12:00', '[''Được đào tạo và hướng dẫn bởi đội ngũ thiết kế giàu kinh nghiệm'', ''Có cơ hội tham gia vào các dự án thực tế'', ''Hỗ trợ dấu mộc thực tập và chứng nhận sau khi kết thúc kỳ thực tập'', ''Được nhận trợ cấp trong quá trình thực tập'', ''Văn hóa doanh nghiệp luôn muốn hướng tới cho nhân viên có được đức tính: tham vọng - tự tin - khiêm tốn - đáng tin cậy - lạc quan - chăm chỉ - sáng tạo - trung thực'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (464, 3, 7, 'Thực Tập Sinh Trợ Lý Giám Đốc (CEO)', 'Bạn sẽ là trợ lý trực tiếp cho CEO – người đang dẫn dắt công ty phát triển các thương hiệu toàn cầu trên nền tảng thương mại điện tử. Vai trò của bạn bao gồm: Hỗ trợ R&D: Tìm hiểu và tổng hợp thông tin thị trường TMĐT tại Mỹ (Amazon, TikTokShop, Etsy,...), tham gia vào quá trình phát triển sản phẩm mới và cải tiến sản phẩm hiện có. Hỗ trợ Digital Marketing: Tham gia tối ưu hoá listing sản phẩm, Tìm kiếm, sàng lọc và làm việc với đối tác thứ 3, KOC, KOL tại thị trường Mỹ, Viết script kịch bản cho KOC/KOL theo từng loại sản phẩm, Tham gia sáng tạo nội dung cho kênh chính thức của các thương hiệu do Wicom quản lý. Thực hiện các nhiệm vụ khác theo phân công của CEO, với cơ hội tiếp cận đa lĩnh vực trong môi trường startup toàn cầu, năng động.', 'Là sinh viên năm 3 trở lên thuộc khối ngành Luật quốc tế, Kinh tế đối ngoại hoặc các chuyên ngành có liên quan. Là sinh viên năm 3 trở lên các ngành Kinh tế, Marketing hoặc lĩnh vực liên quan. Yêu thích Digital Marketing, có mong muốn làm việc trong môi trường cross-border ecommerce. Tư duy logic tốt, tự chủ, biết ứng dụng AI để phân tích, báo cáo, tạo nội dung. Có kỹ năng quay dựng video, thành thạo CapCut hoặc các ứng dụng tương tự. Có khả năng đọc hiểu tiếng Anh tốt. Trách nhiệm, chủ động, tinh thần học hỏi cao. Ưu tiên ứng viên đam mê kinh doanh và có tinh thần làm chủ.
Kỹ năng chuyên môn: [''Kỹ năng quay dựng video'', ''Thành thạo CapCut hoặc các ứng dụng tương tự'']
Kỹ năng mềm: [''Tư duy logic tốt'', ''Trách nhiệm'', ''Chủ động'', ''Tinh thần học hỏi cao'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Làm việc trực tiếp và được mentorship 1-1 từ CEO'', ''Cơ hội học hỏi thực tế về mô hình kinh doanh thương mại điện tử xuyên biên giới'', ''Được định hướng phát triển nghề nghiệp phù hợp với năng lực và sở thích cá nhân'', ''Nếu thể hiện tốt, có cơ hội trở thành nhân sự chính thức sau thực tập'', ''Hỗ trợ dấu mộc xác nhận thực tập (nếu cần)'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (465, 7, 7, 'Nhân Viên Bán Bánh Parttime Mùa Vụ', 'Tư vấn và bán sản phẩm Trung Thu cho khách hàng. Hỗ trợ khách hàng trong việc lựa chọn sản phẩm phù hợp. Sắp xếp và trưng bày sản phẩm tại cửa hàng. Quản lý và kiểm kê hàng hóa. Xử lý các giao dịch thanh toán. Giải quyết các khiếu nại của khách hàng.', 'Tốt nghiệp Trung học phổ thông hoặc tương đương. Ưu tiên sinh viên. Kinh nghiệm bán hàng hoặc dịch vụ khách hàng là một lợi thế. Kỹ năng giao tiếp tốt và khả năng làm việc nhóm. Thời gian làm việc 6h-21h đăng kí ca linh hoạt 4-8 tiếng hoặc ca 8 tiếng 6h-14h và 13h30-21h30.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '6h-21h, linh hoạt 4-8 tiếng hoặc ca 8 tiếng 6h-14h và 13h30-21h30', '[''Môi trường làm việc năng động, vui vẻ'', ''Quản lý nhiệt tình, gần gũi'', ''Cơ hội gắn bó lâu dài, thăng tiến'', ''Làm việc trong môi trường thơm lừng mùi bánh'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (466, 8, 7, 'Thực Tập Sinh Marketing', 'Thực hiện chỉnh sửa video cơ bản bằng CapCut (hoặc phần mềm khác) để tạo nội dung cho các kênh truyền thông của công ty. Thiết kế hình ảnh đơn giản bằng Canva phục vụ cho các bài đăng và chiến dịch marketing. Hỗ trợ đăng tải và tương tác nội dung lên các nền tảng truyền thông xã hội. Thực hiện các nhiệm vụ khác theo sự phân công của quản lý.', 'Không yêu cầu kinh nghiệm, được đào tạo 100%. Sinh viên đang theo học hoặc đã tốt nghiệp các ngành liên quan đến Marketing, Kinh doanh, Truyền thông hoặc Thiết kế đồ họa. Đam mê, yêu thích lĩnh vực kinh doanh, tư vấn, marketing và chăm sóc khách hàng. Biết sử dụng các công cụ thiết kế ảnh và dụng video cơ bản (Ví dụ: Canva, Capcut, PS, Pre..). Kiên trì, có tinh thần trách nhiệm cao và thái độ làm việc tích cực.
Kỹ năng chuyên môn: [''Canva'', ''CapCut'', ''Photoshop'']
Kỹ năng mềm: [''Kiên trì'', ''Tinh thần trách nhiệm cao'', ''Thái độ làm việc tích cực'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Hỗ trợ xác nhận thực tập'', ''Có thưởng khi đạt hiệu quả tốt trong công việc'', ''Được training về kỹ năng marketing, chăm sóc khách hàng, sale và thuyết phục khách hàng'', ''Môi trường làm việc trẻ trung, thân thiện, năng động'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (467, 9, 7, 'Thực Tập Sinh Content Marketing', 'Sáng tạo nội dung: Nội dung fanpage Facebook, Nội dung quảng cáo, Zalo. Seeding: Lên kịch bản seeding, vận hành tool seeding (Được hướng dẫn). Tìm kiếm, booking KOL, KOC (Được hướng dẫn). Thực hiện các công việc content khác không yêu cầu nhiều kinh nghiệm dưới sự hướng dẫn của người phụ trách.', 'Ứng viên đang học tập hoặc tốt nghiệp chuyên ngành Marketing, Báo chí, Truyền thông. Ưu tiên ứng viên có kinh nghiệm viết content Social. Yêu thích viết lách, sáng tạo nội dung, có định hướng theo ngành Content marketing. Ưu tiên ứng viên biết sử dụng AI phục vụ công việc. Làm việc có trách nhiệm, đúng deadline. Chủ động, tỉ mỉ trong công việc. Biết thiết kế đơn giản bằng Canva là 1 lợi thế. Vui lòng gửi kèm portfolio (Nếu có).
Kỹ năng chuyên môn: [''Viết nội dung'', ''Sử dụng AI'', ''Thiết kế đơn giản bằng Canva'']
Kỹ năng mềm: [''Chủ động'', ''Tỉ mỉ'', ''Có trách nhiệm'', ''Đúng deadline'', ''Yêu thích viết lách'', ''Sáng tạo nội dung'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '4.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:30)', '[''Môi trường làm việc ổn định, thoải mái'', ''Hỗ trợ dấu mộc báo cáo sau thời gian thực tập'', ''Cơ hội gắn bó cùng công ty sau thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (468, 10, 7, 'Tư Vấn Khách Hàng', 'Công việc đơn giản: Chat, tư vấn khách hàng qua Fanpage. Gọi điện hỗ trợ, đảm bảo khách hàng có trải nghiệm tốt nhất. Trực hotline, giải đáp thắc mắc. Công việc cụ thể sẽ được hướng dẫn chi tiết khi vào làm việc.', 'Có kinh nghiệm mảng tư vấn khách hàng. Chịu khó, nhanh nhẹn, hòa đồng. Có tinh thần trách nhiệm cao. Kỹ năng giao tiếp khá. Làm việc Xoay ca: 08h - 22h. Làm việc tại Phan Đăng Lưu - Phú Nhuận (cũ) hoặc Hậu Giang - Q6 cũ.
Kỹ năng mềm: [''Chịu khó'', ''Nhanh nhẹn'', ''Hòa đồng'', ''Kỹ năng giao tiếp khá'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '08h - 22h', '[''Tập gym miễn phí tại các chi nhánh The New Gym'', ''Môi trường làm việc năng động'', ''Môi trường làm việc thân thiện hoà đồng'', ''Cơ hội ứng tuyển các vị trí khác trong công ty'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (469, 2, 7, 'Thực Tập Sinh PR Truyền Thông', 'Hỗ trợ sản xuất nội dung truyền thông về sự kiện (viết bài, chụp ảnh, edit video). Ứng viên sử dụng máy ảnh mức độ khá tốt. Biên dịch bài viết sang tiếng Anh. Kĩ năng viết tiếng Anh ở mức độ khá. Hỗ trợ các hoạt động tổ chức sự kiện học sinh, hội thảo (lên kế hoạch sự kiện, hậu cần và truyền thông). Các hoạt động khác theo phân công.', 'Sinh viên đang học năm 2,3,4, thực sự đam mê truyền thông, thực sự có mong muốn trải nghiệm, học hỏi công việc thực tế, để tích lũy kinh nghiệm. Thời gian thực tập từ 4-6 tháng. Tối thiểu 20h/tuần. Cần đáp ứng được thời gian thực tập. Chuyên ngành theo học: Truyền thông đa phương tiện, Báo chí, Ngoại ngữ, Ngoại giao, Kinh tế, ... Cầu tiến, ham học hỏi, nhiệt tình, chăm chỉ.
Kỹ năng chuyên môn: [''Viết bài'', ''Chụp ảnh'', ''Edit video'', ''Biên dịch tiếng Anh'']
Kỹ năng mềm: [''Cầu tiến'', ''Ham học hỏi'', ''Nhiệt tình'', ''Chăm chỉ'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', '7:45 đến 16:45, từ thứ 2 đến thứ 6, và 2 ngày thứ 7 trong một tháng', '[''Hỗ trợ tiền 2tr (tự túc ăn) nếu fulltime, 1tr (tự túc ăn) nếu parttime'', ''Hỗ trợ ăn sáng, ăn trưa tại trường trong thời gian thực tập'', ''Nhận được thư xác nhận, dấu mộc từ trưởng đơn vị về quá trình thực tập'', ''Được trải nghiệm môi trường truyền thông giáo dục chuyên nghiệp'', ''Được đào tạo về truyền thông, tổ chức sự kiện'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (470, 3, 7, 'Marketing Intern', 'SKY PAK là công ty chuyên ứng các giải pháp công nghệ về đóng gói sau thành phẩm cho Doanh nghiệp. Một số sản phẩm tiêu biểu như Pallet gỗ, Túi khí chèn Container, Hút ẩm treo container, Cột khí/ Gối khí/ Đệm khí chống sốc, Gói hút oxy bảo quản thực phẩm,… - Công việc chính: * Viết bài chuẩn SEO trên nền tảng Website * Viết bài về sản phẩm/ sự kiện/ công ty trên Fanpage - Công việc khác: * Lên Plan Marketing trên các nền tảng: Website, Fanpage, Tiktok, Youtube,… * Xây dựng nội dung và lên bài cho kênh Tiktok và Youtube * Lên plan và tham gia các sự kiện MKT offline như triển lãm, giới thiệu sản phẩm,… * Thiết kế các ấn phẩm truyền thông cho công ty (brochure, profile, bài đăng trên các kênh social,…) * Thường xuyên báo cáo tiến độ công việc cho Leader * Thực hiện các nhiệm vụ khác theo yêu cầu của cấp trên.', '- Nữ, đang là sinh viên năm 3, năm cuối Đại học chuyên ngành Marketing. - Không yêu cầu kinh nghiệm. - Chịu được áp lực cao. - Siêng năng, ham học hỏi và mong muốn cơ hội thăng tiến rõ ràng. - Thành thạo tin học văn phòng và có laptop. - Điểm cộng: thiết kế (canva, AI) và chụp ảnh, quay dựng tốt.
Kỹ năng chuyên môn: [''SEO'', ''Tin học văn phòng'', ''Thiết kế (canva, AI)'']
Kỹ năng mềm: [''Chịu được áp lực cao'', ''Siêng năng'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 - 2.5 triệu', '7,5 tiếng/ngày, nghỉ trưa 1h30, nghỉ Thứ 7 và Chủ nhật', '[''Trợ cấp: 2.500.000đ/ tháng'', ''Phụ cấp cơm trưa: 700.000đ/ tháng'', ''Được đào tạo từ cơ bản đến nâng cao'', ''Cơ hội trở thành nhân viên chính thức sau 3-6 tháng thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (471, 7, 7, 'CTV Khảo Sát Part-Time', '- Gặp trực tiếp, đến từng hộ gia đình để thực hiện khảo sát theo bảng hỏi có sẵn - Báo cáo lên trưởng nhóm về tiến độ, kết quả công việc, vấn đề cần giải quyết - Thời gian làm việc linh động, không gò bó - Địa điểm làm việc linh động, tùy dự án', '- Đã tốt nghiệp Cao Đẳng trở lên - Không yêu cầu kinh nghiệm - Có phương tiện di chuyển - Chịu khó, có trách nhiệm, có khả năng giao tiếp tốt - Trung thực, liêm chính
Kỹ năng mềm: [''Chịu khó'', ''Có trách nhiệm'', ''Có khả năng giao tiếp tốt'', ''Trung thực'', ''Liêm chính'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '0.1 - 2.0 triệu', 'Linh động', '[''Thu nhập trung bình 80-150k/ 1 bài, tùy năng lực'', ''Được đào tạo kiến thức về phỏng vấn, thu thập dữ liệu khảo sát'', ''Có trang bị công cụ làm việc (máy tính bảng)'', ''Môi trường làm việc thân thiện, năng động, có cơ hội thăng tiến'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (472, 8, 7, 'Thực Tập Sinh Marketing Nghiên Cứu Thị Trường', 'Cập nhật xu hướng thị trường Ecommerce. Nghiên cứu, báo cáo đánh giá thông tin liên quan đến thị trường, phân khúc thị trường sản phẩm của công ty. Thực hiện báo cáo công việc và các nhiệm vụ khác theo phân công từ cấp trên.', 'Không yêu cầu kinh nghiệm. Ưu tiên các bạn sinh viên năm 3, năm 4 thuộc các nhóm ngành có chuyên môn: Marketing, Quản trị kinh doanh,..; Tiếng Anh đọc hiểu tốt; Tư duy logic, kỹ năng phân tích thị trường, sản phẩm; Có thể lên văn phòng tối thiểu 6 ca/ tuần.
Kỹ năng chuyên môn: [''Kỹ năng phân tích thị trường'', ''Tiếng Anh đọc hiểu'']
Kỹ năng mềm: [''Tư duy logic'', ''Kỹ năng phân tích'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)', '[''Hỗ trợ chi phí thực tập'', ''Được đào tạo về kiến thức chuyên môn'', ''Tham gia các hoạt động vui chơi, du lịch của công ty'', ''Cơ hội trở thành nhân viên chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (473, 9, 7, 'Nhân Viên Part Time Marketing, Content', 'Bạn đam mê sáng tạo nội dung, yêu thích môi trường nghệ thuật và mong muốn có công việc bán thời gian linh hoạt? Hãy gia nhập đội ngũ của chúng tôi! Thời gian làm việc: Từ 8h30 – 12h30, Thứ 2 – Thứ 7. Địa điểm làm việc: Làm việc trực tiếp tại trung tâm (Quận 7). Mô tả công việc: - Sáng tạo nội dung: Viết bài chuẩn SEO cho website, quản lý và cập nhật nội dung trên Fanpage, TikTok. - Làm video ngắn: Quay, dựng clip ngắn về lớp học, học viên để chạy quảng cáo và thu hút học viên mới. - Hỗ trợ tổ chức các sự kiện cho trường và lên kế hoạch hoạt động.', 'Có kinh nghiệm viết content, chỉnh sửa video cơ bản (dùng CapCut, Canva hoặc phần mềm tương tự). Hiểu cơ bản về SEO, fanpage marketing là một lợi thế. Giao tiếp tốt, chủ động trong công việc. Cẩn thận, nhanh nhẹn, có trách nhiệm. Mang theo laptop đi làm.
Kỹ năng chuyên môn: [''Viết bài chuẩn SEO'', ''Chỉnh sửa video cơ bản (dùng CapCut, Canva hoặc phần mềm tương tự)'', ''Quản lý và cập nhật nội dung trên Fanpage, TikTok'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Chủ động trong công việc'', ''Cẩn thận'', ''Nhanh nhẹn'', ''Có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'quận 7', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Từ 8h30 – 12h30, Thứ 2 – Thứ 7', '[''Môi trường nghệ thuật sáng tạo, năng động'', ''Cơ hội phát triển kỹ năng content marketing, quay dựng video, tư vấn khách hàng'', ''Kiến thức về lĩnh vực mới'', ''Tham gia các lớp học với học phí ưu đãi'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (474, 10, 7, 'Thực Tập Sinh Sales Marketing', '- Tìm kiếm khách hàng mới trên social media - Chủ động liên hệ với khách hàng tiềm năng để giới thiệu các dịch vụ của công ty - Xây dựng hệ thống dữ liệu khách hàng tiềm năng - Viết Content Marketing về sản phẩm, dịch vụ được giao trên account làm việc', '- Là sinh viên năm 3, 4 hoặc vừa mới tốt nghiệp các trường ĐH, CĐ - Hiểu biết cơ bản về nền tảng social media - Quan tâm, yêu thích và định hướng về sales - Đáp ứng thời gian làm việc tối thiểu 8 buổi/tuần từ Thứ 2 - Thứ 6 (Được đăng kí thời gian làm việc linh hoạt và linh hoạt online/offline) - Có laptop để làm việc - Năng động, sáng tạo, có tinh thần học hỏi và cầu tiến
Kỹ năng chuyên môn: [''Hiểu biết cơ bản về nền tảng social media'']
Kỹ năng mềm: [''Năng động'', ''Sáng tạo'', ''Có tinh thần học hỏi'', ''Cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 – Thứ 6, Sáng: 09h00 – 12h00, Chiều: 13h30 – 17h30', '[''Hỗ trợ dấu mộc về báo cáo thực tập'', ''Có cơ hội tham gia các khóa học về Digital Marketing trị giá 9,600,000 VNĐ của công ty'', ''Môi trường làm việc chuyên nghiệp, năng động, trẻ và nhiệt huyết'', ''Được training các kỹ năng tư vấn, giới thiệu, chăm sóc, mở rộng tập khách hàng'', ''Chính sách thăng tiến và KPIs minh bạch'', ''Cơ hội được trở thành nhân viên chính thức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (475, 2, 7, 'Thực Tập Sinh Nhân Sự', 'Tham gia xử lý các công việc phát sinh tại phòng nhân sự, tuyển dụng. Huấn luyện các kỹ năng để thực hiện công việc nhân sự, tuyển dụng. Một số công việc khác có liên quan trực tiếp đến nhân sự, tuyển dụng. Được đào tạo, hướng dẫn, chia sẽ kinh nghiệm, kiến thức nhân sự tuyển dụng trong quá trình thực tập.', 'Giới tính: Nam/Nữ. Là sinh viên năm 3, 4 các trường đại học và cao đẳng chuyên ngành quản trị kinh doanh, nhân sự, marketing. Trung thực, nhiệt tình và có tinh thần trách nhiệm. Thực tập toàn thời gian trong giờ hành chính tại văn phòng Công ty trong khoảng thời gian ít nhất là 03 tháng.
Kỹ năng mềm: [''Trung thực'', ''Nhiệt tình'', ''Có tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung'', ''Được hỗ trợ dấu mộc thực tập'', ''Cơ hội trở thành nhân viên chính thức sau thời gian thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (476, 3, 7, 'Phát triển kinh doanh & tiếp thị thực tập', 'Hỗ trợ phát triển và thực hiện các chiến dịch tiếp thị trực tuyến/ngoại tuyến, cũng như phân tích hiệu suất chiến dịch và phản hồi của khách hàng và xác định các cơ hội sản phẩm. Tiến hành nghiên cứu thị trường trên các kênh bán hàng truyền thống (cuộc gọi trực tiếp với B2C, khách hàng B2B, cơ quan, v.v.). Hỗ trợ thu thập, phân tích dữ liệu và động não các chiến lược bán hàng với nhóm. Giúp nghiên cứu các khách hàng tiềm năng, giới thiệu các sản phẩm và sắp xếp các cuộc họp với triển vọng mới. Chuẩn bị các báo cáo, sàn trình bày và tài liệu tiếp thị cho các đối tác nội bộ và bên ngoài. Cung cấp hỗ trợ quản trị viên và các nhiệm vụ khác theo yêu cầu.', 'Strong English skills (writing, speaking, listening). Proficiency in Excel, PowerPoint, Canva. Proactivity, quick learning ability, critical thinking, and eager to learn. Good at teamwork and hard-working. 3rd/4th-year university students or fresh graduates in Business Administration, Marketing, Communications, or related fields. Able to commit at least 4 working days per week for a minimum of 3 months.
Kỹ năng chuyên môn: [''Excel'', ''PowerPoint'', ''Canva'']
Kỹ năng mềm: [''Proactivity'', ''Quick learning ability'', ''Critical thinking'', ''Teamwork'', ''Hard-working'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Monthly allowance based on performance'', ''Dynamic, professional, and international environment'', ''Opportunities for training, experience, and growth in a start-up environment'', ''Internship certification (if needed)'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (477, 7, 7, 'Cộng Tác Viên Livestream', 'Phụ trách live trên các nền tảng thương mại điện tử, giới thiệu công ty, quảng cáo sản phẩm. Thông qua kênh, giới thiệu cho khách hàng thông tin về sản phẩm, giải đáp thắc mắc, đóng góp ý kiến, kêu gọi người dùng mua sản phẩm. Dựa theo yêu cầu và nội dung đã soạn sẵn, khuấy động sức nóng của livestream. Tôn trọng quy định của sàn và các quy định của công ty, đáp ứng được các yêu về thời gian, đạt được hiệu quả mong muốn.', 'Tuổi từ 18-30, có cá tính, không ngại máy quay. Có khí chất, tính cách hướng ngoại, dám bộc lộ bản thân. Tư duy mạch lạc, nói năng lưu loát. Có kinh nghiệm live cùng hàng hoá, quen thuộc với sàn thương mại điện tử.
Kỹ năng chuyên môn: [''Kinh nghiệm live cùng hàng hoá'', ''Quen thuộc với sàn thương mại điện tử'']
Kỹ năng mềm: [''Khí chất'', ''Tính cách hướng ngoại'', ''Tư duy mạch lạc'', ''Nói năng lưu loát'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 11:30)', '[''Cơ hội thăng tiến, phát triển nghề nghiệp'', ''Có cơ hội hợp tác lâu dài và trở thành nhân viên chính thức'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (478, 8, 7, 'Thực Tập Sinh Digital Marketing', 'Tham gia xây dựng và triển khai các chiến lược Digital Marketing hiệu quả, bao gồm SEO, SEM, Social Media Marketing, Email Marketing, Content Marketing... Phân tích dữ liệu, đánh giá hiệu quả các chiến dịch Marketing và đề xuất các giải pháp tối ưu. Nghiên cứu và cập nhật xu hướng Digital Marketing mới nhất. Phối hợp với các bộ phận khác trong công ty để thực hiện các chiến dịch Marketing tổng thể. Tạo chiến dịch quảng cáo (lên camp chạy ads đa kênh).', 'Sinh viên năm cuối hoặc mới ra trường chuyên ngành truyền thông Marketing, Kinh tế, Công nghệ thông tin và chuyên ngành liên quan. Có hiểu biết trong lĩnh vực Digital Marketing (Ưu tiên ứng viên có kinh nghiệm thực tế). Nắm kiến thức các kênh Digital Marketing phổ biến như SEO, SEM, Social Media Marketing, Email Marketing, Content Marketing... Có khả năng phân tích dữ liệu, đánh giá hiệu quả chiến dịch và đề xuất giải pháp tối ưu. Khả năng làm việc độc lập và làm việc nhóm tốt. Biết sử dụng các công cụ hỗ trợ Marketing online như Google Analytics, Google Search Console, Facebook Ads Manager.
Kỹ năng chuyên môn: [''SEO'', ''SEM'', ''Social Media Marketing'', ''Email Marketing'', ''Content Marketing'', ''Google Analytics'', ''Google Search Console'', ''Facebook Ads Manager'']
Kỹ năng mềm: [''Khả năng phân tích dữ liệu'', ''Đánh giá hiệu quả chiến dịch'', ''Làm việc độc lập'', ''Làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:15), Thứ 7 (từ 08:00 đến 11:30 và từ 13:15 đến 16:45), Thứ 7 làm luân phiên 1 tuần làm, 1 tuần nghỉ', '[''Được hướng dẫn, đào tạo chuyên môn'', ''Được làm việc trong môi trường trẻ, năng động'', ''Hỗ trợ dấu thực tập nếu ứng viên cần'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (479, 9, 7, 'Thực Tập Sinh Media - Quay Dựng', 'Quay và dựng video ngắn: TikTok, Reels, Viral video, Video sản phẩm, Video dự án,... Tối ưu định dạng, chất lượng video theo từng nền tảng (TikTok, YouTube, Facebook...). Tham gia các hoạt động của Team marketing. Phối hợp với team thảo luận kịch bản, ý tưởng cho video.', 'Biết sử dụng công cụ: Capcut, Premiere và các phần mềm thiết kế, edit khác. Biết quay, chụp ảnh cơ bản bằng máy quay, máy ảnh, điện thoại,... Ưu tiên tư duy thẩm mỹ, Marketing. Sinh viên năm cuối hoặc mới tốt nghiệp Cao đẳng, Đại học ở các chuyên ngành truyền thông đa phương tiện, designer, marketing hoặc các chuyên ngành liên quan. Khả năng làm việc độc lập và làm việc nhóm tốt.
Kỹ năng chuyên môn: [''Capcut'', ''Premiere'', ''Phần mềm thiết kế'', ''Phần mềm edit'']
Kỹ năng mềm: [''Tư duy thẩm mỹ'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (08:00 - 17:15), Thứ 7 (08:00 - 11:30, 13:15 - 16:45)', '[''Được hướng dẫn, đào tạo chuyên môn'', ''Hỗ trợ dấu thực tập nếu cần'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (480, 10, 7, 'Tiếp thị nội dung thực tập', 'Hỗ trợ sáng tạo nội dung về mảng mobile app/game. Xây dựng content, video truyền thông quảng cáo trên các nền tảng quảng cáo với ngân sách lớn (Facebook, tiktok, google...). Research và nghiên cứu xu hướng thị trường Mỹ, Châu Âu, Global. Hỗ trợ các công việc khác khi có phân công.', 'Có kỹ năng chỉnh sửa ảnh cơ bản, làm video cơ bản bằng capcut. Biết sử dụng AI để hỗ trợ công việc. Biết làm tiktok hoặc có kênh là một lợi thế lớn. Thành thạo tiếng Anh. Làm việc tối thiểu 8 buổi/tuần hoặc 4 ngày/tuần. Tiếng anh tương đương 650 Toeic hoặc 5.5 ielts.
Kỹ năng chuyên môn: [''Chỉnh sửa ảnh cơ bản'', ''Làm video cơ bản bằng capcut'', ''Sử dụng AI'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Cơ hội lên nhân viên chính sau khi kết thúc thời gian thực tập'', ''Được đào tạo các kỹ năng về xây dựng content'', ''Thu nhập 13-15 tháng lương/năm'', ''Quà tặng vào các ngày Lễ Tết'', ''Chế độ bảo hiểm xã hội, bảo hiểm y tế'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (481, 2, 7, 'Người tạo nội dung thực tập', 'Tối ưu hóa nội dung, từ khóa sản phẩm, xây dựng bộ content chuẩn ASO. Research trending thị trường. Lên idea, sáng tạo nội dung quảng cáo, lên kịch bản quảng cáo, truyền thông đa phương tiện (video ngắn 15-30s, hình ảnh, tin đăng). Các nền tảng tiktok ads, fb ads,. Quảng cáo, truyền thông các sản phẩm về mobile game/app. Phối hợp với các bộ phận khác để làm việc nhóm hiệu quả.', 'Có kinh nghiệm quay edit video, hình ảnh cơ bản. Biết làm tiktok hoặc có kênh là một lợi thế lớn. Thành thạo tiếng Anh. Đam mê chơi game mobile là điểm cộng.
Kỹ năng chuyên môn: [''Quay edit video'', ''Hình ảnh cơ bản'', ''Làm tiktok'']
Kỹ năng mềm: [''Sáng tạo nội dung'', ''Làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Lương cứng từ 3.000.000đ - 4.000.000đ/tháng'', ''Lộ trình cho intern'', ''Thưởng hiệu quả làm việc'', ''Khám sức khỏe định kỳ'', ''Các chế độ về bảo hiểm xã hội, bảo hiểm y tế'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (482, 3, 7, 'Thực Tập Sinh Marketing', '• Hỗ trợ phát triển và triển khai các chiến lược truyền thông xã hội trên nhiều nền tảng mạng xã hội của công ty ( Facebook, Instagram, Tiktok,..) • Hỗ trợ quản lý các kênh truyền thông của công ty • Hợp tác với nhóm để đưa ra ý tưởng nội dung • Sử dụng nền tảng để tạo bài đăng tin và nội dung video ngắn • Hỗ trợ phát triển các chiến dịch tiếp thị qua email • Hỗ trợ tổ chức và điều hành các sự kiện online và offline • Hỗ trợ quay phim, thiết kế hình ảnh, video • Hỗ trợ triển khai chiến dịch quảng cáo • Hỗ trợ các hoạt động nội bộ khác và các công việc theo yêu cầu của quản lý.', '• Sinh viên năm ba, năm tư hoặc vừa tốt nghiệp chuyên ngành Marketing, Truyền thông, chuyên ngành truyền thông tổ chức sự kiện, hoặc các ngành liên quan • Biết sử dụng các thiết bị máy ảnh, máy quay phim. Hoặc yêu thích công việc quay phim chụp hình. • Biết sử dụng các công cụ thiết kế cơ bản như Canva, Premiere, Capcut hoặc các phần mềm edit video. • Có tinh thần học hỏi, chủ động trong công việc, năng động và khả năng làm việc nhóm tốt. • Ưu tiên ứng viên có kinh nghiệm hỗ trợ trong lĩnh vực truyền thông, tham gia hoạt động đoàn nhóm, có kinh nghiệm tổ chức sự kiện • Thời gian thực tập từ 3-6 tháng
Kỹ năng chuyên môn: [''Sử dụng các thiết bị máy ảnh, máy quay phim'', ''Sử dụng các công cụ thiết kế cơ bản như Canva, Premiere, Capcut hoặc các phần mềm edit video'']
Kỹ năng mềm: [''Tinh thần học hỏi'', ''Chủ động trong công việc'', ''Năng động'', ''Khả năng làm việc nhóm tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Trợ cấp đi lại'', ''Gửi xe'', ''Thưởng (tùy vào khả năng thể hiện)'', ''Môi trường làm việc trẻ trung, năng động'', ''Cơ hội trở thành nhân viên chính thức nếu thể hiện tốt trong quá trình thực tập'', ''Hỗ trợ đóng mộc, xác nhận kết quả thực tập'', ''Được đào tạo các kỹ năng marketing, tổ chức sự kiện'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (483, 7, 7, 'Thực Tập Sinh Content Marketing', 'Tham gia cùng team xây dựng và quản lý các chiến dịch Marketing, đóng góp các ý tưởng nội dung sáng tạo cho chiến dịch Digital Marketing. Tìm hiểu sản phẩm, insight khách hàng và xây dựng các nội dung content đánh trúng insight khách hàng trên các kênh truyền thông của công ty như: Facebook, Tiktok, Website,... Cập nhật thường xuyên các tin tức mới nhất để bổ sung vào ý tưởng và tăng thêm kho nội dung viết bài. Thực hiện các công việc theo chỉ đạo trực tiếp từ Trưởng bộ phận và Ban lãnh đạo.', 'Khả năng làm việc độc lập và teamwork. Khả năng giao tiếp, thuyết phục. Khả năng lập kế hoạch, báo cáo. Ham học hỏi có mục tiêu rõ ràng trong công việc.
Kỹ năng mềm: [''Khả năng làm việc độc lập và teamwork'', ''Khả năng giao tiếp, thuyết phục'', ''Khả năng lập kế hoạch, báo cáo'', ''Ham học hỏi có mục tiêu rõ ràng trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được hướng dẫn đào tạo theo lộ trình, kèm cặp, trực chỉ'', ''Môi trường chuyên nghiệp, thân thiện, năng động'', ''Được xác nhận thực tập và đóng dấu công ty'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (484, 8, 7, 'Thực Tập Sinh Content Marketing Part Time', 'Phát triển ý tưởng và lên kế hoạch nội dung marketing. Hợp tác với team quay dựng để sản xuất video, quản lý kênh truyền thông. Hỗ trợ quản lý các kênh truyền thông và đo lường hiệu quả. Điều chỉnh và cải thiện kế hoạch cùng team.', '1. Bạn phải thực sự đam mê, quyết liệt với mục tiêu, nói không với ổn định, an toàn, làm hết giờ về và về chill. 2. Bạn có trong mình tinh thần học tập không ngừng luôn khao khát được bứt phá phát triển, thăng tiến trong sự nghiệp, gia tăng thu nhập. 3. Tham gia 1 buổi Tuyển dụng Thực tập sinh thông qua đào tạo độc quyền tại Nuy để định hướng vị trí và ngành hàng phù hợp năng lực. 4. Độ tuổi ưu tiên: dưới 23 tuổi.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Nghiên Cứu Thị Trường'', ''Viết content Marketing Cơ Bản'', ''Sử Dụng Mạng Xã Hội'']
Kỹ năng mềm: [''Đam mê'', ''Tinh thần học tập'', ''Khả năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Part time tối thiểu 3 buổi offline, kết hợp online linh hoạt', '[''Được đào tạo và phát triển nhanh gấp 3-5 lần'', ''Tiếp xúc với hơn 100 trưởng phòng, giám đốc marketing'', ''Thời gian làm việc linh hoạt'', ''Cơ hội triển khai các dự án đa dạng'', ''Cơ hội trở thành nhân viên chính thức với mức thu nhập 3-5 triệu part time'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (485, 9, 7, 'Hỗ trợ vận hành chiến dịch thực tập', 'Làm việc và trao đổi trực tiếp với các thương hiệu tham gia TAP (TikTok Affiliate Program) để nắm thông tin sản phẩm, ngân sách, chính sách và nhu cầu tuyển KOC. Phối hợp với Account/BD để tạo và cập nhật file onboarding (Google Sheet, Slide, Folder nội dung…) cho từng campaign. Đảm bảo toàn bộ tài liệu hỗ trợ brand (brief, nội dung sản phẩm, hướng dẫn KOC…) được chuẩn hoá và dễ tiếp cận. Thực hiện đăng nội dung tuyển dụng KOC (bài viết, ảnh, banner, minigame...) trên các kênh cộng đồng TAP (Facebook Group, Zalo OA, Instagram, Threads…). Đi bài truyền thông hàng tuần theo kế hoạch – ưu tiên các campaign hot, có ưu đãi cao hoặc sản phẩm trendy. Hỗ trợ tạo nội dung, viết caption ngắn gọn thu hút, có CTA rõ ràng cho các bài viết. Phối hợp với team tuyển KOC để tổng hợp thông tin ứng viên từ form đăng ký. Đăng banner chương trình trên các kênh truyền thông chính thức của Accesstrade nhằm thu hút thêm KOC mới cho campaign. Hỗ trợ trả lời comment/inbox từ KOC liên quan đến các chương trình hiện có. Hỗ trợ cập nhật danh sách KOC tham gia từng chiến dịch để thuận tiện tracking hiệu quả. Làm việc cùng các bạn trong team để đảm bảo KOC được cung cấp thông tin đầy đủ và hỗ trợ xử lý các vấn đề phát sinh (chậm nhận quà, thiếu thông tin brief…).', 'Sinh viên năm 3 hoặc năm cuối các ngành: Marketing, Kinh doanh, Truyền thông, Thương mại điện tử hoặc các ngành liên quan. Có định hướng phát triển trong lĩnh vực Digital Marketing, Influencer Marketing, hoặc E-commerce. Thành thạo Google Workspace (Docs, Sheets, Slides) – biết sử dụng các hàm cơ bản trong Google Sheet là một lợi thế. Có khả năng viết lách tốt, ưu tiên ứng viên có kinh nghiệm viết bài trên fanpage, group cộng đồng hoặc từng làm CTV content. Biết cách sử dụng các công cụ thiết kế cơ bản như Canva, Figma là điểm cộng. Cẩn thận, có tinh thần trách nhiệm trong công việc và chủ động cập nhật tiến độ với team. Kỹ năng giao tiếp tốt, biết cách xử lý tình huống khi làm việc với đối tác (brand) và KOC. Có khả năng làm việc nhóm cũng như làm việc độc lập dưới áp lực thời gian. Sẵn sàng học hỏi, chịu khó tìm hiểu về quy trình vận hành chiến dịch affiliate/influencer. Chủ động cập nhật xu hướng social media, đặc biệt là TikTok, để hỗ trợ truyền thông hiệu quả.
Kỹ năng chuyên môn: [''Google Workspace (Docs, Sheets, Slides)'', ''Canva'', ''Figma'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Cẩn thận'', ''Có tinh thần trách nhiệm'', ''Khả năng làm việc nhóm'', ''Chủ động cập nhật tiến độ'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:30)', '[''Có cơ hội lên chính thức sau 3 tháng thực tập.'', ''Được đào tạo bài bản, thực chiến tại công ty hàng đầu về digital marketing.'', ''Văn hóa nội bộ hướng đến việc phát triển con người.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (486, 10, 7, 'Thực Tập Sinh Phát Triển Dự Án Kinh Doanh', 'Hỗ trợ nghiên cứu và phân tích thị trường, đối thủ cạnh tranh, xu hướng ngành liên quan đến các dự án kinh doanh. Được đào tạo để thực hiện khảo sát khách hàng, thu thập thông tin, phân tích dữ liệu. Tham gia họp nội bộ và hỗ trợ chuẩn bị tài liệu, báo cáo dự án, thuyết trình, proposal. Hỗ trợ kết nối và làm việc với các đối tác, khách hàng hoặc phòng ban liên quan trong quá trình triển khai dự án. Hỗ trợ các công việc hành chính, lưu trữ tài liệu, quản lý thông tin dự án theo yêu cầu. Đề xuất các ý tưởng sáng tạo để tối ưu hóa hiệu quả dự án và trải nghiệm khách hàng.', 'Sinh viên năm 3, 4 hoặc vừa tốt nghiệp các chuyên ngành: Quản trị Kinh doanh, Marketing, Kinh tế, Tài chính, hoặc các ngành liên quan. Có khả năng tư duy phân tích, tổng hợp và giải quyết vấn đề tốt. Kỹ năng giao tiếp, làm việc nhóm và quản lý thời gian hiệu quả. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). Chủ động, ham học hỏi, cầu tiến và có tinh thần trách nhiệm cao. Có khả năng làm việc độc lập và chịu được áp lực.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Tư duy phân tích'', ''Giải quyết vấn đề'', ''Giao tiếp'', ''Làm việc nhóm'', ''Quản lý thời gian'', ''Chủ động'', ''Ham học hỏi'', ''Cầu tiến'', ''Tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ Bảy (tuần làm 1 thứ Bảy trên công ty, còn lại làm từ xa)', '[''Trở thành nhân viên chính thức sau 3 tháng'', ''Cơ hội được tiếp cận thực tế với các dự án kinh doanh đa dạng'', ''Làm việc trong môi trường chuyên nghiệp, năng động, có mentor hỗ trợ'', ''Được đào tạo và hướng dẫn chi tiết trong quá trình làm việc'', ''Hỗ trợ dấu mộc, xác nhận thực tập và hỗ trợ chi phí (nếu có)'', ''Xăng xe'', ''Cước điện thoại'', ''Team building'', ''Thưởng hiệu quả làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (487, 2, 7, 'Video Editor (Bán Thời Gian)', 'Sáng tạo ý tưởng, nội dung, kịch bản cho các video ngắn trên social media. Quay, dựng video ngắn theo kế hoạch. Quản lý, đăng tải, phân phối nội dung trên TikTok, FB REELS, YOUTUBE SHORT trong hệ sinh thái của THALIC. Lập kế hoạch phát triển các chiến dịch media. Các công việc khác theo yêu cầu của Quản lý.', 'Biết cơ bản 4 kỹ năng: Lên ý tưởng - Làm kịch bản - Quay video cơ bản - Dựng video. Đã có kinh nghiệm sáng tạo nội dung Video ngắn trên Social media. Tư duy sáng tạo tốt; Nhạy bén với các nội dung thịnh hành, xu hướng trên mạng xã hội. Tinh thần làm việc Ổn định, không thường xuyên bị ảnh hưởng bởi các yếu tố cá nhân, bên ngoài. Các ứng viên chỉ có nhu cầu làm việc thời gian ngắn (dưới 6 tháng) KHÔNG phù hợp với chúng tôi.
Kỹ năng chuyên môn: [''Kỹ năng quay phim cơ bản'', ''Sử dụng phần mềm chỉnh sửa video (Adobe Premiere Pro, Final Cut Pro, Davinci Resolve, v.v.)'', ''Kỹ năng biên tập video (cắt ghép, thêm hiệu ứng, âm thanh, phụ đề)'', ''Hiểu biết về xu hướng video ngắn trên mạng xã hội (TikTok, Instagram Reels, YouTube Shorts, v.v.)'']
Kỹ năng mềm: [''Tư duy sáng tạo tốt'', ''Nhạy bén với các nội dung thịnh hành, xu hướng trên mạng xã hội'', ''Tinh thần làm việc ổn định'']', 'PART_TIME', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Linh động Sáng hoặc chiều hoặc cả ngày', '[''Lương cứng + Lương KPI + Thưởng + Phụ cấp (Gửi xe, điện thoại) + Chế độ (Sinh nhật, Lễ, Tết...)'', ''Tham gia MIỄN PHÍ các lớp học tại THALIC VOICE'', ''Thưởng thành tích theo tháng, quý, năm'', ''Thưởng theo các ngày lễ tết trong năm'', ''Chế độ lương tháng thứ 13'', ''Tham gia các hoạt động nội bộ như Team building, Year end party, Sinh nhật'', ''Môi trường tích cực, giúp đỡ nhau cùng phát triển'', ''Cơ hội thăng tiến rõ ràng'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (488, 3, 7, 'Nhân Viên Marketing', 'Thu thập và phân tích dữ liệu từ khảo sát, phỏng vấn, số liệu bán hàng và nhu cầu khách hàng. Đánh giá hành vi người tiêu dùng, phân tích đối thủ cạnh tranh. Nghiên cứu xu hướng thị trường và các yếu tố tác động để đưa ra chiến lược Marketing phù hợp. Xây dựng các mục tiêu Marketing cụ thể dựa trên mục tiêu chung của công ty (tăng trưởng doanh thu, nâng cao nhận diện thương hiệu, phát triển khách hàng tiềm năng, v.v..). Lên kế hoạch và thực hiện các chiến lược Marketing đã được phê duyệt và phối hợp với các bộ phận khác để triển khai. Xác định các kênh truyền thông phù hợp (quảng cáo, mạng xã hội, báo chí, v.vv..) và triển khai kế hoạch chi tiết cho các chiến dịch Marketing. Sáng tạo và phát triển các nội dung quảng cáo, bao gồm bài viết, video, hình ảnh và các dạng nội dung khác phù hợp với từng chiến dịch Marketing. Đảm bảo nội dung quảng cáo luôn nhất quán với hình ảnh thương hiệu và thu hút sự quan tâm của đối tượng mục tiêu. Phối hợp với bộ phận kinh doanh và chăm sóc khách hàng để đảm bảo tính nhất quán của thông điệp Marketing. Tổ chức sự kiện trực tuyến, hội thảo, webinar, hoặc các hoạt động tiếp thị khác.', 'Nhanh nhẹn, hoạt bát, có khả năng tiếp thu nhanh. Chủ động trong công việc , tự lên kế hoạch và sắp xếp công việc. Có mindset về marketing. Có kĩ năng: xử lí thiết kế hình ảnh, phân tích, nghiên cứu thị trường, tổng hợp đánh giá kết quả.
Kỹ năng chuyên môn: [''xử lí thiết kế hình ảnh'', ''phân tích'', ''nghiên cứu thị trường'', ''tổng hợp đánh giá kết quả'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''hoạt bát'', ''có khả năng tiếp thu nhanh'', ''Chủ động trong công việc'', ''tự lên kế hoạch và sắp xếp công việc'', ''Có mindset về marketing'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', '9h đến 18h từ thứ 2 và 9h- 11h30 thứ 7 (ca làm linh hoạt)', '[''Mức lương thử việc: 6,000,000'', ''Thưởng chuyên cần'', ''thưởng năng suất'', ''thưởng doanh thu hàng quý'', ''ưu đãi tặng quà theo đợt'', ''thưởng tết tháng 13 dành cho nhân viên chính thức'', ''Môi trường làm việc thân thiện'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (489, 7, 7, 'Nhân Viên Chăm Sóc Fanpage', '- Quản lý & vận hành fanpage: Đăng bài daily, tương tác với khách hàng qua comment/inbox - Sáng tạo nội dung hình ảnh/video: Thiết kế hình ảnh bằng Canva, chỉnh sửa video bằng Capcut - Xây dựng chiến lược content: Lên kế hoạch nội dung theo tuần/tháng, tăng engagement - Báo cáo hiệu suất: Theo dõi insights, phân tích hiệu quả chiến dịch - Hỗ trợ team Marketing: Triển khai campaign quảng cáo Facebook/Google', '- Kinh nghiệm: Tối thiểu 6 tháng - 1 năm quản trị fanpage - Kỹ năng bắt buộc: • Thành thạo Canva (thiết kế ảnh, banner, infographic) • Sử dụng Capcut cơ bản (cắt ghép video, add sub, hiệu ứng) • Hiểu thuật toán Facebook/Instagram Ưu tiên: • Có portfolio fanpage từng quản lý hệ thông fanpage • Biết chạy quảng cáo Facebook Ads
Kỹ năng chuyên môn: [''Thành thạo Canva'', ''Sử dụng Capcut cơ bản'', ''Hiểu thuật toán Facebook/Instagram'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Thứ 2 - Thứ 7 (từ 13:00 đến 17:00)', '[''Lương thưởng theo năng lực'', ''Hỗ trợ nâng cao kỹ năng thiết kế & content'', ''Linh động remote/offline'', ''Được đào tạo thêm về Marketing'', ''Team building'', ''Thưởng hiệu quả làm việc'', ''Ăn trưa'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (490, 8, 7, 'Thực Tập Content Và Social Media Agency Quảng Cáo', 'GIAI ĐOẠN 1: LÀM QUEN VÀ XÂY NỀN TẢNG CONTENT & SOCIAL MEDIA 1. Nắm rõ lộ trình phát triển tại Trần Vũ Group: 1. Content writer: Viết nội dung tin tức và tương tác 2. Coppywriter: Viết nội dung quảng cáo và hướng dẫn chuyên môn 3. Growth Marketing và vị trí Planner dự án: Vận hành chiến dịch đa kênh hướng tới chuyển đổi doanh thu 2. Tìm hiểu các quy trình và công cụ nội bộ như Notion, ChatGPT, Jira, Big Picture 3. Viết caption, bài post và gửi draft nội dung đầu tiên 4. Làm quen với các nhóm Planner, HR, Design, Ads để phối hợp triển khai nội dung 5. Phân biệt 03 loại tri thức nền tảng: 6. Nội dung (Insight, thông điệp, định dạng) 7. Công cụ hỗ trợ (Canva,CapCut...) 8. Đối thủ trên các nền tảng (Facebook, TikTok...) GIAI ĐOẠN 2: THỰC HÀNH CONTENT & SOCIAL MEDIA CHO DỰ ÁN THẬT 1. Chăm sóc các Zalo Group và Facebook Group bằng content 2. Viết bài fanpage, viết caption cho social (Facebook, TikTok, Instagram...) 3. Biên tập nội dung video ngắn (short-form video) hỗ trợ team Design/Video 4. Tạo kế hoạch nội dung tuần – tháng – chiến dịch theo brief đã được training 5. Lên lịch và đăng bài qua Creator Studio hoặc hệ thống riêng của công ty 6. Phối hợp với team chạy Ads để tối ưu content theo hiệu suất quảng cáo GIAI ĐOẠN 3: ĐỊNH HÌNH SỰ NGHIỆP TƯƠNG LAI 1. Generalist: Quản lý nội dung đa nền tảng, tham gia chiến lược 2. Specialist: Phụ trách toàn bộ nội dung – hình ảnh – tăng tương tác – phát triển kênh 3. Career path rõ ràng: Định hướng nghề nghiệp, xây CV chuẩn ngành Content/Digital. 4. Mục tiêu: 1. Chọn hướng đi phù hợp: Sáng tạo, Chiến lược hay Vận hành kênh 2. Thực hành đủ vòng đời content: từ idea → viết → thiết kế → triển khai → phân tích hiệu quả 3. Tìm kiếm cơ hội nghề nghiệp tương lai hoặc thử sức làm freelancer', '1. Tuyệt đối chủ động và nghiêm túc phát triển sự nghiệp của bản thân 2. Học cách biết ơn và tri ân cha mẹ trong suốt thời gian thực tập 3. Sẵn sàng teamwork và làm việc chân thành 4. Cam kết thực tập online tối thiểu 3 tháng. Ít nhất 4 buổi/tuần 5. Làm việc qua hệ thống và Quản lý nhóm online nếu được phân công nếu lên vị trí Planner dự án 6. Có tầm nhìn dài hạn về sự nghiệp Digital Marketing 7. Sẽ có những buổi họp và đào tạo đột xuất ngoài giờ, nhưng không quá 4 lần/tuần 8. Tuân thủ các Quy định và Hỗ trợ phòng HR 9. Sinh viên năm 1, 2, 3, 4 hoặc Tốt nghiệp trung cấp trở lên
Kỹ năng chuyên môn: [''Notion'', ''ChatGPT'', ''Jira'', ''Big Picture'', ''Canva'', ''CapCut'']
Kỹ năng mềm: [''Chủ động'', ''Nghiêm túc'', ''Teamwork'', ''Cam kết'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm 100% Online linh động', '[''Được đào tạo bài bản từ đầu'', ''Làm việc 100% online, thời gian linh hoạt'', ''Học các công cụ cần thiết'', ''Phát triển thành Planner quản lý dự án sau 06 tháng'', ''Được xác nhận thực tập'', ''Có thưởng theo dự án'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (491, 9, 7, 'Thực Tập Chạy Quảng Cáo Facebook Google Tiktok', 'GIAI ĐOẠN 1: LÀM QUEN VỚI CÁC KÊNH QUẢNG CÁO VÀ CÔNG CỤ 1. Làm quen hệ thống công cụ nội bộ: Google Ads, Facebook Ads Manager, TikTok Ads, Notion, ChatGPT, Big Picture 2. Hiểu rõ lộ trình phát triển nghề chạy quảng cáo tại TRẦN VŨ 3. Đọc hiểu chỉ số hiệu suất cơ bản của quảng cáo: CPC, CTR, CPM, ROAS 4. Thực hành phân tích quảng cáo mẫu, các case study 5. Phối hợp cùng team Planner, Content và Design để lên nội dung quảng cáo đầu tiên GIAI ĐOẠN 2: THỰC HÀNH CHẠY QUẢNG CÁO CHO DỰ ÁN THẬT 1. Tham gia triển khai các chiến dịch quảng cáo Facebook, Google và TikTok theo từng brief cụ thể 2. Học cách biết ơn và tri ân cha mẹ trong suốt thời gian thực tập. Từ đó giúp cha mẹ an tâm và tự hào 3. Thực hành viết nội dung và chọn hình ảnh/format quảng cáo phù hợp theo từng mục tiêu 4. Học cách cài đặt, theo dõi, và điều chỉnh chiến dịch quảng cáo qua trình quản lý quảng cáo 5. Học cách phân tích hiệu suất và lập báo cáo hằng tuần 6. Phối hợp với team Content để tối ưu hiệu quả quảng cáo theo feedback dữ liệu GIAI ĐOẠN 3: ĐỊNH HÌNH SỰ NGHIỆP DIGITAL ADVERTISING 1. Generalist: Làm chủ kỹ năng chạy đa kênh và phân tích số liệu 2. Specialist: Tập trung chuyên sâu Facebook Ads hoặc Google Ads/TikTok Ads 3. Career path rõ ràng: từ thực tập sinh → planner quản lý dự án đa kênh → chuyên viên ads → chuyên viên digital marketing 4. Có khả năng tư vấn và tự triển khai các chiến dịch cơ bản 5. Sẵn sàng trở thành freelancer hoặc làm full-time tại các Digital Agency', '1. Tuyệt đối chủ động và nghiêm túc phát triển sự nghiệp của bản thân 2. Học cách biết ơn và tri ân cha mẹ trong suốt thời gian thực tập 3. Sẵn sàng teamwork và làm việc chân thành 4. Cam kết thực tập online tối thiểu 3 tháng. Ít nhất 4 buổi/tuần 5. Làm việc qua hệ thống và Quản lý nhóm online nếu được phân công nếu lên vị trí Planner dự án 6. Có tầm nhìn dài hạn về sự nghiệp Digital Marketing 7. Sẽ có những buổi họp và đào tạo đột xuất ngoài giờ, nhưng không quá 4 lần/tuần 8. Tuân thủ các Quy định và Hỗ trợ phòng HR 9. Sinh viên năm 1, 2, 3, 4 hoặc Tốt nghiệp trung cấp trở lên
Kỹ năng chuyên môn: [''Google Ads'', ''Facebook Ads Manager'', ''TikTok Ads'', ''Notion'', ''ChatGPT'', ''Big Picture'']
Kỹ năng mềm: [''Chủ động'', ''Nghiêm túc'', ''Teamwork'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm 100% Online linh động', '[''Được đào tạo bài bản từ đầu, từ các dự án thực tế'', ''Làm việc 100% online, thời gian linh hoạt'', ''Học các công cụ cần thiết'', ''Phát triển thành Planner quản lý dự án sau 06 tháng'', ''Được xác nhận thực tập, hướng dẫn làm báo cáo từ 9 điểm'', ''Có thưởng theo dự án'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (492, 10, 7, 'Nhân Viên Livestream Part - Time', 'Trực tiếp Livestream giới thiệu, tư vấn và bán các sản phẩm của công ty: Dược - mỹ phẩm, thực phẩm chức năng… Hướng dẫn, giải đáp thắc mắc của khách hàng về sản phẩm, các chương trình khuyến mãi, cách đặt hàng… Nghiên cứu sản phẩm, cập nhật thông tin sản phẩm mới để giới thiệu chính xác, hấp dẫn. Tham gia xây dựng hình ảnh thương hiệu, tăng sự nhận diện và thu hút khách hàng thông qua livestream. Ghi hình và quay video giới thiệu, review sản phẩm, lên chương trình Livestream. Các công việc khác theo yêu cầu của cấp trên.', 'Có kinh nghiệm livestream, bán hàng online là lợi thế. Khuôn mặt ưa nhìn, phong thái tự tin, giọng nói rõ ràng, dễ nghe, giao tiếp lưu loát, dẫn dắt người xem. Nhạy bén với các xu hướng trên mạng xã hội. Có am hiểu về Marketing, Tiktok, yêu thích công việc livestream, giao tiếp và thuyết phục khách hàng. Có khả năng xử lý tình huống nhanh, ứng biến linh hoạt trong các buổi phát sóng. Ham học hỏi, chịu khó và có trách nhiệm trong công việc. Sẵn sàng làm việc theo ca, lịch livestream linh hoạt. Ưu tiên ứng viên có thể nhận việc ngay.
Kỹ năng chuyên môn: [''Kỹ năng livestream'', ''Kỹ năng bán hàng online'']
Kỹ năng mềm: [''Giao tiếp lưu loát'', ''Xử lý tình huống nhanh'', ''Ham học hỏi'', ''Chịu khó'', ''Có trách nhiệm trong công việc'']', 'PART_TIME', 'ONSITE', 'tân phú', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Lương cứng + Thưởng doanh thu'', ''Ăn trưa miễn phí'', ''Tham gia BHXH, BHYT, BHTN đầy đủ sau thử việc'', ''Thưởng lễ, Tết, sinh nhật, lương tháng 13, du lịch, team building định kỳ'', ''Cơ sở vật chất, phòng livestream hiện đại, chuyên nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (493, 2, 7, 'Chuyên Viên Telesales', '(1) Tiếp cận khách hàng: Gọi điện thoại cho khách hàng dựa trên data có sẵn. Xác định nhu cầu và mong muốn của khách hàng để đưa ra giải pháp phù hợp. (2) Giới thiệu sản phẩm/dịch vụ in ấn: business card, menu, brochure, window decal, banner, ... Trình bày thông tin chi tiết về sản phẩm hoặc dịch vụ một cách rõ ràng và hấp dẫn. Giải đáp các thắc mắc của khách hàng về sản phẩm/dịch vụ. (3) Thuyết phục và chốt đơn hàng: Sử dụng kỹ năng giao tiếp và thuyết phục để tạo nên nhu cầu ở khách hàng. Đàm phán các điều khoản bán hàng, giá cả, và chốt đơn hàng thành công. (4) Xử lý đơn hàng và thông tin khách hàng: Ghi nhận và cập nhật thông tin khách hàng vào hệ thống quản lý. Đảm bảo các đơn hàng được xử lý nhanh chóng và chính xác. (5) Chăm sóc khách hàng: Theo dõi và duy trì mối quan hệ với khách hàng hiện tại. Giải quyết các khiếu nại và phản hồi của khách hàng một cách hiệu quả.', '* Từ 6 tháng kinh nghiệm ở vị trí liên quan. * Có laptop cá nhân. * Khả năng giao tiếp tốt. * Biết sử dụng cơ bản các phần mềm tin học văn phòng. * Có tính kiên trì, chịu khó.
Kỹ năng chuyên môn: [''Sử dụng cơ bản các phần mềm tin học văn phòng'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Tính kiên trì'', ''Chịu khó'']', 'FREELANCE', 'ONSITE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Full-time: 5 giờ/ngày, Part-time: 2 giờ/ngày, Làm việc trong khung giờ: Từ 9:00 PM đến 8:00 AM (giờ Việt Nam)', '[''Thưởng tháng 13'', ''Thưởng theo Quý'', ''Thưởng hiệu quả làm việc'', ''Thời gian làm việc linh hoạt'', ''Các chương trình phúc lợi của công ty'', ''Tham gia các hoạt động văn hóa đoàn thể trong năm: Nghỉ mát, Teambuilding, Thể thao'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (494, 3, 7, 'Thực Tập Sinh CONTENT MARKETING PART-TIME', '- Sáng tạo nội dung thu hút cho các kênh truyền thông của AOM: Fanpage, Tiktok - Đề xuất các cải tiến cho các chiến dịch content marketing trong tương lai. - Phối hợp Teamwork triển khai chiến lược/mục tiêu Marketing - Phối hợp các Bộ phận khác sản xuất và triển khai các nội dung content để đạt mục tiêu Kinh doanh/Thương hiệu. - Thực hiện các nhiệm vụ khác theo yêu cầu của Trưởng phòng/ BGĐ', '- Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp chuyên ngành Truyền thông, Marketing, Tiếp thị, hoặc một lĩnh vực liên quan. - Có kỹ năng viết và giao tiếp tốt, đặc biệt là khả năng tạo lập nội dung hấp dẫn và sáng tạo. - Hứng thú với lĩnh vực mỹ phẩm thiên nhiên và khả năng làm việc độc lập cũng như làm việc nhóm. - Có kiến thức cơ bản về các công cụ đồ họa (photoshop, canva) là một lợi thế. - Ưu tiên khuôn mặt ưa nhìn, không ngại lên hình. - Đam mê về thiên nhiên và bảo vệ môi trường
Kỹ năng chuyên môn: [''Photoshop'', ''Canva'']
Kỹ năng mềm: [''Kỹ năng viết'', ''Giao tiếp'', ''Sáng tạo nội dung'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Thử việc 20-25.000đ/giờ'', ''Thưởng lễ tết, KPI'', ''Hỗ trợ dấu, tài liệu thực tập'', ''Đào tạo tư duy MKT từ a - z'', ''Được đào tạo kỹ năng chuyên môn & kỹ năng mềm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (495, 7, 7, 'Tiếp thị nội dung (Bán thời gian)', 'Sáng tạo nội dung trên các kênh truyền thông cho công ty và khách hàng chủ yếu ở nền tảng Tiktok và Facebook/ Instagram và Threads. Hỗ trợ trong việc định hướng và phát triển các concept nội dung mới lạ, mang tính viral trên các nền tảng số. Lên kế hoạch nội dung hàng tháng và các công việc phát sinh. Liên tục nắm bắt nhanh nhạy các xu hướng trên nền tảng và đề xuất ý tưởng sáng tạo nhằm truyền thông cho các dự án của công ty và tạo hiệu ứng lan truyền tốt. Đồng bộ hóa thương hiệu của công ty trên các kênh truyền thông tới khách hàng. Đảm bảo chất lượng nội dung, hoàn thành đúng KPI và Deadline. Các công việc khác được giao.', 'Tối thiểu 1 năm ở vị trí sáng tạo nội dung. Ưu tiên ứng viên có hiểu biết về branding agency. Thành thạo các kĩ năng: viết nội dung, lên kịch bản, quay dựng, edit video cơ bản. Sáng tạo, nhạy bén với trend và có tư duy đổi mới, đi đầu. Am hiểu và đam mê sáng tạo nội dung trên mạng xã hội. Có thẩm mỹ hình ảnh tốt, năng động và tự tin.
Kỹ năng chuyên môn: [''viết nội dung'', ''lên kịch bản'', ''quay dựng'', ''edit video cơ bản'']
Kỹ năng mềm: [''sáng tạo'', ''nhạy bén với trend'', ''tư duy đổi mới'', ''có thẩm mỹ hình ảnh'', ''năng động'', ''tự tin'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thời gian linh hoạt, tối thiểu 5 buổi/1 tuần', '[''Môi trường agency trẻ trung, năng động và thân thiện'', ''Không gian văn phòng thoải mái và sáng tạo, được cấp máy tính làm việc'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (496, 8, 7, 'Thực Tập Sinh Phòng Marketing', 'Quay, dựng clips cơ bản. Cắt, chỉnh sửa video, hỗ trợ sản xuất video. Đưa ra ý tưởng và chủ động thiết kế banner, flyer, ấn phẩm tái bản. Tham gia các sự kiện tại trường Đại học (2-3 sự kiện/tháng). Dịch thuật Anh Việt. Tìm hiểu từ khóa hot cho các khóa học dài hạn, lên ý tưởng viết bài tư vấn SEO. Đăng tin website dựa trên nội dung mailchimp được duyệt hàng ngày. Hỗ trợ cập nhật tin tức, nội dung, hình ảnh trên các chuyên mục website, các kênh social media của công ty đầy đủ, chính xác và kịp thời.', 'Sinh viên Đại Học chuyên ngành Marketing, Kinh Tế năm cuối hoặc vừa tốt nghiệp. Thực tập full-time từ tối thiểu 3 tháng trở lên. Tư duy logic, nhạy bén. Hoạt bát và giao tiếp tốt. Định hướng nghề nghiệp rõ ràng. Chăm chỉ và nghiêm túc trong công việc. Ưu tiên SV có kỹ năng MC, công tác Đoàn, Đội sẽ được tạo điều kiện phát huy năng khiếu.
Kỹ năng chuyên môn: [''Kỹ năng MC'', ''Tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Tư duy logic'', ''Nhạy bén'', ''Hoạt bát'', ''Giao tiếp tốt'', ''Chăm chỉ'', ''Nghiêm túc trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Thực tập có lương'', ''Được trải nghiệm công việc thật'', ''Được tham gia đào tạo nội bộ'', ''Được mở rộng mối quan hệ'', ''Được hỗ trợ thông tin làm bài báo cáo'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (497, 9, 7, 'Nhân Viên Marketing Part Time', 'Phụ trách nội dung các viết bài đăng tải trên nền tảng online gia tăng sự nhận diện thương hiệu đến với khách hàng. Tiếp cận các khu vực trường học, toà nhà trực tiếp nhằm tìm kiếm KH tiềm năng. Các kế hoạch khác được tổ chức bởi phòng Marketing và cơ sở hiện đang làm việc.', 'Ưu tiên các bạn đại học chuyên ngành báo chí, truyền thông (hoặc) đã có kinh nghiệm làm việc trong lĩnh vực này. Tin học văn phòng. Giao tiếp Tiếng Anh cơ bản. Thời gian làm việc: xoay ca. Ca sáng chiều/ Ca chiều tối theo sự sắp xếp của Công ty.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Giao tiếp'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.5 - 4.0 triệu', 'Xoay ca linh hoạt, 3 ca: sáng, chiều, tối', '[''Môi trường làm việc trẻ, năng động'', ''Cơ hội tăng kĩ năng tiếng Anh'', ''Tham gia các hoạt động nghỉ mát, teambuilding'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (498, 10, 7, 'Content Social Part-Time', 'Lên ý tưởng và viết nội dung sáng tạo cho các kênh social: Facebook, Instagram, TikTok, v.v. Phối hợp với team thiết kế, media để sản xuất bài viết, hình ảnh, video ngắn phù hợp với từng nền tảng. Theo dõi, đánh giá hiệu quả các nội dung đăng tải (reach, engagement, conversion...) và tối ưu định kỳ. Nắm bắt xu hướng thị trường, trend hot để đề xuất nội dung bắt trend kịp thời. Hỗ trợ các hoạt động truyền thông nội bộ, seeding, event hoặc chiến dịch marketing khác khi cần.', 'Có kinh nghiệm từ 6 tháng trở lên ở vị trí content hoặc quản trị fanpage. Có khả năng viết sáng tạo, đúng tone & voice thương hiệu, tư duy hình ảnh tốt. Biết sử dụng các nền tảng social phổ biến, nắm bắt xu hướng nhanh. Ưu tiên ứng viên biết cơ bản về Canva, CapCut, hoặc các công cụ edit đơn giản.
Kỹ năng chuyên môn: [''Canva'', ''CapCut'']
Kỹ năng mềm: [''Viết sáng tạo'', ''Tư duy hình ảnh'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Môi trường làm việc thoải mái, linh động'', ''Được cung cấp đầy đủ trang thiết bị phục vụ công việc'', ''Cơ hội mở rộng network & làm việc trong ngành game và CNTT'', ''Các hoạt động gắn kết: Tiệc sinh nhật hàng tháng, Tiệc liên hoan cuối năm, team building, nghỉ mát, sinh hoạt tập thể.'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (499, 2, 7, 'Thực Tập Sinh Account Marketing', 'Tiếp cận, tư vấn và phát triển các khách hàng tiềm năng có sẵn. Xây dựng và duy trì mối quan hệ bền vững với khách hàng hiện tại. Phân tích và nắm bắt sâu sắc nhu cầu, mục tiêu của khách hàng để đưa ra giải pháp phù hợp. Phối hợp các team xây dựng kế hoạch truyền thông cho khách hàng. Hỗ trợ triển khai, theo dõi, báo cáo hiệu quả chiến dịch quảng cáo cho khách hàng và đưa ra giải pháp phù hợp với kế hoạch tiếp theo cho khách hàng. Hỗ trợ đảm bảo việc cung cấp dịch vụ và sản phẩm cho khách hàng được thực hiện đúng lúc, đáp ứng được nhu cầu và mục tiêu của khách hàng. Hỗ trợ liên hệ chăm sóc khách hàng, khảo sát đánh giá chất lượng dịch vụ sau bán hàng.', 'Sinh viên theo chuyên ngành Marketing, QTKD, Ngoại thương, FPT,... Có hiểu biết cơ bản về marketing, quảng cáo và truyền thông trực tuyến. Ưu tiên ứng viên có định hướng phát triển lên nhân viên chính thức tại công ty. Ưu tiên ứng viên có khả năng Tiếng Anh giao tiếp tốt sẽ được tham gia các dự án với khách hàng nước ngoài.
Kỹ năng chuyên môn: [''Hiểu biết cơ bản về marketing'', ''Quảng cáo'', ''Truyền thông trực tuyến'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng phân tích'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.5 - 2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Thưởng Lễ, Tết'', ''Môi trường làm việc trẻ trung, năng động'', ''Du lịch theo chính sách của công ty'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (500, 3, 7, 'Thực Tập Sinh Truyền Thông', 'Sản xuất nội dung cho các dự án âm nhạc của công ty: Chỉnh sửa, cắt ghép hình ảnh, video, nội dung đăng tải trên các nền tảng - chủ yếu là Tiktok. Kết hợp với các bộ phận khác để lên kế hoạch, ý tưởng cho những dự án mới, liên tục tìm hiểu và cập nhật về xu hướng âm nhạc. Được hướng dẫn thực hiện lên content xây dựng Tiktok. Viết kịch bản và nội dung hàng ngày cho các kênh Tik Tok hệ thống. Đi quay một số content tiktok cùng Team và Nghệ Sĩ. Học và tạo các mẫu template capcut hot trend trên nên tảng CapCut.', 'Biết sử dụng Capcut - thành thạo là điểm cộng.( Chưa có kinh nghiệm sẽ được hướng dẫn). Nam/nữ dưới 23 tuổi. Chấp nhận sinh viên mới ra trường/sinh viên thực tập. Có kinh nghiệm hoặc đã từng làm về các mảng truyền thông. Ưu Tiên các bạn và đang học về ngành truyền thông. Yêu thích và có hiểu biết về âm nhạc, có gu thẩm mỹ, tư duy sáng tạo. Yêu thích âm nhạc và các video trên nền tảng giải trí nhanh như Youtube, Facebook, Tiktok…. Có thái độ hòa đồng, học hỏi ,tiếp thu nhanh, cầu tiến và làm việc nhóm tốt. Hướng ngoại, có khả năng sáng tạo. Ưu tiên các bạn có laptop cá nhân. Thành thạo kỹ năng sự dụng máy tính. Có ngoại hình là một lợi thế. Công việc liên qua nhiều về cập nhật tin tức trend và âm nhạc, nên yêu cầu có thể làm việc vào buổi tối.
Kỹ năng chuyên môn: [''Capcut'']
Kỹ năng mềm: [''Học hỏi'', ''Tiếp thu nhanh'', ''Làm việc nhóm'', ''Sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Môi trường làm việc năng động'', ''Được hướng dẫn, đào tạo bài bản'', ''Cơ hội trở thành nhân viên chính thức'', ''Tham gia các hoạt động ngoại khóa'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (501, 7, 7, 'Nhân Viên Livestream/Streamer TikTok', 'Livestream cực đỉnh trên TikTok, giao lưu và kết nối với cộng đồng fan đông đảo. Được hướng dẫn chi tiết về nội dung, phong cách livestream ngay cả khi bạn chưa có kinh nghiệm. Tự do sáng tạo – bạn có thể chọn cách livestream riêng biệt: trò chuyện, hát, nhảy, kể chuyện, hoặc thể hiện những tài năng độc đáo khác. Linh hoạt địa điểm livestream: bạn có thể stream tại nhà hoặc văn phòng, tùy thích!', 'Bạn có thể livestream trò chuyện, hát, chơi game nhẹ, mukbang, cosplay, tâm sự. Là người Việt Nam, có khả năng giao tiếp tốt. Hỗ trợ cả những bạn mới chưa có kinh nghiệm.
Kỹ năng chuyên môn: [''Sáng tạo nội dung'', ''Quay Phim Và Chỉnh Sửa Video'', ''Hiểu Biết Về Xu Hướng Tiktok'', ''Kỹ Năng Giao Tiếp Trước Ống Kính'', ''Xây Dựng Và Tương Tác Cộng Đồng'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Tự tin'']', 'FREELANCE', 'REMOTE', 'hồ chí minh', 'Hồ Chí Minh', 'FIXED_PROJECT', 20000000.00, '5.0 - 20.0 triệu', 'Thời gian làm việc linh động', '[''Hướng dẫn từ A-Z'', ''Thưởng nóng đến 500 nghìn cho bạn nào live tốt trong tuần đầu'', ''Làm việc tại nhà, online 100%'', ''Mức lương cứng: 2.000.000 VNĐ / tháng'', ''Thưởng thêm năm trăm nghìn đồng nếu bạn đạt 10.000 kim cương đầu tiên'', ''Bonus thêm hai trăm nghìn đồng/người nếu bạn bè cùng làm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (502, 8, 7, 'Thiết kế đồ họa thực tập', 'Đảm nhận công việc thiết kế các sản phẩm (Poster, backdrop, banner,...) phục vụ hoạt động truyền thông cho các chương trình, sự kiện của công ty; Phối hợp với content và các thành viên trong team để sản xuất nội dung và hình ảnh chất lượng; Học tập các quy trình làm việc thiết kế đồ hoạ chuyên nghiệp; Tham gia brainstorm cùng Team truyền thông để đưa ra các ý tưởng sáng tạo; Thiết kế mới và resize các thiết kế đã có sẵn theo yêu cầu.', 'Sinh viên đang theo học chuyên ngành Thiết kế Đồ họa, Truyền thông đa phương tiện hoặc các lĩnh vực liên quan; Sử dụng tốt các phần mềm thiết kế như Adobe Photoshop, Ilustrator, InDesign; Ưu tiên biết sử dụng phần mềm dựng video...; Chủ động trong công việc và có khả năng sáng tạo, hanh nhẹn, hòa đồng khả năng giao tiếp tốt.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Illustrator'', ''InDesign'']
Kỹ năng mềm: [''Chủ động trong công việc'', ''Có khả năng sáng tạo'', ''Nhanh nhẹn'', ''Hòa đồng'', ''Khả năng giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Có cơ hội trở thành cộng tác viên, nhân viên chính thức với mức thu nhập hấp dẫn sau quá trình đào tạo'', ''Được đào tạo, hướng dẫn, định hướng chuyên môn sớm bởi các kỹ sư, chuyên gia giàu kinh nghiệm'', ''Hỗ trợ đánh giá và dấu mộc thực tập'', ''Tham gia các hoạt động văn hoá, sự kiện hấp dẫn của Công ty FPT IS và Tập đoàn FPT'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (503, 9, 7, 'Thực Tập Sinh Marketing', 'Hỗ trợ quản lý hoạt động trên các nền tảng, FB, Website... Hỗ trợ Xây dựng content thu hút, bắt trend, dễ tiếp cận... Hỗ trợ Chạy ads bài viết fanpage Hỗ trợ Nắm bắt tình hình biến động của thị trường, thị hiếu... để đề xuất kế hoạch, chi phí cho các chương trình quảng bá, mục tiêu thu hút khách hàng tiềm năng sử dụng dịch vụ của Công ty.', 'Sinh viên năm cuối đã hoàn thành chương trình học. Học lực KHÁ GIỎI. Không cần kinh nghiệm. Siêng năng, chịu học hỏi, năng động và nhiệt tình. Có định hướng lâu dài và rõ ràng.
Kỹ năng mềm: [''Siêng năng'', ''Chịu học hỏi'', ''Năng động'', ''Nhiệt tình'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 từ 08h00 đến 12h00', '[''Được cấp đầy đủ trang thiết bị để làm việc'', ''Được hỗ trợ dấu mộc báo cáo sau 2⁄3 thời gian thực tập'', ''Được đào tạo chuyên môn lý thuyết + thực hành'', ''Được làm việc trong môi trường chuyên nghiệp'', ''Cơ hội gắn bó cùng công ty sau thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (504, 10, 7, 'Video Intern', 'Sản xuất video, nội dung sản phẩm theo hướng dẫn (theo loại và danh mục sản phẩm, đảm bảo sản phẩm ra mắt kịp thời với tiêu chuẩn chất lượng cao nhất). Hỗ trợ sản xuất video, nội dung cho các chiến dịch marketing. Hỗ trợ livestream. Tìm kiếm, tổng hợp, sản xuất và cập nhật nội dung, hình ảnh sản phẩm tiếng Việt và tiếng Anh. Thực hiện các công việc khác theo phân công từ Quản lý.', 'GPA 3.0/4.0 trở lên hoặc tương đương. Ưu tiên Sinh viên giao tiếp tốt tiếng Hàn hoặc tiếng Anh. Khả năng tổ chức sắp xếp công việc, quản lý thời gian tốt. Có kinh nghiệm lên kịch bản, quay dựng video. Tự tin, ngoại hình sáng, không ngại tham gia quay clip, tham gia livestream.
Kỹ năng chuyên môn: [''Kỹ năng lên kịch bản'', ''Kỹ năng quay dựng video'']
Kỹ năng mềm: [''Khả năng tổ chức sắp xếp công việc'', ''Quản lý thời gian'', ''Tự tin'', ''Ngoại hình sáng'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '08:00 đến 17:00 (T2 - T6)', '[''Phụ cấp tiền cơm: 40.000 đồng/ngày'', ''Hỗ trợ mộc thực tập'', ''Đào tạo, hướng dẫn làm việc thực tế'', ''Cơ hội trở thành nhân viên chính thức sau thời gian thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (505, 2, 7, 'Thực Tập Sinh Thiết Kế Đồ Họa', 'Lên ý tưởng sáng tạo & thiết kế các tài liệu, ấn phẩm. Hỗ trợ thiết kế các ấn phẩm truyền thông & tài liệu sản phẩm (social media & print ads). Hỗ trợ chụp hình quảng cáo, hình ảnh sản phẩm.', 'Ưu tiên sinh viên chuyên ngành Thiết kế đồ họa hoặc các ngành liên quan. Năng động, chủ động trong công việc, tinh thần học hỏi cao. Ưu tiên thành thạo các tools chỉnh sửa: PS, AI, Figma. Ưu tiên có kinh nghiệm mảng UX/UI, Video Editing cơ bản. Ưu tiên sinh viên ngành Thiết kế đồ họa, mỹ thuật hoặc có định hướng về lĩnh vực thiết kế. Ưu tiên có laptop để chủ động công việc.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Figma'']
Kỹ năng mềm: [''Năng động'', ''Chủ động trong công việc'', ''Tinh thần học hỏi cao'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Môi trường làm việc chuyên nghiệp'', ''Phụ cấp thực tập'', ''Chi phí gửi xe'', ''Tham gia các hoạt động nội bộ'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (506, 3, 7, 'Freelancer Vận Hành Sàn Thương Mại Điện Tử', 'Thực hiện các gói dịch vụ theo checklist: tạo gian hàng, tối ưu SEO, đăng sản phẩm, buff đơn, tăng đánh giá, chạy quảng cáo, vận hành gian hàng… Giao file, báo cáo tiến độ và update trạng thái trên hệ thống Lark/Sheet. Đảm bảo chất lượng và tiến độ theo timeline đã cam kết với khách. Kết hợp với CSKH nếu cần xử lý phát sinh.', 'Có kinh nghiệm vận hành gian hàng Shopee/TikTokShop, biết thiết kế và chạy quảng cáo là một lợi thế. Thành thạo Google Sheet, Drive, các công cụ quản lý công việc cơ bản. Làm việc có trách nhiệm, tỉ mỉ, báo cáo rõ ràng. Ưu tiên freelancer từng cộng tác với agency hoặc từng làm chủ shop.
Kỹ năng chuyên môn: [''Google Sheet'', ''Google Drive'', ''Thiết kế quảng cáo'']
Kỹ năng mềm: [''Trách nhiệm'', ''Tỉ mỉ'', ''Báo cáo rõ ràng'']', 'FREELANCE', 'ONSITE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 18:00)', '[''Thanh toán theo gói dịch vụ hoàn thành, nhận từ 15-20% giá trị gói dịch vụ'', ''Thưởng theo doanh thu khi vận hành'', ''Thưởng khi vượt số lượng gói dịch vụ trong 1 tháng'', ''Hỗ trợ quy trình – file – checklist đầy đủ'', ''Cơ hội làm việc lâu dài nếu chất lượng tốt và đúng deadline'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (507, 7, 7, 'Nhân Viên Marketing Du Lịch Inbound (Parttime)', 'Thực hiện truyền thông thương hiệu công ty và sản phẩm theo sự phân công của Team Leader. Xây dựng, quản lý và tối ưu nội dung trên các kênh mạng xã hội. Được đào tạo để sử dụng các công cụ đăng bài trên WordPress. Tham gia hỗ trợ các hoạt động/sự kiện quảng bá thương hiệu sản phẩm/công ty. Quản lý và viết bài cho các kênh truyền thông của công ty, bao gồm các website và nhóm/fanpage facebook. Hỗ trợ sản xuất các ấn phẩm truyền thông liên quan đến các sản phẩm và dịch vụ của công ty. Đi khảo sát điểm đến khi được yêu cầu. Các công việc khác theo yêu cầu của Trưởng bộ phận.', 'Ham học hỏi, siêng năng, nhanh nhẹn. Tư duy logic tốt, có trách nhiệm với công việc. Có laptop cá nhân. Có khả năng đọc hiểu và sử dụng Tiếng Anh khá. Có khả năng viết & sáng tạo nội dung tốt. Nhạy bén, năng động, sáng tạo, có tinh thần trách nhiệm với công việc. Ham học hỏi, tư duy tích cực, có mong muốn phát triển bản thân trong môi trường trẻ trung, năng động.
Kỹ năng chuyên môn: [''SEO/SEM'', ''Marketing Kỹ Thuật Số'', ''Thiết Kế Đồ Họa Cơ Bản (photoshop, Canva)'', ''Quảng Cáo Trên Mạng Xã Hội (facebook, Instagram,...)'', ''Viết Nội Dung Marketing (tiếng Việt)'']
Kỹ năng mềm: [''Ham học hỏi'', ''Siêng năng'', ''Nhanh nhẹn'', ''Tư duy logic tốt'', ''Có trách nhiệm với công việc'', ''Nhạy bén'', ''Năng động'', ''Sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.8 triệu', 'Tối thiểu 20h/tuần, linh động giữa 2 ca: Sáng: 8h30 – 12h30, Chiều: 13h30 – 17h30', '[''Có cơ hội trở thành nhân viên chính thức sau 3 tháng học việc'', ''Được đào tạo & hướng dẫn công việc của một chuyên viên truyền thông & marketing chuyên nghiệp'', ''Tham gia các hoạt động truyền thông đối ngoại của công ty'', ''Trải nghiệm văn hóa doanh nghiệp hiện đại'', ''Đi khảo sát các điểm du lịch miễn phí'', ''Được làm việc trong môi trường năng động, chuyên nghiệp, nhiều cơ hội phát triển'', ''Được tham gia các sự kiện nội bộ, các khóa đào tạo chuyên môn/kỹ năng của công ty'', ''Hỗ trợ xin dấu thực tập và có giấy chứng nhận'', ''Nhận lương theo giờ làm: 25k/h. Ăn trưa tại công ty khi làm full ngày'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (508, 8, 7, 'Thực Tập Sinh Thiết Kế Đồ Họa', '- Thực hiện và quản lý công việc thiết kế phục vụ Marketing - Thiết kế các hạng mục phục vụ Digital Marketing như: banner, landing page, infographic, post, cover fanpage facebook - Thiết kế ảnh theo nội dung bài viết có sẵn - Lên ý tưởng, thiết kế các hình ảnh phục vụ nhu cầu Marketing quảng bá thương hiệu của công ty, sản phẩm, ấn phẩm ... - Chỉnh sửa, tạo Video giới thiệu sản phẩm, Công ty ... - Tham gia thiết kế hình ảnh cho các chương trình khuyến mại / chiến dịch truyền thông của công ty, banner công ty, hệ thống website công ty', '- Tốt nghiệp đại học hoặc là sinh viên năm 3 trở lên chuyên ngành Thiết Kế Đồ Họa - Có kinh nghiệm về thiết kế đồ họa, biết chụp ảnh và dàn dựng video ở mức cơ bản - Sử dụng tốt một trong các phần mềm thiết kế hình ảnh như: Photoshop, AI, InDesign, Adobe Premiere ... - Khả năng lên ý tưởng tốt, tiếp thu công việc nhanh, nhiệt tình, chịu được áp lực công việc - Tinh thần trách nhiệm, ham học hỏi, năng động, sáng tạo trong công việc - Làm Full Time 2-3 tháng
Kỹ năng chuyên môn: [''Photoshop'', ''AI'', ''InDesign'', ''Adobe Premiere'']
Kỹ năng mềm: [''Khả năng lên ý tưởng tốt'', ''Tiếp thu công việc nhanh'', ''Nhiệt tình'', ''Chịu được áp lực công việc'', ''Tinh thần trách nhiệm'', ''Ham học hỏi'', ''Năng động'', ''Sáng tạo trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:15)', '[''Được làm việc trong môi trường chuyên nghiệp'', ''Được xem xét tuyển dụng thẳng sau thực tập'', ''Có chế độ hỗ trợ tùy theo kết quả công việc'', ''Đi quay, chụp tại các sự kiện được nhận công tác phí'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (509, 9, 7, 'Thực Tập Content Marketing-Online/Remote-Lương', '- Sử dụng hình ảnh & thông tin căn hộ có sẵn trên hệ thống căn hộ dịch vụ An Home để: * Thiết kế hình ảnh, dựng video thu hút khách hàng * Sáng tạo content để thu hút khách hàng tiềm năng thuê căn hộ. * Đăng tải content lên các nền tảng: Facebook (Fanpage, Group, Marketplace), TikTok, Threads.... - Chủ đề xoay quanh: thuê căn hộ dịch vụ, căn hộ mini, căn hộ ngắn hạn/dài hạn tại TP.HCM - Mục tiêu: Thu hút khách hàng tiềm năng thuê căn hộ', 'Biết dùng Canva, CapCut, ChatGPT Biết chỉnh sửa video cơ bản Biết chỉnh sửa hình ảnh Có tinh thần tự học, chủ động , kỷ luật bản thân. Yêu thích marketing, bất động sản, căn hộ dịch vụ….
Kỹ năng chuyên môn: [''Canva'', ''CapCut'', ''ChatGPT'', ''Chỉnh sửa video cơ bản'', ''Chỉnh sửa hình ảnh'']
Kỹ năng mềm: [''Tinh thần tự học'', ''Chủ động'', ''Kỷ luật bản thân'', ''Yêu thích marketing'', ''Yêu thích bất động sản'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Linh hoạt', '[''Được cấp giấy xác nhận thực tập (mộc đỏ)'', ''Thưởng từ 2-4 triệu nếu đạt kết quả mỗi tháng'', ''Hình thức: Online'', ''Tài nguyên hỗ trợ: App căn hộ dịch vụ An Home – đầy đủ hình & thông tin'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (510, 10, 7, 'Thực Tập Sinh Marketing', 'PR, marketing sử dụng digital marketing. Viết content, thảo luận với khách qua mạng xã hội. Lên kế hoạch marketing cho công ty. Thảo luận, tư vấn với khách, học viên về dự án.', 'Là sinh viên năm 3 trở lên, ưu tiên các ngành Marketing / Quản trị kinh doanh ... Hiểu biết về content marketing, marketing online, mạng xã hội... Có kinh nghiệm phát triển cộng đồng trên các trang mạng xã hội... Tinh thần trách nhiệm cao, tâm huyết với công việc.
Kỹ năng chuyên môn: [''Content marketing'', ''Marketing online'', ''Mạng xã hội'']
Kỹ năng mềm: [''Tinh thần trách nhiệm cao'', ''Tâm huyết với công việc'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường chuyên nghiệp'', ''Xem xét tuyển dụng thẳng sau thực tập'', ''Thực tập 3 tháng có dấu công ty'', ''Thưởng theo số lượng học viên / dự án'', ''Chỗ ở tại công ty với chi phí ưu đãi'', ''Ưu tiên thực tập toàn thời gian'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (511, 2, 7, 'Sản phẩm/dự án hỗ trợ thực tập', 'Hỗ trợ chuẩn bị slide trình bày cho các cuộc họp, báo cáo dự án, tài liệu nội bộ. Thiết kế và trình bày nội dung bằng Canva, PowerPoint hoặc Google Slides. Ghi chú biên bản họp, tổng hợp ý chính từ các team liên quan. Sắp xếp, cập nhật tài liệu dự án: biểu mẫu, quy trình làm việc, roadmap. Hỗ trợ các công việc vận hành của team sản phẩm/dự án theo sự phân công.', 'Là sinh viên năm 4 hoặc mới tốt nghiệp các ngành Marketing, Thiết kế hoặc các ngành liên quan. Thành thạo Canva (biết cách sử dụng các template, căn chỉnh bố cục, phối màu, chèn biểu tượng, hình ảnh...). Kỹ năng tổng hợp và viết nội dung tốt (ưu tiên nếu từng làm tài liệu, báo cáo hoặc content). Tỉ mỉ, có trách nhiệm, giao tiếp tốt, có tinh thần học hỏi và làm việc nhóm. Ưu tiên nếu đã từng tham gia vào các CLB/trường hoặc có kinh nghiệm làm việc nhóm, hỗ trợ dự án.
Kỹ năng chuyên môn: [''Canva'', ''PowerPoint'', ''Google Slides'']
Kỹ năng mềm: [''Kỹ năng tổng hợp và viết nội dung'', ''Tỉ mỉ'', ''Có trách nhiệm'', ''Giao tiếp tốt'', ''Có tinh thần học hỏi'', ''Làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'phú nhuận', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Trợ cấp thực tập hàng tháng (thỏa thuận theo năng lực)'', ''Cơ hội tham gia các dự án nội bộ và được training bởi team sản phẩm/dự án có kinh nghiệm'', ''Làm việc trong môi trường trẻ, năng động, khuyến khích sáng tạo'', ''Được training 1:1'', ''Có cơ hội lên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (512, 3, 7, 'Nhân Viên Seo Content', 'Sử dụng công cụ phân tích SEO như Google Analytics, Google Search Console, Ahrefs, SEMrush để tăng traffic tự nhiên cho website. Lên kế hoạch Đăng sản phẩm, bài viết chuẩn SEO. Đề xuất các thay đổi/cải thiện về cấu trúc website, content, linking cũng như các yếu tố khác nhằm ưu hiệu quả SEO.', 'Có kiến thức cơ bản về SEO. Sẵn sàng nghiên cứu kiến thức mới. Tinh thần trách nhiệm cao, cẩn thận, tỉ mỉ trong công việc.
Kỹ năng chuyên môn: [''Google Analytics'', ''Google Search Console'', ''Ahrefs'', ''SEMrush'']
Kỹ năng mềm: [''Tinh thần trách nhiệm cao'', ''Cẩn thận'', ''Tỉ mỉ'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Thưởng KPI'', ''Thưởng trực tiếp theo hiệu quả công việc'', ''Đóng dấu đỏ thực tập của công ty'', ''Chứng nhận có đóng góp cho công ty'', ''Chứng nhận tham gia Global Marketing'', ''Chứng nhận tham gia Triển Lãm Quốc Tế của công ty'', ''Môi trường làm việc năng động, sáng tạo'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (513, 7, 7, 'Thực Tập Sinh Content Marketing', 'Phụ trách content cho các kênh của công ty. Lên kế hoạch xây dựng các cộng đồng mục tiêu. Quản lý email marketing. Tham gia lên kế hoạch các chiến dịch marketing của công ty.', 'Chịu khó, ham học hỏi. Cẩn thận, tỉ mỉ trong công việc. Nhanh nhẹn, chủ động trong công việc. Có kinh nghiệm viết content là 1 lợi thế. Có kỹ năng làm việc nhóm. Chưa có kinh nghiệm sẽ được đào tạo. Sinh viên đang theo học chuyên ngành Marketing, Kinh tế hoặc các ngành liên quan. Biết sử dụng các công cụ như: Canva, TikTok, AI tools, Photoshop,… là một lợi thế. Năng động, nhanh nhẹn, linh hoạt, giao tiếp tốt. Có laptop cá nhân để làm việc.
Kỹ năng chuyên môn: [''Canva'', ''TikTok'', ''AI tools'', ''Photoshop'']
Kỹ năng mềm: [''Chịu khó'', ''Ham học hỏi'', ''Cẩn thận'', ''Tỉ mỉ'', ''Nhanh nhẹn'', ''Chủ động'', ''Kỹ năng làm việc nhóm'', ''Giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', 'Linh động theo lịch học của ứng viên', '[''Hỗ trợ phụ cấp, lương'', ''Được hỗ trợ con dấu thực tập'', ''Môi trường làm việc chuyên nghiệp'', ''Được đào tạo bài bản về nghiệp vụ'', ''Cơ hội đi du lịch, teambuilding, công tác nước ngoài hàng năm'', ''Chế độ phúc lợi và nhiều đãi ngộ đặc biệt của công ty'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (514, 8, 7, 'Thực Tập Sinh SEO Content Marketing', 'Hỗ trợ quản lý kênh thương mại điện tử (Shopee, Tik Tok Shop,...). Quản lý và sáng tạo content trên các Fanpage của công ty. Sáng tạo nội dung SEO cho trang Web. Chi tiết công việc sẽ được hướng dẫn 1 kèm 1 khi thực hiện.', 'Không yêu cầu kinh nghiệm, sẽ được đào tạo. Thời gian thực tập: tối thiểu 5 ngày/ tuần. Ưu tiên Sinh viên mới tốt nghiệp hoặc sinh viên đang theo học ngành Marketing. Có laptop cá nhân. Biết sử dụng các phần mềm office cơ bản, canva.
Kỹ năng chuyên môn: [''Sử dụng phần mềm office cơ bản'', ''Canva'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Phụ cấp thực tập: 1.000.000đ'', ''Hoa hồng 2% từ doanh số các sàn thương mại'', ''Được đào tạo 1:1 kiến thức sâu về chuyên môn Marketing'', ''Hỗ trợ học hỏi các kỹ năng cần thiết miễn phí'', ''Hỗ trợ dấu mộc báo cáo thực tập'', ''Được cọ sát và thực tiễn trong công việc, nâng cao kiến thức chuyên môn trước khi ra trường'', ''Linh động thời gian để xử lý các công việc tại nhà trường'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (515, 9, 7, 'Nhân Viên Livestream TikTok', 'Tham gia vào các buổi livestream trực tiếp trên fanpage Biluxury để giới thiệu sản phẩm thời trang, đặc biệt là các dòng quần áo nam như áo sơ mi, quần âu, polo, và phụ kiện. Giới thiệu sản phẩm, nhãn hàng, tính năng sản phẩm, giá bán, chương trình khuyến mãi... Phối hợp với đội ngũ marketing để xây dựng kịch bản và lên ý tưởng cho mỗi buổi livestream, đảm bảo phù hợp với chiến dịch truyền thông và mục tiêu kinh doanh. Làm việc tại studio chuyên nghiệp của công ty với đầy đủ thiết bị hỗ trợ live (ánh sáng, máy ảnh, điện thoại...). Sản phẩm bán: thời trang nam. Thời gian live linh động theo sắp xếp của Công ty. Thực hiện các công việc khác theo chỉ đạo của Quản lý trực tiếp.', 'Nam/nữ tuổi từ 18-30. Có kinh nghiệm Livestream, tự tin trước ống kính, ưu tiên kinh nghiệm diễn xuất. Giọng nói rõ ràng, giao tiếp lưu loát. Ngoại hình ưa nhìn, khuôn mặt sáng. Có chất giọng dễ nghe, thu hút, dẫn dắt người xem. Được đào tạo kỹ năng livestream, bán hàng online.
Kỹ năng chuyên môn: [''Kỹ Năng Tương Tác Với Khán Giả'', ''Kỹ Năng Sử Dụng Tiktok'', ''Kỹ Năng Livestream'', ''Kỹ Năng Giao Tiếp Trước Ống Kính'', ''Kỹ Năng Biên Tập Video Cơ Bản'']
Kỹ năng mềm: [''Giọng nói rõ ràng'', ''Giao tiếp lưu loát'', ''Ngoại hình ưa nhìn'', ''Khuôn mặt sáng'', ''Chất giọng dễ nghe'', ''Thu hút người xem'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 20000000.00, '15.0 - 20.0 triệu', 'Thời gian linh hoạt theo ca 4 tiếng', '[''Phụ cấp trách nhiệm'', ''Xăng xe & điện thoại'', ''Gửi xe'', ''Được đào tạo để nâng cao kiến thức, kỹ năng'', ''Nhiều cơ hội thăng tiến'', ''Môi trường làm việc trẻ trung, chuyên nghiệp'', ''Canteen tự phục vụ trà, cà phê, teabreak'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (516, 10, 7, 'Thực Tập Sinh Content', 'Hỗ trợ viết bài chuẩn SEO cho website, fanpage,… của công ty. Nghiên cứu từ khóa, lên outline và triển khai nội dung theo định hướng. Tham gia đóng góp ý tưởng cho các video, clip giới thiệu sản phẩm, dự án. Chăm sóc nội dung fanpage, seeding tăng tương tác. Báo cáo công việc hàng tuần.', 'Sinh viên năm 3, 4 chuyên ngành Truyền thông, Báo chí, Marketing, … hoặc các ngành có liên quan. Yêu thích viết lách, sáng tạo nội dung. Ứng viên có kinh nghiệm về content SEO, social là một điểm cộng. Có tư duy logic, sáng tạo, tinh thần cầu tiến. Năng động, nhanh nhẹn và có trách nhiệm.
Kỹ năng chuyên môn: [''Content SEO'', ''Social Media'']
Kỹ năng mềm: [''Sáng tạo'', ''Tư duy logic'', ''Năng động'', ''Trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Tối thiểu 4 buổi trong tuần', '[''Trợ cấp thực tập'', ''Môi trường làm việc năng động'', ''Hỗ trợ dấu mộc và số liệu báo cáo'', ''Tham gia các hoạt động giải trí, thể thao hàng tuần'', ''Cơ hội trở thành mảnh ghép chính thức tại HiFarm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (517, 2, 7, 'Nội dung SEO bán thời gian', 'Viết bài content theo yêu cầu, bao gồm bài PR, SEO, social media, blog, landing page… Nghiên cứu từ khóa, tối ưu nội dung chuẩn SEO theo hướng dẫn. Lên ý tưởng, xây dựng nội dung cho website. Hỗ trợ chỉnh sửa, cập nhật nội dung theo feedback từ khách hàng, team. Tham gia brainstorming, đóng góp ý tưởng phát triển nội dung.', 'Sinh viên năm cuối, sắp ra trường hoặc đã ra trường từ Đại học trở lên. Có kinh nghiệm viết content SEO (từ 3 tháng trở lên). Sáng tạo, chủ động, có trách nhiệm với công việc. Kỹ năng viết tốt, mạch lạc, đúng chính tả, ngữ pháp. Biết cách tối ưu nội dung theo SEO là lợi thế. Kiên trì, cẩn thận, tỉ mỉ cao để đảm bảo chất lượng nội dung. Có thể làm việc tối thiểu 5 buổi/tuần.
Kỹ năng chuyên môn: [''Viết content SEO'', ''Tối ưu nội dung theo SEO'']
Kỹ năng mềm: [''Sáng tạo'', ''Chủ động'', ''Có trách nhiệm với công việc'', ''Kỹ năng viết tốt'', ''Mạch lạc'', ''Đúng chính tả'', ''Ngữ pháp'', ''Kiên trì'', ''Cẩn thận'', ''Tỉ mỉ'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Lộ trình phát triển năng lực'', ''Phụ cấp xa nhà, công tác'', ''Môi trường làm việc chuyên nghiệp'', ''Làm việc linh hoạt, có thể remote'', ''Tham gia thực chiến tại các dự án lớn'', ''Được hướng dẫn, kèm cặp 1:1 bởi các Leader'', ''Cơ hội phát triển kỹ năng, mở rộng networking'', ''Được đào tạo về SEO, content marketing'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (518, 3, 7, 'Thực Tập Sinh Marketing', '- Xây dựng kế hoạch và timeline cho nội dung bài đăng tải facebook và các kênh truyền thông khác - Tiếp nhận thông tin, nhu cầu của khách hàng - Viết bài, lên content trên các nền tảng mạng xã hội Facebook, Instagram, .... - Nghiên cứu thị trường, cập nhật thông tin thị trường mới nhất để tham mưu cho cấp trên - Quản trị các webside - Biết Editor Video cơ bản là 1 lợi thế', '- Là sinh viên năm cuối các chuyên ngành liên quan đến marketing - Biết chụp ảnh ,edit hình ảnh là 1 lợi thế - Có khả năng viết nội dung và giao tiếp tốt - Có thể sử dụng các phần mềm Photoshop, AI, Canva,.... là 1 lợi thế - Chịu lắng nghe và thay đổi
Kỹ năng chuyên môn: [''Photoshop'', ''AI'', ''Canva'']
Kỹ năng mềm: [''Viết nội dung'', ''Giao tiếp tốt'', ''Chịu lắng nghe'', ''Thay đổi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được đăng ký ca làm'', ''Môi trường làm việc trẻ trung năng động'', ''Lương tăng thưởng theo năng lực'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (519, 7, 7, 'Nội dung cộng đồng thực tập (MạNH AI)', 'Sử dụng AI để tạo bản nháp bài viết, sau đó chỉnh sửa, tinh chỉnh và đăng tải theo lịch đã được phân công. Duy trì engagement trên các bài đăng: trả lời bình luận, gợi mở thảo luận, và biết cách sử dụng AI để phản hồi thông minh khi cần. Ghi nhận các bài viết hoặc bình luận nổi bật, tổng hợp và đề xuất các topic tiếp theo để duy trì sự sôi nổi cho cộng đồng. Tìm kiếm và phát triển các chủ đề liên quan đến xu hướng mùa, hành vi người dùng hoặc các social media trends nổi bật. Báo cáo hoạt động nội dung hàng tuần (bao gồm các bài đã đăng, nội dung nổi bật và xu hướng đã phát hiện được). Nắm vững và thực hiện công việc theo hệ thống tổ chức của chúng tôi (trên Lark) và báo cáo tiến độ theo mẫu.', 'Sinh viên các ngành liên quan Marketing/ Truyền thông/ Media. Ưu tiên ứng viên ở khu vực Thủ Đức - HCM hoặc Dĩ An - Bình Dương. Có sự hiểu biết nhất định và vận hành công cụ AI. Ưu tiên các UV biết sử dụng Lark Suite. Khả năng lên Content: Viết tự nhiên, linh hoạt, và thể hiện đúng văn hóa cộng đồng. Kỹ năng sử dụng AI (AI Proficiency): Biết cách dùng AI để generate ideas, draft content, create responses, và summarize information. Tinh tế trong quan sát và đề xuất: Có khả năng tinh ý trong việc nắm bắt community reactions và đưa ra những đề xuất ý tưởng phù hợp. Tinh thần học hỏi và cầu tiến: Sẵn sàng tiếp thu feedback và liên tục cải thiện cách vận hành AI để nâng cao hiệu quả công việc.
Kỹ năng chuyên môn: [''Sử dụng AI'', ''Lark Suite'']
Kỹ năng mềm: [''Viết tự nhiên'', ''Linh hoạt'', ''Tinh tế trong quan sát'', ''Tinh thần học hỏi và cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Hỗ trợ lương thực tập'', ''Hỗ trợ dấu mộc Công ty'', ''Được hướng dẫn và đào tạo từ team chuyên môn'', ''Môi trường Gen Z năng động, sáng tạo và cởi mở'', ''Tham gia các hoạt động giải trí nội bộ hàng tuần'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (520, 8, 9, 'Thực Tập Sinh Tín Dụng', 'Thực hiện trải nghiệm bán hàng (các sản phẩm của MB) theo các chương trình, chiến dịch phân công của CBQL. Rèn luyện kỹ năng giao tiếp, bán hàng, đàm phán. Thực hiện các công việc khác tại MB theo phân công CBQL.', 'Sinh viên chuyên ngành (Kinh tế, tài chính tín dụng, ngân hàng Kinh tế Luật, Kế toán, kiểm toán, quản trị kinh doanh, ngoại thương...). Sinh viên hệ Đại học năm 1, năm 2, năm 3, năm 4 , chuyên ngành (Kinh tế, tài chính tín dụng, ngân hàng Kinh tế Luật, Kế toán, kiểm toán, quản trị kinh doanh...). Sinh viên có tố chất nhanh nhẹn, tự tin, giao tiếp tốt.
Kỹ năng mềm: [''Nhanh nhẹn'', ''Tự tin'', ''Giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Chứng nhận hoàn thành báo cáo thực tập'', ''Trải nghiệm môi trường làm việc TOP 1 Châu Á- Thái Bình Dương'', ''Được đào tạo các nghiệp vụ ngân hàng như 1 nhân viên chính thức'', ''Kỹ năng bán hàng'', ''Chốt deal'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (521, 9, 9, 'Chuyên Gia Phỏng Vấn Giả Lập - Freelancer', 'Tham gia các buổi phỏng vấn mô phỏng 1:1 hoặc theo nhóm, đóng vai trò nhà tuyển dụng theo ngành nghề thực tế của bạn. Đặt câu hỏi, đánh giá phản ứng và kỹ năng của học viên trong quá trình phỏng vấn. Góp ý, nhận xét và hướng dẫn kỹ năng chuyên môn/nghiệp vụ để học viên hoàn thiện hồ sơ & kỹ năng trả lời. Gợi ý các điểm cần cải thiện về cách ứng xử, năng lực chuyên môn và tác phong chuyên nghiệp.', 'Có 5-10 năm kinh nghiệm thực tiễn tại vị trí tương ứng trong các ngành: Nhân sự, Kế toán, Marketing, IT, Sales, Xây dựng, Giáo dục, Hành chính, Dịch vụ, Sản xuất… Tư duy đào tạo, sẵn sàng chia sẻ và hỗ trợ định hướng nghề nghiệp cho người học. Kỹ năng giao tiếp tốt, truyền đạt rõ ràng, ưu tiên từng tham gia phỏng vấn/đào tạo/mentor. Có máy tính để tham gia phỏng vấn online.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng lắng nghe'', ''Kỹ năng phỏng vấn'', ''Kỹ năng đánh giá'', ''Kỹ năng đặt câu hỏi'']', 'FREELANCE', 'ONSITE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Thứ 2 - Thứ 7, nghỉ 4 chủ nhật và 2 thứ 7 trong tháng', '[''Thù lao hấp dẫn'', ''Cơ hội mở rộng networking với cộng đồng đào tạo – tuyển dụng chuyên nghiệp'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (522, 10, 9, 'Chuyên Viên Tư Vấn Tâm Lý', '• Làm trắc nghiệm tâm lý cho bệnh nhân. • Thực hiện tư vấn tâm lý, liệu pháp tâm lý cho bệnh nhân theo chỉ định của bác sĩ chuyên môn. • Giải quyết kịp thời các thắc mắc, khiếu nại của khách hàng liên quan đến chuyên môn khám chữa bệnh. • Đảm bảo năng lực và an toàn trong điều trị bệnh bằng cách tham gia các chương trình phát triển nghề nghiệp, đào tạo liên tục bên trong và bên ngoài bệnh viện. • Chi tiết công việc sẽ được trao đổi trong buổi phỏng vấn.', '• Bằng tốt nghiệp đại học tâm lý lâm sàng , có chứng chỉ tư vấn tâm lý. • Có ít nhất 1 năm kinh nghiệm ở vị trí chuyên môn phù hợp. • Có tinh thần trách nhiệm, tích cực và cầu tiến, chịu được áp lực cao. • Khả năng giao tiếp tốt, năng động, nhiệt tình, thái độ thân thiện với bệnh nhân.
Kỹ năng mềm: [''Tinh thần trách nhiệm'', ''Tích cực'', ''Cầu tiến'', ''Chịu được áp lực cao'', ''Khả năng giao tiếp tốt'', ''Năng động'', ''Nhiệt tình'', ''Thái độ thân thiện với bệnh nhân'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Linh động theo lịch hẹn của bệnh nhân', '[''Thu nhập tương xứng với năng lực chuyên môn và hiệu quả công việc đóng góp'', ''Môi trường làm việc thân thiện, năng động'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (523, 2, 9, 'Nhân Viên Xây Dựng Mô Hình Chuỗi Kinh Doanh', 'Nghiên cứu, thiết kế và triển khai mô hình kinh doanh nhượng quyền hoặc chuỗi điểm rửa bát công nghiệp. Chuẩn hóa toàn bộ quy trình, công cụ và bộ tài liệu liên quan. Hỗ trợ tìm kiếm, đào tạo và triển khai mô hình cho các đối tác nhượng quyền.', 'Tốt nghiệp Đại học các ngành: Quản trị kinh doanh, Kinh tế, Kỹ thuật hệ thống, Chuỗi cung ứng, F&B… Có kinh nghiệm 1–3 năm làm trong các lĩnh vực: xây dựng mô hình kinh doanh, triển khai chuỗi, nhượng quyền, hoặc vận hành F&B. Am hiểu mô hình kinh doanh nhượng quyền, biết xây dựng quy trình, bộ tiêu chuẩn hóa. Khả năng tư duy hệ thống, lập kế hoạch, viết tài liệu tốt. Giao tiếp và phối hợp tốt giữa các phòng ban và đối tác bên ngoài. Sẵn sàng đi công tác các tỉnh để khảo sát và triển khai điểm rửa.
Kỹ năng chuyên môn: [''Xây dựng mô hình kinh doanh'', ''Triển khai chuỗi'', ''Nhượng quyền'', ''Vận hành F&B'']
Kỹ năng mềm: [''Khả năng tư duy hệ thống'', ''Lập kế hoạch'', ''Viết tài liệu'', ''Giao tiếp'', ''Phối hợp'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 15000000.00, '10.0 - 15.0 triệu', 'Làm online từ xa không gò bó thời gian', '[''Bảo hiểm xã hội'', ''Thưởng hiệu quả làm việc'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (524, 3, 9, 'Doanh nghiệp tư vấn thực tập', 'Tham gia vào chương trình đào tạo tư vấn SAP S/4HANA chuyên nghiệp (bao gồm lý thuyết, thực hành thực hành, kỹ năng mềm, kiến ​​thức quản lý doanh nghiệp và phương pháp thực hiện). Tham gia triển khai các dự án SAP S/4HANA cho các khách hàng lớn trong nước và quốc tế cùng với một nhóm các chuyên gia trong ngành. Các nhiệm vụ chính của dự án bao gồm: Kiểm tra đơn vị các chức năng hệ thống, kiểm tra các tính năng tùy chỉnh dựa trên thiết kế, hỗ trợ đào tạo người dùng cuối, hỗ trợ hướng dẫn vận hành hệ thống và các nhiệm vụ liên quan đến dự án khác theo sự phân công của người quản lý trực tiếp.', 'Preferably 4th-year students available for full-time work. Majoring in Management Information Systems, E-commerce, Accounting – Auditing, or Industrial Management. Having studied and practiced ERP/SAP in university is a plus. High standard of professional working attitude. Willingness to work overtime when required. Strong motivation to learn, with a clear career goal. Ability to work both independently and in a team. Able to work under high pressure. Proficiency in MS Office tools (Word, Excel, PowerPoint, MS Project). Good communication skills, confidence, enthusiasm, quick learning ability, and high work intensity tolerance. English proficiency: TOEIC 650 (4 skills) / IELTS 6.0 or equivalent certifications.
Kỹ năng chuyên môn: [''ERP/SAP'', ''MS Office (Word, Excel, PowerPoint, MS Project)'']
Kỹ năng mềm: [''Strong motivation to learn'', ''Ability to work independently and in a team'', ''Good communication skills'', ''Confidence'', ''Enthusiasm'', ''Quick learning ability'', ''High work intensity tolerance'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Monday - Friday (from 08:00 to 17:00)', '[''Internship certificate with official company stamp'', ''Opportunity to sign an official labor contract upon successful completion of the internship'', ''Training by a highly experienced technical team'', ''Hands-on experience in projects with large corporations or international clients'', ''Dynamic, youthful, enthusiastic, and friendly working environment'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (525, 7, 9, 'Thực Tập Nhân Sự Part Time, Full Time', 'Tư vấn tuyển dụng và đào tạo nhân sự mới. Tư vấn Quản lý hồ sơ nhân sự, đảm bảo cập nhật thông tin chính xác và kịp thời. Thực hiện các thủ tục hành chính nhân sự như: ký hợp đồng lao động, quản lý lương thưởng,các chế độ phúc lợi khác. Tư vấn Hỗ trợ các phòng ban trong việc giải quyết các vấn đề liên quan đến nhân sự. Tư vấn Tham gia xây dựng và triển khai các chính sách, quy trình nhân sự. Tư vấn Thực hiện các báo cáo định kỳ về tình hình nhân sự. Tư vấn Phối hợp với các bộ phận liên quan để tổ chức các hoạt động chăm sóc, động viên tinh thần nhân viên. Tư vấn Thực hiện các công việc khác theo sự phân công của cấp trên. Thời gian thực tập: 6 tháng. Công ty chỉ tuyển ứng viên đi thực tập lấy kinh nghiệm, để được đào tạo chuyên ngành và ở lại làm việc lâu dài cho công ty. Chứng chỉ thực tập được cấp sau khi hoàn thành khóa thực tập.', 'Không yêu cầu kinh nghiệm. Có laptop cá nhân. Chấp nhận sinh viên 1, 2, 3, 4. Thành thạo tin học văn phòng (Word, Excel, Powerpoint). Khả năng giao tiếp tốt, kỹ năng làm việc nhóm. Cẩn thận, tỉ mỉ, trung thực, có trách nhiệm trong công việc. Khả năng làm việc độc lập và chịu được áp lực công việc. Có tinh thần học hỏi và cầu tiến.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Kỹ năng làm việc nhóm'', ''Cẩn thận'', ''Tỉ mỉ'', ''Trung thực'', ''Có trách nhiệm trong công việc'', ''Khả năng làm việc độc lập'', ''Chịu được áp lực công việc'', ''Có tinh thần học hỏi và cầu tiến'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Toàn thời gian: Từ thứ 2 đến thứ 6, 7h/ngày; Bán thời gian: Tối thiểu 15h/tuần', '[''Phụ cấp hỗ trợ thực tập để ăn trưa, gửi xe, xăng xe: 10.000 đ/h'', ''Cấp chứng chỉ thực tập'', ''Môi trường làm việc năng động, trẻ trung'', ''Được tăng lương và đề bạt làm nhân viên chính thức nếu có kết quả thực tập tốt'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (526, 8, 9, 'Thực Tập Sinh Nghiên Cứu Thị Trường (R&D)', 'Được trực tiếp tham gia vào quá trình nghiên cứu, triển khai dự án, tổng hợp dữ liệu giá các dự án. Khảo sát thị trường, thu thập dữ liệu, lập báo cáo nghiên cứu thị trường. Hỗ trợ giám đốc dự án đóng góp xây dựng nội dung giới thiệu sản phẩm. Hỗ trợ theo dõi tình trạng dự án.', 'Không yêu cầu có kinh nghiệm sẽ được đào tạo. Ưu tiên sinh viên các khối nghành, chuyên nghành: kinh tế, bất động sản, quản trị kinh doanh. Thích trải nghiệm trong lĩnh vực Bất động sản. Ưu tiên có kỹ năng thuyết trình, giải quyết vấn đề tốt. Có laptop cá nhân. Thành thạo tin học văn phòng: word, excel, powerpoint Tinh thần sáng tạo, học hỏi, cầu tiến.
Kỹ năng chuyên môn: [''Phân tích dữ liệu'', ''Xử Lý Dữ Liệu'', ''Thu Thập Dữ Liệu'', ''word'', ''excel'', ''powerpoint'']
Kỹ năng mềm: [''Viết Báo Cáo'', ''Nghiên Cứu Thị Trường'', ''thuyết trình'', ''giải quyết vấn đề'', ''sáng tạo'', ''học hỏi'', ''cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'thanh xuân, hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30) Thứ 7: 08:00 - 12:00', '[''Lương hỗ trợ 3.000.000 VNĐ/ tháng, có cơ hội thăng tiến rõ ràng.'', ''Được làm việc cùng đội ngũ hàng đầu thị trường trong lĩnh vực Bất động sản.'', ''Được đào tạo trực tiếp từ trưởng phòng và kèm 1:1 từ nhân sự cứng trong phòng, phát triển nhiều kỹ năng chuyên môn.'', ''Được đào tạo offline nhiều mảng kiến thức và kỹ năng mềm từ các chuyên gia.'', ''Được làm việc trong môi trường đội nhóm đoàn kết, năng động, trẻ trung, văn phòng sang – xịn – xanh.'', ''Có cơ hội trở thành nhân viên chính thức của công ty'', ''Tham gia vào các hoạt động vui chơi, Teambuilding, sinh nhật thành viên, vinh danh cá nhân/tập thể...'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (527, 9, 9, 'Thực Tập Sinh Nghiên Cứu Thị Trường', 'Lập kế hoạch và tiến hành thăm thị trường; Nghiên cứu thị trường và điều tra thông tin; Thu thập và sắp xếp thông tin của nghiên cứu; Soạn thảo và báo cáo kết quả của nghiên cứu.', 'College degree; 4th year of bachelor degree is acceptable. Average English level is preferred Good at market and brands; Good at database search and internet searching skills Open, eager to learn and good manner; Dynamic, hard-working, curious, enthusiastic, active, Willing to travel for market research Male is Preferred.
Kỹ năng chuyên môn: [''database search'', ''internet searching skills'', ''Phân tích dữ liệu'', ''Viết Báo Cáo'', ''Nghiên Cứu Thị Trường'', ''Xử Lý Dữ Liệu'', ''Thu Thập Dữ Liệu'']
Kỹ năng mềm: [''Open'', ''eager to learn'', ''good manner'', ''Dynamic'', ''hard-working'', ''curious'', ''enthusiastic'', ''active'', ''Willing to travel for market research'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''You will have chance to work in a professional environment of an International Intellectual Property Firm.'', ''More than 15 days of annual leave'', ''annual health check'', ''bonus'', ''team building'', ''regular trainings'', ''pantry with snacks and drinks'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (528, 10, 9, 'Thực Tập Sinh Marketing (Chuyên Content)', '* Hỗ trợ viết bài nội dung cho các kênh truyền thông của công ty: Website, Fanpage, Zalo OA, Email,... * Biên tập, chỉnh sửa và đăng tải bài viết theo hướng dẫn và kế hoạch đã phân công. * Nghiên cứu từ khóa, xu hướng thị trường, và lên outline bài viết theo yêu cầu. * Viết bài PR, nội dung quảng cáo hoặc các nội dung truyền thông nội bộ. * Phối hợp với các bộ phận khác (thiết kế, marketing, kinh doanh…) để xây dựng nội dung phù hợp mục tiêu chiến dịch. * Tham gia đóng góp ý tưởng cho các chiến dịch truyền thông, kế hoạch phát triển nội dung. * Thực hiện các công việc khác theo phân công của quản lý.', 'Sinh viên năm 3 trở lên các ngành Marketing, Truyền thông, Thiết kế đồ họa. Có khả năng viết lách tốt, tư duy hình ảnh sáng tạo. Biết sử dụng Canva/Photoshop/AI là một lợi thế. Chủ động, ham học hỏi, có tinh thần trách nhiệm Có laptop cá nhân, phương tiện đi lại phục vụ nhu cầu công việc
Kỹ năng chuyên môn: [''Canva'', ''Photoshop'', ''AI'']
Kỹ năng mềm: [''Khả năng viết lách tốt'', ''Tư duy hình ảnh sáng tạo'', ''Chủ động'', ''Ham học hỏi'', ''Có tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Có cơ hội trở thành nhân viên chính thức sau thời gian thực tập'', ''Được hỗ trợ dấu mộc và tài liệu liên quan để làm thực tập'', ''Được đào tạo các kỹ năng marketing thực chiến'', ''Được tham gia các khóa học, các buổi training nội bộ của công ty.'', ''Làm việc trong môi trường năng động, được tham gia các dự án thực tế.'', ''Có lộ trình thăng tiến rõ ràng'', ''Làm việc trong môi trường trẻ trung, năng động, thân thiện'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (529, 2, 9, 'Thực tập sinh Trợ lý Giám đốc (CEO)', 'Bạn sẽ là trợ lý trực tiếp cho CEO – người đang dẫn dắt công ty phát triển các thương hiệu toàn cầu trên nền tảng thương mại điện tử. Vai trò của bạn bao gồm: 1. Hỗ trợ R&D: Tìm hiểu và tổng hợp thông tin thị trường TMĐT tại Mỹ (Amazon, TikTokShop, Etsy,...), tham gia vào quá trình phát triển sản phẩm mới và cải tiến sản phẩm hiện có. 2. Hỗ trợ Digital Marketing: * Tham gia tối ưu hoá listing sản phẩm * Tìm kiếm, sàng lọc và làm việc với đối tác thứ 3, KOC, KOL tại thị trường Mỹ. * Viết script kịch bản cho KOC/KOL theo từng loại sản phẩm * Tham gia sáng tạo nội dung cho kênh chính thức của các thương hiệu do Wicom quản lý. 3. Thực hiện các nhiệm vụ khác theo phân công của CEO, với cơ hội tiếp cận đa lĩnh vực trong môi trường startup toàn cầu, năng động.', '* Là sinh viên năm 3 trở lên thuộc khối ngành Luật quốc tế, Kinh tế đối ngoại hoặc các chuyên ngành có liên quan. * Là sinh viên năm 3 trở lên các ngành Kinh tế, Marketing hoặc lĩnh vực liên quan. * Yêu thích Digital Marketing, có mong muốn làm việc trong môi trường cross-border ecommerce. * Tư duy logic tốt, tự chủ, biết ứng dụng AI để phân tích, báo cáo, tạo nội dung. * Có kỹ năng quay dựng video, thành thạo CapCut hoặc các ứng dụng tương tự. * Có khả năng đọc hiểu tiếng Anh tốt. * Trách nhiệm, chủ động, tinh thần học hỏi cao. * Ưu tiên ứng viên đam mê kinh doanh và có tinh thần làm chủ.
Kỹ năng chuyên môn: [''Sử dụng AI để phân tích, báo cáo, tạo nội dung'', ''Kỹ năng quay dựng video'', ''Thành thạo CapCut hoặc các ứng dụng tương tự'']
Kỹ năng mềm: [''Tư duy logic tốt'', ''Tự chủ'', ''Trách nhiệm'', ''Chủ động'', ''Tinh thần học hỏi cao'', ''Đam mê kinh doanh'', ''Tinh thần làm chủ'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), thời gian linh hoạt theo lịch học', '[''Được mentorship 1-1 từ CEO'', ''Cơ hội học hỏi thực tế về mô hình kinh doanh thương mại điện tử xuyên biên giới'', ''Được định hướng phát triển nghề nghiệp phù hợp với năng lực và sở thích cá nhân'', ''Cơ hội trở thành nhân sự chính thức sau thực tập (nếu thể hiện tốt)'', ''Hỗ trợ dấu mộc xác nhận thực tập (nếu cần)'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (530, 3, 9, 'CTV Khảo Sát Part-Time', '- Gặp trực tiếp, đến từng hộ gia đình để thực hiện khảo sát theo bảng hỏi có sẵn - Báo cáo lên trưởng nhóm về tiến độ, kết quả công việc, vấn đề cần giải quyết - Thời gian làm việc linh động, không gò bó - Địa điểm làm việc linh động, tùy dự án', '- Đã tốt nghiệp Cao Đẳng trở lên - Không yêu cầu kinh nghiệm - Có phương tiện di chuyển - Chịu khó, có trách nhiệm, có khả năng giao tiếp tốt - Trung thực, liêm chính
Kỹ năng chuyên môn: []
Kỹ năng mềm: [''Có phương tiện di chuyển'', ''Chịu khó'', ''Có trách nhiệm'', ''Có khả năng giao tiếp tốt'', ''Trung thực'', ''Liêm chính'']', 'PART_TIME', 'ONSITE', 'hồ chí minh, cần thơ', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '0.1 - 2.0 triệu', 'Thời gian làm việc linh động, không gò bó', '[''Được đào tạo kiến thức về phỏng vấn, thu thập dữ liệu khảo sát, tiếp cận khách hàng và xử lý tình huống'', ''Có trang bị công cụ làm việc (máy tính bảng)'', ''Môi trường làm việc thân thiện, năng động'', ''Có cơ hội thăng tiến'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (531, 7, 9, 'Phát triển kinh doanh & tiếp thị thực tập', 'Hỗ trợ phát triển và thực hiện các chiến dịch tiếp thị trực tuyến/ngoại tuyến, cũng như phân tích hiệu suất chiến dịch và phản hồi của khách hàng và xác định các cơ hội sản phẩm. Tiến hành nghiên cứu thị trường trên các kênh bán hàng truyền thống (cuộc gọi trực tiếp với B2C, khách hàng B2B, cơ quan, v.v.). Hỗ trợ thu thập, phân tích dữ liệu và động não các chiến lược bán hàng với nhóm. Giúp nghiên cứu các khách hàng tiềm năng, giới thiệu các sản phẩm và sắp xếp các cuộc họp với triển vọng mới. Chuẩn bị các báo cáo, sàn trình bày và tài liệu tiếp thị cho các đối tác nội bộ và bên ngoài. Cung cấp hỗ trợ quản trị viên và các nhiệm vụ khác theo yêu cầu.', 'Strong English skills (writing, speaking, listening) Proficiency in Excel, PowerPoint, Canva Proactivity, quick learning ability, critical thinking, and eager to learn Good at teamwork and hard-working 3rd/4th-year university students or fresh graduates in Business Administration, Marketing, Communications, or related fields Able to commit at least 4 working days per week for a minimum of 3 months
Kỹ năng chuyên môn: [''Excel'', ''PowerPoint'', ''Canva'']
Kỹ năng mềm: [''Proactivity'', ''Quick learning ability'', ''Critical thinking'', ''Eager to learn'', ''Good at teamwork'', ''Hard-working'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Monday - Friday (9:00 AM - 6:00 PM)', '[''Monthly allowance based on performance'', ''Able to work in a dynamic, professional, and international environment'', ''Opportunities for training, experience, and growth in a start-up environment'', ''Internship certification (if needed)'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (532, 8, 9, 'Thực Tập Sinh Phát Triển Dự Án Kinh Doanh', '* Hỗ trợ nghiên cứu và phân tích thị trường, đối thủ cạnh tranh, xu hướng ngành liên quan đến các dự án kinh doanh. * Được đào tạo để thực hiện khảo sát khách hàng, thu thập thông tin, phân tích dữ liệu * Tham gia họp nội bộ và hỗ trợ chuẩn bị tài liệu, báo cáo dự án, thuyết trình, proposal. * Hỗ trợ kết nối và làm việc với các đối tác, khách hàng hoặc phòng ban liên quan trong quá trình triển khai dự án. * Hỗ trợ các công việc hành chính, lưu trữ tài liệu, quản lý thông tin dự án theo yêu cầu. * Đề xuất các ý tưởng sáng tạo để tối ưu hóa hiệu quả dự án và trải nghiệm khách hàng.', '* Sinh viên năm 3, 4 hoặc vừa tốt nghiệp các chuyên ngành: Quản trị Kinh doanh, Marketing, Kinh tế, Tài chính, hoặc các ngành liên quan. * Có khả năng tư duy phân tích, tổng hợp và giải quyết vấn đề tốt. * Kỹ năng giao tiếp, làm việc nhóm và quản lý thời gian hiệu quả. * Thành thạo tin học văn phòng (Word, Excel, PowerPoint). * Chủ động, ham học hỏi, cầu tiến và có tinh thần trách nhiệm cao. * Có khả năng làm việc độc lập và chịu được áp lực.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Tư duy phân tích, tổng hợp và giải quyết vấn đề tốt'', ''Kỹ năng giao tiếp, làm việc nhóm và quản lý thời gian hiệu quả'', ''Chủ động, ham học hỏi, cầu tiến và có tinh thần trách nhiệm cao'', ''Khả năng làm việc độc lập và chịu được áp lực.'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00) Thứ Hai - Sáng thứ Bảy (tuần làm 1 thứ Bảy trên công ty, còn lại làm từ xa) Sáng: 08:00-12:00 Chiều: 13:30-17:30', '[''Lương hỗ trợ: 3 - 5 triệu'', ''Trở thành nhân viên chính thức sau 3 tháng'', ''Cơ hội được tiếp cận thực tế với các dự án kinh doanh đa dạng.'', ''Làm việc trong môi trường chuyên nghiệp, năng động, có mentor hỗ trợ.'', ''Được đào tạo và hướng dẫn chi tiết trong quá trình làm việc.'', ''Hỗ trợ dấu mộc, xác nhận thực tập và hỗ trợ chi phí (nếu có).'', ''Xăng xe, Cước điện thoại'', ''Team building, Thưởng hiệu quả làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (533, 9, 9, 'Nhân Viên R&D', '1. Phân tích và nghiên cứu thị trường: Thực hiện nghiên cứu chuyên sâu về thị trường du lịch inbound và outbound để xác định đối tượng khách hàng, xu hướng và sở thích du lịch. Phân tích sản phẩm của đối thủ cạnh tranh và vị trí của họ trên thị trường để đề xuất các chiến lược phù hợp. Cập nhật thông tin về các xu hướng du lịch toàn cầu và đề xuất các chiến lược phát triển thị trường. 2. Hỗ trợ phát triển sản phẩm: Soạn thảo thông số sản phẩm (product specifications) cho các gói du lịch bao gồm lịch trình, mô hình giá cả và các dịch vụ đi kèm. Phối hợp với đội ngũ vận hành để đảm bảo sản phẩm đáp ứng nhu cầu thị trường và phù hợp với sứ mệnh bền vững của công ty. 3. Phát triển tài liệu marketing: Tạo nội dung cho brochure, tờ rơi và các tài liệu quảng cáo khác phù hợp với thị trường quốc tế và trong nước. Hỗ trợ xây dựng các tài liệu digital như bài viết blog, bài đăng mạng xã hội và email marketing. Đảm bảo nội dung truyền tải đúng thông điệp thương hiệu và cam kết của VEcoTra với du lịch bền vững. 4. Hỗ trợ phối hợp: Làm việc với đội ngũ kinh doanh để chia sẻ các thông tin thị trường và hỗ trợ các chiến lược bán hàng. Phối hợp với đội thiết kế và các phòng ban khác để phát triển các tài liệu truyền thông hấp dẫn.', 'Đang theo học chuyên ngành Marketing, Kinh doanh quốc tế, Du lịch hoặc các lĩnh vực liên quan. Kỹ năng phân tích và nghiên cứu tốt, đam mê với ngành du lịch và thị trường quốc tế. Thành thạo tiếng Anh (ưu tiên biết thêm các ngôn ngữ khác). Kỹ năng viết lách tốt, chú ý đến chi tiết và khả năng điều chỉnh nội dung phù hợp với từng đối tượng. Thành thạo Microsoft Office; biết sử dụng các công cụ như Canva, Photoshop là một lợi thế. Chủ động, sáng tạo, và có tinh thần học hỏi trong môi trường quốc tế.
Kỹ năng chuyên môn: [''Microsoft Office'', ''Canva'', ''Photoshop'']
Kỹ năng mềm: [''Kỹ năng phân tích'', ''Kỹ năng nghiên cứu'', ''Kỹ năng viết lách'', ''Chú ý đến chi tiết'', ''Khả năng điều chỉnh nội dung'', ''Chủ động'', ''Sáng tạo'', ''Tinh thần học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Phụ cấp thực tập'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Môi trường làm việc sáng tạo, năng động và chuyên nghiệp'', ''Cơ hội mở rộng kiến thức và xây dựng mạng lưới trong ngành du lịch toàn cầu'', ''Phụ cấp ăn trưa'', ''Bảo hiểm xã hội'', ''Thưởng hiệu quả làm việc'', ''Thưởng tháng 13'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (534, 10, 9, 'Admin Gia Sư & Admin Coi Chấm Thi IELTS Part Time Tối - Từ 6.5 IELTS - Không YCKN', '1. Admin gia sư tại HN * Tutor IELTS online cho học viên đăng ký học lớp gia sư - Giảng dạy các lớp chờ khai giảng (online hoặc offline) tại văn phòng làm việc - Coi thi speaking các kỳ thi giữa khoá, cuối khoá của trung tâm - Động viên khuyến khích, có phương pháp tạo động lực học IELTS cho học viên - Thực hiện công việc khác theo sự phân công của Trưởng bộ phận. - Coi thi speaking các kỳ thi giữa khoá, cuối khoá của trung tâm 2. Admin coi - chấm thi tại HCM * Coi thi IELTS 4 kỹ năng cho học viên (thi trên giấy và thi speaking) - Chấm thi giữa kỳ, cuối kỳ, tổng hợp kết quả và báo cáo với các bộ phận liên quan * Gia sư Online theo nhu cầu của học viên; - Giảng dạy các lớp chờ khai giảng tại văn phòng làm việc; - Tổ chức kiểm tra đánh giá năng lực tiếng Anh đầu vào cho học viên; - Chấm bài và phân loại trình độ đầu vào cho học viên; - Tổ chức kiểm tra đánh giá các kỳ thi giữa khóa và cuối khóa cho học viên tại cơ sở làm việc;', '- IELTS ≥ 6.5 (Không có kỹ năng nào dưới 6.0) - Phát âm Tiếng Anh trôi chảy, chuẩn IPA - Có kiến thức về format bài thi IELTS - Tinh thần tự học hỏi, chủ động trong công việc
Kỹ năng chuyên môn: [''Kiến thức về format bài thi IELTS'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kiên Nhẫn'', ''Khả Năng Quản Lý'', ''Tinh thần tự học hỏi'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 5000000.00, '4.5 - 5.5 triệu', 'Thứ 2 - Thứ 7 (từ 18:00 đến 22:00)', '[''Được đào tạo kỹ năng chuyên môn ngoại ngữ'', ''Được đào tạo bài bản về các kỹ năng IELTS'', ''Thưởng lễ tết, du lịch, tham gia teambuilding, party'', ''Review lương 3-6 tháng/lần'', ''Hỗ trợ dấu thực tập sau 3 tháng làm việc'', ''Trà, coffee luôn sẵn sàng tại văn phòng'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (535, 2, 9, 'C & B Intern (6 tháng)', 'Quản lý và lưu trữ các tập tin nhân viên. Theo dõi và quản lý các quy trình ký tài liệu cho nhóm C & B. Giám sát và hỗ trợ thư từ đến và đi cho nhân viên. Hỗ trợ liên hệ với nhân viên để bổ sung thông tin cá nhân cho hố (thuế thu nhập cá nhân) và mục đích bảo hiểm xã hội. Những nhiệm vụ giấy tờ khác theo yêu cầu.', 'Full time at office. Education: 3rd, 4th year student in Human Resources, or related fields. Skills: Good proficiency in office software (Word, Excel, PowerPoint). Basic knowledge of accounting and tax is a plus - for Intern 2. Careful, meticulous, and highly responsible. Good organizational skill. Good analytical and information synthesis skills. Careful, accurate, and able to work under pressure.
Kỹ năng chuyên môn: [''Good proficiency in office software (Word, Excel, PowerPoint)'', ''Basic knowledge of accounting and tax'']
Kỹ năng mềm: [''Careful'', ''Meticulous'', ''Highly responsible'', ''Good organizational skill'', ''Good analytical and information synthesis skills'', ''Able to work under pressure'']', 'INTERNSHIP', 'ONSITE', 'phú nhuận', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Internship Allowance'', ''Free Parking Fee'', ''Training & Development'', ''International environment'', ''Engagement/ Team Gathering Party'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (536, 3, 9, 'Thực Tập Sinh Hành Chính Nhân Sự', 'Nhập liệu, sắp xếp hồ sơ nhân sự. Đón tiếp khách, chuẩn bị phòng họp, mua sắm một số trang thiết bị văn phòng. Sắp xếp CV, lọc hồ sơ ứng viên tiềm năng, đăng tin tuyển dụng trên một số hội nhóm fb, xóa bỏ bài đăng khi tin đăng hết hạn. Phối hợp tổ chức các hoạt động gắn kết nhân viên.', 'Có khả năng làm việc độc lập và làm việc nhóm. Năng động, nhiệt tình. Chăm chỉ, ham học hỏi và tìm tòi cái mới. Luôn có tinh thần trách nhiệm, hoàn thành tốt những đầu việc được giao. Có hiểu biết và hứng thú tìm hiểu các quy định về lương thưởng, bảo hiểm, luật lao động,...
Kỹ năng mềm: [''Có khả năng làm việc độc lập và làm việc nhóm'', ''Năng động, nhiệt tình'', ''Chăm chỉ, ham học hỏi và tìm tòi cái mới'', ''Luôn có tinh thần trách nhiệm, hoàn thành tốt những đầu việc được giao'', ''Có hiểu biết và hứng thú tìm hiểu các quy định về lương thưởng, bảo hiểm, luật lao động'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 đến sáng thứ 7, có thể linh hoạt theo lịch học', '[''Môi trường làm việc năng động, chuyên nghiệp trong lĩnh vực thời trang'', ''Phụ cấp hàng tháng'', ''Học hỏi công việc chuyên môn từ thực tế'', ''Được đào tạo các kỹ năng mềm'', ''Đóng dấu thực tập tại Công ty'', ''Có cơ hội được đào tạo và phát triển nghề nghiệp'', ''Thưởng các ngày lễ, tết theo quy định của công ty'', ''Được tham gia các hoạt động tập thể của công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (537, 7, 9, 'Cộng Tác Viên Gán Nhãn Dữ Liệu (Remote) – Làm Tại Nhà', 'Alchera là một công ty AI ''Full-Stack'' có thể thu thập và gắn nhãn khối lượng lớn dữ liệu mới tại các trung tâm dữ liệu dữ liệu riêng đặt tại Hàn Quốc và Việt Nam. Mỗi ngày, công ty thực hiện hàng chục dự án khác nhau, và chuyên môn về dữ liệu cùng các công cụ AI của Alchera đã tạo ra lợi thế cạnh tranh vượt trội, khó có thể sao chép trong nhiều lĩnh vực của ngành công nghiệp trí tuệ nhân tạo. Chúng tôi cần tuyển Cộng Tác Viên Gán Nhãn Dữ Liệu (Remote) – Làm Tại Nhà: Thực hiện gán nhãn dữ liệu (data labeling) trên phần mềm nội bộ được cung cấp sẵn. Làm việc chủ yếu với hình ảnh, phục vụ cho các dự án AI (Trí tuệ nhân tạo). Tham gia vào các dự án tùy theo khả năng và thời gian cá nhân.', 'Có máy tính/laptop cá nhân. Tỉ mỉ, kiên nhẫn, có khả năng làm việc độc lập. Ưu tiên: ứng viên từng tham gia các dự án AI hoặc xử lý dữ liệu (không bắt buộc). Chưa có kinh nghiệm vẫn có thể đăng ký, sẽ có file ppt hướng dẫn.
Kỹ năng mềm: [''Tỉ mỉ'', ''Kiên nhẫn'', ''Có khả năng làm việc độc lập'']', 'FREELANCE', 'REMOTE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Lương tính theo số lượng ảnh hoàn thành'', ''Làm càng nhiều, thu nhập càng cao'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (538, 8, 9, 'Thực Tập Sinh', 'Nghiên cứu và tạo nguồn tuyển dụng theo nhu cầu Công ty. Liên hệ ứng viên mời phỏng vấn và hỗ trợ tiến hành công tác nhận việc. Giải đáp thắc mắc của ứng viên kịp thời trên các kênh tuyển dụng của công ty như Facebook, Zalo, email,... Hỗ trợ xây dựng thương hiệu nhà tuyển dụng trên các nền tảng mạng xã hội như Facebook, LinkedIn, Tiktok, Instagram của công ty.', '* Sinh viên năm cuối các trường đại học * Đam mê và có định hướng ngành nhân sự * Mạnh về social là lợi thế * Am hiểu, biết thiết kế, chỉnh sửa video cơ bản * Thái độ/tư duy cởi mở, sẵn sàng học hỏi. * Chủ động, trách nhiệm và yêu thích công việc ứng tuyển.
Kỹ năng chuyên môn: [''Thiết kế video cơ bản'', ''Sử dụng mạng xã hội'']
Kỹ năng mềm: [''Thái độ cởi mở'', ''Sẵn sàng học hỏi'', ''Chủ động'', ''Trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường làm việc hiện đại, chuyên nghiệp'', ''Hỗ trợ báo cáo thực tập'', ''Được hỗ trợ cơm trưa'', ''Cơ hội nghề nghiệp tại Sen Vàng Việt Nam'', ''Trợ cấp thực tập'', ''Thưởng hiệu quả làm việc'', ''Team building'', ''Du lịch hàng năm'', ''Khám sức khỏe định kỳ'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (539, 9, 9, 'Thực Tập Sinh Hành Chính', 'Hỗ trợ các bộ phận khác trong công ty như kinh doanh, văn phòng, sản xuất, giao nhận,... Công việc được sắp xếp tùy vào năng lực và phù hợp với từng bạn. Chi tiết sẽ được thảo luận trong buổi phỏng vấn.', 'Đang theo học trung cấp trở lên. Nhanh nhẹn, chịu khó và ham học hỏi. Ưu tiên các bạn sinh viên sinh sống hoặc học tại các trường khu vực gần phường Hiệp Bình Phước và quận Gò Vấp.
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chịu khó'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường làm việc năng động, thân thiện'', ''Được training nâng cao kỹ năng nghề nghiệp'', ''Được hỗ trợ định hướng nghề nghiệp và các kỹ năng mềm hỗ trợ cho công việc'', ''Có cơ hội làm việc và gắn bó lâu dài với Công ty'', ''Phụ cấp, thưởng theo hiệu quả công việc'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (540, 10, 9, 'Thực Tập Sinh Trợ Lý Kinh Doanh', 'Hỗ trợ bộ phận bán hàng trong phối hợp công việc như sau: 1. Nhận đơn đặt hàng, trích dẫn giá và chuẩn bị hợp đồng 2. Quản lý các hoạt động bán hàng tại điểm bán hàng của công ty. 3. Quản lý các hoạt động bán hàng trên nền tảng thương mại điện tử. 4. Các nhiệm vụ khác theo quản lý được giao. Thời gian làm việc: 9 giờ sáng đến 18 giờ tối (Thứ Hai- Thứ Sáu)', 'Priority for economics, foreign trade, foreign languages 3rd and 4th year students interested in sales & sales management, operations management. Fresh graduates. Good communication skills and basic English/Korean. Hardworking, agile. Short class schedule (1-2 sessions/week)
Kỹ năng chuyên môn: [''Microsoft Office (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Làm việc nhóm'', ''Quản lý lịch trình'', ''Sắp xếp và tổ chức công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', '9am-6pm (Thứ 2 - Thứ 6)', '[''Hỗ trợ 2,000,000 - 3,000,000 VND/tháng cho thực tập sinh'', ''Hỗ trợ tiền gửi xe: 300,000 VND/tháng'', ''Cơ hội trở thành nhân viên chính thức sau khi tốt nghiệp'', ''Được đào tạo 1-1 với đầy đủ kỹ năng trong Sales Support, Phân tích dữ liệu, và các kỹ năng văn phòng'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (541, 2, 9, 'Thực Tập Sinh Nhân Sự - Có Lương', '- Hỗ trợ đăng tin tuyển dụng trên các nền tảng (Facebook, LinkedIn, TopCV, v.v.); - Sàng lọc hồ sơ, liên hệ ứng viên, sắp xếp lịch phỏng vấn; - Cập nhật dữ liệu ứng viên và báo cáo tiến độ tuyển dụng; - Hỗ trợ lên ý tưởng và thực hiện các hoạt động truyền thông nội bộ; - Hỗ trợ lên ý tưởng, viết bài, làm infographic, hoặc video ngắn cho các kênh truyền thông nội bộ và phát triển thương hiệu tuyển dụng; - Góp ý và đề xuất các hoạt động nâng cao văn hóa doanh nghiệp; - Hỗ trợ các nghiệp vụ khác trong phòng Hành chính - Nhân sự theo năng lực và mong muốn.', '- Sinh viên năm 3, 4 hoặc mới tốt nghiệp các ngành Quản trị nhân lực, Truyền thông, Kinh tế, Quản trị kinh doanh... - Kỹ năng giao tiếp tốt, nhanh nhẹn, hoạt bát, trách nhiệm; - Thích làm việc với con người và có khả năng tổ chức; - Có kỹ năng viết nội dung, làm việc nhóm, chủ động học hỏi; - Ưu tiên ứng viên có kinh nghiệm trong CLB/sự kiện trường hoặc từng làm truyền thông/tuyển dụng trước đó.
Kỹ năng chuyên môn: [''Microsoft Office (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Nhanh nhẹn'', ''Hoạt bát'', ''Trách nhiệm'', ''Thích làm việc với con người'', ''Có khả năng tổ chức'', ''Kỹ năng viết nội dung'', ''Làm việc nhóm'', ''Chủ động học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00) theo lịch học của ứng viên', '[''Được trải nghiệm xử lý và làm việc với các nghiệp vụ trong công việc quản trị nhân sự'', ''Làm việc trong môi trường gen Z trẻ trung, năng động, hỗ trợ nhau'', ''Cơ hội trở thành nhân viên chính thức'', ''Hỗ trợ lương thực tập và có dấu mộc công ty nếu cần'', ''Được tham gia đầy đủ hoạt động của công ty như một nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (542, 3, 9, 'Talent Acquisition Intern', 'Hỗ trợ công tác tuyển dụng như: đăng tin tuyển dụng lên các trang mạng tuyển dụng, xử lý hồ sơ ứng viên, sàng lọc hồ sơ ứng viên, sắp xếp lịch phỏng vấn, hỗ trợ liên hệ - phỏng vấn ứng viên, viết content, thiết kế hình ảnh tuyển dụng,... Quản lý và cập nhật cơ sở dữ liệu ứng viên. Hỗ trợ các sự kiện tuyển dụng và xây dựng thương hiệu tuyển dụng của công ty. Các công việc hành chính khác liên quan đến tuyển dụng.', 'Sinh viên năm 3, 4 nghiệp chuyên ngành Quản trị nhân lực, Kinh tế, hoặc các ngành liên quan. Có đam mê với nghề nhân sự, đặc biệt là mảng tuyển dụng. Sử dụng thành thạo các công cụ tin học văn phòng (Word, Excel, PowerPoint). Ưu tiên thực tập Full-Time hoặc Part-time (Thứ 2 đến Thứ 6). Có laptop cá nhân.
Kỹ năng chuyên môn: [''Word'', ''Excel'', ''PowerPoint'']
Kỹ năng mềm: [''Giao tiếp'', ''Làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ mộc và số liệu báo cáo (nếu cần)'', ''Được hướng dẫn và đào tạo trực tiếp các công việc liên quan đến nhân sự và tuyển dụng'', ''Cơ hội được tiếp xúc với quy trình tuyển dụng thực tế và các công cụ nhân sự hiện đại'', ''Tham gia các hoạt động văn hóa đoàn thể của Sendo và Tập đoàn FPT'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (543, 7, 9, 'Thực Tập Sinh Tuyển Dụng Có Lương', '– Tìm kiếm các nguồn ứng viên từ các trang mạng xã hội: Facebook, Vietnamwork – Liên hệ với ứng viên để trao đổi và hẹn lịch phỏng vấn. Kết nối với các phòng ban lịch phỏng vấn ứng viên và book phòng phỏng vấn – Đón tiếp ứng viên và thông báo kết quả sau phỏng vấn – Kết hợp với đội tuyển dụng để xây dựng và phát triển nguồn ứng viên qua các trường Đại học, Cao Đẳng – Chăm sóc fanpage tuyển dụng, website tuyển dụng…. – Các công việc khác theo sự phân công của trưởng nhóm Nhân sự', '– Thời gian làm việc: Fulltime – Ưu tiên: Sinh viên đang theo học hoặc đã tốt nghiệp các chuyên ngành về Hành chính/ Nhân sự/ các chuyên ngành liên quan', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 – thứ 6, 8h00 – 17h00', '[''Làm việc trong môi trường quốc tế, chuyên nghiệp, văn phòng 5 sao, công ty quy mô > 1000 nhân sự'', ''Được đào tạo chuyên sâu về tuyển dụng (lọc CV, setup phỏng vấn,…)'', ''Cấp chứng chỉ sau quá trình thực tập 3 tháng'', ''Ăn trưa miễn phí tại canteen trường'', ''Phụ cấp 2.000.000/tháng'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (544, 8, 9, 'Thực Tập Sinh Nhân Sự', '- Lên hoạch định và mô tả công việc cho các vị trí cần tuyển - Liên hệ phỏng vấn ứng viên và chuẩn bị hồ sơ ứng viên - Quản lý nhân sự trong hệ thống và thông báo các lịch đào tạo - Thực hiện các quy trình onboarding và out-boarding nhân sự - Chăm sóc ứng viên và nhân sự - Chủ động tìm kiếm ứng viên cho các vị trí cần', '- Muốn theo đuổi ngành nhân sự lâu dài , đam mê với nghề - Sự quyết liệt - Khả năng quản trị cảm xúc tốt, kỹ năng giao tiếp, thuyết phục và xử lý vấn đề linh hoạt - Sinh viên năm 2-3 - Có Laptop cá nhân
Kỹ năng chuyên môn: [''Quản Trị Kinh Doanh'', ''Quản Trị Nhân Lực'']
Kỹ năng mềm: [''Khả năng quản trị cảm xúc tốt'', ''Kỹ năng giao tiếp'', ''Thuyết phục'', ''Xử lý vấn đề linh hoạt'']', 'PART_TIME', 'ONSITE', 'nam từ liêm', 'Hà Nội', 'MONTHLY', 2000000.00, '1.5 - 2.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 17:30)', '[''Mức lương khởi điểm: 2.000.000 + hoa hồng tuyển dụng 200k/ứng viên'', ''Tháng đầu tiên học việc có lương học việc, từ tháng thứ 2 trở đi có lương chính thức'', ''Được đào tạo kỹ năng chuyên môn và kỹ năng mềm'', ''Môi trường làm việc sáng tạo, nhiệt huyết'', ''Teambuilding định kỳ cùng công ty 2 miền Nam-Bắc 3-4 lần/năm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (545, 9, 9, 'Học Việc Thư Ký Dự Án', 'Hỗ trợ việc chuẩn bị và làm hồ sơ dự án, hồ sơ đấu thầu dự án xây dựng nội thất. Theo dõi và cập nhật tiến độ dự án, hỗ trợ sắp xếp lịch họp với khách hàng. Soạn thảo các biểu mẫu, hợp đồng, thư từ, công văn… Hỗ trợ các công việc khác trong quá trình thi công. Sẽ được hướng dẫn trong quá trình thực tập và học việc.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các khối ngành Kinh tế, Quản trị, Nội thất, Xây dựng,... Giao tiếp tốt, cẩn thận, có trách nhiệm và chủ động trong công việc. Ham học hỏi và phát triển bản thân.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Cẩn thận'', ''Có trách nhiệm'', ''Chủ động trong công việc'', ''Ham học hỏi và phát triển bản thân'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '3.0 - 8.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 cách tuần', '[''Cơ hội trở thành nhân viên chính thức sau thời gian học việc'', ''Có hỗ trợ phụ cấp cho học việc cao'', ''Môi trường làm việc thoải mái, thân thiện và được hướng dẫn bởi mentor giỏi, chuyên nghiệp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (546, 10, 9, 'Thực Tập Sinh Hành Chính Nhân Sự', 'Công việc hành chính nhân sự của công ty. Tham gia vào quá trình tuyển dụng hoặc đào tạo nhân sự. Dự án nhân sự và phát triển kế hoạch tuyển dụng cho công ty. Công tác tuyển dụng: tiếp nhận, đăng tin tuyển dụng, sàng lọc hồ sơ, gửi thư mời phỏng vấn, thông báo kết quả cho ứng viên. Thu thập, quản lý hồ sơ ứng viên. Hỗ trợ trong công tác kê khai thuế, bảo hiểm. Hỗ trợ xử lý các công việc khác theo sự phân công của cấp trên.', 'Trình độ: Sinh viên năm 2 đến cử nhân tốt nghiệp đại học/cao đẳng chuyên ngành kinh tế, quản trị nhân sự hành chính, ... Có khả năng làm việc với thái độ làm việc tích cực và chủ động. Chủ động trong công việc, có tinh thần trách nhiệm, có tinh thần làm việc nhóm, có khả năng nghiên cứu công việc mới, thực hiện các yêu cầu từ cấp trên.
Kỹ năng chuyên môn: [''Microsoft Office (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Thái độ làm việc tích cực'', ''Chủ động trong công việc'', ''Tinh thần trách nhiệm'', ''Làm việc nhóm'', ''Khả năng nghiên cứu'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Hỗ trợ dấu mộc xác nhận thực tập'', ''Cấp giấy chứng nhận, chứng chỉ thực tập khi hoàn thành chương trình'', ''Có nhân viên công ty hướng dẫn training trực tiếp'', ''Nâng cao hồ sơ profile công việc'', ''Nghỉ lễ, Tết đầy đủ theo quy định nhà nước'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (547, 2, 9, 'Thực Tập Sinh Tuyển Dụng', '1. Tuyển dụng (80%) - Tìm kiếm ứng viên, tạo nguồn ứng viên. - Hẹn lịch phỏng vấn, gửi email mời phỏng vấn - thông báo kết quả phỏng vấn. - Đăng tin tuyển dụng, xóa bỏ bài đăng khi tin đăng hết hạn trên các jobsite. 2. Truyền thông thương hiệu tuyển dụng (20%) - Quản lý, khai thác và xây dựng tuyến nội dung trên các kênh truyền thông thương hiệu tuyển dụng: fanpage, linkedin,…', '- Là sinh viên năm 3 hoặc năm 4 các trường đại học, đáp ứng tối thiểu 7 buổi (3.5 ngày)/tuần làm việc. - Có kinh nghiệm tuyển dụng là một điểm cộng lớn. - Có tư duy nhân sự, yêu thích làm việc với con người và định hướng phát triển trong ngành Nhân sự. - Nhanh nhẹn, có trách nhiệm với công việc.
Kỹ năng mềm: [''Nhanh nhẹn'', ''Có trách nhiệm với công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Phụ cấp ăn'', ''Cung cấp dấu mộc thực tập'', ''Có pantry và trà, coffee miễn phí trong văn phòng'', ''Được học hỏi sâu về chuyên môn nhân sự ở các mảng Tuyển dụng'', ''Cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (548, 3, 9, 'Cộng Tác Viên Tuyển Dụng Bất Động Sản', 'Tìm kiếm, sàng lọc và đề xuất hồ sơ ứng viên theo yêu cầu từng vị trí (ưu tiên: Sales, Telesales,…). Đăng tin tuyển dụng trên các kênh: TopCV, Facebook, Zalo, TikTok,… Thực hiện gọi điện, nhắn tin mời ứng viên phỏng vấn (nếu cần). Hỗ trợ quản lý database ứng viên, báo cáo kết quả lọc hồ sơ hàng tuần. Có thể tham gia hỗ trợ phỏng vấn hoặc follow ứng viên trong quá trình onboarding.', 'Không yêu cầu kinh nghiệm, ưu tiên sinh viên các ngành: Quản trị Nhân lực, Kinh tế, Truyền thông,… Yêu thích công việc tuyển dụng, nhanh nhẹn, giao tiếp tốt. Biết dùng các nền tảng tuyển dụng, mạng xã hội, Google Sheet cơ bản. Có laptop cá nhân, chủ động trong công việc.
Kỹ năng chuyên môn: [''Sử dụng các nền tảng tuyển dụng'', ''Mạng xã hội'', ''Google Sheet cơ bản'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Giao tiếp tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:30 đến 12:00)', '[''Hỗ trợ lương cứng + dấu mộc thực tập'', ''Được đào tạo quy trình tuyển dụng thực tế'', ''Môi trường trẻ trung, teamwork thoải mái'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (549, 7, 9, 'Thực Tập Sinh Đào Tạo', 'Hỗ trợ tổ chức các lớp đào tạo nội bộ, sự kiện đào tạo của công ty. Tham gia điều phối, hỗ trợ thuyết trình, kết nối trong các hoạt động đào tạo, các sự kiện văn hoá của công ty. Tham gia xây dựng nội dung đào tạo, soạn giáo trình, slide, tài liệu học tập. Hỗ trợ quản lý học viên, theo dõi và tổng hợp kết quả đào tạo. Thực hiện các công việc hành chính liên quan đến đào tạo theo phân công. Tham gia các dự án phát triển văn hóa học tập và phát triển con người trong doanh nghiệp.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các ngành: Quản trị nguồn nhân lực, Sư phạm, Tâm lý, Truyền thông, Quản trị kinh doanh… Có kỹ năng thuyết trình, MC hoặc hùng biện là một lợi thế. Tư duy tích cực, có mong muốn phát triển lâu dài trong lĩnh vực đào tạo & phát triển con người. Có khả năng làm việc với cường độ cao, chịu được áp lực. Tinh thần học hỏi cao, cầu tiến, chủ động trong công việc. Sử dụng tốt các phần mềm văn phòng (PowerPoint, Word, Excel) đặc biệt các nền tảng/phần mềm thiết kế truyền thông là một lợi thế lớn.
Kỹ năng chuyên môn: [''PowerPoint'', ''Word'', ''Excel'']
Kỹ năng mềm: [''Kỹ năng thuyết trình'', ''Tư duy tích cực'', ''Khả năng làm việc với cường độ cao'', ''Chịu được áp lực'', ''Tinh thần học hỏi cao'', ''Cầu tiến'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Ký hợp đồng học việc 3-6 tháng'', ''Môi trường làm việc chuyên nghiệp-năng động-trẻ trung-thân thiện'', ''Hỗ trợ thực tập sinh đóng dấu mộc, chữ ký, tài liệu làm báo cáo thực tập'', ''Được hỗ trợ trong suốt quá trình làm việc, đào tạo kĩ năng làm việc'', ''Tham gia các chương trình đào tạo nội bộ và các khóa học bên ngoài'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (550, 8, 9, 'Thực Tập Sinh', '- Thiết kế hình ảnh, tin đăng tuyển dụng. Đăng tin tuyển dụng lên các trang mạng xã hội. Sơ vấn ứng viên, sắp xếp lịch phỏng vấn, trực tiếp phỏng vấn ứng viên - Quản lý và theo sát cộng tác viên để các bạn nhanh chóng nắm bắt công việc và hoàn thành chỉ tiêu được giao - Công việc hành chính nhân sự: hồ sơ thủ tục đầu vào, đầu ra cho cộng tác viên', '- Thực tập tối thiểu 3 tháng. - Biết vi tính văn phòng, có máy tính cá nhân - Kỹ năng giao tiếp hiệu quả, có trách nhiệm với công việc. Năng động, tự tin, sáng tạo. - Kỹ năng làm việc: quản lý thời gian, sắp xếp công việc.
Kỹ năng chuyên môn: [''Vi tính văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp hiệu quả'', ''Có trách nhiệm với công việc'', ''Năng động'', ''Tự tin'', ''Sáng tạo'', ''Quản lý thời gian'', ''Sắp xếp công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Tham gia toàn bộ quy trình tuyển dụng của công ty'', ''Hướng dẫn đầy đủ kỹ năng làm việc tại văn phòng'', ''Môi trường làm việc chuyên nghiệp, thân thiện'', ''Cơ hội trở thành nhân viên chính thức sau khi thực tập'', ''Được đóng dấu xác nhận thực tập tại công ty'', ''Thưởng cao khi đạt chỉ tiêu trong từng tháng thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (551, 9, 9, 'Cộng Tác Viên Tuyển Dụng Tài Chính', 'Đăng bài tuyển dụng để tìm ứng viên theo các vị trí mà công ty đang tuyển. Tuyển chọn và lọc CV Ứng viên phù hợp với các vị trí. Kết nối ứng viên với doanh nghiệp.', 'Bạn đang là Freelance tuyển dụng. Bạn đang là nhân sự/ Tuyển dụng tại các công ty Ưu tiên các công ty Bảo hiểm, Bất Động sản, Chứng khoán, Tài chính mong muốn có thêm thu nhập. Đam mê tuyển dụng và có kỹ năng đàm phán, thương lượng, thuyết phục. Có thời gian rảnh ngoài công việc hành chính mong muốn kiếm thêm thu nhập.
Kỹ năng mềm: [''Kỹ năng đàm phán'', ''Thương lượng'', ''Thuyết phục'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm việc từ xa', '[''Hoa hồng tuyển dụng hấp dẫn'', ''Thưởng'', ''Tài liệu hỗ trợ và định hướng rõ ràng'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (552, 10, 9, 'Thực Tập Sinh Tuyển Dụng', 'Thực hiện đăng tuyển thông tin tuyển dụng trên các kênh tuyển dụng. Hỗ trợ phỏng vấn: liên hệ với ứng viên, sắp xếp lịch phỏng vấn và hỗ trợ trong buổi phỏng vấn. Lưu trữ, chuyển phát các giấy tờ, hợp đồng liên quan đến tuyển dụng. Hỗ trợ các công việc khác của Phòng Tuyển dụng khi được phân công.', '1. Trình độ học vấn - Sinh viên năm 3, năm 4 các trường Cao đẳng, Đại học khối ngành Kinh tế, Thương mại, Tiếng Anh, Quản trị Nhân lực, Luật..... Có thể đăng ký làm việc fulltime hoặc part time. Nếu làm partime thì yêu cầu thời gian làm việc tối thiểu 5 - 6 buổi/tuần. 2. Kiến thức/ Kỹ năng - Đam mê và muốn tìm hiểu về nghề Quản trị nhân lực (Tuyển dụng). - Thành thạo tin học văn phòng. - Có khả năng sắp xếp công việc hợp lý, chăm chỉ. - Tinh thần làm việc với trách nhiệm cao, tuân thủ quy định.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Có khả năng sắp xếp công việc hợp lý'', ''Chăm chỉ'', ''Tinh thần làm việc với trách nhiệm cao'', ''Tuân thủ quy định'']', 'INTERNSHIP', 'ONSITE', 'gia lâm', NULL, 'MONTHLY', 4000000.00, '0.0 triệu', 'Fulltime hoặc Part time, tối thiểu 5 - 6 buổi/tuần', '[''Cơ hội làm việc trong môi trường chuyên nghiệp'', ''Được đào tạo, hướng dẫn các công việc chuyên môn'', ''Cơ hội phát triển lên nhân viên chính thức'', ''Hỗ trợ ăn trưa và gửi xe miễn phí'', ''Hỗ trợ dấu thực tập nếu cần'', ''Văn phòng làm việc hiện đại, đẹp chuẩn Châu Âu'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (553, 2, 9, 'Thực Tập Sinh Sale Admin', 'Hỗ trợ cập nhật dữ liệu theo bảng Excel và nhập liệu vào phần mềm. Hỗ trợ photocopy, scanning, lưu hồ sơ/ chứng từ và giao/ nhận hồ sơ/ tài liệu. Soạn thảo văn bản, quyết định, lưu trữ các công văn, giấy tờ, tài liệu, hồ sơ, hợp đồng. Các công việc khác khi có yêu cầu của Trưởng BP/ BGĐ.', 'Sinh viên các ngành ngành Hành Chính Nhân Sự, Quản trị kinh doanh hoặc các ngành liên quan khác. Kỹ năng tin học văn phòng cơ bản, ưu tiên ứng viên có bằng MOS EXCEL. Kỹ năng giao tiếp và quản lý thời gian tốt. Cẩn thận, tỉ mỉ và có khả năng làm việc độc lập cũng như theo nhóm. Có laptop cá nhân để phục vụ cho công việc. Ưu tiên ứng viên có khả năng làm việc fulltime.
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng cơ bản'', ''Bằng MOS EXCEL'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Quản lý thời gian'', ''Cẩn thận'', ''Tỉ mỉ'', ''Có khả năng làm việc độc lập và theo nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30), Part-time linh hoạt theo lịch học', '[''Cơ hội học hỏi và trải nghiệm môi trường làm việc thực tế, chuyên nghiệp'', ''Được đào tạo và hỗ trợ phát triển kỹ năng tin học văn phòng'', ''Hỗ trợ ký và đóng mộc thực tập'', ''Môi trường làm việc năng động, trẻ trung, chuyên nghiệp; phát triển kỹ năng, giao lưu, học hỏi, mở rộng kiến thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (554, 3, 9, 'Sale Phái Cử Lao Động (Full-Time, Part-Time)', 'Tuyển dụng vị trí nhân viên Sale tư vấn xuất khẩu lao động Nhật Bản. Đăng bài trên các hội nhóm tìm kiếm ứng viên có nhu cầu lao động tại Nhật Bản. Tư vấn ứng viên theo kịch bản có sẵn (Sẽ được đào tạo từ đầu). Làm việc tại văn phòng, không yêu cầu di chuyển công tác.', 'Không yêu cầu kinh nghiệm, sẽ được đào tạo từ đầu bởi những chuyên gia hàng đầu trong lĩnh vực tư vấn xuất khẩu lao động Nhật Bản. Kiên trì, ham học hỏi có chí tiến thủ trong công việc. Chủ động trong công việc. Có laptop cá nhân phục vụ cho công việc. Đối với nhân viên Partime: Làm tối thiểu 3 buổi/ tuần.
Kỹ năng chuyên môn: [''Thành Thạo Các Phần Mềm Văn Phòng (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Kiên trì'', ''Ham học hỏi'', ''Chủ động'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '10.0 - 15.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Mức lương cạnh tranh'', ''Tỷ lệ triết khấu hoa hồng cao'', ''Được đào tạo trong lĩnh vực Xuất khẩu lao động Nhật'', ''Tham gia các lớp học đào tạo tiếng Nhật, tiếng Hàn miễn phí tại công ty'', ''Cước điện thoại'', ''Thưởng hiệu quả làm việc'', ''Bảo hiểm xã hội'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (555, 7, 9, 'Cộng Tác Viên Tuyển Dụng Nhân Sự (Tuyển Mass)', 'Tiếp nhận thông tin tuyển dụng theo tuần - tháng của công ty. Truyền thông tuyển dụng: Chủ động khai thác tìm kiếm ứng viên qua các kênh mạng xã hội, mạng lưới cá nhân, các mối quan hệ khác. Sàng lọc ứng viên theo tiêu chí tuyển dụng vị trí Sales tại công ty. Gửi CV ứng tuyển cho chuyên viên tuyển dụng, hỗ trợ giải đáp ứng viên theo nội dung JD/các câu hỏi phát sinh cần hỗ trợ thông tin từ Chuyên viên tuyển dụng, Nhận thông tin về kết quả công việc hàng tháng.', 'Là các cá nhân có khả năng giới thiệu ứng viên phù hợp với tiêu chí tuyển dụng của công ty (Người đang đi làm các ngành nghề có liên quan tới sales, HR công ty khác, sinh viên..).
Kỹ năng chuyên môn: [''Biết dùng các nền tảng tuyển dụng'', ''Mạng xã hội'', ''Google Sheet cơ bản'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng tìm kiếm và sàng lọc hồ sơ'', ''Kỹ năng xây dựng mối quan hệ'']', 'PART_TIME', 'ONSITE', 'hải phòng', 'Hải Phòng', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Làm việc từ xa', '[''Chủ động thời gian'', ''Nhận hoa hồng trên mỗi ứng viên tuyển thành công'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (556, 8, 9, 'Thực Tập Sinh Trợ Lý Giám Đốc', 'Kiểm tra các tài liệu cần được đóng dấu trước khi trình lên Tổng Giám đốc. Hỗ trợ sắp xếp lịch trình của Tổng Giám đốc. Thực hiện công tác văn thư, lưu trữ văn thư. Các nhiệm vụ khác được giao.', 'Sinh viên năm 4 hoặc vừa tốt nghiệp Đại học chuyên ngành Ngôn ngữ Trung/Anh, Tài chính - Ngân hàng hoặc các ngành liên quan. Tiếng Trung (HSK4) trở lên là một lợi thế. Khả năng sử dụng tiếng Anh cơ bản. Sử dụng thành thạo các ứng dụng vi tính văn phòng (Word, Excel và Power Point). Có tinh thần trách nhiệm. Cẩn thận.
Kỹ năng chuyên môn: [''Sử dụng thành thạo các ứng dụng vi tính văn phòng (Word, Excel và Power Point)'']
Kỹ năng mềm: [''Có tinh thần trách nhiệm'', ''Cẩn thận'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 - 2.4 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ phụ cấp thực tập Full-time: 2.000.000 VND/tháng và chi phí gửi xe: 400.000 VND/tháng'', ''Tham gia các chương trình đào tạo của công ty (kỹ năng chuyên môn, kỹ năng giao tiếp)'', ''Có cơ hội tham gia Team building/ Đi chơi/ Hoạt động trong nhà/ Tiệc tùng/ Du lịch hàng năm với công ty'', ''Môi trường năng động, chuyên nghiệp, cơ hội làm việc và học tập liên quan đến kiến thức đầu tư, trực tiếp từ các chuyên gia trong ngành chứng khoán'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (557, 9, 9, 'Thực Tập Sinh Tuyển Dụng Hành Chính', 'Hỗ trợ công tác tuyển dụng nhân sự; Hỗ trợ công tác tiếp nhận, lưu trữ hồ sơ hành chính (các loại văn bản đến đi, hồ sơ nhân sự, hợp đồng nhân sự); Hỗ trợ soạn thảo các văn bản hành chính (thông báo, quyết định, quy trình,…); Hỗ trợ các thủ tục hành chính cho người nước ngoài; Hỗ trợ công tác truyền thông nội bộ; Thực hiện công việc theo yêu cầu của quản lý trực tiếp.', 'Sinh viên mới tốt nghiệp Đại học chuyên ngành Quản trị nhân lực, Luật,…. Và các chuyên ngành khác có liên quan; Có kinh nghiệm liên quan đến tuyển dụng; Có định hướng phát triển theo Hành chính – nhân sự; Tiếng Anh hoặc tiếng Nhật giao tiếp thành thạo là điểm cộng.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Giao tiếp tốt'', ''Chăm chỉ'', ''Cẩn thận'', ''Khả năng học hỏi nhanh'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.5 triệu', 'Thứ 2 - Thứ 6 (08:30 - 17:30), Thứ 7 (08:30 - 12:30)', '[''Có cơ hội trở thành nhân viên chính thức sau thời gian thực tập'', ''Môi trường làm việc trẻ, năng động, sáng tạo'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (558, 10, 9, 'Nhân Viên Lễ Tân Văn Phòng (Theo Ca)', 'Chào đón khách theo quy trình chuẩn. Thực hiện quy trình check-in, check-out cho khách. Hướng dẫn chi tiết về các gói thuê, tiện ích và dịch vụ của khu coworking. Cập nhật và theo dõi quản lý khách sử dụng coworking. Phối hợp với PA thực hiện kiểm tra vệ sinh & sắp xếp khu coworking theo checklist hàng ngày. Đảm bảo các thiết bị văn phòng luôn trong trạng thái sẵn sàng. Quản lý lịch đặt phòng họp. Gửi thư từ, bưu phẩm. Báo cáo và theo dõi việc khắc phục sự cố. Quản lý, mua sắm vật tư và thiết bị văn phòng. Phối hợp với các phòng/ban/bộ phận liên quan để giải quyết các vấn đề phát sinh. Địa điểm làm việc: Vinhomes Ocean Park, Nghĩa Trụ, Văn Giang, Hưng Yên.', 'Sinh viên năm 3,4 các trường Đại học, Cao đẳng chuyên ngành hành chính văn phòng, văn thư - lưu trữ, hoặc các ngành nghề liên quan khác. Ưu tiên ứng viên từng làm các công việc tại nhà hàng, quán cà phê,..hoặc các công việc hành chính. Kỹ năng giao tiếp tốt, ứng xử chuyên nghiệp. Chăm chỉ, chịu khó, nhanh nhẹn, hoạt bát. Cẩn thận, tỉ mỉ trong công việc. Sử dụng thành thạo Microsoft Office. Có trách nhiệm cao trong công việc, trung thực, trung thành với công ty. Làm việc xoay ca: 8:00-12:00, 13:30-17:30 hoặc 18:00-22:00. Yêu cầu làm việc tối thiểu 4h/ngày.
Kỹ năng chuyên môn: [''Sử dụng thành thạo Microsoft Office'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Chăm chỉ'', ''Chịu khó'', ''Nhanh nhẹn'', ''Hoạt bát'', ''Cẩn thận'', ''Tỉ mỉ trong công việc'', ''Có trách nhiệm cao trong công việc'', ''Trung thực'', ''Trung thành với công ty'']', 'PART_TIME', 'ONSITE', 'hưng yên', 'Hưng Yên', 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm việc xoay ca: 8:00-12:00, 13:30-17:30 hoặc 18:00-22:00. Yêu cầu làm việc tối thiểu 4h/ngày', '[''Có thể xoay ca linh động'', ''Được đào tạo bài bản về nghiệp vụ lễ tân - hành chính'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Tham gia các sự kiện, hoạt động vui chơi giải trí tại công ty như: teambuilding, companytrip, sinh nhật công ty'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (559, 2, 9, 'Trợ Lý Tuyển Dụng', 'Tìm hiểu , lên kế hoạch mở rộng nguồn ứng viên. Lập báo cáo và mục tiêu công việc theo tháng, quý. Tham dự các khóa đào tạo kỹ năng căn bản và chuyên sâu. Hỗ trợ phát triển số lượng và chất lượng nhân sự. Thiết lập tiêu chí tuyển dụng theo từng dự án, chiến dịch. Đăng tin tuyển dụng và liên hệ ứng viên. Sàng lọc hồ sơ, sắp xếp lịch phỏng vấn.', 'Không yêu cầu kinh nghiệm. Giới tính: Nam, Nữ. Học vấn: sinh viên hoặc tốt nghiệp Trung cấp trở lên. Có kỹ năng giao tiếp, thuyết phục là lợi thế.
Kỹ năng mềm: [''kỹ năng giao tiếp'', ''kỹ năng thuyết phục'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 17:00)', '[''Môi trường làm việc chuyên nghiệp đầy tiềm năng, năng động, trẻ trung'', ''Quan tâm và chú trọng phát triển kỹ năng, cơ hội thăng tiến cho nhân viên'', ''Chương trình tưởng thưởng, du lịch, team-building được áp dụng công bằng với mọi cấp bậc từ trợ lý tới quản lý'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (560, 3, 9, 'Điều hành tài khoản (thực tập)', 'Hiểu rõ về sản phẩm và dịch vụ của TRÒN, tìm hiểu nhu cầu của khách hàng để đề xuất giải pháp phù hợp. Chăm sóc khách hàng, tư vấn và giải đáp thắc mắc. Tiếp nhận, xử lý đơn hàng, theo dõi, cập nhật tiến độ đơn hàng, đảm bảo đúng tiến độ và chất lượng. Tham gia các hoạt động chăm sóc và duy trì mối quan hệ với khách hàng. Báo cáo công việc với cấp trên và làm các nhiệm vụ khác khi được giao.', 'Laptop cá nhân. Sinh viên đang theo học các ngành Marketing, Kinh doanh, Truyền thông, Ngôn Ngữ. Có kỹ năng giao tiếp, làm việc nhóm, chủ động, ham học hỏi. Khả năng giao tiếp tiếng Anh tốt.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng làm việc nhóm'']
Kỹ năng mềm: [''Chủ động'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00), Thứ 7 (từ 08:30 đến 12:30)', '[''Đa dạng khách hàng, đối tác trong - ngoài nước mang lại nhiều cơ hội học hỏi và phát triển kỹ năng.'', ''Trở thành nhân viên chính thức tại TRÒN'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (561, 7, 9, 'Nhân Viên Tuyển Dụng Part-Time', '- Trực tiếp tuyển dụng các vị trí trong toàn công ty - Đăng tin tuyển dụng qua các kênh nguồn online và offline - Tiếp nhận hồ sơ, sàng lọc, sắp xếp lịch phỏng vấn. - Tổ chức phỏng vấn, đánh giá, lựa chọn, đàm phán trực tiếp với ứng viên nhận việc - Tổ chức các hoạt động truyền thông tuyển dụng - Quản lý và thực hiện các báo cáo tuyển dụng - Thực hiện các công việc khác được giao', '* Có máy tính cá nhân. * Nhanh nhẹn, hoạt bát, hướng ngoại. * Cẩn thận, trung thực, nhiệt tình, có trách nhiệm với công việc và sắp xếp công việc khoa học. * Ưu tiên các bạn yêu thích tuyển dụng và muốn phát triển định hướng tuyển dụng * Thành thạo kỹ năng Ms Office và các phần mềm khác liên quan.
Kỹ năng chuyên môn: [''Ms Office'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Hoạt bát'', ''Hướng ngoại'', ''Cẩn thận'', ''Trung thực'', ''Nhiệt tình'', ''Có trách nhiệm với công việc'', ''Sắp xếp công việc khoa học'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Hỗ trợ dấu thực tập'', ''Được mở rộng và phát triển mạng lưới tuyển dụng'', ''Được kèm cặp về kỹ năng tuyển dụng nhân sự'', ''Cơ hội trở thành Nhân viên chính thức sau thời gian thực tập'', ''Môi trường gen Z trẻ trung, năng động, sáng tạo'', ''Các chính sách, chế độ khác theo quy định của Công ty'', ''Môi trường làm việc chuyên nghiệp và thân thiện'', ''Có nhiều cơ hội thăng tiến, phát triển nghề nghiệp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (562, 8, 9, 'Nhân Viên Chăm Sóc Khách Hàng', 'Nhận danh sách khách hàng tiềm năng từ công ty (khách hàng mới chưa từng sử dụng sản phẩm/dịch vụ ZoZin). Chủ động gọi điện cho khách hàng để: Giới thiệu về sản phẩm, dịch vụ, các ưu đãi hiện có. Tư vấn lợi ích khi sử dụng dịch vụ bảo dưỡng, sửa chữa, thay lõi lọc tại nhà. Khơi gợi nhu cầu, tạo sự tin tưởng và đặt lịch cho kỹ thuật viên đến hỗ trợ tại nhà. Không cần tìm kiếm khách hàng, không bị ép doanh số – chỉ cần làm tốt theo danh sách có sẵn. Được giữ lại khách hàng tiềm năng của riêng mình để chăm sóc và phát triển mối quan hệ lâu dài. Sau 06 tháng, nhân viên sẽ tiếp tục được phân bổ khách hàng cũ định kỳ (đã từng phát sinh trước đó) để gọi lại và đặt lịch chăm sóc tiếp theo.', 'Thái độ: Lạc quan, tích cực; Chủ động, không ngại gọi điện; Tận tâm với công việc, muốn kiếm tiền; Kỹ năng: Giao tiếp tốt, Xử lý từ chối, Tư vấn bán hàng, Biết quản lý thời gian.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Xử lý từ chối'', ''Tư vấn bán hàng'', ''Biết quản lý thời gian'']', 'PART_TIME', 'REMOTE', 'bắc ninh', 'Bắc Ninh', 'MONTHLY', 8000000.00, '5.0 - 8.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 11:30, 14:30 đến 17:30, 17:35 đến 20:30)', '[''Thu nhập ổn định & rõ ràng'', ''Đào tạo & phát triển'', ''Môi trường làm việc thân thiện'', ''Chế độ làm việc hợp lý'', ''Phúc lợi đầy đủ'', ''Du lịch hàng năm'', ''Thưởng hiệu quả làm việc'', ''Thưởng tháng 13'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (563, 9, 9, 'Tuyển dụng tư vấn nhập học đại học', 'Cung cấp phản hồi khái niệm về ý tưởng và cấu trúc của sinh viên tuyên bố cá nhân và các bài tiểu luận bổ sung. Đánh giá và sửa đổi các bài tiểu luận sinh viên cho phong cách, ngữ pháp và giọng nói, khuyến khích các sinh viên theo đuổi quá trình học tập của riêng họ với tư cách là nhà văn. Nhận xét về và chỉnh sửa học sinh, sơ yếu lý lịch và các bài tiểu luận hoạt động ngoại khóa. Huấn luyện viên sinh viên về các kỹ năng giao tiếp và phỏng vấn giao tiếp (nếu cần).', 'We are open to recruiting both English speakers and Vietnamese nationals who have graduated from 4-year colleges and universities in English speaking countries, with: At least a Bachelor’s Degree from an accredited University, preferably Ivy league university or Top UN/LAC with majors in Philosophy, Literature, the Social Sciences, History, English or other related disciplines... Experience in essay editing and writing coaching is a plus Excellent critical thinking and writing skills, with flexible confidence across a range of writing formats Excellent organizational skills and team spirit A desire to help students learn and reach their full potential
Kỹ năng chuyên môn: [''Essay editing'', ''Writing coaching'']
Kỹ năng mềm: [''Excellent critical thinking'', ''Excellent writing skills'', ''Excellent organizational skills'', ''Team spirit'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Flexible work schedule', '[''Highly competitive compensation package and bonus'', ''Flexible work schedule for editors'', ''Quality training program with career tracks'', ''Intellectual and friendly working environment'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (564, 10, 9, 'CV Đối Tác Nhân Sự Thời Vụ (HRBP Exe_Seasonal)', '- Ký HĐ 8 tháng - Thực hiện kiểm soát cơ cấu và tổ chức nguồn nhân lực nhằm đảm bảo hoạt động vận hành của các phòng ban được ổn định và đảm bảo trong kế hoạch được duyệt - Hướng dẫn và hỗ trợ bộ phận chuyên môn về chính sách và thủ tục nhân sự - Quản trị hiệu quả công việc và tư vấn phòng ban nâng cao hiệu suất làm việc của nhân viên - Phân tích các chỉ số về nguồn nhân lực để đảm bảo hiệu suất của tổ chức cũng như ngăn ngừa rủi ro trong quá trình vận hành - Xây dựng kế hoạch phát triển và gắn kết nguồn nhân sự chủ chốt, nhân tài và kế cận trong công ty đảm bảo quản lý các phân khúc nhân tài để sử dụng hiệu quả nguồn nhân lực - Tư vấn cho các Phòng ban/ Bộ phận về các giải pháp liên quan đến thay đổi nhân sự: tuyển dụng, nghỉ việc, điều chuyển, thăng tiến, kiêm nhiệm… trong quá trình vận hành - Các dự án và sáng kiến nhân sự khác theo phân công', '- Tốt nghiệp Đại học trở lên, ưu tiên chuyên ngành Quản trị Nhân sự, Quản trị Nguồn nhân lực, Quản lý và phát triển nguồn nhân lực, Quan hệ lao động, ... - Có tối thiểu 2 năm kinh nghiệm ở vị trí tương đương - Có kinh nghiệm về quản trị hiệu suất và các dự án liên quan - Khả năng quản trị dữ liệu tốt
Kỹ năng chuyên môn: [''Quản trị hiệu suất'', ''Quản trị dữ liệu'']
Kỹ năng mềm: [''Giao tiếp'', ''Tư vấn'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:15)', '[''Tham gia BH đầy đủ ngay từ tháng đầu tiên'', ''Môi trường trẻ, năng động, chuyên nghiệp'', ''Cơ hội phát triển về chuyên môn và thăng tiến lên các vị trí chính thức'', ''Ăn trưa'', ''Cước điện thoại'', ''Được cấp Máy tính'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (565, 2, 9, 'Thực Tập Sinh Văn Thư Lưu Trữ', 'Hỗ trợ quản lý văn bản đi – đến của Công ty; Quản lý và sử dụng con dấu của Công ty; Hỗ trợ lưu trữ văn bản nội bộ trong công ty; Phân loại tài liệu, lập hồ sơ và biên mục văn bản; Cập nhật, tổng hợp, thống kê hồ sơ, tài liệu; Các công việc khác theo yêu cầu.', 'Sinh viên năm 3,4 chuyên ngành Văn thư – Lưu trữ ở các trường Cao đẳng, Đại học. Có thể thực tập từ 4 - 6 tháng. Có tính cẩn thận, siêng năng, trung thực và nhanh nhẹn.
Kỹ năng mềm: [''Cẩn thận'', ''Siêng năng'', ''Trung thực'', ''Nhanh nhẹn'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Từ T2 - T6 (9h - 18h) & T7 (9h - 13h)', '[''Trợ cấp thực tập: 1.000.000/ tháng'', ''Được tiếp xúc với hồ sơ vụ việc thực tế'', ''Được hướng dẫn cách thức xử lý tình huống'', ''Được đào tạo theo chính sách của công ty'', ''Được tham gia các hoạt động ngoại khóa'', ''Được xác nhận thực tập sau khi kết thúc thực tập'', ''Được ưu tiên tuyển dụng vào nguồn nhân lực chính thức của công ty'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (566, 3, 9, 'Nhân viên dịch vụ khách hàng (ca đêm- 1-2 người)', 'Xử lý khối lượng lớn yêu cầu của khách hàng qua điện thoại và Live chat (và các yêu cầu từ email nếu cần) bằng tiếng Anh. Các trường hợp thường gặp đều có mẫu trả lời sẵn. Hỗ trợ khách hàng giải quyết vấn đề, trả lời câu hỏi và giải quyết các mối quan tâm liên quan đến sản phẩm hoặc dịch vụ. Luôn nỗ lực hết mình làm hài lòng khách hàng, xác định và đánh giá nhu cầu của khách hàng để đạt được sự hài lòng. Ghi chép thông tin của khách hàng và duy trì nhật ký chính xác về các vấn đề và giải pháp trong hệ thống CRM của công ty, tuân thủ các báo cáo vấn đề hiệu quả đến đội ngũ nội bộ và quản lý. Cung cấp phản hồi về xu hướng và vấn đề của khách hàng để cải thiện dịch vụ và sản phẩm. Thực hiện các nhiệm vụ theo yêu cầu của trưởng nhóm và hỗ trợ đội ngũ hoàn thành các mục tiêu chung.', 'Có thể làm việc vào các ngày lễ nếu cần. Có máy tính/laptop cấu hình cao và kết nối internet để làm việc trực tuyến. Thái độ: Tỉ mỉ, có trách nhiệm, linh hoạt và khả năng học hỏi nhanh. Kỹ năng: Kỹ năng nói và viết tiếng Anh tốt (tương đương IELTS từ 6.0 trở lên). Có khả năng tư duy phản biện và đưa ra các giải pháp hiệu quả cho các vấn đề của khách hàng. Khả năng làm việc độc lập cao. Tỉ mỉ, đảm bảo độ chính xác cao trong các phản hồi và việc ghi chú thông tin. Khả năng nhanh chóng xác định vấn đề, đưa ra giải pháp và thực hiện các quy trình khắc phục sự cố từng bước. Ưu tiên: Có trên 1 năm kinh nghiệm trong ngành dịch vụ khách hàng e-commerce là một lợi thế. Có khả năng thích nghi hiệu quả với các thay đổi trong quy trình làm việc và hệ thống để đạt được mục tiêu của dự án hoặc nhóm.
Kỹ năng chuyên môn: [''Kỹ năng nói và viết tiếng Anh tốt (tương đương IELTS từ 6.0 trở lên)'', ''Kỹ năng sử dụng hệ thống CRM'']
Kỹ năng mềm: [''Tỉ mỉ'', ''Có trách nhiệm'', ''Linh hoạt'', ''Khả năng học hỏi nhanh'', ''Tư duy phản biện'', ''Khả năng làm việc độc lập'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7, 8 giờ/ngày (từ 9 giờ tối đến 5 giờ sáng)', '[''Các khoản thưởng và khuyến khích nếu vượt hiệu suất kỳ vọng'', ''Được đào tạo và hướng dẫn trực tiếp từ quản lý'', ''Cơ hội cải thiện chuyên môn/kỹ năng và khả năng giao tiếp tiếng Anh'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (567, 7, 9, 'Thực Tập Sinh Phát Triển Tổ Chức', 'Hỗ trợ xây dựng, tổ chức và vận hành các hoạt động phát triển tổ chức (foundation) theo định hướng chiến lược: cấu trúc, điều lệ, mô hình quản trị và vận hành. Nghiên cứu mô hình hoạt động của các tổ chức tương tự trong nước và quốc tế (foundation phi lợi nhuận, DAO, v.v.) để đề xuất áp dụng phù hợp. Tham gia vào việc xây dựng các quy trình, quy chế hoạt động và tài liệu pháp lý liên quan đến thành lập và vận hành foundation. Hỗ trợ tổ chức các hoạt động đối ngoại, làm việc với cộng đồng, cố vấn, đối tác hoặc các bên thứ ba (luật sư, kế toán, tổ chức kiểm toán). Chuẩn bị tài liệu trình bày, báo cáo, kế hoạch phát triển tổ chức cho đội ngũ quản lý và nhà tài trợ (nếu có). Phối hợp với các phòng ban để đảm bảo foundation vận hành hiệu quả, minh bạch và đúng định hướng.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các ngành: Quản trị Kinh doanh, Luật, Quan hệ Quốc tế, Hành chính công, hoặc các ngành liên quan. Có kỹ năng nghiên cứu, tổng hợp và viết báo cáo tốt. Có tư duy tổ chức, logic và khả năng làm việc chi tiết, cẩn thận. Khả năng giao tiếp tốt, đặc biệt là trong môi trường đa bên và định hướng cộng đồng. Ưu tiên ứng viên có kiến thức hoặc kinh nghiệm với tổ chức phi lợi nhuận, dự án cộng đồng. Kỹ năng sử dụng Google Workspace hoặc Microsoft Office thành thạo.
Kỹ năng chuyên môn: [''Kỹ năng sử dụng Google Workspace'', ''Microsoft Office'']
Kỹ năng mềm: [''Kỹ năng nghiên cứu'', ''Tổng hợp và viết báo cáo'', ''Tư duy tổ chức'', ''Logic'', ''Khả năng làm việc chi tiết'', ''Cẩn thận'', ''Khả năng giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ dấu mộc xác nhận thực tập, báo cáo thực tập, bài luận văn, chuyên đề, đồ án tốt nghiệp.'', ''Cấp giấy chứng nhận, chứng chỉ thực tập khi hoàn thành chương trình.'', ''Có nhân viên công ty hướng dẫn training trực tiếp.'', ''Nâng cao hồ sơ profile công việc.'', ''Nghỉ lễ, Tết đầy đủ theo quy định nhà nước và luật lao động.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (568, 8, 9, 'Nhân Viên Hành Chính Nhân Sự', 'Công tác về Nhân sự: Chịu trách nhiệm tuyển dụng Direct Sales (Nhân viên kinh doanh phần mềm quản lý bán hàng KiotViet). Lưu trữ hồ sơ và các giấy tờ khác liên quan của ứng viên và nhân viên. Thực hiện công tác chấm công, tính tiền lương, tiền thưởng và gửi bảng lương cho nhân viên định kỳ hàng tháng. Kiểm soát việc chấp hành nội quy hành chính của các nhân viên trong văn phòng; ghi nhận và tiến hành thưởng, phạt theo đúng quy định (nghỉ phép, nghỉ ốm, ...). Công tác về Hành chính – Kế toán – Hỗ trợ kinh doanh: Mua sắm, quản lý các trang thiết bị và đồ dùng văn phòng. Kiểm soát và lưu trữ giấy tờ hành chính và pháp lý của công ty. Tiếp nhận và kiểm tra thông tin hợp đồng từ nhân viên kinh doanh chuyển về và cập nhật lên hệ thống theo quy định Công ty. Kiểm tra và quyết chi các chương trình khuyến mãi của công ty theo đúng quy định. Thực hiện việc xuất nhập kho phần cứng & chứng từ theo đúng quy định. Kiểm soát kho hàng thực tế đầu nhập từ nội bộ điều chuyển và xuất cho nhân viên kinh doanh: chứng từ phiếu xuất kho, nhập kho; các quy định nhập và xuất máy. Hỗ trợ chuẩn bị công tác cho nhân sự tại văn phòng: đặt vé máy bay, khách sạn,... trong trường hợp cần thiết. Các công việc khác theo yêu cầu của quản lý trực tiếp.', 'NỮ, Ngoại hình ưa nhìn, nhanh nhẹn, thật thà, giao tiếp tốt. Độ tuổi 23 - 27. Ưu tiên có kinh nghiệm trong mảng nhân sự, hành chính - văn phòng. Tốt nghiệp cao đẳng trở lên chuyên ngành Nhân sự, Hành chính, Tài chính – kế toán, Kinh Tế. Thành thạo tin học văn phòng (Word, Excel). Làm thời vụ trong 6 tháng.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng (Word, Excel)'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Nhanh nhẹn'', ''Thật thà'']', 'PART_TIME', 'ONSITE', 'ninh bình', 'Ninh Bình', 'MONTHLY', 7000000.00, '6.0 - 7.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Thu nhập ổn định trong quá trình làm việc'', ''Được đào tạo trước và trong suốt quá trình làm việc'', ''Du lịch, nghỉ mát theo chi nhánh văn phòng'', ''Môi trường làm việc trẻ trung năng động'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (569, 9, 9, 'Business Admin Intern', '- Dự thảo và gửi email kinh doanh chuyên nghiệp cho khách hàng, đối tác và nhóm nội bộ. - Hỗ trợ chuẩn bị tài liệu và tham gia các cuộc họp giới thiệu kinh doanh. - Tham dự các cuộc họp với người quản lý tài khoản và ghi chú rõ ràng, chi tiết về tài liệu nội bộ và theo dõi. - Hỗ trợ hành chính - Tổ chức và cập nhật tài liệu, hồ sơ kinh doanh và báo cáo. - Hỗ trợ lập kế hoạch cuộc họp, hậu cần và phối hợp nội bộ. - Làm việc đa chức năng với các nhóm để đảm bảo các hoạt động và luồng thông tin trơn tru. - Thiết kế & giao tiếp nội bộ - Tạo và chỉnh sửa vật liệu hình ảnh bằng cách sử dụng Canva (slide, infographics, tài sản truyền thông xã hội). - Đảm bảo tất cả nội dung trực quan phù hợp với hướng dẫn thương hiệu Luna.', '- Strong communication skills in Vietnamese and basic English (especially for email writing). - Confident in both written and verbal communication; able to attend meetings with managers and partners. - Familiarity with Canva or similar design tools. - Detail-oriented, responsible, and eager to learn. - Able to work independently and collaboratively in a fast-paced environment. - Preferred Qualifications - Senior student or recent graduate in Business, Marketing, Communications, or related fields. - Previous experience in admin, assistant, or internship roles is a plus. - Interest in startups, technology, or AI is highly appreciated.
Kỹ năng chuyên môn: [''Canva'', ''design tools'']
Kỹ năng mềm: [''Strong communication skills'', ''Detail-oriented'', ''Responsible'', ''Eager to learn'', ''Able to work independently and collaboratively'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''A chance to work in a high-growth AI tech startup with global reach'', ''Hands-on experience and mentorship from experienced professionals'', ''Opportunity for full-time conversion based on performance'', ''Exposure to cutting-edge AI tools and software innovation'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (570, 10, 9, 'Thực Tập Sinh', 'Đăng tin tuyển dụng trên các kênh phù hợp, sàng lọc hồ sơ và liên hệ ứng viên. Sắp xếp lịch phỏng vấn, hỗ trợ quá trình tuyển dụng. Thực hiện các công việc hành chính nhân sự: lưu trữ, cập nhật hồ sơ nhân sự; soạn thảo hợp đồng lao động, quyết định, văn bản liên quan. Kiểm tra, xác minh thông tin của KOL/KOC tham gia chiến dịch và livestream. Hỗ trợ soạn thảo hợp đồng hợp tác, theo dõi và xử lý thanh toán chi phí. Cập nhật và lưu trữ hồ sơ KOL/KOC theo từng chiến dịch, phối hợp với các bộ phận liên quan. Thực hiện các công việc khác theo sự phân công của quản lý trực tiếp.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các ngành: Quản trị Nhân sự, Lao động – Tiền lương, Luật hoặc các chuyên ngành khác có liên quan. Có kiến thức về Luật lao động, Luật BHXH, thuế TNCN. Siêng năng, trung thực, có tinh thần học hỏi, trách nhiệm trong công việc. Giao tiếp tốt, cẩn thận, tỉ mỉ trong xử lý hồ sơ, dữ liệu. Thành thạo tin học văn phòng (Word, Excel, PowerPoint).
Kỹ năng chuyên môn: [''Kiến thức về Luật lao động'', ''Luật BHXH'', ''thuế TNCN'', ''Thành thạo tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Siêng năng'', ''Trung thực'', ''Có tinh thần học hỏi'', ''Trách nhiệm trong công việc'', ''Giao tiếp tốt'', ''Cẩn thận'', ''Tỉ mỉ trong xử lý hồ sơ, dữ liệu'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), 8h00 - 17h00 từ thứ 2 đến thứ 7 (làm 2 ngày thứ 7 trong tháng)', '[''Hỗ trợ chi phí thực tập 3.000.000 đồng/tháng'', ''Tham gia các hoạt động cùng công ty (party, team building...)'', ''Trải nghiệm thực tế trong lĩnh vực Nhân sự'', ''Trợ cấp thực tập hằng tháng'', ''Xác nhận sau khi kết thúc kỳ thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (571, 2, 9, 'Thực Tập Sinh Tuyển Dụng Full-Time', 'Khối lượng công việc: 70% hỗ trợ các công tác chuyên môn về Tuyển dụng + 30% hỗ trợ công tác admin; Hỗ trợ tạo nguồn, thu thập & xử lý data ứng viên; Hỗ trợ liên hệ sơ vấn ứng viên để sơ vấn, chốt kết quả và hẹn phỏng vấn trực tiếp; Hỗ trợ chuẩn bị các giấy tờ hồ sơ cần thiết trong quy trình tuyển dụng; Hỗ trợ hằng ngày các công việc về hành chính: trình ký chứng từ, đóng mộc giấy tờ văn bản, kiểm đếm và sửa lỗi các giấy tờ nếu có phát sinh, ...; Hỗ trợ tham gia các hoạt động, các sự kiện job-fair tại các Trường Cao Đẳng / Đại Học, ...; Hỗ trợ các hoạt động truyền thông thương hiệu tuyển dụng như: Hỗ trợ tham gia quay clip Tiktok, share và re-up tin đăng tuyển dụng, ...; Thực hiện các công việc khác theo phân công của Quản lý trực tiếp.', 'Sinh viên năm 3, năm 4 hoặc vừa tốt nghiệp tại các trường Cao Đẳng / Đại Học, thuộc các ngành Quản Trị Nhân Sự, Quản Trị Kinh Doanh hoặc các ngành khác có liên quan; Có thể đáp ứng thời gian thực tập trong vòng 03 tháng, và làm việc được tối thiểu 04 ngày toàn thời gian / tuần; Ưu tiên các bạn ứng viên ở gần Văn phòng Công Ty để tiện di chuyển (Địa chỉ VP: Lầu 7, TTTM Giga Mall, 240-242 Phạm Văn Đồng, TP. Thủ Đức); Yêu thích và có định hướng phát triển trong lĩnh vực Nhân Sự / Tuyển Dụng; Có kĩ năng giao tiếp và trình bày khá; Khả năng sử dụng Microsoft Office tốt.
Kỹ năng chuyên môn: [''Microsoft Office'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Trình bày'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '["Hỗ trợ đóng mộc ''Giấy xác nhận thực tập'' hoặc ''Đánh giá thực tập''", ''Công ty cung cấp thẻ gửi xe tại GigaMall'', ''Cung cấp Điện thoại để phục vụ công việc'', ''Môi trường làm việc trẻ trung, thân thiện & năng động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (572, 3, 9, 'Cộng Tác Viên Tuyển Dụng Online', '- Tiếp nhận thông tin tuyển dụng theo tuần, tháng của công ty, - Truyền thông tin tuyển dụng, tạo nguồn ứng viên theo mô tả công việc, - Gửi CV & nhập liệu data theo mẫu, - Hỗ trợ giải đáp ứng viên theo nội dung JD/các câu hỏi phát sinh cần hỗ trợ thông tin từ NV Tuyển dụng, - Nhận thông tin về kết quả công việc hàng tháng.', '- Sinh viên năm 2,3,4 ngành nhân sự, hoặc các khối ngành khác đang có nhu cầu làm việc trong lĩnh vực tuyển dụng - Ưu tiên ứng viên có kỹ năng soạn content và hình ảnh tuyển dụng (sẽ có bài tham khảo để định hướng), - Chăm chỉ, cẩn thận - Ứng viên đang không nằm trong mối quan hệ hợp tác với các công ty Giáo dục (bao gồm Edtech) tại vị trí nhân viên/CTV Tuyển dụng.
Kỹ năng chuyên môn: [''Kỹ năng soạn content'', ''Kỹ năng hình ảnh tuyển dụng'']
Kỹ năng mềm: [''Chăm chỉ'', ''Cẩn thận'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Cơ chế 1: Summit CV => CV được chọn phỏng vấn => Ứng viên đến phỏng vấn thì nhận 15.000 VNĐ - 25.000 VNĐ tùy vào độ khó mỗi vị trí.'', ''Cơ chế 2: Summit CV => CV được chọn phỏng vấn => Ứng viên pass và đến onboard thì đạt 500.000 VNĐ.'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (573, 7, 9, 'Tài khoản thực tập', 'Làm việc với khách hàng để giải quyết các vấn đề, yêu cầu của khách hàng. Điều phối, quản lý dự án quảng cáo online. Phối hợp với team nội bộ cũng như nhà cung cấp bên ngoài. Xử lý các công việc hành chính, giấy tờ.', 'Ưu tiên sinh viên năm 1, năm 2 hoặc năm 3. Tiếng Anh viết email và chat, không cần nói được. Kỹ năng dùng phần mềm word, excel. Chăm chỉ, trung thực, định hướng làm việc lâu dài. Thời gian làm việc dự kiến từ 1 năm trở lên.
Kỹ năng chuyên môn: [''Kỹ năng dùng phần mềm word'', ''Kỹ năng dùng phần mềm excel'']
Kỹ năng mềm: [''Chăm chỉ'', ''Trung thực'', ''Định hướng làm việc lâu dài'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 16:30)', '[''Lương 50.000 VNĐ/ buổi sáng hoặc chiều (đăng ký ít nhất 16 buổi làm việc mỗi tháng)'', ''Hỗ trợ phí gửi xe'', ''Hỗ trợ laptop làm việc'', ''Được đào tạo kiến thức về lĩnh vực digital và các sản phẩm - dịch vụ của công ty'', ''Phát triển mạnh mẽ kinh nghiệm & kỹ năng trong một thời gian ngắn'', ''Một môi trường thân thiện, chuyên nghiệp'', ''Cơ hội trải nghiệm nhiều loại hình khách hàng & lĩnh vực'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (574, 8, 9, 'Nhân Viên Thu Thập Dữ Liệu & Đăng Tin', '• Thu thập thông tin bất động sản (địa chỉ, diện tích, giá, hình ảnh) từ các website theo danh sách có sẵn • Đăng tin lên các nền tảng theo hướng dẫn và đúng khung giờ • Viết mô tả sản phẩm (1–2 lần/tuần) • Làm việc hoàn toàn online, đảm bảo nộp bài trước 19h mỗi ngày', '• Sinh viên có laptop hoặc điện thoại kết nối internet ổn định • Nghiêm túc, chăm chỉ, đúng hạn, có trách nhiệm với công việc • Ưu tiên biết tin học văn phòng, chỉnh sửa ảnh cơ bản
Kỹ năng chuyên môn: [''tin học văn phòng'', ''chỉnh sửa ảnh cơ bản'']
Kỹ năng mềm: [''nghiêm túc'', ''chăm chỉ'', ''đúng hạn'', ''có trách nhiệm với công việc'']', 'FREELANCE', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'FIXED_PROJECT', 2000000.00, '2.0 triệu', 'Khoảng 2 giờ/ngày (chọn sáng hoặc tối linh hoạt), Làm 7 ngày/tuần', '[''Thưởng hiệu suất nếu hoàn thành đúng tiến độ, chất lượng'', ''Thanh toán chuyển khoản minh bạch, đúng hạn'', ''Làm việc 100% từ xa, không cần đến văn phòng'', ''Được hướng dẫn công việc chi tiết'', ''Đào tạo miễn phí trước khi bắt đầu'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (575, 9, 9, 'Thực Tập Sinh Hành Chính Nhân Sự', 'Quản lý hồ sơ và dữ liệu nhân sự: Theo dõi, cập nhật và lưu trữ hồ sơ nhân viên; Nhập liệu và quản lý dữ liệu nhân sự trên hệ thống; Rà soát, sắp xếp và bảo quản hồ sơ nhân sự. Hỗ trợ công tác nhân sự: Hỗ trợ theo dõi các hợp đồng, soạn thảo hợp đồng, các văn bản khác theo yêu cầu của cán bộ hướng dẫn; Theo dõi thời hạn hợp đồng, hỗ trợ ký kết, gia hạn hay thanh lý hợp đồng; Hỗ trợ các công việc khác liên quan đến công tác tuyển dụng, đào tạo và quan hệ lao động, chính sách theo hướng dẫn của quản lý trực tiếp. Phối hợp với các phòng ban tổ chức các hoạt động nội bộ của công ty. Thực hiện các công việc khác theo yêu cầu của cán bộ hướng dẫn và lãnh đạo phòng.', '1.Kiến thức: - Tốt nghiệp hoặc đang theo học các chuyên ngành Quản trị nhân lực, Hành chính, Luật, Kinh tế... hoặc một số ngành liên quan; - Hiểu biết về Luật Lao động và các quy định pháp luật liên quan. 2. Kinh nghiệm: Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực nhân sự. 3. Kỹ năng: - Tin học văn phòng: Microsoft Word, Excel, Power Point; - Kỹ năng giao tiếp; - Kỹ năng soạn thảo văn bản, phân tích, xử lý thông tin; - Cẩn thận, tỉ mỉ, có tinh thần trách nhiệm cao, có khả năng làm việc độc lập và làm việc nhóm.
Kỹ năng chuyên môn: [''Microsoft Word'', ''Excel'', ''Power Point'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng soạn thảo văn bản'', ''Phân tích'', ''Xử lý thông tin'', ''Cẩn thận'', ''Tỉ mỉ'', ''Có tinh thần trách nhiệm cao'', ''Có khả năng làm việc độc lập và làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.5 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Phụ cấp thực tập: thỏa thuận theo năng lực'', ''Được cọ xát với các nhiệm vụ, chức năng của Phòng Nhân sự'', ''Môi trường làm việc sáng tạo, linh hoạt, tôn trọng và kích thích khả năng phát triển cá nhân cao'', ''Được đào tạo và hướng dẫn trực tiếp từ cán bộ quản lý'', ''Thực hành và làm việc trong môi trường chuyên nghiệp'', ''Thực hiện các công việc thực tế của phòng Nhân sự, từ đó nâng cao năng lực và kiến thức chuyên môn'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (576, 10, 9, 'Cộng Tác Viên Tuyển Dụng', '- Tiếp nhận thông tin tuyển dụng theo tuần, tháng của công ty, - Truyền thông tin tuyển dụng, tạo nguồn ứng viên theo mô tả công việc, - Gửi CV & nhập liệu data theo mẫu, - Hỗ trợ giải đáp ứng viên theo nội dung JD/các câu hỏi phát sinh cần hỗ trợ thông tin từ NV Tuyển dụng, - Nhận thông tin về kết quả công việc hàng tháng.', '- Ứng viên có kinh nghiệm trong lĩnh vực tuyển dụng - Ứng viên có kinh nghiệm Headhunt là lợi thế - Ứng viên có thời gian rảnh rồi muốn làm CTV để có thểm thu nhập và kinh nghiệm tuyển dụng (Làm việc tại nhà, không đến công ty) - Sinh viên năm 3,4 ngành nhân sự, hoặc các khối ngành khác đang có nhu cầu làm việc trong lĩnh vực tuyển dụng - Ưu tiên ứng viên có kỹ năng soạn content và hình ảnh tuyển dụng (sẽ có bài tham khảo để định hướng)
Kỹ năng chuyên môn: [''Kỹ năng soạn content'', ''Kỹ năng hình ảnh tuyển dụng'']
Kỹ năng mềm: [''Giao tiếp'', ''Giải quyết vấn đề'']', 'FREELANCE', 'ONSITE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 5000000.00, '2.0 - 5.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Mức submit từ 150.000 đến 1.000.000 cho mỗi ứng viên thành công'', ''Thời gian thanh toán: Trong vòng 10 ngày kể từ ngày Ứng viên được giới thiệu Pass phỏng vấn và nhận thử việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (577, 2, 9, 'Thực Tập Sinh Nhân Sự', 'Thực tập sinh nhân sự sẽ được yêu cầu thực hiện nhiệm vụ của họ một cách lịch sự, an toàn và hiệu quả, theo các chính sách và quy trình của khách sạn, đảm bảo rằng một mức độ dịch vụ cao được duy trì. 1. Tuyển dụng: * Hỗ trợ quản lý các hoạt động trong tuyển dụng thông qua các kênh bên trong và bên ngoài (Facebook, LinkedIn, GRS ....) * Sàng lọc CV và phỏng vấn qua điện thoại * Lịch phỏng vấn chính 2. Đào tạo: * Chuẩn bị tài liệu đào tạo * Thiết lập một lớp đào tạo * Video và bản địa của bản địa hóa * Hồ sơ và báo cáo giờ đào tạo * Sắp xếp lịch đào tạo 3. Các hoạt động của Takecare: * Chuẩn bị bản tin hàng tháng * Thiết kế và trang trí phụ trách cho các sự kiện (bao gồm cả việc đăng trên phương tiện truyền thông xã hội) * Đóng góp ý tưởng cho mỗi sự kiện * Sinh nhật để chuẩn bị liên kết', 'No Experience Required Can start as soon as possible Able to work full-time Good communication skill in both Vietnamese and English Commit to work for at least 03 months
Kỹ năng chuyên môn: [''Microsoft Office (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Giao tiếp'', ''Kỹ năng tổ chức'', ''Quản lý thời gian'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''On-the-job training'', ''Internship Certificate'', ''Professional workplace with young, dynamic and awesome team members'', ''Duty meal & Uniform provided'', ''05 working days & 02 day-off per week'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (578, 3, 9, 'Thực Tập Sinh Trợ Lý Tiếng Trung', 'Hỗ trợ biên dịch, phiên dịch giấy tờ hồ sơ, chứng từ. Hỗ trợ nhân viên phòng ban trao đổi, chăm sóc khách hàng bằng Tiếng Trung. Hỗ trợ phòng trợ lý kinh doanh các công việc liên quan của phòng.', 'Sinh viên năm cuối đã hoàn thành chương trình học. Học lực KHÁ GIỎI. Không cần kinh nghiệm. Học ngành ngôn ngữ Trung hoặc tiếng Anh các trường CĐ, ĐH hoặc có tiếng Trung cơ bản, học các ngành khác có liên quan. Nhanh nhẹn, độc lập, thái độ tốt.
Kỹ năng chuyên môn: [''Tiếng Trung (nghe, nói, đọc, viết)'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Độc lập'', ''Thái độ tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 làm từ 08h00 đến 12h00', '[''Được hỗ trợ chi phí thực tập'', ''Được cấp đầy đủ trang thiết bị để làm việc'', ''Được hỗ trợ dấu mộc báo cáo sau 2/3 thời gian thực tập'', ''Được đào tạo chuyên môn lý thuyết + thực hành'', ''Được làm việc trong môi trường chuyên nghiệp'', ''Cơ hội gắn bó cùng công ty sau thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (579, 7, 9, 'Thực Tập Sinh Đào Tạo', 'Triển khai các hoạt động đào tạo cho khối Vận hành theo yêu cầu (Thiết kế thư mời, thông báo mời học, chuẩn bị CCDC đào tạo, thanh toán, báo cáo, truyền thông...). Trực tiếp đứng lớp đào tạo theo yêu cầu đối với khối vận hành gồm: Kiến thức sản phẩm, Đào tạo Sơ chế - Pha chế... Tham gia tinh chỉnh các tài liệu đào tạo trong phạm vi được yêu cầu. Tham gia và phối hợp chuyển đổi tài liệu đào tạo sang E-Learning (Quay video, cắt ghép chỉnh sửa video theo yêu cầu). Vận hành trực tiếp vai trò nhân viên tại cửa hàng để thành thạo nghiệp vụ và có trải nghiệm thực tế. Công việc khác: Tham dự, tổ chức các hoạt động phát triển văn hoá và gắn kết nội bộ trong Công ty và nội bộ phòng ĐT&PT; Các công việc khác theo sự phân công của quản lý.', 'Sinh viên năm cuối hoặc đã tốt nghiệp Đại học QTKD, Quản Trị Nguồn Nhân lực, Giáo dục, các chuyên ngành khác có liên quan. Tính cách: Trung thực, công tâm, quyết đoán, nhiệt tình, tinh thần trách nhiệm cao, chịu được áp lực công việc. Tư duy tích cực, sáng tạo và có khả năng giải quyết vấn đề. Kinh nghiệm hoạt động đoàn hội tích cực (Trong ban điều hành các CLB là một lợi thế). Ưu tiên kinh nghiệm phục vụ > 6 tháng trong lĩnh vực dịch vụ, đồ uống, đồ ăn... Kỹ năng giao tiếp, trình bày tốt. Khả năng học hỏi nhanh và thích nghi. Có khả năng làm việc với AI. Có khả năng sử dụng các phần mềm thiết kế ảnh/dựng video. Yêu cầu khác: Khoảng cách di chuyển từ nhà tới nơi làm việc: < 15km.
Kỹ năng chuyên môn: [''Sử dụng các phần mềm thiết kế ảnh/dựng video'', ''Có khả năng làm việc với AI'']
Kỹ năng mềm: [''Trung thực'', ''Công tâm'', ''Quyết đoán'', ''Nhiệt tình'', ''Tinh thần trách nhiệm cao'', ''Chịu được áp lực công việc'', ''Tư duy tích cực'', ''Sáng tạo'', ''Khả năng giải quyết vấn đề'', ''Kỹ năng giao tiếp'', ''Trình bày tốt'', ''Khả năng học hỏi nhanh'', ''Thích nghi'']', 'INTERNSHIP', 'ONSITE', 'cầu giấy', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Từ thứ 2 – thứ 6: 8h00 – 17h00. Thứ 7: 8h00 – 12h00', '[''Được cung cấp đầy đủ công cụ và nguồn lực làm việc'', ''Được đóng dấu thực tập'', ''Được tham gia các khóa đào tạo nâng cao kỹ năng'', ''Môi trường làm việc năng động, sáng tạo'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (580, 8, 9, 'Thực Tập Sinh Nhân Sự', 'Tìm kiếm nguồn ứng viên tiềm năng. Tiếp nhận các nhu cầu tuyển dụng, lên kế hoạch tuyển dụng. Soạn thảo thông báo tuyển dụng nội bộ và nội dung đăng tuyển trên các kênh tuyển dụng, tiến hành đăng tuyển. Lọc hồ sơ, tổng hợp kết quả phỏng vấn và thông báo kết quả phỏng vấn.', 'Có laptop cá nhân. Ưu tiên các bạn làm full time. Có khả năng làm việc độc lập và kỹ năng làm việc nhóm. Có tinh thần trách nhiệm cao, cầu tiến, ham học hỏi và phát triển bản thân. Có thái độ tích cực, linh hoạt trong công việc. Có khả năng phỏng vấn là một lợi thế.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng phỏng vấn'', ''Kỹ năng tuyển dụng'']
Kỹ năng mềm: [''Kỹ năng làm việc nhóm'', ''Tinh thần trách nhiệm cao'', ''Cầu tiến'', ''Ham học hỏi'', ''Thái độ tích cực'', ''Linh hoạt trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Hỗ trợ các bạn TTS đầy đủ về các báo cáo thực tập: dấu mộc, số liệu'', ''Thưởng hoạt động theo memo hàng tháng'', ''Cơ chế thăng tiến rõ ràng'', ''Môi trường làm việc năng động, tự do, hiện đại và thỏa sức sáng tạo'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (581, 9, 9, 'Thực Tập Sinh Tuyển Dụng Nhân Sự', '1. Tuyển dụng: - Hỗ trợ tuyển dụng theo yêu cầu của quản lý trực tiếp. - Hỗ trợ sàng lọc CV, liên hệ hẹn phỏng vấn và hỗ trợ CV cho team. - Hướng dẫn, hỗ trợ ứng viên đến tham gia phỏng vấn và nhận việc. - Chịu trách nhiệm trong việc kết nối/follow ứng viên: trả lời tin nhắn, comment, hướng dẫn ứng tuyển cho ứng viên. 2. Xây dựng thương hiệu tuyển dụng: - Hỗ trợ xây dựng Fanpage/website phục vụ cho công việc: chỉnh sửa hình ảnh cơ bản, content, đăng bài và các hoạt động khác. - Tham gia các hoạt động khác theo yêu cầu của quản lý trực tiếp.', 'Sinh viên năm cuối không vướng bận lịch học hoặc vừa tốt nghiệp cao đẳng/ đại học các ngành học liên quan. Ưu tiên những bạn mong muốn gắn bó, phát triển lâu dài với công việc tuyển dụng và công ty. Tiếng Anh đọc hiểu tài liệu và viết tốt. Giao tiếp tốt, hoạt bát, nhanh nhẹn. Có khả năng chịu áp lực công việc. Có niềm yêu thích công việc tuyển dụng và làm việc với con người. Kỹ năng vi tính văn phòng Google Drive, Google Sheet, Google Doc. Chịu khó và cầu tiến, sẵn sàng học cái mới. Thời gian thực tập: tối thiểu 4 tháng full time.
Kỹ năng chuyên môn: [''Kỹ năng vi tính văn phòng Google Drive'', ''Google Sheet'', ''Google Doc'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Hoạt bát'', ''Nhanh nhẹn'', ''Chịu áp lực công việc'', ''Có niềm yêu thích công việc tuyển dụng và làm việc với con người'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 06:00)', '[''Nghỉ thứ 7 & Chủ nhật hàng tuần'', ''Được làm việc tại nhà 1-2 ngày/ tuần'', ''Được đào tạo sử dụng các công cụ tuyển dụng'', ''Được học và sử dụng GPT, Canva, Capcut Pro phục vụ công việc'', ''Môi trường trẻ, cởi mở và linh động'', ''Cơ hội được làm việc và đào tạo trực tiếp bởi chuyên gia tư vấn tuyển dụng nhân sự dày dạn kinh nghiệm thực chiến trong lĩnh vực nhân sự các tập đoàn đa quốc gia cho các vị trí tuyển dụng cụ thể'', ''Lộ trình thăng tiến lên nhân viên chính thức và chuyên viên chuyên nghiệp cho sinh viên năm cuối có định hướng làm chuyên môn Tuyển Dụng sau khi tốt nghiệp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (582, 10, 9, 'Nhân Viên Sale/Admin', '• Tư vấn & giải đáp thông tin sản phẩm • Xử lý & theo dõi đơn hàng • Chăm sóc khách hàng & duy trì mối quan hệ • Nghiên cứu thị trường & đề xuất phát triển • Quản lý Fanpage, trả lời tin nhắn, bình luận khách hàng • Phối hợp phòng marketing đề xuất ý tưởng khuyến mãi, minigame, hoạt động tăng tương tác. • Hỗ trợ đăng bài và phối hợp với team marketing khi cần thiết.', '• Siêng năng, chăm chỉ, có tinh thần học hỏi • Yêu thích bánh ngọt, có gu thẩm mỹ là một lợi thế • Giao tiếp tốt, thân thiện với khách hàng • Có khả năng tư vấn, chốt đơn qua tin nhắn hoặc tại quầy • Kiên nhẫn, linh hoạt trong xử lý tình huống • Biết sử dụng cơ bản Facebook, Zalo, Google Sheet (nếu làm online) • Ưu tiên có kinh nghiệm bán hàng tiệm bánh, chăm sóc khách hàng hoặc từng làm trong ngành F&B
Kỹ năng chuyên môn: [''Sử dụng cơ bản Facebook'', ''Zalo'', ''Google Sheet'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Thân thiện với khách hàng'', ''Kiên nhẫn'', ''Linh hoạt trong xử lý tình huống'']', 'FREELANCE', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'FIXED_PROJECT', 20000000.00, '14.0 - 20.0 triệu', '4-6 tiếng offline tại cửa hàng, linh động chốt đơn online tại nhà', '[''Lương cứng + hoa hồng'', ''Đào tạo miễn phí'', ''Môi trường làm việc trẻ trung, năng động'', ''Lộ trình tăng thu nhập'', ''Tuần off 1 ngày linh động'', ''Thưởng tháng lương 13'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (583, 2, 9, 'Thực Tập Sinh Tuyển Dụng', '• Hỗ trợ đăng tin tuyển dụng, sàng lọc hồ sơ ứng viên. • Gọi điện mời phỏng vấn, xác nhận lịch hẹn với ứng viên. • Hỗ trợ tổ chức các buổi phỏng vấn, kiểm tra, tiếp nhận hồ sơ và thực hiện quy trình hướng dẫn nhân viên mới. • Cập nhật và quản lý dữ liệu ứng viên trên hệ thống. • Hỗ trợ đăng bài viết truyền thông tuyển dụng, xây dựng nội dung fanpage. • Tham gia các buổi họp nhóm, đóng góp ý tưởng nâng cao hiệu quả tuyển dụng. • Thực hiện các nhiệm vụ khác theo sự phân công của quản lý.', '• Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp các ngành Quản trị nhân sự, Kinh tế, Quản trị kinh doanh hoặc lĩnh vực liên quan. • Có kỹ năng giao tiếp tốt, nhanh nhẹn, cầu tiến. • Chủ động học hỏi, có khả năng làm việc nhóm. • Biết sử dụng tin học văn phòng cơ bản (Word, Excel). • Thời gian thực tập bắt buộc: Thực tập sinh bắt buộc có mặt tại công ty lúc 8h sáng (từ thứ 2 đến thứ 6) để điểm danh và đảm bảo thời gian làm việc tối thiểu 2 tiếng/ngày. • Tham gia đầy đủ 03 ngày đào tạo định hướng trước khi bắt đầu công việc.
Kỹ năng chuyên môn: [''Tin học văn phòng cơ bản (Word, Excel)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Nhanh nhẹn'', ''Cầu tiến'', ''Chủ động học hỏi'', ''Có khả năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 14:00)', '[''Được đào tạo, hướng dẫn thực tế nghiệp vụ tuyển dụng'', ''Cơ hội thực hành và phát triển kỹ năng nghề nghiệp'', ''Hỗ trợ dấu mộc sau 45 ngày làm việc cho các thực tập sinh có thành tích tốt'', ''Có cơ hội trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (584, 3, 9, 'Trưởng Phòng Hành Chính', 'Tham mưu cho Ban Giám đốc về công tác hành chính của Công ty. Tiếp nhận các yêu cầu công việc liên quan đến công tác hành chính. Chịu trách nhiệm về công tác hành chính (Văn thư lưu trữ, hành chính tổng hợp, lễ tân, tài sản văn phòng Công ty, công tác vệ sinh tại văn phòng, các sự kiện Công ty,…) tại văn phòng Công ty. Quản lý việc mua sắm/ thanh toán các chi phí văn phòng và thanh toán chi phí Điện/ Nước/ Điện thoại,...của Hệ thống Phòng khám. Điều phối công việc và các nhân sự thuộc phòng Hành chính đảm bảo công việc được vận hành xuyên suốt, hiệu quả. Quản lý các văn bản, hồ sơ pháp lý của Công ty theo quy định. Tham gia xây dựng, sửa đổi, bổ sung hệ thống văn bản, quy định của Công ty. Tổ chức quản lý công tác hành chính văn phòng và kiểm soát chi phí hoạt động hành chính. Quản lý, phân công nhiệm vụ, hướng dẫn cấp nhân viên. Hỗ trợ, soát xét và chịu trách nhiệm toàn bộ về chất lượng công việc Hành chính của Công ty. Thực hiện Báo cáo công việc theo quy định của Công ty. Thực hiện các công việc khác liên quan nhiệm vụ theo sự phân công của cấp Quản lý, Ban Giám đốc.', '1. Nữ, tuổi từ 30 - 40 2. Tốt nghiệp Đại học trở lên 3. Có kinh nghiệm từ 05 năm vị trí Trưởng phòng Hành chính 4. Kỹ năng giao tiếp, trình bày tốt 5. Khả năng quản lý, tố chức, sắp xếp, điều phối công việc, xử lý vấn đề phát sinh hiệu quả 6. Chủ động, nhiệt tình, tinh thần trách nhiệm cao trong việc, có thể làm việc ngoài giờ khi cần 7. Thái độ hoà nhã, nhiệt tình, trung thực
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Khả năng quản lý'', ''Tổ chức'', ''Sắp xếp'', ''Điều phối công việc'', ''Xử lý vấn đề'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ Hai đến Thứ Sáu: 8:00 - 17:00; Thứ Bảy: 8:00 - 12:00', '[''Hưởng đủ chế độ theo quy định pháp luật về quản lý lao động'', ''Lương tháng 13'', ''Khám sức khỏe định kỳ'', ''Company trip hằng năm'', ''Phụ cấp di chuyển (nếu có)'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (585, 7, 9, 'Thực Tập Sinh Sales Admin', 'Hỗ trợ việc chuẩn bị và làm hồ sơ dự án, hồ sơ đấu thầu dự án xây dựng nội thất. Theo dõi và cập nhật tiến độ dự án, hỗ trợ sắp xếp lịch họp với khách hàng. Soạn thảo các biểu mẫu, hợp đồng, thư từ, công văn… Sẽ được hướng dẫn trong quá trình thực tập và học việc.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các khối ngành Kinh tế, Quản trị, Nội thất, Xây dựng,... Giao tiếp tốt, cẩn thận, có trách nhiệm và chủ động trong công việc. Ham học hỏi và phát triển bản thân.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Cẩn thận'', ''Có trách nhiệm'', ''Chủ động trong công việc'', ''Ham học hỏi và phát triển bản thân'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '3.0 - 8.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 làm cách tuần', '[''Cơ hội trở thành nhân viên chính thức sau thời gian thực tập'', ''Có hỗ trợ phụ cấp (nếu làm việc full-time)'', ''Môi trường làm việc thoải mái, thân thiện và được hướng dẫn bởi mentor giỏi, chuyên nghiệp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (586, 8, 9, 'HR Intern (mua lại tài năng & thương hiệu nhà tuyển dụng)', 'Hỗ trợ hoạt động Tuyển dụng (Talent Acquisition): Đăng tin tuyển dụng trên các nền tảng (Facebook, LinkedIn, job site…). Lọc CV, sắp xếp lịch phỏng vấn và hỗ trợ liên hệ ứng viên. Tham gia tổ chức các buổi phỏng vấn hoặc test tuyển dụng. Hỗ trợ hoạt động Xây dựng Thương hiệu tuyển dụng (Employer Branding): Tham gia xây dựng nội dung tuyển dụng sáng tạo (hình ảnh, video, bài viết…). Thiết kế các ấn phẩm truyền thông nội bộ bằng Canva, CapCut... Góp ý và đề xuất ý tưởng content tuyển dụng trên các kênh mạng xã hội. Phối hợp tổ chức các chương trình truyền thông nội bộ, sự kiện nhân sự. Các công việc hành chính – nhân sự khác: Tham gia các hoạt động gắn kết, họp phòng ban, mini game nội bộ…', 'Là sinh viên năm 3 hoặc năm 4 chuyên ngành Quản trị Nhân lực, Kinh tế, Truyền thông, Quản trị Kinh doanh hoặc các ngành liên quan. Sử dụng tốt các công cụ thiết kế và dựng video cơ bản như Canva, CapCut,… Năng động, sáng tạo, có tinh thần học hỏi và chủ động trong công việc. Yêu thích công việc liên quan đến tuyển dụng, thương hiệu tuyển dụng và truyền thông nội bộ. Có kỹ năng giao tiếp, làm việc nhóm tốt và tinh thần trách nhiệm cao.
Kỹ năng chuyên môn: [''Canva'', ''CapCut'']
Kỹ năng mềm: [''Năng động'', ''Sáng tạo'', ''Có tinh thần học hỏi'', ''Chủ động trong công việc'', ''Kỹ năng giao tiếp'', ''Làm việc nhóm tốt'', ''Tinh thần trách nhiệm cao'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Phụ cấp thực tập hấp dẫn'', ''Được hướng dẫn và đào tạo trực tiếp bởi đội ngũ HR chuyên nghiệp'', ''Tham gia vào các chiến dịch tuyển dụng thực tế'', ''Môi trường làm việc trẻ trung, linh hoạt, năng động'', ''Xác nhận thực tập và hỗ trợ dấu mộc khi hoàn thành chương trình'', ''Cơ hội trở thành nhân viên chính thức sau thời gian thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (587, 9, 9, 'Thực Tập Sinh Nhân Sự', 'Hỗ trợ công việc nhân sự: - Hỗ trợ quy trình tuyển dụng, bao gồm đăng tin tuyển dụng, sàng lọc hồ sơ, sắp xếp lịch phỏng vấn và liên hệ với ứng viên - Hỗ trợ công việc truyền thông nội bộ Hỗ trợ hành chính - Hỗ trợ hành chính và các công việc liên quan Trách nhiệm khác: - Tuân thủ thời gian làm việc - Tuân thủ quy định của công ty - Mặc trang phục lịch sự hoặc đồng phục', 'Đang là sinh viên các trường Đại học Ưu tiên sinh viên chuyên ngành Quản trị nhân sự/ Quản trị kinh doanh Kỹ năng tin học văn phòng Sử dụng tiếng anh thành thạo
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng'']
Kỹ năng mềm: [''Sử dụng tiếng anh thành thạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ chi phí đăng kí gửi xe'', ''Chứng chỉ hoàn thành thực tập'', ''Tham gia các hoạt động team-building, hoạt động vì cộng đồng'', ''Môi trường làm việc lành mạnh, đồng nghiệp thân thiện'', ''Được tham gia training, workshop đào tạo kỹ năng chuyên môn'', ''Các quyền lợi khác theo quy định của công ty'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (588, 10, 9, 'Thực Tập Sinh Văn Thư', 'Là đầu mối hỗ trợ, cung cấp các dịch vụ hành chính cho CBNV, khách đến làm việc, quản lý và sử dụng con dấu pháp nhân của VPBank, quản lý văn bản đến/đi, ban hành văn bản và lưu trữ hồ sơ, đảm bảo cung cấp môi trường làm việc phù hợp cho Công ty.', '1. Sinh viên cao đẳng/ đại học các chuyên ngành văn thư lưu trữ 2. Kiến thức/ Chuyên môn Có Liên Quan ·Hành chính,lễ tân, văn thư; · Tin học văn phòng Hiểu biết về lĩnh vực hoạt động của Ngân hàng 3. Các Kỹ Năng/ Skills · Kỹ năng giao tiếp khéo léo; · Kỹ năng sắp xếp khoa học; · Kỹ năng quan sát; · Kỹ năng phát hiện và xử lý tình huống;
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp khéo léo'', ''Kỹ năng sắp xếp khoa học'', ''Kỹ năng quan sát'', ''Kỹ năng phát hiện và xử lý tình huống'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được đào tạo, hướng dẫn từ cán bộ quản lý và chuyên gia trong lĩnh vực Tài chính - Ngân hàng'', ''Được tiếp xúc với hệ thống vận hành chuyên nghiệp, chuẩn quốc tế'', ''Môi trường: Năng động, thân thiện, có nhiều cơ hội học đào tạo, học hỏi và phát triển'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (589, 2, 9, 'Cộng Tác Viên Scan', 'Cộng tác viên sẽ tham gia hỗ trợ các Đơn vị Kinh doanh trong công tác xử lý hồ sơ DVKH, hồ sơ thẻ với các nội dung công việc cụ thể như sau: Hỗ trợ kiểm kê, phân loại hồ sơ chứng từ. Thực hiện scan và đặt tên file theo quy ước. Đóng quyển, đóng thùng hồ sơ theo hướng dẫn. Phối hợp với cán bộ ĐVKD trong quá trình thực hiện. Các công việc hỗ trợ khác theo phân công của cán bộ phụ trách tại đơn vị.', 'Có thể làm việc toàn thời gian trong thời gian nêu trên: Cam kết làm việc nghiêm túc, đúng tiến độ, không bỏ ngang giữa chừng. Sử dụng thành thạo máy tính, máy scan (được đào tạo thêm khi nhận việc). Cẩn thận, tỉ mỉ, trung thực, có trách nhiệm cao trong công việc liên quan đến tài liệu nội bộ.
Kỹ năng chuyên môn: [''Sử dụng máy tính'', ''Sử dụng máy scan'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Trung thực'', ''Có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường làm việc năng động'', ''Chuyên nghiệp'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (590, 3, 9, 'Thực Tập Sinh Đào Tạo', 'Hỗ trợ và sắp xếp lịch làm việc của giáo viên nước ngoài và trợ giảng. Hỗ trợ lập kế hoạch học tập, thời khóa biểu cho học sinh; giám sát và báo cáo tình hình học tập của học viên theo tuần/tháng/khóa học. Hỗ trợ ôn bài cho học viên ngoài giờ lên lớp. Hỗ trợ theo dõi và cập nhật thường xuyên các thông tin của phụ huynh và học sinh lên hệ thống: Họ tên, tuổi, địa chỉ, học phí, thông tin phản hồi,... Hỗ trợ đăng ký các môn SAT, SSAT, TOEFL... Làm các công việc khác liên quan đến chuyên môn do trưởng phòng chỉ đạo.', 'Là sinh viên năm 3 – 4 theo học các ngành Kinh tế, quản trị nhân sự hoặc giáo dục. Là người cởi mở năng động, yêu thích và có định hướng phát triển trong mảng đào tạo. Tiếng anh tốt, IELTS 5.0 trở lên hoặc trình độ tương đương. Trung thực, ham học hỏi, nhiệt tình và trách nhiệm cao trong công việc.
Kỹ năng chuyên môn: [''Tiếng Anh tốt, IELTS 5.0 trở lên hoặc trình độ tương đương'']
Kỹ năng mềm: [''Cởi mở'', ''Năng động'', ''Trung thực'', ''Ham học hỏi'', ''Nhiệt tình'', ''Trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', 'Làm việc 6 ngày/tuần & 1 ngày nghỉ tự chọn. Lựa chọn theo ca 4 tiếng/ca: Ca sáng: 8h30 – 12h30. Ca chiều: 14h00 – 18h00. Ca tối: 17h00 – 21h00', '[''Môi trường làm việc trẻ trung, năng động'', ''Ăn nhẹ giữa giờ nghỉ giải lao'', ''Tham gia các khóa đào tạo nghiệp vụ'', ''Du lịch trong và ngoài nước'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (591, 7, 9, 'Nhân Viên Part-Time Hỗ Trợ Sales Phòng', 'Tư vấn, giải đáp thắc mắc của khách hàng qua zalo, fb...các trang mạng xã hội (không đi thị trường, không đi tiếp khách hàng, không cần telesales). Nhắn tin/trả lời/ tư vấn khi khách có nhu cầu tìm hiểu thông tin liên quan theo nguồn có sẵn. Tạo/ up bài/ video sản phẩm (Phòng trống, chung cư mi ni,.. theo danh sách có sẵn) lên mxh, zalo,... Làm việc tại văn phòng. Các công việc khác theo sự phân công của quản lý.', 'Ứng viên có khả năng giao tiếp tốt, có khả năng viết content tốt là một lợi thế. Tư duy nhanh - Siêng năng – Trung thực – Kiên trì. Không yêu cầu kinh nghiệm. Có laptop cá nhân. Có tinh thần trách nhiệm trong công việc.
Kỹ năng chuyên môn: [''Sử dụng laptop'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Tư duy nhanh'', ''Siêng năng'', ''Trung thực'', ''Kiên trì'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '5.0 triệu', 'Sáng từ 8h30-11h30, chiều từ 13h30-17h30 từ thứ 2 đến thứ 7', '[''Môi trường năng động sáng tạo'', ''Lương 25k/h cho học sinh, sinh viên'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (592, 8, 9, 'Thực Tập Sinh Đào Tạo', 'Hỗ trợ soạn thảo tài liệu đào tạo, slide. Vận hành chương trình đào tạo: gửi/reply email, tổ chức lớp đào tạo, phản hồi điểm đánh giá. Đăng tải nội dung các khóa học lên cổng đào tạo E-learning.', 'Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). Cẩn thận, tỷ mỉ, chi tiết trong công việc, chủ động, ham học hỏi. Làm việc tối thiểu 5 buổi/tuần (2.5 buổi fulltime), bắt buộc lịch cố định sáng thứ 2 và 5.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỷ mỉ'', ''Chi tiết trong công việc'', ''Chủ động'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được đào tạo, hướng dẫn công việc và tham gia các lớp đào tạo nội bộ miễn phí'', ''Được tham gia các hoạt động gắn kết nội bộ của công ty'', ''Cơ hội học hỏi, tích lũy kinh nghiệm thực tế trong mảng đào tạo – phát triển'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (593, 9, 9, 'Điều hành tài khoản Junior (Bán thời gian)', 'Chăm sóc khách hàng, tư vấn và giải đáp thắc mắc. Tiếp nhận, xử lý đơn hàng, theo dõi, cập nhật tiến độ đơn hàng, đảm bảo đúng tiến độ và chất lượng. Thực hiện các nhiệm vụ khác trong chuyên môn khi được giao.', 'Có Laptop cá nhân. Sinh viên đang theo học các ngành Marketing, Kinh doanh, Truyền thông. Có kỹ năng giao tiếp, cẩn thận. Năng động, chủ động, ham học hỏi. Đăng ký làm việc tối thiểu 5 buổi/ tuần.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'']
Kỹ năng mềm: [''Cẩn thận'', ''Năng động'', ''Chủ động'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00), Thứ 7 (từ 08:30 đến 12:30)', '[''Thu nhập: 3-4 triệu/ tháng'', ''Học hỏi kinh nghiệm làm việc thực tế tại Agency Marketing'', ''Đa dạng khách hàng, đối tác trong - ngoài nước'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (594, 10, 9, 'Nhân Viên Admin Kinh Doanh (Thời Vụ 6 Tháng)', 'Thực hiện và hỗ trợ các công việc liên quan đến hoạt động thanh toán của phòng Kinh doanh/Marketing. Thực hiện các thủ tục, hợp đồng, giấy tờ cho Nhà cung cấp/Khách hàng theo định kỳ và phát sinh. Công việc thanh toán phòng Kinh doanh/Marketing: Thực hiện và hỗ trợ các công việc liên quan đến hoạt động thanh toán của phòng Kinh doanh/Marketing. Công việc tổ chức Hội nghị Hội thảo của phòng Marketing. Tìm kiếm địa điểm, dịch vụ theo yêu cầu. Thực hiện các công tác hậu cần, chuẩn bị cho sự kiện. Thực hiện các Công việc khác theo phân công của Quản lý.', 'Trình độ: Cao Đẳng trở lên. Kinh nghiệm: Ưu tiên kinh nghiệm làm việc vị trí tương đương là một lợi thế. Kỹ năng: Thành thạo tin học văn phòng (Word, Excel). Có khả năng tổ chức và sắp xếp công việc tốt. Cẩn thận, trách nhiệm, Chăm chỉ, hòa đồng, có tinh thần hợp tác.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng (Word, Excel)'']
Kỹ năng mềm: [''Có khả năng tổ chức và sắp xếp công việc tốt'', ''Cẩn thận'', ''Trách nhiệm'', ''Chăm chỉ'', ''Hòa đồng'', ''Có tinh thần hợp tác'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00), Thời gian làm việc linh hoạt', '[''Được đóng BHXH theo quy định hiện hành của Luật Lao động'', ''Ăn trưa miễn phí tại Công ty'', ''Được tham gia các khóa đào tạo kiến thức chuyên môn và kỹ năng mềm'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (595, 2, 9, 'HRBP Intern', '1. Tuyển dụng (80%) - Áp phích tuyển dụng thiết kế và viết nội dung đăng công việc để xuất bản trên các nền tảng truyền thông xã hội và trang web việc làm, nhằm thu hút các ứng viên phù hợp cho các vị trí được giao. - Chủ động tiếp cận với các ứng viên tiềm năng để giới thiệu các cơ hội việc làm, làm rõ các yêu cầu công việc và tiến hành sàng lọc ban đầu để đánh giá sự phù hợp. - Phối hợp lịch phỏng vấn và cung cấp hỗ trợ hậu cần cho các cuộc phỏng vấn với các bộ phận liên quan. - Thực hiện các nhiệm vụ liên quan đến tuyển dụng khác theo sự phân công của người quản lý. 2. Hỗ trợ thương hiệu truyền thông nội bộ và sử dụng lao động (20%) - Tham gia vào ý tưởng và tạo nội dung cho thương hiệu nhà tuyển dụng trên các nền tảng như LinkedIn và Facebook. - Xu hướng nội dung nghiên cứu hấp dẫn khán giả trẻ để tăng cường phạm vi tiếp cận và tham gia vào trang web nghề nghiệp của công ty và sự tham gia tuyển dụng. - Hỗ trợ tổ chức các sự kiện nội bộ.', 'Education: Final-year student or recent graduate in Human Resources, Business, Marketing, Communication, or related fields. Experience: No prior experience is required, but having experience in HR-related tasks is a plus. Competencies: Continuous learning, Effective communication, Systematic thinking. Skills: Proficiency in Google Workspace (Docs, Sheets, Forms, Gmail...) or Microsoft Office. Basic design skills (e.g., Canva or Photoshop). Personal Traits/Attitude: Energetic, goal-driven, and hands-on, Extroverted, Hard-working.
Kỹ năng chuyên môn: [''Proficiency in Google Workspace (Docs, Sheets, Forms, Gmail...)'', ''Microsoft Office'', ''Basic design skills (e.g., Canva or Photoshop)'']
Kỹ năng mềm: [''Effective communication'', ''Continuous learning'', ''Systematic thinking'', ''Energetic'', ''Goal-driven'', ''Hands-on'', ''Extroverted'', ''Hard-working'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Minimum of 24 hours per week, from Monday to Friday. Morning shift: 8:30 AM – 12:30 PM, Afternoon shift: 1:45 PM – 5:45 PM', '[''Monthly allowance: internship allowance based on working hours (around 3-5 mil/ month)'', ''Learning & Development opportunities: hands-on training in a professional environment'', ''Full-time opportunity for high-performing interns'', ''Flexible working hours'', ''Recommendation letter upon successful completion of the internship'', ''Young and dynamic work environment'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (596, 3, 9, 'Nhân Viên HR Parttime', 'Tuyển dụng, tìm kiếm ứng viên phù hợp với nhu cầu của công ty. Đăng tin tuyển dụng trên các kênh online và offline. Sàng lọc hồ sơ, phỏng vấn ứng viên. Thực hiện các bài kiểm tra năng lực, đánh giá ứng viên. Làm việc với các bộ phận khác để đảm bảo quá trình tuyển dụng diễn ra suôn sẻ. Cập nhật và quản lý thông tin ứng viên. Thực hiện các thủ tục hành chính liên quan đến tuyển dụng. Báo cáo kết quả tuyển dụng cho cấp trên. Xây dựng và duy trì mối quan hệ tốt với các trường đại học, các trung tâm đào tạo. Tham gia xây dựng kế hoạch tuyển dụng của công ty.', 'Không yêu cầu kinh nghiệm. Tốt nghiệp Cao đẳng/Đại học chuyên ngành Quản trị nhân lực, Tâm lý học hoặc các chuyên ngành liên quan. Có kỹ năng giao tiếp tốt, khả năng thuyết phục. Có kỹ năng làm việc nhóm, tinh thần trách nhiệm cao. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). Khả năng tổ chức, sắp xếp công việc hiệu quả. Trung thực, năng động, nhiệt tình. Có khả năng làm việc độc lập và chịu được áp lực công việc. Khả năng sử dụng các mạng xã hội và các trang web tuyển dụng. Am hiểu về thị trường bất động sản là một lợi thế.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng thuyết phục'', ''Kỹ năng làm việc nhóm'', ''Tinh thần trách nhiệm cao'', ''Khả năng tổ chức'', ''Sắp xếp công việc hiệu quả'', ''Trung thực'', ''Năng động'', ''Nhiệt tình'', ''Khả năng làm việc độc lập'', ''Chịu được áp lực công việc'', ''Khả năng sử dụng các mạng xã hội và các trang web tuyển dụng'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '2.5 - 6.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30), Thứ 7 làm đến 15h30', '[''Đóng bảo hiểm xã hội'', ''Bảo hiểm y tế'', ''Bảo hiểm thất nghiệp theo quy định của pháp luật'', ''Môi trường làm việc năng động, chuyên nghiệp, thân thiện'', ''Cơ hội thăng tiến và phát triển nghề nghiệp'', ''Tham gia các hoạt động tập thể, teambuilding'', ''Chế độ nghỉ phép năm, nghỉ lễ tết theo quy định'', ''Được đào tạo nghiệp vụ thường xuyên'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (597, 7, 9, 'Thực Tập Sinh Nhân Sự', 'Hỗ trợ công tác tuyển dụng, lọc hồ sơ ứng viên, liên lạc ứng viên, đặt lịch phỏng vấn, kiểm tra thông tin, hồ sơ ứng viên. Hỗ trợ các nhiệm vụ hành chính ở văn phòng, cập nhật, lưu trữ hồ sơ nhân viên, chuẩn bị tài liệu cho các chương trình đào tạo, hội nghị, danh sách nhân viên tham gia.', 'Sinh viên năm cuối theo học các chuyên ngành: Quản trị nguồn nhân lực, Quản trị kinh doanh hoặc các ngành có liên quan. Đam mê, yêu thích lĩnh vực Nhân sự. Có thể đọc, hiểu tiếng Anh. Siêng năng, cẩn thận, ham học hỏi. Giờ làm việc: 9:00 – 17:00, 5 ngày/tuần. Thời gian thực tập: ít nhất 3 tháng.
Kỹ năng mềm: [''Siêng năng'', ''Cẩn thận'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'tây ninh', 'Tây Ninh', 'MONTHLY', 4000000.00, '0.0 triệu', '9:00 – 17:00, 5 ngày/tuần', '[''Trợ cấp cơm trưa'', ''Hướng dẫn và tích lũy kinh nghiệm trong môi trường thực tế'', ''Cơ hội trở thành nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (598, 8, 9, 'Thực Tập Sinh Admin Partnership', 'Hỗ trợ làm hồ sơ nghiệm thu thanh toán cho khách hàng như: Hợp đồng, báo cáo, nghiệm thu, chứng từ cho khách hàng. Hỗ trợ xử lý hồ sơ nghiệm thu thanh toán cho đối tác như: Hợp đồng, báo cáo, nghiệm thu, chứng từ, đề nghị thanh toán... Gửi bản cứng các hồ sơ cho KH/đối tác/kế toán. Chủ động phối hợp các thành viên trong team để tối ưu công việc. Thực hiện các việc khác được giao bởi quản lý trực tiếp.', 'Là sinh viên năm cuối/đợi bằng các chuyên nghành Cao Đẳng, Đại Học tài chính & Marketing, truyền thông quảng cáo. Có khả năng quản trị dự án hợp đồng, các thủ tục giấy tờ. Sử dụng thành thạo các phần mềm: Microsof Office và các công cụ thiết kế cơ bản. Khả năng làm việc độc lập và tập thể tốt. Có khả năng làm việc dưới áp lực và trách nhiệm cao trong công việc; tính tỉ mỉ, cẩn thận. Có thể làm Partime, off tối đa 4 buổi/tuần.
Kỹ năng chuyên môn: [''Microsoft Office'', ''các công cụ thiết kế cơ bản'']
Kỹ năng mềm: [''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Chịu được áp lực công việc'', ''Tính tỉ mỉ'', ''Cẩn thận'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '1.5 - 2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30) và 1 buổi sáng Thứ 7 đầu tiên của tháng', '[''Trợ cấp thực tập 1.500.000 - 2.000.000/tháng'', ''Hỗ trợ chi phí gửi xe'', ''Hỗ trợ dấu mộc thực tập'', ''Được tham gia học hỏi & phát triển, hướng dẫn bởi những Mentor dày dạn kinh nghiệm'', ''Môi trường làm việc chuyên nghiệp, uy tín'', ''Cơ hội trở thành nhân viên chính thức sau quá trình thực tập nếu năng lực phù hợp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (599, 9, 9, 'Thực Tập Hỗ Trợ Kinh Doanh', 'Hỗ trợ thực hiện các công việc được giao từ Phòng Kinh doanh: hỗ trợ soạn thảo hợp đồng, báo giá, proposal, hồ sơ thầu,.. Hỗ trợ telesales và hỗ trợ tổ chức event tại Phòng Kinh doanh. Chi tiết sẽ trao đổi ở buổi phỏng vấn.', 'Sinh viên năm cuối hoặc sắp tốt nghiệp các chuyên ngành: Hành chính, QTKD, Tiếng Anh,... Trung thực, nhanh nhẹn và nhiệt tình với công việc. Khả năng giao tiếp tốt. Ưu tiên ứng viên có thể thực tập full time.
Kỹ năng mềm: [''Trung thực'', ''Nhanh nhẹn'', ''Nhiệt tình'', ''Khả năng giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được làm việc với các doanh nghiệp, tập đoàn trong và ngoài nước'', ''Được học hỏi, đào tạo và tham gia vào các dự án lớn'', ''Môi trường làm việc thân thiện, năng động'', ''Được xem xét tuyển chính thức sau thời gian đào tạo'', ''Tham gia các hoạt động văn hoá, sự kiện hấp dẫn'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (600, 10, 9, 'Thực Tập Sinh Tuyển Dụng', 'Tuyển dụng theo yêu cầu từng phòng ban. Lọc CV theo yêu cầu. Chốt và lên lịch phỏng vấn trên Lark. Các công việc khác theo yêu cầu cấp trên.', 'Nhanh nhẹn, hoạt bát. Không yêu cầu kinh nghiệm. Tinh thần trách nhiệm. Trung thực trong công việc. Ưu tiên sinh viên năm cuối về quản trị nhân lực hoặc các ngành liên quan.
Kỹ năng mềm: [''Nhanh nhẹn'', ''Hoạt bát'', ''Tinh thần trách nhiệm'', ''Trung thực trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '1.9 - 2.0 triệu', 'Tối đa 4h/ngày, từ T2-T6 (T7 được WFH)', '[''Hỗ trợ 2.000.000đ/tháng'', ''Đóng mộc thực tập đầy đủ'', ''Rèn được các kĩ năng cần có của 1 người nhân sự'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (601, 2, 9, 'Thực Tập Sinh Tuyển Dụng', 'Thực hiện công tác truyền thông tuyển dụng, tìm kiếm ứng viên theo yêu cầu tuyển dụng của công ty; Sàng lọc hồ sơ, tổ chức phỏng vấn, liên hệ ứng viên, sắp xếp lịch phỏng vấn, theo dõi, đánh giá ứng viên; Hỗ trợ quản lý data dữ liệu ứng viên và nhập thông tin ứng viên vào hệ thống; Hỗ trợ tổ chức các sự kiện của công ty Online và Offline.', 'Sinh viên năm 4 các chuyên ngành Quản trị nguồn nhân lực hoặc các chuyên ngành khác có liên quan, có định hướng phát triển trong lĩnh vực nhân sự; Kỹ tính, cẩn thận và tư duy logic tốt; Chăm chỉ, nhanh nhẹn, chủ động trong công việc; Thành thạo kỹ năng tin học văn phòng (Word và Excel); Ưu tiên các bạn thực tập full time từ 3 tháng trở lên.
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng (Word và Excel)'']
Kỹ năng mềm: [''Kỹ tính'', ''Cẩn thận'', ''Tư duy logic tốt'', ''Chăm chỉ'', ''Nhanh nhẹn'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Cơ hội trở thành thành viên chính thức của Công ty sau quá trình thực tập'', ''Được training phát triển kỹ năng trong công việc và bản thân'', ''Hỗ trợ mộc thực tập (mộc tròn)'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (602, 3, 9, 'Sales Admin Thời Vụ', 'Theo dõi tình trạng nhập – xuất – tồn của hàng hóa, vật tư, các nguyên liệu phục vụ cho việc sản xuất. Bạn sẽ phải theo dõi lịch trình của đơn hàng, lập các biên bản giao – nhận chính xác đối với từng đơn. Tiếp nhận mọi ý kiến đóng góp từ đại lý, khách hàng, v.v sau đó sẽ gửi các thông tin lên cấp trên để kiểm tra và thực hiện các báo cáo theo yêu cầu. Theo dõi tỷ lệ hoàn thành chỉ tiêu của các nhân viên. Từ đó, bạn sẽ thúc đẩy nhân viên bám sát với tiến độ để đạt được tối đa chỉ tiêu doanh số. Tham gia vào việc hỗ trợ và soạn thảo các văn bản, giấy tờ nội bộ liên quan đến công việc, cuộc họp, hoạt động của phòng kinh doanh. Nắm rõ thông tin của khách hàng, phân loại khách hàng như khách thường, khách VIP, khách VIP 1, v.v. Để từ đó, bạn đưa ra các chương trình tri ân, chính sách chăm sóc phù hợp. Cập nhật số liệu bán hàng và tổng hợp để lập báo cáo theo ngày, tuần, tháng, quý, năm. Các thông tin này sẽ giúp bạn biết được nhân viên nào có thành tích nổi trội và đề xuất khen thưởng.', 'Tốt nghiệp Cao Đẳng/Đại Học. Vi tính văn phòng. Kỹ tính, biết cách sắp xếp công việc.
Kỹ năng chuyên môn: [''Vi tính văn phòng'']
Kỹ năng mềm: [''Kỹ tính'', ''Biết cách sắp xếp công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Thưởng tháng 13, 14'', ''2 tháng thử việc hưởng 100% lương, bảo hiểm'', ''Bảo hiểm tư nhân (24/7) - Free'', ''Đóng BHXH trên mức thực lãnh'', ''Company trip hàng năm'', ''Khám sức khỏe hàng năm'', ''Cước điện thoại'', ''Được cấp Máy tính'', ''Bảo hiểm sức khỏe'', ''Bảo hiểm xã hội'', ''Bảo hiểm full lương'', ''Khám sức khỏe định kỳ'', ''Team building'', ''Du lịch hàng năm'', ''Phụ cấp thâm niên'', ''Thưởng hiệu quả làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (603, 7, 9, 'Thực Tập Sinh Sale Admin', 'Nhận điện thoại tư vấn, báo giá, giới thiệu các sản phẩm của công ty tới khách hàng. Phụ trách tiếp nhận, xử lý thông tin đặt hàng, hợp đồng bán hàng của khách hàng với bộ phận kinh doanh. Lên đơn hàng, làm việc với hãng cung cấp về P.O và bộ phận logistic về nhập khẩu hàng hóa. Chuẩn bị các giấy tờ giao hàng, làm việc với kế toán chuẩn bị hóa đơn cho khách hàng. Ghi nhận doanh thu, công nợ của khách hàng. Nhắc nhở bộ phận kinh doanh thu hồi công nợ khi đến hạn. Tham gia, hỗ trợ trong công tác soạn thảo văn bản theo sự phân công của các cấp quản lý. Thực hiện các nhiệm vụ khác theo sự phân công của cấp trên. Hỗ trợ các chương trình, sự kiện của công ty.', 'Sinh viên năm 3-4 hoặc vừa tốt nghiệp Đại học chuyên ngành kinh tế, ngoại ngữ, kỹ thuật. Thành thạo Excel, Word, tin học văn phòng. Năng động, nhanh nhẹn, kiên trì, trung thực, có trách nhiệm cao trong công việc. Giọng nói dễ nghe, không nói ngọng, nói lắp hay tiếng địa phương. Khả năng giao tiếp và xử lý tình huống tốt. Nhiệt tình, mong muốn làm việc gắn bó lâu dài.
Kỹ năng chuyên môn: [''Thành thạo Excel'', ''Thành thạo Word'', ''Tin học văn phòng'']
Kỹ năng mềm: [''Năng động'', ''Nhanh nhẹn'', ''Kiên trì'', ''Trung thực'', ''Có trách nhiệm cao trong công việc'', ''Khả năng giao tiếp và xử lý tình huống tốt'', ''Nhiệt tình'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Làm việc trong môi trường năng động, chuyên nghiệp, có nhiều cơ hội thăng tiến'', ''Được hưởng các chính sách phúc lợi theo quy định của công ty'', ''Có hỗ trợ lương thực tập'', ''Hỗ trợ dấu mộc thực tập'', ''Được đào tạo, nâng cao nghiệp vụ thường xuyên'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (604, 8, 9, 'Thực Tập Sinh Nhân Sự', '- Lên kế hoạch định và mô tả công việc cho các vị trí cần tuyển - Liên hệ phỏng vấn ứng viên và chuẩn bị hồ sơ ứng viên - Quản lý nhân sự trong hệ thống và thông báo các lịch đào tạo - Thực hiện các quy trình onboarding và outboarding nhân sự - Chăm sóc ứng viên và nhân sự - Chủ động tìm kiếm ứng viên cho các vị trí cần tuyển', '- Muốn theo đuổi ngành nhân sự lâu dài - Ưu tiên những bạn học ngành nhân sự, quản lý nhân sự, … - Sức khỏe tốt, trung thực, cam kết - Khả năng quản trị cảm xúc tốt, kỹ năng giao tiếp, thuyết phục và xử lý vấn đề linh hoạt - Tuổi : 2k4 - 2k6 - Có Laptop cá nhân
Kỹ năng chuyên môn: [''Microsoft Office (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Khả năng quản trị cảm xúc tốt'', ''Kỹ năng giao tiếp'', ''Thuyết phục'', ''Xử lý vấn đề linh hoạt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '1.0 - 3.5 triệu', 'Tối thiểu 4h/ngày', '[''Được đào tạo kỹ năng chuyên môn và kỹ năng mềm'', ''Du lịch xa 2 lần/năm'', ''Teambuilding hàng tháng'', ''Thưởng hiệu quả làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (605, 9, 9, 'Thực Tập-Hành Chính (English/Chinese Speaking)', 'THỰC TẬP SINH PHÒNG HÀNH CHÍNH Mô tả công việc 1- Hành chính (40%) - Tổ chức và quản lý các nhiệm vụ hành chính văn phòng. - Thực hiện công tác nhập liệu dữ liệu, nhập thông tin vào hệ thống theo yêu cầu - Thực hiện công tác hỗ trợ thư đến, thư đi - Thực hiện việc giao nhận hàng hoá, chuyển phát nhanh - Xử lý các công việc hành chính khác (trực lễ tân, văn phòng phẩm, cơ sở vật chất, cà phê, nước uống...). - Hỗ trợ Truyền thông Nội bộ trong việc lập kế hoạch và tổ chức các buổi tiệc, sinh nhật, chuyến du lịch công ty, hoạt động xây dựng đội ngũ và các sự kiện khác. - Xử lý chi phí văn phòng để thanh toán (nếu có yêu cầu) 2-Hỗ trợ bộ phận thu mua (40%) - Khảo sát thu thập thông tin - Hỗ trợ nhập dữ liệu - Các công việc khác được yêu cầu 3-Nhiệm vụ Khác (20%): Theo phân công của Trưởng Nhóm', 'Yêu cầu công việc: Sinh viên năm 2 hoặc năm 3, không yêu cầu kinh nghiệm. Tin học văn phòng cơ bản. Kỹ năng giao tiếp và tư duy logic tốt, siêng năng, chủ động. Cẩn thận tỉ mỉ. Có tinh thần trách nhiệm.
Kỹ năng chuyên môn: [''Tin học văn phòng cơ bản'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Tư duy logic'', ''Siêng năng'', ''Chủ động'', ''Cẩn thận'', ''Tỉ mỉ'', ''Có tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Part-time (ca sáng: 8h30 - 12h00, ca chiều: 13h00 - 17h30)', '[''Cung cấp giấy xác nhận thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (606, 10, 9, 'Nhân Viên Nhân Sự (Hợp Đồng 06 Tháng)', '1/ Quản lý tuyển dụng - Tuyển dụng cho các vị trí theo yêu cầu của quản lý - Thực hiện các hoạt động tuyển dụng: Sàng lọc, phỏng vấn, tiếp nhận… - Quản lý dữ liệu ứng viên để khai thác cho các vị trí trong tương lai - Phỏng vấn thôi việc - Hoàn thành các báo cáo tuyển dụng 2/ Đào tạo - Hỗ trợ và phối hợp các hoạt động đào tạo - Chịu trách nhiệm đào tạo nhân viên mới theo quy định - Trách nhiệm về đào tạo công việc cho nhân viên mới 3/ Quản lý dữ liệu chấm công, tính lương - Hỗ trợ chấm công, tính lương - Check và sửa lỗi cho các bộ phận liên quan 4/ Các công việc khác theo sự phân công', 'Cao đẳng Ưu tiên có kinh nghiệm liên quan đến bộ phận nhân sự. Chịu được áp lực cao. Có khả năng sử dụng máy tính, Microsoft office Chi tiết và có khả năng xử lý nhiều nhiệm vụ cùng lúc. Có thể làm việc theo ca và trong các ngày lễ.
Kỹ năng chuyên môn: [''Sử dụng máy tính'', ''Microsoft Office'']
Kỹ năng mềm: [''Chịu được áp lực cao'', ''Chi tiết'', ''Có khả năng xử lý nhiều nhiệm vụ cùng lúc'']', 'PART_TIME', 'ONSITE', 'hải phòng', 'Hải Phòng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), làm việc 6 ngày/tuần, 8h/ngày, xoay ca linh hoạt', '[''Môi trường làm việc chuyên nghiệp, năng động'', ''Cơ hội thăng tiến và phát triển nghề nghiệp'', ''Mức lương và chế độ phúc lợi cạnh tranh'', ''Tham gia đầy đủ chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo Luật lao động'', ''Chương trình đào tạo và phát triển năng lực'', ''Giảm giá khi mua sắm tại hệ thống siêu thị AEON'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (607, 2, 9, 'Thực Tập Sinh IT (Chuyên Mạng)', 'Hỗ trợ vận hành và giám sát hệ thống mạng nội bộ (LAN, WiFi) trong công ty. Tham gia cài đặt, cấu hình thiết bị mạng như router, switch, access point,... Xử lý các sự cố liên quan đến kết nối mạng, đường truyền và thiết bị IT cơ bản. Cài đặt phần mềm, hỗ trợ sửa lỗi máy tính, máy in, thiết bị văn phòng. Hỗ trợ kiểm kê, quản lý tài sản IT thuộc hệ thống của công ty. Phối hợp với bộ phận hành chính hỗ trợ kỹ thuật cho nhân sự nội bộ. Thực hiện các công việc khác theo phân công từ quản lý bộ phận.', 'Là sinh viên năm 3, năm cuối hoặc mới tốt nghiệp chuyên ngành CNTT, Mạng máy tính, Kỹ thuật phần cứng,... Nắm kiến thức cơ bản về mô hình mạng TCP/IP, cấu hình thiết bị mạng. Biết sử dụng và cài đặt hệ điều hành, phần mềm văn phòng, xử lý lỗi phần cứng cơ bản. Chủ động, trách nhiệm, có tinh thần học hỏi và cầu tiến. Ưu tiên có thể thực tập fulltime-partime tối thiểu 7b/tuần.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về mô hình mạng TCP/IP'', ''Cấu hình thiết bị mạng'']
Kỹ năng mềm: [''Chủ động'', ''Trách nhiệm'', ''Có tinh thần học hỏi và cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Nghỉ Trưa 12h-13h30, T7&CN: OFF', '[''Phụ cấp thực tập'', ''Hỗ trợ mộc báo cáo thực tập'', ''Đào tạo từ A-Z về kỹ năng kỹ thuật'', ''Có cơ hội lên chính thức nếu thể hiện tốt'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (608, 3, 9, 'Thực Tập Sinh IT (Có Phụ Cấp)', 'Hỗ trợ vận hành và giám sát hệ thống mạng nội bộ (LAN, WiFi) trong công ty. Tham gia cài đặt, cấu hình thiết bị mạng như router, switch, access point,... Xử lý các sự cố liên quan đến kết nối mạng, đường truyền và thiết bị IT cơ bản. Cài đặt phần mềm, hỗ trợ sửa lỗi máy tính, máy in, thiết bị văn phòng. Hỗ trợ kiểm kê, quản lý tài sản IT thuộc hệ thống của công ty. Phối hợp với bộ phận hành chính hỗ trợ kỹ thuật cho nhân sự nội bộ. Thực hiện các công việc khác theo phân công từ quản lý bộ phận.', 'Là sinh viên năm 3, năm cuối hoặc mới tốt nghiệp chuyên ngành CNTT, Mạng máy tính, Kỹ thuật phần cứng,... Nắm kiến thức cơ bản về mô hình mạng TCP/IP, cấu hình thiết bị mạng. Biết sử dụng và cài đặt hệ điều hành, phần mềm văn phòng, xử lý lỗi phần cứng cơ bản. Chủ động, trách nhiệm, có tinh thần học hỏi và cầu tiến. Ưu tiên có thể thực tập fulltime - parttime tối thiểu 7 buổi/tuần.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về mô hình mạng TCP/IP'', ''Cấu hình thiết bị mạng'', ''Sử dụng và cài đặt hệ điều hành'', ''Phần mềm văn phòng'', ''Xử lý lỗi phần cứng cơ bản'']
Kỹ năng mềm: [''Chủ động'', ''Trách nhiệm'', ''Có tinh thần học hỏi'', ''Cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), nghỉ trưa: 12h-13h30, T7&CN: Off', '[''Phụ cấp thực tập'', ''Hỗ trợ mộc báo cáo thực tập'', ''Đào tạo từ A-Z về kỹ năng kỹ thuật'', ''Cơ hội lên chính thức nếu thể hiện tốt'', ''Môi trường làm việc thân thiện'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (609, 7, 9, 'Thực Tập Sinh Nhân Sự', 'Hỗ trợ các hoạt động tuyển dụng của Khối Nhân sự. Hỗ trợ sắp xếp hồ sơ, giấy tờ. Hỗ trợ dịch thuật các văn bản. Các nhiệm vụ khác được giao.', 'Sinh viên năm 3 hoặc năm cuối các trường Đại học với chuyên ngành Quản lý nguồn nhân lực, Quản trị kinh doanh hoặc các ngành liên quan khác. Ưu tiên ứng viên có thể thực tập full-time với thời gian tối thiểu 3 tháng. Thành thạo tin học văn phòng. Kỹ năng giao tiếp tốt. Tiếng Anh tốt là một lợi thế. Thân thiện, cẩn thận, năng động. Có tinh thần trách nhiệm, sẵn sàng hoàn thành mọi nhiệm vụ được giao.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Thân thiện'', ''Cẩn thận'', ''Năng động'', ''Có tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 - 2.4 triệu', 'Full-time', '[''Hỗ trợ phụ cấp thực tập full-time: 2.000.000 VND/tháng và chi phí gửi xe: 400.000 VND/tháng.'', ''Tham gia các chương trình đào tạo của công ty (kỹ năng chuyên môn, kỹ năng giao tiếp).'', ''Được hỗ trợ đóng dấu mộc thực tập (nếu có).'', ''Có cơ hội tham gia Team building/ Đi chơi/ Hoạt động trong nhà/ Tiệc tùng/ Du lịch hàng năm với công ty.'', ''Môi trường năng động, chuyên nghiệp, cơ hội làm việc và học tập liên quan đến kiến thức đầu tư, trực tiếp từ các chuyên gia trong ngành chứng khoán.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (610, 8, 9, 'Thực Tập Sinh Nhân Sự', 'Cập nhập thông tin nhân sự vào hệ thống thông tin quản lý nhân sự chung của Tập đoàn. Quản lý hồ sơ lao động; Sắp xếp phân loại lưu trữ hồ sơ lao động; Tiếp nhận và giải đáp thắc mắc về toàn bộ các vấn đề liên quan đến chính sách, quy định pháp luật về công tác nhân sự bao gồm Nội quy lao động, Khen thưởng kỷ luật,… Được hướng dẫn soạn thảo các văn bản, quy định và hợp đồng. Thực hiện các công việc khác trong phần hành QHLĐ.', 'Tốt nghiệp Đại học trở lên các chuyên ngành: Quản trị nhân lực, Luật,… hoặc hoặc các chuyên ngành khác có liên quan. Có ít nhất 03 tháng kinh nghiệm tại vị trí tương đương. Ngoại hình ưa nhìn, khả năng giao tiếp, thuyết trình, đàm phán tốt. Nhiệt tình, thái độ làm việc chuyên nghiệp. Kỹ năng tin học văn phòng tốt, biết thống kê báo cáo dữ liệu. Có kinh nghiệm trong công tác công đoàn.
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng tốt'', ''Biết thống kê báo cáo dữ liệu'']
Kỹ năng mềm: [''Khả năng giao tiếp'', ''Thuyết trình'', ''Đàm phán'', ''Nhiệt tình'', ''Thái độ làm việc chuyên nghiệp'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '5.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được đánh giá lên nhân viên chính thức sau 3-6 tháng làm việc'', ''Phụ cấp theo quy định của Tập đoàn'', ''Làm việc trong môi trường năng động, chuyên nghiệp có nhiều cơ hội thăng tiến'', ''Cung cấp trang thiết bị đầy đủ để phục vụ công việc'', ''Được hưởng các chính sách phúc lợi theo quy định của công ty'', ''Được đào tạo, nâng cao nghiệp vụ thường xuyên'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (611, 9, 9, 'Chuyên Viên Nhân Sự', 'Công tác tuyển dụng và đào tạo nhân sự. Quản lý chấm công, thời gian làm việc của nhân viên theo nội quy. Tính lương cho đội ngũ kinh doanh, văn phòng. Báo tăng, giảm BHXH, chế độ ốm đau. Xử lý HĐLĐ, HĐTV theo đúng luật. Soạn thảo văn bản, quy chế liên quan đến nhân sự. Báo cáo dữ liệu lao động cho Giám đốc. Tham mưu, tư vấn cho Giám đốc về chế độ nhân sự liên quan.', 'Nam/Nữ, tuổi từ 25 - 35 tuổi. Tốt nghiệp Cao đẳng/Đại học. Có kinh nghiệm mảng nhân sự (C&B). Ưu tiên có ngoại ngữ Tiếng Trung. Nhanh nhẹn, trung thực trong giao tiếp và cẩn trọng trong xử lý công việc. Thành thạo các kỹ năng Tin học văn phòng.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Trung thực'', ''Cẩn trọng trong xử lý công việc'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00), Thứ 7 nghỉ cách tuần', '[''Đóng BHXH'', ''Chế độ nghỉ phép, nghỉ ốm đầy đủ'', ''Thưởng hiệu suất công việc'', ''Cơ hội học hỏi và phát triển kỹ năng trong môi trường chuyên nghiệp'', ''Tham gia các hoạt động team building, du lịch nghỉ mát hàng năm'', ''Được mua điện thoại Smartphone VIVO với giá ưu đãi'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (612, 10, 9, 'Thực Tập Sinh Hành Chính Văn Phòng', 'Hỗ trợ các công việc hành chính, lễ tân, văn thư. Soạn thảo, sắp xếp hồ sơ, giấy tờ. Hỗ trợ tổ chức các hoạt động nội bộ. Các công việc khác theo sự phân công của quản lý.', 'Sinh viên năm 4 hoặc đã ra trường các ngành liên quan. Nhiệt tình, cẩn thận, có tinh thần học hỏi. Thành thạo tin học văn phòng là một lợi thế.
Kỹ năng chuyên môn: [''Microsoft Office (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Nhiệt tình'', ''Cẩn thận'', ''Có tinh thần học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 : Từ 08h00 - 12h00', '[''Hỗ trợ lương thực tập'', ''Hỗ trợ dấu mộc thực tập'', ''Cơ hội lên làm chính thức'', ''Môi trường làm việc thân thiện, chuyên nghiệp'', ''Được training hướng dẫn và đào tạo bài bản'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (613, 2, 9, 'Thực Tập Sinh', 'Hỗ trợ triển khai quy trình tuyển dụng theo nhu cầu tuyển dụng của công ty. Thực hiện công tác tìm kiếm nguồn ứng viên, sàng lọc hồ sơ và sắp xếp lịch phỏng vấn tuyển dụng. Hỗ trợ quản lý các kênh tuyển dụng của công ty. Cập nhật dữ liệu thông tin ứng viên và báo cáo theo yêu cầu của cấp trên. Hỗ trợ thực hiện các công việc liên quan khác.', 'Yêu cầu: Đang học hoặc đã tốt nghiệp Cao đẳng, Đại học ngành Quản trị nguồn nhân lực và ngành khác có liên quan. Không yêu cầu kinh nghiệm. Ưu tiên ứng viên từng có kinh nghiệm liên hệ với các trường để tìm ứng viên tìm năng. Kỹ năng tin học văn phòng tốt (Word – Excel). Yêu thích, có định hướng lâu dài trong ngành Tuyển dụng. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng (Word, Excel)'']
Kỹ năng mềm: [''Yêu thích ngành Tuyển dụng'', ''Kỹ năng giao tiếp'', ''Kỹ năng sắp xếp công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 6 (08:30 - 17:30), Thứ 7 (08:30 - 12:00)', '[''Được hỗ trợ 2 triệu/ tháng'', ''Có cơ hội trở thành nhân viên chính thức'', ''Chế độ tăng lương định kỳ 6 tháng/1 lần'', ''4 lần xét duyệt thưởng mỗi quý'', ''Môi trường làm việc chuyên nghiệp'', ''Team Building hàng năm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (614, 3, 9, 'Thực Tập Sinh Hành Chính Nhân Sự', 'Thực hiện công tác truyền thông tuyển dụng, lập kế hoạch tìm kiếm ứng viên theo nhu cầu tuyển dụng của công ty; Thực hiện hoạt động sàng lọc CV ứng viên, bố trí và tham gia vào quá trình phỏng vấn ứng viên; Thực hiện ký kết các thủ tục nhân sự. Triển khai công tác tổ chức họp, đào tạo theo kế hoạch. Tổ chức các sự kiện gắn kết nhân sự. Thực hiện các nhiệm vụ khác theo yêu cầu của quản lý.', 'Tổng thời gian tham gia chương trình thực tập: 3 tháng hoặc 6 tháng; Luôn nỗ lực hết mình để hoàn thành chương trình thực tập; Ưu tiên ngành học: chuyên ngành Nhân sự, Kinh tế, Marketing, Luật…. đang tìm kiếm cơ hội thực tập/ phát triển trong lĩnh vực Tuyển dụng/ Nhân sự.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Giải quyết vấn đề khéo léo'', ''Cẩn thận'', ''Cầu tiến trong công việc'', ''Quản lý thời gian'', ''Khả năng làm việc nhóm'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), tối thiểu 4 tiếng/ ngày, 5 buổi/ tuần', '[''Được tham gia các khóa đào tạo, phát triển kỹ năng'', ''Cơ hội tham gia trực tiếp vào quá trình thực hiện công việc'', ''Hỗ trợ chữ ký và mộc thực tập'', ''Cấp chứng chỉ hoàn thành chương trình thực tập'', ''Có cơ hội trở thành Best Talent với giải thưởng 5,000,000 VND'', ''Có cơ hội trở thành Best Transformation với giải thưởng 5,000,000 VND hoặc 01 năm mentoring'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (615, 7, 9, 'Thực Tập Sinh Pháp Lý', 'Tham gia thực tập trong mảng Thành lập doanh nghiệp & Đầu Tư của công ty với công việc như sau: Tham gia các hoạt động xử lý nghiệp vụ liên quan đến Đầu tư doanh nghiệp mới, Thu thập thông tin Đầu tư, Thủ tục thành lập Doanh nghiệp mới, Thủ tục thay đổi các thông tin doanh nghiệp, Tìm hiểu và thực hiện các hoạt động liên quan đến thủ tục hành chính cho doanh nghiệp: Thủ tục đăng ký đấu thầu, đăng ký đầu tư, Hồ sơ chứng minh ngành nghề, Tham gia các hoạt động đào tạo, tìm hiểu kiến thức chuyên sâu : Giấy phép con, Tham gia hoạt động chăm sóc, tư vấn Khách hàng. Thời gian thực tập full-time hoặc bán thời gian.', 'Sinh viên năm cuối các trường Đại Học, Cao Đẳng chuyên ngành Luật doanh nghiệp, Tài chính kế toán, Quản trị kinh doanh. Có khả năng đọc hiểu, tìm hiểu nhanh các văn bản luật, quy định về doanh nghiệp, thuế. Nhiệt tình, năng nổ, quyết tâm, tự tin. Có thái độ tích cực, làm việc trách nhiệm và không ngừng học hỏi. Tự tin, sáng tạo, chủ động trong công việc.
Kỹ năng chuyên môn: [''Đọc hiểu văn bản luật'', ''Quy định về doanh nghiệp'', ''Quy định về thuế'']
Kỹ năng mềm: [''Nhiệt tình'', ''Năng nổ'', ''Quyết tâm'', ''Tự tin'', ''Thái độ tích cực'', ''Trách nhiệm'', ''Sáng tạo'', ''Chủ động'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Lương thực tập'', ''Phụ cấp thực tập'', ''Thưởng KPI'', ''Đào tạo về Marketing'', ''Môi trường làm việc trẻ trung'', ''Làm việc từ xa tối đa 10 ngày / tháng'', ''Chế độ phúc lợi khác: Thưởng dịp lễ, tết, sinh nhật'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (616, 8, 9, 'Recruitment Intern', 'Thực hiện công tác truyền thông tuyển dụng, tìm kiếm ứng viên theo yêu cầu tuyển dụng của công ty; Sàng lọc hồ sơ, tổ chức phỏng vấn, liên hệ ứng viên, sắp xếp lịch phỏng vấn, theo dõi, đánh giá ứng viên; Hỗ trợ quản lý data dữ liệu ứng viên và nhập thông tin ứng viên vào hệ thống; Hỗ trợ tổ chức các sự kiện của công ty Online và Offline.', 'Sinh viên năm 4 các chuyên ngành Quản trị nguồn nhân lực hoặc các chuyên ngành khác có liên quan, có định hướng phát triển trong lĩnh vực nhân sự; Kỹ tính, cẩn thận và tư duy logic tốt; Chăm chỉ, nhanh nhẹn, chủ động trong công việc; Thành thạo kỹ năng tin học văn phòng (Word và Excel); Ưu tiên các bạn thực tập full time từ 3 tháng trở lên.
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng (Word và Excel)'']
Kỹ năng mềm: [''Kỹ tính'', ''Cẩn thận'', ''Tư duy logic tốt'', ''Chăm chỉ'', ''Nhanh nhẹn'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Hỗ trợ thực tập: 2.000.000 VNĐ/ tháng'', ''Cơ hội trở thành thành viên chính thức của Công ty sau quá trình thực tập'', ''Được training phát triển kỹ năng trong công việc và bản thân'', ''Hỗ trợ mộc thực tập (mộc tròn)'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (617, 9, 9, 'Tuyển dụng thực tập (MASS)', 'Thực hiện đăng tuyển thông tin tuyển dụng trên các kênh tuyển dụng. Tiếp nhận và xử lý hồ sơ ứng viên; thực hiện sắp xếp, lên lịch gửi thư mời và thực hiện phỏng vấn ứng viên. Chốt danh sách và mời nhận việc đối với ứng viên trúng tuyển. Hỗ trợ quản lý, vận hành và trả lời các thông tin trên Fanpage tuyển dụng. Hỗ trợ nghiên cứu và phát triển các kênh nguồn ứng viên tiềm năng. Tham gia lên ý tưởng các hoạt động truyền thông nội bộ và thương hiệu tuyển dụng.', 'Sinh viên năm 3,4 các ngành: Quản trị Nhân sự, Quản trị Kinh doanh, Kinh doanh quốc tế, Ngoại thương hoặc các ngành học khác liên quan. Thành thạo tin học văn phòng (Microsoft Office), biết sử dụng các phần mềm thiết kế là lợi thế (AI, Photoshop, Canva, ...). Có khả năng sắp xếp công việc hợp lý. Tinh thần làm việc với trách nhiệm cao và luôn chủ động trong công việc. Cẩn thận, tỉ mỉ, chịu được áp lực công việc cao.
Kỹ năng chuyên môn: [''Microsoft Office'', ''AI'', ''Photoshop'', ''Canva'']
Kỹ năng mềm: [''Sắp xếp công việc hợp lý'', ''Tinh thần làm việc với trách nhiệm cao'', ''Chủ động trong công việc'', ''Cẩn thận'', ''Tỉ mỉ'', ''Chịu được áp lực công việc cao'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Full - time (Hành chính 8:30 – 17:30 thứ Hai – Sáu)', '[''Cơ hội được đào tạo, trải nghiệm và phát triển trong lĩnh vực Nhân sự.'', ''Cơ hội được trở thành Nhân viên chính thức của Con Cưng sau quá trình thực tập.'', ''Được tham gia hầu hết các hoạt động của công ty.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (618, 10, 9, 'Thực Tập Sinh - Hành Chính Nhân Sự', 'Chuẩn hóa toàn bộ hồ sơ bản cứng cho nhân viên đang làm việc. Phối hợp thu thập bổ sung hồ sơ nhân viên còn thiếu. Sắp xếp, phân loại, scan lưu trữ file mềm, bàn giao lưu trữ hợp lý. Hỗ trợ rà soát các thủ tục pháp lý liên quan đến hồ sơ lao động. Thực hiện các công việc liên quan khác theo yêu cầu của Trưởng Phòng & BGĐ.', 'Là sinh viên năm 3-4 đang học ĐH, CĐ, TC luật, quản trị nhân lực, yêu thích ngành nghề nhân sự ... (Ưu tiên các bạn sinh viên năm cuối). Đảm bảo thời gian thực tập ít nhất 3 tháng, từ 3-4 ngày fulltime/ tuần. Có tinh thần “cầu thị” (chịu khó học hỏi, lắng nghe và chủ động trao đổi để cùng giải quyết vấn đề). Có thái độ tích cực, khiêm nhường, kiên trì, bền bỉ, bình tĩnh xử lý tình huống... Có sức khỏe tốt, ổn định, giọng nói dễ nghe, có khả năng bình tĩnh xử lý các tình huống phát sinh, chủ động trong công việc. Có khả năng sử dụng Word, Excel ở mức độ cơ bản; đọc hiểu tài liệu Tiếng Anh. Ưu tiên biết sử dụng Canva.
Kỹ năng chuyên môn: [''Word'', ''Excel'', ''Canva'']
Kỹ năng mềm: [''Cầu thị'', ''Thái độ tích cực'', ''Kiên nhẫn'', ''Bình tĩnh xử lý tình huống'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Được đào tạo kiến thức, kỹ năng'', ''Hỗ trợ gửi xe'', ''Hỗ trợ chi phí ăn trưa'', ''Xác nhận báo cáo thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (619, 2, 9, 'Thực Tập Sinh Nhân Sự', 'Tuyển dụng và tìm kiếm ứng viên phù hợp với nhu cầu của công ty. Đăng tin tuyển dụng trên các trang web, diễn đàn và mạng xã hội. Sàng lọc hồ sơ, phỏng vấn và đánh giá ứng viên. Thực hiện các bài kiểm tra năng lực và đánh giá tính cách của ứng viên. Lập kế hoạch và tổ chức các buổi phỏng vấn. Thực hiện các thủ tục tuyển dụng và làm hợp đồng lao động. Xây dựng và quản lý cơ sở dữ liệu ứng viên. Cập nhật và cải tiến quy trình tuyển dụng. Báo cáo kết quả tuyển dụng cho ban lãnh đạo. Hỗ trợ các bộ phận khác trong việc đào tạo và định hướng nhân viên mới. Quản lý các mối quan hệ với các trường đại học và các trung tâm đào tạo.', 'Không yêu cầu kinh nghiệm. Có kỹ năng giao tiếp, đàm phán và thuyết phục tốt. Có khả năng làm việc độc lập và làm việc nhóm. Có kỹ năng tổ chức và quản lý thời gian hiệu quả. Có khả năng sử dụng thành thạo máy tính và các phần mềm văn phòng. Trung thực, năng động, nhiệt tình và có trách nhiệm trong công việc. Khả năng chịu áp lực công việc cao.
Kỹ năng chuyên môn: [''Microsoft Office (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Đàm phán'', ''Thuyết phục'', ''Làm việc độc lập'', ''Làm việc nhóm'', ''Kỹ năng tổ chức'', ''Quản lý thời gian'', ''Trung thực'', ''Năng động'', ''Nhiệt tình'', ''Có trách nhiệm trong công việc'', ''Khả năng chịu áp lực công việc cao'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), thời gian linh hoạt theo lịch của các bạn', '[''Hỗ trợ mộc thực tập'', ''Có hỗ trợ lương'', ''Có thưởng khi đạt hiệu quả công việc'', ''Môi trường làm việc chuyên nghiệp, năng động và thân thiện, có pantry cà phê miễn phí'', ''Có nhiều cơ hội học hỏi và phát triển nghề nghiệp'', ''Có nhiều cơ hội tiếp xúc các hoạt động tạo thêm thu nhập nếu có nhu cầu'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (620, 3, 9, 'Thực Tập Sinh Quản Trị Nhân Lực - Kinh Doanh', 'Tham gia công tác tuyển dụng: đăng tuyển, thu CV, hẹn phỏng vấn, follow ứng viên và tiếp nhận kết quả thông báo cho ứng viên. Hỗ trợ xây dựng thương hiệu tuyển dụng cho HR, tập đoàn. Cập nhật và quản lý CV, hồ sơ nhân sự nội bộ. Tham gia vào công tác hành chính nhân sự: mua sắm văn phòng phẩm, cấp phát đồng phục, thẻ nhân sự, làm ĐNTT. Nhắn tin tương tác với khách hàng theo kịch bản có sẵn từ danh sách dữ liệu và profile được leader phân bổ. Cập nhật, ghi chú và báo cáo tiến độ công việc hàng ngày.', 'Sinh viên các ngành Quản trị kinh doanh, Kinh tế, Quản trị nhân lực, Quản trị văn phòng, văn thư lưu trữ, ngôn ngữ,... Chủ động, ham học hỏi, cẩn thận và có tinh thần trách nhiệm trong công việc. Tác phong lịch sự, nhanh nhẹn, tinh tế. Đam mê nghề nhân sự, kinh doanh, có mục tiêu công việc cụ thể.
Kỹ năng chuyên môn: [''Microsoft Office (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Chủ động'', ''Ham học hỏi'', ''Cẩn thận'', ''Có tinh thần trách nhiệm'', ''Tác phong lịch sự'', ''Nhanh nhẹn'', ''Tinh tế'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Tea-break miễn phí mỗi chiều'', ''Gửi xe miễn phí'', ''Được đào tạo 1:1 kiến thức và kỹ năng thực tế'', ''Môi trường làm việc thân thiện, chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức'', ''Tham gia các buổi đào tạo, huấn luyện'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (621, 7, 9, 'Thực Tập Sinh Nhân Sự', 'Tìm hiểu và thực hành với hoạt động tuyển dụng (chính): Thiết kế poster, viết bài content cho các hoạt động tuyển dụng, đăng bài, lọc CV, liên hệ ứng viên, gửi thư mời tham gia phỏng vấn, phản hồi kết quả phỏng vấn đến với ứng viên; tìm kiếm đối tác tuyển dụng, đề xuất các kế hoạch tuyển dụng mới, báo cáo kết quả tuyển dụng. Tìm hiểu và thực hành với hoạt động đào tạo: Lên danh sách tham gia đào tạo, gửi lịch và thư mời tham gia đào tạo, thực hiện công tác điểm danh, hỗ trợ CBNV trong quá trình tham gia đào tạo, setup khu vực đào tạo, báo cáo số lượng nhân sự tham gia đào tạo. Tìm hiểu và thực hành với hoạt động C&B: Thực hiện các công việc khác theo sự hướng dẫn của Trưởng Bộ Phận Quản Trị Nguồn Nhân Lực.', 'Là sinh viên năm 3, năm 4. Đang trong thời gian chương trình thực tập. Có Laptop cá nhân. Kỹ năng giao tiếp tốt, Chủ động giải quyết vấn đề. Thời gian thực tập từ 3 - 6 tháng.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Sử dụng Laptop'']
Kỹ năng mềm: [''Chủ động giải quyết vấn đề'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Phụ cấp chi phí thực tập'', ''Hỗ trợ xác nhận thực tập'', ''Được đào tạo, hướng dẫn thực tế'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (622, 8, 9, 'Nhân Viên Admin Finance Thời Vụ 3 Tháng', 'Hỗ trợ team Finance trong việc thu thập giấy tờ, chứng từ. Sắp xếp, kiểm tra giấy tờ, hồ sơ, đảm bảo chất lượng và thời gian xử lí hồ sơ theo đúng quy định. Nhập dữ liệu vào hệ thống. Các công việc hỗ trợ khác khi cần. Đảm bảo tuân thủ các quy định của công ty.', 'Số lượng: 01 HC. Cẩn thận, chăm chỉ, trung thực. Tự giác thực hiện công việc, sẵn sàng hỗ trợ các thành viên trong team để hoàn thành mục tiêu công việc. Tiếng Anh cơ bản, có khả năng sử dụng máy tính và excel/G-sheet thành thạo. Trình độ trung cấp trở lên, background về kế toán là lợi thế.
Kỹ năng chuyên môn: [''Sử dụng máy tính'', ''Excel'', ''G-sheet'']
Kỹ năng mềm: [''Cẩn thận'', ''Chăm chỉ'', ''Trung thực'', ''Tự giác'', ''Sẵn sàng hỗ trợ'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '5.0 - 6.0 triệu', '9h - 18h (nghỉ trưa 1 tiếng) từ thứ hai đến thứ sáu', '[''Thu nhập: 300.000đ/8h'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (623, 9, 9, 'Thực Tập Sinh Tuyển Dụng Part-Time/Full-Time', 'Thực hiện thiết kế và đăng tin tuyển dụng trên các nền tảng để tiếp cận ứng viên. Tiếp cận với ứng viên và trao đổi thông tin công việc. Hỗ trợ giải đáp thắc mắc của ứng viên trong quá trình ứng tuyển nhằm tạo trải nghiệm tốt cho ứng viên. Thực hiện các công việc khác theo sự phân công của Leader.', 'Sinh viên năm 2, 3, 4 đang học tại các trường ĐH trên địa bàn Hà Nội (ưu tiên sinh viên học ngành Quản trị Nhân lực, QTKD, Marketing, Truyền thông...). Có định hướng/mong muốn phát triển nghề nghiệp theo Tuyển dụng – Nhân sự. Kỹ năng giao tiếp và sử dụng tin học văn phòng tốt. Máu lửa, chăm chỉ, kiên trì và chịu khó.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Máu lửa'', ''Chăm chỉ'', ''Kiên trì'', ''Chịu khó'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được đào tạo bài bản về tuyển dụng thực chiến từ Leader có kinh nghiệm'', ''Được làm việc trong môi trường trẻ trung, tư duy mở, thoải mái sáng tạo'', ''Cơ hội trải nghiệm hoạt động tuyển dụng chuyên nghiệp cho các đối tác lớn'', ''Được tham gia vào các hoạt động party, hoạt động thể thao, gắn kết của công ty...'', ''Cơ hội trở thành nhân viên chính thức của tại team tuyển dụng của công ty'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (624, 10, 9, 'Thực Tập Sinh Admin', '1. Hỗ trợ công việc hành chính đơn giản: in ấn, book xe, book họp, scan,... Update thông tin về sản phẩm mới trên CRM, trên Driver. Chuẩn bị các đề xuất và đề nghị thanh toán (cố định và phát sinh). 2. Xử lý các công việc phát sinh theo yêu cầu: Hỗ trợ thực hiện các báo cáo về hoạt động bán hàng và các chỉ số của Phòng Kinh doanh.', 'Thực tập sinh có laptop. Sinh viên năm 3 hoặc năm 4. Chăm chỉ, chịu khó. Làm việc tối thiểu 3 ngày/ tuần.
Kỹ năng chuyên môn: [''Sử dụng laptop'']
Kỹ năng mềm: [''Chăm chỉ'', ''Chịu khó'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ dấu thực tập'', ''Phí gửi xe'', ''Đào tạo 1-1'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (625, 2, 9, 'Thực Tập Sinh Trợ Lý Cá Nhân', 'Hỗ trợ làm công việc về gửi message cho đối tác, connect các kênh mạng xã hội với các CEO, Founder ở US, post các thông tin dịch vụ cty lên các nền tảng ib mxh. Research để tìm kiếm thông tin về job ở US và Canada, thực hiện nộp hồ sơ, đánh giá kết quả đề xuất giải pháp để tối ưu công việc. Thực hiện công việc mà đối tác giao cho công ty, vd các dịch vụ về HR Executive ở California, US. Hỗ trợ công tác hợp tác và tuyển dụng TTS với các trường ĐH-CĐ ở Việt. Quản lý các công việc tổng thể trong công ty, quản lý chất lượng TTS, thời gian làm việc của TTS, đề bài công ty giao cho TTS.', 'Trình độ: Sinh viên năm 2 đến cử nhân tốt nghiệp đại học/cao đẳng chuyên ngành Kinh tế, Quản trị nhân sự hành chính,... Có khả năng làm việc với thái độ làm việc tích cực và chủ động trong công việc, có tinh thần trách nhiệm, có tinh thần làm việc nhóm, có khả năng nghiên cứu công việc mới, thực hiện các yêu cầu từ cấp trên.
Kỹ năng mềm: [''Thái độ làm việc tích cực'', ''Chủ động trong công việc'', ''Tinh thần trách nhiệm'', ''Tinh thần làm việc nhóm'', ''Khả năng nghiên cứu'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:00 đến 17:00)', '[''Hỗ trợ dấu mộc xác nhận thực tập'', ''Cấp giấy chứng nhận, chứng chỉ thực tập khi hoàn thành chương trình'', ''Có nhân viên công ty hướng dẫn training trực tiếp'', ''Nâng cao hồ sơ profile công việc'', ''Thời gian làm việc linh động'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (626, 3, 9, 'Thực Tập Sinh Nhân Sự', 'Thực tập sinh Tuyển dụng sẽ được hướng dẫn và tham gia quy trình tuyển dụng tại 30Shine: Hỗ trợ khai thác nguồn thông tin ứng viên, đăng thông tin tuyển dụng. Sàng lọc và lựa chọn ứng viên phù hợp. Hỗ trợ liên hệ ứng viên sắp xếp lịch phỏng vấn. Thực hiện một số công việc khác theo sự phân công.', 'Nam/Nữ đang là sinh viên năm 2, 3, 4 tại các trường Đại học. Sinh viên ngành QTNL hoặc các chuyên ngành liên quan, có định hướng theo nghề nhân sự. Nhanh nhẹn, chủ động. Không yêu cầu kinh nghiệm. Có tinh thần ham học hỏi.
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chủ động'', ''Có tinh thần ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Được định hướng chuyên môn sớm'', ''Được đào tạo kỹ năng, nghiệp vụ'', ''Được trải nghiệm môi trường văn hóa trẻ trung, năng động, hiện đại'', ''Có cấp dấu khi tham gia thực tập'', ''Hỗ trợ số liệu và tài liệu làm báo cáo, khóa luận tốt nghiệp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (627, 7, 9, 'Thực Tập Sinh Trợ Lý Cá Nhân', 'Hỗ trợ làm công việc về gửi message cho đối tác, connect các kênh mạng xã hội với các CEO, Founder ở US, post các thông tin dịch vụ công ty lên các nền tảng mạng xã hội. Research để tìm kiếm thông tin về job ở US và Canada, thực hiện nộp hồ sơ, đánh giá kết quả đề xuất giải pháp để tối ưu công việc. Thực hiện công việc mà đối tác giao cho công ty, vd các dịch vụ về HR Executive ở California, US. Hỗ trợ công tác hợp tác và tuyển dụng thực tập sinh với các trường Đại Học - Cao Đẳng ở Việt Nam. Quản lý các công việc tổng thể trong công ty, quản lý chất lượng thực tập sinh, thời gian làm việc của thực tập sinh, đề bài công ty giao cho thực tập sinh.', 'Trình độ: Sinh viên năm 2 đến cử nhân tốt nghiệp đại học/cao đẳng chuyên ngành kinh tế, quản trị nhân sự hành chính, ... Có khả năng làm việc với thái độ làm việc tích cực và chủ động. Chủ động trong công việc, có tinh thần trách nhiệm, có tinh thần làm việc nhóm, có khả năng nghiên cứu công việc mới, thực hiện các yêu cầu từ cấp trên.
Kỹ năng mềm: [''Thái độ làm việc tích cực'', ''Chủ động trong công việc'', ''Tinh thần trách nhiệm'', ''Làm việc nhóm'', ''Khả năng nghiên cứu'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ dấu mộc xác nhận thực tập'', ''Cấp giấy chứng nhận, chứng chỉ thực tập khi hoàn thành chương trình'', ''Hướng dẫn training trực tiếp'', ''Nâng cao hồ sơ profile công việc'', ''Nghỉ lễ, Tết đầy đủ theo quy định nhà nước'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (628, 8, 9, 'Thực Tập Sinh Kinh Doanh', 'Hỗ trợ xây dựng và cập nhật thông tin sản phẩm, chính sách bán hàng, chương trình khuyến mãi, kế hoạch phát triển sản phẩm mới. Tham gia khảo sát thị trường, kênh bán hàng, thói quen tiêu dùng, thu thập thông tin đối thủ và phản hồi khách hàng. Hỗ trợ lập báo cáo kinh doanh theo tuần/tháng (doanh số, tồn kho, phản hồi thị trường...). Tham gia vào các công tác truyền thông, marketing và cung cấp thông tin hỗ trợ hoạt động kinh doanh của khách hàng. Hỗ trợ đơn vị để phối hợp với các phòng ban như Mua hàng, Giao hàng, Kế toán để theo dõi đơn hàng và công nợ. Tham gia các buổi đào tạo nội bộ để hiểu rõ vai trò, chức năng, nhiệm vụ của vị trí Sales và PM. Luân phiên thực tập tại line kinh doanh để trải nghiệm công việc, quy trình, cách thức phối hợp. Hỗ trợ các công việc khác theo phân công của Trưởng bộ phận hoặc cán bộ được phân công phụ trách.', 'Sinh viên Năm 4 hoặc sắp tốt nghiệp thuộc khối ngành Kinh tế của các trường như ĐH Ngoại Thương, Kinh tế quốc dân… Có thể sử dụng tốt Tiếng Anh tốt (IELTS ≥ 5.0 hoặc Toeic >=500) Sử dụng thành thạo vi tính văn phòng. Ngoại hình ưa nhìn, giao tiếp tốt, nhanh nhẹn, chăm chỉ, ham học hỏi. Mong muốn tìm kiếm cơ hội gắn bó và phát triển lâu dài.
Kỹ năng chuyên môn: [''Sử dụng thành thạo vi tính văn phòng'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Nhanh nhẹn'', ''Chăm chỉ'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được hỗ trợ chi phí tùy theo năng lực'', ''Có cơ hội được trở thành nhân viên chính thức sau thời gian thực tập'', ''Được học thật làm thật, tiếp xúc với môi trường doanh nghiệp lớn'', ''Được đào tạo kỹ năng và nghiệp vụ'', ''Được tham gia các hoạt động của Công ty và tập đoàn FPT'', ''Xác nhận quá trình thực tập (nếu cần), thư giới thiệu'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (629, 9, 9, 'HR Intern', '- Hỗ trợ công tác tuyển dụng: * Đăng tin tuyển dụng trên các kênh: website, mạng xã hội, job-site. * Tổng hợp hồ sơ, cập nhật nguồn ứng viên và quản lý dữ liệu tuyển dụng. * Liên hệ, hướng dẫn và cung cấp thông tin cho ứng viên trong suốt quy trình. - Hỗ trợ công tác C&B: * Thực hiện quy trình onboarding và offboarding cho nhân sự mới/nghỉ việc. * Quản lý, cập nhật, sắp xếp, scan và lưu trữ hồ sơ nhân sự (bản cứng & bản mềm). * Tổng hợp và đối chiếu dữ liệu nhân sự phục vụ báo cáo C&B. * Thu thập và tổng hợp dữ liệu C12, mã số thuế cá nhân và hồ sơ đăng ký NPT. - Hỗ trợ thực hiện công tác hành chính, văn phòng: * Quản lý văn phòng phẩm, teabreak và trang thiết bị văn phòng. * Kiểm tra, đối soát và lưu trữ chứng từ hóa đơn, hợp đồng hành chính. - Các công việc khác theo yêu cầu của Trưởng nhóm/ Trưởng bộ phận.', '- Trình độ học vấn: Đang học năm 3 hoặc năm 4 chuyên ngành Quản trị Nhân sự, Truyền thông hoặc các ngành liên quan tại các trường đại học. - Kỹ năng & phẩm chất: * Sử dụng thành thạo Excel (hàm cơ bản, PivotTable, lọc – sắp xếp dữ liệu). * Tư duy logic, kỹ năng phân tích và định hướng kết quả. * Kỹ năng giao tiếp, phối hợp và làm việc nhóm. * Trung thực, cẩn thận và có trách nhiệm trong công việc.
Kỹ năng chuyên môn: [''Sử dụng thành thạo Excel (hàm cơ bản, PivotTable, lọc – sắp xếp dữ liệu)'']
Kỹ năng mềm: [''Tư duy logic'', ''Kỹ năng phân tích'', ''Kỹ năng giao tiếp'', ''Phối hợp và làm việc nhóm'', ''Trung thực'', ''Cẩn thận'', ''Có trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:30)', '[''Trợ cấp thực tập: 3.000.000 vnđ/tháng'', ''Được đào tạo chuyên sâu về quy trình tuyển dụng, C&B và hành chính nhân sự'', ''Cơ hội học hỏi, phát triển kỹ năng chuyên môn và tiếp cận môi trường làm việc chuyên nghiệp'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (630, 10, 9, 'Nhân Viên Tuyển Dụng', 'Phụ trách tuyển các vị trí khối Kinh doanh khu vực miền Nam. Lập kế hoạch và triển khai hoạt động thu hút nhân tài & tuyển dụng để có phương án tuyển dụng phù hợp. Xây dựng nguồn ứng viên đa dạng, phù hợp chuyên môn cho các vị trí mà công ty cần tuyển dụng trong hiện tại và tương lai. Hỗ trợ xây dựng thương hiệu nhà tuyển dụng để tiếp cận, thu hút được ứng viên tiềm năng, tăng tỉ lệ lựa chọn ứng viên phù hợp với công ty và tiết kiệm chi phí tuyển dụng. Tuyển dụng đúng người, đúng vị trí, đúng thời gian để đảm bảo vận hành các hoạt động của công ty. Thực hiện hội nhập cho nhân viên mới nhằm đảm bảo khả năng hòa nhập môi trường mới, thích nghi với công việc và nắm bắt công việc trong thời gian ngắn nhất. Các công việc khác liên quan theo yêu cầu của quản lý.', 'Tốt nghiệp Đại Học trở lên. Ít nhất 1 năm kinh nghiệm tuyển dụng, ưu tiên ứng viên có kinh nghiệm tuyển Mass. Thành thạo các phương pháp tìm kiếm ứng viên (headhunting, networking, job boards, social recruiting, ...). Kỹ năng giao tiếp, đàm phán tốt. Kỹ năng lập kế hoạch và quản lý tuyển dụng tốt. Chịu được áp lực công việc cao.
Kỹ năng chuyên môn: [''headhunting'', ''networking'', ''job boards'', ''social recruiting'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng đàm phán'', ''Kỹ năng lập kế hoạch'', ''Quản lý tuyển dụng'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:15)', '[''Chế độ bảo hiểm đầy đủ theo Luật lao động'', ''Môi trường làm việc chuyên nghiệp, năng động'', ''Cơ hội đào tạo, phát triển nghề nghiệp'', ''Ăn trưa'', ''Cước điện thoại'', ''Bảo hiểm xã hội'', ''Thưởng hiệu quả làm việc'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (631, 2, 9, 'Thực Tập Sinh Tuyển Dụng', 'Hỗ trợ đăng tin tuyển dụng, tìm kiếm và sàng lọc hồ sơ ứng viên, hỗ trợ quy trình phỏng vấn, quản lý dữ liệu ứng viên, hỗ trợ các công việc khác.', 'Sinh viên năm 4 Đại học các chuyên ngành: Quản trị nhân lực/ Quản trị kinh doanh,… có thể đi làm fulltime. Không yêu cầu kinh nghiệm. Có mong muốn phát triển trong mảng Nhân sự, Tuyển dụng. Nhanh nhẹn. Teamwork và làm việc độc lập tốt. Kỹ năng giao tiếp tốt; Nhiệt tình, ham học hỏi. Kỹ năng tin học văn phòng (Word, Excel, Powerpoint) tốt.
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng (Word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Teamwork'', ''Làm việc độc lập'', ''Kỹ năng giao tiếp tốt'', ''Nhiệt tình'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30) hoặc (từ 08:00 đến 17:00)', '[''Được đào tạo và có cơ hội trau dồi tư duy, kiến thức, kỹ năng về quản trị nhân lực'', ''Hỗ trợ đánh giá và đóng mộc xác nhận hoàn tất thực tập'', ''Môi trường làm việc trẻ trung, khuyến khích học tập, sáng tạo'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (632, 3, 9, 'Thực Tập Sinh Sales Admin', 'Bán hàng Phần mềm (Zoom, Canva, Adobe, Email Marketing, CRM,...) qua kênh online (đăng thông tin, quảng bá phần mềm,...). Nhận và chăm khách từ hệ thống Marketing của công ty (phần Inbox của Hubspot). Tư vấn các dịch vụ/phần mềm cho các khách hàng của công ty như Zoom, Mailchimp... Thực hiện làm báo giá, đề xuất, hợp đồng cho khách hàng. Làm báo cáo hàng ngày.', 'Không yêu cầu kinh nghiệm. Ưu tiên các bạn đã có kinh nghiệm. Chấp nhận sinh viên năm 3, 4 của các trường Đại học có đầu vào cao và đã có kinh nghiệm làm việc. Ưu tiên các bạn có kinh nghiệm liên quan tới phần mềm Marketing, CRM, quản lý dự án. Ưu tiên đọc hiểu tiếng Anh, hoặc quen sử dụng phần mềm giao diện tiếng Anh. Ưu tiên các bạn có hiểu biết về Digital Marketing.
Kỹ năng chuyên môn: [''Tin học văn phòng'', ''Mạng xã hội'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Đàm phán'', ''Thuyết trình'', ''Tư duy tốt'', ''Nhanh nhẹn'', ''Nhiệt tình'', ''Có trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '2.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00), Sáng thứ 7: Từ 08:30 đến 12:30', '[''Môi trường làm việc chuyên nghiệp, năng động, thân thiện'', ''Cơ hội thăng tiến rõ ràng'', ''Trợ cấp ăn trưa'', ''Tiền gửi xe (nếu làm fulltime)'', ''Lương, thưởng theo quy định'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (633, 7, 9, 'Thực Tập Sinh Tuyển Dụng', 'Nhận mô tả công việc đăng tin tuyển dụng trên các kênh mạng xã hội, website, hội nhóm. Sàng lọc hồ sơ, sơ vấn và theo dõi lịch hẹn. Hỗ trợ tổ chức buổi phỏng vấn cùng quản lý. Cập nhật kết quả ứng viên.', 'Sinh viên năm 3, năm 4 hoặc vừa tốt nghiệp các ngành liên quan: Quản trị nhân lực, Kinh doanh, Tâm lý học... Không yêu cầu kinh nghiệm. Yêu thích lĩnh vực nhân sự, đặc biệt là tuyển dụng. Có kinh nghiệm tuyển dụng, hiểu biết về mảng bất động sản là một lợi thế. Chủ động, ham học hỏi, có tinh thần trách nhiệm.
Kỹ năng mềm: [''Chủ động'', ''Ham học hỏi'', ''Có tinh thần trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hoa hồng tuyển dụng khi tuyển dụng thành công'', ''Được đào tạo bài bản, học hỏi quy trình tuyển dụng chuyên nghiệp'', ''Làm việc trong môi trường cởi mở, năng động, có cơ hội học hỏi thực tế từ ngành bất động sản'', ''Có cơ hội thăng tiến, trở thành nhân viên chính thức sau thực tập'', ''Cấp mộc chứng nhận thực tập sau khi hoàn thành'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (634, 8, 9, 'Thực Tập Sinh Nhân Sự', 'Hỗ trợ đăng tin trên các trang tuyển dụng (Linkedln, FB,..). Sàng lọc hồ sơ, liên hệ ứng viên, sắp xếp lịch phỏng vấn. Tạo mô tả công việc cho từng vị trí. Tạo câu hỏi phỏng vấn ứng viên. Tham gia triển khai các hoạt động, kế hoạch giúp nâng cao quy trình tuyển dụng tại công ty. Hỗ trợ các công việc khác theo yêu cầu của quản lý.', 'Sinh viên năm 3, 4 hoặc mới tốt nghiệp chuyên ngành Quản trị Nhân lực, Kinh tế, Quản trị Kinh doanh hoặc liên quan. Năng động, nhiệt tình, có trách nhiệm. Kỹ năng giao tiếp tốt, cẩn thận và ham học hỏi. Ưu tiên có định hướng theo đuổi nghề Nhân sự. Đáp ứng được thời gian làm việc tối thiểu 24t/1 tuần, 1 buổi/4t.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Microsoft Office (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Năng động'', ''Nhiệt tình'', ''Có trách nhiệm'', ''Cẩn thận'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Có hỗ trợ lương thực tập'', ''Cung cấp tài liệu làm báo cáo, mộc thực tập'', ''Môi trường làm việc trẻ trung, năng động'', ''Cơ hội trở thành nhân viên chính thức sau thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (635, 9, 9, 'Thực Tập Sinh Quản Trị Hợp Đồng', 'Thực hiện các đầu việc về quản trị hợp đồng hợp tác với các Đối tác: Tiếp nhận yêu cầu trình ký hợp đồng, soạn thảo hợp đồng gửi tới Đối tác theo yêu cầu; Nhận hợp đồng từ Đối tác, kiểm tra và nhập thông tin các chứng từ đi kèm lên hệ thống, bàn giao cho Chuyên viên phụ trách hợp đồng; Scan, sắp xếp và lưu trữ hồ sơ, hợp đồng bản gốc theo đúng quy trình; Thực hiện các công việc giao, nhận, chuyển phát hợp đồng bản gốc tới các Đối tác; Hỗ trợ công việc kinh doanh khác dưới sự phân công của Quản lý.', 'Sinh viên năm cuối các khối ngành Kinh doanh, Kinh tế hoặc các chuyên ngành liên quan khác; Không yêu cầu kinh nghiệm; Có thể đi làm toàn thời gian từ Thứ 2 đến sáng Thứ 7; Trung thực, tinh thần trách nhiệm cao; Nhanh nhẹn, cẩn thận và tỉ mỉ trong công việc.
Kỹ năng mềm: [''Trung thực'', ''Tinh thần trách nhiệm cao'', ''Nhanh nhẹn'', ''Cẩn thận'', ''Tỉ mỉ trong công việc'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Toàn thời gian từ Thứ 2 đến sáng Thứ 7', '[''Hỗ trợ chi phí thực tập kèm hỗ trợ gửi xe, ăn ca'', ''Cung cấp dấu xác nhận hoàn thành quá trình thực tập'', ''Hỗ trợ đào tạo những nghiệp vụ liên quan tới lĩnh vực kinh doanh, quy trình hợp tác cùng đối tác'', ''Môi trường trẻ trung, năng động, chuyên nghiệp với nhiều cơ hội phát triển bản thân, phát triển nghề nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (636, 10, 9, 'Thực Tập Sinh Sales Admin', 'Hỗ trợ thực hiện các báo cáo về hoạt động bán hàng và các chỉ số của Phòng Kinh doanh. Hỗ trợ nhân viên Phòng Kinh doanh gửi các chứng từ, thủ tục cần thiết. Thực hiện các công việc hành chính của Phòng Kinh doanh. Thực hiện một số công việc khác theo yêu cầu của cấp trên.', 'Có laptop cá nhân. Ưu tiên các bạn sinh viên năm 4 có thể đi làm fulltime từ thứ hai đến thứ sáu (hoặc đi linh hoạt theo lịch học). Thực tập tối thiểu 3 tháng. Trung thực, trách nhiệm, có đam mê với công việc Sales Admin.
Kỹ năng chuyên môn: [''Microsoft Office (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Trung thực'', ''Trách nhiệm'', ''Có đam mê với công việc Sales Admin'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ dấu thực tập và phí gửi xe'', ''Đào tạo 1-1'', ''Tham gia các khóa học trong và ngoài công ty'', ''Hướng dẫn viết báo cáo hàng ngày, hàng tuần, hàng tháng'', ''Tham gia các hoạt động văn nghệ, văn hóa phong trào cùng Công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (637, 2, 9, 'Thực Tập Sinh Đào Tạo', '1. Thiết kế tài liệu * Tài liệu cần thiết kế gồm PowerPoint, Catalogue tài liệu đào tạo, các ấn phẩm truyền tải nội dung đào tạo * Tài liệu video cần chỉnh sửa, cắt dựng từ file ghi hình các buổi học trực tiếp hoặc trực tuyến 2. Xây dựng nội dung thông qua hình ảnh * Xây dựng content cô đọng, truyền tải nội dung phù hợp định dạng tài liệu 3. Công việc khác được phân công * Hỗ trợ các công việc khác của phòng Đào tạo', 'Sinh viên năm cuối, các CN: thiết kế ấn phẩm, tài liệu,… Không yêu cầu kinh nghiệm Có thể thực tập tối thiểu 4 ngày/tuần Thẩm mỹ và tư duy thiết kế sáng tạo, cởi mở Sử dụng tốt các phần mềm thiết kế, đồ họa: Canva, MS Powerpoint Biết sử dụng Photoshop, AI hoặc các phần mềm khác để thiết kế bài giảng E-learning là một lợi thế
Kỹ năng chuyên môn: [''Canva'', ''MS Powerpoint'', ''Photoshop'', ''AI'']
Kỹ năng mềm: [''Thẩm mỹ'', ''Tư duy thiết kế sáng tạo'', ''Cởi mở'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:15 đến 17:15)', '[''Hỗ trợ tiền lương 3 triệu/tháng'', ''Hỗ trợ sinh viên đóng dấu thực tập'', ''Được tiếp xúc trực tiếp với công việc'', ''Được đào tạo, hướng dẫn chi tiết trong công việc'', ''Môi trường hòa đồng, thân thiện'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (638, 3, 9, 'Talent Acquisition Intern', 'Tham gia quá trình tạo nguồn, đánh giá, phỏng vấn, offer ứng viên các vị trí IT và Non IT. Thực hiện truyền thông tuyển dụng qua các kênh social network: Facebook, Linkedin, Jobsite,... Hỗ trợ lên kế hoạch và triển khai các hoạt động xây dựng thương hiệu tuyển dụng. Hỗ trợ tổ chức/ hỗ trợ tổ chức các sự kiện cần thiết nhằm thu hút nhân sự chất lượng cao: Job Fair, Workshop,... Mở rộng, phát triển các kênh tuyển dụng, thiết lập các mối quan hệ với các cá nhân, tổ chức, đơn vị trong lĩnh vực tuyển dụng.', 'Sinh viên năm 2,3,4 các trường Đại học chuyên ngành Quản trị nhân sự, Quản trị kinh doanh, Kinh tế, Công nghệ thông tin,... hoặc có định hướng phát triển về Nhân sự. Có khả năng giao tiếp khéo léo linh hoạt, máu chiến, nhiệt huyết, cầu tiến trong công việc. Khả năng nghiên cứu, tìm kiếm thông tin. Yêu thích các công việc liên quan đến mở rộng network, giao tiếp con người. Đã có kinh nghiệm tuyển dụng hoặc hoạt động trong các CLB nhân sự là lợi thế lớn. Làm việc linh động part time 4-5 buổi (sáng hoặc chiều)/1 tuần.
Kỹ năng mềm: [''Giao tiếp khéo léo'', ''Linh hoạt'', ''Nhiệt huyết'', ''Cầu tiến trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca sáng (8h30 - 12h) và Ca chiều (13h30-18h)', '[''Được dẫn dắt, định hướng bởi Leader dày dạn kinh nghiệm'', ''Được đào tạo và phát triển theo khung năng lực'', ''Tham gia các Workshop, Master talk, CEO talk'', ''Có lộ trình thăng tiến rõ ràng'', ''Môi trường làm việc trẻ trung, năng động và sáng tạo'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (639, 7, 9, 'Thực Tập Sinh Tuyển Dụng (HRBP Intern)', 'Tuyển dụng (70%) ● Hỗ trợ công tác truyền thông tuyển dụng: Đăng tin, tạo nguồn từ đa kênh để thu hút ứng viên tiềm năng. ● Tiếp nhận các cuộc gọi đến, hướng dẫn ứng viên các thông tin cần thiết. ● Phỏng vấn và sàng lọc ứng viên qua điện thoại và set up lịch phỏng vấn trực tiếp. ● Tham gia hỗ trợ trong quá trình phỏng vấn, nhận phản hồi từ ứng viên. ● Nghiên cứu, đóng góp ý tưởng và cùng bộ phận thực hiện các dự án tạo nguồn ứng viên và xây dựng thương hiệu tuyển dụng. Công tác hỗ trợ tuyển dụng (30%) ● Hướng dẫn ứng viên hoàn tất hồ sơ, hợp đồng. ● Quản lý hồ sơ nhân viên. ● Tham gia vào quá trình đào tạo thử việc cho nhân viên mới. ● Hỗ trợ công việc khác theo yêu cầu của cấp trên trực tiếp.', '● Có laptop cá nhân để làm việc. ● Sinh viên mới tốt nghiệp Đại học hoặc sinh viên năm 3,4, ưu tiên chuyên ngành Quản trị nhân lực, Quản trị kinh doanh, Kinh tế,… ● Kỹ năng giao tiếp tốt, kỹ năng làm việc nhóm. ● Yêu thích tuyển dụng, làm việc với con người. ● Ưu tiên các bạn có định hướng theo nhân sự lâu dài. ● Có tư duy lên kế hoạch, sáng tạo, biết thiết kế ảnh, video là một lợi thế.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Kỹ năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Phụ cấp thực tập'', ''Hỗ trợ xác nhận quá trình thực tập'', ''Được hướng dẫn với đội ngũ nhân viên tận tình và giàu kinh nghiệm'', ''Được training các nghiệp vụ trở thành một nhân viên Tuyển dụng chuyên nghiệp'', ''Môi trường làm việc chuyên nghiệp, năng động và đầy nhiệt huyết'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (640, 8, 9, 'Thực Tập Sinh', 'Tìm kiếm, sàng lọc hồ sơ ứng viên. Thực hiện liên hệ ứng viên mời phỏng vấn và hỗ trợ điều phối phỏng vấn ứng viên. Hỗ trợ làm báo cáo tổng hợp.', 'Đang học hoặc tốt nghiệp các trường đại học/cao đẳng liên quan đến Quản lý nhân sự... Có kỹ năng giao tiếp, thuyết phục. Tinh thần trách nhiệm, kỹ năng làm việc độc lập hoặc làm việc nhóm. Có thể làm fulltime.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'', ''Tinh thần trách nhiệm'', ''Kỹ năng làm việc độc lập'', ''Kỹ năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 nghỉ cách tuần', '[''Được hướng dẫn, làm việc đối với các bạn chưa có kinh nghiệm'', ''Môi trường làm việc trẻ trung, dễ dàng hòa nhập và phát triển'', ''Cơ hội trở thành nhân viên chính thức sau 3 tháng làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (641, 9, 9, 'Thực Tập Sinh', '• Hỗ trợ bộ phận Tuyển dụng thực hiện các công việc hành chính tuyển dụng theo hướng dẫn và phân công. • Tìm hồ sơ ứng viên. • Sắp xếp, lưu trữ hồ sơ ứng viên. • Cập nhật thông tin ứng viên vào ngân hàng ứng viên. • Tham gia các chương trình tuyển dụng của công ty trong vai trò hậu cần.', '• Ứng viên làm tối thiểu 5 ngày/ tuần • Có kinh nghiệm trong công tác tuyển dụng là lợi thế • Kỹ năng giao tiếp tốt, làm việc độc lập và làm việc nhóm tốt. • Thành thạo tin học văn phòng • Chịu được áp lực công việc
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Làm việc độc lập'', ''Làm việc nhóm tốt'', ''Chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '5 ngày/tuần', '[''Môi trường làm việc chuyên nghiệp, năng động và hiệu quả'', ''Cơ hội thăng tiến cao'', ''Phụ cấp tiền thực tập nếu làm tốt'', ''Hỗ trợ lịch học + dấu mộc làm báo cáo (nếu cần)'', ''Cơ hội trở thành nhân viên chính thức sau thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (642, 10, 9, 'Thực Tập Sinh Quản Trị Nhân Lực', 'Tham gia công tác tuyển dụng: đăng tin, thu CV, lọc hồ sơ, hẹn lịch phỏng vấn và follow ứng viên trong suốt quá trình. Tiếp nhận kết quả từ các bộ phận, thông báo kết quả cho ứng viên. Hỗ trợ xây dựng thương hiệu tuyển dụng cho HR, tập đoàn. Cập nhật và quản lý CV, hồ sơ nhân sự nội bộ. Tham gia vào công tác hành chính nhân sự: mua sắm văn phòng phẩm, cấp phát đồng phục, thẻ nhân sự, làm ĐNTT... Khảo sát và liên hệ các đơn vị cung cấp khi được phân công. Thực hiện các công việc khác theo phân công của leader.', 'Sinh viên các ngành Quản trị nhân lực, Quản trị văn phòng, văn thư lưu trữ, ngôn ngữ,... Chủ động, ham học hỏi, cẩn thận và có tinh thần trách nhiệm trong công việc. Tác phong lịch sự, nhanh nhẹn, tinh tế. Đam mê nghề nhân sự, có mục tiêu công việc cụ thể.
Kỹ năng chuyên môn: [''Microsoft Office (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Chủ động'', ''Ham học hỏi'', ''Cẩn thận'', ''Tinh thần trách nhiệm'', ''Tác phong lịch sự'', ''Nhanh nhẹn'', ''Tinh tế'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Tea-break miễn phí mỗi chiều'', ''Gửi xe miễn phí'', ''Được đào tạo kiến thức và kỹ năng thực tế về ngành Nhân sự'', ''Môi trường làm việc thân thiện, chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức sau khi kết thúc kì thực tập'', ''Tham gia các buổi đào tạo, huấn luyện'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (643, 2, 9, 'Thực Tập Sinh Tuyển Dụng Nhân Sự', 'Hỗ trợ công tác truyền thông tuyển dụng: Đăng tin, tạo nguồn từ đa kênh để thu hút ứng viên tiềm năng. Tiếp nhận các cuộc gọi đến, hướng dẫn ứng viên các thông tin cần thiết; Phỏng vấn và sàng lọc ứng viên qua điện thoại và set up lịch phỏng vấn trực tiếp. Tham gia hỗ trợ trong quá trình phỏng vấn, nhận phản hồi từ ứng viên. Nghiên cứu, đóng góp ý tưởng và cùng bộ phận thực hiện các dự án tạo nguồn ứng viên và xây dựng thương hiệu tuyển dụng.', 'Sinh viên mới tốt nghiệp Cao đẳng, Đại học hoặc sinh viên năm 3,4 (có thể làm fulltime hoặc partime), ưu tiên chuyên ngành Quản trị nhân lực, Quản trị kinh doanh, Kinh tế,... Kỹ năng giao tiếp tốt, chịu được áp lực. Yêu thích tuyển dụng, làm việc với con người. Ưu tiên các bạn có kinh nghiệm tuyển dụng, kinh nghiệm thực tập sinh và định hướng theo nhân sự lâu dài. Có tư duy lên kế hoạch, sáng tạo, biết thiết kế ảnh, video là một lợi thế.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Chịu được áp lực'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Cơ hội trở thành nhân viên chính thức'', ''Môi trường làm việc thân thiện, cởi mở, chuyên nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (644, 3, 9, 'Thực Tập Sinh', 'Thực hiện các công tác về tuyển dụng nhân sự. Đăng tin tuyển dụng lên các trang web, mạng xã hội. Liên hệ trao đổi, sàng lọc hồ sơ, hẹn lịch phỏng vấn. Tham gia đào tạo, hướng dẫn hội nhập nhân viên mới. Hỗ trợ tổ chức và tham gia các chương trình Ngày hội tuyển dụng tại Trường ĐH/CĐ. Hỗ trợ các công việc hành chính khác theo yêu cầu.', 'Sinh viên năm 3- 4 chuyên ngành Kinh tế, Quản trị nhân lực, Quản trị kinh doanh, Luật, Quản trị văn phòng... Ưu tiên ứng viên có định hướng phát triển về Tuyển dụng nhân sự. Nhiệt tình, năng động, sáng tạo trong công việc. Ưu tiên ứng viên có thể nhận việc ngay.
Kỹ năng mềm: [''Nhiệt tình'', ''Năng động'', ''Sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Được hướng dẫn, đào tạo bài bản về công tác tuyển dụng nhân sự'', ''Được hỗ trợ số liệu làm khóa luận, đóng mộc thực tập'', ''Tích lũy kinh nghiệm thực tế tại Doanh nghiệp'', ''Định hướng phát triển nghề nghiệp trong tương lai'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (645, 7, 9, 'Thực Tập Sinh Nhân Sự', '_**Sở hữu hơn 4 thương hiệu nhà hàng bao gồm nhãn Bò Tơ Quán Mộc, Bánh Tráng An Vũ, Lẩu Hấp Thủy Nhiệt HongKong LongWang, Lẩu Bò Tươi Triều Châu Tian Long,... Công ty Aladdin đang ngày càng mở rộng phát triển và phủ khắp khu vực TP Hồ Chí Minh. Căn cứ vào nhu cầu phát triển kinh doanh 2025, Aladdin chiêu mộ các vị trí kế toán Kho ,.... để đồng hành và phát triển vượt bậc cùng Aladdin.**_ * Hỗ trợ tìm nguồn, đăng bài tuyển dụng vào các group online. * Nhập thông tin ứng viên lên data ứng tuyển. * Liên hệ với ứng viên thông báo thời gian/kết quả phỏng vấn khối Nhà hàng. * Hỗ trợ sắp xếp và kiểm tra hồ sơ nhân viên nhận việc. * Hỗ trợ tạo dấu vân tay cho nhân viên mới nhận việc. * Hỗ trợ công tác phỏng vấn tập trung. * Hỗ trợ chăm sóc Fanpage Tuyển dụng, thiết kế content/ hình ảnh.', 'Đang học tại các trường chuyên ngành Quản trị nguồn nhân lực, Luật, Quản trị kinh doanh … Yêu thích công việc nhân sự Chịu khó, ham học hỏi Không yêu cầu kinh nghiệm
Kỹ năng mềm: [''Chịu khó'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 - 3.7 triệu', 'Giờ hành chính (8h00 – 12h00; 13h00 – 17h00), nghỉ chiều Thứ 7 & Chủ Nhật.', '[''Phụ cấp ăn trưa: 730.000 đồng/tháng'', ''Bảo hiểm xã hội'', ''Thưởng tháng 13'', ''Team building'', ''Du lịch hàng năm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (646, 8, 9, 'Chuyên Viên Tuyển Dụng', 'Tiếp nhận các đề nghị tuyển dụng của các phòng ban được phân giao, nhập đề nghị tuyển dụng lên phần mềm nhân sự HRM và chủ động lập kế hoạch tuyển dụng. Đăng tuyển, tìm kiếm nguồn ứng viên qua các kênh đăng tuyển, các website, diễn đàn, các trung tâm giới thiệu việc làm, hội chợ việc làm ... Cập nhật và quản lý các file thông tin ứng viên, lọc xét hồ sơ ứng viên, điều phối việc sắp xếp bố trí phỏng vấn. Tham gia phỏng vấn ứng viên cùng các phòng ban chuyên môn. Thông báo kết quả phỏng vấn, gửi thư mời làm việc cho ứng viên trúng tuyển. Chuẩn bị các công việc tiếp nhận nhân viên mới. Báo cáo/phân tích theo định kỳ kết quả tuyển dụng và đề xuất cải tiến quy trình làm việc để đảm bảo hiệu quả công việc. Làm hồ sơ thanh toán các chế độ liên quan đến tuyển dụng.', 'Tốt nghiệp Đại học trở lên các chuyên ngành: Quản trị nhân lực, kinh tế lao động, quản trị kinh doanh hoặc các ngành có liên quan. Có kinh nghiệm từ 6 tháng trở lên ở vị trí tương đương. Có kinh nghiệm tuyển mass/ kinh doanh. Có hiểu biết về việc xây dựng, phát triển và dự trữ nguồn. Kỹ năng giao tiếp, đàm phán tốt. Có kỹ năng nhìn nhận và đánh giá con người. Khả năng xử lý tình huống. Sử dụng thành thạo các phần mềm tin học văn phòng. Nhanh nhẹn, chịu khó, cẩn thận. Chịu được áp lực công việc.
Kỹ năng chuyên môn: [''Sử dụng thành thạo các phần mềm tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng đàm phán'', ''Kỹ năng nhìn nhận và đánh giá con người'', ''Khả năng xử lý tình huống'', ''Nhanh nhẹn'', ''Chịu khó'', ''Cẩn thận'', ''Chịu được áp lực công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:45)', '[''Ký hợp đồng dịch vụ CTV (6 tháng)'', ''Làm việc trong môi trường chuyên nghiệp, có hướng dẫn cụ thể'', ''Được tham gia các buổi đào tạo nội bộ, chia sẻ kinh nghiệm thực tế'', ''Hưởng các phúc lợi theo quy định dành cho CTV (phụ cấp, tham gia hoạt động nội bộ...)'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (647, 9, 9, 'Thực Tập Sinh Nhân Sự', 'Thực hiện công việc hành chính (VPP, Văn thư, Giao nhận bưu phẩm,…) Phối hợp tuyển dụng các vị trí Văn phòng và nhà máy Hỗ trợ thực hiện hội nhập nhân sự mới Lưu trữ giấy tờ, hồ sơ nhân sự,… Các công việc khác theo yêu cầu quản lý', 'Có thể làm được 5 ngày/tuần Sinh viên từ năm 2 trở đi Nhiệt tình, chịu khó và chăm chỉ trong công việc Có định hướng phát triển theo ngành nhân sự
Kỹ năng chuyên môn: [''Microsoft Office (word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng làm việc nhóm'', ''Khả Năng Học Hỏi Nhanh'', ''Kỹ Năng Tổ Chức Và Lập Kế Hoạch'']', 'INTERNSHIP', 'ONSITE', 'quận 3', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '0.5 - 1.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được đào tạo bài bản để hoàn thành công việc'', ''Hướng dẫn công việc tận tình'', ''Cung cấp trang thiết bị làm việc'', ''Môi trường làm việc chuyên nghiệp, năng động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (648, 10, 9, 'Thực Tập Sinh Nhân Sự', 'Hỗ trợ cập nhật và theo dõi dữ liệu chấm công, phép năm, tăng ca, nghỉ việc,… của nhân viên. Hỗ trợ tính lương, phụ cấp, các khoản thưởng – phạt theo quy định nội bộ. Hỗ trợ soạn thảo, lưu trữ và quản lý các văn bản hành chính liên quan đến quan hệ lao động: hợp đồng lao động, quyết định điều chuyển, nghỉ việc,... Hỗ trợ theo dõi, nhắc nhở ký kết, gia hạn HĐLĐ và cập nhật hồ sơ nhân viên. Tìm hiểu và cập nhật các quy định pháp luật về lao động, bảo hiểm,... để hỗ trợ đảm bảo tính tuân thủ trong công việc. Phối hợp tổ chức các hoạt động nội bộ, phổ biến nội quy, văn hóa công ty tới nhân sự. Các công việc hành chính nhân sự khác theo sự phân công của quản lý.', 'Sinh viên năm 4 hoặc mới tốt nghiệp các ngành: Quản trị nhân lực, Luật, Kinh tế, Hành chính,... Có định hướng phát triển nghề nghiệp trong lĩnh vực C&B hoặc Quan hệ lao động. Tỉ mỉ, cẩn thận, yêu thích làm việc với số liệu và quy trình. Có tinh thần trách nhiệm, chủ động trong công việc. Sử dụng tốt Word, Excel (biết dùng hàm cơ bản là một lợi thế). Ưu tiên ứng viên có hiểu biết sơ bộ về Luật Lao động hoặc Bảo hiểm xã hội.
Kỹ năng chuyên môn: [''Sử dụng tốt Word'', ''Excel (biết dùng hàm cơ bản là một lợi thế)'']
Kỹ năng mềm: [''Tỉ mỉ'', ''Cẩn thận'', ''Yêu thích làm việc với số liệu và quy trình'', ''Có tinh thần trách nhiệm'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được đào tạo thực tế về các nghiệp vụ C&B, quan hệ lao động trong doanh nghiệp'', ''Có cơ hội tiếp cận quy trình tính lương, xử lý chế độ và hợp đồng lao động'', ''Làm việc trong môi trường chuyên nghiệp, thân thiện và hỗ trợ'', ''Có xác nhận thực tập và cơ hội trở thành nhân viên chính thức nếu phù hợp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (649, 2, 9, 'Thực Tập Sinh Sale Admin', 'Hỗ trợ các công việc (làm báo giá, soạn hợp đồng,...) của Trung tâm Kinh doanh. Theo dõi quản lí quá trình nghiệm thu, bàn giao, thanh toán đối với các hợp đồng đã ký. Follow việc hoàn thực hiện KPI của NVKD. Hỗ trợ Sales chuẩn bị tài liệu gặp khách hàng. Nhắc nhở và tổng hợp báo cáo tuần của các nhân viên trong Trung tâm KD. Công việc khác theo sự chỉ đạo của Quản lý: thông báo đào tạo, tham gia họp và soạn thảo biên bản cuộc họp.', 'Giới tính: Nữ. Sinh viên năm 2, năm 3, chưa tốt nghiệp. Có kỹ năng làm PPT, tài liệu bán hàng, báo cáo chỉn chu. Có kỹ năng lập báo cáo, tiến độ, kế hoạch thực hiện dự án. Cẩn thận, tỉ mỉ và có trách nhiệm. Kỹ năng giao tiếp tốt, hướng ngoại, cầu tiến. Có thái độ tích cực, tư duy tiến bộ, định hướng phát triển bản thân lâu dài.
Kỹ năng chuyên môn: [''Kỹ năng làm PPT'', ''Kỹ năng lập báo cáo'', ''Kỹ năng tiến độ'', ''Kỹ năng kế hoạch thực hiện dự án'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Có trách nhiệm'', ''Kỹ năng giao tiếp tốt'', ''Hướng ngoại'', ''Cầu tiến'', ''Thái độ tích cực'', ''Tư duy tiến bộ'', ''Định hướng phát triển bản thân lâu dài'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được làm việc cùng đội ngũ nhân viên nhiệt huyết, sáng tạo, hòa đồng'', ''Cơ hội đào tạo chuyên nghiệp, học hỏi và trải nghiệm các nghiệp vụ thực tế, phát triển chuyên môn cá nhân'', ''Được tham gia các hoạt động văn hóa, phong trào, sự kiện nổi bật của công ty'', ''Hỗ trợ dấu mộc và chữ ký cho giấy xác nhận thực tập và báo cáo thực tập'', ''Được đăng ký lịch làm việc linh hoạt, phù hợp với lịch học'', ''Xem xét hỗ trợ lương nếu làm tốt công việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (650, 3, 9, 'Thực Tập Sinh Tuyển Dụng', 'Hỗ trợ công tác tuyển dụng các vị trí tại công ty. Liên hệ, sắp xếp lịch phỏng vấn, thông báo kết quả tuyển dụng. Tham gia tổ chức các chương trình nhằm xây dựng thương hiệu tuyển dụng. Một số công việc khác theo phân công của bộ phận.', 'Là sinh viên năm cuối, hoặc vừa mới ra trường chuyên ngành Nhân sự, Quản trị nguồn nhân lực, kinh tế nguồn nhân lực... Định hướng lâu dài mong muốn gắn bó với tuyển dụng, nhân sự. Chăm chỉ, nhiệt tình, ham học hỏi. Ưu tiên ứng viên có kinh nghiệm tuyển dụng. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Sử dụng laptop'']
Kỹ năng mềm: [''Chăm chỉ'', ''Nhiệt tình'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ dấu thực tập'', ''Có lương hỗ trợ thực tập'', ''Môi trường làm việc hòa đồng, trẻ trung, linh hoạt'', ''Được đào tạo nâng cao kỹ năng, kiến thức nghiệp vụ ngành tuyển dụng'', ''Tham gia teambuilding, teamdinner và các buổi liên hoan, du lịch cùng phòng'', ''Có cơ hội trở thành nhân viên chính thức sau 2-3 tháng'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (651, 7, 9, 'Thực Tập Sinh L&D', 'Hỗ trợ xây dựng và phát triển nội dung chương trình đào tạo liên quan đến lĩnh vực Công nghệ Thông tin. Tham gia tổ chức, điều phối các buổi đào tạo dành cho nhân viên và đối tác (online/offline). Chuẩn bị tài liệu đào tạo, bài giảng, bài tập thực hành theo yêu cầu. Cập nhật và quản lý dữ liệu đào tạo: tài liệu, nội dung giảng dạy và thông tin học viên. Phối hợp với các bộ phận khác để triển khai hoạt động đào tạo hiệu quả. Thực hiện các nhiệm vụ khác theo sự phân công của phòng L&D.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các chuyên ngành: Quản trị Kinh doanh, Nhân sự, hoặc các ngành liên quan. Có kiến thức cơ bản về CNTT và phần mềm phục vụ đào tạo (Google Workspace, Microsoft Office, LMS là một lợi thế). Giao tiếp tốt, cởi mở, thân thiện, có khả năng làm việc nhóm. Ham học hỏi, tinh thần chủ động và cầu tiến trong công việc. Có thể sử dụng tiếng Anh cơ bản trong công việc (đọc hiểu tài liệu, viết email đơn giản...).
Kỹ năng chuyên môn: [''Kiến thức cơ bản về CNTT'', ''Google Workspace'', ''Microsoft Office'', ''LMS'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Cởi mở'', ''Thân thiện'', ''Khả năng làm việc nhóm'', ''Ham học hỏi'', ''Tinh thần chủ động'', ''Cầu tiến trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Trợ cấp thực tập hàng tháng'', ''Hỗ trợ vé gửi xe tháng tại văn phòng'', ''Cung cấp thiết bị làm việc (laptop/PC)'', ''Được đào tạo bài bản'', ''Môi trường làm việc trẻ trung, thân thiện'', ''Cơ hội trở thành nhân viên chính thức nếu thể hiện tốt'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (652, 8, 9, 'Sales & Admin Intern', 'Xác định và tiếp cận khách hàng tiềm năng; Tham khảo ý kiến ​​về các sản phẩm/dịch vụ phần mềm của công ty; Lịch trình các cuộc họp với khách hàng (trực tuyến/ngoại tuyến), tham gia các bản trình diễn sản phẩm, lắng nghe nhu cầu của họ và phối hợp với nhóm kỹ thuật để đề xuất các giải pháp phù hợp; Cập nhật thông tin khách hàng và các hoạt động bán hàng trong hệ thống nội bộ; Hỗ trợ việc thực hiện các chiến dịch tiếp cận khách hàng theo hướng dẫn; Hoạt động như một cầu nối giữa khách hàng và nhóm kỹ thuật khi cần có các giải pháp kỹ thuật. Chuẩn bị báo giá, hợp đồng và thư cung cấp bằng cách sử dụng các mẫu có sẵn; Hỗ trợ chuẩn bị báo cáo bán hàng hàng tuần/hàng tháng để quản lý; Giám sát tiến độ thanh toán và hỗ trợ trong việc nhắc nhở khách hàng hoàn thành các thủ tục cần thiết nếu cần; Phối hợp với các bộ phận nội bộ để xử lý các đơn đặt hàng và cung cấp hỗ trợ sau bán hàng.', 'Good command in English is a plus. Student (4 years) or fresh graduate majoring in Sales, Advertising, Marketing, Business, or related majors abroad. Knowledge about information technology is a plus. Strong self-motivation. Ability to work alone or as part of a team. Excellent communication skills. Ability to remain calm in fast-paced environments. Agility, hard work, enthusiasm. (If you do not have these experience but eager to learn, please do not hesitate to apply)
Kỹ năng chuyên môn: [''Knowledge about information technology'']
Kỹ năng mềm: [''Strong self-motivation'', ''Ability to work alone or as part of a team'', ''Excellent communication skills'', ''Ability to remain calm in fast-paced environments'', ''Agility'', ''Hard work'', ''Enthusiasm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Internship Allowance: 1,000,000 VND/month'', ''Support: Company stamp and official data for reports'', ''Training: Comprehensive training with dedicated mentorship'', ''Working Environment: Dynamic and creative workplace'', ''Engagement: team-building activities, happy hours, and team fund'', ''Perks: Birthday gift from the company'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (653, 9, 9, 'Thực Tập Sinh Tuyển Dụng', 'Hỗ trợ đăng tin tuyển dụng trên các kênh: mạng xã hội, website tuyển dụng, nội bộ,... Sàng lọc hồ sơ ứng viên theo yêu cầu từng vị trí. Hẹn lịch phỏng vấn, gửi thư mời và hỗ trợ tổ chức phỏng vấn. Cập nhật và quản lý dữ liệu ứng viên trên hệ thống hoặc file theo dõi. Hỗ trợ xây dựng thương hiệu tuyển dụng: thiết kế bài đăng, hỗ trợ tổ chức sự kiện tuyển dụng,... Thực hiện các công việc hành chính liên quan đến tuyển dụng (hợp đồng, offer, hồ sơ,...). Hỗ trợ các công việc khác theo yêu cầu của cấp trên.', 'Sinh viên năm 3 hoặc năm cuối các ngành: Quản trị Nhân sự, Kinh tế, Quản trị Kinh doanh, Tâm lý học hoặc các ngành liên quan. Kỹ năng giao tiếp và làm việc nhóm tốt. Cẩn thận, chủ động và có trách nhiệm trong công việc. Có mong muốn học hỏi và phát triển trong lĩnh vực nhân sự. Thành thạo tin học văn phòng (Word, Excel, Google Sheets,...). Ưu tiên ứng viên có thể thực tập tối thiểu 3 tháng.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, Google Sheets)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Làm việc nhóm'', ''Cẩn thận'', ''Chủ động'', ''Có trách nhiệm trong công việc'', ''Mong muốn học hỏi và phát triển trong lĩnh vực nhân sự'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Cơ hội học hỏi và trải nghiệm công việc với môi trường năng động và sáng tạo'', ''Hỗ trợ chi phí đi lại'', ''Hỗ trợ ký báo cáo thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (654, 10, 9, 'Thực Tập Sinh Nhân Sự', 'Hỗ trợ các công việc của bộ phận Hành chính. Chịu trách nhiệm quản lý con dấu, trực tiếp thực hiện việc đóng dấu. Hỗ trợ các phần hành về lương, chấm công cho bộ phận C&B. Hỗ trợ lưu trữ toàn bộ hệ thống công văn, giấy tờ, hợp đồng lao động, hồ sơ nhân sự và các tài liệu liên quan.', 'Yêu thích và có định hướng theo mảng Nhân sự. Sinh viên các trường Cao Đẳng, Đại Học... hoặc vừa tốt nghiệp. Backgroud tham gia các CLB khi còn sinh viên, sôi nổi. Thái độ cởi mở, ham học hỏi, tỉ mỉ. Tinh thần nhiệt huyết, thể hiện sự năng động của thế hệ gen Z.
Kỹ năng chuyên môn: [''Microsoft Office (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Quản lý thời gian'', ''Giao tiếp'', ''Tổ chức'', ''Sắp xếp'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6', '[''Được hướng dẫn và đào tạo công việc thực tế của team'', ''Trải nghiệm môi trường làm việc trẻ trung, năng động'', ''Hỗ trợ xác nhận thực tập và cân nhắc lên các vị trí khác trong tương lai'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (655, 2, 9, 'Nhân Viên Tuyển Dụng Tài Xế ShopeeFood (Thời Vụ)', 'Hỗ trợ đối tác tài xế trong quá trình hợp tác, bao gồm tư vấn, xác minh hồ sơ,... cho đến khi trở thành tài xế chính thức. Thu thập và đánh giá thông tin ứng viên thông qua nhiều kênh truyền thông, bao gồm cuộc gọi khảo sát, Gmail, SMS và Zalo. Triển khai hoạt động tuyển dụng trực tuyến: đăng tin tuyển dụng, seeding trên mạng xã hội và truyền thông các chương trình ưu đãi/chính sách hoạt động trên Zalo OA. Đảm bảo kiểm soát tuân thủ quy trình tuyển dụng tài xế theo quy định của công ty. Phối hợp với các bộ phận liên quan theo phân công và hỗ trợ các nhiệm vụ khác theo yêu cầu của quản lý.', 'Tốt nghiệp Cao đẳng trở lên. Có ít nhất 6 tháng kinh nghiệm trong lĩnh vực tuyển dụng, đặc biệt là tuyển dụng số lượng lớn (mass hiring) hoặc hỗ trợ khách hàng, là một lợi thế lớn. Thành thạo các công cụ Microsoft Office (đặc biệt là Google Sheets); quen thuộc với Zalo OA là một điểm cộng. Tỉ mỉ, có tổ chức; kỹ năng giao tiếp và giải quyết vấn đề tốt. Chủ động, ham học hỏi và có khả năng xử lý nhiều công việc cùng lúc trong môi trường nhịp độ nhanh.
Kỹ năng chuyên môn: [''Microsoft Office'', ''Google Sheets'', ''Zalo OA'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Giải quyết vấn đề'', ''Tỉ mỉ'', ''Có tổ chức'', ''Chủ động'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 12000000.00, '12.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Bảo hiểm xã hội'', ''Phụ cấp thâm niên'', ''Thưởng hiệu quả làm việc'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (656, 3, 9, 'Thực Tập Sinh Nhân Sự', 'Phụ trách công tác về TẠO NGUỒN tuyển dụng (Lao động phổ thông). Viết bài chuẩn SEO đăng lên website + fanpage. Phân tích đánh giá hiệu quả của nguồn tuyển dụng. Liên hệ, trao đổi công việc cùng với Người Lao Động. Xử lý các công việc phát sinh liên quan đến tạo nguồn được phân công bởi quản lý.', 'Nam/nữ sinh năm 2002 - 2006, là sinh viên hoặc tốt nghiệp/đang chờ bằng CĐ, ĐH. Có tinh thần học hỏi cao, chăm chỉ, biết tiếp thu ý kiến. Có đam mê thực sự với Ngành Nhân sự và mong muốn làm việc với con người. Có laptop cá nhân để làm việc. Không yêu cầu kinh nghiệm.
Kỹ năng chuyên môn: [''Viết bài chuẩn SEO'']
Kỹ năng mềm: [''Tinh thần học hỏi cao'', ''Chăm chỉ'', ''Biết tiếp thu ý kiến'', ''Đam mê ngành Nhân sự'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '2.5 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Phụ cấp thực tập'', ''Thưởng KPI (tb 5-8tr)'', ''Được training, đào tạo bài bản (1:1 và theo nhóm)'', ''Có cơ hội trở thành nhân viên chính thức sau 3 – 6 tháng'', ''Được hỗ trợ dấu mộc, phiếu đánh giá thực tập'', ''Được hỗ trợ ăn trưa miễn phí tại công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (657, 7, 9, 'Thực Tập Sinh - Nhân Sự Tuyển Dụng', 'Trực tiếp tham gia công tác tuyển dụng các vị trí Lao động phổ thông: shipper, tài xế, nhân viên kho thông qua việc: Tìm kiếm, tạo nguồn ứng viên đa kênh để thu hút ứng viên tiềm năng; Tư vấn, giải đáp các vấn đề thắc mắc của ứng viên; Xây dựng nội dung tuyển dụng trên Tiktok, Page FB từng địa phương; Liên hệ phỏng vấn và setup phỏng vấn trực tiếp ứng viên; Phỏng vấn/sơ vấn ứng viên.', 'Chưa có kinh nghiệm sẽ được đào tạo bài bản, được quan sát, tìm hiểu sâu công việc của vị trí phụ trách. Có cơ hội để phát huy tối đa năng lực của bản thân qua các thử thách cá nhân, đội nhóm. Phẩm chất tốt, có trách nhiệm và chịu áp lực cao trong công việc. Có máy tính cá nhân phục vụ công việc.
Kỹ năng mềm: [''Tinh tế'', ''Khéo léo'', ''Khả năng kết nối tốt'', ''Ham học hỏi'', ''Khả năng tự học hỏi tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 9000000.00, '2.5 - 9.0 triệu', '08h00-17h30 từ T2 đến T7, nghỉ 1h30', '[''Được đào tạo bài bản'', ''Cơ hội trở thành nhân viên chính thức tại công ty sau 3 - 6 tháng thực tập'', ''Môi trường trẻ trung, năng động, đa bản sắc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (658, 8, 9, 'Thực Tập Sinh Nhân Sự - Có Hưởng Lương', 'Hỗ trợ bộ phận nhân sự trong các hoạt động tuyển dụng: đăng tin tuyển dụng, sàng lọc CV, liên hệ ứng viên. Tham gia tổ chức phỏng vấn và đánh giá ứng viên. Hỗ trợ xây dựng và duy trì cơ sở dữ liệu ứng viên. Truyền thông nội bộ: quản lý fanpage, kênh truyền thông nội bộ của công ty, tổ chức các chương trình. Công việc khác theo yêu cầu của Quản lý.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các ngành liên quan đến Quản trị Nhân sự, Quản trị Kinh doanh, Tâm lý học, hoặc các ngành có liên quan. Có đam mê và quan tâm đến lĩnh vực tuyển dụng, quản trị nhân sự trong ngành công nghệ. Kỹ năng giao tiếp tốt, trung thực, cẩn thận, chủ động trong công việc. Sử dụng thành thạo các công cụ tin học văn phòng (Word, Excel, PowerPoint).
Kỹ năng chuyên môn: [''Sử dụng thành thạo các công cụ tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Trung thực'', ''Cẩn thận'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được làm việc trong môi trường công nghệ tiên tiến và được trao quyền phát triển bản thân'', ''Được đào tạo bài bản về quy trình tuyển dụng và quản trị nhân sự hiện đại'', ''Môi trường làm việc năng động, thân thiện, nhiều cơ hội học hỏi và phát triển'', ''Ăn sáng, pantry trà chiều miễn phí tại công ty'', ''Được hưởng các chế độ ngày lễ, tết theo quy định của nhà nước'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (659, 9, 9, 'Cộng Tác Viên Đánh Máy', 'Nhập liệu và xử lý dữ liệu văn bản theo đúng yêu cầu và định dạng chuẩn do công ty cung cấp. Đánh máy các loại hồ sơ, văn bản hành chính, tài liệu dịch thuật,... đảm bảo chính xác, đúng thời hạn. Lưu trữ, sắp xếp và quản lý dữ liệu trên hệ thống nội bộ một cách khoa học và bảo mật. Phối hợp với các bộ phận liên quan để đảm bảo tiến độ và chất lượng công việc được giao.', 'Có kỹ năng đánh máy nhanh, thao tác chuẩn xác, thành thạo bàn phím máy tính. Sử dụng thành thạo các công cụ văn phòng như Microsoft Word, Excel; đặc biệt có khả năng định dạng văn bản chuyên nghiệp, trình bày sạch sẽ, khoa học. Ưu tiên ứng viên có kinh nghiệm nhập liệu, hành chính văn phòng hoặc từng làm trong lĩnh vực dịch thuật, lưu trữ hồ sơ. Trung thực, chăm chỉ, có tinh thần học hỏi, trách nhiệm cao trong công việc, phối hợp tốt với quản lý và đồng nghiệp. Tốt nghiệp Trung cấp trở lên.
Kỹ năng chuyên môn: [''Sử dụng Microsoft Word'', ''Sử dụng Microsoft Excel'', ''Đánh máy nhanh'']
Kỹ năng mềm: [''Trung thực'', ''Chăm chỉ'', ''Có tinh thần học hỏi'', ''Trách nhiệm cao'', ''Phối hợp tốt với quản lý và đồng nghiệp'']', 'FREELANCE', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Làm việc Online, không gò bó thời gian', '[''Làm việc online tại nhà, linh hoạt thời gian'', ''Thu nhập cạnh tranh'', ''Thưởng hàng tháng'', ''Cơ hội học hỏi và rèn luyện kỹ năng hành chính – văn phòng'', ''Môi trường làm việc thân thiện'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (660, 10, 9, 'Nhân viên tuyển dụng thực tập (toàn thời gian/bán thời gian)', 'Nguồn và xác định các ứng cử viên tiềm năng trên các nền tảng trực tuyến khác nhau (LinkedIn, bảng công việc, phương tiện truyền thông xã hội, v.v.). Hỗ trợ nhóm tuyển dụng trong việc tổ chức và lập lịch phỏng vấn. Hỗ trợ nhóm tuyển dụng trong việc điều phối quá trình tuyển dụng, bao gồm lập lịch phỏng vấn và liên lạc với các ứng viên.', 'Third-year or final-year students in Human Resources, Business Administration, Economics, or related fields. Experience with recruitment websites is a plus. Proficient in English is required. Strong interest in talent acquisition and recruitment processes. Excellent communication and interpersonal skills.
Kỹ năng chuyên môn: [''Experience with recruitment websites'']
Kỹ năng mềm: [''Proficient in English'', ''Strong interest in talent acquisition and recruitment processes'', ''Excellent communication and interpersonal skills'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Monday - Friday (from 08:30 to 18:00)', '[''Hands-on experience in candidate sourcing and recruitment'', ''A dynamic, collaborative working environment'', ''Off every Saturday and Sunday'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (661, 2, 9, 'Thực Tập Sinh Nhân Sự', 'Hỗ trợ tuyển dụng, đăng bài, tìm kiếm, liên hệ ứng viên, set up phỏng vấn. Hỗ trợ thực hiện các công việc truyền thông nội bộ. Thực hiện các công việc khác theo yêu cầu. Quay dựng clip, content nội dung thu hút tuyển dụng, tạo nguồn ứng viên.', 'Sinh viên các ngành Quản trị nhân sự, Luật, Kinh tế, truyền thông… Sinh viên năm 3 hoặc năm 4, sắp ra trường. Tinh thần học hỏi và phát triển bản thân. Có kĩ năng sử dụng các công cụ hỗ trợ như chat GPT, Canva, Capcut…
Kỹ năng chuyên môn: [''Sử dụng các công cụ hỗ trợ như chat GPT, Canva, Capcut'']
Kỹ năng mềm: [''Tinh thần học hỏi'', ''Phát triển bản thân'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 1000000.00, '1.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Được hướng dẫn công việc và làm việc trong môi trường chuyên nghiệp.'', ''Cơ hội trở thành nhân viên chính thức.'', ''Phụ cấp ăn trưa'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (662, 3, 14, 'Thực Tập Sinh Nhân Sự - C&B Intern', '- Kiểm tra và lưu trữ hồ sơ đầu vào của nhân viên mới. - Phụ trách quản lý và cập nhật hồ sơ nhân viên. - Hỗ trợ công tác làm hồ sơ BHXH/ thuế (đăng ký mst) của nhân viên. - Hỗ trợ làm bộ hồ sơ thanh tra và các công việc admin khác (tra cứu, công chứng hồ sơ,...) - Các công việc C&B liên quan khác theo chỉ dẫn của quản lý trực tiếp.', '- Chủ động trong công việc và ham học hỏi - Tư duy mở, có khả năng làm việc độc lập và quản lý thời gian tốt - Có trách nhiệm trong công việc, cẩn thận, tỉ mỉ là một lợi thế - Ưu tiên ứng viên có thể làm việc 3 – 6 tháng (ưu tiên ứng viên có thể làm 6 tháng)
Kỹ năng mềm: [''Chủ động trong công việc'', ''Tư duy mở'', ''Có khả năng làm việc độc lập'', ''Quản lý thời gian tốt'', ''Có trách nhiệm trong công việc'', ''Cẩn thận'', ''Tỉ mỉ'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ Hai đến Thứ Sáu, từ 9:00 đến 18:00', '[''Có trợ cấp thực tập'', ''Được hướng dẫn và đào tạo bài bản các kỹ năng trong công việc C&B'', ''Làm việc trong môi trường chuyên nghiệp, năng động'', ''Cơ hội phát triển nghề nghiệp tại Apollo English'', ''Được cấp laptop làm việc'', ''Hỗ trợ xác nhận thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (663, 7, 14, 'Thực Tập Sinh Kế Toán', 'Sắp xếp chứng từ, Kiểm tra tính hợp lệ của chứng từ kế toán lên bảng kê hóa đơn, Nhập liệu hóa đơn, chứng từ vào phần mềm kế toán, In sổ, đóng sổ sách kế toán.', 'Sinh viên năm 4 chuyên ngành kế toán, kiểm toán. Trung thực, nhiệt tình, chịu được áp lực công việc, ý thức kỷ luật tốt. Khả năng làm việc độc lập, làm việc nhóm- Tư duy logic tốt. Kỹ năng giao tiếp tốt, trình bày vấn đề rõ ràng, mạch lạc. Thành thao tin học văn phòng.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Trung thực'', ''Nhiệt tình'', ''Chịu được áp lực công việc'', ''Ý thức kỷ luật tốt'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Tư duy logic tốt'', ''Kỹ năng giao tiếp tốt'', ''Trình bày vấn đề rõ ràng, mạch lạc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Thực tập trong môi trường kế toán chuyên nghiệp'', ''Hỗ trợ học lên tờ khai thuế GTGT'', ''Được ưu tiên giới thiệu tuyển dụng cho khách hàng của Công ty'', ''Nếu tốt sẽ được giữ lại công ty làm việc chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (664, 8, 14, 'Nhân Viên Kế Toán Thời Vụ', '1. Quản lý công nợ: Theo dõi, đối chiếu công nợ với khách hàng, nhà cung cấp định kỳ. Lập báo cáo công nợ, cảnh báo nợ quá hạn và đề xuất biện pháp thu hồi. Phối hợp với bộ phận liên quan giải quyết các vấn đề phát sinh về công nợ. 2. Xử lý chứng từ: Kiểm tra tính hợp lệ, hợp pháp của hóa đơn, chứng từ đầu vào/đầu ra. 3. Nhập liệu, sắp xếp và lưu trữ chứng từ theo quy định. Thực hiện các nhiệm vụ khác theo yêu cầu của cấp trên. 4. Lập báo cáo thuế GTGT, báo cáo tạm tính thuế (nếu được phân công). 5. Công việc khác: Sao lưu dữ liệu, in ấn tài liệu theo yêu cầu. Phối hợp với các phòng ban liên quan để cung cấp thông tin kế toán.', '1. Tốt Nghiệp cao đẳng hoặc đại học 2. Kỹ năng giao tiếp tốt 3. Có hiểu biết cơ bản về kế toán, thuế, chứng từ. ưu tiên cho người có kinh nghiệm 4. Thành thạo Excel và các phần mềm văn phòng 5. Cần người cận thận, siêng năng, nhảy bén.
Kỹ năng chuyên môn: [''Thành thạo Excel'', ''Có hiểu biết cơ bản về kế toán, thuế, chứng từ'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Cẩn thận'', ''Siêng năng'', ''Nhạy bén'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '6.5 - 8.0 triệu', 'Thứ 2 - Thứ 7 (từ 07:30 đến 16:30), Thứ 7 làm 1/2 ngày', '[''Có bảo hiểm 24/24'', ''Hỗ trợ phụ cấp cơm'', ''Hỗ trợ chi phí giao thông nếu ở xa'', ''Lương thưởng cạnh tranh'', ''Môi trường làm việc chuyên nghiệp, cơ hội phát triển nghề nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (665, 9, 14, 'Kế Toán Bán Hàng', 'Lập hóa đơn bán hàng và gửi hóa đơn cho khách hàng; Kiểm tra thông tin và phê duyệt đơn hàng; Cập nhật thông tin liên quan đến khách hàng, đơn hàng lên phần mềm; Cập nhật doanh số mỗi tuần và mỗi tháng; Lưu hóa đơn, chứng từ; Hỗ trợ kiểm kho hàng tháng; Các công việc liên quan theo chỉ đạo của cấp trên.', 'Tốt nghiệp cao đẳng trở lên, chuyên ngành Kế toán; Từ 6 tháng – 1 năm kinh nghiệm tại vị trí tương đương; sinh viên mới ra trường sẽ được đào tạo; Nắm được quy định về hóa đơn, chứng từ, thuế GTGT; Kỹ năng sử dụng phần mềm kế toán; Kỹ năng tổng hợp số liệu, phân tích báo cáo; Trung thực, chăm chỉ, cẩn thận, có trách nhiệm; Có khả năng thích ứng nhanh công việc nhanh.
Kỹ năng chuyên môn: [''Kỹ năng sử dụng phần mềm kế toán'', ''Kỹ năng tổng hợp số liệu'', ''Phân tích báo cáo'']
Kỹ năng mềm: [''Trung thực'', ''Chăm chỉ'', ''Cẩn thận'', ''Có trách nhiệm'', ''Có khả năng thích ứng nhanh'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 9000000.00, '7.0 - 9.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:30 đến 12:30)', '[''Được đào tạo kiến thức và kỹ năng chuyên môn'', ''Tham gia BHXH, BHYT, BHTN theo quy định'', ''Cung cấp máy tính xách tay và các trang thiết bị phục vụ công việc'', ''Thưởng lễ Tết'', ''Lương tháng 13'', ''Company trip'', ''Sinh nhật'', ''Các phúc lợi Công đoàn khác'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (666, 10, 14, 'Thực Tập Sinh Kế Toán', 'Thực hiện các công việc liên quan tới nghiệp vụ Kế toán như: Nhập liệu hóa đơn, chứng từ thanh toán, tạm ứng đầu vào; Kiểm tra sổ sách chứng từ thanh toán, tạm ứng; thống kê các hồ sơ thanh toán, tạm ứng, hóa đơn xuất ra cho khách hành; Hỗ trợ các công việc liên quan nhập số liệu kế toán trên phần mềm Kế toán; Kiểm tra chứng từ, hóa đơn hồ sơ thanh toán với khách hàng; Sắp xếp hồ sơ, chứng từ, tài liệu; Thực hiện các công việc khác theo sự phân công, sắp xếp của quản lý.', 'Sinh viên kế toán năm cuối, hoặc mới tốt nghiệp; Không yêu cầu kinh nghiệm; Nhanh nhẹn, chăm chỉ; Sử dụng thành thạo excel; Chịu khó, hòa đồng, có thể tăng ca thêm giờ; Đã từng sử dụng phần mềm kế toán Misa là 1 lợi thế.
Kỹ năng chuyên môn: [''Sử dụng thành thạo excel'', ''Phần mềm kế toán Misa'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chăm chỉ'', ''Chịu khó'', ''Hòa đồng'']', 'INTERNSHIP', 'ONSITE', 'tp đà lạt', NULL, 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Hỗ trợ ăn trưa tại nhà ăn của công ty'', ''Hỗ trợ gửi xe miễn phí tại tầng hầm công ty'', ''Hỗ trợ dấu mộc báo cáo thực tập'', ''Linh hoạt thời gian'', ''Tham gia vào các hoạt động nội bộ như nhân viên chính thức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (667, 2, 14, 'Thực Tập Sinh Kế Toán', 'Hoàn thiện và theo dõi công nợ và hồ sơ thanh toán thu mua với hộ trồng rừng. Hoàn thiện và theo dõi công nợ và hồ sơ với hộ gia công, hộ sản xuất. Hoàn thiện và theo dõi công nợ và hồ sơ thanh toán với người mua, người bán. Thực hiện kê khai và các báo cáo thuế định kỳ tại công ty. Thực hiện hỗ trợ hoàn thuế và quyết toán thuế tại các cty trong hệ thống. Thực hiện các công việc khác do Trưởng bộ phận giao phó.', 'Ứng viên đã tốt nghiệp đại học các ngành kinh tế, tài chính,.... (Ứng viên đã tốt nghiệp và có thể đi làm fulltime). Ưu tiên nam giới. Trung thực, thật thà. Chăm chỉ, chịu khó học hỏi. Có trách nhiệm trong công việc. Có kỹ năng sử dung Word, Exel, PM kế toán.
Kỹ năng chuyên môn: [''Word'', ''Excel'', ''PM kế toán'']
Kỹ năng mềm: [''Trung thực'', ''Chăm chỉ'', ''Chịu khó học hỏi'', ''Có trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Nghỉ luân phiên ngày thứ 7'', ''Nghỉ các chủ nhật hàng tuần'', ''Công ty hỗ trợ ăn trưa tại Văn phòng'', ''Học hỏi kinh nghiệm từ các anh chị đi trước'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (668, 3, 14, 'Nhân Viên Kế Toán Nội Bộ', 'Kiểm tra, đối chiếu, hạch toán các chứng từ kế toán hàng ngày. Theo dõi thu - chi, công nợ, và tồn kho. Quản lý sổ sách và các chứng từ liên quan.', 'Nữ tốt nghiệp Cao đẳng/Đại học chuyên ngành kế toán. Có kinh nghiệm ít nhất 6 tháng - 1 năm ở vị trí tương đương. Sử dụng thành thạo phần mềm kế toán Misa. Am hiểu luật thuế. Cẩn thận, trung thực, có trách nhiệm trong công việc. Kỹ năng giao tiếp tốt. Biết tiếng Anh, tiếng Trung là một lợi thế.
Kỹ năng chuyên môn: [''Phần mềm kế toán Misa'', ''Am hiểu luật thuế'']
Kỹ năng mềm: [''Cẩn thận'', ''Trung thực'', ''Có trách nhiệm trong công việc'', ''Kỹ năng giao tiếp tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 15000000.00, '7.0 - 15.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:30 đến 15:00) và (từ 14:30 đến 21:00), làm việc từ thứ 2 đến chủ nhật, xoay ca. Nghỉ 2 ngày/tháng + mỗi tháng 1 ngày nghỉ phép', '[''Phụ cấp xăng xe'', ''Phụ cấp điện thoại'', ''Đóng bảo hiểm theo luật lao động'', ''Lương tháng 13'', ''Tham gia các hoạt động team building của công ty'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (669, 7, 14, 'Nhân Viên Kế Toán Nội Bộ', '- Kiểm tra, đối chiếu, hạch toán các chứng từ kế toán hàng ngày - Theo dõi thu - chi, công nợ, và tồn kho - Quản lý sổ sách và các chứng từ liên quan', 'Nữ tốt nghiệp Cao đẳng/Đại học chuyên ngành kế toán Có kinh nghiệm ít nhất 6 tháng - 1 năm ở vị trí tương đương Sử dụng thành thạo phần mềm kế toán Misa Am hiểu luật thuế Cẩn thận, trung thực, có trách nhiệm trong công việc Kỹ năng giao tiếp tốt Biết tiếng Anh, tiếng Trung là một lợi thế
Kỹ năng chuyên môn: [''Phần mềm kế toán Misa'', ''Am hiểu luật thuế'']
Kỹ năng mềm: [''Cẩn thận'', ''Trung thực'', ''Có trách nhiệm trong công việc'', ''Kỹ năng giao tiếp tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 15000000.00, '7.0 - 15.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:30 đến 15:00) và (từ 14:30 đến 21:00), nghỉ 2 ngày/tháng + mỗi tháng 1 ngày nghỉ phép', '[''Phụ cấp xăng xe'', ''Cước điện thoại'', ''Đóng bảo hiểm theo luật lao động'', ''Lương tháng 13'', ''Tham gia các hoạt động team building'', ''Du lịch hàng năm'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (670, 8, 14, 'Nhân Viên Kế Toán Thuế', 'Xuất hoá đơn bán hàng hằng ngày, lập tờ khai và nộp thuế TNCN, GTGT hàng tháng, hạch toán chi phí phát sinh hàng tháng lên phần mềm kế toán FAST, cân đối thu chi tiền mặt trên PM kế toán FAST, theo dõi tiền thu chi trên ngân hàng và hạch toán lên PM kế toán FAST, theo dõi và thanh toán công nợ Gia công trụ cho NCC, sắp xếp và lưu trữ chứng từ thuế.', 'Tốt nghiệp cao đẳng trở lên chuyên ngành tài chính - kế toán, kiểm toán. Kinh nghiệm làm việc 1-2 năm trở lên. Ngoại hình dễ nhìn, tác phong nhanh nhẹn. Cẩn thận, siêng và có trách nhiệm trong công việc. Thành thạo vi tính văn phòng: Word, Excel, các phần mềm kế toán, xuất hàng.
Kỹ năng chuyên môn: [''Word'', ''Excel'', ''phần mềm kế toán FAST'']
Kỹ năng mềm: [''Cẩn thận'', ''siêng năng'', ''có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 11000000.00, '10.0 - 11.0 triệu', '8h30 – 17h30 (thứ 2 - thứ 7)', '[''Nhận 100% lương thử việc'', ''Được đào tạo và nâng cao kiến thức chuyên môn'', ''Tham gia các hoạt động khác của Công ty'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (671, 9, 14, 'Kế Toán Bán Hàng-Xuất Hóa Đơn', 'Nhận thông tin và kiểm tra dữ liệu PO từ bộ phận bán hàng. Thực hiện nhập liệu phần mềm: thao tác xuất hóa đơn hàng hóa và phát hành hóa đơn. Tập hợp, thống kê dữ liệu hóa đơn đã phát hành & đã thu hồi theo định kỳ. Thực hiện thao tác kê khai, điều chỉnh, xóa bỏ hóa đơn trên phần mềm hóa đơn điện tử. Thống kê các báo cáo phát sinh liên quan tình hình điều chỉnh và xóa bỏ hóa đơn. Hạch toán và kiểm tra tài khoản hạch toán trong kỳ (đảm bảo tuân thủ chế độ hạch toán kế toán và quy định công ty). Công việc phát sinh liên quan (vd: sắp xếp hồ sơ, chứng từ….)', 'Trình độ: tốt nghiệp Cao đẳng - Đại học chuyên ngành kế toán. Kinh nghiệm: có kinh nghiệm kế toán từ 1 năm trở lên. Kỹ năng: giải quyết tình huống, giao tiếp khá, sử dụng vi tính văn phòng khá (đặc biệt excel phục vụ việc báo cáo). Trung thực, trách nhiệm, cẩn thận, siêng năng, nhanh nhẹn, nhiệt tình, chịu được áp lực công việc cao.
Kỹ năng chuyên môn: [''Sử dụng vi tính văn phòng'', ''Excel'']
Kỹ năng mềm: [''Giải quyết tình huống'', ''Giao tiếp'', ''Trung thực'', ''Trách nhiệm'', ''Cẩn thận'', ''Siêng năng'', ''Nhiệt tình'', ''Chịu được áp lực công việc cao'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Đóng BHXH theo quy định'', ''Các chế độ khác theo quy định công ty (điện thoại, ăn trưa, ...)'', ''Có cơ hội được lên nhân viên chính thức khi có phát sinh tuyển dụng'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (672, 10, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ thực hiện các nghiệp vụ chuyên môn liên quan đến kế toán – tài chính. Tiếp nhận, kiểm tra và xử lý hồ sơ thanh toán chuyển khoản từ các phòng ban. Rà soát công nợ, hợp đồng và các chứng từ, hóa đơn đính kèm đề nghị thanh toán. Nhập liệu chứng từ, hóa đơn kế toán vào hệ thống. Hỗ trợ chuẩn bị và kiểm tra báo cáo thuế (đặc biệt là thuế GTGT, thuế TNCN,...). Thực hiện các công việc khác theo sự phân công của quản lý trực tiếp.', 'Sinh viên năm cuối hoặc mới tốt nghiệp chuyên ngành Kế toán, Kiểm toán, Tài chính. Có kiến thức nền tảng về kế toán doanh nghiệp. Thành thạo tin học văn phòng, đặc biệt là Excel. Có laptop cá nhân để phục vụ công việc. Trung thực, cẩn thận, có tinh thần trách nhiệm và mong muốn học hỏi, phát triển bản thân.
Kỹ năng chuyên môn: [''Kiến thức nền tảng về kế toán doanh nghiệp'', ''Thành thạo tin học văn phòng, đặc biệt là Excel'']
Kỹ năng mềm: [''Trung thực'', ''Cẩn thận'', ''Có tinh thần trách nhiệm'', ''Mong muốn học hỏi và phát triển bản thân'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '0.5 - 1.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7: 8:00 – 16:00', '[''Hỗ trợ chi phí đi lại: 250.000 VNĐ/tháng cho các bạn thực tập sinh có địa chỉ nhà cách công ty từ 15km trở lên'', ''Thời gian làm việc linh hoạt, phù hợp với lịch học của sinh viên'', ''Môi trường làm việc thân thiện, năng động, sẵn sàng hỗ trợ và chia sẻ'', ''Cơ hội trở thành nhân viên chính thức sau thời gian thực tập'', ''Học hỏi và tích lũy kinh nghiệm thực tế trong lĩnh vực kế toán – tài chính'', ''Phát triển các kỹ năng mềm như giao tiếp, làm việc nhóm, quản lý thời gian'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (673, 2, 14, 'Nhân Viên Kế Toán Tổng Hợp', 'Công việc đóng sổ hàng tháng (ghi sổ số khấu hao, phân bổ SAP, đối chiếu, kiểm tra, cân đối phát sinh,…); Báo cáo đóng sổ hàng tháng (thuộc công tác phân công); Dự báo kế hoạch tài chính (dòng tiền tự do); Dự báo báo cáo lưu chuyển tiền tệ và phân tích dòng tiền; Báo cáo IFRS (hỗ trợ cung cấp dữ liệu cho kiểm toán, chuẩn bị thuyết minh, quản lý trên hệ thống IFRS theo phân công của trưởng bô phận); Kiểm tra số dư tài khoản tồn đọng và đưa ra hướng xử lý theo ngày và theo tháng; Tiến hành thiết kế hồ sơ cần thiết và cải thiện quy trình liên quan dựa vào danh mục rủi ro kiểm soát hệ thống theo quy định của KSOX; Dự báo báo cáo lưu chuyển tiền tệ cả năm/kế hoạch dài hạn; Có khả năng đề xuất và phát triển quy trình; Các nhiêm vụ khác theo yêu cầu và sự phân công của cấp trên cũng như tình hình hiện tại của Công ty.', 'Cử nhân chuyên ngành Kế toán, kiểm toán; Có ít nhất 02 năm kinh nghiệm làm việc liên quan; Có kiến thức về kế toán và kiểm toán, các quy định pháp luật liên quan; Kỹ năng vi tính sử dụng tốt Microsoft Office.
Kỹ năng chuyên môn: [''Kiến thức về kế toán và kiểm toán'', ''Sử dụng tốt Microsoft Office'']', 'PART_TIME', 'ONSITE', 'tây ninh', 'Tây Ninh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Tham gia Bảo hiểm Y tế, BH tai nạn 24/7, BHXH 100%'', ''BH cho người thân (Đủ điều kiện năm làm việc tại CJ)'', ''Khám sức khỏe định kỳ'', ''Lương tháng 13'', ''Thưởng KPI (Theo kết quả kinh doanh)'', ''Thẻ thành viên CJ được hưởng dịch vụ ưu đãi trong tập đoàn'', ''Nghỉ lễ theo quy định của nhà nước và quà tặng các ngày lễ trong năm'', ''Môi trường làm việc có tính chủ động và độc lập cao'', ''Các phúc lợi lương, thưởng theo quy định của tập đoàn và công ty'', ''Có Xe đưa đón: TP.HCM: Quận 7, Quận 10, Ngã tư An Sương; Long An: Thành phố Tân An'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (674, 3, 14, 'Kế Toán', 'Công ty Phục Linh hiện đang tìm kiếm một Kế toán trưởng có năng lực, trách nhiệm và tâm huyết để đồng hành cùng chúng tôi trong việc phát triển hoạt động tài chính – kế toán vững mạnh, minh bạch và hiệu quả. Tổ chức, điều hành bộ phận kế toán theo đúng quy định của pháp luật và quy chế công ty. Kiểm soát, tổng hợp, lập báo cáo tài chính hàng tháng, quý, năm. Phân tích tình hình tài chính, dòng tiền và đề xuất giải pháp cải thiện hiệu quả hoạt động. Tư vấn cho Ban lãnh đạo về chiến lược tài chính – kế toán. Quản lý, đào tạo và phát triển đội ngũ kế toán viên.', 'YÊU CẦU ỨNG VIÊN: Tốt nghiệp đại học chuyên ngành kế toán, tài chính, kiểm toán hoặc liên quan. Tối thiểu 3 năm kinh nghiệm, trong đó có ít nhất 2 năm ở vị trí Kế toán trưởng hoặc tương đương. Am hiểu pháp luật về kế toán, thuế, tài chính doanh nghiệp. Kỹ năng lãnh đạo, quản lý đội nhóm tốt. Cẩn trọng, trung thực, chịu áp lực cao trong công việc. Thành thạo phần mềm kế toán và Excel.
Kỹ năng chuyên môn: [''Thành thạo phần mềm kế toán'', ''Excel'']
Kỹ năng mềm: [''Kỹ năng lãnh đạo'', ''Quản lý đội nhóm'', ''Cẩn trọng'', ''Trung thực'', ''Chịu áp lực cao trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 20000000.00, '15.0 - 20.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:30 đến 18:00)', '[''Thưởng hiệu quả công việc'', ''Thưởng lễ – Tết'', ''Lương tháng 13'', ''Môi trường làm việc chuyên nghiệp'', ''Cơ hội thăng tiến rõ ràng'', ''Được đào tạo và cập nhật kiến thức chuyên môn thường xuyên'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (675, 7, 14, 'Kế Toán Thời Vụ', '- Thực hiện các công việc kế toán hàng tháng bao gồm nhập liệu hóa đơn đầu vào đầu ra, ngân hàng, lương và đối chiếu số liệu thu chi công nợ vào phần mềm kế toán Misa. - Phân bổ ccdc, tài sản và doanh thu hàng tháng trên Misa. - Lập báo cáo thuế GTGT, TNCN theo quy định nhà nước. - Tính bảng lương, bảo hiểm xã hội hàng tháng cho toàn bộ nhân viên trong công ty. - Kiểm tra thu chi hằng ngày, xuất hoá đơn GTGT, tổng hợp và báo cáo doanh thu theo tuần/tháng/quý. - Theo dõi và kiểm soát các khoản chi phí, công nợ đối tác. - In sổ sách, hóa đơn, chứng từ lưu trữ cho doanh nghiệp. - Các công việc phát sinh khác.', 'Tốt nghiệp Cao đẳng trở lên, chuyên ngành Kế toán, Tài chính hoặc các ngành liên quan ưu tiên chuyên nghành quản trị kinh doanh, kinh tế,... Sử dụng thành thạo excel/word, phần mềm kế toán. Trung thực, cẩn trọng, làm việc khoa học, tinh thần trách nhiệm cao. Có 1 – 2 năm kinh nghiệm ở vị trí tương đương. Biết tiếng Trung là 1 lợi thế. Sức khỏe tốt, trung thực, nhanh nhẹn, nhiệt tình trong công việc. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Sử dụng thành thạo excel/word'', ''Phần mềm kế toán Misa'']
Kỹ năng mềm: [''Trung thực'', ''Cẩn trọng'', ''Làm việc khoa học'', ''Tinh thần trách nhiệm cao'', ''Nhiệt tình trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 12000000.00, '8.0 - 12.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Hỗ trợ tiền gửi xe nếu không gửi tại Học Viện'', ''Môi trường làm việc năng động, trẻ trung'', ''Cơ hội học tiếng Trung miễn phí khi trở thành nhân sự chính thức'', ''Lương tháng 13 tùy theo tình hình kinh doanh của công ty'', ''Tham gia BHXH theo quy định của Pháp luật'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (676, 8, 14, 'Chuyên Gia Tư Vấn Thuế', 'NextTech là một tập đoàn công nghệ với hệ sinh thái đa dạng. Hiện tại công ty con của chúng tôi phục vụ hơn 700.000 hộ kinh doanh trên toàn quốc. Chúng tôi cung cấp các nền tảng hỗ trợ kinh doanh, thanh toán, vận hành, và hiện đang mở rộng sang dịch vụ đại lý thuế nhằm hỗ trợ hộ kinh doanh trong việc tuân thủ pháp luật về thuế một cách đơn giản, minh bạch và hiệu quả. Hiện cần tuyển Chuyên gia Đại lý thuế/ Tư vấn thuê Hộ kinh doanh với công việc cụ thể: Trực tiếp thực hiện và giám sát các hoạt động khai thuế, nộp thuế, quyết toán thuế cho các hộ kinh doanh trong hệ sinh thái của tập đoàn. Đại diện khách hàng làm việc với cơ quan thuế theo phạm vi được ủy quyền. Thiết kế quy trình và bộ công cụ mẫu để triển khai dịch vụ đại lý thuế quy mô lớn và tự động hóa một phần. Phối hợp với đội ngũ công nghệ và sản phẩm để tích hợp dịch vụ thuế vào nền tảng hiện có. Đào tạo và hỗ trợ nội bộ cho đội ngũ chăm sóc khách hàng, nhằm nâng cao hiểu biết và khả năng hướng dẫn hộ kinh doanh về chính sách thuế. Cập nhật thường xuyên các quy định thuế liên quan và chủ động tư vấn cải tiến dịch vụ.', 'Có chứng chỉ hành nghề dịch vụ làm thủ tục về thuế (chứng chỉ đại lý thuế). Tối thiểu 2 năm kinh nghiệm thực tế trong lĩnh vực thuế/kế toán cho hộ kinh doanh, cá nhân kinh doanh. Hiểu biết sâu về các mô hình kinh doanh cá thể, tiểu thương, hộ kinh doanh quy mô nhỏ. Ưu tiên ứng viên từng làm tại các đại lý thuế, cục thuế, hoặc có kinh nghiệm triển khai các giải pháp công nghệ tài chính (fintech, govtech). Kỹ năng giao tiếp, đào tạo, và làm việc nhóm tốt. Tư duy hệ thống, mong muốn xây dựng dịch vụ có tác động quy mô lớn.
Kỹ năng chuyên môn: [''Luật Thuế'', ''Kế Toán Thuế'', ''Kiến Thức Thuế Chuyên Sâu'', ''Phần Mềm Kế Toán Thuế'', ''Soạn Thảo Báo Cáo Thuế'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Đào tạo'', ''Làm việc nhóm'', ''Tư duy hệ thống'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Thu nhập cạnh tranh theo mô hình lương cố định + thưởng hoặc chia sẻ lợi nhuận theo hiệu quả'', ''Cơ hội định hình một dịch vụ thiết yếu có tính lan tỏa trong cộng đồng hộ kinh doanh'', ''Được hỗ trợ bởi đội ngũ công nghệ, sản phẩm, vận hành giàu kinh nghiệm'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (677, 9, 14, 'Nhân Viên Kế Toán Thuế', 'Hạch toán, kiểm tra và đối chiếu số liệu kế toán thuế. Lập và nộp các báo cáo thuế định kỳ (GTGT, TNCN, TNDN…). Theo dõi công nợ thuế, cập nhật các văn bản pháp luật liên quan đến thuế. Làm việc với cơ quan thuế khi có phát sinh. Hỗ trợ các công việc kế toán nội bộ khi cần. Quản lý hóa đơn đầu vào, đầu ra và phối hợp xuất hóa đơn cho khách hàng. Thực hiện các công việc khác theo phân công của cấp trên.', 'Nữ, tuổi từ 24–40. Có máy tính. Tốt nghiệp Cao đẳng/Đại học chuyên ngành Kế toán, Tài chính, Kiểm toán. Có kinh nghiệm từ 1 năm trở lên làm kế toán thuế. Am hiểu luật thuế, chính sách thuế hiện hành. Thành thạo Excel và phần mềm kế toán (Misa, Fast…). Cẩn thận, trung thực, có tinh thần trách nhiệm cao. Thời gian làm việc: Giờ hành chính 8h00’ -17h00’, nghỉ trưa từ 12h00’ – 13h00’ (từ thứ 2 - sáng thứ 7, chiều thứ bảy và ngày chủ nhật sẽ thay đổi luân phiên trực theo lịch trực phân công của Quản lý và được hỗ trợ làm việc online tại nhà). Thời gian thử việc từ 1-3 tháng tùy khả năng tiếp nhận công việc của mỗi bạn.
Kỹ năng chuyên môn: [''Excel'', ''Misa'', ''Fast'']
Kỹ năng mềm: [''Cẩn thận'', ''Trung thực'', ''Có tinh thần trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'quảng ninh', 'Quảng Ninh', 'MONTHLY', 9000000.00, '7.5 - 9.0 triệu', 'Giờ hành chính 8h00’ - 17h00’', '[''Thưởng các dịp lễ, tết'', ''Thưởng hiệu quả công việc'', ''Được đóng BHXH – BHYT – BHTN theo quy định nhà nước'', ''Môi trường làm việc thân thiện, chuyên nghiệp'', ''Cơ hội gắn bó lâu dài và phát triển trong lĩnh vực Logistics – Xuất nhập khẩu'', ''Tháng lương 13'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (678, 10, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ chuẩn bị và xử lý các tài liệu tài chính. Tổ chức và duy trì các tập tin và hồ sơ kế toán. Hỗ trợ chuẩn bị tài liệu thuế và đảm bảo tuân thủ các quy định. Tham gia vào kiểm toán nội bộ hoặc kiểm tra hàng tồn kho theo chỉ định. Các nhiệm vụ kế toán khác như được giao.', 'Fresh graduate or student majoring in Accounting, Finance, Auditing, or a related field. Understanding of accounting principles and processes. Proficient in Microsoft Office. Working time: 7:30 - 16:30, Monday - Friday (at least 4 days/week).
Kỹ năng chuyên môn: [''Understanding of accounting principles and processes.'', ''Proficient in Microsoft Office.'']
Kỹ năng mềm: [''Ability to work in a team.'', ''Attention to detail.'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', '7:30 - 16:30, Monday - Friday (at least 4 days/week)', '[''Professional, modern working environment.'', ''Hands-on experience in accounting at a production company.'', ''Intern allowance, lunch support.'', ''Official stamp for intern.'', ''Flexible working schedule for students.'', ''Networking opportunities with professionals in the field.'', ''Chance to be an official member at Ducksan Vina accounting team.'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (679, 2, 14, 'Nhân Viên Kế Toán', 'Theo dõi công nợ, chốt công nợ, xuất hóa đơn, check hợp đồng, chứng từ, giao dịch ngân hàng, quản lý thu chi tiền mặt, phụ trách mảng nhân sự: Chấm công, tính lương, bảo hiểm, chế độ, các yêu cầu khác của ban giám đốc.', 'Giới tính: Nữ. Độ tuổi: 24 - 35 tuổi. Tốt nghiệp Cao đẳng, Đại học các ngành Tài chính - kế toán. Có kinh nghiệm 1 năm vị trí tương đương.
Kỹ năng chuyên môn: [''Thành thạo các kỹ năng văn phòng: word, excel'']
Kỹ năng mềm: [''Kỹ năng đàm phán'', ''Xử lý tình huống tốt'', ''Kỹ năng lập kế hoạch'', ''Phân tích số liệu'', ''Tổ chức thực hiện công việc tốt'', ''Khả năng sáng tạo'', ''Chịu áp lực'', ''Bảo mật thông tin'', ''Phẩm chất thật thà'', ''Chủ động'', ''Quyết tâm trong công việc'']', 'PART_TIME', 'ONSITE', 'bắc ninh', 'Bắc Ninh', 'MONTHLY', 7000000.00, '7.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Lương tháng 13'', ''Thưởng sáng kiến'', ''Cung cấp trang thiết bị, vật tư làm việc'', ''Phụ cấp ăn trưa'', ''Gửi xe'', ''Điện thoại'', ''Công tác phí'', ''Bảo hiểm xã hội'', ''Bảo hiểm y tế'', ''Bảo hiểm thất nghiệp'', ''Nghỉ phép theo quy định'', ''Quà các dịp Lễ Tết'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (680, 3, 14, 'Thực Tập Sinh Kế Toán', 'Cập nhập thu, chi, chứng từ vào Google drive, phần mềm fast. Quản lý hợp đồng. Hạch toán các nghiệp vụ phát sinh liên quan đến thanh toán. Quản lý hàng hóa nhập kho, xuất kho. Thực hiện công việc khác theo yêu cầu của cấp trên.', 'Đang theo học các chuyên ngành Tài chính, Kế toán hoặc các chuyên ngành liên quan. Có tư duy kế toán là một điểm mạnh. Có laptop cá nhân. Thông thạo các kỹ năng Excel cơ bản và hiểu biết về các phương pháp Excel trong kế toán.
Kỹ năng chuyên môn: [''Kỹ năng Excel cơ bản'', ''Hiểu biết về các phương pháp Excel trong kế toán'']
Kỹ năng mềm: [''Tư duy kế toán'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường làm việc trẻ trung, năng động'', ''Lộ trình thăng tiến rõ ràng'', ''Được nâng cao năng lực bản thân'', ''Khuyến khích sáng tạo và phát triển bản thân'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (681, 7, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ kiểm tra, soát xét tờ khai thuế hàng tháng/ quý trước khi gửi cho khách hàng. Hỗ trợ khách hàng trong công việc nộp giấy tờ chứng từ cho các bên như: thuế, ngân hàng, v.v. Hỗ trợ nhập số liệu sổ sách kế toán, hóa đơn chứng từ cho khách hàng lên phần mềm kế toán. Hỗ trợ kiểm tra bảng tính quyết toán thuế TNCN hàng năm, tờ khai quyết toán thuế. Các công việc khác khi được yêu cầu.', 'Sinh viên năm cuối Chuyên ngành Kế toán/ Kiểm toán/ Tài chính hoặc chuyên ngành có liên quan (Chấp nhận là parttime). Có khả năng sử dụng Tiếng Anh, Microsoft Office, đặc biệt Excel; Có khả năng làm việc độc lập và theo nhóm, tư duy tốt; Có sự tiến bộ trong quá trình tham gia đào tạo Job chuyên sâu; có tinh thần trách nhiệm trong công việc; Giao tiếp tốt, chủ động, tự tin và cam kết làm việc lâu dài trong môi trường chuyên nghiệp.
Kỹ năng chuyên môn: [''Tiếng Anh'', ''Microsoft Office'', ''Excel'']
Kỹ năng mềm: [''Làm việc độc lập'', ''Làm việc theo nhóm'', ''Tư duy tốt'', ''Giao tiếp tốt'', ''Chủ động'', ''Tự tin'', ''Tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:30 đến 15:30)', '[''Môi trường năng động, thân thiện, sáng tạo'', ''Ưu tiên tuyển dụng cho các tổ chức kế toán, kiểm toán, thuế sau thực tập'', ''Tham gia vào các Job chuyên nghiệp và chuyên sâu'', ''Chương trình đào tạo chuyên sâu'', ''Hỗ trợ lương thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (682, 8, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ hoàn thiện hồ sơ, chứng từ đi kèm với các nghiệp vụ kinh tế phát sinh. In sổ sách, lưu trữ, bảo quản chứng từ. Hỗ trợ đi ủy nhiệm chi với ngân hàng. Được đào tạo và thực hiện các nghiệp vụ tài chính kế toán theo định hướng và thế mạnh cá nhân (nội bộ, thuế, công nợ, ngân hàng).', 'Nam sinh viên năm 3,4 các chuyên ngành liên quan đến kế toán, văn phòng. Thực tập toàn thời gian 6 tháng. Cẩn thận, tỉ mỉ, trung thực, nhanh nhẹn, chủ động trong công việc.
Kỹ năng chuyên môn: [''Kiến Thức Cơ Bản Về Kế Toán'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Trung thực'', ''Nhanh nhẹn'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Được đào tạo và thực hiện các nghiệp vụ tài chính kế toán'', ''Đóng dấu cho báo cáo thực tập của Thực tập sinh'', ''Hỗ trợ chi phí ăn trưa, xăng xe đi lại'', ''Cơ hội thăng tiến nhân viên chính thức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (683, 9, 14, 'Thực Tập Kế Toán', '- Chia lệnh xe/bill xe, vé cầu đường, bến đỗ.... - Hỗ trợ kế toán chính thức Kiểm tra tính chính xác các khoản thanh toán: Cầu đường, bến đỗ…. - Hỗ trợ kế toán chính thức Nhập số liệu kế toán lên phần mềm kế toán - Công việc khác theo yêu cầu.', 'Trình độ: Sinh viên năm cuối Cao Đẳng, Đại học chuyên ngành kế toán. Ưu tiên các bạn thực tập fulltime và ở khu vực gần nơi làm việc: Phường Kim Liên - Hà Nội và có thể làm việc fulltime Khỏe mạnh, chăm chỉ ham học hỏi và có tinh thần trách nhiệm trong công việc Thành thạo vị tính văn phòng. Yêu thích công việc kế toán
Kỹ năng chuyên môn: [''Thành thạo vị tính văn phòng'']
Kỹ năng mềm: [''Khỏe mạnh'', ''Chăm chỉ'', ''Ham học hỏi'', ''Có tinh thần trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 11:30)', '[''Được hưởng lương thực tập theo quy định'', ''Được tham gia các hoạt động ngoại khóa, và dã ngoại tại công ty'', ''Được đào tạo và có cơ hội trở thành nhân viên chính thức sau 3-6 tháng'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (684, 10, 14, 'Thực Tập Sinh Kế Toán', 'Thực hiện nhập liệu chứng từ vào phần mềm SAP Business One, ECUS, MISA. Hỗ trợ photocopy, scanning, lưu trữ hồ sơ/ chứng từ Kế toán. Hỗ trợ đối chiếu các đề nghị thanh toán và ngân sách được duyệt. Hỗ trợ đối chiếu các khoản thanh toán qua ngân hàng. Hỗ trợ AP trong việc rà soát chứng từ liên quan Phiếu Thu/ Chi. Hỗ trợ AR trong việc rà soát chứng từ xuất/ nhập kho. Hỗ trợ kiểm tra/ đối chiếu thông tin hóa đơn tài chính. Hỗ trợ các công việc khác khi có yêu cầu từ Trưởng Bộ Phận.', 'Trình độ học vấn: Sinh viên năm cuối hoặc mới tốt nghiệp Đại học/ trung cấp chuyên ngành Kinh tế/ Kế toán/ Ngân Hàng/ Ngoại thương. Kinh nghiệm làm việc: Vị trí dành cho sinh viên mới ra trường có tinh thần học hỏi và cầu tiến. Trình độ ngoại ngữ: Có khả năng đọc hiểu tiếng Anh. Kỹ năng vi tính: Có khả năng sử dụng vi tính văn phòng MS-Excel, MS-Word, MS-PowerPoint.
Kỹ năng chuyên môn: [''SAP Business One'', ''ECUS'', ''MISA'', ''MS-Excel'', ''MS-Word'', ''MS-PowerPoint'']
Kỹ năng mềm: [''Tinh thần học hỏi'', ''Cầu tiến'', ''Trung thực'', ''Cẩn thận'', ''Tỉ mỉ'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '8h30 - 17h30 (thứ 2 đến thứ 6)', '[''Hỗ trợ chi phí gửi xe'', ''Hỗ trợ chi phí điện thoại'', ''Các chương trình đào tạo chuyên môn nghiệp vụ tại doanh nghiệp và các trung tâm bên ngoài'', ''Các chương trình kết nối, teambuilding'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (685, 2, 14, 'Thực Tập Sinh Kế Toán', 'Hạch toán các nghiệp vụ kinh tế phát sinh liên quan đến tiền mặt, ngân hàng, chi phí, hóa đơn. Lưu trữ chứng từ kế toán. Các công việc khác theo phân công của cán bộ quản lý giao. Thực hiện công tác báo cáo khi được yêu cầu.', 'Là sinh viên năm năm 04 đang theo học tại các Trường Đại học chuyên ngành Kế toán doanh nghiệp, hoặc các chuyên ngành có liên quan. Hiểu biết kiến thức về chuyên môn kế toán, quy định, chuẩn mực, thông tư kế toán. Sử dụng thành thạo các ứng dụng tin học văn phòng như Ms.Word, Ms.Excel, Ms. Powerpoint, Ms. Outlook,... đã tiếp cận với các phần mềm kế toán tại trường học. Chỉnh chu, cẩn thận và chi tiết. Có tinh thần trách nhiệm, có tâm huyết. Tinh thần đồng đội, hỗ trợ, giúp đỡ mọi người. Có khả năng học hỏi nhanh, làm việc nghiên cứu độc lập, biết lắng nghe. Tác phong làm việc chuyên nghiệp, năng động, linh hoạt và dễ thích nghi với môi trường làm việc. Yêu thích công việc và có mong muốn gắn bó lâu dài để phát triển cùng Công ty; Chỉnh chu, nhiệt tình, có trách nhiệm, thái độ trong công việc tốt.
Kỹ năng chuyên môn: [''Ms.Word'', ''Ms.Excel'', ''Ms.Powerpoint'', ''Ms.Outlook'', ''Phần mềm kế toán'']
Kỹ năng mềm: [''Chỉnh chu'', ''Cẩn thận'', ''Chi tiết'', ''Tinh thần trách nhiệm'', ''Tinh thần đồng đội'', ''Khả năng học hỏi nhanh'', ''Làm việc độc lập'', ''Lắng nghe'', ''Tác phong chuyên nghiệp'', ''Năng động'', ''Linh hoạt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '1.0 - 4.0 triệu', 'Full-time', '[''Hỗ trợ thực tập: 1.000.000 - 4.000.000'', ''Lương cứng nhân viên chính thức: từ 8 - 12 triệu'', ''Đóng BHXH và các chế độ phúc lợi theo quy định của Pháp Luật'', ''Tham gia đào tạo kỹ năng mềm / kỹ năng chuyên môn'', ''Tham gia hoạt động team building, du lịch hàng năm'', ''Cơ hội nghề nghiệp ổn định lâu dài'', ''Tăng lương, xét thưởng dựa trên năng lực'', ''Phụ cấp ăn trưa, gửi xe'', ''Tặng quà vào các dịp sinh nhật, lễ Tết'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (686, 3, 14, 'Thực Tập Sinh Kế Toán', 'Nhập, xuất hóa đơn trên phần mềm Misa. Sắp xếp hồ sơ, chứng từ Phòng Kế toán. Hỗ trợ nhập liệu lên hệ thống của công ty. Thực hiện các công việc khác theo phân công của cấp trên.', 'Tốt nghiệp/Sinh viên năm 4 các trường Cao đẳng/ĐH trở lên. Ưu tiên biết sử dụng phần mềm Misa. Có kỹ năng phân tích, sử dụng Excel tốt là một lợi thế. Tỉ mỉ, cẩn thận, chịu khó.
Kỹ năng chuyên môn: [''Sử dụng phần mềm Misa'', ''Sử dụng Excel'']
Kỹ năng mềm: [''Tỉ mỉ'', ''Cẩn thận'', ''Chịu khó'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được cấp giấy xác nhận thực tập'', ''Môi trường làm việc năng động, thân thiện, có cơ hội thăng tiến'', ''Được đào tạo nâng cao nghiệp vụ chuyên môn'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (687, 7, 14, 'Thực Tập Sinh Kế Toán', 'Kiểm tra, lưu trữ các hồ sơ chứng từ. Nhập liệu mới/rà soát điều chỉnh số liệu cũ từ chứng từ mua vào, bán ra trên phần mềm kế toán. Thực hiện các công việc khác theo yêu cầu của Quản lý trực tiếp.', 'Là sinh viên năm cuối hoặc đăng chờ bằng tốt nghiệp chuyên ngành Kế toán, Kiểm toán,... sử dụng tốt excel, ưu tiên biết sử dụng phần mềm kế toán bất kỳ. Nhiệt huyết với công việc. Nắm vững định khoản. Có thể làm fulltime. Coi trọng thực tập là một cơ hội nghề nghiệp.
Kỹ năng chuyên môn: [''Sử dụng tốt Excel'', ''Biết sử dụng phần mềm kế toán'']
Kỹ năng mềm: [''Nhiệt huyết với công việc'', ''Nắm vững định khoản'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Cơ hội trở thành nhân viên chính thức'', ''Được đào tạo nâng cao kiến thức, kỹ năng nghiệp vụ'', ''Được tham gia các khóa học, cập nhật kiến thức nghề, thông tư mới về lĩnh vực kinh tế, kế toán, thuế'', ''Hỗ trợ cung cấp số liệu/đóng dấu luận văn/báo cáo khóa luận'', ''Môi trường năng động, chuyên nghiệp, thân thiện, hòa đồng'', ''Cơ hội trau dồi thể thao, kiến thức về sức khỏe hàng tuần, được tham gia nhiều Giải thể thao, cuộc thi thú vị trong năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (688, 8, 14, 'Thực Tập Sinh Kế Toán', 'Trợ giúp Kế toán thực hiện các công việc liên quan tới kiểm tra, đối chiếu công nợ Khách hàng, đối tác. Tìm hiểu, học hỏi tham gia các công việc liên quan đến Kế toán. In bổ sung giấy tờ còn thiếu và sắp xếp lưu trữ hồ sơ, chứng từ có liên quan. Soạn hợp đồng theo form và các giấy tờ khác khi được yêu cầu. Hoàn thành các công việc khác do Leader đưa ra.', 'Đang là sinh viên năm cuối hoặc mới tốt nghiệp các trường Đại học, Cao đẳng, chuyên ngành Kế toán, Kiểm toán. Thành thạo tin học văn phòng. Trung thực, chăm chỉ, cẩn thận, chính xác. Có tinh thần trách nhiệm, sẵn sàng hoàn thành mọi nhiệm vụ được giao. Có Laptop cá nhân để làm việc. Thời gian làm việc: 8h - 17h30 (Thứ 2 - thứ 6)
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Trung thực'', ''Chăm chỉ'', ''Cẩn thận'', ''Chính xác'', ''Có tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '8h - 17h30 (Thứ 2 - thứ 6)', '[''Được cung cấp con dấu và tài liệu cho bài báo cáo'', ''Môi trường làm việc thân thiện, teamwork'', ''Cơ hội cao được trở thành nhân viên chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (689, 9, 14, 'Thực Tập Sinh Dịch Vụ Kế Toán', '- Kiểm tra, kiểm soát chứng từ, giấy tờ, tài liệu chứng minh trên một nghiệp vụ kinh tế phát sinh đủ điều kiện để hạch toán ghi sổ kế toán; - Hạch toán ghi sổ kế toán trên phần mềm kế toán theo hệ thống kế toán TT133 hoặc TT200; - Sử dụng phần mềm hỗ trợ kê khai, lập và nộp các loại tờ khai thuế: Lệ phí môn bài; Thuế GTGT; Thuế TNCN; Thuế xuất nhập khẩu; Thuế TNDN; - Sử dụng dụng phần mềm xuất hóa đơn GTGT; - Lập các báo cáo nội bộ theo hệ thống báo cáo của Công ty.', 'YÊU CẦU: - Trình độ chuyên môn: sinh viên năm 3 trở lên chuyên ngành kế toán hoặc tương đương; - Kinh nghiệm: không yêu cầu --------------------------------------------- KỸ NĂNG: - Kỹ năng tin học: sử dụng cơ bản Word, Excel; - Hiểu biết về phần mềm kế toán: Misa
Kỹ năng chuyên môn: [''sử dụng cơ bản Word'', ''Excel'', ''phần mềm kế toán Misa'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'thứ 2 - sáng thứ 7 (sáng 8h00-12h00; chiều 13h30-17h30)', '[''Được hướng dẫn, đào tạo bài bản'', ''Mục tiêu công việc rõ ràng'', ''Nghỉ lễ, tết theo quy định của nhà nước'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (690, 10, 14, 'Nhân Viên Kế Toán Thời Vụ', '+ KẾ TOÁN * Kiểm tra chứng từ thanh toán, hạch toán vào phần mềm * Thực hiện thanh toán ngân hàng, lập phiếu thu chi tiền mặt * Xuất hóa đơn cho khách hàng * Lưu trữ chứng từ kế toán đúng quy định + NHÂN SỰ * Tính lương và hạch toán lương vào phần mềm * Theo dõi thời hạn của các hợp đồng lao động * Kiểm tra số liệu và thanh toán BHXH Vị trí tuyển dụng **thời vụ 6 tháng**', 'Trình độ Cao đẳng trở lên Ít nhất 1-2 năm kinh nghiệm Tiếng Anh cơ bản, thành thạo tin học văn phòng Sức khỏe tốt, trách nhiệm, cẩn thận và có kỹ năng lập kế hoạch
Kỹ năng chuyên môn: [''Sử dụng phần mềm kế toán'', ''Tin học văn phòng'']
Kỹ năng mềm: [''Trách nhiệm'', ''Cẩn thận'', ''Kỹ năng lập kế hoạch'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6; 8am - 5pm', '[''Tham gia BHXH full lương từ ngày vào làm, không thử việc'', ''Công ty sẽ chi trả 10.5% BHXH và PIT cho NLĐ'', ''Phép năm: 6 ngày'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (691, 2, 14, 'Thực Tập Sinh Kế Toán Doanh Thu', '• Đối chiếu báo cáo doanh thu và báo cáo thu tiền hàng ngày • Đối chiếu báo cáo thu tiền với các kênh thanh toán. • Đối chiếu dữ liệu trên phần mềm bán hàng và phần mềm xuất hóa đơn điện tử. • Hỗ trợ kế toán doanh thu xử lý khi phát sinh chênh lệch và lỗi hệ thống', '• Sinh viên năm cuối hoặc mới tốt nghiệp các chuyên ngành có liên quan. • Có thể Thực tập tối thiểu 5 tháng. • Nhiệt tình, chăm chỉ, có trách nhiệm với công việc. • Sử dụng tốt Excel, tư duy logic • Ưu tiên các bạn có thể làm full-time hoặc off 1-2 buổi trong tuần
Kỹ năng chuyên môn: [''Excel'']
Kỹ năng mềm: [''Nhiệt tình'', ''Chăm chỉ'', ''Có trách nhiệm với công việc'', ''Tư duy logic'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '2.0 - 2.5 triệu', 'Full-time hoặc off 1-2 buổi trong tuần', '[''Phụ cấp thực tập: 2.500.000 – 3.000.000 đ/tháng'', ''Được tặng vé xem phim hàng tháng (2 cặp vé tại hệ thống rạp Beta)'', ''Tham gia hoạt động gắn kết Happy Hour'', ''Được làm việc trong môi trường rạp chiếu phim trẻ trung năng động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (692, 3, 14, 'Thực Tập Sinh Kế Toán Thanh Toán', 'Hỗ trợ chuẩn bị hồ sơ giải ngân ra ngân hàng. Hỗ trợ làm hồ sơ thanh toán cho nhà cung cấp (hàng hóa, nguyên vật liệu) đảm bảo hợp lệ và đầy đủ chứng từ. Cùng với 2 quản lý kế toán điểm để thực hiện chốt báo cáo kho hàng tháng.', 'Sinh viên năm cuối hoặc mới tốt nghiệp ngành Kế toán, Tài chính hoặc các chuyên ngành có liên quan. Thành thạo tin học văn phòng, sử dụng tốt Excel. Có tư duy Logic, cẩn thận, chăm chỉ, kỹ năng giao tiếp tốt. Có thể thực tập từ 3-6 tháng. Ưu tiên các bạn có thể làm full-time, hoặc off 1-2 buổi/tuần.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng'', ''Sử dụng tốt Excel'']
Kỹ năng mềm: [''Tư duy Logic'', ''Cẩn thận'', ''Chăm chỉ'', ''Kỹ năng giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Phụ cấp thực tập: 2 triệu/tháng'', ''Hỗ trợ cấp dấu mộc thực tập'', ''Được đào tạo bài bản về quy trình làm việc'', ''Được tặng vé xem phim hàng tháng'', ''Tham gia hoạt động Teambuilding, Happy Hour'', ''Môi trường làm việc trẻ trung năng động'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (693, 7, 14, 'Thực Tập Sinh Kế Toán', '- Sắp xếp chứng từ, nhập liệu (nếu có) - Đối chiếu chứng từ so với bảng kê, sổ sách - Kiểm kê hàng hóa - Các công việc khác theo yêu cầu của trưởng bộ phận', '- Ưu tiên sinh viên năm cuối chuyên ngành Kế toán/ Kiểm toán - Có thể làm Full-time, thực tập ít nhất 03 đến 06 tháng - Trung thực, nhanh nhẹn, hoạt bát. - Thành thạo vi tính văn phòng
Kỹ năng chuyên môn: [''Word'', ''Excel'', ''Kiến Thức Cơ Bản Về Kế Toán'']
Kỹ năng mềm: [''Trung thực'', ''nhanh nhẹn'', ''hoạt bát'', ''Khả Năng Làm Việc Nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Làm việc trong môi trường chuyên nghiệp, nhiệt tình, năng động, có cơ hội học hỏi'', ''Phụ cấp: 3.000.000 đồng/ tháng'', ''TRỞ THÀNH NHÂN VIÊN CHÍNH THỨC (nếu được đánh giá tốt)'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (694, 8, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ kiểm tra, đối chiếu số liệu nhập – xuất – tồn giữa sổ sách và thực tế. Ghi nhận phiếu nhập, phiếu xuất kho, và cập nhật vào phần mềm kế toán/kho. Lưu trữ, sắp xếp chứng từ kho theo đúng quy định. Hỗ trợ lập các báo cáo tồn kho hàng ngày, hàng tuần hoặc theo yêu cầu. Phối hợp với các bộ phận liên quan để kiểm kê định kỳ. Thực hiện các công việc hành chính, kế toán khác theo phân công của cấp trên.', 'Sinh viên năm 3, năm cuối chuyên ngành Kế toán, Tài chính, Kiểm toán hoặc các ngành liên quan. Có kiến thức cơ bản về kế toán kho, hàng tồn kho. Biết sử dụng Excel, ưu tiên biết phần mềm kế toán (MISA, Bravo, Fast...). Cẩn thận, trung thực, chịu khó học hỏi. Có thể thực tập tối thiểu 3 tháng.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về kế toán kho, hàng tồn kho'', ''Sử dụng Excel'', ''Biết phần mềm kế toán (MISA, Bravo, Fast...)'']
Kỹ năng mềm: [''Cẩn thận'', ''Trung thực'', ''Chịu khó học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được hướng dẫn nghiệp vụ bởi kế toán có kinh nghiệm'', ''Hỗ trợ dấu mộc thực tập, tài liệu xác nhận sau thời gian thực tập'', ''Có hỗ trợ chi phí (cơm trưa)'', ''Cơ hội trở thành nhân viên chính thức nếu thể hiện tốt'', ''Môi trường làm việc thân thiện, chuyên nghiệp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (695, 9, 14, 'Cộng Tác Viên Kế Toán Part-Time', 'Lên danh sách xuất hóa đơn tuyển sinh, bán trú, các khoản thu hộ chi hộ… Tổng hợp thu nhập CBNV, Giáo viên trong tháng. Các công việc khác theo sự phân công của Trưởng, phó phòng TCKT.', 'Đang là sinh viên năm ba, năm cuối hoặc mới tốt nghiệp chuyên ngành Kế toán các trường Đại học. Có kiến thức cơ bản về kế toán. Nhanh nhẹn, tỉ mỉ, cẩn thận, tiếp thu nhanh.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về kế toán'', ''Sử dụng thành thạo phần mềm Excel'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Tỉ mỉ'', ''Cẩn thận'', ''Tiếp thu nhanh'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Được hướng dẫn, đào tạo tiếp xúc trực tiếp với công việc kế toán thực tế.'', ''Môi trường giáo dục nhân văn, nhiệt huyết, sẵn sàng học hỏi.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (696, 10, 14, 'Thực Tập Sinh Kế Toán', 'Trợ giúp kế toán sắp xếp hóa đơn chứng từ. Trợ giúp kế toán ghi chép sổ sách kế toán (bằng phần mềm kế toán). Một số việc có liên quan trực tiếp đến kế toán.', '• Là sinh viên các trường đại học và cao đẳng chuyên ngành kế toán, kiểm toán và tài chính. • Trung thực, nhiệt tình và có tinh thần trách nhiệm. • Thực tập toàn thời gian trong giờ hành chính tại văn phòng Công ty trong khoảng thời gian ít nhất là 04 tháng.
Kỹ năng chuyên môn: [''Phần mềm kế toán'']
Kỹ năng mềm: [''Trung thực'', ''Nhiệt tình'', ''Có tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Toàn thời gian trong giờ hành chính', '[''Thực tập trong môi trường kế toán chuyên nghiệp'', ''Được học hỏi nhiều từ công việc thực tế'', ''Được trợ cấp tiền ăn'', ''Cơ hội được Công ty tuyển dụng sau khi ra trường'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (697, 2, 14, 'Thực Tập Sinh Kế Toán', 'Thực tập xử lý các giấy tờ, chứng từ kế toán. Nhập liệu thông tin lên phần mềm. Hỗ trợ lên báo cáo thuế, BCTC.', 'Có laptop cá nhân. Học chuyên ngành kế toán và các ngành liên quan. Định hướng gắn bó lâu dài với công ty. Nhanh nhẹn, nhiệt tình trong công việc. Là người cẩn thận, có tinh thần trách nhiệm cao. Chấp nhận ứng viên đã ra trường và muốn học việc.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về kế toán'', ''Sử dụng phần mềm kế toán (Misa, Fast Accounting)'', ''Sử dụng phần mềm Excel'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Nhiệt tình'', ''Cẩn thận'', ''Có tinh thần trách nhiệm cao'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:30 đến 17:30), 2 thứ 7 trong 1 tháng', '[''Được hướng dẫn từ đầu về nghiệp vụ kế toán'', ''Hỗ trợ dấu thực tập và chi phí xăng xe đi lại là 2.000.000 tới 4.000.000 đồng'', ''Cơ hội trở thành nhân viên chính thức của công ty sau 3 tháng học việc'', ''Sếp vui tính, đồng nghiệp trẻ, năng động'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (698, 3, 14, 'Thực Tập Sinh Kế Toán', '· Hỗ trợ lập chứng từ kế toán theo hướng dẫn của kế toán. · Kiểm tra hóa đơn, chứng từ đầu vào, đầu ra. · Sử dụng phần mềm Kế toán để nhập liệu. · Hỗ trợ sắp xếp, lưu trữ hồ sơ và chứng từ kế toán. · Tìm hiểu, học hỏi tham gia các công việc liên quan đến Kế toán. · Các công việc khác theo sự phân công của kế toán.', '- Sinh viên năm cuối hoặc mới tốt nghiệp chuyên ngành Kế toán. - Kỹ năng tin học văn phòng, đặc biệt là Excel - Trung thực, chăm chỉ, cẩn thận và chính xác. - Đảm bảo thời gian thực tập 3 tháng fulltime (Hoặc off 1 buổi trong tuần);
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng'', ''Excel'']
Kỹ năng mềm: [''Trung thực'', ''Chăm chỉ'', ''Cẩn thận'', ''Chính xác'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 1000000.00, '1.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Hỗ trợ phụ cấp thực tập 1,000,000'', ''Hỗ trợ 1 bữa ăn trưa tại Công ty'', ''Hỗ trợ dấu mộc thực tập'', ''Được đào tạo bài bản quy trình làm việc trong quá trình thực tập'', ''Có cơ hội trở thành nhân viên chính thức của Công ty'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (699, 7, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ kiểm tra, nhập liệu chứng từ kế toán – hóa đơn đầu vào, đầu ra. Phối hợp lập báo cáo thuế GTGT, TNCN, TNDN định kỳ. Học cách sử dụng phần mềm kế toán doanh nghiệp thực tế. Hỗ trợ rà soát sổ sách, lưu trữ chứng từ kế toán. Thực hiện các công việc khác theo phân công của kế toán hướng dẫn.', 'Tốt nghiệp thuộc chuyên ngành là một lợi thế. Yêu cầu có tính trung thực, nhanh nhẹn, chịu khó, ham học hỏi, tỉ mỉ và tự giác trong công việc. Có định hướng làm việc trong lĩnh vực kế toán thuế sau khi ra trường. Ưu tiên ứng viên có thể thực full time.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về kế toán'', ''Sử dụng thành thạo phần mềm Excel'']
Kỹ năng mềm: [''Trung thực'', ''Nhanh nhẹn'', ''Chịu khó'', ''Ham học hỏi'', ''Tỉ mỉ'', ''Tự giác'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 07:30 đến 17:00)', '[''Được đào tạo bài bản từ các kế toán thuế nhiều năm kinh nghiệm'', ''Tiếp cận hồ sơ, dữ liệu thực tế từ nhiều loại hình doanh nghiệp'', ''Hỗ trợ phí thực tập hàng tháng (theo năng lực & thời gian hỗ trợ)'', ''Xác nhận Giấy chứng nhận thực tập theo yêu cầu'', ''Có cơ hội ở lại làm chính thức sau kỳ thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (700, 8, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ nhập liệu chứng từ kế toán vào phần mềm kế toán. Lưu trữ, sắp xếp chứng từ, hồ sơ kế toán một cách khoa học, hợp lý. Hỗ trợ xuất hóa đơn bán hàng theo yêu cầu. Hỗ trợ các công việc khác theo sự phân công của Kế toán trưởng hoặc Quản lý trực tiếp.', 'Chăm chỉ, có tinh thần học hỏi và cầu tiến trong công việc. Cẩn thận, kỹ lưỡng, có trách nhiệm trong công việc được giao. Có kiến thức cơ bản về nghiệp vụ kế toán. Sử dụng thành thạo Microsoft Word, Excel. Ưu tiên ứng viên đang học năm cuối hoặc mới tốt nghiệp chuyên ngành Kế toán, Tài chính, Kiểm toán hoặc các ngành liên quan.
Kỹ năng chuyên môn: [''Sử dụng thành thạo Microsoft Word'', ''Sử dụng thành thạo Excel'']
Kỹ năng mềm: [''Chăm chỉ'', ''Có tinh thần học hỏi'', ''Cẩn thận'', ''Kỹ lưỡng'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Chiều thứ 7 làm việc tại nhà', '[''Bảo hiểm xã hội'', ''Bảo hiểm sức khỏe'', ''Bảo hiểm sức khỏe người thân'', ''Team building'', ''Du lịch hàng năm'', ''Thưởng tháng 13'', ''Thưởng cổ phần'', ''Khám sức khỏe định kỳ'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (701, 9, 14, 'Nhân Viên Thời Vụ Admin Finance', 'Hỗ trợ team Finance trong việc thu thập giấy tờ, chứng từ. Sắp xếp, kiểm tra giấy tờ, hồ sơ, đảm bảo chất lượng và thời gian xử lí hồ sơ theo đúng quy định. Nhập dữ liệu vào hệ thống. Các công việc hỗ trợ khác khi cần. Đảm bảo tuân thủ các quy định của công ty.', 'Trình độ trung cấp trở lên, có background về kế toán. Cẩn thận, chăm chỉ, trung thực. Tự giác thực hiện công việc, sẵn sàng hỗ trợ các thành viên trong team để hoàn thành mục tiêu công việc. Tiếng Anh cơ bản, có khả năng sử dụng máy tính và excel/G-sheet thành thạo.
Kỹ năng chuyên môn: [''Sử dụng máy tính'', ''Excel'', ''G-sheet'']
Kỹ năng mềm: [''Cẩn thận'', ''Chăm chỉ'', ''Trung thực'', ''Tự giác'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Được đào tạo trong quá trình làm việc'', ''Được cung cấp trang thiết bị làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (702, 10, 14, 'Chuyên Viên Quản Lý Công Nợ - Thời Vụ 6 Tháng', '- Đảm bảo công tác thu hồi nợ theo đúng quy định Công ty - Chủ động tạo mối quan hệ với Khách hàng để thúc đẩy nhanh quá trình thu nợ - Kiểm tra chi tiết công nợ từng khách hàng theo từng chứng từ phát sinh, hạn thanh toán, số tiền đã quá hạn thông báo đến từng khách hàng - Kiểm tra số liệu công nợ để lập biên bản xác nhận công nợ khách hàng - Kiểm tra thông tin khách hàng trước khi cập nhật vào hệ thống - Cung cấp số liệu, hồ sơ liên quan để Bộ phận Hợp đồng tiến hành thủ tục thanh lý khi hết hiệu lực Hợp đồng - Phối hợp cùng Nhân viên Xử lý đơn hàng để thông báo tình hình khách hàng đang vướng công nợ, theo dõi những đơn hàng đang chờ Approve do nợ quá hạn - Phối hợp cùng Nhân viên của Hãng khi khách hàng phản hồi những vấn đề liên quan luân chuyển hàng hóa ảnh hưởng đến việc thu hồi nợ - Liên lạc thường xuyên với nhân viên hãng khi khách hàng phản hồi những vấn đề liên quan đến luân chuyển hàng hóa ảnh hưởng đến việc thu hồi nợ - Thực hiện các công việc phát sinh khác theo phân công của Quản lý trực tiếp. * Địa điểm làm việc tại Tp.HCM: Tòa nhà CitiHouse, 100A Cao Thắng, Quận 3, Tp.HCM.', '- Nam / Nữ sức khỏe tốt - Học vấn: tốt nghiệp Trung cấp trở lên các chuyên ngành - Kinh nghiệm: 01 năm tại vị trí tương đương - Kỹ năng giao tiếp, giải quyết vấn đề và làm việc đội nhóm - Năng động, khéo léo và khả năng chịu được áp lực công việc cao - Sử dụng cơ bản MS.Office.
Kỹ năng chuyên môn: [''Sử dụng cơ bản MS.Office'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Giải quyết vấn đề'', ''Làm việc đội nhóm'', ''Năng động'', ''Khéo léo'', ''Khả năng chịu được áp lực công việc cao'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Từ thứ 2 đến thứ 6 hàng tuần', '[''Thử việc: 02 tháng (100% Lương)'', ''Lương cạnh tranh theo năng lực'', ''Lương tháng 13 và Thưởng cuối năm theo hiệu quả công việc và kết quả kinh doanh Công ty'', ''Tham gia BHXH và Bảo hiểm Sức khỏe theo chính sách Công ty'', ''Khám sức khỏe định kỳ'', ''Hoạt động Team Building'', ''Du lịch hàng năm'', ''Nghỉ chế độ, Phép năm, các ngày Lễ / Tết theo quy định'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (703, 2, 14, 'Kế Toán Trưởng Part Time', 'Kiểm tra, rà soát và ký duyệt chứng từ kế toán, hóa đơn, sổ sách, báo cáo tài chính theo đúng quy định. Tư vấn và giám sát việc tuân thủ các quy định pháp luật về thuế, kế toán, tài chính. Định kỳ lập và/hoặc kiểm tra báo cáo tài chính tháng, quý, năm. Hỗ trợ, hướng dẫn kế toán nội bộ xử lý các vấn đề phát sinh liên quan đến nghiệp vụ kế toán. Làm việc với cơ quan thuế, kiểm toán, ngân hàng hoặc các bên liên quan khi cần thiết. Ký các giấy tờ kế toán, tài chính với tư cách là Kế toán trưởng theo quy định. Hỗ trợ xây dựng, rà soát quy trình kiểm soát nội bộ liên quan đến kế toán – tài chính.', 'Tiếng Trung tốt. Tốt nghiệp Đại học chuyên ngành Kế toán, Tài chính, Kiểm toán. Có Chứng chỉ hành nghề kế toán (CPA Việt Nam) hoặc đủ điều kiện đứng tên kế toán trưởng theo quy định. Tối thiểu 5 năm kinh nghiệm, trong đó có ít nhất 2 năm ở vị trí Kế toán trưởng. Có kinh nghiệm trong lĩnh vực Logistics, Forwarding, Xuất nhập khẩu. Am hiểu luật thuế và các quy định liên quan. Trung thực, cẩn trọng, có tinh thần trách nhiệm cao.
Kỹ năng chuyên môn: [''Phần Mềm Kế Toán (Misa, Fast Accounting)'', ''Kiến Thức Kế Toán Tổng Hợp'', ''Kiến Thức Về Thuế'', ''Kỹ Năng Phân Tích Số Liệu'', ''Kinh Nghiệm Lập Báo Cáo Tài Chính'']
Kỹ năng mềm: [''Trung thực'', ''Cẩn trọng'', ''Có tinh thần trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:30 đến 12:00)', '[''Thời gian làm việc linh hoạt có thể làm từ xa online, chỉ cần lên Công ty 3 buổi/ tuần'', ''Môi trường làm việc chuyên nghiệp, hỗ trợ và cởi mở'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (704, 3, 14, 'Thực Tập Sinh Kế Toán', 'Nhập liệu trên chứng từ thực tế phát sinh cho từng doanh nghiệp. Lên báo cáo thuế. Hạch toán - lên sổ sách. Các công việc liên quan đến thuế - giải trình tại cơ quan thuế theo sự hướng dẫn.', 'Nữ, có thời gian thực tập fulltime là sinh viên năm cuối hoặc tốt nghiệp chuyên ngành kế toán, kiểm toán, tài chính hoặc các chuyên ngành liên quan. Trung thực, chăm chỉ, cẩn thận, có trách nhiệm trong công việc. Khả năng giao tiếp tốt, chủ động và ham học hỏi. Có laptop. Không yêu cầu kinh nghiệm, sẽ được đào tạo trong quá trình làm việc.
Kỹ năng chuyên môn: [''Sử dụng thành thạo phần mềm Excel'']
Kỹ năng mềm: [''Trung thực'', ''Chăm chỉ'', ''Cẩn thận'', ''Có trách nhiệm trong công việc'', ''Khả năng giao tiếp tốt'', ''Chủ động'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), 2 thứ 7 cách tuần làm fulltime', '[''Phụ cấp: Thỏa thuận theo năng lực'', ''Được đào tạo trở thành kế toán thuế- kế toán tổng hợp'', ''Nâng cao kỹ năng thực hành'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (705, 7, 14, 'Thực Tập Sinh Tài Chính - Kế Toán', 'Nghiên cứu thực hành các chế độ về Tài chính – Kế toán. Thực hành các chế độ Tài chính – Kế toán trên phần mềm. Thực hiện các công việc chuyên môn, nghiệp vụ khác theo phân công và hướng dẫn của Công ty.', 'Sinh viên năm cuối hoặc mới tốt nghiệp chuyên ngành: Tài chính, Kế toán, Kiểm toán,... Có khả năng làm full-time. Ưu tiên sinh viên đại học NEU, FTU, BA, AOF, TMU, UEB, …
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Hòa đồng'', ''Năng động'', ''Kỹ năng thuyết trình'', ''Tinh thần trách nhiệm'', ''Nhiệt tình trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 3 - Chủ nhật (từ 08:00 đến 18:30)', '[''Được công ty tạo điều kiện tiếp cận, thực hành các chế độ Tài chính - Kế toán'', ''Được hỗ trợ tài chính trong quá trình thực tập từ 3,000,000 đến 5,000,000 đồng/ tháng'', ''Có cơ hội trở thành nhân viên chính thức sau quá trình thực tập'', ''Làm việc trong môi trường hiện đại, năng động, bình đẳng, phát huy tối đa tính sáng tạo'', ''Được trang bị đầy đủ trang thiết bị phục vụ công việc'', ''Được đào tạo, tư vấn, chia sẻ về nghiệp vụ, nâng cao kiến thức chuyên môn về kỹ năng mềm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (706, 8, 14, 'Kế toán viên thực tập', 'Hỗ trợ team Account/Booking các thủ tục hợp đồng kinh doanh, tính thuế, thanh toán với các đối tác, KOC, KOL. Hỗ trợ công việc team kế toán. Hỗ trợ sắp xếp hồ sơ, in ấn, hoàn thiện chứng từ kế toán. Được đào tạo xuất hóa đơn, kê khai thuế. Thực hiện các thủ tục Ngân hàng, bảo hiểm, cơ quan thuế.', '1. Có laptop cá nhân để có thể làm việc. 2. Là người hòa đồng, nhanh nhẹn, có kỷ luật cao trong công việc. 3. Có tinh thần làm việc chủ động, trách nhiệm, chịu được áp lực cao và có mong muốn gắn bó lâu dài với công ty. 4. Tò mò, cầu tiến & ham học hỏi, chủ động đề xuất & tự học.
Kỹ năng chuyên môn: [''Microsoft Word'', ''Excel (cao cấp)'', ''Phần Mềm Kế Toán (ví Dụ: Misa, Fast Accounting)'']
Kỹ năng mềm: [''Hòa đồng'', ''Nhanh nhẹn'', ''Kỷ luật cao'', ''Chủ động'', ''Trách nhiệm'', ''Chịu được áp lực cao'', ''Tò mò'', ''Cầu tiến'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00) hoặc (từ 09:00 đến 18:30)', '[''Môi trường lý tưởng để phát triển'', ''Thời gian làm việc linh hoạt'', ''Quy trình và môi trường làm việc trẻ trung, hiện đại'', ''Được hưởng các chế độ phúc lợi như nhân viên chính thức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (707, 9, 14, 'Thực Tập Kế Toán', 'Hỗ trợ các công việc về kế toán, xuất hóa đơn trong công ty. Sắp xếp các chứng từ kế toán theo quy trình. Kiểm tra, đối chiếu số liệu kê khai báo cáo thuế. Hỗ trợ thực hiện các công việc khác theo sự phân công của trưởng phòng kế toán.', 'Sinh viên năm thứ 4 đại học, chuyên ngành Kế toán, Tài chính. Có kiến thức cơ bản về hóa đơn, chứng từ. Có khả năng phân tích, sắp xếp dữ liệu. Cẩn thận, tỉ mỉ, chịu khó. Có khả năng làm việc độc lập và nhóm. Thực tập toàn thời gian.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về hóa đơn, chứng từ'', ''Khả năng phân tích, sắp xếp dữ liệu'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Chịu khó'', ''Khả năng làm việc độc lập và nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được đào tạo bài bản về nghiệp vụ kế toán'', ''Được cấp chứng nhận thực tập sau khi hoàn thành khóa thực tập'', ''Thực tập 6 tháng (100.000VNĐ/ ngày)'', ''Cơ hội trở thành nhân viên chính thức sau 3 - 6 tháng'', ''Tính chất công việc ổn định, văn hóa Công ty thân thiện'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (708, 10, 14, 'Thực Tập Sinh Kế Toán - Thuế (CV Tiếng Anh)', '• Nhập các giao dịch kế toán của khách hàng vào phần mềm kế toán (phần mềm FAST); • Tính và lập bảng lương hàng tháng cho khách hàng, bao gồm thuế TNCN (cả người Việt Nam và người nước ngoài), bảo hiểm bắt buộc; • Hỗ trợ khách hàng trong các thủ tục nộp cho cơ quan chức năng (tờ khai thuế, hồ sơ đăng ký bảo hiểm, v.v.); liên lạc với chính quyền khi cần thiết; • Soạn thảo và sắp xếp các chứng từ kế toán, thuế; • Các nhiệm vụ đặc biệt khác theo yêu cầu của người quản lý.', '• Sinh viên năm 3,4 đại học chuyên ngành Kế toán, Kiểm toán hoặc Tài chính; • Sử dụng thành thạo các công cụ văn phòng, đặc biệt là excel; • Có trách nhiệm trong công việc
Kỹ năng chuyên môn: [''Sử dụng thành thạo các công cụ văn phòng'', ''Excel'']
Kỹ năng mềm: [''Có trách nhiệm trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ lương hàng tháng + các phụ phí khác'', ''Hỗ trợ báo cáo thực tập'', ''Hỗ trợ phụ cấp khi đi công tác'', ''Tham gia các chương trình sự kiện của công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (709, 2, 14, 'Kế Toán Tổng Hợp - Part-Time', 'Thực hiện các nghiệp vụ kế toán tổng hợp: hạch toán chứng từ, đối chiếu số liệu, lập báo cáo tài chính, báo cáo thuế hàng tháng/quý/năm. Kiểm tra và đảm bảo tính hợp lệ của hóa đơn, chứng từ kế toán. Hỗ trợ rà soát, hoàn thiện sổ sách kế toán theo yêu cầu. Phối hợp làm việc với kế toán nội bộ, thuế hoặc kiểm toán (nếu có). Các công việc khác theo sự phân công của quản lý.', 'Có kinh nghiệm tối thiểu 2 năm ở vị trí kế toán tổng hợp. Tốt nghiệp: đại học học viện tài chính, đại học thương mại, ưu tiên có kinh nghiệm 5 năm kế toán thuế. Am hiểu các quy định, luật thuế, chế độ kế toán hiện hành. Ưu tiên ứng viên đã từng làm việc cho doanh nghiệp vừa và nhỏ. Có thể làm việc part-time tại văn phòng (số buổi linh hoạt). Trung thực, cẩn thận, chủ động trong công việc.
Kỹ năng chuyên môn: [''Hạch toán chứng từ'', ''Lập báo cáo tài chính'', ''Báo cáo thuế'']
Kỹ năng mềm: [''Trung thực'', ''Cẩn thận'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Số buổi linh hoạt', '[''Môi trường làm việc thân thiện'', ''Cơ hội làm việc lâu dài nếu phù hợp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (710, 3, 14, 'Thực Tập Sinh Kế Toán', '- Kiểm tra và nhập dữ liệu kế toán vào hệ thống theo yêu cầu - Kiểm tra chứng từ kế toán, định khoản nghiệp vụ phát sinh - Lưu trữ các chứng từ kế toán - Hỗ trợ cập nhật chứng từ, kê khai thuế, làm sổ sách, lập báo cáo tài chính - Hỗ trợ cập nhật kịp thời các nghiệp vụ vào phần mềm kế toán - Hỗ trợ lập báo cáo tài chính theo quý/năm - Các công việc khác theo sự phân công của cấp trên', '- Sinh viên năm 3 hoặc năm cuối khoa kế toán thuộc các trường cao đẳng, đại học. - Giới tính: Nữ. - Không cần có kinh nghiệm, ưu tiên các bạn có mong muốn nâng cao kỹ năng về kế toán thuế, khả năng vi tính tốt - Khả năng vi tính tốt, nhanh nhẹn. - Nhanh nhẹn, tác phong chuyên nghiệp - Yêu thích công việc - Cẩn thận, nhiệt tình, ham học hỏi
Kỹ năng chuyên môn: [''Khả năng vi tính tốt'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Tác phong chuyên nghiệp'', ''Yêu thích công việc'', ''Cẩn thận'', ''Nhiệt tình'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được đào tạo kế toán thuế trong môi trường bài bản, chuyên nghiệp, có quy trình rõ ràng.'', ''Đóng dấu mộc chứng nhận thực tập'', ''Hỗ trợ thực tập 03 tháng (33 ngày đầu: 60.000 đồng/Ngày, các ngày tiếp theo: 120.000 đồng/Ngày)'', ''Có thể được nhận làm chính thức sau khi tốt nghiệp.'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (711, 7, 14, 'Cộng Tác Viên Kế Toán Dịch Vụ - Đi Làm Ngay', 'Chịu trách nhiệm chuyên môn: Trực tiếp tiếp nhận và phụ trách toàn bộ công tác kế toán - thuế cho các khách hàng doanh nghiệp được phân công. Xử lý sổ sách & chứng từ: Kiểm tra tính hợp lý, hợp lệ của hóa đơn, chứng từ do khách hàng cung cấp. Thực hiện hạch toán, ghi nhận tất cả các nghiệp vụ kinh tế phát sinh vào phần mềm kế toán chuyên dụng. Kê khai và Báo cáo Thuế: Lập và nộp các tờ khai thuế định kỳ (GTGT, TNCN,...) theo đúng thời hạn quy định. Lập Báo cáo tài chính và Quyết toán thuế TNDN, TNCN cuối năm cho khách hàng. Tư vấn và hỗ trợ: Tư vấn cho khách hàng các vấn đề cơ bản liên quan đến luật thuế, kế toán để tối ưu chi phí và đảm bảo tuân thủ pháp luật. Làm việc, giải trình số liệu với cơ quan thuế khi có yêu cầu. Báo cáo nội bộ: Báo cáo định kỳ về tiến độ và kết quả công việc cho quản lý trực tiếp tại công ty.', 'Có ít nhất 02 năm kinh nghiệm ở vị trí Kế toán tổng hợp hoặc Kế toán dịch vụ. Ưu tiên hàng đầu ứng viên đã làm việc tại các công ty dịch vụ kế toán. Sử dụng thành thạo phần mềm kế toán phổ biến (MISA, Fast, Bravo,...). Kỹ năng tổ chức, sắp xếp công việc một cách khoa học để quản lý nhiều khách hàng cùng lúc. Kỹ năng làm việc độc lập, tự chủ và có trách nhiệm cao. Tự chủ về công cụ làm việc (máy tính cá nhân).
Kỹ năng chuyên môn: [''Sử dụng phần mềm kế toán (MISA, Fast, Bravo)'']
Kỹ năng mềm: [''Kỹ năng tổ chức'', ''Kỹ năng làm việc độc lập'', ''Tự chủ và có trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thời gian làm việc hoàn toàn linh hoạt', '[''Thu nhập hấp dẫn, cạnh tranh'', ''Cơ chế tính thu nhập minh bạch'', ''Chủ yếu làm việc từ xa'', ''Được hỗ trợ về mặt chuyên môn từ đội ngũ chuyên gia'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (712, 8, 14, 'Thực Tập Sinh Kế Toán', 'Nhập liệu lên phần mềm: Nhập mua đầu vào, nhập hóa đơn, nhập giải ngân... Hỗ trợ xuất hóa đơn, lưu hóa đơn file XML, cung cấp bản sao theo yêu cầu của khách hàng hoặc các bên liên quan. In ấn hồ sơ, sổ sách và lưu trữ. Các công việc khác theo yêu cầu của cấp trên.', 'Các bạn sinh viên năm 3, 4 học các chuyên ngành Kế toán, Kiểm toán, Tài chính, Luật tại các trường Đại học, Học viện, ưu tiên các bạn đang trong kỳ thực tập. Không yêu cầu kinh nghiệm; Trung thực, tinh thần trách nhiệm cao; Có thái độ nhiệt tình, cầu tiến trong công việc. Làm việc tối thiểu 4 buổi/ tuần.
Kỹ năng mềm: [''Trung thực'', ''Tinh thần trách nhiệm cao'', ''Thái độ nhiệt tình'', ''Cầu tiến trong công việc'']', 'INTERNSHIP', 'ONSITE', 'tây ninh', 'Tây Ninh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 16:30)', '[''Có cơ hội trở thành nhân viên chính thức sau thời gian thực tập từ 03-06 tháng'', ''Môi trường làm việc thân thiện, chuyên nghiệp'', ''Được hướng dẫn công việc, đào tạo các kỹ năng mềm'', ''Hỗ trợ phụ cấp cơm trưa'', ''Hỗ trợ đóng mộc và đánh giá sau thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (713, 9, 14, 'Thực Tập Sinh Kế Toán', 'Nhập liệu và xử lý sổ sách kế toán. Lưu trữ chứng từ kế toán. Được đào tạo về các nghiệp vụ phát sinh tại phần mềm. Hỗ trợ các công việc khác dưới sự phân công của quản lý, có hướng dẫn cụ thể.', 'Là sinh viên năm 04 đang theo học tại các Trường Đại học chuyên ngành Kế toán - Kiểm toán. Hiểu biết kiến thức về chuyên môn kế toán, quy định, chuẩn mực, thông tư kế toán. Biết sử dụng các phần mềm kế toán là một lợi thế. Chỉn chu, cẩn thận và chi tiết. Có khả năng học hỏi nhanh, năng động, linh hoạt.
Kỹ năng chuyên môn: [''Sử dụng phần mềm kế toán'']
Kỹ năng mềm: [''Chỉn chu'', ''Cẩn thận'', ''Chi tiết'', ''Khả năng học hỏi nhanh'', ''Năng động'', ''Linh hoạt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Hỗ trợ mộc và số liệu cho sinh viên làm báo cáo thực tập'', ''Môi trường làm việc chuyên nghiệp, thân thiện'', ''Khóa đào tạo không giới hạn để nâng cao kỹ năng'', ''Có thể trở thành nhân viên sau khi kết thúc thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (714, 10, 14, 'Thực Tập Sinh Kế Toán', 'Hoàn thành các nhiệm vụ phân công của kế toán, người hướng dẫn trực tiếp; Đọc hiểu ngành nghề kinh doanh của công ty, các tài khoản ghi sổ thường dùng; Hỗ trợ kiểm tra các tài khoản ghi sổ; Hỗ trợ phòng kế toán thu thập, nhập dữ liệu thô vào phần mềm; Giúp kiểm tra, đối chiếu số liệu ghi sổ với các hóa đơn, chứng từ ngân hàng; Hỗ trợ xử lý hồ sơ kế toán; Giúp kiểm tra, xử lý bảng cân đối kế toán; Học cách thực hiện các báo cáo thu nhập và báo cáo tài chính theo sự hướng dẫn; Hỗ trợ rà soát chi phí, hoặc hồ sơ thuế, các chi tiêu ở công ty; Cập nhập các thông tin, kiểm tra và cập nhật các số liệu lên phần mềm theo sự phân công của phòng ban.', 'Sinh viên đang có nhu cầu thực tập hoặc sinh viên vừa mới tốt nghiệp chuyên ngành: chuyên ngành Tài chính - kế toán; Không yêu cầu kinh nghiệm; Tiếng Anh đọc hiểu chuyên ngành; Trung thực và kỹ năng làm việc độc lập, làm việc nhóm; Kỹ năng giao tiếp tốt, quyết đoán, khéo léo, chịu được áp lực công việc.
Kỹ năng chuyên môn: [''Sử dụng phần mềm kế toán'', ''Nhập dữ liệu'']
Kỹ năng mềm: [''Trung thực'', ''Kỹ năng làm việc độc lập'', ''Kỹ năng làm việc nhóm'', ''Kỹ năng giao tiếp'', ''Quyết đoán'', ''Khéo léo'', ''Chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', '8h30 đến 12h, 13h30 đến 17h30 từ Thứ 2 đến Thứ 6', '[''Được giữ lại Công ty làm việc chính thức nếu được đánh giá tốt'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (715, 2, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ nhập liệu, kiểm tra và đối chiếu chứng từ kế toán. Theo dõi, kiểm tra công nợ phải thu, phải trả. Hỗ trợ lập báo cáo tài chính, báo cáo thuế, hóa đơn điện tử. Sắp xếp, lưu trữ chứng từ kế toán theo quy định. Thực hiện các công việc khác theo sự phân công của kế toán viên/kế toán trưởng.', 'Sinh viên năm 3, 4 hoặc mới tốt nghiệp chuyên ngành Kế toán, Kiểm toán, Tài chính. Có thể làm Fulltime. Thành thạo tin học văn phòng (Excel, Word); biết sử dụng phần mềm kế toán (MISA, Fast...). Cẩn thận, trung thực, có trách nhiệm, ham học hỏi.
Kỹ năng chuyên môn: [''Tin học văn phòng (Excel, Word)'', ''Phần mềm kế toán (MISA, Fast)'']
Kỹ năng mềm: [''Cẩn thận'', ''Trung thực'', ''Có trách nhiệm'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Có cơ hội phát triển lớn cùng với lộ trình thăng tiến rõ ràng'', ''Được tiếp cận với các nền tảng công nghệ mới'', ''Hỗ trợ dấu thực tập'', ''Thưởng thâm niên'', ''Thưởng các ngày lễ, sinh nhật CBNV, sinh nhật Công ty'', ''Đóng BHXH, BHYT và đầy đủ các chế độ phúc lợi của công ty, nghỉ phép 12 ngày/năm khi lên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (716, 3, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ các anh/chị phòng dịch vụ hạch toán số liệu; Hoàn thiện hồ sơ, chứng từ đi kèm với các nghiệp vụ kinh tế phát sinh; In sổ sách; Các bạn xuất sắc sẽ được hướng dẫn hoàn thiện chứng từ, lập báo cáo tài chính, quyết toán thuế hoàn chỉnh từ A Z cho các công ty khách hàng của Đại Lý thuế ATC; Các công việc khác theo sự phân công của cấp trên; Thực tập sinh tối đa 04 tháng.', 'Tuổi 22-28; Giới tính: Nam/Nữ; Hoàn thành chương trình Đại học trở lên chuyên ngành: Kế toán - Tài chính; Thành thạo tin học văn phòng; Nhanh nhẹn, trung thực, có tinh thần trách nhiệm cao, ham học hỏi, chịu được áp lực công việc.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Trung thực'', ''Có tinh thần trách nhiệm cao'', ''Ham học hỏi'', ''Chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 1000000.00, '1.5 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Thưởng 04 lần/năm'', ''Được đóng đầy đủ BHXH, BHYT, BHTN khi làm nhân viên chính thức'', ''Được đào tạo các kỹ năng quản lý trong công việc hàng ngày'', ''Đi du lịch nghỉ mát hàng năm'', ''Tham gia các hoạt động văn hoá thể thao'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (717, 7, 14, 'Thực Tập Sinh Kế Toán', 'Hỗ trợ, cọ sát thực tế các công việc theo chuyên ngành, được hướng dẫn từ người phụ trách chuyên môn. Lên kế hoạch và đưa ra mục tiêu hoàn thành. Hỗ trợ các bộ phận liên quan để hoàn thành nhiệm vụ. Chủ động trong công việc. Làm báo cáo, đề xuất các giải pháp, định hướng phát triển khi kết thúc thời gian thực tập.', 'Các sinh viên trong thời gian thực tập tại các trường CĐ, ĐH mong muốn có môi trường trải nghiệm thực tế chuyên ngành kỹ thuật, kinh tế, Marketing… Ham học hỏi, nhiệt tình, chủ động trong công việc. Có khả năng làm việc độc lập và làm việc nhóm, tinh thần trách nhiệm cao. Nhanh nhẹn, chịu khó, biết lên kế hoạch cho công việc với mục tiêu rõ ràng.
Kỹ năng chuyên môn: [''Kiến Thức Cơ Bản Về Kế Toán'', ''Sử Dụng Thành Thạo Phần Mềm Excel'', ''Khả Năng Phân Tích Số Liệu'']
Kỹ năng mềm: [''Khả Năng Làm Việc Nhóm'', ''Trung Thực'', ''Cẩn Thận'', ''Ham học hỏi'', ''Nhiệt tình'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Cơ hội tiếp cận môi trường làm việc thực tế'', ''Được training đào tạo'', ''Cơ hội trở thành nhân viên chính thức'', ''Môi trường chuyên nghiệp, thân thiện'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (718, 8, 14, 'Trợ lý quy trình tài chính bán thời gian', '1. Thu thập và tổng hợp thông tin quy trình: Làm việc với các bộ phận để ghi nhận các bước công việc hiện tại đang thực thi. Chuẩn hóa biểu mẫu thu thập thông tin và cập nhật dữ liệu vào hệ thống tài liệu chuẩn. Chuyển thông tin thành sơ đồ quy trình chi tiết bằng công cụ trực quan (flowchart). 2. Tham gia rà soát và cải tiến quy trình vận hành: Xác định các điểm yếu trong quy trình hiện tại, bao gồm: bước trùng lặp, thiếu kiểm soát, hoặc chưa có tiêu chuẩn. Tổng hợp và hệ thống hóa các điểm yếu để hỗ trợ quản lý đề xuất phương án cải tiến. 3. Hỗ trợ cập nhật và hoàn thiện tài liệu quy trình sau cải tiến: Lập và điều chỉnh sơ đồ quy trình mới theo định hướng cải tiến từ người quản lý. Cập nhật lại tài liệu mô tả quy trình, checklist và các biểu mẫu liên quan.', 'Sinh viên năm 3 trở lên chuyên ngành Kế toán, Kiểm toán, Tài chính hoặc các lĩnh vực liên quan. Có khả năng thu thập, phân tích và tổng hợp thông tin một cách logic và chính xác. Sử dụng thành thạo Microsoft Excel và PowerPoint; ưu tiên ứng viên biết sử dụng các công cụ vẽ sơ đồ quy trình như Lucidchart, Visio hoặc Miro. Tỉ mỉ, cẩn thận, trung thực, có tinh thần trách nhiệm và thái độ cầu tiến. Có định hướng phát triển nghề nghiệp trong lĩnh vực tài chính – kế toán và mong muốn học hỏi thông qua các dự án thực tế.
Kỹ năng chuyên môn: [''Microsoft Excel'', ''PowerPoint'', ''Lucidchart'', ''Visio'', ''Miro'']
Kỹ năng mềm: [''Tỉ mỉ'', ''Cẩn thận'', ''Trung thực'', ''Có tinh thần trách nhiệm'', ''Thái độ cầu tiến'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:45)', '[''Môi trường làm việc trẻ trung, năng động, nhiều cơ hội học hỏi'', ''Được đào tạo và tiếp cận thực tế với công việc tài chính'', ''Có cơ hội phát triển bản thân và định hướng nghề nghiệp rõ ràng'', ''Phụ cấp xăng xe'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (719, 9, 14, 'Thực Tập Sinh Kế Toán', '- Tiếp nhận và kiểm tra hóa đơn mua vào + hóa đơn bán ra - Kiểm tra, đối chiếu sao kê ngân hàng - Xuất hóa đơn GTGT cho khách hàng khi có yêu cầu - Hỗ trợ các công việc khác của kế toán trưởng khi có yêu cầu', '- Ưu tiên sinh viên năm 4 các trường đại học chuyên ngành kế toán. - Sẵn sàng làm việc toàn thời gian thực tập - Có laptop cá nhân - Trung thực, chăm chỉ, cẩn thận, chính xác
Kỹ năng mềm: [''Trung thực'', ''Chăm chỉ'', ''Cẩn thận'', ''Chính xác'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 triệu', 'Toàn thời gian', '[''Hỗ trợ chi phí trong thời gian thực tập: 2.000.000 vnđ/ tháng'', ''Trải nghiệm môi trường làm việc thực tế, năng động, sáng tạo'', ''Có cơ hội được lên chính thức ở vị trí tương đương sau thời gian thực tập'', ''Môi trường làm việc: Được làm việc trong môi trường năng động, sáng tạo, nhiều thử thách'', ''Được kèm cặp bởi đội ngũ nhân sự trẻ trung, dễ gần'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (720, 10, 14, 'Kế Toán Kho Bán Thời Gian', '• Kiểm soát kho hàng, kiểm tra số liệu tồn kho khớp với số bán, số hủy, hàng sản xuất & luân chuyển nội bộ • Thực hiện kiểm kê kho định kỳ mỗi tuần (vào cuối tuần) • Lập biên bản chênh lệch, vi phạm nếu có • Gửi báo cáo kho cho cấp quản lý theo mẫu chuẩn', '• Có kinh nghiệm làm kế toán kho trong ngành thực phẩm, sản xuất. • Trung thực, chững chạc, làm việc có trách nhiệm. • Biết sử dụng cơ bản Excel và hiểu quy trình luân chuyển hàng hóa nội bộ. Ưu tiên biết sử dụng Misa và Kiot Việt.
Kỹ năng chuyên môn: [''Excel'', ''Misa'', ''Kiot Việt'']
Kỹ năng mềm: [''Trung thực'', ''Chững chạc'', ''Làm việc có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', '1 buổi/tuần (thứ 7 hoặc chủ nhật)', '[''Mức lương cạnh tranh'', ''Thời gian làm việc linh hoạt'', ''Thưởng các dịp Lễ, Tết theo quy định của công ty'', ''Hỗ trợ phụ cấp ăn trưa (nếu có)'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (721, 2, 14, 'Thực Tập Sinh Nhập Liệu', 'Nhập số liệu theo hướng dẫn của kế toán. Sắp xếp hồ sơ. Lưu trữ chứng từ. Sắp xếp ngăn nắp, khoa học. Lưu trữ chứng từ, hồ sơ hợp lý.', 'Cần có mặt tại công ty được 3 ngày 1 tuần. Nam/ nữ đều được. Không yêu về chuyên môn, kinh nghiệm.
Kỹ năng mềm: [''Cần cù siêng năng'', ''Cẩn thận'', ''Tỉ mỉ'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '1.5 - 2.0 triệu', '8h – 17h (nghỉ trưa 1 tiếng rưỡi)', '[''Công ty hỗ trợ đóng dấu thực tập'', ''Công ty hỗ trợ cơm trưa tại văn phòng'', ''Công ty hỗ trợ thêm 1 triệu/ tháng tiền xăng xe đi lại'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (722, 3, 14, 'Thực Tập Sinh Kế Toán', 'Thực hiện kiểm soát và theo dõi hàng hoá, lập phiếu xuất- nhập kho, lập các báo cáo hàng tồn kho, thực hiện các nghiệp vụ kế toán hạch toán trên misa.', 'Các bạn sinh viên năm 3-4 chuyên ngành kế toán. Trung thực, chịu khó học hỏi, tiếp thu. Đã từng tiếp xúc, có kiến thức cơ bản phần mềm Misa.
Kỹ năng chuyên môn: [''Phần mềm Misa'']
Kỹ năng mềm: [''Trung thực'', ''Chịu khó học hỏi'', ''Tiếp thu'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Hỗ trợ phụ cấp cho thực tập sinh'', ''Hỗ trợ dấu mộc báo cáo thực tập'', ''Được training đầy đủ trong môi trường làm việc thân thiện'', ''Có cơ hội thăng tiến thành nhân viên chính thức'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (723, 7, 14, 'Kế Toán Học Việc', 'Tiếp nhận thông tin, lập chứng từ hồ sơ kế toán. Theo dõi hạch toán, định khoản lên sổ sách. Cân đối doanh thu chi phí, lên báo cáo tài chính. Kê khai thuế, quyết toán thuế cuối quý, cuối năm. Hỗ trợ trưởng nhóm làm việc với cơ quan thuế, bảo hiểm. In hoàn thiện hồ sơ kế toán, lưu trữ và bàn giao cho khách hàng.', 'Tốt nghiệp Cao đẳng/ Đại học chuyên ngành kế toán. Yêu cầu bắt buộc: Đã học khóa thực hành kế toán tại các trung tâm dạy thực hành. Nhanh nhẹn, trung thực, có tinh thần cầu thị. Thành thạo tin học văn phòng.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Trung thực'', ''Có tinh thần cầu thị'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '5.0 - 8.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được training chuyên môn nghiệp vụ'', ''Phụ cấp ăn trưa'', ''Thưởng hiệu quả làm việc'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (724, 8, 14, 'Kế Toán Viên', 'Theo dõi khoản phải trả (bao gồm phải trả khác), chi phí khác cho nhà cung cấp thuộc công ty. Kiểm tra chứng từ thanh toán đúng hợp lệ, hợp lý khi bộ phận điều độ, kinh doanh, tài xế,… đề xuất thanh toán nhà cung cấp. Kiểm tra, đối chiếu và báo cáo công nợ phải trả đối với từng nhà cung cấp. Theo dõi các khoản tạm ứng, tính lương tài xế, theo dõi nhập xuất tồn kho dầu, nhớt và khí thải…', 'Tốt nghiệp Cao đẳng/ Đại học chuyên ngành Kế toán, Tài chính, hoặc các chuyên ngành liên quan. Từ 01 năm kinh nghiệm ở vị trí tương đương, ưu tiên ứng viên có kinh nghiệm trong lĩnh vực logistics. Tinh thần trách nhiệm cao, trung thực, cẩn thận. Có khả năng làm việc độc lập và chịu được áp lực công việc.
Kỹ năng chuyên môn: [''Phần Mềm Kế Toán (Misa, Fast Accounting)'', ''Sử Dụng Thành Thạo Excel'']
Kỹ năng mềm: [''Tinh thần trách nhiệm cao'', ''Trung thực'', ''Cẩn thận'', ''Có khả năng làm việc độc lập và chịu được áp lực công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:15), Thứ 7 (từ 08:00 đến 12:00)', '[''Chế độ nghỉ mát hàng năm'', ''Khám sức khỏe định kỳ'', ''Đóng BHXH, BHTN, BHYT và các chế độ khác theo luật Lao động'', ''Ngày nghỉ: nghỉ chế độ, phép năm'', ''Thưởng lễ, Tết, sinh nhật'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (725, 9, 8, 'Giáo Viên Tiếng Anh Online/Offline', '- Có thể dạy online hoặc offline. - Giảng dạy tiếng Anh giao tiếp. - Đối tượng học viên: Người đi làm. - Số lượng học viên: 1- 6 học viên/ 1 lớp. - Giáo viên đăng ký nhận lớp theo tuần, chịu trách nhiệm theo sát cho 1 khoá học khoảng 40 -80 giờ của học viên.', '- Sinh năm 1982-2002. - Tiếng Anh thành thạo 4 kỹ năng (nghe, nói, đọc, viết), phát âm chuẩn, diễn đạt ý rõ ràng. - Ưu tiên có chứng chỉ Tiếng Anh: IELTS từ 7.0, TOEIC từ 800. Tốt nghiệp Sư phạm Anh, Ngôn ngữ Anh hoặc chứng chỉ nghiệp vụ sư phạm tương đương: TESOL, CELTA,… - Tác phong chuyên nghiệp, đúng giờ và trách nhiệm cao với công việc. - Có kinh nghiệm giảng dạy tiếng Anh cho người đi làm là một lợi thế. - Ngoại hình ưa nhìn là một lợi thế. - Với dạy online: Có máy tính cá nhân, có webcam, có mic, có đường truyền Internet ổn định. Có không gian, địa điểm phù hợp để giảng dạy.
Kỹ năng chuyên môn: [''Tiếng Anh thành thạo 4 kỹ năng (nghe, nói, đọc, viết)'', ''Phát âm chuẩn'']
Kỹ năng mềm: [''Tác phong chuyên nghiệp'', ''Đúng giờ'', ''Trách nhiệm cao với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 12000000.00, '10.0 - 12.0 triệu', 'Thời gian giảng dạy linh động (ca sáng, ca chiều, ca tối)', '[''Được đào tạo phương pháp giảng dạy'', ''Môi trường làm việc tự do, tại nhà'', ''Tiếp cận với hệ thống phần mềm hiện đại'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (726, 10, 8, 'Cộng Tác Viên Biên Dịch Tiếng Trung, Nhật, Hàn, Nga, Pháp', 'Biên phiên dịch đa ngôn ngữ (tiếng Trung, tiếng Pháp, tiếng Nhật, Hàn Quốc, Nga) cho các văn bản, tài liệu khác nhau tùy thuộc vào yêu cầu của công ty. Đảm bảo tính chính xác, sự mạch lạc và rõ ràng của bản dịch, tuân thủ đúng các quy tắc ngữ pháp và văn phong của ngôn ngữ đích. Nghiên cứu và làm quen với các thuật ngữ chuyên ngành liên quan đến các dự án được giao. Phối hợp với các bộ phận khác trong công ty để hoàn thành công việc một cách hiệu quả. Quản lý thời gian và công việc cá nhân một cách hiệu quả để đáp ứng tiến độ các dự án. Có khả năng làm việc độc lập và làm việc nhóm. Thường xuyên cập nhật kiến thức và từ vựng chuyên ngành để nâng cao chất lượng dịch thuật. Đi phiên dịch (nếu có).', 'Tốt nghiệp Đại học chuyên ngành Ngôn ngữ, phiên dịch hoặc các chuyên ngành liên quan. Ít nhất 3 năm kinh nghiệm trong lĩnh vực biên phiên dịch đa ngôn ngữ. Thành thạo ít nhất 2 ngoại ngữ đăng ký biên phiên dịch. Có kỹ năng biên phiên dịch tốt, đảm bảo tính chính xác và sự mạch lạc của bản dịch. Có khả năng làm việc dưới áp lực cao và đáp ứng tiến độ công việc. Biết sử dụng phần mềm hỗ trợ dịch thuật (CAT tools) như Trados Studio, MemoQ, SDL Studio, là một lợi thế.
Kỹ năng chuyên môn: [''Sử dụng phần mềm hỗ trợ dịch thuật (CAT tools) như Trados Studio, MemoQ, SDL Studio'']
Kỹ năng mềm: [''Kỹ năng biên phiên dịch tốt'', ''Khả năng làm việc dưới áp lực cao'', ''Quản lý thời gian hiệu quả'', ''Làm việc độc lập và làm việc nhóm'']', 'FREELANCE', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Mức lương cạnh tranh'', ''Cơ hội được đào tạo và nâng cao trình độ chuyên môn'', ''Được làm việc remote'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (727, 2, 8, 'Thực Tập Sinh Comtor Tiếng Nhật', 'Biên dịch tài liệu Nhật - Việt, Việt - Nhật; Phiên dịch trong các cuộc họp dự án, đảm bảo thông tin dự án được truyền đạt chính xác và kịp thời cho cả khách hàng và nhóm phát triển; Hỗ trợ các thành viên trong nhóm về kỹ năng chuyên môn và phối hợp với Trưởng nhóm dự án trong việc quản lý tiến độ dự án; Có thể đi công tác nếu dự án yêu cầu; Các nhiệm vụ khác theo yêu cầu của dự án (nếu có).', 'Trình độ tiếng Nhật từ N2 trở lên; Có khả năng giao tiếp tốt, xử lý tình huống linh hoạt; Yêu thích và có hứng thú làm việc trong lĩnh vực công nghệ, Phần mềm, sản xuất; Tinh thần trách nhiệm cao, nghiêm túc trong công việc; Có khả năng làm việc độc lập cũng như phối hợp nhóm hiệu quả; Tiếng Anh thương mại (không bắt buộc); Tính cách vui vẻ, hòa đồng.
Kỹ năng chuyên môn: [''Tiếng Nhật N2'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Xử lý tình huống linh hoạt'', ''Làm việc độc lập'', ''Phối hợp nhóm hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:45)', '[''Phụ cấp thỏa thuận'', ''Cơ hội lên chính thức với mức lương cạnh tranh'', ''Được hướng dẫn, đào tạo kỹ năng liên quan đến nghề'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (728, 3, 8, 'Thực Tập Sinh Vị Trí Kỹ Sư Cầu Nối', 'Tham gia vào khóa đào tạo vị trí Comtor theo giáo trình được xây dựng riêng (đào tạo kỹ thuật chuyên ngành, từ vựng chuyên ngành, các bước trong dự án, phương thức báo cáo,…v…v). Được kết hợp lý thuyết và thực hành. Được cọ sát với dự án thực tế. Trải nghiệm môi trường làm việc thực sự (có áp lực, có deadline).', 'Sinh viên năm cuối, đã tốt nghiệp chuyên ngành Tiếng Nhật tại các trường Đại học như: Đại học Ngoại Ngữ, Đại học Ngoại thương, Đại học Hà Nội,…v…v hoặc khoa công nghệ thông tin (tương đương) đã có tiếng Nhật. Tiếng Nhật từ N2. Chủ động, trách nhiệm trong công việc. Đảm bảo thời gian làm việc tối thiểu 5 buổi/ tuần (sáng, chiều).
Kỹ năng chuyên môn: [''Tiếng Nhật từ N2'']
Kỹ năng mềm: [''Chủ động'', ''Trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6', '[''Hỗ trợ dấu mộc thực tập'', ''Cơ hội tham gia khóa đào tạo nâng cao, trở thành nhân viên chính thức'', ''Lịch làm việc thay đổi linh hoạt với lịch học'', ''Tiếp xúc với dự án thực tế'', ''Lộ trình đào tạo xây dựng kỹ lưỡng, sát thực tế'', ''Miễn phí trà, cà phê tại khu vực ăn uống của công ty'', ''Máy pha cà phê tiện ích tại văn phòng'', ''Party cuối thứ 6 hàng tuần'', ''Các CLB thể thao: bóng đá, cầu lông, bilac, game'', ''Chương trình radio phát nhạc, confession theo yêu cầu'', ''Seminar về kiến thức chuyên môn, ngoại ngữ và các kỹ năng khác'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (729, 7, 8, 'Thực Tập Sinh/Part-Time Học Thuật Tiếng Hàn', 'Làm việc, thực tập tại trung tâm Hàn ngữ Saechang; Hỗ trợ soạn và sửa slide Powerpoint giảng dạy; Hỗ trợ nhập liệu và soạn câu hỏi bài tập và dịch nội dung liên quan tới các khoá học tiếng Hàn.', 'Có Topik 5 trở lên hoặc có bằng tương đương; Phù hợp với các bạn có nhu cầu thực tập; Có thể lên văn phòng tại Quận 2 ít nhất 3 ngày trong tuần để làm việc; Ưu tiên các bạn chuyên ngành ngôn ngữ Hàn; Đảm bảo giờ làm việc 32 giờ/ tuần (Thời gian làm việc tuỳ vào lịch học của ứng viên).
Kỹ năng chuyên môn: [''Ngữ Pháp Tiếng Hàn'', ''Kỹ Năng Nghe Hiểu Tiếng Hàn'', ''Từ Vựng Tiếng Hàn'', ''Kỹ Năng Đọc Hiểu Tiếng Hàn'', ''Kỹ Năng Giao Tiếp Tiếng Hàn'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Hỗ trợ cơm trưa văn phòng'', ''Cà phê'', ''Hỗ trợ thực tập và lấy dấu xác nhận thực tập'', ''Cơ hội thăng tiến làm nhân viên fulltime - giáo viên tiếng Nhật'', ''Môi trường làm việc trẻ trung, thoải mái, vui vẻ'', ''Tham gia các lớp học ngoại ngữ miễn phí'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (730, 8, 8, 'Chuyên Viên Viết Tài Liệu Kỹ Thuật Phần Mềm PT', '_**_Mục tiêu công việc:_**_ • Nghiên cứu, phân tích mã nguồn phần mềm hoặc tài liệu kỹ thuật hiện có để hiểu rõ phần mềmBệnh viện• Viết, biên tập và duy trì các tài liệu kỹ thuật như: hướng dẫn sử dụng, tài liệu triển khai, tài liệubảo trì, tài liệu API, tài liệu đào tạo người dùng• Phối hợp với các bộ phận phát triển phần mềm, kiểm thử và nghiệp vụ để thu thập thông tin vàxác minh tính chính xác của tài liệu• Xây dựng và cập nhật các bộ tài liệu chuẩn để đảm bảo tính nhất quán và dễ hiểu• Hỗ trợ soạn thảo tài liệu phục vụ thuyết trình, tài liệu đấu thầu, hồ sơ dự án khi cần• Đảm bảo tài liệu phát hành đúng tiến độ và đạt chất lượng theo yêu cầu.', '__Yêu cầu công việc:__ • Tốt nghiệp Đại học chuyên ngành CNTT, Kỹ thuật phần mềm, hoặc các ngành có liên quan• Có khả năng đọc hiểu code (ít nhất ở mức cơ bản)• Kỹ năng viết rõ ràng, mạch lạc và có khả năng diễn đạt thông tin kỹ thuật bằng ngôn ngữ dễ hiểu• Kỹ năng giao tiếp, phối hợp nhóm tốt• Có kinh nghiệm tối thiểu 1 năm ở vị trí Technical Writer hoặc công việc tương tự là một lợi thế• Ưu tiên ứng viên đã từng tham gia phát triển phần mềm hoặc có kiến thức lập trình cơ bản• Sử dụng thành thạo Word, Excel, PowerPoint; ưu tiên biết thêm công cụ quản lý tài liệu(Confluence, Jira, v.v.)
Kỹ năng chuyên môn: [''Có khả năng đọc hiểu code (ít nhất ở mức cơ bản)'', ''Sử dụng thành thạo Word, Excel, PowerPoint'', ''Biết thêm công cụ quản lý tài liệu (Confluence, Jira, v.v.)'']
Kỹ năng mềm: [''Kỹ năng viết rõ ràng, mạch lạc'', ''Kỹ năng giao tiếp'', ''Phối hợp nhóm tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Mức lương được trả theo giờ làm việc thực tế, đảm bảo minh bạch và cạnh tranh'', ''Làm việc trong môi trường chuyên nghiệp, có cơ hội phát triển và học hỏi'', ''Tham gia trực tiếp vào các dự án phần mềm thực tế, được tiếp cận công nghệ mới'', ''Hỗ trợ linh hoạt thời gian làm việc hoặc hybrid nếu phù hợp dự án'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (731, 9, 8, 'Phiên Dịch Tiếng Hàn Không Cần Chứng Chỉ', 'Phiên dịch chuyên ngành Chế tạo máy móc, tự động hoá tại nhà máy Samsung: Phiên dịch hiện trường (Việt – Hàn): hỗ trợ giao tiếp giữa kỹ sư Hàn và công nhân Việt trong quá trình lắp đặt, vận hành thiết bị tự động hóa. Dịch trong môi trường nhà xưởng, đứng line, dịch kỹ thuật liên quan đến cơ khí – điện – lập trình cơ bản. Thực hiện các công việc theo yêu cầu của quản lý. Tuân thủ quy định An toàn tại dự án.', 'Không yêu cầu bằng cấp. Yêu cầu có kinh nghiệm và phiên dịch được tiếng hàn chuyên môn tại mô tả công việc. Thời gian cần: Phiên dịch 01 tháng theo dự án. Thái độ ý thức làm việc tốt, tuân thủ thời gian.
Kỹ năng chuyên môn: [''Kỹ Năng Nghe Hiểu Tốt'', ''Kỹ Năng Nói Tốt'', ''Kỹ Năng Giao Tiếp Tiếng Hàn Lưu Loát'', ''Kỹ Năng Dịch Thuật Cơ Bản'', ''Hiểu Biết Văn Hóa Hàn Quốc'']
Kỹ năng mềm: [''chịu được áp lực công việc'', ''Trung thực trong phiên dịch'', ''nhiệt tình hỗ trợ phiên dịch'']', 'PART_TIME', 'REMOTE', 'bắc ninh', 'Bắc Ninh', 'MONTHLY', 28000000.00, '23.0 - 28.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được ứng lương'', ''Được hỗ trợ suất ăn chính + phụ'', ''Làm việc trong môi trường chuyên nghiệp'', ''Tiếp cận các dự án Phiên dịch khác tại SDV'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (732, 10, 8, 'Thực Tập Sinh Biên Phiên Dịch Tiếng Nhật', 'Dịch bài viết đăng trang Fanpage (tin tức, văn hóa, phong tục, giả trí…) về Nhật Bản. Tìm kiếm lên ý tưởng, viết và đăng bài post cho trang web, Fanpage. Thực tập đối ứng trả lời tin nhắn khách hàng từ Nhật. Thực tập đọc và hiểu nội dung yêu cầu dự án từ khách, chọn lọc những thông tin cần thiết và tạo chỉ thị cho team lập trình. Thực tập kiểm tra, quản lý tiến độ cũng như chất lượng dự án, liên lạc thông tin và xác nhận với khách nếu cần.', 'Sinh viên ngành Ngôn ngữ Nhật tại các trường Đại học hoặc có trình độ tiếng Nhật tương đương N3. Đam mê và có định hướng làm việc trong lĩnh vực Công nghệ thông tin (IT). Yêu thích văn hóa Nhật Bản. Thành tạo máy tính tin học văn phòng (Excel, word,...). Chịu áp lực công việc cao. Chăm chỉ, có trách nhiệm với công việc. Có năng lực đối ứng nhiều công việc cùng 1 lúc (handle multi-task).
Kỹ năng chuyên môn: [''Thành thạo máy tính tin học văn phòng (Excel, Word)'']
Kỹ năng mềm: [''Chịu áp lực công việc cao'', ''Chăm chỉ'', ''Có trách nhiệm với công việc'', ''Có năng lực đối ứng nhiều công việc cùng 1 lúc (handle multi-task)'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 8000000.00, '6.0 - 8.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Tham gia các event như Sinh nhật, Dinner hàng tháng, teambuilding, company trip'', ''Cơ hội phát triển sự nghiệp trong lĩnh vực công nghệ phần mềm'', ''Môi trường làm việc trẻ, năng động, chú trọng đến hiệu quả công việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (733, 2, 8, 'Thực Tập Sinh Tiếng Nhật - Được Đào Tạo Bài Bản', 'Phiên dịch trực tiếp Việt – Nhật và Nhật – Việt, hỗ trợ dịch thông tin trong cuộc họp dự án nội bộ, họp với Khách hàng. Truyền đạt thông tin đến các Phòng/ Bộ phận một cách rõ ràng. Dịch, chuẩn bị tài liệu/ báo cáo.', 'Không yêu cầu kinh nghiệm làm việc trước đó. Đang là sinh viên năm 3, năm 4 chuyên ngành ngôn ngữ Nhật. Tin học văn phòng thành thạo: Word, Excel, Powerpoint. Chủ động trong công việc và khả năng sắp xếp công việc hiệu quả. Không ngại di chuyển, có thể đi công tác. Có Laptop. Thực tập tối thiểu 3 tháng.
Kỹ năng chuyên môn: [''Tin học văn phòng thành thạo: Word, Excel, Powerpoint'']
Kỹ năng mềm: [''Chủ động trong công việc'', ''Khả năng sắp xếp công việc hiệu quả'', ''Không ngại di chuyển'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00)', '[''Phụ cấp từ 1.000.000đ - 2.500.000đ (tùy theo năng lực và thời gian làm việc tại công ty)'', ''Được tự do đề xuất ý tưởng phát triển sản phẩm hay quy trình làm việc'', ''Làm việc trong môi trường năng động, thân thiện, có cơ hội sáng tạo, thể hiện năng lực'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (734, 3, 8, 'Nhân Viên Phiên Dịch Tiếng Trung', 'Phiên dịch trực tiếp tiếng Trung – tiếng Việt trong quá trình làm việc giữa chuyên gia Trung Quốc và nhân viên công ty Việt Nam liên quan đến dự án phần mềm quản trị doanh nghiệp. Hỗ trợ truyền đạt các yêu cầu, thông tin, nội dung trao đổi giữa hai bên. Ghi chép biên bản cuộc họp nếu cần. Hỗ trợ các công việc liên quan đến ngôn ngữ và truyền đạt trong suốt thời gian triển khai dự án.', 'Tốt nghiệp đại học các chuyên ngành. Thành thạo tiếng Trung (nghe – nói – đọc – viết); ưu tiên ứng viên có chứng chỉ HSK 5 trở lên hoặc trình độ tương đương, có thể dịch các từ ngữ chuyên ngành tài chính, kế toán. Có khả năng phiên dịch trực tiếp, phản xạ tốt trong môi trường làm việc. Ưu tiên ứng viên đã có kinh nghiệm phiên dịch trong lĩnh vực hành chính nhân sự, kế toán,… từ 1 năm trở lên.
Kỹ năng chuyên môn: [''Thành thạo tiếng Trung (nghe – nói – đọc – viết)'', ''Có chứng chỉ HSK 5 trở lên hoặc trình độ tương đương'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Có trách nhiệm'', ''Cẩn thận'', ''Tác phong chuyên nghiệp'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 22000000.00, '18.0 - 22.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Thu nhập hấp dẫn'', ''Làm việc trong môi trường chuyên nghiệp'', ''Hỗ trợ trang thiết bị làm việc'', ''Có cơ hội mở rộng quan hệ và tích lũy kinh nghiệm làm việc chuyên sâu'', ''Thưởng hiệu quả làm việc'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (735, 7, 8, 'CTV Dịch Sách Thiếu Nhi', '• Dịch thuật / hiệu đính sách thiếu nhi tiếng Anh, Trung, Pháp, Hàn, Nhật sang tiếng Việt. • Phối hợp với biên tập viên để nâng cao chất lượng bản dịch, đảm bảo các quy định liên quan đến xuất bản của Luật xuất bản hoặc Nhà xuất bản. • Bảo mật bản dịch. • Hỗ trợ Công ty quảng bá xuất bản phẩm. • Báo cáo công việc.', '• Tốt nghiệp Đại học trở lên các chuyên ngành Tiếng Anh, Trung, Pháp, Hàn, Nhật hoặc Ngôn ngữ, Văn học, các ngành Khoa học,... (có chứng chỉ ngoại ngữ tương đương). • Riêng với dòng sách khoa học, ưu tiên: Ứng viên có trình độ thạc sĩ, tiến sĩ, giáo sư, phó giáo sư có chuyên môn về các ngành khoa học và có đủ trình độ ngoại ngữ để dịch / hiệu đính. • Đã có kinh nghiệm dịch sách từ 2 năm trở lên. • Yêu thích và hiểu biết về văn học / sách thiếu nhi.
Kỹ năng chuyên môn: [''Dịch thuật'', ''Hiệu đính'']
Kỹ năng mềm: [''Yêu thích văn học'', ''Hiểu biết về sách thiếu nhi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thời gian làm việc linh hoạt', '[''Nhuận bút dịch'', ''Cơ hội được gắn tên trên bìa sách'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (736, 8, 8, 'Giáo viên tiếng Anh', 'Có thể dạy cả trực tuyến và ngoại tuyến. Chịu trách nhiệm dạy các kỹ năng giao tiếp tiếng Anh. Mục tiêu Người học: Chuyên gia làm việc. Kích thước lớp học: 1-6 học sinh mỗi lớp. Giáo viên sẽ đăng ký các lớp học hàng tuần và dự kiến ​​sẽ theo dõi toàn bộ khóa học, thường kéo dài 40-80 giờ.', 'Born between 1982 and 2002. Proficient in all four English skills (listening, speaking, reading, and writing) with clear pronunciation and effective communication. Preferably holds English certifications: IELTS 7.0+, TOEIC 800+, or a degree in English Teaching, English Language, or equivalent teaching certifications such as TESOL, CELTA, etc. Professional demeanor, punctuality, and a high sense of responsibility. Experience in teaching English to working professionals is an advantage. Presentable appearance is a plus. For online teaching: Must have a personal computer, webcam, microphone, stable internet connection, and a suitable teaching space.
Kỹ năng chuyên môn: [''Proficient in all four English skills (listening, speaking, reading, and writing)'']
Kỹ năng mềm: [''Professional demeanor'', ''Punctuality'', ''High sense of responsibility'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 12000000.00, '10.0 - 12.0 triệu', 'Flexible teaching schedule (morning, afternoon, or evening shifts)', '[''Attractive income based on competency and work hours'', ''Training provided'', ''Flexible and independent working environment'', ''Access to modern software systems'', ''Opportunity to expand professional networks'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (737, 9, 8, 'Phần giáo viên tiếng Anh - thời gian', 'Có thể dạy cả trực tuyến và ngoại tuyến. Chịu trách nhiệm dạy các kỹ năng giao tiếp tiếng Anh. Mục tiêu Người học: Chuyên gia làm việc. Kích thước lớp học: 1-6 học sinh mỗi lớp. Giáo viên sẽ đăng ký các lớp học hàng tuần và dự kiến ​​sẽ theo dõi toàn bộ khóa học, thường kéo dài 40-80 giờ.', 'Born between 1982 and 2002. Proficient in all four English skills (listening, speaking, reading, and writing) with clear pronunciation and effective communication. Preferably holds English certifications: IELTS 7.0+, TOEIC 800+, or a degree in English Teaching, English Language, or equivalent teaching certifications such as TESOL, CELTA, etc. Professional demeanor, punctuality, and a high sense of responsibility. Experience in teaching English to working professionals is an advantage. Presentable appearance is a plus. For online teaching: Must have a personal computer, webcam, microphone, stable internet connection, and a suitable teaching space.
Kỹ năng chuyên môn: [''Proficient in all four English skills (listening, speaking, reading, and writing)'']
Kỹ năng mềm: [''Professional demeanor'', ''Punctuality'', ''High sense of responsibility'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 12000000.00, '10.0 - 12.0 triệu', 'Flexible teaching schedule (morning, afternoon, or evening shifts)', '[''Attractive income based on competency and work hours'', ''Training provided'', ''Flexible and independent working environment'', ''Access to modern software systems'', ''Opportunity to expand professional networks'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (738, 10, 8, 'Thực Tập Sinh Biên Phiên Dịch', 'Xử lý, in ấn hồ sơ. Biên dịch các tài liệu từ tiếng Việt - Anh hoặc Anh - Việt. Biên dịch các tài liệu theo ngôn ngữ được yêu cầu. Thực hiện các công việc khác theo sự hướng dẫn của trưởng Bộ phận.', 'Sinh viên năm cuối hoặc mới tốt nghiệp chuyên ngành dịch thuật tiếng Anh. Có khả năng tìm kiếm và xử lý thông tin, tư duy logic tốt. Có khả năng làm việc độc lập và làm việc nhóm tốt. Thành thạo ngôn ngữ thứ 3 ngoài tiếng Anh là một lợi thế. Có trách nhiệm với công việc. Sẵn sàng học hỏi và cải thiện kỹ năng của mình trong ngành dịch thuật. Tự chủ về phương tiện đi lại.
Kỹ năng chuyên môn: [''Kỹ Năng Phiên Dịch'', ''Kỹ Năng Biên Dịch'', ''Ngữ Pháp Tốt'']
Kỹ năng mềm: [''Tư duy logic tốt'', ''Làm việc độc lập'', ''Làm việc nhóm'', ''Có trách nhiệm với công việc'', ''Sẵn sàng học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Môi trường làm việc chuyên nghiệp, thân thiện, năng động'', ''Hỗ trợ và đào tạo từ các chuyên gia trong ngành dịch thuật'', ''Cơ hội trở thành nhân viên chính thức sau khi hoàn thành khóa thực tập'', ''Phát triển các kỹ năng mềm cần thiết về giao tiếp, quản lý đội nhóm, quản lý thời gian'', ''Phụ cấp ăn trưa'', ''Được cấp máy tính'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (739, 2, 8, 'Giáo Viên Tiếng Anh Part Time', '- Có thể dạy online hoặc offline. - Giảng dạy tiếng Anh giao tiếp. - Đối tượng học viên: Người đi làm. - Số lượng học viên: 1- 6 học viên/ 1 lớp. - Giáo viên đăng ký nhận lớp theo tuần, chịu trách nhiệm theo sát cho 1 khoá học khoảng 40 -80 giờ của học viên.', '- Sinh năm 1982-2002. - Tiếng Anh thành thạo 4 kỹ năng (nghe, nói, đọc, viết), phát âm chuẩn, diễn đạt ý rõ ràng. - Ưu tiên có chứng chỉ Tiếng Anh: IELTS từ 7.0, TOEIC từ 800. Tốt nghiệp Sư phạm Anh, Ngôn ngữ Anh hoặc chứng chỉ nghiệp vụ sư phạm tương đương: TESOL, CELTA,… - Tác phong chuyên nghiệp, đúng giờ và trách nhiệm cao với công việc. - Có kinh nghiệm giảng dạy tiếng Anh cho người đi làm là một lợi thế. - Ngoại hình ưa nhìn là một lợi thế. - Với dạy online: Có máy tính cá nhân, có webcam, có mic, có đường truyền Internet ổn định. Có không gian, địa điểm phù hợp để giảng dạy.
Kỹ năng chuyên môn: [''Tiếng Anh thành thạo 4 kỹ năng (nghe, nói, đọc, viết)'', ''Phát âm chuẩn'']
Kỹ năng mềm: [''Tác phong chuyên nghiệp'', ''Đúng giờ'', ''Trách nhiệm cao với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 16000000.00, '12.0 - 16.0 triệu', 'Thời gian giảng dạy linh động (ca sáng, ca chiều, ca tối)', '[''Được đào tạo phương pháp giảng dạy'', ''Môi trường làm việc tự do, tại nhà'', ''Tiếp cận với hệ thống phần mềm hiện đại'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (740, 3, 8, 'Online Gọi Tổng Đài CSKH Tiếng Anh Gỡ Tài Khoản', 'Sử dụng số hotline do công ty cung cấp để gọi lên tổng đài chăm sóc khách hàng, yêu cầu mở khóa tài khoản bị khóa. Quy trình gọi điện sẽ được hướng dẫn chi tiết trong quá trình đào tạo. Làm việc hoàn toàn online tại nhà, phối hợp với các thành viên trong team để xử lý case.', 'Nghe – nói tiếng Anh tốt, phát âm rõ ràng, tự tin giao tiếp (ghi rõ kỹ năng tiếng anh trong CV). Kiên trì, cẩn thận, chăm chỉ, có tinh thần trách nhiệm và kỹ năng làm việc nhóm. Sở hữu máy tính cá nhân chạy hệ điều hành Windows. Có thể làm việc độc lập, chủ động sắp xếp thời gian. Có thể làm việc vào khung giờ muộn/tối. Là sinh viên các trường đại học tại Hà Nội (ưu tiên các bạn có thời gian linh hoạt).
Kỹ năng chuyên môn: [''Sử dụng máy tính cá nhân chạy hệ điều hành Windows'']
Kỹ năng mềm: [''Nghe – nói tiếng Anh tốt'', ''Phát âm rõ ràng'', ''Tự tin giao tiếp'', ''Kiên trì'', ''Cẩn thận'', ''Chăm chỉ'', ''Có tinh thần trách nhiệm'', ''Kỹ năng làm việc nhóm'', ''Có thể làm việc độc lập'', ''Chủ động sắp xếp thời gian'']', 'FREELANCE', 'REMOTE', 'hà đông', 'Hà Nội', 'FIXED_PROJECT', 4000000.00, '1.0 - 4.0 triệu', 'Thời gian linh động, ưu tiên làm việc khung giờ tối và khuya', '[''Lương thanh toán 2 tuần/lần qua tài khoản ngân hàng'', ''Được đào tạo bài bản'', ''Làm việc linh động, không yêu cầu đến văn phòng'', ''Môi trường trẻ trung, năng động'', ''Hỗ trợ nhiệt tình từ các thành viên dày dạn kinh nghiệm'', ''Tham gia các buổi party, du lịch của công ty tổ chức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (741, 7, 8, 'Biên Phiên Dịch Tiếng Anh (Teaching Assistant)', '- Trao đổi công việc, hỗ trợ giáo viên nước ngoài theo lớp lớn các mảng: Giao tiếp, Junior, Ielts... - Kết nối, chăm sóc trên lớp học của giảng viên theo lịch cố định - Hỗ trợ học viên học qua group, inbox... - Thực hiện báo cáo liên quan đến lớp học - Các công việc khác theo sự phân công của phòng đào tạo. - Làm việc online hoặc offline khi có yêu cầu', '- Sinh viên các trường Đại học/ Cao đẳng, ưu tiên ứng viên năm 1 hoặc năm 2,3 trở lên chuyên ngành Sư phạm Anh/ Ngôn ngữ Anh. - Ưu tiên ứng viên có kinh nghiệm trợ giảng, gia sư tiếng Anh - Ưu tiên ứng viên có chứng chỉ IELTS/TOEIC - Có khả năng giao tiếp và làm việc với giáo viên nước ngoài - Nhiệt huyết, tận tâm, yêu thích công việc giảng dạy - Vui vẻ, thân thiện, cởi mở và ham học hỏi.
Kỹ năng chuyên môn: [''Chứng chỉ IELTS/TOEIC'']
Kỹ năng mềm: [''Khả năng giao tiếp'', ''Nhiệt huyết'', ''Tận tâm'', ''Yêu thích công việc giảng dạy'', ''Vui vẻ'', ''Thân thiện'', ''Cởi mở'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.0 - 1.5 triệu', 'Thứ 2 - Thứ 6 (từ 17:45 đến 21:45)', '[''Có cơ hội trở thành GV giảng dạy chính thức tại trung tâm'', ''Thời gian làm việc linh hoạt'', ''Được làm việc trực tiếp với giáo viên nước ngoài và học viên'', ''Được tham gia các hoạt động ngoại khóa của công ty'', ''Được đào tạo hoàn toàn miễn phí phong cách trợ giảng và chuyên môn Tiếng Anh'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (742, 8, 3, 'Admin Gia Sư & Admin Coi Chấm Thi IELTS Part Time Tối - Từ 6.5 IELTS - Không YCKN', '1. Admin gia sư tại HN * Tutor IELTS online cho học viên đăng ký học lớp gia sư - Giảng dạy các lớp chờ khai giảng (online hoặc offline) tại văn phòng làm việc- Coi thi speaking các kỳ thi giữa khoá, cuối khoá của trung tâm- Động viên khuyến khích, có phương pháp tạo động lực học IELTS cho học viên- Thực hiện công việc khác theo sự phân công của Trưởng bộ phận.- Coi thi speaking các kỳ thi giữa khoá, cuối khoá của trung tâm 2. Admin coi - chấm thi tại HCM * Coi thi IELTS 4 kỹ năng cho học viên (thi trên giấy và thi speaking) - Chấm thi giữa kỳ, cuối kỳ, tổng hợp kết quả và báo cáo với các bộ phận liên quan * Gia sư Online theo nhu cầu của học viên;- Giảng dạy các lớp chờ khai giảng tại văn phòng làm việc;- Tổ chức kiểm tra đánh giá năng lực tiếng Anh đầu vào cho học viên;- Chấm bài và phân loại trình độ đầu vào cho học viên;- Tổ chức kiểm tra đánh giá các kỳ thi giữa khóa và cuối khóa cho học viên tại cơ sở làm việc;', '- IELTS ≥ 6.5 (Không có kỹ năng nào dưới 6.0) - Phát âm Tiếng Anh trôi chảy, chuẩn IPA - Có kiến thức về format bài thi IELTS - Tinh thần tự học hỏi, chủ động trong công việc
Kỹ năng chuyên môn: [''Kiến thức về format bài thi IELTS'']
Kỹ năng mềm: [''Tinh thần tự học hỏi'', ''Chủ động trong công việc'', ''Kỹ năng giao tiếp'', ''Kỹ năng giảng dạy'', ''Kiên Nhẫn'', ''Khả Năng Quản Lý Thời Gian'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 5000000.00, '4.5 - 5.5 triệu', 'Thứ 2 - Thứ 7 (từ 18:00 đến 22:00)', '[''Được đào tạo kỹ năng chuyên môn ngoại ngữ'', ''Được đào tạo bài bản về các kỹ năng IELTS'', ''Thưởng lễ tết, du lịch, tham gia teambuilding, party'', ''Review lương 3-6 tháng/lần'', ''Hỗ trợ dấu thực tập sau 3 tháng làm việc'', ''Trà, coffee luôn sẵn sàng tại văn phòng'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (743, 9, 3, 'Giáo Viên Giảng Dạy TOEIC 4 Kỹ Năng', '– Trực tiếp giảng dạy các lớp TOEIC 2 hoặc 4 Kỹ Năng Nghe Đọc Nói Viết. - Chữa bài tập kèm nhận xét, đánh giá học viên từng buổi. – Hỗ trợ đưa ra giải pháp giúp học viên cải thiện chất lượng học tập trong khóa học.', '– Có chứng chỉ Sư Phạm (như CELTA, TESOL) hoặc tiếng Anh (Toeic trên 900 LR, 350 SW hoặc Ielts trên 7.0) là một lợi thế. - Ưu tiên tốt nghiệp các khoa ngoại ngữ chuyên ngành tiếng Anh, theo học các chương trình giảng dạy bằng tiếng Anh. - Năng động và có trách nhiệm trong công việc. - Có tâm huyết với nghề, làm việc có trách nhiệm. - Phong cách giảng dạy tự tin, lôi cuốn. - Kỹ năng giao tiếp, ứng xử tốt.
Kỹ năng mềm: [''Năng động và có trách nhiệm trong công việc.'', ''Có tâm huyết với nghề, làm việc có trách nhiệm.'', ''Phong cách giảng dạy tự tin, lôi cuốn.'', ''Kỹ năng giao tiếp, ứng xử tốt.'']', 'PART_TIME', 'ONSITE', 'quận 7', 'Hồ Chí Minh', 'MONTHLY', 12000000.00, '5.0 - 12.0 triệu', 'Thứ 2 - Thứ 7 (từ 18:00 đến 21:15)', '[''Thu nhập hấp dẫn, dao động 250k đến 300k/buổi.'', ''Thưởng năng lực: thưởng học viên đi thi đạt thành tích tốt.'', ''Tham gia BHXH, BHYT, BHTN khi trở thành giáo viên fulltime tại hệ thống.'', ''Nhận lớp dạy ngay sau khi pass PV và kết thúc training.'', ''Sẵn bộ giáo trình, học liệu được chuẩn hóa của hệ thống.'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (744, 10, 3, 'Giáo Viên IELTS', 'Giảng dạy, luyện thi IELTS cho lớp sĩ số từ 16 - 20 học viên theo giáo trình và lộ trình có sẵn. Chấm & chữa Bài tập 2 kỹ năng Speaking & Writing. Độ tuổi học viên: 16 - 25 tuổi. Giáo viên giảng dạy các lớp trình độ từ Basic - IELTS 6.5.', 'IELTS từ 7.0+. Từ 3 tháng - 6 tháng kinh nghiệm đứng lớp. Kỹ năng truyền đạt bài giảng dễ hiểu. Yêu thích công việc giảng dạy. Có kinh nghiệm dạy IELTS, chưa biết sẽ được đào tạo.
Kỹ năng chuyên môn: [''Kỹ năng sư phạm'', ''Ngữ Pháp'', ''Tiếng Anh phát âm chuẩn'', ''Chứng chỉ IELTS 7.0+'']
Kỹ năng mềm: [''Kỹ năng truyền đạt bài giảng dễ hiểu'', ''Yêu thích công việc giảng dạy'', ''Sáng tạo'', ''Kiên Nhẫn'', ''Linh Hoạt trong Phương Pháp Giảng Dạy'']', 'PART_TIME', 'ONSITE', 'ninh bình, thái nguyên', 'Ninh Bình', 'MONTHLY', 30000000.00, '15.0 - 30.0 triệu', 'Thứ 2 - Thứ 7 (từ 18:00 đến 21:30)', '[''Đóng BHXH với GV cố định'', ''Các khoản thưởng nóng, thưởng tháng, thưởng quý theo chính sách công ty'', ''Review tăng thu nhập 3 tháng/lần'', ''Sinh nhật, ngày lễ theo chính sách công ty'', ''Được cung cấp công cụ quản lý lớp học'', ''Được tham gia các khóa đào tạo nội bộ'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (745, 2, 3, 'Nhân Viên Tư Vấn Khóa Học Tiếng Anh', 'Liên hệ tư vấn cho khách hàng tiềm năng theo Data công ty cung cấp hoặc tự tìm kiếm. Tư vấn các khóa học IELTS, Giao tiếp, Tutor tại hệ thống Công ty; Hỗ trợ tư vấn tuyển sinh tại các đơn vị đối tác. Hỗ trợ học viên hoàn thành các mục tiêu học tập. Đảm bảo cung cấp chất lượng dịch vụ theo dõi tốt nhất cho học viên.', 'Đang là sinh viên tại các trường ĐH/CĐ, trống nhiều lịch trong tuần. Giao tiếp khéo léo, yêu thích công việc liên quan đến kinh doanh/ tư vấn. Thường xuyên sử dụng mạng xã hội và tin học văn phòng. Không đang làm việc cho doanh nghiệp khác. Có laptop cá nhân và phương tiện di chuyển cá nhân.
Kỹ năng chuyên môn: [''Tin học văn phòng'', ''Sử dụng mạng xã hội'']
Kỹ năng mềm: [''Giao tiếp khéo léo'', ''Yêu thích công việc liên quan đến kinh doanh/tư vấn'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 10000000.00, '2.5 - 10.0 triệu', '30h/tuần, linh hoạt theo lịch rảnh cá nhân', '[''Team building'', ''Du lịch hàng năm'', ''Khám sức khỏe định kỳ'', ''Thưởng hiệu quả làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (746, 3, 3, 'Giáo Viên Tiếng Anh Part-Time', '- Thực hiện giảng dạy chương trình tiếng Anh thông qua môn Toán và Khoa học sử dụng bài giảng số iSMART bậc Tiểu học/ THCS theo sự điều phối của quản lý chuyên môn. - Đảm bảo chất lượng đào tạo, giảng dạy theo tiêu chuẩn được hướng dẫn và đưa ra từ đội ngũ Đào Tạo và Nghiên Cứu Phát Triển. - Thực hiện các công việc khác liên quan đến chuyên môn như hoàn thiện giáo án, thiết kế đề kiểm tra, chấm bài kiểm tra, làm báo cáo đánh giá xếp loại học sinh và các công tác chuyên môn khác của một giáo viên. - Tham gia các buổi đào tạo, tập huấn, họp chuyên môn dành cho giáo viên.', '- Ứng viên tốt nghiệp đại học trở lên với chuyên ngành sư phạm tiếng Anh hoặc các chuyên ngành sư phạm khác (giảng dạy bằng tiếng Anh). - Đối với các ứng viên không tốt nghiệp từ các trường đại học sư phạm: Cần có bằng đại học trở lên chuyên ngành tiếng Anh cùng với chứng chỉ nghiệp vụ sư phạm. - Khả năng tiếng Anh tốt, phát âm chuẩn, trình độ tương đương B2 trở lên. - Lợi thế: Có chuyên môn trong lĩnh vực Toán - Khoa học hoặc có kinh nghiệm giảng dạy tại các trường công lập hoặc dân lập. - Làm việc với tinh thần trách nhiệm, hợp tác và kỷ luật. - Thành thạo tin học văn phòng.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Tinh thần trách nhiệm'', ''Hợp tác'', ''Kỷ luật'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '5.0 - 15.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Mức lương theo số giờ giảng dạy (Từ 170.000 VNĐ - 250.000 VNĐ/giờ)'', ''Được đào tạo về kỹ năng sử dụng công nghệ tương tác vào giảng dạy'', ''Môi trường làm việc thân thiện, chuyên nghiệp, hiện đại'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (747, 7, 3, 'Giảng Viên Lập Trình Part-Time', 'Dạy học theo chương trình giảng dạy của TagEdu. Điều chỉnh hoạt động học tập để phù hợp với các cấp độ khả năng khác nhau. Đồng thời theo dõi kết quả học tập của các học viên. Làm việc với các bộ phận để hiểu tiến trình học tập của học sinh, phân tích các nhu cầu học tập và giải quyết vấn đề phát sinh (nếu có). Hỗ trợ các phòng ban trong việc tương tác với phụ huynh. Hợp tác với các bộ phận để hỗ trợ phát triển chương trình giảng dạy và tài liệu học tập. Theo dõi tiến trình học tập của học sinh và làm báo cáo sau các buổi học để thông tin tới Phụ huynh. Hỗ trợ các sự kiện giáo dục được lên lịch trong suốt năm học để phát triển chuyên môn. Tham gia các buổi training dành cho giáo viên.', 'Có khả năng giao tiếp và dẫn dắt bài giảng bằng Tiếng Anh (Ưu tiên IELTS trên 6.0). Thành thạo giảng dạy nền tảng lập trình Scratch và ngôn ngữ lập trình Python. Hỗ trợ phần giáo án và bài giảng khi cần. Yêu thương và có khả năng tương tác với trẻ em.
Kỹ năng chuyên môn: [''Lập trình Scratch'', ''Ngôn ngữ lập trình Python'']
Kỹ năng mềm: [''Giao tiếp'', ''Tương tác với trẻ em'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm việc theo ca', '[''Được đào tạo và phát triển chuyên môn'', ''Làm việc trong môi trường thoải mái, khuyến khích sáng tạo'', ''Phát triển được thêm nhiều kĩ năng mới'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (748, 8, 3, 'Trợ Giảng Tiếng Anh', 'Hỗ trợ học tập cho học viên: Dạy bù, phụ đạo cho các học viên vắng/ chưa hiểu bài (Sẽ được phân vào lớp có cấp độ phù hợp năng lực). Hỗ trợ giáo viên: chuẩn bị các tài liệu, dụng cụ học tập trong lớp học. Hỗ trợ Phòng Đào tạo: cập nhật thông tin học viên, liên hệ phụ huynh báo cáo về tình hình học tập của học viên. Các công việc khác theo sự phân công của Phòng Đào Tạo.', 'Sinh viên chuyên ngành Ngôn ngữ Anh, Tiếng Anh, Ngữ văn Anh, Sư phạm Tiếng Anh hoặc các chuyên ngành khác có kỹ năng Tiếng Anh tốt. Ưu tiên sinh viên có định hướng giảng dạy tại Trung tâm sau khi tốt nghiệp. Yêu thích giảng dạy, yêu thích trẻ em. Có tinh thần hợp tác và cầu tiến. Cẩn thận và ý thức chịu trách nhiệm cao.
Kỹ năng chuyên môn: [''Kỹ năng Tiếng Anh'']
Kỹ năng mềm: [''Yêu thích giảng dạy'', ''Yêu thích trẻ em'', ''Có tinh thần hợp tác'', ''Cầu tiến'', ''Cẩn thận'', ''Ý thức chịu trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca tối từ thứ 2 - thứ 7: 17h-20h30; Ca sáng T7 – CN: 08h00 - 11h00; Ca chiều T7 – CN: 14h00-17h30', '[''Tham gia đào tạo nâng cao nghiệp vụ'', ''Có thể ứng tuyển vào các vị trí Fulltime như Nhân viên đào tạo, Giáo viên sau khi tốt nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (749, 9, 3, 'Thực tập phát triển kinh doanh', 'Tìm kiếm và xây dựng mối quan hệ với khách hàng B2B tiềm năng (trường học, trung tâm tiếng Anh, giáo viên,...). Hỗ trợ lên kế hoạch và triển khai các chiến dịch bán hàng, giới thiệu sản phẩm tới khách hàng. Chuẩn bị tài liệu, báo giá, demo và tham gia pitching cùng đội ngũ chính thức. Cập nhật dữ liệu, phản hồi của khách hàng và đóng góp vào quá trình cải thiện sản phẩm. Phối hợp với team Marketing để phát triển kênh bán hàng online.', 'Ưu tiên sinh viên năm 3, 4 hoặc mới tốt nghiệp các ngành Kinh tế, Quản trị, Marketing, hoặc các chuyên ngành tương tự. (GPA: từ 7.0/10.0 trở lên). Có khả năng giao tiếp tốt, tư duy logic, làm việc có trách nhiệm. Có định hướng làm việc lâu dài trong lĩnh vực kinh doanh. Tiếng Anh ở mức tương đương 6.5 IELTS trở lên (ưu tiên có chứng chỉ tiếng Anh). Ưu tiên các bạn có kinh nghiệm với mảng giáo dục, giảng dạy. Có thể đảm bảo được ít nhất 70% thời gian đi làm trong tuần (hỗ trợ xoay ca linh hoạt với các bạn chưa chính thức tốt nghiệp).
Kỹ năng mềm: [''Giao tiếp tốt'', ''Tư duy logic'', ''Làm việc có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Lộ trình đào tạo rõ ràng trong 3 tháng'', ''Mentor 1-1 từ team Business'', ''Cơ hội lên nhân sự chính thức nếu thể hiện tốt'', ''Mức phụ cấp: 3-5.000.000 VNĐ/tháng + bonus theo hiệu quả công việc'', ''Môi trường startup trẻ trung, sáng tạo, linh hoạt'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (750, 10, 3, 'Giáo Viên Toán Bằng Tiếng Anh Cấp 1 2 3', 'Việc giảng dạy Toán bằng tiếng Anh không chỉ giúp học sinh tiếp cận với nền giáo dục quốc tế mà còn mở ra nhiều cơ hội nghề nghiệp cho giáo viên có khả năng giảng dạy bằng ngoại ngữ. Hiện nay, nhu cầu học Toán bằng tiếng Anh ngày càng tăng, đặc biệt là đối với học sinh theo học tại các trường quốc tế ở Việt Nam (BIS, UNIS, BVIS, AIS...), du học sinh đang học tại Anh, Úc và Mỹ, và học sinh cần học theo chương trình quốc tế như IGCSE, A-Level, IB, HSC. Giảng dạy, có nền tảng toán học vững chắc và có khả năng sử dụng tiếng Anh để giúp học sinh tiếp thu kiến thức một cách hiệu quả. Dạy Toán bằng tiếng Anh (Cấp 1, Cấp 2, Cấp 3). Hình thức làm việc: Có thể dạy trực tiếp hoặc dạy online tùy theo lớp học.', 'Nền tảng Toán học tốt: Giáo viên hoặc sinh viên chuyên ngành Toán, Sư phạm Toán hoặc các ngành liên quan. Có khả năng giảng dạy Toán một cách dễ hiểu, giúp học sinh nắm chắc kiến thức. Khả năng sử dụng tiếng Anh trong giảng dạy: Có thể giao tiếp tự nhiên, phát âm rõ ràng và truyền đạt kiến thức bằng tiếng Anh một cách dễ hiểu. Trình độ tiếng Anh tương đương IELTS 6.5 trở lên hoặc có khả năng giảng dạy Toán bằng tiếng Anh một cách trôi chảy. Tư duy sư phạm và tinh thần học hỏi: Không yêu cầu kinh nghiệm dạy Toán bằng tiếng Anh trước đó. Sẽ được training bài bản về phương pháp giảng dạy trước khi nhận lớp. Tinh thần trách nhiệm và yêu thích giảng dạy: Quan tâm đến sự tiến bộ của học sinh. Có khả năng tương tác và truyền cảm hứng học tập cho học sinh.
Kỹ năng chuyên môn: [''Khả năng giảng dạy Toán bằng tiếng Anh'']
Kỹ năng mềm: [''Tư duy sư phạm'', ''Tinh thần học hỏi'', ''Tinh thần trách nhiệm'', ''Khả năng tương tác và truyền cảm hứng học tập'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được đào tạo bài bản trước khi nhận lớp'', ''Môi trường làm việc chuyên nghiệp'', ''Cơ hội phát triển lâu dài'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (751, 2, 3, 'Sale Online-Tư Vấn Online - Parttime - Đi Làm Ngay', 'Kết nối khách hàng với trung tâm thông qua việc chat, nhắn tin online. Đăng bài, bình luận, tương tác trong các cộng đồng Facebook, Zalo, TikTok. Thực hiện công việc lên kế hoạch seeding facebook. Đăng tải bài viết liên quan lên hội nhóm, trang,... Chia sẻ, bình luận nội dung của công ty trên các hội nhóm nhằm quảng bá, PR sản phẩm, dịch vụ của công ty. Trả lời comment, inbox sơ bộ hướng khách đến trung tâm. Tương tác thường xuyên vào nội dung của công ty. Chuyển khách cho tư vấn viên chuyên sâu. Phối hợp với trưởng nhóm để cải thiện nội dung, kịch bản tương tác.', 'Các bạn sinh viên năm 1 năm 2. ĐAM MÊ NHIỆT TÌNH NHẮN TIN, CHAT, TRÒ CHUYỆN. Thành thạo Facebook, Zalo, có khiếu tương tác, biết tạo tin nhắn hấp dẫn người đọc. Có laptop. Nhiệt tình, chăm chỉ, cam kết làm việc tối thiểu 2 tháng.
Kỹ năng chuyên môn: [''Thành thạo Facebook'', ''Zalo'']
Kỹ năng mềm: [''Nhiệt tình'', ''Chăm chỉ'', ''Có khiếu tương tác'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 10000000.00, '6.0 - 10.0 triệu', '6 ngày/tuần - Nghỉ 1 ngày không cố định trong tuần', '[''Bảo hiểm sức khỏe'', ''Thưởng hiệu quả làm việc'', ''Tài trợ 100% các lớp học'', ''Cơ hội phát triển nghề nghiệp rõ ràng'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (752, 3, 3, 'Giáo Viên Kids Online (Parttime)', 'Giảng dạy Tiếng Anh online cho học sinh từ 6 tuổi trở lên theo chương trình của trung tâm. Sử dụng nền tảng học trực tuyến Classin để tổ chức lớp học hiệu quả, sinh động. Soạn giáo án, chuẩn bị bài giảng theo giáo trình có sẵn (hoặc tùy chỉnh theo năng lực học sinh). Quản lý lớp học, tạo sự tương tác và kết nối với học sinh. Đánh giá và nhận xét tiến độ học tập của học sinh định kỳ. Tham gia các buổi đào tạo chuyên môn, họp giáo viên theo lịch của trung tâm.', 'Có tình yêu với trẻ nhỏ, kiên nhẫn. Trình độ tiếng Anh đáp ứng 1 trong 4 điều kiện sau: Có chứng chỉ ielts >= 5.5 (speaking 5.0 trở lên), Có chứng chỉ Toeic LR >= 700, Có chứng chỉ Toeic WS >= 250, Chuyên ngành tiếng anh của các trường đại học. Có kinh nghiệm dạy hoặc trợ giảng tiếng Anh từ 3 tháng trở lên. Phát âm chuẩn bảng IPA quốc tế. Số lớp: Nhận dạy tối thiểu 2 lớp. Số ca: Tối thiếu mỗi tuần 5 ca 1 tiếng.
Kỹ năng mềm: [''Có tình yêu với trẻ nhỏ'', ''Kiên nhẫn'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Tối thiểu mỗi tuần 5 ca 1 tiếng', '[''Cơ chế xét lương: 3 tháng đánh giá, xét tăng lương 1 lần'', ''Cơ chế thưởng và phúc lợi rõ ràng'', ''Thời gian dạy: Sắp xếp theo thời gian rảnh của giáo viên và học sinh'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (753, 7, 3, 'Giáo Viên Tiếng Anh Part-Time', 'Có thể dạy online hoặc offline. Giảng dạy tiếng Anh giao tiếp. Đối tượng học viên: Người đi làm. Số lượng học viên: 1- 6 học viên/ 1 lớp. Giáo viên đăng ký nhận lớp theo tuần, chịu trách nhiệm theo sát cho 1 khoá học khoảng 40 -80 giờ của học viên.', 'Sinh năm 1982-2002. Tiếng Anh thành thạo 4 kỹ năng (nghe, nói, đọc, viết), phát âm chuẩn, diễn đạt ý rõ ràng. Ưu tiên có chứng chỉ Tiếng Anh: IELTS từ 7.0, TOEIC từ 800. Tác phong chuyên nghiệp, đúng giờ và trách nhiệm cao với công việc. Có kinh nghiệm giảng dạy tiếng Anh cho người đi làm là một lợi thế. Ngoại hình ưa nhìn là một lợi thế. Với dạy online: Có máy tính cá nhân, có webcam, có mic, có đường truyền Internet ổn định. Có không gian, địa điểm phù hợp để giảng dạy.
Kỹ năng chuyên môn: [''Tiếng Anh thành thạo 4 kỹ năng (nghe, nói, đọc, viết)'', ''Phát âm chuẩn'']
Kỹ năng mềm: [''Tác phong chuyên nghiệp'', ''Đúng giờ'', ''Trách nhiệm cao với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Đa dạng, tùy khung giờ của giáo viên', '[''Được đào tạo phương pháp giảng dạy'', ''Môi trường làm việc tự do, tại nhà'', ''Được tiếp cận với hệ thống phần mềm hiện đại'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (754, 8, 3, 'Thực Tập Sinh Trợ Lý Vận Hành Trung Tâm Anh Ngữ', 'Quản lý hoạt động vận hành của trung tâm, sắp xếp lịch làm việc của nhân sự, sắp xếp lịch học của học sinh, lên kế hoạch trang trí trung tâm vào các sự kiện, quản lý đồ dùng giáo cụ của trường.', 'Yêu trẻ, biết cách làm việc với trẻ em, nhiệt tình, sáng tạo, có tinh thần trách nhiệm và tinh thần tập thể tốt, thân thiện với học viên, có khả năng quán xuyến nhiều công việc, phát âm tiếng Anh chuẩn là một lợi thế.
Kỹ năng chuyên môn: [''Microsoft Office'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Quản lý thời gian'', ''Giao tiếp'', ''Chịu khó sắp xếp công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '2.5 - 5.0 triệu', 'Tối thiểu 19h/tuần từ thứ Hai đến Chủ Nhật', '[''Review lương thưởng 1 năm/2 lần'', ''Môi trường chuyên nghiệp, trẻ trung'', ''Được định hướng rõ ràng'', ''Có cơ hội lên quản lý sau khi review năng lực'', ''Được đóng BH theo quy định của NN'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (755, 9, 3, 'Nhân Viên Giáo Vụ', 'Trợ giảng các lớp học tại Trung tâm. Cập nhật lịch học, sắp xếp phòng học hàng ngày, phát giáo trình cho học viên. Theo dõi việc cập nhật bài giảng dạy của giáo viên hàng ngày. Tiếp nhận phản hồi và hỗ trợ giáo viên cũng như học viên trong quá trình làm việc. Hỗ trợ kiểm soát mức độ chuyên cần của học viên, liên hệ học viên khi nghỉ học, liên hệ, sắp xếp lịch học và lịch thi bù cho học viên. Tổ chức các kỳ thi, gác thi và kiểm tra chất lượng giữa kỳ, cuối kỳ. Tổng hợp kết quả thi, chấm bài thi (Reading & Listening), cập nhật lưu trữ điểm và thông báo kết quả thi của các lớp. Thực hiện lấy phản hồi của học viên định kỳ, giải đáp các thắc mắc của học viên và phụ huynh liên quan đến các khóa học của trung tâm. Hỗ trợ các công việc theo sự phân công của quản lý và kịp thời xử lý các sự cố phát sinh.', 'Từ 17:30 - 21:30 hàng ngày. Làm việc từ thứ Hai đến thứ Bảy (Off Chủ Nhật hàng tuần). Tiếng Anh tốt, phát âm chuẩn hoặc có các chứng chỉ tiếng Anh như IELTS, TOEIC. Sinh viên năm 2,3,4 đang theo học các ngành liên quan đến tiếng Anh và Ngôn Ngữ. Ưu tiên ứng viên đã làm việc trong môi trường giáo dục và tiếp xúc thường xuyên với tiếng Anh. Có trách nhiệm, nhiệt tình, có đam mê và muốn phát triển nghề nghiệp trong lĩnh vực giáo dục; có khả năng truyền lửa, truyền cảm hứng học tiếng Anh. Chưa có kinh nghiệm được đào tạo từ đầu chỉ cần đam mê với công việc trong ngành giáo dục.
Kỹ năng chuyên môn: [''Tiếng Anh tốt, phát âm chuẩn'', ''Chứng chỉ tiếng Anh như IELTS, TOEIC'']
Kỹ năng mềm: [''Có trách nhiệm'', ''Nhiệt tình'', ''Đam mê giáo dục'', ''Khả năng truyền cảm hứng'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', '17:30 - 21:30, từ thứ Hai đến thứ Bảy', '[''Môi trường startup phát triển nhanh'', ''Cân nhắc lên vị trí fulltime'', ''Được đào tạo kỹ năng'', ''Tham gia Teambuilding, du lịch 2-3 lần/năm'', ''Học tiếng Anh miễn phí'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (756, 10, 3, 'Giáo Viên Kiểm Tra Trình Độ Đầu Vào', '- Giảng dạy buổi học trải nghiệm cho các đối tượng học sinh từ 5-17 tuổi. - Báo cáo sau buổi dạy: Video giảng dạy, Phiếu đánh giá năng lực học viên, Định hướng lộ trình học tập cho học sinh. - Tổng hợp những ý kiến góp ý của học viên và phụ huynh, phản hồi thông tin đến quản lý.', '- Độ tuổi: Từ 20 tuổi trở lên - Giới tính: Nam/nữ - Trình độ Tiếng Anh: IELTS từ 5.5 trở lên/ TOEIC từ 785 trở lên/ VSTEP (từ B2 trở lên). Ưu tiên ứng viên tốt nghiệp chuyên ngành sư phạm Anh, ngôn ngữ Anh. - Có các chứng chỉ liên quan đến giảng dạy Tiếng Anh: TESOL, TEFL, Nghiệp vụ sư phạm - là một lợi thế. - Kinh nghiệm chuyên môn: Dạy học tối thiểu 6 tháng trong vòng 1 năm gần đây. Phát âm rõ ràng, dễ nghe, không ngọng, không bị ảnh hưởng của giọng địa phương. Ưu tiên ứng viên có kinh nghiệm dạy online. - Cam kết làm việc tối thiểu 4 tháng sau khi ký hợp đồng chính thức. - Có máy tính: loa, mic, webcam sử dụng tốt và đường truyền Internet ổn định đảm bảo phục vụ cho việc dạy học online. - Thời gian làm việc: linh hoạt, ngoài giờ hành chính. Chỉ cẩn đảm bảo thực hiện công việc tối thiểu 10 giờ/tuần.
Kỹ năng chuyên môn: [''Tiếng Anh: IELTS từ 5.5 trở lên/ TOEIC từ 785 trở lên/ VSTEP (từ B2 trở lên)'', ''Chứng chỉ TESOL, TEFL, Nghiệp vụ sư phạm'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng sư phạm'', ''Kỹ năng quan sát và lắng nghe'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 20000000.00, '3.0 - 20.0 triệu', 'Linh hoạt, ngoài giờ hành chính', '[''Thưởng và tăng lương theo Quý'', ''Thưởng sinh nhật'', ''Được tham gia chương trình đào tạo bài bản'', ''Cung cấp giáo trình giảng dạy'', ''Hỗ trợ chuyên môn và kỹ thuật 24/7'', ''Cơ hội thăng tiến lên vị trí quản lý'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (757, 2, 3, 'Giáo Viên Chương Trình Tú Tài Quốc Tế (IB)', 'Marathon tìm đồng đội về chung nhà trên Toàn Quốc: Lên kế hoạch và giảng dạy các bài học theo tiêu chuẩn IB, bao gồm các môn học như IB English, IB Mathematics, IB Science, IB History hoặc các môn học liên quan khác. Xây dựng và thực hiện các hoạt động học tập khuyến khích tư duy phản biện, nghiên cứu độc lập và kỹ năng giải quyết vấn đề. Hướng dẫn học sinh thực hiện các dự án nghiên cứu và lập kế hoạch bài luận dài hạn (Extended Essay) theo yêu cầu của IB. Đánh giá, theo dõi sự tiến bộ của học sinh và cung cấp phản hồi chi tiết để cải thiện kết quả học tập. Tham gia và hỗ trợ các hoạt động ngoại khóa, hội thảo và các sự kiện của chương trình IB nhằm xây dựng một cộng đồng học tập tích cực.', 'Tốt nghiệp Cao Đẳng trở lên các chuyên ngành liên quan (Giáo dục, Ngôn ngữ, Khoa học, Toán học hoặc các lĩnh vực khác phù hợp). Ưu tiên ứng viên có bằng Sư Phạm hoặc chứng chỉ IB. Có ít nhất 2 năm kinh nghiệm giảng dạy chương trình Tú tài Quốc tế IB hoặc chương trình quốc tế tương đương. Kinh nghiệm làm việc với học viên quốc tế và hiểu biết sâu sắc về các tiêu chuẩn học thuật của IB là một lợi thế. Có chứng chỉ giảng dạy IB hoặc các chứng chỉ quốc tế khác là một lợi thế (Ví dụ: chứng nhận IB Workshop hoặc đào tạo chuyên môn về IB).
Kỹ năng chuyên môn: [''Bằng Sư Phạm'', ''Chứng chỉ IB'']
Kỹ năng mềm: [''Kỹ năng giảng dạy hiệu quả'', ''Kỹ năng quản lý lớp học'', ''Kỹ năng đánh giá và phản hồi học sinh'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 đến Chủ Nhật (18h00 đến 19h30 hoặc 20h00 đến 21h30 hoặc 18h00 đến 21h30)', '[''Thời gian làm việc linh hoạt'', ''Môi trường làm việc trẻ trung'', ''Nhiều loại thưởng đi kèm'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (758, 3, 3, 'Thực Tập Sinh Kinh Doanh', 'Hỗ trợ xử lý vấn đề khách hàng, quản lý tệp khách hàng, tìm kiếm khách hàng tiềm năng. Hỗ trợ khách hàng trải nghiệm dịch vụ sản phẩm của công ty hẹn khách lên lịch tư vấn để anh/chị tư vấn, giải quyết các vấn đề của khách hàng. Chi tiết công việc sẽ trao đổi cụ thể hơn trong quá trình phỏng vấn. Thời gian và địa điểm làm việc: LK 24, TT01, Khu nhà ở cao cấp 96-96B, Nguyễn Huy Tưởng, Thanh Xuân, Hà Nội. Có thể làm việc online nếu vẫn đáp ứng được đủ điều kiện công việc. Linh hoạt thời gian phù hợp (Ca làm việc offline linh hoạt, đăng kí tối thiểu 3 ca/tuần).', 'Đang là học sinh, sinh viên học tập và làm việc trong địa bàn Thanh Xuân, Hà Nội (cách khoảng 5-6km). KHÔNG YÊU CẦU KINH NGHIỆM. Mong muốn phát triển bản thân và học kỹ năng nắm bắt tâm lý khách hàng. Có kỹ năng giao tiếp và thuyết phục tốt, tự tin nói chuyện qua điện thoại hoặc trực tiếp. Có tinh thần học hỏi, chủ động, nhiệt tình trong công việc. Ưu tiên ứng viên yêu thích lĩnh vực giáo dục và mong muốn phát triển kỹ năng kinh doanh, tư vấn bán hàng.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'', ''Tinh thần học hỏi'', ''Chủ động'', ''Nhiệt tình'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được đào tạo về kỹ năng giao tiếp'', ''Có lộ trình thăng tiến'', ''Giấy chứng nhận làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (759, 7, 3, 'Cộng Tác Viên Quản Lý Lớp Học', 'Hỗ trợ chuẩn bị tài liệu, bài giảng và các hoạt động học tập. Hướng dẫn, giải đáp thắc mắc và hỗ trợ học viên trong các buổi học hoặc hoạt động nhóm. Quản lý lớp học, đảm bảo môi trường học tập hiệu quả và tích cực. Tham gia tổ chức các hoạt động ngoại khóa, sự kiện học thuật hoặc kiểm tra, đánh giá học viên. Phối hợp với bộ phận học vụ để theo dõi tiến độ học tập và cung cấp phản hồi cho học viên.', 'Chấp nhận sinh viên từ năm 2 trở lên. Kỹ năng giao tiếp tốt, kiên nhẫn và yêu thích trẻ em. Giao tiếp và ngữ pháp tiếng Anh tốt. Có chứng chỉ tiếng Anh tương đương B2 trở lên, chuyên ngành học liên quan tới ngôn ngữ Anh là một lợi thế. Có kiến thức nền tảng về lĩnh vực giảng dạy hoặc sẵn sàng học hỏi. Tinh thần trách nhiệm, chủ động và khả năng quản lý thời gian hiệu quả. Thời gian rảnh nhiều từ sau 17h15 các ngày trong tuần và thứ 7, Chủ Nhật.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Quản lý thời gian'', ''Tổ chức'']
Kỹ năng mềm: [''Kiên nhẫn'', ''Yêu thích trẻ em'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '1.0 - 4.0 triệu', 'Linh hoạt ca làm việc từ 1.5 tiếng - 3 tiếng, các ngày trong tuần từ 17h đến 21h, các ngày cuối tuần từ 8h đến 18h', '[''Cơ hội trở thành giáo viên chính thức tại Language Link'', ''Giờ giấc làm việc linh hoạt'', ''Thu nhập không hạn chế theo năng lực và nhu cầu làm việc'', ''Các hoạt động gắn kết nhân viên'', ''Môi trường làm việc năng động, chuyên nghiệp, thân thiện'', ''Trang thiết bị, cơ sở vật chất khang trang, hiện đại, đầy đủ'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (760, 8, 3, 'Cộng Tác Viên Giảng Dạy', 'Hỗ trợ chuẩn bị tài liệu, bài giảng và các hoạt động học tập. Hướng dẫn, giải đáp thắc mắc và hỗ trợ học viên trong các buổi học hoặc hoạt động nhóm. Quản lý lớp học, đảm bảo môi trường học tập hiệu quả và tích cực. Tham gia tổ chức các hoạt động ngoại khóa, sự kiện học thuật hoặc kiểm tra, đánh giá học viên. Phối hợp với bộ phận học vụ để theo dõi tiến độ học tập và cung cấp phản hồi cho phụ huynh.', 'Chấp nhận sinh viên từ năm 2 trở lên. Kỹ năng giao tiếp tốt, kiên nhẫn và yêu thích trẻ em. Giao tiếp và ngữ pháp tiếng Anh tốt. Có chứng chỉ tiếng Anh tương đương B2 trở lên, chuyên ngành học liên quan tới ngôn ngữ Anh là một lợi thế. Có kiến thức nền tảng về lĩnh vực giảng dạy hoặc sẵn sàng học hỏi. Tinh thần trách nhiệm, chủ động và khả năng quản lý thời gian hiệu quả. Thời gian rảnh nhiều từ sau 17h15 các ngày trong tuần và thứ 7, Chủ Nhật.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kiến thức nền tảng về lĩnh vực giảng dạy'']
Kỹ năng mềm: [''Kiên nhẫn'', ''Tinh thần trách nhiệm'', ''Khả năng quản lý thời gian hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Các ngày trong tuần từ 17h đến 21h, các ngày cuối tuần từ 8h - 18h', '[''Cơ hội trở thành giáo viên chính thức tại Language Link'', ''Giờ giấc làm việc linh hoạt'', ''Các hoạt động gắn kết nhân viên'', ''Môi trường làm việc năng động, chuyên nghiệp, thân thiện'', ''Trang thiết bị, cơ sở vật chất khang trang, hiện đại, đầy đủ'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (761, 9, 3, 'Giáo Viên Tiếng Nhật Dạy Online', 'Giảng dạy các lớp từ N5 - N2 theo lộ trình, giáo án có sẵn tại trung tâm. Yêu cầu phụ trách đến hết khóa học (Thông thường 1 khóa học sẽ từ 3-6 tháng). Công ty sẽ sắp xếp lớp học dựa trên thời gian bạn đăng ký. Tham gia họp hàng tháng (nếu có). Sao sát quá trình học của học viên để kết hợp với các bộ phận của trường để hỗ trợ học viên tốt nhất.', 'Đối với lớp trình độ N5,4: Trình độ JLPT N2 trở lên (ứng viên trình độ N3 vui lòng không ứng tuyển), Kinh nghiệm giảng dạy sơ cấp 1 năm trở lên, Ưu tiên các ứng viên có kinh nghiệm và đã từng đi Nhật, Độ tuổi: trên 23 tuổi. Đối với lớp trình độ N3, N2: Trình độ tiếng Nhật N2,N1 cứng đối với lớp N3; N1 với lớp N2, Kinh nghiệm giảng dạy N3 1 năm trở lên, Ưu tiên các ứng viên có kinh nghiệm và đã từng đi Nhật, Độ tuổi: trên 23 tuổi. Chung: Có định hướng phát triển công việc theo ngành giáo dục, tâm huyết với nghề, có ý thức học hỏi, nâng cao chuyên môn.
Kỹ năng chuyên môn: [''Giảng dạy tiếng Nhật'']
Kỹ năng mềm: [''Chăm chỉ'', ''Ham học hỏi'', ''Sáng tạo'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'nước ngoài', NULL, 'MONTHLY', 15000000.00, '5.0 - 15.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Thưởng cuối khóa'', ''Thưởng khi có học viên học lên'', ''Được đào tạo phương pháp dạy'', ''Được hỗ trợ 100% chi phí thi JLPT N1 1 lần/năm'', ''Được hỗ trợ 90% học phí học N1 tại Kohi'', ''Tham gia các buổi đào tạo nâng cao kiến thức, văn hoá do Kohi tổ chức'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (762, 10, 3, 'Giáo Viên Tiếng Anh', 'Đứng lớp và giảng dạy theo nội dung đào tạo và giáo trình có sẵn của khóa học; đảm bảo hoàn thành khung kiến thức yêu cầu của từng khóa; Sáng tạo các hoạt động giảng dạy, bài tập về nhà, kiến thức bổ trợ cho khóa học dựa trên giáo trình của Jaxtina; Theo dõi, kiểm soát, đánh giá chất lượng học viên, đề ra kế hoạch nâng cao chất lượng học viên và đảm bảo đầu ra cam kết; Báo cáo cho Jaxtina về tình hình học tập của học viên thường xuyên và theo đúng lộ trình; Thực hiện các công việc chăm sóc và quản lý lớp học tại trường Đại học; Phối hợp cùng Jaxtina trong việc tổ chức sự kiện, workshop, chia sẻ chuyên môn tại trường Đại học.', 'Ứng viên tốt nghiệp trường đại học đào tạo Ngôn ngữ Anh và có chứng chỉ sư phạm; hoặc ứng viên có bằng cử nhân/ chứng chỉ sư phạm Anh; Có tâm với nghề, trách nhiệm, nhiệt tình, có đam mê và muốn phát triển nghề nghiệp trong lĩnh vực giáo dục; có khả năng truyền lửa, truyền cảm hứng học tiếng Anh; Có chứng chỉ tiếng Anh sau: TOEIC 900+, TESOL,hoặc bằng cấp tương đương; Ưu tiên tuyển dụng các giảng viên tiếng Anh, cựu sinh viên trường Đại học yêu thích giảng dạy và mong muốn tạo nên những thay đổi tích cực cho sinh viên.
Kỹ năng chuyên môn: [''TOEIC 900+'', ''TESOL'']
Kỹ năng mềm: [''Có tâm với nghề'', ''Trách nhiệm'', ''Nhiệt tình'', ''Đam mê'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 25000000.00, '10.0 - 25.0 triệu', 'Trung bình 2-3 buổi/tuần, mỗi buổi 2,5 giờ giảng dạy', '[''Môi trường giảng dạy chuyên nghiệp, hiện đại'', ''Cơ hội đứng lớp tại các giảng đường đại học hàng đầu'', ''Tham gia các chương trình đào tạo nội bộ'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (763, 2, 3, 'Thực Tập Sinh Tư Vấn', 'Tiếp đón và tư vấn học viên tại trung tâm, hỗ trợ đội ngũ tư vấn tuyển sinh, hỗ trợ công tác truyền thông & tuyển sinh tại trung tâm, học hỏi & tham gia đào tạo.', 'Là sinh viên năm 3, năm cuối hoặc vừa tốt nghiệp các ngành: Kinh doanh, Marketing, Giáo dục, Sư phạm, Ngôn ngữ Anh, Truyền thông, hoặc các ngành liên quan. Có kỹ năng giao tiếp tốt, nói chuyện rõ ràng, thuyết phục, biết lắng nghe và tạo thiện cảm với người đối diện. Yêu thích môi trường giáo dục, có mong muốn phát triển nghề nghiệp trong lĩnh vực tư vấn – chăm sóc khách hàng – dịch vụ đào tạo. Chủ động – cầu tiến – ham học hỏi; tiếp thu nhanh, sẵn sàng cải thiện khi được phản hồi. Tác phong làm việc chuyên nghiệp – đúng giờ – trung thực – có trách nhiệm với công việc được giao. Có tinh thần “Say Yes”, sẵn sàng thử sức với nhiều nhiệm vụ khác nhau để khám phá năng lực và sở trường của bản thân. Ưu tiên ứng viên từng tham gia các hoạt động CLB, tình nguyện viên, từng làm part-time liên quan đến tư vấn, telesales, giáo dục, chăm sóc khách hàng.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Nói chuyện rõ ràng, thuyết phục'', ''Biết lắng nghe và tạo thiện cảm với người đối diện'', ''Chủ động – cầu tiến – ham học hỏi'', ''Tác phong làm việc chuyên nghiệp'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6, làm full time theo ca hoặc part time 4 giờ/ngày', '[''Dấu mộc xác nhận thực tập'', ''Chứng nhận hoàn thành thực tập sinh xuất sắc'', ''Thư giới thiệu từ CEO'', ''Cơ hội làm việc chính thức sau kỳ thực tập nếu thể hiện tốt'', ''Khóa học tiếng Anh miễn phí'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (764, 3, 3, 'Người tạo kinh doanh xã hội-Cộng tác viên (3 tháng)', 'Chúng tôi đang tìm kiếm các cộng tác viên nhiệt tình và chủ động để tham gia nhóm tổ chức SBC của chúng tôi trong khoảng thời gian 3 tháng. Bạn sẽ làm việc trực tiếp với nhóm cốt lõi để hỗ trợ truyền thông, thực hiện sự kiện, tiếp cận cộng đồng và hậu cần dự án. Trách nhiệm chính bao gồm hỗ trợ lập kế hoạch và thực hiện các phiên định hướng SBC, hoạt động kết nối mạng và hội thảo đào tạo, hỗ trợ giao tiếp người tham gia, điều phối hậu cần cho các sự kiện, nghiên cứu các đối tác tiềm năng, ghi lại những điểm nổi bật chính và đóng góp ý tưởng để cải thiện trải nghiệm của người tham gia.', 'You Are Someone Who: Is a university student or fresh graduate (preferably in Communications, Marketing, Business, or related fields). Has strong communication skills in both English and Vietnamese. Enjoys working with youth, social impact projects, and global initiatives. Is detail-oriented, responsible, and a proactive team player. Has experience with content creation, design tools (Canva, CapCut, etc.), or event organizing (a plus but not required).
Kỹ năng chuyên môn: [''Content creation'', ''Design tools (Canva, CapCut, etc.)'', ''Event organizing'']
Kỹ năng mềm: [''Strong communication skills'', ''Detail-oriented'', ''Responsible'', ''Proactive team player'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Monday - Friday (from 08:00 to 17:30)', '[''First-hand experience in organizing an international social innovation program'', ''Network expansion with students, experts, and mentors from around the world'', ''Mentorship and feedback from professionals in business, education, and impact sectors'', ''Certificate of contribution upon successful completion'', ''Flexible working hours'', ''Dynamic, supportive team culture'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (765, 7, 3, 'Thực Tập Sinh Học Thuật', 'Tham gia hỗ trợ vận hành học thuật, trợ giảng & hỗ trợ giảng viên, hỗ trợ R&D học thuật, tham gia đào tạo nội bộ và chương trình định hướng nghề nghiệp.', 'Sinh viên năm 3, năm cuối hoặc vừa tốt nghiệp các chuyên ngành: Sư phạm tiếng Anh, Ngôn ngữ Anh, Biên phiên dịch hoặc các ngành nghề khác có sử dụng ngôn ngữ Anh thành thạo. Có năng lực tiếng Anh tốt, tương đương IELTS 7.0 trở lên. Ưu tiên ứng viên đã từng: Là trợ giảng, gia sư, tình nguyện viên giáo dục; tham gia hoạt động học thuật tại trường hoặc các CLB tiếng Anh… Cầu tiến, chủ động, luôn học hỏi, tiếp thu nhanh và phản hồi tốt. Tác phong chuyên nghiệp, đúng giờ, nghiêm túc với công việc được giao. Tinh thần “Say Yes”, sẵn sàng thử thách ở nhiều mảng khác nhau để khám phá năng lực bản thân. Trung thực, có trách nhiệm, cẩn thận trong xử lý thông tin và nội dung học thuật. Có thể sẵn sàng di chuyển các trung tâm Anh ngữ của Jaxtina trong nội thành để học hỏi và phát triển.
Kỹ năng chuyên môn: [''Tiếng Anh tốt, tương đương IELTS 7.0 trở lên'']
Kỹ năng mềm: [''Cầu tiến'', ''Chủ động'', ''Luôn học hỏi'', ''Tiếp thu nhanh'', ''Phản hồi tốt'', ''Tác phong chuyên nghiệp'', ''Đúng giờ'', ''Nghiêm túc với công việc'', ''Tinh thần “Say Yes”'', ''Trung thực'', ''Có trách nhiệm'', ''Cẩn thận trong xử lý thông tin'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:15 đến 17:30)', '[''Lộ trình phát triển sau thực tập'', ''Được đào tạo bài bản về nghiệp vụ học vụ, sư phạm cơ bản, tư duy phát triển chương trình, kỹ năng truyền đạt'', ''Tham gia các buổi mentoring 1:1 với quản lý học thuật'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (766, 8, 3, 'Giáo Viên Tiếng Anh Dạy Tại Các Doanh Nghiệp (B2B)', 'Trực tiếp giảng dạy và vận hành lớp học nhằm đảm bảo học viên đạt mục tiêu đầu ra khóa học, theo dõi tiến độ học viên và báo cáo tình hình lớp học. Trực tiếp giảng dạy tiếng Anh tại các doanh nghiệp đối tác, theo chương trình và kế hoạch đào tạo được thiết kế riêng cho từng đơn vị. Theo dõi tiến độ và hiệu quả học tập của học viên, đảm bảo học viên đạt mục tiêu đầu ra đã cam kết với doanh nghiệp. Tư vấn, hỗ trợ học viên trong suốt quá trình học: giải đáp thắc mắc, định hướng phương pháp học phù hợp với môi trường công việc thực tế. Thiết lập môi trường lớp học chuyên nghiệp, tích cực và tôn trọng, phù hợp với đặc thù đối tượng học viên là người đi làm. Đề xuất tài liệu, bài tập thực hành bổ trợ phù hợp với nhu cầu công việc và năng lực đầu vào của từng nhóm học viên. Phối hợp với bộ phận học thuật và quản lý dự án doanh nghiệp để cập nhật tình hình lớp học, tham gia điều chỉnh phương pháp giảng dạy nếu cần thiết. Đóng góp ý kiến cải tiến chương trình giảng dạy, xây dựng nội dung học tập sát với ngành nghề hoặc đặc thù doanh nghiệp (nếu có). Tham gia các buổi training, họp chuyên môn định kỳ để nâng cao năng lực sư phạm và cập nhật xu hướng đào tạo doanh nghiệp. Thể hiện hình ảnh giảng viên chuyên nghiệp, chuẩn mực, là người đại diện uy tín của Jaxtina tại môi trường doanh nghiệp.', 'Tốt nghiệp Đại học trở lên các chuyên ngành liên quan đến tiếng Anh. Có chứng chỉ IELTS từ 8.0 hoặc Toeic 900 trở lên. Có tối thiểu 01–02 năm kinh nghiệm giảng dạy tiếng Anh, ưu tiên trong môi trường trung tâm Anh ngữ, lớp doanh nghiệp hoặc tổ chức đào tạo chuyên nghiệp. Ưu tiên ứng viên: Đã từng giảng dạy các lớp Giao tiếp, lớp doanh nghiệp (online hoặc offline); Có kinh nghiệm thiết kế giáo án, tổ chức hoạt động lớp học và kiểm soát tiến độ học viên; Có chứng chỉ sư phạm. Con người: Tận tâm, chủ động, nhiệt huyết, tác phong chuẩn mực, chững trạc, cầu thị, sẵn sàng tiếp nhận góp ý từ học viên/doanh nghiệp, linh hoạt, xử lý tình huống khéo léo. Yêu cầu khác: Làm việc theo ca, sẵn sàng di chuyển tới địa điểm giảng dạy khác nhau trong nội thành.
Kỹ năng chuyên môn: [''Chứng chỉ IELTS từ 8.0'', ''Chứng chỉ Toeic 900 trở lên'']
Kỹ năng mềm: [''Tận tâm'', ''Chủ động'', ''Nhiệt huyết'', ''Tác phong chuẩn mực'', ''Chững trạc'', ''Cầu thị'', ''Sẵn sàng tiếp nhận góp ý'', ''Linh hoạt'', ''Xử lý tình huống khéo léo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 25000000.00, '15.0 - 25.0 triệu', 'Thứ 2 - Thứ 6', '[''Tham gia các buổi đào tạo, workshop chuyên môn'', ''Được đề xuất cải tiến chương trình'', ''Hỗ trợ giáo trình, tài liệu'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (767, 9, 3, 'IELTS Instructor 7.5+ - Parttime/Fulltime', 'Giảng dạy IELTS trực tuyến & trực tuyến theo nhu cầu mỗi lớp được sắp xếp sẵn tại trung tâm. Hiểu cấu trúc chứng chỉ ngoại ngữ để chấm điểm, đánh giá năng lực, thiết kế chương trình dạy cá nhân hóa mỗi học viên. Tham gia viết Scholarly Articles, đóng góp vào kho tài nguyên học thuật của ZIM. Hỗ trợ phát triển tài liệu học tập: giáo trình, đề thi thử, video khóa học, livestream… Cập nhật phương pháp giảng dạy mới, sáng tạo cách học IELTS hiệu quả hơn cho học viên. Hỗ trợ học viên Onsite: Kiểm tra đầu vào, coaching 1-1.', 'Có tư duy thiết kế bài giảng, đánh giá và xây dựng giải pháp định hướng học của học viên. Có kiến thức về (các) chứng chỉ năng lực ngoại ngữ: thông tin tổng quan, cấu trúc, cách đánh giá, cách tính điểm. Theo đuổi học thuật: research, report các tuyến bài khoa học giáo dục ngoại ngữ theo hướng cá nhân hóa và bối cảnh hóa.
Kỹ năng chuyên môn: [''Kiến thức về chứng chỉ năng lực ngoại ngữ'', ''Thiết kế chương trình dạy cá nhân hóa'']
Kỹ năng mềm: [''Tư duy thiết kế bài giảng'', ''Đánh giá và xây dựng giải pháp định hướng học'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 40000000.00, '15.0 - 40.0 triệu', 'Thứ 2 - Sáng Chủ Nhật, 8h - 12h, 14h - 18h, 18h - 22h', '[''Bảo hiểm xã hội'', ''Bảo hiểm sức khỏe'', ''Khám sức khỏe định kỳ'', ''Thưởng hiệu quả làm việc'', ''Du lịch hàng năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (768, 10, 3, 'Giáo Viên Tiếng Anh Người Việt', '- Thực hiện theo các kế hoạch bài học và tài liệu được cung cấp cho VNT. - Để thích ứng các kế hoạch bài học theo quy định khi cần thiết dựa trên nhu cầu của người học. - Để cung cấp các bài học năng động và giao tiếp có hiệu quả và thu hút các sinh viên. - Để chuẩn bị các kế hoạch và tài liệu bài học cho các bài học thường xuyên, chẳng hạn như dự án, Cambridge hoặc các bài học giảm nhẹ khác bên ngoài các khóa học và chương trình giảng dạy tiêu chuẩn. -đảm nhận các nhiệm vụ hành chính thiết yếu, chẳng hạn như giữ các hồ sơ công việc, đăng ký lớp học, kế hoạch bài học, đánh giá, v.v. theo chỉ dẫn của Giám đốc Trung tâm, Giám đốc học thuật hoặc giáo viên cao cấp theo các yêu cầu.', '- Bachelor’s degree - 6.5 IELTS level (or equivalent; mock test at the centre will be provided for candidates) - TEFL/TESOL preferred - Able to work by shifts (weekday nights, weekends) Please make sure to write your CV in English. Please note that only successful candidates will be contacted due to high volumes of applications.
Kỹ năng chuyên môn: [''6.5 IELTS level (or equivalent)'', ''TEFL/TESOL preferred'']
Kỹ năng mềm: [''Able to work by shifts'', ''Good communication skills'']', 'PART_TIME', 'ONSITE', 'đồng nai', 'Đồng Nai', 'MONTHLY', 4000000.00, '0.0 triệu', 'Weekday evenings and weekend', '[''Hourly salary based on experience and qualifications'', ''Professional training provided'', ''On-going development opportunities'', ''Working in a cross-cultural, dynamic and professional environment'', ''Expanding network with ILA social events'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (769, 2, 3, 'Nhân Viên Kinh Doanh', 'Tư vấn khách hàng về khóa học, giúp các học viên, phụ huynh nắm rõ khung chương trình đào tạo, hỗ trợ học viên đăng kí các lớp phù hợp theo lứa tuổi, trình độ. Thực hiện ký kết hợp đồng đào tạo với khách hàng. Chăm sóc khách hàng, học viên tái đăng ký, gửi báo cáo học tập định kì cho phụ huynh học viên. Lên kế hoạch, định hướng và phát triển trung tâm về hạng mục doanh số, thương hiệu. Báo cáo kết quả kinh doanh và tổng kết các chỉ số kinh doanh. Hỗ trợ chăm sóc lớp học, các công việc chung bao quát tại trung tâm.', 'Sinh viên đang học chuyên về âm nhạc nghệ thuật, quản trị kinh doanh… hoặc có kinh nghiệm trong lĩnh vực trung tâm giáo dục, dịch vụ, chăm sóc khách hàng là một lợi thế. Thành thạo Word, Excel, Google Sheet, Zalo, Drive. Biết cách lập kế hoạch, xây dựng quy trình công việc. Giao tiếp linh hoạt, truyền cảm hứng. Quản lý thời gian và phân phối công việc hiệu quả. Nhiệt tình, trách nhiệm cao. Yêu thích âm nhạc, giáo dục. Phong cách làm việc chủ động – cầu tiến – đồng hành cùng đội ngũ.
Kỹ năng chuyên môn: [''Thành thạo Word'', ''Excel'', ''Google Sheet'', ''Zalo'', ''Drive'']
Kỹ năng mềm: [''Giao tiếp linh hoạt'', ''Truyền cảm hứng'', ''Quản lý thời gian'', ''Phân phối công việc hiệu quả'', ''Nhiệt tình'', ''Trách nhiệm cao'', ''Yêu thích âm nhạc'', ''Giáo dục'', ''Phong cách làm việc chủ động'', ''Cầu tiến'', ''Đồng hành cùng đội ngũ'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 3 - Chủ nhật (từ 08:00 đến 17:00)', '[''Có thể thực tập hoặc làm việc chính thức'', ''Được chứng nhận thực tập sau khi hoàn thành khóa'', ''Làm việc trong môi trường giáo dục nghệ thuật chuyên nghiệp – năng động'', ''Tham gia hoạt động nội bộ: sinh nhật, teambuilding, sự kiện âm nhạc'', ''Được học piano miễn phí'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (770, 3, 3, 'Giáo Viên THPT Part Time Khối 12', 'Giảng dạy theo Bộ giáo trình chuẩn có sẵn của trung tâm. Soạn giáo án, đề test tháng, lên kế hoạch soạn giảng theo từng tuần-từng tháng. Chấm bài test, nhận xét học sinh theo từng buổi/ theo bài kiểm tra các đợt. Hướng dẫn và theo sát việc học tập của học sinh của các lớp đảm nhận, đảm bảo sự tiến bộ của học sinh trong quá trình học.', 'Độ tuổi từ 25 đến 30. Có kinh nghiệm đứng lớp, giảng dạy các khối lớp 12 từ 02 năm - 03 năm trở lên. Khả năng truyền đạt tốt, đam mê giải Toán. Nhiệt tình, học hỏi, chủ động trong công việc và gắn bó lâu dài. Ưu tiên ứng viên có kinh nghiệm làm việc ở các khối trung tâm.
Kỹ năng chuyên môn: [''Kỹ năng sư phạm'', ''Kỹ Năng Soạn Giáo Án'', ''Kỹ Năng Quản Lý Lớp Học'', ''Kỹ Năng Giao Tiếp Và Truyền Đạt Hiệu Quả'']
Kỹ năng mềm: [''Khả năng truyền đạt tốt'', ''Nhiệt tình'', ''Học hỏi'', ''Chủ động trong công việc'', ''Gắn bó lâu dài'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 20000000.00, '10.0 - 20.0 triệu', '17h00 - 21h00 hàng ngày, Thứ 7, Chủ Nhật làm sáng/ chiều/ tối', '[''Được ĐÀO TẠO BÀI BẢN kỹ năng giảng dạy'', ''Có cơ hội thăng tiến lên các vị trí FULL -TIME'', ''Tổng thu nhập 10-20 triệu/ tháng'', ''Được làm việc trong môi trường trẻ trung năng động'', ''Đi du lịch, hoạt động team building 3 lần/ năm'', ''Đóng đầy đủ chế độ BHXH, BHYT, BHTN theo quy định nhà nước'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (771, 7, 3, 'Thực Tập Sinh Phát Triển Học Liệu Tiếng Anh', 'Tham gia biên soạn, hiệu chỉnh, cập nhật các tài liệu học tập dựa trên khung chương trình có sẵn. Đảm bảo hợp bố cục và tối ưu hóa tư liệu cho học sinh. Thiết kế slide, tài liệu học trên lớp, sách học, và bài tập về nhà dành cho học sinh các cấp độ dựa theo khung chương trình có sẵn. Hỗ trợ nhập liệu, cập nhật tài liệu lên hệ thống học tập theo tài liệu có sẵn. Tham gia hỗ trợ các công việc chuyên môn khác khi được yêu cầu từ bộ phận học thuật hoặc quản lý.', 'Sinh viên năm 2, 3, 4 chuyên ngành ngôn ngữ Anh hoặc sư phạm tiếng Anh. Sử dụng thành thạo Canva và hiểu rõ các hiệu ứng trên PowerPoint là 1 lợi thế. Có máy tính laptop và kết nối mạng Internet ổn định tại nhà. Cầu tiến, nhiệt tình, có tinh thần học hỏi.
Kỹ năng chuyên môn: [''Sử dụng thành thạo Canva'', ''Hiểu rõ các hiệu ứng trên PowerPoint'']
Kỹ năng mềm: [''Cầu tiến'', ''Nhiệt tình'', ''Có tinh thần học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hỗ trợ vé xe: 5.000 VNĐ/ngày (làm việc tại công ty)'', ''Được đào tạo và tham gia vào mảng phát triển học liệu'', ''Hỗ trợ dấu mộc và xác nhận thực tập'', ''Môi trường trẻ trung, năng động'', ''Có cơ hội làm việc lâu dài tại Rino'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (772, 8, 3, 'Cộng Tác Viên Tuyển Sinh Du Học', 'Tìm kiếm cá nhân có nguyện vọng học tiếng Đức, đi du học nghề tại Đức. Tuyển sinh học viên qua các kênh khác nhau; Phối hợp với Công ty triển khai các sự kiện, chương trình phục vụ tuyển sinh tại các trường, đơn vị, tổ chức, địa phương. Tư vấn cho học viên về du học nghề Đức (điều kiện, hồ sơ, học tiếng, ngành nghề v..v). Phối hợp với Bộ phận chuyên trách của Công ty để hỗ trợ học viên từ khi ký hợp đồng cho đến khi hoàn thiện hồ sơ du học. Thiết lập các văn phòng tư vấn tại các địa phương (khuyến khích theo khả năng).', 'Có tinh thần quyết chiến với công việc, đam mê kiếm tiền, yêu thích kinh doanh/bán hàng. Có kỹ năng giao tiếp, thuyết phục, xây dựng niềm tin, có kỹ năng chốt sale là một lợi thế. Ưu tiên người am hiểu về lĩnh vực Kinh doanh/Marketing, Giáo dục & Đào tạo, Du học, Xuất khẩu lao động, có mối quan hệ rộng. Nam/Nữ trong độ tuổi từ 25 ÷ 60, không yêu cầu bằng cấp.
Kỹ năng chuyên môn: []
Kỹ năng mềm: [''kỹ năng giao tiếp'', ''thuyết phục'', ''xây dựng niềm tin'', ''kỹ năng chốt sale'']', 'PART_TIME', 'ONSITE', 'đại kim, hoàng mai', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Mức hoa hồng hấp dẫn'', ''Thưởng'', ''Được tham gia các khóa đào tạo cơ bản/chuyên sâu'', ''Quyền lợi đặc biệt cho CTV xuất sắc'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (773, 9, 3, 'Giáo Viên IELTS Offline Part-Time/Sẵn Giáo Trình', 'Trực tiếp giảng dạy IELTS tại một trong các cơ sở của trung tâm (giáo viên được lựa chọn địa điểm dạy phù hợp). Dạy chuyên sâu cả 4 kỹ năng IELTS theo lộ trình và mục tiêu của từng học viên. Sử dụng giáo trình do trung tâm thiết kế, không cần tự soạn bài. Nhận lớp theo sự phân công của bộ phận Điều phối Giảng viên.', 'IELTS đạt tối thiểu 8.0, ưu tiên Speaking từ 7.0 trở lên. Ưu tiên ứng viên có kinh nghiệm giảng dạy hoặc sở hữu chứng chỉ đào tạo sư phạm, không bắt buộc phải có kinh nghiệm dạy IELTS. Có đam mê trong lĩnh vực giáo dục, đào tạo và phát triển con người. Thẳng thắn, chủ động, trách nhiệm và tận tâm trong công việc. Có tinh thần cầu tiến, yêu thích sự đổi mới, sáng tạo và mong muốn gắn bó lâu dài.
Kỹ năng chuyên môn: [''Khả năng giảng dạy IELTS'', ''Kiến thức sâu rộng về IELTS (tất cả các kỹ năng)'']
Kỹ năng mềm: [''Thẳng thắn'', ''Chủ động'', ''Trách nhiệm'', ''Tận tâm'', ''Cầu tiến'', ''Yêu thích sự đổi mới'', ''Sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 30000000.00, '15.0 - 30.0 triệu', 'Ca 1: 17h45 - 19h45, Ca 2: 20h - 22h', '[''Lương theo ca: từ 500.000 – 840.000 đồng/buổi'', ''Thưởng chấm chữa bài: từ 640.000 – 4.500.000 đồng/lớp'', ''Thưởng lớp kiểu mẫu: 1.000.000 đồng/lớp'', ''Được tham gia khóa đào tạo Giảng viên chuyên sâu trị giá 4.990.000 VNĐ'', ''Được đánh giá năng lực hàng tháng và xét duyệt điều chỉnh thu nhập'', ''Hỗ trợ hệ thống giảng dạy online chuyên nghiệp'', ''Môi trường làm việc trẻ trung, hiện đại'', ''Tham gia gói đào tạo nâng cao kỹ năng trị giá 100.000.000 VNĐ/người/năm'', ''Hưởng chính sách miễn/giảm học phí từ hệ thống đào tạo thuộc HBR Holdings'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (774, 10, 3, 'Giáo Viên Tiếng Anh', 'Giảng dạy tiếng Anh cho học viên các cấp độ từ cơ bản đến nâng cao. Xây dựng và triển khai kế hoạch giảng dạy phù hợp với từng lớp học. Chuẩn bị bài giảng, tài liệu và học liệu phục vụ cho việc giảng dạy. Đánh giá và theo dõi tiến độ học tập của học viên. Tổ chức các hoạt động ngoại khóa để tăng cường khả năng sử dụng tiếng Anh của học viên. Tham gia các buổi họp giáo viên và đóng góp ý kiến để cải thiện chất lượng giảng dạy. Hỗ trợ học viên ngoài giờ học khi cần thiết.', 'Không yêu cầu kinh nghiệm giảng dạy. Tốt nghiệp Đại học chuyên ngành Sư phạm Tiếng Anh, Ngôn ngữ Anh hoặc các chuyên ngành liên quan. Có chứng chỉ giảng dạy tiếng Anh quốc tế như TESOL, CELTA là một lợi thế. Phát âm chuẩn, giao tiếp tiếng Anh lưu loát. Có kiến thức nền tảng vững chắc về ngữ pháp và từ vựng tiếng Anh. Kỹ năng giao tiếp và thuyết trình tốt. Nhiệt tình, kiên nhẫn và có khả năng truyền đạt kiến thức hiệu quả. Có kỹ năng quản lý lớp học và tạo môi trường học tập tích cực. Thích ứng nhanh với các phương pháp giảng dạy mới và công nghệ hỗ trợ giảng dạy.
Kỹ năng chuyên môn: [''Chứng chỉ giảng dạy tiếng Anh quốc tế như TESOL'', ''CELTA'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Thuyết trình'', ''Nhiệt tình'', ''Kiên nhẫn'', ''Truyền đạt kiến thức hiệu quả'', ''Quản lý lớp học'', ''Thích ứng nhanh'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 12000000.00, '3.0 - 12.0 triệu', 'Linh hoạt chọn ca trong ngày: 18h, 19h, 20h, 21h', '[''Môi trường làm việc chuyên nghiệp, năng động và thân thiện'', ''Cơ hội phát triển nghề nghiệp và nâng cao kỹ năng giảng dạy'', ''Được tham gia các khóa đào tạo, workshop nâng cao chuyên môn'', ''Lương thưởng cạnh tranh, tăng lương định kỳ theo năng lực'', ''Được hưởng đầy đủ các chế độ bảo hiểm theo quy định của pháp luật'', ''Nghỉ phép có lương, nghỉ lễ tết theo quy định'', ''Tham gia các hoạt động teambuilding, du lịch hàng năm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (775, 2, 3, 'Nhân Viên Phát Triển Môn Tiếng Anh (Center)', 'Nghiên cứu, phân tích, và đánh giá các tài liệu giảng dạy Tiếng Anh cho cấp 1,2; Lên chương trình và thiết kế các sản phẩm như bài giảng, bài học, bài thi dựa trên hướng dẫn chuyên môn và nghiên cứu của bản thân; Xây dựng ngân hàng tài liệu, đề thi, câu hỏi cho những chương trình/ sản phẩm liên quan; Theo dõi, đánh giá và báo cáo hiệu quả của các chương trình/ sản phẩm; Hướng dẫn và hỗ trợ đội ngũ giảng dạy trong các công việc liên quan đến chương trình; Cập nhật những kiến thức mới, bổ sung, điều chỉnh, hiệu đính những chương trình/ sản phẩm cũ nếu cần; Những công việc liên quan khác theo yêu cầu trực tiếp và điều động của cấp trên.', 'Tốt nghiệp chuyên ngành sư phạm Tiếng Anh hoặc Ngôn ngữ Anh; Có chứng chỉ IELTS ít nhất band 7.5 hoặc trình độ tiếng Anh tương đương C1 trở lên; Có niềm yêu thích đam mê với Tiếng Anh và giáo dục; Thích tìm hiểu, nghiên cứu tài liệu; Khả năng đọc hiểu, dịch tài liệu tốt; Có kinh nghiệm giảng dạy, kinh nghiệm làm việc với trẻ nhỏ tại các cơ sở giáo dục uy tín và hiểu biết về chuyên ngành kiểm tra đánh giá là lợi thế; Sáng tạo, có khả năng nghiên cứu tốt, thường xuyên cập nhật các kiến thức mới đáp ứng công việc; Có khả năng phối hợp làm việc nhóm tốt; Chăm chỉ, cầu tiến, không ngại thử thách và áp lực.
Kỹ năng chuyên môn: [''Chứng chỉ IELTS ít nhất band 7.5 hoặc trình độ tiếng Anh tương đương C1 trở lên'']
Kỹ năng mềm: [''Sáng tạo'', ''Khả năng nghiên cứu tốt'', ''Khả năng phối hợp làm việc nhóm tốt'', ''Chăm chỉ'', ''Cầu tiến'', ''Không ngại thử thách và áp lực'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 12000000.00, '8.0 - 12.0 triệu', 'Thời gian làm việc linh hoạt (giờ vào làm từ 8h đến 9h, miễn đủ 8h/ngày)', '[''Ưu đãi cực lớn lên đến 90% đối với con em nhân viên học tập tại Tổ chức Giáo dục IEG'', ''Làm việc Offsite nguyên lương mỗi tháng 1 ngày'', ''Bảo hiểm Bảo Việt (50tr/năm)'', ''Buffet nước ép 2 tuần/1 lần'', ''Cơ hội đi công tác tại Anh, Trung Quốc, Bali, Đài Loan'', ''Được hưởng các chế độ BHXH, BHYT, BHTN, tham quan, nghỉ phép, nghỉ các ngày lễ theo quy định của Luật lao động hiện hành và theo quy định của Công ty'', ''Xét duyệt tăng lương và thưởng mỗi năm theo hiệu quả công việc và năng lực của nhân viên'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (776, 3, 3, 'Nhân Viên Kinh Doanh/ Tư Vấn / Sales (Part-Time)', 'Chủ động tìm kiếm và kết nối với học viên tiềm năng qua các kênh trực tiếp và online. Tư vấn, giới thiệu các khóa học lập trình game Unity cho học viên. Trực fanpage, trả lời tin nhắn, giải đáp thắc mắc và thuyết phục học viên đăng ký. Hướng dẫn học viên hoàn tất thủ tục đăng ký khóa học.', 'Độ tuổi: Từ 20 tuổi trở lên. Có laptop cá nhân. Năng động, trung thực, có tinh thần trách nhiệm và kỹ năng giao tiếp tốt. Yêu thích lĩnh vực tư vấn, giáo dục, đặc biệt là công nghệ và game (là một lợi thế).
Kỹ năng chuyên môn: [''Word'', ''Excel'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Năng động'', ''Trung thực'', ''Tinh thần trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Lương cứng: 25.000đ/giờ – Không phụ thuộc doanh số'', ''Được xác nhận thực tập nếu là sinh viên'', ''Môi trường trẻ trung, năng động, nhiều cơ hội học hỏi về ngành Game và CNTT'', ''Tham gia các hoạt động nội bộ: teambuilding, du lịch, nghỉ mát cùng công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (777, 7, 3, 'Thực Tập Sinh Kinh Doanh', 'Nhiệm vụ chính (70%): Tư vấn, chăm sóc học viên dựa trên warm-data công ty cung cấp. Chủ động tìm kiếm khách hàng/học viên tiềm năng trên các nền tảng mạng xã hội và các nguồn hội nhóm, fanpage, website. Chăm sóc, hỗ trợ, giải đáp thắc mắc của khách hàng xuyên suốt quá trình học tại trung tâm. Công việc liên quan: (30%) Hỗ trợ đón khách và tư vấn trực tiếp tại trung tâm. Nắm rõ thông tin các khóa học Tiếng Anh và gọi điện tư vấn khách hàng qua điện thoại về khóa học. Nhập liệu và quản lý data khách hàng qua phần mềm quản lý.', '1. Chân dung ứng viên: Học vấn: sinh viên năm cuối, chuẩn bị ra trường, mong muốn trau dồi các kỹ năng mềm, kiến thức chuyên môn và được làm việc trong môi trường chuyên nghiệp, năng động để có thể thỏa sức sáng. KHÔNG YÊU CẦU KINH NGHIỆM, được đào tạo bài bản. Có kinh nghiệm tư vấn, telesales, chăm sóc khách, kinh doanh... là một lợi thế. 2. Yêu cầu khác: Có laptop cá nhân. Tinh thần cầu tiến, sẵn sàng học hỏi cái mới, không ngại thay đổi. Nhiệt tình, năng động.
Kỹ năng chuyên môn: [''sử dụng laptop'']
Kỹ năng mềm: [''tinh thần cầu tiến'', ''sẵn sàng học hỏi'', ''nhiệt tình'', ''năng động'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '6.0 - 15.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''lương cứng + phụ cấp + thưởng'', ''nghỉ lễ theo lịch quốc gia'', ''đào tạo nội bộ'', ''team building'', ''thưởng theo KPIs'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (778, 8, 3, 'Giảng Viên Ielts', 'Giảng dạy IELTS trực tuyến qua một trong các nền tảng: Zoom. Giảng dạy chuyên sâu 4 kỹ năng của bài thi IELTS theo mục tiêu đề ra của học viên. Giảng dạy dựa theo giáo trình được biên soạn bởi Hệ thống luyện thi IELTS LangGo. Tham gia đề xuất, cải tiến và phát triển chương trình giảng dạy, phương pháp giảng dạy, ... Tham gia đào tạo, huấn luyện trong toàn bộ quá trình làm việc.', 'IELTS 8.0+ (Speaking 7.0+). Có trách nhiệm, nghiêm túc tham gia giảng dạy tại trung tâm cũng như trong quá trình đào tạo. Yêu thích công việc chia sẻ, đào tạo & phát triển con người. Khả năng giao tiếp tốt và khuyến khích học viên nói tiếng Anh. Có máy tính cá nhân, tham gia quá trình huấn luyện để đảm bảo yêu cầu.
Kỹ năng chuyên môn: [''IELTS 8.0+ (Speaking 7.0+)'']
Kỹ năng mềm: [''Có trách nhiệm'', ''Nghiêm túc'', ''Yêu thích chia sẻ'', ''Khả năng giao tiếp tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 25000000.00, '15.0 - 25.0 triệu', 'Thứ 2 - Thứ 7 (từ 17:45 đến 19:45), Thứ 2 - Thứ 7 (từ 20:00 đến 22:00)', '[''Lương giảng dạy theo giờ (420.000 – 800.000đ/ buổi)'', ''Hỗ trợ phụ cấp chấm bài'', ''Thưởng lớp kiểu mẫu'', ''Tham gia chương trình đào tạo Giảng viên chuyên nghiệp'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (779, 9, 3, 'Giảng Viên IELTS Offline Part-Time', 'Giảng dạy chuyên sâu 4 kỹ năng của bài thi IELTS theo mục tiêu đề ra của học viên. Giảng dạy dựa theo giáo trình được biên soạn bởi Hệ thống luyện thi IELTS LangGo. Nhận lớp theo sắp xếp của nhân viên Điều phối Giảng viên. Tham gia đề xuất, cải tiến và phát triển chương trình giảng dạy, phương pháp giảng dạy, ... Tham gia đào tạo, huấn luyện trong toàn bộ quá trình làm việc. Chăm sóc học viên trong suốt quá trình trước, trong và sau học tập. Gửi báo cáo đánh giá lớp học cho Ban chuyên môn định kỳ theo yêu cầu.', 'Chứng chỉ IELTS Academic overall 8.0+, S + R + L >=7.0, W>=6.5. Ưu tiên ứng viên đã từng đi giảng dạy/có kinh nghiệm (không yêu cầu kinh nghiệm giảng dạy về IELTS) hoặc chứng chỉ đào tạo. Yêu thích công việc chia sẻ, đào tạo & phát triển con người. Khả năng giao tiếp tốt và khuyến khích học viên nói tiếng Anh. Có trách nhiệm với công việc. Tâm huyết, có tinh thần học hỏi và phát triển bản thân, gắn bó và yêu thích sự đổi mới sáng tạo. Nhanh nhẹn, chủ động.
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Có trách nhiệm với công việc'', ''Tâm huyết'', ''Có tinh thần học hỏi và phát triển bản thân'', ''Nhanh nhẹn'', ''Chủ động'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 30000000.00, '15.0 - 30.0 triệu', '2 ca dạy vào buổi tối: Ca 1: 17h45 - 19h45, Ca 2: 20h - 22h', '[''Được cung cấp 100% tài liệu giảng dạy đã được chuẩn hóa'', ''Tham gia chương trình đào tạo Giảng viên chuyên nghiệp theo phương pháp NLP và ELC trong 2-4 tuần ngay khi nhận việc'', ''Thưởng theo KPIs, thưởng tết và phúc lợi theo cơ chế/quy định của công ty'', ''Được review năng lực và đề xuất thay đổi thu nhập mỗi buổi dạy theo thâm niên, phân bậc Giảng viên'', ''Được làm việc trong môi trường trẻ trung, năng động, sáng tạo'', ''Gói coaching phát triển năng lực (Gói đào tạo với tổng trị giá 100.000.000 VNĐ)'', ''Gói chính sách đào tạo thuộc HBR Holdings, miễn giảm học phí nâng cao năng lực'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (780, 10, 3, 'Operations Intern - Thực Tập Sinh Vận Hành', 'Công tác vận hành giáo vụ và lớp học. Chuẩn bị tài liệu giảng dạy hằng ngày: in ấn, sắp xếp tài liệu,.... Hỗ trợ công tác xếp lớp, mở lớp và quản lý dữ liệu lớp học trên các nền tảng quản lý như: Dashboard, các file Tracking,.... Quản lý hồ sơ học viên và tài khoản học tập; Hỗ trợ quản lý và tổ chức công tác IELTS Final Test định kỳ; Quản lý phòng học, cơ sở vật chất, thiết bị giảng dạy; kiểm tra phòng học thường xuyên để đảm bảo không gian học tập vào các khung thời gian đã quy định; Quản lý chuyên cần: lên danh sách học viên, kiểm tra và cập nhật chuyên cần hằng ngày. Hỗ trợ Event: Thực hiện khảo sát các trung tâm giảng dạy Anh ngữ và lập báo cáo nghiên cứu thị trường theo yêu cầu của Ban Giám đốc; Tham gia tổ chức các sự kiện Activation quảng bá thương hiệu IELTS CITY theo chiến lược Marketing của Ban Giám đốc; Hỗ trợ bộ phận Marketing chia sẻ, bình luận và đăng bài quảng bá thương hiệu và khoá học IELTS trên các cộng đồng học tiếng Anh trên mạng xã hội.', 'Sinh viên các trường Đại học, Cao đẳng chuyên ngành Quản trị Kinh doanh, Quản trị nhân lực và Tiếng anh; Kĩ năng giao tiếp khá; Kĩ năng thuyết phục; Nhanh nhẹn, hoạt bát, biết lắng nghe, giọng nói dễ nghe; Thời gian thực tập tại công ty ít nhất 3 buổi/ tuần; Giao tiếp Tiếng anh khá là một lợi thế.
Kỹ năng chuyên môn: [''Microsoft Office (Excel, Word, PowerPoint)'']
Kỹ năng mềm: [''Kĩ năng giao tiếp'', ''Kĩ năng thuyết phục'', ''Nhanh nhẹn'', ''Hoạt bát'', ''Biết lắng nghe'', ''Giọng nói dễ nghe'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ít nhất 3 buổi/ tuần', '[''Hỗ trợ dấu mộc thực tập'', ''Thực tập trong môi trường chuyên nghiệp'', ''Được training, hướng dẫn công việc cụ thể chi tiết'', ''Được cọ xát với những công việc, tình huống thực tế'', ''Trải nghiệm môi trường làm việc Tiếng anh'', ''Hoàn thiện các kĩ năng mềm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (781, 2, 3, 'Giáo Viên Tiếng Anh', 'Giảng dạy Tiếng Anh cho học sinh cấp 1-2-3 theo Giáo trình của Trung tâm. Soạn bài bổ sung thêm theo chương trình học của lớp đang phụ trách. Chăm sóc học sinh tận tình và đánh giá tiến bộ của học sinh trong suốt khoá học.', 'Trình độ chuyên môn: Có chuyên môn Tiếng Anh tốt; ưu tiên ứng viên có nghiệp vụ sư phạm/ kinh nghiệm giảng dạy, có chứng chỉ Tiếng Anh. Phát âm chuẩn, ngữ điệu tự nhiên, có cá tính riêng hiệu quả trong giảng dạy. Kỹ năng giao tiếp, kỹ năng giải quyết vấn đề và kỹ năng truyền đạt tốt. Nhiệt huyết, tận tâm, yêu thích công việc giảng dạy. Vui vẻ, linh hoạt, cởi mở và ham học hỏi.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng giải quyết vấn đề'', ''Kỹ năng truyền đạt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 07:30 đến 19:30)', '[''Thu nhập ổn định'', ''Công việc lâu dài, ổn định, chế độ phúc lợi tốt'', ''Tham gia BHYT, BHXH'', ''Có review lương định kì'', ''Được đào tạo, nâng cao kỹ năng giảng dạy'', ''Môi trường làm việc chuẩn chỉ, thân thiện, vui vẻ'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (782, 3, 3, 'Trợ Giảng Dạy Đàn Piano (Part-Time)', 'Hỗ trợ giảng viên đứng lớp để quan sát lớp học, viết bảng, chuẩn bị và sắp xếp giáo án. Quan tâm, theo dõi quá trình học tập - luyện đàn của học viên. Các việc khác theo hoạt động của trung tâm và sự hướng dẫn giáo viên đứng lớp. Theo dõi tình hình tiến bộ của học viên, đưa ra các biện pháp cải thiện tốt hơn cho học viên.', 'Từ 20 tuổi trở lên. Có đam mê và định hướng phát triển trong lĩnh vực Piano (ưu tiên các hồ sơ có bằng cấp/ chứng chỉ liên quan). Tự tin khả năng đánh Piano, thị tấu, đọc sheet nhạc,… (ưu tiên các hồ sơ có kinh nghiệm biểu diễn trên sân khấu). Được hướng dẫn về chuyên môn và quy trình làm việc cụ thể. Ưu tiên ứng viên đã từng là giáo viên/trợ giảng dạy đàn Piano với đa dạng đối tượng (Người lớn, trẻ em) với các hình thức lớp 1-1/Nhóm tại các Trung tâm/Tại nhà/Nhà thờ.
Kỹ năng chuyên môn: [''Đánh Piano'', ''Thị tấu'', ''Đọc sheet nhạc'']
Kỹ năng mềm: [''Kiên nhẫn'', ''Khả năng truyền đạt kiến thức'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Đăng ký tối thiểu 4 ca/tuần', '[''Thử việc 100% lương'', ''Phụ cấp tiền gửi xe 100%'', ''Được hỗ trợ hướng dẫn chuyên môn'', ''Được đào tạo từ trợ giảng trở thành giáo viên chính thức'', ''Thưởng Lễ, Tết theo chính sách của Công ty'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (783, 7, 3, 'Giáo Viên Piano Dạy Học Thử (Part-Time)', 'Dạy các lớp học thử cho học viên mới (tối thiểu 1 học viên, tối đa 4 học viên/lớp). Phối hợp xếp lịch học thử cùng với nhân sự nội bộ. Đánh giá buổi học thử cho Học viên (sẽ được đào tạo để đánh giá). Các công tác khác theo sự phân công của Phụ trách phòng.', 'Tự tin về khả năng đánh đàn, biểu diễn Piano và có khả năng quan sát. Có bằng cấp/chứng chỉ liên quan là một lợi thế. Ưu tiên ứng viên có kinh nghiệm giảng dạy Piano với đa dạng hình thức lớp và đối tượng hoặc có kinh nghiệm biểu diễn tại nhà thờ, sân khấu.
Kỹ năng chuyên môn: [''Đánh đàn'', ''Biểu diễn Piano'']
Kỹ năng mềm: [''Tự tin'', ''Khả năng quan sát'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.5 - 5.0 triệu', 'Đăng ký linh động tối thiểu 4 ca/tuần', '[''Thử việc 100% Lương'', ''Phụ cấp tiền gửi xe 100%'', ''Được hỗ trợ hướng dẫn chuyên môn'', ''Được đào tạo từ nhân viên part-time thành nhân viên chính thức'', ''Cơ hội thăng tiến'', ''Thưởng Lễ, Tết'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (784, 8, 3, 'Giáo Viên Piano (Part-Time)', 'Vận hành và giảng dạy các lớp Piano Sunny Days với giáo trình tại trung tâm. Theo sát, nắm bắt tiến trình và trình độ của từng học viên giảng dạy, lên giáo án giảng dạy phù hợp. Theo dõi tình hình tiến bộ của học viên và đưa ra các biện pháp cải thiện tốt hơn cho học viên. Các việc khác theo hoạt động của trung tâm dưới sự điều động của Quản lý trực tiếp.', 'Từ 20 tuổi trở lên, có kinh nghiệm giảng dạy từ 6 tháng đến 1 năm. Có đam mê và định hướng phát triển trong lĩnh vực Piano (ưu tiên các hồ sơ có bằng cấp/ chứng chỉ liên quan). Từng là giáo viên dạy đàn Piano với đa dạng đối tượng (Người lớn, trẻ em) với các hình thức lớp 1-1/Nhóm tại các Trung tâm/Tại nhà/Nhà thờ.
Kỹ năng chuyên môn: [''Giảng dạy Piano'']
Kỹ năng mềm: [''Giao tiếp'', ''Theo dõi tiến độ học viên'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.5 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 17:00 đến 21:00), Thứ 7 - Chủ nhật (từ 08:00 đến 20:00)', '[''Thử việc 100% lương'', ''Phụ cấp tiền gửi xe 100%'', ''Được đào tạo từ nhân viên part-time trở thành nhân viên full-time'', ''Thưởng Lễ, Tết theo chính sách của Công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (785, 9, 3, 'Nhân Viên Tư Vấn Tuyển Sinh', '1. Tư vấn - Telesale ● Gọi điện chăm sóc khách hàng đã để lại thông tin (messenger, web, landing page...) ● Tư vấn các khóa học nội trú, bán trú, kid summer... theo nhu cầu (Online/Offline). ● Đặt lịch học thử/trải nghiệm cho khách và check lịch khách tham gia. ● Theo dõi trạng thái khách từng giai đoạn: đã gọi – đã booking – đã học thử – chốt. Cập nhật tình trạng khách hàng ngày vào file báo cáo theo yêu cầu. 2. Chăm sóc khách hàng tại cơ sở ● Hỗ trợ khách khi đến tham quan, học thử, check-in. ● Phối hợp với bộ phận học vụ, marketing, quản lý nhà để xử lý các phản hồi, phát sinh. ● Giải đáp các thắc mắc cơ bản về chương trình, quy định học. ● Gửi báo giá, thông tin ưu đãi cho khách. 3. Theo dõi & báo cáo ● Cập nhật tình trạng khách hàng lên hệ thống (Google Sheet, CRM). ● Báo cáo số lượng cuộc gọi, số khách chốt mỗi ngày/tuần. ● Đề xuất cải tiến quy trình chăm sóc và nâng cao trải nghiệm khách hàng.', '● Thời gian làm việc trong ngày: 17h30 - 21h30 ● Thời gian làm việc trong tháng: Từ thứ Hai đến thứ 7 (Nghỉ các ngày chủ nhật trong tháng và các ngày Lễ, Tết) ● Kinh nghiệm: Có kinh nghiệm Telesale, CSKH, tư vấn từ 1 năm là một lợi thế ● Kỹ năng bắt buộc: - Kỹ năng giao tiếp - Giọng nói dễ nghe, tự tin trò chuyện qua điện thoại - Biết sử dụng công cụ làm việc cơ bản: Google Sheet, CRM ● Tố chất cá nhân: - Cầu tiến, có trách nhiệm, trung thực- Chịu được áp lực và sẵn sàng học hỏi ● Sẵn sàng làm các ngày nghỉ lễ, Tết nếu có yêu cầu
Kỹ năng chuyên môn: [''Google Sheet'', ''CRM'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Giọng nói dễ nghe'', ''Tự tin trò chuyện qua điện thoại'', ''Cầu tiến'', ''Có trách nhiệm'', ''Trung thực'', ''Chịu được áp lực'', ''Sẵn sàng học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 12000000.00, '8.0 - 12.0 triệu', '17h30 - 21h30, từ thứ Hai đến thứ Bảy', '[''Bảo hiểm xã hội'', ''Thưởng tháng 13'', ''Du lịch hàng năm'', ''Thưởng hiệu quả làm việc'', ''Hỗ trợ học tiếng Anh giao tiếp với người nước ngoài 2 buổi/1 tuần'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (786, 10, 3, 'Giáo Viên Tiếng Anh Trẻ Em', '- Giảng dạy tiếng Anh kèm 1-1 với sỹ số từ 5-7 học sinh/ca - Quay video test định kì để gửi phụ huynh - Làm báo cáo tình hình học tập hàng tháng - Giúp đỡ và quan tâm đến các học viên. - Tham gia vào quá trình đánh giá kiểm tra việc học tập trên lớp của học viên. - Thiết kế thêm các dạng bài tập nâng cao/bổ trợ cho các học sinh cần luyện thêm.', '- Tốt nghiệp chuyên ngành tiếng Anh. - Giao tiếp tiếng Anh thành thạo. - Có khả năng giao tiếp và kết nối tư vấn phụ huynh học sinh. - Yêu trẻ và nhiệt tình với việc dạy học. - Thái độ làm việc tích cực, có tinh thần ham học hỏi. - Ưu tiên ứng viên có kinh nghiệm, và có bằng cấp chứng chỉ quốc tế TOIEC > 700, IELTS > 6.5, TOEFL IBT > 80 - Ưu tiên ứng viên có chứng chỉ TESOL.
Kỹ năng chuyên môn: [''Giao tiếp tiếng Anh thành thạo'']
Kỹ năng mềm: [''Có khả năng giao tiếp và kết nối tư vấn phụ huynh học sinh'', ''Yêu trẻ và nhiệt tình với việc dạy học'', ''Thái độ làm việc tích cực'', ''Có tinh thần ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', '5-9 PM từ thứ 2 đến thứ 7', '[''Bảo hiểm xã hội'', ''Team building'', ''Du lịch hàng năm'', ''Thưởng hiệu quả làm việc'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (787, 2, 3, 'Giáo viên toán cấp A', 'Cung cấp các bài học chất lượng cao phù hợp với các mục tiêu chương trình học và học tập của tổ chức. Phát triển kế hoạch bài học, tài liệu giảng dạy và phương pháp đánh giá để tăng cường học tập của học sinh. Đánh giá sự tiến bộ của học sinh và cung cấp phản hồi mang tính xây dựng. Foster một môi trường học tập hấp dẫn và toàn diện. Luôn cập nhật về các phương pháp giảng dạy mới và xu hướng giáo dục.', '1. B.Ed/M.Ed in relevant field or BA/MA in relevant field with professional teaching qualification/license 2. Minimum 2 years of teaching experience; 3. Fluent level English speaker (minimum C1 fluency - evidence required for non-natives).', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Competitive salary, negotiable based on qualifications and experience'', ''Meals provided: The school supports two meals per day (breakfast and lunch)'', ''13th-month salary bonus'', ''Paid leave according to the school’s schedule'', ''Social, health, and unemployment insurance in compliance with regulations'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (788, 3, 3, 'Cộng Tác Viên Telesale', 'Gọi điện chăm sóc khách hàng. Tiếp nhận và giải đáp thắc mắc của học viên và phụ huynh (nếu có). Hỗ trợ các chương trình sự kiện của công ty.', 'Sinh viên các trường Cao đẳng, Đại học. Giao tiếp tốt, Nhanh nhẹn, Có trách nhiệm & Đam mê trong Công việc; Ưu tiên sinh viên có học lực Khá và nắm vững các kiến thức căn bản của Chuyên ngành mình theo học.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Nhanh nhẹn'', ''Có trách nhiệm'', ''Đam mê trong Công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được hướng dẫn Chi tiết khi tham gia Công việc thực tế'', ''Phụ cấp hàng tháng & Thưởng theo Kết quả hoàn thành Công việc được giao'', ''Xác nhận thực tập, Tạo điều kiện & Hỗ trợ đồ án'', ''Cơ hội tham gia tập huấn tại Thủ đô Hà Nội'', ''Cơ hội trở thành Cán bộ chính thức sau khi Tốt nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (789, 7, 3, 'Nhân Viên Telesales Part Time', 'Thực hiện các cuộc gọi tư vấn khơi gợi nhu cầu học Tiếng Anh với khách hàng tiềm năng từ data có sẵn. Thiết lập danh sách khách hàng tiềm năng. Đảm nhiệm một số công việc khác khi được yêu cầu.', 'Có thể làm được ca chiều hoặc tối (Từ 13h30 - 20h00). Đăng ký ca linh hoạt từ 3 tiếng trở lên. Ứng viên là sinh viên năm 3,4 hoặc đã tốt nghiệp. Ưu tiên ứng viên có kinh nghiệm ở mảng giáo dục. Giao tiếp tốt, có khả năng gắn kết mọi người. Có tinh thần làm việc nhóm.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Có khả năng gắn kết mọi người'', ''Có tinh thần làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Linh hoạt theo ca, ưu tiên ca chiều/tối (4h/ngày)', '[''Mức lương 35k/giờ'', ''Được làm việc trong môi trường giáo dục, chuyên nghiệp, uy tín hàng đầu tại Hà Nội'', ''Tham gia chương trình đào tạo từ các chuyên gia giáo dục hàng đầu'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (790, 8, 3, 'Giảng Viên Truyền Thông & Tổ Chức Sự Kiện', 'Giảng dạy các môn học trong chương trình chuyên ngành Truyền thông và tổ chức sự kiện tại FPT Polytechnic dưới sự phân công của chủ nhiệm bộ môn. Thực hiện các công việc chuyên môn khác theo phân công của bộ môn.', 'Tốt nghiệp đại học trở lên chuyên ngành: Truyền Thông, Báo chí & truyền thông, PR – Marketing, Quan hệ công chúng, Quản trị sự kiện, hoặc các chuyên ngành liên quan. Yêu thích, tận tâm, nhiệt huyết với công việc giảng dạy. Ưu tiên ứng viên có kinh nghiệm làm việc trong dự án thực tế hoặc giảng dạy tại các Trường Cao đẳng/Đại học. Có kỹ năng sư phạm, giao tiếp tốt. Nhiệt tình, tâm huyết, thích làm việc với sinh viên.
Kỹ năng mềm: [''Kỹ năng sư phạm'', ''Giao tiếp tốt'', ''Nhiệt tình'', ''Tâm huyết'', ''Thích làm việc với sinh viên'']', 'PART_TIME', 'ONSITE', 'đắk lắk', 'Đắk Lắk', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường làm việc năng động, chuyên nghiệp.'', ''Có mức thu nhập hấp dẫn, cân xứng với năng lực.'', ''Có cơ hội tham gia các hoạt động đào tạo nâng cao trình độ chuyên môn.'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (791, 9, 3, 'Giáo Viên Toeic Part-Time', '– Nhận lớp giảng dạy TOEIC theo lịch của Phòng Đào tạo và giảng dạy đúng tiến độ, nội dung theo chương trình học và mục tiêu khoá học của Trung tâm. – Theo dõi tiến độ học, chấm, sửa bài tập cho học viên – Chia sẻ kiến thức tiếng Anh đến cộng đồng – Hỗ trợ các hoạt động khác của trung tâm', 'Phát âm tiếng Anh chuẩn, có chứng chỉ TOEIC 850+; Tận tâm, yêu nghề, có trách nhiệm với kết quả của học viên; Có năng lực tiếng Anh tốt và có khả năng giải đáp các vấn đề trong việc học tiếng Anh của người học; Có kỹ năng đứng lớp tốt, tự tin, truyền cảm hứng; Ưu tiên ứng viên tốt nghiệp chuyên ngành Sư Phạm Anh hoặc Ngôn Ngữ Anh có chứng chỉ nghiệp vụ sư phạm, TESOL; Ứng viên chưa có kinh nghiệm giảng dạy TOEIC sẽ được đào tạo đầu vào
Kỹ năng chuyên môn: [''Giảng Dạy Tiếng Anh'', ''Kiến Thức Về Toeic'']
Kỹ năng mềm: [''Tận tâm'', ''Có trách nhiệm với kết quả của học viên'', ''Kỹ năng đứng lớp tốt'', ''Tự tin'', ''Truyền cảm hứng'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 15000000.00, '8.0 - 15.0 triệu', 'Thứ 2 - Thứ 7 (từ 17:30 đến 21:30)', '[''Được đào tạo đầu vào bài bản'', ''Nhận feedback để nâng cao kỹ năng chuyên môn'', ''Được cung cấp giáo án, giáo trình, tài liệu'', ''Môi trường làm việc năng động, thân thiện, chuyên nghiệp và ổn định lâu dài'', ''Thưởng theo năng lực làm việc và kết quả lớp học'', ''Thưởng lễ Tết và các ngày lễ khác'', ''Tham gia các chuyến nghỉ dưỡng, team building hàng năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (792, 10, 3, 'Giáo Viên Tiếng Đức Fulltime/Partime', 'Chuẩn bị, giảng dạy các khóa học luyện thi tiếng Đức cho học viên các trình độ từ A1 đến B1. Soạn giáo án, lên kế hoạch giảng dạy theo yêu cầu các kì thi và trình độ học viên của lớp được giao. Cập nhật các tài liệu học mới nhất để giúp học viên đạt kết quả tối ưu. Kiểm tra và đánh giá học viên định kỳ theo lộ trình của trung tâm. Cung cấp phản hồi chi tiết về kết quả học tập của học viên. Tư vấn, động viên học viên trong quá trình ôn luyện, phỏng vấn. Truyền đạt kiến thức, kỹ năng học tiếng Đức, kết hợp cùng trung tâm giới thiệu về văn hóa Đức cho học viên trong quá trình giảng dạy.', 'Tốt nghiệp loại Khá trở lên các trường Đại học trong và ngoài nước chuyên ngành Ngôn ngữ Đức hoặc liên quan đến giảng dạy tiếng Đức. Có chứng chỉ tiếng Đức C1 trở lên hoặc các chứng chỉ tương đương. Có kinh nghiệm giảng dạy, luyện thi tiếng Đức các trình độ. Nhiệt tình và tinh thần trách nhiệm cao trong công việc.
Kỹ năng chuyên môn: [''Giảng dạy tiếng Đức'', ''Soạn giáo án'']
Kỹ năng mềm: [''Nhiệt tình'', ''Tinh thần trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 30000000.00, '15.0 - 30.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:30 đến 12:00)', '[''Mức lương theo thỏa thuận, hấp dẫn và xứng đáng với năng lực, kinh nghiệm'', ''Được tham gia các chương trình đào tạo nâng cao kỹ năng nghiệp vụ'', ''Thưởng và quà tặng vào các dịp lễ, Tết, sinh nhật, ngày Nhà giáo Việt Nam, 8/3, 20/10'', ''Chương trình hoạt động văn hóa đa dạng: Teambuilding, hoạt động dã ngoại, sinh nhật hàng tháng, tiệc giáng sinh, tất niên'', ''Cơ hội giao lưu, học hỏi với giáo viên và khách hàng người Đức'', ''Có cơ hội thăng tiến và ổn định lâu dài'', ''Môi trường giảng dạy chuyên nghiệp, rộng rãi, thoáng mát, cơ sở vật chất hiện đại, đầy đủ thiết bị phục vụ công tác giảng dạy'', ''Môi trường làm việc trẻ trung, năng động, cởi mở cùng sự hỗ trợ từ đồng nghiệp hay các phòng ban liên quan'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (793, 2, 3, 'Trợ Giảng Tiếng Đức', 'Trợ giảng tiếng Đức các trình độ từ A1 đến B1/B2 cho đối tượng học sinh du học nghề. Hỗ trợ các học sinh du học nghề củng cố kiến thức và làm bài tập các trình độ từ A1 đến B1 cho học viên. Kiểm tra bài tập học viên theo lộ trình của trung tâm. Truyền đạt kiến thức, kỹ năng học tiếng Đức, kết hợp giới thiệu về văn hóa Đức cho học viên trong quá trình giảng dạy.', 'Sinh viên năm 3,4 chuyên ngành Ngôn ngữ Đức hoặc liên quan đến giảng dạy tiếng Đức. Có chứng chỉ tiếng Đức B2 Goethe trở lên hoặc các chứng chỉ tương đương. Ưu tiên các bạn đã có kinh nghiệm giảng dạy. Có khả năng giao tiếp, truyền đạt tốt. Nhiệt tình, nhanh nhẹn, thân thiện, tinh thần trách nhiệm cao trong công việc.
Kỹ năng mềm: [''Có khả năng giao tiếp, truyền đạt tốt'', ''Nhiệt tình, nhanh nhẹn, thân thiện, tinh thần trách nhiệm cao trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Part-time theo thỏa thuận 2 bên; Full-time: Sáng 8h30 - 12h30, Chiều 13h30 - 17h30', '[''Lương thỏa thuận xứng đáng với năng lực'', ''Cơ hội giao lưu, học hỏi với giáo viên và khách hàng người Đức'', ''Môi trường làm việc trẻ trung, năng động, có cơ hội thăng tiến và ổn định lâu dài'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (794, 3, 3, 'Giảng Viên Dạy Vẽ', 'Giảng dạy trực tiếp các môn vẽ tĩnh vật, đầu tượng, chân dung và môn vẽ màu cho học viên; Theo dõi quá trình luyện thi của học viên; Tư vấn môn thi, trường thi phù hợp với khả năng của học viên; Cập nhật khối thi, trường thi hàng năm.', 'Tốt nghiệp trường đại học Kiến trúc, Mỹ thuật, Sư phạm vẽ; Yêu thích công việc giảng dạy; Đã có kinh nghiệm giảng dạy; Kỹ năng vẽ tay tốt; Soạn thảo giáo án, chuẩn bị tư liệu giảng dạy; Khả năng giao tiếp tốt, có tinh thần trách nhiệm, nhiệt huyết với học viên.
Kỹ năng chuyên môn: [''Kỹ năng vẽ tay'', ''Soạn thảo giáo án'', ''Chuẩn bị tư liệu giảng dạy'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Tinh thần trách nhiệm'', ''Nhiệt huyết với học viên'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Lịch giảng dạy cố định', '[''Được làm việc trong môi trường uy tín, chất lượng'', ''Ăn sáng và ăn trưa tại trung tâm'', ''Nghỉ lễ, tết theo luật quy định'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (795, 7, 3, 'Giáo Viên Tiếng Anh Cho Người Hàn Part-Time', 'Lập kế hoạch giảng dạy, đánh giá hiệu quả bài học dựa trên tài liệu và giáo trình được SIMPace cung cấp. Chuẩn bị bài học bằng cách sử dụng slides, phiếu ôn tập và video phù hợp với giáo trình và nội dung bài học. Theo dõi quá trình học tập, sự tiến bộ và hướng dẫn khi học viên gặp vấn đề hoặc khó khăn trong lớp. Trực tiếp giảng dạy tiếng Anh bằng cách sử dụng thiết bị giáo dục, thao tác, đạo cụ và các phương tiện hỗ trợ học tập khác theo sự phân công và sắp xếp của Phòng học thuật. Chấm điểm, kiểm tra bài tập về nhà và theo dõi tình hình học tập của học viên. Tham gia xây dựng chương trình giảng dạy bằng cách cung cấp phản hồi cho quản lý trực tiếp về tài liệu, quy trình và hoạt động giảng dạy. Tham dự các cuộc họp nhóm và hội thảo để phát triển kỹ năng.', 'Tốt nghiệp chuyên ngành sư phạm tiếng Hàn, biên phiên dịch tiếng Hàn, ngôn ngữ Hàn,... tại các trường cao đẳng, đại học chuyên về ngoại ngữ. Chứng chỉ tiếng Hàn tối thiểu TOPIK 5. Tiếng anh giao tiếp.
Kỹ năng chuyên môn: [''Chứng chỉ tiếng Hàn tối thiểu TOPIK 5'', ''Tiếng anh giao tiếp'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng tạo lập bài giảng'']', 'PART_TIME', 'ONSITE', 'hà nội, bắc ninh', 'Hà Nội', 'MONTHLY', 30000000.00, '18.0 - 30.0 triệu', 'Làm theo lịch thi đã có sẵn (bao gồm cuối tuần nếu có)', '[''Môi trường làm việc giáo dục, tích cực, năng động, trẻ trung, nhân văn'', ''Được tham gia các nội dung hướng dẫn/ đào tạo, hội họp định kỳ góp phần nâng cao kĩ năng nghiệp vụ'', ''Các phúc lợi khác theo quy định chính sách công ty'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (796, 8, 3, 'Giáo Viên Vật Lý (Physics Teacher) Bằng Tiếng Anh', '- Dạy Vật Lý (Physics Cambridge) bằng tiếng Anh cho học sinh bậc trung học cơ sở (lớp 6-8) và/hoặc bậc Trung học phổ thông (9-12) Chương trình quốc tế Cambridge theo phân phối chương trình được phân công. - Trực tiếp giảng dạy theo tiết (bằng tiếng Anh và tiếng Việt) theo phân công và linh hoạt theo thời khóa biểu phù hợp với lịch của giảng viên. - Chuẩn bị phân phối chương trình môn Vật Lý (Physics Cambridge) của các lớp đầu năm học (bao gồm long term, medium term/syllabus và short term plan của môn học). - Chuẩn bị và lưu trữ theo quy định giáo án môn Vật Lý (Physics Cambridge) (bao gồm giáo án, slide học tập, work sheet…), bảo đảm bộ giáo án đảm đúng phân phối chương trình, đúng năng lực học sinh, có điều chỉnh phù hợp yêu cầu học tập thực tế từng lớp học; - Chuẩn bị Unit Test môn Vật Lý (Physics Cambridge). - Chuẩn bị đề kiểm tra môn Toán (Mathematics) trong năm học bao gồm 04 đề (bao gồm đề dự phòng): giữa kỳ và cuối kỳ học kỳ 1 và học kỳ 2; - Tutor/phụ đạo cho học sinh 1 buổi/lớp/tuần (mỗi buổi khoảng 30’ – 45’); - Theo dõi tình hình học tập, chấm chữa bài tập, làm báo cáo định kì về tình hình học tập của học sinh theo mẫu có sẵn. - Quản lý học sinh trong các hoạt động giáo dục - Full time: ban ngày (buổi sáng và buổi chiều), theo tiết được phân công và theo lịch cụ thể và linh hoạt với lịch của ứng cử viên. - Nội dung cụ thể khác sẽ được trao đổi và giải đáp khi phỏng vấn.', '- Tiến sĩ/Thạc sĩ ngành Vật Lý hoặc các ngành khác có liên quan. - Có kinh nghiệm học tập, làm việc ở nước ngoài là một lợi thế. - Năng lực ngôn ngữ tiếng Anh phù hợp giảng dạy, tương đương IELTS 6.5 trở lên; - Kinh nghiệm giảng dạy là lợi thế; - Tận tâm với học sinh và nghề dạy học. - Có kinh nghiệm đứng lớp là một lợi thế.
Kỹ năng chuyên môn: [''Năng lực ngôn ngữ tiếng Anh tương đương IELTS 6.5 trở lên'']
Kỹ năng mềm: [''Tận tâm với học sinh và nghề dạy học'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 30000000.00, '15.0 - 30.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Bảo hiểm y tế'', ''Bảo hiểm thất nghiệp'', ''Bảo hiểm xã hội'', ''Khám sức khoẻ định kỳ'', ''Thưởng học kì'', ''Thưởng Tết'', ''Hỗ trợ chi phí đi lại'', ''Ăn trưa'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (797, 9, 3, 'Giáo Viên Tiếng Anh', 'Giảng dạy theo chương trình phân phối của trung tâm với giáo trình và tài liệu được cung cấp sẵn. Tuy nhiên giáo viên có thể linh hoạt với điều kiện đảm bảo được chất lượng đầu ra của học viên. Báo cáo và nhận xét học sinh sau mỗi buổi học; tiến độ học tập từng khoá học; Lập kế hoạch và phát triển các phương pháp học tập nhằm nâng cao chất lượng giảng dạy. Xây dựng hình ảnh giáo viên nhiệt tình, truyền cảm hứng học tập cho học sinh; Phối hợp với đội ngũ học vụ để đảm bảo chất lượng lớp học.', 'Tốt nghiệp cao đẳng, đại học chuyên ngành sư phạm tiếng Anh, hoặc các nghành có liên quan tiếng Anh. Có chứng chỉ giảng dạy (đối với ứng viên học ngành ngoài sư phạm). Ưu tiên ứng viên có bằng IELTS từ 6.5 trở lên.
Kỹ năng chuyên môn: [''Kỹ năng sư phạm'', ''Kiến thức chuyên môn về tiếng Anh (ngữ pháp, từ vựng, ngữ âm)'', ''Kỹ năng soạn giáo án'', ''Kỹ năng quản lý lớp học'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tiếng Anh lưu loát'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Môi trường làm việc chuyên nghiệp, năng động'', ''Cơ hội học hỏi, phát triển kỹ năng và thăng tiến trong công việc'', ''Được tham gia các khóa đào tạo về lĩnh vực trung tâm tiếng Anh'', ''Công việc ổn định, lâu dài'', ''Môi trường làm việc thân thiện, thoải mái'', ''Bảo hiểm xã hội'', ''Team building'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (798, 10, 3, 'Thực Tập Sinh Học Thuật', 'Nhập liệu giáo trình, sửa giáo án, slide bài giảng. Nghiên cứu học liệu (đề thi, giáo trình). Nhập liệu học liệu lên trang điện tử, ứng dụng của công ty. In ấn hồ sơ tài liệu. Hoàn thành các công việc khác theo yêu cầu của bộ phận Học thuật khi cần.', 'Có đam mê, yêu thích với công việc giảng dạy và nghiên cứu học thuật. Ưu tiên những bạn định hướng sư phạm chuyên nghiệp. Ưu tiên các bạn sinh viên mới ra trường, đang chờ bằng.
Kỹ năng mềm: [''Làm việc nhóm'', ''Giao tiếp tốt'', ''Khả năng giải quyết vấn đề'', ''Chịu được áp lực công việc'', ''Khả Năng Học Hỏi Nhanh'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:00), Thứ 7 (từ 08:30 đến 12:30)', '[''Thu nhập hấp dẫn'', ''Thời gian làm việc linh hoạt'', ''Môi trường làm việc năng động, trẻ trung kích thích sáng tạo'', ''Có lộ trình thăng tiến rõ ràng lên nhân viên chính thức'', ''Được tham gia các hoạt động của công ty: Team Building, Tea Break'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (799, 2, 3, 'Giáo Viên Cờ Vua Part/Full-Time', 'Giảng dạy cờ vua cho các em học viên từ 4 - 12 tuổi, giảng dạy theo chương trình và giáo trình trung tâm đưa ra. Quản lý lớp, điểm danh học viên, cập nhật nội dung bài học của học viên và nhận xét, đánh giá kết quả test cuối khóa của học viên. Kiểm tra đầu vào của học viên. Phối hợp góp ý và trao đổi về chuyên môn với Bộ phận chuyên môn. Kiểm tra tình hình tiến bộ của học viên hàng tháng và báo cáo tiến độ học tập của học viên cho Bộ phận đào tạo 1 lần/ tháng. Tham gia phối hợp và hỗ trợ các sự kiện của Trung tâm (Online & Offline). Tham gia các buổi đào tạo, họp chuyên môn của trung tâm.', 'Biết chơi Cờ vua và có các bằng cấp liên quan đến Cờ vua là một lợi thế. Độc lập và chủ động, thái độ và tư duy tích cực trong công việc. Thương yêu trẻ, thích công việc giảng dạy, tự tin, nhiệt huyết và trung thực. Có chuyên môn, Kỹ năng sư phạm, Kỹ năng giao tiếp tốt (Sẽ được đào tạo thêm khi nhận việc). Có phương tiện đi lại.
Kỹ năng chuyên môn: [''Kiến thức về Cờ vua'', ''Kỹ năng sư phạm'', ''Kỹ năng giao tiếp'']
Kỹ năng mềm: [''Độc lập'', ''Chủ động'', ''Thái độ tích cực'', ''Yêu trẻ'', ''Nhiệt huyết'', ''Trung thực'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 5 (từ 16:00 đến 20:30), Thứ 7 - Chủ nhật (từ 08:00 đến 17:30)', '[''Được đào tạo từ đầu'', ''Cơ hội giao lưu học hỏi'', ''Tham gia teambuilding và đi du lịch hàng năm'', ''Lương tháng 13'', ''Thưởng cuối năm'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (800, 3, 3, 'Giáo Viên Chương Trình Tư Duy Tài Chính', 'Trực tiếp giảng dạy chương trình Tư duy Tài chính dành cho học sinh theo khung nội dung của MDJ. Tổ chức các tiết học sinh động, tích hợp kể chuyện, trò chơi, trải nghiệm, hoạt động nhóm... để học sinh tiếp cận kiến thức tài chính một cách thực tế và dễ hiểu. Tham gia xây dựng giáo án. Theo dõi, đánh giá sự tiến bộ của học sinh và phối hợp với phụ huynh. Tham dự các buổi đào tạo nội bộ về chuyên môn, kỹ năng giảng dạy, và cập nhật nội dung chương trình. Có thể hỗ trợ tổ chức sự kiện trải nghiệm, hội thảo phụ huynh, các dự án giáo dục cộng đồng.', 'Tốt nghiệp đại học, từ các khối ngành: Tài chính, Kinh tế, Ngân hàng, Kế toán, Quản trị kinh doanh... Ưu tiên tốt nghiệp các trường: Học viện Tài chính, ĐH Kinh tế Quốc dân, ĐH Ngoại thương, v.v. Có kinh nghiệm thực tế trong lĩnh vực tài chính, như: Làm việc tại quỹ đầu tư, tổ chức tài chính, công ty startup gọi vốn, hoặc từng vận hành mô hình tài chính cá nhân. Các ứng viên tốt nghiệp các ngành sư phạm hoặc các ngành liên quan đến phát triển kỹ năng sống sẽ được xem xét và đào tạo chuyên sâu về kiến thức tài chính. Yêu thích trẻ em, có sự kiên nhẫn, tinh thần giáo dục tích cực. Có kỹ năng giao tiếp, truyền đạt tốt, sẵn sàng học hỏi và làm việc theo nhóm. Ưu tiên ứng viên có định hướng gắn bó lâu dài với lĩnh vực giáo dục tài chính.
Kỹ năng chuyên môn: [''Kỹ năng giảng dạy'', ''Kỹ năng truyền đạt kiến thức'', ''Kiến thức chuyên sâu về tài chính cá nhân'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Tinh thần giáo dục tích cực'', ''Sẵn sàng học hỏi'', ''Làm việc theo nhóm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thời gian làm việc phân công theo tổ chức lớp học online hoặc offline', '[''Đào tạo bài bản miễn phí về sư phạm, tài chính và phương pháp giáo dục đổi mới'', ''Cơ hội làm việc trong môi trường sáng tạo'', ''Cấp chứng nhận đào tạo & giảng dạy sau thời gian làm việc'', ''Ưu đãi học phí cho con/em khi tham gia chương trình tại MDJ'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (801, 7, 3, 'Cố Vấn Học Tập', 'Góp phần vào phát triển kỹ năng, thói quen học tập lành mạnh cho học viên. Góp phần vào định hướng chuyên ngành, nghề nghiệp cho học viên. Đảm bảo tỷ lệ tái đăng ký hàng tháng của học viên đạt mục tiêu đề ra. Cập nhật tình hình kết quả học tập hàng tuần. Gửi báo cáo kết quả học tập hàng tháng cho học viên và phụ huynh.', 'Về trình độ: Sinh viên năm 3,4 hoặc chờ bằng. Có năng lực gia sư môn Toán/ Lý/ Hoá/ Anh. Có kinh nghiệm gia sư hoặc luyện thi đại học cho học sinh cấp 3 là một lợi thế. Có đam mê làm việc trong ngành giáo dục.
Kỹ năng chuyên môn: [''Gia sư môn Toán'', ''Gia sư môn Lý'', ''Gia sư môn Hóa'', ''Gia sư môn Anh'']
Kỹ năng mềm: [''Giao tiếp hiệu quả'', ''Kỹ Năng Lắng Nghe Tích Cực'', ''Phân Tích Nhu Cầu Học Tập'', ''Lập Kế Hoạch Học Tập'', ''Cá Nhân Hóa Động Viên'', ''Khích Lệ Học Sinh'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'T2 – CN: 16g00 – 21g00 Off 1 ngày trong tuần', '[''Mức lương cạnh tranh'', ''Quyền lợi thuế và bảo hiểm theo luật hiện hành'', ''Cơ hội học hỏi và phát triển kỹ năng Coaching'', ''Con đường thăng tiến rõ ràng'', ''Môi trường khởi nghiệp trẻ trung, năng động, sáng tạo và chuyên nghiệp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (802, 8, 3, 'Giảng Viên Digital Art Part-Time', '- Tham gia dạy các môn liên quan đến thiết kế sản phẩm đồ họa truyền thông số. - LĨNH VỰC DIGITAL ART & DESIGN - Đối tượng học: từ 6 đến 15 tuổi Lớp Cấp 1: VISUAL ART + VISUAL CREATION Lớp Cấp 2: GRAPHIC DESIGN Ai - PTS Lớp Cấp 3: VIDEO - ANIMATION - Ui/Ux', 'Yêu cầu ứng viên: • Độ tuổi: không giới hạn (Tinh thần tự giác cao) • Kinh nghiệm trong dạy hoặc truyền đạt kiến thức (đã hoặc đang dạy trong một lĩnh vực) • Ưu tiên ứng viên có kỹ năng vẽ tay hoặc minh họa. • Biên soạn giáo án và giảng dạy theo giáo trình và tài liệu của TagEdu. • Quản lý lớp học và đảm bảo kết quả học tập của học sinh. • Ưu tiên sinh viên và có kinh nghiệm trong ngành Thiết Kế Đồ Họa, Digital Art. • Nắm vững các nguyên tắc thiết kế: Màu sắc, bố cục, nguyên lý thị giác, typo... • Kỹ năng giao tiếp tự tin và trình bày trước đám đông. • Thích và hiểu tâm lý trẻ em và học sinh, tiếng Anh là một lợi thế. • Tuân thủ các quy định và cơ chế của công ty, nghiêm túc và sẵn sàng học hỏi.
Kỹ năng chuyên môn: [''Kỹ năng vẽ tay'', ''Minh họa'', ''Thiết kế đồ họa'', ''Digital Art'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tự tin'', ''Trình bày trước đám đông'', ''Quản lý lớp học'', ''Tâm lý trẻ em'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Làm việc theo ca', '[''Đào tạo chuyên sâu từ giảng viên có kinh nghiệm'', ''Cơ hội tham gia vào quản lý và đào tạo giảng viên mới'', ''Tham gia xây dựng kho tài liệu kiến thức'', ''Chế độ nghỉ phép và nghỉ lễ Tết theo quy định'', ''Tham gia BHXH, BHYT sau thử việc'', ''Phụ cấp hỗ trợ phí gửi xe, ăn trưa'', ''Tham gia các hoạt động và sự kiện do công ty tổ chức'', ''Môi trường làm việc tích cực và đầy tính nhân văn, năng động'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (803, 9, 3, 'Thực Tập Sinh Tư Vấn Tuyển Sinh', 'Gọi điện tư vấn khách hàng tiềm năng theo danh sách có sẵn. Tư vấn, ghi nhận, giải đáp thắc mắc của khách hàng về thông tin khoá đào tạo và tư vấn khoá đào tạo phù hợp. Tìm kiếm khách hàng mục tiêu trên các kênh: CafeF, Stockbiz, ssc.gov, HOSE, linked in, FB, website. Cập nhật dữ liệu khách hàng theo quy trình. Hỗ trợ tổ chức sự kiện: quà tặng, in ấn tài liệu, đón khách. Hỗ trợ hành chính: giao nhận văn thư, soạn thảo văn bản, dịch tài liệu Anh – Việt (nếu có).', 'Sinh viên Đại Học chuyên ngành Kinh Tế năm 3, năm 4 hoặc vừa tốt nghiệp. Có thể thực tập full-time tối thiểu 3 tháng trở lên. Tư duy logic, nhạy bén, sáng tạo, định hướng nghề nghiệp rõ ràng. Hoạt bát, giao tiếp tốt. Chăm chỉ và nghiêm túc trong công việc. Ưu tiên SV có kỹ năng MC, công tác Đoàn, Đội sẽ được tạo điều kiện phát huy năng khiếu.
Kỹ năng mềm: [''Tư duy logic'', ''Nhạy bén'', ''Sáng tạo'', ''Định hướng nghề nghiệp rõ ràng'', ''Hoạt bát'', ''Giao tiếp tốt'', ''Chăm chỉ'', ''Nghiêm túc trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được trải nghiệm công việc thật'', ''Được phụ cấp lương thực tập'', ''Được hỗ trợ thông tin làm bài báo cáo'', ''Được tham gia đào tạo nội bộ'', ''Được mở rộng mối quan hệ và nâng cao kỹ năng giao tiếp'', ''Có cơ hội trở thành nhân viên chính thức sau kỳ thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (804, 10, 3, 'Giáo Viên Mỹ Thuật (Thỉnh Giảng)', '1. Nhiệm vụ giảng dạy chính khóa (theo tiết) Chuẩn bị giáo án, bài giảng và tài liệu học tập theo đúng phân phối chương trình và thời khóa biểu được giao; Tổ chức các tiết dạy Mỹ thuật sinh động, sáng tạo, phù hợp với độ tuổi học sinh; Đánh giá, nhận xét kết quả học tập, sản phẩm học sinh và hỗ trợ các em hoàn thiện kỹ năng nghệ thuật theo mục tiêu môn học; Phối hợp với giáo viên chủ nhiệm và Nhà trường trong công tác quản lý, giáo dục học sinh liên quan đến bộ môn. 2. Tham gia dạy Câu lạc bộ Mỹ thuật (nếu có) Thiết kế nội dung Câu lạc bộ phù hợp với năng lực và hứng thú của học sinh theo từng nhóm tuổi; Tổ chức các buổi học Câu lạc bộ vào buổi chiều (ngoài giờ học chính khóa) nhằm phát triển năng khiếu và tư duy sáng tạo cho học sinh; Đề xuất tổ chức triển lãm sản phẩm, hoạt động mỹ thuật chủ đề theo từng tháng, từng học kỳ (nếu có). 3. Các công việc khác Tham gia một số hoạt động chuyên môn, hoạt động ngoại khóa có liên quan theo phân công; Chấp hành nghiêm túc nội quy, quy định và văn hóa làm việc của Nhà trường; Thực hiện các nhiệm vụ khác theo chỉ đạo của quản lý chuyên môn và Ban Giám hiệu.', 'Tốt nghiệp Đại học trở lên chuyên ngành Sư phạm Mỹ thuật hoặc các chuyên ngành liên quan đến Mỹ thuật, Hội họa... Nếu không có bằng sư phạm cần có chứng chỉ bồi dưỡng nghiệp vụ sư phạm theo quy định; Ưu tiên có kinh nghiệm giảng dạy Mỹ thuật tại các trường Tiểu học và THCS Có khả năng sư phạm, biết cách tổ chức giờ học sinh động, truyền cảm hứng sáng tạo cho học sinh; Linh hoạt về thời gian, có thể tham gia giảng dạy theo tiết học chính khóa theo lịch phân công của Nhà trường, và tham gia dạy Câu lạc bộ Mỹ thuật buổi chiều nếu có.
Kỹ năng mềm: [''Có khả năng sư phạm'', ''Biết cách tổ chức giờ học sinh động'', ''Truyền cảm hứng sáng tạo cho học sinh'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 07:30 đến 17:00)', '[''Chính sách ưu đãi giảm học phí 50 - 70% cho con CBGVNV'', ''Khám sức khỏe định kỳ 1 lần trên năm'', ''Hưởng đầy đủ các chế độ theo quy định của pháp luật và các chế độ phúc lợi theo Nội quy, quy chế của Trường'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (805, 2, 3, 'Thực Tập Sinh Học Vụ', 'Kiểm tra trình độ đầu vào của học viên, xếp lớp theo trình độ. Tổ chức khai giảng lớp học theo lịch sắp xếp của trung tâm. Dự giờ và kiểm soát chất lượng lớp học. Hỗ trợ xây dựng chương trình học. Điều phối, sắp xếp lịch dạy cho giáo viên. Phối hợp chăm sóc, hỗ trợ giáo viên và học viên trong quá trình học.', 'Sinh viên năm 3,4 hoặc tốt nghiệp Đại học, cao đẳng chuyên ngành Tiếng Anh. Tiếng Anh thành thạo 4 kỹ năng là 1 lợi thế. Có kỹ năng xử lý tình huống linh hoạt, khéo léo. Chăm chỉ, nhiệt tình.
Kỹ năng chuyên môn: [''Tiếng Anh thành thạo 4 kỹ năng'']
Kỹ năng mềm: [''Kỹ năng xử lý tình huống linh hoạt'', ''Chăm chỉ'', ''Nhiệt tình'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Full time hoặc partime xoay ca: Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Hỗ trợ dấu mộc thực tập'', ''Có cơ hội trở thành nhân sự chính thức sau 3-4 tháng thực tập'', ''Được đào tạo kỹ năng cơ bản và nâng cao'', ''Môi trường chuyên nghiệp, tôn trọng và tạo điều kiện phát huy giá trị cá nhân'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (806, 3, 3, 'Thực Tập Sinh Điều Phối Và Đánh Giá Giáo Viên', '- Thực hiện test tiếng Anh, phỏng vấn đội ngũ giáo viên đầu vào của AROMA. - Đào tạo giáo viên mới. Điều phối giáo viên nhận lớp. - Xây dựng, nâng cấp khung chương trình, giáo án giảng dạy. - Hỗ trợ giáo viên trong quá trình nhận lớp, xử lý vấn đề phát sinh.', '- Độ tuổi từ 19-24. - Sinh viên năm 2, 3, 4 hoặc tốt nghiệp các trường cao đẳng trở lên. - Ưu tiên: Tiếng Anh thành thạo 4 kỹ năng. Ưu tiên có chứng chỉ IELTS 6.5 trở lên hoặc văn bằng, chứng chỉ tương đương. - Tự tin, kỹ năng giao tiếp, thuyết phục tốt. - Giọng nói chuẩn, không nói ngọng. - Có kỹ năng xử lý tình huống linh hoạt, khéo léo, ngoại hình tốt là một lợi thế. - Có laptop cá nhân.
Kỹ năng chuyên môn: [''Tiếng Anh thành thạo 4 kỹ năng'', ''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Tự tin'', ''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'', ''Kỹ năng xử lý tình huống linh hoạt'', ''Ngoại hình tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Thứ 2 - thứ 6, và thứ 7 cách tuần. Full-time: Sáng 8h30’ - 12h00’, Chiều 13h30’ - 18h00’ hoặc 13h30'' - 21h30''.', '[''Hỗ trợ dấu mộc thực tập'', ''Có cơ hội trở thành nhân sự chính thức sau 3-4 tháng thực tập'', ''Được đào tạo kỹ năng cơ bản và nâng cao'', ''Môi trường chuyên nghiệp, tôn trọng và tạo điều kiện phát huy giá trị cá nhân'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (807, 7, 3, 'Giáo Viên Tiếng Anh Ielts Part-Time', 'WISE ENGLISH được thành lập với sứ mệnh giúp các bạn trẻ Việt Nam thay đổi phương pháp học tiếng Anh theo TƯ DUY NÃO BỘ (NLP) và NGÔN NGỮ để chinh phục ngôn ngữ này một cách NHANH NHẤT và HIỆU QUẢ NHẤT. Với các phương pháp học đặc biệt như HỌC TỪ 06 BƯỚC, NGHE TỰ ĐỘNG, WISE English đã giúp hàng ngàn học viên đạt IELTS 6.0, 6.5+ và giao tiếp lưu loát với người bản xứ. Để đạt được sứ mệnh, chúng tôi tìm kiếm những bạn đảm nhận các công việc sau: Dạy chương trình tiếng Anh Giao tiếp và/hoặc IELTS theo phương pháp TƯ DUY NÃO BỘ (NLP) và NGÔN NGỮ (Linguistics) (được training bởi WISE Team). Hỗ trợ học viên trong học tập.', 'VỀ PHẨM CHẤT, chúng tôi đang tìm kiếm các bạn có những phẩm chất sau: Có tác phong làm việc chuyên nghiệp; Tận tâm với công việc, với học viên; Nhận trách nhiệm trong công việc; Suy nghĩ tích cực, ham học hỏi và khao khát phát triển bản thân; Trung thực. VỀ KỸ NĂNG, chúng tôi đang tìm kiếm các bạn có những yếu tố sau: Giáo viên IELTS: IELTS tối thiểu 7.0 (Speaking tối thiểu 7.0); Giáo viên Giao tiếp: Thành thạo tiếng Anh, phát âm chuẩn, nói lưu loát; Có kinh nghiệm giảng dạy tối thiểu 06 tháng.
Kỹ năng chuyên môn: [''Giáo viên IELTS: IELTS tối thiểu 7.0 (Speaking tối thiểu 7.0)'', ''Giáo viên Giao tiếp: Thành thạo tiếng Anh, phát âm chuẩn, nói lưu loát'']
Kỹ năng mềm: [''Tác phong làm việc chuyên nghiệp'', ''Tận tâm với công việc, với học viên'', ''Nhận trách nhiệm trong công việc'', ''Suy nghĩ tích cực, ham học hỏi và khao khát phát triển bản thân'', ''Trung thực'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 18000000.00, '9.0 - 18.0 triệu', 'Thứ 2 - Thứ 7 (từ 17:30 đến 21:30)', '[''Thưởng theo hiệu quả công việc'', ''Thưởng lễ, Tết'', ''Được training phương pháp học tập đặc biệt của Trung tâm theo NLP'', ''Được liên tục training về IELTS và kỹ năng giảng dạy'', ''Cơ hội làm Giáo viên full-time nếu làm tốt'', ''Cơ hội lên vị trí Trưởng phòng Đào tạo/Phát triển chất lượng và Giám đốc chi nhánh WISE'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (808, 8, 3, 'CTV Kiểm Tra Trình Độ Học Viên Offline Part-Time', 'Kiểm tra năng lực tiếng Anh cho học viên đăng ký khóa học IELTS của trung tâm: Phát âm, ngữ pháp, từ vựng, kỹ năng Nghe - Nói. Đánh giá đúng trình độ tiếng Anh (Kỹ năng Nói và Viết) theo các tiêu chí của IELTS. Kiểm tra, tư vấn và phân loại trình độ học viên. Gợi ý khóa học phù hợp cho học viên sau khi kiểm tra trình độ tiếng Anh. Điền đầy đủ các nhận xét form mẫu và gửi lại kết quả trong khoảng thời gian từ 15 phút đến 20 phút khi hoàn thành phần kiểm tra và tư vấn cho học viên. Lập báo cáo data học viên kiểm tra đầu vào theo ngày, tuần và tháng. Các công việc khác theo phân công của quản lý trực tiếp.', 'Độ tuổi: Trên 18 tuổi. Chứng chỉ IELTS ≥ 7.5, Speaking ≥ 7.0. Có kỹ năng lập mục tiêu, kế hoạch, checking, follow công việc. Đảm bảo làm được 6 ca/1 tuần. Yêu cầu khác: Có máy tính cá nhân, tham gia quá trình đào tạo để đảm bảo yêu cầu.
Kỹ năng chuyên môn: [''Kỹ năng lập mục tiêu'', ''Kỹ năng lập kế hoạch'', ''Kỹ năng checking'', ''Kỹ năng follow công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', 'Có 3 ca làm việc (tự chọn): Ca 1: 8h30-12h30, Ca 2: 13h30 - 17h30, Ca 3: 17h30 - 21h30', '[''Thưởng ngày lễ, tết theo quy định của nhà nước'', ''Được làm việc trong môi trường trẻ trung, năng động, sáng tạo'', ''Gói chính sách đào tạo thuộc HBR Holdings, miễn giảm học phí nâng cao năng lực'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (809, 9, 3, 'Thực Tập Sinh Tư Vấn/Kinh Doanh Part-Time', 'Tìm kiếm thông tin khách hàng. Tư vấn, hỗ trợ khách hàng trong quá trình sử dụng dịch vụ. Chăm sóc, giải đáp thắc mắc cho các bạn học viên. Nhập dữ liệu lên hệ thống tại công ty.', 'KHÔNG YÊU CẦU KINH NGHIỆM. Có tinh thần học hỏi và muốn phát triển bản thân. Có trách nhiệm và cố gắng trong công việc. Mong muốn gắn bó lâu dài tại công ty. Có laptop cá nhân.
Kỹ năng mềm: [''Có tinh thần học hỏi và muốn phát triển bản thân'', ''Có trách nhiệm và cố gắng trong công việc'', ''Mong muốn gắn bó lâu dài tại công ty'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', '4 tiếng/ngày, 5-6 buổi/tuần, tự chọn ca làm việc', '[''Được hỗ trợ dấu mộc và số liệu làm báo cáo'', ''Lộ trình thăng tiến rõ ràng để lên chính thức'', ''Được linh động lịch làm, đăng kí trước khi bắt đầu tuần mới'', ''Được hưởng chế độ sự kiện, lễ Tết như nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (810, 10, 3, 'CTV Giáo Vụ - Văn Phòng Tổng Hợp', 'Hỗ trợ các công việc hành chính văn phòng như nhập liệu, quản lý hồ sơ học sinh, giáo viên. Sắp xếp lịch học, lịch làm việc của giáo viên và các hoạt động của trung tâm. Chuẩn bị tài liệu, giáo trình, dụng cụ học tập cho các lớp học. Theo dõi và hỗ trợ quản lý tiến độ học tập, điểm danh học sinh. Đón tiếp phụ huynh, học sinh và khách đến trung tâm. Trả lời điện thoại, email, tin nhắn liên quan đến các thắc mắc về dịch vụ của trung tâm (nếu có). Đảm bảo không gian trung tâm, lớp học luôn sạch sẽ, gọn gàng và chuyên nghiệp. Tham gia trang trí không gian trung tâm theo các sự kiện, chương trình đặc biệt. Các công việc khác theo sự phân công của quản lý.', 'Nam/Nữ, đang là sinh viên năm 2 trở lên. Có trình độ Tiếng Anh là 1 lợi thế. Kỹ năng giao tiếp tốt, thân thiện, nhiệt tình, có trách nhiệm trong công việc. Có khả năng làm việc nhóm và xử lý tình huống linh hoạt. Biết sử dụng các phần mềm văn phòng cơ bản (Word, Excel, Google Sheets…). Ưu tiên ứng viên có kinh nghiệm làm việc hành chính, lễ tân hoặc chăm sóc khách hàng. Có thể làm việc xoay ca linh hoạt theo lịch đăng ký của trung tâm.
Kỹ năng chuyên môn: [''Word'', ''Excel'', ''Google Sheets'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Thân thiện'', ''Nhiệt tình'', ''Có trách nhiệm trong công việc'', ''Có khả năng làm việc nhóm'', ''Xử lý tình huống linh hoạt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Linh hoạt theo giờ đăng ký làm việc của trung tâm', '[''Môi trường làm việc thân thiện, năng động'', ''Cơ hội học hỏi kỹ năng hành chính, giao tiếp, quản lý thời gian'', ''Hỗ trợ xác nhận thực tập'', ''Cơ hội thăng tiến trong công việc'', ''Không gian làm việc sạch đẹp, sáng sủa và ngăn nắp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (811, 2, 3, 'Trợ Giảng Tiếng Anh', 'Hỗ trợ giáo viên chính tổ chức các hoạt động, dự án học tập và chăm sóc trẻ em theo chương trình giáo dục của nhà trường. Thực hiện các nhiệm vụ giảng dạy và hỗ trợ giảng dạy theo các chủ đề cụ thể được phân công trong kế hoạch giảng dạy. Tham gia tổ chức sự kiện, hoạt động ngoại khóa tại trường. Các công việc khác theo sự phân công của quản lý.', 'Hướng dẫn học sinh hoàn thành chương trình học trong giờ. Kỹ năng giao tiếp và tương tác với trẻ em tốt. Nhiệt tình, Trách nhiệm với công việc. Không yêu cầu chứng chỉ ngoại ngữ.
Kỹ năng mềm: [''Kỹ năng giao tiếp và tương tác với trẻ em tốt'', ''Nhiệt tình'', ''Trách nhiệm với công việc'']', 'PART_TIME', 'ONSITE', 'hưng yên', 'Hưng Yên', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Mức lương: Thỏa thuận theo giờ (khoảng 40k/ giờ)'', ''Các chế độ đãi ngộ hấp dẫn với nhiều chính sách đặc biệt, chỉ áp dụng cho CBNV'', ''Cơ hội được đào tạo lên giáo viên chuẩn quốc tế'', ''Cơ hội phát triển bản thân và thăng tiến cùng với sự phát triển của hệ thống'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (812, 3, 3, 'Giảng Viên IELTS Offline', 'Giảng dạy chuyên sâu 4 kỹ năng của bài thi IELTS theo mục tiêu đề ra của học viên. Giảng dạy dựa theo giáo trình được biên soạn bởi Hệ thống luyện thi IELTS LangGo. Nhận lớp theo sắp xếp của nhân viên Điều phối Giảng viên. Tham gia đề xuất, cải tiến và phát triển chương trình giảng dạy, phương pháp giảng dạy. Tham gia đào tạo, huấn luyện trong toàn bộ quá trình làm việc. Chăm sóc học viên trong suốt quá trình trước, trong và sau học tập. Gửi báo cáo đánh giá lớp học cho Ban chuyên môn định kỳ theo yêu cầu.', 'Kinh nghiệm: IELTS ≥ 8.0, speaking từ 7.0 trở lên (Ứng viên vui lòng gửi bản scan chứng chỉ đính kèm). Ưu tiên ứng viên đã từng đi giảng dạy/có kinh nghiệm hoặc chứng chỉ đào tạo. Kỹ năng: Yêu thích công việc chia sẻ, đào tạo & phát triển con người. Khả năng giao tiếp tốt và khuyến khích học viên nói tiếng Anh. Thái độ, tố chất: Trung thực, nhiệt tình, có trách nhiệm với công việc. Tâm huyết, có tinh thần học hỏi và phát triển bản thân, gắn bó và yêu thích sự đổi mới sáng tạo. Nhanh nhẹn, chủ động. Yêu cầu khác: Có máy tính cá nhân, tham gia quá trình huấn luyện để đảm bảo yêu cầu.
Kỹ năng chuyên môn: [''IELTS ≥ 8.0'', ''speaking từ 7.0 trở lên'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Yêu thích công việc chia sẻ, đào tạo & phát triển con người'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 25000000.00, '15.0 - 25.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Lương giảng dạy theo giờ'', ''Thưởng lớp kiểu mẫu'', ''Tham gia chương trình đào tạo Giảng viên chuyên nghiệp'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (813, 7, 3, 'Giáo Viên Tiếng Anh', 'Giảng dạy tiếng Anh các lớp được phân công theo lịch đã đăng ký. Cấp độ giảng dạy: KIDS, TEENS, GIAO TIẾP, PRE-IELTS, IELTS. Hình thức giảng dạy: trực tiếp tại các cơ sở do ứng viên đăng ký.', 'Ứng viên là sinh viên năm thứ 4 (đang học ở học kỳ 2) hoặc sắp/đã tốt nghiệp chuyên ngành tiếng Anh, Sư phạm Anh; Ứng viên các chuyên ngành khác cần có Chứng chỉ nghiệp vụ sư phạm/TESOL/TKT hoặc đang theo học các chương trình này. Yêu thích và đảm bảo gắn bó với công việc ít nhất 6 tháng kể từ ngày nhận lớp. Kỹ năng nghe - nói - đọc - viết tiếng Anh tốt. Tích cực tham gia các hoạt động chung của Trung tâm; Ứng viên có kiến thức về phương pháp giảng dạy tiếng Anh và kỹ năng quản lý lớp (không yêu cầu kinh nghiệm).
Kỹ năng chuyên môn: [''Kỹ năng nghe - nói - đọc - viết tiếng Anh'']
Kỹ năng mềm: [''Tích cực tham gia các hoạt động chung của Trung tâm'', ''Kỹ năng quản lý lớp'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ Hai-Tư-Sáu và/hoặc Thứ Ba-Năm-Bảy', '[''Xét tăng lương hằng năm'', ''Thưởng, nghỉ Lễ theo Quy định Công ty'', ''Tham gia các buổi training miễn phí'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (814, 8, 3, 'CTV Kiểm Tra Trình Độ Học Viên Part-Time', 'Kiểm tra năng lực tiếng Anh cho học viên đăng ký khóa học IELTS của trung tâm: Phát âm, ngữ pháp, từ vựng, kỹ năng Nghe - Nói. Đánh giá đúng trình độ tiếng Anh (Kỹ năng Nói và Viết) theo các tiêu chí của IELTS. Kiểm tra, tư vấn và phân loại trình độ học viên. Gợi ý khóa học phù hợp cho học viên sau khi kiểm tra trình độ tiếng Anh. Điền đầy đủ các nhận xét form mẫu và gửi lại kết quả trong khoảng thời gian từ 15 phút đến 20 phút khi hoàn thành phần kiểm tra và tư vấn cho học viên. Lập báo cáo data học viên kiểm tra đầu vào theo ngày, tuần và tháng. Các công việc khác theo phân công của quản lý trực tiếp.', 'Độ tuổi: Trên 18 tuổi. Chứng chỉ IELTS ≥ 7.5, Speaking ≥ 7.0. Có kỹ năng lập mục tiêu, kế hoạch, checking, follow công việc. Đảm bảo làm được 6 ca/1 tuần. Yêu cầu khác: Có máy tính cá nhân, tham gia quá trình đào tạo để đảm bảo yêu cầu.
Kỹ năng chuyên môn: [''Kỹ năng lập mục tiêu'', ''Kế hoạch'', ''Checking'', ''Follow công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '5.0 - 6.0 triệu', 'Có 3 ca làm việc (tự chọn): Ca 1: 8h30-12h30, Ca 2: 13h30 - 17h30, Ca 3: 17h30 - 21h30', '[''Thưởng ngày lễ, tết theo quy định của nhà nước'', ''Môi trường làm việc trẻ trung, năng động, sáng tạo'', ''Gói chính sách đào tạo thuộc HBR Holdings, miễn giảm học phí nâng cao năng lực'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (815, 9, 3, 'Cố Vấn Luyện Thi IELTS Part Time Tối - Không Yêu Cầu Kinh Nghiệm - Cơ Hội Phát Triển Khả Năng Ngoại Ngữ', '-Định hướng phương pháp ôn tập phù hợp cho học viên -Kiểm tra năng lực của học viên -Động viên khuyến khích, có phương pháp tạo động lực học IELTS cho học viên -Thực hiện công việc khác theo sự phân công của Trưởng bộ phận.', '-IELTS ≥ 7.0 (Không có kỹ năng nào dưới 6.5) -Có kiến thức về format bài thi IELTS -Hiểu rõ Band Descriptors của 2 kỹ năng Speaking và Writing -Phát âm tiếng Anh tốt, không nói ngọng, không nói giọng địa phương
Kỹ năng chuyên môn: [''Kiến thức về format bài thi IELTS'', ''Hiểu rõ Band Descriptors của 2 kỹ năng Speaking và Writing'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ Năng Giảng Dạy'', ''Khả Năng Lên Kế Hoạch Bài Học'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '5.0 - 5.5 triệu', 'Thứ 2 - Thứ 7 (từ 18:00 đến 22:00)', '[''Được đào tạo kỹ năng chuyên môn'', ''Thưởng lễ tết'', ''Tham gia teambuilding, party'', ''Review lương 2 lần/năm'', ''Hỗ trợ dấu thực tập sau 3 tháng làm việc'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (816, 10, 3, 'Giáo Viên IELTS', 'Giảng dạy, luyện thi IELTS cho lớp có số lượng từ 16 - 20 học viên theo giáo trình và lộ trình có sẵn. Được cung cấp slide & lesson plan chi tiết mỗi buổi dạy. Chấm & chữa Bài tập 2 kỹ năng Speaking & Writing. Độ tuổi học viên: 16 - 25 tuổi.', 'IELTS từ 7.0 trở lên. Từ 3 tháng - 6 tháng kinh nghiệm dạy. Kỹ năng truyền đạt bài giảng dễ hiểu. Nhiệt tình, tận tâm với học viên. Kỹ năng giảng dạy dễ hiểu.
Kỹ năng chuyên môn: [''Kỹ năng giảng dạy'', ''Kỹ Năng Giao Tiếp Tiếng Anh Lưu Loát'', ''Khả Năng Quản Lý Lớp Học'', ''Phương Pháp Giảng Dạy Hiệu Quả'', ''Kiến Thức Ielts Toàn Diện (reading, Writing, Listening, Speaking)'']
Kỹ năng mềm: [''Kỹ năng truyền đạt bài giảng dễ hiểu'', ''Nhiệt tình, tận tâm với học viên'']', 'PART_TIME', 'ONSITE', 'quảng ninh', 'Quảng Ninh', 'MONTHLY', 30000000.00, '15.0 - 30.0 triệu', '17h40 - 21h50 (2h hoặc 3h/ca tùy khóa học)', '[''Thưởng nóng, thưởng tháng, thưởng quý theo chính sách công ty'', ''Review tăng thu nhập đầu mỗi quý'', ''Hỗ trợ về truyền thông thương hiệu cá nhân trên các nền tảng xã hội'', ''Được tham gia các khóa đào tạo nội bộ'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (817, 2, 3, 'Giảng viên kiểm tra-prep (tập trung SAT)', 'Giáo viên bán thời gian hoặc toàn thời gian: Hướng dẫn các khóa học bằng tiếng Anh học thuật (Sat Reading & Writing Kỹ năng/ Kỹ năng IELTS 4). Cung cấp các bài học ESL nghiêm ngặt, hiệu quả phù hợp với các chương trình và mục tiêu chiến lược của Hội nghị thượng đỉnh. Đánh giá và đưa ra phản hồi kịp thời đối với sinh viên, các bài tập, bài tập và tiến độ tổng thể. Đảm bảo việc chạy hiệu quả của các lớp học; Chuyên nghiệp của hiệu suất. Chuẩn bị và trả lại các báo cáo đánh giá giữa khóa học và cuối khóa học. Công việc bắt đầu vào tháng 6 năm 2025.', '- At least a Bachelor’s Degree from an accredited University - Clean criminal check - IELTS 8.0++ or TOEFL 110++ - SAT 2200++/2400 (old format) or 1500++/1600 (new format) or ACT 34++/36 - Teaching experience and/or a TEFL, TESOL, CELTA certificate. - Ability to exercise judgment and work independently utilizing Summit syllabuses and curriculums - Excellent critical thinking and communication skills - Outstanding organizational skills and team spirit - A desire to help students learn and reach their full potential
Kỹ năng chuyên môn: [''IELTS 8.0++'', ''TOEFL 110++'', ''SAT 2200++/2400 (old format) or 1500++/1600 (new format) or ACT 34++/36'', ''TEFL, TESOL, CELTA certificate'']
Kỹ năng mềm: [''Excellent critical thinking and communication skills'', ''Outstanding organizational skills'', ''Team spirit'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Weekday classes from 6:00 PM – 9:00 PM; additional weekend schedules at 9:00 AM – 12:00 PM and 2:00 PM – 5:00 PM', '[''Comprehensive training provided'', ''Competitive hourly pay based on actual teaching hours'', ''Holiday and New Year bonuses'', ''Annual performance reviews for salary increases'', ''Entitlement to teacher benefits and welfare policies'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (818, 3, 3, 'Tư Vấn Tuyển Sinh Parttime', '- Tìm kiếm các nguồn học viên qua các kênh như mối quan hệ cá nhân, mạng xã hội,... - Đăng bài và bình luận giới thiệu về trung tâm & giáo viên trên các hội nhóm. - Tìm hiểu nhu cầu của học viên & tư vấn khóa học tại trung tâm cho phù hợp - Sắp xếp và hỗ trợ khi học viên qua trung tâm test, học thử, và tìm hiểu trực tiếp - Chăm sóc học viên trong quá trình đăng ký để tối đa tỷ lệ đăng ký khóa học thành công', '- Đang là sinh viên hoặc đã tốt nghiệp đều được - Có khả năng giao tiếp tốt, khả năng chăm sóc khách hàng, kiên nhẫn, cẩn thận - Chưa yêu cầu kinh nghiệm được đào
Kỹ năng mềm: [''Giao tiếp tốt'', ''Chăm sóc khách hàng'', ''Kiên nhẫn'', ''Cẩn thận'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.5 - 5.0 triệu', 'Xoay ca linh hoạt', '[''Lương cứng: 20.000/giờ'', ''Hoa hồng: 6% giá trị hợp đồng ký kết thành công'', ''Được ưu tiên tham gia các buổi training nhân sự'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (819, 7, 3, 'Giáo Viên Tiếng Anh 1-1', 'Dạy Tiếng Anh lớp offline 1-1 tại Phú Mỹ Hưng, quận 7. Giáo viên chịu trách nhiệm giảng dạy cho 1 khoá học khoảng 40-80 giờ.', 'Tiếng Anh tốt 4 kỹ năng (nghe, nói, đọc, viết), phát âm chuẩn, diễn đạt rõ ràng. Ưu tiên có chứng chỉ Tiếng Anh: IELTS từ 7.0, TOEIC từ 800 (Hoặc trình độ tương đương). Tốt nghiệp Sư phạm Anh, Ngôn ngữ Anh hoặc chứng chỉ nghiệp vụ sư phạm tương đương: TESOL, CELTA,… Tác phong chuyên nghiệp, đúng giờ và trách nhiệm cao với công việc. Có kinh nghiệm giảng dạy tiếng Anh cho người đi làm là một lợi thế. GV (độ tuổi 26 -> 36) có kinh nghiệm và chuyên môn giảng dạy, có bằng Thạc sỹ Quản trị Kinh doanh (MBA) là điểm cộng.
Kỹ năng chuyên môn: [''Tiếng Anh tốt 4 kỹ năng (nghe, nói, đọc, viết)'', ''Phát âm chuẩn'']
Kỹ năng mềm: [''Tác phong chuyên nghiệp'', ''Đúng giờ'', ''Trách nhiệm cao với công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '4.5 - 6.0 triệu', '9:00 - 11:00 Sáng, Thứ Hai & Thứ Tư & Thứ Sáu', '[''Hỗ trợ chi phí đi lại'', ''Được đào tạo phương pháp giảng dạy'', ''Tiếp cận với hệ thống phần mềm hiện đại'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (820, 8, 3, 'Giáo Viên IELTS Online Part-Time (Cấp Giáo Trình)', 'Thực hiện giảng dạy trực tuyến qua nền tảng Zoom Pro. Đảm nhiệm giảng dạy đầy đủ 4 kỹ năng IELTS (Nghe, Nói, Đọc, Viết) theo mục tiêu cá nhân của từng học viên. Sử dụng giáo trình được biên soạn riêng bởi hệ thống luyện thi IELTS LangGo. Nhận lớp học theo sự phân công của bộ phận Điều phối Giảng viên. Tham gia đóng góp, đề xuất ý tưởng cải tiến nội dung và phương pháp giảng dạy. Tham dự đầy đủ các buổi đào tạo, tập huấn trong suốt quá trình công tác. Theo sát học viên trước – trong – sau khoá học để đảm bảo kết quả học tập. Gửi báo cáo định kỳ và đánh giá lớp học theo yêu cầu từ Ban chuyên môn.', 'Chứng chỉ & kinh nghiệm: Đạt IELTS overall từ 8.0 trở lên, kỹ năng Speaking tối thiểu 7.0 (vui lòng gửi kèm bản scan chứng chỉ). Ưu tiên ứng viên có kinh nghiệm giảng dạy hoặc đã tham gia các chương trình đào tạo chuyên môn. Kỹ năng & thái độ: Đam mê giảng dạy, yêu thích việc truyền cảm hứng và hỗ trợ học viên phát triển. Giao tiếp tốt, tạo động lực để học viên chủ động sử dụng tiếng Anh. Trung thực, tận tâm, trách nhiệm cao trong công việc. Có tinh thần cầu tiến, ham học hỏi, chủ động tiếp nhận cái mới và đổi mới phương pháp giảng dạy. Tác phong chuyên nghiệp, hình ảnh chỉn chu, phù hợp vai trò đại sứ thương hiệu của Tập đoàn. Yêu cầu khác: Có máy tính cá nhân và cam kết tham gia các khóa huấn luyện bắt buộc để đảm bảo chất lượng giảng dạy.
Kỹ năng chuyên môn: [''Sử dụng Zoom Pro'', ''Sử dụng giáo trình IELTS LangGo'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Truyền cảm hứng'', ''Trách nhiệm cao'', ''Tinh thần cầu tiến'', ''Tác phong chuyên nghiệp'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 25000000.00, '12.0 - 25.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), 2 ca giảng dạy: Ca 1: 17h45 - 19h45, Ca 2: 20h00 - 22h00', '[''Thưởng cho giảng viên đạt chuẩn “lớp kiểu mẫu”'', ''Khóa đào tạo chuyên sâu 2–4 tuần theo phương pháp NLP và ELC'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (821, 9, 3, 'Art Teacher', 'Cung cấp các bài học nghệ thuật hấp dẫn và phù hợp với lứa tuổi cho sinh viên. Lập kế hoạch bài học và đóng góp cho phát triển chương trình giảng dạy. Giới thiệu cho sinh viên một loạt các kỹ thuật nghệ thuật và biểu cảm sáng tạo. Hỗ trợ các sự kiện hoặc triển lãm của trường liên quan đến nghệ thuật (nếu có).', 'Bachelor’s degree in Fine Arts or a related field; teaching certification is a plus. Previous experience teaching art, preferably in an international or bilingual setting. Proficiency in a range of artistic techniques (e.g., drawing, painting, crafts, design). Creative, student-focused, and passionate about art education.
Kỹ năng chuyên môn: [''Proficiency in a range of artistic techniques (e.g., drawing, painting, crafts, design)'']
Kỹ năng mềm: [''Creative'', ''Student-focused'', ''Passionate about art education'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 16:30)', '[''A professional, supportive, and creative international teaching environment'', ''Opportunities for personal and professional development'', ''Involvement in school-wide art programs and student exhibitions'', ''Competitive part-time compensation based on experience and teaching hours'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (822, 10, 3, 'Giáo Viên Dạy Trực Tiếp 1-1', '- Hình thức: Dạy trực tiếp 1 kèm 1 - Đối tượng học viên: Người đi làm (đa phần đã có nền tảng cơ bản, muốn cải thiện kỹ năng giao tiếp thực tế) - Thời lượng mỗi ca: 1.5 – 2 giờ/ca - Thời gian giảng dạy: Linh hoạt theo lịch của học viên và giáo viên, ưu tiên ca tối hoặc cuối tuần', '- Sinh năm 1982-2000. - Tiếng Anh thành thạo 4 kỹ năng (nghe, nói, đọc, viết), phát âm chuẩn, diễn đạt ý rõ ràng. - Tác phong chuyên nghiệp, đúng giờ và trách nhiệm cao với công việc. - Có kinh nghiệm giảng dạy tiếng Anh cho người đi làm là một lợi thế.
Kỹ năng chuyên môn: [''Tiếng Anh thành thạo 4 kỹ năng (nghe, nói, đọc, viết)'']
Kỹ năng mềm: [''Tác phong chuyên nghiệp'', ''Đúng giờ'', ''Trách nhiệm cao với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', 'Linh hoạt theo lịch của học viên và giáo viên, ưu tiên ca tối hoặc cuối tuần', '[''Được đào tạo phương pháp giảng dạy chuyên biệt'', ''Môi trường làm việc tự do, linh hoạt về thời gian và địa điểm'', ''Tiếp cận hệ thống phần mềm quản lý hiện đại'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (823, 2, 3, 'Giáo Viên Tiếng Trung', '- Tham gia giảng dạy các lớp học tại trung tâm - Chấm, chữa bài tập về nhà cho học viên - Điền bảng theo dõi tình hình học tập và làm bài tập về nhà của học viên', 'Tốt nghiệp Đại học các ngành Ngôn ngữ Trung Quốc, Sư phạm tiếng Trung Quốc hoặc Giáo dục Hán ngữ Quốc tế. Ưu tiên giáo viên tốt nghiệp Thạc sĩ các trường tại Trung Quốc.', 'PART_TIME', 'ONSITE', 'tp vinh', NULL, 'MONTHLY', 15000000.00, '10.0 - 15.0 triệu', 'Thứ 2 - Thứ 6 (từ 18:00 đến 22:00)', '[''Thu nhập tốt'', ''Môi trường làm việc trẻ trung, năng động'', ''Có cơ hội thăng tiến'', ''Đào tạo giảng dạy bài bản trước khi bắt đầu giảng dạy'', ''Thưởng lễ, tết đầy đủ'', ''Được cử đi đào tạo kỹ năng giảng dạy tại Trung Quốc nếu gắn bó trên 1 năm'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (824, 3, 3, 'Thực tập sinh, tuyển sinh', 'Hợp tác với nhóm tuyển sinh tham gia các sự kiện và hội thảo tuyển sinh để cung cấp tư vấn, chia sẻ thông tin và hỗ trợ phụ huynh và học sinh trong quá trình đăng ký. Thực hiện các hoạt động telesales để tư vấn cho phụ huynh qua điện thoại và mời họ, cùng với các sinh viên, tham dự các hội thảo và sự kiện ghi danh. Hợp tác với nhóm tuyển sinh trong việc tổ chức và tham gia các hoạt động tuyển sinh cả trong và ngoài khuôn viên trường, bao gồm tại các trung tâm mua sắm, khu vực giải trí, trường học và cộng đồng dân cư gần đó. Hỗ trợ các nhân viên tuyển sinh trong việc thu thập thông tin và tư vấn cho phụ huynh về môi trường học tập phù hợp và các chương trình học tập, cả trực tiếp và qua điện thoại. Cung cấp tư vấn về các kênh kỹ thuật số như FanPage và Zalo OA, theo hướng dẫn, bao gồm trong giờ làm việc, sau giờ và vào cả hai ngày trong tuần và cuối tuần (dựa trên các ca được giao). Hỗ trợ trong nhóm tuyển sinh để thông báo, hướng dẫn cho sinh viên làm bài kiểm tra vị trí. Hỗ trợ nhập học trong việc điền vào tất cả các loại hình thức nhập học, thu thập và sắp xếp chúng theo thứ tự. Báo cáo trong hàng ngày, hàng tuần, hàng tháng và hàng năm về số lượng nhập học của chì, kết quả telesale. Tham gia phần đào tạo đầy đủ từ bộ phận nhập học cũng như trường học. Xử lý các khiếu nại từ phụ huynh như quy trình quản lý khiếu nại để đảm bảo tất cả các khiếu nại được trả lời và giải quyết hoàn toàn một cách chuyên nghiệp và tận tụy, cũng như để giảm các khiếu nại và rủi ro, có thể đáp ứng và tăng sự tin tưởng của trường cho phụ huynh và học sinh.', 'Final year students or Fresh Graduate in University/ College with major in Business Administration/English or relevant. Experience in student care at schools, especially international schools and language centers. Proficient in office computer skills. Conversational English skills. Calm, patient, and friendly demeanor. Good listening skills. Quick adaptability and flexibility.
Kỹ năng chuyên môn: [''Proficient in office computer skills'']
Kỹ năng mềm: [''Calm'', ''Patient'', ''Friendly demeanor'', ''Good listening skills'', ''Quick adaptability'', ''Flexibility'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 07:45 đến 17:00), Thứ 6 - Thứ 7 (từ 08:00 đến 12:00), Thứ 7: 8h-12h', '[''Competitive salary and annual salary review'', ''Performance appraisal bonus'', ''Tuition support for children studying at UTS'', ''Provide nutritious and hygienic lunches'', ''Healthcare insurance & annual medical checkups'', ''Positive and transparent working environment'', ''Opportunities for professional and career development'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (825, 7, 3, 'Giáo Viên Dạy Cờ Vây (Part-Time)', 'Giảng dạy cờ vây mầm non, phổ thông tại các cơ sở RoyalChess. Giảng dạy cờ vây tại các trường học, đối tác liên kết. Các công việc khác theo chỉ đạo của cấp trên (Nếu có).', 'Có trình độ chuyên môn về cờ vây. Yêu thích cờ vây. Yêu thích công việc giảng dạy trẻ em và thật sự yêu trẻ. Làm việc nghiêm túc, trách nhiệm. Có kỹ năng sư phạm là lợi thế. Tốt nghiệp Trung cấp trở lên.
Kỹ năng chuyên môn: [''Có trình độ chuyên môn về cờ vây'']
Kỹ năng mềm: [''Yêu thích cờ vây'', ''Yêu thích công việc giảng dạy trẻ em'', ''Làm việc nghiêm túc'', ''Trách nhiệm'', ''Kỹ năng sư phạm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 15000000.00, '5.0 - 15.0 triệu', 'PART TIME: bán thời gian, theo ca dạy, tiết học.', '[''Được Trung tâm tập huấn nghiệp vụ “Giảng dạy cờ vây theo Hệ thống RoyalChess”'', ''Bồi dưỡng khi làm sự kiện, hoạt động của công ty'', ''Môi trường giáo dục trẻ em vui học'', ''Môi trường làm việc trẻ trung, năng động, đồng nghiệp thân thiện'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (826, 8, 3, 'Nhân Viên Tư Vấn Tuyển Sinh (Nữ - Ca Luân Phiên)', 'Liên hệ, tư vấn giới thiệu khoá học ngoại ngữ cho phụ huynh, học sinh theo nguồn data có sẵn. Khai thác tìm hiểu nhu cầu và chăm sóc khách hàng qua điện thoại, xây dựng mối quan hệ gắn kết và thuyết phục khách hàng sử dụng sản phẩm, chủ động tìm kiếm, mở rộng tệp khách hàng tiềm năng, khách hàng mới. Tương tác, hỗ trợ chăm sóc thêm khách hàng trong quá trình học. Quản lý thông tin khách hàng, cập nhật liên tục trạng thái khách hàng trên hệ thống cơ sở dữ liệu.', 'Ứng viên có kinh nghiệm trong lĩnh vực giáo dục là một lợi thế. Kỹ năng xử lý vấn đề, tình huống phát sinh. Kỹ năng định hướng, dẫn dắt khách hàng. Có thể làm việc luân phiên theo ca. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Kỹ năng xử lý vấn đề'', ''Kỹ năng định hướng khách hàng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'']', 'PART_TIME', 'ONSITE', 'hải phòng', 'Hải Phòng', 'MONTHLY', 20000000.00, '7.0 - 20.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:00 đến 11:30, 13:30 đến 18:00, 18:00 đến 21:30)', '[''Thưởng theo các ngày lễ tết'', ''Tham gia BHXH – BHYT – BHTN theo luật định'', ''Khóa học tiếng anh miễn phí cho nhân viên và người thân'', ''Chế độ quỹ khuyến học hàng tháng cho nhân viên có con nhỏ dưới 16 tuổi'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (827, 9, 3, 'Giáo Viên Tiếng Anh 1-1 Dạy Part-Time Offline', 'Dạy Tiếng Anh lớp offline 1-1 tại Thượng Thanh, Long Biên. Dạy kỹ năng giao tiếp. Dạy trên giáo trình và slide có sẵn của trung tâm. Ngày và giờ học: Thời gian linh hoạt, ưu tiên ca tối. Được sắp xếp phù hợp với lịch của giảng viên và học viên.', '- Tiếng Anh tốt 4 kỹ năng (nghe, nói, đọc, viết), phát âm chuẩn, diễn đạt rõ ràng. - Ưu tiên có chứng chỉ Tiếng Anh: IELTS từ 7.0, TOEIC từ 800 (Hoặc trình độ tương đương). Tốt nghiệp Sư phạm Anh, Ngôn ngữ Anh hoặc chứng chỉ nghiệp vụ sư phạm tương đương: TESOL, CELTA,… - Tác phong chuyên nghiệp, đúng giờ và trách nhiệm cao với công việc. - Có kinh nghiệm giảng dạy tiếng Anh cho người đi làm là một lợi thế.
Kỹ năng chuyên môn: [''Tiếng Anh tốt 4 kỹ năng (nghe, nói, đọc, viết)'', ''Phát âm chuẩn'']
Kỹ năng mềm: [''Tác phong chuyên nghiệp'', ''Đúng giờ'', ''Trách nhiệm cao với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '4.5 - 6.0 triệu', 'Thời gian linh hoạt: Sáng - Chiều - Tối (ưu tiên ca tối)', '[''Hỗ trợ chi phí đi lại'', ''Được đào tạo phương pháp giảng dạy'', ''Tiếp cận với hệ thống phần mềm hiện đại'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (828, 10, 3, 'Thực Tập Sinh Học Vụ', '- Xây dựng, nâng cấp nội dung, giáo trình, tài liệu giảng dạy. - Chọn lọc, đánh giá, đào tạo và điều phối đội ngũ giáo viên. - Kiểm soát chất lượng, đảm bảo lớp học triển khai theo đúng quy trình, quy chuẩn. - Kiểm tra đánh giá đầu vào của học viên, xếp lớp theo trình độ. - Hoàn thành các công việc được cấp trên phân công.', '- Kỹ năng tiếng Anh tốt đặc biệt ở khả năng nghe nói, phát âm chuẩn. - Ưu tiên: Học chuyên ngành sư phạm Anh, Ngôn Ngữ Anh Tiếng Anh Thương Mại,.. hoặc có chứng chỉ tiếng Anh, Giảng dạy (IELTS, TOEIC, TOEFL, TESOL,...) - Yêu thích công việc có sử dụng tiếng Anh. - Có laptop cá nhân.
Kỹ năng chuyên môn: [''Kỹ năng tiếng Anh tốt'']
Kỹ năng mềm: [''Chịu được áp lực'', ''Chủ động'', ''Có trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Thứ 2 đến thứ 6 và thứ 7 cách tuần', '[''Hỗ trợ dấu mộc thực tập'', ''Có cơ hội trở thành nhân sự chính thức sau 3-4 tháng thực tập'', ''Được đào tạo kỹ năng cơ bản và nâng cao'', ''Môi trường chuyên nghiệp, tôn trọng và tạo điều kiện phát huy giá trị cá nhân'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (829, 2, 3, 'Academic Intern', '- Xây dựng, nâng cấp nội dung, giáo trình, tài liệu giảng dạy. - Kiểm soát chất lượng, đảm bảo lớp học triển khai theo đúng quy trình, quy chuẩn. - Chọn lọc, đào tạo và điều phối đội ngũ giáo viên đầu vào của AROMA. - Kiểm tra đánh giá đầu vào của học viên, xếp lớp theo trình độ.', '- Độ tuổi từ 19-30. - Sinh viên năm 2, 3, 4 hoặc tốt nghiệp các trường cao đẳng trở lên. - Ưu tiên: Tiếng Anh thành thạo 4 kỹ năng. Ưu tiên có chứng chỉ IELTS 6.5 trở lên hoặc văn bằng, chứng chỉ tương đương. - Tự tin, kỹ năng giao tiếp, thuyết phục tốt. - Giọng nói chuẩn, không nói ngọng. - Có kỹ năng xử lý tình huống linh hoạt, khéo léo, ngoại hình tốt là một lợi thế. - Có laptop cá nhân.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'', ''Kỹ năng xử lý tình huống linh hoạt'', ''Ngoại hình tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - thứ 6, và thứ 7 cách tuần. Full-time: Sáng 8h30’ - 12h00’, Chiều 13h30’ - 18h00’ hoặc 13h30'' - 21h30''.', '[''Có cơ hội trở thành nhân sự chính thức sau 3-4 tháng thực tập'', ''Học tiếng Anh miễn phí tất cả các khóa học của AROMA'', ''Được đào tạo kỹ năng cơ bản và nâng cao'', ''Môi trường chuyên nghiệp, tôn trọng và tạo điều kiện phát huy giá trị cá nhân'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (830, 3, 3, 'Cộng Tác Viên Tuyển Sinh', '- Xử lý data và tư vấn tuyển sinh cho học sinh THPT có nhu cầu tìm hiểu và đăng ký vào Trường Đại học Phú Xuân; - Tham gia tổ chức các hoạt động tuyển sinh như event, school tour, sự kiện…; - Hỗ trợ các anh chị trong phòng hoàn thành công việc chung; - Thực hiện các nhiệm vụ theo sự phân công từ trưởng phòng.', 'Nam/Nữ từ 18 tuổi trở lên Kỹ năng giao tiếp tốt, siêng năng, trách nhiệm, chủ động trong công việc. Có thiết bị cá nhân để làm việc (điện thoại, internet, v.v.). Ưu tiên người có khả năng kết nối cộng đồng, nhóm học sinh hoặc phụ huynh.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng kết nối cộng đồng'']
Kỹ năng mềm: [''Siêng năng'', ''Trách nhiệm'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'thừa thiên huế', 'Huế', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:00 đến 17:00)', '[''Được đào tạo bài bản kỹ năng, nghiệp vụ theo chuẩn cán bộ tuyển sinh'', ''Cơ hội rèn luyện tác phong chuyên nghiệp'', ''Nhận lương và thưởng theo chế độ riêng dành cho CTV'', ''Có thể xoay ca linh hoạt theo lịch cá nhân'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (831, 7, 3, 'Giáo Viên Tiếng Anh', 'Giảng dạy Tiếng Anh cho học viên từ 6–18 tuổi theo chương trình có sẵn (Cambridge, giao tiếp, IELTS...). Soạn giáo án và kế hoạch giảng dạy phù hợp với trình độ học viên. Theo dõi, đánh giá tiến bộ của học viên và phối hợp với phụ huynh, quản lý lớp. Tuân thủ nội quy, quy trình làm việc và chủ động hỗ trợ cải thiện chất lượng đào tạo.', 'Tốt nghiệp Đại học chuyên ngành Sư phạm tiếng Anh, Ngôn ngữ Anh hoặc các ngành liên quan. Có ít nhất 01 năm kinh nghiệm giảng dạy tiếng Anh. Có chứng chỉ giảng dạy tiếng Anh (TESOL, CELTA, hoặc tương đương) là một lợi thế. Tác phong chuyên nghiệp, tinh thần trách nhiệm cao, làm việc hăng say và cầu tiến. Có khả năng làm việc nhóm và tuân thủ nội quy, quy định của trung tâm.
Kỹ năng chuyên môn: [''Chứng chỉ giảng dạy tiếng Anh (TESOL, CELTA, hoặc tương đương)'']
Kỹ năng mềm: [''Tác phong chuyên nghiệp'', ''Tinh thần trách nhiệm cao'', ''Làm việc hăng say và cầu tiến'', ''Có khả năng làm việc nhóm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 3 - Thứ 7 (từ 17:30 đến 21:00)', '[''Thu nhập cạnh tranh'', ''Cơ hội được đào tạo nâng cao kỹ năng giảng dạy'', ''Làm việc trong môi trường trẻ trung, tôn trọng và hỗ trợ lẫn nhau'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (832, 8, 3, 'Trợ lý Giám đốc Camp / Giám đốc chương trình', 'Để tiếp tục giáo dục, nhiệm vụ giáo dục bằng cách lập kế hoạch và cung cấp các hoạt động và sự kiện chương trình chất lượng cao cho các trại theo mùa của chúng tôi. Thiết kế và thực hiện các hoạt động an toàn, hấp dẫn và phát triển phù hợp. Hỗ trợ Giám đốc trại trong các hoạt động tổng thể và đảm bảo rằng các chương trình phản ánh các giá trị cốt lõi của sự an toàn - vui vẻ - tăng trưởng.', 'Proven experience in managing or directing educational or experiential programs. Strong background in outdoor curriculum planning and activity design.
Kỹ năng chuyên môn: [''Outdoor curriculum planning'', ''Activity design'']
Kỹ năng mềm: [''Leadership'', ''Communication'', ''Empathy'', ''Creativity'', ''Responsibility'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Be part of a team that is dedicated to empowering students to live meaningful lives and achieve Total WellBeing.'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (833, 9, 3, 'Nhân Viên Quản Lý Lớp Học', '- Đón tiếp khách hàng tại văn phòng cơ sở - Quản lý, sắp xếp cơ sở vật chất, văn phòng phẩm, nhu yếu phẩm đảm bảo đủ chất lượng, tiêu chuẩn dịch vụ - Quản lý ngân sách chi văn phòng theo tháng - Quản lý giáo vụ & lưu trữ văn thư - Chăm sóc học viên định kỳ - Hỗ trợ phụ huynh cập nhật tình hình của học viên (với các học viên dưới 18 tuổi) - Tiếp nhận & xử lý phản hồi khách hàng - Làm các thủ tục đầu vào cho học viên khi đăng ký khoá học - Phối hợp với bộ phận liên quan xếp lớp phù hợp cho các học viên - Thực hiện các công việc khác theo yêu cầu của quản lý trực tiếp.', '- Nữ từ 18 - 25 tuổi - Có Laptop cá nhân - Không yêu cầu kinh nghiệm (Có kinh nghiệm làm việc trong ngành dịch vụ CSKH, lễ tân là một lợi thế) - Khả năng giao tiếp, xử lý tình huống tốt, linh hoạt - Tư duy dịch vụ tốt - Ứng viên có tư duy tích cực, năng lượng, biết lắng nghe - Có trách nhiệm trong công việc.
Kỹ năng chuyên môn: [''Sử dụng Laptop'']
Kỹ năng mềm: [''Khả năng giao tiếp'', ''Xử lý tình huống'', ''Tư duy dịch vụ'', ''Trách nhiệm trong công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 12:00)', '[''Lộ trình thăng tiến rõ ràng'', ''Review tăng lương 3-6 tháng/lần'', ''Tham gia các chương trình nội bộ'', ''Được tham gia đào tạo kĩ năng mềm và chuyên môn'', ''Môi trường làm việc trẻ trung, năng động'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (834, 10, 3, 'Trợ Giảng Kỹ Năng Sống', 'TRÁCH NHIỆM CHÍNH: Dẫn dắt nhóm học viên trong sự kiện, Hỗ trợ phát triển kỹ năng cho từng học viên, Ghi nhận tiến bộ và chia sẻ feedback với phụ huynh, Phối hợp với trainer trong các hoạt động nhóm, Tạo không khí tích cực, vui vẻ cho học viên.', 'YÊU CẦU: Học vấn: Sinh viên hoặc Đã tốt nghiệp Ngành Tâm lý, Giáo dục, Sư phạm. Kinh nghiệm: Yêu thích làm việc với trẻ em. Kỹ năng: Giao tiếp tốt, khả năng dẫn dắt nhóm. Tính cách: Kiên nhẫn, yêu thương trẻ, nhiệt huyết. Thời gian: Linh hoạt cuối tuần, có thể tham gia 8h/ngày.
Kỹ năng chuyên môn: [''Giao tiếp tốt'', ''Khả năng dẫn dắt nhóm'']
Kỹ năng mềm: [''Kiên nhẫn'', ''Yêu thương trẻ'', ''Nhiệt huyết'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 7 - Chủ nhật (từ 08:00 đến 18:00)', '[''Lương thưởng hấp dẫn + thưởng theo KPI'', ''Đào tạo miễn phí + tài liệu chuyên môn'', ''Cơ hội phát triển thành Coach chính thức'', ''Môi trường năng động, tác động xã hội'', ''Linh hoạt thời gian, phù hợp sinh viên/người đi làm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (835, 2, 3, 'Giáo Viên Tiếng Anh Trẻ Em (Online)', 'Giảng dạy tiếng Anh cho trẻ trong độ tuổi từ 4 đến 13 trực tuyến thông qua các nền tảng như: Zoom, Skype, Google Meet,...; Giảng dạy theo giáo trình có sẵn. Khuyến khích giáo viên tham gia đóng góp ý kiến, điều chỉnh, tối ưu hóa chương trình học phù hợp với học viên; Thời lượng 1 lớp học: 45 - 90p/ buổi (Tuỳ theo sĩ số lớp 1 - 4 học viên); Truyền cảm hứng, nuôi dưỡng sự yêu thích tiếng Anh cho trẻ.', 'Độ tuổi: Từ 2006 trở lên; Chứng chỉ TOEIC ≥ 900/ IELTS ≥ 7.0 / các chứng chỉ tương đương (CEFR, APTIS, PTE, TOEFL,...) hoặc tốt nghiệp chuyên ngành Ngôn ngữ Anh/Sư phạm Anh/Biên phiên dịch/Tiếng Anh thương mại...loại Khá trở lên; Ưu tiên ứng viên đã có kinh nghiệm giảng dạy tiếng Anh cho trẻ em; Định hướng phát triển lâu dài trong lĩnh vực giáo dục.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Kiên nhẫn'', ''Thấu hiểu tâm lý trẻ em'', ''Tư duy sáng tạo'', ''Quản lý thời gian hiệu quả'', ''Thích ứng nhanh với công nghệ'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '4.0 - 8.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 22:00), Tối thiểu: 6 tiếng/tuần', '[''Lộ trình thăng tiến'', ''Khóa đào tạo đầu vào'', ''Môi trường năng động'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (836, 3, 3, 'Giáo Viên Part Time', 'Tham gia giảng dạy một trong các bộ môn sau: Bộ môn lập trình, sử dụng các ngôn ngữ: Python, Scratch, HTML, Mobile App, JAVASCRIPT, JAVA. Bộ môn điện tử – tự động hóa như: Lego Mindstorm, Arduino, Raspberry Pi... Bộ môn vẽ tay 3D, In 3D, Quay phim, Làm phim, Nhiếp ảnh.... Tham gia các buổi seminar, training.', 'Đang là sinh viên đang theo học khoa CNTT, Điện tử – tự động, mỹ thuật,Tự động hoá, sư phạm kỹ thuật......... của các trường cao đẳng, đại học liên quan. Tốt nghiệp Đại học chuyên ngành Sư phạm, khoa công nghệ thông tin. Đang làm việc tại các công ty Truyền thông, Công nghệ thông tin. Là giảng viên đã và đang giảng dạy tại các trường cấp 1, cấp 2 bộ môn Tin học, Công nghệ thông tin.
Kỹ năng chuyên môn: [''Python'', ''Scratch'', ''HTML'', ''Mobile App'', ''JAVASCRIPT'', ''JAVA'', ''Lego Mindstorm'', ''Arduino'', ''Raspberry Pi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 7000000.00, '2.0 - 7.0 triệu', 'Thứ 2 - Chủ nhật, Sáng 8h00 - 12h00, Chiều 13h00 - 17h00, Tối 17h00 - 21h00', '[''Công việc lành mạnh, văn hoá doanh nghiệp giàu bản sắc'', ''Cơ hội làm việc trực tiếp tham gia các dự án giáo dục mang tính quốc tế cao'', ''Thường xuyên tham gia các buổi đào tạo kĩ năng chuyên môn và kiến thức sư phạm'', ''Được làm việc trong môi trường Giáo dục năng động, chuyên nghiệp, cơ sở vật chất hiện đại'', ''Cơ chế đặc biệt khi hoàn thành nhiệm vụ'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (837, 7, 3, 'Nhân Viên Tư Vấn Tuyển Sinh', '- Kết hợp với nhân viên full-time hỗ trợ quy trình chăm sóc khách hàng và học sinh: điểm danh, đón trả học sinh tại trung tâm... - Tư vấn về giáo dục cho phụ huynh - Tham gia tổ chức, điều phối các chương trình, hoạt động của trung tâm', '- Ca làm việc: 4h/ ngày (tối thiểu 6 ngày/tuần) - Thời gian làm việc: ca chiều tối từ 17:00 - 21:00; 17h30 - 21h30 - Yêu thích làm trong lĩnh vực giáo dục, yêu quý trẻ con - Khả năng làm việc độc lập, làm việc theo nhóm tốt và xử lý tình huống linh hoạt - Có khả năng gọi điện tư vấn cho khách hàng
Kỹ năng mềm: [''Khả năng làm việc độc lập'', ''Làm việc theo nhóm'', ''Xử lý tình huống linh hoạt'']', 'PART_TIME', 'ONSITE', 'hà nội, hưng yên', 'Hà Nội', 'MONTHLY', 10000000.00, '3.0 - 10.0 triệu', '4h/ ngày (tối thiểu 6 ngày/tuần)', '[''Thu nhập: 25k/ giờ + hoa hồng doanh số'', ''Hỗ trợ cấp dấu thực tập'', ''Cơ hội thăng tiến'', ''Giảm học phí khóa học tiếng Anh cho người thân'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (838, 8, 3, 'Giáo Viên Tiếng Đức', '- Giảng dạy tiếng Đức từ trình độ A1 - B1 và Luyện thi các chứng chỉ tiếng Đức TELC, ÖSD, Goethe… theo chương trình chuẩn của Havina - Đánh giá và phản hồi cho học viên để phát triển kiến thức, kỹ năng, thái độ học tập theo cam kết đầu ra. - Tham gia các hoạt động kiểm soát chất lượng và bồi dưỡng phát triển chuyên môn giảng dạy và kiến thức tiếng Đức', '- Tốt nghiệp sư phạm tiếng Đức; các chuyên ngành tiếng Đức tương đương hoặc có chứng chỉ tiếng Đức từ bậc C1 trở lên. - Thành thạo tiếng Đức, phát âm chuẩn. - Kỹ năng đứng lớp tốt, có kinh nghiệm từ 1 năm trở lên đứng lớp giảng dạy hoặc gia sư tiếng Đức. - Có tinh thần trách nhiệm và tinh thần tập thể tốt, thân thiện với học viên. - Biết cách quản lý lớp học, tổ chức và điều phối các hoạt động trong giờ học. - Tính cách vui vẻ, năng động, kiên nhẫn và có mục tiêu phát triển gắn bó lâu dài.
Kỹ năng chuyên môn: [''Thành thạo tiếng Đức'', ''Kỹ năng đứng lớp'']
Kỹ năng mềm: [''Tinh thần trách nhiệm'', ''Tinh thần tập thể'', ''Thân thiện với học viên'', ''Quản lý lớp học'', ''Tổ chức và điều phối hoạt động'']', 'PART_TIME', 'ONSITE', 'đống đa', 'Hà Nội', 'MONTHLY', 30000000.00, '10.0 - 30.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Thưởng lớp lên trình đạt tỉ lệ cao'', ''Thưởng kết quả thi TELC'', ''Tham gia các buổi đào tạo nội bộ hàng quý'', ''Môi trường làm việc chuyên nghiệp'', ''Tham gia các hoạt động của công ty như: Du lịch; team building; sinh nhật'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (839, 9, 3, 'Giáo Viên Tiếng Anh Part-Time', 'Thực hiện giảng dạy chương trình tiếng Anh thông qua môn Toán và Khoa học sử dụng bài giảng số iSMART bậc Tiểu học/ THCS theo sự điều phối của quản lý chuyên môn. Đảm bảo chất lượng đào tạo, giảng dạy theo tiêu chuẩn được hướng dẫn và đưa ra từ đội ngũ Đào Tạo và Nghiên Cứu Phát Triển. Thực hiện các công việc khác liên quan đến chuyên môn như hoàn thiện giáo án, thiết kế đề kiểm tra, chấm bài kiểm tra, làm báo cáo đánh giá xếp loại học sinh và các công tác chuyên môn khác của một giáo viên. Tham gia các buổi đào tạo, tập huấn, họp chuyên môn dành cho giáo viên.', 'Ứng viên tốt nghiệp đại học trở lên với chuyên ngành sư phạm tiếng Anh hoặc các chuyên ngành sư phạm khác (giảng dạy bằng tiếng Anh). Đối với các ứng viên không tốt nghiệp từ các trường đại học sư phạm: Cần có bằng đại học trở lên chuyên ngành tiếng Anh cùng với chứng chỉ nghiệp vụ sư phạm. Khả năng tiếng Anh tốt, phát âm chuẩn, trình độ tương đương B2 trở lên. Lợi thế: Có chuyên môn trong lĩnh vực Toán - Khoa học hoặc có kinh nghiệm giảng dạy tại các trường công lập hoặc dân lập. Làm việc với tinh thần trách nhiệm, hợp tác và kỷ luật. Thành thạo tin học văn phòng.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Tinh thần trách nhiệm'', ''Hợp tác'', ''Kỷ luật'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '5.0 - 15.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Mức lương theo số giờ giảng dạy (Từ 170.000 VNĐ - 250.000 VNĐ/giờ)'', ''Được đào tạo về kỹ năng sử dụng công nghệ tương tác vào giảng dạy'', ''Môi trường làm việc thân thiện, chuyên nghiệp, hiện đại'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (840, 10, 3, 'Giáo Viên Ielts 8.0', 'Giảng dạy các lớp IELTS theo lịch được phân công từ phía trung tâm. Chuẩn bị tài liệu và trực tiếp giảng dạy các khóa học IELTS tùy theo trình độ. Luôn sẵn sàng hỗ trợ học viên sửa BTVN, giải đáp các câu hỏi chuyên môn, bù bài cho học viên (nếu có). Tham gia vào các công việc soạn giáo án, lên kế hoạch giảng dạy, nghiên cứu và phát triển các chương trình học IELTS mà mình phụ trách. Theo dõi sát sao tới từng học viên, giám sát kết quả học tập của từng học viên để đảm bảo chất lượng đầu ra theo tiêu chuẩn của khoá học. Cập nhật thường xuyên tình hình học tập của học viên đến phụ huynh thông qua Zalo. Chịu trách nhiệm 100% với kết quả học tập của học viên. Thường xuyên trau dồi về phương pháp dạy học, tham gia các chương trình đào tạo nâng cao chuyên môn từ trung tâm để nâng cao hiệu quả giảng dạy.', 'IELTS 8.0 trở lên (không kĩ năng nào dưới 7.0) hoặc có chứng chỉ tiếng Anh tương đương C1 CEFR. Tốt nghiệp ngành Ngôn Ngữ Anh hoặc ngành Sư Phạm Tiếng Anh. Có kinh nghiệm giảng dạy IELTS là một lợi thế. Có tinh thần cầu tiến, giao tiếp tốt, có kĩ năng làm việc nhóm, có trách nhiệm trong công việc.
Kỹ năng chuyên môn: [''IELTS 8.0 trở lên'', ''Chứng chỉ tiếng Anh tương đương C1 CEFR'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Kỹ năng làm việc nhóm'', ''Có trách nhiệm trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Theo lịch của giáo viên và theo sự sắp xếp của trung tâm (các buổi tối trong tuần + sáng, chiều chủ nhật)', '[''Review lương sau 6-12 tháng nếu có thái độ và thành tích công việc tốt'', ''Được đào tạo bài bản theo quy chuẩn của Hệ thống Anh ngữ quốc tế Panda'', ''Tham gia các khóa đào tạo nâng cao công ty tài trợ'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (841, 2, 3, 'Nhân Viên Học Vụ', 'Trực tư vấn thông tin khóa học, giải đáp thắc mắc cho học viên/phụ huynh. Ghi nhận, xử lý và báo cáo các tình huống phát sinh đến cấp Quản lý trực tiếp. Hỗ trợ vận hành lớp học: điểm danh, cập nhật thông tin học viên, sắp xếp phòng học. Tổng hợp dữ liệu học viên, báo cáo kết quả lớp học theo yêu cầu. Gửi thông báo, nhắc lịch học, chuyển lớp, đổi ca,... qua Zalo/Email/Facebook. Các công việc khác theo phân công của Quản lý cơ sở hoặc cấp trên.', 'Có ít nhất 01 năm kinh nghiệm ở vị trí tương đương (ưu tiên ứng viên từng làm tại trung tâm ngoại ngữ hoặc giáo dục). Giao tiếp tốt, giọng nói dễ nghe, thái độ thân thiện và chuyên nghiệp. Thành thạo các công cụ văn phòng (Google Sheet, Gmail,...). Chưa có kinh nghiệm sẽ được đào tạo.
Kỹ năng chuyên môn: [''Google Sheet'', ''Gmail'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Thái độ thân thiện'', ''Chuyên nghiệp'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Tham gia BHXH'', ''Tiền thưởng lễ, Tết, sinh nhật, du lịch'', ''Nghỉ phép, nghỉ lễ, Tết theo quy định'', ''Cơ hội thăng tiến và phát triển nghề nghiệp'', ''Môi trường trẻ trung, năng động, thân thiện, khuyến khích sáng tạo'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (842, 3, 3, 'Giáo Viên Toán - Ngữ Văn Tiềm Năng', 'Lên kế hoạch bài giảng, chuẩn bị giáo án theo quy định. Giảng dạy theo lịch xếp của Trung tâm. Theo dõi, đánh giá chất lượng học sinh. Phối hợp với Trợ giàng/ Quản nhiệm lớp để hỗ trợ, động viên học sinh trong quá trình học. Báo cáo tình hình lớp học theo định kỳ. Tham gia các buổi training chuyên môn, họp giao ban giáo viên theo lịch Trung tâm. Thực hiện các công việc khác do Quản lý cơ sở/Trưởng bộ môn giao.', 'Đam mê, yêu thích môi trường và công việc liên quan đến giáo dục, đào tạo. Tốt nghiệp đại học chuyên ngành sư phạm Toán hoặc các ngành liên quan. Giao tiếp tốt, thân thiện, ngoại hình dễ nhìn. Có kinh nghiệm giảng dạy tại các trung tâm dạy thêm là một lợi thế.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Thân thiện'', ''Ngoại hình dễ nhìn'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 7000000.00, '3.0 - 7.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Tham gia các buổi đào tạo, hệ thống bổ trợ chuyên môn'', ''Cơ hội thăng tiến lên trưởng nhóm, trưởng bộ môn'', ''Chế độ BHXH, phúc lợi đầy đủ theo quy định'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (843, 7, 3, 'Gia Sư Lịch Sử, Địa Lý Online', '- Giảng dạy Lịch Sử hoặc Địa Lý cho học sinh THCS và THPT. - Dạy online qua Zoom, kèm 1-1. Làm việc online tại mọi địa điểm ở Việt Nam và nước ngoài. - Thời gian: lịch dạy linh hoạt theo gia sư và học viên, mỗi buổi 60 phút. - Gia sư chủ động lựa chọn thời gian dạy và đối tượng học viên. - Theo dõi, đánh giá quá trình học tập và sự tiến bộ của học viên. - Phản hồi và hỗ trợ học viên cải thiện kết quả học tập theo từng buổi. - Báo cáo ngắn gọn về tình hình học tập của học viên khi được yêu cầu.', '- Có chuyên môn vững, tinh thần trách nhiệm cao. - Có thiết bị dạy online (máy tính, webcam, micro, đường truyền Internet ổn định). - Môi trường giảng dạy yên tĩnh, phù hợp. - Giao tiếp tốt, kiên nhẫn, có kỹ năng truyền đạt. - Không yêu cầu kinh nghiệm. Có kinh nghiệm giảng dạy/gia sư là lợi thế.
Kỹ năng chuyên môn: [''Thiết bị dạy online (máy tính, webcam, micro, đường truyền Internet ổn định)'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Kiên nhẫn'', ''Kỹ năng truyền đạt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 10000000.00, '3.0 - 10.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 21:00)', '[''Thu nhập hấp dẫn, phụ thuộc số lượng các buổi tham gia giảng dạy'', ''Hỗ trợ cung cấp tài liệu giảng dạy'', ''Hỗ trợ đào tạo và hướng dẫn phương pháp giảng dạy trực tuyến hiệu quả'', ''Làm việc hoàn toàn online, linh hoạt về địa điểm'', ''Cơ hội phát triển kỹ năng giao tiếp, thuyết trình, quản lý học viên'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (844, 8, 3, 'CTV Thư Viện Kiêm Chăm Sóc Khách Hàng', 'Duy trì không gian thư viện chuyên nghiệp và thân thiện cho học sinh và phụ huynh; Tham gia tổ chức và điều phối các hoạt động liên quan đến thư viện (tổ chức trò chơi cùng các con); Nhận thông tin phản hồi từ PH về chất lượng dạy học & Trung Tâm (gọi điện thoại); Hỗ trợ PHHS trong các hoạt động đăng ký thẻ, mượn/trả sách và các hỗ trợ khác (nếu có phát sinh); Sắp xếp, phân loại các sách/tài liệu được trả lại theo loại, vị trí; Thực hiện báo cáo kiểm kê sách định kỳ, thông báo các sách quá hạn/thất lạc; Sửa chữa sách hỏng hoặc sắp hỏng (nếu có); Hỗ trợ các công việc liên quan đến bộ phận CSKH khi có yêu cầu và các công việc khác khi được phân công.', 'Có tinh thần tổ chức, sắp xếp và quản lý công việc khoa học, hiệu quả; Đúng giờ, trung thực, trách nhiệm; Có năng lực tự học, tư duy tích cực.
Kỹ năng mềm: [''Có tinh thần tổ chức'', ''Sắp xếp và quản lý công việc khoa học'', ''Đúng giờ'', ''Trung thực'', ''Trách nhiệm'', ''Có năng lực tự học'', ''Tư duy tích cực'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Tham gia các hoạt động sự kiện của Công ty'', ''Tham gia các khóa đào tạo nội bộ của Công ty'', ''Hỗ trợ chi phí khi làm việc tại IEG'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (845, 9, 3, 'Giáo Viên Tiếng Anh', '- Giảng dạy theo chương trình của KTV English (Kid/Teen/Adult/IELTS). - Theo dõi tiến trình học tập của học viên và báo cáo, tổng kết định kỳ. - Hỗ trợ các công việc có liên quan. - Công việc cụ thể sẽ trao đổi trực tiếp khi phỏng vấn.', '- Tiếng anh lưu loát, phát âm chuẩn - Thái độ làm việc chuyên nghiệp, cầu tiến; siêng năng, hòa nhã - Tốt nghiệp Sư phạm Anh hoặc Ngôn ngữ Anh, có chứng chỉ nghiệp vụ sư phạm là một lợi thế
Kỹ năng mềm: [''Tiếng anh lưu loát'', ''Phát âm chuẩn'', ''Thái độ làm việc chuyên nghiệp'', ''Cầu tiến'', ''Siêng năng'', ''Hòa nhã'']', 'PART_TIME', 'ONSITE', 'đồng nai', 'Đồng Nai', 'MONTHLY', 10000000.00, '5.0 - 10.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường làm việc chuyên nghiệp'', ''Thân thiện'', ''Hỗ trợ lẫn nhau'', ''Cơ hội được đào tạo kỹ năng nghiệp vụ thường xuyên'', ''Cơ hội nâng cao kiến thức qua các workshop online/offline'', ''Review lương theo năng lực'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (846, 10, 3, 'Giáo Viên Chứng Chỉ Ielts', 'Soạn nội dung bài dạy dựa trên giáo trình được cung cấp. Thực hiện giảng dạy, kiểm tra và đánh giá học viên theo lịch của trung tâm. Hỗ trợ trung tâm biên soạn và phát triển hệ thống tài liệu, học liệu. Tương tác và hỗ trợ truyền thông trên fanpage trung tâm.', 'Có chứng chỉ IELTS 7.0 trở lên. Có lịch trống vào các buổi tối trong tuần và ban ngày cuối tuần (T7 + CN). Không yêu cầu kinh nghiệm, ứng viên sẽ được đào tạo trong 2 tháng thử việc. Có thể dạy được tiếng Anh phổ thông trong trường hợp trung tâm cần là điểm cộng.', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 17:00 đến 21:00)', '[''Lương hấp dẫn, cạnh tranh theo năng lực và thỏa thuận khi phỏng vấn'', ''Được đào tạo về chuyên môn và nghiệp vụ'', ''Môi trường trẻ trung, năng động với lộ trình thăng tiến rõ ràng'', ''Tăng lương định kỳ theo năng lực và kết quả giảng dạy'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (847, 2, 3, 'Trợ lý quản trị bán hàng thực tập', 'Vị trí này sẽ hỗ trợ khách hàng và tất cả các thành viên của nhóm bán hàng. Kiểm tra tin nhắn từ khách hàng qua email, đường dây nóng và phương tiện truyền thông xã hội và hỗ trợ để xử lý các vấn đề liên quan. Hỗ trợ làm việc với nhóm bán hàng/ nhóm CS để kiểm tra thông tin của khách hàng. Thực hiện cuộc gọi cho các khách hàng cũ và hỗ trợ họ nếu cần. Các yêu cầu khác được chỉ định bởi người giám sát trực tiếp.', 'Current undergraduate or graduate student, recent graduate from economics, business administration, marketing, journalism, public relations, or related fields. Have relevant experience through real work or extracurricular activities. Excellent communication skills, customer orientation mindset. Willing-to-learn and Willing-to-do mindset. Understanding and using office information technology: work, excel... proficiently is an advantage. Be able to work full-time.
Kỹ năng chuyên môn: [''Office information technology'', ''Excel'']
Kỹ năng mềm: [''Excellent communication skills'', ''Customer orientation mindset'', ''Willing-to-learn'', ''Willing-to-do'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Monthly allowance'', ''ELSA Premium Account'', ''Internship certification'', ''Working with seniors in real projects'', ''Company Happy Hour and other company internal activities'', ''Experience the true startup spirit of a fast-growing and well-funded Silicon Valley startup'', "Opportunities to grow professionally and play a critical role in shaping the next stage of our company''s growth", ''Opportunity to create an impact on the lives of 1.5 billion language learners around the world'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (848, 3, 3, 'Gia Sư Tiếng Anh', 'Giảng dạy trực tuyến theo mô hình 1 kèm 1 (mỗi lớp 1 giáo viên 1 học viên). Giảng dạy theo Giáo trình và tài liệu được biên soạn sẵn từ ALES cho các lớp giao tiếp và giảng dạy IELTS đầu ra từ 4.0+. Nhận lớp theo lịch rảnh cá nhân. Nhận xét, đánh giá học sinh sau mỗi buổi dạy. Tham gia các buổi đào tạo trực tuyến, nâng cao kỹ năng sư phạm.', 'Có chứng chỉ IELTS từ 6.5 trở lên hoặc các chứng chỉ TOEIC, TESOL,... Ưu tiên kinh nghiệm giảng dạy hoặc gia sư tiếng Anh (online và offline). Có máy tính kết nối mạng ổn định, đảm bảo không gian dạy online. Làm việc tối thiểu 08 ca/tuần (60 phút/ca) các buổi tối thứ 2-CN, từ 17h-23h, ưu tiên ứng viên có thể làm các ca tối. Thành thạo máy tính, phần mềm Office, MS Teams,...
Kỹ năng chuyên môn: [''Thành thạo máy tính'', ''Phần mềm Office'', ''MS Teams'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kiên nhẫn'', ''Khả năng truyền đạt kiến thức'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '3.0 - 7.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:00 đến 22:30)', '[''Thu nhập tối thiểu từ 2tr - 15tr/tháng'', "Cơ hội nhận ''Chứng Nhận Nghiệp Vụ Sư Phạm''", ''Môi trường làm việc năng động, chuyên nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (849, 7, 3, 'Giáo Viên Tiếng Anh Giao Tiếp Online Part-Time', 'Giảng dạy Tiếng Anh Giao Tiếp trực tuyến 1:1 cho học viên (sinh viên, người đi làm) qua một trong các nền tảng: Zoom, GG Meet, MS Teams. Giảng dạy theo giáo trình có sẵn. Khuyến khích giảng viên tham gia đóng góp ý kiến, điều chỉnh, tối ưu hóa chương trình học phù hợp với học viên. Chăm sóc học viên trong suốt quá trình học tập. Thời lượng 1 lớp học: 60p/ buổi, 3 buổi/ tuần. Dạy tối thiểu 2 lớp/ tuần theo thứ 2-4-6 hoặc 3-5-7 (Theo từng học viên đến hết khóa học 36 - 72 buổi).', 'Đáp ứng một trong các điều kiện sau: Chứng chỉ TOEIC ≥ 900, Chứng chỉ IELTS ≥ 7.0, Bằng Đại học Cử nhân Ngôn ngữ/Sư phạm Anh/Biên phiên dịch...loại Khá trở lên. Khả năng phát âm tốt, có kỹ năng giao tiếp tốt và khuyến khích học viên học tiếng Anh. Tâm huyết, có tinh thần học hỏi và phát triển bản thân, gắn bó và yêu thích sự đổi mới sáng tạo. Tuổi từ 2006 - 1993. Có laptop và tham gia quá trình huấn luyện để đảm bảo yêu cầu.
Kỹ năng chuyên môn: [''Sử dụng Zoom'', ''Sử dụng Google Meet'', ''Sử dụng MS Teams'']
Kỹ năng mềm: [''Khả năng phát âm tốt'', ''Kỹ năng giao tiếp tốt'', ''Tâm huyết'', ''Có tinh thần học hỏi'', ''Yêu thích sự đổi mới sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '4.0 - 10.0 triệu', 'Linh hoạt, tối thiểu 6h/tuần', '[''Tham gia khóa training 1:1'', ''Sử dụng giáo trình độc quyền'', ''Làm việc tại nhà'', ''Chính sách khen thưởng hàng quý'', ''Lộ trình thăng tiến rõ ràng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (850, 8, 3, 'Cộng Tác Viên Telesales', '- Được cung cấp các thiết bị cần thiết phục vụ công việc, số tổng đài. - Gọi điện theo data có sẵn cho khách hàng/ học viên. - Tư vấn khóa học tiếng Anh và mời học viên đến kiểm tra trình độ tiếng Anh. - Hoàn thành các công việc được cấp trên phân công. - Tuyển cả full-time và part-time.', '- Giới tính: Nữ. Độ tuổi từ 18 - 25. - Chất giọng chuẩn, dễ nghe, không nói lắp, nói ngọng. - Nhanh nhẹn, khéo léo, hoạt ngôn. Kỹ năng giao tiếp và thuyết phục tốt. - Ưu tiên ứng viên có kinh nghiệm tư vấn. - Có laptop cá nhân. Thành thạo tin học văn phòng.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'', ''Nhanh nhẹn'', ''Khéo léo'', ''Hoạt ngôn'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '5.0 - 7.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Thưởng 1-4% doanh số'', ''Có cơ hội trở thành nhân viên chính thức sau 2-4 tháng thực tập'', ''Hỗ trợ dấu mộc thực tập'', ''Được đào tạo kỹ năng cơ bản và nâng cao'', ''Môi trường chuyên nghiệp, tôn trọng và tạo điều kiện phát huy giá trị cá nhân'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (851, 9, 3, 'Gia sư tiếng Anh trực tuyến (bán thời gian)', '- Dạy học sinh từ 4 đến 14 tuổi, cũng như học sinh và người lớn lớn tuổi. - Đảm bảo kết quả học tập của học sinh bằng cách là một giáo viên có trách nhiệm và tận tâm. -Tiến hành hầu hết các lớp 1 trên 1. - Cung cấp các lớp chuẩn bị IELTS.', '- Passion and enthusiasm for teaching English to both children and adults. - Ability to teach a minimum of 15 hours per week. - Passionate about teaching and patient.
Kỹ năng mềm: [''Passion for teaching'', ''Patience'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Flexible, minimum 15 hours per week', '[''Flexibility to teach from home'', ''Opportunities for advancement'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (852, 10, 3, 'Thực Tập Sinh Telemarketing (Phụ Cấp + Dấu Mộc)', 'Gọi điện tư vấn cho khách hàng về các khóa học và sản phẩm của trung tâm. Giải đáp thắc mắc, cung cấp thông tin chi tiết về chương trình học, học phí, lịch học. Chăm sóc khách hàng tiềm năng, duy trì mối quan hệ với khách hàng. Hỗ trợ đặt lịch hẹn cho khách hàng đến trải nghiệm lớp học thử hoặc gặp gỡ tư vấn viên. Cập nhật thông tin khách hàng vào hệ thống, báo cáo kết quả công việc theo yêu cầu. Phối hợp đội ngũ Marketing và Sales để tối ưu hiệu quả tiếp cận khách hàng.', 'Thời gian thực tập: 03 tháng. Sinh viên Đại học hoặc Cao đẳng. Có thể làm việc Full-time. Có kỹ năng giao tiếp và thuyết phục tốt. Khả năng xử lý tình huống tốt. Giọng nói dễ nghe. Thái độ vui vẻ, thân thiện, yêu thích trẻ em. Có trách nhiệm trong công việc.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'']
Kỹ năng mềm: [''Khả năng xử lý tình huống'', ''Thái độ vui vẻ'', ''Thân thiện'', ''Yêu thích trẻ em'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.5 triệu', 'Thứ 3 - Chủ nhật', '[''Hỗ trợ lương + Phụ cấp'', ''Hỗ trợ dấu mộc thực tập'', ''Được đào tạo kỹ năng telesales'', ''Môi trường làm việc năng động, thân thiện và cởi mở'', ''Có cơ hội trở thành nhân viên chính thức sau thời gian thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (853, 2, 3, 'Giáo Viên Tiếng Anh', '- Giảng dạy cho các đối tượng học sinh từ 5-17 tuổi. - Báo cáo sau mỗi buổi dạy: Video giảng dạy, Phiếu bài tập. - Hoàn thành báo cáo học tập. - Kiểm tra trình độ học tập và gửi kết quả học tập. - Định hướng lộ trình học tập cho học sinh. - Tổng hợp những ý kiến góp ý của học viên và phụ huynh, phản hồi thông tin đến quản lý.', '- Độ tuổi: Từ 20 tuổi trở lên - Giới tính: Nam/nữ - Trình độ Tiếng Anh (bắt buộc có một trong các chứng chỉ): IELTS từ 6.0 trở lên/ TOEIC từ 785 trở lên/ VSTEP (từ B2 trở lên). Ưu tiên ứng viên tốt nghiệp chuyên ngành sư phạm Anh, ngôn ngữ Anh. - Có các chứng chỉ liên quan đến giảng dạy Tiếng Anh: TESOL, TEFL, Nghiệp vụ sư phạm - là một lợi thế. - Kinh nghiệm chuyên môn: Dạy học tối thiểu 6 tháng liên tục trong vòng 1 năm gần đây. Phát âm rõ ràng, dễ nghe, không ngọng, không bị ảnh hưởng của giọng địa phương. Ưu tiên ứng viên có kinh nghiệm dạy online. - Cam kết làm việc tối thiểu 6 tháng sau khi ký hợp đồng chính thức. - Có máy tính: loa, mic, webcam sử dụng tốt và đường truyền Internet ổn định đảm bảo phục vụ cho việc dạy học online. - Thời gian làm việc: linh hoạt, ngoài giờ hành chính. Chỉ cẩn đảm bảo thực hiện công việc tối thiểu 8 giờ/tuần. - Hình thức làm việc: Online.
Kỹ năng chuyên môn: [''Chứng chỉ IELTS từ 6.0 trở lên'', ''Chứng chỉ TOEIC từ 785 trở lên'', ''Chứng chỉ VSTEP từ B2 trở lên'', ''Chứng chỉ TESOL'', ''Chứng chỉ TEFL'', ''Nghiệp vụ sư phạm'']
Kỹ năng mềm: [''Phát âm rõ ràng'', ''Kỹ năng giao tiếp'', ''Kỹ năng quản lý lớp học'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 25000000.00, '3.0 - 25.0 triệu', 'Linh hoạt, tối thiểu 8 giờ/tuần', '[''Thưởng và tăng lương theo Quý'', ''Thưởng sinh nhật'', ''Chương trình đào tạo bài bản'', ''Cung cấp giáo trình giảng dạy'', ''Hỗ trợ chuyên môn và kỹ thuật 24/7'', ''Cơ hội thăng tiến lên vị trí quản lý'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (854, 3, 3, 'Giáo Viên Dạy Đàn Piano', 'Soạn giáo án giảng dạy, Giảng dạy lý thuyết và thực hành âm nhạc cho học viên, Dạy đàn piano - organ, Theo sát, nắm bắt tiến trình và trình độ của từng học viên giảng dạy, lên giáo án giảng dạy phù hợp, Tham gia phỏng vấn, đánh giá chất lượng học sinh đầu vào, chấm Học bổng, tham dự các Hội thảo tuyển sinh, các lớp học trải nghiệm và tham dự các sự kiện của trường trong suốt năm học và thời gian hè (nếu có) theo phân công. Tham gia xây dựng và cải tiến chương trình hàng Kỳ, hàng năm và xây dựng kế hoạch hướng dẫn triển khai Chương trình chính khóa và ngoại khóa ở các cơ sở mới khi có yêu cầu từ cấp trên. Thực hiện đầy đủ các loại sổ sách của nhà trường quy định (bao gồm sổ sách Bộ và sổ sách báo cáo nội bộ).', 'Có kiến thức sư phạm. Giỏi chuyên môn. Tận tâm. Tốt nghiệp chuyên ngành sư phạm âm nhạc hoặc liên quan. Sinh viên hoặc giáo viên có trình độ và chuyên môn về piano organ guitar, có kinh nghiệm giảng dạy.
Kỹ năng chuyên môn: [''Kiến thức sư phạm'', ''Chuyên môn về piano, organ, guitar'']
Kỹ năng mềm: [''Tận tâm'', ''Khả năng truyền đạt kiến thức'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 12000000.00, '8.0 - 12.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Chế độ đãi ngộ tốt'', ''Được đào tạo huấn luyện về chuyên môn'', ''Cơ hội thăng tiến'', ''Hỗ trợ 70% học phí tại Trung tâm cho nhân viên và người thân'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (855, 7, 3, 'Giáo Viên Dạy Scratch', '- Chịu trách nhiệm giảng dạy các khóa về lập trình như: Code, Scratch, Code monkey... - Giảng dạy kiến thức lập trình dựa trên lộ trình giáo án có sẵn - Hỗ trợ học viên hoàn thành tốt khóa học, đảm bảo chất lượng đầu ra của học viên', '- Có kinh nghiệm giảng dạy Scratch tại các trường hoặc trung tâm - Có niềm đam mê với lập trình, yêu quý trẻ em - Yêu thích công việc giảng dạy - Có tinh thần kiên trì và trách nhiệm cao với công việc
Kỹ năng chuyên môn: [''Lập trình Scratch'']
Kỹ năng mềm: [''Kiên trì'', ''Trách nhiệm'', ''Yêu thích trẻ em'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Chỉ làm ngoài giờ tối và cuối tuần', '[''Được đào tạo nâng cao kỹ năng nếu ít kinh nghiệm'', ''Được xem xét nâng lương sau 4-6 tháng'', ''Được tuyển dụng làm việc full time sau khi dạy thử'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (856, 8, 3, 'Giáo Viên Tiếng Anh IELTS/TOEIC/VSTEP', 'Giảng dạy các lớp Tiếng Anh từ trình độ: Cơ bản, tới Luyện thi chứng chỉ: IELTS, TOEIC, VSTEP. Kiểm tra, chấm điểm, nhận xét, đánh giá học viên định kỳ. Thực hiện các công việc học thuật liên quan khác theo yêu cầu của Trưởng bộ phận và Ban Lãnh đạo khi cần.', 'Đã tốt nghiệp Đại học trở lên, ưu tiên chuyên ngành Sư phạm Tiếng Anh hoặc Ngôn ngữ Anh. Ưu tiên các ứng viên tốt nghiệp: Đại học Sư phạm, Đại học Ngoại ngữ, Đại học Hà Nội… Có chứng chỉ ngoại ngữ còn hạn: IELTS 7.5 trở lên hoặc TOEIC 900 trở lên hoặc VSTEP 8.5 trở lên. Ưu tiên các ứng viên có cả 2-3 chứng chỉ. Có ít nhất 01 năm kinh nghiệm giảng dạy trực tiếp các lớp học Tiếng Anh, với số lượng tối thiểu từ 05 học viên trở lên. Ưu tiên ứng viên có chứng chỉ giảng dạy còn hạn: TESOL, CELTA, Chứng chỉ nghiệp vụ sư phạm,...
Kỹ năng chuyên môn: [''Chứng chỉ ngoại ngữ còn hạn: IELTS 7.5 trở lên hoặc TOEIC 900 trở lên hoặc VSTEP 8.5 trở lên'']
Kỹ năng mềm: [''Phong cách giảng dạy sôi nổi, năng lượng, đa dạng và sáng tạo'', ''Trung thực, nhiệt tình và có trách nhiệm cao trong công việc'', ''Chịu được áp lực về tiến độ công việc tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 25000000.00, '15.0 - 25.0 triệu', 'Từ Thứ 2-Thứ 7, 3h/ngày', '[''Thưởng hiệu quả làm việc'', ''Phụ cấp thâm niên'', ''Du lịch hàng năm'', ''Team building'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (857, 9, 3, 'Giáo Viên IELTS Part-Time Online, Sẵn Giáo Trình', 'Giảng dạy IELTS trực tuyến qua nền tảng Zoom Pro. Giảng dạy IELTS dựa trên giáo trình được biên soạn sẵn bởi Hệ thống luyện thi IELTS LangGo. Nhận lớp theo điều phối của ban vận hành. Giảng dạy với size lớp tối đa 8 bạn. Chấm chữa bài cho học sinh.', 'Kinh nghiệm: IELTS ≥ 8.0, S + R + L >=7.0, W>=6.5. Ưu tiên ứng viên đã từng đi giảng dạy/có kinh nghiệm hoặc chứng chỉ đào tạo.
Kỹ năng chuyên môn: [''Giảng dạy IELTS'', ''Khả năng giao tiếp tốt'']
Kỹ năng mềm: [''Trung thực'', ''Nhiệt tình'', ''Có trách nhiệm với công việc'', ''Tâm huyết'', ''Có tinh thần học hỏi'', ''Nhanh nhẹn'', ''Chủ động'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 20000000.00, '15.0 - 20.0 triệu', 'Làm việc online tại nhà, tự đăng kí theo lịch rảnh', '[''Thưởng chấm bài và hoàn thành lớp học đúng quy định'', ''Tham gia chương trình đào tạo Giảng viên chuyên nghiệp'', ''Thưởng theo KPIs'', ''Thưởng tết và phúc lợi theo cơ chế/quy định của công ty'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (858, 10, 3, 'Giáo Viên Tiếng Đức', 'Giảng dạy tiếng ĐỨC trình độ A1 trở lên, luyện thi lấy bằng. Theo sát và đánh giá học viên, sinh viên. Ra đề và chấm thi môn học được giao đúng qui trình và đúng hạn. Tham gia những công việc khác do trưởng đơn vị phân công.', '- Giáo viên sử dụng tiếng ĐỨC trình độ B2 trở lên - Có kinh nghiệm dạy tiếng ĐỨC - Ưu tiên có kinh nghiệm.
Kỹ năng chuyên môn: [''Sử dụng tiếng Đức trình độ B2 trở lên'', ''Có kinh nghiệm dạy tiếng Đức'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thời gian làm việc linh hoạt theo giáo viên', '[''Thu nhập: Trao đổi khi tham gia phỏng vấn'', ''Để xem miễn phí trong tầng hầm của tòa nhà'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (859, 2, 3, 'Chuyên Viên Quản Lý Đào Tạo', 'Quản lý, lập kế hoạch, điều phối, báo cáo hoạt động các dự án học tập, tư vấn. Triển khai các hoạt động hỗ trợ học tập nhằm gia tăng chất lượng và trải nghiệm học tập của học viên. Triển khai các hoạt động hỗ trợ công tác giảng dạy với chuyên gia, nhằm giúp gia tăng chất lượng đào tạo và trải nghiệm giảng dạy của chuyên gia. Phối hợp cùng chuyên gia và các bộ phận khác để triển khai các hoạt động hỗ trợ sau đào tạo và chăm sóc học viên, khách hàng doanh nghiệp như tổ chức các hoạt động giao lưu, sự kiện cựu học viên, bản tin học viên,... Theo dõi, cập nhật các dữ liệu đào tạo của đơn vị. Các nhiệm vụ khác theo chiến dịch, hoặc sự phân công của lãnh đạo.', 'Có trình độ từ cao đẳng trở lên, có ít nhất 02 năm kinh nghiệm ở vị trí chuyên viên chăm sóc khách hàng, hành chính nhân sự tổng hợp, hoặc triển khai đào tạo. Có kỹ năng giao tiếp, chăm sóc khách hàng tốt. Có kỹ năng lập kế hoạch, phân tích, tổng hợp, báo cáo. Thành thạo Tin học văn phòng (Excel, Word, Power Point, …). Có kiến thức về dịch vụ, nhân sự, giáo dục đào tạo là một lợi thế.
Kỹ năng chuyên môn: [''Tin học văn phòng (Excel, Word, Power Point)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng lập kế hoạch'', ''Kỹ năng phân tích'', ''Kỹ năng tổng hợp'', ''Kỹ năng báo cáo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 12000000.00, '8.0 - 12.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), giờ làm việc linh hoạt', '[''Được đóng BHXH, BHYT, BHTN đầy đủ theo quy định'', ''Nghỉ Lễ, Tết theo lịch chung của Nhà nước, phép: 12 ngày/năm'', ''Xem xét tăng lương hàng năm, thưởng cuối năm'', ''Khám sức khỏe định kỳ, team building, nghỉ hè, picnic'', ''Được học tập và phát triển không ngừng với kho tài nguyên đào tạo số'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (860, 3, 3, 'Giáo Viên Tiếng Anh Part Time', 'Cấp độ dạy – tự chọn: Kindergarten, Kids, Teenagers, Adults. Dạy các lớp được phân công theo lịch đã đăng ký. Có năng lực giảng dạy các giáo trình phổ biến như BEENO, TINY TALK, FAMILY AND FRIENDS, MORE; Chuẩn bị tài liệu, vật dụng dạy học, chấm và sửa bài tập về nhà cho học viên. Nhận xét tình tình học tập của học viên. Thời gian làm việc ít nhất 06 tháng từ ngày nhận lớp (tương đương 01 khóa học).', 'Tốt nghiệp chuyên ngành (hoặc sinh viên năm 4 chuẩn bị tốt nghiệp/ chờ bằng) từ CĐ/ ĐH chuyên ngành Sư phạm Tiếng Anh/ Ngôn ngữ Anh/ Tiếng Anh và chứng chỉ Nghiệp vụ Sư phạm/ TESOL/TKT (nếu có). Có năng lực giảng dạy các giáo trình phổ biến như BEENO, TINY TALK, FAMILY AND FRIENDS, MORE; Cấp độ dạy – tự chọn: Kindergarten, Kids, Teenagers, Adults. Có năng lực giao tiếp và xử lý tình huống tốt; Yêu thích trẻ em; Có tinh thần hợp tác và cầu tiến.
Kỹ năng chuyên môn: [''Giảng dạy giáo trình BEENO'', ''Giảng dạy giáo trình TINY TALK'', ''Giảng dạy giáo trình FAMILY AND FRIENDS'', ''Giảng dạy giáo trình MORE'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Xử lý tình huống tốt'', ''Yêu thích trẻ em'', ''Tinh thần hợp tác'', ''Cầu tiến'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 10000000.00, '5.0 - 10.0 triệu', 'Tối thứ 2 – 4 – 6 hoặc tối 3 – 5 – 7', '[''Chế độ bonus sĩ số theo quy định tại trung tâm'', ''Chế độ đào tạo nâng cao nghiệp vụ sư phạm'', ''Chế độ xét tăng lương định kỳ và đột xuất'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (861, 7, 3, 'Giáo Viên Tiếng Đức', '• Giảng dạy tiếng Đức từ trình độ A1 đến B1 theo giáo trình Schritte Plus Neu. • Đánh giá tiến độ học tập, đưa ra phản hồi và định hướng giúp học viên phát triển kiến thức, kỹ năng và thái độ học tập. • Tham gia các hoạt động nâng cao chất lượng giảng dạy và phát triển chuyên môn nghiệp vụ.', '• Tốt nghiệp chuyên ngành tiếng Đức tại các trường Đại học Ngoại ngữ (ULIS, HANU,...) • Có chứng chỉ Sư phạm • Ưu tiên ứng viên có chứng chỉ tiếng Đức C1 hoặc tương đương (TestDaF, DSH, telc,...). • Ưu tiên có kinh nghiệm giảng dạy hoặc từng sinh sống, học tập, làm việc tại CHLB Đức. • Có năng lực sư phạm, tinh thần trách nhiệm và khả năng truyền cảm hứng cho học viên.
Kỹ năng chuyên môn: [''Tiếng Đức giao tiếp thành thạo'']
Kỹ năng mềm: [''Năng lực sư phạm'', ''Tinh thần trách nhiệm'', ''Khả năng truyền cảm hứng cho học viên'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Mức lương cạnh tranh, thỏa thuận theo năng lực khi phỏng vấn'', ''Môi trường làm việc chuyên nghiệp, minh bạch, hỗ trợ phát triển lâu dài'', ''Được tham gia miễn phí tất cả các khóa học tiếng Đức tại trung tâm'', ''Được đào tạo về kỹ năng giảng dạy và phát triển chuyên môn'', ''Thưởng các dịp lễ, Tết và các phúc lợi khác theo quy định của công ty'', ''Tham gia các hoạt động team building, sự kiện, du lịch hàng năm'', ''Cơ hội trở thành giảng viên full-time nếu có nguyện vọng và phù hợp năng lực'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (862, 8, 3, 'Giáo Viên Tiếng Trung (Parttime)', 'Nghiên cứu và xây dựng nội dung cho từng chủ đề học. Giảng dạy học sinh theo từng cấp độ theo yêu cầu của Trung tâm. Thực hiện các công tác như điểm danh, tổ chức thi, hoạt động ngoại khóa, test đầu vào... Đề xuất kiến nghị về chuyên môn và các hoạt động khác giúp Trung tâm ngày càng phát triển. Nghiên cứu phương pháp dạy và học vui, thực tế, dễ học dễ nhớ... Nghiên cứu và cập nhật kiến thức mới thường xuyên. Các công việc khác do BGĐ yêu cầu.', 'Tốt nghiệp Đại học chuyên ngành Tiếng Trung hoặc Trình độ tiếng Trung tương đương HSK5 trở lên. Ưu tiên có kinh nghiệm làm công tác giảng dạy online và offline. Kỹ năng chuyên môn: phát âm chuẩn, giao tiếp lưu loát. Có ngoại hình và khả năng truyền đạt dễ hiểu, cuốn hút, yêu trẻ em. Sử dụng thành thạo vi tính.
Kỹ năng chuyên môn: [''Phát âm chuẩn'', ''Giao tiếp lưu loát'', ''Sử dụng thành thạo vi tính'']
Kỹ năng mềm: [''Có ngoại hình'', ''Khả năng truyền đạt dễ hiểu'', ''Cuốn hút'', ''Yêu trẻ em'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Dạy vào buổi tối theo lịch của Trung tâm. Mỗi ca dạy 2 tiết.', '[''Được đào tạo kỹ năng sư phạm và chuyên môn'', ''Môi trường làm việc thân thiện, năng động'', ''Có cơ hội trở thành giáo viên cơ hữu của Trung tâm'', ''Được tham gia các hoạt động vui chơi, du lịch cùng Trung tâm'', ''Du lịch hàng năm'', ''Thưởng tháng 13'', ''Thưởng hiệu quả làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (863, 9, 6, 'Nhân Viên Kiểm Đếm Và Ghi Chép Số Lượng Hàng Hóa', 'Tuyển dụng Cộng tác viên Tally Man (Kiểm đếm và ghi chép số lượng hàng hóa) khu vực Quảng Ninh hoặc Hải Phòng (nếu chấp nhận di chuyển). Nội dung công việc: Kiểm tra trọng lượng xe tải hoặc container trên cầu cân, Lấy mẫu hàng hóa trên tàu hoặc kiểm tra kho bãi, Giám sát hàng hóa dự trữ trong kho, đảm bảo xe tải trái phép đều bị từ chối, Thông báo cho trưởng ca về việc không hợp tác của người làm việc tại cảng hoặc xe tải, Báo cáo công việc theo hướng dẫn. Khu vực làm việc: Cái Lân (Quảng Ninh), thỉnh thoảng có làm ở Hải Phòng. Công việc làm ca 12 tiếng (thời vụ nhưng sẽ làm lâu dài), phù hợp cho nam.', 'Tốt nghiệp phổ thông, đọc-viết tiếng Việt tốt, dùng zalo trao đổi công việc. Ưu tiên nếu có kinh nghiệm liên quan. Ưu tiên ở Quảng Ninh, hoặc Hải Phòng (nếu chấp nhận di chuyển)
Kỹ năng chuyên môn: [''Sử dụng Zalo để trao đổi công việc'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Trung thực'']', 'PART_TIME', 'ONSITE', 'quảng ninh', 'Quảng Ninh', 'MONTHLY', 4000000.00, '0.0 triệu', '12 tiếng/ngày', '[''Bảo hiểm tai nạn lao động'', ''Tham gia bảo hiểm xã hội'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (864, 10, 6, 'Thực Tập Sinh Mua Hàng Tiếng Trung (Có Đào Tạo)', '1. Liên hệ làm việc với nhà cung cấp, trao đổi đàm phán để mua hàng với mức giá hợp lý; 2. Triển khai mua hàng theo kế hoạch đảm bảo cung cấp nguồn hàng đầy đủ và đúng tiến độ; 3. Thực hiện các công việc làm báo giá, dịch báo giá, đơn chào hàng, đặt đơn và theo dõi tiến độ đơn hàng; 4. Kiểm tra chất lượng nguồn vật tư được giao đến và phản ánh với nhà cung cấp trong trường hợp hàng hóa không đạt yêu cầu; 5. Báo cáo công việc theo yêu cầu; 6. Chi tiết sẽ trao đổi trong buổi phỏng vấn.', '1. Chỉ tuyển Nữ, độ tuổi từ 20-25 tuổi; 2. Hiện đang là sinh viên hoặc đã tốt nghiệp các chuyên ngành liên quan đến Mua hàng, Logistics, Ngoại ngữ,… 3. Tiếng Trung: Trình độ tương đương HSK 4 trở lên; 4. Có mong muốn gắn bó tối thiểu 3-6 tháng trở lên; 5. Ham học hỏi, yêu thích và có định hướng phát triển trong lĩnh vực Mua hàng; 6. Khả năng giao tiếp, tìm kiếm và tổng hợp thông tin tốt; 7. Nhiệt tình, trung thực và có trách nhiệm với công việc; 8. Thành thạo máy vi tính.
Kỹ năng chuyên môn: [''Tiếng Trung (HSK 4 trở lên)'', ''Kỹ năng máy vi tính'']
Kỹ năng mềm: [''Khả năng giao tiếp'', ''Tìm kiếm và tổng hợp thông tin'', ''Nhiệt tình'', ''Trung thực'', ''Có trách nhiệm với công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), 02 ngày thứ 7 hàng tháng', '[''Hỗ trợ lương thực tập'', ''Được đào tạo bài bản về kiến thức và kỹ năng phục vụ công việc'', ''Hỗ trợ đóng dấu thực tập'', ''Cơ hội phát triển thành nhân viên chính thức'', ''Được tham gia các chương trình, hoạt động, liên hoan do công ty tổ chức'', ''Làm việc trong môi trường năng động, trẻ trung, chuyên nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (865, 2, 6, 'Lao Động Phổ Thông Chính Thức & Thời Vụ', 'Phân loại, đóng gói, sắp xếp hàng hóa trong kho theo đúng quy định. Xử lý đơn hàng, làm việc theo sản lượng được giao. Hỗ trợ kiểm hàng, kiểm đếm số lượng, tem nhãn. Tuân thủ quy trình kho, đảm bảo an toàn và đúng quy định. Giữ vệ sinh khu vực làm việc, sẵn sàng hỗ trợ các công việc phát sinh khác theo yêu cầu quản lý.', 'Không yêu cầu kinh nghiệm – sẽ được đào tạo trong quá trình làm việc. Trung thực, cẩn thận, siêng năng. Có sức khỏe tốt. Độ tuổi: từ 18 đến 45 tuổi. Biết đọc, biết viết (trình độ cơ bản).
Kỹ năng mềm: [''Trung thực'', ''Cẩn thận'', ''Siêng năng'']', 'PART_TIME', 'ONSITE', 'tây ninh', 'Tây Ninh', 'MONTHLY', 12000000.00, '9.0 - 12.0 triệu', 'Làm việc 6 ngày/tuần (26 ngày/tháng), Ca ngày: 8h–17h | 9h–18h, Ca đêm: 21h–6h | 22h–7h', '[''Bảo hiểm xã hội'', ''Bảo hiểm sức khỏe'', ''Thưởng tháng 13'', ''Phụ cấp thâm niên'', ''Thưởng hiệu quả làm việc'', ''Ăn trưa'', ''Xăng xe'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (866, 3, 6, 'Thực Tập Sinh Quản Lý Kho Vận - Có Lương', 'Tạo và theo dõi đơn hàng, đảm bảo sự chính xác trong việc xử lý đơn hàng và đơn hàng được vận chuyển đúng thời hạn. Xử lý khiếu nại với đơn vị vận chuyển. Đóng gói sản phẩm theo đơn hàng, đảm bảo đóng gói chính xác sản phẩm và số lượng hàng hóa theo đơn hàng. Quản lý tồn kho. Hỗ trợ kiểm kê, theo dõi số lượng hàng hóa. Báo cáo khi phát sinh sai lệch. Hỗ trợ sắp xếp, thống kê hàng hóa ngăn nắp, theo quy chuẩn chung. Dọn dẹp, vệ sinh sau khi đóng hàng ngăn nắp, sạch sẽ.', 'Sinh viên sắp tốt nghiệp các ngành Thương mại Điện tử, Logistics, Quản trị kinh doanh,... các ngành tương đương hoặc yêu thích thương mại điện tử. Yêu thích việc soạn hàng và đóng gói hàng hóa. Cẩn thận, tỉ mỉ, trung thực. Chăm chỉ, siêng năng, nhiệt huyết, trách nhiệm với công việc.
Kỹ năng chuyên môn: [''Sử dụng phần mềm quản lý kho (nếu có)'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Trung thực'', ''Chăm chỉ'', ''Siêng năng'', ''Nhiệt huyết'', ''Trách nhiệm với công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Trợ cấp thực tập hàng tháng: 2.000.000đ/tháng'', ''Hỗ trợ xác nhận và cung cấp mộc thực tập tại công ty'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Được tham gia các hoạt động tập thể: ăn uống, sinh nhật, liên hoan, Year end Party, Team Building'', ''Được nghỉ theo lịch nghỉ lễ của công ty'', ''Cơ hội thăng tiến, phát triển nghề nghiệp'', ''Được tham gia các chương trình đào tạo của công ty'', ''Đồ ăn nhẹ, thức uống miễn phí'', ''Bảo hiểm xã hội'', ''Team building'', ''Thưởng tháng 13'', ''Du lịch hàng năm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (867, 7, 6, 'Nhân Viên Thời Vụ Bộ Phận Hàng Nhập', 'Nhận thông tin lô hàng nhập từ bộ phận pricing hoặc bộ phận sales tiến hành handle các bước tiếp theo của lô hàng cho đến khi hàng cập cảng tại Việt Nam. Khai Manifest cho lô hàng nhập. Làm đề nghị thanh toán cho hãng tàu, coloader gửi bộ phận kế toán thanh toán. Gửi giấy báo hàng đến cho khách hàng. Thời gian làm việc giờ hành chính từ thứ 2 đến thứ 6. Nghỉ thứ 7 và Chủ Nhật.', 'Đã tốt nghiệp đại học, cao đẳng chuyên nghành Logistics, kinh tế, ngoại thương. Có ít nhất 1 năm kinh nghiệm làm việc trong công ty thuộc lĩnh vực logistic. Năng động, giao tiếp tốt, giải quyết công việc nhanh gọn, hiệu quả. Có trình độ ngoại ngữ tiếng Anh.
Kỹ năng mềm: [''Năng động'', ''Giao tiếp tốt'', ''Giải quyết công việc nhanh gọn'', ''Hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Làm việc trong môi trường trẻ trung, năng động, chuyên nghiệp'', ''Cung cấp trang thiết bị, phần mềm phục vụ công việc'', ''Được hưởng các chính sách phúc lợi theo quy định của công ty'', ''Được đào tạo, nâng cao nghiệp vụ thường xuyên'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (868, 8, 6, 'Thực Tập Sinh Mua Hàng Tiếng Trung', 'Hỗ trợ tìm kiếm NCC hàng hóa, nguyên vật liệu và thực hiện đơn hàng phục vụ sản xuất và chế tác trang sức (được đào tạo). Hỗ trợ thu thập thông tin, so sánh giá cả, chất lượng sản phẩm từ các nhà cung cấp. Thực hiện thống kê thông tin, điền form mẫu biểu bảng theo yêu cầu của người hướng dẫn trực tiếp. Hỗ trợ theo dõi đơn hàng, kiểm tra chất lượng sản phẩm. Thực hiện theo các công việc khác theo yêu cầu của bộ phận.', 'Sinh viên 3, năm cuối/ Tốt nghiệp đại học, ưu tiên chuyên ngành: Quản trị kinh doanh/ Kinh tế/ Quản trị doanh nghiệp/Ngoại thương/Thương mại… tại các trường Đại học Ngoại Thương, Kinh Tế Quốc Dân, Thương Mại, Ngân hàng… Ưu tiên ứng viên có thể làm fulltime. Tiếng Anh, Tiếng Trung tốt (ưu tiên Tiếng Trung tốt). Tinh thần trách nhiệm cao trong công việc. Chăm chỉ, cẩn thận, tỉ mỉ. Nhiệt tình trong công việc. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Tiếng Anh'', ''Tiếng Trung'']
Kỹ năng mềm: [''Tinh thần trách nhiệm cao trong công việc'', ''Chăm chỉ'', ''Cẩn thận'', ''Tỉ mỉ'', ''Nhiệt tình trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Thứ 2 - Thứ 7 (Sáng thứ 7 làm online)', '[''Mức lương: 23.000 VNĐ/giờ'', ''Phụ cấp gửi xe 100.000 VNĐ/tháng'', ''Tham gia các hoạt động gắn kết của Công ty'', ''Cơ hội được trở thành nhân viên chính thức của công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (869, 9, 6, 'Thực Tập Sinh Sale Xuất Nhập Khẩu', 'Nhân viên Sales-Marketing sẽ là mắt xích quan trọng trong việc phát triển mạng lưới khách hàng B2B quốc tế và thúc đẩy doanh số cho mảng kinh doanh may mặc của Tổng Công ty tại thị trường quốc tế. Các trách nhiệm chính bao gồm: Chủ động tìm kiếm và tiếp cận khách hàng B2B thông qua nhiều nền tảng: Facebook, Instagram, các sàn thương mại điện tử quốc tế và các kênh tiềm năng khác. Xây dựng nền tảng bán hàng cá nhân để đăng bài, thu hút và tương tác với khách hàng tiềm năng. Tư vấn, chăm sóc, xử lý yêu cầu và giữ kết nối sát sao với khách hàng trong suốt hành trình mua hàng: từ khi tìm hiểu, đặt mẫu, lên đơn, đến sau bán. Duy trì mối quan hệ dài hạn với khách hàng, xây dựng lòng tin và tăng khả năng mua hàng lặp lại. Tạo đơn hàng, tiếp nhận, đối chiếu hồ sơ hàng hóa để đảm bảo đúng đủ số lượng và chất lượng thực tế theo như đơn đặt hàng của khách. Quản lý, theo dõi đơn hàng, phối hợp với các bộ phận liên quan để đảm bảo khách thanh toán đủ công nợ và lịch giao nhận hàng đúng tiến độ. Thực hiện các báo cáo và chỉ số KPI mà công ty đã đề ra cũng như các yêu cầu khác từ cấp trên (theo ngày/tuần/tháng).', 'Ưu tiên các khối trường Kinh tế, Marketing có tiếng Anh giao tiếp tốt (IELTS 6.0 hoặc tương đương trở lên). Đảm bảo tối thiểu đi làm 5 buổi chiều/tuần (có thể chọn 4 buổi chiều, 1 buổi sáng), sẵn sàng phản hồi khách ngoài giờ hành chính (do lệch múi giờ).
Kỹ năng chuyên môn: [''Kỹ năng chỉnh sửa hình ảnh/video cơ bản bằng Canva, CapCut'', ''Vận hành hoặc tạo nội dung trên các nền tảng social như Facebook, Instagram'']
Kỹ năng mềm: [''Năng động'', ''Có trách nhiệm'', ''Nhiệt tình'', ''Trung thực'', ''Chủ động'', ''Chịu áp lực tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '6.0 - 8.0 triệu', 'Thứ 2 - Thứ 6 (từ 13:30 đến 18:00)', '[''Lương cứng: Từ 4 triệu VND trở lên'', ''Thưởng kinh doanh'', ''Được làm việc trong môi trường có hệ đào tạo bài bản'', ''Được làm việc trong một môi trường quốc tế chuyên nghiệp'', ''Được công ty cung cấp trà, bánh, hoa quả… free tại văn phòng'', ''Hỗ trợ dấu thực tập nếu có nhu cầu'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (870, 10, 6, 'Nhân Viên Kho', 'Thực hiện phân loại và sắp xếp hàng hoá trong kho sản phẩm là Vali, Balo, Túi xách và phụ kiện du lịch khác. Thực hiện thao tác trong quá trình nhập và xuất hàng bao gồm: dán mã tem quản lý, kiểm đếm số lượng, kiểm tra chất lượng, đóng gói sản phẩm. Thực hiện bốc xếp, lên hàng và xuống hàng khi đi theo xe tải giao hàng đến các điểm bán. Báo cáo kết quả công việc cho quản lý trực tiếp và các công việc khác theo phân công.', 'Đặc thù công việc cần sức khoẻ tốt, là lao động nam. Ưu tiên độ tuổi từ: 20 đến 30 tuổi. Trung thực, cẩn thận, chu đáo trong công việc. Thái độ hợp tác, cùng phối hợp với đồng đội để đưa ra phương án xử lý (nếu có).
Kỹ năng chuyên môn: [''Quản Lý Kho'', ''Kiểm Kê Hàng Hóa'', ''Nhận Hàng'', ''Xuất Hàng'', ''Phân Loại Hàng Hóa'', ''Vận Chuyển Hàng Hóa'']
Kỹ năng mềm: [''Trung thực'', ''Cẩn thận'', ''Chu đáo'', ''Thái độ hợp tác'']', 'PART_TIME', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'MONTHLY', 7000000.00, '7.5 triệu', 'Ca 1: 8h00-17h00, Ca 2: 13h00-22h00', '[''Chính sách lương thưởng đầy đủ, rõ ràng'', ''Thưởng cuối năm theo kết quả kinh doanh'', ''Đóng BHXH, BHYT theo quy định Nhà nước'', ''Tham gia du lịch công ty'', ''Mua hàng nội bộ với chính sách ưu đãi'', ''Nhận quà vào ngày sinh nhật'', ''Hoạt động ngoại khóa thường xuyên'', ''Được tiếp nhận đầy đủ hướng dẫn từ đồng nghiệp và quản lý'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (871, 2, 6, 'Thực Tập Sinh Chứng Từ', 'Xử lí chứng từ đơn hàng, đóng gói, xử lí nhãn mác & Theo dõi đơn hàng. Làm báo cáo theo yêu cầu của cấp trên.', 'Thực tập sinh. Siêng năng chịu khó, thành thạo tiếng anh là 1 lợi thế. Cẩn thận, tỉ mỉ trong công việc. Có lối sống lành mạnh.
Kỹ năng mềm: [''Siêng năng'', ''Chịu khó'', ''Cẩn thận'', ''Tỉ mỉ'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Được hỗ trợ làm báo cáo tốt nghiệp'', ''Đào tạo thực tập chuyên sâu thực tế về ngành logistics'', ''Xác nhận thực tập sau khi kết thúc khóa thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (872, 3, 6, 'Thực Tập Sinh Điều Phối Vận Tải', '- Nhận đơn vận chuyển hàng hóa từ các đại lý và khách hàng - Sắp xếp điều hành tài xế/shipper nội bộ công ty thực hiện các đơn hàng đảm bảo chất lượng cam kết - Điều phối năng lực vận tải bên thứ ba để bổ sung năng lực vận tải nội bộ công ty - Tối ưu hoá khai thác năng lực vận tải của công ty và các đối tác - Nghiên cứu tìm hiểu để đưa ra phương án vận tải mới hiệu quả hơn - Báo cáo số liệu hàng tuần/hàng tháng', '- Có kinh nghiệm thực tập tại các công ty vận chuyển hàng hoá/ chuyển phát là một lợi thế - Có định hướng phát triển nghề nghiệp ở các công ty Chuyển phát/ Logistic sử dụng công nghệ - Nhanh nhẹn, xử lý tình huống tốt và chủ động trong công việc - Có kỹ năng về tin học văn phòng, báo cáo
Kỹ năng chuyên môn: [''Kỹ năng tin học văn phòng'', ''Kỹ năng báo cáo'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Xử lý tình huống tốt'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00), Thứ 7 (từ 09:00 đến 17:00)', '[''Phụ cấp ăn trưa'', ''Gửi xe'', ''Được đào tạo và thực hành thực tế trong môi trường công ty thiên về ứng dụng công nghệ vào lĩnh vực vận chuyển hàng hoá'', ''Môi trường làm việc năng động, thân thiện'', ''Có cơ hội trở thành nhân viên chính thức sau thời gian thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (873, 7, 6, 'Nhân Viên Đóng Gói Hàng Hoá', 'UVGREEN là thương hiệu cung cấp các sản phẩm gia dụng, đang bán hàng trên các sàn TMĐT. Chúng tôi tìm đồng đội cùng kiểm tra - đóng gói hàng hoá để giao cho khách hàng yêu quý. Vị trí này luôn chào đón thành viên với mô hình FULL-TIME / PART-TIME / INTERNSHIP.', 'NAM từ 18-30 tuổi. Sức khỏe tốt, chịu khó, có trách nhiệm, chủ động trong công việc. Cẩn thận, tỉ mỉ, chịu được áp lực công việc. Biết sắp xếp công việc một cách hiệu quả, khoa học. Năng động, nhanh nhạy trong nắm bắt, giải quyết vấn đề. Có khả năng làm việc độc lập và làm theo nhóm. Thời gian làm việc linh động từ 9h - 18h (Thứ 2 - thứ 7) tuỳ mô hình công việc full-time / part-time / internship.
Kỹ năng mềm: [''Chịu khó'', ''Có trách nhiệm'', ''Cẩn thận'', ''Tỉ mỉ'', ''Năng động'', ''Giải quyết vấn đề'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Bảo hiểm xã hội'', ''Team building'', ''Du lịch hàng năm'', ''Thưởng tháng 13'', ''Thưởng hiệu quả làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (874, 8, 6, 'Cộng Tác Viên Đóng Gói Parttime', 'Công việc chân tay nhẹ nhàng bao gồm: Lọc lá, đóng gói trà, hoàn thiện đóng gói trà các loại lá khô. Giám sát máy đóng trà,...', 'Yêu cầu: Từ 18 tuổi trở lên. Chăm chỉ, nhiệt tình, cẩn thận, sạch sẽ. Môi trường văn minh, thân thiện và chuyên nghiệp. Ưu tiên: nhanh nhẹn, chịu khó, đã từng làm các công việc tương tự.
Kỹ năng mềm: [''Chăm chỉ'', ''Nhiệt tình'', ''Cẩn thận'', ''Sạch sẽ'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Sáng: 8h-12h, Chiều: 13h30-17h30, Tăng Ca: 17h30-19h30, Ca tối: 18h-22h', '[''Thanh toán lương vào thứ 5 hàng tuần'', ''Thử việc 7 buổi đầu lương 23k/h'', ''Làm việc trong môi trường năng động'', ''Thời gian làm việc linh hoạt'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (875, 9, 6, 'Thực Tập Sinh Kinh Doanh Quốc Tế', 'Hỗ trợ các công việc liên quan đến hoạt động kinh doanh xuất khẩu của công ty. Tham gia vào quá trình tìm kiếm và phát triển khách hàng mới trong lĩnh vực xuất khẩu. Hỗ trợ chuẩn bị và xử lý các tài liệu, hồ sơ liên quan đến giao dịch xuất khẩu. Tham gia vào quá trình đàm phán, thương lượng với khách hàng dưới sự hướng dẫn của nhân viên cấp cao. Theo dõi và cập nhật thông tin về thị trường xuất khẩu, đặc biệt trong lĩnh vực xây dựng. Hỗ trợ trong việc lập kế hoạch và thực hiện các chiến lược kinh doanh xuất khẩu.', 'Sinh viên năm 4 chuyên ngành Kinh tế, Thương mại, Kinh doanh Quốc tế hoặc liên quan. Tiếng Anh thành thạo (giao tiếp và đọc hiểu tài liệu). Có định hướng làm việc lâu dài trong lĩnh vực xuất khẩu. Năng động, cầu tiến, có tinh thần trách nhiệm cao và chủ động trong công việc.
Kỹ năng chuyên môn: [''Tiếng Anh thành thạo'']
Kỹ năng mềm: [''Năng động'', ''Cầu tiến'', ''Có tinh thần trách nhiệm cao'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '3.0 - 10.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Hỗ trợ lương thực tập: 3.000.000 VNĐ/tháng + thưởng theo hiệu suất'', ''Cơ hội trở thành nhân viên chính thức sau thực tập'', ''Được đào tạo bài bản về nghiệp vụ và kỹ năng xuất khẩu thực tế'', ''Cơ hội đi công tác trong và ngoài nước'', ''Môi trường làm việc chuyên nghiệp, năng động, có định hướng quốc tế'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (876, 10, 6, 'CTV Nhập Đơn Hàng', 'Nhặt đơn hàng mỹ phẩm khách đặt hàng từ facebook, tiktok của Công ty; Nhập thông tin số liệu, kiểm duyệt đơn hàng; Đăng đơn, in đơn hàng. Thực hiện các công việc phát sinh khác theo sự phân công của trưởng nhóm.', 'Có laptop cá nhân để làm việc; Tin học văn phòng cơ bản; Nhanh nhẹn, ham học hỏi; Ưu tiên sinh viên.
Kỹ năng chuyên môn: [''Tin học văn phòng cơ bản'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '6.0 - 8.0 triệu', '8h30 – 17h30 (Nghỉ trưa 12h-13h15)', '[''200k/ngày + phụ cấp ăn trưa 30k/ngày'', ''Được đào tạo bài bản'', ''Có lộ trình thăng tiến rõ ràng'', ''Môi trường năng động, chuyên nghiệp, chủ động sáng tạo'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (877, 2, 6, 'Thực Tập Sinh Hải Quan', 'Chuẩn bị hồ sơ kê khai hải quan. Tiến hành thủ tục khai báo nháp tờ khai hải quan. Nhận báo giá và thông tin có liên quan khác từ bộ phận phát triển kinh doanh và chăm sóc khách hàng. Nhận yêu cầu dịch vụ và hồ sơ lô hàng từ khách hàng. Trao đổi nhằm làm rõ thông tin, yêu cầu (nếu có). Căn cứ quy định của pháp luật, tập quán thương mại để thực hiện các công việc dưới đây: Tư vấn cho khách hàng về quy trình thủ tục của lô hàng/ yêu cầu. Kiểm tra tính hợp pháp, hợp lệ, đầy đủ, chính xác của hồ sơ do khách hàng cung cấp. Đề nghị khách hàng điều chỉnh, bổ sung thêm các loại chứng từ và/hoặc thông tin trên hồ sơ. Thu thập từ khách hàng bộ hồ sơ hoàn chỉnh để thực hiện dịch vụ.', '1. Học vấn: Sinh viên năm cuối học từ Cao đẳng trở lên 2. Khác: Nhiệt tình, chịu khó - Ưu tiên ứng viên có khả năng sử dụng Excel tốt
Kỹ năng chuyên môn: [''Excel'']
Kỹ năng mềm: [''Nhiệt tình'', ''Chịu khó'']', 'INTERNSHIP', 'ONSITE', 'hải phòng', 'Hải Phòng', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7: 8:00-12:00 (làm 2 sáng thứ 7/tháng)', '[''Hỗ trợ xe bus đưa đón từ nội thành (Đường Lê Hồng Phong)'', ''Hỗ trợ cơm trưa tại công ty'', ''Hỗ trợ tiền thực tập sinh 2 triệu đồng/tháng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (878, 3, 6, 'Management Trainee', 'Vị trí: Management Trainee – Chuỗi Cung ứng - Sourcing Thời gian: Tối thiểu 6 tháng Thu nhập: 2.500.000 – 3.500.000 VND/tháng Báo cáo & Hướng dẫn: Anh Chị quản lý Bộ phận Cung ứng Đây không chỉ là thực tập – đây là hành trình để bạn: - Hiểu chuỗi cung ứng thực tế từ đơn hàng đến sản xuất, vận chuyển, kiểm hàng – trong một doanh nghiệp xuất khẩu B2B toàn cầu. - Trực tiếp tham gia vào các dự án tối ưu hóa dữ liệu, vận hành, chất lượng nhà cung cấp, quy trình đặt hàng – giao hàng. - Sử dụng các nền tảng công nghệ (Base.vn – Google Workspace – Airtable ...) để làm việc bài bản – khoa học – số hóa.', 'Bạn phù hợp nếu: - Là sinh viên năm 3 – năm cuối hoặc mới tốt nghiệp các ngành: Logistics, Kinh tế, Quản trị chuỗi cung ứng, Quản trị kinh doanh... - Cẩn thận, có tư duy hệ thống, yêu thích dữ liệu và quy trình. - Biết dùng AI, Google Sheets, ưu tiên có kinh nghiệm với Notion / Base / các hệ thống vận hành khác. - Có tinh thần trách nhiệm, muốn học để làm – không ngại va chạm thực tế. - Sẵn sàng đồng hành 6–9 tháng để trưởng thành rõ rệt về tư duy và kỹ năng.
Kỹ năng chuyên môn: [''Google Sheets'', ''AI (ChatGPT)'', ''Notion'', ''Base.vn'']
Kỹ năng mềm: [''Cẩn thận'', ''Tư duy hệ thống'', ''Tinh thần trách nhiệm'', ''Yêu thích dữ liệu và quy trình'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được hướng dẫn bởi các anh/chị có kinh nghiệm'', ''Cơ hội trở thành nhân sự chính thức nếu phù hợp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (879, 7, 6, 'Thực Tập Sinh Chứng Từ', 'Tùy theo sự phù hợp, được đào tạo và thực hành 1 trong các vị trí công việc: Thực tập sinh khai báo hải quan, Thực tập sinh chứng từ hàng xuất sea, Thực tập sinh giao nhận hiện trường.', 'Có kiến thức cơ bản về ngành logistics, học theo các chuyên ngành: logistics, xuất nhập khẩu, kinh tế ngoại thương,... Có thể đi thực tập fulltime. Mong muốn học hỏi, trau dồi kiến thức/kỹ năng. Chăm chỉ, cẩn thận, nhanh nhẹn, hòa đồng, tinh thần trách nhiệm cao. Chịu được áp lực công việc.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel)'']
Kỹ năng mềm: [''Chăm chỉ'', ''Cẩn thận'', ''Nhanh nhẹn'', ''Hòa đồng'', ''Tinh thần trách nhiệm cao'', ''Chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'hải phòng', 'Hải Phòng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Được đào tạo, trau dồi kĩ năng lĩnh vực xuất nhập khẩu, logistics'', ''Môi trường làm việc chuyên nghiệp, năng động'', ''Cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (880, 8, 6, 'Cung cấp thực tập', 'Hướng dẫn lập kế hoạch sản xuất, đảm bảo tồn kho và khả năng cung ứng thành phẩm dựa trên kế hoạch nhu cầu & đơn đặt hàng. Xây dựng & tối ưu chính sách tồn kho an toàn cho thành phẩm (TP), bán thành phẩm (BTP), nguyên vật liệu (NVL). Thực hiện các công việc theo sự sắp xếp của quản lý.', 'Sinh viên năm cuối hoặc đã tốt nghiệp từ Cao đẳng trở lên ngành Quản lý Công nghiệp, Kế toán, Kinh tế hoặc các chuyên ngành có liên quan. Có kiến thức về công việc kế hoạch điều độ, quy trình chuỗi cung ứng, kiểm soát tồn kho. Có năng lực về thống kê và phân tích dữ liệu.
Kỹ năng chuyên môn: [''Kiến thức về công việc kế hoạch điều độ'', ''Quy trình chuỗi cung ứng'', ''Kiểm soát tồn kho'', ''Thống kê'', ''Phân tích dữ liệu'']
Kỹ năng mềm: [''Làm việc nhóm'', ''Quản lý thời gian'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:15)', '[''Trợ cấp thực tập 5.000.000đ'', ''Tham gia BHXH theo quy định của pháp luật'', ''Cung cấp ăn trưa tại nhà ăn'', ''Đào tạo các kỹ năng chuyên môn theo khóa học nội bộ'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (881, 9, 6, 'TTS Kinh Doanh Quốc Tế/Sales Export Intern', 'Đây là một vai trò toàn thời gian tại chỗ cho một thực tập sinh kinh doanh quốc tế ở Hà Nội. Thực tập sinh kinh doanh quốc tế sẽ chịu trách nhiệm về các nhiệm vụ như sau: duy trì mức độ cao của sản phẩm, thị trường, kiến ​​thức của đối thủ cạnh tranh để giải quyết hiệu quả các câu hỏi và mối quan tâm của khách hàng. Tiếp cận với khách hàng mới, mở rộng cơ sở dữ liệu khách hàng trên thị trường quốc tế. Theo dõi với doanh số tiềm năng dẫn đến việc nuôi dưỡng các mối quan hệ và bán hàng gần. Phối hợp với nhóm bán hàng để phát triển và thực hiện các kế hoạch bán hàng hiệu quả. Báo cáo công việc hàng tuần cho Trưởng nhóm/Quản lý. Các nhiệm vụ khác theo sự phân công của người quản lý.', 'Final year students or recent graduates with the ability to work full time. Ability to organize work and work well in groups. Good communication, negotiation, persuasion and presentation skills. "Can do" attitude, willing to accept challenges and find solutions. Proficient in English in 4 skills (with English certificate). Having second foreign language is an advantage.
Kỹ năng chuyên môn: [''Proficient in English in 4 skills'']
Kỹ năng mềm: [''Good communication'', ''Negotiation'', ''Persuasion'', ''Presentation'', ''Ability to organize work'', ''Teamwork'', ''Can do attitude'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 08:30 đến 12:00)', '[''Fixed salary with bonus when completing orders'', ''Dynamic and professional working environment'', ''Trained in in-depth knowledge of import and export'', ''Clear training roadmap, capable of becoming an official employee'', ''Participate in extracurricular activities, Teambuilding quarterly and annually'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (882, 10, 6, 'Merchandising Intern', 'Nhóm hỗ trợ thu thập và kiểm tra các tài liệu liên quan đến sản phẩm. Hỗ trợ trong việc tạo báo cáo, phân tích dữ liệu. Hỗ trợ và thực hiện các nhiệm vụ theo sự phân công của người quản lý và các thành viên khác của bộ phận.', 'Senior students of colleges and universities. Major in economics/supply chain is preferred. Good skills in Microsoft Office (Excel, PowerPoint, Word). Hardworking and eager to learn. Proactive, careful and detail-oriented.
Kỹ năng chuyên môn: [''Good skills in Microsoft Office (Excel, PowerPoint, Word)'']
Kỹ năng mềm: [''Hardworking'', ''Eager to learn'', ''Proactive'', ''Careful'', ''Detail-oriented'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Issuance of internship certificate'', ''Lunch support at the canteen'', ''Laptop support during work'', ''Experience, study and work at a multinational corporation'', ''Support in arranging appropriate study & work time'', ''Shuttle bus support for those living far away'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (883, 2, 6, 'Nhân Viên Mua Hàng', 'Tiếp nhận và xử lý yêu cầu mua hàng từ các bộ phận liên quan. Tìm kiếm, đánh giá và đề xuất nhà cung cấp phù hợp theo từng danh mục: In ấn & POSM, quà tặng khuyến mãi... Theo dõi và quản lý quy trình mua hàng – thanh toán đảm bảo đúng tiến độ và tuân thủ quy trình. Phối hợp với các phòng ban liên quan để giải quyết các vấn đề phát sinh trong quá trình mua sắm. Hỗ trợ xử lý các vấn đề liên quan đến hệ thống mua hàng. Đảm bảo việc thực hiện mua hàng tuân thủ đúng chính sách công ty và quy định nội bộ.', 'Có từ 1 năm kinh nghiệm trong lĩnh vực mua hàng hoặc vị trí tương đương. Ưu tiên ứng viên từng làm việc với hệ thống mua hàng. Kỹ năng đàm phán tốt, tư duy độc lập và tinh thần hợp tác cao. Chủ động trong giải quyết vấn đề, giao tiếp cởi mở và sẵn sàng học hỏi. Kỹ năng quản lý thời gian và xử lý công việc hiệu quả.
Kỹ năng chuyên môn: [''Kỹ năng đàm phán'', ''Quản lý thời gian'', ''Giải quyết vấn đề'']
Kỹ năng mềm: [''Tư duy độc lập'', ''Tinh thần hợp tác'', ''Giao tiếp cởi mở'', ''Sẵn sàng học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Tham gia đầy đủ BHXH full lương'', ''BHYT'', ''BHTN theo quy định'', ''Môi trường làm việc chuyên nghiệp'', ''Được đào tạo, hướng dẫn nghiệp vụ'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (884, 3, 6, 'Nhân Viên Kho (Đóng Gói) Part-Time', 'Kiểm tra chất lượng (QC) và đóng gói sản phẩm. Các công việc đều được hướng dẫn cụ thể, rõ ràng. Đóng gói sản phẩm, hàng hóa theo tiêu chuẩn, quy định của công ty. Vệ sinh khu vực đóng gói trước và sau khi thực hiện công việc, đảm bảo sạch sẽ, gọn gàng. Kiểm tra quản lý kho hàng, hàng hóa. Báo cáo mỗi ngày. Thực hiện các công việc khác theo hướng dẫn.', 'Trung thực, siêng năng, nhanh nhẹn và nhiệt tình trong công việc. Cẩn thận, chi tiết trong công việc. Có trách nhiệm. Có kinh nghiệm đóng gói là lợi thế.
Kỹ năng mềm: [''Trung thực'', ''Siêng năng'', ''Nhanh nhẹn'', ''Nhiệt tình'', ''Cẩn thận'', ''Chi tiết'', ''Có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.5 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 12:30) và (từ 13:30 đến 17:30)', '[''Thu nhập hấp dẫn: từ 3,500,000VNĐ - 5,000,000VNĐ/tháng (lương 25.000đ/giờ)'', ''Công việc được hướng dẫn chi tiết'', ''Môi trường trẻ trung, năng động, vui vẻ'', ''Làm việc văn phòng máy lạnh'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (885, 7, 6, 'Nhân Viên Nhập Liệu Part-Time', 'Công việc chính tạo bill điện tử và nhập liên trắng. Nhập liệu thông tin lên hệ thống, báo cáo tổng số lượng nhập được, đóng gói, giao nhận hàng hóa... Thực hiện các công việc khác theo yêu cầu của cấp trên.', 'Sinh viên các trường cao đẳng, đại học. Có khả năng đánh máy tính tốt; cẩn thận. Tuân thủ quy định, đi làm đúng giờ, nhà gần công ty là 1 lợi thế.
Kỹ năng chuyên môn: [''Khả năng đánh máy tính tốt'']
Kỹ năng mềm: [''Cẩn thận'', ''Tuân thủ quy định'', ''Đi làm đúng giờ'']', 'PART_TIME', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 17:30 đến 21:30)', '[''Môi trường làm việc thân thiện, không áp lực'', ''Được cung cấp thiết bị làm việc'', ''Được hướng dẫn, chỉ bảo công việc chi tiết đến khi làm quen'', ''Thưởng hiệu quả làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (886, 8, 1, 'Đảm bảo chất lượng/ kiểm soát chất lượng thực tập', 'Hỗ trợ nhận và phân tích các yêu cầu của khách hàng và dự án. Hỗ trợ chuẩn bị các tài liệu kiểm tra, danh sách kiểm tra và hướng dẫn người dùng. Tạo các trường hợp kiểm tra toàn diện và kịch bản kiểm tra dựa trên các yêu cầu của dự án. Thực hiện kiểm tra thủ công để xác định các lỗi phần mềm và đảm bảo chức năng hệ thống. Log và theo dõi các khiếm khuyết bằng cách sử dụng các công cụ quản lý khuyết tật (JIRA, Trello, v.v.). Hỗ trợ báo cáo kiểm tra, đánh giá rủi ro chất lượng và cập nhật tiến độ cho các nhóm và khách hàng nội bộ. Hỗ trợ kiểm tra chấp nhận người dùng (UAT) và xác thực sau triển khai khi cần thiết. Đóng góp ý tưởng để cải thiện quá trình thử nghiệm.', 'Final-year students or recent graduates are available for a full-time internship. Strong logical and critical thinking and attention to detail. Good time management and organizational skills. English proficiency is a plus. Eager to learn and grow in the QA field.
Kỹ năng chuyên môn: [''JIRA'', ''Trello'']
Kỹ năng mềm: [''Logical thinking'', ''Critical thinking'', ''Attention to detail'', ''Time management'', ''Organizational skills'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Allowance: 3,000,000 VND/month'', ''Social insurance'', ''Health insurance'', ''Unemployment insurance'', ''Annual team-building activities'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (887, 9, 1, 'Bán thực tập - làm việc từ xa - thời gian linh hoạt', 'Chúng tôi đào tạo một thế hệ chuyên gia bán hàng mới - được trang bị các kỹ năng, công cụ và tư duy toàn cầu để mang lại các sản phẩm có tác động như Volta cho khách hàng Úc. Trong quá trình thực tập, bạn sẽ được đào tạo thực hành về bán hàng, tiếp thị, tham gia khách hàng và nền tảng công nghệ-chuẩn bị cho bạn tự tin bán và giải pháp thực sự trong một thị trường toàn cầu.', 'Basic English skills (able to read documents, communication is a plus). A genuine passion for sales, business, and working with people. Goal-oriented, with a clear career path and strong desire to grow in the sales field. Strong interpersonal skills, proactive attitude, and a hands-on, can-do mindset. Open to students of all majors and years – as long as you’re eager to grow.
Kỹ năng mềm: [''Strong interpersonal skills'', ''Proactive attitude'', ''Goal-oriented'']', 'INTERNSHIP', 'ONSITE', 'cần thơ', 'Cần Thơ', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 07:30 đến 17:00)', '[''3-month training program'', ''Professional growth'', ''Global experience'', ''Flexible schedule & remote-friendly'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (888, 10, 1, 'Nhà phát triển PHP thực tập (WordPress)', 'Chúng tôi đang tìm kiếm một thực tập sinh của nhà phát triển web, người đam mê phát triển PHP và WordPress. Bạn sẽ làm việc chặt chẽ với nhóm web của chúng tôi để hỗ trợ các tác vụ phát triển, bảo trì và tối ưu hóa trang web - chủ yếu sử dụng WordPress. Trách nhiệm: Hỗ trợ phát triển và tùy chỉnh các trang web bằng WordPress và PHP. Hỗ trợ xây dựng hoặc sửa đổi các chủ đề và plugin. Làm việc với HTML, CSS, JavaScript để thực hiện các cải tiến UI/UX. Khắc phục sự cố và khắc phục các lỗi nhỏ hoặc các vấn đề bố cục. Hỗ trợ cập nhật nội dung và kiểm tra cho các trang web. Hợp tác với các nhà thiết kế, nhà văn nội dung và nhà phát triển khi cần thiết.', 'Final year student or recent graduate majoring in Information Technology. Full-time internship and work full time after internship. Basic knowledge of PHP and WordPress. Familiar with HTML, CSS, and JavaScript. Eagerness to learn and improve coding skills. Responsible, detail-oriented, and a team player. Excellent problem-solving skills, a meticulous attention to detail, and a logical approach to challenges. Strong communication and teamwork skills, with a proactive and eager-to-learn attitude. Ability to commit to a full-time internship schedule. (Optional but nice to have) Experience with Git, Figma.
Kỹ năng chuyên môn: [''PHP'', ''WordPress'', ''HTML'', ''CSS'', ''JavaScript'']
Kỹ năng mềm: [''Eagerness to learn'', ''Responsible'', ''Detail-oriented'', ''Team player'', ''Excellent problem-solving skills'', ''Strong communication skills'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '4.2 - 6.9 triệu', 'Monday - Friday (from 08:00 to 17:00)', '[''Attractive Intern salary'', ''Motorbike or bus support allowance'', ''Professional and challenge working environment'', ''Japanese culture and working atmosphere discovery'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (889, 2, 1, 'Thực Tập Sinh PHP (Sinh Viên Năm Cuối, Backend)', '_Quy trình tuyển dụng:_ [1] Screen CV => [2] Test chuyên môn (Offline) => [3] Phỏng vấn (Offline) _Nội dung công việc:_ - Tuỳ theo nhu cầu dự án tại từng thời điểm hiện tại, công ty sẽ đào tạo những ngôn ngữ lập trình khác nhau và các kỹ thuật mới nhất, cụ thể như:+ Ngôn ngữ lập trình PHP với các framework phiên bản mới nhất.+ Kỹ thuật về OOP, PHP Basic, Database, ...+ Frontend và các framework như Vuejs, Reactjs, ...- Nắm bắt nghiệp vụ phân tích để phát triển hệ thống trên nền web cùng với các kỹ sư tại Việt Nam và tại Nhật Bản.', '_Yêu cầu:_ - Sinh viên đang học năm cuối các ngành Khoa học máy tính, Công nghệ phần mềm tại các trường Đại Học và có kết quả học tập loại khá trở lên. - Có thể tham gia thực tập tại công ty từ 6 – 10 buổi / tuần ( tương đương 3 – 5 ngày/ tuần). - Có hiểu biết hoặc đã tìm hiểu về lập trình website mà có sử dụng một trong các ngôn ngữ lập trình PHP, Java, .Net (C#,VB.NET), NodeJS. - Nắm vững kiến thức về SQL Query. - Giao tiếp tốt, chủ động trong công việc. - Có đam mê phát triển phần mềm. - Có kỹ năng làm việc theo nhóm, hòa đồng. - Có tư duy logic, sáng tạo.
Kỹ năng chuyên môn: [''PHP'', ''MySQL'', ''Java'', ''.Net'', ''NodeJS'', ''SQL Query'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Chủ động trong công việc'', ''Kỹ năng làm việc theo nhóm'', ''Hòa đồng'', ''Tư duy logic'', ''Sáng tạo'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Công ty sẽ quyết định ký HĐLĐ nếu đánh giá sinh viên đủ năng lực sau thời gian thực tập 2 tháng.'', ''Mức trợ cấp thực tập tại công ty: 100,000 VND/ngày.'', ''Bữa trưa chào mừng nhân viên mới.'', ''Thời gian thực tập linh động phù hợp với lịch học của sinh viên.'', ''Được tham gia vào dự án phần mềm thực tế cùng các kỹ sư có kinh nghiệm và chuyên môn cao.'', ''Môi trường làm việc chuyên nghiệp.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (890, 3, 1, 'Thực Tập Sinh Front-End', 'Thực tập sinh sẽ được đào tạo theo các gia đoạn sau: • Giai đoạn 1: Đào tạo kiến thức cơ bản về lập trình • Giai đoạn 2: Đào tạo chuyên sâu về một trong các framework được sử dụng để xây dựng và phát triển các ứng dụng • Giai đoạn 3: Tham gia vào các dự án thực tế của công ty gồm các công việc của một thực tập sinh trong dự án: + Phát triển chức năng từ đơn giản đến phức tạp + Phát tiển các kỹ năng làm việc nhóm, các kỹ năng trao đổi và phân tích yêu cầu + Được review code bởi các kỹ sư có kinh nghiệm giúp phát triển các kỹ năng code.', '• Sinh viên năm cuối các trường ĐH Bách Khoa, HV Bưu Chính, Viễn Thông, ĐH Công Nghệ, ĐH Khoa học tự nhiên. • Có định hướng và yêu thích, đam mê lập trình • Khả năng tư duy, tìm tòi, học hỏi nhanh, làm việc độc lập, chủ động trong công việc
Kỹ năng chuyên môn: [''CSS'']
Kỹ năng mềm: [''Khả năng tư duy'', ''Tìm tòi'', ''Học hỏi nhanh'', ''Làm việc độc lập'', ''Chủ động trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '1.5 - 5.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường chuyên nghiệp, năng động, sáng tạo.'', ''Cơ hội học hỏi và làm việc với những con người năng động, nhiệt huyết, giàu kinh nghiệm.'', ''Cơ hội tham gia các dự án thực tế của Công ty.'', ''Cung cấp kiến thức và kỹ năng làm việc chuyên nghiệp.'', ''Trợ cấp thực tập theo Level, trợ cấp ăn trưa, gửi xe.'', ''Cơ hội trở thành nhân viên chính thức của Công ty.'', ''Xác nhận và nhận xét tốt khi hoàn thành nhiệm vụ được phân công.'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (891, 7, 1, 'Thực Tập Lập Trình Backend (Webhook, Automation)', '1. Thiết kế & triển khai Automation: Thiết lập và tối ưu luồng Automation trên hệ thống CNV CDP. Vận hành thử, đảm bảo hoạt động chính xác trước khi bàn giao. 2. Tích hợp hệ thống & xử lý dữ liệu: Kết nối, đồng bộ dữ liệu với CRM, POS, ERP qua API/Webhook. Kiểm tra hiệu suất luồng, đảm bảo hệ thống hoạt động ổn định. 3. Giám sát & cải tiến: Theo dõi, debug luồng Automation, khắc phục lỗi nhanh chóng. Đề xuất giải pháp nâng cấp, tối ưu quy trình.', 'Có kiến thức về API, Webhook, JSON, JavaScript, Python, Appscript, Postman. Có tư duy logic, khả năng phân tích và giải quyết vấn đề tốt. Sinh viên năm 3, 4 hoặc mới tốt nghiệp chuyên ngành: Công nghệ thông tin, Khoa học máy tính, Kỹ thuật phần mềm,...
Kỹ năng chuyên môn: [''API'', ''Webhook'', ''JSON'', ''JavaScript'', ''Python'', ''Appscript'', ''Postman'']
Kỹ năng mềm: [''Tư duy logic'', ''Khả năng phân tích'', ''Giải quyết vấn đề'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 (từ 09:00 đến 16:00)', '[''Thưởng theo hiệu quả công việc và các dịp lễ, tết'', ''Cơ hội trở thành nhân viên chính thức'', ''Tham gia các khóa đào tạo nâng cao kỹ năng chuyên môn'', ''Các hoạt động team building, du lịch hàng năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (892, 8, 1, 'Thực Tập Sinh Lập Trình Viên', 'Phân tích yêu cầu và thiết kế hệ thống phần mềm. Phát triển và bảo trì các ứng dụng web và mobile. Viết code sạch, hiệu quả và dễ bảo trì. Thực hiện các bài test đơn vị và tích hợp. Cộng tác với các thành viên khác trong nhóm để hoàn thành dự án. Tham gia vào các cuộc họp và thảo luận về kỹ thuật. Học hỏi và cập nhật kiến thức công nghệ mới. Có khả năng làm việc độc lập và làm việc nhóm. Có khả năng giải quyết vấn đề và đưa ra các giải pháp hiệu quả. Có tinh thần trách nhiệm cao và cam kết với công việc.', 'Có kiến thức cơ bản về các ngôn ngữ lập trình như Java, Python, PHP, Ruby on Rails, Node.js, React, Angular, Vue.js, ... (ít nhất 1 ngôn ngữ backend và 1 ngôn ngữ frontend). Và các cơ sở dữ liệu như MySQL, PostgreSQL, MongoDB, ... Có kiến thức về các framework và thư viện phổ biến, kiến trúc phần mềm, thiết kế mô hình dữ liệu. Có khả năng làm việc độc lập và làm việc nhóm. Có khả năng giải quyết vấn đề và đưa ra các giải pháp hiệu quả. Có tinh thần trách nhiệm cao và cam kết với công việc. Có khả năng giao tiếp tốt và làm việc hiệu quả trong môi trường năng động. Có khả năng đọc hiểu tài liệu tiếng Anh (hoặc tiếng Nhật thì càng tốt)
Kỹ năng chuyên môn: [''Java'', ''Python'', ''PHP'', ''Ruby on Rails'', ''Node.js'', ''React'', ''Angular'', ''Vue.js'', ''MySQL'', ''PostgreSQL'', ''MongoDB'']
Kỹ năng mềm: [''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Khả năng giải quyết vấn đề'', ''Tinh thần trách nhiệm'', ''Khả năng giao tiếp'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Môi trường làm việc năng động và chuyên nghiệp'', ''Được đào tạo và phát triển kỹ năng chuyên môn'', ''Chế độ phúc lợi tốt theo quy định của pháp luật'', ''Cơ hội thăng tiến và phát triển nghề nghiệp'', ''Tham gia các hoạt động team building'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (893, 9, 1, 'Dev Fullstack Web App Tài Chính Tích Hợp AI', 'Xây dựng app AI Quản lý Tài chính Đầu tư, Tích hợp AI chạy trên Web, Android, IOS với các module tính năng cơ bản như Chatbot AI tư vấn User, quản lý thu chi, tài sản cá nhân, ngân sách, tích hợp AI tư vấn, quản lý dự án kinh doanh, quản lý công việc hàng ngày, và nhiều hơn nữa.', 'Thành thạo Codecanyon / custom source code, Thành thạo AI trí tuệ nhân tạo + kiến thức tài chính cơ bản, Ít nhất 2 năm kinh nghiệm làm việc như một Fullstack Developer, Thành thạo PHP / Flutter / React..., Có khả năng làm việc độc lập và theo nhóm, Khả năng giải quyết vấn đề và tư duy logic tốt, Khả năng giao tiếp và làm việc hiệu quả với các nhóm khác nhau.
Kỹ năng chuyên môn: [''PHP'', ''Flutter'', ''React'', ''AI trí tuệ nhân tạo'', ''Codecanyon'', ''custom source code'']
Kỹ năng mềm: [''Khả năng làm việc độc lập'', ''Khả năng làm việc theo nhóm'', ''Khả năng giải quyết vấn đề'', ''Tư duy logic'', ''Khả năng giao tiếp'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Cơ hội phát triển nghề nghiệp'', ''Các chế độ phúc lợi theo quy định của pháp luật'', ''Các hoạt động team building thường xuyên'', ''Có thể làm việc tại nhà / remote từ xa'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (894, 10, 1, 'Thực Tập Sinh Thiết Kế Đồ Họa', 'Thực tập thiết kế dựa trên các sản phẩm của công ty như: Các mẫu thiết kế in trên áo thun, Các thiết kế quảng cáo cho công ty, Thiết kế và quản lý website của công ty. Hỗ trợ các bộ phận khác khi cần thiết.', 'Sinh viên tốt nghiệp chuyên ngành Thiết kế đồ họa và các chuyên ngành có liên quan. Sử dụng tốt các phần mềm thiết kế: Adobe Illustrator, Photoshop. Nhiệt tình, năng động, chịu được áp lực và có trách nhiệm với công việc. Có tinh thần học hỏi và biết lắng nghe. Ưu tiên và tạo điều kiện cho các bạn sinh viên năm 4 các trường ĐH / CĐ hoặc học nghề ngành thiết kế đồ họa, thiết kế thời trang... Biết vẽ tay là một lợi thế.
Kỹ năng chuyên môn: [''Adobe Illustrator'', ''Photoshop'']
Kỹ năng mềm: [''Nhiệt tình'', ''Năng động'', ''Chịu được áp lực'', ''Có trách nhiệm với công việc'', ''Có tinh thần học hỏi'', ''Biết lắng nghe'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Toàn thời gian', '[''Được xác nhận thực tập theo yêu cầu của trường'', ''Môi trường làm việc năng động, thân thiện'', ''Được training nâng cao kỹ năng nghề nghiệp'', ''Được hỗ trợ định hướng nghề nghiệp và các kỹ năng mềm'', ''Có cơ hội làm việc và gắn bó lâu dài với Công ty'', ''Phụ cấp, thưởng theo hiệu quả công việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (895, 2, 1, 'Thực Tập Sinh Video Editor', 'Lên ý tưởng và làm video quảng cáo app mobile; Cắt ghép các video giới thiệu app, các video phục vụ cho team Marketing,... Chỉnh sửa , biên tập video theo kế hoạch đã lên. Phối hợp với team Marketing để dựng video theo kịch bản có sẵn. Nghiên cứu thị trường và các xu hướng mới của đối thủ trên nền tảng. Các công việc khác được Leader phân công.', 'Ưu tiên sinh viên năm cuối hoặc đã tốt nghiệp Cao đẳng/đại học chuyên ngành có liên quan. Ưu tiên ứng viên có thể đi làm full-time. Sử dụng thành thạo bất kỳ phần mềm chỉnh sửa video nào: Adobe Premiere, Capcut... Kinh nghiệm ghép âm thanh và tìm kiếm âm thanh. Hoàn thành deadline chính xác. Kỹ năng làm việc nhóm. Có trách nhiệm, đam mê, sáng tạo, chi tiết, cẩn thận.
Kỹ năng chuyên môn: [''Adobe Premiere'', ''Capcut'']
Kỹ năng mềm: [''Kỹ năng làm việc nhóm'', ''Có trách nhiệm'', ''Đam mê'', ''Sáng tạo'', ''Chi tiết'', ''Cẩn thận'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 12:00, từ 13:30 đến 18:00)', '[''Cơ hội trở thành nhân viên chính thức'', ''Review năng lực hàng năm'', ''Lương tháng 13'', ''Chế độ sinh nhật, sinh con, hiếu hỷ, ngày lễ'', ''12 phép/năm'', ''Hỗ trợ 100% vé tháng gửi xe'', ''Teambuilding, du lịch nghỉ mát hàng năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (896, 3, 1, 'Thực Tập Sinh Kinh Doanh', 'Hỗ trợ các nhân viên kinh doanh trong việc tìm kiếm và chăm sóc khách hàng tiềm năng. Tham gia vào quá trình xây dựng và thực hiện các chiến lược kinh doanh của công ty. Hỗ trợ phân tích thị trường và đối thủ cạnh tranh trong lĩnh vực tài chính, thanh toán. Tham gia các buổi họp nội bộ và gặp gỡ khách hàng để học hỏi kinh nghiệm. Hỗ trợ chuẩn bị tài liệu bán hàng, báo giá và hợp đồng. Tham gia vào quá trình đàm phán và chốt các thỏa thuận kinh doanh dưới sự hướng dẫn của mentor. Hỗ trợ theo dõi và báo cáo các chỉ số kinh doanh quan trọng.', 'Không yêu cầu kinh nghiệm làm việc trước đây. Đang là sinh viên năm cuối hoặc mới tốt nghiệp các ngành liên quan đến Kinh tế, Tài chính, Quản trị kinh doanh, Marketing. Có kiến thức cơ bản về kinh doanh, bán hàng và tài chính. Kỹ năng giao tiếp tốt, có khả năng thuyết trình và đàm phán. Thái độ tích cực, năng động và sẵn sàng học hỏi. Kỹ năng sử dụng các công cụ MS Office (Word, Excel, PowerPoint). Ưu tiên ứng viên có hiểu biết về lĩnh vực tài chính, kinh doanh, công nghệ. Có khả năng làm việc độc lập và làm việc nhóm hiệu quả. Có tư duy phân tích và giải quyết vấn đề tốt.
Kỹ năng chuyên môn: [''Kỹ năng sử dụng các công cụ MS Office (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Có khả năng thuyết trình và đàm phán'', ''Thái độ tích cực'', ''Năng động'', ''Sẵn sàng học hỏi'', ''Có khả năng làm việc độc lập và làm việc nhóm hiệu quả'', ''Có tư duy phân tích và giải quyết vấn đề tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Được đào tạo chuyên sâu về kỹ năng bán hàng, kinh doanh và quy trình làm việc chuyên nghiệp'', ''Cơ hội được làm việc trong môi trường năng động, chuyên nghiệp'', ''Được tiếp xúc với các dự án thực tế và khách hàng lớn trong ngành'', ''Nhận được sự hướng dẫn trực tiếp từ các chuyên gia có kinh nghiệm trong lĩnh vực'', ''Cơ hội được chuyển đổi thành nhân viên chính thức sau khi hoàn thành xuất sắc chương trình thực tập'', ''Được tham gia các hoạt động nội bộ, teambuilding của công ty'', ''Được cấp giấy chứng nhận sau khi hoàn thành chương trình thực tập'', ''Hỗ trợ chi phí đi lại (nếu có)'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (897, 7, 1, 'Thực Tập Sinh Chăm Sóc Khách Hàng', 'Xử lý khiếu nại, bảo hành, đơn hoàn, đơn giao lại,... Hỗ trợ làm việc với đơn vị vận chuyển, giải quyết đơn hoàn, đơn giao trễ,... Xác nhận đơn website (khách hàng đã chốt đơn, chỉ hỗ trợ lên đơn, gọi xác nhận lại thông tin) Hỗ trợ trực page tư vấn khách hàng (nếu có) Các công việc đều được Leader hướng dẫn chi tiết, quy trình đào tạo bài bản.', 'Không yêu cầu kinh nghiệm. Trung thực, trách nhiệm, nhanh nhẹn. Thao tác máy tính tốt, thành thạo tin học văn phòng. Thời gian làm việc: Tối thiểu 5 ca/tuần, có ca ngày và ca tối để các bạn đăng ký. Ca ngày: 8:00 - 17:00. Ca tối: 17:00 - 23:00.
Kỹ năng chuyên môn: [''Thao tác máy tính tốt'', ''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Trung thực'', ''Trách nhiệm'', ''Nhanh nhẹn'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Tối thiểu 5 ca/tuần, có ca ngày và ca tối', '[''Được offer lên vị trí Full-time nếu phù hợp với công việc'', ''Hỗ trợ dấu mộc thực tập và nhận xét khi ứng viên cần'', ''Được cung cấp các khoá học liên quan đến Kinh Doanh, Tư vấn, Marketing'', ''Được chính Leader có nhiều năm kinh nghiệm hướng dẫn'', ''Được đào tạo các công cụ làm việc nhóm và quản lý công việc hiệu quả'', ''Được làm việc trong môi trường chuyên nghiệp, năng động, thân thiện'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (898, 8, 1, 'Nhân Viên Kiểm Soát (Unity/Godot/Unreal)', '• Kiểm soát các nội dung cơ bản trong game • Nội dung kiểm tra liên quan đến dữ liệu số, biết lập trình Unity hoặc engine tương tự • Báo cáo lỗi bằng cách sử dụng các công cụ theo dõi lỗi. • Hỗ trợ các thử nghiệm khác nhau, xem xét các kế hoạch và công việc, đã từng làm game hoặc demo cá nhân • Rà soát dự án. • Viết tình huống kiểm tra lỗi. • Kiểm soát nội dung mới và quan trọng. • Kiểm soát sản phẩm trả phí và tính khả thi • Kiểm soát theo các tiêu chí đánh giá trên nền tảng iOS / Android • Kiểm soát quá trình đối chiếu. • Quản lý và phân công công việc trong nhóm, đảm bảo chất lượng dự án đáp ứng thời hạn yêu cầu.', 'Mới tốt nghiệp, ở gần 136 Hồ Tùng Mậu, Bắc Từ Liêm, Hà Nội • Bằng cấp: Đại học trở lên • Ưu tiên độ tuổi từ 20 - 27 • Có kiến thức và đam mê chơi game. (Vui lòng mô tả cụ thể kinh nghiệm hoặc kiến thức game của bạn trong CV). • Chủ động học hỏi và tiếp thu kiến thức mới. • Thành thạo MS Office • Kỹ năng đọc và viết tiếng Anh là một lợi thế. • Có tinh thần đồng đội, kỷ luật và tuân thủ các chính sách và quy định của công ty. • Quyết tâm đem lại dịch vụ chất lượng cao cho người dùng.
Kỹ năng chuyên môn: [''Lập trình Unity'', ''Sử dụng công cụ theo dõi lỗi'']
Kỹ năng mềm: [''Chủ động học hỏi'', ''Tinh thần đồng đội'', ''Kỷ luật'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', '8 tiếng/ngày [9:00 - 18:00] and 6 ngày/tuần (Từ Thứ Hai đến Thứ Bảy)', '[''Cơ hội làm việc trong các dự án toàn cầu'', ''Mức lương và chế độ đãi ngộ hấp dẫn'', ''Môi trường làm việc năng động, sáng tạo'', ''Đánh giá lương hàng năm'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (899, 9, 1, 'Thực Tập Sinh Kinh Doanh', '- Tham gia đào tạo, học và tìm hiểu về sản phẩm phần mềm LukLak – phần mềm Quản lý công việc; - Gọi điện theo data có sẵn cho khách hàng; - Hỗ trợ và tư vấn khách hàng; - Soạn thảo hợp đồng, các giấy tờ liên quan; - Nhận yêu cầu từ phía BDM.', '- Sinh viên năm 3, 4 tại các trường Đại học, ưu tiên các bạn chuyên ngành Kinh tế, Thương mại, QTKD… - Có thể đi làm full time - Tư duy nhanh nhẹn làm việc có hệ thống, có khả năng tự tìm hiểu tốt. - Có laptop cá nhân. - Nhanh nhẹn, cầu toàn, giao tiếp tốt.
Kỹ năng mềm: [''Tư duy nhanh nhẹn'', ''Làm việc có hệ thống'', ''Có khả năng tự tìm hiểu tốt'', ''Nhanh nhẹn'', ''Cầu toàn'', ''Giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Sáng 8h30’ - 12h00’, Chiều 13h00’ - 17h30’. Từ thứ 2 đến thứ 6. Thứ 7 cách tuần làm remote', '[''Hỗ trợ lương cứng lên tới 3.000.000 đồng/tháng'', ''Có cơ hội lên chính thức nếu kết quả làm việc tốt'', ''Chương trình đào tạo TTS bài bản'', ''Được làm việc với các phần mềm quản lý nổi tiếng'', ''Làm việc trong môi trường chuyên nghiệp, trẻ và cởi mở'', ''Cơ hội mở rộng social network'', ''Được đào tạo tiếng Anh miễn phí'', ''Cước điện thoại'', ''Được cấp Tai nghe'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (900, 10, 1, 'UI/UX Design Intern', 'Thiết kế giao diện, bố cục cho các ứng dụng và website. Tham gia vào quy trình thiết kế của các dự án. Phối hợp với các bộ phận liên quan để tối ưu thiết kế. Cập nhật các xu hướng thiết kế mới. Thực hiện các nhiệm vụ được giao trong phạm vi công việc của Team Design.', 'Thành thạo các công cụ thiết kế, đặc biệt là Figma. Tư duy logic tốt. Có kỹ năng vẽ tay là một lợi thế. Có tinh thần chủ động học hỏi, làm việc có tổ chức, có khả năng làm việc độc lập và làm việc nhóm. Cam kết tham gia đầy đủ trong suốt kỳ thực tập 3 tháng.
Kỹ năng chuyên môn: [''Figma'']
Kỹ năng mềm: [''Tư duy logic tốt'', ''Tinh thần chủ động học hỏi'', ''Làm việc có tổ chức'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'cần thơ', 'Cần Thơ', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Thực tập có lương và thưởng hàng tháng dựa trên hiệu quả công việc'', ''Tham gia các dự án thử thách giúp phát triển kỹ năng và sự nghiệp'', ''Môi trường làm việc thoải mái, cởi mở, tạo điều kiện phát triển cá nhân'', ''Cơ hội làm việc với các đối tác trong lĩnh vực công nghệ'', ''Được cấp giấy chứng nhận thực tập và có cơ hội trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (901, 2, 1, 'Thực Tập Sinh Thiết Kế Đồ Hoạ', 'Hỗ trợ thiết kế các ấn phẩm truyền thông phục vụ hoạt động nội bộ và truyền thông số (digital), bao gồm: banner, poster, standee, backdrop, tờ rơi, name card, quà tặng, sale kit,... Tham gia hỗ trợ xây dựng và duy trì hệ thống nhận diện thương hiệu của công ty. Chỉnh sửa, tối ưu hình ảnh, video đơn giản trên các kênh truyền thông của công ty (website, fanpage, nội bộ,...). Hỗ trợ chụp và chỉnh sửa ảnh sự kiện, hoạt động nội bộ khi cần. Phối hợp cùng team Marketing triển khai các ý tưởng thiết kế cho chiến dịch truyền thông; hỗ trợ team Nội thất trong việc lên ý tưởng đồ họa cho các dự án (nếu có). Thực hiện các công việc liên quan khác theo phân công của Quản lý trực tiếp.', 'Sử dụng thành thạo các phần mềm thiết kế như Adobe Illustrator, Photoshop, InDesign, Premiere và các phần mềm chỉnh sửa video cơ bản. Có khả năng vẽ tay/sketch và biết sử dụng phần mềm thiết kế 3D là một lợi thế. Yêu thích hoặc có đam mê với nghệ thuật, mỹ thuật, thiết kế đồ họa. Có tư duy sáng tạo, tinh thần trách nhiệm cao, chủ động trong công việc, có khả năng làm việc nhóm và độc lập. Biết chụp ảnh, set-up bố cục chụp ảnh sản phẩm hoặc sự kiện là điểm cộng.
Kỹ năng chuyên môn: [''Adobe Illustrator'', ''Photoshop'', ''InDesign'', ''Premiere'']
Kỹ năng mềm: [''Sáng tạo'', ''Tinh thần trách nhiệm'', ''Chủ động'', ''Làm việc nhóm'', ''Làm việc độc lập'']', 'INTERNSHIP', 'ONSITE', 'bình thạnh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Thực tập có trợ cấp'', ''Hỗ trợ chi phí gửi xe'', ''Môi trường làm việc trẻ trung, năng động'', ''Được hướng dẫn, đào tạo phát triển nghề nghiệp'', ''Đi du lịch - teambuilding 2 lần/ năm'', ''Văn phòng tiện nghi'', ''Cơ hội trở thành nhân viên chính thức'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (902, 3, 1, 'Nhân Viên Tư Vấn Part-Time', 'Giải đáp, chăm sóc khách hàng về sản phẩm, hệ thống, dịch vụ qua các kênh hỗ trợ (Điện thoại, Email, Fanpage...). Tư vấn giới thiệu dịch vụ, sản phẩm công ty từ Data được cung cấp. Tư vấn sản phẩm: Trả lời thắc mắc, hướng dẫn khách hàng, hỗ trợ demo sản phẩm. Tìm kiếm khách hàng: chủ động hoặc sử dụng data công ty, đặt lịch hẹn demo với đội chuyên gia. Được đào tạo về sản phẩm của công ty.', 'Độ tuổi: 20 – 35. Không yêu cầu kinh nghiệm, được đào tạo bài bản. Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực Sales, Marketing hoặc đam mê kinh doanh.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Giao tiếp'', ''Đàm phán'', ''Thuyết phục'', ''Chủ động'', ''Kỷ luật'', ''Tinh thần cầu tiến'', ''Giọng nói rõ ràng, dễ nghe'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Cơ hội thăng tiến rõ ràng – Trở thành nhân viên chính thức sau 3-6 tháng!'', ''Đào tạo bài bản về sản phẩm, kỹ năng tư vấn & chăm sóc khách hàng.'', ''Làm việc trong môi trường trẻ trung, năng động, có định hướng phát triển lâu dài.'', ''Tham gia các khóa đào tạo chuyên sâu, nâng cao kỹ năng chuyên môn & giao tiếp.'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (903, 7, 1, 'Giảng Viên Dạy Lập Trình Cho Trẻ Part Time', 'Dạy học theo chương trình giảng dạy của TagEdu. Điều chỉnh hoạt động học tập để phù hợp với các cấp độ khả năng khác nhau. Đồng thời theo dõi kết quả học tập của các học viên. Làm việc với các bộ phận để hiểu tiến trình học tập của học sinh, phân tích các nhu cầu học tập và giải quyết vấn đề phát sinh (nếu có). Hỗ trợ các phòng ban trong việc tương tác với phụ huynh. Hợp tác với các bộ phận để hỗ trợ phát triển chương trình giảng dạy và tài liệu học tập. Theo dõi tiến trình học tập của học sinh và làm báo cáo sau các buổi học để thông tin tới Phụ huynh. Hỗ trợ các sự kiện giáo dục được lên lịch trong suốt năm học để phát triển chuyên môn. Tham gia các buổi training dành cho giáo viên.', 'Có khả năng giao tiếp và dẫn dắt bài giảng bằng Tiếng Anh (Ưu tiên IELTS trên 6.0). Thành thạo giảng dạy nền tảng lập trình Scratch và ngôn ngữ lập trình Python. Hỗ trợ phần giáo án và bài giảng khi cần. Yêu thương và có khả năng tương tác với trẻ em. Ưu tiên tuyển dụng: Có khả năng dạy được các môn lập trình khác (Roblox Studio, Unity, chương trình ICT – IGCSE – A Level của các trường Quốc tế, chương trình CS50, Lego Education)
Kỹ năng chuyên môn: [''Lập trình Scratch'', ''Ngôn ngữ lập trình Python'']
Kỹ năng mềm: [''Giao tiếp'', ''Tương tác với trẻ em'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', '5 ngày/tuần, từ 08:30 - 17:30 pm, cuối tuần linh động', '[''Được đào tạo và phát triển chuyên môn'', ''Môi trường làm việc thoải mái, khuyến khích sáng tạo'', ''Phát triển thêm nhiều kĩ năng mới'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (904, 8, 1, 'Thực Tập Sinh Motion Graphic Designer', 'Thực hiện công việc cho ngành chính của công ty như: giải pháp công nghệ, đào tạo & thương mại điện tử. Biên tập, thực hiện các video về quảng cáo marketing cho sản phẩm. Biên tập và thực hiện motion cho các design Animation nhân vật để quảng cáo trên các nền tảng và khoá học (Tiktok, Youtube short...) dạng 2D và 3D dự án thương mại điện tử. Cắt ghép các clip, video, hình ảnh, soure online để tạo thành 1 clip hoàn chỉnh theo kịch bản để phục vụ cho kênh bao gồm cả Thay đổi kích thước và ngôn ngữ video. Thực hiện các dự án thiết kế motion khác của công ty. Đề xuất ý tưởng khả thi để tăng tính hiệu quả về mặt mỹ thuật cho các sản phẩm. Thực hiện công việc đã được Trưởng bộ phận phân công đúng tiến độ, đảm bảo chất lượng. Bảo mật thông tin liên quan đến công việc được giao.', 'Sử dụng thành thạo công cụ graphic (Photoshop, After Effect), nắm vững cơ bản diễn đạt visual. Có ý tưởng độc đáo và sáng tạo. Có khả năng giao tiếp linh hoạt, chính xác và phối hợp chặt chẽ trong công việc. Đối với 2D/ 3D Animation Motion Graphic Designer yêu cầu các kỹ năng: Adobe Photoshop, Adobe Illustrator, Adobe After effects, Maxon Cinema 4D (không biết học hỏi và đào tạo thêm). Độ tuổi: Từ > 20 tuổi. Kinh nghiệm: Yêu cầu từ 2-6 tháng làm về quay và dựng Video Motion Graphic. Biết sử dụng công cụ AI phục vụ công việc. Thái độ, tố chất ham học hỏi. Trung thực, nhiệt tình, có trách nhiệm với công việc. Tâm huyết, có tinh thần học hỏi và phát triển bản thân, gắn bó và yêu thích sự đổi mới sáng tạo. Nhanh nhẹn, chủ động.
Kỹ năng chuyên môn: [''Adobe Photoshop'', ''Adobe Illustrator'', ''Adobe After Effects'', ''Maxon Cinema 4D'']
Kỹ năng mềm: [''Giao tiếp linh hoạt'', ''Sáng tạo'', ''Trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'cầu giấy', 'Hà Nội', 'MONTHLY', 7000000.00, '2.0 - 7.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Được thực tập có dấu công ty'', ''Phụ cấp sinh hoạt hàng tháng'', ''Được xem xét tuyển dụng thẳng sau thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (905, 9, 1, 'Design', '- Thiết kế các ấn phẩm truyền thông - Lên kế hoạch thực hiện các chiến dịch truyền thông theo yêu cầu của trung tâm - Chỉnh sửa hình ảnh - Làm việc trực tiếp tại trường Cao Đẳng Huế - 82 Hùng Vương, Tp Huế - Thời gian có thể Full time hoặc Part-time', '- Sinh viên các ngành thiết kế đồ họa, Marketing, Báo chí và các ngành có liên quan - Không có kinh nghiệm sẽ được đào tạo - Có tuyển dụng sinh viên chưa tốt nghiệp - Sử dụng thành thạo các công cụ thiết kế đồ họa như PTS, AI, … - Biết edit video cơ bản là một lợi thế
Kỹ năng chuyên môn: [''Sử dụng thành thạo các công cụ thiết kế đồ họa như PTS, AI'', ''Biết edit video cơ bản'']', 'INTERNSHIP', 'ONSITE', 'thừa thiên huế', 'Huế', 'MONTHLY', 5000000.00, '2.5 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Môi trường làm việc trẻ trung, năng động, có cơ hội phát triển bản thân'', ''Tham gia các hoạt động phong trào của trung tâm'', ''Đầy đủ chế độ BHYT, BHXH sau thử việc'', ''Chế độ đãi ngộ tốt theo quy chế trung tâm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (906, 10, 1, 'Trợ Giảng/ Gia Sư/ Giáo Viên Part-Time CNTT/Lập Trình/Điện Tử/Truyền Thông Đa Phương Tiện', 'Tham gia giảng dạy theo chuyên môn tại các cơ sở học viện TEKY hoặc các địa điểm giảng dạy của Teky. Báo cáo quá trình giảng dạy, trực tiếp đánh giá khả năng tiếp thu của học sinh, kết quả học tập cuối cùng cho phụ huynh. Có trách nhiệm tham gia tư vấn về bộ môn học cho phụ huynh; xây dựng và phát triển quan hệ với phụ huynh nhằm duy trì việc học của học sinh tại học viện. Tham gia các hoạt động sự kiện ngày hội trải nghiệm công nghệ, workshop cho phụ huynh, học sinh. Thực hiện các yêu cầu khác của Khối đào tạo chuyên môn.', 'Đang là sinh viên theo học các chuyên ngành Công nghệ thông tin, Kỹ thuật điện tử, tự động hoá, Mỹ thuật, Sư phạm kỹ thật, Toán, Tin, hoặc tốt nghiệp Đại học chuyên ngành Sư phạm, khoa công nghệ thông tin. Là giảng viên đã và đang giảng dạy tại các trường cấp 1, cấp 2 bộ môn Tin học, Công nghệ thông tin. Đang làm việc tại các công ty Truyền thông, Công nghệ thông tin, Điện tử – tự động, mỹ thuật, truyền thông đa phương tiện.
Kỹ năng chuyên môn: [''Kiến thức chuyên môn vững chắc trong lĩnh vực CNTT, thiết kế, điện tử viễn thông, truyền thông đa phương tiện'']
Kỹ năng mềm: [''Kỹ năng giảng dạy, truyền đạt kiến thức hiệu quả'', ''Kỹ năng giao tiếp tốt, tạo mối quan hệ tốt với học sinh sinh viên'', ''Khả năng quản lý lớp học, duy trì kỷ luật'', ''Khả năng chuẩn bị bài giảng, tài liệu học tập'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '3.0 - 7.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Công việc lành mạnh, văn hoá doanh nghiệp giàu bản sắc'', ''Cơ hội làm việc trực tiếp tham gia các dự án giáo dục mang tính quốc tế cao'', ''Thường xuyên tham gia các buổi đào tạo kĩ năng chuyên môn và kiến thức sư phạm'', ''Được làm việc trong môi trường Giáo dục năng động, chuyên nghiệp, cơ sở vật chất hiện đại'', ''Cơ chế đặc biệt khi hoàn thành nhiệm vụ'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (907, 2, 1, 'Nhân Viên Kinh Doanh', '1. Tìm kiếm & tiếp cận khách hàng tiềm năng Chủ động tìm kiếm cá nhân, doanh nghiệp, cửa hàng đang có nhu cầu: Thiết kế website chuyên nghiệp (giới thiệu sản phẩm, bán hàng online, dịch vụ…) Dịch vụ SEO từ khóa giúp website tăng thứ hạng Google, tăng lượt truy cập bền vững Chạy quảng cáo Facebook, Google giúp tiếp cận khách hàng tiềm năng hiệu quả 2. Giới thiệu dịch vụ Chia sẻ thông tin về dịch vụ của công ty qua Zalo, Facebook, email, hoặc gặp mặt trực tiếp (nếu có) Giúp khách hàng hiểu được lợi ích khi sử dụng dịch vụ của GPWEBMEDIA 3. Gửi thông tin khách hàng cho đội ngũ kỹ thuật Sau khi khách hàng có nhu cầu, bạn chỉ cần: Thu thập họ tên, số điện thoại, mô tả nhu cầu Gửi lại thông tin cho công ty', 'Yêu thích công việc kết nối, giới thiệu dịch vụ đến người khác Có kỹ năng giao tiếp cơ bản, tư duy chủ động và tinh thần cầu tiến Biết sử dụng Zalo, Facebook hoặc các nền tảng mạng xã hội để tìm kiếm khách hàng Ưu tiên: Freelancer, sinh viên, nhân viên văn phòng, người đang làm sales/marketing Có mối quan hệ rộng trong các lĩnh vực thương mại, dịch vụ, doanh nghiệp khởi nghiệp… Không bắt buộc làm việc full-time Không yêu cầu đến văn phòng – Làm việc từ xa, thời gian linh hoạt
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Sử dụng Zalo, Facebook'']
Kỹ năng mềm: [''Tư duy chủ động'', ''Tinh thần cầu tiến'']', 'FREELANCE', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Hoa hồng hấp dẫn: 25%/hợp đồng'', ''Thanh toán minh bạch, đúng hẹn'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (908, 3, 1, 'Thực Tập Lập Trình Unity Game', 'Lập trình Game 3D cho hệ điều hành Android & iOS. Hoàn thiện tính năng Game theo Design. Thực hiện cải thiện hiệu suất Game để phù hợp với Mobile.', 'Có kiến thức về lập trình Game 3D bằng Unity : Transform, RectTransform, Navigation, Animator, Coroutine. Có hiểu biết về các Component UI Cơ bản trong Unity. Có hiểu biết cơ bản về Design Pattern : Singleton, Object Pool. Nắm vững kiến thức căn bản trong lập trình C# : Access Modifier, Value and reference types. Có kiến thức cơ bản về thuật toán, lập trình hướng đối tượng và cấu trúc dữ liệu. Đam mê lập trình tạo ra những sản phẩm Game phục vụ nhiều triệu người chơi.
Kỹ năng chuyên môn: [''Lập trình Game 3D bằng Unity'', ''C#'', ''Kiến thức về Design Pattern'', ''Kiến thức về thuật toán'', ''Lập trình hướng đối tượng'', ''Cấu trúc dữ liệu'']
Kỹ năng mềm: [''Khả năng giải quyết vấn đề'', ''Khả năng học hỏi nhanh'', ''Khả năng làm việc nhóm'', ''Đam mê lập trình'']', 'INTERNSHIP', 'ONSITE', 'nam từ liêm', 'Hà Nội', 'MONTHLY', 4000000.00, '4.0 - 4.5 triệu', 'Thứ 2 - Thứ 6 (08:00 - 17:30), Thứ 7 (08:00 - 12:00)', '[''Tham gia quy trình sản xuất game chuyên nghiệp'', ''Được đào tạo trong môi trường chuyên nghiệp'', ''Thưởng dự án hàng tháng'', ''Thưởng sáng tạo'', ''Tham gia BHXH, BHYT'', ''Review lương định kỳ 6 tháng/ lần'', ''Du lịch, nghỉ mát, team building'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (909, 7, 1, 'Thực tập phát triển phần mềm', 'Hỗ trợ thiết kế, mã hóa, thử nghiệm và gỡ lỗi các dự án phần mềm, bao gồm: trang web CW, trình sàng lọc chứng khoán, cổng thông tin khách hàng, cổng thông tin môi giới. Phối hợp với các kỹ sư cao cấp và các nhóm chức năng chéo để hiểu các yêu cầu của dự án và cung cấp các giải pháp chất lượng cao. Tham gia vào các đánh giá mã để đảm bảo tuân thủ các thực tiễn tốt nhất và tiêu chuẩn mã hóa. Viết các bài kiểm tra đơn vị và tập lệnh tự động hóa để hỗ trợ các dự án nội bộ. Triển khai các giải pháp thử nghiệm tự động để đảm bảo chức năng và hiệu suất của các dự án phần mềm. Duy trì và cập nhật tài liệu kỹ thuật để tham khảo và chia sẻ kiến ​​thức trong tương lai.', 'Currently pursuing a degree in Computer Science, Information Technology, Software Engineering, or a related field. Basic knowledge of NodeJS, RESTful API, NestJS, Java, ReactJS, and Python. Experience with version control systems (e.g., Git, Gitflow, GitLab). Understanding of database management systems (SQL, NoSQL, MongoDB, Redis, MySQL). Familiarity with React framework and Microservices architecture is a plus. Strong problem-solving and analytical thinking abilities. Good communication and teamwork skills. Eagerness to learn and adapt to new technologies. Basic English skill.
Kỹ năng chuyên môn: [''NodeJS'', ''RESTful API'', ''NestJS'', ''Java'', ''ReactJS'', ''Python'', ''version control systems (e.g., Git, Gitflow, GitLab)'', ''database management systems (SQL, NoSQL, MongoDB, Redis, MySQL)'']
Kỹ năng mềm: [''Strong problem-solving and analytical thinking abilities'', ''Good communication and teamwork skills'', ''Eagerness to learn and adapt to new technologies'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 - 2.4 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Full-time internship allowance: 2.000000 VND/month'', ''Parking fee support: 400.000 VND/month'', ''Support for internship certification stamping (if required)'', ''Opportunity to join team-building activities, internal events, and other company recreational activities'', ''Dynamic and professional working environment'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (910, 8, 1, 'Thực Tập IT', '- Cài đặt, hỗ trợ khách hàng, - Khắc phục lỗi kỹ thuật liên quan thiết bị mạng, thoại VoIP, phần mềm máy tính - Tư vấn giải pháp, mô hình mạng và hướng dẫn khách hàng sử dụng các dịch vụ mạng, thoại IP, phần mềm máy tính.', '- Sinh viên ngành công nghệ thông tin, điện tử viễn thông - Sinh viên các ngành khác có đam mê tìm hiểu về mạng máy tính, thoại IP - Ứng viên cần có laptop và phương tiện đi lại
Kỹ năng chuyên môn: [''Mạng máy tính'', ''Thao tác với thiết bị mạng'', ''Phần mềm máy tính'']
Kỹ năng mềm: [''Giao tiếp'', ''Giải quyết vấn đề'']', 'INTERNSHIP', 'ONSITE', 'hà nội, hồ chí minh', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Cơ hội làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung'', ''Tiếp xúc với những công nghệ / thiết bị truyền thông mới nhất hiện nay (VoIP)'', ''Được đào tạo thêm chuyên môn trong ngành'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (911, 9, 1, 'Thực Tập Sinh Kỹ Thuật Máy Tính Phần Cứng', 'Thực tập về việc giao, lắp, cài đặt thiết bị; Thực tập về lắp ráp bộ máy, cài đặt, kiểm tra, khắc phục lỗi của thiết bị máy tính; Được hướng dẫn thực tập sửa chữa các thiết bị, linh phụ kiện máy tính, máy in ... CNTT; Thực tập các công việc kỹ thuật khác theo sự phân công của Trưởng bộ phận.', '– Tốt nghiệp các Trường kỹ thuật về CNTT, Kỹ thuật, hoặc người đã ra trường mà chưa có kinh nghiệm về lĩnh vực Kỹ thuật IT phần cứng... – Trung thực, nhanh nhẹn và có tinh thần trách nhiệm trong công việc.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về phần cứng máy tính'', ''Khả năng lắp ráp, sửa chữa máy tính'']
Kỹ năng mềm: [''Trung thực'', ''Nhanh nhẹn'', ''Có tinh thần trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '2.5 - 2.6 triệu', 'Ca 1: từ 8h00 đến 17h30, Ca 2: từ 10h đến 19h', '[''Mức phụ cấp thực tập: 2.500.000 đ + Phu cấp (xăng xe, gửi xe)'', ''Được làm việc trong môi trường chuyên nghiệp'', ''Được đào tạo tất cả các kỹ năng cần thiết'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (912, 10, 1, 'Thực Tập Sinh Lập Trình Website', 'Phát triển, xây dựng các dự án website sử dụng ngôn ngữ lập trình PHP hoặc trên nền mã nguồn WordPress. Làm việc với PHP, MySQL, CSS, Javascript, HTML. Phát triển, triển khai lập trình website, các ứng dụng trên nền web sử dụng ngôn ngữ PHP, MySQL. Phát triển các sản phẩm website bán hàng, thương mại điện tử, website tin tức đáp ứng đa nền tảng PC, Smartphone, Tablet. Xử lý các lỗi của trang web, thiết kế những tính năng mới phù hợp cho web. Bảo vệ web chống bị tấn công DMCA. Xây dựng kế hoạch và triển khai chiến lược SEO, đảm bảo rằng các hoạt động SEO website và SEO đang diễn ra đúng hướng và đạt được mục tiêu của công ty. Tối ưu hóa các trang web, tiến hành kiểm tra kỹ thuật SEO thường xuyên, khắc phục các vấn đề kỹ thuật của trang web (ví dụ: tốc độ tải trang chậm, lỗi thu thập thông tin trang và nội dung trùng lặp, link lỗi, link xấu). Quản trị website, email, hosting (Cài đặt, biên tập, sửa đổi, nâng cấp, sao chép, lưu trữ).', '1. PHP căn bản, luôn được đào tạo Update kỹ năng liên tục. 2. HTML/CSS, Javascript, Jquery căn bản. 3. Biết sử dụng CMS Wordpress theme và hiểu về Wordpress plugin. 4. Biết Wordpress core theme căn bản. 5. Tư duy lập trình tốt, có khả năng nắm bắt và học hỏi nhanh. 6. Không ngại thử thách với những ngôn ngữ, framework lập trình mới.
Kỹ năng chuyên môn: [''PHP'', ''MySQL'', ''CSS'', ''Javascript'', ''HTML'']
Kỹ năng mềm: [''Tư duy lập trình tốt'', ''Khả năng nắm bắt và học hỏi nhanh'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thời gian làm việc linh động tại nhà', '[''Được hướng dẫn và đào tạo bởi Lead Developer'', ''Tham gia vào các dự án thực tế, tích lũy kinh nghiệm'', ''Hỗ trợ dấu mộc và số liệu báo cáo thực tập (nếu cần)'', ''Có thể xét tuyển chính thức sau thực tập'', ''Các buổi training chuyên sâu kỹ thuật/ kỹ năng mềm định kỳ'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (913, 2, 1, 'Thực tập phát triển kinh doanh', 'Tích cực tìm kiếm các cơ hội bán hàng mới thông qua mạng và phương tiện truyền thông xã hội; Thúc đẩy các sản phẩm/dịch vụ của công ty giải quyết với các dịch vụ chăm sóc khách hàng có lương tâm để tối đa hóa sự hài lòng của khách hàng; Thương lượng/giao dịch gần gũi sau khi thiết kế giải pháp hấp dẫn nhất cho khách hàng và kết quả là xử lý khiếu nại hoặc phản đối; Chuẩn bị hợp đồng bán hàng đảm bảo tuân thủ các quy tắc và hướng dẫn được thiết lập theo luật; Xây dựng mối quan hệ lâu dài với khách hàng mới và hiện tại; Tham gia thay mặt cho Công ty trong các triển lãm, hội nghị và các sự kiện kết nối; Thực hiện các nhiệm vụ khác theo yêu cầu của cấp trên.', 'Final year students or recent graduates of Business English, Business Chinese, or Economics-related majors; Proficient in English or Chinese, equivalent to 6.5 IELTS or HSK 5, proficient in these two languages simultaneously is an advantage; Good at communication, personal branding and networking; Hardworking, creative, progressive spirit; Energetic and sociable; Can work full-time at GO office; Personal laptop is required; 1-year working as an official staff after internship commitment.
Kỹ năng chuyên môn: [''Proficient in English or Chinese, equivalent to 6.5 IELTS or HSK 5'']
Kỹ năng mềm: [''Good at communication'', ''Personal branding'', ''Networking'', ''Hardworking'', ''Creative'', ''Progressive spirit'', ''Energetic'', ''Sociable'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Competitive internship allowance: 3.000.000 VND/month + commission + parking allowance'', ''Tea break & team-building monthly'', ''Opportunity to experience a professional working environment'', ''Work under coaching of mentor and team leader'', ''On-job training'', ''Opportunity to be a full-time position after the internship'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (914, 3, 1, 'Thực Tập Sinh Kinh Doanh', 'Hỗ trợ, tìm kiếm giới thiệu tới khách hàng các giải pháp và dịch vụ của Công ty. Hỗ trợ các hồ sơ thủ tục cho các hoạt động đấu thầu, quản trị dự án. Hỗ trợ theo dõi các thủ tục ký kết hợp đồng dịch vụ. Tìm kiếm, thu thập và tổng hợp thông tin thị trường, đối thủ cạnh tranh. Tham gia các hội thảo, triển lãm công nghệ. Thực hiện các công việc khác theo sự phân công của Cán bộ quản lý trực tiếp.', 'Sinh viên năm 3, 4 hoặc đã tốt nghiệp chuyên ngành: Quản Trị Kinh Doanh, Thương Mại, Xuất Nhập Khẩu, Ngoại ngữ,... Yêu cầu sử dụng được tiếng Anh. Ngoại hình ưa nhìn. Yêu thích và có định hướng phát triển trong lĩnh vực Kinh doanh B2B. Có thể thực tập được fulltime ít nhất 3 tháng.
Kỹ năng chuyên môn: [''Tiếng Anh'']
Kỹ năng mềm: [''Ngoại hình ưa nhìn'', ''Yêu thích và có định hướng phát triển trong lĩnh vực Kinh doanh B2B'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được trải nghiệm thực tế, rèn luyện và phát triển bản thân trong một môi trường làm việc năng động, nhiệt huyết'', ''Được tham gia các lớp đào tạo chuyên nghiệp trong nhiều lĩnh vực khác nhau của FPT'', ''Tham gia các hoạt động văn hoá, sự kiện hấp dẫn của Công ty FPT IS và Tập đoàn FPT'', ''Được hỗ trợ, hướng dẫn thực hiện các báo cáo liên quan'', ''Được ưu tiên xem xét tuyển dụng chính thức sau thời gian thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (915, 7, 1, 'Hỗ trợ khách hàng của đám mây - L1 bán thời gian/điều khiển từ xa', 'Hãy chắc chắn rằng đường dây nóng 247 luôn có sẵn. Nhận và xử lý các yêu cầu hỗ trợ kỹ thuật từ khách hàng và đơn vị nội bộ thông qua hệ thống hỗ trợ dịch vụ. Các trường hợp hỗ trợ mở với Microsoft nếu cần. Tạo người thuê, đăng ký và tài nguyên cung cấp cho khách hàng theo yêu cầu từ nhóm bán hàng. Tham gia các khóa đào tạo kỹ năng kỹ thuật và mềm để cải thiện kỹ năng làm việc và chuyên môn.', 'Graduated from College or University majoring in Information Technology. Intern in IT system administration for any company. Have basic networking knowledge. Proficient in using Windows and Linux systems. Basic understanding of cloud services. Have CCNA, LPI is an advantage. Able to work under high pressure. Capable of multi-tasking at the same time. Able to read and understand specialized English and respond via email. Reasoning the problem convincingly (logically).
Kỹ năng chuyên môn: [''Basic networking knowledge'', ''Proficient in using Windows and Linux systems'', ''Basic understanding of cloud services'']
Kỹ năng mềm: [''Able to work under high pressure'', ''Capable of multi-tasking'', ''Able to read and understand specialized English and respond via email'', ''Reasoning the problem convincingly'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '5.0 triệu', 'Ngoài giờ hành chính', '[''Competitive salary, pay according to ability'', ''Training roadmap for Cloud L1 -> L2 -> Advanced Cloud Engineer'', ''Creative, open-minded working environment'', ''Participation in technology events and team-building activities'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (916, 8, 1, 'Thực Tập Sinh Kinh Doanh Dự Án', 'Hỗ trợ phát triển khách hàng tiềm năng trong lĩnh vực công nghệ thông tin. Cùng Sale gặp gỡ trực tiếp để giới thiệu sản phẩm/dịch vụ phần mềm của công ty. Hỗ trợ lên báo giá, hợp đồng. Tham gia các hoạt động marketing và quảng bá sản phẩm/dịch vụ. Hỗ trợ khách hàng trong quá trình sử dụng sản phẩm/dịch vụ.', 'Không yêu cầu kinh nghiệm, được đào tạo bài bản. Sinh viên năm cuối/cử nhân Cao đẳng/Đại học chuyên ngành kinh tế, kỹ thuật hoặc các ngành liên quan. Kỹ năng giao tiếp tốt. Khả năng làm việc độc lập và chịu được áp lực cao. Có tinh thần cầu tiến, ham học hỏi và mong muốn phát triển sự nghiệp trong lĩnh vực kinh doanh. Có thể thực tập fulltime.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng làm việc độc lập'', ''Chịu được áp lực cao'', ''Có tinh thần cầu tiến'', ''Ham học hỏi'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 tuần 2 và tuần 4 làm online', '[''Được đào tạo các kỹ năng trong mảng kinh doanh dự án số hóa, phần mềm'', ''Được làm việc trong các dự án số hóa lớn'', ''Hỗ trợ lương và dấu mộc thực tập'', ''Môi trường làm việc năng động sáng tạo, cơ hội phát triển lên vị trí chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (917, 9, 1, 'Thực tập bảo mật đám mây', 'Thực tập 2 tháng về an toàn và bảo mật thông tin nhằm xây dựng các kỹ năng thực hiện công việc: Tham gia các dự án bảo mật trên nền tảng điện toán đám mây. Làm việc trực tiếp với 100% khách hàng quốc tế (EU, US, Nhật Bản, Hàn Quốc, Singapore, …). Triển khai, vận hành và tối ưu hóa các giải pháp cloud (AWS, Azure, …). Thực hiện các tác vụ liên quan đến bảo mật: quản lý danh tính, kiểm soát truy cập, mã hóa dữ liệu, tuân thủ các framework bảo mật. Xây dựng và duy trì automation scripts (Python, Bash) phục vụ vận hành và bảo mật. Quản trị hệ thống Linux cơ bản, xử lý sự cố. Làm việc với container và orchestration (Docker, Kubernetes).', '• Sinh viên năm ba/năm cuối hoặc đã tốt nghiệp các chuyên ngành CNTT, An toàn thông tin, Hệ thống thông tin, Toán Tin, Điện tử viễn thông... tại các trường Đại học. • Có kiến thức về An toàn thông tin và các phương thức tấn công mạng. • Biết về Docker, Kubernetes. • Nắm vững kiến thức cơ bản về Cloud Security. • Có kỹ năng lập trình/scripting: Python, Bash. • Có khả năng giao tiếp Tiếng anh tốt.
Kỹ năng chuyên môn: [''Docker'', ''Kubernetes'', ''Python'', ''Bash'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Khả năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được thực tập và đào tạo chuyên sâu về các công nghệ mới nhất trong lĩnh vực Cyber Security'', ''Nhận trợ cấp đào tạo hàng tháng trong quá trình đào tạo'', ''Tham gia các dự án thực tế với công nghệ mới nhất (AWS, Azure, Kubernetes)'', ''Lộ trình phát triển nghề nghiệp rõ ràng trong lĩnh vực Cloud Security'', ''Hỗ trợ ôn luyện và tài trợ lệ phí thi các chứng chỉ chuyên nghiệp quốc tế như: CEH, CHFI, Security+, CCNA Security, OSCP, GWAPT, PMP'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (918, 10, 1, 'Nhân Viên Phát Triển Game (Unity/Godot/Unreal)', 'Mình đang tìm bạn đồng hành để cùng phát triển các sản phẩm game indie mang phong cách sáng tạo, dễ chơi – dễ nghiện – dễ lan truyền. Mình có: Kỹ năng thiết kế gameplay, quản lý dự án, Kinh nghiệm làm sản phẩm MVP, marketing, publishing, Mối quan hệ với publisher, hỗ trợ phát hành quốc tế. Có thể remote hoặc gặp trực tiếp ở Hà Nội.', 'Chỉ cần bạn: Có kinh nghiệm làm game cá nhân hoặc từng build game demo (tốt nghiệp không bắt buộc), nhà gần 136 Hồ Tùng Mậu, Quận Bắc Từ Liêm, Hà Nội. Thành thạo Unity hoặc Godot / Unreal. Biết cách tổ chức project game đơn giản, clean code. Hiểu tư duy phát triển MVP (Minimum Viable Product).
Kỹ năng chuyên môn: [''Unity'', ''Godot'', ''Unreal'']
Kỹ năng mềm: [''Tinh thần học hỏi'', ''Chủ động'', ''Đam mê khởi nghiệp'']', 'PART_TIME', 'REMOTE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Môi trường sáng tạo, tự chủ, hướng tới sản phẩm thực tế'', ''Chia sẻ lợi nhuận nếu ra sản phẩm'', ''Có mentor hỗ trợ các phần: quản lý dự án, marketing, xuất bản quốc tế'', ''Không gò bó thời gian – làm việc theo mục tiêu'', ''Được tự do phát triển ý tưởng cá nhân'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (919, 2, 1, 'Game Designer Intern', 'Hỗ trợ việc phát triển ý tưởng và thiết kế các tính năng game mới dưới sự hướng dẫn của các Game Designer có kinh nghiệm. Tham gia vào quy trình brainstorming và đóng góp ý kiến để cải thiện gameplay và trải nghiệm người chơi. Hỗ trợ việc tạo ra các tài liệu thiết kế chi tiết, bao gồm viết mô tả tính năng, lập kế hoạch cấp độ và tổ chức thông tin. Thực hiện nghiên cứu thị trường và phân tích đối thủ cạnh tranh để hiểu rõ về xu hướng hiện tại và yêu cầu của người chơi. Thử nghiệm prototype game, góp phần vào quá trình kiểm thử chất lượng sản phẩm. Học hỏi và áp dụng kiến thức về các công cụ thiết kế game và phần mềm liên quan.', 'Là sinh viên năm thứ 3, 4, 5 các trường Đại học chính quy. Có thể đi làm tối thiểu 6 buổi/tuần, ưu tiên có thể đi fulltime. Yêu thích chơi game, ham tìm hiểu về game, có khả năng phát triển ý tưởng cho game, mong muốn phát triển sự nghiệp trở thành game designer. Giỏi toán, số học, tư duy logic tốt, khả năng phân tích dữ liệu tốt. Thông minh, chăm chỉ, ham học hỏi, cầu tiến.
Kỹ năng chuyên môn: [''Kiến thức về game design'', ''Sử dụng các công cụ thiết kế game'']
Kỹ năng mềm: [''Tư duy logic tốt'', ''Khả năng phân tích dữ liệu'', ''Chăm chỉ'', ''Ham học hỏi'', ''Cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:45)', '[''Trợ cấp bữa ăn trưa'', ''Tham gia các khóa đào tạo chuyên môn'', ''Tham gia các hoạt động teambuilding, du lịch cùng Công ty'', ''Được ưu tiên xét tuyển lên nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (920, 3, 1, 'Thực Tập Sinh', 'Công việc văn phòng (in ấn, làm file báo giá, đặt văn phòng phẩm cho cửa hàng). Hỗ trợ vận hành làm hệ thống các Payment Request cho thầu và lên form yêu cầu đặt hàng. Làm báo cáo theo dõi sale hàng tuần của các cửa hàng. Các nhiệm vụ hoặc trách nhiệm khác theo sự phân công của Quản lý.', 'Sinh viên năm 3 hoặc năm 4 chuyên ngành Marketing/Ecommerce/PR hoặc các ngành liên quan. Ưu tiên các bạn thực tập Full-time và tối thiểu 3 tháng. Sử dụng tin học văn phòng cơ bản: Word, Excel, PowerPoint, Outlook và Internet. Kỹ năng giao tiếp tốt. Cẩn thận chi tiết và có khả năng xử lý nhiều nhiệm vụ cùng một lúc. Đam mê trong lĩnh vực Retail business & Operational Excellence.
Kỹ năng chuyên môn: [''Sử dụng tin học văn phòng cơ bản: Word, Excel, PowerPoint, Outlook và Internet'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Cẩn thận chi tiết'', ''Có khả năng xử lý nhiều nhiệm vụ cùng một lúc'', ''Đam mê trong lĩnh vực Retail business & Operational Excellence'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ cấp giấy xác nhận thực tập + Đóng mộc theo mẫu của công ty'', ''Hỗ trợ bữa ăn trưa tại canteen'', ''Hỗ trợ laptop trong quá trình làm việc'', ''Được trải nghiệm, học tập và làm việc tại tập đoàn đa quốc gia'', ''Hỗ trợ sắp xếp thời gian học & làm việc phù hợp'', ''Hỗ trợ xe đưa đón cho các bạn ở xa (nếu bạn đang cư trú ở Q.7, Q.Bình Thạnh, TP.Thủ Đức)'', ''Không hỗ trợ lương'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (921, 7, 1, 'Giảng Viên An Ninh Mạng', 'Hợp tác theo hình thức thỉnh giảng (linh động lịch đáp ứng giảng dạy theo 3 ca: sáng, chiều hoặc tối). Phối hợp cùng đội ngũ nhân sự của Trường để biên soạn giáo án theo tiêu chuẩn. Tham gia công tác giảng dạy phù hợp với chuyên môn Bảo mật và an toàn thông tin.', 'Trình độ: Tốt nghiệp Đại học khối ngành Công nghệ thông tin, An toàn thông tin hoặc các ngành liên quan. Kinh nghiệm tối thiểu 3 năm ở vị trí: Giảng viên CNTT hoặc Trưởng nhóm/Chuyên viên trở lên tại các công ty chuyên về Công nghệ. Kiến thức chuyên sâu về: xử lý sự cố an ninh mạng, thực hiện đánh giá rủi ro bảo mật, kiểm tra lỗ hổng hệ thống...
Kỹ năng chuyên môn: [''Xử lý sự cố an ninh mạng'', ''Đánh giá rủi ro bảo mật'', ''Kiểm tra lỗ hổng hệ thống'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Linh động lịch giảng dạy từ thứ 2 đến thứ 7, theo 3 ca: Sáng: 8h30 - 11h30, Chiều: 13h30 - 16h30, Tối: 18h00 - 21h00', '[''Lộ trình phát triển cụ thể, rõ ràng'', ''Chế độ chăm sóc Giảng viên: sinh nhật, hiếu hỉ, ốm đau'', ''Du lịch, teambuilding Giảng viên hàng năm'', ''Các hoạt động truyền thông nội bộ định kì: Lễ Tri ân Giảng viên 20/11, Workshop, Talkshow'', ''Chế độ thưởng, chăm sóc sức khỏe, đào tạo nội bộ'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (922, 8, 1, 'Thực Tập Sinh Kinh Doanh B2B (Phần Mềm)', 'Tìm kiếm, khai thác khách hàng. Hỗ trợ bộ phận kinh doanh giao dịch, giới thiệu giải pháp phần mềm cho khách hàng. Xúc tiến bán sản phẩm và dịch vụ phần mềm cho khách hàng. Thực hiện các công việc theo quy trình của công ty.', 'Ưu tiên sinh viên năm cuối các trường đại học. Khả năng học hỏi & truyền đạt các khái niệm phức tạp một cách nhanh chóng & dễ hiểu. Khả năng đọc hiểu tiếng Anh tốt. Có kinh nghiệm trong lĩnh vực công nghệ và sử dụng AI là một lợi thế.
Kỹ năng chuyên môn: [''Sử dụng AI'']
Kỹ năng mềm: [''Khả năng học hỏi'', ''Khả năng truyền đạt'', ''Giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '3.0 - 10.0 triệu', 'Thứ 2 - Thứ 6 (08:00 - 17:00), Thứ 7 (08:00 - 12:00)', '[''Hỗ trợ thực tập: 3 triệu - 5 triệu'', ''Thưởng cá nhân khi hoàn thành KPI'', ''Thưởng tập thể theo phòng ban khi hoàn thành mục tiêu'', ''Được đào tạo bài bản về B2B Sales'', ''Được đào tạo về sử dụng AI'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (923, 9, 1, 'Phát triển kinh doanh thực tập', 'Chúng tôi đang tìm kiếm một chuyên gia thế hệ chính có động lực để tham gia nhóm của chúng tôi. Thực tập này cung cấp một cơ hội duy nhất để hợp tác chặt chẽ với các bộ phận tiếp thị và bán hàng của chúng tôi, có được kinh nghiệm thực tế và tôn vinh các kỹ năng cần thiết cho sự nghiệp thành công trong phát triển kinh doanh. Trách nhiệm chính: Nghiên cứu thị trường: Tiến hành nghiên cứu thị trường chi tiết để xác định khách hàng tiềm năng và phân tích xu hướng thị trường, từ đó hỗ trợ các quyết định kinh doanh sáng suốt. Tạo khách hàng tiềm năng: Hỗ trợ phát triển và thực hiện các chiến lược tạo khách hàng tiềm năng để thu hút và thu hút khách hàng tiềm năng, thúc đẩy tăng trưởng kinh doanh. Quản lý chiến dịch: Tham gia tạo và quản lý email, phương tiện truyền thông xã hội và các chiến dịch tiếp thị khác nhằm quảng bá sản phẩm/dịch vụ của chúng tôi. Hỗ trợ bán hàng: Làm việc cùng với nhóm bán hàng để hướng dẫn khách hàng tiềm năng thông qua kênh bán hàng, nâng cao hiệu suất bán hàng. Phân tích hiệu suất: Đánh giá kết quả của các nỗ lực tạo khách hàng tiềm năng, tạo ra các báo cáo và đề xuất các cải tiến. Nhiệm vụ hành chính: Cung cấp hỗ trợ với các nhiệm vụ hành chính như quản lý tài liệu, chuẩn bị báo cáo và phối hợp sự kiện. Hợp tác nhóm: Tham gia vào các cuộc họp nhóm, các phiên động não và đào tạo để mở rộng kiến ​​thức và đóng góp ý tưởng.', 'Requirements: Communication skills: Excellent command of English, both verbal and written, for effective communication. Self-motivation: Eager to learn, grow, and contribute to the company''s success. Organization: Ability to juggle multiple responsibilities and prioritize tasks in a fast-paced environment. Teamwork: Strong interpersonal skills for collaboration within diverse teams. Adaptability: Fast learner, capable of quickly mastering new tools and systems. Industry passion: A keen interest in IT services industry is highly beneficial.
Kỹ năng mềm: [''Communication skills'', ''Self-motivation'', ''Organization'', ''Teamwork'', ''Adaptability'']', 'INTERNSHIP', 'ONSITE', 'hà đông', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Practical experience'', ''Skill development'', ''Work flexibility'', ''Career growth'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (924, 10, 1, 'Technical Intern - Thực Tập Sinh Kỹ Thuật', 'Tham gia công tác đào tạo, lập kế hoạch triển khai, thử nghiệm công nghệ trước khi triển khai, lập phương án triển khai và tài liệu thiết kế giải pháp, xây dựng tài liệu theo yêu cầu Dự án, tham gia các khóa đào tạo, thi chứng chỉ được giao.', 'Ưu tiên sinh viên theo học ngành Kỹ thuật, hoặc các ngành liên quan. Hiểu biết cơ bản hoặc đã học qua các môn học về các lĩnh vực kỹ thuật (ví dụ như hệ thống, security,…). Có khả năng giải quyết vấn đề kỹ thuật ở các tình huống thực tế hoặc các dự án môn học tại trường. Có khả năng thích nghi và học hỏi: Có khả năng học hỏi nhanh chóng và áp dụng các khái niệm kỹ thuật mới. Có khả năng truyền đạt thông tin về kỹ thuật một cách hiệu quả.
Kỹ năng chuyên môn: [''Hiểu biết cơ bản về các lĩnh vực kỹ thuật'']
Kỹ năng mềm: [''Khả năng giải quyết vấn đề'', ''Khả năng thích nghi và học hỏi'', ''Khả năng truyền đạt thông tin về kỹ thuật'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 triệu', 'T2, T4, T6', '[''Cơm trưa văn phòng cao cấp'', ''Hỗ trợ ăn sáng'', ''Có cơ hội làm việc chính thức tại công ty'', ''Bảo hiểm sức khỏe toàn diện hàng năm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (925, 2, 1, 'Thực tập bảo mật ứng dụng', 'Thực tập 3 tháng về an toàn và bảo mật thông tin nhằm xây dựng các kỹ năng thực hiện công việc: Đánh giá bảo mật, kiếm tra xâm nhập (Penetration Testing), code audits và design reviews, Báo cáo và đề xuất biện pháp khắc phục sự cố, các lỗ hổng bảo mật ứng dụng trên đa nền tảng (Web/Mobile...), Cung cấp hướng dẫn bảo mật cho các kỹ sư và nhân viên hỗ trợ. Nghiên cứu và cập nhật các xu hướng về an toàn và bảo mật thông tin. Phát triển các giải pháp kỹ thuật để tối ưu hóa quy trình đánh giá bảo mật. Làm việc cùng đội ngũ giảng viên là các chuyên gia hàng đầu trong lĩnh vực Cyber Security tại FPT Software.', '• Sinh viên năm ba/năm cuối hoặc đã tốt nghiệp các chuyên ngành CNTT, An toàn thông tin, Hệ thống thông tin, Toán Tin, Điện tử viễn thông... tại các trường Đại học. • Có kiến thức cơ bản về kỹ thuật bảo mật, bảo mật máy tính và mạng, xác thực, các giao thức bảo mật. • Có định hướng, yêu thích và đam mê lĩnh vực nghiên cứu phát triển về mảng An toàn và Bảo mật thông tin. • Có khả năng đọc hiểu tiếng Anh tốt. Ưu tiên ứng viên có trình độ tương đương từ TOEIC 500 trở lên.
Kỹ năng chuyên môn: [''Kỹ thuật bảo mật'', ''Bảo mật máy tính'', ''Mạng'', ''Xác thực'', ''Các giao thức bảo mật'']
Kỹ năng mềm: [''Định hướng'', ''Yêu thích'', ''Đam mê'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Được thực tập và đào tạo chuyên sâu về các công nghệ mới nhất trong lĩnh vực Cyber Security'', ''Nhận trợ cấp đào tạo hàng tháng'', ''Hoàn thiện kỹ năng mềm'', ''Hỗ trợ ôn luyện và tài trợ lệ phí thi các chứng chỉ chuyên nghiệp quốc tế'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (926, 3, 1, 'AI Engineer', 'Trách nhiệm chính - Hỗ trợ triển khai và duy trì cơ sở hạ tầng LLM tại chỗ - Giúp tích hợp và tối ưu hóa API thương mại LLM vào các ứng dụng của chúng tôi - Làm việc về định lượng mô hình hóa và tối ưu hóa để triển khai hiệu quả - Đóng góp để xây dựng các giải pháp lai kết hợp - Phát triển và duy trì trình bao bọc API và các lớp trừu tượng - Hỗ trợ điểm chuẩn hiệu suất và tối ưu hóa chi phí trên các giải pháp LLM khác nhau - Giúp thực hiện các cơ chế dự phòng mạnh mẽ và các giải pháp có sẵn cao - Tham gia triển khai bảo mật để triển khai LLM - Các quy trình triển khai tài liệu và các mẫu tích hợp', 'Required Qualifications - Currently pursuing a Bachelor''s or Master''s degree in Computer Science, AI, or related technical field - Strong programming skills in Python - Basic understanding of API integration and REST principles - Familiarity with commercial LLM APIs (OpenAI, Anthropic, etc.) - Basic understanding of machine learning concepts and algorithms - Experience with common ML libraries (e.g., TensorFlow, PyTorch, scikit-learn) - Solid foundation in mathematics and statistics - Good problem-solving and analytical skills
Kỹ năng chuyên môn: [''Python'', ''API integration'', ''REST principles'', ''commercial LLM APIs (OpenAI, Anthropic, etc.)'', ''machine learning concepts and algorithms'', ''TensorFlow'', ''PyTorch'', ''scikit-learn'']
Kỹ năng mềm: [''Good problem-solving skills'', ''Analytical skills'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Competitive internship stipend'', ''Access to high-performance computing resources'', ''Professional development opportunities'', ''Networking events and workshops'', ''Exposure to both open-source and commercial LLM ecosystems'', ''Possibility of full-time conversion based on performance'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (927, 7, 1, '2D Game Artist', 'Chúng tôi đang tìm kiếm freelancer để làm việc trên cơ sở dự án. Thiết kế/vẽ các mặt hàng trong một trò chơi thông thường theo yêu cầu; Đảm bảo nghệ thuật giống như phong cách nghệ thuật của công ty; Strictly gắn bó với các mốc thời gian dự án là tốt.', '1. Academic background in Arts or equivalent; 2. Have ability of drawing by hands, using Wacom, proficiently using Photoshop; 3. Have a mindset on designing in Shape, Composition, Color, Shade and Light; 4. Proficiently using Adobe Photoshop, Adobe Illustrator; 5. Extensive experience with Casual Games; 6. Experienced in Global Launching; 7. CV and Portfolio are available.
Kỹ năng chuyên môn: [''Drawing by hand'', ''Using Wacom'', ''Adobe Photoshop'', ''Adobe Illustrator'']
Kỹ năng mềm: [''Design mindset on Shape, Composition, Color, Shade and Light'']', 'FREELANCE', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Monday - Friday (from 08:00 to 17:00)', '[''Opportunities to work with international and experienced talents'', ''Attractive freelance fee'', ''Professional working environment'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (928, 8, 1, 'Nhân Viên Giám Sát Hệ Thống Công Nghệ Thông Tin', 'Sử dụng công cụ (Công ty cung cấp) để giám sát hệ thống đang vận hành của khách hàng. Cảnh báo ngay lập tức các vấn đề bất thường của hệ thống bao gồm Server, Network, Application. Phương thức cảnh báo: email, điện thoại. Báo cáo định kỳ: Ngày, Tuần, Tháng. Nơi làm việc: Onsite tại Huyện Bình Chánh-TPHCM.', 'Sinh viên mới tốt nghiệp các trường Cao đẳng, Đại Học chuyên ngành IT (Network, System) hoặc các chuyên ngành liên quan - chấp nhận sinh viên năm cuối. Có trách nhiệm với công việc. Có khả năng đọc, hiểu tiếng Anh. Kỹ năng báo cáo, giao tiếp, làm việc nhóm tốt.
Kỹ năng chuyên môn: [''Kiến thức về mạng máy tính'', ''Kiến thức về hệ điều hành'', ''Sử dụng các công cụ giám sát hệ thống'']
Kỹ năng mềm: [''Có trách nhiệm với công việc'', ''Kỹ năng báo cáo'', ''Giao tiếp tốt'', ''Làm việc nhóm tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), ca đêm từ 17h30 đến 8h30 sáng hôm sau', '[''Chế độ hấp dẫn'', ''Có chỗ nghỉ ngơi, sinh hoạt'', ''Thưởng hiệu quả làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (929, 9, 1, 'Thực Tập Sinh Kinh Doanh B2B', 'Tiếp cận và tìm hiểu nhu cầu, mong muốn của khách hàng tiềm năng. Tư vấn và phối hợp với đội ngũ kĩ thuật để đáp ứng nhu cầu của khách hàng. Báo giá, đàm phán và thống nhất phương án triển khai dịch vụ với khách hàng. Đối tượng khách hàng: các Doanh nghiệp.', 'Sinh viên các trường đại học hoặc các bạn mới ra trường. Không yêu cầu kinh nghiệm, có đam mê với công việc kinh doanh. Có kiến thức cơ bản về công nghệ thông tin là một lợi thế. Có khả năng giao tiếp tốt.
Kỹ năng chuyên môn: [''Kiến thức cơ bản về công nghệ thông tin'']
Kỹ năng mềm: [''Giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Full time: Thứ 2 - Thứ 6 (8:00 - 17:30), Part time: Hỗ trợ theo lịch của ứng viên', '[''Hướng dẫn công việc chi tiết'', ''Thời gian làm việc linh động'', ''Có hỗ trợ lương thực tập/ cộng tác viên'', ''Có hỗ trợ mộc thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (930, 10, 1, 'Thực Tập Thiết Kế Đồ Hoạ', 'GIAI ĐOẠN 1: LÀM QUEN VỚI THIẾT KẾ ĐỒ HOẠ VÀ CÔNG CỤ 1. Làm quen với các công cụ thiết kế: Canva Pro, Figma, Photoshop, AI hỗ trợ sáng tạo (ChatGPT, DALL·E...) 2. Tìm hiểu hệ thống nhận diện thương hiệu của TRẦN VŨ và các brand khách hàng 3. Phân biệt các loại thiết kế trong marketing: social post, banner quảng cáo, slide, visual hỗ trợ video 4. Phối hợp với team Content và Planner để triển khai các thiết kế đầu tiên 5. Làm quen với quy trình nhận – phản hồi – chỉnh sửa – xuất bản thiết kế GIAI ĐOẠN 2: THỰC HÀNH THIẾT KẾ ĐỒ HOẠ CHO DỰ ÁN THẬT 1. Thiết kế banner, bài post, hình ảnh quảng cáo cho các chiến dịch thật của agency 2. Làm việc trực tiếp với brief từ team Content, Planner hoặc khách hàng nội bộ 3. Biến ý tưởng thành thiết kế cụ thể – đúng format, đúng nhận diện, đúng thời gian 4. Tìm hiểu và thực hành các dạng thiết kế đa nền tảng: Facebook, Zalo, TikTok, Website, Landing Page 5. Chỉnh sửa theo feedback từ các bên và hoàn thiện sản phẩm trước khi bàn giao GIAI ĐOẠN 3: ĐỊNH HÌNH SỰ NGHIỆP THIẾT KẾ ĐỒ HOẠ 1. Generalist: Làm chủ kỹ năng thiết kế phục vụ đa nền tảng quảng cáo 2. Specialist: Chuyên sâu về UI/UX, Branding hoặc Social Visual 3. Career path rõ ràng: từ thực tập → designer → senior designer → creative lead 4. Sẵn sàng phát triển kênh cá nhân hoặc portfolio mạnh để ứng tuyển vị trí thiết kế chuyên nghiệp', '1. Tuyệt đối chủ động và nghiêm túc phát triển sự nghiệp của bản thân 2. Học cách biết ơn và tri ân cha mẹ trong suốt thời gian thực tập 3. Sẵn sàng teamwork và làm việc chân thành 4. Cam kết thực tập online tối thiểu 3 tháng. Ít nhất 4 buổi/tuần 5. Làm việc qua hệ thống và Quản lý nhóm online nếu được phân công nếu lên vị trí Planner dự án 6. Có tầm nhìn dài hạn về sự nghiệp Digital Marketing 7. Sẽ có những buổi họp và đào tạo đột xuất ngoài giờ, nhưng không quá 4 lần/tuần 8. Tuân thủ các Quy định và Hỗ trợ phòng HR 9. Sinh viên năm 1, 2, 3, 4 hoặc Tốt nghiệp trung cấp trở lên
Kỹ năng chuyên môn: [''Canva Pro'', ''Figma'', ''Photoshop'', ''AI hỗ trợ sáng tạo (ChatGPT, DALL·E)'']
Kỹ năng mềm: [''Chủ động'', ''Teamwork'', ''Nghiêm túc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thực tập Online 100% linh động', '[''Được đào tạo bài bản từ đầu, từ các dự án thực tế'', ''Làm việc 100% online, thời gian linh hoạt'', ''Được xác nhận thực tập, hướng dẫn làm báo cáo từ 9 điểm'', ''Có thưởng theo dự án và phụ cấp cố định'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (931, 2, 15, 'Thực Tập Sinh Kinh Doanh Bất Động Sản', 'Tìm kiếm, khai thác, phát triển khách hàng tiềm năng từ các nguồn. Chăm sóc khách hàng từ nguồn Marketing của công ty, hỗ trợ chốt deal. Tư vấn về sản phẩm cho khách hàng: các thông tin bao gồm loại hình bất động sản, giá thành, các tiện ích khu vực, vị trí, chính sách khuyến mãi,... nhằm đáp ứng nhu cầu của khách hàng. Giải đáp mọi thắc mắc liên quan, để giúp khách hàng được bất động sản phù hợp với mức giá tốt nhất. Hướng dẫn khách hàng tham quan các dự án mà công ty phân phối. Thực hiện giao dịch và hỗ trợ khách hàng theo dõi tiến độ thanh toán. Xây dựng và duy trì mối quan hệ với khách hàng. Quảng bá hình ảnh công ty đến khách hàng một cách chuyên nghiệp. Báo cáo và thực hiện các công việc khác theo yêu cầu của cấp trên.', 'Tư duy kinh doanh, đột phá. Đam mê thu nhập. Chăm chỉ, kiên trì, không ngại khó khăn. Sẵn sàng học hỏi, nâng trình, phát triển, hoàn thiện bản thân. Chấp nhận Sinh viên ứng tuyển vừa làm vừa học muốn định hướng nghề nghiệp trong tương lai hoặc thực tập sinh của các Trường muốn tìm một Doanh nghiệp thực tập.
Kỹ năng mềm: [''Tư duy kinh doanh'', ''Đam mê thu nhập'', ''Chăm chỉ'', ''Kiên trì'', ''Sẵn sàng học hỏi'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Linh động thời gian', '[''Thu nhập KHÔNG GIỚI HẠN'', ''Thưởng Lễ, Tết'', ''Lương tháng 13'', ''Thưởng thành tích bán hàng'', ''Tham gia các buổi đào tạo'', ''Cơ hội phát triển nghề nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (932, 3, 15, 'Nhân Viên Kinh Doanh Bất Động Sản', 'Tìm kiếm và khai thác khách hàng quan tâm và mua các sản phẩm Bất Động Sản. Tư vấn khách hàng các thông tin về sản phẩm, dẫn khách hàng đi xem (Chưa có kinh nghiệm sẽ được đội nhóm hỗ trợ). Hỗ trợ khách hàng trong quy trình mua bán và thủ tục pháp lý để tiến tới hoàn tất giao dịch. Duy trì các mối quan hệ khách hàng hiện có, đồng thời xây dựng kế hoạch tìm kiếm và mở rộng mạng lưới khách hàng tiềm năng. Tham gia triển khai bán hàng, quảng cáo, giới thiệu sản phẩm ra thị trường.', 'Độ tuổi từ 22 tuổi trở lên. Không yêu cầu kinh nghiệm. Yêu thích kinh doanh và đam mê Bất động sản. Có phương tiện đi lại, smartphone.
Kỹ năng mềm: [''Yêu thích kinh doanh'', ''Đam mê Bất động sản'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 100000000.00, '50.0 - 100.0 triệu', 'Tự do thời gian', '[''Được Training và Đào tạo các kỹ năng từ cơ bản - chuyên sâu'', ''Hỗ trợ lên đến 90% chi phí đăng tin quảng cáo tìm kiếm khách hàng, marketing sản phẩm'', ''Cấp chứng chỉ môi giới Bất động sản miễn phí'', ''Thưởng nóng quý/năm'', ''Tham gia các hoạt động ngoại khoá: Du xuân đầu năm, Đi du lịch trong và ngoài nước, Team Building, Bóng đá, thể thao hàng tuần'', ''Được hỗ trợ chi phí ăn trưa, cà phê'', ''Hưởng chế độ BHXH và các chế độ khác theo quy định của Nhà nước'', ''Có lộ trình thăng tiến rõ ràng lên các vị trí cấp cao hơn như Trưởng phòng, Giám đốc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (933, 7, 15, 'CTV Kinh Doanh BĐS Bán Nhà Thổ Cư', '- Nhận nguồn hàng có sẵn từ công ty (hơn 40.000 căn nhà), tiếp cận đến khách hàng tiềm năng. - Khảo sát nguồn nhà có sẵn của Công ty theo từng Quận (chủ động thời gian). - Tìm kiếm khách hàng có nhu cầu mua nhà phố (được đào tạo, cung cấp các công cụ tìm kiếm). - Đăng tin tìm kiếm khách hàng (được đào tạo những thủ thuật hút khách). - Tư vấn và hỗ trợ khách trong quá trình xem nhà, kiểm tra pháp lý, quy hoạch Bất động sản. - Tham gia thương lượng đàm phán để đạt được thoả thuận giữa bên mua và bán. - Phối hợp với Chuyên gia, Trưởng phòng nhiều kinh nghiệm để hoàn thành giao dịch. - Hỗ trợ khách hàng ra công chứng mua bán. - Trao đổi kỹ hơn khi tham gia phỏng vấn.', '- Có điện thoại và phương tiện đi lại. - Chăm chỉ, ham học hỏi. - Nam/ Nữ. Từ 18-60 tuổi, không cần bằng cấp. - Bạn có thể làm nhiều công việc cùng nhau.
Kỹ năng mềm: [''Chăm chỉ'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Lương: thỏa thuận/ hoa hồng tối thiểu 3%/ ít nhất 43 triệu'', ''Nhận phí hoa hồng khi phát sinh giao dịch thành công'', ''Môi trường làm việc năng động, thân thiện'', ''Được đào tạo thường xuyên, cầm tay chỉ việc và hỗ trợ bán hàng từ các cấp quản lý'', ''Cơ hội thăng tiến lên Chuyên gia, Trưởng phòng, Giám đốc rõ ràng'', ''Du lịch trong và ngoài nước miễn phí, Team building thường niên, thể thao bóng đá nâng cao sức khỏe'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (934, 8, 15, 'Thực Tập Sinh Thiết Kế Nội Thất', 'Tham gia cùng bộ phận kinh doanh và phát triển dự án tư vấn mặt bằng, định hướng concept cho khách hàng. Triển khai thiết kế mặt bằng công năng theo yêu cầu của khách hàng. Lên phương án concept cho sản phẩm thiết kế. Triển khai diễn họa 3D nội thất – ngoại thất. Xây dựng và phát triển các mẫu thiết kế mới, cập nhật xu hướng thiết kế nội thất trên thị trường. Các công việc khác theo sự hướng dẫn của Quản lý.', 'Sinh viên Đại học/Cao đẳng/ họa viên trung tâm đào tạo về nội thất/kiến trúc/mỹ thuật công nghiệp (năm 3,4 hoặc đang chờ bằng). Có đam mê với công việc thiết kế nội thất. Sử dụng thành thạo các phần mềm chuyên ngành: Autocad, Sketchup, 3Ds Max, Revit, Corona, Photoshop .... Ưu tiên các ứng viên có khả năng sử dụng đồng thời nhiều phần mềm hỗ trợ và cập nhật xu hướng ứng dụng mới. Tinh thần trách nhiệm trong công việc, khả năng lập kế hoạch và quản lí công việc hiệu quả; Trung thực, thẳng thắn, tuân thủ kỷ luật. Chăm chỉ, chịu khó, có tinh thần cầu tiến.
Kỹ năng chuyên môn: [''Autocad'', ''Sketchup'', ''3Ds Max'', ''Revit'', ''Corona'', ''Photoshop'']
Kỹ năng mềm: [''Tinh thần trách nhiệm trong công việc'', ''Khả năng lập kế hoạch'', ''Quản lí công việc hiệu quả'', ''Trung thực'', ''Thẳng thắn'', ''Tuân thủ kỷ luật'', ''Chăm chỉ'', ''Chịu khó'', ''Có tinh thần cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Có thể linh hoạt thời gian theo lịch học của ứng viên'', ''Được đào tạo kiến thức, kinh nghiệm, kỹ năng làm việc từ các đội ngũ giàu kinh nghiệm'', ''Được làm việc trong môi trường chuyên nghiệp, trẻ trung, năng động, sáng tạo'', ''Được hỗ trợ đóng dấu thực tập'', ''Ưu tiên tuyển dụng nhân viên chính thức sau khi tốt nghiệp'', ''Được hỗ trợ thưởng hoa hồng theo các dự án mà mình đảm nhận được trúng thầu'', ''Được công ty cung cấp hỗ trợ máy tính cấu hình cao phục vụ công việc'', ''Được phụ cấp công tác và các chế độ hoạt động ngoại khóa (team building, tham quan, du lịch)'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (935, 9, 15, 'Thực Tập Sinh Thiết Kế Nội Thất 3D', 'Hỗ trợ thiết kế concept nội thất, triển khai mô hình 3D trên SketchUp. Học hỏi và thực hành về thiết kế không gian, bố cục và vật liệu. Phối hợp với đội ngũ thiết kế để phát triển ý tưởng và hoàn thiện bản vẽ. Chỉnh sửa và hoàn thiện các mô hình 3D theo yêu cầu.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các ngành Kiến trúc, Thiết kế Nội thất, Xây dựng hoặc các ngành liên quan. Có khả năng sử dụng SketchUp cơ bản, biết thêm AutoCAD hoặc Photoshop là lợi thế. Đam mê thiết kế nội thất, mong muốn học hỏi và phát triển trong ngành. Chủ động, sáng tạo, có trách nhiệm trong công việc.
Kỹ năng chuyên môn: [''SketchUp'', ''AutoCAD'', ''Photoshop'']
Kỹ năng mềm: [''Chủ động'', ''Sáng tạo'', ''Có trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 cách tuần', '[''Hỗ trợ lương thực tập 3,000,000 đồng/tháng'', ''Cơ hội tham gia vào các dự án thực tế'', ''Được đào tạo, hướng dẫn trực tiếp bởi đội ngũ thiết kế giàu kinh nghiệm'', ''Môi trường làm việc chuyên nghiệp, năng động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (936, 10, 15, 'Kỹ Sư Xây Dựng Làm Việc Thời Vụ', '1- Giám sát đơn vị nhà thầu thực hiện thi công đảm bảo thực hiện tiến độ và chất lượng theo bản vẽ thiết kế được phê duyệt. 2- Viết nhật ký thi công. 3- Tổng hợp khối lượng báo cáo về phòng kế toán nhà máy hàng ngày. 4- Theo dõi giám sát các đơn vị nhà thầu, tổ đội thi công trên công trường triển khai thi công dự án theo đúng yêu cầu đã đề ra 5- Lên kế hoạch công việc tuần, tháng 6- Tiếp nhận, quản lý cấp phát vật tư, thiết bị, nguyên nhiên vật liệu, công cụ dụng cụ. 7- Theo dõi, Quản lý và báo cáo Khối lượng, chất lượng, tiến độ dự án được phân công theo dõi 8- Nghiệm thu xác nhận khối lượng, chất lượng và thanh, quyết toán cho thầu phụ, các tổ đội thi công, nghiệm thu xác nhận các vật tư, thiết bị, nguyên nhiên vật liệu nhập về cho dự án. 9- Quản lý toàn bộ hồ sơ thanh quyết toán công trình và các tài liệu khác có liên quan đến việc thanh quyết toán công trình. 10- Thực hiện các công việc khác theo sự phân công của lãnh đạo Nhà máy Tinh bột sắn Bá Thước', '1- Nam: từ 32 – 45 tuổi. 2- Tốt nghiệp đại học chuyên ngành xây dựng, kết cấu 3- công trình, kinh tế xây dựng, kiến trúc. 3- Đã có tối thiểu 8-10 năm kinh nghiệm công trình xây dựng nhà xưởng, móng máy, nhà văn phòng bằng thép tiền chế, nhà công nghiệp 4- Am hiểu định mức dự toán trong một công trình (kiến trúc, kết cấu, hệ thống điện,..). Phải am hiểu bóc tách khối lượng các hạng mục bản vẽ thiết kế. 5- Thành thạo Cad, Word Excel.
Kỹ năng chuyên môn: [''Cad'', ''Word'', ''Excel'']', 'PART_TIME', 'ONSITE', 'bá thước', NULL, 'MONTHLY', 4000000.00, '0.0 triệu', 'Cả tuần bám theo tiến độ công việc triển khai thực tế trên công trường', '[''Thưởng hiệu quả công việc'', ''Bao ăn ở tại Nhà máy'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (937, 2, 15, 'Cộng Tác Viên Thực Tập Sinh Kinh Doanh', 'Tìm kiếm khách hàng, thuyết phục khách hàng trong công tác bán sản phẩm thuộc khối Housing ban hành (căn hộ, phòng trọ, toà nhà vận hành...). Hướng dẫn hỗ trợ khách hàng xem, ký hợp đồng căn hộ, phòng trọ trong hệ thống. Phát triển Hệ thống Fanpage được phân giao theo sự hướng dẫn của các cấp Quản lý. Chia sẻ/Seeding các bài viết từ Fanpage chính thức vào các Group thông qua sự phân giao từ các cấp quản lý.', 'Giới tính: Nam/Nữ. Độ tuổi: 18-21 tuổi (Sinh viên các trường đại học tại Đà Nẵng năm 1 – năm 4).
Kỹ năng mềm: [''Xử lý vấn đề nhanh'', ''Nắm bắt tâm lý khách hàng'', ''Cam kết bảo mật thông tin khách hàng'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 7000000.00, '4.0 - 7.0 triệu', 'Thứ 2 - Thứ 7 (08:00 - 18:00)', '[''Lương cơ bản từ 1.200.000 - 3.000.000đ + KPIs + thưởng nóng'', ''Cơ hội thăng tiến làm nhân viên chính thức'', ''Đào tạo phân tích thị trường'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (938, 3, 15, 'Thực tập thử nghiệm ô tô', 'Hỗ trợ bằng văn bản và xem xét các trường hợp kiểm tra theo hướng dẫn. Hỗ trợ thiết lập thử nghiệm: Kết nối ECU, cảm biến và dây nối. Tham gia vào các hoạt động thử nghiệm cơ bản trong môi trường HIL hoặc labcar. Thu thập và tổ chức dữ liệu kiểm tra. Giúp phân tích kết quả kiểm tra đơn giản và chuẩn bị các báo cáo kiểm tra cơ bản. Nhóm hỗ trợ theo dõi các vấn đề kiểm tra bằng các công cụ nội bộ (ví dụ: JIRA). Tìm hiểu và hỗ trợ viết các tập lệnh tự động hóa cơ bản (Python hoặc CAPL).', 'Final-year student or fresh graduate in Electrical Engineering, Automotive Engineering, Mechatronics, or related fields. Basic knowledge of automotive electrical systems and CAN/LIN communication is a plus. Interest in automotive software testing and automation. Familiar with Python or C programming is a plus. Good logical thinking, careful and detail-oriented. Willingness to learn and cooperate in team-based environment. Basic English communication and documentation skills.
Kỹ năng chuyên môn: [''Basic knowledge of automotive electrical systems'', ''CAN/LIN communication'', ''Python'', ''C programming'']
Kỹ năng mềm: [''Good logical thinking'', ''Careful and detail-oriented'', ''Willingness to learn'', ''Cooperate in team-based environment'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hands-on experience with real automotive components and test systems'', ''Opportunity to learn from experienced engineers'', ''Participate in real EV development projects'', ''Monthly internship allowance'', ''Opportunity to be considered for full-time position after internship'', ''Ăn trưa'', ''Được cấp Máy tính'', ''Du lịch hàng năm'', ''Team building'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (939, 7, 15, 'Thực Tập Sinh Thiết Kế Nội Thất Fulltime', '– Khảo sát đo đạc tiếp thu ý kiến khách hàng, lên ý tưởng thiết kế. – Thiết kế nội thất: văn phòng, nhà phố, chung cư,..... – Dựng phối cảnh 3D, sketchup, hoặc triển khai hồ sơ kỹ thuật 2D theo yêu cầu thiết kế nội thất của khách hàng. – Giám sát tác giả thiết kế trong quá trình thi công những công trình đang thực hiện. – Thực hiện các công việc nghiệp vụ và công việc khác.', '– Nam/Nữ từ 20 – 24 tuổi, - Đang chờ bằng/ tốt nghiệp Cao đẳng trở lên ngành Thiết kế nội thất, Kiến trúc, Xây dựng,… – Yêu cầu thành thạo AutoCAD, SketchUp, 3D Max.
Kỹ năng chuyên môn: [''AutoCAD'', ''SketchUp'', ''3D Max'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Hỗ trợ dấu mộc, lương thực tập'', ''Môi trường làm việc chuyên nghiệp, năng động'', ''Được đào tạo, trao dồi chuyên môn thường xuyên'', ''Tham gia tiệc mỗi tháng, đi du lịch hàng năm do Công ty tổ chức'', ''Có cơ hội làm nhân viên chính thức tại công ty'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (940, 8, 15, 'Thực Tập Sinh Kỹ Thuật', 'TTS - KỸ THUẬT TÒA NHÀ - Theo dõi, xử lý yêu cầu bảo hành thiết bị trong căn hộ. - Xử lý các lỗi kỹ thuật liên quan đến thẻ xe, FaceID, thẻ ra vào. - Tiếp nhận và thực hiện yêu cầu trên hệ thống Salesforce. - Kiểm tra định kỳ hệ thống kỹ thuật tại các phòng máy (tầng hầm) theo checklist. - Tham gia bảo trì, bảo dưỡng, kiểm định hệ thống kỹ thuật tòa nhà. - Kiểm tra, nghiệm thu các căn hộ sau thi công. - Đóng góp cải tiến quy trình kỹ thuật và tham gia các khóa đào tạo nội bộ. - Thực hiện báo cáo công việc định kỳ, nhập số liệu và tuân thủ quy trình công ty.', 'Yêu cầu ứng viên - Sinh viên năm 3 hoặc 4 các ngành: Kỹ thuật, Cơ khí, Cơ điện, Điện – Nước, Xây dựng, Quản lý công trình hoặc các ngành liên quan. - Bằng cấp từ Trung cấp trở lên, GPA tối thiểu 2.8/4.0 hoặc 6.0/10. - Kỹ năng giao tiếp, xử lý tình huống và thái độ làm việc tích cực.
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Xử lý tình huống'', ''Thái độ làm việc tích cực'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Giờ làm linh hoạt', '[''Làm việc tại các tòa nhà hiện đại, quy mô lớn, môi trường chuyên nghiệp và uy tín hàng đầu trong ngành BĐS.'', ''Hướng dẫn trực tiếp từ mentor giàu kinh nghiệm.'', ''Cơ hội trở thành nhân viên chính thức mới mức lương cạnh tranh sau thực tập.'', ''Tham gia đào tạo chuyên sâu trong chương trình GEN M Future Talents.'', ''Phụ cấp cạnh tranh'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (941, 9, 15, 'Nhân Viên Dự Toán QS', 'Dự án Tender dự thầu: Nhận thông tin hồ sơ mời thầu từ phòng Sales bao gồm: phạm vi công việc (SOW), bảng khối lượng (BOQ), hình ảnh phối cảnh_3D, bản vẽ thiết kế / bản vẽ chi tiết, spec nguyên vật liệu, màu sắc hoàn thiện, spec FF&E, Họp triển khai báo giá với PD. Đo đạc, bốc tách khối lượng bao gồm các các công tác Fit-out liên quan hoàn thiện nội thất trần, tường, sàn, công tác đồ liền tường, đồ rời theo phạm vi hạng mục công việc được mô tả trong hồ sơ mời thầu. Không bao gồm các công tác ngoại thất, kết cấu, Landscape, MEP... Lập bảng kê danh mục chủng loại vật tư kèm khối lượng sơ bộ theo bản vẽ thiết kế, spec nguyên vật liệu trong hồ sơ mời thầu. Triển khai thông tin cho phòng Sourcing để lấy báo giá từ nhà cung cấp và Thầu Phụ. Tính giá sản phẩm đồ gỗ liền tường & nội thất rời. Đánh giá kiểm tra các báo giá, tiến hành nhập đơn giá vào BOQ để lập bảng báo giá tổng hợp. Khi có thông tin “Lệnh Khởi Công”, tiến hành upload BOQ (mã BOQ, giá bán, giá Cost tender, giá giao) theo Template quy định lên hệ thống SAP. Nhận hợp đồng điền các thông tin chi tiết của dự án và giá trị, chuyển Hợp đồng cho phòng hợp đồng kiểm tra và thông tin cho các điều khoản hợp đồng, in ấn Trình kí.', 'Tốt nghiệp CĐ/ ĐH chuyên ngành kinh tế - dự toán xây dựng, quản lý dự án. Ít nhất 1 năm kinh nghiệm ở vai trò dự toán về mảng (Kiến trúc, nội thất, hoặc vật liệu nội thất). Có thể đọc hiểu bản vẽ/shopdrawing. Ưu tiên có thể sử dụng được tiếng Anh.
Kỹ năng chuyên môn: [''Đọc hiểu bản vẽ/shopdrawing'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)', '[''Đóng BHXH, BHYT, BH PVI ... theo luật quy định'', ''Được tham gia du lịch, team-building'', ''Xét đánh giá: 1 năm 2 lần'', ''Các phúc lợi khác theo quy định công ty'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (942, 10, 15, 'Thực Tập Sinh Sales', '– Hỗ trợ tìm kiếm, tư vấn khách hàng tiềm năng theo danh sách được cung cấp. – Tư vấn thông tin sản phẩm, dự án bất động sản đang phân phối. – Cập nhật tiến độ dự án, tham gia các buổi training và sự kiện bán hàng. – Thực hiện các công việc theo sự phân công của quản lý.', '– Các bạn ngành Kinh doanh, Marketing, Quản trị hoặc yêu thích BĐS. – Năng động, ham học hỏi, chịu khó và có tinh thần cầu tiến. – Giao tiếp tốt, có laptop và phương tiện di chuyển cá nhân.
Kỹ năng mềm: [''Năng động'', ''Ham học hỏi'', ''Chịu khó'', ''Có tinh thần cầu tiến'', ''Giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 10000000.00, '2.0 - 10.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Được đào tạo bài bản kỹ năng sale, chăm sóc khách hàng, tư duy tư vấn chiến lược'', ''Làm việc trực tiếp cùng đội ngũ cố vấn giàu kinh nghiệm trong ngành'', ''Có hỗ trợ chi phí và hoa hồng hấp dẫn ngay trong quá trình thực tập'', ''Môi trường làm việc trẻ trung – năng động – chuyên nghiệp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (943, 2, 15, 'Thực Tập Sinh Kinh Doanh', '- Hỗ trợ đội ngũ kinh doanh trong việc tìm kiếm khách hàng mới thông qua các kênh trực tuyến và offline (quảng cáo, mạng xã hội, website, sự kiện...). - Hỗ trợ nghiên cứu thị trường, thu thập thông tin khách hàng và được đào tạo về phân tích nhu cầu của khách hàng tiềm năng. - Cập nhật và theo dõi thông tin khách hàng tiềm năng theo dữ liệu có sẵn từ công ty. - Tham gia vào quá trình hỗ trợ tư vấn khách hàng về các sản phẩm, dự án bất động sản của công ty. - Thực hiện các công việc khác theo chỉ đạo của cấp trên', '- Sinh viên năm 3, năm 4 có thể làm fulltime. - Ưu tiên sinh viên theo học các chuyên ngành về Bất động sản, Kinh tế, Quản trị kinh doanh... - Ham học hỏi, tinh thần nhiệt huyết, có thái độ cầu tiến. - Có phương tiện đi lại, laptop và biết sử dụng nhiều nền tảng mạng xã hội.
Kỹ năng chuyên môn: [''Sử dụng nền tảng mạng xã hội'']
Kỹ năng mềm: [''Ham học hỏi'', ''Tinh thần nhiệt huyết'', ''Thái độ cầu tiến'', ''Làm việc nhóm'', ''Giao tiếp'', ''Trung thực'', ''Chăm chỉ'', ''Khả năng học hỏi nhanh'', ''Kỹ năng bán hàng'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Từ thứ Hai đến sáng thứ Bảy; Sáng: 8h30 - 12h00, Chiều: 13h - 17h30', '[''Thu nhập không giới hạn (3 triệu + Thưởng nóng + Thưởng doanh số + % Hoa hồng)'', ''Thưởng các ngày lễ, tết theo quy định của công ty và nhà nước'', ''Du lịch hàng năm'', ''Đánh giá lên chính thức sau 2 tháng'', ''Môi trường làm việc năng động, trẻ trung, chuyên nghiệp, hiện đại, văn phòng sang xịn'', ''Hỗ trợ chi phí Marketing về sản phẩm, dự án của công ty'', ''Được đào tạo bài bản từ A đến Z về các kỹ năng: tìm kiếm, chăm sóc và chốt khách, hỗ trợ chốt deal đến khi có giao dịch'', ''Hỗ trợ dấu thực tập'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (944, 3, 15, 'Thực Tập Sinh Bất Động Sản', 'Mô tả công việc * Hỗ trợ đội ngũ kinh doanh trong việc giới thiệu, tư vấn sản phẩm bất động sản (đất nền, căn hộ, nhà phố, shophouse,…). * Tìm kiếm và chăm sóc khách hàng qua các kênh: Facebook, Zalo, telesales, data marketing,... * Tham gia tổ chức các sự kiện mở bán, hội thảo đầu tư, tham quan dự án. * Cập nhật thông tin thị trường, sản phẩm để tư vấn cho khách hàng chính xác và hiệu quả. * Thực hiện báo cáo công việc định kỳ cho trưởng nhóm.', 'Yêu cầu ứng viên * Yêu thích lĩnh vực bất động sản và định hướng theo nghề môi giới/chuyên viên tư vấn đầu tư. * Giao tiếp tốt, chịu khó, nhanh nhẹn, có tinh thần cầu tiến. * Không yêu cầu kinh nghiệm – sẽ được đào tạo bài bản từ A–Z. * Có laptop và phương tiện di chuyển.
Kỹ năng chuyên môn: [''Facebook'', ''Zalo'', ''Telesales'', ''Laptop'']
Kỹ năng mềm: [''Yêu thích lĩnh vực bất động sản'', ''Giao tiếp tốt'', ''Chịu khó'', ''Nhanh nhẹn'', ''Có tinh thần cầu tiến'', ''Làm việc nhóm'', ''Khả Năng Học Hỏi Nhanh'', ''Chăm Chỉ'', ''Siêng Năng'', ''Trung Thực'', ''Có Trách Nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 20000000.00, '10.0 - 20.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30). Chiều thứ 02 đến thứ 06, sáng thứ 07, sáng chủ nhật đi sự kiện.', '[''Được đào tạo chuyên sâu về kiến thức thị trường, kỹ năng tư vấn, chăm sóc khách hàng,...'', ''Có cơ hội thực chiến và tạo thu nhập ngay từ khi thực tập.'', ''Môi trường làm việc năng động, chuyên nghiệp, đồng nghiệp trẻ trung, hỗ trợ tận tình.'', ''Hỗ trợ dấu mộc/thư xác nhận thực tập nếu cần.'', ''Thu nhập hấp dẫn (10 – 20 triệu/tháng nếu làm tốt).'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (945, 7, 15, 'Thực Tập Sinh Phát Triển Dự Án', 'Mô tả công việc: * Tìm kiếm, khảo sát và khai thác thông tin các dự án BĐS nhằm phục vụ theo kế hoạch của Công ty; * Xây dựng bảng giá, chính sách bán hàng, tính toán cấu trúc giá bán phù hợp với mục tiêu kinh doanh. * Lập phương án và đề xuất kế hoạch kinh doanh chi tiết theo từng dự án cụ thể; * Phối hợp với các bộ phận Thư ký, Pháp chế, Marketing, Kinh doanh xây dựng quy trình bán hàng, quy trình giao dịch, kế hoạch truyền thông marketing; * Tham gia quá trình đàm phán hợp đồng với các đối tác Chủ Đầu tư. Làm các thủ tục liên quan đến công tác ký kết hợp tác với các đối tác Chủ Đầu tư và đơn vị phân phối; * Theo dõi, báo cáo và thúc đẩy tiến độ bán hàng của dự án triển khai; * Các công việc khác theo sự phân công của quản lý. Quyền lợi: Công ty hỗ trợ lương cứng 4tr + dấu thực tập trong quá trình phỏng vấn. Nếu làm tốt, sẽ chuyển từ thực tập sinh lên làm nhân viên chính thức, tham gia bảo hiểm, hưởng các chế độ đãi ngộ của công ty. Được đào tạo các kỹ năng cần thiết cho công việc chuyên viên liên quan phát triển dự án. Có cơ hội thăng tiến lên các vị trí chính thức của công ty. Làm việc trong môi trường văn phòng hạng A, chuyên nghiệp, nhân sự gen Z vui tính hòa đồng.', '• Sinh viên chuẩn bị tốt nghiệp, sinh viên năm cuối Cao đẳng/Đại học các chuyên ngành liên quan Bất động sản, Xây dựng, Kinh tế,… • Có thể đi làm full time. ( ứng viên chuẩn bị ra trường) • Chăm chỉ chịu khó, trung thực. • Kĩ năng giao tiếp tốt, muốn phát triển kĩ năng mềm. • Mong muốn hoặc định hướng phát triển và gắn bó lâu dài với công ty.
Kỹ năng chuyên môn: [''Kỹ Năng Lập Trình (tùy Thuộc Vào Dự Án)'']
Kỹ năng mềm: [''Chăm chỉ'', ''chịu khó'', ''trung thực'', ''Kĩ năng giao tiếp tốt'', ''phát triển kĩ năng mềm'', ''Làm việc nhóm'', ''Quản lý thời gian'', ''phân tích yêu cầu'', ''Giải quyết vấn đề'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Dấu thực tập'', ''Cơ hội trở thành nhân viên chính thức'', ''Tham gia bảo hiểm (nếu chuyển chính thức)'', ''Hưởng các chế độ đãi ngộ của công ty (nếu chuyển chính thức)'', ''Được đào tạo các kỹ năng cần thiết cho công việc chuyên viên liên quan phát triển dự án'', ''Có cơ hội thăng tiến lên các vị trí chính thức của công ty'', ''Làm việc trong môi trường văn phòng hạng A'', ''Môi trường chuyên nghiệp'', ''Nhân sự Gen Z vui tính hòa đồng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (946, 8, 15, 'Kỹ Sư Trắc Đạc', '- Lập phương án và kế hoạch trắc địa các công trình của công ty; - Thực hiện công tác đo đạc, trắc địa; - Định vị và đảm bảo tính chính xác các điểm tím, mốc công trình ngoài thực tế; - Quản lý, giám sát hiệu quả sử dụng máy thiết bị; - Chuẩn bị, thực hiện công tác nghiệm thu, bàn giao theo đúng thiết kế; - Viết và nộp báo cáo theo chính sách công ty; - Các công việc khác theo yêu cầu của Ban lãnh đạo.', '- Tốt nghiệp Cao đẳng, Đại học các trường kỹ thuật: Giao thông, Xây dựng, Thủy Lợi, Mỏ địa chất chuyên ngành đo đạc công trình; - Ưu tiên các bạn có kinh nghiệm; - Chấp nhận đào tạo cho các bạn mới ra học khoa công trình ngành nghề công nghiệp dân dụng hoặc trắc địa; - Nắm vững các quy định pháp luật về xây dựng, tiêu chuẩn xây dựng và các quy định có liên quan đến công tác trắc đạc; - Có khả năng chịu áp lực công việc tốt, có tinh thần cầu tiến, yêu nghề và chuyên tâm với công việc; - Có kỹ năng làm việc độc lập hoặc theo nhóm; - Trung thực, tư cách đạo đức nghề nghiệp tốt.
Kỹ năng chuyên môn: []
Kỹ năng mềm: [''Có khả năng chịu áp lực công việc tốt'', ''Có tinh thần cầu tiến'', ''Yêu nghề và chuyên tâm với công việc'', ''Có kỹ năng làm việc độc lập hoặc theo nhóm'', ''Trung thực'', ''Tư cách đạo đức nghề nghiệp tốt'']', 'PART_TIME', 'ONSITE', 'hà nội, hải phòng', 'Hà Nội', 'MONTHLY', 18000000.00, '10.0 - 18.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Mức lương/ thưởng hấp dẫn: 10 - 18 triệu/tháng (Thỏa thuận cụ thể khi phỏng vấn); Nuôi ăn ở'', ''Làm việc tại Tập đoàn lớn 4000 nhân sự, công việc ổn định, lâu dài, cơ hội thăng tiến cao'', ''Xét tăng lương một lần/ năm phù hợp với sự nỗ lực, đóng góp cho sự phát triển công ty'', ''Được tham gia đầy đủ BHXH, BHYT và các chế độ phúc lợi khác theo quy định của công ty.'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (947, 9, 15, 'Thực Tập Sinh Kinh Doanh', 'Hỗ trợ tìm kiếm và tiếp cận khách hàng tiềm năng (trực tuyến và trực tiếp). Thực hành quy trình bán hàng thực chiến: từ tư vấn, chốt đơn đến chăm sóc sau bán. Cập nhật thông tin khách hàng và đơn hàng lên hệ thống. Tham gia họp và các hoạt động nội bộ cùng team Kinh doanh. Được đào tạo bài bản về sản phẩm nội thất, kỹ năng bán hàng và tư duy kinh doanh thực tế. Quyền lợi: Trợ cấp: 1.500.000 – 3.000.000 VNĐ/tháng (tùy năng lực) + hoa hồng theo kết quả. Đào tạo & phát triển: Hướng dẫn 1:1 cùng đội ngũ kinh doanh giàu kinh nghiệm, Cơ hội tham gia các dự án thực tế, làm việc với khách hàng thật. Môi trường làm việc: Trẻ trung, năng động, sáng tạo, Được công nhận và tạo điều kiện phát triển năng lực cá nhân. Cơ hội: Xét lên nhân viên chính thức sau thời gian thực tập nếu thể hiện tốt. Phụ cấp: Xăng xe. Thiết bị làm việc: Được cấp Máy tính.', 'Sinh viên năm cuối hoặc đã tốt nghiệp Cao đẳng/Đại học các ngành: Quản trị Kinh doanh, Kinh tế, Tài chính hoặc lĩnh vực liên quan Có thể làm việc toàn thời gian (full-time) Ưu tiên ứng viên có kiến thức về nội thất (không bắt buộc – sẽ được đào tạo) Giao tiếp tốt, yêu thích kết nối và làm việc với con người Sẵn sàng khảo sát thị trường và gặp gỡ khách hàng khi cần Chủ động, ham học hỏi, có tinh thần trách nhiệm cao
Kỹ năng mềm: [''Giao tiếp tốt'', ''Yêu thích kết nối và làm việc với con người'', ''Chủ động'', ''Ham học hỏi'', ''Có tinh thần trách nhiệm cao'', ''Làm việc nhóm'', ''Khả Năng Học Hỏi Nhanh'', ''Chăm chỉ'', ''Trung thực'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh, thành phố thủ đức, quận 9', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Trợ cấp: 1.500.000 – 3.000.000 VNĐ/tháng (tùy năng lực) + hoa hồng theo kết quả'', ''Đào tạo & phát triển: Hướng dẫn 1:1 cùng đội ngũ kinh doanh giàu kinh nghiệm'', ''Cơ hội tham gia các dự án thực tế, làm việc với khách hàng thật'', ''Môi trường làm việc: Trẻ trung, năng động, sáng tạo'', ''Được công nhận và tạo điều kiện phát triển năng lực cá nhân'', ''Cơ hội: Xét lên nhân viên chính thức sau thời gian thực tập nếu thể hiện tốt'', ''Phụ cấp: Xăng xe'', ''Thiết bị làm việc: Được cấp Máy tính'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (948, 10, 15, 'Thực Tập Sinh Kỹ Sư MEP', 'Hỗ trợ thiết kế, triển khai và giám sát thi công hệ thống cơ khí, điện, cấp thoát nước của các hạng mục dự án xây dựng. Hỗ trợ tính toán, bóc tách khối lượng, lập kế hoạch – đề xuất vật tư, hồ sơ thanh toán. Hỗ trợ lập hồ sơ quản lý chất lượng, bản vẽ hoàn công. Phối hợp với các bộ liên quan, tham gia công tác giám sát đảm bảo các hệ thống MEP được triển khai chính xác và tuân thủ các tiêu chuẩn kỹ thuật, chất lượng và an toàn. Hỗ trợ lập báo cáo kỹ thuật, báo cáo tiến độ và các tài liệu liên quan đến công việc của hệ thống MEP cho Ban Giám đốc và các phòng ban liên quan. Thực hiện các nhiệm vụ khác theo phân công từ Ban Giám đốc.', 'Sinh viên năm cuối hoặc mới tốt nghiệp, có kiến thức về các chuyên ngành: Cơ khí, Điện, MEP hoặc các ngành kỹ thuật liên quan. Có khả năng tự tìm hiểu các tài liệu chuyên ngành để nâng cao năng lực và cập nhật các kỹ thuật, công nghệ mới liên quan đến công việc được phân công. Trung thực, có trách nhiệm với công việc và có khả năng làm việc theo nhóm, giao tiếp và phối hợp làm việc nhóm tốt. Năng động, tác phong làm việc chuyên nghiệp, xử lý tình huống nhanh nhẹn, quyết đoán. Thời gian thực tập: 05-06 ngày/tuần, tối thiểu 03 tháng. Có thể làm việc trực tiếp tại Dự án (trao đổi chi tiết khi phỏng vấn).
Kỹ năng chuyên môn: [''Khả Năng Đọc Và Hiểu Bản Vẽ Kỹ Thuật'', ''Sử Dụng Phần Mềm Thiết Kế Cad (Autocad, Revit)'', ''Kiến Thức Cơ Bản Về Kỹ Thuật Mep (Mechanical, Electrical, Plumbing)'']
Kỹ năng mềm: [''Khả Năng Học Hỏi Nhanh'', ''Khả Năng Làm Việc Nhóm'', ''Trung thực'', ''Có trách nhiệm với công việc'', ''Giao tiếp'', ''Phối hợp làm việc nhóm tốt'', ''Năng động'', ''Tác phong làm việc chuyên nghiệp'', ''Xử lý tình huống nhanh nhẹn'', ''Quyết đoán'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh, bình thạnh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', '05-06 ngày/tuần, tối thiểu 03 tháng', '[''Phụ cấp thực tập: 3.000.000 đồng'', ''Được đào tạo chuyên môn & bản thân khi thực tập tại Công ty'', ''Cơ hội trở thành nhân viên chính thức'', ''Môi trường làm việc quốc tế thân thiện & chuyên nghiệp'', ''Được hưởng các quyền lợi khác theo chính sách công ty'', ''Hỗ trợ đóng dấu mộc và báo cáo thực tập'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (949, 2, 15, 'Nhân Viên Thiết Kế', '- Đề xuất ý tưởng thông qua các khái niệm, Moodboard, Layout thiết kế sơ bộ. - Phát triển phương án 3D, điều chỉnh theo yêu cầu Khách hàng (nếu có). - Phối hợp chặt chẽ với các bộ môn trong giai đoạn báo giá và thi công dự án.', '- Tốt nghiệp ĐH chuyên ngành thiết kế các trường đào tạo kiến trúc và nội thất - Biết sử dụng các phần mềm Autocad, 3Dmax, Photoshop, Sketchup,... là một lợi thế - Nhanh nhẹn, chăm chỉ
Kỹ năng chuyên môn: [''Autocad'', ''3Dmax'', ''Photoshop'', ''Sketchup'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chăm chỉ'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 18000000.00, '16.0 - 18.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''% hoa hồng theo công trình'', ''Được hưởng một mức lương như mong muốn.'', ''Mội trường làm việc chuyên nghiệp, đồng nghiệp hòa đồng,thân thiện và chia sẻ.'', ''Văn phòng làm việc hiện đại, tiện nghi mang lại cho bạn cảm giác thoải mái đến không ngờ.'', ''Được hưởng đầy đủ các chế độ như bộ luật lao động qui định.'', ''Được trải nghiệm vào thức tế các công trình và nhanh chóng trưởng thành hơn sự mong đợi.'', ''Được tăng lương ngay khi chúng tôi nhận thấy năng lực của bạn vượt trội.'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (950, 3, 15, 'Thực Tập Sinh Kinh Doanh', '* Tìm hiểu, nghiên cứu về các sản phẩm bất động sản của công ty để giới thiệu, tư vấn và giải đáp thắc mắc cho khách hàng (các dự án tại Hà Nội). * Giới thiệu, tư vấn giải pháp tài chính về BĐS và thuyết phục khách hàng đầu tư dự án của công ty. * Đàm phán, thương lượng với khách hàng về giá cả, hợp đồng, tiến hành chốt đơn và hỗ trợ khách hàng ký hợp đồng. * Chăm sóc khách hàng sau khi bán hàng, duy trì mối quan hệ với khách hàng hiện tại. * Tìm kiếm khách hàng qua các kênh được hướng dẫn và cung cấp data. * Nghiên cứu chiến dịch kinh doanh, xây dựng đội nhóm để có cơ hội thăng tiến các vị trí cao hơn. * Tất cả các nghiệp vụ chuyên môn, kiến thức dự án, kỹ năng mềm... sẽ được đào tạo và hướng dẫn kèm cặp từ Trưởng phòng/ Giám đốc Kinh doanh', '* Sinh viên năm 4 có thể đi làm fulltime. * Phương tiện làm việc và di chuyển: Xe máy, điện thoại, laptop. * Không yêu cầu giới tính, độ tuổi từ 19 trở lên. * Sẽ được đào tạo và dẫn dắt từ đầu.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Kỹ năng làm việc nhóm'', ''Khả Năng Học Hỏi Nhanh'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:00)', '[''Hỗ trợ lương + hoa hồng + thưởng doanh thu'', ''Hỗ trợ dấu thực tập'', ''Đóng BHXH đầy đủ'', ''tham gia các chương trình gắn kết, Teambuilding hằng năm, thưởng sinh nhật, thưởng lễ tết các dịp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (951, 7, 15, 'Thực Tập Sinh Kinh Doanh', '* Hỗ trợ bộ phận Kinh doanh trong việc tìm kiếm, tiếp cận và chăm sóc khách hàng tiềm năng * Gọi điện thoại tư vấn sản phẩm/dịch vụ theo data có sẵn hoặc tự tìm kiếm * Hỗ trợ xây dựng và triển khai các chương trình bán hàng, khuyến mãi. * Tham gia trực tiếp vào các buổi gặp gỡ khách hàng (nếu có) * Cập nhật dữ liệu khách hàng, báo cáo kết quả công việc hàng ngày/tuần * Thực hiện các công việc khác theo phân công của quản lý', '* Sinh viên năm 3, năm 4 các ngành Kinh doanh, Marketing, Quản trị Kinh doanh hoặc các ngành liên quan khác * Yêu thích công việc kinh doanh * Giao tiếp tốt, tự tin, năng động * CÓ tinh thần học hỏi, chủ động và trách nhiệm trong công việc * Ứng viên có thể thực tập toàn thời gian
Kỹ năng mềm: [''Giao tiếp tốt, tự tin, năng động'', ''CÓ tinh thần học hỏi, chủ động và trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hải phòng', 'Hải Phòng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30) Thứ 7 (từ 08:00 đến 12:00)', '[''Hỗ trợ thực tập: 3.000.000 đồng/tháng'', ''Được đào tạo kỹ năng bán hàng, giao tiếp, làm việc nhóm và các kiến thức về sản phẩm'', ''Môi trường làm việc trẻ trung, năng động, hỗ trợ tận tình'', ''Hỗ trợ xác nhận thực tập và đánh giá kết quả thực tập (nếu cần)'', ''Có cơ hội được trở thành nhân viên của công ty sau thời gian thực tập.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (952, 8, 15, 'Cộng Tác Viên Kiến Trúc - Nội Thất', '* Tìm hiểu nhu cầu của khách hàng, khảo sát mặt bằng, bối cảnh địa điểm, xu hướng thiết kế * Phân chia mặt bằng không gian, phân tích các yếu tố về công năng, thẩm mỹ, phong thủy (nếu cần) * Lên ý tưởng tổng thể cho công trình (hình khối, phong cách, không gian) và tư vấn trang trí, phong cách, màu sắc, chất liệu theo yêu cầu của khách hàng * Vẽ phác thảo (sketch) hoặc dựng hình 3D để truyền tải ý tưởng * Chuẩn bị bản vẽ sơ bộ, bản vẽ phối cảnh để trình bày với khách hàng và điều chỉnh theo phản hồi * Phối hợp với bộ phận liên quan để đảm bảo khả thi về công năng và thẩm mỹ', '* Đang ở Hà Nội, có thể gặp khách trực tiếp để trao đổi chuyên môn * Tốt nghiệp cao đẳng, đại học chuyên ngành Kiến trúc, thiết kế nội thất * Ưu tiên có kinh nghiệm thiết kế công trình nhà dân, chung cư mini, căn hộ dịch vụ, sử dụng AI trong công việc * Tư duy thẩm mỹ tốt, sáng tạo, có khả năng phát triển ý tưởng độc đáo * Biết vẽ tay, phác thảo ý tưởng nhanh là một lợi thế * Sử dụng thành thạo các phần mềm thiết kế 2D, 3D: Autocad, 3Ds Max, SketchUp, Lumion,… hoặc các phần mềm thiết kế tương đương khác * Có khả năng sáng tạo, tư duy thẩm mỹ và am hiểu về kiến trúc * Biết trình bày, bảo vệ ý tưởng, giao tiếp tốt với khách hàng và đội nhóm
Kỹ năng chuyên môn: [''Autocad'', ''3Ds Max'', ''SketchUp'', ''Lumion'']
Kỹ năng mềm: [''Tư duy thẩm mỹ tốt'', ''Sáng tạo'', ''Khả năng phát triển ý tưởng độc đáo'', ''Biết trình bày'', ''Giao tiếp tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Hình thức làm việc từ xa'', ''Thời gian làm việc linh hoạt'', ''Hoa hồng theo dự án thực tế'', ''Được tạo điều kiện học tập, nâng cao kỹ năng'', ''Môi trường làm việc trẻ trung năng động'', ''Có lộ trình thăng tiến rõ ràng'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (953, 9, 15, 'Thực Tập Sinh Thiết Kế Nội Thất Trên Phần Mềm Jega', '- Hỗ trợ thiết kế, làm việc theo sự phân công của phòng ban -Sử dụng thành thạo phần mềm thiết kế Jega, hỗ trợ & đào tạo về mặt kỹ thuật cho khách hàng - Tư vấn về thiết kế nội thất. - Thiết kế phối cảnh 3D. - Triển khai chi tiết bản vẽ kỹ thuật chi tiết nếu cần - Hỗ trợ các công việc khác của phòng ban, phối hợp với các thành viên trong công ty để hoàn thành công việc. - Mức hỗ trợ thực tập phù hợp - Môi trường làm việc thoải mái, đội ngũ nhân viên trẻ trung thỏa sức sáng tạo, hỗ trợ và đào tạo nhiệt tình - Linh động thời gian làm việc để phù hợp với lịch học. - Trở thành nhân viên chính thức và được kết nối về mặt công việc với các khách hàng lớn/ đối tác của Công ty sau khi hoàn thành chương trình thực tập', '- Sinh viên các trường ĐH, CĐ chuyên ngành Kiến trúc, Xây dựng, thiết kế nội thất, ưu tiên các bạn đã hoàn thành xong chương trình học. - Tinh thần trách nhiệm công việc cao. - Thành thạo các phần mềm chuyên dụng phục vụ thiết kế như Autocad, 3Dmax, Sketchup, photoshop... - Luôn cập nhật xu thế nội thất để đảm bảo thiết kế có tính sáng tạo, thẩm mỹ cao, định hướng nhu cầu và có thể khai thác thương mại trên thị trường. - Tinh thần trách nhiệm công việc cao, thái độ làm việc tốt.
Kỹ năng chuyên môn: [''Jega'', ''Autocad'', ''3Dmax'', ''Sketchup'', ''photoshop'', ''3ds Max'', ''Revit'', ''Vẽ Tay'']
Kỹ năng mềm: [''Tinh thần trách nhiệm công việc cao'', ''Thái độ làm việc tốt'', ''Khả năng Làm Việc Nhóm'', ''Sáng tạo'', ''Thẩm mỹ cao'', ''Định hướng nhu cầu thị trường'', ''Khả năng khai thác thương mại'']', 'INTERNSHIP', 'ONSITE', 'cầu giấy, hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)', '[''Mức hỗ trợ thực tập phù hợp'', ''Môi trường làm việc thoải mái, đội ngũ nhân viên trẻ trung thỏa sức sáng tạo'', ''Hỗ trợ và đào tạo nhiệt tình'', ''Linh động thời gian làm việc để phù hợp với lịch học'', ''Cơ hội trở thành nhân viên chính thức'', ''Được kết nối về mặt công việc với các khách hàng lớn/ đối tác của Công ty sau khi hoàn thành chương trình thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (954, 10, 15, 'Thực Tập Sinh Thiết Kế Nội Thất', 'Hỗ trợ thiết kế 2D-3D nội thất theo yêu cầu của cấp trên hoặc khách hàng. Hỗ trợ trình bày bản vẽ, hồ sơ thiết kế để trình bày cho khách hàng. Tham gia đo đạc, khảo sát và lên ý tưởng thiết kế sơ bộ dựa vào hiện trạng các công trình (nếu có). Tham gia quá trình giám sát, theo dõi quá trình thi công để học hỏi. Thực hiện các công việc khác theo phân công từ cấp trên. Được mentor trực tiếp bởi các chuyên gia nội thất tại Baha Homes. Cơ hội tiếp cận AI và các công cụ thiết kế hiện đại. Làm việc trong môi trường startup chuyên nghiệp, cởi mở, định hướng phát triển cá nhân rõ ràng. Có phụ cấp thực tập: 2.000.000 – 4.000.000 VNĐ. Có cơ hội được giữ lại làm chính thức sau kỳ thực tập.', 'Sinh viên năm 3 – năm cuối hoặc mới tốt nghiệp ngành Thiết kế nội thất, Kiến trúc, Mỹ thuật công nghiệp. Sử dụng tốt ít nhất một phần mềm thiết kế 3D (SketchUp, Revit, Coohom...) và đồ họa cơ bản (Photoshop, Illustrator...). Có tư duy thẩm mỹ tốt, khả năng phối màu, bố cục hợp lý. Ưu tiên ứng viên biết cách ứng dụng AI trong thiết kế (ví dụ: tạo moodboard AI, mô phỏng ý tưởng, gợi ý giải pháp thiết kế...). Chủ động, ham học hỏi, chịu được áp lực. Có laptop cá nhân hỗ trợ công việc.
Kỹ năng chuyên môn: [''SketchUp'', ''Revit'', ''Coohom'', ''Photoshop'', ''Illustrator'', ''AI in design'', ''AutoCAD'', ''3ds Max'']
Kỹ năng mềm: [''Chủ động'', ''Ham học hỏi'', ''Chịu được áp lực'', ''Làm việc nhóm'', ''Tư duy thẩm mỹ tốt'', ''Khả năng phối màu'', ''Bố cục hợp lý'', ''Khả năng lựa chọn vật liệu'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 12:00)', '[''Được mentor trực tiếp bởi các chuyên gia nội thất tại Baha Homes'', ''Cơ hội tiếp cận AI và các công cụ thiết kế hiện đại'', ''Làm việc trong môi trường startup chuyên nghiệp, cởi mở, định hướng phát triển cá nhân rõ ràng'', ''Phụ cấp thực tập'', ''Cơ hội được giữ lại làm chính thức sau kỳ thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (955, 2, 15, 'Thực Tập Sinh Thiết Kế Kiến Trúc', '- Tham gia hỗ trợ thiết kế kiến trúc trong các dự án của đơn vị tổng thầu Design & Build - Hỗ trợ đầu mối trong việc phối hợp thông tin giữa các phòng ban nội bộ Công ty, Chủ đầu tư và các đơn vị tư vấn đối tác khác để thống nhất phương án, giải pháp thiết kế cho các dự án; - Quản lý thông tin liên lạc tổng thể và thông tin liên quan đến các hạng mục công trình, đồng thời tích hợp các bộ môn liên quan như nội thất, cảnh quan, kết cấu, MEP, HTKT; - Tham gia lập kế hoạch và thực hiện triển khai các hồ sơ thiết kế Cơ sở, thiết kế kỹ thuật và thi công dự án. - Phối hợp và làm việc với các bộ môn kỹ thuật liên quan: kết cấu, cơ điện, phòng cháy chữa cháy, chiếu sáng, cảnh quan, dự toán, các nhà thầu phụ và cung cấp vật liệu khác; - Thực hiện công việc theo phạm vi trách nhiệm và những công việc khác theo sự phân công của cấp trên.', '### Yêu cầu ứng viên - Có kiến thức chuyên môn vững về Thiết kế, đặc biệt trong các lĩnh vực: Trung tâm thương mại, Nhà hàng, Văn phòng. - Hỗ trợ triển khai hồ sơ thiết kế theo đúng các tiêu chuẩn kỹ thuật, quy chuẩn và quy định của nhà nước về thiết kế kiến trúc công trình. - Sử dụng thành thạo các phần mềm cần thiết cho thiết kế và quản lý công trình như AutoCad, Revit, Sketch-up,... - Có kiến thức về vật liệu xây dựng và các tiêu chuẩn kỹ thuật, quy chuẩn, cũng như các quy định nhà nước liên quan đến thiết kế kiến trúc công trình. - Kỹ năng thuyết trình và giao tiếp hiệu quả. - Khả năng làm việc nhóm, phân tích và giải quyết vấn đề tốt. - Có tinh thần trách nhiệm và chịu được áp lực trong công việc. - Thời gian thực tập: toàn thời gian, tối thiểu 03 tháng.
Kỹ năng chuyên môn: [''AutoCad'', ''Revit'', ''Sketch-up'', ''Kiến Thức Về Quy Hoạch Và Thiết Kế Kiến Trúc'', ''Vẽ Tay Kiến Trúc'']
Kỹ năng mềm: [''Kỹ năng thuyết trình'', ''Giao tiếp hiệu quả'', ''Khả năng làm việc nhóm'', ''Phân tích và giải quyết vấn đề tốt'', ''Tinh thần trách nhiệm'', ''Chịu được áp lực trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'toàn thời gian', '[''Phụ cấp lương thực tập'', ''Được đào tạo chuyên môn & bản thân khi thực tập tại Công ty'', ''Cơ hội trở thành nhân viên chính thức'', ''Môi trường làm việc quốc tế thân thiện & chuyên nghiệp'', ''Được hưởng các quyền lợi khác theo chính sách công ty'', ''Thưởng hiệu quả làm việc'', ''Team building'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (956, 3, 15, 'Thực Tập Sinh Thiết Kế Nội Ngoại Thất', '- Hỗ trợ thiết kế, làm việc theo sự phân công của phòng ban - Tư vấn về thiết kế nội thất. - Thiết kế phối cảnh 3D. - Triển khai chi tiết bản vẽ kỹ thuật chi tiết nếu cần - Hỗ trợ các công việc khác của phòng ban, phối hợp với các thành viên trong công ty để hoàn thành công việc. **1. An tâm về phúc lợi:** – Cơ chế lương và thưởng tương xứng với năng lực và đóng góp. – Thu nhập = Lương cứng + Thưởng KPIs + % doanh thu (tùy vị trí). – Lương tháng 13, Bảo hiểm Y tế, chế độ nghỉ lễ, Tết, teambuilding,... – 12 ngày phép/năm (có thể cộng dồn để nghỉ hoặc quy đổi thành tiền). **2. Môi trường làm việc:** – Phát huy tố chất, năng lực và bứt phá mọi giới hạn trong công việc của bạn. – Tôn trọng cá tính, năng lực, ý kiến và sự đóng góp của bạn – Tự do, trẻ trung, năng động và được là chính mình. – Chế độ làm việc linh hoạt và đề cao ý thức trách nhiệm cá nhân. **3. Phát triển và khẳng định bản thân:** – Bạn sẽ được làm mọi việc theo cách khác đi và luôn tốt hơn từng ngày. – Trở thành người Giỏi và Tự tin về những gì mình đang làm. – Không giới hạn sự phát triển của bạn từ thời gian đến cấp bậc.', '- Sinh viên năm cuối sắp ra trường của các trường đại học, cao đẳng chuyên ngành Kiến trúc, Xây dựng, thiết kế nội thất - Tinh thần trách nhiệm công việc cao. - Thành thạo các phần mềm chuyên dụng phục vụ thiết kế như Autocad, 3Dmax, Sketchup, photoshop... - Luôn cập nhật xu thế nội thất để đảm bảo thiết kế có tính sáng tạo, thẩm mỹ cao, định hướng nhu cầu và có thể khai thác thương mại trên thị trường. - Tinh thần trách nhiệm công việc cao, thái độ làm việc tốt.
Kỹ năng chuyên môn: [''Autocad'', ''3Dmax'', ''Sketchup'', ''Photoshop'', ''Revit'']
Kỹ năng mềm: [''Tinh thần trách nhiệm công việc cao'', ''Khả năng cập nhật xu thế nội thất để đảm bảo thiết kế có tính sáng tạo, thẩm mỹ cao, định hướng nhu cầu và có thể khai thác thương mại'', ''Thái độ làm việc tốt'', ''Khả năng làm việc nhóm'', ''Khả năng vẽ tay'', ''Hiểu biết về nguyên tắc thiết kế nội thất'', ''Khả năng phối màu và lựa chọn vật liệu'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Linh hoạt (Chế độ làm việc linh hoạt và đề cao ý thức trách nhiệm cá nhân)', '[''Cơ chế lương và thưởng tương xứng với năng lực và đóng góp'', ''Thu nhập = Lương cứng + Thưởng KPIs + % doanh thu (tùy vị trí)'', ''Lương tháng 13'', ''Bảo hiểm Y tế'', ''Chế độ nghỉ lễ, Tết'', ''Teambuilding'', ''12 ngày phép/năm (có thể cộng dồn để nghỉ hoặc quy đổi thành tiền)'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (957, 7, 15, 'Thực Tập Sinh QA/QC', 'Hỗ trợ kiểm tra, giám sát chất lượng thi công các hạng mục tại công trình theo đúng bản vẽ, tiêu chuẩn kỹ thuật, quy chuẩn xây dựng. Ghi nhận, báo cáo các vấn đề chất lượng phát sinh trong quá trình thi công cho cấp trên và bộ phận liên quan. Thực hiện các nhiệm vụ khác theo phân công của Quản lý. Hỗ trợ làm hồ sơ thanh toán, nghiệm thu, quyết toán công trình. Phối hợp với các phòng ban và nhà thầu để đảm bảo tiến độ và chất lượng công việc. Hỗ trợ lương thực tập. Cơ hội trở thành nhân viên chính thức sau thực tập. Môi trường làm việc thoải mái, thân thiện. Được hướng dẫn bởi mentor giỏi, chuyên nghiệp.', '- Sinh viên năm cuối hoặc mới tốt nghiệp các chuyên ngành Kinh tế xây dựng, Xây dựng dân dụng và công nghiệp, hoặc các ngành liên quan. - Cẩn thận, tỉ mỉ, có tinh thần trách nhiệm cao trong công việc. - Thành thạo tin học văn phòng và các phần mềm chuyên ngành (Excel, AutoCAD, ...) - Kỹ năng làm việc nhóm và giao tiếp tốt.
Kỹ năng chuyên môn: [''Excel'', ''AutoCAD'', ''Phân tích dữ liệu'', ''Kiểm Tra Chất Lượng'', ''Báo cáo'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Tinh thần trách nhiệm'', ''Làm việc nhóm'', ''Giao tiếp'']', 'INTERNSHIP', 'ONSITE', 'thủ đức, hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30) thứ 7 làm cách tuần', '[''Hỗ trợ lương thực tập'', ''Cơ hội trở thành nhân viên chính thức sau thực tập'', ''Môi trường làm việc thoải mái, thân thiện'', ''Được hướng dẫn bởi mentor giỏi, chuyên nghiệp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (958, 8, 15, 'Thực Tập Sinh Giám Sát Thi Công', 'Mô tả công việc: - Hỗ trợ giám sát an toàn, tiến độ, chất lượng thi công các hạng mục nội thất tại công trình. - Kiểm tra, đảm bảo việc thi công đúng theo bản vẽ thiết kế, tiêu chuẩn kỹ thuật. - Ghi nhận và báo cáo tình hình thi công hàng ngày cho cấp trên. - Hỗ trợ nghiệm thu công trình, kiểm tra và đánh giá chất lượng sản phẩm sau khi hoàn thiện. Quyền lợi: - Hỗ trợ chi phí phụ cấp thực tập. - Được hướng dẫn, đào tạo trực tiếp các kỹ năng, nghiệp vụ chuyên môn. - Hỗ trợ dấu thực tập, giấy chứng nhận thực tập. - Cơ hội làm việc thực tế tại các công trình nội thất chuyên nghiệp. - Cơ hội trở thành nhân viên chính thức sau khi kết thúc thực tập.', '- Sinh viên năm cuối đang làm luận văn tốt nghiệp, sắp ra trường hoặc đã tốt nghiệp chuyên ngành Xây dựng Dân dụng & Công nghiệp, Kỹ thuật Xây dựng hoặc các ngành liên quan. - Yêu thích về hoàn thiện và nội thất. - Kỹ năng xử lý tình huống tốt. - Sử dụng tốt phần mềm AutoCAD, Microsoft Office. - Ngoại ngữ: Tiếng Anh khá.
Kỹ năng chuyên môn: [''AutoCAD'', ''Microsoft Office'', ''Sketchup'', ''Revit'']
Kỹ năng mềm: [''Xử lý tình huống tốt'', ''Kỹ Năng Giao Tiếp Và Làm Việc Nhóm'', ''Khả Năng Quan Sát Chi Tiết'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh, hà nội, đà nẵng', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Hỗ trợ chi phí phụ cấp thực tập'', ''Được hướng dẫn, đào tạo trực tiếp các kỹ năng, nghiệp vụ chuyên môn'', ''Hỗ trợ dấu thực tập, giấy chứng nhận thực tập'', ''Cơ hội làm việc thực tế tại các công trình nội thất chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức sau khi kết thúc thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (959, 9, 15, 'Thực Tập Sinh M&E - Hệ Thống Điện Mặt Trời', '- Hỗ trợ triển khai và giám sát thi công các hạng mục dự án năng lượng mặt trời. - Đọc và triển khai bản vẽ kỹ thuật, đảm bảo tiến độ và chất lượng thi công. - Bóc tách khối lượng, lập kế hoạch và đề xuất vật tư. - Hỗ trợ tính toán khối lượng và lập hồ sơ thanh toán. - Tham gia lập hồ sơ quản lý chất lượng, bản vẽ hoàn công. - Giám sát công tác an toàn và vệ sinh lao động tại công trường. - Thực hiện các nhiệm vụ khác theo phân công từ Ban Giám đốc.', '- Sinh viên năm cuối hoặc mới tốt nghiệp, chuyên ngành: Điện Điện tử, Hệ thống Điện, Năng lượng tái tạo và các ngành kỹ thuật liên quan. - Có khả năng tự tìm hiểu các tài liệu chuyên ngành để nâng cao năng lực và cập nhật các kỹ thuật, công nghệ mới liên quan đến công việc được phân công. - Trung thực, có trách nhiệm với công việc và có khả năng làm việc theo nhóm, giao tiếp và phối hợp làm việc nhóm tốt. - Năng động, tác phong làm việc chuyên nghiệp, xử lý tình huống nhanh nhẹn, quyết đoán. - Có thể làm việc trực tiếp tại Dự án (Trao đổi chi tiết khi Phỏng vấn). - Thời gian thực tập: Fulltime, tối thiểu 03 tháng.
Kỹ năng chuyên môn: [''Thiết Kế Hệ Thống Điện Năng Lượng Mặt Trời'', ''Kiểm Tra Và Nghiệm Thu Hệ Thống Điện'', ''Phân Tích Và Tính Toán Hệ Thống Điện'', ''Vẽ Bản Vẽ Kỹ Thuật Điện'', ''Hiểu Biết Về Các Thiết Bị Điện Năng Lượng Mặt Trời (pin Mặt Trời, Inverter, Bộ Tích Điện...)'']
Kỹ năng mềm: [''Có khả năng tự tìm hiểu các tài liệu chuyên ngành để nâng cao năng lực và cập nhật các kỹ thuật, công nghệ mới liên quan đến công việc được phân công.'', ''Trung thực, có trách nhiệm với công việc và có khả năng làm việc theo nhóm, giao tiếp và phối hợp làm việc nhóm tốt.'', ''Năng động, tác phong làm việc chuyên nghiệp, xử lý tình huống nhanh nhẹn, quyết đoán.'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Phụ cấp lương thực tập.'', ''Được đào tạo chuyên môn & bản thân khi thực tập tại Công ty.'', ''Cơ hội trở thành nhân viên chính thức.'', ''Môi trường làm việc quốc tế thân thiện & chuyên nghiệp.'', ''Được hưởng các quyền lợi khác theo chính sách công ty.'', ''Hỗ trợ đóng dấu mộc và báo cáo thực tập.'', ''Thưởng hiệu quả làm việc'', ''Team building'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (960, 10, 15, 'Thực Tập Sinh Graphic Designer', '* Thiết kế hình ảnh cho bài đăng mạng xã hội, banner, poster, brochure,... * Hỗ trợ chỉnh sửa và hoàn thiện các file thiết kế. * Phối hợp với team Marketing và Thiết kế để triển khai ý tưởng.', '* Biết sử dụng cơ bản Photoshop, Illustrator. * Sử dụng tốt Premiere, After Effect là một lợi thế. * Yêu thích thiết kế và có gu thẩm mỹ tốt. * Siêng năng, chịu học hỏi, làm việc có trách nhiệm.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Premiere'', ''After Effect'']
Kỹ năng mềm: [''Khả Năng Làm Việc Nhóm'', ''Khả Năng Sáng Tạo Và Tư Duy Hình Ảnh'', ''Siêng năng'', ''Chịu học hỏi'', ''Làm việc có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '3.0 - 8.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30) Thứ 7 làm cách tuần', '[''Học hỏi kinh nghiệm thực tế, phát triển kỹ năng thiết kế.'', ''Môi trường làm việc trẻ trung, thân thiện.'', ''Hỗ trợ xác nhận thực tập & phụ cấp.'', ''Được hướng dẫn bởi mentor giỏi, chuyên nghiệp.'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (961, 2, 15, 'Thực Tập Sinh Kiến Trúc', 'Triển khai phối cảnh 3D, bản vẽ kỹ thuật thi công nội thất. Chỉnh sửa, hoàn thiện hồ sơ thiết kế theo phân công. Làm việc với team kỹ thuật và thi công để đảm bảo thiết kế thực thi đúng yêu cầu. Tự quản lý tiến độ và chất lượng công việc được giao.', 'Là sinh viên năm cuối hoặc đã tốt nghiệp ngành Kiến trúc/Nội thất. Biết sử dụng thành thạo: AutoCAD, SketchUp, Vray/Lumion, Photoshop,... Có khả năng làm việc độc lập, tự chịu trách nhiệm với deadline. Ưu tiên ứng viên có kinh nghiệm tham gia tối thiểu 01 dự án thực tế.
Kỹ năng chuyên môn: [''AutoCAD'', ''SketchUp'', ''Vray/Lumion'', ''Photoshop'']
Kỹ năng mềm: [''khả năng làm việc độc lập'', ''tự chịu trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 11:30) Thứ 2 - Thứ 6 (từ 13:00 đến 17:30)', '[''Cơ hội tham gia vào các dự án thực tế, từ khâu ý tưởng đến thi công'', ''Cung cấp thiết bị làm việc (máy tính, phần mềm thiết kế)'', ''Hỗ trợ chi phí thực tập và có cơ hội trở thành nhân viên chính thức sau thực tập'', ''Cơ hội phát triển nghề nghiệp trong môi trường sáng tạo và chuyên nghiệp'', ''Xác nhận thực tập nếu cần cho hồ sơ tốt nghiệp.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (962, 3, 15, 'Kỹ Sư Giám Sát', '* Giám sát, thi công các công trình xây dựng dân dụng * Trực tiếp làm việc với khách hàng các vấn đề về tiến độ, chất lượng công trình * Phối hợp khảo sát đề xuất các giải pháp nâng cao công tác xây dựng * Ký biên bản nghiệm thu khối lượng giữa đơn vị và đối tác', '* Trình độ: Tốt nghiệp Trung cấp, Cao đẳng, Đại học * Chuyên ngành: Xây dựng dân dụng * Nhiệt tình, chịu khó học hỏi * Biết đọc bản vẽ thiết kế * Biết giám sát thi công, lựa chọn đối tác thi công
Kỹ năng chuyên môn: [''Biết đọc bản vẽ thiết kế'', ''Biết giám sát thi công'', ''Kiểm Tra Bản Vẽ Thiết Kế'', ''Quản Lý Tiến Độ Công Trình'', ''Kiểm Soát Chất Lượng Công Trình'']
Kỹ năng mềm: [''Nhiệt tình, chịu khó học hỏi'', ''lựa chọn đối tác thi công'']', 'PART_TIME', 'ONSITE', 'hà tĩnh', 'Hà Tĩnh', 'MONTHLY', 20000000.00, '10.0 - 20.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Được làm việc trong môi trường chuyên nghiệp, có nhiều cơ hội thăng tiến'', ''Thưởng hoàn thành vượt năng suất'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (963, 7, 15, 'Top Hot gấp mới {{featurejob.title}}', 'Cơ hội ứng tuyển việc làm với đãi ngộ hấp dẫn tại các công ty hàng đầu. Trước sự phát triển vượt bậc của nền kinh tế, rất nhiều ngành nghề trở nên khan hiếm nhân lực hoặc thiếu nhân lực giỏi. Vì vậy, hầu hết các trường Đại học đều liên kết với các công ty, doanh nghiệp, cơ quan để tạo cơ hội cho các bạn sinh viên được học tập, rèn luyện bản thân và làm quen với môi trường làm việc từ sớm. Trong danh sách việc làm trên đây, TopCV mang đến cho bạn những cơ hội việc làm tại những môi trường làm việc năng động, chuyên nghiệp. Việc làm Chất lượng: Hàng ngàn tin tuyển dụng chất lượng cao được cập nhật thường xuyên để đáp ứng nhu cầu tìm việc của ứng viên. Hệ thống thông minh tự động gợi ý các công việc phù hợp theo CV của bạn. Công cụ viết CV đẹp Miễn phí: Nhiều mẫu CV đẹp, phù hợp nhu cầu ứng tuyển các vị trí khác nhau. Tương tác trực quan, dễ dàng chỉnh sửa thông tin, tạo CV online nhanh chóng trong vòng 5 phút. Hỗ trợ Người tìm việc: Nhà tuyển dụng chủ động tìm kiếm và liên hệ với bạn qua hệ thống kết nối ứng viên thông minh. Báo cáo chi tiết Nhà tuyển dụng đã xem CV và gửi offer tới bạn.', 'Sinh viên nhiệt tình, có trách nhiệm trong công việc.', 'FREELANCE', 'ONSITE', '{{ featurejob.short_cities }}', NULL, 'FIXED_PROJECT', 2500000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', NULL, true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (964, 8, 15, 'Học Việc Giám Sát An Toàn', '### Mô tả công việc * Hỗ trợ theo dõi và ghi nhận tình hình an toàn, vệ sinh lao động tại công trường dưới sự hướng dẫn của cán bộ phụ trách. * Học cách kiểm tra trang bị bảo hộ của công nhân và cách nhắc nhở, hướng dẫn khi cần thiết. * Hỗ trợ trong việc phổ biến nội quy an toàn cho công nhân mới. * Ghi chú các quan sát thực tế và tham gia cùng đội ngũ trong các buổi kiểm tra hiện trường. * Học hỏi quy trình xử lý các tình huống phát sinh liên quan đến an toàn lao động. * Thực hiện các công việc khác theo sự phân công và hướng dẫn từ người phụ trách. ### Quyền lợi * Có lương hỗ trợ học việc hấp dẫn * Môi trường làm việc chuyên nghiệp, thân thiện, năng động * Được tham gia và đào tạo thực tế tại các công trình nội thất cao cấp * Cơ hội trở thành nhân viên chính thức sau kì học việc', '### Yêu cầu ứng viên * Sinh viên mới tốt nghiệp hoặc đang chờ bằng thuộc các ngành: Xây dựng, An toàn lao động, Môi trường,... * Chăm chỉ, tinh thần cầu tiến, sẵn sàng học hỏi trong môi trường công trình. * Không yêu cầu kinh nghiệm – sẽ được đào tạo và hướng dẫn trong suốt quá trình học việc.
Kỹ năng mềm: [''Chăm chỉ'', ''Tinh thần cầu tiến'', ''Sẵn sàng học hỏi'', ''Khả năng nhận biết và đánh giá rủi ro'', ''Khả năng lập kế hoạch và thực hiện các biện pháp an toàn'', ''Khả năng giám sát và thực thi các quy định an toàn'', ''Kỹ năng giao tiếp và truyền đạt thông tin'']', 'INTERNSHIP', 'ONSITE', 'long biên, hà nội', 'Hà Nội', 'MONTHLY', 8000000.00, '5.0 - 8.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Lương hỗ trợ học việc hấp dẫn'', ''Môi trường làm việc chuyên nghiệp, thân thiện, năng động'', ''Được tham gia và đào tạo thực tế tại các công trình nội thất cao cấp'', ''Cơ hội trở thành nhân viên chính thức sau kì học việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (965, 9, 15, 'Thực tập bất động sản', 'Mô tả công việc: * Hỗ trợ tìm kiếm, thu thập và phân tích thông tin thị trường bất động sản. * Hỗ trợ tư vấn khách hàng về các sản phẩm bất động sản theo hướng dẫn của cấp trên. * Tham gia các hoạt động marketing, phát triển thương hiệu và sản phẩm của công ty. * Hỗ trợ công tác pháp lý liên quan đến giao dịch bất động sản (hợp đồng, thủ tục pháp lý, v.v.). * Cập nhật dữ liệu khách hàng, duy trì và phát triển mối quan hệ với khách hàng tiềm năng. * Thực hiện các công việc khác theo yêu cầu của cấp trên. Quyền lợi: * Hỗ trợ dấu mộc xác nhận thực tập, báo cáo thực tập, bài luận văn, chuyên đề, đồ án tốt nghiệp. * Cấp giấy chứng nhận, chứng chỉ thực tập khi hoàn thành chương trình. * Có nhân viên công ty hướng dẫn training trực tiếp truyền đạt kinh nghiệm khi làm việc thực tiễn, được áp dụng kiến thức học tại trường vào các dự án thực tế của công ty. * Nâng cao hồ sơ profile công việc, khi hoàn thành thực tập sẽ được công ty hỗ trợ làm người references cho TTS sau khi đi tìm việc ở các công ty khác. Làm việc được trải nghiệm trực tiếp với các lãnh đạo cấp cao của các công ty hàng tỷ đô la trên toàn cầu. * Thời gian làm việc linh động, không gò bó, không ép buộc, không deadline, nghỉ lễ, tết đầy đủ theo quy định nhà nước và luật lao động.', 'Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp các chuyên ngành liên quan: Kinh doanh, Bất động sản, Kinh tế, Tài chính, Marketing,... Có đam mê và định hướng phát triển trong lĩnh vực bất động sản. Kỹ năng giao tiếp tốt, có khả năng làm việc độc lập và làm việc nhóm. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). Ưu tiên ứng viên có kinh nghiệm thực tập hoặc từng làm việc trong lĩnh vực sales, tư vấn, bất động sản.
Kỹ năng chuyên môn: [''Tin học văn phòng'', ''Microsoft Word'', ''Microsoft Excel'', ''Microsoft PowerPoint'']
Kỹ năng mềm: [''Giao tiếp'', ''Làm việc độc lập'', ''Làm việc nhóm'', ''Khả năng học hỏi nhanh'', ''Chăm chỉ'', ''Cẩn thận'', ''Có đam mê và định hướng phát triển trong lĩnh vực bất động sản'']', 'INTERNSHIP', 'ONSITE', 'đà nẵng, hải châu - đà nẵng, hà nội, ba đình - hà nội, hồ chí minh, quận 1 - tp hcm', 'Đà Nẵng', 'MONTHLY', 4000000.00, '0.0 triệu', 'Flexible, Monday - Sunday (from 08:00 to 17:00), self-selected time slots (Morning: 8h - 11h, Afternoon: 13h30 - 16h, Evening: 22h-24h). 100% remote online.', '[''Hỗ trợ dấu mộc xác nhận thực tập, báo cáo thực tập, bài luận văn, chuyên đề, đồ án tốt nghiệp'', ''Cấp giấy chứng nhận, chứng chỉ thực tập khi hoàn thành chương trình'', ''Có nhân viên công ty hướng dẫn training trực tiếp truyền đạt kinh nghiệm khi làm việc thực tiễn'', ''Được áp dụng kiến thức học tại trường vào các dự án thực tế của công ty'', ''Nâng cao hồ sơ profile công việc'', ''Được công ty hỗ trợ làm người references cho TTS sau khi đi tìm việc ở các công ty khác'', ''Làm việc được trải nghiệm trực tiếp với các lãnh đạo cấp cao của các công ty hàng tỷ đô la trên toàn cầu'', ''Nghỉ lễ, tết đầy đủ theo quy định nhà nước và luật lao động'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (966, 10, 15, 'Nghiên cứu thực tập', '### Mô tả Công Việc * Cập nhật thông tin thị trường thông qua các cuộc gọi, tìm kiếm Internet, kiểm tra trang web và các nguồn khác. * Dự đoán phân tích và nhu cầu cho các lĩnh vực bất động sản liên quan: Khách sạn/Khu nghỉ dưỡng, Khu nghỉ dưỡng, v.v. * Hỗ trợ trong việc chuẩn bị các sự kiện của bộ phận, và hỗ trợ tiếp nhận sự kiện. * Phân tích hỗ trợ. * Dịch. ### QUYềN LợI Chúng tôi sẽ cung cấp những gì? * Sẵn sàng để khởi động sự nghiệp của bạn? Savills Việt Nam cung cấp đào tạo thực hành để đưa bạn vào thế giới bất động sản. * Học hỏi từ những điều tốt nhất: Nhận lời khuyên và hướng dẫn nội bộ từ những người cố vấn có kinh nghiệm đã ở đó và làm điều đó. * Tăng lên các kỹ năng của bạn: Làm sắc nét các kỹ năng của bạn như giao tiếp và làm việc nhóm để trở thành một chuyên gia toàn diện. * Thực tập sinh hôm nay, Savillian ngày mai: Hãy gây ấn tượng với chúng tôi bằng màn trình diễn của bạn và nhận một công việc toàn thời gian tại Savills Việt Nam! Kiểm tra làm thế nào những người khác đã làm điều đó! * Tham gia cộng đồng Savills: Chúng tôi là một nơi làm việc đa dạng và toàn diện, nơi giọng nói của bạn quan trọng.', '### Yêu cầu ứng viên * Study in Real Estate, Finance, Economics (3rd year or 4th year student). * Strong interpersonal, negotiation and communication skills, for liaising with colleagues, customers and other stakeholders. * Good at Microsoft Office. * Proficient English (both speaking and writing). * Strong understanding of market research and market analysis, analytical and report writing skills. * Possess a Growth mindset, be result-oriented, and data-driven. * Demonstrated willingness to learn, creativity, and ability to work independently
Kỹ năng chuyên môn: [''Microsoft Office'', ''Research'', ''Data Analysis'', ''Report Writing'', ''Data Collection'', ''Data Presentation'']
Kỹ năng mềm: [''Interpersonal skills'', ''Negotiation'', ''Communication'', ''Growth mindset'', ''Result-oriented'', ''Data-driven thinking'', ''Willingness to learn'', ''Creativity'', ''Ability to work independently'', ''Teamwork'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh, quận 1', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Monday - Friday (08:30 - 17:30)', '[''Hands-on training'', ''Mentorship from experienced professionals'', ''Skill development'', ''Opportunity for full-time employment after internship'', ''Diverse and inclusive workplace'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (967, 2, 15, 'Nhân Viên Kiến Trúc Sư', 'Tiếp xúc khách hàng cá nhân, doanh nghiệp Tham gia ký kết hợp đồng và lên bản vẽ thiết kế thi công Thực hiện thiết kế bản vẽ mặt bằng, dựng 3D, Render nội ngoại thất, các bản vẽ thiết kế thi công chi tiết', 'Độ tuổi: không quá 28 tuổi. Tốt nghiệp Đại học chính quy trở lên chuyên ngành Kiến trúc, thiết kế nội thất. Có chứng chỉ hành nghề thiết kế, Sử dụng thành thạo các phần mềm: Revit, 3D Max, Sketchup. Chủ động, sáng tạo, có khả năng làm việc độc lập và làm việc nhóm tốt; chịu được áp lực trong công việc..
Kỹ năng chuyên môn: [''Revit'', ''3D Max'', ''Sketchup'', ''AutoCAD'', ''Vẽ Kỹ Thuật'']
Kỹ năng mềm: [''Chủ động'', ''Sáng tạo'', ''Làm việc độc lập'', ''Làm việc nhóm'', ''Chịu được áp lực trong công việc'']', 'PART_TIME', 'ONSITE', 'bắc ninh, bắc ninh', 'Bắc Ninh', 'MONTHLY', 25000000.00, '12.0 - 25.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Được làm việc trong một môi trường chuyên nghiệp, năng động'', ''Có cơ hội được tham gia các hoạt động văn hóa doanh nghiệp của Công ty'', ''Hưởng chế độ phúc lợi của Tập Đoàn Viettel'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (968, 3, 15, 'Giảng Viên Ngành Kiến Trúc (Thời Gian Linh Hoạt)', '1. Giảng dạy và hướng dẫn đào tạo nghề: • Vẽ tay • Vẽ kỹ thuật • AutoCAD • Nguyên lý thiết kế kiến trúc • Quy hoạch không gian kiến trúc nhà ở • Kiến trúc cảnh quan • Cấu tạo kiến trúc nhà ở • Vật liệu xây dựng • SketchUp - Vray chuyên ngành - Layout cơ bản • Render Enscape • Photoshop hậu kỳ kiến trúc • Lập hồ sơ kiến trúc • Design thị giác • Tư duy sáng tác kiến trúc • ………. • Giảng dạy các môn học liên quan đến thiết kế nhà ở, biệt thự, các công trình dịch vụ thương mại như quán cà phê, nhà hàng, văn phòng. • Thiết kế kiến trúc công trình dân dụng. • Tổ chức không gian và các yêu cầu kỹ thuật cho các công trình như nhà ở, biệt thự, và không gian thương mại. • Quy trình thi công và lựa chọn vật liệu cho các công trình dân dụng. • Tổ chức các lớp học lý thuyết và thực hành, giúp sinh viên làm quen với công việc thiết kế, lập bản vẽ kỹ thuật, và tính toán kết cấu công trình. 2. Phát triển chương trình đào tạo nghề: • Xây dựng và cập nhật giáo trình, tài liệu giảng dạy về thiết kế và thi công các công trình dân dụng, đặc biệt là nhà ở, biệt thự, và các công trình dịch vụ như nhà hàng, văn phòng. • Đảm bảo nội dung chương trình giảng dạy phù hợp với xu hướng và yêu cầu thực tế trong ngành xây dựng hiện nay, đặc biệt là trong thiết kế công trình dân dụng và thương mại. 3. Hướng dẫn thực tập và thực hành dự án thực tế: • Hướng dẫn sinh viên thực hiện các dự án thiết kế, từ giai đoạn phát triển ý tưởng đến việc hoàn thiện các bản vẽ thi công cho các công trình nhà ở, biệt thự, quán cà phê, nhà hàng và văn phòng. • Tổ chức thực hành tại công trường xây dựng để sinh viên có thể hiểu và áp dụng kiến thức trong môi trường thực tế. • Tạo cơ hội cho sinh viên thực hiện các dự án mô phỏng hoặc thực tế, kết hợp với các đối tác xây dựng và thiết kế. 4. Hỗ trợ tư vấn nghề nghiệp cho sinh viên: • Tư vấn nghề nghiệp cho sinh viên về cơ hội việc làm trong ngành kiến trúc và xây dựng, đặc biệt là trong lĩnh vực thiết kế nhà ở, biệt thự và công trình dịch vụ thương mại. • Hướng dẫn sinh viên phát triển kỹ năng mềm như kỹ năng giao tiếp với khách hàng, kỹ năng thuyết trình, quản lý dự án, và giải quyết vấn đề trong quá trình thiết kế và thi công.', '1. Trình độ và kinh nghiệm: • Tốt nghiệp đại học hoặc sau đại học chuyên ngành Kiến trúc, Xây dựng hoặc các ngành liên quan. • Có ít nhất 3 năm kinh nghiệm làm việc trong lĩnh vực thiết kế và thi công công trình dân dụng, đặc biệt là các công trình nhà ở, biệt thự, quán cà phê, nhà hàng, văn phòng. • Có kinh nghiệm giảng dạy hoặc đào tạo nghề là một lợi thế. 2. Kỹ năng: * Kỹ năng giảng dạy tốt, khả năng truyền đạt kiến thức lý thuyết và thực hành một cách rõ ràng và dễ hiểu. * Thành thạo các phần mềm thiết kế kiến trúc (AutoCAD, Revit, SketchUp, v.v.). * Kỹ năng giao tiếp và làm việc nhóm, có khả năng hướng dẫn và hỗ trợ sinh viên trong quá trình học tập và thực hành. 3. Phẩm chất: • Đam mê giảng dạy, yêu thích công việc phát triển nghề nghiệp cho sinh viên. • Tinh thần trách nhiệm cao, sáng tạo trong phương pháp giảng dạy và khả năng giải quyết vấn đề thực tế. • Khả năng tiếp cận và áp dụng các xu hướng thiết kế và thi công mới vào chương trình giảng dạy.
Kỹ năng chuyên môn: [''Vẽ tay'', ''Vẽ kỹ thuật'', ''AutoCAD'', ''Nguyên lý thiết kế kiến trúc'', ''Quy hoạch không gian kiến trúc nhà ở'', ''Kiến trúc cảnh quan'', ''Cấu tạo kiến trúc nhà ở'', ''Vật liệu xây dựng'', ''SketchUp'', ''Vray chuyên ngành'', ''Layout cơ bản'', ''Render Enscape'', ''Photoshop hậu kỳ kiến trúc'', ''Lập hồ sơ kiến trúc'', ''Design thị giác'', ''Tư duy sáng tác kiến trúc'', ''Revit'']
Kỹ năng mềm: [''Kỹ năng giảng dạy tốt'', ''Khả năng truyền đạt kiến thức lý thuyết và thực hành một cách rõ ràng và dễ hiểu'', ''Kỹ năng giao tiếp'', ''Làm việc nhóm'', ''Khả năng hướng dẫn và hỗ trợ sinh viên trong quá trình học tập và thực hành'', ''Đam mê giảng dạy'', ''Yêu thích công việc phát triển nghề nghiệp cho sinh viên'', ''Tinh thần trách nhiệm cao'', ''Sáng tạo trong phương pháp giảng dạy'', ''Khả năng giải quyết vấn đề thực tế'', ''Khả năng tiếp cận và áp dụng các xu hướng thiết kế và thi công mới vào chương trình giảng dạy'', ''Kỹ năng thuyết trình'', ''Quản lý dự án'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Buổi sáng: 8h30-12h từ thứ 2 đến thứ 6 hàng tuần. Buổi chiều: 14h-17h30 từ thứ 2 đến thứ 6 hàng tuần. Buổi tối: 18h30-21h15, dạy lịch 2-4-6 hoặc 3-5-7. Giảng viên có thể chọn một trong các lịch dạy trên.', '[''Được đào tạo và phát triển kỹ năng chuyên môn'', ''Làm việc trong môi trường trẻ trung, năng động, hướng tới hiệu quả'', ''Tham gia các hoạt động team building, du lịch hàng năm'', ''Các sự kiện kết nối và giao lưu nâng cao tinh thần đồng đội'', ''Được tham gia các khóa học nâng cao chuyên môn do công ty cử đi học'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (969, 7, 15, 'Giảng Viên Ngành Nội Thất', '**1. Giảng dạy và hướng dẫn đào tạo nghề:** Giảng dạy các môn học liên quan đến thiết kế nội thất: Môn Vẽ tay Môn 3Ds Max chuyên ngành Môn Render Vray chuyên ngành nội thất Môn Photoshop hậu kỳ nội thất Môn Vẽ kỹ thuật Môn Nguyên lý thiết kế nội thất Môn Làm mô hình nội thất Môn AutoCAD cơ bản Môn Ứng công nghệ AI dùng trong nội thất, kiến trúc Môn Cơ sở mỹ thuật ngành nội thất Môn Tư duy thiết kế ngành nội thất Môn Corona Render Môn Chaos Vantage Môn Quy chuẩn kích thước đồ nội thất Môn Bổ kỹ thuật nội thất …………… - Thiết kế không gian sống cho các công trình nhà ở, biệt thự. - Thiết kế nội thất cho các công trình dịch vụ thương mại như quán cà phê, nhà hàng, văn phòng, khách sạn. - Phân tích yêu cầu không gian, chức năng và thẩm mỹ trong thiết kế nội thất. - Lên ý tưởng thiết kế, lựa chọn vật liệu, màu sắc và ánh sáng cho không gian. - Quy trình thiết kế và thi công nội thất. Hướng dẫn sinh viên sử dụng phần mềm thiết kế nội thất (AutoCAD, SketchUp, 3ds Max, v.v.) để thực hiện bản vẽ kỹ thuật và mô phỏng không gian 3D. Giới thiệu các kỹ thuật vẽ tay và mô phỏng không gian bằng mô hình để sinh viên có thể thể hiện ý tưởng thiết kế của mình một cách trực quan. **2. Phát triển chương trình đào tạo nghề:** Cập nhật và xây dựng giáo trình, tài liệu giảng dạy về thiết kế nội thất, bao gồm các công trình nhà ở, biệt thự, văn phòng, và các công trình dịch vụ như quán cà phê, nhà hàng, khách sạn. Đảm bảo nội dung chương trình giảng dạy phù hợp với xu hướng thiết kế mới nhất, bao gồm các công nghệ thiết kế tiên tiến, vật liệu mới và các yêu cầu kỹ thuật hiện đại trong ngành. **3. Hướng dẫn thực tập và thực hành dự án thực tế:** Hướng dẫn sinh viên thực hiện các dự án thiết kế nội thất, từ phát triển ý tưởng đến việc hoàn thiện các bản vẽ thi công. Cung cấp các bài tập thực hành để sinh viên có thể áp dụng kiến thức vào công việc thiết kế thực tế. Tổ chức các chuyến tham quan công trình thực tế hoặc phối hợp với các đối tác trong ngành để sinh viên có thể thực hành tại công trường, hiểu rõ hơn về quy trình thi công và các yếu tố thực tế trong thiết kế nội thất. **4. Hỗ trợ tư vấn nghề nghiệp cho sinh viên:** Tư vấn nghề nghiệp cho sinh viên về cơ hội việc làm trong ngành thiết kế nội thất, giúp sinh viên phát triển mạng lưới quan hệ trong ngành. Hướng dẫn sinh viên phát triển kỹ năng mềm như kỹ năng giao tiếp với khách hàng, kỹ năng thuyết trình và trình bày ý tưởng thiết kế, kỹ năng làm việc nhóm và quản lý dự án.', '**1. Trình độ và kinh nghiệm:** Tốt nghiệp đại học hoặc sau đại học chuyên ngành Nội thất, Kiến trúc, Xây dựng hoặc các ngành liên quan. Có ít nhất 3 năm kinh nghiệm làm việc trong lĩnh vực thiết kế và thi công nội thất, đặc biệt là các công trình nhà ở, biệt thự, quán cà phê, nhà hàng, văn phòng, khách sạn. Kinh nghiệm giảng dạy hoặc đào tạo nghề là một lợi thế. **2. Kỹ năng:** Kỹ năng giảng dạy tốt, khả năng truyền đạt kiến thức lý thuyết và thực hành một cách rõ ràng và dễ hiểu. Thành thạo các phần mềm thiết kế nội thất (AutoCAD, SketchUp, 3ds Max, v.v.). Kỹ năng giao tiếp và làm việc nhóm, có khả năng hướng dẫn và hỗ trợ sinh viên trong quá trình học tập và thực hành. Hiểu biết vững về các xu hướng thiết kế nội thất hiện đại và các vật liệu mới. **3. Phẩm chất:** Đam mê giảng dạy, yêu thích công việc phát triển nghề nghiệp cho sinh viên. Tinh thần trách nhiệm cao, sáng tạo trong phương pháp giảng dạy và khả năng giải quyết vấn đề thực tế. Khả năng tiếp cận và áp dụng các xu hướng thiết kế mới vào chương trình giảng dạy.
Kỹ năng chuyên môn: [''Vẽ tay'', ''3Ds Max'', ''Render Vray'', ''Photoshop hậu kỳ nội thất'', ''Vẽ kỹ thuật'', ''Nguyên lý thiết kế nội thất'', ''Làm mô hình nội thất'', ''AutoCAD'', ''Ứng công nghệ AI dùng trong nội thất, kiến trúc'', ''Cơ sở mỹ thuật ngành nội thất'', ''Tư duy thiết kế ngành nội thất'', ''Corona Render'', ''Chaos Vantage'', ''Quy chuẩn kích thước đồ nội thất'', ''Bổ kỹ thuật nội thất'', ''SketchUp'']
Kỹ năng mềm: [''Kỹ năng giảng dạy tốt'', ''Khả năng truyền đạt kiến thức lý thuyết và thực hành một cách rõ ràng và dễ hiểu'', ''Kỹ năng giao tiếp'', ''Làm việc nhóm'', ''Khả năng hướng dẫn và hỗ trợ sinh viên'', ''Đam mê giảng dạy'', ''Yêu thích công việc phát triển nghề nghiệp cho sinh viên'', ''Tinh thần trách nhiệm cao'', ''Sáng tạo trong phương pháp giảng dạy'', ''Khả năng giải quyết vấn đề thực tế'', ''Khả năng tiếp cận và áp dụng các xu hướng thiết kế mới vào chương trình giảng dạy'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Buổi sáng: 8h30-12h từ thứ 2 đến thứ 6 hàng tuần. Buổi chiều: 14h-17h30 từ thứ 2 đến thứ 6 hàng tuần. Buổi tối: 18h30-21h15, dạy lịch 2-4-6 hoặc 3-5-7. Giảng viên có thể chọn một trong các lịch dạy trên.', '[''Cơ chế lương, thưởng được trao đổi cụ thể trong buổi phỏng vấn'', ''Hệ thống bảng bậc lương rõ ràng, với mức lương được xác định dựa trên năng lực và kinh nghiệm'', ''Được đào tạo và phát triển kỹ năng chuyên môn'', ''Làm việc trong môi trường trẻ trung, năng động, hướng tới hiệu quả'', ''Tham gia các hoạt động team building, du lịch hàng năm'', ''Các sự kiện kết nối và giao lưu nâng cao tinh thần đồng đội'', ''Được tham gia các khóa học nâng cao chuyên môn do công ty cử đi học'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (970, 8, 15, 'Thực Tập Sinh Kinh Doanh (Có Sẵn Data, Chính Sách Tốt, Trợ Cấp Thực Tập)', 'Tìm kiếm, tạo nguồn khách hàng, liên hệ khách hàng có nhu cầu về dự án từ data có sẵn. Marketing sản phẩm. Tư vấn cho khách hàng về các sản phẩm đất nền, nhà phố. Hướng dẫn khách hàng thực hiện các thủ tục mua bán, chốt cọc, ký hợp đồng... theo sự chỉ dẫn của quản lý trực tiếp. Chăm sóc khách hàng trước và sau bán hàng. Công việc cụ thể sẽ được trao đổi thêm khi phỏng vấn.', 'Sinh viên theo học các ngành Bất động sản, Quản trị kinh doanh, Tài chính-ngân hàng, Marketing... Có phương tiện đi lại và Laptop. Có nhiệt huyết, chịu khó học hỏi. Có thể làm Full-time.
Kỹ năng mềm: [''Có nhiệt huyết'', ''Chịu khó học hỏi'', ''Kỹ năng giao tiếp'', ''Kỹ năng làm việc nhóm'', ''Kỹ Năng Lập Kế Hoạch Và Tổ Chức'', ''Khả Năng Học Hỏi Nhanh'', ''Kỹ Năng Nghiên Cứu Và Phân Tích'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh, quận 12', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '3.0 - 8.0 triệu', 'Thứ 3 - Chủ nhật (từ 07:45 đến 16:30)', '[''Trợ cấp thực tập 3.000.000 vnđ'', ''Chính sách Hoa hồng sản phẩm tương đương với nhân viên chính thức'', ''Thu nhập không giới hạn'', ''Tham dự các khóa đào tạo kiến thức về thị trường, dự án, kỹ năng cần có khi tư vấn khách hàng trước khi làm việc'', ''Đào tạo về phân tích sản phẩm, phân tích thị trường chung nhằm thuyết phục khách hàng'', ''Cơ hội thực chiến như một nhân viên chính thức'', ''Tham dự các khóa đào tạo sử dụng công cụ marketing, chiến lược marketing'', ''Cung cấp tài liệu báo cáo liên quan, dấu mộc công ty'', ''Phụ cấp xăng xe'', ''Bảo hiểm xã hội'', ''Du lịch hàng năm'', ''Thưởng tháng 13'', ''Thưởng cổ phần'', ''Thưởng hiệu quả làm việc'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (971, 9, 15, 'Thực Tập Sinh Sales Admin', '* Hỗ trợ việc chuẩn bị và làm hồ sơ dự án, hồ sơ đấu thầu dự án xây dựng nội thất. * Theo dõi và cập nhật tiến độ dự án, hỗ trợ sắp xếp lịch họp với khách hàng * Soạn thảo các biểu mẫu, hợp đồng, thư từ, công văn… * _**_Sẽ được hướng dẫn trong quá trình thực tập và học việc._**_', 'Sinh viên năm cuối hoặc mới tốt nghiệp các khối ngành Kinh tế, Quản trị, Nội thất, Xây dựng,... Giao tiếp tốt, cẩn thận, có trách nhiệm và chủ động trong công việc Ham học hỏi và phát triển bản thân
Kỹ năng mềm: [''Giao tiếp tốt'', ''Cẩn thận'', ''Có trách nhiệm'', ''Chủ động trong công việc'', ''Ham học hỏi'', ''Phát triển bản thân'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '3.0 - 8.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30) Thứ 7 làm cách tuần', '[''Cơ hội trở thành nhân viên chính thức sau thời gian thực tập'', ''Có hỗ trợ phụ cấp (nếu làm việc full-time) và dấu mộc, số liệu cho thực tập'', ''Môi trường làm việc thoải mái, thân thiện và được hướng dẫn bởi mentor giỏi, chuyên nghiệp'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (972, 10, 15, 'Nhân Viên Triển Khai Bản Vẽ 2D - Part Time (Toàn Quốc - Online)', '- Lộ trình đào tạo đến khi làm việc * Đào tạo kỹ thuật cho ứng viên học việc: đào tạo trong 10 ngày. * Kiểm tra chuyên môn cơ bản cho công việc, xét để được nhận làm việc tự do trong bộ phận gia công sản phẩm. - Mô tả công việc: * Sử dụng hoàn toàn bằng ứng dụng của Công ty để gia công bản vẽ mặt bằng nhà 2D thông qua nguồn video của khách hàng cung cấp, hoàn thành chỉ tiêu Công ty đề ra theo từng giai đoạn; * Nhân viên sẽ được chuyên viên của công ty đào tạo kỹ năng trước khi vào làm việc chính thức;', '**1. Yêu cầu** + Không cần bằng cấp, kinh nghiệm + Có máy tính và thành thạo các thao tác cơ bản trên máy. **2. Thời gian làm việc:** 2.1. Đối với lịch làm việc từ **Thứ 4 đến Thứ 6** mỗi tuần, từ tháng 3 đến tháng 10 hàng năm và có thể chọn các khung giờ như sau: * Khung giờ sáng 4h - 8h; * Khung giờ sáng 5h - 9h; 2.2. Đối với lịch làm việc từ **Thứ 3 đến Thứ 5** mỗi tuần, từ tháng 3 đến tháng 10 hàng năm và có thể chọn các khung giờ như sau: * Khung giờ sáng 8h - 12h; * Khung giờ chiều 13h - 17h; * Khung giờ chiều tối 17h - 21h; * Khung giờ tối 22h - 2h sáng;
Kỹ năng chuyên môn: []
Kỹ năng mềm: []', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[]', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (973, 2, 15, 'Thực Tập Sinh Ngành Xây Dựng', 'Hỗ trợ kỹ sư/giám sát công trình trong các công việc hàng ngày tại công trường hoặc văn phòng. Tham gia đo đạc, giám sát, ghi nhận tiến độ thi công thực tế. Hỗ trợ triển khai hồ sơ thiết kế, bản vẽ thi công. Soạn thảo và lưu trữ hồ sơ chất lượng, nhật ký công trình, biên bản nghiệm thu. Tham gia bóc tách khối lượng, lập dự toán theo phân công. Làm việc với đội thi công, nhà thầu phụ theo chỉ đạo của cấp trên. Các công việc khác theo yêu cầu của trưởng bộ phận hoặc người hướng dẫn.', 'Sinh viên năm 3 hoặc năm cuối chuyên ngành: Kỹ thuật xây dựng, Kinh tế xây dựng, Kiến trúc, Giao thông, Cấp thoát nước, Nội thất,... Có kiến thức nền tảng về chuyên môn, hiểu bản vẽ kỹ thuật. Sử dụng được AutoCAD, MS Office; biết Revit, Tekla, Etabs là lợi thế. Có tinh thần học hỏi, chăm chỉ, trung thực và chịu được áp lực công việc. Có thể thực tập toàn thời gian hoặc tối thiểu 3 buổi/tuần. Ưu tiên sinh viên có thể thực tập tại công trình.
Kỹ năng chuyên môn: [''AutoCAD'', ''MS Office'', ''Revit'', ''Tekla'', ''Etabs'']
Kỹ năng mềm: [''Có tinh thần học hỏi'', ''chăm chỉ'', ''trung thực'', ''chịu được áp lực công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được hướng dẫn bởi kỹ sư giàu kinh nghiệm.'', ''Cơ hội học hỏi thực tế tại công trình, tham gia các dự án quy mô.'', ''Hỗ trợ dấu mộc thực tập, xác nhận thời gian/thành tích thực tập.'', ''Có hỗ trợ chi phí (nếu có) theo năng lực và thời gian tham gia.'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (974, 3, 4, 'Chăm Sóc Khách Hàng Nước Ngoài', 'Chăm sóc khách hàng: Làm việc trực tiếp với khách hàng nước ngoài. Hỗ trợ đội sales, gửi order, invoice. Theo dõi các hóa đơn đến hạn thanh toán. Thu hồi công nợ qua email, gọi điện, cập nhật tình trạng công nợ.', 'Anh văn thành thạo, làm việc trực tiếp với người nước ngoài. Ielts 6.0-6.5. Không yêu cầu kinh nghiệm, sẽ được hướng dẫn, đào tạo. Có thể làm ca đêm.
Kỹ năng chuyên môn: [''Microsoft Office'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 15000000.00, '12.0 - 15.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00), Thứ 2 - Thứ 7 (từ 23:00 đến 07:00)', '[''Được đào tạo, hướng dẫn nghiệp vụ'', ''Lương, thưởng phù hợp với năng lực'', ''Thưởng tháng 13'', ''Phụ cấp thâm niên'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (975, 7, 4, 'Cộng Tác Viên Vận Hành Voucher', 'Phòng Vận hành Loyalty thuộc khối Vận hành - Công ty cổ phần Onemount Consumer, hoạt động với 4 nhóm chức năng chính như sau: Vận hành các chương trình Loyalty (tích tiêu điểm) trong hệ sinh thái: Chương trình VinID (hệ sinh thái Vingroup) và Chương trình TechcombankRewards (hệ sinh thái cùng Techcombank). Vận hành các chương trình voucher trên TCB app và OneU app. Vận hành các chương trình Gamification trên TCB app và OneU app. Vận hành thẻ quà tặng VinID Gift card và OneU Giftcard. Để đáp ứng nhu cầu mở rộng và phát triển các dự án cùng với Hệ sinh thái, chúng tôi đang tìm kiếm những ứng viên tài năng và có trách nhiệm cho vị trí Cộng tác viên Vận hành Voucher. Đây là cơ hội tuyệt vời cho các bạn sinh viên mới ra trường hoặc những ai đang tìm kiếm một công việc thời vụ để tích lũy kinh nghiệm trong môi trường chuyên nghiệp, năng động.', 'Tốt nghiệp từ Đại học trở lên, không phân biệt chuyên ngành. Không yêu cầu kinh nghiệm. Các ứng viên chưa có kinh nghiệm sẽ được đào tạo bài bản từ đầu. Ưu tiên lớn cho ứng viên đã có kinh nghiệm ở vị trí nhập liệu, xử lý dữ liệu (data entry), quản trị viên website hoặc các công việc tương tự. Sử dụng thành thạo máy tính và các phần mềm văn phòng cơ bản (Word, Excel, Email). Khả năng học hỏi và làm quen nhanh với các hệ thống, phần mềm quản lý mới. Trung thực và Trách nhiệm: Có ý thức cao về việc bảo mật thông tin và hoàn thành công việc được giao đúng hạn. Cẩn thận: Luôn có ý thức kiểm tra kỹ công việc của mình để hạn chế tối đa sai sót. Chăm chỉ và Kiên trì: Sẵn sàng xử lý các tác vụ có tính lặp lại với sự tập trung cao độ. Nhanh nhẹn và Thông minh: Có khả năng tiếp thu nhanh các hướng dẫn và chủ động trong công việc.
Kỹ năng chuyên môn: [''Sử dụng thành thạo máy tính'', ''Phần mềm văn phòng cơ bản (Word, Excel, Email)'']
Kỹ năng mềm: [''Trung thực'', ''Trách nhiệm'', ''Cẩn thận'', ''Chăm chỉ'', ''Kiên trì'', ''Nhanh nhẹn'', ''Thông minh'']', 'FREELANCE', 'ONSITE', 'hà nội', 'Hà Nội', 'FIXED_PROJECT', 12000000.00, '8.0 - 12.0 triệu', 'Giờ hành chính, từ Thứ 2 - Thứ 6 (9h - 18h), Thứ 7 (9h - 13h)', '[''Mức lương/thù lao cạnh tranh theo thỏa thuận'', ''Được đào tạo chi tiết về quy trình làm việc, kỹ năng và các công cụ, phần mềm của công ty'', ''Làm việc trong môi trường trẻ trung, năng động, thân thiện và tôn trọng cá nhân'', ''Cơ hội trở thành nhân viên chính thức nếu thể hiện năng lực xuất sắc và gắn bó lâu dài'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (976, 8, 4, 'Thực Tập Sinh Trợ Lý Vận Hành', 'Quản lý hoạt động vận hành của trung tâm, sắp xếp lịch làm việc của nhân sự, sắp xếp lịch học của học sinh, lên kế hoạch trang trí trung tâm vào các sự kiện, quản lý đồ dùng giáo cụ của trường.', 'Yêu trẻ, biết cách làm việc với trẻ em. Nhiệt tình, sáng tạo, có tinh thần trách nhiệm và tinh thần tập thể tốt, thân thiện với học viên. Có khả năng quán xuyến nhiều công việc. Phát âm tiếng Anh chuẩn là một lợi thế.
Kỹ năng mềm: [''Yêu trẻ'', ''Nhiệt tình'', ''Sáng tạo'', ''Có tinh thần trách nhiệm'', ''Tinh thần tập thể tốt'', ''Thân thiện với học viên'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '2.5 - 5.0 triệu', 'Tối thiểu 19h/tuần từ thứ Hai đến Chủ Nhật', '[''Review lương thưởng 1 năm/2 lần'', ''Môi trường chuyên nghiệp, trẻ trung'', ''Được định hướng rõ ràng'', ''Có cơ hội lên quản lý sau khi review năng lực'', ''Được đóng BH theo quy định của NN'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (977, 9, 4, '(Lương Cao) Nhân Viên Thời Vụ', 'Tiếp đón và cung cấp thông tin, hướng dẫn khách đến giao dịch. Phối hợp với các bộ phận chuyên trách để giải đáp/xử lý các vấn đề. Nhận thư, bưu phẩm theo kích thước quy định, thực hiện việc báo động, liên hệ với bộ phận chuyên trách, CSKH khi có sự cố xảy ra. Phối hợp bộ phận an ninh giám sát việc vận chuyển đồ đạc ra vào, đảm bảo an ninh theo đúng quy trình/ hướng dẫn công việc. Xử lý thực hiện các báo cáo công việc theo quy định. Hiểu rõ và tuân thủ tuyệt đối các Tiêu chuẩn, Nội quy, Quy trình, Hướng dẫn công việc và các Quy định có liên quan đến vị trí công việc của mình. Chủ động báo cáo lên CBLĐ cấp trên những khó khăn vướng mắc hoặc các vấn đề bất thường phát sinh để có phương án xử lý triệt để, kịp thời.', 'Tốt nghiệp từ trung cấp trở lên. Có thể sử dụng Word/Excel. Có kỹ năng giao tiếp, khéo léo, thân thiện xử lý các tình huống phát sinh. Ngoại hình ưa nhìn, cẩn thận, chăm chỉ, nhiệt tình, kiên nhẫn, có tinh thần trách nhiệm cao và chủ động với công việc.
Kỹ năng chuyên môn: [''Sử dụng Word'', ''Sử dụng Excel'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Khéo léo'', ''Thân thiện'']', 'PART_TIME', 'ONSITE', 'hà nội, quảng ninh', 'Hà Nội', 'MONTHLY', 10000000.00, '8.0 - 10.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:30)', '[''Lương cứng 9 triệu + phụ cấp cơm trưa'', ''Môi trường chuyên nghiệp, tiêu chuẩn 5 sao'', ''Được đào tạo nâng cao nghiệp vụ liên tục'', ''Xem xét ký hợp đồng chính thức nếu đáp ứng tốt công việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (978, 10, 4, 'Chăm Sóc Lớp Học Tiếng Anh', 'Trợ giảng các lớp học được phân công. Thực hiện các công việc admin chăm sóc thông tin lớp học được phân công trên hệ thống nội bộ (nhập điểm danh, nhận xét học tập, gửi ảnh/clip khoảnh khắc học sinh lớp, làm báo cáo test định kỳ...). Đứng lớp bổ trợ cho học sinh yếu khi được phân công. Hỗ trợ hiệu chỉnh tài liệu giảng dạy, phiếu bài tập, tài liệu học thuật khác khi được phân công. Hỗ trợ các Sự kiện/ Chương trình ngoại khóa của trung tâm khi được phân công.', 'Sinh viên năm 3, 4 các Trường Đại học Chuyên ngành tiếng Anh/Sư phạm tiếng Anh & có kỹ năng giao tiếp tiếng Anh Nghe-Nói tốt (tương đương IELTS 6.0 hoặc B2). Có năng lực giao tiếp tốt, cởi mở, nhanh nhẹn, ham học hỏi. Yêu thích và đam mê môi trường giáo dục với trẻ em.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp tiếng Anh Nghe-Nói tốt (tương đương IELTS 6.0 hoặc B2)'']
Kỹ năng mềm: [''Năng lực giao tiếp tốt'', ''Cởi mở'', ''Nhanh nhẹn'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', '17h00 – 21h00 các ngày từ Thứ 3 đến Chủ nhật', '[''Được xác nhận đóng dấu hoàn thành thực tập (thời lượng thực tập: ít nhất trong 6 tháng)'', ''Được đào tạo, học hỏi phát triển bản thân trong môi trường làm việc chuyên nghiệp'', ''Cơ hội thăng tiến lên vị trí full-time sau khi tốt nghiệp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (979, 2, 4, 'Nhân Viên Bán Hàng - Trực Page Part Time', 'Trực fanpage, tiếp nhận và phản hồi tin nhắn, bình luận của khách hàng một cách nhanh chóng, thân thiện và chuyên nghiệp. Gọi điện xác nhận đơn hàng, tư vấn sản phẩm khi khách hàng có nhu cầu. Phối hợp với các bạn nhân viên tư vấn khác và bộ phận vận đơn để xử lý đơn hàng hiệu quả. Thường xuyên chăm sóc khách hàng cũ, thực hiện khảo sát mức độ hài lòng và thu thập phản hồi về sản phẩm/dịch vụ.', 'Ưu tiên sinh viên các trường đại học đang tìm công việc part-time ổn định. Chỉ tuyển nữ và các bạn sinh sống/học tập gần khu vực cửa hàng để thuận tiện đi lại.
Kỹ năng mềm: [''Chăm chỉ'', ''Cẩn thận'', ''Nhanh nhẹn'', ''Có tinh thần trách nhiệm cao'', ''Sẵn sàng học hỏi'', ''Yêu thích công việc kinh doanh'', ''Giao tiếp'', ''Có khả năng thích nghi tốt với môi trường làm việc mới'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Chủ nhật (từ 15:00 đến 21:00)', '[''Thưởng nóng'', ''Thưởng hiệu quả theo ngày/tháng/quý/năm'', ''Môi trường làm việc trẻ trung, năng động, thân thiện'', ''Cơ hội học hỏi kỹ năng bán hàng, chăm sóc khách hàng, tư duy kinh doanh'', ''Được đào tạo bài bản, hỗ trợ tận tình từ team'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (980, 3, 4, 'Chăm Sóc Khách Hàng', 'Trực tổng đài giải đáp thắc mắc của khách hàng. Chăm sóc khách hàng sau bán. Trả lời các comment của khách hàng trên Website của Hoàng Hà Mobile.', 'Thành thạo kỹ năng máy tính. Có giọng nói truyền cảm, không nói ngọng và giao tiếp tốt với khách hàng. Kiên trì, năng động, trung thực, nhiệt tình. Yêu thích công nghệ, giao tiếp, chăm sóc khách hàng.
Kỹ năng chuyên môn: [''Thành thạo kỹ năng máy tính'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Kiên trì'', ''Năng động'', ''Trung thực'', ''Nhiệt tình'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', '17h30 - 21h30', '[''Thưởng thêm theo tăng trưởng công ty'', ''Được đào tạo về chuyên môn & kỹ năng trước khi làm việc'', ''Chế độ thăng tiến lên trưởng nhóm, trưởng ca'', ''Có thể đổi ca theo lịch học cá nhân'', ''Cước điện thoại'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (981, 7, 4, 'Thực Tập Sinh Vận Hành Kênh', '- Vận hành kênh CRM của công ty, đảm bảo hoạt động giữa CRM với các nguồn data - Chăm sóc inbox, comment của khách hàng trên các kênh truyền thông online như facebook, tawk.to, zalo, tiktok,... - Cung cấp thông tin và giải đáp thắc mắc của khách hàng - Seeding tìm kiếm data khách hàng tiềm năng - Thực hiện các công việc khác theo sự chỉ đạo của quản lý.', '- Chăm chỉ, siêng năng, ham học hỏi; - Có tinh thần trách nhiệm; - Khả năng tin học văn phòng cơ bản; - Ưu tiên ứng viên yêu thích và am hiểu văn hóa Nhật.
Kỹ năng chuyên môn: [''Tin học văn phòng cơ bản'']
Kỹ năng mềm: [''Chăm chỉ'', ''Siêng năng'', ''Ham học hỏi'', ''Tinh thần trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ dấu thực tập (nếu cần)'', ''Được đào tạo, hướng dẫn thêm về chuyên môn'', ''Tham gia chương trình Jellyfish Coffee Talk'', ''Hoạt động xã hội, từ thiện, đóng góp cho cộng đồng'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (982, 8, 4, 'Nhân Viên Chăm Sóc Khách Hàng Trực Page', '1. Tư vấn & Chăm sóc khách hàng - Tư vấn sản phẩm và chốt đơn qua Facebook, Shopee, Tiktok, Zalo... - Tiếp nhận & xử lý đơn hàng – hỗ trợ khách trước/trong/sau bán - Xử lý các khiếu nại/đánh giá xấu nếu có 2. Tập sự phát triển kênh Affiliate đa nền tảng (truyền thông số) - Quản lý kênh (lên kế hoạch, đăng bài/video) Shopee, TikTok, Instagram, Facebook - Sáng tạo nội dung (Đã có sẵn công thức để thực hành) - Thực hành tư duy content bán hàng & tăng traffic 3. Công việc phối hợp & báo cáo - Cập nhật doanh thu, xử lý đánh giá xấu, báo cáo chỉ số cơ bản - Phối hợp với các bộ phận như content, kho, vận hành khi cần', 'Yêu cầu ứng viên - Nữ, từ 19–25 tuổi – ưu tiên sinh viên ĐH/CĐ tại Đà Nẵng - Giao tiếp tự nhiên, chăm chỉ, có trách nhiệm, trung thực, chủ động - Yêu thích thời trang, thích học hỏi về marketing và kinh doanh online - Có laptop cá nhân
Kỹ năng chuyên môn: [''Sáng tạo nội dung'', ''Quản lý kênh truyền thông'']
Kỹ năng mềm: [''Giao tiếp tự nhiên'', ''Chăm chỉ'', ''Có trách nhiệm'', ''Trung thực'', ''Chủ động'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Ca làm việc đăng ký linh hoạt theo lịch cá nhân. Sáng: 8h30 - 12h30, Chiều: 13h30 - 17h30, Tối (Tại Nhà): 20h00 - 24h00', '[''Thưởng hấp dẫn'', ''Trợ cấp: xăng xe, ăn trưa, lễ tết'', ''Được đào tạo & làm việc thực chiến trong môi trường chuyên nghiệp'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (983, 9, 4, 'Nhân Viên Hướng Dẫn Chăm Sóc Khách Hàng', 'Saigon Shooting Club - Chí nhánh Thảo Điền tuyển dụng Hướng dẫn viên hướng dẫn và chăm sóc khách hàng sử dụng dịch vụ: Hướng dẫn khách sử dụng súng hơi đảm bảo tiêu chuẩn an toàn, Bảo trì súng hơi và các thiết bị khác tại CLB, Tham gia các công việc vệ sinh cố định, Hỗ trợ công việc thu ngân, pha chế khi cần thiết, Các công việc khác theo phân công của Trưởng ca.', 'Hướng dẫn viên: Nam đủ 18 tuổi trở lên, có kỉ luật, có kinh nghiệm chăm sóc khách hàng. Yêu cầu giao tiếp Tiếng Anh. Có ngoại hình ưu nhìn là lợi thế. Có kinh nghiệm pha chế là 1 lợi thế. Thời gian làm việc: Thứ 2 đến Chủ nhật (được nghỉ 1 ngày trong tuần)
Kỹ năng chuyên môn: [''Kinh nghiệm chăm sóc khách hàng'', ''Kinh nghiệm pha chế'']
Kỹ năng mềm: [''Giao tiếp hiệu quả'', ''Kỹ năng giải quyết vấn đề'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '5.0 - 8.0 triệu', 'Thứ 2 - Chủ nhật (từ 14:30 đến 21:30)', '[''Lương 30.000 một giờ'', ''Lương nhận hàng tháng'', ''Được nghỉ 1 ngày trong tuần'', ''Được đào tạo đầy đủ, cung cấp đồng phục'', ''Cơ hội vừa làm vừa nâng cao khả năng tiếng Anh'', ''Thưởng hiệu quả làm việc'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (984, 10, 4, 'Nhân Viên Chăm Sóc Khách Hàng', 'Đặt lịch hẹn, gọi cho khách và gửi thư mời đến dự sự kiện. Đón khách, hỗ trợ khi khách đến dự sự kiện, chăm sóc khách hàng. Các việc sẽ do quản lý phân công các bạn vào từng ban dựa theo năng lực của mỗi người.', 'Độ tuổi: sinh viên năm cuối trở lên. Có phương tiện di chuyển cá nhân. Không yêu cầu kinh nghiệm, không yêu cầu bằng cấp (sẽ được đào tạo lại từ đầu).
Kỹ năng mềm: [''Giao tiếp tốt'', ''Giải quyết vấn đề'', ''Quản Lý Thời Gian Hiệu Quả'', ''Khả Năng Lắng Nghe Tích Cực'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Xoay ca linh hoạt phù hợp với lịch học', '[''Bảo hiểm xã hội'', ''Du lịch hàng năm'', ''Team building'', ''Thưởng hiệu quả làm việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (985, 2, 4, 'Cộng Tác Viên Thu Phí', 'Hỗ trợ tại các trạm thu phí tự động tại Sân bay Cam Ranh. Hỗ trợ xử lý các công việc vận hành tại địa điểm khách hàng. Làm cầu nối giữa khách hàng và đội ngũ nội bộ nhằm xử lý, cập nhật tình trạng hoạt động của hệ thống. Theo dõi và báo cáo kịp thời các vấn đề phát sinh tại hiện trường.', 'Ứng viên sinh sống trực tiếp tại các khu vực gần sân bay: Liên Khương/ Buôn Ma Thuột/ Cần Thơ/ Vinh/ Pleiku. Không yêu cầu kinh nghiệm, ứng viên sẽ được đào tạo toàn bộ các nghiệp vụ liên quan phục vụ cho công việc. Ứng viên dưới 45 tuổi, có thể làm việc theo ca từ 8-12 tiếng/ngày. Nhanh nhẹn, biết sử dụng máy tính. Chăm chỉ, cẩn thận.
Kỹ năng chuyên môn: []
Kỹ năng mềm: [''Nhanh nhẹn'', ''Chăm chỉ'', ''Cẩn thận'']', 'PART_TIME', 'ONSITE', 'tp cam ranh', NULL, 'MONTHLY', 4000000.00, '0.0 triệu', '8-12 tiếng/ngày', '[''Môi trường làm việc chuyên nghiệp, sạch sẽ và lịch sự'', ''Được đào tạo về công việc'', ''Được hỗ trợ liên tục trong quá trình trực tại Sân bay'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (986, 3, 4, 'Nhân Viên Chăm Sóc Khách Hàng', '- Trực/ chat tư vấn, hỗ trợ, chăm sóc khách hàng quan tâm sản phẩm - Hình thức: nhắn tin ở Facebook, Zalo của Công ty. - Báo cáo công việc theo ngày/ tuần/ tháng. - Thực hiện các công việc khác liên quan được giao.', '- Nam/Nữ độ tuổi 2006 – 2000 - Có laptop cá nhân - Có kinh nghiệm sale, tư vấn, CSKH là 1 lợi thế - Tốt nghiệp THPT, Trung cấp, Cao đẳng, Đại học - Nhanh nhẹn, giao tiếp tốt, hòa đồng
Kỹ năng chuyên môn: [''Có laptop cá nhân'', ''Kinh nghiệm sale, tư vấn, CSKH là 1 lợi thế'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Giao tiếp tốt'', ''Hòa đồng'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '5.0 - 10.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 2 - Sáng Thứ 7: 8h30-17h30', '[''Cước điện thoại'', ''Thưởng hiệu quả làm việc'', ''Team building'', ''Du lịch hàng năm'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (987, 7, 4, 'Nhân Viên Telesale- Part Time', '- Gọi điện tìm kiếm khách hàng từ những nguồn data khách hàng sẵn từ Trưởng phòng - Cung cấp, tư vấn đầy đủ và chính xác thông tin sản phẩm - Giải quyết thắc mắc của khách hàng, phối hợp bộ phận Hành chính Kinh doanh xử lý khiếu nại - Chăm sóc khách hàng theo chương trình chung của công ty - Thực hiện các báo cáo hàng tuần - Những công việc khác theo sự phân công của quản lý trực tiếp.', '- Không yêu cầu kinh nghiệm, chưa có sẽ được cầm tay chỉ việc. - Kỹ năng tìm kiếm khách hàng mới, chăm sóc khách hàng cũ - Kỹ năng giao tiếp tốt - Kỹ năng xử lý tình huống - Kỹ năng phân tích - Kỹ năng làm việc độc lập và làm việc nhóm - Thân thiện, ham học hỏi, kiên trì là 1 lợi thế. - Năng động, sáng tạo, nhiệt tình, nghiêm túc và có trách nhiệm với công việc.
Kỹ năng mềm: [''Kỹ năng tìm kiếm khách hàng mới'', ''Kỹ năng giao tiếp tốt'', ''Kỹ năng xử lý tình huống'', ''Kỹ năng phân tích'', ''Kỹ năng làm việc độc lập và làm việc nhóm'', ''Thân thiện, ham học hỏi, kiên trì'', ''Năng động, sáng tạo, nhiệt tình, nghiêm túc và có trách nhiệm với công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '5.0 - 7.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được cấp các thiết bị cần thiết phục vụ cho công việc'', ''Làm việc trong môi trường chuyên nghiệp, trẻ trung năng động và có cơ hội thăng tiến trong công việc'', ''Được tham dự các chương trình team building, party, du lịch, đãi ngộ theo chế độ lễ Tết và các ngày lễ hấp dẫn'', ''Chính sách đào tạo về các kĩ năng mềm: MKT, tư vấn, đàm phán, thuyết phục'', ''Được cầm tay chỉ việc nếu không có kinh nghiệm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (988, 8, 4, 'CTV Tổng Đài – Xác Minh Thông Tin (Service Desk Intern)', 'Tiếp nhận, tư vấn cơ bản và phân loại khách hàng từ các kênh (Facebook, Zalo, Website, Email......). Call data nguồn xác định thông tin đăng ký của khách hàng. (30% tổng data đưa về từ các nguồn). Các công việc khác theo yêu cầu của quản lý.', 'Sinh viên năm cuối đang chờ bằng hoặc tốt nghiệp tại các trường Trung cấp/Cao đẳng/Đại học khối ngành: Kinh tế, Quản trị Kinh doanh, Tài chính, Marketing,... Có laptop cá nhân và không ngại làm cuối tuần. Thời gian làm việc:Làm việc theo ca linh hoạt.
Kỹ năng chuyên môn: [''Sử dụng laptop'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Khả năng giải quyết vấn đề'', ''Kiên nhẫn'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', 'Thứ 2 - Chủ nhật: Ca sáng 8h00 - 12h00, Ca chiều 13h00 - 17h00 hoặc 17h00 - 21h00', '[''Lương hỗ trợ: 20,000đ/giờ, 2 – 4tr/tháng'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Team building theo Quý, chế độ du lịch, nghỉ mát 1 lần/năm'', ''Tham gia các buổi đào tạo kĩ năng chuyên môn hàng tháng'', ''Trang bị công nghệ hiện đại'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (989, 9, 4, 'Thực Tập Sinh Chăm Sóc Khách Hàng', 'Hỗ trợ bộ phận kinh doanh chăm sóc khách hàng sau bán hàng đối với khách hàng hợp tác qua online. Tiếp nhận, giải đáp các cuộc gọi đến của khách hàng, chuyển thông tin cho đối tác. Theo dõi, quản lý, cập nhật thông tin khách hàng có nhu cầu về Nha khoa. Nhập liệu thông tin khách hàng lên trang quản trị của Công ty và theo dõi. Thực hiện các công việc theo phân công của quản lý. Báo cáo kết quả công việc hàng ngày cho quản lý.', 'Không yêu cầu kinh nghiệm; Kỹ năng giao tiếp tốt; Có giọng nói chuẩn, không nói tiếng địa phương; Tư duy sáng tạo, logic, tư duy giải quyết vấn đề; Chăm chỉ, nhanh nhẹn, có trách nhiệm với công việc được giao.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Tư duy sáng tạo'', ''Tư duy logic'', ''Tư duy giải quyết vấn đề'', ''Chăm chỉ'', ''Nhanh nhẹn'', ''Có trách nhiệm với công việc'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Nghỉ Lễ, Tết theo quy định được hưởng lương'', ''Cơ hội lên chính thức sau quá trình thực tập'', ''Được đào tạo các kỹ năng làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (990, 10, 4, 'Nhân Viên Chăm Sóc Khách Hàng Parttime', 'Nhận danh sách khách hàng tiềm năng từ công ty (khách hàng mới chưa từng sử dụng sản phẩm/dịch vụ ZoZin). Chủ động gọi điện cho khách hàng để: Giới thiệu về sản phẩm, dịch vụ, các ưu đãi hiện có. Tư vấn lợi ích khi sử dụng dịch vụ bảo dưỡng, sửa chữa, thay lõi lọc tại nhà. Khơi gợi nhu cầu, tạo sự tin tưởng và đặt lịch cho kỹ thuật viên đến hỗ trợ tại nhà. Không cần tìm kiếm khách hàng, không bị ép doanh số – chỉ cần làm tốt theo danh sách có sẵn. Được giữ lại khách hàng tiềm năng của riêng mình để chăm sóc và phát triển mối quan hệ lâu dài. Sau 06 tháng, nhân viên sẽ tiếp tục được phân bổ khách hàng cũ định kỳ (đã từng phát sinh trước đó) để gọi lại và đặt lịch chăm sóc tiếp theo.', 'Thái độ: Lạc quan, tích cực; Chủ động, không ngại gọi điện; Tận tâm với công việc, muốn kiếm tiền. Kỹ năng: Giao tiếp tốt, Xử lý từ chối, Tư vấn bán hàng, Biết quản lý thời gian.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Xử lý từ chối'', ''Tư vấn bán hàng'', ''Biết quản lý thời gian'']', 'PART_TIME', 'REMOTE', 'bắc ninh', 'Bắc Ninh', 'MONTHLY', 8000000.00, '5.0 - 8.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 11:30), (từ 14:30 đến 17:30), (từ 17:35 đến 20:30)', '[''Thu nhập ổn định & rõ ràng'', ''Được đào tạo bài bản'', ''Môi trường làm việc thân thiện'', ''Chế độ làm việc hợp lý'', ''Phúc lợi đầy đủ'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (991, 2, 4, 'Thực Tập Chăm Sóc Khách Hàng Và Đối Tác', '- Hỗ trợ các yêu cầu của khách hàng như làm rõ chi tiết hợp đồng, chi tiết thông tin triển khai - Tiếp đón khách hàng tại văn phòng - Gọi điện thoại cho khách hàng đã lâu không liên hệ, cập nhật lại tình trạng khách hàng, làm khách hàng thấy được quan tâm và trân trọng - Giới thiệu đến khách hàng đang triển khai những tiện ích mới, dịch vụ mới qua điện thoại - Gọi điện thoại đến các khách hàng đăng ký dịch vụ, giúp khách hàng chia sẻ thông tin để tiện cho bộ phận kinh doanh tiếp tục làm bước tiếp theo sau đó - Làm theo sự phân công từ quản lý. - Thời gian thực tập: 6 tháng - Công ty chỉ tuyển ứng viên đi thực tập lấy kinh nghiệm, để được đào tạo chuyên ngành và ở lại làm việc lâu dài cho công ty. chứ không phải thực tập đi thực tập ngắn hạn để lấy dấu đỏ theo khóa thực tập rồi nghỉ, công ty không cần nhân viên làm việc vặt hay làm miễn phí thời gian ngắn. Do vậy công ty không cấp dấu đỏ thực tập, ứng viên vui lòng đọc kỹ điều này - Chứng chỉ thực tập được cấp sau khi hoàn thành khóa thực tập - Công ty không chấp nhận những ứng viên đang làm tại công ty khác muốn tìm thêm công việc. - Ứng viên chọn làm toàn thời gian/ bán thời gian hành chính (Ca sáng từ 8 - 12h, Ca chiều từ 13h30 - 17h30)/ bán thời gian Ngoài giờ hành chính (Ca tối: Từ 18h30 - 21h) theo thời gian dưới đây: + Thời gian làm việc Toàn thời gian: Từ thứ 2 đến thứ 6 theo giờ hành chính + 01 ca bắt buộc nằm trong “các ca tối hoặc ca chiều thứ 7 hoặc sáng chiều Chủ Nhật”, ứng viên tùy chọn 01 ca này chỉ cần làm trong khoảng thời gian đó + Thời gian làm việc Bán thời gian trong giờ hành chính: 1 tuần làm tối thiểu 6 ca, tương tương đương Tối thiểu 21h/ tuần, Ca sáng/ Ca chiều/ Ca so le/ Ca gãy/ Ca tối từ thứ 2 đến chủ nhật. Trong đó có 02 ca bắt buộc nằm trong “các ca tối hoặc ca chiều thứ 7 hoặc sáng chiều Chủ Nhật”, ứng viên tùy chọn 02 ca này chỉ cần làm trong khoảng thời gian đó,.04 ca còn lại tùy ứng viên chọn + Thời gian làm việc Bán thời gian ngoài giờ hành chính: 1 tuần làm tối thiểu 6 ca, tương tương đương Tối thiểu 21h/ tuầnn, Ca sáng/ Ca chiều/ Ca so le/ Ca gãy/ Ca tối từ thứ 2 đến chủ nhật. Trong đó có 04 ca bắt buộc nằm trong “các ca tối hoặc ca chiều thứ 7 hoặc sáng chiều Chủ Nhật”, ứng viên tùy chọn 04 ca này chỉ cần làm trong khoảng thời gian đó,.02 ca còn lại tùy ứng viên chọn', '- Chấp nhận sinh viên năm 1, 2, 3, 4 các trường trung cấp, cao đẳng, đại học - Nhanh nhẹn, linh hoạt, giao tiếp tốt - Có laptop cá nhân - Sẵn sàng gọi điện cho khách hàng để đáp ứng công việc - Kiên định, tỉ mỉ trong công việc - Không yêu cầu bằng cấp, chấp nhận lao động phổ thông - Chấp nhận sinh viên và mới ra trường
Kỹ năng chuyên môn: [''Có laptop cá nhân'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Linh hoạt'', ''Giao tiếp tốt'', ''Kiên định'', ''Tỉ mỉ trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca sáng từ 8 - 12h, Ca chiều từ 13h30 - 17h30, Ca tối từ 18h30 - 21h', '[''Phụ cấp hỗ trợ thực tập để ăn trưa, gửi xe, xăng xe là: 10.000 đ'', ''Được tăng lương và đề bạt làm nhân viên chính thức nếu có kết quả thực tập tốt'', ''Cấp chứng chỉ thực tập'', ''Môi trường làm việc năng động, trẻ trung'', ''Có quyền tự chủ trong công việc'', ''Đào tạo nhân viên theo ISO 9001'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (992, 3, 4, 'Nhân Viên Trực Điện Thoại Tiếng Ý', 'Nhận cuộc gọi từ khách hàng nước ngoài qua ứng dụng Aircall (máy tính/điện thoại) và điền thông tin của khách vào mẫu đơn cho sẵn. Gọi lại những cuộc gọi nhỡ để lấy thông tin và điền form có sẵn. Những nhiệm vụ liên quan khác. Thông tin ca làm: Ca 2: từ 18h đến 22h (140.000vnđ/ca), Ca 3: từ 19h đến 23h (150.000vnđ/ca).', 'Có khả năng sử dụng tốt tiếng Ý, Nghe hiểu và giao tiếp tiếng Anh, Có thể làm việc vào cuối tuần và các ngày lễ, Một tuần đăng ký tối thiểu 4 ca làm việc, Có sẵn các thiết bị làm việc (laptop/PC, điện thoại, tai nghe…), Đảm bảo được không gian yên tĩnh khi làm việc để có chất lượng cuộc gọi tốt, Thử việc: 5 buổi làm việc đầu tiên, hưởng 85% thù lao.
Kỹ năng chuyên môn: [''Tiếng Ý lưu loát'', ''Tiếng Anh giao tiếp'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Khả năng làm việc dưới áp lực'', ''Kiên nhẫn'', ''Khả năng lắng nghe'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 14:00 đến 03:00)', '[''Tham gia các buổi training'', ''Thưởng hiệu suất'', ''Lương gấp 3 lần khi làm vào các ngày Lễ Tết'', ''Review tăng lương 6 tháng 1 lần'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (993, 7, 4, 'Giáo Vụ', '- Quản lý lớp học & Hỗ trợ giảng dạy Sắp xếp lịch học, phòng học, đảm bảo lớp học diễn ra đúng kế hoạch. Hỗ trợ giáo viên trong công tác giảng dạy, cung cấp tài liệu học tập. Theo dõi sĩ số, điểm danh, hỗ trợ học sinh trong quá trình học. - Làm việc với phụ huynh & học viên Giải đáp thắc mắc, tư vấn chương trình học phù hợp cho học sinh/phụ huynh. Hỗ trợ xử lý các vấn đề liên quan đến học viên: đổi lớp, xin nghỉ học, bảo lưu khóa học,… - Hỗ trợ hoạt động tuyển sinh & quản lý học vụ Hỗ trợ tổ chức thi đầu vào, thi giữa kỳ, cuối kỳ cho học sinh. Quản lý hồ sơ học sinh, cập nhật kết quả học tập. Phối hợp với bộ phận truyền thông để quảng bá các khóa học.', '- Tốt nghiệp hoặc đang theo học Cao đẳng/Đại học, ưu tiên ngành Sư phạm, Quản lý giáo dục, Ngôn ngữ Anh,… - Kỹ năng giao tiếp tốt, chủ động trong công việc. - Có kinh nghiệm làm việc trong môi trường giáo dục là một lợi thế. - Sử dụng thành thạo tin học văn phòng (Word, Excel, PowerPoint). - Tinh thần trách nhiệm cao, cẩn thận, tỉ mỉ.
Kỹ năng chuyên môn: [''Sử dụng thành thạo tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Chủ động trong công việc'', ''Tinh thần trách nhiệm cao'', ''Cẩn thận'', ''Tỉ mỉ'']', 'PART_TIME', 'ONSITE', 'đội 3, lạc thị, ngọc hồi, thanh trì', NULL, 'MONTHLY', 8000000.00, '1.0 - 8.0 triệu', 'Thứ 2 - Chủ nhật (từ 16:00 đến 21:00)', '[''Thưởng theo hiệu suất công việc'', ''Được đào tạo chuyên môn'', ''Cơ hội thăng tiến lên vị trí quản lý'', ''Môi trường làm việc năng động, chuyên nghiệp, có nhiều cơ hội học hỏi'', ''Du lịch hàng năm'', ''Phụ cấp thâm niên'', ''Thưởng tháng 13'', ''Thưởng hiệu quả làm việc'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (994, 8, 4, 'Cộng Tác Viên Dịch Vụ Khách Hàng', 'Hỗ trợ khách hàng: Liên hệ hỗ trợ khách hàng xử lý các vấn đề liên quan tới kỹ thuật, cài cắm thiết bị với phần mềm như máy in, máy quét, máy hiển thị QR; Phối hợp với bộ phận quản lý xử lý các công việc liên quan.', '1. Trình độ học vấn: Tốt nghiệp từ trung cấp trở lên, hoặc sinh viên đang theo học các trường CĐ, ĐH trên toàn quốc. 2. Kiến thức chuyên môn: Am hiểu cơ bản về kết nối các thiết bị ngoại vi vào máy tính và sử dụng trên Phần mềm bán hàng. 3. Kinh nghiệm: Ưu tiên ứng viên có kinh nghiệm 3 tháng ở vị trí chăm sóc khách hàng hoặc đã từng sử dụng phần mềm quản lý bán hàng. 4. Kỹ năng: Giao tiếp tốt, không nói ngọng, nói lắp, giọng địa phương; Sử dụng thành thạo phần mềm văn phòng (Word, Excel), công cụ hỗ trợ khách hàng (chat, ticket, CRM); Nhanh nhẹn, ham học hỏi chịu được áp lực công việc.
Kỹ năng chuyên môn: [''Am hiểu cơ bản về kết nối các thiết bị ngoại vi vào máy tính'', ''Sử dụng phần mềm bán hàng'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Nhanh nhẹn'', ''Ham học hỏi'', ''Chịu được áp lực công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Sáng thứ 7 (8h30-18h00)', '[''Có phụ cấp'', ''Được đào tạo về phần mềm, kỹ năng và nghiệp vụ kỹ thuật trong quá trình làm việc'', ''Môi trường công nghệ, trẻ trung, linh hoạt và cơ hội phát triển nghề nghiệp rõ ràng'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (995, 9, 4, 'Nhân Viên Gọi Điện Tư Vấn Nhà Hàng (ShopeeFood)', 'Nhận data khách hàng, phân chia và lọc những khách hàng tiềm năng theo khu vực..., quản lý và cập nhật dữ liệu khách hàng. Gọi điện cho Cửa hàng/Nhà hàng để tư vấn giới thiệu, thuyết phục quán tham gia các chương trình khuyến mãi/deal chạy trên ShopeeFood. Đảm bảo các chỉ số KPI được yêu cầu.', 'Tốt nghiệp THPT trở lên. Không vướng bận lịch học. Ưu tiên nhân sự có kinh nghiệm Telesales từ 6 Tháng trở lên hoặc vị trí chăm sóc khách hàng từ 1 năm. Giọng chuẩn, lưu loát, không nói giọng địa phương. Sử dụng tin học văn phòng cơ bản. Có trách nhiệm với công việc, hỗ trợ tối đa để giải quyết vấn đề của khách hàng. Nhẫn nại, nhiệt tình, nhanh nhẹn, chủ động, yêu thích công việc chăm sóc khách hàng và đảm bảo KPIs được đề ra.
Kỹ năng chuyên môn: [''Sử dụng tin học văn phòng cơ bản'']
Kỹ năng mềm: [''Giọng chuẩn'', ''Lưu loát'', ''Có trách nhiệm với công việc'', ''Nhẫn nại'', ''Nhiệt tình'', ''Nhanh nhẹn'', ''Chủ động'', ''Yêu thích công việc chăm sóc khách hàng'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 9000000.00, '6.0 - 9.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Thưởng Quý: 2.000.000 - 3.000.000 VNĐ'', ''Chuyên cần: 200k'', ''Bảo hiểm xã hội'', ''Bảo hiểm full lương'', ''Thưởng hiệu quả làm việc'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (996, 10, 4, 'Nhân Viên Pha Chế', 'Pha chế các đồ uống chuyên về cà phê, trà, đá xay đúng công thức quy định. Tư vấn, phục vụ khách hàng nhiệt tình, tận tâm, niềm nở các sản phẩm được bán tại cửa hàng. Đảm bảo vệ sinh quầy làm nước và cửa hàng theo quy định. Kiểm tra, bảo quản, bảo đảm hạn sử dụng các công cụ, dụng cụ & nguyên vật liệu hàng ngày trước và sau khi kết thúc ca làm việc. Hỗ trợ các công việc trong quầy và sảnh theo sự sắp xếp của Quản lý cửa hàng.', 'Đam mê pha chế nước uống và cà phê. Chủ động phục vụ & trung thực, trách nhiệm trong công việc. Yêu thích công việc tư vấn & chăm sóc khách hàng. Ham học hỏi & áp dụng những kiến thức được đào tạo trong công việc thực tế. Ưu tiên ứng viên đã qua các khoá chế biến cơ bản.
Kỹ năng chuyên môn: [''Pha chế đồ uống'', ''Vệ sinh an toàn thực phẩm'']
Kỹ năng mềm: [''Chủ động phục vụ'', ''Trung thực'', ''Trách nhiệm trong công việc'', ''Yêu thích công việc tư vấn & chăm sóc khách hàng'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'nha trang', NULL, 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Nhiều cơ hội thăng tiến'', ''Được đào tạo và phát triển kỹ năng Barista'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (997, 2, 4, 'TTS Kỹ Sư O&M - Hệ Thống Điện Năng Lượng Mặt Trời', '- Kiểm tra và giám sát thông số vận hành của toàn bộ hệ thống. - Thông báo và xử lý khi phát sinh sự cố, bất thường. - Cập nhật và ghi chép nhật ký vận hành hàng ngày. - Theo dõi, cảnh báo và báo cáo hiệu suất của các dự án được phân công. - Hỗ trợ bộ phận thiết kế khi được phân công.', '- Sinh viên năm cuối hoặc mới tốt nghiệp Đại học chuyên ngành Năng lượng tái tạo và các ngành kỹ thuật liên quan. - Có hiểu biết về hệ thống điện năng lượng mặt trời, năng lượng, hệ thống giám sát. - Có kiến thức và biết sử dụng các phần mềm PVSyst, AutoCAD, MS Office. - Có khả năng tự tìm hiểu các tài liệu chuyên ngành để nâng cao năng lực và cập nhật các kỹ thuật, công nghệ mới liên quan đến công việc được phân công. - Trung thực, có trách nhiệm với công việc và có khả năng làm việc theo nhóm, giao tiếp và phối hợp làm việc nhóm tốt. - Có thể làm việc tại Dự án (Trao đổi chi tiết khi Phỏng vấn). - Thời gian thực tập: 05-06 ngày/tuần, tối thiểu 03 tháng.
Kỹ năng chuyên môn: [''Hệ thống điện năng lượng mặt trời'', ''Phần mềm PVSyst'', ''AutoCAD'', ''MS Office'']
Kỹ năng mềm: [''Trung thực'', ''Có trách nhiệm với công việc'', ''Khả năng làm việc theo nhóm'', ''Giao tiếp và phối hợp làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', '05-06 ngày/tuần, tối thiểu 03 tháng', '[''Phụ cấp lương thực tập'', ''Được đào tạo chuyên môn & bản thân khi thực tập tại Công ty'', ''Cơ hội trở thành nhân viên chính thức'', ''Môi trường làm việc quốc tế thân thiện & chuyên nghiệp'', ''Được hưởng các quyền lợi khác theo chính sách công ty'', ''Hỗ trợ đóng dấu mộc và báo cáo thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (998, 3, 4, 'Nhân Viên Thời Vụ Seller Engagement - Shopee', 'Phân loại thông tin có sẵn trên các nhóm Facebook thành các nhóm theo hướng dẫn. Cập nhật nội dung, hình ảnh, bài viết trên website theo yêu cầu. Chỉnh sửa bài viết theo nhu cầu của người bán hàng. Gửi yêu cầu và theo dõi các design hình ảnh, gif với team internal. Golive: ASAP. Task không giới hạn thời gian kết thúc. Làm việc 5 ngày/tuần. Trong trường hợp phát sinh thêm nhiều task cần tăng thời gian làm việc sẽ trao đổi trực tiếp với BPO để chấm thêm ngày công.', 'Tuổi 20-28. Không quan trọng nam nữ. Có kiến thức về social, hội nhóm Facebook. Có kỹ năng phân tích dữ liệu (data analytics skill). Tiếng Anh cơ bản. Thành thạo tin học văn phòng: Excel, Google Sheet, … Tỉ mỉ, cẩn thận, trung thực, chịu khó, linh động, không ngại di chuyển, có thời gian trống đảm bảo được công việc.
Kỹ năng chuyên môn: [''Kỹ năng phân tích dữ liệu'', ''Thành thạo tin học văn phòng: Excel, Google Sheet'']
Kỹ năng mềm: [''Tỉ mỉ'', ''Cẩn thận'', ''Trung thực'', ''Chịu khó'', ''Linh động'', ''Không ngại di chuyển'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '9h-18h (nghỉ trưa 1 tiếng) hoặc có thể đi ca tối nếu có phát sinh', '[''Môi trường làm việc trẻ trung, năng động'', ''Cơ hội học hỏi kinh nghiệm'', ''Được đào tạo nếu chưa có kinh nghiệm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (999, 7, 4, 'Hoạt động thực tập (tiếng Đức)', 'Xử lý và nhập hóa đơn và tài liệu viết tay bằng tiếng Đức. Thực hiện các nhiệm vụ khác theo sự phân công của người quản lý. Thời gian thực tập: 4 - 6 tháng.', 'Qualification: College/University. German language proficiency in all four skills. Careful and hard-working.
Kỹ năng chuyên môn: [''German language proficiency in all four skills'']
Kỹ năng mềm: [''Careful'', ''Hard-working'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '8:00-17:50, Monday - Friday', '["Flexibility: provide flexible scheduling options to accommodate the intern''s educational commitments or other obligations", ''Professional development: opportunities to become full time employee'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1000, 8, 4, 'Nhân Viên Trực Điện Thoại Tiếng Pháp', 'Nhận cuộc gọi từ khách hàng nước ngoài qua ứng dụng Aircall (máy tính/điện thoại) và điền thông tin của khách vào mẫu đơn cho sẵn. Gọi lại những cuộc gọi nhỡ để lấy thông tin và điền form có sẵn. Những nhiệm vụ liên quan khác.', 'Có khả năng sử dụng tốt tiếng Pháp, Nghe hiểu và giao tiếp tiếng Anh, Có thể làm việc vào cuối tuần và các ngày lễ, Một tuần đăng ký tối thiểu 4 ca làm việc, Có sẵn các thiết bị làm việc (laptop/PC, điện thoại, tai nghe…), Đảm bảo được không gian yên tĩnh khi làm việc để có chất lượng cuộc gọi tốt, Thử việc: 5 buổi làm việc đầu tiên, hưởng 85% thù lao.
Kỹ năng chuyên môn: [''Tiếng Pháp'', ''Tiếng Anh'']
Kỹ năng mềm: [''Giao tiếp'', ''Làm việc nhóm'', ''Giải quyết vấn đề'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 14:00 đến 03:00)', '[''Tham gia các buổi training'', ''Thưởng hiệu suất'', ''Lương gấp 3 lần khi làm vào các ngày Lễ Tết'', ''Review tăng lương 6 tháng 1 lần'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1001, 9, 4, 'Nhân Viên Thời Vụ Hunt Merchant ShopeeFood', 'Nhận data khách hàng, phân chia và lọc những khách hàng tiềm năng theo khu vực..., quản lý và cập nhật dữ liệu khách hàng. Gọi điện cho Cửa hàng/Nhà hàng để tư vấn giới thiệu, thuyết phục quán tham gia các chương trình khuyến mãi/deal chạy trên Shopee Food. Các nội dung khác theo yêu cầu của quản lý.', 'Không yêu cầu kinh nghiệm. Không vướng bận công việc/lịch học.
Kỹ năng mềm: [''Khả năng chịu được áp lực cao'', ''Khả năng xử lý tình huống'', ''Kỹ năng giao tiếp'', ''Thuyết phục tốt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 9000000.00, '6.0 - 9.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Chuyên cần: 200.000 VNĐ'', ''Thưởng Quý: 2.000.000 - 3.000.000 VNĐ (tùy vào Performance)'', ''Hỗ trợ chi phí đào tạo 200.000/ngày (Đào tạo 2 ngày)'', ''Được trang bị đầy đủ các công cụ, trang thiết bị phục vụ công việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1002, 10, 4, 'Nhân Viên Chăm Sóc Khách Hàng', '- Kiểm tra đơn hàng theo toàn trình đơn, theo dõi xử lý đơn vận chuyển. - Liên hệ tài xế để xử lý đơn giao hàng sớm cho khách. - Thông báo cho shop về tình trạng đơn hàng. - Dán mã đơn, phân loại hàng, lên đơn, quét mã vạch.', '⮚ Linh động theo lịch học, đảm bảo ít nhất 4 buổi/tuần, 4 tiếng/buổi; ⮚ Có laptop cá nhân; ⮚ Chịu khó, chăm chỉ; ⮚ Khi nghỉ báo trước 15 ngày.
Kỹ năng chuyên môn: [''Sử dụng laptop'']
Kỹ năng mềm: [''Chịu khó'', ''Chăm chỉ'', ''Linh động'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', '4 buổi/tuần, 4 tiếng/buổi', '[''Thưởng sinh nhật'', ''Thưởng lễ tết'', ''Hướng dẫn về quy trình vận hành ngành thương mại điện tử'', ''Hướng dẫn nâng cao về các kỹ năng tin học văn phòng'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1003, 2, 4, 'Nhập Liệu Part Time, Full Time', '- Nhập các hồ sơ có cùng thuộc tính vào một nhóm - Liên hệ với người dùng, cập nhật lại những thông tin còn thiếu khi đăng ký - Liên hệ với người đăng ký thời gian đã lâu, cập nhật lại thông tin, yêu cầu của họ. - Cập nhật lại các nội dung dịch vụ cho Người dùng - Gửi thông tin các hồ sơ phù hợp cho người dùng - Làm theo sự phân công từ quản lý. - Trao đổi công việc với ứng viên tại văn phòng, không trao đổi online - Làm việc tại văn phòng công ty, không làm online. - Công ty không chấp nhận những ứng viên đang làm tại công ty khác muốn tìm thêm công việc.', '- Chấp nhận sinh viên năm 1, 2, 3, 4 các trường trung cấp, cao đẳng, đại học - Không yêu cầu bằng cấp, chấp nhận trung cấp, lao động phổ thông - Chấp nhận sinh viên và mới ra trường - Nhanh nhẹn, linh hoạt, giao tiếp tốt - Có laptop cá nhân - Sẵn sàng gọi điện cho khách hàng để đáp ứng công việc - Kiên định, tỉ mỉ trong công việc - Chịu được áp lực công việc
Kỹ năng chuyên môn: [''Có laptop cá nhân'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Linh hoạt'', ''Giao tiếp tốt'', ''Kiên định'', ''Tỉ mỉ trong công việc'', ''Chịu được áp lực công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 16000000.00, '3.0 - 16.0 triệu', 'Toàn thời gian: Từ thứ 2 đến thứ 7, 13h30 - 22h; Bán thời gian: 5 ca/tuần vào các buổi tối hoặc chiều T7 hoặc sáng chiều CN', '[''Môi trường làm việc năng động, trẻ trung'', ''Có quyền tự chủ trong công việc'', ''Được đào tạo về Quản Lý Chất Lượng ISO 9001'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1004, 3, 4, 'Chăm Sóc Khách Hàng Mảng Cá Nhân', '- Hỗ trợ giải đáp cho khách hàng cá nhân qua điện thoại, email, hỗ trợ khách hàng nâng cấp hợp đồng - Gọi điện thoại đến các khách hàng đăng ký dịch vụ, khảo sát sự hài lòng và tìm cách nâng cấp sự hài lòng của khách hàng - Triển khai dịch vụ cho khách hàng sau mua - Giải đáp khiếu nại của khách hàng - Làm theo sự phân công từ quản lý. - Phỏng vấn tại văn phòng công ty, không phỏng vấn online - Làm việc tại văn phòng công ty, không làm online. - Công ty không chấp nhận những ứng viên đang làm tại công ty khác muốn tìm thêm công việc. - Ứng viên chọn làm toàn thời gian/ bán thời gian theo thời gian dưới đây: + Thời gian làm việc Toàn thời gian: Từ thứ 2 đến thứ 7, trong đó bắt đầu làm từ 13h - 17h30, nghỉ từ 17h30 - 18h30, sau đó làm tiếp từ 18h30 đến 22h. Nghỉ Chủ nhật + Thời gian làm việc Bán thời gian: 1 tuần làm tối thiểu 5 ca "ngoài giờ hành chính" là “các ca tối hoặc ca chiều thứ 7 hoặc sáng chiều Chủ Nhật”. Ca sáng 8 - 12h/ Ca chiều 13h30 - 17h30/ Ca so le/ Ca gãy(2 ca gãy được tính là 1 ca)/ Ca tối 18h30 - 22h. Ứng viên có thể làm thêm nhiều giờ nếu muốn tăng thêm thu nhập', '- Chấp nhận sinh viên năm 1, 2, 3, 4 các trường trung cấp, cao đẳng, đại học - Không yêu cầu bằng cấp, chấp nhận bằng trung cấp, lao động phổ thông - Chấp nhận sinh viên và mới ra trường - Nhanh nhẹn, linh hoạt, giao tiếp tốt - Có laptop cá nhân - Sẵn sàng gọi điện cho khách hàng để đáp ứng công việc - Kiên định, tỉ mỉ trong công việc
Kỹ năng chuyên môn: [''Có laptop cá nhân'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Linh hoạt'', ''Giao tiếp tốt'', ''Kiên định'', ''Tỉ mỉ trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 20000000.00, '7.0 - 20.0 triệu', 'Toàn thời gian: Từ thứ 2 đến thứ 7, 13h30 - 22h; Bán thời gian: 5 ca/tuần vào các buổi tối hoặc chiều T7 hoặc sáng chiều CN', '[''Môi trường làm việc năng động, trẻ trung'', ''Có quyền tự chủ trong công việc'', ''Được đào tạo về Quản Lý Chất Lượng ISO 9001'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1005, 7, 4, 'Nhân Viên Thiết Lập Cuộc Hẹn Parttime', 'Xây dựng và duy trì mối quan hệ tốt đẹp với khách hàng hiện tại. Theo dõi sát sao tiến độ giao dịch và giải đáp mọi thắc mắc của khách hàng. Cung cấp thông tin và hỗ trợ khách hàng về các sản phẩm/dịch vụ bất động sản của công ty. Giải quyết các vấn đề và khiếu nại của khách hàng một cách hiệu quả và chuyên nghiệp. Thu thập thông tin phản hồi từ khách hàng và báo cáo cho bộ phận quản lý. Lập kế hoạch và thực hiện các hoạt động chăm sóc khách hàng định kỳ. Đảm bảo khách hàng hài lòng với chất lượng dịch vụ và sản phẩm của công ty. Phối hợp với các bộ phận khác để giải quyết các vấn đề liên quan đến khách hàng. Cập nhật thông tin khách hàng vào hệ thống quản lý khách hàng (CRM).', 'Ưu tiên có kinh nghiệm. Tốt nghiệp trung cấp trở lên, các chuyên ngành liên quan là một lợi thế. Kỹ năng giao tiếp tốt, giọng nói dễ nghe, khả năng thuyết phục. Khả năng quản lý thời gian hiệu quả, biết cách ưu tiên công việc. Kỹ năng tổ chức và lập kế hoạch tốt. Thành thạo phần mềm lịch hẹn (ví dụ: Google Calendar, Outlook Calendar). Khả năng sử dụng điện thoại và email hiệu quả. Trung thực, nhiệt tình, có trách nhiệm trong công việc. Khả năng làm việc độc lập và làm việc nhóm. Khả năng chịu áp lực công việc cao. Có kiến thức cơ bản về bất động sản là một lợi thế.
Kỹ năng chuyên môn: [''Thành thạo phần mềm lịch hẹn (ví dụ: Google Calendar, Outlook Calendar)'', ''Khả năng sử dụng điện thoại và email hiệu quả'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng quản lý thời gian hiệu quả'', ''Kỹ năng tổ chức và lập kế hoạch tốt'', ''Trung thực, nhiệt tình, có trách nhiệm trong công việc'', ''Khả năng làm việc độc lập và làm việc nhóm'', ''Khả năng chịu áp lực công việc cao'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 10:00)', '[''Mức lương cạnh tranh, thỏa thuận theo năng lực'', ''Chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp theo quy định của pháp luật'', ''Được tham gia các hoạt động đào tạo, nâng cao kỹ năng chuyên môn'', ''Môi trường làm việc năng động, chuyên nghiệp và thân thiện'', ''Cơ hội thăng tiến và phát triển nghề nghiệp'', ''Thưởng lễ, tết, thưởng hiệu quả công việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1006, 8, 4, 'Nhân Viên Chăm Sóc Khách Hàng', 'Tiếp nhận vấn đề/đơn hàng cần hỗ trợ của khách hàng, đội ngũ cộng tác viên qua kênh Chat (Fanpage - Zalo Shop - Web - Telegram). Tư vấn khách hàng về sản phẩm, quy trình mua hàng và chính sách bảo hành sản phẩm của công ty. Nhận đơn hàng từ khách hàng/Đại lý/CTV sau đó gửi cho bộ phận kỹ thuật, sau khi xử lý xong thì thông tin tới người mua. Thực hiện các yêu cầu công việc khác theo yêu cầu của quản lý. Quản lý đơn hàng và nhắc nhở khách hàng gia hạn khi gói đăng ký hết hạn. Từ 18 tuổi trở lên.', 'Có trách nhiệm với công việc, hỗ trợ tối đa để giải quyết vấn đề của khách hàng. Kiên nhẫn, nhiệt tình, nhanh nhẹn, chủ động, yêu thích công việc CSKH và đảm bảo KPIs được đề ra. Thao tác vi tính văn phòng tốt và khả năng đánh máy tốt. Hiểu biết 1 số phần mềm mạng xã hội, phần mềm bản quyền là một lợi thế. Có laptop cá nhân.
Kỹ năng chuyên môn: [''Thao tác vi tính văn phòng'', ''Hiểu biết một số phần mềm mạng xã hội'']
Kỹ năng mềm: [''Trách nhiệm'', ''Kiên nhẫn'', ''Nhiệt tình'', ''Nhanh nhẹn'', ''Chủ động'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Ca 1: 8:00 - 12:30, Ca 2: 14:00 - 18:30, Ca 3: 18:30 - 23:30', '[''Được cấp máy tính'', ''Được đào tạo nâng cao kỹ năng'', ''Thưởng các ngày lễ Tết, sinh nhật, cưới'', ''Du lịch hàng năm'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1007, 9, 4, 'Cộng Tác Viên Chăm Sóc Khách Hàng', 'Làm việc online TẠI NHÀ theo ca trực đã được phân công (bao gồm ca tối, cuối tuần, các dịp lễ, tết...). Chăm sóc, hỗ trợ khách hàng là người chơi game trong và ngoài nước qua các kênh hotline, email, fanpage,... Cung cấp các thông tin về game, hướng dẫn, giải đáp thắc mắc của người chơi trong quá trình chơi game. Tiếp nhận ý kiến, xử lý khiếu nại xảy ra khi chơi game. Tiếp nhận thông tin về các trường hợp lỗi game, các vấn đề khác và chuyển thông tin cho các bộ phận liên quan để xử lý. Không tìm kiếm khách hàng, không áp chỉ tiêu doanh số.', 'Là sinh viên các trường Đại học tại Hà Nội. Có máy tính và kết nối mạng. Khả năng đọc, hiểu tiếng Anh khá. Năng động, cẩn thận, nhiệt tình. Kỹ năng giao tiếp, đàm phán, ứng xử tốt. Yêu thích, đam mê chơi game và công việc hỗ trợ khách hàng. Có khả năng làm việc vào các dịp lễ tết của Việt Nam. Sau training sẽ làm việc online tại nhà.
Kỹ năng chuyên môn: [''Máy tính'', ''Kết nối mạng'']
Kỹ năng mềm: [''Năng động'', ''Cẩn thận'', ''Nhiệt tình'', ''Kỹ năng giao tiếp'', ''Đàm phán'', ''Ứng xử tốt'']', 'PART_TIME', 'REMOTE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - thứ 7: 18h - 21h; Chủ nhật: 9h - 12h, 12h - 15h, 15h - 18h, 18h - 21h', '[''Thời gian đào tạo được hưởng lương'', ''Cơ hội thăng tiến'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1008, 10, 4, 'Nhân Viên Chăm Sóc Khách Hàng', 'Gọi điện, nhắn tin bằng điện thoại công ty cho danh sách chủ nhà được soạn sẵn để xác nhận thông tin nhà đất; Cung cấp thông tin thu nhập được cho bộ phận Nhập Liệu; Sắp xếp, báo cáo công việc hằng ngày; Một số công việc khác theo yêu cầu của cấp trên; Thời gian làm việc xoay ca (1 tuần tối thiểu 5 ca).', 'Là sinh viên năm 1,2,3 các trường Đại học thuộc địa bàn Thành phố Hồ Chí Minh; Không cần kinh nghiệm, sẽ được đào tạo; Chăm chỉ, có tinh thần cầu tiến; Nghiêm túc hoàn thành tiến độ công việc.
Kỹ năng mềm: [''Chăm chỉ'', ''Có tinh thần cầu tiến'', ''Nghiêm túc hoàn thành tiến độ công việc'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '4.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Mức lương: 25.000 VND/giờ (tháng đầu thử việc: 23.000 VND/giờ)'', ''Giờ giấc xoay ca, phù hợp với lịch'', ''Được hỗ trợ tận tình bởi đồng nghiệp, quản lý có kinh nghiệm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1009, 2, 4, 'Thực Tập Sinh Chăm Sóc Khách Hàng', '- Tiếp nhận và xử lý thông tin - Kiểm tra dữ liệu thông tin khách hàng - Hỗ trợ các công việc hành chính - Kiểm tra các thông tin trên hệ thống', '- Có tinh thần trách nhiệm, tỉ mỉ, tích cực, cầu tiến - Ưu tiên ứng viên có kinh nghiệm chăm sóc khách hàng - Biết sử dụng tin học văn phòng - Kỹ năng giao tiếp và trình bày lưu loát - Ngoại hình ưa nhìn, giọng nói rõ ràng, dễ nghe - Thái độ nhiệt tình, thân thiện
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Trình bày lưu loát'', ''Tinh thần trách nhiệm'', ''Tỉ mỉ'', ''Tích cực'', ''Cầu tiến'', ''Thái độ nhiệt tình'', ''Thân thiện'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '4.0 - 6.0 triệu', 'Thứ 2 - Thứ 7 (từ 09:00 đến 18:00)', '[''Hỗ trợ dấu mộc thực tập'', ''Được đào tạo chuyên môn về nha khoa, kỹ năng giao tiếp'', ''Đóng bảo hiểm theo quy định của nhà nước'', ''Làm việc trong môi trường năng động, trẻ trung'', ''Có cơ hội phát triển'', ''Đầy đủ chế độ công đoàn: Hiếu, Hỉ, Sinh Nhật'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1010, 3, 4, 'Nhân Viên CSKH', '- Tiếp nhận và xử lý đơn hàng, hỗ trợ khách hàng qua các sàn TMĐT Shopee/Lazada/Tiktok/Tiki... - Tiếp nhận và xử lý các khiếu nại của khách hàng liên quan chất lượng sản phẩm, tiến độ giao hàng... - Chăm sóc khách hàng cũ bằng các chương trình khuyến mãi, hậu mãi... - Phối hợp làm việc với tất cả bộ phận liên quan (kho, ship, thu mua, đóng hàng,...) để đảm bảo tiến độ và hiệu quả công việc. - Liên hệ làm việc với nhân viên viên support của các sàn TMĐT để đăng kí chương trình khuyến mãi. - Thực hiện các yêu cầu khi được cấp quản lí giao phó.', '- Có laptop để làm việc - Có làm chủ nhật theo hình thức xoay vòng trong team, miễn là chủ nhật team CSKH có người làm việc. - Đăng kí tối thiểu 6 ca/tuần: + Ca 1: 8h - 12h + Ca 2: 13h - 17h + Ca 3: 18h - 22h
Kỹ năng chuyên môn: [''Microsoft Office'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:00 đến 17:00)', '[''Company trip mỗi năm 1 lần'', ''Chế độ lương, thưởng phù hợp với năng lực của mỗi nhân viên'', ''Đăng kí ca làm việc linh động theo sự sắp xếp của quản lý'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1011, 7, 4, 'Cộng tác viên Chăm Sóc Khách Hàng (Part-time)', 'Trực page và xin SĐT khách hàng mới để chuyển tới bộ phận tư vấn. Hỗ trợ tư vấn, giải đáp thắc mắc học viên tìm hiểu khóa học. Tiếp nhận phản hồi, khiếu nại của khách hàng để chuyển tới bộ phận liên quan. Thực hiện báo báo hàng ngày. Thực hiện các công việc khác theo điều phối của Trưởng bộ phận.', 'Kỹ năng giao tiếp, kỹ năng xử lý tình huống và kỹ năng làm việc nhóm tốt. Chủ động và biết cách tổ chức, sắp xếp công việc. Làm việc : 4 giờ/1 ca làm việc, có làm việc cuối tuần. Hiểu biết và hứng thú với sản phẩm e-Learning là lợi thế. Sử dụng thành thạo Google Sheets và phần mềm quản lý học viên là lợi thế. Nhanh nhẹn, chăm chỉ, có trách nhiệm với công việc. Có máy tính cá nhân.
Kỹ năng chuyên môn: [''Google Sheets'', ''Phần mềm quản lý học viên'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng xử lý tình huống'', ''Kỹ năng làm việc nhóm'', ''Chủ động'', ''Tổ chức công việc'']', 'PART_TIME', 'ONSITE', 'cầu giấy, hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.5 - 4.0 triệu', '4 giờ/1 ca làm việc, có làm việc cuối tuần', '[''Lương cơ bản: 25.000/giờ + bonus'', ''Môi trường làm việc trẻ trung'', ''Hỗ trợ chi phí gửi xe'', ''Team building'', ''Du lịch hàng năm'', ''Thưởng hiệu quả làm việc'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1012, 8, 4, 'Cộng Tác Viên Chăm Sóc Khách Hàng', 'Trực Inbound: Tiếp nhận, giải đáp, hướng dẫn và xử lý khiếu nại của Khách hàng. Làm việc luân phiên giờ hành chính và theo ca. Trực Outbound: Gọi ra chăm sóc khách hàng, khảo sát các nhu cầu khách hàng khi sử dụng dịch vụ, gọi ra chuẩn hóa thông tin hồ sơ khách hàng, gọi ra mời KH trải nghiệm thêm các dịch vụ mới, sản phẩm mới trong hệ sinh thái giao thông thông minh. Làm việc theo các ca được phân công trong ngày.', 'Sinh viên năm 3 hoặc đang chờ lấy bằng, ưu tiên đã có kinh nghiệm tại vị trí CSKH. Có thể làm theo ca, ca xoay. Chất giọng dễ nghe, sử dụng thành thạo vi tính. Ưu tiên các bạn đã có kinh nghiệm telesale, telemarketing.
Kỹ năng chuyên môn: [''Sử dụng vi tính'']
Kỹ năng mềm: [''Chất giọng dễ nghe'', ''Có khả năng làm việc theo ca'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '7.0 triệu', 'Ca 1: 07h00-14h30, Ca 2: 14h30-22h00, Ca 3: 22h00-07h00', '[''Học hỏi và trau dồi kinh nghiệm CSKH thực tế'', ''Phù hợp với các bạn sinh viên chưa ra trường, mong muốn tìm kiếm công việc làm thêm'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1013, 9, 4, 'Cộng Tác Viên Chăm Sóc Khách Hàng Parttime', 'Cộng tác viên chăm sóc khách hàng (Part-time) | Prep Mô tả công việc • Trực page và xin SĐT khách hàng mới để chuyển tới bộ phận tư vấn • Hỗ trợ tư vấn, giải đáp thắc mắc học viên tìm hiểu khóa học • Tiếp nhận phản hồi, khiếu nại của khách hàng để chuyển tới bộ phận liên quan • Thực hiện báo báo hàng ngày • Thực hiện các công việc khác theo điều phối của Trưởng bộ phận Địa điểm làm việc: 39 ngõ 12 Trần Kim Xuyến, Cầu Giấy, Hà Nội Thời gian làm việc: Yêu cầu làm các tối và cuối tuần', '• Kỹ năng giao tiếp, kỹ năng xử lý tình huống và kỹ năng làm việc nhóm tốt • Chủ động và biết cách tổ chức, sắp xếp công việc • Làm việc : ca tối 17h-21h (4 giờ/1 ca làm việc, có làm việc cuối tuần). Thời gian này sẽ làm việc online tại nhà và sau sẽ có phân công địa chỉ làm việc cụ thể sau • Hiểu biết và hứng thú với sản phẩm e-Learning là lợi thế • Sử dụng thành thạo Google Sheets và phần mềm quản lý học viên là lợi thế • Nhanh nhẹn, chăm chỉ, có trách nhiệm với công việc • Có máy tính cá nhân
Kỹ năng chuyên môn: [''Google Sheets'', ''Phần mềm quản lý học viên'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng xử lý tình huống'', ''Kỹ năng làm việc nhóm'', ''Chủ động'', ''Tổ chức công việc'']', 'PART_TIME', 'ONSITE', 'cầu giấy, hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '2.5 - 4.0 triệu', '17h-21h, có làm việc cuối tuần', '[''Lương cơ bản: 25.000/giờ + bonus'', ''Môi trường làm việc trẻ trung'', ''Hỗ trợ chi phí gửi xe'', ''Du lịch hàng năm'', ''Team building'', ''Thưởng hiệu quả làm việc'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1014, 10, 4, 'Thực Tập Vận Hành Sàn Tiktok (Hỗ Trợ Dấu Thực Tập)', 'Nội dung thực tập sẽ được hướng dẫn bài bản, chi tiết gồm 05 phần: 25%: Thực tập xây dựng gian hàng trên sàn thương mại điện tử Tiktok Shop US. 25%: Nghiên cứu, xây dựng hệ thống sản phẩm độc đáo, thu hút người mua hàng về Shop của mình. 40%: Trực tiếp vận hành các hoạt động của sàn thương mại điện tử (Sáng tạo video tiktok, Xử lý đơn hàng, Chạy quảng cáo). 10%: Báo cáo kết quả công việc hằng ngày cho quản lý. Đánh giá ưu nhược điểm của toàn bộ quá trình vận hành sàn thương mại điện tử, cải thiện những gì còn thiếu sót.', 'Tiêu chí ngoại ngữ: TOEIC: 500 trở lên (Không yêu cầu chứng chỉ). Ưu tiên biết sử dụng canva, PTS, AI. Ưu tiên biết edit video, kinh nghiệm content. Yêu cầu thời gian: Có thể làm Full Time và có mong muốn lên nhân viên chính thức tại công ty (hỗ trợ 1-2 buổi nếu có lịch học).
Kỹ năng chuyên môn: [''Sử dụng Canva'', ''Photoshop'', ''AI'', ''Edit video'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Khả năng làm việc nhóm'', ''Hiểu biết về thuật toán Tiktok'', ''Kỹ năng phân tích dữ liệu'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', '8h - 17h, thứ 2 - thứ 7', '[''Lương hỗ trợ'', ''Dấu thực tập'', ''Cơ hội lên nhân viên chính thức'', ''Môi trường làm việc chuyên nghiệp'', ''Thưởng hiệu quả làm việc'', ''Du lịch hàng năm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1015, 2, 4, 'Chăm Sóc Khách Hàng App Du Lịch Quốc Tế (Tiếng Anh)', 'Kết nối với khách hàng qua điện thoại, email, tin nhắn để hỗ trợ nhanh chóng các vấn đề liên quan đến chuyến du lịch, lưu trú, thay đổi/hủy đặt phòng và phản hồi thắc mắc. Cung cấp thông tin chính xác, đầy đủ bằng cách sử dụng các công cụ và quy trình chuyên nghiệp. Tận tâm mang đến trải nghiệm tuyệt vời, đảm bảo mỗi khách hàng đều cảm thấy hài lòng khi sử dụng dịch vụ.', 'Tốt nghiệp THPT, mong muốn phát triển sự nghiệp lâu dài. Thành thạo tiếng Anh (nghe, nói, đọc, viết) và tự tin làm việc 100% bằng tiếng Anh. Có trách nhiệm cao, tận tâm trong công việc và luôn hướng đến sự chuyên nghiệp. Bắt buộc xoay ca (phụ cấp 30% lương khi làm việc ca đêm).
Kỹ năng chuyên môn: [''Thành thạo tiếng Anh (nghe, nói, đọc, viết)'']
Kỹ năng mềm: [''Có trách nhiệm cao'', ''Tận tâm trong công việc'', ''Hướng đến sự chuyên nghiệp'']', 'PART_TIME', 'ONSITE', 'quận 12', 'Hồ Chí Minh', 'MONTHLY', 13000000.00, '10.0 - 13.0 triệu', 'Bắt buộc xoay ca 5 ngày/tuần, 9 tiếng/ca', '[''Bảo hiểm xã hội'', ''Bảo hiểm sức khỏe'', ''Team building'', ''Du lịch hàng năm'', ''Thưởng tháng 13'', ''Phụ cấp thâm niên'', ''Thưởng hiệu quả làm việc'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1016, 3, 4, 'Chăm Sóc Khách Hàng Cho Thuê Căn Hộ Part-Time', 'Tham gia tư vấn và giới thiệu dịch vụ căn hộ của công ty đến khách hàng người nước ngoài. Lập kế hoạch, triển khai chiến lược phù hợp với từng khách hàng. Đảm bảo việc quản lý và phát triển mối quan hệ với khách hàng hiện tại và tiềm năng. Theo dõi và báo cáo hiệu quả của các hoạt động chăm sóc khách hàng. Tham gia bàn giao, thanh lý căn hộ và hỗ trợ khách thuê trong quá trình ở tại căn hộ.', 'Tiếng Anh giao tiếp cơ bản, có thể làm việc với người nước ngoài. Sinh viên năm 3-4 các trường Đại học, Cao đẳng (có kinh nghiệm trong lĩnh vực BĐS, CSKH là một lợi thế). Sáng tạo, năng động và có khả năng làm việc dưới áp lực cao. Kỹ năng giao tiếp và thuyết phục tốt. Chưa có kinh nghiệm sẽ được đào tạo.
Kỹ năng mềm: [''Sáng tạo'', ''Năng động'', ''Kỹ năng giao tiếp'', ''Kỹ năng thuyết phục'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 làm việc online', '[''Nâng cao trình độ giao tiếp Tiếng Anh'', ''Lương cứng + hoa hồng cao theo doanh số'', ''Môi trường làm việc chuyên nghiệp, năng động'', ''Được đào tạo bài bản các kỹ năng kinh doanh, chăm sóc khách hàng'', ''Công ty có hỗ trợ mộc thực tập cho sinh viên'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1017, 7, 4, 'Nhân Viên CSKH', 'Tư vấn và chốt đơn cho khách hàng cho nhu cầu sử dụng dịch vụ của công ty cụ thể trên Pancake và phần mềm CRM. Khách hàng của công ty là chủ shop bán hàng trên các trang TMĐT. Hỗ trợ và giải đáp kịp thời các thắc mắc trong quá trình khách hàng sử dụng dịch vụ. Kết hợp với bộ phận Kỹ thuật để xử lý các vấn đề phát sinh. Một số công việc khác theo yêu cầu của Quản lý.', 'Yêu cầu ứng viên: Không yêu cầu kinh nghiệm, sẽ được đào tạo từ đầu. Có định hướng và đam mê yêu thích công việc kinh doanh. Sinh viên năm 2,3 các trường CĐ/ĐH tại Hà Nội, có định hướng theo đuổi mảng Kinh doanh, Bán hàng, Digital Marketing hoặc Thương mại điện tử. Có laptop cá nhân, sử dụng tin học văn phòng tốt. Kỹ năng giao tiếp tốt, không bị giọng địa phương.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Không bị giọng địa phương'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 21:00)', '[''Hỗ trợ từ Leader'', ''Lương chính thức: 20k/h + thưởng doanh thu + thưởng khác'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1018, 8, 4, 'Chăm Sóc Khách Hàng Parttime Ca Tối', '- Hỗ trợ khách hàng giải đáp thắc mắc về sản phẩm của công ty qua hình thức chat/gọi điện cho khách hàng. - Ghi nhận thông tin khách hàng và cập nhật vào hệ thống quản lý. - Giải quyết các vấn đề, khiếu nại của khách hàng một cách nhanh chóng và hiệu quả. - Báo cáo và thực hiện công việc theo sự phân phó của Leader.', '- Nhanh nhẹn, cẩn thận - Giao tiếp tốt - Có kinh nghiệm làm CSKH hoặc sale là một lợi thế; - Có thể lên văn phòng training tầm 3 - 5 buổi theo giờ hành chính (Linh hoạt các ca sáng/chiều các ngày trong tuần)
Kỹ năng mềm: [''Nhanh nhẹn'', ''Cẩn thận'', ''Giao tiếp tốt'']', 'PART_TIME', 'ONSITE', 'bắc từ liêm', 'Hà Nội', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', '18h - 00h', '[''Có cơ hội được offer làm nhân viên chính thức tại Công ty'', ''Được đào tạo, nâng cao kỹ năng CSKH và cơ hội thăng tiến lên các vị trí cao hơn'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1019, 9, 4, 'Nhân Viên Kiểm Duyệt Đơn Hàng Part Time, Full Time', 'Kiểm Duyệt các đơn đăng ký dịch vụ mới. Xây dựng và thực hiện các chiến lược vận hành với khách hàng hiệu quả, gọi điện thúc đẩy khách hàng đã từng tiếp cận sử dụng dịch vụ. Quản lý và tối ưu hóa hoạt động của khách hàng bao gồm liên hệ gọi điện đến khách hàng khi khách hàng đăng ký, tư vấn về nội dung dịch vụ. Phân tích dữ liệu, báo cáo hiệu quả hoạt động của khách hàng và đề xuất các giải pháp cải thiện. Giám sát và xử lý các vấn đề phát sinh của khách hàng, đảm bảo hoạt động trơn tru. Hỗ trợ và giải quyết các vấn đề của khách hàng. Cập nhật và quản lý thông tin dịch vụ. Phối hợp với các bộ phận khác trong công ty để đảm bảo hoạt động hiệu quả. Thực hiện các công việc khác theo sự phân công của cấp trên.', 'Không yêu cầu kinh nghiệm. Chấp nhận Sinh viên năm 1, 2, 3 và 4 các trường đại học và cao đẳng. Khả năng phân tích dữ liệu và báo cáo hiệu quả. Kỹ năng giao tiếp và giải quyết vấn đề tốt. Khả năng làm việc độc lập và làm việc nhóm. Có tinh thần trách nhiệm cao và năng động. Thành thạo tin học văn phòng (Word, Excel, PowerPoint). Am hiểu về các kênh marketing online là một lợi thế (Facebook, Google,…). Khả năng làm việc dưới áp lực cao.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, PowerPoint)'', ''Am hiểu về các kênh marketing online (Facebook, Google)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Giải quyết vấn đề'', ''Khả năng làm việc độc lập'', ''Làm việc nhóm'', ''Tinh thần trách nhiệm cao'', ''Năng động'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 20000000.00, '2.0 - 20.0 triệu', 'Toàn thời gian: Từ thứ 2 đến thứ 6, 13h30 - 21h; Bán thời gian: 1 tuần tối thiểu 6 ca', '[''Môi trường làm việc năng động, trẻ trung'', ''Được đào tạo về Quản Lý Chất Lượng ISO 9001'', ''Thưởng, service, hoa hồng team'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1020, 10, 4, 'Nhân Viên Chăm Sóc Khách Hàng', 'Tư vấn và giới thiệu các sản phẩm bất động sản của công ty đến khách hàng. Thực hiện các cuộc gọi và tư vấn sản phẩm phù hợp. Cập nhật thông tin thị trường bất động sản và các sản phẩm mới của công ty. Tham gia các hoạt động, sự kiện chào bán của công ty và chủ đầu tư.', 'Không yêu cầu kinh nghiệm, được đào tạo bài bản. Sinh viên các trường trung cấp, cao đẳng, đại học, có thể đi làm 4-5 ca/ tuần.
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, PowerPoint)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Giọng nói dễ nghe'', ''Nắm bắt nhanh kiến thức mới'', ''Ham học hỏi'', ''Trung thực'', ''Nhiệt tình'', ''Năng động'']', 'PART_TIME', 'ONSITE', 'hà nội, hưng yên', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca sáng 09h00 -12h00 và Ca chiều 14h00 -17h00', '[''Lương cứng 30.000VNĐ/giờ + hoa hồng hấp dẫn'', ''Được đào tạo bài bản về kiến thức bất động sản và kỹ năng tư vấn khách hàng'', ''Môi trường làm việc năng động, chuyên nghiệp và thân thiện'', ''Có nhiều cơ hội thăng tiến trong nghề nghiệp'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1021, 2, 4, 'Content Management', 'Cập nhật dữ liệu sản phẩm, quản lý thư viện hình ảnh, cập nhật nội dung thương hiệu, kiểm tra và chỉnh sửa định kỳ, phối hợp các bộ phận khác.', 'Cẩn thận, tỉ mỉ, có tư duy hệ thống. Thành thạo Excel, Google Sheet, các nền tảng CMS quản trị nội dung. Có kiến thức cơ bản về chỉnh sửa ảnh và tối ưu hóa nội dung số. Ưu tiên có kinh nghiệm đăng sản phẩm cho website TMĐT hoặc vận hành gian hàng thương mại điện tử.
Kỹ năng chuyên môn: [''Excel'', ''Google Sheet'', ''CMS quản trị nội dung'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Tư duy hệ thống'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 20000000.00, '15.0 - 20.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '[''Ăn trưa'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1022, 3, 4, 'Nhân Viên Giáo Vụ', 'Tiếp nhận thông tin đặt lịch học và điều phối lịch học hợp lý. Xử lý các yêu cầu dời lịch, đổi lịch theo quy định của trung tâm. Điểm danh, theo dõi học viên, nhắc nhở khi vắng học, hết hạn bảo lưu, đến kỳ thanh toán. Lập hóa đơn và theo dõi thu/chi cho học viên. Hỗ trợ tư vấn viên các công việc tư vấn, hướng dẫn khách hàng mới. Sắp xếp vệ sinh khu vực lễ tân, phòng học theo phân công. Tổng hợp và gửi báo cáo theo định kỳ.', 'Nữ đã từng có kinh nghiệm làm việc liên quan đến giáo vụ, sắp xếp lịch học, lễ tân or chăm sóc khách hàng. Ưu tiên ứng viên từng làm trong lĩnh vực giáo dục, đào tạo, nghệ thuật. Tác phong chuyên nghiệp, nhanh nhẹn, chủ động học hỏi và thao tác máy tính thành thạo. Giọng nói dễ nghe, truyền cảm – tạo cảm giác thân thiện khi giao tiếp với học viên. Mang năng lượng tích cực, vui vẻ; có tư duy cầu tiến và luôn sẵn sàng cải thiện để phát triển bản thân. Luôn niềm nở với học viên, giáo viên.
Kỹ năng chuyên môn: [''Thao tác máy tính thành thạo'']
Kỹ năng mềm: [''Tác phong chuyên nghiệp'', ''Nhanh nhẹn'', ''Chủ động học hỏi'', ''Giọng nói dễ nghe'', ''Truyền cảm'', ''Mang năng lượng tích cực'', ''Vui vẻ'', ''Tư duy cầu tiến'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Cơ hội được đào tạo nâng cao chuyên môn'', ''Làm việc trong môi trường sáng tạo, trẻ trung'', ''Được hướng dẫn và tiếp cận quy trình sản xuất nội dung bài bản'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1023, 7, 4, 'Nhân Viên Chăm Sóc Khách Hàng', 'Gọi điện trao đổi, tư vấn khách hàng. Giải đáp các vấn đề có liên quan đến dịch vụ. Phối hợp với các nhân viên, phòng ban khác để giải quyết công việc. Thực hiện các công việc khác theo yêu cầu.', 'Độ tuổi từ 18-22 tuổi, ưu tiên sinh viên các trường Trung Cấp, Cao đẳng, Đại học. Chăm chỉ , nhiệt tình, trung thực. Kỹ năng giao tiếp, tư vấn qua điện thoại. Giọng nói dễ nghe, truyền cảm. Ưu tiên sinh viên làm partime, có thể làm cả Fulltime.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Tư vấn qua điện thoại'']
Kỹ năng mềm: [''Chăm chỉ'', ''Nhiệt tình'', ''Trung thực'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '5.0 - 7.0 triệu', 'Thứ 2 - Chủ nhật (từ 08:30 đến 17:00)', '[''Lương cứng 5-7tr/tháng + thưởng hàng tháng'', ''Được cung cấp trang thiết bị làm việc'', ''Chế độ ngày lễ Tết, sinh nhật'', ''Được đăng ký làm việc Fulltime/Partime, đăng ký ca linh hoạt'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1024, 8, 4, 'Thực Tập Sinh Chăm Sóc Khách Hàng Tiếng Trung', 'Dịch thuật tài liệu, văn bản, hợp đồng. Làm việc với nhà cung ứng như token, ngân hàng. Hỗ trợ scan lưu trữ tài liệu, đóng dấu tài liệu cho khách hàng. Hỗ trợ khách hàng Trung Quốc làm thủ tục ngân hàng, xin giấy khám sức khỏe, làm lý lịch tư pháp khi có yêu cầu. Hỗ trợ gửi thư cho khách hàng, bàn giao hồ sơ cho khách.', 'Ưu tiên Sinh viên năm cuối chuyên ngành Tiếng Trung hoặc các chuyên ngành có liên quan. Có thể thực tập tối thiểu 3 tháng và thực tập tối thiểu 3 ngày/ tuần từ T2-T6. Có tinh thần tìm tòi, học hỏi, cập nhật kiến thức mới, nhiệt tình, trung thực và kiên nhẫn. Có máy tính cá nhân. Thái độ tốt, thực sự khao khát với nghề. Cầu tiến, nắm bắt nhanh các tiện ích công nghệ để áp dụng hiệu quả vào công việc.
Kỹ năng chuyên môn: [''Tiếng Trung'']
Kỹ năng mềm: [''Tinh thần tìm tòi'', ''Học hỏi'', ''Nhiệt tình'', ''Trung thực'', ''Kiên nhẫn'', ''Thái độ tốt'', ''Cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 1000000.00, '1.5 - 1.8 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Phụ cấp thực tập từ 1.500.000-1.800.000 VNĐ'', ''Cơ hội trở thành nhân viên chính thức'', ''Được học nghiệp vụ và thực hành giao tiếp tiếng Trung'', ''Được đào tạo về kiến thức và kỹ năng chuyên môn'', ''Tham gia các hoạt động ngoại khóa, phúc lợi, dã ngoại'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1025, 9, 4, 'Thực Tập Sinh Hỗ Trợ Kinh Doanh', '- Hỗ trợ chăm sóc khách hàng sau bán hàng (kênh chat, không Tele) - Học hỏi quy trình tư vấn và chốt giao dịch. - Tham gia các buổi đào tạo nội bộ, hỗ trợ các hoạt động bán hàng - Các công việc khác theo yêu cầu của cấp trên', '- Ưu tiên quản trị kinh doanh/marketing - Có kiến thức cơ bản về marketing và truyền thông trên mạng xã hội / sàn TMĐT - Có khả năng viết kịch bản sáng tạo và hấp dẫn. - Có khả năng làm việc độc lập và làm việc nhóm tốt - Có laptop
Kỹ năng chuyên môn: [''Kiến thức cơ bản về marketing'', ''Truyền thông trên mạng xã hội'', ''Sàn TMĐT'']
Kỹ năng mềm: [''Khả năng viết kịch bản sáng tạo'', ''Làm việc độc lập'', ''Làm việc nhóm tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:00)', '[''Phụ cấp: 20.000đ/giờ'', ''Bãi gửi xe miễn phí'', ''Hướng dẫn 1-1 bởi mentor chuyên môn'', ''Có xác nhận thực tập'', ''Hỗ trợ làm báo cáo / luận văn tốt nghiệp'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1026, 10, 4, 'Thực Tập Sinh Kinh Doanh', 'Hỗ trợ tiếp nhận và phản hồi tin nhắn/inbox của khách hàng qua các kênh: Facebook, Instagram, Zalo, hotline,…. Tư vấn về tầm quan trọng của da, cách chăm sóc da; giới thiệu về nhãn hàng và các cách chăm sóc da dùng sản phẩm Sakura và kết hợp các sản phẩm khác, các chương trình và địa điểm bán của Sakura trên toàn quốc chính xác, thân thiện. Hỗ trợ chăm sóc khách hàng cũ, nhắn tin hỏi thăm trải nghiệm, đánh giá dịch vụ/sản phẩm. Phối hợp với các bộ phận liên quan (bán hàng, kho, vận đơn...) để xử lý yêu cầu từ khách. Cập nhật, ghi nhận thông tin khách hàng và tương tác lên hệ thống (CRM,...) Tham gia các chiến dịch CSKH định kỳ như: sinh nhật khách hàng, chăm sóc hậu mãi,... Thực hiện các công việc hành chính – CSKH khác theo phân công', 'Là sinh viên năm 4 hoặc mới tốt nghiệp các ngành: Kinh doanh, Marketing, Mỹ phẩm, Chăm sóc sắc đẹp hoặc các ngành liên quan. Đam mê lĩnh vực làm đẹp, mỹ phẩm; có hiểu biết hoặc từng sử dụng các sản phẩm chăm sóc da, trang điểm là lợi thế. Giao tiếp tốt, nhanh nhẹn, chăm chỉ, có tinh thần cầu tiến. Biết sử dụng tin học văn phòng, các nền tảng mạng xã hội (Facebook, Zalo, Instagram...). Có thể làm việc full-time là một điểm cộng.
Kỹ năng chuyên môn: [''Sử dụng tin học văn phòng'', ''Sử dụng các nền tảng mạng xã hội (Facebook, Zalo, Instagram)'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Nhanh nhẹn'', ''Chăm chỉ'', ''Có tinh thần cầu tiến'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 6000000.00, '3.0 - 6.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30), Thứ 7 (từ 08:00 đến 12:00)', '[''Được đào tạo chuyên sâu về sản phẩm mỹ phẩm, kỹ năng tư vấn bán hàng và chăm sóc khách hàng'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập'', ''Làm việc trong môi trường trẻ trung, năng động, nhiều cơ hội học hỏi'', ''Tham gia các chương trình làm đẹp, sự kiện nội bộ, teambuilding'', ''Phụ cấp: Gửi xe'', ''Xăng xe'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1027, 2, 4, 'Cộng Tác Viên Quản Lý Dữ Liệu Khách Hàng', 'Thu thập và nhập chính xác thông tin menu nhà hàng lên hệ thống quản lý của AhaFood AI. Cập nhật menu định kỳ hoặc khi có sự thay đổi từ phía nhà hàng. Làm việc trực tiếp với đội phát triển kinh doanh (BD) để tạo và cập nhật các chương trình giảm giá. Quản lý hệ thống deal giảm giá, đảm bảo các chương trình khuyến mãi diễn ra suôn sẻ và đúng kế hoạch. Giám sát và báo cáo tình hình hiệu quả của các chương trình giảm giá, đề xuất cải tiến nếu cần thiết. Phối hợp với đội ngũ phát triển sản phẩm và marketing để điều chỉnh thông tin trên hệ thống nhằm tối ưu hóa trải nghiệm người dùng. Quản lý webstore giúp tăng trưởng trải nghiệm người dùng. Giải quyết các vấn đề phát sinh liên quan đến dữ liệu menu và deal giảm giá.', 'Có kỹ năng làm việc với máy tính và các phần mềm quản lý cơ bản. Chi tiết, cẩn thận, có khả năng nhập liệu chính xác. Kỹ năng giao tiếp tốt để làm việc với đội phát triển kinh doanh, marketing & phòng sản phẩm. Có khả năng làm việc độc lập và tự giác trong công việc. Tinh thần hỗ trợ cao & trách nhiệm cao. Làm tối thiểu 6 ca/ tuần.
Kỹ năng chuyên môn: [''Sử dụng phần mềm quản lý dữ liệu (Excel, Google Sheets, SQL)'']
Kỹ năng mềm: [''Chi tiết, cẩn thận'', ''Kỹ năng giao tiếp tốt'', ''Có khả năng làm việc độc lập'', ''Tinh thần hỗ trợ cao'', ''Trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'đà nẵng', 'Đà Nẵng', 'MONTHLY', 7000000.00, '4.0 - 7.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Cơ hội học hỏi và làm việc với công nghệ AI tiên tiến'', ''Môi trường làm việc trẻ, năng động, sáng tạo'', ''Cơ hội trở thành nhân viên chính thức tại Ahamove'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1028, 3, 4, 'Trợ lý dự án thực tập', 'Thu thập dữ liệu từ nhiều nguồn khác nhau, đảm bảo báo cáo chính xác dữ liệu, biên dịch dữ liệu vào các báo cáo, hỗ trợ các cuộc họp lập lịch, quản lý thư từ với khách hàng, làm việc chặt chẽ với các trợ lý dự án cao cấp.', 'Currently pursuing or recently completed a degree in Business, Project Management, Administration, or a related field. Proficiency in Microsoft Office Suite (Excel, Word, PowerPoint). A minimum English proficiency level of B2 is required, along with excellent writing and listening skills. Basic proficiency in Chinese / Korean / Japanese is an advantage. Strong analytical and problem-solving skills. Excellent organizational and time management abilities. Effective communication skills, both written and verbal. Ability to work independently and as part of a team.
Kỹ năng chuyên môn: [''Microsoft Office Suite (Excel, Word, PowerPoint)'']
Kỹ năng mềm: [''Strong analytical and problem-solving skills'', ''Excellent organizational and time management abilities'', ''Effective communication skills, both written and verbal'', ''Ability to work independently and as part of a team'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 7000000.00, '7.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Gain hands-on experience in project management and administrative support'', ''Opportunity to work with a dynamic, supportive and multilingual team'', ''Mentorship and professional development opportunities'', ''Provide with working devices'', ''Monthly Internship Allowance: B2 English level: 6,000,000 VND, C1 English level: 7,000,000 VND'', ''100% monthly internship allowance + 1,000,000 VND monthly incentive'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1029, 7, 4, 'Nhân Viên Tư Vấn Khách Hàng Theo Ca (Call Center)', 'Công việc của bạn tập trung vào việc thực hiện các cuộc gọi first-call để xác minh thông tin và hỗ trợ khách hàng, từ đó tạo nền tảng vững chắc cho quy trình bán hàng chuyên nghiệp của Vucar. Thực hiện cuộc gọi First-call theo quy trình: Trong ca trực, bạn cần thực hiện cuộc gọi trong vòng 5 phút kể từ khi nhận được thông tin khách hàng (lead). Sử dụng kịch bản có sẵn để gọi điện xác minh thông tin, tìm hiểu insights về nhu cầu bán xe và mức độ sẵn sàng của khách hàng. Kết bạn Zalo, hướng dẫn gửi hình ảnh xe và thông tin đăng kiểm, đảm bảo thông tin chính xác và đầy đủ để Sales Executive follow-up hiệu quả. Đối với các lead chưa bắt máy, bạn sẽ gọi lại tối đa 3 lần (mỗi lần cách nhau 1-2 tiếng), đồng thời kết bạn và nhắn tin Zalo để tiếp cận khách hàng. Nhập liệu và hỗ trợ chăm sóc khách hàng: Nhập liệu chi tiết các thông tin đã thu thập vào hệ thống CRM của Vucar (được hướng dẫn). Chuyển giao thông tin đầy đủ cho đội ngũ Sales và hỗ trợ họ trong các bước tiếp theo của quy trình bán hàng. Các nhiệm vụ khác liên quan đến chăm sóc và tư vấn khách hàng theo yêu cầu.', 'Giọng nói nhẹ nhàng, dễ nghe, truyền cảm, phát âm rõ ràng. Kỹ năng giao tiếp và lắng nghe tốt, có sự đồng cảm và kiên nhẫn, xử lí tình huống nhạy bén. Thái độ tích cực, thân thiện, chuyên nghiệp, luôn đặt khách hàng lên hàng đầu. Khả năng thích ứng trong môi trường startup trẻ trung, nhịp độ nhanh. Thành thạo sử dụng máy tính và các ứng dụng văn phòng. Ưu tiên những người có kinh nghiệm sử dụng CRM. Khả năng quản lý thời gian tốt. Có máy tính xách tay cá nhân để làm việc. Nghỉ báo trước tối thiểu 30 ngày.
Kỹ năng chuyên môn: [''Sử dụng máy tính'', ''Sử dụng các ứng dụng văn phòng'', ''Kinh nghiệm sử dụng CRM'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Kỹ năng lắng nghe'', ''Thái độ tích cực'', ''Thân thiện'', ''Chuyên nghiệp'', ''Khả năng thích ứng'', ''Quản lý thời gian'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '2.0 - 4.0 triệu', '3-4 ca/tuần, Ca sáng: 8h - 14h; Ca chiều: 14h - 20h', '[''Thưởng hiệu quả làm việc'', ''Team building'', ''Cước điện thoại'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1030, 8, 4, 'Nhân Viên Hỗ Trợ Livestream', 'Hỗ trợ host trong các buổi livestream trên TikTok/ Facebook/ Shopee/.... Chuẩn bị sản phẩm, đạo cụ, kịch bản, và các công cụ hỗ trợ livestream. Set-up deal, ghim deal xuyên suốt phiên live theo kịch bản. Hỗ trợ tương tác với khách hàng trong livestream: trả lời bình luận, ghi nhận đơn hàng. Kiểm soát chất lượng hình ảnh, âm thanh, ánh sáng trong quá trình livestream.', 'Nam/nữ từ 18 - 30 tuổi, ưu tiên có kinh nghiệm làm trợ livestream, bán hàng online. Nhanh nhẹn, hoạt bát, hoạt ngôn, có tinh thần trách nhiệm. Có kỹ năng giao tiếp, xử lý tình huống linh hoạt. Biết sử dụng các công cụ hỗ trợ livestream là một lợi thế. Sẵn sàng làm việc vào các khung giờ tối hoặc cuối tuần theo lịch livestream.
Kỹ năng chuyên môn: [''Sử dụng các công cụ hỗ trợ livestream'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Hoạt bát'', ''Hoạt ngôn'', ''Có tinh thần trách nhiệm'', ''Kỹ năng giao tiếp'', ''Xử lý tình huống linh hoạt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Theo lịch livestream', '[''Mức lương hấp dẫn 40k/1h'', ''Được tham gia các khóa đào tạo về chuyên môn, phát triển bản thân'', ''Làm việc tại studio chuyên nghiệp của công ty với đầy đủ thiết bị hỗ trợ live'', ''Nhiều cơ hội thăng tiến cho nhân sự tâm huyết, gắn bó lâu dài'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1031, 9, 4, 'Thực Tập Sinh Triển Khai Phần Mềm', '- Tiếp nhận, xử lý và chuyển tiếp các yêu cầu của khách hàng một cách nhanh chóng, chính xác. - Lập kế hoạch xử lý các yêu cầu của khách hàng. - Cung cấp đầy đủ thông tin tình trạng dịch vụ mà khách hàng yêu cầu. - Giải đáp thắc mắc của khách hàng với thái độ nhã nhặn, lịch sự và chuyên nghiệp. - Thông báo cho khách hàng trạng thái và tiến độ giải quyết yêu cầu.', '- Sinh viên năm cuối hoặc tốt nghiệp chuyên ngành công nghệ thông tin - Có hiểu biết về cơ sở dữ liệu quan hệ, có kinh nghiệm làm việc với hệ quản trị CSDL Acess và MS SQL Server - Có kinh nghiệm chăm sóc khách hàng là một lợi thế. - Am hiểu nghiệp vụ chăm sóc khách hàng. - Kỹ năng giao tiếp tốt. - Tinh thần trách nhiệm. - Có kỹ năng viết tài liệu
Kỹ năng chuyên môn: [''Cơ sở dữ liệu quan hệ'', ''Hệ quản trị CSDL Acess'', ''MS SQL Server'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Tinh thần trách nhiệm'', ''Kỹ năng viết tài liệu'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Trợ cấp thực tập sau 1 tháng học việc'', ''Gửi xe miễn phí'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1032, 10, 4, 'Thực Tập Sinh Glam Beautique (Khối Vận Hành)', 'Công việc văn phòng (in ấn, làm file báo giá, đặt văn phòng phẩm cho cửa hàng). Hỗ trợ vận hành làm hệ thống các Payment Request cho thầu và lên form yêu cầu đặt hàng. Làm báo cáo theo dõi sale hàng tuần của các cửa hàng. Các nhiệm vụ hoặc trách nhiệm khác theo sự phân công của Quản lý.', 'Sinh viên năm 3 hoặc năm 4 chuyên ngành Marketing/Ecommerce/PR hoặc các ngành liên quan. Ưu tiên các bạn thực tập Full-time và tối thiểu 3 tháng. Sử dụng tin học văn phòng cơ bản: Word, Excel, PowerPoint, Outlook và Internet. Kỹ năng giao tiếp tốt. Cẩn thận chi tiết và có khả năng xử lý nhiều nhiệm vụ cùng một lúc. Đam mê trong lĩnh vực Retail business & Operational Excellence.
Kỹ năng chuyên môn: [''Sử dụng tin học văn phòng cơ bản: Word, Excel, PowerPoint, Outlook và Internet'']
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Cẩn thận chi tiết'', ''Có khả năng xử lý nhiều nhiệm vụ cùng một lúc'', ''Đam mê trong lĩnh vực Retail business & Operational Excellence'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Hỗ trợ cấp giấy xác nhận thực tập + Đóng mộc theo mẫu của công ty'', ''Hỗ trợ bữa ăn trưa tại canteen'', ''Hỗ trợ laptop trong quá trình làm việc'', ''Được trải nghiệm, học tập và làm việc tại tập đoàn đa quốc gia'', ''Hỗ trợ sắp xếp thời gian học & làm việc phù hợp'', ''Hỗ trợ xe đưa đón cho các bạn ở xa (nếu bạn đang cư trú ở Q.7, Q.Bình Thạnh, TP.Thủ Đức)'', ''Không hỗ trợ lương'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1033, 2, 4, 'Nhân Viên Dịch Vụ Khách Hàng', '- Tiếp nhận và xử lý thông tin khách hàng qua hệ thống Call Center, Chatbot, Email,.. nhằm đảm bảo việc tiếp nhận và xử lý thông tin khách hàng theo quy định và hoàn thành các công việc được giao. - Phối hợp với các bộ phận liên quan, giải đáp các thắc mắc của khách hàng về chương trình khuyến mãi, các chương trình CSKH. - Tổng hợp các báo cáo theo quy định - Thực hiện các công việc khác theo sự phân công của cấp Quản lý', '- Tốt nghiệp cao đẳng, đại học hoặc đang là sinh viên năm 4 có thể sắp xếp đi làm full-time - Giao tiếp tốt, có khả năng xử lý tình huống linh hoạt - Ưu tiên ứng viên có kinh nghiệm về CSKH, Call center, Telesales,...
Kỹ năng mềm: [''Giao tiếp tốt'', ''Có khả năng xử lý tình huống linh hoạt'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 8000000.00, '7.0 - 8.0 triệu', 'Từ 8h00 tới 18h00 các ngày từ thứ 2 tới thứ 6, Trực từ xa từ 18h00 tới 21h30 các ngày trong tuần thứ 2 tới thứ 6, từ 8h00 tới 21h30 các ngày thứ 7, Chủ nhật và các ngày lễ, tết.', '[''Tham gia BH đầy đủ ngay từ tháng đầu tiên'', ''Được đào tạo bài bản, chuyên nghiệp'', ''Có cơ hội trở thành nhân viên chính thức tại TH'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1034, 3, 4, 'Nhân Viên Trải Nghiệm Khách Hàng', '● Hỗ trợ quản lý bộ phận lớp học: Sắp xếp, tổ chức, vận hành lớp học trong quy trình. ● Hỗ trợ tiếp nhận vấn đề học viên, giải quyết vấn đề liên quan đến bộ phận lớp học. ● Hỗ trợ phối hợp với các phòng ban khác trong việc giải quyết vấn đề Học viên.', '● Sinh viên đang học năm 2 hoặc năm 3 đại học ● Linh hoạt với giờ làm việc, có khả năng thích ứng với các lịch trình khác nhau. ● Kỹ năng giao tiếp bằng lời nói và viết tốt; tính cách tự tin và hòa đồng. ● Năng động, chủ động và có khả năng làm việc độc lập với tính trách nhiệm cao. ● Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực dịch vụ khách hàng hoặc liên quan ● Có laptop cá nhân
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp bằng lời nói và viết'']
Kỹ năng mềm: [''Tính cách tự tin'', ''Hòa đồng'', ''Năng động'', ''Chủ động'', ''Có khả năng làm việc độc lập'', ''Tính trách nhiệm cao'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:30 đến 18:45)', '[''Mức lương 24.000 VNĐ/giờ'', ''Cơ hội trải nghiệm thực tế trong hoạt động trải nghiệm khách hàng'', ''Phát triển kỹ năng giao tiếp, giải quyết vấn đề và làm việc nhóm'', ''Thời gian làm việc linh hoạt'', ''Môi trường làm việc thân thiện'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1035, 7, 4, 'Nhân Viên ECom Operations - CSKH (Part-Time)', 'JOB DESCRIPTIONS: - Tiếp nhận và xử lý đơn hàng online trên đa kênh Ecom (Order) - Xử lý packing, đóng gói và Giao đơn hàng đi cho đơn vị ship (Dispatch) - Theo dõi và tracking giao hàng và tình trạng đơn hàng (Online Tracking) - Tham gia quản lý kho; giao nhận, đổi trả hàng hoá và sản phẩm (Warehousing) - Quản lý và đặt mua vật tư, công cụ, dụng cụ kho và công việc phát sinh - Hỗ trợ các công việc vận hành, Dịch vụ khách hàng (CS) phát sinh thực tế', 'REQUIREMENTS: - Nhanh nhẹn, tháo vát - Cẩn thận và chú ý chi tiết - Chăm chỉ, trung thực và có trách nhiệm Ưu tiên ứng viên ở khu vực GẦN 58 Tố Hữu - Trung Văn, HN Ưu tiên ứng viên có thể làm theo ca cố định ca SÁNG/CHIỀU Ưu tiên ứng viên đã từng làm vận hành, CSKH, bán hàng online, FnB Nhà hàng... (Yêu cầu tăng ca vào những giai đoạn, thời điểm có nhiều đơn hàng)
Kỹ năng mềm: [''Nhanh nhẹn'', ''Tháo vát'', ''Cẩn thận'', ''Chú ý chi tiết'', ''Chăm chỉ'', ''Trung thực'', ''Có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:45), Thứ 7 (từ 08:30 đến 12:30)', '[''Lương khởi điểm từ 23k/giờ + Phụ cấp + Thưởng (nếu có)'', ''Xét tăng lương trong từ 3 - 6 tháng'', ''Phụ cấp công việc, chi phí văn phòng và các chi phí khác'', ''Tham gia Team Building, Party, Nghỉ mát và Events của Công ty'', ''Chế độ phúc lợi, phụ cấp khác theo quy định và chính sách Công ty'', ''Lộ trình tuyển dụng nhân viên Fulltime/Chính thức rõ ràng, nhiều cơ hội'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1036, 8, 4, 'Thực Tập Sinh Vận Hành Sàn Thương Mại Điện Tử', 'Hỗ trợ vận hành gian hàng Shopee, Tiktok: Đăng tải sản phẩm, cập nhật nội dung mô tả, hình ảnh, thông tin và giá của các sản phẩm. Theo dõi đơn hàng, hỗ trợ xử lý phát sinh, xử lý đánh giá sản phẩm và chăm sóc khách hàng qua các kênh với khách hàng. Triển khai, lên chương trình khuyến mãi, voucher và các hoạt động khuyến mãi khác nhằm tăng trưởng doanh thu trên kênh Shopee và tiktok. Thực hiện các yêu cầu liên quan tới vận hành sàn khác theo yêu cầu của cấp trên. Hỗ trợ tìm kiếm & làm việc với KOL/KOC trên TikTok, Shopee: Tìm kiếm KOL/KOC/UGC tiềm năng phù hợp với yêu cầu và sản phẩm của công ty. Liên hệ và booking các KOL/KOC/UGC review sản phẩm của công ty trên tiktok và shopee. Soạn brief, hỗ trợ lên kế hoạch nội dung cho video review hoặc livestream sản phẩm. Theo dõi tiến độ bài đăng và tổng hợp kết quả chiến dịch.', 'KHÔNG YÊU CẦU KINH NGHIỆM. Là sinh viên năm cuối hoặc mới tốt nghiệp ngành Marketing, TMĐT, Truyền thông, Kinh doanh... Yêu thích lĩnh vực vận hành Sàn Thương mại Điện Tử (Shopee, Tiktokshop, Lazada) hoặc quan tâm đến booking KOL/KOC. Biết dùng Google Sheet/Excel cơ bản. Siêng năng, chủ động, không ngại việc, sẵn sàng học cái mới mỗi ngày. Có laptop cá nhân để làm việc. Biết thiết kế trên Canva, Photoshop, AI là 1 lợi thế (cơ bản).
Kỹ năng chuyên môn: [''Google Sheet'', ''Excel'', ''Canva'', ''Photoshop'', ''AI'']
Kỹ năng mềm: [''Siêng năng'', ''Chủ động'', ''Không ngại việc'', ''Sẵn sàng học cái mới'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 7 (8h30-17h30)', '[''Cơ hội lên nhân viên chính thức sau khi quá trình thực tập hoàn tất'', ''Được training trực tiếp về TMĐT'', ''Môi trường thoải mái, trẻ trung'', ''Cơ hội học hỏi ứng dụng AI vào công việc'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1037, 9, 4, 'Thương mại điện tử thực tập', 'Tại V-Odyssey, chúng tôi tạo ra những hành trình độc quyền, chạm cao cho những cá nhân sành điệu nhất Việt Nam. Là một phần trong việc mở rộng của chúng tôi vào các nền tảng kỹ thuật số, chúng tôi đang tìm kiếm một thực tập sinh thương mại điện tử để hỗ trợ các sáng kiến ​​bán lẻ trực tuyến của chúng tôi với độ chính xác và phong cách.', 'Key Responsibilities: Manage Online Store Operations Oversee daily tasks on Shopify: product listings, pricing, visuals, promotions, and campaign setup. Customer & Partner Communication Communicate with U.K.-based customers and partners in English; join meetings with Manager and external teams. Inventory & Order Tracking Monitor inventory and top-selling items; provide insights to production and logistics teams. Marketing & Campaign Execution Assist in executing email marketing flows (ActiveCampaign), seasonal campaigns, and upsell/cross-sell initiatives. Data Analysis & Reporting Use Shopify Analytics to track performance (GMV, ROAS, conversion rate...) and suggest improvements.
Kỹ năng chuyên môn: [''Familiarity with digital marketing and e-commerce platforms'', ''Shopify'', ''ActiveCampaign'']
Kỹ năng mềm: [''Strong communication'', ''Analytical thinking'', ''Growth mindset'', ''Reliable'', ''Detail-oriented'', ''Committed to deadlines'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Internship certificate recognized both in Vietnam and the UK'', ''Direct pathway to enter the luxury travel & education industry in both markets'', ''Financial support and on-the-job training throughout the internship'', ''Continuous mentorship in a youthful, dynamic, and professional environment'', ''Opportunity to transition into a full-time role'', ''Potential recommendation and certification from our UK-based company for top performers'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1038, 10, 4, 'Nhân Viên Trực Page Part-Time', 'Trả lời Fanpage tin học và ngoại ngữ theo hướng dẫn. Tư vấn, hỗ trợ, chăm sóc từng học viên đang học tập tại các trung tâm về tin học và ngoại ngữ trực thuộc hệ thống của công ty. Ghi nhận ý kiến từ học viên để nghiên cứu, đưa ra các giải pháp để cải thiện chất lượng dịch vụ; Các công việc khác theo sắp xếp của quản lý.', 'Ưu tiên sinh viên đang theo học tại trường Đại học Kinh tế TP. HCM (UEH), Trường Đại học Ngoại ngữ – Tin học Thành phố Hồ Chí Minh (HUFLIT). Có khả năng giao tiếp tốt, sáng tạo, nhiệt tình. Có chứng chỉ IELTS/TOEIC hoặc MOS/IC3 là một lợi thế.
Kỹ năng chuyên môn: [''Có laptop cá nhân'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Sáng tạo'', ''Nhiệt tình'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', '4 ca/tuần: Ca sáng: 8h00 - 12h00, Ca chiều: 13h00 - 17h00, Ca tối: 17h30-21h30', '[''Thử việc 1 tháng hưởng 85% lương'', ''Thưởng lễ tết và các dịp trong năm'', ''Cơ hội tăng lương, thăng tiến theo năng lực và thời gian gắn bó'', ''Môi trường làm việc trẻ, năng động'', ''Tham gia các chương trình, sự kiện thường niên của Công ty'', ''Ưu đãi dành riêng cho nhân viên'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1039, 2, 4, 'IELTS Invigilator', 'IDP IELTS Inturilators là để đảm bảo hành vi kiểm tra công bằng và đúng đắn theo các quy tắc và quy định của IELTS, và trong một môi trường cho phép người thực hiện thử nghiệm thực hiện tốt nhất. Chủ sở hữu vị trí chịu trách nhiệm thúc đẩy hình ảnh tích cực của IDP bằng cách cung cấp một tiêu chuẩn chăm sóc khách hàng cao trong ngày thử nghiệm cũng như hỗ trợ kỹ thuật cơ bản và hành chính để kiểm tra trong khi đảm bảo tuân thủ các hướng dẫn đã thiết lập về hoạt động kiểm tra.', 'Availability: Minimum of 2 sessions during weekends
Kỹ năng mềm: [''Punctuality and a strong sense of time discipline'', ''Customer service and people skills'', ''Good attention to detail'']', 'PART_TIME', 'ONSITE', 'hưng yên', 'Hưng Yên', 'MONTHLY', 6000000.00, '1.0 - 6.0 triệu', 'Thời gian linh hoạt, từ Thứ 2 đến Chủ nhật', '[''Competitive Pay – Earn a fair and attractive remuneration per session.'', ''Flexible working hours'', ''Professional Development – Gain valuable experience working in an internationally recognized testing environment.'', ''Enhance Your CV – Build your skills in test administration, communication, and organizational management.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1040, 3, 4, 'Management Trainee', 'Vị trí: Management Trainee – Bộ phận Thị trường (Xuất khẩu B2B) Thời gian: Tối thiểu 6 tháng Thu nhập: 2.500.000 – 3.500.000 VND/tháng Báo cáo & hướng dẫn: Sales lead, Admin Salesforce và anh chị chính thức trong team Phòng ban: Bộ phận Thị trường (Sales – Marketing – Service) Bạn sẽ học được gì khi tham gia cùng A Plus? - Hiểu cách một doanh nghiệp xuất khẩu quốc tế vận hành chuỗi khách hàng B2B toàn cầu. - Làm việc trong môi trường có hệ thống số hóa hiện đại: Salesforce, Airtable, Base.vn, Agentforce AI. - Được giao nhiệm vụ cụ thể để rèn kỹ năng làm việc thật – có trách nhiệm – không phải “thực tập cho có”. - Có cơ hội phát triển thành nhân viên chính thức nếu thể hiện tốt trong 6–9 tháng.', 'Bạn phù hợp nếu: - Là sinh viên năm cuối hoặc mới tốt nghiệp các ngành: Ngoại thương, Kinh doanh quốc tế, Logistics, Kinh tế, Quản trị kinh doanh. - Ham học, thích làm việc có hệ thống, có tinh thần hợp tác và chăm chỉ. - Biết dùng Google Workspace (Docs, Sheets, Calendar…), ưu tiên có trải nghiệm với bất kỳ nền tảng số nào. - Có định hướng làm việc trong môi trường chuyên nghiệp, quốc tế hóa và yêu thích học cái mới mỗi ngày.
Kỹ năng chuyên môn: [''Google Workspace (Docs, Sheets, Calendar...)'']
Kỹ năng mềm: [''Ham học'', ''Thích làm việc có hệ thống'', ''Có tinh thần hợp tác'', ''Chăm chỉ'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.5 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Làm việc thật – học từ việc thật'', ''Giao tiếp cùng team chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1041, 7, 4, 'CTV Chăm Sóc Khách Hàng', 'Giới thiệu sản phẩm đến khách hàng mới, chăm sóc khách hàng hiện có thông qua các kênh website, fanpage, zalo,.... Nhận và theo dõi đơn hàng của khách; phối hợp để đảm bảo giao hàng đúng hạn, đúng yêu cầu. Hỗ trợ giải quyết các vấn đề liên quan đến đơn hàng, chất lượng sản phẩm, khiếu nại… Ghi nhận ý kiến khách hàng.', 'Sắp xếp thời gian lên công ty tối thiểu 1 lần/tuần để báo cáo và trao đổi công việc với Line Manager (Nếu được yêu cầu). Học và làm việc trong ngành dược là 1 lợi thế. Kỹ năng giao tiếp, chăm sóc khách hàng tốt, thái độ tích cực. Làm được các ca tối và cuối tuần. Thời gian làm việc: Thứ hai đến thứ bảy (theo lịch phân bổ từ Line Manager). Thành thạo tin học văn phòng.
Kỹ năng chuyên môn: [''Thành thạo tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Chăm sóc khách hàng'', ''Thái độ tích cực'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 20:00 đến 22:00)', '[''Môi trường làm việc năng động'', ''Cơ hội thăng tiến'', ''Học hỏi và phát triển'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1042, 8, 4, 'Thực Tập Sinh Phát Triển Thẻ', 'Tiếp xúc, tìm hiểu thông tin đối tác, khảo sát, đánh giá, đề xuất liên kết. Thực hiện thủ tục thương thảo, ký kết liên kết về sản phẩm/dịch vụ. Phân loại các Đối tác theo thứ tự ưu tiên chăm sóc. Giao lưu, thăm hỏi, tặng quà, tham gia các sự kiện của ĐTLK tổ chức nhằm duy trì mối quan hệ. Phối hợp với Chi nhánh/Phòng Giao dịch ra thị trường tiếp cận Đối Tác Liên Kết trong các đợt đầu triển khai bán thẻ. Các công việc khác do Ban Giám đốc Trung tâm thẻ hoặc Trưởng phòng giao.', '- Sinh viên chuyên ngành Quản trị kinh doanh, Tài chính - Ngân hàng, Kinh tế năm thứ 3 hoặc năm thứ 4. - Kỹ năng thu thập thông tin và nắm bắt xu hướng thị trường. - Đã từng tham gia các hoạt động đoàn hội của trường. - Giọng nói dễ nghe, không nói ngọng, nói lặp hay nói tiếng địa phương. - Cẩn thận, nhiệt tình, chăm chỉ, có trách nhiệm với công việc, chịu được áp lực và không ngại thử thách bản thân - Tố chất & sở thích công việc: * Tính tuân thủ cao. * Chính trực, đáng tin cậy. * Chịu áp lực công việc. * Nỗ lực hướng tới kết quả.
Kỹ năng chuyên môn: [''Kỹ năng thu thập thông tin'', ''Nắm bắt xu hướng thị trường'']
Kỹ năng mềm: [''Cẩn thận'', ''Nhiệt tình'', ''Chăm chỉ'', ''Có trách nhiệm với công việc'', ''Chịu được áp lực'', ''Không ngại thử thách bản thân'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Được làm việc tại Ngân hàng có môi trường làm việc tốt nhất Châu Á 8 năm liền'', ''Được đào tạo các kiến thức, kỹ năng trong lĩnh vực Ngân hàng'', ''Được trải nghiệm và chia sẻ các kinh nghiệm làm việc thực tế'', ''Hỗ trợ phụ cấp theo quy định của Ngân hàng'', ''Hỗ trợ báo cáo thực tập theo quy định của nhà trường'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1043, 9, 4, 'Nhân Viên Chăm Sóc Khách Hàng Part-Time', '● Tiếp nhận và xử lý các yêu cầu, thắc mắc từ khách hàng qua điện thoại, zalo, fanpage facebook ● Hỗ trợ khách hàng sau khi mua sản phẩm thành công: duyệt vào nhóm học, cấp mã khoá học, v.v... ● Không phải bán hàng, không áp doanh số ● Một số nhiệm vụ khác được giao từ cấp trên', '● Kinh Nghiệm: Ưu tiên ứng viên đã có kinh nghiệm làm trong lĩnh vực sale, tư vấn, bán hàng, có kiến thức, hiểu biết về các kỳ thi THPT QG Không có kinh nghiệm sẽ được đào tạo ● Tinh thần thái độ tốt, chăm chỉ, nhiệt huyết, quyết liệt.
Kỹ năng mềm: [''Tinh thần thái độ tốt'', ''Chăm chỉ'', ''Nhiệt huyết'', ''Quyết liệt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.0 - 4.0 triệu', 'Làm việc theo ca: 8h - 12h, 13h30 - 17h30, 17h30 - 21h30', '[''Thu nhập: thử việc 24k/h, chính thức 26k/1h + phụ cấp 300k'', ''Được trang bị thiết bị làm việc hiện đại'', ''Lương tăng theo năng lực và hiệu suất làm việc'', ''Du lịch hàng năm cùng công ty 1 năm 2 lần'', ''Cơ hội thăng tiến lên vị trí cao hơn trong công ty'', ''Môi trường trẻ trung, chuyên nghiệp, thân thiện, cầu tiến'', ''Được đào tạo bài bản và nâng cấp thường xuyên về nghiệp vụ, kiến thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1044, 10, 4, 'Thực Tập Trực Nhóm Và Page Facebook', 'Công ty có 720 Nhóm Facebook, mỗi ngày trung bình khách hàng liên hệ qua các Nhóm này khoảng 100 - 200 khách hàng. Ứng viên cần trả lời câu hỏi, giải đáp thắc mắc của khách hàng. Theo dõi và xử lý các bình luận, tin nhắn, phản hồi của khách hàng trên các nền tảng Nhóm. Cập nhật thông tin sản phẩm, dịch vụ, chương trình khuyến mãi lên các kênh Nhóm. Tương tác với khách hàng, xây dựng mối quan hệ tốt đẹp và tạo ấn tượng tích cực về thương hiệu. Thực hiện các báo cáo về hoạt động trực Nhóm, số lượng khách hàng tương tác, phản hồi của khách hàng. Đề xuất các ý tưởng, chiến lược để cải thiện chất lượng dịch vụ chăm sóc khách hàng trên Nhóm. Hỗ trợ bộ phận marketing trong việc lên kế hoạch và thực hiện các chiến dịch quảng cáo trên Nhóm. Triển khai tìm kiếm và sàng lọc thông tin trong kho hồ sơ theo yêu cầu của khách hàng. Cập nhật tình trạng hồ sơ khách hàng theo thời gian. Liên hệ với các khách hàng để giải đáp, giới thiệu về dịch vụ. Hỗ trợ khách hàng ký hợp đồng. Liên hệ với các khách hàng đăng ký qua Nhóm đã được marketing chuyển thành dạng data. Thời gian thực tập: 6 tháng. Công ty chỉ tuyển ứng viên đi thực tập lấy kinh nghiệm, để được đào tạo chuyên ngành và ở lại làm việc lâu dài cho công ty.', 'Sinh viên năm 1, 2, 3, và 4, Không yêu cầu kinh nghiệm, được đào tạo bài bản. Có khả năng sử dụng thành thạo Facebook. Khả năng giao tiếp tốt, giọng nói dễ nghe, thái độ thân thiện, lịch sự. Khả năng xử lý tình huống tốt, giải quyết vấn đề nhanh chóng và hiệu quả. Trung thực, cẩn thận, chịu được áp lực công việc. Có khả năng làm việc độc lập và làm việc nhóm. Khả năng viết tốt, sử dụng chính tả và ngữ pháp chuẩn xác. Có laptop cá nhân. Thành thạo tin học văn phòng (Word, Excel, Powerpoint).
Kỹ năng chuyên môn: [''Sử dụng thành thạo Facebook'', ''Tin học văn phòng (Word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Giọng nói dễ nghe'', ''Thái độ thân thiện, lịch sự'', ''Khả năng xử lý tình huống tốt'', ''Trung thực'', ''Cẩn thận'', ''Chịu được áp lực công việc'', ''Khả năng làm việc độc lập và làm việc nhóm'', ''Khả năng viết tốt'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Part Time Trong giờ hành chính: 6 ca/ Tuần, Trong đó có 02 ca vào ''các buổi tối hoặc chiều T7 hoặc CN'', 4 ca còn lại tùy chọn', '[''Cấp chứng chỉ thực tập'', ''Môi trường làm việc năng động, trẻ trung'', ''Được tăng lương và đề bạt làm nhân viên chính thức nếu có kết quả thực tập tốt'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1045, 2, 4, 'Nhân Viên Trực Page', 'Trả lời tin nhắn, bình luận của khách hàng trên fanpage, tiktok, zalo OA. Tư vấn, chốt đơn hàng và chuyển thông tin cho bộ phận xử lý đơn. Phân loại Data khách hàng, sau đó đưa nhân viên kinh doanh xử lý. Quản lý thời gian một cách hiệu quả để đảm bảo rằng không có tin nhắn nào bị bỏ sót. Xử lý phản hồi khách hàng, bao gồm cả phản hồi tiêu cực, một cách chuyên nghiệp và tôn trọng. Theo dõi tương tác, lập báo cáo định kỳ về hiệu quả fanpage.', 'Làm việc theo ca từ 07h00 - 16h00 và 15h00 - 21h30, từ thứ 2 - CN, nghỉ 1 ngày trong tuần.
Kỹ năng mềm: [''Khả năng thuyết phục'', ''Giao tiếp'', ''Xử lý vấn đề'', ''Chịu khó'', ''Trách nhiệm cao'', ''Trung thực'', ''Khả năng làm việc đội nhóm'', ''Sáng tạo'', ''Ham học hỏi'', ''Cẩn thận'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 7000000.00, '6.0 - 7.5 triệu', 'Ca 1: 7h - 16h (8 tiếng), Ca 2: 15h - 21h30 (6 tiếng)', '[''Chế độ bảo hiểm: Hưởng chế độ BHXH, BHYT, BHTN theo luật lao động'', ''Ngày lễ/tết theo quy định của nhà nước'', ''Thưởng vào các ngày Lễ trong năm'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1046, 3, 4, 'Nhân Viên Quản Lý Lớp Học', 'Quản lý các lớp học phát sinh trong ca học và gửi nhận xét của giáo viên cuối buổi học cho Phụ huynh. Tiếp nhận và xử lý các vấn đề phát sinh hàng ngày của học viên trong quá trình học tập tại ESO như: check lớp học để đảm bảo đúng giờ giáo viên và học viên tham gia lớp học. Học viên báo nghỉ, đổi giờ học, góp ý về phương pháp dạy của giáo viên, phát hiện các trục trặc trong lớp học như đường truyền, skype...hay các vấn đề khác nữa để kịp thời xử lý. Hỗ trợ CN để giải quyết các vấn đề tồn đọng phát sinh vào buổi tối. Hỗ trợ lớp thử và gửi kết quả lớp thử cho Kinh doanh ngay sau khi lớp thử kết thúc. Công việc khác do trưởng phòng phân công.', 'Chấp nhận ứng viên là sinh viên, không yêu cầu kinh nghiệm; Làm việc cố định ca: 18:00-22:00; Kỹ năng giao tiếp ổn; Khả năng nắm bắt và xử lý thông tin tốt; Thành thạo tin học văn phòng; Tiếng anh giao tiếp cơ bản; Có laptop cá nhân; Thời gian làm việc: Ca tối: 18h00 – 22h00, từ thứ 2 – thứ 7, nghỉ CN và các ngày lễ theo quy định nhà nước.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Khả năng nắm bắt và xử lý thông tin'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', '18:00-22:00, từ thứ 2 – thứ 7, nghỉ CN và các ngày lễ theo quy định nhà nước', '[''Lương cứng: 3.000.000 VNĐ + KPI + Phụ cấp (hỗ trợ laptop, gửi xe)'', ''Môi trường làm việc văn minh, trẻ trung'', ''Được đào tạo các kỹ năng cần thiết'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1047, 7, 4, 'Nhân Viên Trực Page', 'Tư vấn thông tin về gói dịch vụ về các khoá học nhiếp ảnh cho khách hàng. Chốt đơn hàng với khách và hỗ trợ giải đáp các thắc mắc trong quá trình sử dụng dịch vụ. Phối hợp với giảng viên phân chia lớp học, tiếp đón học viên đến trực tiếp. Chăm sóc khách hàng trước, trong và sau khi ký kết hợp đồng.', 'Ưu tiên sinh năm từ 2005 trở lên. Có kinh nghiệm bán hàng qua Pancake. Có laptop cá nhân. Yêu thích công việc kinh doanh, đam mê kiếm tiền. Chăm chỉ, nhiệt tình, ham học hỏi.
Kỹ năng chuyên môn: [''Kỹ năng bán hàng'', ''Tư vấn'', ''Chăm Sóc Khách Hàng'']
Kỹ năng mềm: [''Chăm chỉ'', ''Nhiệt tình'', ''Ham học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 12:00), Thứ 2 - Thứ 7 (từ 13:30 đến 18:00)', '[''Lương Parttime: 2.000.000 + % Doanh Thu + Phụ cấp + Thưởng (Thu nhập 5 - 7tr/tháng)'', ''Có sẵn data, khách hàng đa dạng, dễ tư vấn'', ''Cơ hội nắm giữ vị trí quan trọng, làm chủ sản phẩm, trở thành Key Member, sát cánh cùng đội ngũ Founding Team của Aloha'', ''Môi trường làm việc năng động, trẻ trung.'', ''Có hỗ trợ dấu thực tập'', ''Team building'', ''Du lịch hàng năm'', ''Thưởng hiệu quả làm việc'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1048, 8, 4, 'Nhân Viên Telesale Tài Xế Shopeefood', 'Thực hiện gọi điện khảo sát nhu cầu đăng ký của ứng viên Tài xế cho ứng dụng ShopeeFood. Tư vấn công việc và hẹn ứng viên qua văn phòng hoàn tất thủ tục đăng ký. Thực hiện 1 số cuộc gọi khảo sát thông tin ứng viên theo yêu cầu. Làm việc từ Thứ 2-Thứ 6 (9:00-18:00) tại Tầng 3, tòa nhà 101 Láng Hạ, Đống Đa, Hà Nội.', 'Khả năng giao tiếp tốt, nhanh nhẹn. Chăm chỉ, sẵn sàng học hỏi. Có kinh nghiệm gần nhất về Telesale hoặc Call khách hàng. Tốt nghiệp Trung cấp trở lên.
Kỹ năng chuyên môn: [''Kinh nghiệm Telesale hoặc Call khách hàng'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Nhanh nhẹn'', ''Chăm chỉ'', ''Sẵn sàng học hỏi'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 11000000.00, '8.0 - 11.0 triệu', 'Thứ 2 - Thứ 6 (9:00-18:00)', '[''Thu nhập lên đến 11.270.000 (đã bao gồm Lương + Thưởng chỉ tiêu hiệu suất công việc)'', ''Trang bị thiết bị làm việc (Máy tính + Headphone) được công ty cung cấp đầy đủ'', ''Việc làm thời vụ 6 tháng - Nếu làm tốt sẽ được gắn bó lâu dài'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1049, 9, 4, 'Hỗ Trợ CSKH App Du Lịch(Part Time) - Thực Tập Sinh', 'Hỗ trợ CSKH app du lịch: Hỗ trợ kênh chat, nhắn tin, gọi điện khi khách hàng có nhu cầu tư vấn, hủy, đổi thông tin. Nhân viên CSKH cung cấp đầy đủ thông tin, chính xác và giải đáp thắc mắc cho khách hàng về những mối quan tâm. Nâng cao trải nghiệm khách hàng đối với ứng dụng du lịch, đảm bảo sự hài lòng của khách hàng. Báo cáo công việc cho quản lý trực tiếp.', 'Tiếng Anh giao tiếp ở mức ổn, đủ để hỗ trợ khách hàng. Phỏng vấn bằng tiếng Anh. Tốt nghiệp THPT hoặc sinh viên đang đợi bằng, thực tập. Khả năng giao tiếp tốt, nhanh nhẹn giọng nói dễ nghe. Làm việc Part time, có thể làm việc tối thiểu 4 tiếng/ ngày.
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Nhanh nhẹn'', ''Giọng nói dễ nghe'']', 'PART_TIME', 'ONSITE', 'quận 12, hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Tối thiểu 4 tiếng/ ngày', '[''Tự do đăng ký lịch làm'', ''Hỗ trợ đóng dấu thực tập (nếu cần)'', ''Được đào tạo bài bản về sản phẩm, kỹ năng làm việc với khách hàng'', ''Làm việc trong môi trường quốc tế chuyên nghiệp'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1050, 10, 4, 'Cố vấn quan hệ khách hàng bán thời gian', 'Tham gia vào dự án bán lẻ đầy tham vọng của chúng tôi ra mắt tại Việt Nam. Chịu trách nhiệm trong quản lý quan hệ khách hàng. Hỗ trợ khách hàng về các đơn đặt hàng và sản phẩm trên kênh trực tuyến Decathlon (fanpage, trang web, email, đường dây nóng, thị trường). Làm việc với các bên thứ ba để hỗ trợ khách hàng (nhà mạng, câu lạc bộ thể thao, ...). Tạo trải nghiệm WOW WOW cho tất cả khách hàng của chúng tôi trên tất cả các kênh.', 'Be ready to work during the weekend (5 days per week) and take another day off instead. Be concrete and punctual, with an on-the-field, organized mindset. Dare to take risks, you play to win and you are able to take responsibility for your role. Have a high sense of customer service and are willing to try new, different ways of engaging and serving customers. Have a digital mindset with ease of working with data and you are process oriented. Be passionate about sports; regularly practice at least one sport. Good at communication, confident, and can speak English.
Kỹ năng chuyên môn: [''Kỹ năng giao tiếp'', ''Kỹ năng làm việc với dữ liệu'']
Kỹ năng mềm: [''Tính tổ chức'', ''Tính trách nhiệm'', ''Tính sáng tạo'', ''Tính cầu tiến'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', '5 ngày/tuần, có thể làm vào cuối tuần', '[''Bảo hiểm y tế cho bản thân và gia đình'', ''Thưởng hàng tháng dựa trên hiệu suất'', ''20 ngày nghỉ phép hàng năm'', ''Trợ cấp thể thao hàng tháng'', ''Đánh giá lương hàng năm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1051, 2, 4, 'Nhân Viên Chăm Sóc Khách Hàng Ca Tối 17h30-22h30', 'Tiếp nhận và xử lý các cuộc gọi, email, tin nhắn từ khách hàng, hướng dẫn khách hàng tại điểm bán hàng. Chào đón, tươi cười, niềm nở đón khách. Hỗ trợ khách hàng giải đáp thắc mắc về sản phẩm, dịch vụ của công ty. Ghi nhận thông tin khách hàng, cập nhật vào hệ thống quản lý khách hàng. Giải quyết các vấn đề, khiếu nại của khách hàng một cách nhanh chóng và hiệu quả. Đề xuất các giải pháp nhằm cải thiện chất lượng dịch vụ khách hàng. Thường xuyên cập nhật kiến thức về sản phẩm, dịch vụ và chính sách của công ty. Tham gia các hoạt động đào tạo, nâng cao nghiệp vụ chăm sóc khách hàng.', 'Tối thiểu 1 năm kinh nghiệm từng làm việc tại các nhà hàng, spa, thẩm mỹ hoặc có đam mê trong ngành dịch vụ. Kỹ năng giao tiếp, xử lý tình huống tốt, giọng nói dễ nghe. Khả năng làm việc độc lập và làm việc nhóm hiệu quả. Trung thực, nhiệt tình, có trách nhiệm trong công việc. Khả năng sử dụng máy tính thành thạo (Word, Excel). Sử dụng tốt tiếng Anh hoặc Hàn, ngôn ngữ thứ 3 là 1 lợi thế phát triển. Khả năng sử dụng phần mềm quản lý khách hàng (nếu có) là một lợi thế. Có khả năng chịu áp lực công việc cao. Tốt nghiệp THPT trở lên.
Kỹ năng chuyên môn: [''Sử dụng máy tính thành thạo (Word, Excel)'', ''Khả năng sử dụng phần mềm quản lý khách hàng (nếu có)'']
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Xử lý tình huống tốt'', ''Khả năng làm việc độc lập và làm việc nhóm hiệu quả'', ''Trung thực'', ''Nhiệt tình'', ''Có trách nhiệm trong công việc'', ''Khả năng chịu áp lực công việc cao'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 15000000.00, '10.0 - 15.0 triệu', '17h30 - 22h30', '[''Mức lương cạnh tranh, được thỏa thuận khi phỏng vấn'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Được đóng bảo hiểm theo quy định của pháp luật'', ''Có cơ hội thăng tiến trong công việc'', ''Được hưởng các chế độ phúc lợi khác theo quy định của công ty (nếu có)'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1052, 3, 4, 'Thực Tập Sinh Quản Trị Kinh Doanh', 'Quản trị: Hỗ trợ xây dựng hồ sơ năng lực (profile) cho nhân sự kinh doanh trong nội bộ công ty. Tìm kiếm, thu thập dữ liệu theo định hướng, hướng dẫn và phân công từ Quản lý. Cập nhật, ghi chú và báo cáo tiến độ công việc hàng ngày để theo dõi hiệu suất và đề xuất điều chỉnh khi cần thiết. Thực hiện các công việc khác theo phân công từ Trưởng bộ phận. Kinh doanh: Tương tác với khách hàng theo kịch bản có sẵn, sử dụng danh sách dữ liệu được cung cấp từ hệ thống.', 'Có sự yêu thích kinh doanh. Kỹ năng giao tiếp tốt, tư duy logic, tinh thần trách nhiệm cao. Có suy nghĩ tích cực, ham học hỏi, nhanh nhẹn, chủ động. Có laptop cá nhân.
Kỹ năng mềm: [''Kỹ năng giao tiếp tốt'', ''Tư duy logic'', ''Tinh thần trách nhiệm cao'', ''Suy nghĩ tích cực'', ''Ham học hỏi'', ''Nhanh nhẹn'', ''Chủ động'']', 'PART_TIME', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Được đào tạo 1:1 bởi Quản lý bộ phận giỏi'', ''Môi trường làm việc thân thiện, chuyên nghiệp'', ''Cơ hội trở thành nhân viên chính thức sau khi kết thúc kì thực tập'', ''Tham gia các buổi đào tạo, huấn luyện'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1053, 7, 4, 'Cộng Tác Viên Vận Hành Lớp Học (Làm Tại Văn Phòng)', 'Vận hành lớp học Toán - Tiếng Anh trực tuyến vào buổi tối tại văn phòng (Thứ 2 đến Thứ 7 hàng tuần). Tiếp nhận & xử lý các cuộc gọi từ Phụ huynh/Học sinh liên quan đến sự cố trong lớp học. Hỗ trợ Giáo viên/Giảng viên vào lớp học đúng giờ và ổn định. Xử lý các yêu cầu phát sinh từ Giáo viên & Học sinh trong thời gian lớp học diễn ra.', 'Có máy tính cá nhân và làm việc tại văn phòng. Giao tiếp tốt, nhanh nhẹn, chăm chỉ và có trách nhiệm. Ưu tiên ứng viên đã có kinh nghiệm trong: Vận hành lớp học online và Chăm sóc khách hàng.
Kỹ năng mềm: [''Giao tiếp tốt'', ''Nhanh nhẹn'', ''Chăm chỉ'', ''Có trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '1.0 - 3.5 triệu', 'Thứ 2 - Thứ 7 (từ 18:00 đến 22:00)', '[''Thử việc nhận 100% lương'', ''Môi trường trẻ trung, thân thiện, cơ hội học hỏi cao'', ''Được tiếp cận với mô hình giáo dục công nghệ hiện đại'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1054, 8, 4, 'Nhân Viên Chăm Sóc Khách Hàng', '• Trả lời tin nhắn của khách trên sàn thương mại điện tử (Tiktok, Shopee,...). • Nhập thông tin đơn hàng vào hệ thống. • Xử lí những đơn hàng có vấn đề. • Trực và chốt đơn trên các sàn thương mại điện tử.', 'Nam nữ từ 18-25 tuổi. • Nhanh nhẹn, trách nhiệm và chăm chỉ. • Có khả năng làm việc nhóm, kĩ năng giao tiếp khá. • Kĩ năng xử lý tình huống tốt, đáp ứng được nhu cầu công việc. • Tuân thủ đầy đủ các quy trình, quy định của công ty. • Có đam mê về Anime là một lợi thế.
Kỹ năng chuyên môn: [''Tin học văn phòng'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Trách nhiệm'', ''Chăm chỉ'', ''Kỹ năng giao tiếp'', ''Kỹ năng xử lý tình huống'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '5.0 triệu', 'Fulltime: 8h-18h; Parttime: ca sáng từ 8h-12h, ca chiều từ 14h-18h, ca tối từ 18h-22h', '[''Môi trường làm việc trẻ trung, năng động'', ''Hỗ trợ và đào tạo tối đa'', ''Đánh giá công việc mỗi 6 tháng để xét duyệt tăng lương'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1055, 9, 4, 'Hỗ trợ vận hành chiến dịch thực tập', 'Làm việc và trao đổi trực tiếp với các thương hiệu tham gia TAP (TikTok Affiliate Program) để nắm thông tin sản phẩm, ngân sách, chính sách và nhu cầu tuyển KOC. Phối hợp với Account/BD để tạo và cập nhật file onboarding (Google Sheet, Slide, Folder nội dung…) cho từng campaign. Đảm bảo toàn bộ tài liệu hỗ trợ brand (brief, nội dung sản phẩm, hướng dẫn KOC…) được chuẩn hoá và dễ tiếp cận. Thực hiện đăng nội dung tuyển dụng KOC (bài viết, ảnh, banner, minigame...) trên các kênh cộng đồng TAP (Facebook Group, Zalo OA, Instagram, Threads…). Đi bài truyền thông hàng tuần theo kế hoạch – ưu tiên các campaign hot, có ưu đãi cao hoặc sản phẩm trendy. Hỗ trợ tạo nội dung, viết caption ngắn gọn thu hút, có CTA rõ ràng cho các bài viết. Phối hợp với team tuyển KOC để tổng hợp thông tin ứng viên từ form đăng ký. Đăng banner chương trình trên các kênh truyền thông chính thức của Accesstrade nhằm thu hút thêm KOC mới cho campaign. Hỗ trợ trả lời comment/inbox từ KOC liên quan đến các chương trình hiện có. Hỗ trợ cập nhật danh sách KOC tham gia từng chiến dịch để thuận tiện tracking hiệu quả. Làm việc cùng các bạn trong team để đảm bảo KOC được cung cấp thông tin đầy đủ và hỗ trợ xử lý các vấn đề phát sinh (chậm nhận quà, thiếu thông tin brief…).', 'Sinh viên năm 3 hoặc năm cuối các ngành: Marketing, Kinh doanh, Truyền thông, Thương mại điện tử hoặc các ngành liên quan. Có định hướng phát triển trong lĩnh vực Digital Marketing, Influencer Marketing, hoặc E-commerce. Thành thạo Google Workspace (Docs, Sheets, Slides) – biết sử dụng các hàm cơ bản trong Google Sheet là một lợi thế. Có khả năng viết lách tốt, ưu tiên ứng viên có kinh nghiệm viết bài trên fanpage, group cộng đồng hoặc từng làm CTV content. Biết cách sử dụng các công cụ thiết kế cơ bản như Canva, Figma là điểm cộng. Cẩn thận, có tinh thần trách nhiệm trong công việc và chủ động cập nhật tiến độ với team. Kỹ năng giao tiếp tốt, biết cách xử lý tình huống khi làm việc với đối tác (brand) và KOC. Có khả năng làm việc nhóm cũng như làm việc độc lập dưới áp lực thời gian. Sẵn sàng học hỏi, chịu khó tìm hiểu về quy trình vận hành chiến dịch affiliate/influencer. Chủ động cập nhật xu hướng social media, đặc biệt là TikTok, để hỗ trợ truyền thông hiệu quả.
Kỹ năng chuyên môn: [''Google Workspace (Docs, Sheets, Slides)'', ''Canva'', ''Figma'']
Kỹ năng mềm: [''Kỹ năng viết lách'', ''Kỹ năng giao tiếp'', ''Làm việc nhóm'', ''Chủ động cập nhật tiến độ'']', 'INTERNSHIP', 'ONSITE', 'đống đa', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:30)', '[''Có cơ hội lên chính thức sau 3 tháng thực tập.'', ''Được đào tạo bài bản, thực chiến tại công ty hàng đầu về digital marketing.'', ''Văn hóa nội bộ hướng đến việc phát triển con người.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1056, 10, 4, 'Thực Tập Sinh Vận Hành Livestream', 'Triển khai các hoạt động trong trước Livestream: Phụ trách hoạt động setup live trên nền tảng Tiktok/Shopee/Lazada; Set up phòng Livestream, chuẩn bị đạo cụ, đồ dùng cần thiết cho phiên live. Triển khai các hoạt động trong phiên Livestream: Trợ lives cho host trong buổi live, theo dõi hiệu suất thực tế và thực hiện các phương án linh hoạt để tương tác với người xem; Trao đổi trực tiếp với nhãn hàng về chương trình bán hàng trong phiên live (voucher, quà tặng bổ sung v..v.)', 'Giọng nói rõ ràng, dễ nghe. Hoạt ngôn, có khả năng nói liên tục trong 2 tới 3 giờ của buổi live trực tiếp. Ưu tiên ứng viên đã có kinh nghiệm vận hành phiên live độc lập của cả nhãn hàng hoặc KOC. Ứng viên nam/nữ, sinh viên năm 3-4 trở lên (Fresher), không vướng lịch học.
Kỹ năng mềm: [''Làm việc nhóm'', ''Khả Năng Học Hỏi Nhanh'', ''Khả Năng Thích Ứng'', ''Cẩn Thận, Tỉ Mỉ'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Môi trường làm việc năng động, chuyên nghiệp'', ''Chính sách đào tạo'', ''Du lịch từ 2-3 lần/năm'', ''Cơ hội đào tạo chuyên nghiệp về công việc và kỹ năng'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1057, 2, 4, 'Nhân Viên Chăm Sóc Khách Hàng', 'Gọi điện, nhắn tin khách hàng thông qua hotline, Fanpage, Tiktok… Để lấy ý kiến khách trước, trong và sau khi lưu trú tại homestay nội thành của công ty. Tư vấn và chăm sóc các khách hàng đã từng lưu trú (có hoa hồng nếu chốt lại). Theo dõi và quản lý các yêu cầu, phản hồi của khách hàng. Giải quyết các khiếu nại của khách hàng một cách nhanh chóng và hiệu quả. Tham gia, hỗ trợ các hoạt động marketing. Báo cáo công việc định kỳ cho quản lý.', 'Không yêu cầu kinh nghiệm. Tốt nghiệp THPT trở lên. Có giọng nói dễ nghe, giao tiếp tốt, khả năng thuyết phục khách hàng. Trung thực, nhiệt tình, chịu khó, có trách nhiệm trong công việc. Khả năng xử lý tình huống tốt, giải quyết vấn đề hiệu quả. Thành thạo tin học văn phòng (Word, Excel, Powerpoint).
Kỹ năng chuyên môn: [''Tin học văn phòng (Word, Excel, Powerpoint)'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Khả năng thuyết phục khách hàng'', ''Trung thực'', ''Nhiệt tình'', ''Chịu khó'', ''Có trách nhiệm trong công việc'', ''Khả năng xử lý tình huống tốt'', ''Giải quyết vấn đề hiệu quả'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 10000000.00, '2.5 - 10.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:30)', '[''Mức lương cạnh tranh'', ''Thưởng hiệu quả công việc'', ''Môi trường làm việc năng động, chuyên nghiệp'', ''Được đào tạo các kỹ năng cần thiết để hoàn thành công việc'', ''Tham gia các hoạt động teambuilding, du lịch, nghỉ mát hàng năm'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1058, 3, 4, 'CTV Chăm Sóc Khách Hàng (Tiếng Anh, Ca Cuối Tuần)', '- Tiếp nhận email, inbox fanpage,... phản hồi cho tất cả khách hàng (thị trường Mỹ) - Tư vấn, hỗ trợ và giải đáp thắc mắc của khách hàng về sản phẩm, đơn hàng, chương trình khuyến mãi,... - Liên hệ với các bộ phận khác để xử lý các vấn đề phát sinh cho khách hàng', '- Đang là sinh viên hoặc mới tốt nghiệp các trường Đại học tại Hà Nội có thể làm việc bán thời gian tối thiểu 06 tháng - Cẩn thận, tỉ mỉ, có trách nhiệm với công việc chung và làm việc nhóm tốt - Tiếng Anh đọc hiểu tốt. **Bắt buộc tham gia training tại văn phòng công ty, dự kiến là 80 giờ (từ 2-3 tuần tùy theo tiến độ, nhận 100% mức thù lao). Sau đó có thể đăng ký làm online.**
Kỹ năng chuyên môn: [''Tiếng Anh đọc hiểu tốt'']
Kỹ năng mềm: [''Cẩn thận'', ''Tỉ mỉ'', ''Có trách nhiệm với công việc'', ''Làm việc nhóm tốt'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 7 - Chủ nhật (từ 08:00 đến 18:00)', '[''Mức thù lao cố định: 35,000 VND/giờ'', ''Hỗ trợ ăn ca'', ''Hỗ trợ đi lại trong trường hợp làm việc/training tại văn phòng'', ''Thưởng các ngày Lễ, Tết'', ''Thưởng kết quả kinh doanh cuối năm'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1059, 7, 4, 'Thực Tập Sinh Vận Hành Sàn TMĐT', 'Hỗ trợ chuyên viên vận hành sàn, trưởng phòng xây dựng và quản lý gian hàng Tiktokshop, Shopee của thương hiệu, bao gồm các công việc sau: Thực hiện thay đổi banner, hình ảnh thumb, thiết kế và bố cục giao diện gian hàng Tiktokshop theo từng chiến dịch. Đăng tải, cập nhật thông tin sản phẩm đầy đủ nhằm hỗ trợ tối ưu hiển thị tìm kiếm. Lên kế hoạch và tạo các chương trình Discount, Flashsale trên sàn. Chủ động xây dựng và đăng ký các chương trình ưu đãi như: voucher giảm giá, quà tặng, combo sản phẩm, nhằm gia tăng tỷ lệ chuyển đổi đơn hàng. Phối hợp triển khai các chương trình affiliate trên sàn; kết nối và làm việc với các KOL/KOC. Đăng ký tham gia các chiến dịch marketing lớn của sàn để tăng độ phủ thương hiệu và doanh số. Lập kế hoạch, triển khai và theo dõi các chiến dịch quảng cáo trên sàn TMĐT. Đánh giá hiệu quả, tối ưu hóa ngân sách và hiệu suất quảng cáo. Tham gia đóng góp chiến lược sàn, chiến lược sản phẩm.', 'Sinh viên năm 3, 4 hoặc sinh viên mới ra trường theo học chuyên ngành TMĐT, Quản trị kinh doanh, Kinh tế… hoặc các chuyên ngành liên quan. Không yêu cầu kinh nghiệm, đào tạo từ đầu. Nắm bắt trend của thị trường; có tư duy kinh doanh, sáng tạo. Chủ động, linh hoạt, ham học hỏi. Gắn bó lâu dài; Cẩn thận, tỉ mỉ, có trách nhiệm với công việc. Chủ động, hòa đồng, có khả năng làm việc team-work.
Kỹ năng mềm: [''Nắm bắt trend của thị trường'', ''Tư duy kinh doanh'', ''Sáng tạo'', ''Chủ động'', ''Linh hoạt'', ''Ham học hỏi'', ''Cẩn thận'', ''Tỉ mỉ'', ''Có trách nhiệm với công việc'', ''Hòa đồng'', ''Có khả năng làm việc team-work'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), làm thứ 7 cách tuần', '[''Có trợ cấp thực tập: 2M-3M, có dấu mộc thực tập'', ''Có cơ hội trở thành Nhân viên Vận Hàng Sàn, Team lead Ecom chính thức nếu có kết quả làm việc tốt'', ''Được tham gia các buổi đào tạo kỹ năng mềm, kỹ năng chuyên môn nghiệp vụ mà công ty tổ chức'', ''Môi trường làm việc trẻ trung, năng động'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1060, 8, 4, 'Thực Tập Sinh Kinh Doanh', 'Hỗ trợ các công việc liên quan đến kinh doanh (công việc liên quan đến tư vấn, làm việc với đơn vị vận chuyển,...). Xử lý các vấn đề phát sinh: bảo hành, khiếu nại,... Hỗ trợ trực chat tư vấn khách hàng. Hỗ trợ theo dõi các chỉ số hiệu quả của kênh Thương mại điện tử. Công việc sẽ được hướng dẫn, có quy trình đào tạo bài bản.', 'Không yêu cầu kinh nghiệm. Có laptop cá nhân. Khả năng cộng tác, thích nghi nhanh. Khả năng nhận định vấn đề, nhạy bén với tình huống là lợi thế. Yêu thích trao đổi, tư vấn, vận hành. Đăng ký theo lịch cá nhân (yêu cầu tối thiểu 4 buổi/tuần, có ca ngày và ca tối để các bạn đăng ký).
Kỹ năng mềm: [''Khả năng cộng tác'', ''Thích nghi nhanh'', ''Khả năng nhận định vấn đề'', ''Nhạy bén với tình huống'', ''Yêu thích trao đổi'', ''Tư vấn'', ''Vận hành'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '2.5 - 5.0 triệu', 'Đăng ký theo lịch cá nhân (tối thiểu 4 buổi/tuần, có ca ngày và ca tối)', '[''Hỗ trợ xác nhận Báo cáo kết quả thực tập'', ''Cơ hội trở thành nhân viên chính thức'', ''Được học tập và rèn luyện kỹ năng bán hàng'', ''Truy cập miễn phí vào hệ thống học tập nội bộ TVT Academy'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1061, 9, 4, 'Nhân Viên Quản Lý Lớp Học Part-Time', 'Tư vấn, hỗ trợ, chăm sóc từng học viên đang học tập tại trung tâm về tiếng Anh, Tin học, tiếng Trung trực thuộc hệ thống của công ty để học viên được nhận những dịch vụ học tập tốt nhất; Xây dựng kế hoạch học tập cho học viên đảm bảo lộ trình học tập liên tục và xuyên suốt khóa học tại trung tâm tiếng Anh, Tin học, tiếng Trung; Theo dõi và báo cáo tình hình học tập, kết quả thi của học viên; Ghi nhận ý kiến từ học viên; Trả lời Fanpage theo hướng dẫn; Các công việc khác theo sắp xếp của quản lý.', 'Part-time tối thiểu 4 ca/tuần; Ưu tiên sinh viên đang theo học tại trường Trường Đại học Kinh tế quốc dân (NEU), Học viện ngân hàng (BA),…; Có khả năng giao tiếp tốt, sáng tạo, nhiệt tình; Có laptop cá nhân.
Kỹ năng chuyên môn: [''Có laptop cá nhân'']
Kỹ năng mềm: [''Giao tiếp tốt'', ''Sáng tạo'', ''Nhiệt tình'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Tối thiểu 4 ca/tuần', '[''Thử việc 1-2 tháng hưởng 85% lương'', ''Thưởng lễ tết và các dịp trong năm'', ''Cơ hội tăng lương, thăng tiến theo năng lực và thời gian gắn bó'', ''Môi trường làm việc trẻ, năng động'', ''Tham gia các chương trình, sự kiện thường niên của Công ty'', ''Ưu đãi dành riêng cho nhân viên'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1062, 10, 4, 'CTV Chăm Sóc Khách Hàng', 'Tiếp nhận thông tin của khách hàng gọi lên tổng đài. Hỗ trợ, giải quyết các vấn đề cơ bản về Chữ ký số, phần mềm BHXH, phần mềm Hóa đơn điện tử… Hỗ trợ duyệt hồ sơ thuê bao. Chi tiết trao đổi trong buổi phỏng vấn.', 'Có laptop làm việc. Chăm chỉ, nhanh nhẹn, chủ động trong công việc. Không yêu cầu kinh nghiệm, được đào tạo. Tin học văn phòng Word, Excel cơ bản. Sắp xếp được lịch tham gia đào tạo tại văn phòng giờ hành chính.
Kỹ năng chuyên môn: [''Tin học văn phòng Word, Excel cơ bản'']
Kỹ năng mềm: [''Chăm chỉ'', ''Nhanh nhẹn'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', '19h00 - 23h00, thứ 2 - chủ nhật', '[''Được đào tạo khi nhận việc tại Công ty'', ''Hỗ trợ trong quá trình làm việc'', ''Được học hỏi kỹ năng, nghiệp vụ chăm sóc khách hàng'', ''Tham gia các hoạt động tại Công ty'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1063, 2, 4, 'Thực Tập Sinh Vận Hành Sàn TMĐT (Remote)', 'Quản lý các sàn Thương Mại Điện Tử (Shopee, TiktokShop,...). Đăng sản phẩm lên các sàn Thương Mại Điện Tử. Theo dõi và thực hiện set up chương trình bán hàng, hình ảnh banner, giao diện, sản phẩm để phát triển doanh thu các kênh TMĐT. Báo cáo công việc - số liệu bán hàng định kỳ theo yêu cầu của quản lý.', '• Sinh viên vừa tốt nghiệp hoặc đã ra trường dưới 01 năm. Ưu tiên các ngành kinh tế, thương mại, marketing • Không yêu cầu kinh nghiệm • Kỹ năng giao tiếp, thuyết trình, giải quyết vấn đề tốt • Phẩm chất cá nhân: nhanh nhẹn, kiên trì, chăm chỉ, cầu tiến
Kỹ năng mềm: [''Kỹ năng giao tiếp'', ''Thuyết trình'', ''Giải quyết vấn đề'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '1.5 - 3.0 triệu', 'Thời gian làm việc linh hoạt', '[''Làm việc Remote tại nhà'', ''Đào tạo Online'', ''Hỗ trợ dấu thực tập'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1064, 3, 4, 'Chăm Sóc Khách Hàng Intern', 'Hỗ trợ tiếp nhận cuộc gọi, tư vấn và xử lý các yêu cầu, thắc mắc của khách hàng qua các kênh facebook, website, tổng đài. Hỗ trợ phối hợp với các bộ phận liên quan xử lý, giải quyết các yêu cầu, vấn đề của khách hàng. Hỗ trợ team Marketing truyền thông dịch vụ.', 'Ưu tiên các ứng viên từng làm qua telesale. Có thể làm việc full-time hoặc 4 ngày/ tuần. Ứng viên có giọng nói dễ nghe, lưu loát, không vùng miền. Vui vẻ, hoạt bát, kỹ năng giao tiếp khéo léo. Có laptop cá nhân.
Kỹ năng mềm: [''Kỹ năng giao tiếp khéo léo'', ''Vui vẻ'', ''Hoạt bát'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '2.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 làm cách tuần', '[''Hỗ trợ chi phí thực tập 2.000.000vnđ/ tháng'', ''Hỗ trợ dấu mộc, báo cáo, đánh giá thực tập'', ''Môi trường trẻ trung, năng động. Có pantry mini cho nhân viên ăn vặt.'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1065, 7, 4, 'Thương mại điện tử', 'Hỗ trợ đội ngũ marketing và vận hành trong việc hoàn thiện website công ty (nội dung, hình ảnh, bố cục, liên kết...) đảm bảo website hoạt động ổn định, đầy đủ thông tin và thân thiện với người dùng. Cập nhật và tối ưu nội dung trên website: bài viết, hình ảnh, mô tả sản phẩm, FAQ… Chỉnh sửa giao diện, điều hướng hoặc cấu trúc trang (trên nền tảng có sẵn như WordPress, Shopify, Webflow…). Kiểm tra lỗi hiển thị, lỗi liên kết và đảm bảo website hoạt động mượt mà trên cả desktop và mobile. Thêm/bố trí các mục như banner, form đăng ký, popup, landing page... theo yêu cầu. Phối hợp với designer/marketing để thực hiện đúng bố cục và tone của thương hiệu. Hỗ trợ các vấn đề kỹ thuật nhỏ (gắn mã pixel, liên kết mạng xã hội, cài plugin…).', 'Có kinh nghiệm quản trị hoặc chỉnh sửa website trên nền tảng phổ biến (ưu tiên: WordPress, Shopify, Webflow...). Biết cơ bản về HTML/CSS là lợi thế.- Có tư duy thẩm mỹ tốt và biết cách tối ưu UX/UI cơ bản. Chủ động, cẩn thận, làm việc có trách nhiệm, đảm bảo đúng tiến độ. Có laptop cá nhân và kết nối Internet ổn định.
Kỹ năng chuyên môn: [''Quản trị website'', ''HTML'', ''CSS'']
Kỹ năng mềm: [''Chủ động'', ''Cẩn thận'', ''Trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', '3 tiếng/ngày', '[''Linh hoạt thời gian'', ''Môi trường làm việc trẻ, năng động'', ''Cơ hội cộng tác dài hạn'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1066, 8, 13, 'TTS Thiết Kế Nội Thất', '• Hỗ trợ đội ngũ thiết kế trong các dự án thực tế (căn hộ, nhà phố, biệt thự, khách sạn,...). • Tham gia vào quá trình lên ý tưởng, triển khai bản vẽ kỹ thuật (2D, 3D) bằng các phần mềm chuyên dụng (AutoCAD, SketchUp, 3Ds Max,...). • Học hỏi và thực hành việc lựa chọn vật liệu, màu sắc, và các yếu tố trang trí. • Có cơ hội tham gia khảo sát hiện trạng công trình (nếu có). • Thực hiện các công việc khác theo sự hướng dẫn của quản lý.', '• Sinh viên năm cuối hoặc mới tốt nghiệp các trường Đại học, Cao đẳng chuyên ngành Thiết kế Nội thất, Kiến trúc hoặc các ngành liên quan. • Có kiến thức cơ bản về các phần mềm thiết kế (AutoCAD, SketchUp, 3Ds Max, Photoshop...). • Yêu thích, có gu thẩm mỹ tốt và mong muốn phát triển trong lĩnh vực thiết kế nội thất. • Năng động, ham học hỏi, có tinh thần trách nhiệm và khả năng làm việc nhóm. • Có laptop cá nhân.
Kỹ năng chuyên môn: [''AutoCAD'', ''SketchUp'', ''3Ds Max'', ''Photoshop'']
Kỹ năng mềm: [''Yêu thích thiết kế'', ''Có gu thẩm mỹ tốt'', ''Năng động'', ''Ham học hỏi'', ''Có tinh thần trách nhiệm'', ''Khả năng làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được đào tạo và hướng dẫn tận tình từ các kiến trúc sư, nhà thiết kế giàu kinh nghiệm.'', ''Trải nghiệm môi trường làm việc thực tế, năng động và sáng tạo tại FAM Interior.'', ''Hỗ trợ chi phí thực tập.'', ''Có cơ hội trở thành nhân viên chính thức sau kỳ thực tập nếu thể hiện tốt năng lực.'', ''Hỗ trợ tài liệu, dấu mộc cho báo cáo thực tập (nếu cần).'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1067, 9, 13, 'Thực Tập Sinh Video Editor', 'Lên ý tưởng và làm video quảng cáo app mobile; Cắt ghép các video giới thiệu app, các video phục vụ cho team Marketing,... Chỉnh sửa, biên tập video theo kế hoạch đã lên. Phối hợp với team Marketing để dựng video theo kịch bản có sẵn. Nghiên cứu thị trường và các xu hướng mới của đối thủ trên nền tảng. Các công việc khác được Leader phân công.', 'Ưu tiên sinh viên năm cuối hoặc đã tốt nghiệp Cao đẳng/đại học chuyên ngành có liên quan. Ưu tiên ứng viên có thể đi làm full-time. Sử dụng thành thạo bất kỳ phần mềm chỉnh sửa video nào: Adobe Premiere, Capcut... Kinh nghiệm ghép âm thanh và tìm kiếm âm thanh. Hoàn thành deadline chính xác. Kỹ năng làm việc nhóm. Có trách nhiệm, đam mê, sáng tạo, chi tiết, cẩn thận.
Kỹ năng chuyên môn: [''Adobe Premiere'', ''Capcut'']
Kỹ năng mềm: [''Kỹ năng làm việc nhóm'', ''Có trách nhiệm'', ''Đam mê'', ''Sáng tạo'', ''Chi tiết'', ''Cẩn thận'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '2.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 12:00 và từ 13:30 đến 18:00)', '[''Cơ hội trở thành nhân viên chính thức'', ''Review năng lực hàng năm'', ''Lương tháng 13'', ''Chế độ sinh nhật, sinh con, hiếu hỷ, ngày lễ'', ''12 phép/năm'', ''Hỗ trợ 100% vé tháng gửi xe'', ''Teambuilding, du lịch nghỉ mát hàng năm'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1068, 10, 13, 'Nhân Viên Thiết Kế Part Time', 'Thiết kế các ấn phẩm truyền thông (banner, poster, brochure, social media post, v.v.). Hỗ trợ xây dựng bộ nhận diện thương hiệu, landing page, slide thuyết trình,... Phối hợp với team Marketing/Content để triển khai các chiến dịch truyền thông. Đảm bảo tiến độ và chất lượng sản phẩm đúng theo yêu cầu.', 'Thành thạo các công cụ thiết kế: Photoshop, Illustrator (biết thêm Figma, Premiere/After Effect là lợi thế). Có tư duy thẩm mỹ tốt, khả năng sáng tạo cao. Có kinh nghiệm thiết kế ít nhất 6 tháng. Có laptop cá nhân và chủ động trong công việc.
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Figma'', ''Premiere'', ''After Effect'']
Kỹ năng mềm: [''Tư duy thẩm mỹ'', ''Khả năng sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', '8h30 – 12h hoặc 14h – 17h30', '[''Môi trường làm việc chuyên nghiệp'', ''Hỗ trợ phát triển cá nhân'', ''Tham gia các hoạt động thường niên của công ty'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1069, 2, 13, 'Thực Tập Sinh Thiết Kế Nội Thất', 'Hỗ trợ thiết kế concept nội thất, triển khai mô hình 3D trên SketchUp. Học hỏi và thực hành về thiết kế không gian, bố cục và vật liệu. Phối hợp với đội ngũ thiết kế để phát triển ý tưởng và hoàn thiện bản vẽ. Chỉnh sửa và hoàn thiện các mô hình 3D theo yêu cầu.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các ngành Kiến trúc, Thiết kế Nội thất, Xây dựng hoặc các ngành liên quan. Có khả năng sử dụng SketchUp cơ bản, biết thêm AutoCAD hoặc Photoshop là lợi thế. Đam mê thiết kế nội thất, mong muốn học hỏi và phát triển trong ngành. Chủ động, sáng tạo, có trách nhiệm trong công việc.
Kỹ năng chuyên môn: [''SketchUp'', ''AutoCAD'', ''Photoshop'']
Kỹ năng mềm: [''Chủ động'', ''Sáng tạo'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30), Thứ 7 cách tuần', '[''Hỗ trợ lương thực tập 3,000,000 đồng/tháng'', ''Cơ hội tham gia vào các dự án thực tế'', ''Được đào tạo, hướng dẫn trực tiếp bởi đội ngũ thiết kế giàu kinh nghiệm'', ''Môi trường làm việc chuyên nghiệp, năng động'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1070, 3, 13, 'Nhân Viên Designer Partime Xoay Ca Linh Hoạt', '- Xây dựng ý tưởng và thiết kế đồ họa các sản phẩm truyền thông thương hiệu - Thiết kế các ấn phẩm quảng cáo in ấn, ấn phẩm cho sự kiện, sản phẩm quảng cáo online - Thực hiện các công việc khác theo sự phân công của Leader', '- Nữ, có kinh nghiệm cộng tác viên từ 3 tháng vị trí tương đương, từng làm lĩnh vực thời trang - Tốt nghiệp Đại Học, Cao Đẳng chuyên nghành thiết kế đồ họa hoặc chuyên nghành có liên quan - Khả năng mỹ thuật tốt, tính năng động, sáng tạo, luôn chủ động trong công việc; - Kỹ năng làm việc độc lập và làm việc theo nhóm; - Gửi CV + Portfolio
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Ai'']
Kỹ năng mềm: [''Khả năng làm việc độc lập'', ''Khả năng làm việc theo nhóm'', ''Tính năng động'', ''Sáng tạo'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '3.5 - 4.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)', '[''Thưởng các ngày lễ, Tết'', ''Sinh nhật hàng tháng'', ''Tặng quà Noel'', ''Tham gia hoạt động vui chơi, party, teambuilding, du lịch do Công ty tổ chức'', ''Được hưởng chế độ đào tạo nâng cao nghiệp vụ'', ''Có cơ hội thăng tiến trong nghề nghiệp'', ''Xét tăng lương phù hợp với sự nỗ lực, đóng góp cho sự phát triển Công Ty'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1071, 7, 13, 'Cộng Tác Viên Multimedia Design', '- Thiết kế các nội dung marketing materials bao gồm: Ad banner, poster, facebook photos, infographic,…; - Xây dựng video giới thiệu về các sản phẩm game của công ty; - Đưa ra ý tưởng cho các video phục vụ chiến dịch quảng cáo và PR sản phẩm; - Cùng với team lên ý tưởng thiết kế quảng bá cho các chiến dịch Marketing của sản phẩm; - Hỗ trợ các thành viên khác trong nhóm thiết kế;', '- Sử dụng thành thạo các phần mềm chuyên dụng PS/AE/Adobe Premiere; - Biết quay dựng, edit video; - Tư duy sáng tạo, đột phá, nhạy bén, có khả năng truyền tải ý tưởng sinh động và độc đáo; - Có kinh nghiệm về 3D, animation là một lợi thế;
Kỹ năng chuyên môn: [''Photoshop'', ''After Effects'', ''Adobe Premiere'', ''Quay dựng video'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Khả năng truyền tải ý tưởng'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 7000000.00, '5.0 - 7.0 triệu', 'Làm việc remote; Thời gian tự do', '[''Tham gia vào các hoạt động lớn của công ty'', ''Tham gia các hoạt động teambuilding'']', false, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1072, 8, 13, 'CTV Customily (Yêu Cầu Kinh Nghiệm Customily)', 'Nhận nguyên liệu thiết kế (File design & Arts), design và xử lý các điều kiện liên kết trên Customily để tạo ra sản phẩm bán trên website. Thiết kế Mockup sản phẩm. Kiểm soát chất lượng đầu ra của sản phẩm. Tham gia các nhiệm vụ khác theo sự phân công của quản lý.', 'Sử dụng được các phần mềm thiết kế (Photoshop) ở mức căn bản. Đã từng làm việc với Customily. Chăm chỉ, cẩn thận, tỉ mỉ, trách nhiệm với công việc chung. Làm offline tại nhà, tháng đầu tiên ưu tiên lên công ty training. Gửi CV + portfolio các sản phẩm từng làm.
Kỹ năng chuyên môn: [''Photoshop'']
Kỹ năng mềm: [''Chăm chỉ'', ''Cẩn thận'', ''Tỉ mỉ'', ''Trách nhiệm'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '1.2 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '[''Lương trả theo mẫu (Mức lương tương đương khoảng 35k/h)'', ''Hỗ trợ dấu mộc thực tập (nếu cần)'', ''Cơ hội trở thành nhân viên chính thức'', ''Thoải mái về không gian làm việc'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1073, 9, 13, 'Giảng Viên Dạy Vẽ', '- Giảng dạy trực tiếp các môn vẽ tĩnh vật, đầu tượng, chân dung và môn vẽ màu cho học viên; - Theo dõi quá trình luyện thi của học viên; - Tư vấn môn thi, trường thi phù hợp với khả năng của học viên; - Cập nhật khối thi, trường thi hàng năm.', '- Tốt nghiệp trường đại học Kiến trúc, Mỹ thuật, Sư phạm vẽ; - Yêu thích công việc giảng dạy; - Đã có kinh nghiệm giảng dạy; - Kỹ năng vẽ tay tốt; - Soạn thảo giáo án, chuẩn bị tư liệu giảng dạy; - Khả năng giao tiếp tốt, có tinh thần trách nhiệm, nhiệt huyết với học viên.
Kỹ năng chuyên môn: [''Kỹ năng vẽ tay tốt'', ''Soạn thảo giáo án'', ''Chuẩn bị tư liệu giảng dạy'']
Kỹ năng mềm: [''Khả năng giao tiếp tốt'', ''Có tinh thần trách nhiệm'', ''Nhiệt huyết với học viên'']', 'PART_TIME', 'ONSITE', 'quận 10', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Ca làm việc linh hoạt theo lịch học', '[''Được làm việc trong môi trường uy tín, chất lượng'', ''Lịch giảng dạy cố định, cộng tác lâu dài'', ''Ăn sáng và ăn trưa tại trung tâm'', ''Nghỉ lễ, tết theo luật quy định'']', false, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1074, 10, 13, 'Thực Tập Sinh Thiết Kế Hệ Thống Điện', 'Hỗ trợ khảo sát dự án và đưa ra các giải pháp thiết kế cơ điện đảm bảo yêu cầu kỹ thuật. Tham gia triển khai thiết kế hệ thống điện cho các dự án Điện Năng lượng Mặt trời áp mái và Điện công trình dân dụng. Hỗ trợ thiết kế nguyên lý, chỉ dẫn lắp đặt, vận hành & xử lý lỗi cải tiến hệ thống. Tham gia bóc tách khối lượng, lập kế hoạch đề xuất vật tư cho dự án. Chi tiết trao đổi trong cuộc phỏng vấn.', 'Sinh viên năm cuối hoặc mới tốt nghiệp Đại học với chuyên ngành về Điện, Năng lượng tái tạo và các ngành kỹ thuật liên quan. Có kiến thức và biết sử dụng các phần mềm AutoCAD, MS Office. Có khả năng tự tìm hiểu các tài liệu chuyên ngành để nâng cao năng lực và cập nhật các kỹ thuật, công nghệ mới liên quan đến công việc được phân công. Trung thực, có trách nhiệm với công việc. Khả năng làm việc nhóm, giao tiếp tốt. Thời gian thực tập: toàn thời gian, trong 06 tháng.
Kỹ năng chuyên môn: [''AutoCAD'', ''MS Office'']
Kỹ năng mềm: [''Trung thực'', ''Có trách nhiệm với công việc'', ''Khả năng làm việc nhóm'', ''Giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Toàn thời gian', '[''Phụ cấp lương thực tập'', ''Được đào tạo chuyên môn & bản thân khi thực tập tại Công ty'', ''Cơ hội trở thành nhân viên chính thức'', ''Môi trường làm việc quốc tế thân thiện & chuyên nghiệp'', ''Được hưởng các quyền lợi khác theo chính sách công ty'', ''Hỗ trợ đóng dấu mộc và báo cáo thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1075, 2, 13, 'Thực Tập Sinh Học Vụ', 'Kiểm tra trình độ đầu vào của học viên, xếp lớp theo trình độ. Tổ chức khai giảng lớp học theo lịch sắp xếp của trung tâm. Dự giờ và kiểm soát chất lượng lớp học. Hỗ trợ xây dựng chương trình học. Điều phối, sắp xếp lịch dạy cho giáo viên. Phối hợp chăm sóc, hỗ trợ giáo viên và học viên trong quá trình học.', 'Sinh viên năm 3,4 hoặc tốt nghiệp Đại học, cao đẳng chuyên ngành Tiếng Anh. Tiếng Anh thành thạo 4 kỹ năng là 1 lợi thế. Có kỹ năng xử lí tình huống linh hoạt, khéo léo. Chăm chỉ, nhiệt tình.
Kỹ năng chuyên môn: [''Tiếng Anh thành thạo 4 kỹ năng'']
Kỹ năng mềm: [''Kỹ năng xử lý tình huống linh hoạt'', ''Chăm chỉ'', ''Nhiệt tình'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh, hà nội', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '2.5 - 3.0 triệu', 'Full time hoặc partime xoay ca: Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''Hỗ trợ dấu mộc thực tập'', ''Có cơ hội trở thành nhân sự chính thức sau 3-4 tháng thực tập'', ''Được đào tạo kỹ năng cơ bản và nâng cao'', ''Môi trường chuyên nghiệp, tôn trọng và tạo điều kiện phát huy giá trị cá nhân'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1076, 3, 13, 'Thực Tập Sinh Thiết Kế Thời Trang', 'Hoàn thành, đảm bảo chất lượng công việc theo yêu cầu của trưởng nhóm và trưởng phòng. Nghiên cứu thị trường, online research. Triển khai ý tưởng bộ sưu tập / vẽ CAD & làm tech pack từ trưởng nhóm. Theo dõi tiến độ phát triển mẫu / fitting mẫu cùng với trưởng nhóm.', 'Thời gian thực tập 3 tháng. Khả năng research, tư duy sáng tạo, có gu thẩm mỹ tốt về màu sắc, hoạ tiết. Có khả năng vẽ các phần mềm thiết kế chuyên nghiệp như PS, AI… Sáng tạo, tìm kiếm và tổng hợp thông tin, hình ảnh phục vụ công việc. Tác phong làm việc chuyên nghiệp, chủ động, có trách nhiệm với công việc và hoàn thành đúng deadline. Sinh viên năm 4 hoặc mới tốt nghiệp chuyên ngành thiết kế thời trang.
Kỹ năng chuyên môn: [''Sử dụng phần mềm thiết kế chuyên nghiệp như PS, AI'']
Kỹ năng mềm: [''Khả năng research'', ''Tư duy sáng tạo'', ''Có gu thẩm mỹ tốt về màu sắc, hoạ tiết'', ''Tác phong làm việc chuyên nghiệp'', ''Chủ động'', ''Có trách nhiệm với công việc'', ''Hoàn thành đúng deadline'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '0.7 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30)', '[''Trợ cấp lương trong quá trình thực tập'', ''Hỗ trợ dấu mộc thực tập'', ''Làm việc trong môi trường về thời trang trẻ trung, năng động, phát triển nhanh'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1077, 7, 13, 'Thực Tập Sinh Video Editor', 'Thực hiện công việc hỗ trợ chỉnh sửa video được phân công theo yêu cầu của bộ phận và Công ty. Phối hợp với phòng MKT hỗ trợ biên tập nội dung, chỉnh sửa video. Lên ý tưởng dựng video đăng trên fanpage, website …. của công ty nhằm mục đích truyền thông văn hóa doanh nghiệp. Hỗ trợ quay phim, chụp ảnh các sự kiện truyền thông nội bộ. Hỗ trợ các công việc khác theo chỉ đạo của Ban lãnh đạo.', 'Sinh viên chuyên ngành Thiết kế đồ họa, Truyền thông và các ngành có liên quan hoặc có niềm yêu thích với Edit video. Biết sử dụng phần mềm edit cơ bản như Premier, Photoshop, Canva, Capcut... (Ưu tiên sử dụng được Capcut). Nhanh nhẹn, thật thà, yêu thích và muốn gắn bó lâu dài về mảng edit Youtube, Tik Tok. Chủ động, Nhiệt tình, nghiêm túc và có trách nhiệm với công việc.
Kỹ năng chuyên môn: [''Premier'', ''Photoshop'', ''Canva'', ''Capcut'']
Kỹ năng mềm: [''Nhanh nhẹn'', ''Thật thà'', ''Chủ động'', ''Nhiệt tình'', ''Nghiêm túc'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 5000000.00, '3.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00) và thứ 7 cách tuần', '[''Hỗ trợ trợ cấp theo năng lực'', ''Hỗ trợ dấu thực tập nếu có nhu cầu'', ''Được hướng dẫn bởi các chuyên gia giỏi và giàu kinh nghiệm'', ''Lộ trình thực tập 3 tháng, được lên nhân viên chính thức nếu hoàn thành tốt'', ''Làm việc trong môi trường IT trẻ, thân thiện và chuyên nghiệp'', ''Tea Break'', ''Team Building tháng/quý'', ''Du lịch hàng năm'', ''Được hưởng đầy đủ các chế độ đãi ngộ theo Luật Lao động Việt Nam (BHXH, BHYT, lương tháng 13...) (Nếu lên chính thức)'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1078, 8, 13, 'Nhân Viên Dự Toán', 'Dự án Tender dự thầu: Nhận thông tin hồ sơ mời thầu từ phòng Sales bao gồm: phạm vi công việc (SOW), bảng khối lượng (BOQ), hình ảnh phối cảnh_3D, bản vẽ thiết kế / bản vẽ chi tiết, spec nguyên vật liệu, màu sắc hoàn thiện, spec FF&E, Họp triển khai báo giá với PD. Đo đạc, bốc tách khối lượng bao gồm các các công tác Fit-out liên quan hoàn thiện nội thất trần, tường, sàn, công tác đồ liền tường, đồ rời theo phạm vi hạng mục công việc được mô tả trong hồ sơ mời thầu. Không bao gồm các công tác ngoại thất, kết cấu, Landscape, MEP... Lập bảng kê danh mục chủng loại vật tư kèm khối lượng sơ bộ theo bản vẽ thiết kế, spec nguyên vật liệu trong hồ sơ mời thầu. Triển khai thông tin cho phòng Sourcing để lấy báo giá từ nhà cung cấp và Thầu Phụ. Tính giá sản phẩm đồ gỗ liền tường & nội thất rời. Đánh giá kiểm tra các báo giá, tiến hành nhập đơn giá vào BOQ để lập bảng báo giá tổng hợp. Khi có thông tin “Lệnh Khởi Công”, tiến hành upload BOQ (mã BOQ, giá bán, giá Cost tender, giá giao) theo Template quy định lên hệ thống SAP. Nhận hợp đồng điền các thông tin chi tiết của dự án và giá trị, chuyển Hợp đồng cho phòng hợp đồng kiểm tra và thông tin cho các điều khoản hợp đồng, in ấn Trình kí. Báo giá phát sinh cho các dự án trúng thầu: Lập bảng kê danh mục chủng loại vật tư kèm khối lượng sơ bộ cho các nguyên vật liệu mới phát sinh theo bản vẽ triển khai (shop drawing). Chuyển toàn bộ hồ sơ mời thầu bao gồm BOQ, bảng kê danh mục vật liệu kèm khối lương, bản vẽ thiết kế, spec nguyên vật liệu, spec FF&E và triển khai thông tin phát sinh cho phòng Sourcing tiến hành báo giá và thực hiện các bước công việc tiếp theo như trên.', 'Tốt nghiệp CĐ/ ĐH chuyên ngành kinh tế - dự toán xây dựng, quản lý dự án. Ít nhất 1 năm kinh nghiệm ở vai trò dự toán về mảng (Kiến trúc, nội thất, hoặc vật liệu nội thất). Có thể đọc hiểu bản vẽ/shopdrawing. Ưu tiên có thể sử dụng được tiếng Anh.
Kỹ năng chuyên môn: [''Đọc hiểu bản vẽ/shopdrawing'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 18:00)', '[''Đóng BHXH, BHYT, BH PVI ... theo luật quy định'', ''Được tham gia du lịch, team-building'', ''Xét đánh giá: 1 năm 2 lần'', ''Các phúc lợi khác theo quy định công ty'']', false, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1079, 9, 13, 'Thực Tập Sinh Video Editor', 'Biên tập, chỉnh sửa, cắt ghép hình ảnh, âm thanh, thành video hoàn chỉnh để đăng trên các nền tảng Facebook, Tiktok,.. (sẽ được training). Cập nhật Trend, biên tập các Short Video dọc để đăng tải các nền tảng Tiktok, Reels. Thực hiện các công việc theo sự hướng dẫn và phân công của Leader.', 'Thời gian thực tập: Trao đổi khi phỏng vấn. Biết Sử dụng phần mềm chỉnh sửa video cơ bản (như CapCut) hoặc là lợi thế. Trung thực, cầu tiến, trách nhiệm trong công việc.
Kỹ năng chuyên môn: [''Sử dụng phần mềm chỉnh sửa video cơ bản (như CapCut)'']
Kỹ năng mềm: [''Trung thực'', ''Cầu tiến'', ''Trách nhiệm trong công việc'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 2000000.00, '1.0 - 2.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Được training về kiến thức và kỹ năng chuyên môn'', ''Được trợ cấp trong quá trình thực tập'', ''Làm việc trong môi trường chuyên nghiệp, năng động và sáng tạo'', ''Có cơ hội trở thành nhân viên chính thức'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1080, 10, 13, 'Intern Video Editor (Game)', 'Hỗ trợ thực hiện các sản phẩm video intro/outro, trailer game phục vụ cho các chiến dịch quảng cáo game ở thị trường global. Phối hợp cùng team Marketing để phát triển ý tưởng video, đảm bảo nội dung truyền tải đúng mục tiêu đề ra. Học hỏi quy trình làm việc chuyên nghiệp từ Leader và được giao các đầu việc phù hợp theo khả năng. Cập nhật các xu hướng video, hình ảnh, âm thanh đang phổ biến trên thị trường để ứng dụng vào công việc. Thực hiện các công việc khác theo sự phân công từ Leader.', 'Làm việc fulltime; Ưu tiên biết sử dụng cơ bản các phần mềm dựng video như Adobe Premiere, After Effects, Audition, hoặc phần mềm tương tự. Yêu thích game, đặc biệt là mobile game là một lợi thế. Có tư duy sáng tạo, gu thẩm mỹ tốt và chủ động học hỏi. Có tinh thần trách nhiệm, chịu khó rèn luyện kỹ năng, làm việc nhóm tốt. Ưu tiên các bạn Gen Z
Kỹ năng chuyên môn: [''Adobe Premiere'', ''After Effects'', ''Audition'']
Kỹ năng mềm: [''sáng tạo'', ''làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00)', '[''trợ cấp'', ''đào tạo bài bản'', ''cơ hội lên làm chính thức'', ''cơ hội nhận thưởng kinh doanh'']', false, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1081, 2, 13, 'Thực Tập Sinh Chỉnh Sửa Ảnh', '* Tham gia vào quá trình thiết kế và phát triển các sản phẩm, dự án kiến trúc/nội thất. * Thực hiện chỉnh sửa ảnh nội thất/ngoại thất theo yêu cầu của khách hàng nước ngoài * Lựa chọn công cụ, màu sắc, ánh sáng phù hợp với từng dự án. * Hợp tác với các bộ phận khác để đảm bảo dự án được thực hiện đúng tiến độ và chất lượng. * Cập nhật kiến thức, xu hướng mới nhất.', '* Không yêu cầu kinh nghiệm, ưu tiên ứng viên có đam mê thiết kế kiến trúc/nội thất. * Tốt nghiệp Đại học/Cao đẳng chuyên ngành Kiến trúc, Thiết kế nội thất hoặc các chuyên ngành liên quan. * Thành thạo các phần mềm thiết kế đồ họa như AutoCAD, SketchUp, 3ds Max, Photoshop, Lumion (hoặc các phần mềm tương đương). * Khả năng tư duy sáng tạo, có gu thẩm mỹ tốt, nắm bắt xu hướng thiết kế hiện đại. * Khả năng làm việc độc lập và làm việc nhóm hiệu quả. * Trung thực, cẩn thận, tỉ mỉ trong công việc. * Khả năng chịu áp lực công việc tốt, sẵn sàng làm việc ngoài giờ khi cần thiết. * Có tinh thần trách nhiệm cao, chủ động trong công việc.
Kỹ năng chuyên môn: [''AutoCAD'', ''SketchUp'', ''3ds Max'', ''Photoshop'', ''Lumion'']
Kỹ năng mềm: [''Khả năng tư duy sáng tạo'', ''Khả năng làm việc độc lập'', ''Khả năng làm việc nhóm'', ''Trung thực'', ''Cẩn thận'', ''Tỉ mỉ'', ''Khả năng chịu áp lực công việc'', ''Có tinh thần trách nhiệm cao'', ''Chủ động trong công việc'']', 'PART_TIME', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 3000000.00, '2.0 - 3.0 triệu', 'Thứ 2-Thứ 7', '[''Có mức hỗ trợ trong thời gian thực tập'', ''Cơ hội được đào tạo'', ''Cơ hội thăng tiến và phát triển nghề nghiệp'', ''Tham gia các hoạt động team building, du lịch nghỉ dưỡng hàng năm.'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1082, 3, 13, 'Thực Tập Sinh Thiết Kế Đồ Hoạ', '* Hỗ trợ thiết kế các hạng mục công việc, dự án tại công ty bao gồm hình ảnh, video; * Hỗ trợ thiết kế ấn phẩm sự kiện và truyền thông: Backdrop, flyer, banner, invitation card, standee… * Hỗ trợ thiết kế thương hiệu: nhận diện thương hiệu, Catalogue,, Card visit, Poster, Banner, Tờ rơi, Brochure, hồ sơ năng lực... sản phẩm in ấn phục vụ công việc quảng bá sản phẩm, thương hiệu của đối tác, khách hàng và công ty. * Chuẩn bị hình ảnh minh họa hoặc các bản phác thảo, format chương trình truyền hình, sự kiện, các bản trình bày ý tưởng. * Thực hiện thiết kế các ấn phẩm liên quan đến truyền thông nội bộ, các ấn phẩm trên các kênh social. * Thiết kế, chỉnh sửa các tài liệu theo yêu cầu của công ty. * Thực hiện các nhiệm vụ khác theo yêu cầu của quản lý.', '* Tổng thời gian tham gia chương trình thực tập: 3 tháng hoặc 6 tháng * Luôn nỗ lực hết mình để hoàn thành chương trình thực tập * Ưu tiên ngành học: Thiết kế đồ họa, Marketing, QTKD, Kinh tế hoặc các ngành có liên quan. Có tư duy và sự yêu thích đối với Thiết kế đồ họa. * Ưu tiên có kiến thức về thiết kế đồ họa, marketing, truyền thông,.. * Biết sử dụng các công cụ thiết kế: Canva; Adobe Photoshop, Adobe Premiere , Illustrator. Sử dụng Facebook/Tiktok/Blog * Hướng tới khách hàng, kỹ năng tổ chức công việc, làm việc nhóm và độc lập. * Có tư duy thẩm mỹ, khả năng sáng tạo cơ bản * Cẩn thận, cầu tiến trong công việc, quản lý thời gian và khả năng làm việc nhóm tốt để xử lý đa nhiệm vụ. * Có khiếu thẩm mỹ phù hợp thị hiếu hiện nay. Chủ động trong công việc.
Kỹ năng chuyên môn: [''Canva'', ''Adobe Photoshop'', ''Adobe Premiere'', ''Illustrator'', ''Facebook/Tiktok/Blog'']
Kỹ năng mềm: [''Hướng tới khách hàng'', ''kỹ năng tổ chức công việc'', ''làm việc nhóm'', ''độc lập'', ''tư duy thẩm mỹ'', ''khả năng sáng tạo'', ''cẩn thận'', ''quản lý thời gian'']', 'PART_TIME', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'tối thiểu 4 tiếng/ ngày, 5 buổi/ tuần', '[''Được tham gia các khóa đào tạo, phát triển kỹ năng và phục vụ cho chuyên môn công việc'', ''Được tạo cơ hội để sinh viên được tham gia trực tiếp vào quá trình thực hiện công việc, thông qua training kiến thức, kỹ năng để phát triển bản thân'', ''Giúp đỡ thực tập sinh nhìn nhận và thấu hiểu bản thân, qua đó mỗi người sẽ có định hướng cho bản thân trong quá trình phát triển'', ''Có cơ hội được kết nối thực với doanh nghiệp/tổ chức phù hợp với định hướng cá nhân và định hướng doanh nghiệp sau khi hoàn thành xong chương trình thực tập tại Amazing Group.'', ''Được trả mức thù lao 1.000.000 VND (kể từ tháng thứ 4 trở đi), thưởng theo hiệu suất công việc trong quá trình thực tập.'', ''Được hỗ trợ chữ ký và mộc thực tập cho Thực tập sinh.'', ''Được cấp chứng chỉ hoàn thành chương trình thực tập bởi Amazing Group và được hỗ trợ thư giới thiệu từ cấp quản lý (nếu có nguyện vọng).'', ''Có cơ hội trở thành Best Talent với giải thưởng 5,000,000 VND tiền mặt & cam kết đồng hành cùng chương trình lương Part time không dưới 5,000,000 VND và lương Fulltime không dưới 10,000,000 VND.'', ''Có cơ hội trở thành Best Transformation với giải thưởng: 5,000,000 VND tiền mặt hoặc 01 năm mentoring cố vấn với CEO & thoả thuận lương theo năng lực cá nhân (Parttime/ Fulltime).'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1083, 7, 13, 'Thực Tập Sinh Video Editor', '- Chỉnh sửa, biên tập video theo kịch bản từ Content Creator. - Thực hiện các hiệu ứng âm thanh, hình ảnh và đồ họa cơ bản để tăng tính sinh động cho video. - Hỗ trợ sáng tạo nội dung video theo xu hướng trên TikTok, Facebook Reels, YouTube. - Hỗ trợ phối hợp với Content Creator, lên kế hoạch ý tưởng, nội dung cho các video để hoàn thiện sản phẩm cuối cùng. - Tham gia vào các dự án thực tế, đóng góp ý tưởng sáng tạo và nhận phản hồi trực tiếp từ các chuyên gia. - Thực hiện các công việc khác theo yêu cầu từ quản lý.', '- Tổng thời gian tham gia chương trình thực tập: 3 tháng hoặc 6 tháng - Luôn nỗ lực hết mình để hoàn thành chương trình thực tập - Sinh viên từ năm nhất đến năm tư tại các trường đại học trên cả nước. (Ưu tiên ứng viên biết sử dụng một số phần mềm như Capcut, Adobe Photoshop, Adobe Premiere, và có kiến thức về Adobe After Effect,...) - Ưu tiên ứng viên có kinh nghiệm biên tập video - Có tư duy thẩm mỹ, khả năng sáng tạo cơ bả - Cẩn thận, cầu tiến trong công việc, quản lý thời gian và khả năng làm việc nhóm tốt để xử lý đa nhiệm vụ. - Có khiếu thẩm mỹ phù hợp thị hiếu hiện nay. - Chủ động trong công việc.
Kỹ năng chuyên môn: [''Capcut'', ''Adobe Photoshop'', ''Adobe Premiere'', ''Adobe After Effect'']
Kỹ năng mềm: [''Khả năng làm việc nhóm'', ''Khả năng quản lý thời gian'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30) Thời gian làm việc: tối thiểu 4 tiếng/ ngày, 5 buổi/ tuần', '[''Được tham gia các khóa đào tạo, phát triển kỹ năng và phục vụ cho chuyên môn công việc'', ''Được tạo cơ hội để sinh viên được tham gia trực tiếp vào quá trình thực hiện công việc, thông qua training kiến thức, kỹ năng để phát triển bản thân'', ''Giúp đỡ thực tập sinh nhìn nhận và thấu hiểu bản thân, qua đó mỗi người sẽ có định hướng cho bản thân trong quá trình phát triển'', ''Có cơ hội được kết nối thực với doanh nghiệp/tổ chức phù hợp với định hướng cá nhân và định hướng doanh nghiệp sau khi hoàn thành xong chương trình thực tập tại Amazing Group.'', ''Được trả mức thù lao 1,000,000 VND (kể từ tháng thứ 4 trở đi), thưởng theo hiệu suất công việc trong quá trình thực tập'', ''Được hỗ trợ chữ ký và mộc thực tập cho Thực tập sinh.'', ''Được cấp chứng chỉ hoàn thành chương trình thực tập bởi Amazing Group và được hỗ trợ thư giới thiệu từ cấp quản lý (nếu có nguyện vọng).'', ''Có cơ hội trở thành Best Talent với giải thưởng 5,000,000 VND tiền mặt & cam kết đồng hành cùng chương trình lương Part time không dưới 5,000,000 VND và lương Fulltime không dưới 10,000,000 VND.'', ''Có cơ hội trở thành Best Transformation với giải thưởng: 5,000,000 VND tiền mặt hoặc 01 năm mentoring cố vấn với CEO & thoả thuận lương theo năng lực cá nhân (Parttime/ Fulltime).'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1084, 8, 13, 'Ui/ux thiết kế thực tập, tươi hơn', 'Thiết kế giao diện, bố cục cho các ứng dụng và website. Tham gia vào quy trình thiết kế của các dự án. Phối hợp với các bộ phận liên quan để tối ưu thiết kế. Cập nhật các xu hướng thiết kế mới. Thực hiện các nhiệm vụ được giao trong phạm vi công việc của Team Design.', 'Thành thạo các công cụ thiết kế, đặc biệt là Figma. Tư duy logic tốt. Có kỹ năng vẽ tay là một lợi thế. Có tinh thần chủ động học hỏi, làm việc có tổ chức, có khả năng làm việc độc lập và làm việc nhóm. Cam kết tham gia đầy đủ trong suốt kỳ thực tập 3 tháng.
Kỹ năng chuyên môn: [''Thiết Kế Giao Diện Người Dùng (ui)'', ''Thiết Kế Trải Nghiệm Người Dùng (ux)'', ''Nghiên Cứu Người Dùng (user Research)'', ''Nguyên Tắc Thiết Kế (typography, Màu Sắc, Bố Cục)'', ''Sử Dụng Phần Mềm Thiết Kế (figma, Adobe Xd, Sketch)'']
Kỹ năng mềm: [''Tư duy logic'', ''chủ động học hỏi'', ''làm việc có tổ chức'', ''làm việc độc lập'', ''làm việc nhóm'']', 'INTERNSHIP', 'ONSITE', 'cần thơ', 'Cần Thơ', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:30)', '[''Thực tập có lương và thưởng hàng tháng dựa trên hiệu quả công việc.'', ''Tham gia các dự án thử thách giúp phát triển kỹ năng và sự nghiệp.'', ''Môi trường làm việc thoải mái, cởi mở, tạo điều kiện phát triển cá nhân.'', ''Cơ hội làm việc với các đối tác trong lĩnh vực công nghệ.'', ''Được cấp giấy chứng nhận thực tập và có cơ hội trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập.'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1085, 9, 13, 'Thực Tập Sinh Thiết Kế Đồ Hoạ (Graphic Design)', 'Hỗ trợ thiết kế các ấn phẩm truyền thông phục vụ hoạt động nội bộ và truyền thông số (digital), bao gồm: banner, poster, standee, backdrop, tờ rơi, name card, quà tặng, sale kit,... Tham gia hỗ trợ xây dựng và duy trì hệ thống nhận diện thương hiệu của công ty. Chỉnh sửa, tối ưu hình ảnh, video đơn giản trên các kênh truyền thông của công ty (website, fanpage, nội bộ,...). Hỗ trợ chụp và chỉnh sửa ảnh sự kiện, hoạt động nội bộ khi cần. Phối hợp cùng team Marketing triển khai các ý tưởng thiết kế cho chiến dịch truyền thông; hỗ trợ team Nội thất trong việc lên ý tưởng đồ họa cho các dự án (nếu có). Thực hiện các công việc liên quan khác theo phân công của Quản lý trực tiếp.', 'Sử dụng thành thạo các phần mềm thiết kế như Adobe Illustrator, Photoshop, InDesign, Premiere và các phần mềm chỉnh sửa video cơ bản. Có khả năng vẽ tay/sketch và biết sử dụng phần mềm thiết kế 3D là một lợi thế. Yêu thích hoặc có đam mê với nghệ thuật, mỹ thuật, thiết kế đồ họa. Có tư duy sáng tạo, tinh thần trách nhiệm cao, chủ động trong công việc, có khả năng làm việc nhóm và độc lập. Biết chụp ảnh, set-up bố cục chụp ảnh sản phẩm hoặc sự kiện là điểm cộng.
Kỹ năng chuyên môn: [''Adobe Illustrator'', ''Photoshop'', ''InDesign'', ''Premiere'', ''phần mềm chỉnh sửa video cơ bản'', ''vẽ tay/sketch'', ''phần mềm thiết kế 3D'', ''chụp ảnh'', ''set-up bố cục chụp ảnh sản phẩm hoặc sự kiện'']
Kỹ năng mềm: [''tư duy sáng tạo'', ''tinh thần trách nhiệm cao'', ''chủ động trong công việc'', ''khả năng làm việc nhóm'', ''khả năng làm việc độc lập'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh: tân cảng, phường 25, bình thạnh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 18:00) Nghỉ trưa 1 tiếng rưỡi', '[''Thực tập có trợ cấp'', ''Hỗ trợ chi phí gửi xe, chi phí đi lại phục vụ cho công việc'', ''Môi trường làm việc trẻ trung, năng động, cởi mở và thoải mái, tạo mọi điều kiện để phát triển năng lực bản thân'', ''Được hướng dẫn, đào tạo phát triển nghề nghiệp, kỹ năng'', ''Đi du lịch - teambuilding 2 lần/ năm'', ''Văn phòng tiện nghi, túi ngủ, bánh trà, cà phê cho nhân viên'', ''Cơ hội làm việc với nhiều đối tác trong lĩnh vực thiết kế nội thất và xây dựng'', ''Hỗ trợ dấu mộc thực tập + Cơ hội trở thành nhân viên chính thức'', ''Các quyền lợi khác theo luật lao động'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1086, 10, 13, 'Intern Thiết Kế/ Design (Thực Tập Sinh)', 'Hỗ trợ thiết kế các ấn phẩm truyền thông cho các chiến dịch Marketing: Banner, Poster, Social Media Post, Catalogue, Profile… Tham gia xây dựng ý tưởng thiết kế theo định hướng của team hoặc theo yêu cầu từng dự án. Phối hợp với các bộ phận liên quan để đảm bảo sản phẩm thiết kế đúng tiến độ và chất lượng. Hỗ trợ chỉnh sửa, hoàn thiện các file thiết kế theo phản hồi. Thực hiện các công việc khác theo sự phân công của quản lý.', 'Sinh viên năm 3, năm 4 hoặc mới tốt nghiệp chuyên ngành Thiết kế đồ họa, Mỹ thuật, hoặc các ngành liên quan. Thành thạo các phần mềm thiết kế cơ bản: Photoshop, Illustrator, Canva là lợi thế. Có tư duy thẩm mỹ tốt, sáng tạo, nắm bắt nhanh xu hướng thiết kế. Khả năng làm việc nhóm và tiếp nhận feedback tốt. Chủ động, trách nhiệm, cẩn thận trong công việc. Có portfolio hoặc một số sản phẩm thiết kế đã từng thực hiện là điểm cộng. Có laptop riêng sử dụng cho công việc
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Canva'', ''Indesign'', ''Hiểu biết về nguyên tắc thiết kế (màu sắc, bố cục, typography)'']
Kỹ năng mềm: [''Tư duy thẩm mỹ tốt'', ''Sáng tạo'', ''Nắm bắt nhanh xu hướng thiết kế'', ''Khả năng làm việc nhóm'', ''Tiếp nhận feedback tốt'', ''Chủ động'', ''Trách nhiệm'', ''Cẩn thận trong công việc'', ''Khả năng giao tiếp tốt'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 3000000.00, '1.5 - 3.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00), Thứ 7 (từ 08:00 đến 11:30) hoặc tùy vào lịch học của thực tập sinh', '[''Đào tạo chuyên ngành và nâng cao kinh nghiệm thực tế'', ''Hỗ trợ dấu mộc thực tập'', ''Nghỉ phép 1 ngày/tháng (Dành cho thực tập sinh full time)'', ''Phụ cấp ăn trưa 500,000 VND'', ''Công ty trả phí giữ xe tháng'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1087, 2, 13, 'Nhà thiết kế đồ họa (thực tập)', 'Vị trí: Intern Graphic Designer Số lượng: 01 - Thiết kế các ấn phẩm truyền thông kỹ thuật số (Facebook, Instagram, YouTube…) theo Key Visual của thương hiệu. - Edit video marketing cơ bản phục vụ các chiến dịch Digital. - Tham gia đóng góp ý tưởng và hỗ trợ triển khai các hoạt động Marketing. - Hỗ trợ một số công việc Marketing khác theo sự phân công từ Leader.', '- Sinh viên năm cuối đã hoàn tất chương trình học chuyên ngành Thiết kế, Marketing, Truyền thông hoặc các ngành liên quan. - Thành thạo phần mềm Adobe chuyên dụng: Illustrator, Photoshop, Premiere. - Phong cách thiết kế hiện đại, phù hợp với lĩnh vực công nghệ làm đẹp. - Kỹ năng giao tiếp tiếng Anh ở mức khá trở lên (Nghe – Nói – Đọc – Viết). - Tư duy sáng tạo, chủ động học hỏi, có định hướng phát triển trong mảng Digital Marketing. - Năng động, nhiệt huyết, cầu tiến, có trách nhiệm với công việc. - Có laptop cá nhân phục vụ công việc. - Không nhận ứng viên làm việc online. - Thời gian thực tập: 03 tháng.
Kỹ năng chuyên môn: [''Illustrator'', ''Photoshop'', ''Premiere'', ''Adobe Photoshop'', ''Adobe Illustrator'']
Kỹ năng mềm: [''Tư duy sáng tạo'', ''Chủ động học hỏi'', ''Năng động'', ''Nhiệt huyết'', ''Cầu tiến'', ''Có trách nhiệm với công việc'', ''Khả năng sáng tạo'', ''Khả Năng Làm Việc Nhóm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 5000000.00, '4.0 - 5.0 triệu', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00)', '[''Trợ cấp thực tập: tối đa 5 triệu đồng/tháng (tùy theo năng lực), bao gồm phụ cấp ăn trưa, gửi xe, đi lại.'', ''Hỗ trợ dấu mộc thực tập và đánh giá năng lực sau chương trình.'', ''Được đào tạo bài bản về thiết kế và edit video trong môi trường chuyên nghiệp.'', ''Làm việc tại không gian hiện đại của Wework – E.Town Central, với nhiều tiện ích: cà phê, trà Phúc Long 24/7, không gian ngủ trưa, bàn bi lắc, quầy craft beer...'', ''Cơ hội trở thành nhân viên chính thức sau kỳ thực tập nếu thể hiện tốt.'']', true, 3, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1088, 3, 13, 'Thực Tập Sinh Thiết Kế Đồ Họa', 'Mô tả công việc - Hỗ trợ thiết kế các mẫu quảng cáo trên kênh digital marketing (website, facebook, google…) như facebook post, banner, clip... - Thiết kế các ấn phẩm truyền thông cho công ty: logo, banner, tờ rơi, brochure,... - Edit video, dựng video theo các kịch bản có sẵn ; - Chỉnh sửa và thiết kế ảnh theo yêu cầu; - Thành thạo các phần mềm thiết kế như Photoshop, Illustrator,... - Có kỹ năng cơ bản của các phần mềm chỉnh sửa video: AE, PR. Quyền lợi - Mức lương: Thỏa thuận - Môi trường làm việc năng động, thân thiện, chuyên; - Tạo điều kiện học hỏi phát triển chuyên môn và cơ hội nghề nghiệp; - Tham gia CLB free các câu lạc bộ: đá bóng, cầu lông,...', 'Yêu cầu ứng viên - Sinh viên năm 3 trở lên các chuyên ngành về thiết kế đồ họa, mỹ thuật công nghiệp, truyền thông đa phương tiện... - Sử dụng được các ứng dụng, công cụ thiết kế đồ họa: Adobe illustrator, Indesign…; chỉnh sửa ảnh: Adobe Photoshop, Lightroom...;xử lý video cơ bản: Adobe Premiere, After Effects… - Có khả năng sáng tạo trong thiết kế; - Có các kỹ năng mềm: tư duy marketing, tổ chức, làm việc nhóm, làm việc độc lập…
Kỹ năng chuyên môn: [''Photoshop'', ''Illustrator'', ''Adobe Illustrator'', ''Indesign'', ''Lightroom'', ''Adobe Premiere'', ''After Effects'', ''AE'', ''PR'', ''Typography'']
Kỹ năng mềm: [''Sáng tạo'', ''Tư duy marketing'', ''Tổ chức'', ''Làm việc nhóm'', ''Làm việc độc lập'']', 'INTERNSHIP', 'ONSITE', 'hà nội', 'Hà Nội', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30). Linh hoạt thời gian làm việc, yêu cầu bắt buộc lên công ty tối thiểu 2 buổi/tuần hoặc 4 buổi sáng/chiều trong tuần.', '[''Môi trường làm việc năng động, thân thiện, chuyên nghiệp'', ''Tạo điều kiện học hỏi phát triển chuyên môn và cơ hội nghề nghiệp'', ''Tham gia các câu lạc bộ miễn phí: đá bóng, cầu lông,...'', ''Được cấp máy tính'', ''Thưởng tháng 13'']', true, 4, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1089, 7, 13, 'Thực Tập Sinh Edit Video', '- Edit các đoạn video ngắn đến trung bình cho sản phẩm trên Social - Video bao gồm thao tác, phụ đề, thêm hiệu ứng, âm thanh, lồng tiếng và chuyển cảnh; - Thích hợp cho bạn sinh viên nghành thiết kế đồ họa, quay dựng... cần môi trường thực tế quay dựng, edit', '- Biết Sử dụng Adobe Premiere + Photoshop * Yêu thích ứng dụng A.I vào công việc - Có kiến thức cơ bản về các trend và mạch video trên các nền tảng khác nhau như Tiktok, Youtube, Facebook. - Có khả năng sáng tạo nội dung, ưu tiên sinh viên năm cuối hoặc vừa Tốt nghiệp ngành Truyền thông đa phương tiện, Dựng phim, Thiết kế đồ họa,...hoặc các ngành khác có liên quan. - Cẩn thận, kỹ tính, có trách nhiệm với công việc, tôn trọng deadline. - Không yêu cầu kinh nghiệm chỉ cần siêng năng, ham học hỏi, và chịu đổi mới, hoạt bát trong công việc. - Tư duy sáng tạo và thẩm mỹ tốt, nhanh nhẹn, chủ động trong công việc, thích nghi tốt.
Kỹ năng chuyên môn: [''Adobe Premiere'', ''Photoshop'', ''A.I'', ''Dựng phim'', ''Biên tập Video'', ''Adobe Photoshop'', ''Adobe Premiere Pro'']
Kỹ năng mềm: [''Sáng tạo nội dung'', ''Cẩn thận'', ''Kỹ tính'', ''Có trách nhiệm với công việc'', ''Tôn trọng deadline'', ''Siêng năng'', ''Ham học hỏi'', ''Chịu đổi mới'', ''Hoạt bát trong công việc'', ''Tư duy sáng tạo'', ''Thẩm mỹ tốt'', ''Nhanh nhẹn'', ''Chủ động trong công việc'', ''Thích nghi tốt'', ''Teamwork'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 2 - Thứ 7 (từ 08:30 đến 17:45)', '[''Trợ cấp thực tập: 1.500.000đ/tháng'', ''Được training và tham gia công việc thực tế tại doanh nghiệp'', ''Hỗ trợ báo cáo thực tập'', ''Có cơ hội được lên nhân viên chính thức sau kỳ thực tập'']', true, 1, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
INSERT INTO jobs (id, employer_id, category_id, title, description, requirements, job_type, work_mode, location, province, salary_type, salary_amount, salary_text, working_hours, benefits, student_friendly, slots_available, status, deadline) VALUES (1090, 8, 13, 'Thực Tập Sinh Media Quay, Dựng', 'Mô tả công việc - Hỗ trợ set đèn, quay, xử lý màu, dựng clip truyền thông social - Phối hợp với bộ phận Content, designer xây dựng ý tưởng quay dựng. - Tham gia các hoạt động của Team marketing - Lập báo cáo định kỳ. - Các công việc liên quan theo sự phân công của người hướng dẫn. Quyền lợi - Được sử dụng máy ảnh, thiết bị chuyên nghiệp. - Được hướng dẫn bởi các Anh/Chị giàu kinh nghiệm. - Môi trường làm việc hiện đại, với đội ngũ marketing trẻ tuổi, chuyên nghiệp. - Cơ hội phát triển lên các vị trí chính thức sau thời gian thực tập. * Phụ cấp: Không có * Xác nhận thực tập: có', 'Yêu cầu ứng viên - Trình độ học vấn: Sinh viên năm cuối hoặc mới tốt nghiệp Cao đẳng, Đại học ở các chuyên ngành truyền thông đa phương tiện, designer, marketing hoặc các chuyên ngành liên quan. - Có gu thẩm mỹ, nhiều ý tưởng trong quay dựng, cảm âm tốt. - Làm việc nhóm. - Chỉnh chu, cẩn thận, có trách nhiệm. - Gửi kèm portfolio - Thời gian đến công ty: 2 buổi/ tuần (có thể đến Cty nhiều hơn theo nhu cầu)
Kỹ năng chuyên môn: [''Dựng phim'', ''Quay Phim'', ''Kỹ Năng Sử Dụng Camera'', ''Hiểu Biết Về Ánh Sáng, Âm Thanh'', ''Sử Dụng Phần Mềm Chỉnh Sửa Video (Premiere Pro, Final Cut Pro, DaVinci Resolve)'']
Kỹ năng mềm: [''Có gu thẩm mỹ'', ''Nhiều ý tưởng trong quay dựng'', ''Cảm âm tốt'', ''Làm việc nhóm'', ''Chỉnh chu'', ''Cẩn thận'', ''Có trách nhiệm'']', 'INTERNSHIP', 'ONSITE', 'hồ chí minh', 'Hồ Chí Minh', 'MONTHLY', 4000000.00, '0.0 triệu', 'Thứ 3 (từ 08:00 đến 17:00), Thứ 5 (từ 08:00 đến 17:00), 2 buổi/tuần (có thể đến Cty nhiều hơn theo nhu cầu)', '[''Được sử dụng máy ảnh, thiết bị chuyên nghiệp'', ''Được hướng dẫn bởi các Anh/Chị giàu kinh nghiệm'', ''Môi trường làm việc hiện đại, với đội ngũ marketing trẻ tuổi, chuyên nghiệp'', ''Cơ hội phát triển lên các vị trí chính thức sau thời gian thực tập'', ''Xác nhận thực tập'']', true, 2, 'OPEN', DATE_ADD(NOW(), INTERVAL 30 DAY)) ON DUPLICATE KEY UPDATE title=VALUES(title), province=VALUES(province), student_friendly=VALUES(student_friendly);
